INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Döndün ki', 'niye-dondun-ki-ali-saglam-3-1zdt2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrıldık...! 

Delicesine severken, 

Hep el ele olmak isterken, 

Evlenmeyi düşlerken, 

Şimdi döndün...

Niye? 

Neredeydin? 

Hayallerim yıkılırken

Umutlarım yok olurken.

Niye döndün ki? 

Niyeeeeee.....!', 'Ayrıldık...!  Delicesine severken,  Hep el ele olmak isterken,  Evlenmeyi düşlerken,  Şimdi döndün... Niye?  Neredeydin?  Hayallerim yıkılır...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/niye-dondun-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Bu Kadar', 'benden-bu-kadar-ali-saglam-3-38swz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğime...

Ne  bir mutluluk verdin bana ne de bir ümit, 

Ömrümün sonuna geldim artık geçti vakit, 

Varsın ben mutsuz olayım, yeterki çek git, 

Yoruldum umudum kalmadı sevmekten, 

Dostuma...

Ceviz kabuğunu doldurmayacak kadarsa sitemin, 

Arkadaşlığın değerini bil, yoksa olmaz değerin, 

Yanında olmazsan en kara gününde dostunun, 

Senin gibi dostun Allah belasını versin derim.

Dünyaya...

Her yanında kavga, kin, intikam.

Yalansın dünya tüm güzelliklerin yalan, 

Aldatırsın insanları, üç kuruş zevke doymayan

Bir beni aldatamadın ya, artık sende ona yan', 'Sevdiğime... Ne  bir mutluluk verdin bana ne de bir ümit,  Ömrümün sonuna geldim artık geçti vakit,  Varsın ben mutsuz olayım, yeterki çek g...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benden-bu-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-nurullah-genc-vi5s1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökleri kucaklasın kolların, gel içime

Ellerin gözlerimin mehtabını süslesin

Akıyorsun ırmaklar gibi hayallerime

Büyülüyor gönlümü sanki rüyada sesin

Naz ile uğulduyor kulaklarımda meltem

İğneli bakışların yıktığı viraneyim

Istırap sergilerken yüzünde, binbir sitem

Neyleyim visalini, ben artık divaneyim

Masmavi bir denizin ortasında ve kırgın

İçiyorum çöllerin bütün susuzluğunu

Damla damla kuruttu bu sevda ve bu yangın

Mendillerin gözümde arayıp bulduğunu

En  acı duygularla bakıyorum göklere

Bahçıvanlar şimdi hep diken yetiştiriyor

Rabbim, kavuşmasamda dünyada çiçeklere

Ebediyyet bahçesi artık beni bekliyor

Şafakla kapanacak içimdeki yaralar

İklimleri ruhumun yaprağında gizledim

Issızlık ülkesinde çürürken hatıralar

Arş''ın hiç değişmeyen iklimini özledim

Mutluluk diyarına gideceğim göklerden

Nur ile penceremi bezeyecek çiçekler

İhtirasın, ölümün olmadığı o yerden

Meçhuller dünyasını dolduracak melekler

Büyülüyor gönlümü sanki rüyada sesin

Akıyorsun ırmaklar gibi hayallerime

Ellerin gözlerimin mehtabını süslesin

Gökleri kucaklasın kolların, gel içime', 'Gökleri kucaklasın kolların, gel içime Ellerin gözlerimin mehtabını süslesin Akıyorsun ırmaklar gibi hayallerime Büyülüyor gönlümü sanki rüy...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gel-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar''ı Özledim', 'bahar-i-ozledim-ali-saglam-3-zmh3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Damarlarımda dolaşan en güzel serüvenime, 

Yaşayıpta doyamadığım en mutlu günlerime, 

Seni hiç unutmayacağım diyen o sese, 

Sevmeye bile kıyamadığım, sevdiğime hasretim.

Geçip gitti artık, bir daha da hiç gelmeyecek, 

Gücüm yetmezki dostum zamana dur diyecek, 

Herzaman akıllarda gönüllerde kalacak, 

Yaşamaya doyamadığım günlerime hasretim.

İçinde bir parça dahi menfeat olmayan, 

Üç kuruş için hesap bile sorulmayan, 

En ufak olaydan sonra kırılıp darılmayan, 

Kalbinde sevgi olan arkadaşlarıma hasretim.

Ağaçları gelin gibi donatıp süsleyen, 

İçinde tüm güzellikleri aşkı besleyen

En azından veda etmesini bilen, 

Mevsimlerin mevsimi bahar''a hasretim.', 'Damarlarımda dolaşan en güzel serüvenime,  Yaşayıpta doyamadığım en mutlu günlerime,  Seni hiç unutmayacağım diyen o sese,  Sevmeye bile kıy...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahar-i-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Özlem', 'baska-bir-ozlem-nurullah-genc-cv02u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şehla bakışın güneş edalım

Deliyor dağ gibi kalkanlarımı

Yitirdim denizin saçına tutkun

Sabahleyin erken kalkanlarımı

Bağrımda  büyüdü ömür dikeni

Hürriyet harcadı alkanlarımı

Gecenin karanlık yüzü içinde

Zaman yuttu şimşek çakanlarımı

Hangi rüzgar alıp götürdü, bilmem

Kendini ateşte yakanlarımı

Dostlarımı geri verin uzaklar

Her seher semaya akanlarımı', 'Bir şehla bakışın güneş edalım Deliyor dağ gibi kalkanlarımı Yitirdim denizin saçına tutkun Sabahleyin erken kalkanlarımı Bağrımda  büyüdü ö...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/baska-bir-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Yalan Söylemiyor', 'gozlerin-yalan-soylemiyor-mahmut-bingul-xlgpd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğini gözlerinde okuyorum şimdi

ve alnında doğuştan kazılmış ismimi.

Kulak ver kalbine! ...

Kalbinin her atışında 

ismim yankılanır içinde

adım düğümlenir adına

bırakmaz ismini.

Sen çırpındıkça 

adım daha da düğümlenir adına

Şunu bil ki sevdiğim! ...

İlan edilmemiş 

aşkların tazeliği var gözlerinde

Gözlerin 

sevgi püskürtmeye hazır bir volkan.

Yüreğinin sesini bekliyor gözlerin.

Gözlerin yalan söylemiyor, 

yüreğin seviyor beni.

Sarıyor beni sevgin 

yakıyor beni gözlerin.

Gözlerin...

Ahh o gözlerin, 

karalığını yitiriyor artık gözlerin! ...', 'Yüreğini gözlerinde okuyorum şimdi ve alnında doğuştan kazılmış ismimi. Kulak ver kalbine! ... Kalbinin her atışında  ismim yankılanır içind...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozlerin-yalan-soylemiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-i-mam-ali-seven-a6pom', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vuslat gibi bir gül sevgilinin elinde

O güldeki renkler ölmüş olsa da güzel.

Sevenler sevgiliye solmuş çiçek verirler, 

Sevgi midir o çiçeği böyle güzel gösteren?', 'Vuslat gibi bir gül sevgilinin elinde O güldeki renkler ölmüş olsa da güzel. Sevenler sevgiliye solmuş çiçek verirler,  Sevgi midir o çiçeği...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cicek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-ali-saglam-3-3ztq6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir on dört şubat sabahı yine

Düşünüyorumda sensiz mi geçecek

Acaba sevgilim bugün 

Görebilecekmiyim bilmiyorum, seni

Tutup ellerini sarılıp belkide, 

Söylemek istiyorum nekadar sevdiğimi, 

Kollarımda olacakmısın sevgililer gününde....

Bir demet gül ile bekleyeceğim seni, 

Sadece ben ve özlemlerim olacak, 

Dinlersen eğer bu gün kalbinin sesini, 

Kalbin bile başka türlü çarpacak, 

Ne kadar uzak olsanda, 

Gelmek isteyeceksin, 

Sevgini haykıracaksın kendi kendine, 

Benimle olurmusun sevgililer gününde? ? ? 

Seni bir kez olsun bu gün göremezsem, 

Bir hüzün dolacak kalbime yakacak beni, 

Çok ama çok sevdiğimi söyleyemezsem, 

İşte o zaman bir acı olacak dudaklarımda, 

Damla damla yaşlar ağlayacakgözlerimde, 

Seni görürmüyüm acaba bir tanem, 

Aşkımızla aydınlanan bir sevgililer gününde....

14-02-1996', 'Bir on dört şubat sabahı yine Düşünüyorumda sensiz mi geçecek Acaba sevgilim bugün  Görebilecekmiyim bilmiyorum, seni Tutup ellerini sarılıp...', ARRAY['Türk Edebiyatı','Şiir','Ali Sağlam 3']::text[], 8.5, '{"poet":"Ali Sağlam 3","poet_slug":"ali-saglam-3","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevgililer-gunu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-i-mam-ali-seven-4fyuh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedir kayıp? 

Ne tam yerli yerinde? 

Kafam allak bullak ne nerde? 

Neyi nerde bulmalı? 

Niye bulmalı? 

Benim nedenim söyleyin nerde?', 'Nedir kayıp?  Ne tam yerli yerinde?  Kafam allak bullak ne nerde?  Neyi nerde bulmalı?  Niye bulmalı?  Benim nedenim söyleyin nerde?...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arayis-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tesellimdir Çocukların gülümsemeleri', 'tesellimdir-cocuklarin-gulumsemeleri-mahmut-bingul-xz7w7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çocuk parkında atıyorum

sevdiğimden ayrılığın hüznünü.

Tesellimdir, 

kumda oynayan çocukların coşkusu.

İçimde bir sarsıntı oluyor, 

aşk şiddetinde. 

Sersemim, 

Sarhoşum.

Ilık bir esinti bozuyor dalgasızlığımı.

Ayıldım! 

Uzaklara bakıyorum

Yakına bakmaktan yorulan gözlerimle

Mutluluğu arıyorum.

Umudum dağların kuytularında 

Sevinci(m)   ise namlunun ucunda bir karanfil

Nisan 2001 / Atâkent', 'Bir çocuk parkında atıyorum sevdiğimden ayrılığın hüznünü. Tesellimdir,  kumda oynayan çocukların coşkusu. İçimde bir sarsıntı oluyor,  aşk ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Bingül']::text[], 8.5, '{"poet":"Mahmut Bingül","poet_slug":"mahmut-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tesellimdir-cocuklarin-gulumsemeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün(1)', 'gun-1-i-mam-ali-seven-q5wra', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günler geçer devran döner ardından

Güller solar bülbül öter kan ağlar

Bir gülüş ki bilmeyene sıradan, 

Ruhuma karanlık bir sır fısıldar.

Esmer gökyüzünden iner kalbime, 

Hiçliğin çığlığı yok oluş ve yas, 

Bir kasırga gibi yırtar varlığı, 

Öylesine bir hırs arsız ihtiras.

Çarpılır gülüşüm söner umudum, 

Bana benden kalan sade hiç olur.

Gözlerimde yaş kalbimde buğu, 

Varlığım kendinde yokluğu bulur.

Tüm günden geriye bir susuş kalır, 

Sağır eder kulakları son çığlığıyla, 

Elini uzatan bu sırrı alır, 

Yanarken dökülen parmaklarıyla...

Günler geçer devran döner ardımdan, 

Güller solar bülbül susar kan sızar.

Ölümsüz ruhuna zorla kazınan, 

Bir izdir benden tüm arta kalan.', 'Günler geçer devran döner ardından Güller solar bülbül öter kan ağlar Bir gülüş ki bilmeyene sıradan,  Ruhuma karanlık bir sır fısıldar. Esm...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gun-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün(2)', 'gun-2-i-mam-ali-seven-awzff', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mucizeler aradım seher vaktine yakın, 

Güneş doğdu, rüzgar esti, çiçekler açtı, 

Seni gecelerde bıraktığımı sanma sakın, 

İsmin dilimin ucuna geldi; diyecekken kaçtı.

Sana bir isim aradım kuşlukta, 

Bulut iyice yaklaştı; diyecekken sustu.

Adın yazıyordu belki ağaçta, dağda

Sana onlardan isim verecektim, yoktu.

Bir ayna buldum akşama doğru, 

Baktım onda uzun uzun aksime.

Fark ettim ruhumun yarısı yoktu.

Aradım, ismi yok cismi kayıptı.

Sana bir gün bir ad bulunca

İnan ki bana gece olacak.

Bir çiçek gibi kalbim solunca, 

O zaman vuslatına hep inanacak.', 'Mucizeler aradım seher vaktine yakın,  Güneş doğdu, rüzgar esti, çiçekler açtı,  Seni gecelerde bıraktığımı sanma sakın,  İsmin dilimin ucun...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Çiçekleri', 'kan-cicekleri-zulfu-livaneli-9b4xf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Topraktan mı sürmüş, candan mı kopmuş

Açar yediveren kan çiçekleri

Türkü mü, şiir mi, ağıt mı yoksa

Açar yediveren kan çiçekleri

Bölük bölük olmuş çaylar dereler

Hiçbiri denize varabilmezmiş

Duvarın dibinde bir yaralı gül

Gülleri solduran gülebilmezmiş

Bu şehrin üstünü duman sis almış

Tomurcuk çiçekler kana belenmiş

Dağlar çiçek açmış, usta dert açmış

Umudun goncası kan çiçekleri', 'Topraktan mı sürmüş, candan mı kopmuş Açar yediveren kan çiçekleri Türkü mü, şiir mi, ağıt mı yoksa Açar yediveren kan çiçekleri Bölük bölük...', ARRAY['Türk Edebiyatı','Şiir','Zülfü Livaneli']::text[], 8.5, '{"poet":"Zülfü Livaneli","poet_slug":"zulfu-livaneli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-i-mam-ali-seven-hto21', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kork ne de kaç benden ben senin yarınınım

Sana uzanmış dalım cennetin ağacından

Kalbinden fışkırmışım ve eğilip dönerek

Tekrar öz kaynağımı seyretmeye dalmışım.', 'Ne kork ne de kaç benden ben senin yarınınım Sana uzanmış dalım cennetin ağacından Kalbinden fışkırmışım ve eğilip dönerek Tekrar öz kaynağı...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/donus-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehirli Dil', 'zehirli-dil-mehmet-yasin-wg46n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıvrılıyor. Zehirlidil

istemese de sokuyor sevgilisini

öpüşürken.

Kusulmuş sözcükler

yalıyor sessizliği. Bir anda

yal
..........
..........', 'Kıvrılıyor. Zehirlidil istemese de sokuyor sevgilisini öpüşürken. Kusulmuş sözcükler yalıyor sessizliği. Bir anda yal .......... .............', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşın']::text[], 8.5, '{"poet":"Mehmet Yaşın","poet_slug":"mehmet-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zehirli-dil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Rüyası', 'korku-ruyasi-mehmet-yasin-2i8j7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birden ölüyor birilerim, ölmediği halde

ölmüş gibi bırakıyorum onları topluca mezarda...

- Ailesi boş ol''an çocuklar gibi

yükleniyorsun hepsinin suçunu.

Zamanında terapiste de gönderilmemiş

ki sen aynı anne dilden de değilsin kendinle

aynı... karşıtım ''ben'' olduğ''na göre

yükleniyorsun kaçınılmaz öldürülü
..........
..........', 'Birden ölüyor birilerim, ölmediği halde ölmüş gibi bırakıyorum onları topluca mezarda... - Ailesi boş ol''an çocuklar gibi yükleniyorsun heps...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşın']::text[], 8.5, '{"poet":"Mehmet Yaşın","poet_slug":"mehmet-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korku-ruyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterdi', 'yeterdi-i-mam-ali-seven-g42ym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece efkarlıyım

Bana dokunmayın

Kurallar yok

Sen yoksun gözlerimde

Rüyalar olmadığı kadar uzak

Gerçekler olmadığı kdar yakın

Bir parça sessizlik

Ve bir kaç damla umut yeterdi oysa

Dünyayı unutmama.', 'Bu gece efkarlıyım Bana dokunmayın Kurallar yok Sen yoksun gözlerimde Rüyalar olmadığı kadar uzak Gerçekler olmadığı kdar yakın Bir parça se...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeterdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Güzeli', 'su-guzeli-mehmet-ocaktan-rpzcb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-I-

Jaguar burcundan bir kadınla

eğilip su ve dolunaylarımı açarım açarım çocuklara

etrafı sözle kaplı bir zamanın amentüsünden.

Su güzeli gözlerinin bittiği

o müphem haritalara

koyu bir sessizlik gibi çöker

ölüme biraz kapı komşu yaşayan çocukların özü.

Ve çocukluğumdan gelirken ağladığım

su şarkılarından

alemi ervaha

kollarında platin rüyalar

hatmederek gider gençlik meleğim.

-II-

Bugün su ve dolunayın ilk günü

asri gül, saatlerindeyim

sular ve melekler içindeyim.

Birazdan gözlerinin

kristal tenine salar beni meleğim.

Gitme, bütün şarkıların sonunda

biriken ateşimde kal

yansın sularında biriken tenim.

Gitme, herkesin yeni bir düş için

dolunaya durduğu gözlerden

ölüme mühürlenmiş bir aşkın.', '-I- Jaguar burcundan bir kadınla eğilip su ve dolunaylarımı açarım açarım çocuklara etrafı sözle kaplı bir zamanın amentüsünden. Su güzeli g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ocaktan']::text[], 8.5, '{"poet":"Mehmet Ocaktan","poet_slug":"mehmet-ocaktan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/su-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-i-mam-ali-seven-vnmn3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl anlarım kanadığımı

Dokunamadan hiç ellerine?', 'Nasıl anlarım kanadığımı Dokunamadan hiç ellerine?...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/anladim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın En Güzel Dönüşü', 'dunyanin-en-guzel-donusu-orhan-alkaya-l0nhk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ölümün uzun atları götürürdü şairi

sonsuzluğun rahmine; hüznün gölgesini silerken

kendi ateşiyle dans eder gece

sarhoş bir rüzgar genişletiyor yangını

tek heceli yılgıların uçsuz güzelliğinde

alnını en son bulutun kıyısına yerleştirmiş

yitirişin kaynağına sızıyor usulca

ve ardından binlerce dize aktı toprağın gergefine

yeryüzüne erimiş insan hem var hem yoktur daima

ölmek en uzun şiirdi ölümü bilene', 'ölümün uzun atları götürürdü şairi sonsuzluğun rahmine; hüznün gölgesini silerken kendi ateşiyle dans eder gece sarhoş bir rüzgar genişletiy...', ARRAY['Türk Edebiyatı','Şiir','Orhan Alkaya']::text[], 8.5, '{"poet":"Orhan Alkaya","poet_slug":"orhan-alkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dunyanin-en-guzel-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke', 'ofke-i-mam-ali-seven-i1qx5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum sana da olur mu? 

Ama ara sıra adamlar yürür kalbimde

Yüzlerini buruşturup yerlere tükürürler

Buldukları her şeye, her şeye küfrederler.', 'Bilmiyorum sana da olur mu?  Ama ara sıra adamlar yürür kalbimde Yüzlerini buruşturup yerlere tükürürler Buldukları her şeye, her şeye küfre...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ofke-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Kendini Yazarsa', 'bir-siir-kendini-yazarsa-orhan-alkaya-vygf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dökülen geceydi, ses

dile getirişten çok nedir

gecede - ve gelen daima nadir

bulunan kimdi her gelişte

gelen yolcuydu ve ise

artık neydi yolcu olan bir vakitte

ses ne söyler ve yoksa

yok muydu hissedişte

var kime denirdi

var olan sorularına eksildikçe

sis! Dokundum, döküldü

oydu gecede', 'dökülen geceydi, ses dile getirişten çok nedir gecede - ve gelen daima nadir bulunan kimdi her gelişte gelen yolcuydu ve ise artık neydi yol...', ARRAY['Türk Edebiyatı','Şiir','Orhan Alkaya']::text[], 8.5, '{"poet":"Orhan Alkaya","poet_slug":"orhan-alkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-siir-kendini-yazarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba?', 'acaba-beyhan-oral-bayram-41y1t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen özençsiz bir beklenti oluyorum

Bakakalıyorum hayatın vurdumduymazlığına.

Donmuş dudaklarımın arasından sıyrılıp

Atmosferde kayboluyorum

Buharlaşmayı beklerken 

Bulut olup yeniden yağmurlaşıyorum

Toprak kokuyorum 

Yeniden sızıyorum hayatın içine 

Bir ırmak oluyorum

Denize  meyilli.

Bir ağaçta özsu oluyorum, 

Bir çiçeğin köklerinde uyuyorum geceleri.

Bazen dingin ve huzurlu bir yuva oluyorum

Boyanmış yosunlara.

Önümdeki kayalıklara çarptıkça 

Acı çekiyorum.

Öğreniyorum acının tadını

Sonraları gülüp geçiyorum

Bir yol buluyorum taşların arasından

Tam ulaştım derken cevaba

Bir soru olarak dönüyorum hayata.

Bazen düşünüyorsun üzerimde 

Kafanı kurcalıyor sonumdaki soru işareti.

Bazen de sıkılıp buruşturup atıyorsun bir kağıt gibi

Acının kırışık izlerini ütülemeye çalışırken

Yakıyorsun

Büyük bir yırtık daha cümle ortasında.

Yamayabilir misin yırttığın hayatımı 

İçi boşaltılmış sözcüklerinle? 

Yeniden kurabilir misin ilk günkü cümleyi? 

Bulabilir misin kaybettiğin kelimelerimi? 

Belki sen sevebilirsin ama

Acaba ben yeniden sevebilir miyim seni....?', 'Bazen özençsiz bir beklenti oluyorum Bakakalıyorum hayatın vurdumduymazlığına. Donmuş dudaklarımın arasından sıyrılıp Atmosferde kayboluyoru...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/acaba-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama', 'anama-beyhan-oral-bayram-uki0n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anam! 

Güzel anam! 

Apak alnını kara etmeden döneceğim yanına.

Elimde yılların hediyesiyle elini öpeceğim.

Sevinçten gözlerin dolacak, 

Gururla sarılacaksın boynuma.

Yeniden senin sıcacık koynunda huzur bulacağım.

Günlerden bir gün

Tozlu yollara düşeceğim yine

Anadolu’nun aydınlık kucağında

Işık olacağım, güneş olacağım karanlık yüreklere.

Bilmezliğin, cahilliğin silahıyla gönlümde, 

Meydan okuyacağım analara ateş eden ellere.

Binlerce çocuğum olacak.

Her biri bir fidan, 

Her biri bir çiçek.

Ekilecek, yeşerecek ve büyüyecekler.

Günün birinde

Silah tutan ellere artık durun diyecekler.

Beni bitirmeden bu kalleş zulüm, 

Göğsümü siper edeceğim taze güllere.

Vadem dolduğunda bile susmayacağım.

Çünkü

Benim gibi konuşacak, 

Benim gibi haykıracak, 

Vatanına yar olacak, 

Daha nice çocuklar doğuracağım.

Canım anam! 

Kadın anam! 

Üzerimde bir bayrakla kollarına geldiğim gün, 

Sanma seni görmeyecek duymayacağım.

Şunu bil ki

Vücudumu ve ruhumu sahibine versem de

Ben

Hep senin sıcacık koynunda uyuyup kalacağım.

Sakın ağlama anam.

Sanma ki beni o gün  kaybettin.

Kaybettin sandığın aciz canımı

Unutma ki

Toprağına vatanına sen hediye ettin.

Güzel anam! 

Seni gittiğim yerde bekleyeceğim.

Sen gelmeden şehitlerin yanına girmeyeceğim.

Şehitler ölmez 

Ölmedim ölmeyeceğim.

Vatan bölünmez 

Böldürmedim böldürmeyeceğim....', 'Anam!  Güzel anam!  Apak alnını kara etmeden döneceğim yanına. Elimde yılların hediyesiyle elini öpeceğim. Sevinçten gözlerin dolacak,  Guru...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/anama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-beyhan-oral-bayram-vqcef', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugünü dünün yarını

Ve yarınların dünü olduğu için değil

Umutlarım ve sevgim için yaşıyorum.

Bugün

Göz yaşlarımın tuzu birikmişse kirpiklerimde

Yarın

Mutluluğun en güzel ifadesi olacak yüzümde.

Dedim ya canım

Yarında saklı olan umutlarım için yaşıyorum.

Hem de iyisiyle kötüsüyle

Her şeyi ile ama her şeyiyle yaşıyorum

Sevgimiz ve geleceğimiz için tüm çabalarım.

Yüzümdeki gülüşler, gözümdeki yaşlar sana

Her gelen günde seni ararım

İçimdeki bekleyiş senle olan yarına...', 'Bugünü dünün yarını Ve yarınların dünü olduğu için değil Umutlarım ve sevgim için yaşıyorum. Bugün Göz yaşlarımın tuzu birikmişse kirpikleri...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bekleyis-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyenler Demiş', 'diyenler-demis-beyhan-oral-bayram-zeutn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Naif şehvetiyle yanan bir mum alevinde

Şimdi şimdi seni yaşıyorum.

Yarınları şimdiden seninle el ele çekiyorum.

Gayretsiz sırtımı duvara yaslayıp

Sadece geceyi ve seni dinliyorum.

Diyenler demiş dostlarım

Hasret kül eder diye

Kaldı ki kül olmuş bedenim savruluyor göklerde.

Geç kaldım dostlarım geç

Çok geç artık geri dönmek

Artık

Bende varım dünyanın tozunda diyebiliyorum.

Hasretle her gün biraz daha  fazla titriyor

Bunca şeyin içinde naif yanan aleve koşuyorum.

Ayak sesimi duy

Haykırışımı hisset

Tümüyle senin olan ruhum ve bedenimle

Senden öte sana koşuyorum

Seninle olan yarınlara koşuyorum...', 'Naif şehvetiyle yanan bir mum alevinde Şimdi şimdi seni yaşıyorum. Yarınları şimdiden seninle el ele çekiyorum. Gayretsiz sırtımı duvara yas...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/diyenler-demis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşime', 'esime-beyhan-oral-bayram-68cul', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kısrağın dörtnala koşuşuyum ben.

Akşam, kızıllığın denize vuruşuyum ben.

Sevdimi tam seven, yüreklerde yer eden.

Atası vatan için ölen bir Türk kızıyım ben.

Sevginin derinliğine adım adım yol alan.

Erkeğine dört eliyle sarılan.

Hasretten yanıp yanıp kavrulan.

Ateşin kıpkızıl koruyum ben

Sevgiye tutulan ışıklar var gözümde.

Dürüstlük yatar benliğimde özümde.

Yalan yoktur inan hiçbir sözümde.

Gözü yollarda kalan sevdalı biriyim ben.

Ekmeğinim, aşınım

Dişinim, kısrağınım

Ocağında ateş, bahçende barınağın

Her şeyden önemlisi tek varlığınım

Karınım.', 'Bir kısrağın dörtnala koşuşuyum ben. Akşam, kızıllığın denize vuruşuyum ben. Sevdimi tam seven, yüreklerde yer eden. Atası vatan için ölen b...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/esime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarılarında', 'gece-yarilarinda-beyhan-oral-bayram-b2ego', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Paketimdeki son sigarayı da alarak 

Uyandım yine gece yarılarında.

Gece yarılarında yine sen diye sayıklarken

Hasretin sonu olmayan ucunu yakalarcasına

Çekiyorum sigaramdan bir nefes daha.

Hüzünlü şarkılarda buluyorum seni bu saatlerde

Alıp yanıma getiriveriyorlar.

Kollarının arasında sıcaklığında kaybolurken

Gözlerimi açmak istemiyorum.

Biliyorum yine gideceksin

Sonsuzluğa uzanan bir çizgi gibi.

Öyle bir sonsuzluk ki bu

Seninle ve sevginle dolu

Gökyüzünün uçsuz bucaksız karanlığında arıyorum seni

Sokak lambalarının ıssız ışıklarında arıyorum.

Sessizliğin içindeki o yumuşak seste buluyorum

Aynaya baktığımda bile senin bakışınla bakıyorum kendime

Seni kendim gibi seviyorum

Sana kendim gibi bakıyorum

Ve seni çok özlüyorum canım...', 'Paketimdeki son sigarayı da alarak  Uyandım yine gece yarılarında. Gece yarılarında yine sen diye sayıklarken Hasretin sonu olmayan ucunu ya...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-yarilarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Sev Sen', 'gel-sev-sen-beyhan-oral-bayram-c8o7z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel! 

Kalbimin en ıssız köşelerinde kalan bir çığlık bu.

Sevgiyi ifadenin en açık ve seçik yolu bu.

Özlemden bıkkınlığım dağların ıssızlığı

Gözlerimin en derin yeri, sevgimin gözbebeği

Hasretin can damarı, içimin yalnızlığı bu.

Sev! 

Dünyanın en güzel ve en zor sözcüğü

İçinde barındırır yaşamı ve ölümü.

Herkesin muhtaç olduğu bir damla yağmur.

Gözlerde hayat bulur, kalpte yeşerir

Belki yine orada kurur.

Sen! 

Anlatmak ne mümkün sende olan sevgiyi

Dünyanın en tatlı sevgi dolu erkeği

Özleminden yorgun düştüm ne olursun gel.

Sev de nasıl seversen sev

Senin için inan her şeye değer...', 'Gel!  Kalbimin en ıssız köşelerinde kalan bir çığlık bu. Sevgiyi ifadenin en açık ve seçik yolu bu. Özlemden bıkkınlığım dağların ıssızlığı ...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-sev-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Nasıl Gelirsen Gel', 'gelde-nasil-gelirsen-gel-beyhan-oral-bayram-00h54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim uykusuz 

Sabahı görmek için.

İçim huzursuz 

Seni göremediğim için.

Çekiyorum içime

Bir sigarayı, 

Birde delice esen rüzgarın yağmurlu kokusunu.

Seviyorum diyorum.

İçim haykırırken sana olan sevgimi, 

Dudaklarım suskun.

Gözlerim uykusuz! 

Dalıyorum uzaklara, karanlık dağlara, 

Işığın altında parlayan yağmur damlalarına.

İçimdeki karanlık geceden de koyu.

Seviyorum diyorum geceye, gözlerimin göremediği yıldızlara, 

Suskunluğuma, durgunluğuma.

Dudaklarımın gülmeyişi, 

Gözlerimin görmeyişi senden.

Hayır canım sensizlikten.

Yanıyor gözlerim, dudaklarımsa çatlak.

Susuzluk değil canım sensizlikten.

Toprağın kuruluğu, 

Çöllerin sıcaklığı, 

Nefesimin ılıklığı

Her şey canım her şey özlem dolu.

Sokaklara boş 

Yitirmiş tüm duyguları.

İnsanlarda kendileriyle baş başa.

Hisler anılar her şey uykuda şimdi.

Bir ben uykusuz ve sensiz.

Bıktım derler ya bende öyleyim.

Sevmekten değil canım hasret çekmekten.

Yorgunum yokluğundan, sensizlikten.

Yılmışım geçmeyen günlerden gecelerden.

Gel! 

Geçmeyen günlerin arasından sıyrılda gel.

Kapalı yollardan koşarak gel.

Dağların karanlığını aydınlat da gel.

GELDE NASIL GELİRSEN GEL!', 'Gözlerim uykusuz  Sabahı görmek için. İçim huzursuz  Seni göremediğim için. Çekiyorum içime Bir sigarayı,  Birde delice esen rüzgarın yağmur...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gelde-nasil-gelirsen-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halkasal Sevdam', 'halkasal-sevdam-beyhan-oral-bayram-5uaia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşam bir yolsa 

Yürüyorum öylesine

Geçtikten sonra fark ediyorum

Öyle güzel günler kalmış ki geride.

Sevda bir zincirse

Her halkasında bin bir gülüş bin bir ah

Her gülüşte bir iç çekiş

Her ah ta ise bir çok umut var

Her umutta hayallerim

Hayallerde geleceğim ve sen

Sen; 

Yaşam yolunda güldürüp ah çektiren

Her halka sevdada

Hasretini buram buram tüttüren....', 'Yaşam bir yolsa  Yürüyorum öylesine Geçtikten sonra fark ediyorum Öyle güzel günler kalmış ki geride. Sevda bir zincirse Her halkasında bin ...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/halkasal-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeyim?', 'nerdeyim-beyhan-oral-bayram-ipsat', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizliğin içime işlediği 

Gözlerimin seni beklediği bir gündeyim.

Öyle olmuşum ki 

Ben bende değil

Sendeyimm...', 'Sensizliğin içime işlediği  Gözlerimin seni beklediği bir gündeyim. Öyle olmuşum ki  Ben bende değil Sendeyimm......', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nerdeyim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara', 'nice-yillara-beyhan-oral-bayram-7i3cb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşadın

Yaşayacaksın

Neler neler göreceksin.

Bazen delice ağlayacak, 

Bazen de umursamadan güleceksin.

Dileğim hep gülerek uyanıp, 

Gülümseyerek uyuman.

Her günün yeni bir başlangıç olsun, 

Geçmişten kalan kötü izleri silsin senin için.

Çektiğin acıları gün gelip unutacaksın güzelim

Dediklerimi hatırlayacak

Ve buruk bir tebessümle anacaksın.

Her şeye rağmen güzel olduğunu düşün.

En sevdiğin mevsimde 

Mutluluğun anahtarını en sevdiğin kişiden alacaksın.

Bunları yaşadıkça 

İnan hiç ama hiç pişman olmayacaksın.

Bir yaşına daha giriyorsun

Yılların arasına sıkışmış neler var seni bekleyen

Korkma

Azimle yürü.

Her zorluğu sevgiyle aş.

İçinde büyüyen sevgiyi hiçbir zaman soldurma.

Gelecekte seni bekleyen sevgi dolu daha nice yıllara....', 'Yaşadın Yaşayacaksın Neler neler göreceksin. Bazen delice ağlayacak,  Bazen de umursamadan güleceksin. Dileğim hep gülerek uyanıp,  Gülümsey...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nice-yillara-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-beyhan-oral-bayram-30g31', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelecekten  güzel günler bekleyeceksen, 

İnsanların insafsızlığını seyredeceksen, 

Eğer büyüyünce gülmeyeceksen, 

Çocuk kalmak güzel sakın büyüme.

İnsanlığı unutan insanlar arasında, 

Dikenden görülmeyen güllerin arasında, 

Cehaletin kapladığı bilginin ortasında, 

Kendini unutacaksan sakın büyüme.

Kimseye boyun eğme sakın incinme, 

Büyüklerine hürmette hiç kusur etme, 

Sevginin ışığında durma ilerle, 

Yolundan şaşıracaksan sakın büyüme.

Kültürünü geleneğini yarına taşı.

Gözünü çıkarma yaparken kaşı.

Unutma bilgidir her yolun başı.

Öğüdümü tutmayacaksan sakın büyüme.

Büyüyeceksen sevgiyle büyü

Hayat dibi görülmeyen karanlık kuyu

Kuyudan çıkardığın o bir tas suyu

Döküp gideceksen sakın büyüme.', 'Gelecekten  güzel günler bekleyeceksen,  İnsanların insafsızlığını seyredeceksen,  Eğer büyüyünce gülmeyeceksen,  Çocuk kalmak güzel sakın b...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogut-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşçı', 'savasci-cengiz-mise-p937c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu son savaşımdı, 

Aşkla giriştiğim.

Çektim kılıcımı, 

Yüreğimin kınından.

Ben seni karşılıksız sevmiştim.

Son damlasına kadar sevgimin.

Çok uğraştım, 

Bir seni yenemedim, 

Bir söz dinlemez aşkımı.

Yüreğimin, 

En derinine gömdüm, 

Bu anlamsız acımı.

Ben seni öylesine sevmiştim.

Son damlasına kadar kanımın.

Kaybettim bu savaşta, 

Yenik düştüm üzgünüm.

Ben seni ölesiye sevmiştim.

Son gününe kadar ömrümün.', 'Bu son savaşımdı,  Aşkla giriştiğim. Çektim kılıcımı,  Yüreğimin kınından. Ben seni karşılıksız sevmiştim. Son damlasına kadar sevgimin. Çok...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Mişe']::text[], 8.5, '{"poet":"Cengiz Mişe","poet_slug":"cengiz-mise","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/savasci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yegane', 'yegane-necip-fazil-kisakurek-50ily', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi bir sur gibi yıkılan gönül

Sevgi diyarının viranesidir.

Yalnızlık içinde sıkılan gönül

Hasret ateşinin pervanesidir.

Başından geçen hal bir mübtelanın, 

Kanlı izleridir aynı belanın; 

Aynı mecnun ile aynı Leylanın

Bu demde söylenen efsanesidir.

Görünce kaygunun azadeleri

Derhal olur ölüm amadeleri, 

Dünyayı taşırır üftadeleri, 

Her biri deliler divanesidir.

Dense delebinde mey bulunduğu

Yoktur bu uğurda mest olunduğu, 

Çünkü o afetin bize sunduğu

Bir zehirli firkat peymanesidir.

Güya mezardan bugün çıkmış kadar

Saldırmış dünyaya acıkmış kadar, 

Artık hissetmeden pek bıkmış kadar

Gönülden sevmenin biganesidir.

Güzelliği nurun değildir eşi, 

Onu aydınlatan bir hırs ateşi; 

başında gezdirse bile güneşi

Bence yine zulmet nişanesidir.

O hüsran yoluna saptıran güzel

Aşk mabedine put yaptıran güzel

Günlerce kendine taptıran güzel

Kafirler bezminin yeganesidir...', 'Şimdi bir sur gibi yıkılan gönül Sevgi diyarının viranesidir. Yalnızlık içinde sıkılan gönül Hasret ateşinin pervanesidir. Başından geçen ha...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yegane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layya', 'layya-sitki-caney-xfvbt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir

karanlıklarda

çok az kalmışsa zaman

aşk için konuşmaya

kaybolup gitmişse canan

ve vakit yoksa ağlamaya

onun aranan bakışlarından

şiirlere can damarıma kan

gibi bir alev dolanmıyorsa

ben bu karanlıklarda

susmaya dayanamam

ırmak olmuş bakışlar akıyor akıyor

böyle duramam

aşk yarılmak üzere bir gökyüzüdür şimdi

ki varolmak adına

kanıyor kanıyor

artık susamam

ilk sezgi ilk rüya ilk kelimeler

ben tutkunu oldum hıçkırıkların

konuşan ve susan o inlemeler

akar denizine tüm çığlıkların

gül ay ilk sevgiler ve bilmemeler

fakülte önünde bir rüzgar esse

ne faytonlar geçer ne çocukluğum

çırpınan halimi bilmiyor kimse

yanağımda deniz ayağımda kum

boğuldum boğuldum artık gülümse

gülümse gülümse gülden yumuşak

bir deniz gözlerin uçsuz bucaksız

olsa da ufukta kanlı bir şafak

gel anla bu aşkı mavi gözlü kız

gülümse gülümse ateşten sıcak

ürperir tüm dünya ağlar çocuklar

aşk yanar dayanmaz yakar baharı

sendedir mevsimler rüzgâr sonbahar

altın saçlarında renklerin sırrı

ürperir göz kırpar beyaz bulutlar

lambalar sönüyor yağmur yağacak

artık bir kelebek intihar eder

söyleyin layyaya neler olacak

yüzümü yalayan mesut kediler

lambalar söndükçe artıyor sağnak

atma çiçekleri küller üstüne

dağlarda bir nevruz olup ağlama

çocuklar oynuyor bak döne döne

inceden bir sızı düşmüş yarama

atma çiçekleri seller üstüne

yağmur çağırıyor o toprak damlar

yağmur çağırıyor o müthiş mavi

gölgeyle savaşan çirkin adamlar

öpüyor durmadan bir küçük devi

yağmur çağırıyor buğulu camlar

ben bu şehre artık veda edemem

açmışsa gül olup göğsünde ölüm

bu aşkı bu halle sana diyemem

yürüyen dehşeti ben öldürürüm

sen aşkın annesi sen çılgın matem

bir dünya uzuyor boş odalarda

sönmüşse yıldızlar ne arıyorum

çığlıklar canverir gece ardarda

sana ben sislerden yalvarıyorum

ben yeryüzünde ben sevdalarda

kül edip bırakma yanan başımı

bir hal gelir sonra ben yaşayamam

gel bir ses boğmadan şu genç yaşımı

tükenir sözcükler süreler tamam

bir resim eylersin ağlayışımı

sönüyor gözlerim boş odalarda

yalnızım boşluğu yumrukluyorum

aşk ve ten bir yalan aşka dalar da

sonra ölür diye çok korkuyorum

gezginler koşuyor tüm adalarda

sessizdir yeryüzü ve koşar cinler

dünyanın cebinde bir delikanlı

ses verir geceye ve şehri dinler

uyur gencecik kız gözleri kanlı

etsek de biz aşka nice yeminler

ey görkemli kusmuk üniversitem

kara kitaplara damlıyor kanlar

sevda perde perde bir yüce matem

biz bir evren gizi bizi kim anlar

layyada çığlıklar ve bende sitem

ıslakmış gözleri sevmişim diye

nazlanır kahkaha atarmış sonra

bir bulut etseydim ona hediye

göklere karışır yatarmış sonra

tutarmış saçını ibrişim diye

tutarmış ırmağı ve gözyaşımı

onun düşlerinde olup bitenler

getirse yağmurdan arkadaşımı

karışır yağmura karanlık tenler

yeryüzü dizinden atar başımı

tenimde ceylanlar bir yarış gece

gözleri gözleri layyanın deniz

geçiyor ruhumdan eşsiz bilmece

ağlamak ki uçsuz bucaksız bir iz

giriyor trenler son dönemece

dünya tren tren akar yollardan

bir adam savrulup gurbet oluyor

anneler bakıyor tüm balkonlardan

ve annem eriyip hasret oluyor

layya dönüp dönüp bakar yollardan

gözler ıslak gözler ceylan ak gözler

turnalar yağmura kapanır şimdi

akıyor akıyor bir ırmak gözler

çarpar da ruhuma utanır şimdi

ölünce toprağa akacak gözler

zakkum çiçekleri kurşuna dönmüş

titriyor arzuyla kızın elleri

kalbimde içiçe çöller bölünmüş

bir rüzgâr tutuyor bütün selleri

rüyalar karanlık lambalar sönmüs

evinin içinde ruhum dolaşır

yağmur hafif hafif vurur camlara

her güzel kalbinde bir hançer taşır

ve bir aşk yerleşir loş akşamlara

ruhunun içinde ruhum dolaşır

artık ölüm benim içime konmuş

umut etmem artık öleceğimi

kar yağar dizlerim yatağım donmuş

bilmezdim ürperip güleceğimi

neylersin yüreğim güle dokunmuş

can gülüm hülyalar ve seni sevmek

ve söyliyememek ağlatır beni

konuşma dillerin alevlenecek

kar dolu bir göğe al yatır beni

kar altında aşklar karınca böcek

ışıktan da aydın kaçak bakışın

önüne kendimi koysam duramam

beni bir renk yakar kumral sarışın

güneşin sırrını böyle bulamam

ışıktan kapısı sonsuz bir kışın

ve suskun aşkların gözbebekleri

içiçe gölgeler tanrı ve kadın

öpüyor bir kara sevdalı yeri

ben yalan bir varlık sen bir rüyaydın

uçurdun ruhunda kelebekleri

merhamet pınarı dağda bir peri

bir masal içinde unutulmuştur

ben seni sevdiğim o günden beri

kalbim mahkum gibi ve tutulmuştur

kalbine ki kalbin sevgi mahşeri

gönüle işkence bir azap taşı

bir mendil bırakıp ve gidiyorsun

sigara ve küller aşk haritası

bırak boş hedefe katiller vursun

karanlık karanlık bir aşk hatası

şehir bunalıyor intihar kadar

gözlerin yok gibi dönmüş kurbana

kim kime ve nasıl canını adar

dilin mi tutuldu kalk anlat bana

ruhunda ruhumu uçuran rüzgar

anlasana gece kara dert kara

bembeyaz bir kader ve sessiz günah

kalbimi açtım ben sert rüzgarlara

yenik isyanlara parça parça ah

anlasana gece yara aşk yara

koşup peşinden ben nefes nefese

yıllar yılı seni arayacağım

kavuşsam sonunda büyük hevese

sevinçten diz çöküp ağlayacağım

el edip sırrımı soran herkese

düş gördüm sen yoktun çok uzaklarda

yusuf ile kenan görünüyordu

bir çocuğun gözü ak bayraklarda

durmadan züleyha ölmez diyordu

sen kendi göğünde ben sokaklarda

boynu bükük bükük açıyor şafak

günler zor geçiyor viranelerde

ben daha ölmeden şu evrene bak

yakma ellerini al perdelerde

herkes pişman herkes deli olacak

şafaklara vurur körpe çağrılar

çoğalır sancısı dudaklarımın

bir sırrı yakar bu yolunan saçlar

inler arasında parmaklarımın

şafaklara vurur sessiz ağrılar

gecelerde mini kediler uyur

sessiz sessiz ağlar küçük bebekler

layya bu şiiri dünyaya duyur

yine de sırrımı bilmeyecekler

bir sofra kur göğe aşkını doyur

o güzel kalbini nasıl vururum

sürgünden sürgüne atsa da beni

layya seni anar anar dururum

gemiler arzuyla açar yelkeni

korkular çağırır hain gururum

bir gemi yelkeni kanlara açar

ben sürgün anları anıp ağlarım

kurtlar gezer dağda kuzular kaçar

kalbimi elime alıp dağlarım

ne gökler alçalır ne kuşlar uçar

içimde bir hiç var inanmadığım

savaştan savaşa gelirmiş veba

bir neşe içinde ben bir çığlığım

dost kardeş sevgili anne ve baba

ne kaldı dünyada tanımadığım

bir mavi ışığın elleri değmiş

dışımda içimde hep çizgi çizgi

ve layyam başını önüne eğmiş

tutturmuş kendince bir garip ezgi

rüyası göklerden düşen bir çığmış

mahzun boş ellerim ah gülüm layya

gözlerim gerçek mi yeşil gözlerim

bir daha dönmedi bülbülüm layya

ondandır yanıyor karda dizlerim

yanıyor her yerim ah gülüm layya

şaşkın şaşkın düşen kara bakma sen

uzanır göklerin kaderi bize

dönüşsüz yollarda gidip bekleşen

verirler söylenmez haberi bize

ruhunu bırakıp böyle çıkma sen

gölgesi dünyanın nerelerdedir

geceden geceye dönermiş geri

aşktan mı hülyama serilen sedir

döner durur aşkla göğün dipleri

ve uzaklar döne döne delirtir

ey dudaklarımda zamanın pası

çıldırma belası gibi aramak

kana boyanan bir gelin yazması

ağıtlar içinde ölüme durmak

ölümler ölümler hiçliğin yası

cennet ve cehennem ve gülüm suna

incecik ruhumun şarkısı ağır

yer ve gök yer ve gök dönmüş efsuna

bin kapı ardından bir melek çağır

ve çağır cinleri aşk uykusuna

çağır gelsin hayat sonra intikam

sevdalar düşümün salıncağında

aşklar yarım yarım garip bir akşam

kederden bir nehir varlık dağında

gelsin gözyaşlarım gelsin ihtişam

dışarda insanlar vahşi ve yamyam

ve aşklar değişmiş aşklar kudurmuş

içerde bu garip bu yalnız babam

bir geyik postunda kıyama durmuş

belki sevmem daha belki uyanmam

onlar ki dünyanın gariplikleri

bu yoksul dünyada ben onlardanım

onlar ki sevdanın son iplikleri

bir rüya uğrunda yananlardanım

yanmak ki dünyanın delilikleri

ufukta bir şehir ve gülüm layya

elleri elleri asılı göğe

sırtımda bir hançer bir ölüm layya

gel çıkar dönmeden kanlı çiçeğe

bak kendini boğan bir gölum layya

istanbul ve bursa arası yollar

gözlerin yolları aşıyor gibi

ve ölüm aşkına açılan kollar

kolların içinde yaşıyor gibi

kalbimle kalbinin yarası yollar

ezmeden ezmeden kaldırımları

bu şehrin kalbini diri isterim

bir kurşun çağırır tüm rüyaları

ben o an en güzel yeri isterim

denizi masmavi kuşları sarı

nisan yağmurları ne zaman gelir

kurak aşkımıza bir pınar gibi

bizi anneler ve çocuklar bilir

ne zaman görünür denizin dibi

denizi ne zaman bırakır nehir

gözlerini layya yukarı çevir

birşey sallanıyor uçsuz bucaksız

umutlar devrilir aşklar devrilir

yaz biter mevsim kış ağaç yapraksız

beyaz pencereden karanlık gelir

delilik ve cinnet içinde suna

toprağa bir tohum bırakıyorum

ağıtlar düşüyor dudaklarına

ben uzanıp göğe gül takıyorum

yakacak günüm yok artık yarına

ölümün alnından öpmek için mi

bu telaş bu koşu boş anonslara

ve hülya kurmayı bilmek için mi

sinema bileti son seanslara

hayatı hayata bölmek için mi

gökler ki yerlerde arar yıldızı

gündüzden de ışık gece tüm yollar

ey şehrin kaybolmuş efsane kızı

gökler seni anar sabaha kadar

gökler ki ruhunda sarar yıldızı

dondurma yiyen kız hani dondurman

dindirir mi artık ızdırabını

boşuna düşleri hep hayra yorman

rüzgârlar dolanır arar rabbini

bir eşarp bir yıldız ateş ve orman

küskün bir hatıra bir alkış layya

ben ki şehir şehir arar dururum

toprağa karışan yakarış layya

seni şiir şiir arar bulurum

titriyor istanbul bu son kış layya

karanlık yalnızlık içre karanlık

bakışın geceme damlarken benim

sonra kalabalık sonra ıssızlık

ruhunda ruhumu ararken benim

kara kara akan deli yalnızlık

bir gelin rüyası ateşten duvak

içinde aklıma sen geliyorsun

az sonra geceden resmin çıkacak

yaptığım resimde hıçkırıyorsun

sende bir deniz var beni boğacak

aşk nedir aşk nedir diye sorana

bir mahşer içinde yalnızlık dedim

sevda ateş gibi girince kana

uğuldayan şehre ıssızlık dedim

yıkadım andımı geldim kapına

gökyüzü uzakta değilse seni

fırat köprüsüne götüreceğim

bulmak için gelen kara treni

her gece bir türkü bekleyeceğim

tanrıdan esinti yağmurdan ninni

bir gelin rüyası bir yalın duvak

içinde aklıma sen geliyorsun

sende bir deniz var beni boğacak

bir gülüşün kalmış bir düş olmuşsun

herşey çığlık çığlık herşey yalnayak

kapılar kapanmış hıçkırıyorsun

ve maviyi geri istiyor kuşlar

aydınlık aydınlık ama sen yoksun

bir resim yanıyor sonra susuşlar

söyleyin öyleyse beni kim vursun

 

Sıtkı Caney', 'bir karanlıklarda çok az kalmışsa zaman aşk için konuşmaya kaybolup gitmişse canan ve vakit yoksa ağlamaya onun aranan bakışlarından şiirler...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Caney']::text[], 8.5, '{"poet":"Sıtkı Caney","poet_slug":"sitki-caney","theme":"Türk Şiiri","is_hero":false,"total_lines":323,"source_url":"https://www.antoloji.com/layya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layya - iki', 'layya-iki-sitki-caney-td2j6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iki

leylaklar yas tutuyor bu şehrin ötesinde

zindanlarda gül açmış bu gece duyuyorum

kaybolup gitmiş sesim senin tatlı sesinde

bu gece bir kartalı öldürmek istiyorum

rüyamda bir mezarın son defa yanan mumu

ve zakkum ağaçları tırmalıyor ruhumu

sana bu gece benim artık kaybolduğumu

söylenmemiş sözlerle bildirmek istiyorum

kimi uyur ve kimi dansa başlar delice

biri bu dansa bakıp matem tutar gizlice

bense burda yapyalnız tam bu saat bu gece

bu şehri baştanbaşa yürümek istiyorum

gülüm layya istersen hançer daya göğsüme

kimse şahit olmadı sevdaya küstüğüme

gecelerden bu gece bu soğukta üstüme

seni yalnızca seni örtünmek istiyorum

evrende paramparça güzelliğin aynası

kıvrım kıvrım bir sevda uzun bir yılan dansı

ve insanlar hep aşkı inkara hazırlanan

bu inkarla delirip hep bu inkarla yanan

uzaktaysa durmadan yağan doğu karları

dağlarda saklı duran keklik yumurtaları

ve mecnunun çölünde karıncalar böcekler

bulunca o şarkıyı artık ölmeyecekler

ve o şarkı dilimle dilinin arasında

o şarkı kanar durur bir ceylan yarasında

ceylanlar yaylalara mecnun gibi koşarlar

uzanır mecnun mecnun sinemizde şavkırlar

inler durur şarkılar ki o bensiz ben onsuz

bu duygu yakar beni o şarkı kadar sonsuz

sonsuz bir ağıt iner gerçek kara habere

gülüm layya kendini atar harabelere

harabelerde izler silinir sessiz sessiz

ben layyadan uzakta olur muyum habersiz

kara haber tez bulur bekleyen yürekleri

doldurur birileri boşalan tüfekleri

çekilince kurşunlar her ses kendine döner

bir hayat yanar yalnız bütün hayatlar söner

her gece insan kendi kendini yakmakta

ufuklar ağlamakta ve bir tren kalkmakta

bir tren midir yırtan geceyi baştan başa

vurma be gülüm vurma başını taştan taşa

durma gülümse layya bak horozlar ötmekte

bu şiir bitmemekte bu şiir bitmemekte

bak tedirgin ceylanlar aralıyor zamanı

gülüm layya gülüşün yaralıyor zamanı

ve sen benim sunamsın ama ben gidiyorum

çaresiz ellerini kaldırsan da göklere

bu aşkın inancına yeminler ediyorum

ayrılık dua olsun kuşlara böceklere

layya seni bulduğum anda kaybediyorum

ne kadar benziyorsun renkli kelebeklere

doğmamış bebeklere intikam diliyorum

güneşlerin ufkunda tutamayınca seni

aradım hep aradım bir mumun ışığında

ve mumlar alevlerde tüketince gölgeni

kaybettim ben kendimi cinlerle kafdağında

bir mezara gömülen hatıralar treni

saklıyor seni beni bir mahşer toprağında

güneş gibi kendime katamayınca seni

ey uyku zalimliği hızla eriyen zaman

dansediyor yumulan gözlerimde yılanlar

yanakları dünyanın layya senin ağlaman

efsane haber taşır artık baylar bayanlar

savurur şapkasını suya bir yavru ceylan

vurulur ceylan gibi canandan ayrılanlar

vurulur ağlamanın ince parmaklarından

bir yudum çay içerek kahvelerde oturmak

seni düşünmek için bahane olmuş bana

ve doğranan yudumdan tatlı vakitler kurmak

girmiş hırsızlık gibi ruhumun arasına

beni beklermiş deniz akıp gidermiş ırmak

katarmış beni kızlar yurdundaki yasına

bir yudum gökyüzüyle ötelerde oturmak

kalmadı lugatımda bu halin kelimesi

nazlı taze günlerden isyana koşuyorum

bir kız gülümsemesi uzak bir bomba sesi

ben bu müphem dünyada acılarla sarhoşum

olmadı hiç rüyamda bir güvercin kafesi

dünyada olamadı benim bir sai kuşum

kalmadı ceblerimde günlerin kelimesi

layya yenikapıda ruhunu aramasın

aramasın ruhumu çağdaş harabelerde

onu sonsuzluklara bu tek şiirle asın

ceylanlar avcıları düşürsün yine derde

layyalar doğmaz diye anneler ağlamasın

gülümseyecek layya her kızdaki kederde

hayat bende kaybolan huyunu aramasın

ararsa beni layya başlarsa ağlamaya

parlar mı gökkuşağı boynunda mevsim mevsim

koynunda yalnızlığın şehir kapalı aya

tenimin mendilinde dilim dilim bir isim

ben ki minnacık acun güller fışkıran kaya

alıp gitsem ruhumu tanınmasa cesedim

başlarsa ağlamaya ararsa beni layya

ben yeni bir inanca göçerken tek başına

dehşet gözyaşlarıyla bir gece örüyorum

geceler ki yürüyen sınırsızlık taşına

tozlu yollar boyunca hep seni görüyorum

bir cinnet öpüşüyüm çığlığa gözyaşına

bakış ince bir resim durmadan yürüyorum

gök yeni bir intikam biçerken tek başına

alıp dola boynuna kimsesiz odalarda

ta kalbinde kıvranan kıvranan ellerimi

ayrılık ılık evren limansiz adalarda

koşturur şafaklara yalnayak seherimi

güneşini al da gel konuş karanlıklarda

kesmesin şu ellerim burada kaderimi

alıp dola boynuna en sessiz adalarda

yorulmam çilelerden çilelerle uyusam

bir ninni şırıl şırıl yatsam su kenarında

bir evren tütsülenir senden bir nefes duysam

ve yıkanır ölüler bengisu pınarında

kandan ve gözyaşından seni damıtıp yazsam

canlanırsın dünyanın en derin duvarında

yokluğunda öteden gölgelerle uyusam

birgün sona erince bu dünya cehennemi

sen de anlarsın artık aynalar yalan söyler

ölüm erken olmasın çok özledim annemi

o yağmurlu turküyü şimdi ancak can söyler

hatırlanmaz sularda neyle sevişir gemi

bir de böyle türküyü yardan ayrılan söyler

eriyince ufukta bu rüya cehennemi

çobanlar kavalları damardan üfleyecek

bakıp bakıp ruhumda kurduğun saltanata

bir buluşma baharı bir gelincik bir çiçek

ağlıyor ötelerden hazan olmuş hayata

her hazan kıvrımında bin bahar dirilecek

baharlar uzar nile ve diceleye fırata

çobanlar kavalları bahardan üfleyecek

uzanır sereserpe parka fakir adamlar

kuşdilini konuşur uzakta bir yabancı

günahkâr yüreğime taze korkular damlar

her yanda dilenciler kaderime duacı

ne bu aşk unutulur ne de o genç idamlar

ne hoca anlar halden ne de çingene falcı

uzanır sereserpe göğe cesur adamlar

ki gökyüzü yeryüzü arasında bu sevda

nasıl yolsun anneler saçını nasıl yolsun

öncesiz ve sonrasız bir açlık ağlamada

sana ey yalan rüya kara yılanlar dolsun

bendedir zalimlikler ve ak gözler layyada

beyaz düşü karartan kara eller kahrolsun

kahrolsun gökyüzüne sıçramayan her sevda

gökkuşağı altında geleceğin koşusu

yıldızlar kanat olsun ve merhamet merhamet

tükensin istiyorum yalan ölüm korkusu

bir gelin bir bebeğe bir genç bir gence hasret

açar artık sırrını çölde saklı kalan su

günahsız bir sevdaya açılır kutlu cennet

ve layyanın alnında geleceğin kokusu

artık veda edemem bavullarımı yaktım

artık veda edemem yandı fırat köprüsü

bütün günahlarımı artık sana bıraktım

giriyor günahına bir kuş bir aşk ölüsü

çocuklar olmasaydı inan ağlayacaktım

sonkez söyleyecektim bir buluşma türküsü

bense hain saçlara kanlı çiçekler taktım

görünmez bir yerden öptüm dilini

dilini dilini gizli dilini

aşk şimdi bir yalan yalandır layya

ve bahar ve başak talandır layya

sen sıcak bir yarım düşün gelini

gelini gelini aşkın gelini

bulandır denizi bulandır layya

başını başımla dolandır layya

bir sözcük olsa da tutsam elini

elini elini nettin elini

kandır bu inceden yanandır layya

ve candır sevdadır canandır layya

nasıl savurdun oy sain telini

telini telini altın telini

aşktır duramayan akandır layya

derinden derine yakandır layya

aşk ki yakar birgün senin belini

belini belini sıcak belini

bir gül ki kalbime dolandır layya

düşün ki bu son ses son andır layya

yitirmiş dilini aşkın gelini

gelini gelini aşkın gelini

 

Sıtkı Caney', 'iki leylaklar yas tutuyor bu şehrin ötesinde zindanlarda gül açmış bu gece duyuyorum kaybolup gitmiş sesim senin tatlı sesinde bu gece bir k...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Caney']::text[], 8.5, '{"poet":"Sıtkı Caney","poet_slug":"sitki-caney","theme":"Türk Şiiri","is_hero":false,"total_lines":182,"source_url":"https://www.antoloji.com/layya-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili', 'ey-sevgili-edip-cangonul-3qo7v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ey sevgili

Uyu 

Uyumuşsundur da

Saat gecenin körü

Körün hırladığı vakit

Vaktin kamilleştiği an

Rüya gör ey sevgili

Tabiri ile

yorumsuz

Bir ben olayım rüyanda

Bir de sen

Dağlar olsun rüyanda

Başı karlı dağlar

Türküymüş gibi

Kaçak olak

          -peşimizde cenderme

dağlardan birinin in’i olsun emi

ya cenderme bilemesin orayı

ya da vursun beni girmeden in’e

veya da sen vazcay girmekten

in’e

veya 

hut 

da

“ölek ölek ölek barabar”

aynı rüyada

dağ harput olsun kurban

“karmı yağmış şu  harputun başına

kurban olam torpağına daşına”

bir deniz olsun ya da

rüyanda

mavi

masmavi

içinde balıklar 

mis

kenarında yosunlar

pis

sevişek birlikte

mehtaplı

mehtapsız

yakamozlar değsin sinene

rüyanda bir de ada olsun

deniz varsa eğer

bir ada

cunda

kıyıda da bir rum

rumun bir evi

rumun ekmeği bitsin

satsın evi

evini

eeeee

o zaman rüyanda paramız olsun

evi biz alak

oluruna

unutma 

söyle rüyana

bahçesi de olsun o aç rumun evinin

rum giritli olsun

ev olsun lo

bir de hasret', 'ey sevgili Uyu  Uyumuşsundur da Saat gecenin körü Körün hırladığı vakit Vaktin kamilleştiği an Rüya gör ey sevgili Tabiri ile yorumsuz Bir b...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ey-sevgili-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layya - üç', 'layya-uc-sitki-caney-4ftve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Layya - üç

şehir yorulmuş

bir kırık testi

sulara veda

yolumu kesti

ağlayan bir kuş

dağlara veda

sıla kül olmuş

bir rüzgâr esti

in cin elveda

sevda bir sisti

kaldı arkada

leylak yok olmuş

nevrûz dağlarda

güzel bir histi

şimdi kurumuş

deme hevesti

bir aşktı layya

içime konmuş

istanbul bir gece ve bir garip düş

ölüler mezardan kalkmış gibiydi

yürüyüş yürüyüş yine yürüyüş

yaklaşan mahşerin sırlı eliydi

unutmam geceydi ve tam bu saat

bir kadın köprüde öksürüyordu

şahlandı içimde saklı duran at

kadın suna olmuş ve yürüyordu

ne bir rüyaydı bu ne hayaletti

gördüm bizzat gördüm ve koşuyordum

kaba sığmaz bir ruh bir tutam etti

ruhuyla layyanın konuşuyordum

varınca köprünün tam ortasına

kaybolmuştu layya öylece durdum

kurşunlar doldurdum azap taşına

işte tam orada kendimi vurdum

bir çift göz ve deniz kana bulandı

depremler içinde şiir ocağım

uykudaymış meğer bu ölüm andı

uyandım büsbütün kayıp yatağım

vurulur tutkular birgün arkadan

tükenir gençliğin kara sevdası

kahpeler çekilsin artık aradan

kana bulanmasın aşkın duası

bir mektup çığlığı her gece veda

uzakta uzakta köy bülbülleri

kaçmak gibi belki ağlamak ya da

minnacık gencecik kızın gülleri

kararan yanıma bir dünya düştü

aç bana ey şiir ilk yüzlerini

kalbe dilim dilim bir rüya düştü

diyemem diyemem ilk sözlerini

aşklar ki azaptan ve demet demet

bir azap için mi öter bülbüller

yaklaşan seslerin içinde hasret

açıyor bu hasret içinde güller

beni ey tanrım de aşklardan yarat

bir bengisu gönder çıldırıyor aşk

dünya bir kahkaha inliyor saat

korkular içinde yemyeşil başak

sonsuz çığlıklarla derdi dinmeyen

gençlerin ruhunu ben hançerledim

o coşan gönlüne hükmedemiyen

bir kızın sesine kendimi verdim

bakıp durdum sana çılgın ve şaşkın

ve düştüm o meşhur belalı derde

sesler sırrı gibi sendeki aşkın

kaynıyor kaynıyor bilinmez yerde

aşk ver ey can gülüm bize bir aşk ver

bu aşk parça parça cinnet ve neşe

yağmurlar yağar da caddeler titrer

ben bir şey ararım hep köşe köşe

sen aşkı çıldırtan bir garip kızdın

ne sunaydı adın ne de canandı

eridin eridin içime sızdın

benim yalnızlıkta hafızam yandı

soldu menekşeler kokular bitti

ve kelimelerim bitecek gibi

aşk bizi bırakıp ilk ana gitti

ellerim evreni itecek gibi

zaman bir an gibi birden biterken

ben son kelimeyi seçemiyorum

aşklar için çok geç ya da çok erken

şiire bir kefen biçemiyorum

bir şiir yazılmış eksik ve yarım

şafaklarsa henüz kurşunlanmamış

layyanın uykusu ve rüyalarım

alevler içinde henüz yanmamış

bu şiir ne diye sormadın layya

bilseydin yeni bir mevsim olurdu

sonunda kendini vurmadın layya

göründü kayboldu sevdanın yurdu

çengelkoy kıyısı bekârderesi

sokağında yoksul bir evde şimdi

kaybolur sesimde layyanın sesi

kimdim ben bilinmez ve layya kimdi

kapanır senin de gözlerin layya

fakülte kapısı yerinde durur

beni deli etti bir garip rüya

seni de perişan bir garip gurur

 

Sıtkı Caney', 'Layya - üç şehir yorulmuş bir kırık testi sulara veda yolumu kesti ağlayan bir kuş dağlara veda sıla kül olmuş bir rüzgâr esti in cin elveda...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Caney']::text[], 8.5, '{"poet":"Sıtkı Caney","poet_slug":"sitki-caney","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/layya-uc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layya - ilk', 'layya-ilk-sitki-caney-5d1jl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Layya - ilk

gülhane parkında uçurduğum kuş

ürktü de konmadı dalına layya

lâl oldum görmedin bak olan olmuş

aç ruhunu bir bak falına layya

yağmurun farkında uçurduğum kuş

çıldırma salına salına layya

atarım kendimi kapanmaz kuyu

yazılar yazılır alına layya

efsanem sonunda böler uykuyu

gizlenir gözyaşın salına layya

istanbul göğünde bir hayal layya

limanda kimsesiz öyle kal layya

 

Sıtkı Caney', 'Layya - ilk gülhane parkında uçurduğum kuş ürktü de konmadı dalına layya lâl oldum görmedin bak olan olmuş aç ruhunu bir bak falına layya ya...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Caney']::text[], 8.5, '{"poet":"Sıtkı Caney","poet_slug":"sitki-caney","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/layya-ilk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layya - son', 'layya-son-sitki-caney-lplxt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben var mıydım o var mıydı

bu şehrin kalbini yakan ateş miydi kar mıydı

ve bir de gözleri vardı layyanın

her gece kalbimi yardı

gözlerin sırrı söylenmemiş sözler kadardı

ben var mıydım o var mıydı

sonra saçları yayıldı layyanın

dönüp dönüp evreni sardı

ben var mıydım o var mıydı

adı ne sunaydı ne de layyaydı

ben var mıydım o var mıydı

her gece bu şehirde bir insan

sevmeyi bilemediğinden

kendini asardı

aşklar ağlardı

ağlamak bir mahşer kadardı

ben var mıydım o var mıydı

şahan olan bu canda

leylak bir güneş

ve gül ay mıydı

ben var mıydım o var mıydı

adımız bir damarda durmadan doğar mıydı

yeşil gözlerim yeşil gözlerim

öyle durmadan maviye maviye

durmadan akar mıydı

böyle mi bitsin bu öykü

bitmeyen inleyen inildeyen bu öykü

bitmiyor ağlıyor uyku ağlıyor sessiz

eriyor eriyor sırrımız mavi deniz

eriyor güller aylar çizgisiz

gönül yapraklarında

gönül yapraklarında

bilmem bu öykü bu kadar mıydı

ben var mıydım o var mıydı

söylenmez söylenmez geriye kalan

aşkın dudaklarında

aşkın dudaklarında

varamam varamam varıp bulsaydım onu

bu şiir beni hiç bu kadar yakar mıydı

ah ben var mıydım o var mıydı

unutmak sözcükten olmasın ey sevgili

açılır evrenin yüce kitabı zamanın arkaları

görünmez bir seste görünür tanrı

gül ay ve bahar ve gece hep bana bakar mıydı

ben var mıydım o var mıydı

ben var mıydım o var mıydı', 'ben var mıydım o var mıydı bu şehrin kalbini yakan ateş miydi kar mıydı ve bir de gözleri vardı layyanın her gece kalbimi yardı gözlerin sır...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Caney']::text[], 8.5, '{"poet":"Sıtkı Caney","poet_slug":"sitki-caney","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/layya-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak', 'tik-tak-cem-yilmazer-pumdb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saatler çalıyor.

Hiç durmadan, 

Ömrümün en güzel, 

Kısacık yıllarından.', 'Saatler çalıyor. Hiç durmadan,  Ömrümün en güzel,  Kısacık yıllarından....', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tik-tak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta', 'nokta-cem-yilmazer-q025s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya; 

Uzayda bir nokta.

Ben; 

Dünyada bir nokta.

Hiçbir şeyin değeri yok.

Her şey alt tarafı: 

Yan yana üç nokta...', 'Dünya;  Uzayda bir nokta. Ben;  Dünyada bir nokta. Hiçbir şeyin değeri yok. Her şey alt tarafı:  Yan yana üç nokta......', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nokta-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi', 'kedi-cem-yilmazer-tbzmc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Resimler çizdim senin için; 

Kuşları, hamam böceklerini...

Ve bir de kediler...

Hele kediler...

Onlara o kadar benziyorsun ki; 

Baktıkça onlara, 

Seni düşünüyorum.

Ve seni çiziyorum.

Nankör kedi kızım.', 'Resimler çizdim senin için;  Kuşları, hamam böceklerini... Ve bir de kediler... Hele kediler... Onlara o kadar benziyorsun ki;  Baktıkça onl...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kedi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burda Olmayayım', 'burda-olmayayim-cem-yilmazer-dw4y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ah, şu an burda olmasam.

Başka  yerde, 

Belki uzayda, 

Belki bir ağacın üstünde, 

Kimsenin olmadığı bir yerde.

Kendimle başbaşa kalayım, 

Gölgemle konuşayım, 

Yıldızlara şarkı söyleyeyim, 

Sincaplarla şakalaşayım, 

Burada olmayayım.', 'Ah, şu an burda olmasam. Başka  yerde,  Belki uzayda,  Belki bir ağacın üstünde,  Kimsenin olmadığı bir yerde. Kendimle başbaşa kalayım,  Gö...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/burda-olmayayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıklıyorum', 'sayikliyorum-cem-yilmazer-5u479', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sayıklıyorum, 

Ve...

Gece yatağımın köşelerini, 

Kapıp da dinliyorlarmış beni.

Ağladığımı gördükleri an, 

Hepsi ağlarmış benim gibi.

Sabahları yastığım ıslak, 

Gözlerim ıslak, tenim ıslak, 

Dudaklarım ıslak, kalbim ıslak, 

Ellerimde tuttuğum

Resimlerin ıslak.

Gözyaşlarım buharlaştı.

Bulut oldu, yağmur oldu.

Belki de dünyadaki okyanusları, 

Benim gözyaşlarım oluşturdu.

Yine uykuya dalıyorum, 

Uyuyup yine sayıklıyorum.

Ama bu kez yalnızım...

Bir ben varım, seni sensizlikte arayan, 

Bir sen varsın, rüyalarımda uyuyan.', 'Sayıklıyorum,  Ve... Gece yatağımın köşelerini,  Kapıp da dinliyorlarmış beni. Ağladığımı gördükleri an,  Hepsi ağlarmış benim gibi. Sabahla...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sayikliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş O Zamana Övgü', 'gecmis-o-zamana-ovgu-kursat-usalan-ngzii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Bilmeden sarılırdım soluğun tutardı beni

Bir pencere açılrdı ta boğaziçine

Yetmişiki olurdu takvimler kanlı

Bir çocuk ağlaması hapsolurdu içime

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Öyle bir çocuktu ki o; kelebek ömürlü

Taş duvarlarda kaldı hep bacağının bir yanı

Yirmiüç Nisan’ların bayram olduğu yıllarda

Sonbahar meydanına darağacı kuruldu

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

O zamanlar Kızılay’da Kızılay binası vardı

Ankara’lı üç camlı yana yatık otobüs

Tedavülden kalkmadan bu çocukluk günleri

Caddede tekerlek yaktılar dünyaya karşı 

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Deniz nedir bilmezdik, serin gözlerin yoktu

Kabzamıza kazıdık en utangaç sözleri

Tel sapanlar depoda, dünyaya küskün

Sloganlar söylerdi duvarda türkümüzü

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

İlk kitabım hediye solcu komşumdan

Bir,1 Mayıs sabahı, okullar tatil

Sorsam söyler mi babam grev ne demek? 

Beslenme çantamda “bahar bayramı”

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Mamak dolmuşları nereden kalkıyor? 

Şirin gecekondu evlerinden geçer mi? 

Sonbaharda mahkumlar neyi özler? 

Görüş günü olursa sen gelir misin? 

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Sazın asılı hala odanın duvarında

Tavşan kanı çayını artık içemez olduk

Kurumuş dudakların sıcak yaz güneşinde

“Barikat”, sokağının, değişmiş adı olmuş

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

Bir rüya gördüm sonra vatan-i görevimde

Bir çocuğu asmışlar henüz onyedisinde

Tank sesiyle uyanmış ülkemin kitapları

Telörgü ve geceyle kuşatmışlar yaşamı

Aklıma arka bahçemizdeki akşamlar geldi

Ölüme aldırmayan genç yaşlarımız geldi

Anneannemden istediğim peynir-ekmekler gibi

Doyurmuyor ki artık bir şey midemi

Herbirimiz  birer yolcu olmuşuz

Yıllar arttıkça da artıyor yolculuğumuz

Uykusuz gecelerden Akdeniz’e sürüldük

Kazı şimdi kazıyabilirsen kendini

Bir yanım hep yetmişli yıllarda kırık kaldı

Bir yanım sorguluyor dünya alemi

				17.04.1994

				ANKARA', 'Bir yanım hep yetmişli yıllarda kırık kaldı Bir yanım sorguluyor dünya alemi Bilmeden sarılırdım soluğun tutardı beni Bir pencere açılrdı ta...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/gecmis-o-zamana-ovgu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersname', 'tersname-mahzuni-serif-h48bj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana diyeceğim var eğlen yolcu

Kurduğun yuvayı yık da öyle git

Zamanede ilk görevdir insana

Baştan dinden haktan çık da öyle git

Bir sudan geçince köprüyü devir

Sel basmış tarlaya ırmağı çevir

Birlik dümenini tersine kıvır

Sağa sola sövüp dök de öyle git

Allah bir deseler sen söyle haşa

Nadanın ehliyle çıkılmaz başa

Komşunun açlığı tatlı tamaşa

Bir tekme de sen vur yık da öyle git

Ortak isen hesap etme ölçmeyi

İhmal etme dost ırzına geçmeyi

Bir döğüşte çok ayıp gör kaçmayı

Beş on yumruk yiyip sek de öyle git

Elinden tut çamurlara at körü

Beriye öte de öteye beri

Kapıya gelirse döv misafiri

Bir de ana avrat çek de öyle git

Kızına bakanın oğlunu öldür

Meclise girersen büyüğe saldır

Kefeni soy mezarlara kül doldur

Ölünün dişini sök de öyle git

Ciğerin yarası sivri cam ister

Kötülük meydanında kendin göster

Adamın cömerdi yavuz it besler

Meteliği başa kak da öyle git

Küfür eksik etme aziz dilinden

Gaddarlık kılıncın koyma belinden

Hiçbir şey gelmezse bile elinden

Fesat tohumunu ek de öyle git

Hasılı sözümün tersine yürü

Görmesin gözlerin topalı körü

Kısa yerden eksik etme ömürü

Mahzuni Şerif’ten bık da öyle git', 'Sana diyeceğim var eğlen yolcu Kurduğun yuvayı yık da öyle git Zamanede ilk görevdir insana Baştan dinden haktan çık da öyle git Bir sudan g...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tersname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abur Cubur Adam', 'abur-cubur-adam-mahzuni-serif-uew78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçi yalan dışı yalan

Her bakışı binbir plan

Gül boyanmış kara yılan

Abur cubur Abdullah

Etme dedim tutma dedim

Dostluğu unutma dedim

Sana verdiğim lokmayı

Çabuk biter yutma dedim

Abur cubur adam

Ben seni nidem

Daha kendini bilmezsin

Kimdir yanındaki madam

Bir elinde kamerası

Sanırsın film ağası

Her dolapta numarası

Abur cubur Abdullah

Etme dedim tutma dedim

Dostluğu unutma dedim

Sana verdiğim lokmayı

Çabuk biter yutma dedim

Abur cubur adam

Ben seni nidem

Daha kendini bilmezsin

Kimdir yanındaki madam

Der Mahzuni tövbe olsun

Böyle dost düşmana kalsın

Şeytanlar namazın kılsın

Abur cubur Abdullah

Etme dedim tutma dedim

Dostluğu unutma dedim

Sana verdiğim lokmayı

Çabuk biter yutma dedim

Abur cubur adam

Ben seni nidem

Daha kendini bilmezsin

Kimdir yanındaki madam', 'İçi yalan dışı yalan Her bakışı binbir plan Gül boyanmış kara yılan Abur cubur Abdullah Etme dedim tutma dedim Dostluğu unutma dedim Sana ve...', ARRAY['Türk Edebiyatı','Şiir','Mahzuni Şerif']::text[], 8.5, '{"poet":"Mahzuni Şerif","poet_slug":"mahzuni-serif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/abur-cubur-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Begonyalı Pencere', 'begonyali-pencere-ahmet-ada-qdv19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin bu küsümser yüz

Bir ağlar bir gülersin

Seninle ayakta duruyor

Hercai sözcüğü.

Seninle biçim - bozuma

Uğruyor Türkçe.

Günübirlik değerleri ters yüz ede ede

Döküntü değeri kazanıyor

Her sevgili.

Yüzün göğe açılmış

Gündeş yazı

Begonyalı pencere', 'Senin bu küsümser yüz Bir ağlar bir gülersin Seninle ayakta duruyor Hercai sözcüğü. Seninle biçim - bozuma Uğruyor Türkçe. Günübirlik değerl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/begonyali-pencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuk', 'bir-cocuk-ahmet-ada-pt2b7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ey engin gönüllü düşsever

Sıfatsız derviş

Dolaştın içinde hep özveriyle

Doğu''yu, Batı''yı, sokakları

Sokaklar ki leylak kokardı

Şuraya koymuştun masaya

Çiçeklerin sokak görgüsünü

Sokakların çiçek örgüsünü

Sen ey uçuruma atlayan çocuk

Anlat şimdi uçurumu, uçan çiçekleri

Bazı güneşleri büyük sulara akan

Bazı aşkları beyaz sessizliğe akan

Bak işte geçti yine

İçinden sümbül yeleli bir at

Sen ey uslanmaz kalender

Doğu''lu bilge, gün doğdu bak

Hasret burcuna düştü

İmgelerin sınırsız dalga boyu

Deniz kıyısında denize karşı

Yaktı sigarasını bir atlı

Sen ey uslanmaz uçarı çocuk

Anlat şimdi vişneçürüğü ufku

Uçurum sessizliğinde suçsuzluğunu

Bak işte Cemal Abidir

Laleli''den dünyaya doğru giden bir tramvayda

Onun kasketine yağan yağmuru anlat', 'Sen ey engin gönüllü düşsever Sıfatsız derviş Dolaştın içinde hep özveriyle Doğu''yu, Batı''yı, sokakları Sokaklar ki leylak kokardı Şuraya ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-cocuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-ahmet-ada-82ag6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denize çıkan sokak soğuktur üşürsün

Ey ince gömlekli Akdenizli çocuk

Yaz geride kaldı yetişirsin sonbahara

Bütün ömrün yok olan mavi bir bakış

Gibi geçiyor bir solukta bilmiyor musun

Yağmura yakalanmış bir kuş gibi üşürsün

Ey parke taşların ağarttığı çocuk

Kalbin deniz üstü yağmur, saçların uykulu

Gülerken güz resmini çekmiş sanki

Yaprağı sapsarı yaprakla bitiştiren

Yaprağı hüzünle değiştiren güz

Bir çarkıfelek otunu değiştiren güz

Önünde çakıl taşları deniz kıpırtısız

Bir park kanepesinin akışında unutulmuş

Güller de birdenbire sızar kalbine

Avlulara girersin: karşında güz

Mor bir gölge şurda ve sonyaz kokusu

Tam öyle işte yıkılmış bir atın duruşu', 'Denize çıkan sokak soğuktur üşürsün Ey ince gömlekli Akdenizli çocuk Yaz geride kaldı yetişirsin sonbahara Bütün ömrün yok olan mavi bir bak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/resim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe', 'serce-ahmet-ada-63qc0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Giydim ben de yalnızlık hırkasını

Dilimde eski hüzzamlar

Kulağımda ipek sesi unutulmuş hatmi çiçeğinin

Kar mavisi kirpiklerinin sesi

Bir güvercin curcunası olan yaz göğünün sesi

Usulca çömelip yem arayan serçe sesi

Uçtum o serçeyle

Uçmasını bilen limon ağacının sesi

Bir Chagall resminin çocuksu sesi

Uykusuz şairler korosunun güneşli sesi

Sanayi sokağında hangarların orada

Uçarı gölgelerin sesi

Mozaikler arasından püsküren bir çiçeğin sesi

Manastır avlusunda

Bir Sümer tabletinin kırık sesi

Yaklaştım yanına gök sayfaları arasında

Sırlar saklayan kapıların sesi

Seviyorsan beni hala saçındaki leylak sesi

Kökü ordadır diye sevdanın

Bir bumerang gibi sana döndüm

Varoşların burcu kalbine

Yaşadım beter bir aşkı, öğrendim

Kalp kalesinin ikiye bölündüğünü

Dolunayların senin çocuk gözlerine dolduğunu

Bunun şaşırtıcı bir şey olduğunu

Solgun gelinciklere söyledim

Ürgüp''te

Develerin üstünde hatıra fotoğrafı çektiren seyyahlara

Bakırcılar çarşısının esnafına

Çömlek ustalarına

Çuha çiçeklerine söyledim dere boyunda

Bir tel uzadı ışıklı bir tel saçında

Giydim aşk urbasını sana geldim

Birdenbire yaz yağmuru başıboş caddelerde

Giyindim yağmuru sana geldim

Üstelik vakit ikindi, 

Kalbe akan çınarların sesi

Balkonların kuş vakti, vaktin sesi

Seviyorsan beni hala pırıl pırıl sevdanın sesi

Yağmur muydu yağan yoksa yıllar mı

Kirli sarı bir şehir omuzlarımda

Sokuldum kırık yazılara

Yazıların veda sesi

Kuş sayfaları arasında', 'Giydim ben de yalnızlık hırkasını Dilimde eski hüzzamlar Kulağımda ipek sesi unutulmuş hatmi çiçeğinin Kar mavisi kirpiklerinin sesi Bir güv...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/serce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-ahmet-ada-0zzdp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte yine sığmıyorsun hiçbir kitaba

Sen ey uçurumdan çekilen şiir

Hangi sürgünden dönüyorsun kimbilir

Bir elinde üçüncü mevki tren bileti

Bir elinde de kış çiçeği

Sevdiğin bir gençkız için', 'İşte yine sığmıyorsun hiçbir kitaba Sen ey uçurumdan çekilen şiir Hangi sürgünden dönüyorsun kimbilir Bir elinde üçüncü mevki tren bileti Bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ada']::text[], 8.5, '{"poet":"Ahmet Ada","poet_slug":"ahmet-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siir-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanama', 'kanama-ahmet-ozer-5eodd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'insanın yabanıl yanı kanıyor her gece

bir saatin sesiyle akarak düşlerimize

göçüp giden kuşlarla

bir yolun sorduğu soruları çoğaltarak

alıp başımı gitsem

taşlara sorsam / ağaç gövdelerine / yıldızlara

çocukların meraklı yüzlerine

kaldırımlarda ayak seslerimi duyan kitaplara

	birden

	bir tarçın tadı

	yanar

	dilimde

	sesi kanar denizin

dizelerim

yeşerir

geçtiğim kentlerde yankılanan.

göğsümde bir sızıdır şiir

nerede ne zaman çığlık oldu

	bilmediğim

yüzümle çakıştığında yaşadıklarım

bir suyun önü açıldı / gördüm.

hangi gün nerede

nasıl tutuştu yaşadıklarımız

bir sorudur hep yanıtı bulunmayan

koynunda salındığımız yıllar

yazıya dökülen sözlerimiz.

alıp götürse bir tren / yolculuklara

	gökyüzü

	ve yıldızlara tanık gençliğime elvererek

tarihin alnında bir karanfil tüter

bir yangın dökülür

güneşle yıkanan dilimden.', 'insanın yabanıl yanı kanıyor her gece bir saatin sesiyle akarak düşlerimize göçüp giden kuşlarla bir yolun sorduğu soruları çoğaltarak alıp ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kanama-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Sevgin', 'senin-sevgin-ahmet-ozer-tq7jy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gül bahçelerinden geçen yağmurlar

saçlarını dağıttı günlerime

yüzün şiir ülkem oldu / kuş sevinçleri yüreğin

sevgini serptim geçtiğim denizlere.

bir sabah alıp gittin sevincimizi

şarkımız yarım kaldı aysız gecelerde

anılar yürüdü günlerimize

elverdik rüzgara seni taşıyan.

şimdi geçtiğim her sokakta yangınlar

uçsuz bucaksız acıları damıtıyor

yüzünü kapıyor şiir dizelere sığınarak.

kendine yenildiğin bir akşam

ellerin yitti karanlıklarda

yazdıkların tutanağıydı hayatın.', 'gül bahçelerinden geçen yağmurlar saçlarını dağıttı günlerime yüzün şiir ülkem oldu / kuş sevinçleri yüreğin sevgini serptim geçtiğim denizl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-sevgin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-neyzar-karahan-9fd7l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çoktandır sana gelmemiştim

Solgun bahçesinde yalnızlığın

Şimdi bir rüzgar oldum

Esiyorum çiçeklerin üstüne

Günlerden çarşamba

Güneş nisan gülüşleriyle

Göz kırpıyor yüreğimin ırmaklarına

			Nasılsın demeyeceğim

			Sonsuzluğun bittiği yerde

			Sen başlıyorsun

			İçimde

Seninle oluşur yeni bir galaksi

Dağlar denizler bulutlar

Ayrılık değil falımda çıkan

Günlerden perşembe

Güneş nisan kelebekleri gibi

Konuyor yüreğimin karanfillerine

			Hiçbir şey anlatamıyorum sana

			Kıskıvrak bağlanmışım karanlığın ipiyle

			Dilsiz bir orkidenin yalnızlığı

			Tütsülenmiş gözlerinin buğusuna

			Pencerelerin esrik gözleri

			Düşer kirpiklerinden yıldız yıldız

Günlerden cuma ya da cumartesi

Ayrımsızdır benim için

Pazar pazartesi salı

Her gün bir nisandır ışıltısıyla gelen

Her gün büyüyen bir şiirdir

İçimde seninle esen', 'Çoktandır sana gelmemiştim Solgun bahçesinde yalnızlığın Şimdi bir rüzgar oldum Esiyorum çiçeklerin üstüne Günlerden çarşamba Güneş nisan gü...', ARRAY['Türk Edebiyatı','Şiir','Neyzar Karahan']::text[], 8.5, '{"poet":"Neyzar Karahan","poet_slug":"neyzar-karahan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/siir-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acının Miladıyla', 'acinin-miladiyla-ahmet-telli-8uas0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acının miladıyla başlayan bir hikayedir bu

yaşayıp gelmişiz ormanlar bir yanarak

her dönemeçte uğultulu uçurumlar

her şafakta uzun uzun kurt ulumaları

Ey masalcı

otur şu geyik postuna

ve anlat şimdi bütün bunları

Önce yaşadıklarımızı koy ortaya

hatamızı ve sevabımızı anlat

görelim nelere kahretmişiz bunca zaman

nelere göğüs germişiz görelim bir bir

bedeli ödenmiş midir şafağın, bilelim

yaşamak

yeni acılara sürgün etse de bizi

Hayatımız göründüğü kadar basit değil

ama anlaşılmaz gibi de değil öyle

çoğunu unuttuk belki şimdiden

belki bitti birtakım bekleyişler

umutlar da bitti bir zaman, sevgiler de

ama unutmayalım

zulüm de biter hayatımızda', 'Acının miladıyla başlayan bir hikayedir bu yaşayıp gelmişiz ormanlar bir yanarak her dönemeçte uğultulu uçurumlar her şafakta uzun uzun kurt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/acinin-miladiyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-hidayet-karakus-zrnwb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'doğum tarihi yeni bir kimlik buldum

adımı yazdım fotoğrafımı yapıştırdım

bir bulut gibiydi boşluktan gelen görüntü

top sesleri dağların ardından yükseldi

sanırım dünyaya yeni bir gol attılar

denizleri oyuncak leğenlerinde çalkalayan

çocukların barış gemilerinde yüzer gibiydim

yüzer gibiydim annemin saklı denizlerinde

bir kimlik buldum fotoğrafı yoktu

numarası yoktu, doğum yeri boş

senin adını yazdım yaşını belirledim

kendi fotoğraflarımdan çıkardım seni

anıların düşten yataklarında sevdim

büyük kentlerin varoşlarından derledim

dereboylarında sele kapılan kadınların

kapı numaralarından buldum yüzünü

siz köşe başlarında ayak üstü gözlenenler

geçerken görülenler ara sıra adı duyulanlar

numaralarınızı söyleyin dünyaya geliş numaralarınızı

sürücü belgelerinizin numaralarını

sigorta poliçelerinizin umutlarınızın

mezarlarınızın pafta numaralaranı

sevdiğiniz kadınların sütyen bedenlerini

omuz gerdan numaralarınızı

sayısız sayılardan oluşan numaralarınızı

söyleyin söyleyin ve geçin tarihteki raflarınıza

anladım ben yufka yürekli zamanlarda

senin yelelerine tutunmuşum

beni yerlere seren rüzgarınmış meğer

anladım bu kimliğin numaraları yalan

kalbi bomboş bir tarihin külü yalnız

anladım büyük ateşlere yazılı adımız.', 'doğum tarihi yeni bir kimlik buldum adımı yazdım fotoğrafımı yapıştırdım bir bulut gibiydi boşluktan gelen görüntü top sesleri dağların ardı...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Karakuş']::text[], 8.5, '{"poet":"Hidayet Karakuş","poet_slug":"hidayet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/arayis-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-hidayet-karakus-gbo8r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iki üç sözcükle

postalanan

kartlar gibiyim

yalnızlık

kendini bana ayarlamış

takviminde

geleceğe gün arıyor', 'iki üç sözcükle postalanan kartlar gibiyim yalnızlık kendini bana ayarlamış takviminde geleceğe gün arıyor...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Karakuş']::text[], 8.5, '{"poet":"Hidayet Karakuş","poet_slug":"hidayet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bayram-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyücü', 'buyucu-hidayet-karakus-f1ipq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suyu dağıt ateşi çöz

saçlarını gözyaşlarının koyağında kurut

hırçın ve aldanmış bir badem ağacının şimdi

parlat düşlerini çocuğum

içimize vuran zincirlerin şıkırtısında

ateş yorulur ağrılar erir

nice masalların sütüyle kesilen göğsün

bir anka kuşunun göğsüne düşer

soluğun bir uzar beni yakalar

bir sararır sonbahar olur

suyu değiştir ölümü büyüle

güğümünü doldurduğun çeşmelere sesini bırak

yaşadığını söylesin acının saatleri', 'suyu dağıt ateşi çöz saçlarını gözyaşlarının koyağında kurut hırçın ve aldanmış bir badem ağacının şimdi parlat düşlerini çocuğum içimize vu...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Karakuş']::text[], 8.5, '{"poet":"Hidayet Karakuş","poet_slug":"hidayet-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buyucu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havai Fişek', 'havai-fisek-i-nci-asena-8m3ux', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle havai fişekler patladı ki denizin üzerinde

		-ben haberleri dinlerken

öyle güzel havai fişekler patladı ki

		-hiç görmediğim kadar

giderek öyle yaklaştı ki pencereme

içeri doldu sanki üstüme yağdı.

Seni düşünmeden edemedim.

***

Seni ne zaman düşünsem

gazete kağıdından bir gemiye konmuş

arkasından küçük bir fiske vurulmuş

süzülerek giden, başı dik ve gözleri cam

bir çocuk geliyor aklıma.', 'Öyle havai fişekler patladı ki denizin üzerinde 		-ben haberleri dinlerken öyle güzel havai fişekler patladı ki 		-hiç görmediğim kadar gide...', ARRAY['Türk Edebiyatı','Şiir','İnci Asena']::text[], 8.5, '{"poet":"İnci Asena","poet_slug":"i-nci-asena","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/havai-fisek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyla Uynamışım', 'korkuyla-uynamisim-i-nci-asena-7ar55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece gözlerini kapamış

Gökyüzünde ay

Dinginiz aslında

Tesadüfen çatal sesleri arasında

Tesadüfen kansız bir gün metrekaremizde.

Aldırmıyoruz

Soframızı altüst eden

Desibel desibel ezan sesine.

Ve uzaktan ulumalar.

Biraz çiçek, biraz böcek, 

Geç kalmış baharın kucağında.

Birden ay patladı

Korkuyla uyanmışım.', 'Gece gözlerini kapamış Gökyüzünde ay Dinginiz aslında Tesadüfen çatal sesleri arasında Tesadüfen kansız bir gün metrekaremizde. Aldırmıyoruz...', ARRAY['Türk Edebiyatı','Şiir','İnci Asena']::text[], 8.5, '{"poet":"İnci Asena","poet_slug":"i-nci-asena","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/korkuyla-uynamisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız', 'adsiz-ergin-gunce-vhzjj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adımız bahçenin köşelerinde saklı

Yeminimiz sözümüz sevgimiz

Bu sarı kağıtta saklı

Güneş işte orda bayram yeri

Sularda ilk cemre

Gökte bir leylek buluyorum

Nedir beni dalgınlığa götüren

Şehirden dönünce bulamamak mı

Yoksa bu yaşta ölümden mi korkuyorum

Bahçenin içinden annemin kahkahası.', 'Adımız bahçenin köşelerinde saklı Yeminimiz sözümüz sevgimiz Bu sarı kağıtta saklı Güneş işte orda bayram yeri Sularda ilk cemre Gökte bir l...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin-gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adsiz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Ağaçlar Seni Söyler', 'butun-agaclar-seni-soyler-mustafa-miyasoglu-o3nfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ucunda korku var gülüşlerimin

Arka arkaya bıraktım pabuçlarımı

Bütün ağaçlar seni söyler

Yırtık resimlerin gülüyor bana

Bütün perdelerin ardında sen

Tren sesleri kaçırmaz insanı

Bir çığlık getirir bunalan geceye

Nice tünele girer içimden korkunç

Ben bunu düşünür yüz yıllarca

Unutulmuş bir tarihi yaşarım

Ve.. bütün ağaçlar seni söyler.', 'Ucunda korku var gülüşlerimin Arka arkaya bıraktım pabuçlarımı Bütün ağaçlar seni söyler Yırtık resimlerin gülüyor bana Bütün perdelerin ard...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Miyasoğlu']::text[], 8.5, '{"poet":"Mustafa Miyasoğlu","poet_slug":"mustafa-miyasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/butun-agaclar-seni-soyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun', 'yosun-mustafa-miyasoglu-qyvh4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin en uç yerinde bir kadın

Örer saçını köpüklü mermere

Parmakları ucundan tutar karanlığın

Ve ömür uzanır bilinmez yere

Saçlarından tuttum gecenin

Yüreğimde ne korku ne keder

İçimde sonsuzluğu bu sevginin

Baktım yüzüne dünyalar değer

O ölüm ötesi kaygılarınla

Bir sevgi kulesidir erişilmez için

Kuru bir dal korkunun uzanışı

Ve ürkek bir tavşan gibi gözlerin

Çıkardım kalbini ay ışığına

Yıkandı acının en derin izi

Belki taş altında kemik ve kül

Bilinmez korkunun karanlık yüzü

Deniz yıllarca besler kalbinde

Sonsuz çırpınışlarını bir arzunun

Duyulur kayanın yeşil dilinde

Bitmeyen açlığı o ilk yosunun', 'Gecenin en uç yerinde bir kadın Örer saçını köpüklü mermere Parmakları ucundan tutar karanlığın Ve ömür uzanır bilinmez yere Saçlarından tut...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Miyasoğlu']::text[], 8.5, '{"poet":"Mustafa Miyasoğlu","poet_slug":"mustafa-miyasoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yosun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz''in Uğultusu Üstünde', 'akdeniz-in-ugultusu-ustunde-nihat-behram-o9bzi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akdeniz

yaslı deniz, 

suboyu

uğul uğul

titreşen yüreğimin

tutuşan

dostu deniz...

Akdeniz

ufkun yanağında

uzanır maviliğin

acıyan tomurcuğa.', 'Akdeniz yaslı deniz,  suboyu uğul uğul titreşen yüreğimin tutuşan dostu deniz... Akdeniz ufkun yanağında uzanır maviliğin acıyan tomurcuğa....', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/akdeniz-in-ugultusu-ustunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykudaki Korku', 'uykudaki-korku-nihat-behram-yh2go', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece kuşları

ışığı tel tel koparıyor pencereden

Ay

yapraklarından

köklerine inmiş papatyaların

Çöllerin

kuru hışırtısını titreyen bir yılan

sanki kıvrılıp kayıyor

gözlerindeki tümsekten

Kalbin geceyle bir gemide

Kapın ya açıldı ya açılacak

Duvarında her gün

gelincik yaprakları toplayan resim

ürkmüş, sığmıyor çerçevesine

Çocukların

düğün evlerinde dolaşan uykusu

zambaklar topluyor

yorgun dönerken bahçelerden

Oysa

ağaç kabuklarını dolduran nem

yıldızları saçlarından gizliyor senin

Her gece bir bekleyiş

kırılmak üzere örtülen kapıların

merdiven ayaklarıyla birleştiği yerden

ürperip çekiliyor

Her gece bir bekleyiş

onların oyulmuş göz çukurlarını perçinliyor

ayrılırken hüzünle bakacağın

başucundaki resme', 'Gece kuşları ışığı tel tel koparıyor pencereden Ay yapraklarından köklerine inmiş papatyaların Çöllerin kuru hışırtısını titreyen bir yılan ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uykudaki-korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Dediğimiz Feryat', 'yasamak-dedigimiz-feryat-nihat-behram-s0uez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbini taşırken harcadığın kuvvet

ufacık elleri olan bir devin çırpınışlarıymış, 

o dev ki: mızraktan yağmurlar altında dolaşarak

bileklerini incecik yasemin saplarına alıştırmış

Demek ki, seninle tanıştırdığım sihir

arpaların, kozaların, peteklerin, 

aslına astarına aşk denilen, 

burçlarında atmacalar, şahinler barındıran, 

bağrın bağra çarpışından

başlayan sevdalı buluşmaların

ürünü bir sihirmiş, 

o sihir ki: kanında öpüşlerin olduğu kadar

şerefli ayrılıkların kıpırtılarını da biriktirmiş

Şimdi beton üstüne serilmiş bir döşeğin kıyısında

bunları yazarken

şaşkınlıklar ve özlemlerle zenginleşen sözlerin

senden çaldığı sıcaklığıyla vedalaşmadayım, 

ve - sevgilim - bıraktığın notu okuduğum sıralar

koyu bir gecenin çıngıraklarından

çok uzakta olacağım, 

üstelik dağlarda, bayırlarda bile

zaptedemediğim o feryadı

çaresiz, oradan

parmaklıklar ardından taşıracağım

Şurada, kaçaklık aylarımın son günüyle

geçip gidiyor hayatımın bir dönemi...

İşte köşesinden köşesine dolaştığım şehir; 

işte içime dolan hava; 

böğürlerimdeki çılgın girdabı aldığım her nefesin...

gelişime kapı örtenler de oldu bu şehirde

yatak serenler de gecelerime

Sen gözlerinin maviliği gözyaşlarına bulaşan titreyiş, 

yosunları dalgalara kıyılara vuran kuvvet, 

sen akılalmaz sarplıklardan fışkıran çiçeklerdeki fiyaka, 

doğuruşların görkemini taşıyan şefkat, 

cançekişler, gerinişler, intikam duyguları, 

yetkinlikler, eriklerin ham lezzeti, körpelikler, 

midyelerde incileşen kumtanesi: aynı hızla

yolumu gözle - geleceğim -

unutma ki

bu gidişler zaferi getirecek...', 'Kalbini taşırken harcadığın kuvvet ufacık elleri olan bir devin çırpınışlarıymış,  o dev ki: mızraktan yağmurlar altında dolaşarak bilekleri...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasamak-dedigimiz-feryat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-nevzat-celik-l2m4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir gün eğer yolun

düşerse sorguevlerine

cinsiyetin yaşın rengin

farketmez kardeşim

yeter ki

tükür dilini yüzüne', 'bir gün eğer yolun düşerse sorguevlerine cinsiyetin yaşın rengin farketmez kardeşim yeter ki tükür dilini yüzüne...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ogut-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vişneçürüğü Aşklar', 'visnecurugu-asklar-osman-olmus-tkmv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'VİŞNEÇÜRÜĞÜ  AŞKLAR

	

	        	 

dullar: yüzlerinde hep vişneçürüğü bir aşk saklar

saklamaz sekiz silindirli chevroletlere binerdin

binek atları kesilince ağzında kesme şekerleri

emerdin sessizce -emily: emzikli bir çingene

kılığına girmeden üflerdin sûr düdüğünü surdibinde

sekiz beygir kesilince sesin -duyulmaz: kekeme

teyyarelerin bildiri dağıttığı yıllar

                                              -ah! tangolar-

susmazdı -sabaha kadar açmayınca sardunyalar

apartman boşluğuna açılırdı bir pencere: camsız

ve apansız girdin gerdeğe: ilgiye mazhar

                                          -çekirdeksiz bir mandalin-

gibiydin.üstelik ekşi ve henüz soyulmamış

kadınları hep sen keşfederdin: kâşif amundsen

ah! keşke sevmeseydin.çürüdüğünde vişneler

                                       boyanır aşk

ve iksir -çok eskidir- içmedikçe ekşir

dulların yüzü: sekiz silindirli bir chevrolettir

bagajında kırık bir çeyiz sandığı: sırf ceviz

kabuğunu doldurmayan bir aşk yüzünden

kesilirse sekiz beygirin sekizi de birden

penceredeki sardunyalar vişneçürüğü açsın lütfen! 

taş plakta tangolar: uzadıkça uzasın

emily diye çağırdığım tüm cücelerin boyu

				                      -kısalmasın-

ağzında kesme şekerlerinin en uzun ömrü

dökülünce boyası chevroletlerin: boyanır aşk

ve iksir -çok eskidir- içmesen de eksilir

dulların yüzü: çekirdeksiz bir mandalin kadar ekşidir

			       10 mart’91/sahne

			        Osman OLMUŞ', 'VİŞNEÇÜRÜĞÜ  AŞKLAR 	 	        	  dullar: yüzlerinde hep vişneçürüğü bir aşk saklar saklamaz sekiz silindirli chevroletlere binerdin binek a...', ARRAY['Türk Edebiyatı','Şiir','Osman Olmuş']::text[], 8.5, '{"poet":"Osman Olmuş","poet_slug":"osman-olmus","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/visnecurugu-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiirler', 'bu-siirler-refik-durbas-1ky53', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimde kan izleri anıların

tarçın kokusu, belki menekşeler

Belki bir ünlem işareti merak

nasıl solgun ve bulanık şiirler

Şiirlere uyanmak istedim de

Çünkü soruda ve sorguda gelecek

günler: neyin bedeli bu işkence

Bu ruhsatsız gurbet, tükenmiş sıla

kimin adına yazıldı söylesene

Yüzümde kuş sesleri acıların

Kır çiçekleri getirdim sana

bir umut, tanıdık korkular biraz

Günler: biraz olsun akılnda tut

ve unutma nasıl, kime yazıldı

Anılarını unutmuş bu şiirler', 'Kalbimde kan izleri anıların tarçın kokusu, belki menekşeler Belki bir ünlem işareti merak nasıl solgun ve bulanık şiirler Şiirlere uyanmak ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Altında Bir Sabah', 'kar-altinda-bir-sabah-refik-durbas-i80rs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağzında yasin gülleri

tuğladan çocuklar döküyor

kar altında bir sabah

toprak kokuyor nefesi

Silmiş künyesini haritadan

taze bedenler yontuyor

kar altında bir sabah

kederin ve aşkın dülgeri

Ruj ve kelebek mimarisidir

geçmiş günlerden düşen alnına

kar altında bir sabah

erkenden aydınlanıyor kefeni

Bulutlar ve yaralı kuşlardan

serin mezarlıklara

kar altında bir sabah

gül ve rüzgardır yağan şimdi

Kim anlar şairlerden başka

çürüyüp solsa da şiirler

kar altında bir sabah

ölümün yüzündeki cevheri', 'Ağzında yasin gülleri tuğladan çocuklar döküyor kar altında bir sabah toprak kokuyor nefesi Silmiş künyesini haritadan taze bedenler yontuyo...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kar-altinda-bir-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse', 'kimse-refik-durbas-t66aq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'flütüm ince ve bereketli yüzümle

her akşam yeni bir dansı çalardı

yürürken yaylasında en uzun gün

kahve fallarında fincanlarda

ve bir sessizliğe ekleyip kendini

birden barbar sesime dolardı

ne kadar derin ve titrekse dolardı

kendisi olan tabancasını dolardı

yüreğimin leylaktan bir çan olduğu

biriken bir kini usuldan üflerdi

süngülerin açtığı ilaçlı soluğuma

bir akşam kuytuluğunu taşıyaraktan

şimdi kime söylesem umutsuzluğumu

günün çoktan indiği kılıçlar derinlikte

aşkların bittiği unutulan derinlikte

bütün herkesle ardarda derinlikte

artık soluyor kanım ağzımda

flütün keskin ve öfkeli

yorgunum çalmasını unuttum

gitsem yüreğim hızlı bir dansa dönerken

sevgi kimbilir nerde kaldı unuttum

şimdi kime söylesem umutsuzluğumu

unuttum', 'flütüm ince ve bereketli yüzümle her akşam yeni bir dansı çalardı yürürken yaylasında en uzun gün kahve fallarında fincanlarda ve bir sessiz...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kimse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar da Ölür', 'kuslar-da-olur-refik-durbas-wjha4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sabah böyle ağlar mı Üsküdar

yoksul karanlığında kuşların

aşkın ve umudun bir de acının

rüzgarıyla uçarken bulutlar

Herkesten çok kendime yabancı

yaşadığımdan bir hayli yanlışsam

kim süzer gözlerimden ışığı

ölümü yüreğimde avlamışsam

Çalınsa da inancın alınteri

sessizlikle boğulsa da sesim

şafaklar yazacaktır kimliğini

ufkumu kuşatan denizlerin

Sabah olsun, giderim, sen kalırsın

kalır seninle, binlerce kuş cesedi

içimde sönmeyen o diri yangın

ve sessizliği özetlemek hüneri

Aydınlığından damlarken umutlar

zulmün ve kederin bir de acının

hala barınağıysa yalnızlığın

artık her sabah ağlasın Üsküdar', 'Her sabah böyle ağlar mı Üsküdar yoksul karanlığında kuşların aşkın ve umudun bir de acının rüzgarıyla uçarken bulutlar Herkesten çok kendim...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuslar-da-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurtma', 'ucurtma-refik-durbas-zoqkp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ev hapsinde küsülü

hasret kuşu çocuklar

Göz hapsinde aydınlık

gurbet kuşu çocuklar

Sonsuz sürgün babaları

İş hapsinde günlerin

keder kuşu çocuklar

Düş hapsinde perişan

ardıç kuşu çocuklar

Mapusa bağlı yolları

Uzun ömürlü mektularda

adresi saklı çocuklar

Kimi telli kavaklı gökyüzü

kimi ipini salmış uçurtma

''Görülmüştür'' yazıları', 'Ev hapsinde küsülü hasret kuşu çocuklar Göz hapsinde aydınlık gurbet kuşu çocuklar Sonsuz sürgün babaları İş hapsinde günlerin keder kuşu ço...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ucurtma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler', 'siirler-refik-durbas-83arm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey ezilmişlik! 

	bir gün ben de ulaşacağım kapılarına.

yoksulluğun o sonsuz panayırını aşacağım.

	aşkın şiirini ve memuriyetini kuracağım

	ve elbette bitecek zamanla edebiyat tarihi

sevdanın ve alkolün kahramanlığı er mektupları

gurbetin yüreğimi dağlayan diktatörlüğü.

	sevgilim acemi bir karanfil gibi açıyor

her sabah şehrin yanaklarında

	bense her gece sıkıntıdan ve yeminden

elbiseler biçiyorum, namussuz ve onurlu sevdalar

	dağları dağları da deliyor yalnızlık

	ışıdım yoksulluğa, perişanlığa.

	uykusuz kamyonlar çizdim gecenin alnına

devşirme köyler, puslu kasabalarda dolaştım.

	kaç yıl

	umudun ve ezilmişliğin çadırında besledim

yorgunluğu

	sokakların dilber ellerinden öptüm

	saçlarını okşadım dağların

	ve kuşlar bile uğramazken karanlığıma

şimdi hey desem şehri saçaklarından sarsıyor yalnızlığım

	eğil yüzüme sevgilim, çöz iplerini

o uslanmaz hayvanlığımı utandır, bırakılmışlığımı çınla

	çünkü doymuyorum abazanlığıma pazar

mecmuaları, şahane çirkinliğim ve hülyalarımla

	ey serseriliğim, ey anılarımın ahşap kraliçesi

	şarabı sev, tütünü incitme, beni de unut artık.', 'ey ezilmişlik!  	bir gün ben de ulaşacağım kapılarına. yoksulluğun o sonsuz panayırını aşacağım. 	aşkın şiirini ve memuriyetini kuracağım 	v...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Nerede?', 'sair-nerede-refik-durbas-frymc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbaharın ara sokaklarında günlerim

yazım nerde, kışım nerde

Dağlara ırmaklara yükleyecektim derdimi

atım nerde, bahtım nerde

Yüzümün kırık aynasında uyurdu geceler

adım nerde, çağım nerde

- Şair, hangi kara karanlığında geleceğin

çağrın nerde, çağrım nerde

Eser şimdi ihtiyarlığın yeli zamanı hayatta

Refik nerde, Durbaş nerde', 'Sonbaharın ara sokaklarında günlerim yazım nerde, kışım nerde Dağlara ırmaklara yükleyecektim derdimi atım nerde, bahtım nerde Yüzümün kırık...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sair-nerede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süngü', 'sungu-refik-durbas-xb6ot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'işte akşam tenimi geren kıyısı

yüzümle çağdaş makinesini sürerdi

petrolün kanımda biriktiren

çiçeği dolardı ekmeğime

kuş olur boyardım ormanı

çünkü azalırdı sömürgesi

çünkü o hiç orman olmamıştır

rüçhanın anlattığı bu

işte geldim yangın yüzü

odalardan sürgün döllere

bırakıp aşkı makinelere

şimdi pençemi süngüleyen

etimde o kalın çark sesi

diyorum ki gerçekse eğer

dönmeliyiz artık

isyan etmeliyiz

bakın nasıl mermiliyorum alnımı

paslı mazotuna göğün

çünkü azalırdı sömürgesi

çünkü o hiç gök olmamıştır

rüçhanın anlattığı bu', 'işte akşam tenimi geren kıyısı yüzümle çağdaş makinesini sürerdi petrolün kanımda biriktiren çiçeği dolardı ekmeğime kuş olur boyardım orman...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sungu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum Ölüm', 'oglum-olum-refik-durbas-ft3zv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tenim kurudu hasretinden

sulara adamıştım senin

sulardan narin bedenini

gözümde yaş kurudu oğul

Göklerin poyrazına

bağışlamıştım senin

ölümünü, benim ecelimi

bağrımda taş kurudu oğul

Ateşin rahminden çalmıştım

benim ihtiyarlığımı, senin

sevdalara kurban ömrünü

yaşmağımda kan kurudu oğul

Vazgeçtim ben ecelimden

sen de gel vazgeç bugün olsun

hayın ölümden, zalım ölümden

canevimde can kurudu oğul', 'Tenim kurudu hasretinden sulara adamıştım senin sulardan narin bedenini gözümde yaş kurudu oğul Göklerin poyrazına bağışlamıştım senin ölümü...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oglum-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firar Türküsü', 'firar-turkusu-sosyal-ekinci-tkqgt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'oturmuşum bir köşeye

bir kuş tutsak ellerimde

iki damla yaş dizimde

gözlerimse yok yerinde

kuşun gagasında bir ses

''haydi firar firar! '' diye

inansam mı uyansam mı

tenim yapışmış demire

fırladım ayağa kalktım

karşımda bir demir kule

üstünde üç büyük lamba

''sakın! '' diyor gözederek

yüksek kulede lamba

nöbet kulesinde memet

lamba bir dakka sönmeli

memet bir rüya görmeli

demir kule büyük lamba

yanıp sönen tuzak ışık

hazırladım her şeyimi

bu gece ben firariyim

demir kule büyük lamba

bana sahte umut verme

şaka değil bu dediğim

bu gece ben firariyim

bir dakika geç yanmazsan

kuledeki büyük lamba

nöbet kulesinde memet

başlar kurşun sağnağına

memet gözünü seveyim

çek tetikten parmağını

üşüyorsun yağan karda

ayşe''yi düşüne çağır

kanın kaynasın damarda

ıpıltılı gözlerinle

ayşe''yi düşüne çağır

uyan ki ben kuş olmuşum

tetik düşür yardım çağır

öyle hüzünlü bakman

küçük kardeşimi andırır

bir anlık bir yanılsaman

bana çok şey kazandırır

karşımda alacaduvar

içimde dost ihaneti

gölgelerden geçeceğim

akbenekli atlar gibi

otuz metredir tünelim

çıkışa vardıktan sonra

bir dakika geç yanarsan

menzili rahat geçerim

işte girdim tünelime

çıkışta beni bekleme

görürsen de sen içinden

''görmedim'' de tetik çekme

kızılca parladı güneş

geceki yağmurdan sonra

işte alarm çığlıkları

işte fırtına başladı

haydi yoldaşlar camlara', 'oturmuşum bir köşeye bir kuş tutsak ellerimde iki damla yaş dizimde gözlerimse yok yerinde kuşun gagasında bir ses ''haydi firar firar! '' diy...', ARRAY['Türk Edebiyatı','Şiir','Sosyal Ekinci']::text[], 8.5, '{"poet":"Sosyal Ekinci","poet_slug":"sosyal-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/firar-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Şiirim Ateş Hattına', 'haydi-siirim-ates-hattina-i-smail-uyaroglu-2acqx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hıncı tanıdım ben artık

Öfkeyi tanıdım

Şiirim tanıdı kendini

Kelimelerin güneşli ve doğurgan yüzünü

Tanıdı şiirim

Umudu tanıdım ben artık

İnancı, ölümü

Sevgilim

Bağışla beni

Yazamam bundan böyle aşk şiiri

Ben artık kavgayı tanıdım

Ölürken herkes bir şey uğruna

Kan kokusu

Bastırırken baharın taze kokusunu

Sinerken alanlara, dağlara

Hayatın en ince kıvrımlarına

Yazamam, yazamam aşk şiiri

Bağışla

Yaktım sıkıntının sözlüğünü

Yeni bir kitap buldum kendime

Ateşten, kandan, umuttan

Öğreniyorum ölmeyi

Ölerek yaşatmayı

Ağzımda şarabın değil artık

Yepyeni bir kelimeyi haykırmanın

Doyumsuz tadı

Evet şiirim

Biz ki zorlu günler yaşadık

Acından ve çileden dokundu kumaşımız

İyi biliriz hayatı

İşte ses veriyor, dinle

Çağırıyor savaşa

Artık bırakıp hüznü, içliliği

Çıkmak gerekiyor kelimelerin dağına

Haydi şiirim

Sen de ateş hattına', 'Hıncı tanıdım ben artık Öfkeyi tanıdım Şiirim tanıdı kendini Kelimelerin güneşli ve doğurgan yüzünü Tanıdı şiirim Umudu tanıdım ben artık İn...', ARRAY['Türk Edebiyatı','Şiir','İsmail Uyaroğlu']::text[], 8.5, '{"poet":"İsmail Uyaroğlu","poet_slug":"i-smail-uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/haydi-siirim-ates-hattina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ki Bilsinler Bundan Sonrakiler', 'ki-bilsinler-bundan-sonrakiler-i-smail-uyaroglu-hk74u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Madem doğmuşuz bir kere

Yaşadığımız belli olsun bari

Diyedir yazdığım bunca şiir

İsterdim, kalsın benden de

Bir şeyler bu dünyada

Bir kelime, bir hece

Ki bilsin bundan sonrakiler

İsmail diye biri yaşamış

Ne günü günmüş, ne gecesi gece', 'Madem doğmuşuz bir kere Yaşadığımız belli olsun bari Diyedir yazdığım bunca şiir İsterdim, kalsın benden de Bir şeyler bu dünyada Bir kelime...', ARRAY['Türk Edebiyatı','Şiir','İsmail Uyaroğlu']::text[], 8.5, '{"poet":"İsmail Uyaroğlu","poet_slug":"i-smail-uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ki-bilsinler-bundan-sonrakiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin', 'zeytin-sina-akyol-hx4m7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cancağ''zım, otursaydık

kavun lezzetiyle! 

Söz ki derindeydi, 

eridi, hamur oldu; 

işte onu lezzetiyle! 

Epey sustum; sesimin

yorgun lezzetiyle! 

(...) 

Zeytin mi dedim? .. Dilim

siyaha çalar. Yeşilken

ağuydu söz. Onu çizdim, 

hünerimle işledim.

(...) 

Ben şimdi ağzıma

öp desem, 

elim sevinir.', 'Cancağ''zım, otursaydık kavun lezzetiyle!  Söz ki derindeydi,  eridi, hamur oldu;  işte onu lezzetiyle!  Epey sustum; sesimin yorgun lezzetiy...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zeytin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Geldim', 'yorgun-geldim-sina-akyol-f0e2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seninle

uykular, uykular, 

uykular uyudum.

Sana erken sabahta

taze değdim.

Meğerki göğsüne

göğsümle değdim.

Ettim şikayet.', 'Ben seninle uykular, uykular,  uykular uyudum. Sana erken sabahta taze değdim. Meğerki göğsüne göğsümle değdim. Ettim şikayet....', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yorgun-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simurg', 'simurg-sina-akyol-63zot', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnce sordum, 

kalın anladım.

Simurg, dedim.

Güzel yalan! 

Yazdım: 

Otuzkuşu.

Hiç kuşu.', 'İnce sordum,  kalın anladım. Simurg, dedim. Güzel yalan!  Yazdım:  Otuzkuşu. Hiç kuşu....', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/simurg-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Şiiri', 'safak-siiri-sina-akyol-dp3ot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargaları ürküten ezan sesi

sabaha değiyor.

Sabah bana değiyor.

İçim acıyor.', 'Kargaları ürküten ezan sesi sabaha değiyor. Sabah bana değiyor. İçim acıyor....', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/safak-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafakla', 'safakla-sina-akyol-tweb4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onlar, erkenci güvercinler, 

sevişmenin kuytusuna, argın

tüyler bıraktılar. Kanat vurmak

sonraki işleri. Değil mi ki beden

arındıkça uçuşur.

...Sabahtı, sana geliyordum.

Böyle deyip geliyordum.', 'Onlar, erkenci güvercinler,  sevişmenin kuytusuna, argın tüyler bıraktılar. Kanat vurmak sonraki işleri. Değil mi ki beden arındıkça uçuşur....', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/safakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Şiiri', 'sevgi-siiri-sina-akyol-d3sd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayacığın kasıldıkça

ayağımı buluyor.

Benim de zaten

gözüm seğiriyor

yalnız durdukça.

Ne yapsak? Biz bize

mi değsek? Sonra bir gün

yol olsa, 

gezmelere gitsek.

Gümüş derelere

gümüş derelere', 'Ayacığın kasıldıkça ayağımı buluyor. Benim de zaten gözüm seğiriyor yalnız durdukça. Ne yapsak? Biz bize mi değsek? Sonra bir gün yol olsa, ...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgi-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saten', 'saten-sina-akyol-0k8yp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-I-

Sabahın serinliğiyle yazıyordum; güneş

hınzır bulutla çekişiyordu.

-II-

Uyuyordun, uykunun kıyısında

usulca durdum.

Yastığına taze otlar bıraktım.

Biraz gümüş, biraz şiir ekledim.

Şenlensin diye om''zun, 

ıslık çalıp çağırdım: 

Gelen, 

çayırkuşuydu.', '-I- Sabahın serinliğiyle yazıyordum; güneş hınzır bulutla çekişiyordu. -II- Uyuyordun, uykunun kıyısında usulca durdum. Yastığına taze otlar...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarın Zararları', 'ruzgarin-zararlari-sina-akyol-98b2y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-I-

Çıkıp gittin...

Sokak

ve rüzgar

sevinmiştir.

-II-

Dönüp gel... Gelirken, 

sevinçler, telaşlar, yemişler getir.

Hem de çarşı, sor bakalım

hoşnut mudur göğünden? 

-III-

Ben mi? .. Seni demliyorum: kurnaz

kafiyeler bularak... İşte bak, boynun...

diye yazdım. İlle de redif: boynun! ..

ki açıktır: haylaz, 

netameli rüzgara.', '-I- Çıkıp gittin... Sokak ve rüzgar sevinmiştir. -II- Dönüp gel... Gelirken,  sevinçler, telaşlar, yemişler getir. Hem de çarşı, sor bakalım...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruzgarin-zararlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşanmak', 'kusanmak-sina-akyol-5j08d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana güzel haberler ulaştırsaydın, içimin rengine aldırmazdım.

Sevinç elbisemi giyerdim.', 'Bana güzel haberler ulaştırsaydın, içimin rengine aldırmazdım. Sevinç elbisemi giyerdim....', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kusanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelduvar Günlüğü''nden', 'guzelduvar-gunlugu-nden-sina-akyol-hj1c8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Sabahla! Sabahın serin

testisiyle başlarım-

Böyle deyip eskittim

yetmiş altı güneş günü.

Tanığımdır: ardıç dalı, 

keçi yolu, şen patika.

Sabahla! Sabahın serin

gömleğiyle bitirdim.

Bayrak astım. Süsledim.

Özenerek ağladım.

Akşam vakti sularım.', '-Sabahla! Sabahın serin testisiyle başlarım- Böyle deyip eskittim yetmiş altı güneş günü. Tanığımdır: ardıç dalı,  keçi yolu, şen patika. Sa...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/guzelduvar-gunlugu-nden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönerken Yıldızlar Gelincikler Gülünce', 'sonerken-yildizlar-gelincikler-gulunce-kaan-i-nce-e9zyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolun hiç de uzak değil umut biliyorum

Sesin yağmurla birlikte tutuklu tel örgülerin arkasında

Bulamıyorum seni beni unut gidiyorum

...

Ve kuğuların kucakladığı, kentin denizsiz kıyısı

Uzak düşler hala gemi mendireğine çekili korsan sevgilere

Hasret düş kırklığı ölü sayrısı

Güvercin taklaları art arda

Kırmızı gece usulca bekler

Ah acıları tütsülü acıları

Büyük harfle başlayan aşkımızı

Kırılmaz kinle

Sönerken yıldızlar gelincikler gülünce

Sen gelelne kadar

...

Yasak dizelere girebilirdi ancak kaçak sözcükler

Ancak ölüm hüzünlü şiirlere

Acemi yüreğim girerken yirmisine

Bilemiyorum gözlerim kimde?', 'Yolun hiç de uzak değil umut biliyorum Sesin yağmurla birlikte tutuklu tel örgülerin arkasında Bulamıyorum seni beni unut gidiyorum ... Ve k...', ARRAY['Türk Edebiyatı','Şiir','Kaan İnce']::text[], 8.5, '{"poet":"Kaan İnce","poet_slug":"kaan-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonerken-yildizlar-gelincikler-gulunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımından', 'yol-ayrimindan-tugrul-asi-balkar-ol59s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-hey nereye gidiyorsun böyle

-düşünmedim hiç

-oraya bırakayım seni gelsene

peşindeyim. bıraktığımız iz

yüreğimin dışındaki pençeli kafes

her çırpınışı beni sana götürür

sen nereye gidersen git

tınısını yitiren ezgiler tamamlarım

türküler mutluluğa kavuşur

ben söylencelerin yitiren kahramanı olurum

örneğin don quijote alonso quijano

yeniden yazılır roman

hey nasıl da savruluyoruz

peşindeyim bıraktığımız iz

çığlığının suda halkanan yalnızlığı

her kulacım beni sana götürür

sen nereye gidersen git

istersen bir ateş gemisi ol

her atışta bir diğerini yitir

istersen bir pieta

başını meryem''in dizlerine yaslamış isa

ey nasıl da ağarıyoruz güneşle

peşindeyim, bıraktığın iz

peşittanın ilk satırı

her göze geliş beni sana götürür

sen nereye gidersen git

göle dalan karabataklara

yem olur çıkar o kadim süryani

mardin beni bağışlar belki deyrüzzeferan asla

tbargelia şenliğinin son günah keçileriyiz biz

kötü yazgıyı kovmanın bedeli

                                         günbe

                                                   gün

ah nasıl da ölüyoruz sevinçle

peşindeyim iz bırakmasam da

asi çocuk, yorulmadım

asi çocuk

asi çocuk

asiiiiii', '-hey nereye gidiyorsun böyle -düşünmedim hiç -oraya bırakayım seni gelsene peşindeyim. bıraktığımız iz yüreğimin dışındaki pençeli kafes her...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul-asi-balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yol-ayrimindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Requiem', 'requiem-turgay-kanturk-0dejr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-I-

Dönsem bir şeyler umarak, dönmesem kim sürer ayak izimi, 

benden başka? Son katın da tutulduğunu bilmesem, bu gövde

kendine kiracı, demlenir.

-II-

Dönerim bir gün, dal gelir dünya. Kalsam giderim buralardan

gitsem oralarda kalırım, yarım.

-III-

Parmaklarımdır tarih; mürekkep ve hokka, o gri kalem, 

yazsam hep sarmal-gece. Kimbilir hangi kapıdır, geçmiş dolunaylar; 

çalmayın! Açılmaz, kendime yazdığım mektuplar! 

-IV-

Çeksem tetiği, kimseler ölmez. Kuşatır eşyanın yılgınlığı; 

siyah! Gitgide uzaklaşan kent rüyasıyım. Kendine saplanan

ok olurum, yok olurum; ölemem!', '-I- Dönsem bir şeyler umarak, dönmesem kim sürer ayak izimi,  benden başka? Son katın da tutulduğunu bilmesem, bu gövde kendine kiracı, deml...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kantürk']::text[], 8.5, '{"poet":"Turgay Kantürk","poet_slug":"turgay-kanturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/requiem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Duvar ki Duvarlar İçinde Acıyı da Duyar Sevinci de', 'bir-duvar-ki-duvarlar-i-cinde-aciyi-da-duyar-sevinci-de-mahmut-alptekin-78ork', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Köşeyi dönünce karşımızda

Alnının ortasına gün vurmuş

Bir duvar

Zamanlar ötesine bir duvar

Dibinde fotoğraf çektirdiğimiz

Yağmurun, karın savrulduğu

Duyarlığı uzanmış pencereye

İnsanlara, sokaklara, dünyaya

Bir duvar ki duvarlar içinde

Acıyı da duyar sevinci de

Duvarlar kuşatmış insanları

Duvarlarda yağmurlar

İlkyaz yağmurları, sonyaz yağmurları

Yazlar, kışlar

Kışlar yazlar

Yağmurlar

Telgraf telleri, duvarlar

Kim uçurmuş yüreğimizin güvercinlerini

Kim uçurmuş duvarlara

Güvercinleri', 'Köşeyi dönünce karşımızda Alnının ortasına gün vurmuş Bir duvar Zamanlar ötesine bir duvar Dibinde fotoğraf çektirdiğimiz Yağmurun, karın sa...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Alptekin']::text[], 8.5, '{"poet":"Mahmut Alptekin","poet_slug":"mahmut-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-duvar-ki-duvarlar-icinde-aciyi-da-duyar-sevinci-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Atlısı Akşamın', 'yorgun-atlisi-aksamin-mahmut-alptekin-wdd3e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Türküler harmanı yüreğim

Acıya karşı diren

Alkole ve yalnızlığa karşı

Sokaklara, akşamlara

Bir ışığa giriyoruz yorgun ayaklarla

Yalancı gülüşler, yanlış adımlar

Kandırmıyor günlerin aldatıcılığı

Bir karanfildir soluğumda kan

Silahların ucundan görünen akşam

Sızan kanla ağzımdan

Yangın küllerimi döküyorum

Karanlık sulara

Bir çark dönüyor geceye

Namluların yüzünü budayan

Akşamın gölgelediği uzak düşlere

Sigara içişine yabancı olduğum

O kentten bu kente göçebe

Yarasa karanlığı sular

Yorgun atlısı akşamın

İçimde az az yürü ve dur

Kimliksiz bir hüzünle geliyor akşam', 'Türküler harmanı yüreğim Acıya karşı diren Alkole ve yalnızlığa karşı Sokaklara, akşamlara Bir ışığa giriyoruz yorgun ayaklarla Yalancı gülü...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Alptekin']::text[], 8.5, '{"poet":"Mahmut Alptekin","poet_slug":"mahmut-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yorgun-atlisi-aksamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta Yanyana', 'nokta-yanyana-i-hsan-uncuoglu-tl12z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nokta nokta''ya bağlanınca 

Çeşit çizgi çıkar ortaya

Gelirse birçok  yanyana 

Harf doğar çok noktalarda, 

***

Olur olmaz her mekanda 

Harf iledir kelamda mana 

Gönül harfi olmayanda 

Karagöz ne der Hacivata

Manasız kalır her sevda. 

*** 

Mecnuna Leylası ne rüya 

Hayaller gelince uç uca 

Kuyudan Nasreddin Hoca

Ay  sırtında gitmiş  uzay''a

Rüyadan ne çıkar uykuda 

Başta sonda yoksa nokta. 

*** 

Aymaz kalır hep çıkmazda

Gönül ne der sevdalarda 

Bilge eğilmez Dünyasında

Yol sahibimi bir kelamda 

Bilir nere virgül nere nokta, 

***

Güneşte noktalar olmazsa

Aydınlık doğmaz karanlığa

Harf aydınlık durur açıkta 

Karanlıkta harf yok inanma

Güneş ile döner bizim Dünya. 

*** 

Dakikalar olmazsa zamanda 

Gece gündüz gelirmi uçuca 

Her renkten olur her rüya 

Ölçü yoksa orda oyalanma

Başı sonu belli olan sınır ara. 

*** 

Bilinmeyen varsa açıkta 

Başta sonda nokta yoksa 

Ölçüden yana o şeytansa 

Hep yanlış ara hesabında. 

*** 

Kaç kuruş yapar kaç lira 

Değer kıymet buluş çaba 

Karşılığında netsin dünya 

Karışır virgül nokta yoksa 

Aydınlık döner karanlığa. 

*** 

Ölçü nedir sor etrafında 

Çook ses bir gele kulağa 

Anlamak benzer bir kuyuya

Şey''i saklama bu kelamda 

Bağlantısız dönmez dünya. 

*** 

Bilen gelsin bu meydanlara 

Ölçü neymiş bizi aydınlata. 

*** 

Ölçü nedir sor ortalığa 

Herkesin kelamında çıkana 

Kaç şey ne uyar bak sana 

Harf ölçüdür elde belde başta, 

***

Dayanılan nokta neyse yaşamda

Ayağa düşse olur ekşi salata 

Nokta sanki harf olurmu havada 

Elinde hangi ölçü net anlat bana. 

*** 

Ölçü nedir sor dünyalara 

Her kafa saklar bir mana 

Kimdir anlatır bunu sana 

Başta ölçü nedir sor ona, 

***

Düz eğri çizgiye bakınca

Üzerinde bir nokta varsa

Yolun bilen kalmaz yolda 

Nokta Ayardır Ölçü anladınsa. 

*** 

Bir gram pamuk çeker mi birton kaya 

Çekerde nokta virgül işareti yoksa 

Nokta virgül arama sınırsız konuda 

Her akıl ne der nerde virgül nere nokta 

***

Karanlıkta yoksa ademe ışıktan birnokta 

Düzeyin bilinmez ya basamak ya parmakta 

Ey insanoğlu ince birlik kolaydır sanma 

Yıkanı yapmazı çoksa netsin Usta bu Hanümana

Eğri oklar çook hedef sapar havalesi Mevlaya.', 'Nokta nokta''ya bağlanınca  Çeşit çizgi çıkar ortaya Gelirse birçok  yanyana  Harf doğar çok noktalarda,  *** Olur olmaz her mekanda  Harf il...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/nokta-yanyana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda İstanbul', 'elveda-i-stanbul-hidir-baspinar-rcdeh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aşk yaşıyorum İstanbul da; 

Sabahın ilk gecenin son saatlerine.

Dar yollar geniş, çıkmaz sokaklar açık.

Soğuk ateşliyor beni sana koşuyorum.

Bir aşk yaşıyorum İstanbul da; 

Ay buluta sarılmış kendini gizliyor.

Sisli bulutlardan bakıyorum sana

Aşkın yıllar geçsede yanan ateşdir.

Bir aşk yaşıyorum İstanbul da; 

Kurşun misali adresim kayıp.

Üzülme sevdiğim sesin yanımda.

Beni bırakmayacak kadar asi.

Bir aşk yaşıyorum İstanbul da; 

Gidiyorum artık yaban gülleri.

Dalından koparcasına şimdi.

Yaşamı bitmiş hazanlara

Bir aşk yaşıyorum İstanbul da; 

Özlem  bitmesini istediğim rüya.

Yıldız seni bana dileyen büyü.

Şimdi sense benim biricik Aşkım', 'Bir aşk yaşıyorum İstanbul da;  Sabahın ilk gecenin son saatlerine. Dar yollar geniş, çıkmaz sokaklar açık. Soğuk ateşliyor beni sana koşuyo...', ARRAY['Türk Edebiyatı','Şiir','Hıdır Başpınar']::text[], 8.5, '{"poet":"Hıdır Başpınar","poet_slug":"hidir-baspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elveda-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Aşkı', 'ana-aski-i-hsan-uncuoglu-n45yj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KAÇA GİDİYON ANAM

BEN KAÇA GİDİYOM

ANA Bana Davranışın 

Ölçüsünü birimini

Benzerini uyumlusunu 

(eşini menendini)   bulamadım bulamam

Karşılık istemedin dayan babam dayan

borcumu  düşünürüm de zaman zaman 

Saygımdan başka birde kanımdan 

verecek varlığım az gelir az ödeyemem Anam! , 

***

Zenginliği çok 

Heryandan dilimizin

Şiir denince  

Leyla ile mecnun  

Her zaman ortada

Ferhat ile şirin 

bunlardır dünyamızda

hemen gelenler her akla,

***

Küçümencik doğduğunda 

Leyla tıpatıp benzermiş

Anaya 

Mecnun ise çekmiş babaya  

Ferhat dayısına 

Şirin''de halasına, 

***

Bunlar Sevgili olmuşlar 

meşhur aşıklar, 

oluncaya kadar 

neler çekmiş analar? ! 

Bilinmez babalar 

nerde idi hep arkada 

hiç geçmemiş sanki yok 

kalan Hikayedir puslu anılarda, 

***

Herkeste olduğu gibi

hele var ya her ağlayışta 

Öyledir heriki eli kanda bile olsa 

uykusuz sütün veren o benim Anam! 

heran gözünden ayırmadan 

başındanberi bana sürekli bakan

gece gündüz üstbaş örtü koyan 

Her zor''da kime ne diye dayanan

Doğuran aklından çıkarmayan 

çocuğuna tül kanat kimi çelik 

şimşek olup davranıp koruyan 

güzel her sıfatın ismi be hey Anam, 

***

Anaların ayakları altına

serilmiş hangi cennet o 

kimin aklından bağışlanmış 

göreyim kim anlayan kim anlatan, 

Hep Güzel her isim fiil sıfatta payı olan

Sen sen sen sensin Anam! 

Böyle bilesin bildim

Asıl sensin Dünyamda Sevgilim Cennetlik olan! 

Bir de eşi bulunmaz kıymetli Vatan!', 'KAÇA GİDİYON ANAM BEN KAÇA GİDİYOM ANA Bana Davranışın  Ölçüsünü birimini Benzerini uyumlusunu  (eşini menendini)   bulamadım bulamam Karşıl...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/ana-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-mehmetsah-subasi-or81w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir güzellik doğuyor içime iplik iplik 

martılar konuyor omuzlarıma 

senden bir haber bekler durur yüreğim, 

ve yalnızlık, içime işleyen

tüm duygularımı senınle yapan 

içimdeki sensin biliyorum.........

birgün gözlerimi görürsen eğer, 

bu senmısın diye çınlatırmısın kulaklarda, 

yaşadığını sanmışsa gözlerim, seni gormeden

görunce senı, hakkı yok artık yaşamayacak....

sen neymişsın ey sevgili ey zamandan, 

butun payını benimle paylaşan..

bir guzelliksin, şiirden, içime dolan, 

bır yağmur sonrası topraksın, kokan, 

yaşadığını sanmışsa ben, senı koklamadan

koklayınca seni, hakkı yok artık yaşamayacak...

seni görmekse yaşamdan, hayattan ayrılık

ayrılmak için yaratıldım, seni görmek için, 

sabır ne taşdır böyle damla oldum da delemedım

açtığın gun yüreğim de derin yarayı, 

anladım kı bu yurek bundan fazla yaşamayacak, , , 

yağmur olmak seninle, düşmek beraber gokyuzunden, 

 gül olmak senınle aynı toprakda, bulbulleri taşımak

yaşamanın diğer  sırrıydı seninle yaşamak, ..

yağmursuz bulut, bulbulsuz gul ise yaşamak

sensız hayat bundan boyle yaşanmayacak.....

bir gun birden yokluğunu hıssettırme bana, 

durgun su gıbı azalacağım, çekilip gokyuzune

guneşi uzak ufuklarda, uzak dağlarda görmeyeceğim...

ve yalnızlık, yıne bi başıma kalacağım, , , 

olmek ise kalmak, bir ömür boyu öleceğim..........

03: 35

08/08/2001', 'Bir güzellik doğuyor içime iplik iplik  martılar konuyor omuzlarıma  senden bir haber bekler durur yüreğim,  ve yalnızlık, içime işleyen tüm...', ARRAY['Türk Edebiyatı','Şiir','Mehmetşah Subaşı']::text[], 8.5, '{"poet":"Mehmetşah Subaşı","poet_slug":"mehmetsah-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/senin-icin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimler', 'resimler-cem-yilmazer-hub2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Resimler; 

Renklerin, şekillerin sihri, 

Duyguların çığlığı.

Mona Lisa; 

Saf bir köylü kızı gibi

Gözlerinden fışkırıyor

Masumiyeti, 

Resimlerde.

Gökkuşağının her rengi, 

Ay ışığının romantikliği, 

Gölgelerin gizi, 

Bakışların alevi, 

Sevgiliye seslenişler, 

Resimler, 

Resimlerde.

Fırçanın her teli, 

Ruhumun izleri.

Boyanın her rengi, 

Kalbimin aksi.

Resimlerde.

Bir düş olur bazan

Aşkı resimlemek, 

Becerememe korkusunu yenememiş

Titreyen ellerimde.

İsyan eden hayata

Kurtar diye bağıran

Asi gönlümün bedenime

Acımasızlığı

Şekillenir kağıtlarda, 

Tuvallerde, duvarlarda, 

Resimlerde.

Neşeli bir türkünün

Nağmelerinde çoşuyor

Parmaklarım, fırçalarım.

Evrenin sırlarına inat, 

Hayallerime kuvvet

Pervasızca koşuyor

Rüyalarım.

Resimlerde.', 'Resimler;  Renklerin, şekillerin sihri,  Duyguların çığlığı. Mona Lisa;  Saf bir köylü kızı gibi Gözlerinden fışkırıyor Masumiyeti,  Resimle...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/resimler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-cem-yilmazer-wrqma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski bir kilim.

Nakışlar, 

Motifler, 

Sevda yarası, 

Renk cümbüşü, 

Aşkın izi, 

Fersiz gözlerin, 

Tütsülü serüveni.

Ay doğarken kalp atışları

Kilimden yükselen sese bulaşmış

Gözyaşlarına bulanmış

Parmak izleri üstünde

Aşk ateşi kilimde

Mektuplaşan nağmeler sevgiliye

Ah onu bir anlasa! 

Onulmaz yaralar

Kalbinde saklı

Bitmez rüyalar

Gecenin böğründe

Bağırıyor

Anlasana...', 'Eski bir kilim. Nakışlar,  Motifler,  Sevda yarası,  Renk cümbüşü,  Aşkın izi,  Fersiz gözlerin,  Tütsülü serüveni. Ay doğarken kalp atışlar...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülemiyorum', 'gulemiyorum-cem-yilmazer-npdzv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koca koca apartmanlar, 

Yapraksız ağaçlar, 

Bana kötü kötü bakan

Asık yüzlü çocuklar

Sanki

Siyah beyaz bir caddeden geçiyorum.

Herşey bana yalancı, 

Ben onlara yabancı.

Çıkmaz sokaklara dalıyorum.

Kendimi kaybediyorum.

Gökyüzünde uçan kara kuşlar

Simsiyah bulutlara dalıyorlar

Duman, 

Hre yer kapkara.

Ve gece çöküyor damların üstüne, 

Ve gece çöküyor, 

Herşeyin üstüne.

Kayboluyorum homurdayan kalabalıkta

Bir sigara yakıyorum

Etrafımı aydınlatsın diye

Yolumu göreyim diye

Umutsuzca çöküyorum

Yabancı gözlerin içinde

Oynamayı unutmuş

Somurtkan çocukların içinde

Bir gülücük arıyorum

Yalancık da olsa

Mutluluk oyunu oynayan

Birilerini.

Bulamıyorum.

Bulsam ne olur? 

Gülemiyorum.', 'Koca koca apartmanlar,  Yapraksız ağaçlar,  Bana kötü kötü bakan Asık yüzlü çocuklar Sanki Siyah beyaz bir caddeden geçiyorum. Herşey bana y...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gulemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakız Satan Çocuk', 'sakiz-satan-cocuk-cem-yilmazer-3ghc8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sakız satan çocuk

Masum, utangaç.

Yalan bilmez.

Tertemiz giysiler içinde

Ellerinde sakız kutusu, 

Gözlerinde ruhu, 

Kalbinde buruklukla; 

Kah bir ağacın altında

Yapraklardan süzülen damlaların

Gözyaşlarına karışmasına sevinerek; 

Kah öğle sıcağının en delici

Saatlerin en gerici anlarında

Buz gibi bir ayran hayali kurarak; 

Kah yüreklerin bile donduğu

Bembeyaz karlar arasında

Sıcak anna kucağını özleyerek

Umutlarını satar.

Aç bekleyen kardeşleri için, 

Yeni doğmuç kedisi için, 

Gözleri nakışlarda kaybolan annesi için, 

Yarınlara yıldızlardan bakmak için, 

Sakız satar, 

Hayalleri için.

Ve ben ne zaman

Şiir yazmak istesem

Sakız satan çocuğu düşünürüm.', 'Sakız satan çocuk Masum, utangaç. Yalan bilmez. Tertemiz giysiler içinde Ellerinde sakız kutusu,  Gözlerinde ruhu,  Kalbinde buruklukla;  Ka...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sakiz-satan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-cem-yilmazer-1ehmq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız bir gün ve gece

Sarıldım sensizliğe

Birkaç anlamsız hece

Zihnimdeki bilmece

Üşüyorum, her yer kar

Düşlerimde zalim yar

Ve gece uykum kaçar

Hep seni düşününce.', 'Yalnız bir gün ve gece Sarıldım sensizliğe Birkaç anlamsız hece Zihnimdeki bilmece Üşüyorum, her yer kar Düşlerimde zalim yar Ve gece uykum ...', ARRAY['Türk Edebiyatı','Şiir','Cem Yılmazer']::text[], 8.5, '{"poet":"Cem Yılmazer","poet_slug":"cem-yilmazer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmece-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevince', 'seni-sevince-turgut-erdogan-d92ds', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben…

Mutsuzluk nedir bilmezdim ki senden önce, 

Yalnızlığımla, 

Ama mutlu yaşardım alabildiğince.

Öğrendim…

Hem de çok iyi öğrendim seni sevince, 

Yalnızlığım yetmezmiş gibi, 

Sensizliği de yaşadım olabildiğince.

Hep aydınlıktı günlerim, 

Hiç karanlık tanımadım, 

Seni sevdim, geceyi gündüz yaşadım.

Önceleri hep gülerdim, hiç ağlamadım.

Seni sevdim de ne oldu? 

Hep gözyaşı, 

Bir gün huzur bulmadım.

05 Nisan 2002', 'Ben… Mutsuzluk nedir bilmezdim ki senden önce,  Yalnızlığımla,  Ama mutlu yaşardım alabildiğince. Öğrendim… Hem de çok iyi öğrendim seni sev...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durma Git', 'durma-git-turgut-erdogan-p7mdv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana “gitme” demeyeceğim! 

Hadi durma, git artık.

Bir bağ evi dinginliğinde, 

Sessiz ve derinden olsun gidişin.

Sana “gitme” demeyeceğim! 

Yalnızlık bile korkutamaz beni artık.

Zaten, bir bağ bozumu gününde, 

Ansızın olmuştu gelişin.

“Gitme” demeyeceğim sana, 

Diz çökmeyeceğim önünde, 

Bent kurmayacağım çağlayan sularına.

Hadi git, nasılsa bitti artık bu sevda.

Sana “gitme” demeyeceğim...

Alanya,20/02/2002', 'Sana “gitme” demeyeceğim!  Hadi durma, git artık. Bir bağ evi dinginliğinde,  Sessiz ve derinden olsun gidişin. Sana “gitme” demeyeceğim!  Y...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/durma-git-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Adam -1-', 'adam-gibi-adam-1-turgut-erdogan-ax9ir', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünmek özgürlüktür bebeğim...

Öyleyse

Bir adam düşün...

Önemli değil

Nasıl bir adam olacağı, 

Önemli değil saç rengi, 

Göz renginin de önemi yok...

Siyah ta olabilir, 

Mavi de.

İstersen mutluluk yeşili olsun.

Veya...

Veya gizemli bir çakır.

Yeter ki mağrur olsun.

Güvenle baksın geleceğe.

Sakallı da olabilir, 

Dilersen, 

Kapkara bıyıkları da...

Düşünmek özgürlüktür dedik ya! ! ! 

Sakın ha, 

Takılıp kalma ırkına.

Dini mi? 

Umursama bile...

Katolik, Ortodoks veya Müslüman

Yok yok istersen Ateist olsun...

Ama...

Ama yeter ki, 

Adam gibi ''ADAM'' olsun...', 'Düşünmek özgürlüktür bebeğim... Öyleyse Bir adam düşün... Önemli değil Nasıl bir adam olacağı,  Önemli değil saç rengi,  Göz renginin de öne...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/adam-gibi-adam-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -7-', 'mektup-7-turgut-erdogan-ac5sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine sensiz, yalnız geçen karanlık gecelerden birindeyim. bak işte, yine ansızın düştün aklıma. Ve ben yine sensiz, bitmek bilmeyen karanlık, zindan gecelerimden birine adım attım. Elinden oyuncağı alınmış çocuk gibiyim, ha ağladım ha ağlayacağım. Sen ise hiç tanımadığım birinin kollarında yine beni düşünüyorsun. İşte kader diye buna derim ben.

Ne kadar garip değil mi? İkimiz de birbirine çok yakın iki kıyıda karşılıklı duran gemici fenerleri gibiyiz ve ikimizde birbirimize bakıp iç çekeriz.Ama talihsizlik bu ya ne kadar yakın olsak birbirimize bir araya gelemiyoruz.Seni düşünmek yok mu! ! ! Çıldırtıyor şu kuş kanatlı kalbimi. Seni düşündüğümde Fırat kıyısından turnalar havalanıyor, bir cinayet işleniyor Endonezya''da bir yerde. Dişi maral eşine ağlıyor yağmur ormanlarında ve ben sana, sensizliğe sessizce, çığlık çığlığa ağlıyorum senden uzakta. Duyuyor musun? .

Deli bir tay gibiyim, vadinin en güzel ama en tehlikeli yarlarında eğitiyorsun beni. Hadi gel çırılçıplak ve savunmasızım sana karşı, al beni kollarına erit beni aşk potanda. Sımsıkı sar beni bırakma ne olursun. Bak üşüyorum sensiz.

Her sabah güne seninle merhaba derim, senin hayalinle başlarım ben yeni güne. Elini uzatsan

tutarsın ellerimden bilirim. Bir söz söylesen ''seni seviyorum desen veya küfür etsen... İşte o gün senin için ölürüm.İsterim ki o günüm seninle geçsin, gecem seninle geçsiz ve düşlerin seninle renklensin. Nedir bu ha nedir? Kader mi? Alın yazısı mı? Nedir bu beni senden uzaklara savuran fırtına? 

Bıktım artık, yeter sana çektiğim hasret. Çölse çölleri geçeceğim, dağsa dağları deleceğim.

Ama bir kez dahi olsa bal dudaklarından öpeceğim...

09/MART/2000  01.25  Alanya', 'Yine sensiz, yalnız geçen karanlık gecelerden birindeyim. bak işte, yine ansızın düştün aklıma. Ve ben yine sensiz, bitmek bilmeyen karanlık...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mektup-7-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -15- (Yazmak!)', 'mektup-15-yazmak-turgut-erdogan-3j55o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazmak... Yazmak... Yazmak ve yine yazmak istiyorum.

	Haksızlığı, yalanı, aldatmayı ve aldatılmayı, riyakârlığı yazmak istiyorum.

	Tanrıya inanışı ve ateistliği yazmak istiyorum.

	Sevgiyi ve aşkı yazmak istiyorum.

	İçimde, her zaman dalgalanan, kuduran hırçın bir kelimeler denizi var ki taşmak üzere. Bir başlayabilsem yazmaya, bir başlayabilsem. Kitaplar dolusunca sayfalar dolusunca yazabilirdim.

	Tabii ki ilk önce seni yazardım. Çok istediğim halde bir kez bile rüzgara bırakmadığın  o ipeksi uzun saçlarını yazardım. Şu küçücük dünyada, içinde bir çok dünya barındıran o duygu denizi gözlerini yazardım. Sonra al yanaklarını ve tatlı, küçük ve zarif burnunu yazardım.

	Hayır hayır! ! ! Hemen sitem etme, dudaklarını unutmadım. O rüya rengi, uçuk pembe dudaklarını unutabilmem mümkün mü? Ben, öpülesi dudaklarını yazmak için şöyle yapardım. Önüme binlerce sayfalık bir defter alır, ilk satırına ''senin dudakların'' yazar ve gerisini boş bırakırdım. O boş sayfaları ancak ben anlardım. Çünkü o sayfalarda hiç bir şey yazmazdı ama çok şey anlatırdı.

	Dudaklarını yazarken seni ilk kez öptüğüm ânı hatırladım. Yanakların al al olmuştu, hatta biraz da utanmıştın. Senin ne tepki göstereceğini bilemediğimden ben de çekingen kalmıştım. Dudakların bir ömre bedeldi.

	Senin en çok neyini seviyorum biliyor musun? 

	Her şeyini! ! ! 

	28/03/2002', 'Yazmak... Yazmak... Yazmak ve yine yazmak istiyorum. 	Haksızlığı, yalanı, aldatmayı ve aldatılmayı, riyakârlığı yazmak istiyorum. 	Tanrıya i...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mektup-15-yazmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -16- (Zehir Gibi)', 'mektup-16-zehir-gibi-turgut-erdogan-shb18', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün benden çok uzaklara gidiyorsun. Belki aramızda aşılması güç dağlar, binlerce metrelik uçurumlar olacak. Ama, unutma bir tanem ben her zaman seni düşünüyor olacağım. Eminim ki sen de beni düşüneceksin. Ve ben seni düşündüğüm her ânımda, birkaç satırla bile olsa yokluğunu gecenin göğsüne yazacağım.

	Dün geceki telefon konuşmamızı hatırlıyor musun? “Yıkılmaz” dediğimiz sevdanın üzerine ansızın kara bulutlar çökmüştü. Birlikteliğimiz depremde kalmış evler gibi çatırdamaya başlamıştı. Ve sen beni ilk defa aşağılamıştın. Hatırlıyor musun? Ben sana  “senden hoşlanıyorum” dediğimde “senden nefret ediyorum” diyordun. “seni seviyorum “ dediğimde ise “seni sevmiyorum” diyordun, hatırladın mı? O zaman sana, beni ne kadar aşağıladığını ve gururumu bir sigara izmariti gibi narin ayaklarının altına aldığını söylemiştim. Biliyordum aslında beni sevdiğini. Ve sen hıçkırıklarını tutamamış, ilk kez o denli ağlamıştın. Ve ağlayarak beni çok ama çok sevdiğini söylemiştin. Ne o yine mi ağlıyorsun? 

	Bu sevincim kısa sürdü. Ardından beni sevmene rağmen başkasının olacağını öğrendim nar dudaklarından. Bu idam fermanı gibiydi benim için. Hastalık ve ölüm gibiydi. Başkasının olman hastalığım da, ya senden ayrılığım? İşte o benim ölümümdü... Ama bir kez değil her an, her saniye tekrar ölmekti.

	Şimdi sen yoksun... Rüzgar yine başladı, sararmış yapraklar oradan oraya uçuşuyor. 

	Şimdi sen yoksun… Yokluğun zehir gibi kanımda dolaşıyor…

Alanya,05/04/2002', 'Bugün benden çok uzaklara gidiyorsun. Belki aramızda aşılması güç dağlar, binlerce metrelik uçurumlar olacak. Ama, unutma bir tanem ben her ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mektup-16-zehir-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -17- (Nefret)', 'mektup-17-nefret-turgut-erdogan-2cobi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçerimde bir hastalık başladı aniden. Bu öylesine amansız bir hastalık ki asalak gibi tüm duygularımı kemiriyor. Hakim olamıyorum ona, hükmedemiyorum…

	Hastalığım ne mi? 

	Nefret… Nefret… Nefret…

	Şimdi, senin yokluğunda her şeyden nefret ediyorum. Eskiden yalnızlığımın, mutluluğumun en yakın sırdaşı olan mavi denizlerden, tatlı sert dalgalardan şimdi nefret ediyorum. Bana yalnızlığımı hatırlatıyor şimdi kıyıya ulaşan her dalga. Şu, bana her zaman romantik gelen, şiirlerimin ilham kaynağı kızıl ufuklardan, güneşin batışından nefret ediyorum.

	Biliyor musun? Artık, dünyadan ve şehirlerden de nefret ediyorum. Şehirleri ayıran uzun yollardan da, derin uçurumlardan da nefret ediyorum. Nefretim en çok iki şehirde yoğunlaşıyor. Birincisi ayrılığı tattığım bu şehirden, adına “ayrılıklar şehri” dediğim,  gecesine şiire yattığım, gündüzüne umutla baktığım, havasını ciğerime çektiğim bu şehirden nefret ediyorum.

	Ve senin yaşadığın şehirden nefret ediyorum. Bana senin yokluğuna ağıtlar yaktırdığı, seni ışıltılı gecelerinde barındırdığı için nefret ediyorum o şehirden. Nefretim o denli yoğun ki... O her gece ışıl ışıl yanan sokak lambalarını teker teker kırıp karanlık katran gecelere mahkum etmek istiyorum. Karanlıklara gömülsün ki karanlıkta kalmak nasılmış anlasın istiyorum.

	İşte nefretim böylesine yoğun Hasret Çiçeğim. Bir gün bu nefretim beni öldürebilir.

	Ama ben, nefretten değil senin sevginden ölmek istiyorum.

	Çabuk dön, ölebilirim…

Alanya,05/04/2002', 'İçerimde bir hastalık başladı aniden. Bu öylesine amansız bir hastalık ki asalak gibi tüm duygularımı kemiriyor. Hakim olamıyorum ona, hükme...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mektup-17-nefret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -18- (Zaman)', 'mektup-18-zaman-turgut-erdogan-b99ma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman o kadar hızlı, her şey o kadar hırçın bir nehir edasıyla değişiyor ki! ! ! Hiçbir şey değişmedi zannediyorum. Ama, pembe düşlerimin, karanlık dehlizlerimin içinden sıyrılıp etrafıma baktığımda her şeyin değişmiş olduğunu, hiçbir şeyin eskisi gibi olmadığını görüyorum.

	Evet her şey değişmiş Hazan Bakışlım…

	Sen bile…

Alanya,  07/04/2002', 'Zaman o kadar hızlı, her şey o kadar hırçın bir nehir edasıyla değişiyor ki! ! ! Hiçbir şey değişmedi zannediyorum. Ama, pembe düşlerimin, k...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mektup-18-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -19- (Dar zamanda söylenen Türkü''ye)', 'mektup-19-dar-zamanda-soylenen-turku-ye-turgut-erdogan-h1h9l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana bu mektubu, giderken beni bıraktığın balıkçı kahvesinde “bana şiirler, mektuplar yaz” diyerek verdiğin kalemle yazıyorum.

	Şimdi yokluğunun ertesindeyim.İnsanlar var bol zamanda az şeyler yaşarlar, insanlar var dar zamanda ömür sığdırırlar zamana. Biz de seninle kısıtlı zamanda yaşadık sevdamızı. Mahkumuyduk zaman mevhumunun. Ne güpegündüz birbirimizin elini tutabildik, ne sarılıp hasretle öpüşebildik; yasaklıydı sevdamız, söylenemezdi türkümüz. Ancak gece olunca mehtaba çıkabildik. Heybeli olmasa da Alanya kumsalında mehtabı izledik.Sazlar olmasa da denizin narin dalgalarıydı eşlik eden sevda türkümüze.

	Sevdamızı dört duvar arasında yaşadık. Bizimkisi özgür mahpusluktu, yeri geldi gölgemizden bile korktuk. Ne kadınlar koğuşundan hüzzam şarkılar yükseliyordu, ne de avlu voltalarında bozlak türküler söyleniyordu. Biz yazdık, biz söyledik türkümüzü gece boyu.Perdemiz vardı, aralayamadık; penceremiz vardı, açamadık; ışığımız vardı, yakamadık; havamız vardı, soluyamadık.

	Sen sessizliklerim, sensizliklerim ve kalabalık yalnızlıklarımın tam ortasından geçen çılgın nehir gibiydin.Dalgaların kıyılarımdaki yalnızlıkları, sessizlikleri ve sensizlikleri okşuyordu usulca.

	Bölük pörçük yaşayabildik sevdamızı. Dedim ya yasaktı sevdamız. Yine de dar zamanda ömür yaşadık. Yapmayı isteyip de yapamadığım tek şey göğsünde karşılamaktı sabahın ilk ışıklarını ve mahmur gözlerimizi aralayıp “günaydın sevgilim” diyebilmekti. Sağlık olsun! ! ! 

	Beklenen zaman geldi sonunda, gitmeliydin. Biliyordun gitmek zorunda olduğunu, biliyordum kalamayacağını. Cesaret edipte söyleyemedim yüzüne “gitme, benimle kal” diye. Bir gün bir yerde yine buluşacaktı ellerimiz, yine kilitlenecekti birbirine gözlerimiz ve yine şiirler okuyup türküler söyleyecekti sevdaya dair yüreklerimiz.

	Gittin! ! ! Ardından bakakalırken gözlerim, “gitme aklım sende kalır, uyuyamam geceleri” türküsünü mırıldanmaya başlamıştı bile dilim. Gittin! ! ! Zamanın tam ortasına o anı durdurmak istercesine bir çivi çakarken ellerim, tüm suskunluğuyla, avaz-avaz  çığlık çığlığa “gitme, ne olur bende kal” diyordu yüreğim. Tekrar gel ırak türküm, tekrar gel…

Alanya,07/08/2002', 'Sana bu mektubu, giderken beni bıraktığın balıkçı kahvesinde “bana şiirler, mektuplar yaz” diyerek verdiğin kalemle yazıyorum. 	Şimdi yokluğ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mektup-19-dar-zamanda-soylenen-turku-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -20- (Kurt Kapanı)', 'mektup-20-kurt-kapani-turgut-erdogan-9rbou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi sensizliğin kurt kapanındayım. Ağaçların karınca sıklığında olduğu çam ormanlarında, asırlık bir çınarın altında yatıyorum. Vakit sensizliğin gece yarısı. Kulaklarımda sessizliğin sağır edici çığlıkları, gözlerimde karanlığın kör edici aydınlığı var.

	Her nefes alışta vaktimin daraldığını hissediyorum. Birazdan gelip alacaklar beni.Üçağacın ortasında bir salıncağa bindirecekler. Suçum? Seni sevmek! ! ! 

	Ne acı değil mi? Bir daha “seni seviyorum” diyemeyeceğim, bir daha “canım” diye sana seslenemeyeceğim, bir daha sarılıp kor dudaklarında yanamayacağım.

	Bak görüyorsun işte, sensizlik ne hayaller kurduruyor bana.

	Bunların hepsi hayal gülüm, ben sensiz kalmayacağım, her an yanında olacağım, sonsuza dek senin kalacağım…

Alanya,17/08/2002', 'Şimdi sensizliğin kurt kapanındayım. Ağaçların karınca sıklığında olduğu çam ormanlarında, asırlık bir çınarın altında yatıyorum. Vakit sens...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mektup-20-kurt-kapani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -21- (Gülüm)', 'mektup-21-gulum-turgut-erdogan-7nn0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım benim…

	Meğer senden ırakta olmak ne zor şeymiş. Daha demin saate baktım 19: 35 idi., aradan beş asır geçtiği halde ancak 19: 40 olmuş. Sanki akrep ve yelkovan prangaya mahkum etmişler. Anla ki sensiz zaman geçmek bilmiyor.

	Oysa birlikte iken öyle miydi? Zaman kavramı yok oluyordu, kocaman ev dar geliyordu aşkımıza. Güneş henüz yeni göstermişken yüzünü dağların ardında, bir de bakıyorduk karanlık çökmüş aşk tapınağımıza.

	Ya şimdi öyle mi gülüm. Sen dağlar, tepeler ötesindesin.Ben se sensizliğin kahreden satırları içinde. Kendimi resimlerimize bakarak avutuyorum. Ve mutlu gelecek hayalleri kurarak sensizliğe katlanıyorum.

	Artık sabahları uyanmak ve yüzümü yıkarken aynaya bakmak istemiyorum. Her sabah sensizliğimi dağınık saçlar bakımsız sakallarla ve kızarmış gözlerle ispatlarcasına aynaya bakan kendi görüntümden bıktım artık.

	Şimdi nereye baksam kocaman neonlarla SENSİZLİK yazıyor. Artık bu hayatı sensiz yaşamaktan bıktım usandım.Bir delilik yapmaktan korkuyorum.

	Ne vakit aklıma gelsen, sensizliği de peşin sıra sürüklüyorsun. O zaman yeryüzünün tüm atları beynimdeki bozkırlarda dörtnala koşuşuyor, hançerin biri böğrüme, diğeri yüreğime vuruyor. Acılar dayanılmaz oluyor, sensizlik katlanılmaz! ! ! 

	Başımı vagonların arasında ezmek istiyorum olmuyor, yapamıyorum. Seninle beyaz çarşaflara sığmayan hatıralarımız saklı düşüncelerimde, yok etmeye kıyamıyorum.

	Birden elim yüreğime gidiyor. Söküp yerinden almak, çıtırtılarla alev alev yanan ateşe atmak istiyorum. Ansızın duruyorum. Elim yana düşüyor, onu bile beceremiyorum.Sen varsın tüm güzelliğinle orada, kıyamam biliyorum.

	Çaresizce sensizliğe katlanacağım. Çünkü seni her an bir öncekinden çok seviyorum gülüm…

Alanya,17/08/2002', 'Canım benim… 	Meğer senden ırakta olmak ne zor şeymiş. Daha demin saate baktım 19: 35 idi., aradan beş asır geçtiği halde ancak 19: 40 olmuş...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mektup-21-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Bile Ayıramaz Sevenleri', 'olum-bile-ayiramaz-sevenleri-ensar-aktas-tb2x6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıradan bir gün batımında

Bir nisan ayında

Issız bir dağ başında

Çamurlu bir yolda

Yavaş yavaşta olsa

İlerlemek istediğim anda

Bir gürültü, bir patlama

Bozuyor tüm sessiziliği

Uyandırıyor beni

Yokediyor seni

Aklımın her köşesine

Nakşettiğim hayallerini

Kimdi ayıran yine bizi

Kimdi çalan yine hayallerimizi

Bu kesin arka lastikti

İsyan etmişti belki

Belki de iflas etmişti

Bir bu eksikti

Ne yapmalı ne etmeli

Çıkıp değiştirmeli

Bulmalı kirkoyu, istetmeyi

Elimden gelmese de

Denemeliyim değiştirmeyi

Ne gelirki zaten elimden

Seni sevmekten başka

Sana kavuşamamaktan, 

Sana ulaşamamaktan başka

Bu yolculuk isyanımdı benim

Seni bulmaktı gayem

Yoksa ne işim olurdu benim

Şu dağ başında bilmem

Buralar çok ıssız çok sessiz

Bir ben böyle çaresiz

Bir de nisan yağmuru kesintisiz

Kimse ayıramaz bir daha bizi

Bulabilirsem seni

Diye sevinirken

Kendimi kandırırken

Bak şu lastiğin yaptığına

Ne güzel de dalmıştım sana

Motor kapağından yükselen serabına

Tam da kavuşmuştum sana

Bu ne sessizlik Allah’ım

Kimseyi yalnız koyma

Yolda koyma, dağ başlarında

Sen sevenleri ayırma

Ne bir gelen var, nede giden

Çok yalnızım üşüyorum

Sessizlikten ve

Sensizlikten ilk defa korkuyorum

Razıyım aç bir kurt bile olsa

Çıksın yeterki karşıma

Bir son versin şu yalnızlığıma

Güneşte batmak üzere

Yanmıyorum ölüp gideceğime 

Bu ıssız yerlerde

Benim isyanım seni son kez

Göremeden, sensiz öleceğime

Nereye gider şu patika

Bir baksam mı acaba

Yaşasın! 

Bak orada bir avcı kulübesi var

Terkedilmiş galiba

Bırakılmış yalnızlığa

Aman Allah’ım

Kimlere ait bu iskeletler, 

Bu kemikler

Birbirine kenetlenip can vermişler

Ölüm bile ayıramaz sevenleri deyip

Ölüme birlikte mi gitmişler

Bu harabe kulübede

Koyun koyuna ölmüşler

Sevgili şair abicim, üstad, 

Ümit Yaşar Oğuzcan, 

Bunlar senin

‘Seninle ölmek istiyorum’

Şiirindeki karakterler değil mi? 

Ne istedin, neydi derdin, 

Niçin izin verdin, 

Niçin kıydın bu sevenlere

‘Nefes almak hüner değil…

Seninle ölmek istiyorum’ diyorsun

Haklısın, ama aynı nefesi

Birlikte teneffüs etmekte

Büyük bir hüner değil mi? 

Evet, ölüm bile ayıramaz belki sevenleri

Birlikte ölmekte güzel, 

Ama birlikte yaşamak, 

Paylaşmak aşkı, sevgiyi

Çok daha güzel değil mi? 

Rotterdam,24.08.2002', 'Sıradan bir gün batımında Bir nisan ayında Issız bir dağ başında Çamurlu bir yolda Yavaş yavaşta olsa İlerlemek istediğim anda Bir gürültü, ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/olum-bile-ayiramaz-sevenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikat', 'hakikat-i-mam-ali-seven-4xel2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana hayatı öğreten gülüş

Aydınlığa mahkum eder ömrümü

Bunu söylerken çarpar hakikat

Aslında kendimi büyüttüğümü

Bir hüzün dalgası çöker kalbime

Gözlerimde gördüğüm sadece bir düş

Ruhum çırpınır şu dar kafeste

Bulamaz manaya ufak bir çıkış

Kalbime çöken mahpusluk kahrı

Kendime vurduğum bir prangadır

İstemesem kaale almam rüyamı

Düşündüğüm var ben öyle varım.', 'Bana hayatı öğreten gülüş Aydınlığa mahkum eder ömrümü Bunu söylerken çarpar hakikat Aslında kendimi büyüttüğümü Bir hüzün dalgası çöker kal...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hakikat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-i-mam-ali-seven-vydlr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyandıracak suyu avuçlarımda tuttum, 

Kafamı gömdüm oraya kendi kendimi boğdum.', 'Uyandıracak suyu avuçlarımda tuttum,  Kafamı gömdüm oraya kendi kendimi boğdum....', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yitik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fitne', 'fitne-i-mam-ali-seven-jgam3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıpkırmızı bir buseyle öperken o alnımı

Karıştırdı kanıma lâl renkli şarabını...', 'Kıpkırmızı bir buseyle öperken o alnımı Karıştırdı kanıma lâl renkli şarabını......', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/fitne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hüzündür anlatamadıgım', 'huzundur-anlatamadigim-osman-colak-26jtp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüzündür anlatamadığım. 

arkamda bıraktığım karanlık 

rıhtımlardakı yalnızlığımdır. 

titreyen mumun ucunda yanan 

ince bir sızıdır büyür içimizde 

''dalgın bekleyen dostlar'' 

sözlerde saklanan ızdıraptır. 

gittiğim gün çığlığa karışsada 

tenhalarda boğulan hicrandır. 

göğe uzanan ellerdir 

taşta yeşeren tomurcuk. 

kupkuru üzüm sarmaşığının 

sakladığı gözyaşıdır danelerinde 

toplansa da  göklerine bin bahar 

tek bir çiçektedir intizar', 'hüzündür anlatamadığım.  arkamda bıraktığım karanlık  rıhtımlardakı yalnızlığımdır.  titreyen mumun ucunda yanan  ince bir sızıdır büyür içi...', ARRAY['Türk Edebiyatı','Şiir','Osman Çolak']::text[], 8.5, '{"poet":"Osman Çolak","poet_slug":"osman-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/huzundur-anlatamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-i-mam-ali-seven-7vdey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece yüreğim gerçekten de titriyor

Değersiz, parıltılı bir sokak

Cam kırıkları gözlerinden geliyor

Soğuk rüzgar nefesinin makamından mı? 

Başka yer baharın kokusu var, 

Hava zalim ve esmer yağmurun kollarında...

Bir anlasam konuşulmaz anları, 

Hayat bir su hiç durmadan akıyor...

Söylemek mi gerek sevgiyi sence

Şiirler mi yazmak şarkılar mı söylemek? 

Suskun aşkın kıymetini bildikçe

Yetmiyor mu bir bakış her şeyi anlatmaya? 

Yine karanlıkta bir yerlerdeyim, 

Demem seni ne kadar sevdiğimi.

Sana sadece bir gül bir öpücük veririm, 

Bir de beni bulman için uzun upuzun yollar.', 'Bu gece yüreğim gerçekten de titriyor Değersiz, parıltılı bir sokak Cam kırıkları gözlerinden geliyor Soğuk rüzgar nefesinin makamından mı? ...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suskun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçe Kapanış(2)', 'i-ce-kapanis-2-i-mam-ali-seven-sh3se', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulut üstüne bulut kapatırken göğümü

Güneş doğdu utançla ödünç alarak aydan

Yakmıyordu şefkati düştüğü hiçbir yeri...

Kuşlar anlatıyordu ekmeğin kavgasını

Sen bir umutsun ama dudağımda isimsin

Sarıldığım kadınsın sıcacıksın koynumda

Niçin sabah gel bana sen benim olmalısın.', 'Bulut üstüne bulut kapatırken göğümü Güneş doğdu utançla ödünç alarak aydan Yakmıyordu şefkati düştüğü hiçbir yeri... Kuşlar anlatıyordu ekm...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ice-kapanis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şefkat', 'sefkat-i-mam-ali-seven-qy26m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annemin duası ipekten kalkan

Kıyamaz etime gerçek demeye

Mekanı dişine takıp da yırtan

Sen gelmeden zehir döktüm diline', 'Annemin duası ipekten kalkan Kıyamaz etime gerçek demeye Mekanı dişine takıp da yırtan Sen gelmeden zehir döktüm diline...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sefkat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâlâ', 'h-l-i-mam-ali-seven-ylt6c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hâlâ yüzer içimde birkaç gemi

Ve benzer kapı gıcırtısına keman sesleri

İstemezdim ben

Kıvrımlarında yüzünün bir hayat istemeyi.

Adım adım boğacakken karanlık

Ellerimden tutan gözlerindeki ışık

Güneşin yansıması

Ben istemezdim

Güneşe bakamamayı istemeyi...', 'Hâlâ yüzer içimde birkaç gemi Ve benzer kapı gıcırtısına keman sesleri İstemezdim ben Kıvrımlarında yüzünün bir hayat istemeyi. Adım adım bo...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hala-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçe Kapanış(1)', 'i-ce-kapanis-1-i-mam-ali-seven-yl641', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece yarısı sokağın ortasından yürümek

Sancısıyla düşürmenin gölgeni duvarlara

Gündüzleri gezenler söyle nerden bilecek

Gecenin annem gibi içten ağladığını.

Yalnızım çok yalnızım boş sözlerime kanma

Benlik sapkın rüyası güneş ışıklarının

Bırak defolsun sesi iğrenç kalabalığın

Defolsun pis kokusu hafifmeşrep kızların.

Saat biri geçince yaşamak başka şeydir

Bir gayretle direnmek yarı ölü olmaya

İçinden geleni yap mağrur büyük dünyaya

Etrafında konuşan sevdasızlara inat.

Mecbur mu sandın beni sevinince gülmeye 

Ve yahut ağlamaya içime çöktüğünde

Ben haykırdım sabaha gırtlağım yettiğince

Yettiğince haykırdım bu garip kavgalara.

Saat iki olunca yaşamak bir başkadır

Yaralarını sarmak amaçsız hayatların

Seni nasıl anlasın mekan için dövüşen

Ölümün kavgasını ölümüne sevdikçe.

Ben artık yürüyemem başım dik elim gökte

Dindiremem sızısını avuçlarımdaki kuşun

Güneş n''olur doğma doğma sabah olacak

Düşecek üzerime karanlığı ışığın.

Saat dördü geçince yaşamak bambaşkadır

Başka türlü görünür buğusu demli çayın

Birkaç saat sevişir yüzün ve kırışığın

Onlar bir parça etler sense garip bir mana...', 'Gece yarısı sokağın ortasından yürümek Sancısıyla düşürmenin gölgeni duvarlara Gündüzleri gezenler söyle nerden bilecek Gecenin annem gibi i...', ARRAY['Türk Edebiyatı','Şiir','İmam Ali Seven']::text[], 8.5, '{"poet":"İmam Ali Seven","poet_slug":"i-mam-ali-seven","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ice-kapanis-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SORUN', 'sorun-mutlu-sozer-0kaq9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çalışamam patronum

Çalışamam şimdi

Ne demire kaynak

Ne de vidaya somun

Yapamam şimdi

Metalik sesi çekiçlerin 

Olmuşsa bir İspanyol rapsodisi

Önümdeki tezgah anımsatıyorsa

Akdenize düşen akşamları

Ve elim

Kalem gibi tutuyorsa levyeyi

Bırak yazayım patronum

Çalışamam şimdi

(Zor aldılar arkadaşları elinden 

 kalemini kağıdını.Levye ile

 duvarı parçalamıştı.) 

Patron ise düşünceli

Yeni bir sendikal sorun

Ya şiir yazmak isterse işçi

- Mutlu Sözer -', 'Çalışamam patronum Çalışamam şimdi Ne demire kaynak Ne de vidaya somun Yapamam şimdi Metalik sesi çekiçlerin  Olmuşsa bir İspanyol rapsodisi...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkışçıl', 'alkiscil-mutlu-sozer-pqjbe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırıldı cama vuran gölge

Yitik duygular hücresinde

Saçlar omuzları ıslattı

Duvar sürtünce beyinlere

(Anaç kedideki kaos bilinemezdi.

Kadın bacaklarının görünmesinden 

şikayetçi.Dört yavru anı oldu 

saydam eller yüzünden.Tesbihleşen

oyuncular hep aynı oyunu oynuyorlar.) 

-İki perde ve trajedi

 kısır döngüsü kişinin rolleri-

-Gibi yaparak- kazanılıyor ekmek

Erek dünyada iki nefes fazla almak

Sonra çekmek perdeyi kapamak

(Ve dişi kuliste evlendi. Kedi ise bir sonraki

martı beklemek zorunda anretede, kendisi

erkek kedilerle evli.)

-Mutlu Sözer-', 'Kırıldı cama vuran gölge Yitik duygular hücresinde Saçlar omuzları ıslattı Duvar sürtünce beyinlere (Anaç kedideki kaos bilinemezdi. Kadın b...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/alkiscil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Metrajlı Şiir', 'kisa-metrajli-siir-mutlu-sozer-v07wh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bomboş odada yerde bir yatakta

Çekip üstüne bir yorganlık dünya

Yarattı kendine

Bilmezdi hangi yerlerin müziğidir bu

Canı sıkılmış ıslık çalıyordu kapı

Nefesini rüzgarlardan alıp

İdamlıktı pantolonu

Asardı bir çiviye

Her gece yatmadan önce

Aşıktı terlikleri (Sol terlik, sağ terliğe) 

Sevmezlerdi ayakkabıları

Dönüp baktı 

Bir çift serseriye

Bir de çay bardağı vardı

Şu duvarın köşesinde duran

Saksılık taslıyordu anaç anaç 

(Fasulye tohumu, çay bardağını

rahimseyince, çay bardağı da

tohumu bebeksemişti.) 

Şarkı mırıldanmaya başlamışken tam

Timur Selçuk girdi kapıdan

İspanyol Meyhanesine gidelim dedi

Bütün hesaplar benden

Gitmedi sevindi yataktaki yataktaki Carmen

Saati vardı arada bir çalardı

(Dayısı fabrikada siren) 

İkinci dünya savaşı yıllarıydı

Killi küfürleden mask yaptı

Hitlere benzedi şaşmadı

Kapı açıldı carlos Saura girdi içeri

Aldı götürdü yatağındaki Carmeni

Söylememişti filmden kaçıp geldiğini

(Zaten çöplükte bulduğu kadın resmine

aşıktı o. Parmağı ile iteledi o güzel yüzde 

ben gibi duran dometes çekirdeğini) 

Sevişince kalabalıklaşırdı kişi

Ama yinede yanlız hissediyordu kendini

Emindi korkmadığından onun yerine

Islık çalıyordu kapı zaten

''Bir dağın durgunluğunda 

Zamanın akıcılığını yaşamak kadar karşıt

Kendini bulma yetisinden yoksunluk

Yaşanır korkularda

Putsallaştırıp tapılmadığı kalmıştı

Çevremize çektiğimiz duvarlara

İçinden çıkamadığımızdandır tapınmamız''

Dedi bakarken tavana

Yoğun saatler geçirirken bir yorganlık dünyasında 

Kara derili bir Afrikalı girdi odaya

Sarılmış şarkısına

Acılarını notalıyordu dünyanın

Çığlıklardan müzikti bu

Özgü ve özgün 

Kendi sokakları geldi aklına dinleyenlerin

Onunsa şarkının nakarat kısmı kaldı aklında

“Kan ki hep kırmızı kalacak

 Çığlık pıhtılanmaz bir tek”

Kalkıp kağıt kalem aldı eline

Şiir yazacaktı kendine

Ünlü şairdi bir önceki düşünde

(Rönesansın mirasıdır ünlü olmak isteği

onusa ünlü olarak bildiği sadece A, O, Ü ve İ) 

Şöyle satırladı şiirini

''Bulanık gökyüzü 

              denizi arkadaş edinir

 Ve dost olur insanlar benleriyle

              kendi dertleriyle dertleşir

Herşey  öyle bir durdu ki

Kıpırdayan sadece 

Rüzgar zorlanması yapraklar 

Pamuk paçavra doldurmalı içlerine

İyice kırışmadan insanlar''

Tam bitirmişti ki şiiri kapıdan önce sesi girdi.

Elma şekeri yalamış çocuk neşesi doluştu

bekleyişi biten eve.Dışarıda yağan yağmur 

son damlasını bıraktı saçının telinden.

Sokak sinmiş üstüne çekidüzen verdi.

Şenlenmişti dünyası ve yatağı.

Yıllardır görmediği dostuydu gelen.

Yetmişsekizde ölmüştü.

Karşısında gülümsüyordu şimdi.

Kafasındaki kurşun hala serseri.

.................

Artık ıslık çalmıyordu kapı

Sol terlik sağ terliğe küsmüştü

Doğum sancısı çekerken çay bardağı

Başka erkeklerin olmuştu Carmen

Saat durmuştu (dayısı fabrikada siren) 

Artık ıslık çalmıyordu kapı

Hitler gülüyordu ağlarken Afrikalı

............

Yorgan yerde o ayaktaydı

Duvara kapanmış hıçkırıyordu

''Böylemi olacaktı” diye haykırdı

Damlarken göz yaşları.

-Mutlu Sözer-', 'Bomboş odada yerde bir yatakta Çekip üstüne bir yorganlık dünya Yarattı kendine Bilmezdi hangi yerlerin müziğidir bu Canı sıkılmış ıslık çal...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":96,"source_url":"https://www.antoloji.com/kisa-metrajli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-mutlu-sozer-xnw5d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek 

Sen çok sevmek yetmiyor

“Bizim şarkımız” laştırdığımız*

Ezgiyi dinlerken bile

Sevgisiz senin 

Sensiz sevgilere yetmediği gibi

Kocamışlara özgü geri dönüşlerin 

Şu gencecikliğimde var olmasının acısı

Çöküyor yüreğime

Kocamışlığımda geri dönemezliğimin

Korkusuyla birlikte

* En evrensel şarkıdır.Her sevginin bir

“bizim şarkımız”ı vardır ya da olmalıdır.

** “Şarkı söyleyen insanların yanında kaygısızca

durabilirsin, çünkü kötüler şarkı söylemez”

(Mazdaznan Felsefesi)', 'Seni sevmek  Sen çok sevmek yetmiyor “Bizim şarkımız” laştırdığımız* Ezgiyi dinlerken bile Sevgisiz senin  Sensiz sevgilere yetmediği gibi K...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dersi', 'ask-dersi-mutlu-sozer-vo2wu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevilen kadınlar

Hep denize benzetilir

Erkekler de nedense

Ay gibidir geceleri

İşte bu yüzündendir çocuğum

Şu durmak bilmeyen

Med-cezir med-cezir

-Mutlu Sözer-', 'Sevilen kadınlar Hep denize benzetilir Erkekler de nedense Ay gibidir geceleri İşte bu yüzündendir çocuğum Şu durmak bilmeyen Med-cezir med-...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-dersi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elmenü', 'elmenu-mutlu-sozer-8ishh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnadına bakarım kaynak yaparken

Gözümü kapattığımda 

Görebilmek için o mavi gülü

Bir demet sarmaşık ve bir gram kaos

Yarımyamalak soleyit ve elmenü

Nasıl düşerse mavi demire

İçim o kadar soğuk ve bilmece

Ne de isteklidir Elmenü

Hele gencecik ve delikanlıyken gece

Halk plajlarında yanık deri kokusu

Kıştan kalma küflü gölgelikleri

Beynimde titreşirken gitar telleri

Edilgen yumuşaklığı dolaştı kumunda

İçimdeki çöllerin

Bir çadırlık cehennem tercihidir o

Hemde Ağustos öğlelerinde

Bile bile acıdır bile bile sızı

Sonrası yoktur ve mecbur sevgili

Farkında bile olmasa boynu bükük udinin

Yamurlu kış öğleden sonralarında

Dilimin ucuna gelen sessizliktir o

Gözümü kapattığımda mavi bir güldür Elmenü

Hele delikanlıyken gece

-Mutlu Sözer-', 'İnadına bakarım kaynak yaparken Gözümü kapattığımda  Görebilmek için o mavi gülü Bir demet sarmaşık ve bir gram kaos Yarımyamalak soleyit ve...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elmenu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-mutlu-sozer-jcki9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çay alırsa cı''yı

Eğer ki

Simitte çi''yi

Sattırır kendini

Kahvaltıdır

Ama sanat

Alınca çı''yı

Peşinden sürükler bizi

Bu da en büyük

Açlığımızdır.

-Mutlu Sözer-', 'Çay alırsa cı''yı Eğer ki Simitte çi''yi Sattırır kendini Kahvaltıdır Ama sanat Alınca çı''yı Peşinden sürükler bizi Bu da en büyük Açlığımızdı...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fark-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibi', 'gibi-mutlu-sozer-c8h6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denize bakan insan

İçinden kötülük geçiremez

Yıkamaz öldüremez savaşamaz

Gibi geliyor bana

Çalamaz sömüremez

Ve hatta küfredemez gibi

Denize bakan insan

Konuşamaz uğraşamaz

Yiyip bitiremez

Gibi geliyor bana

Kısacası

Denize bakan insan

İnsan gibi gelmiyor bana.

-Mutlu Sözer-', 'Denize bakan insan İçinden kötülük geçiremez Yıkamaz öldüremez savaşamaz Gibi geliyor bana Çalamaz sömüremez Ve hatta küfredemez gibi Denize...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gibi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Boyu', 'gun-boyu-mutlu-sozer-eiywl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yollar yürüyorum bir karanfilin

Kollarında sabahlamışlığımla

Sataşan sardalya kokuları peşimde

Denizi teğetliyorum.

-Mutlu Sözer-', 'Yollar yürüyorum bir karanfilin Kollarında sabahlamışlığımla Sataşan sardalya kokuları peşimde Denizi teğetliyorum. -Mutlu Sözer-...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gun-boyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü İstemek', 'olumu-i-stemek-mutlu-sozer-oal1q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atınca taşı denize

Kaydıracak sanmışlardı

İple boynuna bağladığı halde

Haklılar

O küçük taşla 

Son verilemezdi yaşama

Bilmezler

Taşın ağırlığı

Duyduğu nefret kadardı 

-Mutlu Sözer-', 'Atınca taşı denize Kaydıracak sanmışlardı İple boynuna bağladığı halde Haklılar O küçük taşla  Son verilemezdi yaşama Bilmezler Taşın ağırlı...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumu-istemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgile Beni', 'sevgile-beni-mutlu-sozer-24oef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün olurda gelirsen evime

Yüzünü donatta gel 

Tomurcuk gül demeti gülüşünle

Kırmızı kahkahaların dolsun odama

Kollarını açta sarıl ben geldim diye

Savur saçlarını yüzüme çarpsın

İçi gülsün gözlerinin dokun ellerime

Dudaklarını da getir bende kalsın

Yüzünü donatta gel

Tomurcuk gül demeti gülüşünle

Otur sandalyeme masama

Doldurayım seni kadehlerimize

Yüzünü donatta gel 

Tomurcuk gül demeti gülüşünle

Yat yatağıma tüm gerçekliğinle

Ser denizini saçların dalgalansın

Sev

Sevgile beni gecelere

-Mutlu Sözer-', 'Gün olurda gelirsen evime Yüzünü donatta gel  Tomurcuk gül demeti gülüşünle Kırmızı kahkahaların dolsun odama Kollarını açta sarıl ben geldi...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgile-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yap''la Hesaplaşma', 'yap-la-hesaplasma-mutlu-sozer-1a95j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmişim miş''lidir

Karşı çıkmıyorum

Mışım''dır muşum''dur

Ama ya

Mamışlıklarım

Asıl onlar sonuç

Ki sorundur

-Mutlu Sözer-', 'Geçmişim miş''lidir Karşı çıkmıyorum Mışım''dır muşum''dur Ama ya Mamışlıklarım Asıl onlar sonuç Ki sorundur -Mutlu Sözer-...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yap-la-hesaplasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-mutlu-sozer-x22u5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eller dolaşıyor yüzünde kanlı

Ölmüş öldürmüş suratlı

Nefret edilesi ve istekli

Eller var saçında gözünde

-Dokunuş bitmez

                           bitmedi-

Eller sarıyor bedenimi

Öldürmemişse de

Tetik çekmiş parmaklı

-İlk nefes- dolaşıyor ensemde

-Öyle bir kin ki İsa''ya duyduğu

Paylaşmadı ne öncesini 

                  ne de sonrasını O -

Sen baksana bana 

Kaşın gözün nerede senin

Ensem saçım yüzüm de kalmadı

-Öncesi- sen dedin

-Sonrası- ben dedim

İsa

Öl

''dan sonra

''dürdü beni

O

Benim artık

-Mutlu Sözer-', 'Eller dolaşıyor yüzünde kanlı Ölmüş öldürmüş suratlı Nefret edilesi ve istekli Eller var saçında gözünde -Dokunuş bitmez                    ...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Sözer']::text[], 8.5, '{"poet":"Mutlu Sözer","poet_slug":"mutlu-sozer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/zaman-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Erken Ben Gec', 'sen-erken-ben-gec-sair-anonym-3hbhz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benden büyüksün, hemde oldukca

Göz görmez ki hakikati ask olunca

Delice düsüncelerin esiri oldum! 

Hayat bu ya Sen Erken Ben Gec gelmisim dünyaya.

Su satirlarimda gizlidir anlatamadigim duygularim, 

Sözler varki sair bile bulamaz anlatmaya

Yasamak gerek bilmek icin aski! 

Hayat bu ya Sen Erken Ben Gec gelmisim dünyaya.', 'Sen benden büyüksün, hemde oldukca Göz görmez ki hakikati ask olunca Delice düsüncelerin esiri oldum!  Hayat bu ya Sen Erken Ben Gec gelmisi...', ARRAY['Türk Edebiyatı','Şiir','Şair Anonym']::text[], 8.5, '{"poet":"Şair Anonym","poet_slug":"sair-anonym","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-erken-ben-gec-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kadıköy-eminönü', 'kadikoy-eminonu-mukerrem-mete-2zntj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yürümeyi ne kadar seviyorsam

o kadar nefret ederdim hatlardan

biri hariç

kadıköy-eminönü

damağımda kaldı

martılarla paylaştığımız simidin

sıcak salebin tadı

aptallık derdin alışkanlık oldu sonraları

seninle başladım sigaraya vapurda

rüzgar sen ve ben birlikte

içiyorduk dallar ard arda

simit parçaları yerine şimdi

satırsız sayfasız zarfsız

mektubum var gagalarında

sana son mesajımı martılarla gönderiyorum

dalgalarda deva arıyorum bu derde 

kafam biraz bulanık biraz dumanlı

köpük köpük bu günlerde

inanmazsın gittiğin günden beri

bıraktım içmiyorum sigara

otobüsle geçiyorum köprüden

binmedim gittin gideli vapura', 'yürümeyi ne kadar seviyorsam o kadar nefret ederdim hatlardan biri hariç kadıköy-eminönü damağımda kaldı martılarla paylaştığımız simidin sı...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kadikoy-eminonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hollanda Kızları', 'hollanda-kizlari-ensar-aktas-5e7np', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yumruk kadar bir kalbim var

İçine nice sevgiler, nice aşklar sığar

Nice güzeller, nice kızlar sığar

Ama bir başkadır mavi gözlü, sarı saçlı

Şu Hollanda kızları

Bir gülüşü, bir yürüyüşü

Aşka düşürür bir görünüşü

Gösterir insana gündüz düşü

Nedense bir başkadır mavi gözlü, sarı saçlı

Şu Hollanda kızları

Kendisini naza çekip seni üzmez

Bir öpücük versen darılıp küsmez

Sevdaya düşürür kendisi düşmez

Hem şirin hem tatlıdır mavi gözlü, sarı saçlı

Şu Hollanda kızları

Rotterdam,04.11.1988', 'Yumruk kadar bir kalbim var İçine nice sevgiler, nice aşklar sığar Nice güzeller, nice kızlar sığar Ama bir başkadır mavi gözlü, sarı saçlı ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hollanda-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Dostlarım 1', 'ah-dostlarim-1-salih-ozalasan-effpc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herzamanki gibi yine sen haklısın belalım

Dost diye birşey yokmuş hayatta

Hep kendinden başka dost yok derdinya

İnsanın kendiside ihanet ediyor bazen insana

Dost dost diye başım yedim

Şimdi dost bildiklerim var etrafımda

Fırsat geçse ellerine eminim

Boğacaklar beni bir kaşık suda ilk fırsatta

Artık rahat uyku yok

Kabuslar ard arda yatakta

Dostlarım fırsat kolluyor pusuda

Bilmemki bunlar yazıyor hangi kitapta

Bana edileni ne kitap yazar

Nede bir hatip okumaya cesaret eder

Dost bildiklerim hergün tepemdeler

Dostum dersem birdaha dilimi kessinler

Kessinlerki birdaha dostum diyemesin

Kırılsın ellerim kimseden aman dileyemesin

Bana müstahak aslında Allah beterini vermesin

Aptal sen belayı zamanında niye dinlemessin

Y.tarihi 24-08-2002 Saat 15.00', 'Herzamanki gibi yine sen haklısın belalım Dost diye birşey yokmuş hayatta Hep kendinden başka dost yok derdinya İnsanın kendiside ihanet edi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ah-dostlarim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Üstü Yine Sen Kanadın Gönlümde', 'bu-aksam-ustu-yine-sen-kanadin-gonlumde-haci-sinan-temel-0ptfl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamın sükutunu soluyor deniz, 

Gündüzün tükendiği yerden

Gece uyanıyor mor renklerle.

Sahil kentinde bir akşam üstü

Islak kayalar arasına

Yorgun argın çökerek

Seni düşünüyorum birtanem.

Usulca sararken sahil kentini koyu ufuklar

Sevdan yüreğimde dalga dalga, 

Bir akşam üstü yalnızlığı yaşıyorum sensiz, 

Özlemin enginler kadar derin, 

Gönlüm akşam üstü kadar ıssız.

Deniz patlayacakmış gibi dolu, 

Kayalar yıllarca ağlamışçasına ıslak.

Bu akşam üstü

Dalgaların vurduğu kıyıda düşünüyorum seni

Çırpınan yüreğimle beraber, 

Ve seni, 

Taşların, yosunların arasından bulup çıkarıyorum.

Tuzlu nemiyle hasretin gözlerimi yakıyor, 

Seni çiziyorum yalnızlığımın sahiline...', 'Akşamın sükutunu soluyor deniz,  Gündüzün tükendiği yerden Gece uyanıyor mor renklerle. Sahil kentinde bir akşam üstü Islak kayalar arasına ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Sinan Temel']::text[], 8.5, '{"poet":"Hacı Sinan Temel","poet_slug":"haci-sinan-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-aksam-ustu-yine-sen-kanadin-gonlumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keke', 'keke-servet-kocakaya-fmrm8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bingöl dağlarında kahveci keke

Sırtında bir çuval şeker çay keke

Uçurumlar seni çeker vay keke

Sırtın yere gelmesin tez dön keke

Demli çayın canım çeker dön keke

Keke şeref keke namus 

Keke babam keke paşam

Keke sesini duymuşam

Yoksa keke

Sen mi geldin

Tez mi geldin

Sen mi geldin hay keke

Yollarına kurtlar çıksa dert değil

Üzerine çığlar düşse dert değil

Yüreğine hasret düşse vay keke

Sırtın yere gelmesin tez dön keke

Demli çayın canım çeker dön keke', 'Bingöl dağlarında kahveci keke Sırtında bir çuval şeker çay keke Uçurumlar seni çeker vay keke Sırtın yere gelmesin tez dön keke Demli çayın...', ARRAY['Türk Edebiyatı','Şiir','Servet Kocakaya']::text[], 8.5, '{"poet":"Servet Kocakaya","poet_slug":"servet-kocakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/keke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-haci-sinan-temel-84mst', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam da bekledim seni

Güneşin solduğu yerde.

Biliyorum geleceksin, 

Denizin sahili bulduğu yerde.

Hani ellerin, hani gözlerin nerde? 

Bekliyorum

Dalgaların gönlüme vurduğu yerde.', 'Bu akşam da bekledim seni Güneşin solduğu yerde. Biliyorum geleceksin,  Denizin sahili bulduğu yerde. Hani ellerin, hani gözlerin nerde?  Be...', ARRAY['Türk Edebiyatı','Şiir','Hacı Sinan Temel']::text[], 8.5, '{"poet":"Hacı Sinan Temel","poet_slug":"haci-sinan-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bekliyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güleyşa', 'guleysa-servet-kocakaya-4rwe5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahpe akar Murat Suyu çamurdan rengi

Güleyşa’ya vurulmuşum bulunmaz dengi

Böyle zaman böyle dünya çekilmez derdi

Söyle Murat söyle bilem darda mı Güleyşa

Zorda mı Güleyşa...

Şahin oldum uçtum dağ başına

Rüzgar oldum estim dağ taşına

Serçelere sordum hep boşuna

Senden evvel ölem

Koyma beni böyle bir başına

Gule le Guleyşa, Guleyşa, Gule...

Bir ceylanın yavrusuna tüfeng tutulmaz

Bir gelinin çeyizine kefen koyulmaz

Böyle zaman böyle dünya derdi çekilmez

Söyle Murat söyle darda mı Güleyşa

Zorda mı Güleyşa...

Şahin oldum uçtum dağ başına 

Yağmur oldum döndüm gözyaşına

Serçelere sordum hep boşuna

Senden evvel ölem

Koyma beni böyle bir başıma

Gule le Güleyşa, Güleyşa, Gule...', 'Kahpe akar Murat Suyu çamurdan rengi Güleyşa’ya vurulmuşum bulunmaz dengi Böyle zaman böyle dünya çekilmez derdi Söyle Murat söyle bilem dar...', ARRAY['Türk Edebiyatı','Şiir','Servet Kocakaya']::text[], 8.5, '{"poet":"Servet Kocakaya","poet_slug":"servet-kocakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guleysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlar', 'daglar-servet-kocakaya-byt8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyalara değişemem sandığım

Bahçelerden çiçekleri çaldığım

Onun için ateşlere daldığım

Bir zalimin ihanetiyle yandım

Dağlar, dağlar

Geceleri benim için kim ağlar

Ben bu gece ölmezsem 

Ölmem, ölmem hiçbir vakit

Dağ gibi bir yiğide kıydı geçti sanki vakit

Ne demeli şu zalime kal bu gece kal yada git

Azrailim şu canımı al bu gece al yada git

Güvendiğim şu dağlara kar yağdı

Ayrılık pusuda kaldı gün saydı

Azrailim şu canımı alsaydı

Bir zalimin ihanetiyle yandım

Dağlar dağlar', 'Dünyalara değişemem sandığım Bahçelerden çiçekleri çaldığım Onun için ateşlere daldığım Bir zalimin ihanetiyle yandım Dağlar, dağlar Geceler...', ARRAY['Türk Edebiyatı','Şiir','Servet Kocakaya']::text[], 8.5, '{"poet":"Servet Kocakaya","poet_slug":"servet-kocakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/daglar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek Derdi', 'ekmek-derdi-servet-kocakaya-3lg9b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sefaletin leş kokusu

Çıkmaz durur üstümde hey

Meteliğe kurşun sıkan

Şarkılar var dilimde hey

Bir yanında açlık

Bir yanım aşık

Bir yanım çaresiz

Aklım karışık

Ben bu derdin üstesinden gelemem

Ekmek derdi yetmez gibi bir de sen

Bir kez olsun sevdiğini söylesen söylesenİlk adım önemliydi

Atamadı veremliydi

Satamadı dertlerini

İki gözü de nemliydi

Servet beni adam etmez

Tütmez benim gözümde, hey

Sevdan beni sultan eder

Bitmez aşkın gönlümde, hey', 'Sefaletin leş kokusu Çıkmaz durur üstümde hey Meteliğe kurşun sıkan Şarkılar var dilimde hey Bir yanında açlık Bir yanım aşık Bir yanım çare...', ARRAY['Türk Edebiyatı','Şiir','Servet Kocakaya']::text[], 8.5, '{"poet":"Servet Kocakaya","poet_slug":"servet-kocakaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ekmek-derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-bulent-yaslan-nt4w2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba derken sabaha 

Merhaba derken akan zamana

Merhaba sevgili sana

Merhaba kuşlar size

Bu sabah bir başka dönüyor dünya

Kıpırtılar var içimde mutluluk adına

Birşey yok ama bir kıpırtı mutluluk adına

Kim bilir belki umutlar yaptırıyor bunu bana

Sevdalı başım dolanır sokaklarda

Bir çocuk edasıyla

Merhaba yalan dünya 

Bilirim sen anlamazsın sevdadan

Yıkıntılar enkazlar var her yanında

Merhaba güzel kız sanada

Bu heyacan bu mutluluk sana

Seni ğördüm diye belki bu haller

İçtiğim çay bile bambaşka

Hayat bu işte oyna oyna

Doymamışızdır sevdalara 

Hasretiz belki hep mutluluklara

Bir güzel şey görünce umutlanırız hep

Mutluluğa aç gönlümüze avuntular var

Merhaba güzel kız sana

Hayatın güzellikleri hep sana

Dolu dolu yaşa

Acılardan habersiz yaşa

Oyna oyna bakalım 

Benim sana sevdamı oyna

Merhaba de ve başla yalanlara', 'Merhaba derken sabaha  Merhaba derken akan zamana Merhaba sevgili sana Merhaba kuşlar size Bu sabah bir başka dönüyor dünya Kıpırtılar var i...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yaslan']::text[], 8.5, '{"poet":"Bülent Yaslan","poet_slug":"bulent-yaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/merhaba-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaturka Rapsody', 'alaturka-rapsody-sukru-ozmen-uynhs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç deniz görmedim

Ömrüm, 

Kara kalelerin burçlarında

Düşmanlar beklemekle geçti

Mızrağımı sivriltmekten

Nakışlar dökemedim 

Kılıncımın üstüne

Geldikçe üstüme gökyüzü

Ben 

Gecenin rahmine kaçardım

...

Hep alaturkaydı

Sevda sözlerim

Basit yani

Asri pencereden

Devrik cümleler kurmayı 

Öğrendiğim gün

Savaş

Sorgulanabilirlik kazandı

Beynimde

Ve güzel savaşları

Kötü şiirlere sattım 

Sırf Mephisto''mun

Gönlü olsun diye

...

Senide sırf bu yüzden 

Sevmiyorum artık

Ruhumu arsız fareler

Kemirmesin diye 

Sana 

Alaturka sevda sözleri

Söyleyemiyorum diye

Evet sadece bu yüzden

Sevmiyorum artık seni

...

Kılıcım kırıldı işte

Denizi gördüğümde

Elimden düştüğü yerde

Yazık ne kadarda zarifmiş

Oysa ben 

Bütün demir kalpleri

Onunla sökmeyi tasarlıyordum

Yerlerinden

...

Karşımda gittikçe büyüyen 

İbrişim düğümleri

İskender''i ne çok özlüyorum

Şimdi bilseniz

...

Belki çiçekler çizseydim

Mızrağımın üstüne

Şiirler yazsaydım 

Göğsüne boydan boya

Mesela şöyle ÖZEL bir şiir: 

''Elbet bir hinlik vardır 

Seni sevişimde eyy

Kanıma çakıllar karıştıran İSYAN''

...

Seni; 

Beni; 

Mızrağıma şiirler yazmaktan 

Alıkoyduğun için 

Sevmiyorum işte

...

Denizi gördüm evet

Ama sadece o kadar

Demirden kalpler

Denizle onarılmazki...

Ağustos 2002', 'Hiç deniz görmedim Ömrüm,  Kara kalelerin burçlarında Düşmanlar beklemekle geçti Mızrağımı sivriltmekten Nakışlar dökemedim  Kılıncımın üstü...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Özmen']::text[], 8.5, '{"poet":"Şükrü Özmen","poet_slug":"sukru-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/alaturka-rapsody-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Vardım', 'ben-vardim-hakan-akyurt-d7sqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki yağmurlarla geldi sevgin, 

Her düşüşünde damlanın, sen vardın..

Sanki gökyüzünden inen sendin, 

Her gelişinde yanında, ben vardım..

Koşarak peşinden gelen bendim, 

Her kaçışında arkanda, ben vardım..

Yüreğini koymaya korkan sendin, 

Verseydin ısıtacak, ben vardım..', 'Sanki yağmurlarla geldi sevgin,  Her düşüşünde damlanın, sen vardın.. Sanki gökyüzünden inen sendin,  Her gelişinde yanında, ben vardım.. Ko...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-vardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız ve Mutsuz', 'yalniz-ve-mutsuz-hakan-akyurt-ortq1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani zamanı harcarsın ya umursamaz, 

Gözlerin yorgun bakar ya yarınlara, 

Aldatarak kendini hayaller kurarsın ya, 

İşte ben o yaşamdayım şimdi, yalnız...

Hani sevmeye çalışırda beceremezsin ya, 

Kader sanki istemez ya mutlu olmanı, 

Hayallerinde yaşarsın ya meleğinle, 

İşte ben o sevdadayım şimdi, mutsuz...', 'Hani zamanı harcarsın ya umursamaz,  Gözlerin yorgun bakar ya yarınlara,  Aldatarak kendini hayaller kurarsın ya,  İşte ben o yaşamdayım şim...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalniz-ve-mutsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık Ben Değil..! !', 'asik-ben-degil-hakan-akyurt-zcz1r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzanırım her gece yatağa bir damla uyku için, 

Sanki yatak benim değil, yatan ben değil..! 

Dalayım isterim rüyalara seni unutmak için, 

Sanki gönlüm senin değil, seven ben değil..! 

Kurmak isterim hayaller içinde sen olmayan, 

Sanki bu kalbim senin değil, aşık ben değil..! 

Yazmak isterim satırlar içinde sen olmayan, 

Sanki şiirlerim senin değil, yazan ben değil...! !', 'Uzanırım her gece yatağa bir damla uyku için,  Sanki yatak benim değil, yatan ben değil..!  Dalayım isterim rüyalara seni unutmak için,  San...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asik-ben-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapay Gülünçlükler Oyunu', 'yapay-gulunclukler-oyunu-hasan-sabah-sfs3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kabahat işlemiş çocuk gibi

Rüzgar, 

Karanlık  bir ormanın içinde eser gibi

Islıklı...soğuk.

Kayıtsız düşler kuruyor yapraklar

Gri bulutlar yağmur söyletiyor

Toprağa.

Telaşsız fakir dilencinin eline düşen

Para gibi

Yalın ve yalnız 

Aşk.

Sabah saatlerine özgü uğultusu

Kulaklarımda, 

Sesinin tınısının son kayboluşunda.

Birden! 

Mezar sessizliğinde

Kaba saba şaşkınlık

Yapay gülünçlükler oyununun, 

Son perdesinde.

Gereksiz küçük züppeliklerin

Çileden çıkaran, 

Soğuk mermer tazeliğinde

Ruhumu.

Sahte sürgünlüklerin ötesinde, 

Alaycı gülümsemen.

Büyük hüzünlerin sevimli

Gönülsüzlüğü, 

Sabah tazeliği

Yağmur tanesinde, 

Teninde', 'Kabahat işlemiş çocuk gibi Rüzgar,  Karanlık  bir ormanın içinde eser gibi Islıklı...soğuk. Kayıtsız düşler kuruyor yapraklar Gri bulutlar y...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sabah']::text[], 8.5, '{"poet":"Hasan Sabah","poet_slug":"hasan-sabah","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yapay-gulunclukler-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adaletsiz Yar', 'adaletsiz-yar-emre-altinok-vquvw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adaletsizlik yaptım sevgi için

Yar ettim seni, kaybettim

Dedim ya ADALETSİZ YAR! 

Sevgiyi son anda farketmişim yada anladım.

Sevgimin hakkını kime vermekte adaletsizlik yapmışım

Hata etmişim..

Aşkın hakkını vermemişim, verememişim.

İsteklerimi anlatamamışım.

İsteklere bile adaletsizlik yapmışım.

Gururuma ekmek banıp yiyememişim

Sonunu geçmişte görmüşüm geleceğin.

Adaletsiz', 'Adaletsizlik yaptım sevgi için Yar ettim seni, kaybettim Dedim ya ADALETSİZ YAR!  Sevgiyi son anda farketmişim yada anladım. Sevgimin hakkın...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adaletsiz-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
