INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua Başlangıcı', 'dua-baslangici-can-yucel-i7wsu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yumurtaya can

Can''a yumurta veren allahım...! !', 'yumurtaya can Can''a yumurta veren allahım...! !...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dua-baslangici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezler', 'bilemezler-haci-sinan-temel-r1lt0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anılar üstüme yağdı bu akşam, 

Şarkılara yükledim tüm acıları.

Çaresizce yaşadığımı bilemezler, 

Bilemezler her sancıya ayrı bir yas tuttuğumu.

Gidene ağlamak benim kaderimmiş, 

Adı konmamış hüzünlerde

Dost günlerin kokusunu bulduğumu

Bilemezler.

Sevgiyi dost şehirde bırakmışım; 

Gençliğim, sevincim, umutlarım, 

Yayla kentinde kalmış.

Şimdi hayatın lezzetinde olmadığımı

Bilemezler.

Anılar çöreklendi yüreğime bu akşam, 

Kar tanelerine bindirdim tüm neşeyi.

İçimde bir denizin hıçkırdığını bilemezler, 

Bilemezler o günleri ölesiye yaşadığımı.

O sanıyorum sisler içinde her güleni, 

Bir el uzatımı ötedeki

Mutluluğu tutamadığımı, 

Dost günleri düşününce

Bir kuşun yüreğimin ucuna konduğunu

Bilemezler.

Anılar öbek öbek üşüştü bu akşam, 

Bir okyanus kayboldu gözlerimde.

Gurbetin garip akşamlarını bilemezler, 

Bilemezler yağmurlarla birlikte yağdığımı.

Her gece yolumun bir başka sokağa açıldığını, 

Her gece dağbaşları kadar yalnızlığımı

Bilemezler.

Dudaklarımda eski bir aşk türküsü, 

Yıllardır bu sevdayı yüreğimden sökemediğimi

Bilemezler.

Anılar yanaklarımdan süzüldü bu akşam, 

Sokaklardan önce gönlüme indi karanlık.

Bu saatlerde beynimin zonkladığını bilemezler, 

Bilemezler mutluluğu sigarada bulduğumu.

Bir çiçek ömrü kadarmış tüm sevinçlerim, 

Yüreğimin sayısız acılara bölündüğünü, 

Yaprakları dökülen bir ağaç olduğumu

Bilemezler.

Hüzzam şarkılar gibi çöker akşam, 

Sine sine iner gözlerime.

Bir uzak şehirde

Rüzgarın benim için ağladığını

Bilemezler.', 'Anılar üstüme yağdı bu akşam,  Şarkılara yükledim tüm acıları. Çaresizce yaşadığımı bilemezler,  Bilemezler her sancıya ayrı bir yas tuttuğu...', ARRAY['Türk Edebiyatı','Şiir','Hacı Sinan Temel']::text[], 8.5, '{"poet":"Hacı Sinan Temel","poet_slug":"haci-sinan-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bilemezler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Zambak', 'sari-zambak-haci-sinan-temel-spfch', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuru soğuk altında üşürken zavallı vücudum, 

Bir vefasızı arayan gözlerim yine ıslak.

Azrail canımı alsa da göğe çıksa ruhum, 

Hâk-i makberimde yeşerecek bir Sarı Zambak.

Bilmem bu kaçıncı akşam gurbetin bağrında, 

Gönlümün dalından koparıldı bir sarı yaprak.

İçim kan ağlar onsuz her gecenin sabahında, 

Gençliğimin kâtili oldu bir Sarı Zambak.

Yağan karlar altında yürürken bir gölge gibi, 

Düşünüyorum da feleği ne kadar oynak.

Çürüse de bedenim toprakta bir gazel gibi, 

Hâk-i makberimde yeşerecek bir Sarı Zambak.

Ellerim bağlı Yüce Hakim huzurundayım, 

Her iki yanımda jandarma konuşmam yasak.

Ey Hakim, bakışlarımdan anla ne durumdayım, 

Hem sebebim, hem çarem oldu bir Sarı Zambak.

Yağmur çiselerken ben eller üstündeyim, 

Donmuş vücudumu taşıyan tabut ıslak.

Dostlar arkamdan gözyaşı dökerken benim, 

Lâkayt duran biri var, o da bir Sarı Zambak.', 'Kuru soğuk altında üşürken zavallı vücudum,  Bir vefasızı arayan gözlerim yine ıslak. Azrail canımı alsa da göğe çıksa ruhum,  Hâk-i makberi...', ARRAY['Türk Edebiyatı','Şiir','Hacı Sinan Temel']::text[], 8.5, '{"poet":"Hacı Sinan Temel","poet_slug":"haci-sinan-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sari-zambak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen-gidersen', 'sen-gidersen-mehmet-fatih-uzut-3abed', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen gidersen; 

      güller küser benimle, 

               gecelerime doğmaz yıldızlar, 

                       ay ışığı hiçbir zaman dolmaz odama, 

    serçeler, penceremin kenarına konmazlar

sen gidersen; 

       efkarlanır gökyüzü, 

                deniz rakısını içer bulutlar, 

                         ardından dolar gözleri, 

     ağlarlar........

sen gidersen; 

        ellerim şiire uzanamaz, 

                  dudaklarım hiçbir şarkıyı fısıldamaz, 

                          kalbim kanar; 

                                   gözyaşlarım kurur, 

      gözlerim ağlayamaz........', 'sen gidersen;        güller küser benimle,                 gecelerime doğmaz yıldızlar,                         ay ışığı hiçbir zaman dolmaz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Uzut']::text[], 8.5, '{"poet":"Mehmet Fatih Uzut","poet_slug":"mehmet-fatih-uzut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gidersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-sureyya-berfe-7t5yd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayışığı unuttu karları

Nerdeyse tipi çıkar

Yaralı bir keklik

Uçtu önümden

Bende kaldı kanadı', 'Ayışığı unuttu karları Nerdeyse tipi çıkar Yaralı bir keklik Uçtu önümden Bende kaldı kanadı...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya-berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gurbet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-sureyya-berfe-ne5zb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni yitirmedim, kaybettim.

Cep saatimi yitirdim, seni kaybettim.

Gökyüzünün herhangi bir yerinde

herhangi bir gökyüzünde

kaybettim seni.

Kim kimi buldu ömründe? 

Herkes başka bir günü düşündü.

Şöyle ya da böyle

ömründe olmayan dünü düşündü.

Yeryüzünde hemen şurda

kaybettim seni.

Telaşla, korkuda kaybettim.

Hüzünde, coşkuda kaybettim.

''Mutluluktan ölebilirim'' dedin, kaybettim.

Kim kimi tanıdı ömründe? 

Herkes başka bir durumu düşündü.

Şöyle ya da böyle

ömründe olmayan umudu düşündü.

Kaybolan ne varsa onlarda, onlarla

geçen günlerden birinde, geçmişte

kaybettim işte, zaman sustu.

Zifiri karanlık bir mağarada

ürkek bir yosun ışıdı, kayboldu.', 'Seni yitirmedim, kaybettim. Cep saatimi yitirdim, seni kaybettim. Gökyüzünün herhangi bir yerinde herhangi bir gökyüzünde kaybettim seni. Ki...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya-berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kayip-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rağmen', 'ragmen-sureyya-berfe-tc8b6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayıp bir gün daha.

Çocuklar büyüyor, yaşlanıyoruz

seni seviyorum.

Soğuk bir çağrı daha.

Tanıdık bir boşluk, dağılıyoruz

seni seviyorum.

Gitti bir arkadaş daha.

Zaman ölüyor, duruyoruz

seni seviyorum.

Gizli-açık bir mutsuzluk daha.

Çok konuşuyorlar, sıkılıyoruz

seni seviyorum.', 'Kayıp bir gün daha. Çocuklar büyüyor, yaşlanıyoruz seni seviyorum. Soğuk bir çağrı daha. Tanıdık bir boşluk, dağılıyoruz seni seviyorum. Git...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya-berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ragmen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla', 'zamanla-sureyya-berfe-y4xb2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşününce uzaklarda olduğunu

öyle uzuyor ki zaman...

Bugün ne? 

Hafta bitti bile.

Bana sorarsan daha günler var.

Ne acı

günlerle ölçülüyor ayrılıklar.

Duyunca uzaklarda olduğunu

öyle duruyor ki zaman...

Saat kaç? 

Gün bitti bile.

Bana sorarsan daha saatler var.

Ne tuhaf

saatlerle ölçülüyor ayrılıklar.

Bilince uzaklarda olduğunu

öyle ağırlaşıyor ki zaman...

Güneş doğdu mu? 

Sabah bitti bile.

Bana sorarsan birkaç dakika var.

Ne korkunç

dakikalarla ölçülüyor ayrılıklar.', 'Düşününce uzaklarda olduğunu öyle uzuyor ki zaman... Bugün ne?  Hafta bitti bile. Bana sorarsan daha günler var. Ne acı günlerle ölçülüyor a...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya-berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zamanla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyor Gibi Çırpınıyorum İşte', 'yasiyor-gibi-cirpiniyorum-i-ste-suha-tugtepe-jq8a3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesimi sordum insana...

Belli ki o da unutmuş, 

bir sesim olabileceğini...

Halen şaşkın, 

bakıp duruyor aynama...

Hayatımı sordum hayata...

Öğrendiklerimin ağırlığı, 

o çığlığı; 

önümde yürüyen gölgeyi, 

o acıtan cümleyi...

Koklamadı bile.

Burun kıvıran bir it gibi, 

bakıp solgun yüzüme, 

yürüdü gitti...

Ne kaldı geriye? 

Üstünü kirletmeyen bir çocuk gibi, 

bekliyorum insanı işte...

Savaşsız, sınıfsız, dinsiz, ırksız, 

bir iyimserliğin avucuna koyup

çelimsiz bedenimi; 

yaşıyor gibi çırpınıyorum işte...', 'Sesimi sordum insana... Belli ki o da unutmuş,  bir sesim olabileceğini... Halen şaşkın,  bakıp duruyor aynama... Hayatımı sordum hayata... ...', ARRAY['Türk Edebiyatı','Şiir','Süha Tuğtepe']::text[], 8.5, '{"poet":"Süha Tuğtepe","poet_slug":"suha-tugtepe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasiyor-gibi-cirpiniyorum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atmeydanında Bir Şarkı', 'atmeydaninda-bir-sarki-suha-tugtepe-tkt6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırık vazolar alırım, 

kurtuluş törenlerime.

Evime kaçan bir çiçek, 

sevinerek yerleşir içine.

Yağların titrek alevinde, 

eski kandillere akarım.

Rengarenk nehirler gibi, 

yanarım üstüne.

Yitirir dengesini eski karyolam.

Yaslanır masaya.

Masa kayar arnavut kaldırımından.

İçip içip yıkılırız birlikte.

Taşplaklar, eski fotoğraflar, eski kitaplar.

Boyası dökük ikonalar, kırık bir heykel başı

Kıyıları tırtırlı bakır sahanda üç yumurta: 

Anılara dalar bandıkça ekmeğimi...

Mis gibi Bizans kokar...', 'Kırık vazolar alırım,  kurtuluş törenlerime. Evime kaçan bir çiçek,  sevinerek yerleşir içine. Yağların titrek alevinde,  eski kandillere ak...', ARRAY['Türk Edebiyatı','Şiir','Süha Tuğtepe']::text[], 8.5, '{"poet":"Süha Tuğtepe","poet_slug":"suha-tugtepe","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/atmeydaninda-bir-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kent, Sevgilim, Bizans', 'bu-kent-sevgilim-bizans-nilgun-ustun-hz7fg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizans, sevgilim, bu kent aşk gibi üstümüze kapanıyor

dev bir fanus eli sımsıkı doğurduklarını sarıyor

bizans, sevgilim, bu kent içimizde saklanıyor

başka ülkelerin loş labirentlerinde adım sayıyor

bizans, sevgilim, bu kent haz dolu düşlerimizi getiriyor

diri çocuk gibi zamanların kirli izlerini elinde tutuyor

bizans, sevgilim, bu kent gülüşüyle melek oluyor

selvi dibinde dev bir kelebek sanki öylece duruyor

bizans, sevgilim, bu kent ay yuvarlıyor pencerende

dönüşü olmayan akşamları sürekli varediyor bıçak üstünde

bizans, sevgilim, bu kent göz kırpıyor eflatun ülkelerde

hep yol biçiyor sesi olmayan çorak yüreklerde

bizans, sevgilim, bu kent şimdi soluk alıyor rüzgar yerinde

tutsak sesini yeniden söylüyor yaş almış teniyle

bizans, sevgilim, bu kent dokunuşuyla geleceği veriyor

ışıklı evlerin mor gecesine yaşlılarını gömüyor

bizans, sevgilim, bu kent örtük gizlerin mekanlarını sunuyor

yarılmış bilinçlerin bembeyaz günlerini yüzümüze çiziyor

bizans, sevgilim, bu kent durgun gözlerini üstümüze salıyor

aç kadın gibi süreksiz çığlığını yeraltı sularına biriktiriyor

bizans, sevgilim, bu kent insanı üç bin yıldır tanıyor

farklı gövdelerin ruh haritasını kuş çocuklarına çıkartıyor

bizans, sevgilim, bu kent köpek leşi gibi kimsesiz kokuyor

uçları açık geçmişini durmaksızın üstümüze kusuyor', 'bizans, sevgilim, bu kent aşk gibi üstümüze kapanıyor dev bir fanus eli sımsıkı doğurduklarını sarıyor bizans, sevgilim, bu kent içimizde sa...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Üstün']::text[], 8.5, '{"poet":"Nilgün Üstün","poet_slug":"nilgun-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-kent-sevgilim-bizans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üvey Arkadaş', 'uvey-arkadas-kucuk-i-skender-ovtfg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk kurşunu alnına sıkacağım. İkincisini karnına; sonraki kurşunlar sırasıyla omuzlarına: Böylece ıstavroz çıkararak öleceksin. Ne mutlu sana! Bana bir kadeh şampanya ısmarlamak için ne bekliyorsun? ! 

İpi boynuna kravat şeklinde bağlayacağım. Asılırken kibar ve efendi görüneceksin. Ne mutlu sana! Her yanım tereyağı içinde, bana biraz havyar sürmek için ne bekliyorsun? ! 

Sana saplayacağım bıçakla tanışmanızı istiyorum; çok eski dostumdur. Birlikte çok iş başardık, çok badireler atlattık. Keskin bir dili vardır. Yani bir ülkeyi bile bölebilir. Öyle keskin bir dil! Ne mutlu sana! Bana şurdan bir kilo tecavüz tarttırmak için ne bekliyorsun? ! 

Susadığın için boğarken seni ben, su sporlarına yeni bir branş kattığını düşün. Alnına neşterle God yazacağım. Gotik harflerle, yeni dalga akımının etkisi altında, biraz Chaplin''i taklit ederek. Biraz kafası karışık bir Richard Brautigan''ı taklit ederek. Biraz enseyi omurgaya almış bir berberi taklit ederek. Ne mutlu sana! Aramızdaki sinir haplarını toplayıp zorla konu komşuya yutturmak için ne bekliyorsun? ! 

Bizim senle hukukumuz var. Avukatımız var. Suçumuz var.

Bizim senle bir ömrü paylaşmaya andımız, bu andı çiğneyip içyüzümüzü ifşa eden ihanetlerimiz, birbirimizi kolayca harcamanın lüksü, bu lükse sığan baş önde boş boş oturuşlarımız var. Konuşamayışlarımız, hiçbir şeyi açıklayamayışlarımız, kaçıp gitmeyi erdem sayışlarımız var. Umutmuş, bir şans daha vermeklermiş, özürlermiş, lütfen unutlarmış: Zaaf Zaaf! Bunlar evrim zaafı! Ben kin tutmayı aşktan daha yüce bilirim. Aşk acısı silinir, kin mezara kadar! Sadece hümanist olacak kadar düşük değil IQ seviyem! 

Bu gece alkolle sabahla; ona de ki: Ben kanıma kırmızı rengi veren kişiyi kaybettim.

Bu gece hüzünle sabahla; ona de ki: Ben bedendeki mıknatısın büyüsünü bozdum.

Bu gece iğrenç bir korku filmiyle sabahla; ona de ki: Kabuslarımın orta yerindeki tek güzel mabedin kapısına sıçtım.

Bu gece imla kurallarına uyulmuş edebi bir intihar mektubu ile sabahla; ona de ki: Farkındayım, ölsem, cesedimi gerçekten teşhis edebilecek tek insan odur; ceset de olsam, hainim hâlâ.

Ne mutlu sana!', 'İlk kurşunu alnına sıkacağım. İkincisini karnına; sonraki kurşunlar sırasıyla omuzlarına: Böylece ıstavroz çıkararak öleceksin. Ne mutlu san...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uvey-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Christi Himmerfahrt', 'christi-himmerfahrt-kucuk-i-skender-9pvrx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olağanüstü bir kandili üfler gibi  yarım bırakılmış bir semanın altında, hızlanan, hep hızlanan acılarla koruduk çoğunluğa gömülü çocuk mezarlıklarını. Oysa biz de oradaydık, kefenini dev bir mendile dönüştürüğ gözyaşlarını silen ejderhalar arasında: Çok sigara içiyorduk acılı. Çok içki içiyorduk bağışıklık sistemine baka baka. Bütün sinemaları kapatmıştık ölüm gelir bir film seyreder diye. Gördün mü, ne yükselmeyi becerebildik sanal sanal ne de toprağa girdik kök olmak, elmas olmak, petrol olmak için.

Arada kaldık: ''Gökyüzüyle yeryüzü arasına sıkışmış, kendisine bile sahte bir böcek tadında.''

Zarif delilik ağaçların yapraklarını döküp döküp meyve verdiğini sanmasında kaldı. Hayalde kaldı. İnsandık. Ot bile olamadık aslında.', 'Olağanüstü bir kandili üfler gibi  yarım bırakılmış bir semanın altında, hızlanan, hep hızlanan acılarla koruduk çoğunluğa gömülü çocuk meza...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/christi-himmerfahrt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delinin İntikamı', 'delinin-i-ntikami-kursat-usalan-vfkmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siz beni bilmezsiniz

Yo, gerçekten bilmezsiniz

Eserim üşümezsiniz

Yağarım ıslanmazsaınız

Ağlarım tınmazsınız

Gülerim deli dersiniz

Hatta aşık olsam 

“boşver” bile dersiniz

siz beni bilmezsiniz

Ama bir gün 

bir şiir yazarım

o zaman gününüzü görürsünüz

07.05.1995

TAVŞANLI', 'Siz beni bilmezsiniz Yo, gerçekten bilmezsiniz Eserim üşümezsiniz Yağarım ıslanmazsaınız Ağlarım tınmazsınız Gülerim deli dersiniz Hatta aşı...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/delinin-intikami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoğul Yanlızlık', 'cogul-yanlizlik-kursat-usalan-2bxcs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haydi gel seninle şöyle

karşı karşıya

oturup da konuşalım.

Yaşamışlıklarımızı dokundurup

anlamlarımızı ve anlamsızlıklarımızı 

ortaklaştıralım.

Haydi yüzünü dök de gel.

Neden düşlerimizi paylaşamayız; 

suçlarımızı paylaştığımız gibi? 

Bi z ki; yapayalnız yastığımızda, 

gecenin terine sinmiş, masum; 

karanlıktan korkup annesine sokulandık.

Biz ki; kalabalığın orta yerinde

korku ve yalnızlıklardan payımıza düşeni

suçlarımıza bölüşendik.

Haydi gel! 

Irmak gibi değil mi ömürlerimiz? 

Hepimiz aynı denize dökülmüyor muyuz? 

Döl yatağında hep aynı değil mi

duruşlarımız? 

Zamanın parçalanışları herbirimizin bedenini

aynı sonsuzluğa bölmüyor mu? 

Ah! Zaman diyorum kardeşim: 

Sarmallarında senin de çaresizce

asılı kaldığın zaman.

Bir solucan gibi peşine düştüğün sevgili.

Her tangodan benzer bir ezgiyi sürükleyip götürüyor.

Bil ki eski bir sessizlik değil bu.

Senin limanın da kurulmuyor artık panayırlar.

Nasıl ki her ışık senin gözlerinde

susturmuyorsa karanlığı, 

hiç bir saat tıkırtısı da 

eşitleyemeyecek  seni

bir sonraki sana.

Yalnız bir tek şey var bilmeni istediğim: 

Güneşi ısıtmak boşuna değildir.

Ve gözlerinde koruduğun nefret, 

sensizliğin sana hediyesidir.

Düşünsene! 

Daha kaç ömrü yaşamaya  yetecek ki 

ölümümüz? 

Ve vardığımız son kenti

kaç uykuya uyuyabileceğiz? 

Bırak toplama artık

geçmiş aşklarının ortalığa saçılmış

boş kovanlarını.

Öylesine bil ki

sensiz de geçebilsin zaman.

Unutma! 

Güler yüzlü ve uysal

her çocuk bir imecedir.

Ve her çocuk geleceğe bilmecedir.

Şimdi sen

tüm yolculuklarını toplasan

kaç tane bana varırsın? 

Ve inan ki 

bana vardığın kadar insansın.

Hayatta en büyük mucize mi, 

bir insanın bir insanı anlaması? 

Peki, neden o zaman

pişirdiğim ekmekleri yemen? 

Ve her gece karanlıkta koynuma girmen? 

Gençliğin neden bu denli benziyor

benim gençliğime? 

Ve neden buluyorum seni

her Galata''ya gidişimde? 

Bu bir sürek avı diyorsun.: 

Peşinde koştuğumuz, 

zaman.

Ama sabaha döndümü yüzümüz, 

hep aynı rüzgar saçlarımızı yalayan

Olmayacak mı diyorsun? 

Öyküne bir virgül de benden; 

kabullenmiyor musun? 

İle de üçüncü tekil mi 

yaşamak istiyorsun? 

Peki öyleyse: 

Ölesiye çağıldarız ama, 

işitemeyeceğimiz bir yerde.

Haydi git sen şimdi! 

Oldu olacak

çoğul yanlızlıklarımızı paylaşalım.

				23.08.1994

				ANKARA', 'Haydi gel seninle şöyle karşı karşıya oturup da konuşalım. Yaşamışlıklarımızı dokundurup anlamlarımızı ve anlamsızlıklarımızı  ortaklaştıral...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/cogul-yanlizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Yolculuk', 'i-stanbul-a-yolculuk-kursat-usalan-tg3rl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ankara’dan Haydarpaşa’ya

Uzun ince yol gider, 

Bir demirden yol gider, 

Bir yaralı yürek gider, 

Bir dosya dolusu şiir gider, 

Ankara’dan Haydarpaşa’ya, 

Bir hayat akıp gider, 

Yarı yolda Eskişehir’e uğrar, 

Garda simit alır, yer

				13.01.2002

				ANKARA', 'Ankara’dan Haydarpaşa’ya Uzun ince yol gider,  Bir demirden yol gider,  Bir yaralı yürek gider,  Bir dosya dolusu şiir gider,  Ankara’dan Ha...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istanbul-a-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuytuda Kanayan', 'kuytuda-kanayan-kursat-usalan-a1ux8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah karam! 

Ah güzelim! 

Ah sevdiğim! 

Nasıl da yabana atılmışlığımız var.

Nasıl ürkek buluşmalarda saklı dokunuşlarımız.

Nasıl ölü toprağı serpilmiş çığlık çığlığa sevişmelerimiz.

Ah karam! 

Ah güzelim! 

Ah sevdiğim! 

Yıllar nerede şimdi bizden habersiz? 

Bir bardak şaraba gömdün gözlerini, 

Yurdundan uzak yolcular gibi sitemlerin.

Bilirsin, divaneyim.

Ne olur bende kalsın bu gece

Yedi renge batırdığın tarihin.

Ah karam! 

Ah güzelim! 

Ah sevdiğim! 

Nasıl da mezesiz yudumladık yaşamı

Ve yaşam nasıl  dörtnala çiğnedi düş bildiklerimizi

Peki bugün nasıl biter sevdiğim? 

Hangi kuytuda yok oluruz saatin birinde? 

Eğer sen de gideceksen bir gündoğumuyla

Ne olur son yıldız  karışmadan gün mavisine

Bir soluk da ben bırakayım yorgun tenine

Sonra beni bulduğun sabah tazeliğinde

O yalınayak, salya-sümük çocuk güzellimle

Beni tükenmez yolculuklara sal öyle git

				03.08.1994

				SİDE', 'Ah karam!  Ah güzelim!  Ah sevdiğim!  Nasıl da yabana atılmışlığımız var. Nasıl ürkek buluşmalarda saklı dokunuşlarımız. Nasıl ölü toprağı s...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kuytuda-kanayan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lades', 'lades-kursat-usalan-fgz35', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O, en deniz

O, en çığlık…

Geçer miyim gözlerinden? 

Bir düş kuruveririm, olur biter; 

hiç kurulmamış gibi.

Okşarsın saçlarımı: Yangın.

Ellerin yanar.

Yanar da 

yine okşarsın bile bile.

Gözlerini yakar gece

Gece olur bile bile

O, en deniz

O, en çığlık…

Gider misin? 

Gitmezsin be! 

Seversin yine bile bile

17.08.1994

ANKARA', 'O, en deniz O, en çığlık… Geçer miyim gözlerinden?  Bir düş kuruveririm, olur biter;  hiç kurulmamış gibi. Okşarsın saçlarımı: Yangın. Eller...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/lades-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceviz', 'ceviz-kursat-usalan-4y72o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O bana ceviz verdi 

Ben ona taviz

Böylece tanıştık

O bana şehvet verdi

Ben ona rüşvet

Böylece seviştik

O bana tüzük verdi 

Ben ona yüzük

Böylece evlendik

O bana çocuk verdi

Ben ona çocuk

Böylece çoğaldık

O bana acı verdi

Ben ona sancı

Böylece yaşlandık

O bana “ergeç” dedi

Ben ona “ çok geç”

Bitiremeden öldük

15.11.1994

TAVŞANLI', 'O bana ceviz verdi  Ben ona taviz Böylece tanıştık O bana şehvet verdi Ben ona rüşvet Böylece seviştik O bana tüzük verdi  Ben ona yüzük Böy...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ceviz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-kursat-usalan-osrdy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eski bir kış gecesinde seni aradım sanırım.

Kilim motifli, konyak kokulu  kahvede yoktun.

Halbuki biz oradaydık, şarkı söylüyorduk.

Kapı camı buğuluydu, pencere buğuluydu.

Dışarıda kar yağıyordu; 

yeni yıl geliyordu, yılbaşı şarkıları söylüyorduk.

Deli gibi konyak içiyor, büyümeye çalışıyorduk.

Aşkı öğreniyorduk; sen yoktun.

Soğuk kapı her açıldığında sobanın başındaydık; 

ısınıyorduk.

Her seferinde bir yabancı geliyordu; 

hiç birisi sen değildin.

Saat onikiye geldiğinde ağlıyorduk.

Çünkü sarhoş olmuştuk, aşık olmuştuk.

Kaçmayı, buralardan  gitmeyi düşlüyorduk; 

onun için de evlerimize dönemiyorduk.

Saat onikiyi geçmişti.

Sırılsıklam aşıktık; kime bilmiyorduk.

Çünkü sen yoktun,  hiç gelmemiştin.

Sabaha kar dinecekti, sokaklar konyak kokacaktı, 

Kırmızı gül satan küçük çingeneler saklanacaktı.

Memurlar koşturacaktı kaldırımlar boyu.

Yepyeni bir yıl gelecekti, ilkbahar gelecekti, 

Akdeniz gelecekti, sen gelecektin.

Kahve kapanacak, karlı gecenin aşıkları saklanacaklardı.

Sonra ben, eski bir kış gecesi seni arayacaktım, 

Sen yoktun

Yoksa hiç olmamış mıydın? 

19.12.1995

TAVŞANLI', 'Eski bir kış gecesinde seni aradım sanırım. Kilim motifli, konyak kokulu  kahvede yoktun. Halbuki biz oradaydık, şarkı söylüyorduk. Kapı cam...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-yoktun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Venseremos', 'venseremos-kursat-usalan-q0zvg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğumumdan tutukluyum gardiyan

kapıları açınca irkilmem ondandır, 

Bu pırıl pırıl 

bu gözlerimi kamaştıran ışık  yabancı bana

rüyalarımda yıldızlar kayardı

ay ışığına doğru pervanecikler uçuşurdu

                                                    karanlık gökyüzünde

yok olurlardı bir bir

karanlık hücrem büyür büyürdü soğuk gecede

Nice aydınlık kokan türküler çalınırdı kulağıma 

söylemeye çalışırdım

Gözüm kamaşıyor gardiyan                                                   

biraz izin ver alışayım

yıllardır görmediğim 

yıllardır özlediğim bu ışık

nicedir beklediğim bu sevgili

                                       sarsın beni

Gidiyorum gardiyan

bir latin sesi geliyor şimdi

                                        uzak ülkelerimden

Venseremos

              Venseremos

Sensizliğe paydos

artık

sevgisizliği de

27.07.1989', 'Doğumumdan tutukluyum gardiyan kapıları açınca irkilmem ondandır,  Bu pırıl pırıl  bu gözlerimi kamaştıran ışık  yabancı bana rüyalarımda yı...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/venseremos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor gelir', 'zor-gelir-emrah-tas-8pklo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zor Gelir

    

       Soğuk, kaskatı bir gecede

      Hayallerimi anlatmak istediğimde

      Ölüm ansızın geldiğinde

      Yaşamak zor gelir insana

       Gelip geçer tren sesleri

       Bitmiyor şu garibin hain geceleri

       Seni sevdiğini söylediği heceleri

       Anlamak zor gelir insana

       Her anında seni düşünürken

       Her gece seni düşlerken

       Gözünü döküp ağlarken

       Gülmek zor gelir insana

        Hayatına girdiğin günden

        Gözünden akan selden

        Ve deli gibi sevdiğinden

        Sevilmeden

        Sevmek zor gelir insana', 'Zor Gelir             Soğuk, kaskatı bir gecede       Hayallerimi anlatmak istediğimde       Ölüm ansızın geldiğinde       Yaşamak zor gelir...', ARRAY['Türk Edebiyatı','Şiir','Emrah Taş']::text[], 8.5, '{"poet":"Emrah Taş","poet_slug":"emrah-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zor-gelir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Behçet', 'behcet-haydar-ergulen-08mou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte ''yağmur dindi''; iki yaz arasına

yokluğu bıraktılar, senin o ağustos

sesini gölgeye değil, külünü aramıza...

''Yağmur dindi'', unutulmaya hazırlanan ne

varsa temmuz gibi tutuşuyor aklımda; 

yarısı o güneşli sesinin tozuyla hala

ürpertili bir yaz hışırtısına takılmış

alymışsekizlik plakta, yarısı kül aklımda! 

Ah, kül razı değil de kul razı, sesinin

dolaylarından alınma bu yanık havaya, 

bir bulut kaynıyor temmuz göğünden

gözümüzde ''yağmur dindi'', yangınsa daha...

''Yağmur dindi'' şairim, tabip değil misin

sen akıl ver bana: Bu acı hangi

arkadaşlığın gölgesine çekilir şimdi, 

ve hangi şiire sığar külün kimsesizliği? 

''Yağmur dindi'' ve sen üstlendin yine

kardeşiyle kül olan bir ülkenin sessizliğini, 

bir elem doktoru üstlenirdi bu acıyı elbet: 

iyisiniz değil mi ruh verdiği şiirler? 

Bir adın Safa''ymış meğer, güldün mü Behçet?', 'İşte ''yağmur dindi''; iki yaz arasına yokluğu bıraktılar, senin o ağustos sesini gölgeye değil, külünü aramıza... ''Yağmur dindi'', unutulmaya ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/behcet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-sair-musturk-dqp1l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çift serçe kanadıdır senin ellerin

Bıraksam uçacak diye 

Tutsam kırılacagından

Korkarım

Yine sığmadı dar vakitlere

Elveda demesi

En zor şeydi teninin kokusunu aldıgımda

Dönüp gitmesi

Minicik ellerin

Kaydıgında avuclarımın arasından

Son bakışın miras kalır bana

Ayrılırken ardırdan', 'Bir çift serçe kanadıdır senin ellerin Bıraksam uçacak diye  Tutsam kırılacagından Korkarım Yine sığmadı dar vakitlere Elveda demesi En zor ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustürk']::text[], 8.5, '{"poet":"Şair Mustürk","poet_slug":"sair-musturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellerin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Aramızda Birşey Var', 'seninle-aramizda-birsey-var-hakki-hakan-kaya-pdp85', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklımdasın hep hiç çıkmıyorsun, 

Seninle aramızda bir şey var.

Yorgun ve üzgünsün, ağlıyorsun, 

Seninle aramızda bir şey var.

Derya, çağlayan suya doymaz, 

Seven gönül yalnız kalmaz, 

Ateş bile boşuna yanmaz, 

Seninle aramızda bir şey var.

Kalmadı mecalim, ümidim soldu, 

Rüzgar sesini bana duyurdu, 

Ayrılık miadım sonunda doldu, 

Seninle aramızda bir şey var.

Ellerim her akşam saçlarını arar, 

Gözlerim karanlıkta boşluğu yarar, 

Bedenimi soğuk bir ürperti sarar, 

Seninle aramızda bir şey var.

Ay yüzlüm geceler göstermesede yüzünü, 

Ateş böcekleri belli eder izini, 

Kavuşuruz birgün sen tut sözünü, 

Seninle aramızda bir şey var.', 'Aklımdasın hep hiç çıkmıyorsun,  Seninle aramızda bir şey var. Yorgun ve üzgünsün, ağlıyorsun,  Seninle aramızda bir şey var. Derya, çağlaya...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seninle-aramizda-birsey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümsüz Aşk', 'olumsuz-ask-hakki-hakan-kaya-naiyd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her nereye gidersem gideyim, 

Her nerede olursam olayım, 

Yıldızlara baktığımda, 

Seninde baktığını bileceğim.

Ve her kiminle gülersem güleyim, 

Her kiminle ağlarsam ağlayayım, 

Ömrümün sonuna dek, 

Yine seni seveceğim.', 'Her nereye gidersem gideyim,  Her nerede olursam olayım,  Yıldızlara baktığımda,  Seninde baktığını bileceğim. Ve her kiminle gülersem güley...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olumsuz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Baştan', 'yeni-bastan-melih-cevdet-anday-6hb9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tam üç ay hasta yattım, 

      kendimi bilmeden

      ve şehrin sokaklarını, 

      tavlada dübeş kapısını unuttum.

      sevdiğim kızın yüzünü.

      şimdi ne güzel, yeni baştan

      yürümeye ve sevmeye başlamak!', 'Tam üç ay hasta yattım,        kendimi bilmeden       ve şehrin sokaklarını,        tavlada dübeş kapısını unuttum.       sevdiğim kızın yüz...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih-cevdet-anday","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yeni-bastan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koku', 'koku-necati-polat-yzvqa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte pislik. Ten kuruyor aklını 

Savralarla. Bilmenin deşildiği yer bumbarlardan

bu kendine dönen kötülük, hunharlara

başkalarından yapılmaktır çünkü ilk

ilk tükrük. Saçılış kapıyor odalarını, odalarda

dışarı çıktığınız her vakitte pharmakon

dayadığınız birşeyler her ebedi cerahatte

size sevgilim dedim, irinlerle doydunuz damarımdan.

Buna çok duygulandım, burnumu da sildiniz

geğirti

olarak girdim hayatınıza, ayaklarımla.

Sevgilim bu koku, ciğerlerinizdeki.

(1988)', 'İşte pislik. Ten kuruyor aklını  Savralarla. Bilmenin deşildiği yer bumbarlardan bu kendine dönen kötülük, hunharlara başkalarından yapılmak...', ARRAY['Türk Edebiyatı','Şiir','Necati Polat']::text[], 8.5, '{"poet":"Necati Polat","poet_slug":"necati-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koku-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar...', 'aksamlar-ozgur-gursoy-nl1fy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şimdi bu zindan karası akşamlar oldu yarim sensiz sevgisiz.

hadi bu akşam çok fazla sev beni yürekliysen..., 

ben şimdi sensiz ağlamaklı bi çocuk gibi sadece ve hala seni bekliyorum...gelebilirsen...

ama bu akşamlar yani sevdiğini söylesen

ranklerine hasret kaldığım bi akşam üstü aşktı benim...

anlatabilsem...

anlayabilsen...', 'şimdi bu zindan karası akşamlar oldu yarim sensiz sevgisiz. hadi bu akşam çok fazla sev beni yürekliysen...,  ben şimdi sensiz ağlamaklı bi ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Gürsoy']::text[], 8.5, '{"poet":"Özgür Gürsoy","poet_slug":"ozgur-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aksamlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti...', 'bitti-ozgur-gursoy-3iv83', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'herşey bitti...

dağlar karanlık meydanlar boşaldı şimdi..

uzun yollar var şimdi yürekte

yürümeyle aşınmayan yollar...

ama en kötüsüde kaybetmek seni...

ve bitti...

artık sadece sardunyaların açmasını bekliyorum, 

tüm renklere inat penceremde, 

ki sensiz onunda tadı yok ya şarkıların

ben hala o eski şarkıları söylüyorum

hatırladıklarımı ki 

onlarda çoktan unutuldu yürekte

ama en kötüsüde kaybetmek seni

ve bitti...', 'herşey bitti... dağlar karanlık meydanlar boşaldı şimdi.. uzun yollar var şimdi yürekte yürümeyle aşınmayan yollar... ama en kötüsüde kaybet...', ARRAY['Türk Edebiyatı','Şiir','Özgür Gürsoy']::text[], 8.5, '{"poet":"Özgür Gürsoy","poet_slug":"ozgur-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bitti-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazlık Ruhum', 'sazlik-ruhum-ozgur-hatem-1ee9t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalkıp gitmek geliyor içimden, 

(Gözlerine bakınca...) 

Duruyorum olmuyor! 

(Bir ateş dağlıyor yüreğimi, usulca) 

İçinden, 

Bütün umarsızlıkları ayıkladım, 

sazlık ruhumun; 

Sular kaldı, gözlerine benzeyen

Kuşlar kaldı, göçüp giden

Geri dönen, 

Sık sık ölen...

Bir çığlık oluyor akşamları sensizlik

Kalkıyorum...gidemiyorum...ölüyorum, yeniden

Yeniden yok olurken dirilen ben, 

Sazlık ruhumda ki kuşlarla beraber, 

Göçüyorum gözlerinden.

Bir sen kalıyorsun, mavilerinle beraber

Suskunluğun kalıyor

İnce parmakların ve türkülerin kalıyor

Kuşları özlüyorsun, 

Bir ateş oluyor bakışlarında ki özlem, 

Sazlık ruhumu dağlıyorsun...

Uyanmak istemediğin bir düş oluyor, 

Yoldan gelenler, 

Gelenler, 

Ve, 

Bir daha gitmeyenler...

Giriyorsun eşikten usulca, 

Kuşlar omuzunda, 

Türküler parmaklarının ucunda, 

Har yanın mavi...

Kalkıyorum...duruyorum...gidemiyorum! 

Ateşten gömlek oluyor ruhum, 

Tam ölürken, 

Diriliyorum

(Ağustos/2002 Mersin)', 'Kalkıp gitmek geliyor içimden,  (Gözlerine bakınca...)  Duruyorum olmuyor!  (Bir ateş dağlıyor yüreğimi, usulca)  İçinden,  Bütün umarsızlık...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sazlik-ruhum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-ozgur-hatem-uuvqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu benim mitolojim, 

Tarihim, 

Hikayem...

Tanrının yarattığı sihir, 

Benim yüreğimin! 

Büyücü; 

Hücrelerimi kattı tozların arasına, 

Adımı üfledi, üç kez usulca...

Tanrının gözyaşlarını kattığı, benim bedenim! 

Büyü, 

Aslında, 

Ben''im...

Sen uyuyordun.

Aslında, 

Sen uyurken, büyüyor gece.

Ben, bir başka dağın eteğinde, 

Büyüyen geceye, ruhumu üflüyordum.

Şimdi

Gece 

Ben''im...

Büyüyen gece, aylanıyor.

Rengi, bu kez mavi.

Yer

Gök

Düş mavi...

Mavi büyünün rengi.

Şimdi, 

Büyücü, 

Ben''im...

Gece, gündüze kesiyor.

Mavi ay, mavi güne bırakıyor rengini.

Uyanıyorsun, 

Göğsünde, üç damla mavi yaş.

Eşikte, kırmızı karanfiller

Uzanıyorsun...dokunamıyorsun

Gördüğün düş, 

Ben''im...

Koşuyorsun düşün peşi sıra, 

Mavi yolda, 

Mavi ruha...

Büyüye bedel, benim yüreğim

Göğsünde ki, üç damla mavi yaş, 

Ben''im...

Büyü, 

Sihrini üflüyor sana.

Deniz kızı, denizine

Yağmur, bulutuna

Ben, sana dönüyorum...

Her yer düş oluyor

Büyü, 

Sevince kesiyor, usulca...

(Ağustos/2002 Mersin)', 'Bu benim mitolojim,  Tarihim,  Hikayem... Tanrının yarattığı sihir,  Benim yüreğimin!  Büyücü;  Hücrelerimi kattı tozların arasına,  Adımı ü...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/buyu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaldız', 'yaldiz-refik-recep-pelit-4nora', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üzerimizde bir yığın toprakla uyuyorken biz, 

Elinde çiçeklerle üstümüzde dans ediyor bir kız, 

Gökyüzünde asılı duran benim dediğim yıldız 

Göçtü çoktan, çıktı boyası, kaldı sahte bir yaldız.', 'Üzerimizde bir yığın toprakla uyuyorken biz,  Elinde çiçeklerle üstümüzde dans ediyor bir kız,  Gökyüzünde asılı duran benim dediğim yıldız ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaldiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Salih''im SALİH', 'ben-salih-im-sali-h-salih-ozalasan-ohz3o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhum zindanda bir mahkum

Sanki ben hücre hapsi çekiyorum

Olmamıştı bugüne kadar hiç korkum

Oysa şimdi kendimden bile korkuyorum

Korkuyorum aynalara bakmaktan

Baksam acaba bu benmiyim diyorum

Yoksa ben kafayımı yedim bu yaşta

Gözlerimin içindeki gülüşleri artık göremiyorum

Herkes herşeyi bana yakıştırıyor

Ya meğer ben neymişim bilemiyorum

Kimse inanmıyor boşa ne söylesem

Ben Salih''im SALİH başka şey diyemiyorum

Küçük şeyleri abartılı yazan

Tatlı sitemlere dahi bazen kızan

Zaman geldiğinde hakaretlere susan

Bazen bir kara sevdalı gibi yazan

Bazen insana düşmanını aratan

Her kılıkta her şartta sadece yazan

Elinde yanlız bir kalemi

Önünde boş bir sayfası daima bulunan

Bu iki şeyden başka hiç bir şeyi olmayan

Vazgeçemediği kalemi ve sayfası uğruna

Artık tek dostuda kalmayan

Ben Salih''im SALİH gerisi hep yalan

Y.Tarihi 26-08-2002 Saat 14.10', 'Ruhum zindanda bir mahkum Sanki ben hücre hapsi çekiyorum Olmamıştı bugüne kadar hiç korkum Oysa şimdi kendimden bile korkuyorum Korkuyorum ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-salih-im-salih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-erhan-sesli-8pbd4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşün ki bir sabah uyandın

Ola ki kalbin bir başka çarpıyor

Başında hafif bir ağrı

Kulağın çın çın ötüyor

Kuvvetle muhtemeldir ki o zaman ben seni düşünüyorum...

Öylesine aklıma gelivermişçesine, 

Öylesine yalandan 

Düşün ki yürüyorsun sahilde, ay ışıl ışıl

Ola ki bir balıkçı teknesi geçiyor uzaktan

Yakamoz vurmuş yüzüne, gülüyorsun

Hafif bir esinti yalıyor saçlarını bir şeyler fısıldayaraktan

Bir anda ürperiyorsun

Kuvvetle muhtemel ki işte o zaman ben seni düşünüyorum

Öylesine bir şeyler geçiriyorum içimden

Öylesine bir şeyler söylüyorum...

Düşün ki sebepsiz bir sıkıntı var içinde

Ola ki sokak köpekleri havlıyor durmadan

Yatağında dönüp duruyorsun

Ne varsa aklına takılan

Unutuyorsun

Kuvvetle muhtemeldir ki işte o zaman ben seni düşünüyorum

Ereğli, 2001', 'Düşün ki bir sabah uyandın Ola ki kalbin bir başka çarpıyor Başında hafif bir ağrı Kulağın çın çın ötüyor Kuvvetle muhtemeldir ki o zaman be...', ARRAY['Türk Edebiyatı','Şiir','Erhan Sesli']::text[], 8.5, '{"poet":"Erhan Sesli","poet_slug":"erhan-sesli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-dusunmek-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çam Ağacı', 'cam-agaci-i-brahim-tezol-rz0c8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇAM AĞACI

Düşler soğuk, gündüzler donuk, gülüşler boğuk

Bu gurbetin kışıda yazıda soğuk

Zira beynimdeki gurbet; bu koca dünya

Kendi filmini seyrettiğin bir loca dünya

Filmin sonu başından belli

Uzunluğu ha kırk olmuş ha elli

Bense dünyada yalçın dağdaki çam ağacıyım

Cinnetin her gece gölgelendiği gam ağacıyım

Ve etrafta ağaçta yok benden başka

Ozaman kaldır kadehini güneş, içelim aşka

Heygidi rüzgar bari sen okşa saçımı

Hiç düşünmüyormusun; bu ağaç mutluluğa açmı? 

Hey yolcu nereye gidiyorsun bir selam yokmu? 

Gel gölgemede anlat, sende hiç gam okmu? 

Bu yolcuda gitti belliki işi acele

Yalnızlık üç hece; hecele babam hecele

Ey akşam üstü serinliğindeki pembe güneş

Em artık içimdeki karanlığı em be güneş

Zira karanlık içimde kendini bulmuş

İstanbul sadece masallarda İstanbul’muş

Baykuş yuvasında bülbül sesi duyulmazki

Baykuşun ninnisiyle geceleri uyunulmazki

Hani yoktu çam ağacının lugatında yaprak dökümü? 

Ey gönül bak, senin kışında yazında yaprak dökümü

Ey bana kucağını açan yalçın dağ 

Köroğlu’na ocağını açan yalçın dağ

Şöyle dik dur göğe doğru yükselt başını

Yıldızlarda  arayayım kara gözün kara kaşını

Sonra nebileim üfle beni mehtaba 

Artık sığamıyorum yalnızlık adlı kitaba

Sıkma canını kara toprak yağmur yağar elbet 

Benimde gölgemde bir tomurcuk doğar elbet

İşte benim hayatım kendi kendini teselli etmek

Zifiri karanlıkta kibrit çakıp, kendini seyretmek 

Bir kara bulut sanki benim yörüngem 

Elinden gelse beni teredecek gölgem.', 'ÇAM AĞACI Düşler soğuk, gündüzler donuk, gülüşler boğuk Bu gurbetin kışıda yazıda soğuk Zira beynimdeki gurbet; bu koca dünya Kendi filmini ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/cam-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşden gelen musiki', 'gunesden-gelen-musiki-i-brahim-tezol-pbiaf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşten Gelen Musiki

Bir akşam üstü serinliği; rüzgar ağaçları okşuyor 

Benim deli dönül gözü kapamış güneşe doğru koşuyor

Bağrını açıyor toprak güneşten düşen pembeliğe 

Gebeliğe hazırlanıyor gece birbaşka gebeliğe

Bakalım negelecek gecenin kucağından 

Belkide bir fasıl kimsesizler bucağından

Güneş doğduğu yere elsallayara batıyor

İçindeki aydınlığı mehtaba yollayarak batıyor

Günüşteki bu batışı izleyen daha bahtiyar deryada

Sanki güneşi kollarını açmış bekliyor bir yar deryada

Ve güneşten gelen yansıma bölüyor denizi ortadan ikiye

Haydi güneş, haydi deniz zamanın deminde musikiye

Güneş musikiyle  gülüyor tabiata, tabiat pür dikkat

İnsanda ki sahte gülüşe inat, işte  gülüşteki hakikat

Oana bütün güzellikler tıkışmak istiyor

Güneş denizin üzerinden benimle el sıkışmak istiyor

İşte uzatıyorum elimi haydi götür beni sonsuza

Elveda dünya ben gidiyorum, gönder kefeni sonsuza', 'Güneşten Gelen Musiki Bir akşam üstü serinliği; rüzgar ağaçları okşuyor  Benim deli dönül gözü kapamış güneşe doğru koşuyor Bağrını açıyor t...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gunesden-gelen-musiki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçti Gitti', 'gecti-gitti-i-brahim-tezol-e7m52', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GEÇTİ GİTTİ

Evet gecem yine bitti

Ölüme iter gibi beni uykuya itti        

Sırma saçlı bir kadın gibi

El  salladı ve gitti

Bense saati kurdum uyumadan 

Beni kuransa; Yaradan

Dünyadan hiçbirşey anlamadan 

Yirmiiki sene geçti gitti', 'GEÇTİ GİTTİ Evet gecem yine bitti Ölüme iter gibi beni uykuya itti         Sırma saçlı bir kadın gibi El  salladı ve gitti Bense saati kurdu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecti-gitti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize gelen misafir', 'denize-gelen-misafir-i-brahim-tezol-wdbgm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DENİZE GELEN MİSAFİR

Aylardan sonra misafir geldim sana 

Korkma biz misafiriz ne bulursak yeriz 

Keşke dile gelsende “hoşgeldin senin yarana 

Biz mehem oluruz” desen ya deniz

Allah’ım ne güzelde yaratmış 

Şu karşımda oynaşan denizi

Ama yalnızlık ruhumu bir kere karartmış

Kirini temileyemez istanbul’un denizi

Sadece bir kaya giriyor denizle arama

Derin bir nefes çeksem deniz içime dolacak

Dalgalarla birlikte kanayan yarama 

Acaba kim nasıl merhem olacak

İsterdim ki; denizin içinde özgür, 

Sadece yüzmeyi düşünen bir balık olmak 

Saçları uzun, selvi boylu, gözleri kömür

Başka bir balık ile denizin dibinde solmak

Böylece sadece yüzerdim 

İstanbul’un denizinde asice

Bazende zıplayıp şehri süzerdim 

Benim gibi içi çürüyenleri, sessiz ve gizlice

Ama ben kayalıklara uzanmış yatıyorum 

Denizse karşımda dalgalarıyla yatıyor

Senin dalgaların var diyorum

Benimse kayalarım, hep sırtıma batıyor

Nazım’ın ise ruhunu hapse kapamışlar 

Zaman nasıl olduysa geçmiş ahile

Ona duvarlar konuşmamış, bana ise kayalar 

Benim ruhumu ise kapattılar; Bayramoğlu Sahile

Kayalar konuşmasada ben onları anlıyorum ey deniz

Hissediyorum diyorlarki dalgalar ve biz

Birer kardeştik anlaşıyorduk mutlu ve sessiz

Gelmeden önce çok daha mutluyduk biz sensiz

Ozaman gidelim buralardan işte avucumu açtım

Haydi dol avucuma ve gidelim nereye gideceğimizi bilmeden

Ben zaten ruhumun elinden sana kaçtım 

Aceleyle gidelim ki, yalnızlık beni defterden silmeden', 'DENİZE GELEN MİSAFİR Aylardan sonra misafir geldim sana  Korkma biz misafiriz ne bulursak yeriz  Keşke dile gelsende “hoşgeldin senin yarana...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/denize-gelen-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orkide', 'orkide-i-brahim-tezol-qasve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orkide

Tüm hissiyatımı kaybettim 

Herşey  okadar boşki

Sanki kimsesizliğe müheppetim 

Ruhum öylesine sarhoşki

Kimbilir, hayat yeni başlıyor belkide 

Belkide bir ışık karanlığıma gizlenecek

Belkide yeni yeni olmuş bir orkide 

K üçücük dünyama filiznecek', 'Orkide Tüm hissiyatımı kaybettim  Herşey  okadar boşki Sanki kimsesizliğe müheppetim  Ruhum öylesine sarhoşki Kimbilir, hayat yeni başlıyor ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/orkide-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portrem', 'portrem-i-brahim-tezol-ywdzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'PORTREM

Bir gece daha çığlığında sukutun

Duygularımı Karacaahmet’tekilere okutun

Hergün biraz daha kaybediyorum kudretimi

Geceler seyrettikçe   ürperiyor suretimi

Lugatta yok kelime halimi anlayacak

Bir çift göz daha yokmu beninle ağlayacak? 

Ey yanlızlık ne olur birazda şu duvarı erit

Benim istediğim gönül ateşi için bir kibrit

Gözün karasını gören anlamazki amadan

Ruhum her gece açılıyor diktiğim yamadan 

Sabah kalk hep aynı, kuşlar aynı, aynı martılar 

Ruhların habersiz kemikten karaltılar 

Karaltılar içinde en mutsuzu benim 

Artık ruhuna ağı geliyor bedenim

Herkes yalanından habersiz doğrusundan emin 

Bense çok çok uzağım menzilin gayemin

Çölde ki   en yalnız kum tanesiyim 

Dibini aydınlatmaktan aciz mum tanesiyim', 'PORTREM Bir gece daha çığlığında sukutun Duygularımı Karacaahmet’tekilere okutun Hergün biraz daha kaybediyorum kudretimi Geceler seyrettikç...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tezol']::text[], 8.5, '{"poet":"İbrahim Tezol","poet_slug":"i-brahim-tezol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/portrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmayana', 'unutulmayana-sair-suphi-v6noc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykirdin acini bir solukta

Saldin yalcin ucurumlara

Yureksizlerin ortasinda

Can havliyle ruzgarlarla

Nami surgunlerde adaletin

Surgun edildi bedenin

Kelepcelerde dag yuregin

Ay neyleyim dayanamaz yuregin

Genclerin var gelecekte

Sarkilarinin daglarinda

Daglarin doruklarinda

Yalanin aºilasi yollarinda

Isyanin bir solukta

Sazinin her telinde

Kavganin her deminde

Olumun soguk nefesinde

Zulanda bir nefes canin

Satmadin askini onurlu yasamin

Bembeyaz bir sayfa karanliklar icinde

Ak mi kara mi dusune dursunlar

Tel telde olsa kirpiklerin

Aglama yuregim, sakin de

Dusecek mi sandin gozum

Sazin ellerimizden', 'Haykirdin acini bir solukta Saldin yalcin ucurumlara Yureksizlerin ortasinda Can havliyle ruzgarlarla Nami surgunlerde adaletin Surgun edild...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutulmayana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin Maşkalı', 'atesin-maskali-sair-suphi-owkon', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ateşin Maşkalı 

Merhaba Fırat''ın asi çocuğu

Hoşça kal ''gözüm'' demeyeceğim sana

O kocaman yüreğini kim durdurabilir

Söyler misin Tanrı aşkına

Bir daha hangi ana doğuracak seni

Hezil çayının çığlık sesi

Kavalısın çobanın, 

Beydağı''nın yelisin, 

Güvercinin kanadı, 

Özgürlüğe süzülüşün kelebeğin

Ateşin maşkalısın

Ey!    bre Ahmet!', 'Ateşin Maşkalı  Merhaba Fırat''ın asi çocuğu Hoşça kal ''gözüm'' demeyeceğim sana O kocaman yüreğini kim durdurabilir Söyler misin Tanrı aşkına...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/atesin-maskali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Kaldım', 'cok-gec-kaldim-sair-suphi-q0aiy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece ağırlaşarak üstüme yıkılıyor

öldüm sanıyorum

beni bu saatte uyanık tutan şarkılar birazdan

odanın içinde yavaş yavaş kaybolup gidecek

puslu bir hava dört duvarı dolanıp

doğru çıkacak  balkona

masada unutulmuş kitabın sayfaları  hep açık

harfler sözcükler  kendini tekrar ediyor

aynı dizeleri kurup duruyor durmadan

ölüm çıkıyor   her şiirin üstünü kazıdığımda

omzumdan çocukluğum bana bakıyor

aklımda kalanları hatırlamaya çalışıyorum

geceleyin odam pencerelerini üstüme kapatıyor ne varsa

balkon kapısı çarpıp duruyor ömrüme

yabancı  ne varsa dağılıyor odaya

ben bir tek hayatı anlamıyorum ölüm neyse

o da odur demeye  nedense dilim varmıyor

terimi  ıslak bir mendille siliyorum dünya

bundan sonra naklen bir savaştan başkası hiç değil

şiir geri çekiliyor harfleri  dağılıyor alfabenin

hiçbiri yerli yerinde durmuyor her şey baştan

başa ölüm kokuyor üstüme fesleğen dalları atıyorum

destimin suyunu bu kez ben dolduruyorum

mezarımın bakacağı yönü belirliyorum

her şey üst üste  yığılsın dursun

ne çıkar bundan

birini aramadıysam adını anmadıysam

mektup yazmadıysam telefon açmadıysam güz

muhitimize çoktan gelmiştir ve hiçbir zaman gitmez

sararmış bir hayatı dökülürcesine yaşadım durdum

yaşadığım kent her geçen gün daha fazla mezarlığa benzedi

apartmanlar mezar taşı  balkonlar çok oldu

çiçek saksıları yıllar var ki sulanmadı ben anladım

ölüm gitsin diye hayata seferler düzenledim

gecenin en derin yerine kendimi bıraktım

kimse çıkarmadı

geriye ölümden başka ne kaldı

bu soruyu sormak için çok geç kaldım

çok geç kaldım bundan epeyidir benim bile haberim yok!', 'gece ağırlaşarak üstüme yıkılıyor öldüm sanıyorum beni bu saatte uyanık tutan şarkılar birazdan odanın içinde yavaş yavaş kaybolup gidecek p...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/cok-gec-kaldim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis Barikatı', 'nergis-barikati-sair-suphi-56xc9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sokaklar taşımıyor ağırlığımı

yokluğunuzun yükü omuzlarımda

iki hasret yumrusu gözlerim içe dönük

ustura gibi gergin ellerim kollarımda

su kadar kıyıcıydınız su kadar mülayim

gençlik kapısız kafeste kuştur, gençtiniz

elleriniz kargılı çıktınız mitoslardan

civanmert yüreklerle gökdepremler geçtiniz

gönülleriniz kavi aşklar silüetiydi

ölümü batan günle inilen bir mezra bellerdiniz

bölüp fetretini en derin suskunluğun

üşüdükçe üstünüze şafaklar çekerdiniz

mağrurdunuz gergin kanatlı kartallar kadar

dingin su nilüferleri gibi uslu değildiniz ah

iki yüzüydünüz dağın beyaz gecede

nergis barikatıydınız kazanılan her sabah

bahadır yerlerindeydiniz söylencelerin

denginizde amansız takiplerin belası

ipek yollarında esmer izdüşümlerle

kaşlarınız kapkara bitişirdi masalsı

nicedir tok kalktığım yok sofralardan

gittiniz ekmeğin tuzu gitti sizinle

uykularım alev-ateş düşlerim yanıkara

pusuya mı düştünüz yastığımda bu kan ne?', 'sokaklar taşımıyor ağırlığımı yokluğunuzun yükü omuzlarımda iki hasret yumrusu gözlerim içe dönük ustura gibi gergin ellerim kollarımda su k...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nergis-barikati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misket', 'misket-duygu-yalcin-gs3b7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk küçükken oynadığımız misket oyununa benzer

İki kaybedip beş kazanırsın

Ne kadar uzaktan vurursan o kadar adın duyulur

Eve heyecanla koşarsın

''''Anne mahallede birinci oldum bak kazandıklarıma! ''''

Annen seni duymaz misketlerini umursamaz bile

''''Ne bu üstün başın kir pas içinde daha yeni yıkadım! ''''

Ve hayallerin yıkılır...

Sen ''''Aferin benim oğluma'''' beklerken bir posta azar işitir suçlu olursun

Zaten hiç yaranamazsın ki karşındakine...

Bundan sonra ne misketi heyecanla oynarsın ne de elindekilerinin kıymetini bilirsin

Bir misket kazanır onlarca kaybedersin üzülmezsin

Onlarca misket kazanıp bir tane bile kaybetmezsin sevinmezsin...

Büyüyünce bu misket oyununu aşka çevirirsin

Ne aşklarına değer verirsin ne de aşk nedir bilirsin

Sadece aşk başlığı altında yalan duygular yaşayıp gidersin

Çocukluğunu hatırlayıp ''''Ne misket oynardım be'''' dedikten sonra hep hüzünlenirsin

Tıpkı şimdi kaybettiğin aşkların boşa giden duyguların arkasından yaptığın gibi...

temmuz2001 / istanbul', 'Aşk küçükken oynadığımız misket oyununa benzer İki kaybedip beş kazanırsın Ne kadar uzaktan vurursan o kadar adın duyulur Eve heyecanla koşa...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/misket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karda Işıltılar', 'karda-isiltilar-sair-suphi-6po0c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece yağmaya başlayan kardan mı nedir? 

Saklamak zorunda olduğum kocaman bir sevinç varmış gibi 

Çok güzel şeyler söyleyecekmişim de 

Söyleyemiyormuşum gibi dolu dolu yüreğim. 

İnsanca bir gülümsemeye rastladım 

Hıdrellez günlerinde salıncaklarda sallanan insanların 

Gönülleri kadar hafif. 

Baloncunun peşinden koşan çocuk yüreği gibi sevdalı 

Al, yeşil, sarı salonlarımız olsun. N''olur diyen 

Bağlara gidelim 

Asma çardaklarda yatalım gecelerde 

İsteyen sabahlasın, istediği kitapla 

İncir, üzüm, nar, şeftali 

Hepsi hepimizin diyen 

Sevginin dostluğun, arkadaşlığın dışında 

Hiçbir anlama gelmeyen 

İnsanca bir gülümsemeye rastladım 

Merdivende verdiğin sarı kasımpatıyı unutmadım 

Sevdiğim bir şiir kitabına taktım onu 

Karıştı çiçeğin şiirlere. 

Kolunu boynuma doluyorsun otobüste 

Çocuğunu seven bir anne gibi 

Yakınlığımız insanlığımızdan geliyor 

Ne kadar insanlaşırsak 

O kadar arkadaşız.', 'Gece yağmaya başlayan kardan mı nedir?  Saklamak zorunda olduğum kocaman bir sevinç varmış gibi  Çok güzel şeyler söyleyecekmişim de  Söyley...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karda-isiltilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırım Taşları', 'kaldirim-taslari-duygu-yalcin-jlawx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaldırımda yürürken bugün

Gözüm taşlara takıldı

Bir pembe bir gri

Biri yerinde birinin kenarı kırılmış

Hayatımızda bir kaldırım taşı gibi

Bir pembe hayaller kuruyoruz

Bir gerçek olan griye dönüyoruz

Hiçbir zaman yerli yerinde kalamıyoruz

Bir kenarımız hep kırık

Bir yanımız hep ezik

Her gelen kaldırımlarla uğraşıyor

Kırıp yeniden yaptırıyor

Zaten kalbimize girenler onlara özeniyor

Ama renk hiç değişmiyor

Bir pembe bir gri

Biri yerinde diğeri kırık...

ağustos2001 / istanbul', 'Kaldırımda yürürken bugün Gözüm taşlara takıldı Bir pembe bir gri Biri yerinde birinin kenarı kırılmış Hayatımızda bir kaldırım taşı gibi Bi...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaldirim-taslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmak Islatan', 'ahmak-islatan-duygu-yalcin-cdi6s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani yağmur yağdığında bir tek arabaların altı kuru kalır ya

Bende kuru hissettim kendimi senin kolların altında

Ama çekip gidince anladım

Sen olmasan da ıslanmazdım ahmak ıslatanın altında

Şimdi her ahmak ıslatan yağışında

Sen geliyorsun aklıma

Umarım şemsiyesi yanındadır deyip

Üzülüyorum senin adına

aralık2001 / istanbul', 'Hani yağmur yağdığında bir tek arabaların altı kuru kalır ya Bende kuru hissettim kendimi senin kolların altında Ama çekip gidince anladım S...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ahmak-islatan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peynir Mutluluğu', 'peynir-mutlulugu-duygu-yalcin-2junm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani unutulmadın zannediyorsun ya

Yanılıyorsun...

Unutalı o kadar çok oldu ki...

Bakma sen bunları yazdığıma

Sadece sen değil geçen günler de unutuldu

Halbuki geçişleri çok zor olmuştu

Geriye dönüp baktığımda sadece fotoğraf albümleri görüyorum

Hepsinde ufak bir tebessüm

O da ayıp olmasın diye

Bilirsin saçma sapan şeyler söyletirler insanlar gülsün diye

Hadi peynir de şimdi patates vs.

Sende zorla dersin

Ve o anda kulaklarında çınlar deklanşörün sesi

Söylesene resimdeki kimin mutluluğu sence

Benim mi yoksa peynirin mi...

eylül2001 / istanbul', 'Hani unutulmadın zannediyorsun ya Yanılıyorsun... Unutalı o kadar çok oldu ki... Bakma sen bunları yazdığıma Sadece sen değil geçen günler d...', ARRAY['Türk Edebiyatı','Şiir','Duygu Yalçın']::text[], 8.5, '{"poet":"Duygu Yalçın","poet_slug":"duygu-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/peynir-mutlulugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Yabancı', 'merhaba-yabanci-sair-suphi-u4z09', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba Yabancı 



Otur şöyle bir kenara, bir sigara yak 

Anlatmak ister misin bana. 

Belki senin anlatacağın çok şey vardır 

Hayata dair... 

Sevgiler, aşklar, ihanetler, riyakarlıklar 

İstersen anlatma hiç bir şey 

Sessizce öyle kal; 

Sadece bir birimize omuz olalım 

Susmak ta bazen çok şey anlatır 

Sadece rüzgarın sesini dinleyelim 

Bak oda neler anlatıyor 

Yok! hayır sakın bana beni sorma........ 

Ben kendimi anlatamam sana 

Benim evcilleşmiş acılarım var 

Hayatta tek başaramadığım şey bu zaten.... 

Kısa cümleler kurarak konuş 

Uzun cümleler manasız oluyor 

Ne o neden gözlerin doldu....? 

Hadi gel seninle mutluluk oyunu oynayalım 

Biraz hayal kuralım, sonra onları yakıp ısınalım 

Kimsenin keşfedemediği yerde tahta bir evimiz olmuş 

Önünde akan minik bir dere, ufacık şirin bir bahçe 

Bu eve mutsuzluklar hiç uğramasın 

Hadi sen balık tut bende roka toplayayım........ 

Ben dans etmeyi çok severim bilir misin.............? 

Benimle dans eder misin........ 

Bak gördün mü yabancı gözlerin parladı 

Birkaç dakikada nasıl yakaladık mutluluğu 

Oysa birbirimizi tanımıyoruz bile 

Duygularla anlaştık senle 

Burası çok soğudu ben üşüdüm artık 

Hadi vakit doldu; yakalım şimdi bunları evi ısıtalım', 'Merhaba Yabancı  Otur şöyle bir kenara, bir sigara yak  Anlatmak ister misin bana.  Belki senin anlatacağın çok şey vardır  Hayata dair...  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/merhaba-yabanci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yanlızlık', 'yanlizlik-sair-suphi-9soif', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'özlerim seni özledigim kartaneleri gibi  avucumda eridigin gibi yüregimde eritiyorum seni bir demiri kızgıncasına suruyorum bedenime yanlızca dostluk adına bir intikam ama adı sevgi gibi tatlı ama hüzünlü sen dostumsun dostum kal ama nefretle ama kinle nede olsa suyun aktıgı yol  sevgini duragıdır bırak öyle kalsın nedenmi öyle söyledimcünkü senin dostlugunda güvensizlik duydum ama her zaman agzında cıkan tek bir kelime vardı dostumsun ama dostlugun içinde karsılıklı saygısızlık sevgisizlik ve yalan doluydu yani gercek bir dostun attıgı gülden yaralanmadık 

ben hiç tanımadıgın kadar yabancı degil kötülügü ateste yakanların adamıyımseni hiç böyle tanımadımkı kötü degilsin kötülügün içinde yesermiş bir gül  olabilirmisin?', 'özlerim seni özledigim kartaneleri gibi  avucumda eridigin gibi yüregimde eritiyorum seni bir demiri kızgıncasına suruyorum bedenime yanlızc...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yanlizlik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykudaki Dev', 'uykudaki-dev-halil-ozcelik-79bk3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ellerinle sundun bana

Sevgi dolu yüreğini.

Almayan ellerim utansın.

''Seni seviyorum'' Dedin; 

Usanmadan sevdiğini söyledin.

''Ben de seviyorum''

Demeyen dillerim utansın.

Gözlerim utansın, 

Gözlerine bakamadım.

Dizlerim utansın

Önünde diz çökemedim.

İçime gömdüm

Binlerce ''Seni seviyorum''u.

Sana içimi dökemedim.

Yüzlerce kez bu yüreği söküp

Atmak istedim ayaklarının dibine

Cesaret edip sökemedim.

Şimdi ben sana sunuyorum

Yorgun yüreğimi.

İster vur yere dağılsın

Ya da koy yüreğinin yanına, 

Tutuşsun, içinde küllenen kor.

Tutuşsun, alev alev yansın.

Yıllardan sonra

Uykudaki dev uyansın.', 'Sen ellerinle sundun bana Sevgi dolu yüreğini. Almayan ellerim utansın. ''Seni seviyorum'' Dedin;  Usanmadan sevdiğini söyledin. ''Ben de seviy...', ARRAY['Türk Edebiyatı','Şiir','Halil Özçelik']::text[], 8.5, '{"poet":"Halil Özçelik","poet_slug":"halil-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uykudaki-dev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk İşimiz Yaşamak', 'i-lk-i-simiz-yasamak-halil-ozcelik-o5y37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyada çok iş var, 

Yapabilsek diyorum; 

Yapabildiğimiz kadar.

Ama ilk işimiz yaşamak.

Sıkıca sarılıp bu inanca

İnsan gibi yaşamalıyız, 

İnsan gibi insanca.

Yaşamak; en çileli işimiz.

Sonra sevmek; 

Her şeyi, herkesi

Ayırmadan, ayrılmadan sevmek.

Her yerde her zaman, 

Sevgiyi yüreklerde duyarak, 

Gözlerde okuyarak sevmek.

Sevmek; en güzel işimiz.

Ve düşünmek; özgürce.

Zorlamadan, zorlanmadan düşünmek.

Geçmişi bir kez, bugünü iki kez

Ve düşünebildiğimiz kadar

Yarını düşünmek.

Düşünmek; en zor işimiz.

Sonra yine sevmek.

Pirinç ayıklar gibi arayarak sevgiyi, 

Kaygılar üzüntüler arasında.

Sonra yine düşünmek.

Yaşama gölge düşüren ne varsa

Silmek için yeryüzünden.

Ve bir gün; 

Masmavi bir gök yüzü yaratıp, 

Kaygıları en uzaklara atıp, 

Sevgiyle beslediğimiz, 

Güzel düşüncelerle süslediğimiz

En güzel işimiz olmalı yaşamak.', 'Dünyada çok iş var,  Yapabilsek diyorum;  Yapabildiğimiz kadar. Ama ilk işimiz yaşamak. Sıkıca sarılıp bu inanca İnsan gibi yaşamalıyız,  İn...', ARRAY['Türk Edebiyatı','Şiir','Halil Özçelik']::text[], 8.5, '{"poet":"Halil Özçelik","poet_slug":"halil-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ilk-isimiz-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'doguda savas var', 'doguda-savas-var-sair-suphi-b5t3w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'doguda savas var elleri nasırlı yigitler var 

elleri kınalı gelinler kızlar var ama elleri 

nazık hiç olmadı doguda savas var 

silahıyla yatan yigitler var 

dersimde. amed te bingölde.mardınde 

doguda savas var ölümcül bir atom var

bu savasta kaybolanlar var anlamıyormusunuz

ey insanlık savasta insanlar var kardeşlik var

doguda hep zülüm var isyan ve yanlızlık var 

bir vatanda hiç tanınmamıs bir kent var doguda

bu hep var insanlar tanınmaz köle misali

ama doguda bilmeyenler için hep özgürlük var 

yüreklerde ellerde bagımsızlık var türkülerde 

agıt sevdalarda hüzün var ama doguda hep biz

ve sevdalılar var bu kımsenin yasamadıgı dünyada 

güzelik var yasayan  biliyorya doguda 

hep savas var doguda ölüm doguda 

bilmeyenler için özgürlük sevdası 

var savasa selam özgürlüge selam 

doguda savas olsada kardeşlik var

doguda insanlıga özlem var  doguda

hep savas var unutulmus

suskun kentliler var munzur fırat murat asi nehirler var  doguda bu kez kardeşlik var 

yasasın özgürlük adına savasanlara doguda..............?', 'doguda savas var elleri nasırlı yigitler var  elleri kınalı gelinler kızlar var ama elleri  nazık hiç olmadı doguda savas var  silahıyla yat...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/doguda-savas-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-sair-suphi-lqndp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yabancı 

Hangi cennetten geldim bu cehenneme 

Ki her yokluk bendedir, her acı benim 

Baltalar kıyasıya inmiş govdeme 

Bak! Şu devrilen hayat agacı benim 

Bir gün beni de unut her yalan gibi 

Adımı sokaklara tükür kan gibi 

Oysaki yaşadıkça bir çıban gibi 

İçinde sızlayacak o sancı benim 

Terkedilmiş eski bir şehircesine 

Sensiz yaşıyor o can verircesine 

Tutuşmuş özleminle erircesine 

Bir zaman sevdigin bu yabancı benim', 'Yabancı  Hangi cennetten geldim bu cehenneme  Ki her yokluk bendedir, her acı benim  Baltalar kıyasıya inmiş govdeme  Bak! Şu devrilen hayat...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yabanci-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-kursat-usalan-33pmg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I-

Kente yağmur yağıyor

Sokaklarda dolaşıyorum

Ve insanların iyi olduğuna inanmaya çalışıyorum

Bu sonbahar böyledir 

Bilenler bilir

Kentlere yağmurlar yağar

Aşksız kalan her kimse eğer

Ya da dostu olmayan….

İnsanların iyi olduğuna inanmaya  çalışır

II-

Eski bir zaman parçasından kendime

Güzel elbiseler dikmeliyim

Herşeyin volanlı olmasını istiyorum

Bana kimse gelip de 

Saramış fotoğraflarını göstermesin

Ya kışın üşütüyorlar

Ya da  yazın 

Acıtıyor

III-

Ayaklarım yorgun

O eski bahçede gezinemiyorum artık

Artık en fazla 

Ellerim tütün kokmuyor diye beni seviyorsun

O da seviyorsan eğer

Eğer yeni bir güne başlayacaksak

Birlikte olmayacağız

İkimiz de biliyoruz bunu

Onun için yıllardır 

O yıpranmış günü yaşıyoruz habire

Hem de yamalayıp yamalayıp

Zamanı çekiştirerek

Şarkımız sesini

Fotoğraflarımız rengini yitirdiler çoktan

Fotoğraf niyetine gazete küpürlerini

Şarkımız  niyetine 

Pop artistlerini biriktiriyoruz

Ve konuşmamız gerektiğinde

Zor günler için sakladığımız

Bir kaç cümle çıkarıyoruz

Yastığımızın altından

Artık herşey demek değilsin benim için

Can sıkıcı bir kıpırdanmasın sade

Hayatımdan çıkmaya çalışan

Senin de ayakların yorgun

O eski bahçenin solmuş yaparakları üstünde

Üzerinde  yüklü yağmur bulutları bile yok

Hatta bilindik bir memleketsin benim için 

Dövize endeksli sorunları olan 

Ve çoğaldınmı ben de

Sadece başağrısı yapıyorsun

Ertesi güne kalan

Korkarım böyle bir asır daha geçireceğiz seninle

Ve sadece bayramlarda 

Birbirimize seni seviyorum diyeceğiz

Adettendir diye

IV –

büyülü yolculuklardan yoruldu düşlerimiz

kente tuksaklıktan emekli olmak üzereyiz

hayatımızda yorgunluklarımız dışında herşey hızla eskiyor

yaşantımızın aynasında görüntülerimiz siliniyor bir bir

Çaresizce alıcımızın ayarıyla oynuyoruz', 'I- Kente yağmur yağıyor Sokaklarda dolaşıyorum Ve insanların iyi olduğuna inanmaya çalışıyorum Bu sonbahar böyledir  Bilenler bilir Kentlere...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/ardindan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hava biraz bulutlansa', 'hava-biraz-bulutlansa-kursat-usalan-e710y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hava biraz bulutlansa

hep birlikte hüzünlensek

Bize özgüdür bu hüzün

batılılar bilmez bunu

harcımıza katılmıştır

Akdeniz’in serin tuzu

Akdeniz’lidir bu hüzün

Manş denizi bilmez bunu

kuzeyden doğmaz ki güneş

ıslanmaz sabahın ilk buzu

Biz bir yığın garip insan

Akdeniz’in doğusunda

konuşuruz buruk lisan

gündelikler konusunda

Ben bir zamanlar vardı ya! 

ne fırsatlar yakaldım

bakma şimdi böyle yaya

zaman geçti bakakaldım.

Eskilerden söz açınca

yaş birikir gözlerince

belli etmez kararınca

gömer sahte bir sevince

Herkes yaşar bu sızıyı

masalarda ondan başka

çekip bir yudum rakıyı

dalıp gider eski aşka

kızı kaçmış bir işsize

silmiş o da defterinden

gözü yaşlı geldi bize

yaralıymış ta derinden

adını anmasın kimse

bir daha bu evde demiş

ama ah kızı  bir bilse

hasretini ölecekmiş

yan masada başka konu

karısını bıçaklamış

on yıl yatmış önü sonu

namusunu temizlemiş

aşığıyla yakalmış

yatağında çırılçıplak

kanı beynine sıçramış

ondan sonra olmuş salak

genç olanı deli sevmiş

vermemiş ailesi kızı

sonra hep buraya gelmiş 

dinmemiş kalbinde sızı

herkesler unut diyormuş

yok mu sana bir başkası

ama o hep içiyormuş

geçer mi gönül yarası

bir başkası yıllar önce

hani içen birasını

sevdalanmış da bir gence

dağıtmışmış yuvasını

sevdalandığı genç kadın

bir hercai hafif meşrep

demiş aldığını aldın

tekme koymuş dişi akrep

hüseyin kendi halinde

bir otuzbeşlik bir meze

sekiz nüfuslu evinde

aslında memleket Rize

bakma gelmiş bir iş için

toplamış çoluk çocuğu

yoksullukmuş için için

herbirini de bulduğu

Derken birden başladı saz

dağılıp gitti acılar

gelip geçti şu koca yaz

nerde saklı bu gacılar

bir misket bir harmandalı

batılılar bilmez bunu

böyle sarhoş yaşamalı

terimizde Akdeniz tuzu

İşte böyledir bu hüzün

okyanuslar bilmez bunu

sararıp giderken yüzün

dağılır dumanı tozu

hava biraz bulutlansa da

hep beraber hüzünlensek…

				14.09.1994

				TAVŞANLI', 'Hava biraz bulutlansa hep birlikte hüzünlensek Bize özgüdür bu hüzün batılılar bilmez bunu harcımıza katılmıştır Akdeniz’in serin tuzu Akden...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/hava-biraz-bulutlansa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen mi', 'sen-mi-kursat-usalan-eoqev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soluk ışıklı gecelerinde, 

kaldırımlarında kaydırak oynadığım

bir kent vardı.

İkliminden ben bile ürkerdim.

Hele sarhoşsam titrerdim

Sen o kenti bilmezsin; 

ben nasıl senin kentini bilmezsem.

İşte bu yüzden

seninle ölene dek

aramızda  445  kilometre olacak

				17.06.1998

				İSTANBUL', 'Soluk ışıklı gecelerinde,  kaldırımlarında kaydırak oynadığım bir kent vardı. İkliminden ben bile ürkerdim. Hele sarhoşsam titrerdim Sen o k...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlandıkça', 'yaslandikca-kursat-usalan-jr2wi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşlandıkça

şiir yazan akranlarımız

azalıyor.

Günahlarımız ve biz 

başbaşa kalıyoruz.

Deneyimlerimiz arttıkça, 

işin kurnazı oluyor, 

kendi yalanlarımıza

daha az kanıyoruz.

Ve bütün bunlardan 

nefret ediyoruz

Gözlerimizin altında

herşeyden habersiz yaşayan

kırışıklıkları bahane edip, 

yok yere kavga çıkarıyoruz

Sonuçta işte

aksi birer ihtiyar oluyoruz.

				17.06.1998

                                                                 İSTANBUL', 'Yaşlandıkça şiir yazan akranlarımız azalıyor. Günahlarımız ve biz  başbaşa kalıyoruz. Deneyimlerimiz arttıkça,  işin kurnazı oluyor,  kendi ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yaslandikca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurgu', 'kurgu-kursat-usalan-o2c8t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kirpiklerimden sarkan gözyaşını görmeden

bir oltaya takıldım.

Hayat beni kollarına aldı ve, 

Sahipsiz bıraktı.

Önce tutkularımız ıssızlaştı

büyük bir gökdelenin önünde.

Gökdelen dağıldı.

Küçük küçük evlere üleşti.

Evler, 

büyük bir ülkeye birleşti; 

enflasyonu üç haneli bir ülkeye…

Üç haneden fazlasını köy yaptılar.

Sonra o köylerin hepsini 

bir bir  yaktılar.

Dumanlar savruldu alevlerden.

Kirli hava oldu.

İnsanların solumadığını gören yatırımcılar, 

havayı temizleyecek

katkı maddeli deterjanlar ürettiler; 

köpüğü ayarsız deterjanlar.

Ortalığı köpükler istila etti.

Her şey bir köpüğün sırtına binip, 

uzaklara gitti.

Günler, anlamlar, aşk…

Uzun yıllar sonrayeryüzüne

sözcük olup yağdılar.

Ortalığa bir sürü sözcük yığıldı.

Sözcüklerin altında kalanlar 

öldü.

Ölü sayısının artmasından endişe edildi.

Enkaz kaldırma çalışmaları için

zaman görevlendirildi.

Zaman aldı sözcükleri; 

tek tek her birinin kabuğunu soydu

ve gördü ki hayretle, 

her birinin içinden

bir damla gözyaşı çıktı.

Zamanın orta yerine

kirpiklerimden  sarkan gözyaşının 

anıtını diktiler.

Ve her bayram gününde ona

su ve güneş verdiler

Hayat herşeyi aldı ve 

Sahipsiz bıraktı

				15.02.1995

				TAVŞANLI', 'Kirpiklerimden sarkan gözyaşını görmeden bir oltaya takıldım. Hayat beni kollarına aldı ve,  Sahipsiz bıraktı. Önce tutkularımız ıssızlaştı ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Usalan']::text[], 8.5, '{"poet":"Kürşat Usalan","poet_slug":"kursat-usalan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/kurgu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-i-smail-safa-ermutlu-cpbck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutma fanidir dost değil dünya

Derlerki batacak mahşerle güya

Gerçek olacak bilki o rüya

Senı musallaya koydukları gün.

Arama Hayatta ne tuz nede tad

Mümkünse düşküne elini uzat

Sorarlar Insana nasıldı bu zat

Senı musallaya koydukları gün

Hıleyı hurdayı kem sözü bırak

Pıse Fıtnebaza olmayın çırak

Anlarsın sonumuz ne kadar ırak

Senı musallaya koydukları gün

Saygıya sevgiye köle olalım

Gelin ağzımızı balla yuğalım

Gönüller bağına bağban olalım

Biyi musallaya koydukları gün.

Ismaıl Safa Ermutlu

27.01.2001  Koblenz.Almanya.', 'Unutma fanidir dost değil dünya Derlerki batacak mahşerle güya Gerçek olacak bilki o rüya Senı musallaya koydukları gün. Arama Hayatta ne tu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Ermutlu']::text[], 8.5, '{"poet":"İsmail Safa Ermutlu","poet_slug":"i-smail-safa-ermutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/o-gun-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öder Giderim', 'oder-giderim-i-smail-safa-ermutlu-pnryd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir can olup düştüm fani aleme

Cefalar yağdırdın ömrü haneme

Kanunu sen yazdın bundan bana ne

Öder emanetin çeker giderim.

Dertler çiçek oldu hayat bağımda

Binbir eziyet var yaşam çağımda

Cefalar yücedir Ömür dağımda

Bahçeyi bağbanı yıkar giderim.

Bir dilim ekmektir yedigim benim

Şikayetçi değil inan bedenim

Sanma bu köprüden ben ilk geçenim

Binlerle beraber geçer giderim.

ERMUTLU yum deyip söyler gezerim

Dünyanın kahrıyla candan bezerim

Bir dirhem ağuyu camda ezerim

Sana minnet etmem ıçer giderim

İsmaıl Safa Ermutlu

10.06.1998  Koblenz.Almanya', 'Bir can olup düştüm fani aleme Cefalar yağdırdın ömrü haneme Kanunu sen yazdın bundan bana ne Öder emanetin çeker giderim. Dertler çiçek old...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Ermutlu']::text[], 8.5, '{"poet":"İsmail Safa Ermutlu","poet_slug":"i-smail-safa-ermutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oder-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Güzel Vatanım', 'benim-guzel-vatanim-i-smail-safa-ermutlu-ebyww', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyorum beni yürekten sevdiğini

Ve üzüldüğünü gurbette oluşuma

Oysaki tahmin ediyorum sevindığini

Benim sende doğuşuma.

Zor şeydir biliyorum ayrılığın tadını

Ben senin yaprak yaprak okudum kitabını

Zirveden düşmedin bil, olsamda senden ayrı

Biliyorsun çok iyi, neyim var senden gayrı.

Bağlarında tomur tomur açarım

Dağlarında pınar pınar coşarım

Güneşinle ak tenimi yakarım

Benim güzel VATANIM

Ismaıl Safa Ermutlu

04.07.1999  Koblenz  Almanya', 'Biliyorum beni yürekten sevdiğini Ve üzüldüğünü gurbette oluşuma Oysaki tahmin ediyorum sevindığini Benim sende doğuşuma. Zor şeydir biliyor...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Ermutlu']::text[], 8.5, '{"poet":"İsmail Safa Ermutlu","poet_slug":"i-smail-safa-ermutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benim-guzel-vatanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Zamanı', 'gitme-zamani-bayram-karaali-zmkr7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuşatıldım, cengime kılıçsızım artık, 

Yorgun yüreğim, kaldırım tıkırtısında, 

Bir yanı gel gel diyor, bir yanı ölüme tutkun, 

Şafaklarım kirli kızıl, koşuyorum ölüm adlı dostuma...

Savaş meydanında çırılçıplak bırakıldım utanmadayım, 

Önce ellerimi aldılar, sonra  ayaklarımı benden, 

Sonra beynime bir kılıç salladılar darmadağınım, 

Ve yüreğimi aldılar elimden  gitme zamanı ölümdeyim...', 'Kuşatıldım, cengime kılıçsızım artık,  Yorgun yüreğim, kaldırım tıkırtısında,  Bir yanı gel gel diyor, bir yanı ölüme tutkun,  Şafaklarım ki...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gitme-zamani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Kanadı Değdi Bana', 'gunesin-kanadi-degdi-bana-bayram-karaali-ws4jw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boldu Güneşim sabah uykusundan başlayıpta, uykuma kan doğrayan, 

Önce kapılar karardı siyah kartonlarla sonra perdeler kapandı, 

Ve giydiklerimde siyah gömlek giymeye başladım giderek, 

Karartmalar başladığında bende kararmaya başladım yüreğimde..

Güneş hep yalamaya başladı nedense çıkmamacasına, 

 İllede dolandı etrafımda kuşatmak için beni  namussuzca, 

Ne elimi uzatabildim nede yüreğimi yalnızlığına bebeğim, 

Bir kötü karanlık bir kötü yalnızlık hülyası sabahlarınca..

Suçmu? kime sorulmalı acaba? 

Neden karartıldı önce kapılar sonra pencereler vede yüreklerimiz, 

BEN kararttım işte önce kapıları sonra pencereleri vede yüreklerimizi

Çünkü GÜNEŞİN KANADI  değdi bana....', 'Boldu Güneşim sabah uykusundan başlayıpta, uykuma kan doğrayan,  Önce kapılar karardı siyah kartonlarla sonra perdeler kapandı,  Ve giydikle...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunesin-kanadi-degdi-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Insanlar Neyin Pesinde', 'bu-insanlar-neyin-pesinde-sair-anonym-6kz9u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu insanlar neyin pesinde, 

Burnu sümüklü, yüzü camura bulasmis cocugun gözünde! 

Dumana bogulmus yaylalarin akan serin sularinda! 

Bir candostun tutulmak isteyen yumusak ve sicak elinde! 

Alligelinin sicak teninde! 

Bu insanlar aslinda huzurun ve sadeligin pesinde!', 'Bu insanlar neyin pesinde,  Burnu sümüklü, yüzü camura bulasmis cocugun gözünde!  Dumana bogulmus yaylalarin akan serin sularinda!  Bir cand...', ARRAY['Türk Edebiyatı','Şiir','Şair Anonym']::text[], 8.5, '{"poet":"Şair Anonym","poet_slug":"sair-anonym","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-insanlar-neyin-pesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Hayalleri', 'bulut-hayalleri-nese-yasin-dallp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BULUT HAYALLERİ 

-I- 

Bulutadam gökleri yarıp çıkar 

çok uzaktadır kadın 

yavaşça yaklaşırlar 

buluşamazlar 

-II- 

Bulut at uçar 

peşinde çığlıklar 

ölüm kapısını geçer 

binicisi suya düşer 

-III- 

Bulut bulutu öper 

birleşip büyürler 

düşleri köprü olur 

köprüden kuzu geçer 

-IV- 

Bulutların sarayı 

kraliçeyi bekler 

uzak atlılar 

yolu şaşırmış 

-V- 

Bulutların milli marşı 

Dünyaca 

-VI- 

Bulut sınırı geçer 

askerler ateş açar 

bulut dünyaya düşer 

-VI- 

Bulutun aklı havada 

hem şair hem bulut 

-VII- 

Kuzeyin bulutları 

Güneyle el sıkışır 

Federal Bulut Cumhuriyeti 

-VIII- 

Bulutun elinde pamuk şekeri 

burnuna bulaşır ısırınca 

-IX- 

Bulut kuş öter 

mavi sesiyle 

-X- 

Dağa bir çiçek verir 

bulutların ecesi 

dağın kalbi taş gibi 

-XI- 

Bulutun pantolonu 

Mayakovski okur 

-XII- 

Göçmen bulutların 

köyü yakılmış 

sırtlarında yangınlar 

-XIII- 

Bayan bulut 

içini çeker 

içinden kuşlar geçer 

-XIV- 

Dalgın bulutlar 

güneşin önünü kapatır 

-XV- 

Bulut yolda bir kızcık 

ayağı aksak 

boyu kısacık 

Buluttan düşer bir damla 

Yüreğimin ortasına 

Bulut çiçeği açılır orda 

-XVI – 

Sevişen bulutlar 

akşama kaçar 

-XVII- 

Bulut köyümü görür 

Sınırın ötesinde 

Bulutun gözleri ne güzel 

-XVIII- 

Bulutların salıncağı 

Beni bekler 

(Bundan kimsenin haberi yok)

-XIX- 

Bulut kadar ömrü vardır 

Bulut hayallerinin.', 'BULUT HAYALLERİ  -I-  Bulutadam gökleri yarıp çıkar  çok uzaktadır kadın  yavaşça yaklaşırlar  buluşamazlar  -II-  Bulut at uçar  peşinde çı...', ARRAY['Türk Edebiyatı','Şiir','Neşe Yaşın']::text[], 8.5, '{"poet":"Neşe Yaşın","poet_slug":"nese-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bulut-hayalleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğun Gün', 'dogdugun-gun-cigdem-simsek-7mc2u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün doğduğun gün, 

Öyleyse MERHABA! ! ! 

Her yıl kaç kere doğuyorsun? 

Hiç ölmeden...

Her ay kaç kere aynaya bakıyorsun? 

Hiç utanmadan...

Her hafta kaç kere ellerini, bedenini yıkıyorsun? 

Hiç günahla kirlenmeden...

Her gün kaç kere gülüyorsun? 

Hiç ağlamadan...

Her saat kaç kere beni düşünüyorsun? 

Hiç unutmadan...

Vee her dakika kaç kere mutlu oluyorsun? 

Hep bensizken...!', 'Bu gün doğduğun gün,  Öyleyse MERHABA! ! !  Her yıl kaç kere doğuyorsun?  Hiç ölmeden... Her ay kaç kere aynaya bakıyorsun?  Hiç utanmadan.....', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dogdugun-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Ne Yahu?', 'daha-ne-yahu-can-akin-2-j1v6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmiyorum yeni yetmeler gibi, 

Kapı arkalarında kırıştırmayı sevdiğim...

İnsan sevdimi adam gibi sevmeli...

Yaşamalı doyasıya, 

Gönlünden geldiğince, 

Olabildiğince hür ve umarsız...

Yok, yok anladım: Hoşuna gidiyor benimle böyle oynamak...

Beni o tutkulu, o gözü dönmüş peşinde dolaştırmak...

Bir tutturmuşsun ''Bu şehirde olmaz! ''

Dar gelecek bu memleket utanmasan...

Şiirse işte şiir, 

Sevdaysa işte sevda, 

Tutkuysa işte tutku, 

Daha ne yahu?', 'Sevmiyorum yeni yetmeler gibi,  Kapı arkalarında kırıştırmayı sevdiğim... İnsan sevdimi adam gibi sevmeli... Yaşamalı doyasıya,  Gönlünden g...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/daha-ne-yahu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksin', 'gideceksin-can-akin-2-pm8sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarın gideceksin uzaklara, 

Göremeyeceğim seni koskoca bir hafta...

Kimbilir, belki de hiç düşünmeyeceksin bile oralarda beni...

Belki döndüğünde unutmuş olacaksın tüm yaşadıklarımızı, 

Göremeyeceğim o tutkulu bakışları birdaha gözlerinde...

Dalga dalga siyah saçların omuzlarından dökülürken, 

Bakmayacaksın bile gözlerime öylesine arzu dolu artık...

Belki kendi kendine kızarak, 

''Zayıf bir anımdı! Eh, işime de yaradı! '' diyeceksin sadece...

Belki, o bütün ikna edilmişliğinle, 

Soğuk zırhına bürünüp, 

Benden başka herkese sımsıcak olacak olan kalbinle, 

Oynamaya çalışacaksın umarsızca yaşamın yüklediği tüm rollerini birkez daha...

Sadece bir kez daha... 

Tüketilene kadar...

Son bir umutla...

Umut değilmidir sevdiğim yaşatan insanı zaten? 

Ha öyle, ha böyle...

Belki de, çıplak ayaklarıyla soğukta mendil satan o minicik kızlara baktığın gibi bakacaksın artık yaşama...

Sımsıkı, dört elle sarılmış olsan da rollerine, 

Reddetsende kesişen yazgılarımızı, 

Binbir renge boyasanda o yorgun maskelerini, 

Her zaman hissederek o korkuyu içinde, 

Bekleyeceksin sevdiğim: 

Ne zaman yıkılacağını, 

Ne zaman parçalanacağını, 

Ne zaman öylesine yapayalnız bırakılacağını yaşamın ortasında bir kez daha...

İşte ben bunu hep bileceğim sevdiğim...

Ve Sen, 

Bunu bildiğimi hep bileceksin...

Hakkım yok biliyorum, 

Suçlayamam seni böyle yaparsan...

İsteyemem umursamazca, bencilce herşeyi...

Sevdim seni...

Yarın gideceksin, 

Seveceğim seni...', 'Yarın gideceksin uzaklara,  Göremeyeceğim seni koskoca bir hafta... Kimbilir, belki de hiç düşünmeyeceksin bile oralarda beni... Belki döndü...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gideceksin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-can-akin-2-e48mk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep bir oğlum olsun istedim, 

Adı, Can olsun istedim...

Sarı saçlı, 

Renkli gözlü bir afacan istedim...

Beraber balık tutmak, 

Karşılıklı rakı içmek istedim...

Biliyorum olmayacak...

Olsun, 

Ben gene de istedim...', 'Hep bir oğlum olsun istedim,  Adı, Can olsun istedim... Sarı saçlı,  Renkli gözlü bir afacan istedim... Beraber balık tutmak,  Karşılıklı ra...', ARRAY['Türk Edebiyatı','Şiir','Can Akın 2']::text[], 8.5, '{"poet":"Can Akın 2","poet_slug":"can-akin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/can-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-abdullah-karaduman-i3s4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Batan güneşte

Sararan yaprakta

Yeşeren tohumda

Hep sen varsın

Geceleri rüyamda

Sabahları aynada

Rüzgarda savrulan

Başaktaki buğdayda

Her motor sesinde

Radyodaki haberde

Suyun akışında

Yağmurun sesinde

Doğan güneşte

Açan çiçekte

Kara toprakta

Hep sen varsın

Mekanın cennet olsun BABACIĞIM.', 'Batan güneşte Sararan yaprakta Yeşeren tohumda Hep sen varsın Geceleri rüyamda Sabahları aynada Rüzgarda savrulan Başaktaki buğdayda Her mot...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-varsin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklerken', 'seni-beklerken-gurkan-gezer-ivw8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belli ki kâbus görmüşsün gece

Belli ki atar hâlâ kalbin hızla

Sevdalar seçmişsin ama belki de

Birbirinden güzel

Belki bir ırmak olup akmışsın düşünde

Belki de rüzgar olup koşmuşsun

Ya da

Duyulmadık türküler olup söylenmişsin sabaha dek

Benim dün gördüğüm düş gibi ama belki de 

Ölmüşsün meğer

Cennete gitmişsin

Cennet te ne? 

Bomboş

Yanında bir tek sevgilin var

İki lokma ekmek bir de

Nefes nefese, sabahı zor getirdim dün gece

Seni görmek ümidi

Uykudan ağır bastı demek ki

Zor uyudum gecelerce

Zor uyandım sabahları

Seni aradım kalabalıkta

Çocuk gözlerinde

Kapkara, tren düdüğü bakışlarında simitçilerin

Seni aradım yıllarca

Parkta kimi beklediğini bilmeyen

Yaşlı adamın bakışlarında

Dilencinin kirli ellerinde 

Yoksul mahallelerin, 

Yırtık donlu bebelerinin

Tiner kokan nefeslerinde

Seni aradım uykusuz gecelerde

Belki yoktun

Ümitsizdim belki

Ama aradım

Belki zordu

Belki imkânsızdı

Ama sıkılmadım

Belki düştün

Pembe rüyaydın

Sırf bunun için

Uyudum geceleri

Ama, uykularım benden daha gerçekçi

Bir gece bile

Göremedim seni düşümde

Sadece bir tek gece

Yaşlı bir kadın evinin bahçesinde

Balık ağı ayıklayan

Onun serin elleri

Belki 

Sendin

17.11.1998', 'Belli ki kâbus görmüşsün gece Belli ki atar hâlâ kalbin hızla Sevdalar seçmişsin ama belki de Birbirinden güzel Belki bir ırmak olup akmışsı...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Gezer']::text[], 8.5, '{"poet":"Gürkan Gezer","poet_slug":"gurkan-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/seni-beklerken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunuş', 'dokunus-gurkan-gezer-8gtmt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunmak sadece

Sevdiğinin kalbine

Filmlerdeki gibi koşmak kırlarda

Ağlamak

Çocuklar gibi

Hıçkıra, hıçkıra

Dokunmak

Sevdiğine

İki dize de olsa

Hissettiklerini aktarsan beyaz kağıda

Belki daha kolay olur herşey

Şiir yazman gerekmez

Kalp çizsen de olur

Oklardan biri

Seni

Diğeri onu gösterse

Ya da çiçek çizsen

Nergis, gül değil

Kır çiçeği

Sevdiğinin üşümüş pembe yanakları gibi

Ninenin elleri gibi eller çizsen

Biri senin elin olsa

Diğeri sevdiğinin

Elli yıl sonraki elleriniz

İç içe

Umut olsa çizdiğin bir çift gözde

Çocuk gözleri gibi

06.01.1998', 'Dokunmak sadece Sevdiğinin kalbine Filmlerdeki gibi koşmak kırlarda Ağlamak Çocuklar gibi Hıçkıra, hıçkıra Dokunmak Sevdiğine İki dize de ol...', ARRAY['Türk Edebiyatı','Şiir','Gürkan Gezer']::text[], 8.5, '{"poet":"Gürkan Gezer","poet_slug":"gurkan-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dokunus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradanlıklar', 'siradanliklar-i-smail-erkan-tolay-ihtlw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bazen, dalgasını geçerse ulular bizle 

uzaklardan bir gelin kefeni geçer 

Tartışır, irdeler, keskinler rüzgar 

sabaha karşı açan çarkıfeleğin 

üzerimize ittiği 

üzerinden güneş geçmemiş 

nedametler... 

Her orospunun bir açalyası vardır 

kızışmaların akabinde 

''geçmiş olsun'' diyerek sarılıp, sırtladığı... 

Kurtaramaz bulutları rüzgardan 

kurtaramaz rüzgarı 

bulutların arkasına takılıp 

uzaklaşmaktan 

Yaşlı istasyon şefleri 

daha çok, karan/filleri üzer 

rüzgar kokusunu taşırken 

yaşlı duyguların. 

Çünkü rüzgar zararlıdır yapraklara 

yapraklarsa acımaz hiç 

gecikmiş sevgilerin 

kitabesiz ve yorgun 

mezar taşlarına 

Nergistir, asi'' si bu alemin 

toprağın karasını gizler 

unutuldu sanılan arzular kadar 

köledir, efendisi olmayan kim varsa 

köledir isyana asiler... 

Var gücüyle bakiredir nilüfer 

zaman unutulmazsa eğer, bu bilinsin 

Çünkü rüzgar bacalara da sızar 

bacalara da sızar gün 

bacalar da sızar kanınca 

gerçeksiz kalmış şarapların 

tortusuna kazılı 

nikah cüzdanları 

Mavidir rüyası bekçinin 

buna mecbur 

ve ancak şımarık ve kıskanç 

lale''nin çeneklerinde bulabilir gerçeği 

eğer biz 

razı olursak kaybetmeye 

razı olursak, rüzgarın 

bizden önce 

               bekçiyi öldürmesine... 

(1989)', 'Bazen, dalgasını geçerse ulular bizle  uzaklardan bir gelin kefeni geçer  Tartışır, irdeler, keskinler rüzgar  sabaha karşı açan çarkıfeleği...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/siradanliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karan/fillerin Korkusu', 'karan-fillerin-korkusu-i-smail-erkan-tolay-3n500', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mehtaptır titreyen 

ibrik ibrik dökülen suda 

narin, hüzünlü, karanlık 

ve en kutsal yanıyla gece 

bir korkudur 

korkmaktan korkan 

karan/fillere 

İmbiklerden damıt karanlığı 

damıt ve iç 

               kendi kanındır 

ağlama hiç koparılırken 

               duygular teninden 

De ki: 

Olamaz, olmamalı 

süngünün ucunda çiçek 

ucunda çiçeğin, şarapnel kokusu 

Budur işte bilinen 

               o bilinemez gerçek 

Budur karan/fillerin korkusu 

Öğrenin bilgeden 

Serin, leylak kokulu kızların 

Ejderhalarla alakası 

                karşıdır akla 

artık her kaza 

bir olasılıksızlık... 

İçimde çıban açar çiçekler 

avunmayı bilirim 

avunmayabilirim 

nice acı oldum ağıtsız kalan 

yarınlar yalnızca bahane 

ilahi bir hayvan gibi 

kezzap içimli memelerinden 

içtim, acıları kanatarak 

Demagog ve uysal 

                 yalancı ve ruhban 

tüm dikenleri içtim... 

Bana ne yüzmeyi unutan balıktan 

açmıyorsa çiçekler, bana ne 

Mademki serinlik gecenindir 

vakti gelmiştir ölümün 

keşfetmeliyim 

okunaksız da olsa 

                  yazmalıyım 

Ölüm, özel bir konudur çünkü 

her harfinde gölge gölge 

karan/filler 

Şık bir ölüm seçilmeli 

karan/fillere üzünç yakışmaz 

her ölünün kendi 

kızıl çiçeği vardır aslında 

her kefen beyaz 

                   karan/fil 

Düğünden kaçırılmış bir 

duvak gibidir... 

(1993)', 'Mehtaptır titreyen  ibrik ibrik dökülen suda  narin, hüzünlü, karanlık  ve en kutsal yanıyla gece  bir korkudur  korkmaktan korkan  karan/fi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/karan-fillerin-korkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zambezi - Zimbabwe hattı', 'zambezi-zimbabwe-hatti-i-smail-erkan-tolay-k75ew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanal sarımsı tatlı buhurlu kuştüylü üşütmüş veya geri kalmış

                                                                  yada basılmış nasırına 

karanlıkta ürkmüş piranhalar dan piraye yi özlemiş 

                                            nazım gibi bi sen bi de ben sanki....

Hani ağaçlara çıkmışta bakarmışız 

Dünden kalmış

Sabahçı öğrenci muhabbeti...

Tembel bir kör kır kirpi

Yine ben yine sen

Oysaki eli değmişti elimize geçen gün otobüste

Hani eli sandıktı diananın, aprodite nin..

Yıkamamıştık hatta elimizi

İşte o sızı....

 Ne zor şeydir mirim yalnızlık...

Yanında varken  bi, havva kızı...

Ağaçların üstünde yapraklar dağınık

Buruşuk sanki suyu denizin

Anadolu kıtası bu 

Dağ tepe kırık çıkık

Nasıl doğru düzgün gideyimki

Düm düz yatayım sonra...

selvilerin altına

diyorlarki şiir düşermiş tepemeze uçakta öpüşen bi çifttin 

                                                                                dudaklarından

hatta kuşlardan..arılardan..börtü böcekten

göğün yeşerdiği sabahlarda ufukta dar kalmış yaşmaktan

ondan..bundan..

neden düşüyor benim kafama

böyle eçiş bücüş biraz abuk

riiş..... 

(2000)', 'Sanal sarımsı tatlı buhurlu kuştüylü üşütmüş veya geri kalmış                                                                   yada basılmı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zambezi-zimbabwe-hatti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hint Kumaşı..', 'hint-kumasi-sukru-soyarslan-mts7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ettiğin artık yeter, bu son olsun

Senin gönlüne de, sevgiler dolsun.

Sabrım taşırıyorsun, haberin olsun

Söyle; bulunmaz Hint Kumaşı mısın? 

Yüreğim yakıp, kalbime kor saldın

Ben ağlarken; zevke, sefaya daldın.

Sanırsın ki, dünyada tek Sen kaldın! 

Söyle; bulunmaz Hint Kumaşı mısın? 

Her gün sitem, her anında cilve, naz

Biliyorum güzelsin, yerin dolmaz.

Birtanem..beni anlasana biraz

Söyle; bulunmaz Hint Kumaşı mısın? 

Nasibini almış, güneşten ay''dan

Kirpikler ok olmuş, fırlamış yay''dan.

Zannedersin, sanki gelmiş uzaydan

Söyle; bulunmaz Hint Kumaşı mısın? 

Sevda yelinde kırıldım, dal gibi

Senin hasretinden, soldum gül gibi.

Niye Ben''den uzaklaştın, el gibi

Anladım..Bulunmaz Hint Kumaşısın.!', 'Ettiğin artık yeter, bu son olsun Senin gönlüne de, sevgiler dolsun. Sabrım taşırıyorsun, haberin olsun Söyle; bulunmaz Hint Kumaşı mısın?  ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Soyarslan']::text[], 8.5, '{"poet":"Şükrü Soyarslan","poet_slug":"sukru-soyarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hint-kumasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karan/fillerin Ölümü', 'karan-fillerin-olumu-i-smail-erkan-tolay-1nfp3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlıktır 

bana sorarsanız; rengi sevilerin 

bazen zor olur uyanmak 

hatta farkına da varılmaz 

gece vakti kara bir saç teli kadar 

gizemli ve hırçın rengi 

sevilerin 

Nedendir'' ki karan/filler 

aykırı bir gerçek gibi yabansı kalır 

herkese ait düşlere 

toprak ayrık otlarına'' da 

                       şefkatlidir oysa 

düşler bile zararlıdır 

karan/filler için 

Bir gün, bir karan/fil 

ola ki düş görebilir 

hatta sever 

kat kat olmuş endamıyla 

tekinsiz bir öç tutkusu gibi 

düşer sulara 

Düşler çabuk biter 

karabasana dönüşecek kadar 

uzun yaşayanlar 

ölümüdür 

          karan/fillerin 

düşler 

yaşanırı anlamsız 

anlamsızı yaşanır kılan 

gerçek gibidir 

Sırları sır eder gece 

bir soru göverir karan/filler 

düşlere de düşer karası 

        -ne çok yalanları var tanrım, 

        -yaraları, ...ne çok 

ay ışığında çalınan hayali saz 

sorular verir 

ya tükenmek kayan yıldızcasına 

ya çiçekler açmak, solmak için 

kaçamaz, bu dur ölümü 

karan/fillerin 

karan/filler ölürken 

üzerimize ancak 

saf ve temiz bir çocuk cesedi 

kanat gerebilir 

(1993)', 'Karanlıktır  bana sorarsanız; rengi sevilerin  bazen zor olur uyanmak  hatta farkına da varılmaz  gece vakti kara bir saç teli kadar  gizeml...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/karan-fillerin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derviş', 'dervis-erol-sen-ec86j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman içindeki değişimleri

Düşünürken geçmiş zamanı, yaşananları

Bakarken gündelik yaşamlara

Bir derviş olsaydım zamanın birinde

Patika yollarda yalın ayak bir gidişe

Eylenmek için bir han kapısına vardığında

Verilen selama yapılan ikrama

Bilgelik payesi verilen dergaha 

Bilge olmak için kapı kulluğuna

Çıkar beklemeden yapılan hizmetlere 

Paylaşımlarım çıkarsızlığına 

İmren dostum geçmiş zamana

Dervişin evi olmaz gezerdi derler

Düşümde bile olsa derviş olmak isterdim

Yada aşka düşen bir şair

Yada Ferhatın dağları deldiren sevdası

Günlerce yol yürüyüp doğayla kucaklaşmak

Kuşların aşk nağmelerini dinlemek

Bir deniz kıyısında maviliklere dalmak

Bir handa yorgun argın uykuya dalmak.

Sevginin bitimsiz bahçelerinde

Güllerle yada hercai menekşeyi

Sevmek ama derviş misali.

27.08.2002', 'Zaman içindeki değişimleri Düşünürken geçmiş zamanı, yaşananları Bakarken gündelik yaşamlara Bir derviş olsaydım zamanın birinde Patika yoll...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dervis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızayak', 'yalnizayak-i-smail-erkan-tolay-99rz4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nuh''u öldürdüm dün gece 

kendi ellerimle söktüm ruhunu 

kopmayacak tufan, 

                     kopamayacak 

gölgesi düşmeyecek hayatımıza 

anlamı yok, anlam 

                     aramayacağım 

serinkanlılıkla işlediğim cinayet 

papatyaların yazgımıza vurduğu prangalar 

ne de yitirilen arkadaşlar 

için 

Ne çiçeklerin çeneklerinde bin bir renk 

ne suların gözüme yansıyan şavkı 

yalnızlık'' sa yalnızlık 

ölesiye, 

      kıran kırana, 

            çığlık çığlığa, 

yaşamak 

vahyedildi kulağıma 

gerçek'' se işte gerçek: 

       yalnız kalmaktır aslında 

ölüm korkusu 

Bundandır ki aşka ayarlı vakitler 

bundandır ki korkmuyorum 

gök gürültüsünden 

Oysa hangi gerçek 

bu kadar kolay ödenebilir ki 

kalabalıkta yalnızlıklar yaratan 

hangi yalandır 

Onu'' da gökkuşağına haykırdım 

Bir gün büyüyüp, serpilecek 

seraplar yaratacak 

ayrık otlarından 

(1993)', 'Nuh''u öldürdüm dün gece  kendi ellerimle söktüm ruhunu  kopmayacak tufan,                       kopamayacak  gölgesi düşmeyecek hayatımıza  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yalnizayak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serin', 'serin-i-smail-erkan-tolay-8jhhv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serin hazlardan bir gömlekti 

ululandı, asıllandı, kamçılandı 

olgunlaşmamış kirazlarla boyandı 

güneşte kızarmadan kara topraklar 

bilemedik, giydik onu 

Upanişad anlamsız kelime 

Enlil'' le İştarın kavgası bile 

itirazlar satarken sanrılarımıza 

bir kızgın büyü gibi seçtik 

toprağın harmanından 

Otuz dokuz ince tüyden 

demir gergef işledik 

her sayfası al ''a çaldı 

gece yatısı trenini beklerken 

yatağımızda sensiz 

gündoğumları 

Çıkardık, çıplak kaldık 

sıyrıldık bulutlardan da 

-Bulutlar, alçalabilirdi; 

Çalabilirdi kavalını çoban- 

rüyalar, üşüyebilirdi 

vakitsiz esen, bir serin yelden 

Dün gece gölgen'' le ben 

seni andık... 

(1992)', 'Serin hazlardan bir gömlekti  ululandı, asıllandı, kamçılandı  olgunlaşmamış kirazlarla boyandı  güneşte kızarmadan kara topraklar  bilemedi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/serin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilyeler', 'bilyeler-i-smail-erkan-tolay-haeh6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerimde ders kitapları yok 

okunmuş romanlar, ayıp dergiler 

                           olmayacak düşler 

Sayfalarla tanımlardım kendimi 

yalnızca bir resm''im oysa 

ölenleri anmak için 

ölemeyenlere acıyan 

Bir gölge gibi dolaşırım geceyi 

loş sokakların kuytularında 

doğar yeniden, 

                   canlanır sanırım 

umut verircesine 

inatçı, sevecen ve kıskanç 

ne kaldıysa içimde 

bilyelerini arayan 

Kiremit damların hırçın 

dudak kızılı bakmalarına yanıt 

yaşamı çağıran çocuk çığlıkları 

kaldırımlara düşen 

ölü dostların hayallerinden 

başka karaltı 

doğacak günden belirtiler 

çağıran, aralık bir kapı 

bulmaksızın 

Karanlıkta yalnızlık yankılanır 

uyanır üç tutsak, çehreler giyer 

üç tutsak hür kalır 

parke taşların gizlediği toprak 

gizlenecek yeri kalmamış düşkırıkları 

bilyeler... 

Bon ami yumuşaklığıyla 

yaslanınca gecenin esmer teni 

tüylerinde hüzün 

tüylerinde hançer 

kalmıştır 

(1993)', 'Ellerimde ders kitapları yok  okunmuş romanlar, ayıp dergiler                             olmayacak düşler  Sayfalarla tanımlardım kendimi  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bilyeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Bitiyor', 'bir-ask-bitiyor-i-smail-erkan-tolay-oua2d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümüne ağır geliyor yaşamak 

her yarın yeni vedalar çağırıyor 

sabah mahmurluklarından 

ve ilk ışıklarıyla güneşin 

yaşanmaya mecbur bir aşk 

bitiyor 

Hiç başlamasaydı keşke 

diyor adam 

azizleri yanına alarak 

azizlerce kışkırtılmış bir kuzgun 

hatırlatıyor: 

Yaşanmaya mecburdu bu aşk 

bitmeye mecbur... 

Kadın 

Bulutlara biniyor 

yeni rüzgarlara salıyor saçlarını 

çekil git karabasan 

diyor, sevgisiz ve mağrur 

yolunu kesen siluete 

çekil git rüzgarımdan 

Sabah yüklü 

bir gemi giyiniyor adam 

aldırmıyor rüzgarlara 

kara, 

demir almış uzaklaşıyor 

`merhaba` diyor adam 

gidiyor... 

ölümüne ağır geliyor yaşamak 

yaşanmaya mecbur bir aşk 

bitiyor 

(1995)', 'Ölümüne ağır geliyor yaşamak  her yarın yeni vedalar çağırıyor  sabah mahmurluklarından  ve ilk ışıklarıyla güneşin  yaşanmaya mecbur bir aş...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-ask-bitiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'il Cogito Ergo Sum...', 'il-cogito-ergo-sum-i-smail-erkan-tolay-le7s6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazılmamış mektuplarım vardı

Gençtim, sevmezdim ki dostluk etmeyi latin harfleriyle

genede lezzeti kaldı

Kekremsi, zihin hücrelerim de

Yazılmamış mektupların

Bilirmisiniz? 

Siz, bu şehrin çamurda saplamaca...misket, 

Kırıkhan oynamamış çocukları

Bilirmisiniz bir zamanlar...

Burda, şehir vardı...

Uzun dilli bakışları vardır opera tadında

Yarınları vardır yangınları vardır

Ağıtları vardır kış günü kazara açan gelinciklerin

Ve yitik ve narin ve prusya mavisi

Düşleri vardır sokaklarında günün solduğu 

Gri hüzün tonajlı şehirlerin..

Hangi tınısında yakalandımki sana

Bakışlarında ney misali bin renkli

Ve kokusu vardı sesinin ergüvani leylak

Yaşlanmanın tecrübesizliğiyle

Kaptı eski zaman fırınlarından

Dumanı üstünde aldığım taze düşleri

Düş kurmak, 

Kırmızı et gibidir oysa, kalbe zararlı

Ve kollestrol ölçüsüne vurmadan

Vurmadan yaşamalı

Taze sevdaları

Gel, gel beni vurgun bi-zeban

Akla ait her sokakta kapışmaz mı

Kentin diş tırnak sakinleri

Hangi yarınlar..hangi acı tadında anı

Yitip gitti posta kutularımızdan

-Renkleri vardı rüzgarın-

bize ucuz glikoz tadı

e-mail ler kaldı...

(2000)', 'Yazılmamış mektuplarım vardı Gençtim, sevmezdim ki dostluk etmeyi latin harfleriyle genede lezzeti kaldı Kekremsi, zihin hücrelerim de Yazıl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/il-cogito-ergo-sum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılgan', 'kirilgan-i-smail-erkan-tolay-gqf7a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Kırılgan bir kabuğum olduğunu farkettiğimde...gözlerinin büyüsünden belki..kabuğumu kalınlaştırmak yerine kırdım.Düş kurmanın zorlukları...

tattım..ve tattın...tadamadık bir türlü..

çünkü..

öpünce kurbağa olan prenslerin vardı senin”', '“Kırılgan bir kabuğum olduğunu farkettiğimde...gözlerinin büyüsünden belki..kabuğumu kalınlaştırmak yerine kırdım.Düş kurmanın zorlukları......', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirilgan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tukumbi', 'tukumbi-i-smail-erkan-tolay-2rwvu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Tukumbi''

dedi, bilgece; 

bir sümer heykeli giyinmişti

''Sorusunu aradığın cevap bu

Bunun içindirki 

kainat, dört bir yandan gelipte

aktı sularına

paylaşımsız yatakların''

ölüm bir soru işareti

yaşam sa ünlem

yaşayamamaksa

nokta

Yüz yıl önceydi ölümüm

Tam yüzyıl sürdü

gömüldüm dingince

Badem ağacı kollarında bir çocuk

göverince

(1989)', '''Tukumbi'' dedi, bilgece;  bir sümer heykeli giyinmişti ''Sorusunu aradığın cevap bu Bunun içindirki  kainat, dört bir yandan gelipte aktı sul...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tukumbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naharina, Tadukhepa', 'naharina-tadukhepa-i-smail-erkan-tolay-h9i6w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(Zamanın anımsamadığı anılar defteri için zamanında yazılmamış 3. şiir)

Fındıklı cihangirde

Timsah sokak

diğer algıların üzerinde

gündelik yaşamakların izleri silik

çatı katı, çatık damların bakışığı

9: 30...

düşmüşsede akşamın karanlığı

izleri silik değil henüz güneşin

boğazda, umarsızca bıraktığı

9: 35...yada başka zaman...

bilinirmi akışkanlar mekaniğiyle

geçiş hızı zamanın? 

hem, zaman varmı? 

isyan var...

isyan var gözlerinde dalga dalga, 

bulut bulut bir kedi çevikliğiyle

yangıları var martıların

yakamozlar var

kıvılcımlar

kurumuş insan tarlalarında

bir düş ölür, bir düş uyanır

uzamış hatlarla yüzleri insanların

gözlerinden tutuşur savanlar

gözlerinden tutuşurum ben

Tadukhepa, Naharina

benim aslında iki nehrin arası

isyanı dinlensin gözlerinin gözlerimde

rengini gör rüzgarın

ve dinle müziğini mavi üstü mor

ve tat...

o notalarda rayiha

o notalarda akşam var

sakınımlı bir salınımdır

akşamın işlediği yalıtılmışlık üzerimizde

ve akşam da hüzün ve akşam da huzur ve akşamda isyan var

gözlerin gibi...

gözlerinki tutuşturur savanları

gözlerinden tutuşurum

Naharina, Tadukhepa, 

Bakışların, fındıklı

çatı katı.

ve bir de artı

zamanın anımsamazlığı

tutuşuyor...

ve gece...

geç gelenlere misal için.

(26/11/1999)', '(Zamanın anımsamadığı anılar defteri için zamanında yazılmamış 3. şiir) Fındıklı cihangirde Timsah sokak diğer algıların üzerinde gündelik y...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/naharina-tadukhepa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-murat-acmaz-zxjoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu şehri yakasım gelir, 

Sensizliğe her isyan edişimde.

Yanmaz kibritlerim, 

İçinde sen olduğunu bildikçe.', 'Bu şehri yakasım gelir,  Sensizliğe her isyan edişimde. Yanmaz kibritlerim,  İçinde sen olduğunu bildikçe....', ARRAY['Türk Edebiyatı','Şiir','Murat Açmaz']::text[], 8.5, '{"poet":"Murat Açmaz","poet_slug":"murat-acmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yangin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün', 'dun-murat-acmaz-lw1hq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dümüm yok benim, 

Yaşanacak yarınlar can vermekte sensizliğe.

Ve bütün ümitlerim; 

yokluğunun bir yerinde ölümü seyretmekte.', 'Dümüm yok benim,  Yaşanacak yarınlar can vermekte sensizliğe. Ve bütün ümitlerim;  yokluğunun bir yerinde ölümü seyretmekte....', ARRAY['Türk Edebiyatı','Şiir','Murat Açmaz']::text[], 8.5, '{"poet":"Murat Açmaz","poet_slug":"murat-acmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dar Kapı', 'dar-kapi-ahmet-altan-uafen', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Andre Gide, Dar Kapı isimli kitabında, yaşanılanın değil yaşanılmayanın hikayesini anlatır; birbirlerini seven iki insanın bir türlü bir araya gelememesinin hikayesidir bu kitap. Ve birleşememelerinin nedeni, başkalarından ziyade kendileridir, kendi inançları, kendi korkuları önler onların aşklarının ifade edilmesini. Koca bir hayatı, istediklerini yapamayarak geçirir kitabın kahramanları.

Yaşamak istediklerimizle yaşayabildiklerimiz arasında ortaya çıkan büyük uçurumun esas sorumlusunun aslında kendimiz olduğunu anlatır kitap. 

Bütün kitap boyunca okuyucu hep aynı isyanı hisseder, söyleyin artık, birleşin artık neden duygularınızı gizliyorsunuz, diye bağırmak ister. Ama, kitabın kahramanları, kendi yarattıkları o ''dar kapıdan'' geçemezler bir türlü, orada sıkışıp kalırlar. 

Herkesin hayatı, dar kapılarla çevrilmiştir aslında.

Rahatlıkla geçip feraha ulaşacağımız birçok kapıyı, kendi inançlarımız, korkularımız, endişelerimizle daraltıp kendimizi kendimize tutsak ettiğimizi çok geç farkederiz. 

Yaptıklarımızdan ziyade yapamadıklarımızdan daha çok pişman olmamızın gizli nedeni de budur zaten, yaptıklarımızın sonuçları kötü çıksa da, çıkan sonuçlarda bizimle birlikte başkaları da sorumludur, başka birilerinin iradesi işin içine girmiştir, pişmanlığımızı ve öfkemizi başkalarının üstüne yıkabilir, pişmanlıktan kendi payımıza düşeni azaltabiliriz.

Ama yapmadıklarımızdan duyduğumuz pişmanlıkların bizden başka sorumlusu yoktur, bizden başka bir suçlu bulamayız, o pişmanlığı tek başımıza sahiplenmek zorunda kalırız.

Kendi geçmişimizden geleceğimize uzanan yolda karşımıza çıkan dar kapıları neden aşamayız, neden takılır kalırız oralarda, nedir bizi durduran, nedir bizi gelecek pişmanlıklara hazırlayan. 

Neden bir türlü istediğimiz gibi yaşayamayız? 

Neden ıslak bir kil parçası gibi elimizde duran hayatımızı şekillendirirken, bir yerinde takılır ve onu istemediğimiz bir biçimde şekillendiririz, kendi isteklerimizden daha önemli ne olabilir? 

Korkularımız tabii.

Gide''nin romanındaki kahramanlar gibi Tanrı''dan korkabiliriz. 

Çekeceğimiz acıdan korkabiliriz. 

Ya da Benjamin Costant''ın ''Adolphe'' romanında anlattığı gibi başkalarının acı çekmesinden korkarız. 

Constant, kendi hayatından esinlenerek yazdığı romanında, kendinden daha yaşlı bir kadınla birlikte olan genç bir erkeğin o kadını neden bırakamadığını anlatır. 

Kadının duyacağı acıyı düşünmek, erkeği hareketsiz kılar, bu çaresizliğine öfkelenip kızsa da bunun üstesinden gelemez. 

Adolphe, ne zaman yeni bir hayata hazırlansa, yaşlı sevgilisinin gözyaşları engeller onu. 

Aynı çaresizliği Daudet''in ''Sara'' isimli kitabında da görürüz. 

Orada da romanın kahramanı bir türlü kendini geçmiş bağlarından kurtarıp yeni bir hayat kuramaz. 

Bütün bunlar, insanın kendi hayatını belirlemekte sandığı kadar özgür olmadığını gösterir. 

Üstelik özgürlüğü kısıtlayan, kendi dışımızdaki dünya değildir. 

Hayatımızı değiştirmemizi engelleyen polisler, hakimler, savcılar, ordular, yasaklar değildir; yasak kendi içimizdedir, kendi korkularımızdadır, kendi geçmişimizdedir. 

Yaşadığımız her gün kendimize biraz daha tutsak oluruz, yaşanan her gün hayatımıza bağlanan zincirlere bir halka daha ekler ve biz yaşadığımız her gün o zincirlerden kurtulmakta biraz daha zorlanırız. 

Yaşamak istediğimizi yaşamamamızın nedeni, yalnızca o isteğin yeterince güçlü olmadığı söylenerek açıklanabilir mi? 

İsteğin güçsüzlüğü değildir her zaman asıl neden. 

Yeni bir hayata başlarken, dar kapıları kırıp geçerken, arkamızda bırakacağımız acıların, uzun selvileri olan bir eski mezarlık gibi gölgesini geleceğin üzerine sereceğini hissederiz. Gelecek, temiz ve aydınlık bir yaz sabahı gibi aydınlık başlamayacak, aksine geçmişle lekelenmiş bir halde başlayacaktır. 

En çok o gölge korkutur bizi. 

Yaşamak istediğimizin de gölgelenmesinden endişe ederiz. 

Çılgınca yaşamak istediğimiz yeni günlerin, bize geçmişle gölgelenmiş olarak gelmesi düşüncesine tahammül edemeyiz. 

Korkaklığımız, biraz da geleceği kurtarmak endişesindendir. 

Geçmişten gelen gölgelerle soluklaşan bir gelecek mi yaşamalı, yoka hiç yaşanmayan, yaşanmadığı için de gölgelenmeyen, yaşanmamış ışıklı bir hayal olarak mı saklamalı isteklerimizi. 

Dar Kapı''da olduğu gibi sevdiğimizle yaşayacaklarımızı bir günahın gölgesinden mi esirgemeli, Adolphe''da olduğu gibi bir başkasının ruhumuza sinen acısından mı sakınmalı, Sara''da olduğu gibi vicdanımızı damla damla lekeleyen gözyaşlarından mı kurtarmalı? 

Yaşanan ilk aşkla birlikte, geleceğe düşen gölgeler de uzamaya başlar. 

Geçmiş olduğu sürece gelecek gölgeli olacak. 

Yaz sabahlarının temiz ve gölgesiz aydınlığı kalmayacak geleceğimizde. 

Geçmişin gölgelerini taşıyan bir gelecek mi, gölgesiz, dokunulmamış ve yaşanılmamış bir hayal mi bizi daha mutlu eder? 

Ne Gide, ne Costant, ne Daudet buna bir cevap vermiyorlar.

Anlattıkları, yaşayamamanın acısı yalnızca. 

Yaşamamak, kendini kendi geçmişinin gölgesinden kurtaramamak acılı bir tortu gibi birikiyor onların kahramanlarının içinde, isyan krizlerine tutulsalar da kendilerine yeni bir hayat yaratamıyorlar. 

Dar kapılardan geçemiyorlar. 

Çünkü yaşadıkça kalabalıklaşıyoruz. 

Gide''nin kahramanlarının hiçbir kapıdan sığmayan günah korkuları var eteklerinde.

Costant''ın kahramanının yaşlı sevgilisinin acıları var kolunda.

Sara''nın kahramanı vicdan azabını taşıyor beraberinde.

Günahı, acıyı, vicdan azabını kapılardan sığdırmak kolay değil, bütün kapıları yıkmak gerekiyor, yıkıntılardan bir ışığa çıkılır mı peki? 

Yaşayamadığımız için pişman olacağımızı bile bile geleceğimizi feda etmeli miyiz? 

Yoksa, gölgeli de olsa o benim istediğimdir, yaşamalıyım mı demeliyiz? Geleceği yaşarken geçmişin gölgeleri zamanla solup silinir mi? 

Geçmişle gelecek arasındaki o dar kapıdan geçerken, oraya buraya sürünüp örselenen ruhumuz, geleceği istediği gibi kucaklayabilecek mi? 

Yaşam dar kapılarla dolu.

Yıkmalı mıyız o kapıları? 

Günahı, acıyı, vicdan azabını silip atmalı mıyız? 

Duyduğumuz istek, günahı, acıyı, azabı silmeye yeter mi? 

Yoksa, günah korkusu, geçmiş acılar, vicdan azapları geleceği mi karartır? 

Neyi seçmeli insan? 

Kendi geçmişinden, hafızasından, hatıralarından, inançlarından nasıl kurtulmalı? 

O dar kapılar bizi yaşamamaya mı mahkum ediyor? 

Kendi geçmişiyle hüküm giymiş birer mahkum muyuz? 

Hayat, kurtulamamanın hikayesi mi? 

Peki, o aşk romanları ne öyleyse, anlatılan aşklar nasıl yaşanıyor? 

Geçmişin bittiği, bizi sahipsiz olarak, boşlukta terk ettiği zamanlar vardır, Tanrıyı, aşkı, sevgiyi, sevgiliyi kaybettiğimiz, yalnızlıktan, inançsızlıktan kıvrandığımız dönemler vardır, lekesiz bir aşk ancak böyle bir boşluğun, yalnızlığın, böyle bir kıvranmanın içinden doğar. 

Kaybetmenin acısını yaşamadan, kazanmanın lekesiz sevincini yaşamaya izin vermiyor Tanrı. 

Ve böyle bir dönemde yeni bir hayatı, yeni bir aşkı kazandığımız anda da, geleceğimize giden yolda yeni bir dar kapı örmeye başlarız.

Ne yapmalıyız? 

Dar kapılardan nasıl geçmeliyiz? Yaşayamamanın acısını mı, gölgeli bir geleceği kucaklamanın hüznünü mü tercih etmeliyiz? 

Duyduğumuz istekler, tutkular, aşklar, geleceğin ruhumuza uzanan gölgelerini silmeye, bizi iyileştirmeye yeter mi? 

Dar kapılardan geçemediğimiz, yaşayamadığımız için pişman olacağız. 

Bizi bekleyenin pişmanlık olduğunu biliyoruz.

Yaşadıklarımızdan olmayacak pişmanlığımız, yaşamadıklarımızdan olacak. 

Gide''e, Costant''a, Daudet''ye bir sormalıyız ne yapmamız gerektiğini.

Ama onlar bize yalnızca, yaşayamamanın acısını anlatıyorlar. 

Nasıl yaşayacağımızın cevabını gene kendimiz bulacağız. 

Bu dar kapılardan nasıl geçeceğimizi kendimiz öğreneceğiz.

Öğrenebilirsek eğer...', 'Andre Gide, Dar Kapı isimli kitabında, yaşanılanın değil yaşanılmayanın hikayesini anlatır; birbirlerini seven iki insanın bir türlü bir ara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altan']::text[], 8.5, '{"poet":"Ahmet Altan","poet_slug":"ahmet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/dar-kapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanı Durdur', 'zamani-durdur-ahmet-altan-a0jw1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer bir alıcı çıksaydı, bir şeytan mesela, ne karşılığında satardınız ruhunuzu, ne karşılığında cehennemlerde yanmaya razı olurdunuz? 

Bir volkan gibi, içi çağıldayan çılgın alevlerle dolu olduğu halde aynı zamanda bir selvi ağacı kadar da huzurlu olan bir aşkı, böyle bir mucizeyi, bir tek gün zerdali çiçeklerinin döküldüğü gizli bir bahçede, bir sevgiliyle yaşamak karşılığında satar mıydınız ruhunuzu? 

Parlak beyaz duvarları floresan lambalarının sert ışıklarıyla aydınlanmış bir laboratuvarda bir geceyarısı kan çanağına dönmüş gözlerinizle mikroskobunuza bakarken, kanserin çaresini keşfetmek karşılığında atar mıydınız ruhunuzu ateşlere? 

Bir sabaha karşı, askerlerin dipçiklerle kapıları kırıp evlere girerek insanları taradığı bir darbenin liderliğini yapan, insanları darağaçlarına, zindanlara sürükleyip korkutan, herkesin karşısında titreyerek selam durduğu bir general olma karşılığında vazgeçer miydiniz ruhunuzdan? 

Bütün dünyanın soluk soluğa seyrettiği bir film çekebilme yeteneğinin size bağışlanması, ruhunuza biçtiğiniz fiyatı karşılar mıydı? 

Yoksa ruhunuzu hiç bir bedel karşılığında satmaz mısınız, sakin bedeninizin içindeki sakin ruhunuzla, hiçbir değiş tokuşa razı gelmeden mi sürdürmek istersiniz ömrünüzü? 

Ruhunuzu, hiçbir bedel karşılığında satılmayacak kadar kıymetli mi buluyorsunuz? 

Yoksa ruhunuzu satmaya razısınız da, korkularınız mı buna engel oluyor? 

Goethe, kimine göre gelmiş geçmiş en zeki insan, Faust''u ''ruhunu satmak'' üzerine yazmıştı. 

Doktor Faust şeytanla yaptığı pazarlıkta, ''şimdi zaman dursun'' diyecek kadar mutlu olup, ''zaman dursun'' dediğinde ruhunu şeytana satacaktı. 

Siz, nasıl bir anda ''zaman dursun'' derdiniz? 

Sizi, geriye kalan ömrünüzü aynı anın içinde geçirmeye razı edecek kadar mutlu edebilecek olay nedir? 

Hayatınızın filmini hangi karede dondurmak isterdiniz? 

Hangi kareyi dondurmak için ruhunuzu satardınız? 

Geçmişinizde var mı böyle bir an? 

Yoksa böyle bir anın sizi gelecekte beklediğini mi hayal ediyorsunuz? 

Ruhunuzu satmak için şeytanla pazarlık eder miydiniz? 

Ya şeytan, o kötü melek, sizin ruhunuzu satın alınacak kadar değerli bulur muydu? 

Ülkenizi, darbeci generallerden korkmayacak kadar güçlü bir ülke yapmak için satar mısınız ruhunuzu, ya da insanların birbirini öldürmediği bir ülke yapmak için? 

Bir kadınla seviştiğiniz anı mı sonsuza kadar uzatmak istersiniz, yoksa sevgilinizin size yaslanıp ''seni seviyorum'' dediği anı mı? 

Doktor Faust ''şimdi zaman dursun'' diyecek kadar mutlu olmadı hiç, ama şeytan gene de onu oyuna getirip ruhunu aldı. 

Zamanın durmasını istememizi sağlayacak kadar mutlu olduğumuz anlar var mıdır? 

En mutlu olduğunuz an bile, ''gelecekte belki daha da mutlu olacağım bir an olur'' ümidiyle zamanın akmasını ister miydiniz? 

Ruhunuzu, sonsuza dek sürecek mutlu bir an karşılığında satar mıydınız? 

Goethe mi, Faust mu yoksa şeytan mı olmak isterdiniz? 

Herkesin ruhunu satın alabilecek bir şeytan olma karşılığında satar mıydınız ruhunuzu? 

Mutluluklar karşılığında ruhumuzu almak için böyle kötü bir melek neden var acaba? 

Niye mutlulukla kötülük ya da mutlulukla şeytan arasında hep bir ilişiki var gibi? 

Neden iyilik melekleri bize huzuru, kötülük melekleri mutluluğu sunuyor? 

Neden huzur ve mutluluk, mutluluk ve iyilik bir araya pek gelmiyor? 

Neden dalgalı bir okyanustaki yalnız bir deniz feneri gibi, mutluluk, huzursuzluklarla kötülüklerin arasında çakıyor? 

Neden mutsuzluğa ulaşmak için muhakkak şeytanın pelerinine sürtünmek gerekiyor? Ve neden şeytan bir mutlu an karşılığında hemen ruhumuzu almak istiyor? 

Neden Tanrı, melekleriyle birlikte şeytanı da gönderdi bize? 

Şeytanın dokunmadığı bir mutluluk, günahın değmediği bir aşk var mı? 

Ne karşılığında satarsınız ruhunuzu? 

Kim olmak ve ne olmak için? 

Sezar''ın Kleopatra''yla yattığı ilk gece karşılığında mı, Lenin''in Moskova''ya girdiği an karşılığında mı, Arşimed''in ''Evraka'' diye bağırdığı an karşılığında mı, Joyce''un ''Ulysses'' romanının son satırını da düzeltip kalemini bıraktığı an karşılığında mı, Mark Spitz''in olimpiyatlarda yedinci altınını da boynuna taktığı an karşılığında mı? 

Yoksa Karındeşen Jack olmak karşılığında mı? Tarihe geçen o ünlü katil gibi hiç yakalanmadan yedi cinayet işleyip yedi insan öldürebilmek karşılığında satar mısınız ruhunuzu? 

Peki Einstain olmak karşılığında? 

Ruhunuza biçtiğiniz bedel ne? 

Mutluluk mu, şöhret mi, başarı mı, yaratabilme yeteneği mi, insanlara ayrdımcı olabilme gücü mü, yakalanmadan cinayet işleme şansı mı? 

Yoksa para mı istersiniz? 

Ruhunu milyarlar karşılığında satan, geçmişi günahla dolu o büyük zenginlerden biri olmak karşılığında vazgeçer misiniz ruhunuzdan? 

Güney Afrika''da Zencileri kırbaçlayarak öldürten bir elmas madeni sahibi, işçilerin üzerine benzin sıktırıp yaktıran bir dolar milyarderi olmak fiyatınızı karşılar mı? 

Paralarınızla çeşit çeşit hayatlar alırsınız. İnsan hayatları. 

Küçük oyuncaklar gibi oynarsınız onlarla, isterseniz kırıp atabilirsiniz, isterseniz bir biblo gibi odanızın bir köşesine koyabilirsiniz. 

Kadınlar için ayrı bedeller de var tabii.

Bir kraliçe olmak mı ruhunuzu alabilir, yoksa erdemini hiç kaybetmeyen Roma''nın kutsal orospusu olmak mı? 

Her gece bir yaveriyle yatıp ertesi sabah yattığı adamı idam ettiren bir imporatoriçe olmak mı yoksa Nobel''i alan ve hayatı laboratuvarlarda geçen bir Madam Curie olmak mı? 

Yoksa sadece bir evliliğe mi satarsınız ruhunuzu? 

Güvence mi istersiniz, çılgınlık mı? 

Kadınlar, ah onlar erkeklerden akıllıdır, güvenceli bir çılgınlık isterler.

Şeytanın bile veremeyeceğinin peşindedir onlar.

Şeytan da, onun için, onların peşinde. 

İmkansızı isteyeni kandırmak ister o.

Ve şeytan çok şanssızdır, imkansızı isteyeni kandırmak için elinde erkekler gibi beceriksiz aletler vardır. Zaten o yüzden, parayı, mücevheri, şöhreti pazarlığa ekler. 

Kadınlar kim olmak karşılığında satar ruhunu? 

Bütün bir ülkeyi ayaklandırıp sonra yağlı kütüklerin üzerinde yakılan Jeanne D''Arc mı, yüzünde hep büyülü bir ışıkla dolaşan Greta Garbo mu, Evita Peron mu? 

''Zaman dursun'' diyeceğiniz kadar mutlu bir an için satar mısınız ruhunuzu? 

Şeytanla ne karşılığında pazarlığa oturursunuz? 

Hiç yalan söylemeden yaşayabilmek mesela.

Yoksa söylediğiniz her yalana insanların inanması mı? 

Korkularınızdan kurtulacağınızı söylese şeytan, verir misiniz ruhunuzu? Bir daha hiç bir şeyden, hiçbir şekilde korkmamak. Ailenizden, sevgililerinizden, dostlarınızdan, düşmanlarınızdan, polislerden, katillerden, hırsızlardan, size doğru yolu göstermek isteyenlerden, size yardım edenlerden, size kızanlardan ve sizi sevenlerden korkmadan yaşayabilmek için vazgeçer misiniz ruhunuzdan? 

Hiç endişesiz yaşayabilmek, nasıl bir fiyat? 

Bir ülkeyi ya da bir insanı kurtarmak için satar mısınız ruhunuzu? 

Goethe, Faust''u neden yazdı acaba? 

Şeytanla pazarlık fikrini ona kim verdi? 

Gördüğü insanlar mı? 

Acaba herkes sürekli şeytanla pazarlık mı ediyor, sürekli satılıyor mu ruhlar, satmayanlar fiyatı beğenmeyenler mi yalnızca, yoksa korkaklar mı ya da çok cesur olanlar mı? 

Ruhunuzu satar mısınız? 

Yoksa daha önceden sattınız mı? 

Nedir fiyatınız? 

Zerdali ağaçları mı, laboratuvarlar mı, emrinize amade ordular mı, lüks kerhaneler mi, saraylar mı, yazı masaları mı, yaldızlı yataklar mı, yakalanmayan cinayetler mi? 

Zamanın durmasını isteyeceğiniz kadar mutlu bir an oldu mu hayatınızda? 

Her mutlu anda şeytanla pazarlık mı var acaba? 

Tanrı, şeytanı niye yarattı? 

Goethe niye yazdı Faust''u? 

Siz ruhunuzu satmaktan mı, yoksa ucuza satmaktan mı pişmansınız? 

Yoksa hiç satmamaktan mı? 

Zamanı durdurmak ister misiniz? 

Yoksa zaman mı sizi durdursun istersiniz?', 'Eğer bir alıcı çıksaydı, bir şeytan mesela, ne karşılığında satardınız ruhunuzu, ne karşılığında cehennemlerde yanmaya razı olurdunuz?  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altan']::text[], 8.5, '{"poet":"Ahmet Altan","poet_slug":"ahmet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/zamani-durdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem''den Selamlar', 'cehennem-den-selamlar-salih-ozalasan-e6x2m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cehennemde olmak bile güzel

Böyle rezil bir Dünya''da yaşamaktan

Günahını çekiyorsun hiç olmassa

Bıktım bu Dünya''da günahsız yanmaktan

Yalancı riyakar iki yüzlü

Bir pula adam satan insanlardan

Burada sadece yanıyorsun

Kİmse vurmuyor insana arkadan

Kimse kazmıyor durmadan kuyunu

Yanmak değiştirmiş herkesin huyunu

Yan bakalım sana az bile Salih

Sen kendin yazdın bu filmin sonunu

Cehennemde yanmak senin son hakkın

Sen her gördüğünü kendin gibimi sandın

Belanı buldun belaydı nede olsa lakabın

Herkesede nasip olmaz yinede çok şanslısın

Ölmeden cehennemide tattın

Dünya sana artık olmaz nasip

Sen artık cehennemin dibine battın

Y.Tarihi 27-08-2002  saat 13.30', 'Cehennemde olmak bile güzel Böyle rezil bir Dünya''da yaşamaktan Günahını çekiyorsun hiç olmassa Bıktım bu Dünya''da günahsız yanmaktan Yalanc...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cehennem-den-selamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Güller', 'mavi-guller-erol-sen-3cgab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güllerin rengi sevgiyi anlatıyorsa

Yorumlar bana ait gülleri bağlamaz

Yada okuyan arkadaşları

Yine de hepsi çiçek severim sevgi çiçeklerini

Beyaz güller saflığa

Kırmızı güller senin için ölüyoruma

Sarı güller ayrılığa 

Soman rengi saygıya

Mavi güller şiirin adı en güzeli

Hayallerimi anlatıyor bu renk

Yaşamın sadeliğini nefes almayı

Ölen sevgilere sünger çekmeyi öğretiyor

Aşkın ölüme eş değer olmadığını

Duru sakin yaşamın bile beni sıkacağını

Manevi değerlerin herşeyin üstünde olduğunu

Sevgiyle maviliklere...

27.08.2002', 'Güllerin rengi sevgiyi anlatıyorsa Yorumlar bana ait gülleri bağlamaz Yada okuyan arkadaşları Yine de hepsi çiçek severim sevgi çiçeklerini ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mavi-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahroluyorum', 'kahroluyorum-sair-karagozlum-lef2x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazik kendime aciyorum

üzüntümden kahroluyorum

Neden hep beno bulur 

dost dedigim sirtimdan vurur

Kirilir kalbim üzüntüden

agitlar yagar gökyüzünden

yüregime tas gibi oturur

icimdeki nefretle bogusur

gözüm görmek istemez kimseyi

derdimi anlayan olmaz hissetmeyeli

kalbim paramparca olur

parcalar sadece nefretle doludur

Bahrima dost diye bastim

yardimlarimi esirgemedim

iyi yasamani istedim

saf kalbimi kullandin

beni sevdigimle aldattin

Bitti! 

artik dost diye birsey kalmamis

dostluk düsmanlarin yalaniymis

güvencim kalmadi insanlara

ben kullanildim ne gibi zararlara

yandim alev alev yanginlarda

Dost diyenden kork

aslinda dostluk artik yok

düsmanlarim ise cok

Ben aslinda yavrularima yaniyorum

her gece üzüntümden agliyorum

günlerim bir kabus gibi gelip geciyor

cehennemde yasar gibi beni yakiyor.

Ne cileler cektim

ne günler yasadim

insanlarda hep aldandim

göreceksin

sevdigim yine dönüp dolasip bana gelecek

ac susuz ölecek

mezara kendini diri diri gömecek

ardindan bir dua edeni bulamayacak

ateslerde yanacak 

benim oldugum gibi kül olup bitecek.', 'Yazik kendime aciyorum üzüntümden kahroluyorum Neden hep beno bulur  dost dedigim sirtimdan vurur Kirilir kalbim üzüntüden agitlar yagar gök...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kahroluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenin Ardından', 'gidenin-ardindan-nurullah-aydin-9acya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine gönlüm hazan mevsiminde

Ne sevdiğim belli, ne de sevildiğim, 

Mutluluk yine doyurmadan gönlümü

Çekip gitti uzak diyarlara

Yalnızlığımla kaldım gecelerde....

Artık ne bir ses var beni neşelendiren

Ne de sıcak bir gülümseme başımı döndüren

Bir hayalim var kavuşamadığım, yanıbaşımda...

Bir de sigaramın dumanı içimde, 

Her nefes çekişimde acıyla doluyorum...

Ve haykırıyorum karanlığa

O''nu çok seviyorum......

Nurullah AYDIN-06.06.2002', 'Yine gönlüm hazan mevsiminde Ne sevdiğim belli, ne de sevildiğim,  Mutluluk yine doyurmadan gönlümü Çekip gitti uzak diyarlara Yalnızlığımla...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidenin-ardindan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nurullah-aydin-eucvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son bir kez tut ellerimi

Sıcaklığın sarsın yine tüm bedenimi

Titreyen ellerim, bırak anlatsın sana

Seni ne kadar çok sevdiğimi...

Gecelerde başlayan aşkımızın kıvılcımları

Yanıp köz ateşe dönüşmesin

Düşürme bu ateşi yüreğime...

İstersen inciler dizeyim yoluna

İstersen sırmalar takayım koynuna

Yatağımı güllerle donatıp seni alayım koynuma....

Gitme... Ne olur....! ! 

Nurullah AYDIN - 06.06.2002', 'Son bir kez tut ellerimi Sıcaklığın sarsın yine tüm bedenimi Titreyen ellerim, bırak anlatsın sana Seni ne kadar çok sevdiğimi... Gecelerde ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Aydın']::text[], 8.5, '{"poet":"Nurullah Aydın","poet_slug":"nurullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gitme-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Gururum', 'buyuk-gururum-sair-karagozlum-gra73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deli gönlüm feryad eder

acisi büyüktür düsman gördügü yari ister

kahrolasi büyük gururum engeldir

kalbim zafere yenik düser.

Isyanim kendime söyledigim sözlere

düsünmeden ettigim büyük yeminlere

gururum kabullenmek istemez bu gercegi

kalbim korkutur, 

gönlüm görmek istemez gelecegi

Sen basimin belasi derdimin dermani

En hasas yerimden vuran

beni benden eden yalan

ben zavallim senin hayallerini kuran

seni düsünen

senin gibi birisi icin aglayan

Kahrolasi gururum yalanlar askim

kabullenmek istemez bu gercek masali

büyük gururum kendisini öfkesinden parcalar

ne yazik ki yarasi ascisindan kanar.

Acimi unutmak icin careyi fallarda ararim

Kendimi avutmak icin yalanlara kanarim

bakilan fallarim dogruyu söyler

dostlarim cizilmis olan kaderime güler.

Kafam karma karisik istemez onu

Kalbim kararsiz bekler bu maslin sonunu

yalan dolan bu oyun sürer

farkinda olmadan aradan yillar gecer.

Fallar korkutur beni

sakin ondan der gibi

Iste, 

ben zavallim düsmüsüm bir tuzagin icine

maslin kahramani ve kaderin elinde, 

ikiside acimadan duygularimla oynarlar

bu masum zararsiz kalbime kiyarlar

gerceklesmeyen bu masal

belkide kurulan bir hayal

masalin kahramani beni ve kendini sönmez bir atesin icinde yakar.', 'Deli gönlüm feryad eder acisi büyüktür düsman gördügü yari ister kahrolasi büyük gururum engeldir kalbim zafere yenik düser. Isyanim kendime...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/buyuk-gururum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-ercan-gencer-rwstb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde hasretin alev alev 

Yol boyu seni düşündüm 

Koşturdum nefes nefes 

Sana geliyorum... 

Beklesin istemezdim gözlerin 

Acele edişim bu yüzdendi 

Bir değil kaç dağ vararada

Aştım sana geldim gül tanem...

Söz vermiştim bekle demiştim 

Bilirim çok zor beklemek

Nede çok sigara tüketmişsin 

Yolları aştım sana geldim... 

Haydi tut ellerimden sıkıca 

Özlemle sar sinemi sarmala 

Seven engel tanımaz derler ya 

Engelleri aştım sana geldim...', 'Yüreğimde hasretin alev alev  Yol boyu seni düşündüm  Koşturdum nefes nefes  Sana geliyorum...  Beklesin istemezdim gözlerin  Acele edişim b...', ARRAY['Türk Edebiyatı','Şiir','Ercan Gencer']::text[], 8.5, '{"poet":"Ercan Gencer","poet_slug":"ercan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geliyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Olsam', 'kar-olsam-ulker-ozdemir-onaran-bafq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ilkbahar güneşi, 

Ben dağlarda kar olsam.

Bir nisan sabahında

Özlemle kucaklasam.

Akar giderim belki

Çağlayan ırmaklara

Seni de sürüklerim

Sonsuz okyanuslara.

Bir çiğ olurum belki

Ilık aydınlığında.

Buz keserim belki de

Ufka kavuştuğunda.

Bağrımda ışığınla

Boy verir kardelenler.

Sana olan aşkımı

Anlatamaz mevsimler.

 Ülker Özdemir (Onaran)', 'Sen ilkbahar güneşi,  Ben dağlarda kar olsam. Bir nisan sabahında Özlemle kucaklasam. Akar giderim belki Çağlayan ırmaklara Seni de sürükler...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kar-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak da Ağlayayım', 'birak-da-aglayayim-ulker-ozdemir-onaran-uuqju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir daha dönmemek üzere gidiyorsun

Biliyorum...

Artık beni sevmediğini söylemesen de

Anlıyorum...

Çaresiz ellerimi uzatıyorum gözyaşlarımla

Gelmiyorsun! 

Bir dua gibi adını haykırıyorum ardından

Duymuyorsun! 

Hayalini de al, git gözlerimden

Ve...Bırak de ağlayayım

Ne olursun! ..

 Ülker Özdemir (Onaran)', 'Bir daha dönmemek üzere gidiyorsun Biliyorum... Artık beni sevmediğini söylemesen de Anlıyorum... Çaresiz ellerimi uzatıyorum gözyaşlarımla ...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birak-da-aglayayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-ulker-ozdemir-onaran-q4u5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesin geliyor gibi

Uzaktan kulağıma

Kokunu duyuyorum 

Kapıyı açtığımda.

Bazen ayak seslerin 

Yankılanıyor yoldan

Sokağa koşuyorum

Tutmak için omzundan.

Sanki sözlerin gibi

Kuşların cıvıltısı

Havada bir ılıklık

Elini arıyorum.

Bazen senin sevdiğin

Bir şarkı dinliyorum.

Seni delicesine

Özlüyor, özlüyorum.

Daha kaç gün, kaç gece

Geçecek böyle sensiz; 

Gözyaşlarım kaç sele

Dönecek bilmiyorum.

Bir gün çıkıp gelirsen

Anılar arasından, 

Tek şey söyleyeceğim

''Seni çok seviyorum.''

 Ülker Özdemir (Onaran)', 'Sesin geliyor gibi Uzaktan kulağıma Kokunu duyuyorum  Kapıyı açtığımda. Bazen ayak seslerin  Yankılanıyor yoldan Sokağa koşuyorum Tutmak içi...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bazen-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayıyorum', 'sayiyorum-ulker-ozdemir-onaran-rghz1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde bir heyecan

Dönmeni bekliyorum.

Saçlarımda dolaşan

Elini özlüyorum.

Seninle bir oyunda

Saklambaç oynuyorum.

Bulduğumda çınlayan

Sesini dinliyorum.

En son fotoğrafında 

Maziye dalıyorum.

Güzel yıllarımızı

Anıyor, ağlıyorum.

Senle geçen her anı

Tek tek hatırlıyorum.

Kıymetini bilmedim

Ona çok yanıyorum.

Şimdi yapayalnızım

İnan, yaşamıyorum.

Sana kavuşacağım

Yılları sayıyorum

Günleri sayıyorum...

 Ülker Özdemir (Onaran)', 'İçimde bir heyecan Dönmeni bekliyorum. Saçlarımda dolaşan Elini özlüyorum. Seninle bir oyunda Saklambaç oynuyorum. Bulduğumda çınlayan Sesin...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sayiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-ulker-ozdemir-onaran-c82si', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz...

Anlamı kalmadı akşamların

Buruk bir tadı var

O elele gezdiğimiz

İstanbul sokaklarının...

 Ülker Özdemir (Onaran)', 'Sensiz... Anlamı kalmadı akşamların Buruk bir tadı var O elele gezdiğimiz İstanbul sokaklarının...  Ülker Özdemir (Onaran)...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensiz-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ulker-ozdemir-onaran-y7l3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen, mehtaplı gecelerde gördüğüm

En parlak yıldızsın gökyüzünde...

Sen, kirpiklerimde nurdan damlalar

Yerleşmiş bir hayalsin gözbebeklerimde...

Sen, dilimden hiç düşmeyen

Ayetlerin en kutsalısın yeryüzünde...

Sen, boğazımda düğümlenen hıçkırık

İnandığım tek varlıksın her şeyde...

 Ülker Özdemir (Onaran)', 'Sen, mehtaplı gecelerde gördüğüm En parlak yıldızsın gökyüzünde... Sen, kirpiklerimde nurdan damlalar Yerleşmiş bir hayalsin gözbebeklerimde...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-177-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılmamış Yasalar', 'yazilmamis-yasalar-rasih-yilmaz-y8z6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içimdeki bütün gizli fısıltıları

bir çelik kafese koyacağım

uçuracağım gökyüzüne

kurban edilişlerini bekleyeceğim bulutların

/aşkın deli gömleğini giydirdiğin ben

kurtulacağım sana dair mecburiyetlerden/

soyut ‘im’lerin peşini bırakıp

gerçeğin değirmeninde öğüteceğim belirsizliğini

ve

yazılmamış yasalara mahkum edeceğim seni', 'içimdeki bütün gizli fısıltıları bir çelik kafese koyacağım uçuracağım gökyüzüne kurban edilişlerini bekleyeceğim bulutların /aşkın deli göm...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yazilmamis-yasalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyde Sen', 'herseyde-sen-ulker-ozdemir-onaran-vr98p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün hayat güzelse

Senin varlığındandır

Sen olduğun içindir

Yüzümdeki tebessüm.

Gözlerim gülüyorsa

İnan mutluluktandır

Sevdiğim için seni

Huzur doludur gönlüm...

 Ülker Özdemir (Onaran)', 'Bugün hayat güzelse Senin varlığındandır Sen olduğun içindir Yüzümdeki tebessüm. Gözlerim gülüyorsa İnan mutluluktandır Sevdiğim için seni H...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/herseyde-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darıldım', 'darildim-ulker-ozdemir-onaran-l4wxc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirler yazdım sana

Mısralarda ağladım.

Okur, gelirsin diye

Şiirleri ağlattım.

Şarkılar tuttum sana

Nağmelerde yalvardım.

Duyar, seversin diye

Şarkıları yalvarttım.

Fallar baktırdım sana

Fincanlara sarıldım.

Ne geldin ne de sevdin

Falcılara darıldım.

 Ülker Özdemir (Onaran)', 'Şiirler yazdım sana Mısralarda ağladım. Okur, gelirsin diye Şiirleri ağlattım. Şarkılar tuttum sana Nağmelerde yalvardım. Duyar, seversin di...', ARRAY['Türk Edebiyatı','Şiir','Ülker Özdemir (Onaran)']::text[], 8.5, '{"poet":"Ülker Özdemir (Onaran)","poet_slug":"ulker-ozdemir-onaran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/darildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gümüş Bir Yürek', 'gumus-bir-yurek-rasih-yilmaz-hnabt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sensizliğin ölümcül yokluğuna işledim, yalnızlığını

ardından zamanın yüzünü boyadım düşlerimle

hep altın sarısı zamanlarını ezdim aşkın

şimdi bizim için gitme vakti

sürgüyü çek ve çık

yine de

bekliyeceğim seni

güzel kadınlar ülkesinin akasya kokulu şehrinde

unutma

sürekli düşler dolaşacak etrafımda

ve gümüş bir yürek taşıyacağım senin için', 'sensizliğin ölümcül yokluğuna işledim, yalnızlığını ardından zamanın yüzünü boyadım düşlerimle hep altın sarısı zamanlarını ezdim aşkın şimd...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gumus-bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-rasih-yilmaz-uo8yr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'öyle bir kabustu ki

sen yoktun…

hasret yanımıza değil, 

tam içimize düşmüştü..

ölümün girdabına kapılıyorduk

sen acı içinde

ben sensizlikte

yavaş yavaş çürüyorduk

düşen ilk yaprak senin

ardından benim oluyordu

sen solarken başka topraklarda

ben sensiz ölüyordum', 'öyle bir kabustu ki sen yoktun… hasret yanımıza değil,  tam içimize düşmüştü.. ölümün girdabına kapılıyorduk sen acı içinde ben sensizlikte ...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruzgar-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bilet', 'son-bilet-rasih-yilmaz-brmqf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'boşluk umarsızca akıyor üzerime..

zaman çöplüğünde attığım adımlar, 

kaosun habercisi

iç ayarları bozuluyor masumluğumun..

/karanlık; savruk bir kurşun olup, 

düşler için işkence odaları kuruyor../

yığılıyor üst üste sensizlik

yüzler kaybolurken bilinmezlik girdabında, 

tozlu gözler sıvanıyor üstüme..

ve son bileti ben kesiyorum, 

ölüm şehrine…', 'boşluk umarsızca akıyor üzerime.. zaman çöplüğünde attığım adımlar,  kaosun habercisi iç ayarları bozuluyor masumluğumun.. /karanlık; savruk...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-bilet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanmak', 'uyanmak-rasih-yilmaz-ve65v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ahşap bir çatı altında

ikindi vakti

yokluk çanıydı

beni sensizlikten uyandıran

-ki ben 

o zaman kelimelerle eritiyordum düşlerimi', 'ahşap bir çatı altında ikindi vakti yokluk çanıydı beni sensizlikten uyandıran -ki ben  o zaman kelimelerle eritiyordum düşlerimi...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyorum', 'kaniyorum-rasih-yilmaz-o3rk2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adıma çekilmeyen hasretleri düşünürken

beynim eriyor

suçu yaşıyorum

seninle birlikte şehvetin kafasına 

bir kurşun sıkıyorum

ölüyor…

ve sensizlik kalıyor bir tek geride

karanlığa gömülüyorum

yokluyorum varlığını

fark ediyorum

bir incir yaprağı örtüyor

gözlerim kanıyor

erdemi kaybediyorum

yine de yoksun…', 'adıma çekilmeyen hasretleri düşünürken beynim eriyor suçu yaşıyorum seninle birlikte şehvetin kafasına  bir kurşun sıkıyorum ölüyor… ve sens...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-rasih-yilmaz-hi9zi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sesin 

öldürülmüş zamanlarda 

kısık bir yaşam vaat ederken bana, 

kanayan düşlerime nisbet

gözlerimin önünde raks ediyordu..

boşluğa senin için attığım her çentikte 

zihnime

siyah-beyaz bir hiçi resmediyordu..', 'sesin  öldürülmüş zamanlarda  kısık bir yaşam vaat ederken bana,  kanayan düşlerime nisbet gözlerimin önünde raks ediyordu.. boşluğa senin i...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ses-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfrengi Bakışlar', 'kufrengi-bakislar-rasih-yilmaz-fb37w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gamzelerinde dolaşırken senin

sokaklarda uğursuz bir karmaşa yaşanıyordu

baharın damlamasını beklerken cümlelerime 

mezarlıkları yeniden ölüyordu şehrin 

/ sonu olan öykülerden birisinin kahramanı sanarken kendimizi

şekilsiz bir deniz karanlığında boğuluyorduk /

cüzamlı bir ayrılıktı bu 

ve biz

küfrengi bakışlara gömülüyorduk', 'gamzelerinde dolaşırken senin sokaklarda uğursuz bir karmaşa yaşanıyordu baharın damlamasını beklerken cümlelerime  mezarlıkları yeniden ölü...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kufrengi-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye…', 'hikaye-rasih-yilmaz-ibjt7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sorumsuz bir akşam yüzü tablosunda

ellerine tutuşturulmış an bakışı günahı

olmayan geleceklerin mavisi

sen benim için

isimsiz bir zaman kaymasısın

beynimdeki sirenler emzirirken yarasa geceleri

namluya verilen kurşun gülüşünde 

sen ölümün sessiz elçisi

bir dokunuşun can alan bedelisin

omurgasız aşkların yaşandığı hayata inat 

şiirin toprağa düşmediği zamanlarda 

sen kristal güllerin prensesi

bitiremediğim hikayelerden birisisin', 'sorumsuz bir akşam yüzü tablosunda ellerine tutuşturulmış an bakışı günahı olmayan geleceklerin mavisi sen benim için isimsiz bir zaman kaym...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hikaye-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düne ait…', 'dune-ait-rasih-yilmaz-fsg2f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'züleyha’nın şehvetinde kaybolan aşk, 

bekaretini verirken bir piramite 	

sensizliğin kapıları o zaman kapanıyordu yüzüme…

keskinliği bıçağın bölemezken acıyı, 

kan meyvaya düşerken, 

ölümü görmekten utanan bir mumyaydı; 

ismi konulmamış bakışların yollarını kesen…

anladım ki

güzelliğin gölgesinde mısır efendisinin 

hiç çizilmemiş bir gravür figürü uysallığında 

beklerken sıramızı

bugüne yarına değil

düne aitti seni kaybedişim…', 'züleyha’nın şehvetinde kaybolan aşk,  bekaretini verirken bir piramite 	 sensizliğin kapıları o zaman kapanıyordu yüzüme… keskinliği bıçağın...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dune-ait-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktı', 'askti-rasih-yilmaz-v7x9w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sustum suskunluğuna bölündüm…

konuştum gerçeğiyle çarptı beni..

ve seninle kurduğum ilk düşte 

beni benden çıkardı

ardından toplamımızın bir hiç olduğunu gösterdi

aşktı…

anladım ki zamansızdı', 'sustum suskunluğuna bölündüm… konuştum gerçeğiyle çarptı beni.. ve seninle kurduğum ilk düşte  beni benden çıkardı ardından toplamımızın bir...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zifaf', 'zifaf-rasih-yilmaz-66p8m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uyandırmaya kıyamadığım sabahların gizi

celladı oldu masumluğumun 

rutubetli yaşamların

inançsız mundar günahları 

labirent aşkların çıkmazında 

kaosa açtı kapılarını

kötürüm bir zifaftı

aşkın volkanında yaşanılan

aç gözlerini bak

senden önce bendim

cehennem teneşirine yatırılan', 'uyandırmaya kıyamadığım sabahların gizi celladı oldu masumluğumun  rutubetli yaşamların inançsız mundar günahları  labirent aşkların çıkmazı...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zifaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koza', 'koza-rasih-yilmaz-jt1ed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'düş yüklü zamanlarda kovaladım sensizliği dila

seninle yaşanan bütün başlangıçların bir son olduğunun bile bile..

hiçbir beklentim yoktu varlığına gönderdiğim tebessümlerde

aslında gümrah bir annenin çocuğuna sunduğu

bakir yağmur kokusuydu aşk

yine de yoktum

gözlerinde hiç sabah olmadı gecelerimin

-ki ben hep gün doğumunu beklerdim…

gözlerinin akına yerleştiremedim

düşlerimizin bize sunduğu yarınları

bahçene ise ne bir gül dikebildim

ne de nemli bir tohum oldum toprağının

kelebek kanadındaydı varlığım ve seninle üç günlük bir ömür

biçilmişti

-ki sen beni kozamda öldürdün', 'düş yüklü zamanlarda kovaladım sensizliği dila seninle yaşanan bütün başlangıçların bir son olduğunun bile bile.. hiçbir beklentim yoktu var...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/koza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözümsüz Düşler', 'cozumsuz-dusler-rasih-yilmaz-jdyvv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölmek için yaşamak gerek dila

sevmek için ise ölmek

yaşamak sevmek ölmek

üç bilinmeyenli bir denklem; sen, ben, aşk…

çözümsüz düşlerin karışık problemiyiz 

gecelerin kirlenmiş karanlığında, sokak

lambalarının altında

umut tüccarlığı yapan

ve yaşlı aşkların sonuncusuyuz; tenleri birbirinden 

uzak…

dila bilemezken ayrılığın içimizde patlayıp yüreğimizde eriyen 

bir gümüş kurşun olacağını

bilemezken ikimizin toplamının bir gerçek olmayacağını

öderken gözlerimiz dudaklarımızın günahını

riyakar sözlerimiz doldururken boşluğunu hayatın, 

unutma

kaybedişlerimiz gerçeğin diyeti olarak yazılacak aşk defterimize', 'ölmek için yaşamak gerek dila sevmek için ise ölmek yaşamak sevmek ölmek üç bilinmeyenli bir denklem; sen, ben, aşk… çözümsüz düşlerin karış...', ARRAY['Türk Edebiyatı','Şiir','Rasih Yılmaz']::text[], 8.5, '{"poet":"Rasih Yılmaz","poet_slug":"rasih-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cozumsuz-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüldaşım', 'gonuldasim-erdal-saricam-8odvg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİLESİN

Gönüldaşım ne haldeyiz duy hele

Dergahtan selamı kestik bilesin

Hiç düşmezdi dilimizden besmele

Onu da duvara astık bilesin

Önce gönül bayrağını indirdik

Sonra yağan hak nurunu dindirdik

İstanbul’u Moskova’ya döndürdük

Fatih camisine kustuk bilesin

Ev değil evlerin yolu da kayıp

“Vay” desem umudun dalı da kayıp

Haktan geçtik hakkın yeli de kayıp

Parmağı batıla bastık bilesin

Bilmem niye böyle dağıldık niye

Bağlıyken yürekten aynı elçiye

Sordular “sancağı nerede” diye

Eğdik başımızı sustuk bilesin

Değişti aşığın sazı değişti

Oğlanı değişti kızı değişti

İmam efendinin sözü değişti

Ezanın sesini kıstık bilesin

Belli değil baharımız yazımız

Görmez oldu hakkı gönül gözümüz

Camilerin dışındadır dizimiz

İbadet ehline küstük bilesin

Sarıçam yiğitler çevrildi muma

“Höst” desen başları girecek kuma

Vallahi itiraf zor iştir ama

Yel olduk çöllere estik bilesin

ERDAL SARIÇAM', 'BİLESİN Gönüldaşım ne haldeyiz duy hele Dergahtan selamı kestik bilesin Hiç düşmezdi dilimizden besmele Onu da duvara astık bilesin Önce gön...', ARRAY['Türk Edebiyatı','Şiir','Erdal Sarıçam']::text[], 8.5, '{"poet":"Erdal Sarıçam","poet_slug":"erdal-saricam","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gonuldasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ardimda', 'ardimda-ozgen-balci-kclev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ardim da ben  aslinda 

yarali sairlere siir olsun diye 

acemi  bir  asigin 

bir  turlu yazamadigi  o kenti  biraktim

............omrumu biraktim ben ardimda 

daha  savunmasi  yapilmamis 

                           

                    ozgen  balci / london  /2000', 'ardim da ben  aslinda  yarali sairlere siir olsun diye  acemi  bir  asigin  bir  turlu yazamadigi  o kenti  biraktim ............omrumu bira...', ARRAY['Türk Edebiyatı','Şiir','Özgen Balcı']::text[], 8.5, '{"poet":"Özgen Balcı","poet_slug":"ozgen-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ardimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım Yalnızlardayım', 'yalnizim-yalnizlardayim-abdullah-karaduman-z5rdv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret içimde kör düğüm, yüreğimde taş

Her gün aynalarda gördüğüm, gözlerimde yaş

Yokluğun ölümden daha zor geliyor bana

Al beni bu cehennemden, susadım sana

Yalnızım yalnızlardayım, 

Sensizim uzaklardayım

Buruşmuş resmin şuan elimde

Her akşam anılarlayım.

Sen gidince dört bir yanıma, çöktü karanlık.

Dön gel artık, inan canıma yetti ayrılık.

Saatler geçmek bilmiyor, 

Uykusuz sabahlardayım.

Mevsim hiç değişmiyor, 

Ben hep sonbahardayım

Yalnızım yalnızlardayım, 

Sensizim uzaklardayım.

30/11/1993

Saat = 04: 30 

Serinyol', 'Hasret içimde kör düğüm, yüreğimde taş Her gün aynalarda gördüğüm, gözlerimde yaş Yokluğun ölümden daha zor geliyor bana Al beni bu cehennem...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yalnizim-yalnizlardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz Aşk', 'caresiz-ask-ahmet-hilmi-tunali-9dp31', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir aşk ki sana duyduğum

Zaman mekan hiç sınır tanımaz

Elemle kederi yoğurduğum

Naciz kalbim bu aşkı taşımaz', 'Öyle bir aşk ki sana duyduğum Zaman mekan hiç sınır tanımaz Elemle kederi yoğurduğum Naciz kalbim bu aşkı taşımaz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hilmi Tunalı']::text[], 8.5, '{"poet":"Ahmet Hilmi Tunalı","poet_slug":"ahmet-hilmi-tunali","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/caresiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Ballanan Bahçe', 'su-ballanan-bahce-edip-cansever-0h31x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mavi rüyalarla dolu göğün kovası

İçinden kana kana içtiğim

Bulut kokulu gelin bohçası

Kısa sanma hayatı koş

Umut dolu bu dirlik kavgasında

Olgun bir kadın şu ballanan bahçe

Bedeller peşin ödenir

Kurumuş boğazında bir yudum suyla

Titrek korku şakacı bir at, içimin eğri ovalarında.', 'Mavi rüyalarla dolu göğün kovası İçinden kana kana içtiğim Bulut kokulu gelin bohçası Kısa sanma hayatı koş Umut dolu bu dirlik kavgasında O...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/su-ballanan-bahce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şebnemim', 'sebnemim-mesut-demircan-vybqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim şebnemimsin

Bir aşk sabahı 

Buruk bir düşten arta kalan

Ellerimde hala kokun 

Ve sıcaklığın yüreğimde

Her sabah gidişinde

Sen benim şebnemimsin

Gözlerimde kalan

Bir güle benziyordu dudakların

Ürkek ceylan gözlerinle

Çıkıp geliyorsun her gece

Ellerinde aşk

Geldiğin yerlere mutluluk doluyor

Yüreğinde yedi veren sevinçler

Seni seviyorum 

Belki sırf bu yüzden

Sen benim şebnemimsin

Titriyorsun

Üşümene veriyorum

Kalbimdeki şömineye biraz daha aşk atıp

Sarılıyorum sana

Ve nefessiz öpüyorum

Gülüyorsun

Aşkın zamanı yokmuş

Kural tanımazmış biliyorsun

Ben seni seviyorum sen gidiyorsun

Gözlerimde senden kalanı görmüyorsun

Sen benim şebnemimsin

Giderken mutlu bir düşten uyarıp beni

Gözlerime buse konduruyorsun

Teşekkür mü bu veda mı

Bilemiyorum

Kalkıyorum

İçimde bir burukluk

Sigara yakıyorum

Güneş doğuyor sen gidiyorsun

Sen benim şebnemimsin

Mutlu bir düşten geriye kalan

Aynaya bakıyorum

Bak ordasın

Kaçıncı gidişindi bu düşlerimden saymadım

Sensiz seni yaşamaya alıştım

Kirpiklerindeki şebnemi fark ediyorum

Bir güle benziyorsun

Ne o sen de ağlıyor musun?', 'Sen benim şebnemimsin Bir aşk sabahı  Buruk bir düşten arta kalan Ellerimde hala kokun  Ve sıcaklığın yüreğimde Her sabah gidişinde Sen beni...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sebnemim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar olsun bana!', 'yaziklar-olsun-bana-abdulhakim-hakkisever-7bv5g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anam beni doğururken, 

Kimbilir nekadar da sevindi.

Nurtopu gibi bir oğlu oldu diye.

Büyüyecek, 

Erkek(!)  olacak diye.

Ne kadar da umut bağlamıştır, 

Oniki yıl aradan sonra, 

Doğurduğu oğluna.

Eğer böyleyse sevgili ana, 

Yanıldın.

Haberin ola.

Çünkü; 

Ne düşündüğün gibi erkek(!)  oldum, 

Ne de bir umut.

Ben günübirlik yaşatılan, 

Makam, mevki, mal, 

Esiri bir evlat.

Filistindekiler, Çeçenistandakiler, 

İlgilendirmiyor artık beni! 

Mazlumlar için, sadece konuşuyorum.

Çıkıpta Erkek(!)  gibi, 

Erkekleşmiyorum.

Dikilmiyorum zalimin karşısına, 

Dilsizlerşiyorum, 

Zalimlerin karşısında.

Haa! 

Bilesin, 

Dinimde diyanetimdeyim.

Günde beş vakiti hiç kaçırmam.

Rahatlatırım kendimce nefsimi.

İçimden geçirmiyor da değilim, 

Anamın istediği erkelik bu muydu? 

Yere batsın, 

Yazıklar olsun bana, benim gibi adama(!) 

Abdulhakim Hakkısever', 'Anam beni doğururken,  Kimbilir nekadar da sevindi. Nurtopu gibi bir oğlu oldu diye. Büyüyecek,  Erkek(!)  olacak diye. Ne kadar da umut bağ...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Hakkısever']::text[], 8.5, '{"poet":"Abdulhakim Hakkısever","poet_slug":"abdulhakim-hakkisever","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yaziklar-olsun-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlılar', 'atlilar-mirzan-sahin-boy77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şafaktan gür sadalarla atlılar geçiyor

Bir nehir iniyor önlerine mor serpintilerle

Bir yol uzanıyor ufuktan sarkmış

Toz dumana bürünmüş o kızıl çizgi

Sanki bir rüya görüyorum

Dağ sırtlarından gölgeler vuruyor

Kamçılar yükseliyor, kamçılar iniyor

Dört nala geçiyor güneşin altından

Kayıyor bir yıldız gibi asumana

Kopan bir çığ gibi ses geliyor

Yıkılıyor tüm haybetiyle semalar

Sanki güneşe yol alıyorlar

Atlılar son kez geçti ufuktan

Yüreğimde bir imlik düğümleniyor

Dem dem düşüyor ızdırap şimdi

Nal sesleriyle halay çeken hayaller

Buz tutmuş diyarlarda bilmem neyler

Vadiler kıraç, çocuklar yetim

Feyz semaveri güz yaprakları gibi

Yağmurlar durulmuş, yağmurlar kuru

Uzun oldu çöllerde su arayalı

Zifirat içinde yorgundur gözler

Atlılar görünmez artık', 'Şafaktan gür sadalarla atlılar geçiyor Bir nehir iniyor önlerine mor serpintilerle Bir yol uzanıyor ufuktan sarkmış Toz dumana bürünmüş o kı...', ARRAY['Türk Edebiyatı','Şiir','Mirzan Şahin']::text[], 8.5, '{"poet":"Mirzan Şahin","poet_slug":"mirzan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/atlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yoktu', 'sevgi-yoktu-mesut-demircan-x4d4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün sevgi yoktu gözlerinde

Bir şeyler arıyordu çevresinde

Her masada her insanda tek tek dolaşıyordu

Bir şeyler arıyordu

Bir tek beni görmeden

Dün sevgi yoktu gözlerinde

Saatlerce baktığım gözler değildi

Manasını yitirmişti

Cümle alem dostuydu ama

Bir tek ben yabancısıydım

Dün sevgi yoktu gözlerinde

Aşk kaybolmuştu zamanın bilinmezliğinde

Ya da ben bulamadım bakışlarında

Dün sevgi yoktu gözlerinde….', 'Dün sevgi yoktu gözlerinde Bir şeyler arıyordu çevresinde Her masada her insanda tek tek dolaşıyordu Bir şeyler arıyordu Bir tek beni görmed...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinmedi', 'dinmedi-mesut-demircan-88npx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç kalemi kırdım

Yargılamalarımın sonunda

Kendim için

Hep suçlu bendim

Hep yüreğimi astım

Şikayet edip durdum

Kendim için tutanaklar yazdım

		İddianameler hazırladım

Savcı bendim hakim ben

Suçluyum dedim hep

Sanık iskemlesinde

Kendim için kırdım kalemleri

		Çekinmedim

Hep yüreğimi astım

Acılarım dinmedi

			(12.05.99/İst.)', 'Kaç kalemi kırdım Yargılamalarımın sonunda Kendim için Hep suçlu bendim Hep yüreğimi astım Şikayet edip durdum Kendim için tutanaklar yazdım...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dinmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-mesut-demircan-3hbfx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalandı sana bütün söylediklerim

git derken hançeri vurup kalbime

kahroluyordum

üzülüyordum gidişine

kal demeyi beceremiyordum

biliyordum aşkta gurur olmaz

ama

sana kal diyemiyordum

gözlerime baksan anlayacaksın

yalandı bütün söylediklerim

git deyişim yalandı

Ağustos ’da yağan kar kadar yalan......

(21.01.2000)', 'yalandı sana bütün söylediklerim git derken hançeri vurup kalbime kahroluyordum üzülüyordum gidişine kal demeyi beceremiyordum biliyordum aş...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalan-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebep Siz', 'sebep-siz-mesut-demircan-iqeg4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sebepsiz olmazdı hiç bir şey

                        ve hiç bir şey sebepsiz değildi.....

Emek isterdi sevgi; 

                        uğraş, alın teri gerekti

Sevgi, bir demet paylaşımıydı yüreklerin

Sevgi karşılık beklemeden vermekti

                           yüreğindeki güzelliği.....

Gülen gözlerle yabancılara, 

                        arayıp sorarak arkadaşlara

                             en güzel sözlerle dostlara

                                ve en sıcak öpüşlerle sevgilimize

                    verdiğimiz o değil miydi......

Sebepsiz değildi hiçbir şey

                ve sebepsiz olamazdı

                    en nadide çiçekler emek isterdi yeşermek için

Sevgi de bir çiçek değil miydi...', 'Sebepsiz olmazdı hiç bir şey                         ve hiç bir şey sebepsiz değildi..... Emek isterdi sevgi;                          uğraş...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sebep-siz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutamazsın', 'tutamazsin-mesut-demircan-gko2j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldırımlar düşer yüreğimden gözlerin tutamaz

Ağır gelir sevgim sana yüreğin incinir

taşıyamazsın

omuzlarında dünden yarına

varolan aşk hikayeleri

hiç biri bana benzemez

hiç biri benim kadar aydınlatamaz

gözlerindeki gülümsemeyi

Yıldırımlar düşer yüreğimden yakar geçer

Gün olur

gözlerinde şebnemlerle

bir bahar sabahı beni hatırlarsın.........

(08.01.2000)', 'Yıldırımlar düşer yüreğimden gözlerin tutamaz Ağır gelir sevgim sana yüreğin incinir taşıyamazsın omuzlarında dünden yarına varolan aşk hika...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tutamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allıgelin', 'alligelin-sair-anonym-no2xd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alligelin pullugelin varmi hic sevenin? 

Yüreginde umutlar ve engelin! 

Yol vermez sana yalcin kayali daglar, 

En iyisi otur yerinde be gelin.

Kaderin bu senin, salla besigin.

Avucunda kurumamis kinan duruyor

Gözünde hayaller ucusuyor, 

Ceylan postunun üstünde kan agliyor! 

Kinaya karismis kani kurumak bilmiyor.

Belki anlamsiz bu siirim, 

Yaziyorum öylesine, gitsin...

Okuyan bulur belki bir cisim, 

Okunacagini bilerek yaziyorum bilinsin!', 'Alligelin pullugelin varmi hic sevenin?  Yüreginde umutlar ve engelin!  Yol vermez sana yalcin kayali daglar,  En iyisi otur yerinde be geli...', ARRAY['Türk Edebiyatı','Şiir','Şair Anonym']::text[], 8.5, '{"poet":"Şair Anonym","poet_slug":"sair-anonym","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/alligelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç Duyarım', 'utanc-duyarim-mesut-demircan-w254h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duygu Hırsızlarına

                

Sahipsiz sözlerin altına bile

Adımı yazmaktan utanç duyarım 

Cansız kelimeler gelirler dile

Sahipsiz değiliz derler duyarım 

Duygu ile yüklenmişler her biri 

Onlarla ağlamış gülmüş şairi 

Şiirlerim hayat gibi dip diri 

Ellere bırakma derler duyarım', 'Duygu Hırsızlarına                  Sahipsiz sözlerin altına bile Adımı yazmaktan utanç duyarım  Cansız kelimeler gelirler dile Sahipsiz değ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Demircan']::text[], 8.5, '{"poet":"Mesut Demircan","poet_slug":"mesut-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/utanc-duyarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Gör Halimi', 'gelde-gor-halimi-unal-akbaba-4a3zq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül sarayimi viran eyledin

 Mor güllü bagimi talan eyledin

 O güzel günleri yalan eyledin

 Ne umut ne güven ne hal kaldi bende

 Sensiz gecelerim sabah olmazdi

 Senden ayri güne günes dogmazdi

 Bagimda gülümdün eller konmazdi

 Simdi bir dikenli dal kaldi bende

 Bülbül idim ayrilmazdim dalindan

 Susardim icerdim ask pinarindan

 Nameler söylerdim o sen gönlümden

 Kirdin gönül sazim tel kaldi bende

 Eserdi rüzgarlar binbir kokuyla

 Sanki konusurdu yaprak daliyla

 Toprak bürünmüsdü yesil haliyla

 Kuruttun bagimi yel kaldi bende

 Ne eyledim söyle gülüm ben sana

 Vurayim basimi kara taslara

 Ne zaman ugrasam bizim pinara

 Caglayib cosarim sel kaldi bende

 20.12.001', 'Gönül sarayimi viran eyledin  Mor güllü bagimi talan eyledin  O güzel günleri yalan eyledin  Ne umut ne güven ne hal kaldi bende  Sensiz gec...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelde-gor-halimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklerim', 'seni-beklerim-unal-akbaba-ee912', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her an geleceksin diye kapiya 

bakar bu gözlerim seni beklerim

Hayalim dönüsür bazen maziye

Döneceksin diye seni beklerim

Sensin benim canim benim bedenim

sendin benim silam simdi gurbetim

Toprak suya bende sana hasretim

Yagacaksin diye seni beklerim

Olmuyor güzelim sensiz olmuyor

Günlerim kederli gecem agliyor

Gözlerimde yassin dolmus akmiyor

Cosacaksin diye seni beklerim

Sensiz bir garibimelim koynumda

Büzülmüsüm sensiz soguk odamda

Gönül günesimsin belki sabahla

Dogacaksin diye seni beklerim

Benim gibi bahtsiz sevenler varmi

Seven bu gönüle zulüm revami

Bu can cikmayinca umut cikarmi

Alacaksin diye seni beklerim

Tatli bir rüyaydi seninle zaman

Kol kola giribte eylerdik seyran

Hicmi sizlamiyor göysünde sinen

Saracaksin diye seni beklerim

 Tah:  16.12.001

  Almanya', 'Her an geleceksin diye kapiya  bakar bu gözlerim seni beklerim Hayalim dönüsür bazen maziye Döneceksin diye seni beklerim Sensin benim canim...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-beklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gider', 'gider-unal-akbaba-3hlwa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdim bir gözü elayi

Ince bel kasi karayi

Acti gönlüme yarayi

El vurmadan cekib gider

Hilal kaslari sürmeli

pamuk elleri kinali

Sanki daglarin marali

Söyle bakib süzüb gider

O edali gülüsleri

Sanki incidir disleri

Tel  tel olmus zülüfleri

Belde durmaz akib gider

Öyle nazli öyle güzel

Görünce yüregim titrer

Bir atesdir cana düser

Sesiz sesiz yakib gider

Kime dersin bu sözleri

Sanki bir tas gönülleri

Baglarinda al gülleri

Derilmeden solub gider

Yaraliyim ben yarali

Bu sevda bahti karali

bir gün seversen ünali

Bu dünyadan göcüb gider

Tah: 28.09.002

 almanya', 'Sevdim bir gözü elayi Ince bel kasi karayi Acti gönlüme yarayi El vurmadan cekib gider Hilal kaslari sürmeli pamuk elleri kinali Sanki dagla...', ARRAY['Türk Edebiyatı','Şiir','Ünal Akbaba']::text[], 8.5, '{"poet":"Ünal Akbaba","poet_slug":"unal-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gider-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayır', 'hayir-arzu-bagriacik-wrc76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardeşim her zaman yakınırdı

Diş gıcırtım yüzünden

Bir sabah uyandığımda 

Sorulan soruya

''HAYIR'' cevabını alınca

Mutlu olmuştum.

Demek ki ben

Huzurluydum

Yolların ötesinde….

2002 Ankara', 'Kardeşim her zaman yakınırdı Diş gıcırtım yüzünden Bir sabah uyandığımda  Sorulan soruya ''HAYIR'' cevabını alınca Mutlu olmuştum. Demek ki be...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-arzu-bagriacik-7klc7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizi nasıl tarif edebilirim ki! 

Sen rüyalara dalarsın

Ben farklı.

O kucaklarmış hep

Kucaklarım

O okşarmış 

Okşayan benim.

Öpermiş sinsice 

Öperim öperim.

O çıldırırmış

Çıldıran benim, 

Kokusundan, 

Varlığından; 

Yoksunum diye…

26.08.2002 Ankara', 'Denizi nasıl tarif edebilirim ki!  Sen rüyalara dalarsın Ben farklı. O kucaklarmış hep Kucaklarım O okşarmış  Okşayan benim. Öpermiş sinsice...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/deniz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabildiğine', 'alabildigine-i-brahim-ozcan-pek94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rengârenk  müzik

deniz batık

rüzgar idamlık

sahil

alabildiğine aydınlık

bir  marmara  zindanlık 

bir de biz                    

o gece biz

biz üçümüz de 

alabildiğine 

yalnızdık...

                                             16 Ağustos  97

                                             C.tesi  21.15 

                                             Erdek Kampı

Yasal Uyarı: İbrahim Özcan''ın bütün şiirleri noter tesbitli olup, izinsiz kullanılamaz,  yayınlanamaz ve ya alıntı yapılamaz;  telif hakları bakımından İLESAM (İlim ve Edebiyat Eserleri Sahipleri Meslek Birliği)   üyesidir.

iletişim  90 536 293 86 38', 'rengârenk  müzik deniz batık rüzgar idamlık sahil alabildiğine aydınlık bir  marmara  zindanlık  bir de biz                     o gece biz b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alabildigine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiir', 'i-simsiz-siir-i-brahim-ozcan-cprn3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsimsiz bir şiir gibi

Öğütüp  başak başak, 

Yaşamın tüm namelerini; 

Zamanın sonsuzluğuna, 

İnce ince dizmek...

Aynı şey değil mi? 

Güzel olan herşeyi, 

Nafile umutlara yem edip; 

Nankörce, ayaklar altında

Kül-ufak edip, ezmek...

Yasal Uyarı: İbrahim Özcan''ın bütün şiirleri noter tesbitli olup, izinsiz kullanılamaz,  yayınlanamaz ve ya alıntı yapılamaz;  telif hakları bakımından İLESAM (İlim ve Edebiyat Eserleri Sahipleri Meslek Birliği Uyesidir.

iletişim  90 533 9262926', 'İsimsiz bir şiir gibi Öğütüp  başak başak,  Yaşamın tüm namelerini;  Zamanın sonsuzluğuna,  İnce ince dizmek... Aynı şey değil mi?  Güzel ol...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isimsiz-siir-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostalji Olmuşlar', 'nostalji-olmuslar-i-brahim-ozcan-uh789', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdanla damlayıp

Şarap çanağıma, 

Gam kasavet dolduran

Yitik şarkılar; 

Artık nöstalji olmuşlar.

Hani vardı ya; 

''İntizar''lar, 

             Beddua''lar..''

Söylerdik, 

Sevda yollarında...

Bir bir sır olmuşlar.

Geçmiş sanki; onca yıllar, 

Uzunca asırlar...

Daha şimdi duymuşlar; 

Yeni yetme aşıklar...

Adını da, 

''Nöstalcik''

             koymuşlar.

Hani vardı ya; 

Yüreğimizden yas, 

Gözlerimizden yaş olup; 

Yıllar yılı akan.

Yeni yetmeleri 

Nöstaljik yakan, 

Karagöz''lü, 

İntizar''lı,             

Beddua''lı                                          

Yitik şarkılar...                                 

                  9.4.1997      03: l0...Bandirma

Yasal Uyarı: İbrahim Özcan''ın bütün şiirleri noter tesbitli olup, izinsiz kullanılamaz,  yayınlanamaz ve ya alıntı yapılamaz;  telif hakları bakımından İLESAM (İlim ve Edebiyat Eserleri Sahipleri Meslek Birliği Uyesidir', 'Sevdanla damlayıp Şarap çanağıma,  Gam kasavet dolduran Yitik şarkılar;  Artık nöstalji olmuşlar. Hani vardı ya;  ''İntizar''lar,             ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nostalji-olmuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İğdeleri, Fesleğenleri de...', 'i-gdeleri-feslegenleri-de-i-brahim-ozcan-ewrdk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşasam yine çocukluğumu; 

Binbir sevgisiyle annemin, 

Toz pembesiyle hayallerimin, 

Korkusuyla karanlık gecelerin.

Çeksin, koparsın yine babam; 

Uykumun, en tatlı derinliğinden.

Göndersin en uzak bahçemize, 

Köyün  ıssız sessizliğinden.

Yine, sımsıkı sarılırdım; 

Bütün kaslarımla kemiklerime.

Usulca taşlar alırdım, 

Korkudan titreyen, ellerime.

Islıklar çalardım; 

             ''Mestana da yavrum mestana''

İçinden geçtiğim kadar yakın; 

Asla gelmeyecekmişim kadar uzak, 

Hüzün-ürperti dolu

                               ''Kabristana''

Geçerdim dikenli çepellerden.

Korkardım yine tepelerden.

Şırıltılarla süzülüp, karanlıkta; 

Kaybolan dikenli derelerden...

Sonu gelirken yavaş yavaş, 

Aysız, uykusuz, gecenin.

Kırıntısı bile dökülmezdi belki, 

Dudaklarından, titrek hecelerin.

Ne olurdu sanki? ...

O günler geri gelse.

Yoğursam çamurları; 

Gever ağzında küreğimle.

Sulasam; kavakları, 

Kaysıları, söğütleri de.

Sulasam iğdeleri, 

Akasyaları, fesleğenleri de...

Burnumda tütüyor şimdi, 

Çocukluğumun kayıp günleri.

Yaşadıkça; gürültülü, betonlu, 

Kokuşmuş çirkinlik dolu; 

Dört duvar arası, 

Yalnız gecen, şehir geceleri...

Özlüyorum, anıyorum her an; 

Kuru Çay''dan, Karaca''dan; 

Akasyaları, kavakları, iğdeleri, 

Kaysıları, söğütleri, fesleğenleri de...

Bir gün öldürecek beni, 

Yalnız gecen, şehir geceleri...

                    

27 Temmuz  1988

KONYA 01; 30

