INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemdağ', 'alemdag-huseyin-asliturk-hqwno', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alemdağ''da bir kız gördüm

Titreyen ellerinin arasında bir gül

Soğuk havada ılık bir nefes gördüm

Titreyen dudakları arasında bir isim

Bir hayatın gittiğini gördüm

Kırpılmayan gözlerin içinden

Alemdağda bir kız gördüm

Gözleri hüzün

Bir kızda kendimi gördüm

Alemdağ''da seni gördüm

Avuçlarımın arasından gittiğini', 'Alemdağ''da bir kız gördüm Titreyen ellerinin arasında bir gül Soğuk havada ılık bir nefes gördüm Titreyen dudakları arasında bir isim Bir ha...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Aslıtürk']::text[], 8.5, '{"poet":"Hüseyin Aslıtürk","poet_slug":"huseyin-asliturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/alemdag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemdağ Gitmeli', 'alemdag-gitmeli-huseyin-asliturk-k371f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alemdağ gitmeliyim

