INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncir Yaprakları', 'i-ncir-yapraklari-behcet-necatigil-bd0ch', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yumuldular uğultular arasında 

İncir yapraklarını artık kim düşünürdü 

Sallanırken iki dalga arasında bir martı 

Bu yatağa, koltuğa, bu kara tahtalara 

Düşmeden önce 

Eksiydi eks
..........
