INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Doğaç Daha', 'bir-dogac-daha-can-yucel-tr80c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bu evi

Bu baba evini

Manolyalarıyla, fıstık ağaçlarıyla, gülibrişimleriyle

Ve televizyonun üstüne asılı Onun resmiyle

Helasının işlemeyen sifonuyla

Kitaplarıyla ve rütubetiyle

Güler''le aşktan her zaman dağınık yatağıyla

Anılar değil, gelecek çocuklarımızın kokularıyla

Ben bu evi saksofon solosuyla yıkıyorum

Duvarların nasıl çökeceğini

Damının göğsüme nasıl ineceğini bile bile

Ben bu evi yıkıyorum Cemil Bey''in bir taksimiyle

Kardeşlerimle taksim edilemeyen bu evi

Yıkıyorum nihaventten bir taksimle

İzale etmek için bir izale-i şuyuyu

Yıldıldı mı bu ev toprağın, kayanın üstüne

Benim tamburumla borazanımla

Görünecek açılan damından

Gündüzleri güneş

Geceleri yıldızlar

Aşkı taksim edilmesin diye bu evin

Cemil Bey''in taksimiyle ben bu evi yıkıyorum

Yıktığımda da yıkıntısı altında değil

Üstümde Güler var

Altımda toprak', 'Ben bu evi Bu baba evini Manolyalarıyla, fıstık ağaçlarıyla, gülibrişimleriyle Ve televizyonun üstüne asılı Onun resmiyle Helasının işlemeye...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-dogac-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denli', 'denli-can-yucel-9vnx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz ki pirinç semaver

En sakin deminde çayın

Çınnnn

Mineli fincan elinde

Kıraathanesine

Yeats ile Pavese''nin

Buyrun...

Dönis ki Güzel''in sevgilisi

Görmedim dişçiymiş keriz

Kıskancımın dalgaları içinden

Kalan iki köpek dişimi

Damat, siz çeker misiniz? 

Deniz ki Güler''le Güzelbahçe''deydik

Patladı Eşek İmbatı

Bu poyraz lekesi, bu liken

Dönünce dehşet lodosa

Huu dedim, huhuu

Secdeyettim laciverdiye

Deniz ki Hemingway''den mürebbiye

Saldı mıydı üstümüne aslanlarını

Göynümüzün en hayvan hayvanat bahçesinden

En LİYON''suz yeleleriyle

Aslan olalım hepimiz

Öfkesiz sevgi

Denizsiz kara

Erkeksiz karı

Eteksiz erkek

Olmayalım

Öyle ölmeyelim diye', 'Deniz ki pirinç semaver En sakin deminde çayın Çınnnn Mineli fincan elinde Kıraathanesine Yeats ile Pavese''nin Buyrun... Dönis ki Güzel''in s...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/denli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyete İlan', 'hurriyete-i-lan-can-yucel-l8t5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava azdı bak, havai mai

Düşüyor üstüme bir semavi

Deterjamanın evren pulları...

Ve teperken tipili yolları

Bir garip uyku görmede rüyam

Olmamak üzre bir daha reklam

Böyleymiş meğer en son yıkanmam...

Çamaşır makinesinde bir adam...', 'Hava azdı bak, havai mai Düşüyor üstüme bir semavi Deterjamanın evren pulları... Ve teperken tipili yolları Bir garip uyku görmede rüyam Olm...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hurriyete-ilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seng-i Derya', 'seng-i-derya-can-yucel-tii13', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daldı gözlerim

Denizin o tirşe ve hareli gözlerine

Derken Poseydon''la beraber

Kaldırıp başlarımızı güneşin

Gülkokusu bacaklarına baktık

Derken martılar geçti

Sıyırarak suları yanımızdan

Karşı sahilde akşamla yanan

Beş pare cama gömmek için bizi...', 'Daldı gözlerim Denizin o tirşe ve hareli gözlerine Derken Poseydon''la beraber Kaldırıp başlarımızı güneşin Gülkokusu bacaklarına baktık Derk...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seng-i-derya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadarcık', 'bu-kadarcik-can-yucel-gllhy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su istemeye geldiler çocuklar

Kumsalda çimerken farımışlar

Mayolarıyla geldiler

En arkada sarışın şipşirin

Olsun olsun dört yaşında bir oğlan

Güler su veriyor onlara

Ben de olsam onlara daha ne verebilirim ki

Musluktan taşan su seslerine karışan

O cıvıl cıvıl seslerini cankulağıylan

		Dinlemekten başka?', 'Su istemeye geldiler çocuklar Kumsalda çimerken farımışlar Mayolarıyla geldiler En arkada sarışın şipşirin Olsun olsun dört yaşında bir oğla...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-kadarcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuyana Rahmet', 'okuyana-rahmet-can-yucel-mmnds', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mitralgözüyle karşı tepelerden

Biçtikçe siyah başaklarını gecenin

Horull uykularımıza kasteden

O tezayaklı eşkıya

Suyolcu Memet Pehlivan

Vadesi doldukta

Güneş müfrezelerinin yaylım ateşiyle

Vuruldu şafakta

Yatıyor şimdi

Rahmet okusak da okumasak da

Kanlar içinde upuzun

Dere boyunda

Eski dölyatağına dönüyor sanki

YAĞMUR', 'Mitralgözüyle karşı tepelerden Biçtikçe siyah başaklarını gecenin Horull uykularımıza kasteden O tezayaklı eşkıya Suyolcu Memet Pehlivan Vad...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/okuyana-rahmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dersi', 'ask-dersi-can-yucel-0zhef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yabancı bir televizyon görüncesinde

Bitkilerin nasıl çiftleştiğin seyrederken ağlıyorum

Derken aklıma geliyor Güler''le ilk seviştiğimiz

Orda da ağladığımı gülerek hatırlıyorum', 'Yabancı bir televizyon görüncesinde Bitkilerin nasıl çiftleştiğin seyrederken ağlıyorum Derken aklıma geliyor Güler''le ilk seviştiğimiz Orda...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-dersi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal Çaresi', 'hal-caresi-can-yucel-1cl8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen bezmimize geldiğin akşam

Neler neler olmaz ki bize, bir güzel haller olur

Hallolur eşek davası dahil, bütün davalar

Düşer İsfahan, yıldızlar, Bağdat ve Şam

Kalkar ayağa ayaklar, türkülerle bir halk olur

Sen bezmimize geldiğin akşam

Kainatın padişahı salavatla hal olur', 'Sen bezmimize geldiğin akşam Neler neler olmaz ki bize, bir güzel haller olur Hallolur eşek davası dahil, bütün davalar Düşer İsfahan, yıldı...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hal-caresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitabesiz Seng-i Mezar', 'kitabesiz-seng-i-mezar-can-yucel-lbz33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz moruna kaptı beni

Getiriyor götürüyor

Zifiri bir laciverdiye doğru...

Dalgalar ki yavaşlayan darbeleri kalbimin

Vuracak ve duracak elbet o ziftli kıyıya

Usuldan usul çırpıntılar halinde...

Denizboku çakıllardır benim mezartaşlarım...', 'Deniz moruna kaptı beni Getiriyor götürüyor Zifiri bir laciverdiye doğru... Dalgalar ki yavaşlayan darbeleri kalbimin Vuracak ve duracak elb...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kitabesiz-seng-i-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşe''ye Sone', 'nese-ye-sone-can-yucel-y38wd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakın gözlüğümü yitirdim 

Yitirince seni kadın- 

Doğumun ardından 

Çatladı kapı sanki 

Öyle uzak bir doğu ki her şey 

Görünmüyor burnumun ucundan 

Çiğnenecekmiş gibi geliyor hep 

Geçerken kıtadan kıtaya 

Ters bir dizeye rastladım demin 

Taburcuymuş, öyle dedi 

Çıkışını yaptırıyormuş acundan 

Lâf! 

Ne sen ne ben sevgilim 

Öldükse ölümden değil 

Sevişmenin acısından', 'Yakın gözlüğümü yitirdim  Yitirince seni kadın-  Doğumun ardından  Çatladı kapı sanki  Öyle uzak bir doğu ki her şey  Görünmüyor burnumun uc...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nese-ye-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nimet', 'nimet-can-yucel-5axxr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir fasulye çimleniyordu

Çiseledikçe yağmur.

Koştum vardım ki yanına

Anlasın ne nimet olduğunu

Sen git yerine! dedi Ayşa Kadın

Böyle kibar erkeyin ayağ’na

Ben kendi ayağ’mnan gelirim

Bu muhabbeti görünce uzaktan

Kıpkırmızı oldu biberiye

Bayram nedir ki dedim kendi kendime

Bayram bir ömürdür ben gibi bir deliye', 'Bir fasulye çimleniyordu Çiseledikçe yağmur. Koştum vardım ki yanına Anlasın ne nimet olduğunu Sen git yerine! dedi Ayşa Kadın Böyle kibar e...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nimet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur İndi', 'nur-i-ndi-can-yucel-tn9tv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kış kışlada kışlar iken

Karakuşi bir yazıylan

Kışkışlanıp, kışkışlanıp

Akkuğulu yazmalarla

İne inmez yazılara

Elif oldu ne demezsin

Teliflerim, teleflerim

Sivil oldu savaşlarım

Onbeş gündür kardı yağdı

Daha da yağacakmış eyvah

Yarına kalmaz görürüm

Bütün çocuklarıyla çocukluğumun

Ve tuşları üzerinde -İLAHİ- bir orgun

Nur baba gibi geçerken Bach

Zeyil

Bu sulu kar ve bu pespaye şiir

Sürerse bu minval üzre

Bizi bilmem ama, aziz karilerim

Gözlerimde hüzünlü ve tütsülü bir tebessüm

Yarına kalmaz, ben, fücceten ölürüm...', 'Kış kışlada kışlar iken Karakuşi bir yazıylan Kışkışlanıp, kışkışlanıp Akkuğulu yazmalarla İne inmez yazılara Elif oldu ne demezsin Telifler...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nur-indi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölemsiz', 'olemsiz-can-yucel-z5nmn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ne şeymiş bu, bu dünyadan ayrılmak

Demir tarar gibisin bigün

Gözlerin arkalarda deryaya açılmak? ''

	Hadi bre gide gide dönmüşlüğüm

	İyadesiz iyadeli tahütlüğüm

	Seni bilem gide koydum, gidi ölüm!', '''Ne şeymiş bu, bu dünyadan ayrılmak Demir tarar gibisin bigün Gözlerin arkalarda deryaya açılmak? '' 	Hadi bre gide gide dönmüşlüğüm 	İyadesi...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olemsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susss-Ma', 'susss-ma-can-yucel-yj5wx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Butün bu cılgıldaklar

Pencerenin ağzına asılı

Bütün bu fırıldaklar

Bütün bu pervaneler

Bütün bu değirmenler

Bütün bu uçurtmalar ve uçaklar

Poyrazın doğrultusunda...

Gülibrişim, mimoza ve manolya, kavak

Yaprakları dahil

Bütün bu kıpır kıpır insanlar

Elleri kolları ve kulaklarıyla

Ve erken öten bir horozun sesiyle

Kaçmışlar öbür dünyaya şimdiden

Seslerini bırakmışlar geriye

Bu ölümlü dünyaya yadigar...', 'Butün bu cılgıldaklar Pencerenin ağzına asılı Bütün bu fırıldaklar Bütün bu pervaneler Bütün bu değirmenler Bütün bu uçurtmalar ve uçaklar P...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/susss-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Sokağa Çıkabilirsin', 'artik-sokaga-cikabilirsin-cezmi-ersoz-pd3du', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evine çağırdın ilkyaz sevinçlerini

çocukluğuna

Yırtıldı gözlerin, içine hayat doldu

o karanlık ışık...

Yükün yok

artık her sabah hoyrat bir özgürlük uyandırıyor seni...

Kalbinde herşey eşitlendi

Haz ve sıkıntı

Boşluk ve güven

Hasret ve ölüm

Gözlerine hastalıklı bir güzellik geldi

Şimdi acı çeken yanınla bile alay ediyorsun...

Kalbine çağırdın herkesi

Kendini bile

Artık sokağa çıkabilirsin

Ömründen düştün kendini', 'Evine çağırdın ilkyaz sevinçlerini çocukluğuna Yırtıldı gözlerin, içine hayat doldu o karanlık ışık... Yükün yok artık her sabah hoyrat bir ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-sokaga-cikabilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Bulun En Zayıf Yerimi', 'hadi-bulun-en-zayif-yerimi-cezmi-ersoz-1de3n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan kendisini merak etmeli; 

hem de ölümüne merak etmeli.

Gün bitti işte...

Kim farkında bunun senden

                        başka...

Herkes bu yenilgiyi nasıl da

                        rahat kabulleniyor...

Vaatlerini tutmadı gün.

Kimse kendisini merak etmedi.

Sabırsızlığın bundan; 

                bundan çocuksu hasretin...

Kabullenince herkes yaşamını

sen ortaya kendini koydun...

ve bütün suçlarını üzerine

                        aldın sonra

Bundan işte

bu çocuksu hasretin

Ve ölümcül bir rulet oynadın

                        insanlarla

hadi dedin, hadi bulun

                         en zayıf yerimi...

Ve diktin gözlerini gözlerine

                        kastın bedenini

                        yükselttin omuzlarını

Öylece kaldın...

Baktılar sana... Baktılar...

Ama yüreğini bir türlü

                            göremediler.', 'İnsan kendisini merak etmeli;  hem de ölümüne merak etmeli. Gün bitti işte... Kim farkında bunun senden                         başka... Her...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hadi-bulun-en-zayif-yerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyadan Uzak', 'dunyadan-uzak-alfred-de-vigny-ns6zc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sızlıyorsa yüreğin dünya gailesinden

Yaralı kartalleyin dönüp duran yerlerde

Tutsak kanatlarında taşıyarak benleyin

Yazılı bir dünya, soğuk ezici hem de

Eğer ancak kanadıkça yaran atıyorsa

Aşkının ışıtmaz olduğunu görüyorsa

O biricik yıldızının o yitik ufkunu

Bu tutsak ruhum gibi senin de ruhun sonra

Usanıp o kulluktan, kara, acı, ekmekten

Tutup o kürekleri bırakmışsa bir yana

Eğilmiş ağlıyorsa sulara bakaraktan

Arayarak uzak bir yol sonsuz dalgalarda

Ve korkuyla omuzunda birden farkedip sonra

O damgayı hani o demirle vurmuşlar

Titriyorsa vücudun giz tutkularla eğer

Üzülüyorsa o kötü kem bakışlardan

Ulu yalnızlıklarda bulmak salt bir yer

Gizlemek güzelliğini tüm o hayasızlardan

Kuruyosa dudağın zehiriyle yılanların

Kızarıyorsa eğer alnın geçerken düşlerinden

Gözü sendeki o pis o hayasız yabancının

Yürü git korkusuzca, şehirleri ko git

Uzat tut ayaklarını o tozlu yolladan

İşte uzak kentler, bizim gözümüzle bak git

Yazılı kayaları gibi tutsak insanlığın

Geniş barınaklardır o tarlalar, ormanlar

Karanlık adalarla çevrili deniz gibi hür

Yürü elinde çiçekler tarlalar arasından', 'Sızlıyorsa yüreğin dünya gailesinden Yaralı kartalleyin dönüp duran yerlerde Tutsak kanatlarında taşıyarak benleyin Yazılı bir dünya, soğuk ...', ARRAY['Türk Edebiyatı','Şiir','Alfred De Vigny']::text[], 8.5, '{"poet":"Alfred De Vigny","poet_slug":"alfred-de-vigny","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dunyadan-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesliler', 'sesliler-arthur-rimbaud-hjcwu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A kara, E ak, I al, U yeşil, O mavi, sesliler

Diyeceğim bir gün gizli doğumlarınızı da

Karanlık koylara, kara sineklere benzer A

O amansız pis kokular üstünde fır dönerler

Kır çiçeği, buhar, çadır beyazlığında E''ler

Benzer dik buzulların mızrağına, ak krallara

Kızıla I, gülüşüne o canım dudakların, kana

Hani hoş pişmanlıklar içinde hani öfkeler

Çevreler U, yeşil denizlerin çalkantısı

Duruluğu onca otlakların, kırışıkların

Bastığı simyanın geniş alınlara damgasını

Kutsal borazan O, yaban çığlıklar, gürültüler

Meleklerden, acunlardan geçmiş sessizlikler

- Sen ey OMEGA, O mor ışığı gözlerinin!', 'A kara, E ak, I al, U yeşil, O mavi, sesliler Diyeceğim bir gün gizli doğumlarınızı da Karanlık koylara, kara sineklere benzer A O amansız p...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sesliler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Kendince', 'kendi-kendince-esma-ozdemir-mlowa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce, kendine sormak herşeyi

Kendinde bulabilmek mutluluğu

Evvela kendinde aramak iyiliği

Canavarlaşmış en kötü duyguları bile...

Aklını kendi hizmetine sunabilmek...

Ve, kendi kıymetini bilebilirsen

Yaşadığın sürece

Çözülür inan düğüm düğüm

Binlerce mesele

Kendi kendince...', 'Önce, kendine sormak herşeyi Kendinde bulabilmek mutluluğu Evvela kendinde aramak iyiliği Canavarlaşmış en kötü duyguları bile... Aklını ken...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kendi-kendince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelince', 'gelince-fikri-coskun-9vcky', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adetimiz üzre

Memleket ahvalinden konuşuyoruz

Seçimden/geçimden

Birkaç akıl aynı yolu bulamıyoruz

Neredeyse birbirimize gireceğiz

Karşı kıyıdan usulca

renkler içiçe yanyana sarmaşdolaş

su üstünde oynaşarak

ışık bir yol olup uzanıyor

karşı kıyı bana

seni gönderiyor

ağırçekim, 

ta orada öylece koşuyorsun

ta orada öylece 

bana doğru ağırçekim

sonunda mor bir ışıktan

mor bir çiçek oluyorsun

saçların kanatların oluyor uzamış

bir martı sakinliğinde

eteğin kocaman bir yelken 

bana koşmanın rüzgarıyla dolmuş

bir durna alayınca uyumlu

memelerin kürek çekiyor

ağırçekim

gülüşün çoğalıp gidiyor /çoğalıp gidiyor

herbiryer oluyor

ayrılıp geliyor senden 

bana ulaşıyor ağırçekim

terli boynuna tutunmuş

bir tutam saçın kokusuyla

bir denizkokusuyla ağırçekim

kokun bana ulaşınca

gelip kanıma girince

yavaşça gelip ben olunca 

ısınıyorum ağırçekim

büyüyorum çoğalıyorum taşıyorum

kimsenin gördüğü yok

memleket ahvalinden konuşuyoruz

                          ağustos 2002', 'Adetimiz üzre Memleket ahvalinden konuşuyoruz Seçimden/geçimden Birkaç akıl aynı yolu bulamıyoruz Neredeyse birbirimize gireceğiz Karşı kıyı...', ARRAY['Türk Edebiyatı','Şiir','Fikri Coşkun']::text[], 8.5, '{"poet":"Fikri Coşkun","poet_slug":"fikri-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gelince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ucu Sevda', 'bir-ucu-sevda-fikri-coskun-fm1u9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bir vaktinde

Yürüyüşe çıkmış bir sevgiyle çarpışınca

Ayın önüne bir yıldız geldi işte

Her bir yer yıldızdı da aslında

Biri de ayın önüne geldi

İlle de ikiye böleceksen kendini

Sevgiler ve acılar olarak

Araya da bir çizgi koyacaksan

Kıldan ince kılıştan keskin

Al sana işte bir inceacı

Durup dururken gökyüzüne 

ille de bayrak yapacaksan

olan oldu işte olacak olan

bir yıldızın tam da altına 

denk gelir artık hep yeri

sana kalan yukardan aşağı

kocaman bir doğru çizmek

oradadır orada lığıyla dünya çiçektarlası olmaktadır durmadan

en beride tomurcuk bir umut

siyasi karmaşa yok olup gider

aydınlığa ulaşırsın

bir ucu acı. 

			Eylül 2002', 'Gecenin bir vaktinde Yürüyüşe çıkmış bir sevgiyle çarpışınca Ayın önüne bir yıldız geldi işte Her bir yer yıldızdı da aslında Biri de ayın ö...', ARRAY['Türk Edebiyatı','Şiir','Fikri Coşkun']::text[], 8.5, '{"poet":"Fikri Coşkun","poet_slug":"fikri-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-ucu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Ayak Sesleri', 'sevginin-ayak-sesleri-cahit-i-pekoglu-q365x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep yüreğini göstermek istedin bana

senin yüreğin ne işe yarar.

Hep sevdiğim derdin bana

nerede o seviyorum diyişlerin.

Bak yoksun arık

neye yarar.

Ne senin yüreğin var

nede sevdan.

Sen sadece kadınlığını yaşamak istedin

Gerçek sevgi

senin ne işine yarar...

Ben hep sevdim

sevginin ayak sesleridir duyduğun.

Seninle aşkı yaşadım

ruhunla meşk eyledim.

Ben hiç korkmadımki hayattan

o hayatki bana seninle aşkı verdi.

Gerçek sevgi bu işte, sen varkende yaşadım, 

yok olsanda yaşarım....', 'Hep yüreğini göstermek istedin bana senin yüreğin ne işe yarar. Hep sevdiğim derdin bana nerede o seviyorum diyişlerin. Bak yoksun arık neye...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevginin-ayak-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrik Şiir-7', 'devrik-siir-7-devrik-sair-5byp6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'karanlığında kentin yitip gitmek

aynı soruda yenilmek ve yinelemek

aynı pencereden seyretmek aynı yalnızlığı

işte bana senden kalanlar geride

sadece bunlar ve belki de...

aynı hüzünlere uyanıyorum ıssız bir yerden seni özlüyorum', 'karanlığında kentin yitip gitmek aynı soruda yenilmek ve yinelemek aynı pencereden seyretmek aynı yalnızlığı işte bana senden kalanlar gerid...', ARRAY['Türk Edebiyatı','Şiir','Devrik Şair']::text[], 8.5, '{"poet":"Devrik Şair","poet_slug":"devrik-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/devrik-siir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-cengiz-analay-fubfu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kağıt, bir kalem ve bir insan

Adı konulmamış sevdamı yazarlar

Oniki yataklı tek can odaya.

Kirletilmemiş bir sevdayı yazarlar...

Aşkı şehvet, 

Canı beden zanneden

Yalan gülüşler tarafından.

Kirletilmemiş

İnsan kılıklı bireyler

Maskeli kişilikler tarafından.

Kalpleri parçalayan kaprislerin pençesinden

Hayatı zindan eden sahte hürriyetlerden, 

Korudum ben sevdamı 

Beko''nun zakkum çiçeğinden.

Sevdam ki, 

Ürkek bir ceylan

Alabildiğince özgür.

Öpülüp koklanmamış

Nazlı bir gül...

Ukde koydum sevdamın adını...

Bir bebeğin tebessümü gibi saf

Bir annenin ağlayışı gibi içten olan, 

Ellerimi titreten, dizlerimi boşaltan

Sevgimin, yani senin

Adını ukde koydum.

Sen

Ürünüydün gerçek sevda türkülerinin, 

Fecr vakti uykularımı bölen

Hayalleri, 

Sıcak Amed gecelerinin.

Saatlerin... Saatlerin...

Hiç dolmuş beklemedim, 

Küfretmedim otobüs şoförlerine gecikti diye, 

Sıkılmadım hiç sızlanmadım, 

Geç kalmaktan korkmadım; okula, eve, işe.

Herşeyden güzeldi çünkü, 

Güzeldi, 

Sohbet etmek seninle.

Çürük otobüs duraklarında...

Taşları sökük sokaklarda, yollarda...

Seninle sohbet güzeldi, 

Beynimde kurduğum dünyamda...

Öğrenciyken ben, 

Yalnız yaşadı bedenim dört ay; 

Penceresi kartondan, 

Tek göz sobasız bir evde.

Üşümedi hiç titremedi

Ateşe tenezzül etmedi, 

Düşüncenin an olduğu soğuk saatlerde.

Isıttı bedenimi

Dinlendirdi beynimi, 

Canımın iki yongası

Evimin en güzel iki eşyası, 

Kaportasız bir teyp ile nevresimsiz Koçer yorganı.

Başım yorgan altındaydı gecelerce

Uyurken üşümeyeyim diye.

Düşünüp seni hep

Ruhum yalnız kalmasın, 

Isınsın, ısınsın diye...

Sen korudun ruhumu paranoyik ölümlerden

Esaret kokan gecelerde...

Isıttın sen ruhumu 

Yaşanan sanal alemlerde.

Yaşanan sanal alemlerde...

Kızardın bana bazen sinirlenirdin, 

Hani çakmak çakmak olurdu ya 

Teslimiyet dolu gözlerin.

Hiç moralimi bozmaz, küsmezdim.

Aksine

İçten içe sevinir, gülerdim.

Bir bilsen güzelim, bir bilsen

O anlarda

Ne kadar da güzeldin.

Saçlarını okşar

Seni bir gül gibi koklar, 

Kızgınlığını yüreğime gömerdim.

Seni ben o anlarda

Daha bir, 

Daha bir severdim.

Mavi kokan gülüşün

Manalı, 

O nazlı tebessümün; 

Ürkütürdü hep beni

Ülkemle benzerliğin.

Sevdamın esiri olmaktan korkardım...

Korkardım kendimden

Tuvalette yaktığım şiirler gibi...

Hüzün dolu şehirde

Akşamüstü arkama bakmadan

Xançepek''ten Bağlar''a yürümek gibi...

Sesimin ulaşabildiği yere kadar

Korkmadan, çekinmeden

Islığımı kullanmadan

Okuduğum

Yasak dilin türküleri gibi...', 'Bir kağıt, bir kalem ve bir insan Adı konulmamış sevdamı yazarlar Oniki yataklı tek can odaya. Kirletilmemiş bir sevdayı yazarlar... Aşkı şe...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/sevdam-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kelime Tek Cümle', 'i-ki-kelime-tek-cumle-cengiz-analay-5ig4y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne düşündüğünü bilmeden yazacaksın, 

Ya da ne istediğini.

İlk sen mi yazdın sanki.

İki kelime tek cümle

Seni seviyorum diye...

Ellerin bile utanırsa yazdıklarına, 

Utanırsa okuyan gözlerinden.

Umursama yaz yine de.

İki kelime tek cümle

Seni seviyorum diye...

Söyle ne geçtiki eline, 

Ne geçti yiten zamandan geriye.

Ket vur geçmişe, geleceğe.

İki kelime tek cümle

Seni seviyorum diye...

Beni seviyor musun diyenlere, 

Söyle gitsin isteyenlere.

Kabul gören yitik yüreklere.

İki kelime tek cümle

Seni seviyorum diye...

Ne düşündüğümü bilmeden yazdım, 

Ya da ne istediğimi.

Ne ilk olacak ne de son bu gidişle, 

Yine de tebessüm edeceksen bu garibe, 

Verilebilecek en güzel hediye, 

İki kelime tek cümle

Seni seviyorum diye...', 'Ne düşündüğünü bilmeden yazacaksın,  Ya da ne istediğini. İlk sen mi yazdın sanki. İki kelime tek cümle Seni seviyorum diye... Ellerin bile ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/iki-kelime-tek-cumle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-cengiz-analay-m4f9i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bilemezsin

Ayrılığı.

Sevdiğin insan hayır dediği zaman

İçimde kopan fırtınayı.

Nasıl çaresiz kaldığımı bilemezsin...

Ne yapacağımı bilemeden, ağlayamadan

Sessizce kendimi gecenin soğuk koynuna bıraktığım gecelerde

Hayalleri yokolmuş bir insanınezilmişliğini

Yalnızlığını, 

Hiçkimse bilemez.

Uzaklardan gelen aşk çığlıklarının sesini

Sen duyamazsın, bir ben duyarım.

Sıcaktan bunalırken esen kuzey rüzgarının serinliğini

Hissedemez insan böyle durumlarda.

İşte bu anlarda tek şey vardır aklında

Neden seni terkettiği, niçin bıraktığı

Hafiften türkü nağmeleri gelir kulağına

İçinden şiir yazmak gelir, 

Romantik bir şiir.

Terkedilmiş, yalnız bırakılmış bir adamın

İnanılmaz hasretini anlatan bir şiir...

Ancak bir yerden sonra kelimeler boğulur.

Cümlelerin sevdiğinin merhametsizliğinde

Acı vermeye başlar

Bırakırsın bu işi de.

Geriye tek bir şey gelir aklına

Ölüm...

Çekersin revolveri dayarsın alnına

Basarsın tetiğe hiç ardına bakmadan

Bir gül koklar gibi giderken ölümün soğuk koynuna

Yaşamı özlersin, 

Sevgilini özlersin umutsuzca...', 'Sen bilemezsin Ayrılığı. Sevdiğin insan hayır dediği zaman İçimde kopan fırtınayı. Nasıl çaresiz kaldığımı bilemezsin... Ne yapacağımı bilem...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ayrilik-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatirla', 'beni-hatirla-gezginci-ugur-71yep', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dünyada hic gülmemis mutluluk nedir bilmemis sevdigi ugruna can vermis birini görürsen beni Hatirla.

Her gülene derdini anlatan yasamadan hayattan bikan, Vefasizlar ugruna kendini yakan birini görürsen beni Hatirla.

Aglayipta derdine care bulamayan kendine ebediyen dost arayan, Avuntugu siir yazmakta bulan birini görürsen beni Hatirla.', 'Bu dünyada hic gülmemis mutluluk nedir bilmemis sevdigi ugruna can vermis birini görürsen beni Hatirla. Her gülene derdini anlatan yasamadan...', ARRAY['Türk Edebiyatı','Şiir','Gezginci Uğur']::text[], 8.5, '{"poet":"Gezginci Uğur","poet_slug":"gezginci-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/beni-hatirla-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgecemedik', 'vazgecemedik-gezginci-ugur-jhxmg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiye inandik, duyguya inandik cok kötü baglandik

Vazgecemedik 

ayri gayri düstük, hasret ile pistik ne yollardan gectik

Vazgecemedik.', 'Sevgiye inandik, duyguya inandik cok kötü baglandik Vazgecemedik  ayri gayri düstük, hasret ile pistik ne yollardan gectik Vazgecemedik....', ARRAY['Türk Edebiyatı','Şiir','Gezginci Uğur']::text[], 8.5, '{"poet":"Gezginci Uğur","poet_slug":"gezginci-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vazgecemedik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazı Aşklar Gözlerde Yaşanır', 'bazi-asklar-gozlerde-yasanir-muhtesem-oksel-j05uw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazı aşklar, gözlerde yaşanır.

Gerek yoktur sözlere, 

Gözler her şeyi anlatır.

Gözlere bakarsın, 

Sevgiyi anlarsın.

Tutkuyu, aşkı

Gözlerde ararsın.

Seni seviyorum der, gözler.

Gel der, gidemezsin.

Sev der, sevemezsin.

Sadece gözlerin söyler, 

Karşılıksız bir aşk olmadığını.

Dokunamazsın.

Gözlerinle öpersin dudakları, 

Gözlerinle sevişirsin.

Konuşmak yasaktır.

Tek bir söz söyleyemezsin.

O sorsa inkâr edersin.

Sen sorsan, 

Yanılıyorsun olur, 

Bir cevap ki aslında yalan, 

Seni yaralayan.

Utanırsın, 

Yerin dibine geçersin.

Ama hakikat gözlerde saklıdır.

Ve gözlerde aşk, inanılmazdır, 

Sınırsız ve zararsız.

Gözlerde bir aşk yaşanır, 

Yasaksız.

Gözlerde aşk ikinizindir, 

Kimseler bilmez.

Sözler kirletemez.

Gözlerde aşk eşsizdir.

Sevdiğini bilirsin, 

Görürsün sevildiğini.

Gözler bir sırrı saklar

Duyamazsın

Söyleyemezsin.', 'Bazı aşklar, gözlerde yaşanır. Gerek yoktur sözlere,  Gözler her şeyi anlatır. Gözlere bakarsın,  Sevgiyi anlarsın. Tutkuyu, aşkı Gözlerde a...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bazi-asklar-gozlerde-yasanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Aydın', 'gozun-aydin-ozer-sutcu-53wgg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözün Aydın Artık sigarada içiyorum

Sabaha Kadar Meyhaneden Çıkmıyorum

Hani demiştin ya görmek istemiyorum diye

Yakında göremiyeceksin yavaş yavaş eriyorum

Yakındır benden kurtulmam özgür kalacaksın

Bana ait resimleri yırtıp atacaksın

Kalbinde, her yanında ben varken

Söyle nasıl başkalarını olacaksın

Hatırlatacak sana sokaktaki kaldırım taşı

Unutturmayacak sana beni her köşe başı

Sen unuttum deyip avuturken kendini

Benim için akacak gözlerinin yaşı

Ben olmasamda anılar bırakmazki seni

Rüzgar fısıldayacak benim ismimi

Her şeyi bir kalaemde silersin ama

Silemezsin kalbine kazıdığım resmini', 'Gözün Aydın Artık sigarada içiyorum Sabaha Kadar Meyhaneden Çıkmıyorum Hani demiştin ya görmek istemiyorum diye Yakında göremiyeceksin yavaş...', ARRAY['Türk Edebiyatı','Şiir','Özer Sütçü']::text[], 8.5, '{"poet":"Özer Sütçü","poet_slug":"ozer-sutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozun-aydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Oyunu', 'golge-oyunu-levent-ozgur-07qof', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bütün yaz gölgede eridiğim oydu

çıplak gözle görülmeyen bezgin çocuk

boyalı kanat sesini taşıran hevesi dün bir

bugün iki kere soldu

eridi

kırbacını boynuna dolayıp astı kendini 

zamana durup su oldu

bekledi bi elmanın içinde 

yenildi tedirgin kaldı...', 'bütün yaz gölgede eridiğim oydu çıplak gözle görülmeyen bezgin çocuk boyalı kanat sesini taşıran hevesi dün bir bugün iki kere soldu eridi k...', ARRAY['Türk Edebiyatı','Şiir','Levent Özgür']::text[], 8.5, '{"poet":"Levent Özgür","poet_slug":"levent-ozgur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/golge-oyunu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Hatıralar Kalır', 'bir-tek-hatiralar-kalir-mehmet-ali-can-anbr7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler, aylar

Durmaz akar; 

Gençlik kalmaz, bir gün biter.

Öyle sevdalanırsın ki, 

Yoluna toprak olursun, 

Sevdiğin de bir gün gider, 

Sararır yaprak olursun.

Dost dost diye dövünürsün, 

Dostun çoksa övünürsün.

Ayrılık zamanı gelir, 

Hepsi birer birer gider.

Ya ölüm alır onları, 

Ya ölümden beter şeyler...

Gençliğinden, sevdiğinden, 

Dostlarından sana bir tek, 

Bir tek hatıralar kalır.', 'Günler, aylar Durmaz akar;  Gençlik kalmaz, bir gün biter. Öyle sevdalanırsın ki,  Yoluna toprak olursun,  Sevdiğin de bir gün gider,  Sarar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Can']::text[], 8.5, '{"poet":"Mehmet Ali Can","poet_slug":"mehmet-ali-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-tek-hatiralar-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-erhan-ozdemir-8xlre', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaşam geçti burdan

Tadına doyamadan

Bir umut, bir sevgi geçti

Yerine koyamadan

Dedim; yerin boş kaldı

Derdi; dolacak birgün

Başın göğemi erdi

Bomboşum o gün, bu gün

Bilsemki olacak çare

Derdime derman sevdan

Olsun başım üstüne

Haksa adaletin mevlam

Kimbilir belki döner

Yalnızlığım son bulur

İçten yanan bu ateş

Başka ne zaman söner

Artık yeter son geldi

Gönül canı tükendi

Ya sen gelecen buraya

Yada ben senin yanına', 'Bir yaşam geçti burdan Tadına doyamadan Bir umut, bir sevgi geçti Yerine koyamadan Dedim; yerin boş kaldı Derdi; dolacak birgün Başın göğemi...', ARRAY['Türk Edebiyatı','Şiir','Erhan Özdemir']::text[], 8.5, '{"poet":"Erhan Özdemir","poet_slug":"erhan-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beklenen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sitem', 'son-sitem-erhan-ozdemir-vq2q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasret ve özlem kolkola girmiş, yürüyor üzerime

Bir parça daha koparmak için, bitiremediği sevgimden

Ölümün gölgesi düşmüş çelimsiz, solgun bedenime

Unutup bıraktığı son şeyide, almak için içimden

Oysa daha dün gibi verdiği coşku, varlığınla sevginin

Bulutlarda dans ederdi, hesapsiz, sana bağlı benliğim

Mutluluga doymustu, seninle çarpan bu tutsak kalbim

Geri çevrilmezdi tanrıya dualarımda, çocuksu isteklerim

Belki imkansiz belkide istemem, asla dönmek geriye

Bu yorgun hislerim dayanabilirmi, aynı hain sevgiye

Yok istemem bir daha dayanamam, sensiz gecen günlere

Umarım mutlu olursun bitanem, alıştır kendini bensizliğe', 'Hasret ve özlem kolkola girmiş, yürüyor üzerime Bir parça daha koparmak için, bitiremediği sevgimden Ölümün gölgesi düşmüş çelimsiz, solgun ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Özdemir']::text[], 8.5, '{"poet":"Erhan Özdemir","poet_slug":"erhan-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver', 'bosver-erhan-ozdemir-1kz51', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha deyince olmuyor

Aşk kural tanımıyor

Gönül konduğu dalda

Uzun süre durmuyor

Sonsuz aşk varmıdırki

Sevgiye dönüşmezse

Bitmesi bellimiki

Önceden görülmezse

Tuzağa düştüm sanma

Peşinden koşar iken

Aşk defterin karartma

Henüz başlangıç iken

Boşver elin sözüne

Sen bak kendi özüne

Çekemez aşk ağrısı

Su serper kalp közüne

Hayat der yak kendini

Eğer mutlu olcaksan

Sonrasını düşünme

Kendini bulacaksan', 'Ha deyince olmuyor Aşk kural tanımıyor Gönül konduğu dalda Uzun süre durmuyor Sonsuz aşk varmıdırki Sevgiye dönüşmezse Bitmesi bellimiki Önc...', ARRAY['Türk Edebiyatı','Şiir','Erhan Özdemir']::text[], 8.5, '{"poet":"Erhan Özdemir","poet_slug":"erhan-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bosver-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin -2-', 'gozlerin-2-ahmet-kurnaz-cttse', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dillerin konuşmuyor, bakışların susmuyor.

Neler söylüyor, neler anlatıyor gözlerin.

Kaşların gerilmiş yay, kirpiklerin ok olmuş, 

Delik deşik sinemi kanatıyor gözlerin.

Buğulanmış ırmağa, göle benziyor göle, 

Sanki bir çift kelebek konmuş kırmızı güle, 

Sözlerin efil efil bir rüzgâr olsa bile, 

Yakıyor yüreğimi, kaynatıyor gözlerin.

Karanlık gecelere doğan bir ışık gibi, 

Öksüzkalan sevdama, bir sıcak beşik gibi, 

Gül dalına sarılmış, taze sarmaşık gibi

Baktığında, canıma can katıyor gözlerin.

Terkedilmiş bir hanın, unutulmuş hancısı, 

Ağlayan gözlerimin damla damla incisi, 

Sensiz kalan gönlümün tükenmeyen sancısı, 

Yüreğimi yerinden oynatıyor gözlerin.

                  16.09.2002', 'Dillerin konuşmuyor, bakışların susmuyor. Neler söylüyor, neler anlatıyor gözlerin. Kaşların gerilmiş yay, kirpiklerin ok olmuş,  Delik deşi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demem Şu Ki Sevgilim', 'demem-su-ki-sevgilim-tayfun-talipoglu-vxnot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Demem şu ki sevgilim

Bir yerinde yaşamın birileri bittiğini anlatıyorsa durmadan sevdaların, ve az biraz, tutunduğumuz yerinden basıyorsa yüreğimize, direnmek gerek, direnmek gerek ki hem de nasıl hani diyor ya Usta: ''o iyi insanlar, o güzel atlara binip gittiler'' gitmemişler.. gittilerse de dönmüşler sevdalalrı zulalarında konuşacakları günü beklemekteler', 'Demem şu ki sevgilim Bir yerinde yaşamın birileri bittiğini anlatıyorsa durmadan sevdaların, ve az biraz, tutunduğumuz yerinden basıyorsa yü...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Talipoğlu']::text[], 8.5, '{"poet":"Tayfun Talipoğlu","poet_slug":"tayfun-talipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/demem-su-ki-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Benim Olsun', 'gul-benim-olsun-mustafa-aydinli-s3xwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğan güneş, bulutları itiyor

Güneşin ışığı bize yetiyor

O ışık, gönlüme coşku katıyor

İstemem lambayı al senin olsun.

                       Tüm çiçekler boyun büker güneşe

                       Doğaya güneşle heyecan, neşe

                       Arılar uçuşur, hem de peş peşe

                        Zehiri neyleyim bal benim olsun. 

                     

Dağ başında duman olur, kar olur

Dosttan ayrılması çok da  zor olur

Ayrılırken ciğer tüter, kor olur

Dosta tutunacak el benim olsun.

                      Aydınlı, söylüyor kendi haline

                      Sevdayı, dostluğu dolar diline

                      Bir tomurcuk gülü alsa eline

                      Dosta uzatacak gül benim olsun.

                                              Mustafa AYDINLI', 'Doğan güneş, bulutları itiyor Güneşin ışığı bize yetiyor O ışık, gönlüme coşku katıyor İstemem lambayı al senin olsun.                      ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Aydınlı']::text[], 8.5, '{"poet":"Mustafa Aydınlı","poet_slug":"mustafa-aydinli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gul-benim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-cengiz-analay-qjm0y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor, yine sensizim 

Islanıyorum, 

Bahardan çıkmış çiçek gibi

Üşüyor seni düşünen yorgun bedenim. 

Terketme diyor yüreğim

Bilirsin sensizliğe dayanamadığını, 

Sensiz yaşayamayıp yıkıldığını.

Yine de gideceksen ağlamam

Haykırırım gökyüzüne 

Avazım çıktığı kadar nefretimi.

Düşer toprağa boylu boyunca 

Sana hasret vücudum...

Gitme, kal desem

Dinlemezsin biliyorum

Ama ne olur gitme

Sonu gelmeyen karanlıkların hüküm sürdüğü

Issız gecelerde yalnız bırakma beni.

Düşüncelerimin sana kilitlendiği

Bütün varlığımla sana muhtaç olduğum bir anda

Terketme beni.

Anla lütfen 

Bunca şeyi kendim için istemiyorum 

Sadece sana muhtaç

Aşkım için istiyorum...', 'Yağmur yağıyor, yine sensizim  Islanıyorum,  Bahardan çıkmış çiçek gibi Üşüyor seni düşünen yorgun bedenim.  Terketme diyor yüreğim Bilirsin...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-cengiz-analay-uhxes', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tadına varamadan yaşamın, 

Ayrılmak ne zordur bilir misin? 

Yaşayamadan sonsuz güzellikleri, 

Ölmek ne zordur bilir misin? 

Kavuşamadan sıcak koynuna, 

Toprağa girmek ne zordur bilir misin? 

Seni düşünmeden yaşamak, 

Ya sensiz yaşamak, ne zordur bilir misin?', 'Tadına varamadan yaşamın,  Ayrılmak ne zordur bilir misin?  Yaşayamadan sonsuz güzellikleri,  Ölmek ne zordur bilir misin?  Kavuşamadan sıca...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasam-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-cengiz-analay-vljxa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve birgün yürüyeceksin enginlere

Yüreğine bastıracaksın mahçup duygularını

Sıcak bir yuvadan ayrı yaşayıp

Kanayan düşüncelerle haykıran

Bir şair olacaksın belki de.

Duygularını bastıramayıp

Beni arayacaksın.

Bulamayacaksın...

Ama buna inan güzelim

Seni seviyorum demeden, 

Gideceğim 

Sevginin zifiri karanlıklara boğulduğu yere

Kurtaracağım aşkımı

Vicdansız kaderden...', 'Ve birgün yürüyeceksin enginlere Yüreğine bastıracaksın mahçup duygularını Sıcak bir yuvadan ayrı yaşayıp Kanayan düşüncelerle haykıran Bir ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isyan-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmaya Yatmak', 'kavusmaya-yatmak-onur-uysal-5ahe9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece başka, 

      gözüme uyku girmiyor, 

Bu gece zaman durmadı

      yelkovanla akrep dansediyor, 

Bu gece karanlık hiç değil, 

      ay ışığı göz yakıyor, 

Bu gece kavuşmaya yatıyorum, 

      yarın sevgilim geliyor...

28 Ağustos 2002', 'Bu gece başka,        gözüme uyku girmiyor,  Bu gece zaman durmadı       yelkovanla akrep dansediyor,  Bu gece karanlık hiç değil,        ay...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kavusmaya-yatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Yolların Adamı', 'kotu-yollarin-adami-cengiz-analay-oare5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne deniz kenarı, ne balıkçı kayıkları

Ne batan güneş, ne uçuşan martılar

Hiçbiri etkilemez beni

Ben buraların adamı değilim

Beyoğlu''nda yaşarım ben

Tutkularım sürükler beni Laleli''ye.

Ket vurur duygularıma İstanbul...

Romantik adam değilimdir vesselam.

Küf kokan meyhanelerin

Terli bedenlerin hakimiyetinde genelevlerin adamıyım 

Elince alınca şarap şişesini

Kendini Haliç''in koynunda bulanlardanım.

Anladın mı şimdi beni 

Hayır, anlayamazsın...

Duygularım erişilmez bir aşkla 

İstanbul''a, meyhanelere bağlıdır.

Kadın kokan yerleri arar ruhum

Anason kokan dudakları arzular dudagım

Sabah uyandığımda tutkuyla seviştikten sonra

Yorgunluktan bitap düşmüş

Sıcak bir kadın teni ister tenim.

Kınama beni, kızma bana arkadaş

Ben kötü yolların adamıyım...', 'Ne deniz kenarı, ne balıkçı kayıkları Ne batan güneş, ne uçuşan martılar Hiçbiri etkilemez beni Ben buraların adamı değilim Beyoğlu''nda yaşa...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kotu-yollarin-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Mesaj', 'kisa-mesaj-cengiz-analay-v3b87', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şiir tadında değildi belki kelimelerim, 

Ya da bir nesrin biçimlenmiş güzelliğinde.

Kalıplara sığmazdı inan bu yürek, 

Çocuksu sevgisinin ince derinliğinde...', 'Bir şiir tadında değildi belki kelimelerim,  Ya da bir nesrin biçimlenmiş güzelliğinde. Kalıplara sığmazdı inan bu yürek,  Çocuksu sevgisini...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Analay']::text[], 8.5, '{"poet":"Cengiz Analay","poet_slug":"cengiz-analay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kisa-mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sineğimin Şarkısı', 'sinegimin-sarkisi-hakan-rodop-b2wjj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızı şarabın içine

düşen cansız bir sinek

alnında siyah bir bant

üstünde çiziktirilmiş bir resim

yazlık ev - hepsi bizim

sinek cansız ama

çırpınıyor

sinek mide bulandırır

bu çok hoş

hep gülüyor

sinek yenilmez

ve dolayısıyla öpülemez

ama ben yiyip bitiriyorum gözlerini

hemde inatla öpüyorum burnundan

bırakmıyorki beni gideyim

bırakmıyorki beni öleyim

sineğim şarkılar söylüyor bana

ve inatla şarabını içiyor

- çirkin bir kızı seviyorum aslında ben -', 'Kırmızı şarabın içine düşen cansız bir sinek alnında siyah bir bant üstünde çiziktirilmiş bir resim yazlık ev - hepsi bizim sinek cansız ama...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sinegimin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatında', 'hayatinda-mehmet-fatin-baki-a1nr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Annene bir gül gönder hayatında

Çelenk, çiçek   yerine  vefatında 

Ziyaret et babanı  hayatında

Hergün ağlayacaksan vefatında

Sakın üzme eşini hayatında

Pişman olacaksan vefatında

Dosta güler yüz göster hayatında

Sana rahmet dilerler  vefatında

Çocukları sevindir hayatında

Hürmetle anılırsın vefatında

Duânı ihmâl etme hayatında

Rahat etmek istersen vefatında

Mefaki şarkı söyle hayatında

Sesin çıkmayacaksa vefatında', 'Annene bir gül gönder hayatında Çelenk, çiçek   yerine  vefatında  Ziyaret et babanı  hayatında Hergün ağlayacaksan vefatında Sakın üzme eşi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayatinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıldı Bir Kez', 'yakildi-bir-kez-hakan-rodop-88bwz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Henüz bir aşkın başındayız

yolumuzu 

oyunlar oynayarak

sesimizi sesinizle birleştirip

topladığımız bir avuç külü

yüreğinize dağıtarak bulacağız

istemeden hatalar yapacağız

ve de bir gün o kapalı kapıları

ardına kadar

görüntünle görüntümü

vücudunla vücudumu

bazen oynaşarak

bazen şaşırarak açacağız

yok artık geri dönüşü

yakıldı bir kez Roma

bir kez

bir kız

bir çocuğu öptü

ve yakıldı ateşler

Henüz bir aşkın başındayız

anlayın bizi

yolumuzu yolunuza katacağız...', 'Henüz bir aşkın başındayız yolumuzu  oyunlar oynayarak sesimizi sesinizle birleştirip topladığımız bir avuç külü yüreğinize dağıtarak bulaca...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yakildi-bir-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyar Değilim', 'i-htiyar-degilim-mehmet-fatin-baki-rai6p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözüne güvenilir merd adam yiğit olur	

Zayıf ve fakirlere her zaman müfit olur

Etrafına nur saçar zulmette hurşit olur	

Yalan dolan geçinen  namerde yâr değilim

Serkeşane değilse sarhoşane dolaştım	

Mecburiyet  icabı köpeklerle dalşatım

Yadellerde bir kerre kanunla karşılaştım 	

Zavahire bakma sen ben sahtekâr değilim

Pelaspare görünen kiyafete aldanma 	 	

Berduş için  söylenen rivayetlere kanma

Küffâr ile uğraştım hata etmedim sanma 	

Allâh şahidim olsun pek günahkâr değilim

İhtilaflı taraflar özümü hakim seçti	

Adalet makamında elime yetki geçti	

Sonunda insafsızlar ektiklerini biçti	

Vicdanen müsterihim asla hünhar değilim

Kaderin emri ile zürriyetim olmadı		

Ahfâdıma gidecek şefkat şevkim dolmadı

Çocuklara  verecek sevgim hiç kaybolmadı	

Öksüz, yetim ve yoksul tıfla ağyar değilim 

Sefahet aleminde Mefaki  sefâ sürdün	

Göklere hakim olan kartal gibi özgürdün

Köyden uzak gurbette yirmibin şafak gördün	

Sen kocadıysan eğer ben ihtiyar değilim

Hurşit = güneş         Hünhar = zalim

Ahfâd = torunlar      Tıfl = küçük çocuk', 'Sözüne güvenilir merd adam yiğit olur	 Zayıf ve fakirlere her zaman müfit olur Etrafına nur saçar zulmette hurşit olur	 Yalan dolan geçinen ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ihtiyar-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Akıllansana', 'artik-akillansana-salih-ozalasan-v2tat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sanmaki ben sevdaları 

Yalnızca yazdım hiç yaşamadım

Ben yüreğimi hep sevdalara adadım

Yaşamadığım sevdaları hiç yazmadım

Ama öyle bir sevdaya tutulmuşumki

Artık yazmaktan yaşamaya fırsat bulamadım

Yazdığım sayfalarda hep onu yaşattım

Ama bir türlü ona ulaşamadım

Dağları aştım ovalarda boğuldum

Elimde hep bir kalem önümde bir sayfa

Ben bu defa yazma hastalığına tutuldum

Sevdaya kalmadı zaman çünki sadece yazar oldum

Bazen diyorum yetmezmi artık yazdığın

Bırak artık sende sevdanı yaşa

Belkide bu son şans kimbilir

Bırakma artık yeter herşeyi şansa

Zaman bulamayacaksın geçti ömrün

Kalan ömrünü artık sende ayır aşk''a

Bulmuşsun gönlünün sultanını

Senden çok ama çok uzaklarda

Belki kavuşmak olmasada sonu

Kavuşursun yazdığın sayfalarda

Sayfalarda kavuşmakta yeter 

Yeterki sen dön şöyle bir bak karşına

Baktığında o zaten senin hep karşında

Sana hayat veren o artık akıllansana

Y.Tarihi 17-09-2002 Saat 01.00', 'Sen sanmaki ben sevdaları  Yalnızca yazdım hiç yaşamadım Ben yüreğimi hep sevdalara adadım Yaşamadığım sevdaları hiç yazmadım Ama öyle bir s...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/artik-akillansana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedildim ve Dokunmak İstedim', 'terkedildim-ve-dokunmak-i-stedim-hakan-rodop-jz7zm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doya doya tarandım

yalnızdım - tek başıma

Dünya ve ben

saçlarım ayrıldı ikiye

sonra katlandı dörde

bir de baktım bir tel bile kalmamış

saatler boyu ağladım

gözlüğüme düştü ince ince

bir ışık gürültüsü

sızılar hissettim alnımda

saatler boyu güldüm

ne komikti

ayna bile güldü

dışarıda bağıran manav bile

kasap''ın kedisi bile güldü halime

neden sonra uyandım düşümden

ayaklarım hükmetmiyordu bana

gövdemden ayrılmışlar

koşa-koşa kaçıyorlar

saçlarım terketti beni

şimdi de ayaklarım

geriye kalan bir başka

vücuttu dokunmak istediğim', 'Doya doya tarandım yalnızdım - tek başıma Dünya ve ben saçlarım ayrıldı ikiye sonra katlandı dörde bir de baktım bir tel bile kalmamış saatl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/terkedildim-ve-dokunmak-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zenci Kızın Kolyesi', 'zenci-kizin-kolyesi-hakan-rodop-jzvw9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kayıp ilanında gördüm

bir küçük zenci kızı

lüks bir lokantanın menüsünde

istek diye sunuluyordu

garip bir türkü söylüyordu

venasara mıydı adı yoksa orlunta mı

şimdi tam hatırlamıyorum

sonra kayıplıktan çıkmak için

aslında pek fazla para etmez

kolyesini satışa çıkardığını duydum

gidip satın aldım

polisler düştü peşime sirenleriyle

çok sonraları onu bir takside

yanında izbandut misali bir adamla

öpüşürken gördüm

adam ısrarla kolyesini arıyordu

çıkarıp silahımı vurdum

sirenleriyle polisler düştü peşime

kaçtım bir afrika ülkesine

çiçeklerle karşılandım

meğerse orada kolye takmak yasakmış

yakalandım...', 'Kayıp ilanında gördüm bir küçük zenci kızı lüks bir lokantanın menüsünde istek diye sunuluyordu garip bir türkü söylüyordu venasara mıydı ad...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zenci-kizin-kolyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetname', 'vasiyetname-hakan-rodop-l3vwv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Darılmayın bana arkadaşlar

sizi arayamıyorum diye

dolaşmış bir yumağı çözmeye

çalışan kedimin sesiyle

sıcacık sobayı karıştırırken

sınıfa dalıveren bir trenin

raylarının 2000 m. altında

kazma vuran işçiyle buluşan

mavi gözlü bir çocuğun okuduğu

Moby Dick'' teki balinanın midesindeydim

cerrahlar hala uğraşıyorlar

beni kurtarmaya

oyununuza bu yüzden gelemedim

ve bu yüzden eğer ölürsem

kedimin sesini

sobamın sıcaklığını

trenin raylarını

işçinin kazmasını

çocuğun mavi gözüyle

cerrahların balinasını

size bırakıyorum...', 'Darılmayın bana arkadaşlar sizi arayamıyorum diye dolaşmış bir yumağı çözmeye çalışan kedimin sesiyle sıcacık sobayı karıştırırken sınıfa da...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vasiyetname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hep Seveceğim', 'seni-hep-sevecegim-gunes-kara-8jbhg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretinden yanıp ölsemde

Gökyüzünde güneş artık doğmasada

Denizler kabarıp taşsada

Seni hep seveceğim..

Yeryüzünde bir tek ağaç kalmasada

Geceler hiç sabah olmasada

Birgün çok istediğimde seni arayıp bulamasamda

Seni hep seveceğim...

Sel gibi akan gözyaşlarım kurusada ağlamaktan

Gözlerimden eser kalmasada

Sana verdiğim yüreğimin atışları dursada

Seni hep seveceğim...', 'Hasretinden yanıp ölsemde Gökyüzünde güneş artık doğmasada Denizler kabarıp taşsada Seni hep seveceğim.. Yeryüzünde bir tek ağaç kalmasada G...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-hep-sevecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arif Olan Anlasın', 'arif-olan-anlasin-metin-eloglu-7qgok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahar gelir gelmez

Sokağa çıkar çıkmaz

Elif''i görür görmez', 'Bahar gelir gelmez Sokağa çıkar çıkmaz Elif''i görür görmez...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/arif-olan-anlasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzlucam', 'buzlucam-metin-eloglu-z0qa8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Camı kırmak çok kolay

Göğü hep göğertmek

Unu hiç acıtmamak

Çölü tez çimlemek

Er''i dişilemek

Piçi babalamak

Sonu ilklemek hemen

Zor olanı sen', 'Camı kırmak çok kolay Göğü hep göğertmek Unu hiç acıtmamak Çölü tez çimlemek Er''i dişilemek Piçi babalamak Sonu ilklemek hemen Zor olanı sen...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buzlucam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgar', 'cilgar-metin-eloglu-nrnnl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oralar yazın mı hala, güpgüzel

Gayri şarapsadım ben, İstanbulsadım

Kuşladıysa gözlerimi bir sakar tavan

Sensiz günlerimi çarçur etmek içindir

Ama pörsümüş, gül bitine karmış bir sarı

Siner külçelenir ta evimde barkımda

Pelit acısından yavuz bir özlem kiri

Yu canım usulcacık

Sen bunca umudumun çılgarı

Göğü maviltir bir kırlangıç yakamoz

Balıklar debreşir suda', 'Oralar yazın mı hala, güpgüzel Gayri şarapsadım ben, İstanbulsadım Kuşladıysa gözlerimi bir sakar tavan Sensiz günlerimi çarçur etmek içindi...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cilgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değerleme', 'degerleme-metin-eloglu-y9x6p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aşk senden önce hürriyete yöneldi

Gecenin ortasında sen sımsıcak bir kadın

İçinde sen varken geceler dile geldi

Barışa yöneldi umudu darmadağın

Onları özlemek belki senden güzeldi

Çünkü sen ancak onlarda vardın

Hayatın mavişliği onlarla vardı', 'Bu aşk senden önce hürriyete yöneldi Gecenin ortasında sen sımsıcak bir kadın İçinde sen varken geceler dile geldi Barışa yöneldi umudu darm...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/degerleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Horozdan Korkan Oğlan', 'horozdan-korkan-oglan-metin-eloglu-jvb3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapı çalındığında ben belki uyumuşum

Belki azıcık bahçe dikiyorum bir saksıya

Şimdi yaz bahar ayı, kim kime kanıksıya

Evet, evliyim bir çocukluyum

Hayınlığı debreşti miydi bu kedinin

Çolak bir pençe içimi tırmalıyor

Elimi cebime sokuyorum, batıyor

Ucu, paslı bir iğnenin

Kardeşim, tavanda bile o sinsi ayakları

Hırsızlama bir duyarlık soluğumu kesen

Gök bile kuşladı ama hanimiş sen

Yoldukça üredi şeytan tırnakları

Hani İstanbul''u bu evin, hani zurnabalığı

Üç pencere ölüsünde bir daracık Üsküdar

O babacan acıkmıya varıyorum daradar

Sofrada bir tutam çamurlu hindibalığı

Saframı kabartan birşey var kapı zilinde

Tam o kez yumurtluyor gözümün sinekleri

Hele o ham salılar, o haziran kökleri

Büyümüş gibi kendi dizidibinde

Ömründe hiç insan görmedi mi ne

Nedir o kuyulara iğliği, damlara tırmanığı

Kanamış ibiğinden oğlanların ürktüğü

Horozlar eşiniyor zincirleme

Merdivene çömel de bak, cumbaya uzan

Gün battı çivileme

Sen açarsın kapıyı, daha gelmedi dersin

Yalan mı, her ikindi uğramam eve', 'Kapı çalındığında ben belki uyumuşum Belki azıcık bahçe dikiyorum bir saksıya Şimdi yaz bahar ayı, kim kime kanıksıya Evet, evliyim bir çocu...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/horozdan-korkan-oglan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sofra Adabı', 'sofra-adabi-metin-eloglu-vr961', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşkek şu kazanda kaynar, benim bildiğim; 

Şu güveçte helmelenir fasulya.

Kuzu şu kadar ateşte çevrilir; 

Tuzlama şu tabağa konur ille..

Yumurta şu sahana kırılır.

Çorba mı? Çorba şu kaşıkla içilir tabii, 

Hoşaf bu kaşıkla..

İster uskumru olsun, ister kolyoz, 

İster orkinoz, ister hanos; 

Balık şu bıçakla kesilir..

Şarap siyahsa şu kadehe konur elbet, 

Beyazsa bu kadehe

Yavan ekmeği nasıl yersen ye...', 'Keşkek şu kazanda kaynar, benim bildiğim;  Şu güveçte helmelenir fasulya. Kuzu şu kadar ateşte çevrilir;  Tuzlama şu tabağa konur ille.. Yum...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sofra-adabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Armalar', 'armalar-edip-cansever-nrqi7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-I-

O sabah, orada, bir başıma

Var mıydım, yok muydum, anlamıyordum ki

Kalakalmış gibiydim aklımda.

-II-

Yalnızken ve senden bu kadar uzakta

Öyle soğuk, öyle anlamsız ki her şey

Sevilen bir insan yüzünde ne yoksa.

-III-

Duyuyorum çıtırtısını gözlerimde

Önümde uzayıp giden kumsalın

Bir deniz minaresinin diliyle

Farkındayım sessizliğe ve

Sonsuzluğa çağrıldığımın.

-IV-

Onlar mı, dedim, kendi kendime

Ne olacak deniz kelebekleri işte

Doldurmuşlar erkenden kumsalı

Oyaladı saatlerce beni bu

Görünen bir şeyle görünmeyen bir şeyin pazarlığı.

-V-

Yağmur yağmur yağmur

Uçsuz bucaksız bir deniz

Anısız, sonrasız, bizbizeyiz

Devinimsiz bir yüz gibi terlemekte zaman.', '-I- O sabah, orada, bir başıma Var mıydım, yok muydum, anlamıyordum ki Kalakalmış gibiydim aklımda. -II- Yalnızken ve senden bu kadar uzakta...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/armalar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onyıl''dan', 'onyil-dan-ozgen-seckin-m5z97', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey sevgili

şiirimin bir yerinde sen

sonsuz tahammülsün

	selamını aldım ağır sorgudaydım

	hafifledi ağrılarım

	sigaranı verediler ekmeğini

	biliyorum büküldü boynun

	kuzusu ayrılmış bir koyun gibi

	dağıttın saçlarını yoldun

	gecelerde iş tutmuş gibi düşlerin

	hep kara hep korkunç hep koşmaca

	yürüyor çocuklarımız yalnızlığa

	öfkeni öğrendim gördüm düşümde

	kapıları bir bir zincirleri bir bir

	kat kokusu da sözcüklerime

	şiirim bitmesin sensiz', 'Ey sevgili şiirimin bir yerinde sen sonsuz tahammülsün 	selamını aldım ağır sorgudaydım 	hafifledi ağrılarım 	sigaranı verediler ekmeğini 	b...', ARRAY['Türk Edebiyatı','Şiir','Özgen Seçkin']::text[], 8.5, '{"poet":"Özgen Seçkin","poet_slug":"ozgen-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onyil-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim İlkin Yaşamak Ne', 'ogrendim-i-lkin-yasamak-ne-ozgen-seckin-e68ev', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir gün görmüşüm ki

onca yıl suladığım fide

beslediğim dal

başkasına tohum verir

başkasını serin tutar

bir gün görmüşüm ki

ağzımda sandığım bal

başka boğazlardan akar', 'bir gün görmüşüm ki onca yıl suladığım fide beslediğim dal başkasına tohum verir başkasını serin tutar bir gün görmüşüm ki ağzımda sandığım ...', ARRAY['Türk Edebiyatı','Şiir','Özgen Seçkin']::text[], 8.5, '{"poet":"Özgen Seçkin","poet_slug":"ozgen-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ogrendim-ilkin-yasamak-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılmaz', 'yilmaz-ozgen-seckin-5l2zw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kapadılar aydınlığı zindanlara

zindanlar aydınlık şimdi, 

çiçeği tomurcuğunda

ağacı bir filizken

sıkıştırdılar iki taş arasına

taşlar çimenlik şimdi

her gediğinde taşların

bir meyve gözeder şimdi

onurlu yaşamanın sevinci

ne de büyük kılıyor kişiyi

ne de güzelleşiyor

her uyanışta insan

atarken tan

kitlelere ışık taşıyor işte

yılmaz''ın hayatından.', 'kapadılar aydınlığı zindanlara zindanlar aydınlık şimdi,  çiçeği tomurcuğunda ağacı bir filizken sıkıştırdılar iki taş arasına taşlar çimenl...', ARRAY['Türk Edebiyatı','Şiir','Özgen Seçkin']::text[], 8.5, '{"poet":"Özgen Seçkin","poet_slug":"ozgen-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kokuyordu Gökyüzü', 'yildiz-kokuyordu-gokyuzu-oya-uysal-cwhoz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aşklık yer aradık güvertede iliştik

ayışığına tuttuk yüzümüzü.

Uçuştu

saçlarımıza serpiştirilmiş tek tük ağarmış tel

açık kalmış göğün penceresinden.

Yıldız kokuyordu gökyüzü.

Işıklarını sarkıtmış suya

kımıldıyor şehir

seçilmiş düşler tutturulmuş yakaya

el tersiyle itilmiş sığıntı dün.

İskelede

dantelli bluzumun fırfırıyla oynaşırken rüzgar

çekip gitti ''kalın sağlıcakla''sız vapurumuz

usuldan içime dönmüştüm bile

çoktan çimdiklenmişti hüzün.', 'Bir aşklık yer aradık güvertede iliştik ayışığına tuttuk yüzümüzü. Uçuştu saçlarımıza serpiştirilmiş tek tük ağarmış tel açık kalmış göğün p...', ARRAY['Türk Edebiyatı','Şiir','Oya Uysal']::text[], 8.5, '{"poet":"Oya Uysal","poet_slug":"oya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildiz-kokuyordu-gokyuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuruma Düşen Nehir', 'ucuruma-dusen-nehir-oya-uysal-wxzyi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sende bu yükseklik korkusu, 

boşluğunun kıyısından geçmişe baktığın gün mü başladı

oturduğun yerden seyrettiğin kuşlar bile ürpertiyor içini.

İçin ki uğultulu bir orman. Ruhunu çizen, kanatan dallar ve rüzgar...

- Ah! kalbin sürgün günlerinden kalma hüzün

				diyorsun

yüzünde güzden gölgelerle karşılarken akşamı

kucağında yalnızlığına sürtünen kedin.

Tanımlamak gerekirse bir imgeyle seni

	uçuruma düşen nehir... Oysa şehir

aşağıdan seni çağırıyor.', 'Sende bu yükseklik korkusu,  boşluğunun kıyısından geçmişe baktığın gün mü başladı oturduğun yerden seyrettiğin kuşlar bile ürpertiyor içini...', ARRAY['Türk Edebiyatı','Şiir','Oya Uysal']::text[], 8.5, '{"poet":"Oya Uysal","poet_slug":"oya-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ucuruma-dusen-nehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelkenli', 'yelkenli-osman-caliskan-hjcqt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağır bir sis çökmüş, gökkarabulut, deniz kirli ve derin

nasıl dalgalanmakta efeliğine bakın şu beyaz yelkenlinin.

Yol alacak biraz sonra mavi sulara, okyanuslara

masmavi özgürlük olacak içi dışı, serenleri yüreklerimizde serin.', 'Ağır bir sis çökmüş, gökkarabulut, deniz kirli ve derin nasıl dalgalanmakta efeliğine bakın şu beyaz yelkenlinin. Yol alacak biraz sonra mav...', ARRAY['Türk Edebiyatı','Şiir','Osman Çalışkan']::text[], 8.5, '{"poet":"Osman Çalışkan","poet_slug":"osman-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yelkenli-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ark Suyu Acın', 'ark-suyu-acin-osman-caliskan-x3lz3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoruluverirsin kaç gündür

Durup soluklanırsın

Hüzünlü zamanındır

Gözlerin doruklanır.

Göğsün sıkıştı gibi

Yüreğin kabar kabar

Arada bir çar-par

Yazıklanır.

Kardeş ne yapsan dağılmaz

Emekçilerin acılarıyla yöndeş

Ark suyudur oluklanır.', 'Yoruluverirsin kaç gündür Durup soluklanırsın Hüzünlü zamanındır Gözlerin doruklanır. Göğsün sıkıştı gibi Yüreğin kabar kabar Arada bir çar-...', ARRAY['Türk Edebiyatı','Şiir','Osman Çalışkan']::text[], 8.5, '{"poet":"Osman Çalışkan","poet_slug":"osman-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ark-suyu-acin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılarımız Geçer Yüzyıllar Sonra', 'anilarimiz-gecer-yuzyillar-sonra-siyami-ozel-ofpt5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar öncesi ölesiye mutluyduk

Şimdi ne kaldı elde o anılardan

Küllenmiş bir sızı belki zaman zaman hatırlanan

Sonra kimler geldi, kimler geçti bilinmez

At sürüp kılıç kuşandığımız ovalardan

Ben siyah perçemli şehzadeyim sözde

Sen düşlerimde altın saçlı sultan

Düşündüm, yedi uzun yıl geçmiş aradan

Yedi uzun yıl... zaman zaman hatırlanan

Sana mutlu yaşantılar dilemiştim

Çünkü ayrı çizilmişti yollarımız

''Başka çözüm yok'' demiştin sarı saçlı sultanım

Ve kırıldı işte kolumuz, kanadımız...

Şimdi düşünüyorum da avutuyorum kendimi

Anılarımız geçer yüzyıllar sonra belki

At sürüp kılıç kuşandığımız ovalardan...', 'Yıllar öncesi ölesiye mutluyduk Şimdi ne kaldı elde o anılardan Küllenmiş bir sızı belki zaman zaman hatırlanan Sonra kimler geldi, kimler g...', ARRAY['Türk Edebiyatı','Şiir','Siyami Özel']::text[], 8.5, '{"poet":"Siyami Özel","poet_slug":"siyami-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anilarimiz-gecer-yuzyillar-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak Kadınlar Şiiri', 'korkak-kadinlar-siiri-gulten-akin-itkgk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlar için pazarlar, erkekler

sevda ile sıkıntı arasında

bir gider bir gelirler

gencömrü aşmak, bir dağı aşmak

sırtta çocuklar

sonra da genç sanmaları kendilerini

ol sebeptendir.

saati sormadan korkuları vardır

yitirmek tek yılgı

sevdikleri sevmedikleri de olmuşsa zamanla

şakırlar sevdiklerini de

ötekini nevroza dönüştürüp saklarlar.', 'Onlar için pazarlar, erkekler sevda ile sıkıntı arasında bir gider bir gelirler gencömrü aşmak, bir dağı aşmak sırtta çocuklar sonra da genç...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akın']::text[], 8.5, '{"poet":"Gülten Akın","poet_slug":"gulten-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkak-kadinlar-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapı', 'yapi-gulten-akin-kw51d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ötekini yıkarlar, eskiden gecelerdi

şimdi açık açığa gündüzün

sağ eller silahta, ele güne karşı yasa

çatılıyor yenisi

kimi yapılar bizimdi kaldık içinde

bir baktık var bir baktık hayal

yıkılsa yıkılsa dediydik ömrümüzce

öteki

kimi yapılardı, uzun sürdü uzun sürdü', 'ötekini yıkarlar, eskiden gecelerdi şimdi açık açığa gündüzün sağ eller silahta, ele güne karşı yasa çatılıyor yenisi kimi yapılar bizimdi k...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akın']::text[], 8.5, '{"poet":"Gülten Akın","poet_slug":"gulten-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar ile Boşluktaki Adam', 'yildizlar-ile-bosluktaki-adam-gulten-akin-h9r8i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hep ondan çoğalır kâğıtlarda

Hep o Meryemsi duruşundan

Döker el kadar Avrupalı yüzünü

Paylaşır milyonla aç adam

Masal ister milyonla aç adam

Soylu ister kral ister -Değildir kendi-

Ve gelsin bir kral kral pazarından

Ve gelsin üç prens kral pazarından

-İlginç olur masalları soylu kişilerin- 

Bir ergen odanın kolay köşesinde

Acıkmaz usanmaz umutsuzlanmaz

Yoncasının dört yaprağı vardır

Binlerce gözüyle boşluktaki adam

Uzanır düşsel bir incelikten

Onu kendi gecesine alır', 'Hep ondan çoğalır kâğıtlarda Hep o Meryemsi duruşundan Döker el kadar Avrupalı yüzünü Paylaşır milyonla aç adam Masal ister milyonla aç adam...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akın']::text[], 8.5, '{"poet":"Gülten Akın","poet_slug":"gulten-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildizlar-ile-bosluktaki-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüseyni Şarkı', 'huseyni-sarki-gazanfer-eryuksel-c2696', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sabah hiç olmadı sanki

sıcaktı... ne öğle, ne ikindi

acemi bir çalgıcıydı akşam

o utangaç aşık...

dön dolaş, dön dolaş dur

ne esinti, ne rüzgar...

çoktan savuşup gitmişti zaman

taneye dönmüş başakların

ağır, usul yürüyüşüydü

yazıda yazın yazgısı...

sözcükleri gördüm sonra

biçer döverin bekleyen

ekinler misal

yazar-çizerin bekleyen

o dingin / dil ekinleri...

akşam / hiç gitmemişti sanki

gurubu yakut kadehlerde sunan

gökçek sürgünü zamanın...', 'sabah hiç olmadı sanki sıcaktı... ne öğle, ne ikindi acemi bir çalgıcıydı akşam o utangaç aşık... dön dolaş, dön dolaş dur ne esinti, ne rüz...', ARRAY['Türk Edebiyatı','Şiir','Gazanfer Eryüksel']::text[], 8.5, '{"poet":"Gazanfer Eryüksel","poet_slug":"gazanfer-eryuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huseyni-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nikriz Şarkı', 'nikriz-sarki-gazanfer-eryuksel-2kkj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aynalarda eritiyoruz geceyi

gün düşmüş saçlarında

ilkyaz esintisi

aşk işte / sanki ayrılık gibi

düş kırıklarında yalınayak bir

güz yürüyor sanki... gazeller

ki ah /

örselenmiş kasımpatlarının

utangaç gözleri...

kaçıncı uyanışı bu sevginin

yağmurun yitiren bulut

rüzgardan korkar mı hiç! 

yitiklerini örten o gök

görebilseydi / ah görebilseydi keşke

saklı yüzünü

aynalarda ergiyen düşlerin

yıldız desenli bir geceyle örtün

çöllerini kainatın...

boz yazıda bir yaz daha

yürüyor işte... gazel buseli bir

güzün / hüzünbaz bestesine...

kaçıncı uyanışı bu sevginin

ayrılıktan korkan

aşka durur mu hiç!', 'aynalarda eritiyoruz geceyi gün düşmüş saçlarında ilkyaz esintisi aşk işte / sanki ayrılık gibi düş kırıklarında yalınayak bir güz yürüyor s...', ARRAY['Türk Edebiyatı','Şiir','Gazanfer Eryüksel']::text[], 8.5, '{"poet":"Gazanfer Eryüksel","poet_slug":"gazanfer-eryuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nikriz-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorumsuz Tarih', 'yorumsuz-tarih-gazanfer-eryuksel-30zo6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zamanın ceplerinde acı kırıntıları

dalgınlığı ormanda kılıcını yitiren

kahramanların... bir ölü geliyor kente

nasıl da yorgun, nikbin... hanların

tahta masalarında

ahşap kupalar ve şarap tortuları...

belleği bilenen kırlar

mavi gelincikler seriyor

ufkun buğusuna..

sokaklar alüminyum grisi

bakır kızılı bir güneş camlarda

bahçelerin çağla yeşili suskun-

luğunda bir kuyu... menekşe moru

hüzünler uykuda. şeker pembesi

pamuk helvalarıyla bayram yerleri

salıncaklar çocukluğu.. tel dolap-

larda otlu peynir, sele zeytini

ve kekik: ölümü kuşanmış dirim

beden dili kutsanmş lanetlilerin.

kente giriş çıkış yasak... ölüm

bir haç boyunda çocuk ölülerin! 

veba salgınında karantina dehlizleri

tutkuyu çizen pentür.. ömrün aykırı

aşk desenleri.

gövdesini tinsel bir ezginin

devinimi gibi sevdi.. aynalarda

çoğalan bedeni esrik yol havası

göçlerin. dil''inde o tümce

sözcük biçim değildir

görme ışığı şey''leri

yalın iklimi çıplaklığın.

enfiye kutularında pastel bir resim

gizli bir tarih. kıyısına varılan o

deniz özgürlük sanki!', 'zamanın ceplerinde acı kırıntıları dalgınlığı ormanda kılıcını yitiren kahramanların... bir ölü geliyor kente nasıl da yorgun, nikbin... han...', ARRAY['Türk Edebiyatı','Şiir','Gazanfer Eryüksel']::text[], 8.5, '{"poet":"Gazanfer Eryüksel","poet_slug":"gazanfer-eryuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yorumsuz-tarih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tasma', 'tasma-nihat-ziyalan-3urz9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kayışın boyunca koşturdum

zınk diye durdum kendimi hala koşuyor sanarak

ne kadar çırpınsam

bitiremiyorum durmamı

daha sabahı kaldırmadan

atlet don

kayışın boyunca bir yüz metre

dilim bir karış dışarda

oturmuş tasma

ağaç mağaç tüm manzara cin

faka basıp çıkmıyor yoluma

göğüs ilerde

karın içerdeyim

yağdanlıkçıbaşı kayışı saatinde

yağladı

dayanmasını yokladı

küçük bir direnme

zınk kayışın boyunca

kükremem de para etmiyor

çakık

kalığım yerimde

dizimde kolumda aynalanma

yağdanlıkçıbaşı kayışı saatinde

yağladı

dayanmasını yokladı

geçirebilsem elime bir sopa

vururdum kıçıma

koş kopar başını

koparıp önüne koy yağdanlıkçıbaşının

isterse yere çalsın kellemi

unufak etsin

tasmasız

kayışsız boyunca', 'kayışın boyunca koşturdum zınk diye durdum kendimi hala koşuyor sanarak ne kadar çırpınsam bitiremiyorum durmamı daha sabahı kaldırmadan atl...', ARRAY['Türk Edebiyatı','Şiir','Nihat Ziyalan']::text[], 8.5, '{"poet":"Nihat Ziyalan","poet_slug":"nihat-ziyalan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirazben', 'kirazben-nihat-ziyalan-2gx0e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çekirdeğimin zorlamasındandır

yuvarlaklığım

hadımdı

bıçak ışıltısı benzeri sözlerim

doyamadım çiçeğime

kısır kaldım

sıçrattı korku

köküm erken oynatıldım

çöktürüldüm cıvık

kekeme kaldım

boy attım kamaştıran

allanıp

diri

çullanmış bir avazdım

beklerim ivecen

yürümesini

can suyumun

teyellemesini

çözülen belimin ipliğini

kirazben', 'çekirdeğimin zorlamasındandır yuvarlaklığım hadımdı bıçak ışıltısı benzeri sözlerim doyamadım çiçeğime kısır kaldım sıçrattı korku köküm erk...', ARRAY['Türk Edebiyatı','Şiir','Nihat Ziyalan']::text[], 8.5, '{"poet":"Nihat Ziyalan","poet_slug":"nihat-ziyalan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirazben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Bir Masal Şimdi...', 'dun-bir-masal-simdi-elif-gevgilili-pyd6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Topladılar yeryüzü 

                          çocuk ve tanrı, ''

Ayırıp dikenleri

can verirken yitiklere

kimin bu ölüm

                                     ''bir çığlığın

                                     soluğunda büyüyen? ..''

Saklayıp günler

zamandan

kaçarken yarına

bu hangi başlangıç, bitmemiş bir gecenin

sabahında bekleyen? 

                                     ''dökülüp içine

                                     yaşadı dışında, ...''

Soyup biçimleri

dinlerken yeryüzünü

bu nasıl sessizlik, hiç söylenmemişsin

yüklenmiş anlamını? 

                                     ''hep sustu o

                                     duydum usulca, ''

Anlattığı bir su...', '''Topladılar yeryüzü                            çocuk ve tanrı, '' Ayırıp dikenleri can verirken yitiklere kimin bu ölüm                      ...', ARRAY['Türk Edebiyatı','Şiir','Elif Gevgilili']::text[], 8.5, '{"poet":"Elif Gevgilili","poet_slug":"elif-gevgilili","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dun-bir-masal-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardiyalar', 'vardiyalar-cetin-boga-t39t3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahın köründe başlar

Acı dolu her günümüz

Kanal''ın köprüsünde toplanıp

Sonra yine döndüğümüz.

Herkes uyurken geceleri

Fabrikaya ulaşır otobüsümüz

Bükeriz ipliğini sevgilerin

Vardiyalardır ömrümüz...', 'Sabahın köründe başlar Acı dolu her günümüz Kanal''ın köprüsünde toplanıp Sonra yine döndüğümüz. Herkes uyurken geceleri Fabrikaya ulaşır oto...', ARRAY['Türk Edebiyatı','Şiir','Çetin Boğa']::text[], 8.5, '{"poet":"Çetin Boğa","poet_slug":"cetin-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vardiyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Çiçekleri', 'bahar-cicekleri-cetin-boga-ngmye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sizdiniz, hüznümü dipdiri sevinçlere dönüştüren.

Sizinle ses bulurum, sizinle yenilenirdim.

Gözlerimdeki o derin acıyı usulca silerdiniz.

Işığınızla eriyip tükenirdi, yüreğimdeki o karanlık mevsim.

Varlığınızla mutlu olurdum, umutlanırdım, sanki yeniden doğardım.

İçtenliğin o coşkulu pınarlarından süzülüp gelen, 

en sıcak sevgilerle dolu güzelliklerdiniz.

İçimde durmadan filizlenen ey bahar çiçekleri, 

sizdiniz evet siz; bir küçük gülümseyişinizle ellerime hayat veren.

Ve ben; hep yanıbaşımda duydukça soluğunuzu, 

öylesine yaşamak isteğiyle dolardım...', 'Sizdiniz, hüznümü dipdiri sevinçlere dönüştüren. Sizinle ses bulurum, sizinle yenilenirdim. Gözlerimdeki o derin acıyı usulca silerdiniz. Iş...', ARRAY['Türk Edebiyatı','Şiir','Çetin Boğa']::text[], 8.5, '{"poet":"Çetin Boğa","poet_slug":"cetin-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bahar-cicekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-cetin-boga-gxner', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyle aşkları severim ben

Sevgilin bırakıp gitmeli seni

Ansızın varolmalı her şey

Vurulup birdenbire ve ayrılıklar

Sonra ıslak bir hüzün! 

Ve yokluğun olan şarkılarda

Böyle yaşları severim ben

Gözlerin sıcak bir akşam

Unutulup birdenbire

Aradığım sesini söylemeli...', 'Böyle aşkları severim ben Sevgilin bırakıp gitmeli seni Ansızın varolmalı her şey Vurulup birdenbire ve ayrılıklar Sonra ıslak bir hüzün!  V...', ARRAY['Türk Edebiyatı','Şiir','Çetin Boğa']::text[], 8.5, '{"poet":"Çetin Boğa","poet_slug":"cetin-boga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ansizin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Üşümek', 'cok-usumek-turgut-uyar-1ix9n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir Kalır uzun resimlerde anısı sakallarımızın

urban içinde Üşüyüp Üşüyüp kaldığımızın

Bir Kalır yanık yağlar kokusu şehirlerde

Uzun nehirlere binip uzaklaşmadıkça

Bir Ka
..........
..........', 'Bir Kalır uzun resimlerde anısı sakallarımızın urban içinde Üşüyüp Üşüyüp kaldığımızın Bir Kalır yanık yağlar kokusu şehirlerde Uzun nehirle...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cok-usumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtarmak Bütün Kaygıları', 'kurtarmak-butun-kaygilari-turgut-uyar-axqgd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sularsa akmak birgün birgün birgün

Birgün dağlara çıkmak birer birer dağlara çıkmak birgün

Çıkmak çıkmak birer birer birgün dağlara dağlara birgün

Birgün birer dağlara

Ah nasıl dağlara birgün

Ey yorgun atlar, ey geri dönenler, sayı bilmiyen çocuklar

Ey bir
..........
..........', 'Sularsa akmak birgün birgün birgün Birgün dağlara çıkmak birer birer dağlara çıkmak birgün Çıkmak çıkmak birer birer birgün dağlara dağlara ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kurtarmak-butun-kaygilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabuklu Balık', 'kabuklu-balik-hasan-sisli-cywnp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yanık çakıl taşı

gezgin güneş altında

yere bakıyor bir yüzü

yuvarlacık damarlı

bir gözünde gökyüzü

tut elinde sıcak çöreği

üfleye üfleye

avucunda çevirdikçe

çift dünyalısın birden

yüreğin yıldız pencereleri

düş gerçek

döne döne

gerçek düş

destanları dünün masalları

böyle sık sık kime

gökten üç elma düşmüş

eski sularda yüzer gibi

yanıyor taşın içinde

- avuçta tutulmaktan -

kabuklu bir balık kristali', 'yanık çakıl taşı gezgin güneş altında yere bakıyor bir yüzü yuvarlacık damarlı bir gözünde gökyüzü tut elinde sıcak çöreği üfleye üfleye avu...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şişli']::text[], 8.5, '{"poet":"Hasan Şişli","poet_slug":"hasan-sisli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kabuklu-balik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerlerde', 'yerlerde-hikmet-szlemiolur-blgjn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kosmanin ve konusmanin farkli olmadigi bir yer

beklemek ve dusunmek krizleri

camurdan kurulmus bir kale

icinde bocalalyan 

ayak izleri

sen benim zamanimda

sanki birinci suclu

koparcasina sevdigim bir anlam icinde

bulutlar yagmurdan

saskinligin ve ardindan dokulen

kul rengi izler

dunyayi ters dondurup

parmagimda oynatirken

yuzume bir sille gibi gelen ikinci alem

sehirde dusunceleri carpiyor yuzume insanlarin

ve yurunmez oluyor sokaklari aklin

yaprak ve firtinanin butunleyici iliskisi

bir ferman yazilmis kara kapli defterlere

fikrimiz kare, en kutsalimiz en ust rafta 

hikmet oturmus ustune ilimin, kaldirip alan yok

ve ''e'' gecmis butun alfabelerin otesine

bir altigen elleri

insan sarhos, insan aptal

insan birakmis degerini bir koseye

sokaklara atmis kendini

aramakta haril haril

ve sakalli bir adam kaldirimlara girmis ilerlemekte

insan seyr etmekte, 

gozleri ellerin elinde

bir zindan acilir alemde

icinde ucuncu suclu

ve dagiliyor kafamda ulkeler

vucudum ayilmakta

uc kursun girmis

uc ferman yazilmakta

daglar fermanlar, daglar ben

daglar yazgimiz gulum, 

daglar menzil

kahpe bir sorguya

vurulup dusmus mekan

ve dokuz boyuta bolunmus alem, 

tane tane

gozlerden fiskiran 

kan 

yesile calan istekler

ve 

karargahidir omrun

kucaklari

kanli kursundur

metalin ve cesedin birlestigi yer yani

kursunun varis noktasi

agaclar yani gulum

bozkirlarin daveti

ve iste bir muhasebesi bu

ucgenin dogrulara ayrismasi

adim adim

yaklasti bir gun ankaraya

uc insan uc ben ayrilmakta

anlamsiz bakislarda', 'kosmanin ve konusmanin farkli olmadigi bir yer beklemek ve dusunmek krizleri camurdan kurulmus bir kale icinde bocalalyan  ayak izleri sen b...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yerlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-turgut-erdogan-h7kqx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Havada Çukurova sıcağı, 

Gece soğuk.

Kendi usumuzda düşman doğurduk, 

Kan akıttık oluk oluk.

Gel etme yar! 

Törpü olmak neye yarar? 

Ak düşmüşse saçlara, 

Rahvan gidiyorsa şu ömür.

Nergis tomurcukken koparılırsa, 

Bir kuş dalında vurulursa, 

Sevda yürekte yorulursa, 

Yaşamak neye yarar.

Oyy havar…

Beden huzursuzsa toprakta, 

Ruh huzursuzsa öte tarafta, 

Türkü tedirginse mızrapta, 

Can sabırsızsa vücutta, 

Yaşamak neye yarar.

Alanya 16/09/2002', 'Havada Çukurova sıcağı,  Gece soğuk. Kendi usumuzda düşman doğurduk,  Kan akıttık oluk oluk. Gel etme yar!  Törpü olmak neye yarar?  Ak düşm...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Tutkusu', 'yasamak-tutkusu-aysin-ulug-1rsnh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşamak tutkusuna sarılmış

ellerimde sen varsın sımsıcak

düşündüğüm bir tek hayatımız

ne iş ne de dünya umurumda

gözlerimden geçen şu deniz manzarası

sensiz bir hiç

seninle masmavi düşlerim

yüzüme değen rüzgar

sensiz bir buz bahar akşamlarında

seninle bir yaz gecesinde yakamoz pırıltısı

yaşamak tutkusu

kurak topraklarında filizlendi ömrümün

şimdi o kadar derindeki kökleri

bir tek aşkın suluyor meyvelerimi

dostuma düşmanıma aşk diliyorum senden beri

dostlarım daha mutlu olsun

düşmanlarım doğruyu bulsun diye

yaşamak tutkusu

yanımda kal

yanımda kalsın bir ömür boyu

bu dünya bu gökyüzü

ister bu topraklar ister denizaşırı başka diyarlar

sen nerdeysen orda yaşarım

başka hiç birşey istemem

yaşamak tutkusu bu

nefesin yüzüme değerken uyanmak

başım göğsünde uykuya dalmak.

ne iş ne dünya umurumda

bir sen ol

sen kal yanımda...', 'yaşamak tutkusuna sarılmış ellerimde sen varsın sımsıcak düşündüğüm bir tek hayatımız ne iş ne de dünya umurumda gözlerimden geçen şu deniz ...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yasamak-tutkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutulacaksın', 'tutulacaksin-tulun-ceylan-ku7br', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tutuldun mu? 

Şöyle en ateşlisinden 

Yattığın yatağı

Yatağının tabanını tavanını

Alevlendiren cinsinden 

Gribe tutulacaksın

Ya da ne bileyim? 

Tutuldun mu? 

Sıtmalarda titreyip

Saralarda nöbetleyip

Ruhuna en yabancı anıları

Çöllere süreceksin

Tutulmak

En günahlısından

AİDS''e ya da 

Ses hızıyla çoğalanından kansere

İki soluk arasına, beş yaşamı hapsedeceksin

Tutul vebalara, cüzzama

Hadi şu ender bulunan 

Behçet''e tutul

Ama tutulma buna

Eğer

İskeletinin sol üst ucunda 

Mumyalanmış bir bebek saflığında

Saklayabiliyorsan yüreğini

Ona tutulacaksın

Tutulacaksan

Hazinelere gebe timülüslerin koynunda

Çiçek açmayı bekleyen bir çiğdem''e didem''e tutul', 'Tutuldun mu?  Şöyle en ateşlisinden  Yattığın yatağı Yatağının tabanını tavanını Alevlendiren cinsinden  Gribe tutulacaksın Ya da ne bileyim...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tutulacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkem', 'ulkem-serkan-kukrer-ln22y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sadece umut

Zifiri karanlık bir geceye direniş

Ayışığı dolmak

Varlık sebebi

Ona karşı direnip, onsuz olmamak

Yaşamak için bir ışık aramak

Sonra tükeniş, yılgınlık', 'Sadece umut Zifiri karanlık bir geceye direniş Ayışığı dolmak Varlık sebebi Ona karşı direnip, onsuz olmamak Yaşamak için bir ışık aramak So...', ARRAY['Türk Edebiyatı','Şiir','Serkan Kükrer']::text[], 8.5, '{"poet":"Serkan Kükrer","poet_slug":"serkan-kukrer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ulkem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-serkan-kukrer-9aq1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmedim gurbeti

Sevmedim ayrılmayı

Sevdiklerimden ayrı kalmayı

Hep ağladım

         ayrılırken evimden

Yıllar geçti

          dönemedim gurbetten.', 'Sevmedim gurbeti Sevmedim ayrılmayı Sevdiklerimden ayrı kalmayı Hep ağladım          ayrılırken evimden Yıllar geçti           dönemedim gur...', ARRAY['Türk Edebiyatı','Şiir','Serkan Kükrer']::text[], 8.5, '{"poet":"Serkan Kükrer","poet_slug":"serkan-kukrer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gurbet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-serkan-kukrer-3inka', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl doldurabilirdim ki boşluğunu! 

O kadar büyüktü ki içimde

İnan, dağlar gibi uluydu

O kadar gölkemli, o kadar korkunçtu

Sakın unutmamı bekleme

Bağışla ne olur beni

Koyamadım yerine', 'Nasıl doldurabilirdim ki boşluğunu!  O kadar büyüktü ki içimde İnan, dağlar gibi uluydu O kadar gölkemli, o kadar korkunçtu Sakın unutmamı b...', ARRAY['Türk Edebiyatı','Şiir','Serkan Kükrer']::text[], 8.5, '{"poet":"Serkan Kükrer","poet_slug":"serkan-kukrer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yoksun-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Alıp Gittin', 'ne-alip-gittin-mehmet-demirel-2-y4ri1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'söyle ne alıp gittin benden

yokluğunu bilirim ben senin

bu kadar yokluğun yoktu senin

söyle ne alıp gittin benden

olmazlığınıda bilirim ben senin

bu kadar olmazlığın olmazdı senin

söyle ne alıp gittin benden

yokluğun olmazlığın senin

var olur bende', 'söyle ne alıp gittin benden yokluğunu bilirim ben senin bu kadar yokluğun yoktu senin söyle ne alıp gittin benden olmazlığınıda bilirim ben ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demirel 2']::text[], 8.5, '{"poet":"Mehmet Demirel 2","poet_slug":"mehmet-demirel-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-alip-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolarına Baka Baka', 'yolarina-baka-baka-huseyin-cayikli-bcu5c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yollarına baka baka ayrıldım 

oysa sesini bile duymadan elini tutmadan

ağlamadan senden geçtim

yüzünü son bir kez gördüm 

giderken son hatıram olur diye.

yollarına baka baka evinin önünden geçtim

sigara yaktım ağlamadım.

unuttum dediğimde anladım 

sana alıştığımı

oysa senin yanında bir adam benim yanımda yalnızlık vardı.

şimdi ayrılık vakti.

şimdi vazgeçmek vakti.

şimdi seni ele verme vakti.

umarım hep gül

gül ki insanlaş

inan bana gülmeyi öğrendin

ben gittiğimden beri...', 'yollarına baka baka ayrıldım  oysa sesini bile duymadan elini tutmadan ağlamadan senden geçtim yüzünü son bir kez gördüm  giderken son hatır...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yolarina-baka-baka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kökün Çürümüş Senin', 'kokun-curumus-senin-cahit-i-pekoglu-nlw4w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni hep ağaca benzettim

aşkla köklerin büyür zannettim.

Ne kadar yüreğimden su versemde

senin için çürümüş.

Aşkım bile kar etmedi...

Tepeden tırnağa sevdim seniyetmedi

boğulmak istediğim yüreğin görülmedi.

Sen aşkı değil, sonsuzluğu seçtin

gövdeni beslesende kökün buna yetmedi.

Sonsuzluğum dediğin şey yalanmış

kökün kurumuş, aşkım bile sana yetmedi...

Sen değişik bir ağaçsın

Aşkla, sevgiyle beslenirsen ölürsün.

Sonunu görebileceğin toprağı seçersin

kökün olsada olur, olmasada...

Hiç düşünmedin sevgiyle beslenen kök

sevgiyle beslenirken yaşar.

Sevgisiz ölüme mahkum olan kök

sonsuzluğu görsede, hep içi boş yaşar...', 'Seni hep ağaca benzettim aşkla köklerin büyür zannettim. Ne kadar yüreğimden su versemde senin için çürümüş. Aşkım bile kar etmedi... Tepede...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kokun-curumus-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Gibi...', 'herkes-gibi-nazim-hikmet-ran-4ulfs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlümle baş başa düşündüm demin; 

Artık bir sihirsiz nefes gibisin. 

Şimdi tâ içinde bomboş kalbimin 

Akisleri sönen bir ses gibisin. 

Mâziye karışıp sevda yeminim, 

Bir anda unuttum seni, eminim 

Kalbimde kalbine yok bile kinim', 'Gönlümle baş başa düşündüm demin;  Artık bir sihirsiz nefes gibisin.  Şimdi tâ içinde bomboş kalbimin  Akisleri sönen bir ses gibisin.  Mâzi...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/herkes-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanda Yolculuk', 'zamanda-yolculuk-umit-acir-52d0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir trrensen raylar üstünde yol alan, 

Ben bir yolcuyum o ternde yolculuk yapan.

Sen yol alırsın rayların götürdüğü yönde durmadan

Ve kara bulutlarla kaplarsın masmavi gökyüzünü

Benimse elimden gelen camdan dışarı bakmaktır

Ve bir kibrit yakmak karanlık tünellerde nedemsizce 

Güzergahta ne bir durak var nede istasyon 

Güzergahta ağaç bile yok çiçek bile güneş bile

Geride kalan tek şey zaman

Şimdi ise son kibritimi yakıyorum bu sonsuz zaman tünelinde

Sen bir trensen zamana karşı yol alan 

Ray olmak isterdim senin altında her zaman', 'Sen bir trrensen raylar üstünde yol alan,  Ben bir yolcuyum o ternde yolculuk yapan. Sen yol alırsın rayların götürdüğü yönde durmadan Ve ka...', ARRAY['Türk Edebiyatı','Şiir','Ümit Acır']::text[], 8.5, '{"poet":"Ümit Acır","poet_slug":"umit-acir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zamanda-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Bir Şafaktı Bu', 'zamansiz-bir-safakti-bu-umit-acir-m1pmp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık şafak söküyor düşüncelerimde

Karanlıklar bitiyor aydınlıklar başlıyor artık

Gelecek beni bekliyor özgür düşüncelerimle birlikte

Zamansız gelen bir şafaktı bu

Oysa ben hiç şafak görmemiştim

Kararsızım çaresizim zamanım yok

Gelecek beni bekliyor özgür düşüncelerimle birlikte

Derken yine karanlık oldu 

Benmi geleceği beklesem diye', 'Artık şafak söküyor düşüncelerimde Karanlıklar bitiyor aydınlıklar başlıyor artık Gelecek beni bekliyor özgür düşüncelerimle birlikte Zamans...', ARRAY['Türk Edebiyatı','Şiir','Ümit Acır']::text[], 8.5, '{"poet":"Ümit Acır","poet_slug":"umit-acir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zamansiz-bir-safakti-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gövdesi Delik Hayaller', 'govdesi-delik-hayaller-ethem-vayvayli-ml0j8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir bakarsın, ince boylu kumlar ağlar ardından

sararmış itimatlar, gövdesi delik hayaller düşer

uzar çığlıklar özlenmiş ıslak aydınlık sokaklara

kaybolup gider öptüğüm dudakların ateş içinde

varolmak takvimlerden sıyrılıp bir anda

ansızlaşmak belki de buğular içinde çırılçıplak

kabartmak, gümüş gövdesinde bir süvari cepkeninin

yarıp yırtmak yosun yeşili geceliğini bir genç kızın

yaşamak seninle mümkün oluncaya kadar koşmak

kızgın toros patikalarında, yamaç cılgalarında

varlıkla savaş etmek, yokluğu sınamak her kez

seni sevmek, seninle karışmak sıcak kumlara

beklemek yıllarca bir ışıklı geminin geçmesini

gelecek efsuni yalnızlığı bitirip, birden

alıp götürecek beni şarabın kıyısından içeri

görkemli düşler, sancısız devinimler içinde

her gece kızarmış heykeller sunacak bana.

ama nafile herşey. çoraklaşan bir yaz ayı

her tarafta altıma yatan yorgun caddeler

kirlenmiş köşelerde bazen bir börtü böceği

bazen cebimde unutulmuş saç telleri ince, narif 

ah bilseydim sevmek benim için değil

çıkardım ince belli sülünler evinden yalnız

yalnız yırtardım bir dağın papatyalı eteğini

eğer başımı içerdim pınarından bir yudum, 

sonra göğe diker, and ederdim varlığa

ve sonsuza dek yaşamın bir mutluluk

seninse bitmeyen güzellik olduğunu düşünüp

soylu bir onurla terkederdim yatağını...

30.08.2002/A.Ayrancı', 'bir bakarsın, ince boylu kumlar ağlar ardından sararmış itimatlar, gövdesi delik hayaller düşer uzar çığlıklar özlenmiş ıslak aydınlık sokak...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/govdesi-delik-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tümce', 'tumce-mine-ozdemirtas-7cq75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk ışıkları...ilk şafağı izleyiş 

Bir çiğ damlası kadar saydam... 

Bir buz dağı gibi gizlenmiş. 

İlk sıcak dalga..bir mor ışık 

El yordamıyla uçuş.Ve, 

Duvara çarpışın sesi.. 

Onun ardından gelense sadece 

Yok oluş tümcesi.', 'Sabahın ilk ışıkları...ilk şafağı izleyiş  Bir çiğ damlası kadar saydam...  Bir buz dağı gibi gizlenmiş.  İlk sıcak dalga..bir mor ışık  El ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tumce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dindiğimde', 'dindigimde-mine-ozdemirtas-0zzrq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı, / gözlerini yaşartırcasına

Sana çok yakın geleceğim.

Yüzünde dudaklarımı hissedeceksin.

Eğilip seni öpeceğim.

Bir anda / saçının bukleleri karma karışık olacak

Duygularınsa; bin bir parça.

Islak kirpiklerin şaşkına dönecek.

Dört bir yanına sarmaş dolaş olacağım.

Deli esmiş bir rüzgar gibi dindiğimde

Müebbet yemiş olacaksın.

Ve kahredeceksin bensizliğe.', 'Bir gece yarısı, / gözlerini yaşartırcasına Sana çok yakın geleceğim. Yüzünde dudaklarımı hissedeceksin. Eğilip seni öpeceğim. Bir anda / sa...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dindigimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni', 'bekle-beni-mine-ozdemirtas-2na7i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pejmurde bir akşam üstüydü az önce, 

Resmedilmemiş tüm özlemleri koymuştum gözlerime. 

Eğer ki sen! ….Eğer ki sen! …..Seslenmeseydin Uzaklardan….. 

Doğmayacaktı şafaklar bir daha, yakılmaya hazır Mısralarımdan. 

Ola ki bir kez daha, Şairliğimin bam teline dokunursan usuldan, usuldan

 Sanırım içiçdeki şair, temelli uyanacak. Ölüm Uykusundan.. 

Parmak uçlarında dansettirmek için; 

Tutuşmamış ateşlerini gecelerin, 

O kadar yorulacak ki kemancı…Yayını tutamaz olacak elleri 

Evrenin bütün melodileri ile, İşte tam o anda! geleceğim….. 

BEKLE BENİ.', 'Pejmurde bir akşam üstüydü az önce,  Resmedilmemiş tüm özlemleri koymuştum gözlerime.  Eğer ki sen! ….Eğer ki sen! …..Seslenmeseydin Uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bekle-beni-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü İçime Atıp Söyleşirim', 'gulu-i-cime-atip-soylesirim-i-smail-karakurt-av13u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar

Baharı yaman

Gözleri güneş ve duman yar

Hangi zamandı

Seni gördüm

Gagasında zehir taşıyan kuşlarını.

Yusuf peygamberin öyküsünü anlatan

Kızların yanından geçerken

Seni gördüm

                        Esrik gezinirim! .

Yağmuru düşün

Topraktan önce yüzümüze düşen

Yüzümüzü çizik çizik eden

Keman hüznü o ince konuğu

Sonra beni düşün

Tutup incileri gülümseyen

Güzel atlara binip

Gürültülü ırmakları geçen

Ellerinde leylaklar büyüten beni.

Senden kalbime düşen şavkla

Bölünerek yürüdüğüm görülsün

Görülsün artık

Arkama alıp dünya çöplerini

Aşkın ağulu ucunu

Yüreğimde taşıdığım.

Av sahnesinden geçip

Kuyu

Saman ve pazardan sonra

Sana söylemem lazımdı

Çatlatamadığını yüzümün kayaları bazen

Kayıtsız kaldığımı güllere karşı.

Hiç mi

Hiç eskimedi tuhaflığım

Gülü içime atıp söyleşirim

Sorma bu işin esrarını

Üzeri kül hikayesi....', 'Yar Baharı yaman Gözleri güneş ve duman yar Hangi zamandı Seni gördüm Gagasında zehir taşıyan kuşlarını. Yusuf peygamberin öyküsünü anlatan ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakurt']::text[], 8.5, '{"poet":"İsmail Karakurt","poet_slug":"i-smail-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gulu-icime-atip-soylesirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yerlerden', 'bir-yerlerden-mine-ozdemirtas-9220t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR DÜŞ MÜYDÜ GÖRDÜĞÜM…/.YOKSA YAŞANDI MI GERÇEKTEN? 

HEYHAT…/ BAŞLAMADAN BİTTİ İŞTE DERKEN…. 

SESİNİ DUYAR GİBİ OLDUM / SANKİ YENİDEN. 

EVET  UZAKLARDASIN…/ AMA BİLİYORUM Kİ…./ HENÜZ ERKEN. 

EMİNİM…/BİRGÜN ÇIKIP GELECEKSİN…/ BİR YERLERDEN.', 'BİR DÜŞ MÜYDÜ GÖRDÜĞÜM…/.YOKSA YAŞANDI MI GERÇEKTEN?  HEYHAT…/ BAŞLAMADAN BİTTİ İŞTE DERKEN….  SESİNİ DUYAR GİBİ OLDUM / SANKİ YENİDEN.  EVE...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-yerlerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lekesiz dağ Nergisi', 'lekesiz-dag-nergisi-i-smail-karakurt-rgca1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bitti. Çağır beni

Su sesli. Hem tütsü hem zehir

Sararmış kitapların

Tozlu nesnelerin arasından

Uzak, ıssız bir yere

Lekesizliğe! 

Dağlara dağlara bakma

İçimdeki dağ nergisi

Sensizliğe ısınamam üşürüm

Savur kara gözlü güvercinlerini

Savur bahar ile.

Ah küçük sevgili. Ah dili yok

Lekesiz bir resim gibi yapıştırdım

Yüreğimin defterine seni

Yüzünü kopardım kırlardan

Yeni açan çiçeklerden

Yüzüne bak! 

Ağır çatısı altında güneşin

Al götür, eşsiz ve ebedi rüzgarınla

Al götür, eşsiz ve ebedi rüzgarınla

Al bu ruhu yorumla

Bu kımıltısız ruhu

İç çekişleri ve fısıltıları taze tut

Ruhunun

Işıldayan, güzel bahçesinde.

Seni seni

İçimdeki dağ nergisi

Lekesizliğe çağır beni

Anla ki ben ne çok yaralandım

Yaşamak denen bu dumanlı çalkantıda

Nasıl olsa ölümü seçeceğim bir gün

Hiçbir şey eskitmiyor ölümü....', 'Bitti. Çağır beni Su sesli. Hem tütsü hem zehir Sararmış kitapların Tozlu nesnelerin arasından Uzak, ıssız bir yere Lekesizliğe!  Dağlara da...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakurt']::text[], 8.5, '{"poet":"İsmail Karakurt","poet_slug":"i-smail-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/lekesiz-dag-nergisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair', 'sair-i-smail-karakurt-87ubd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kuytularda ışıldayan bir endişeyim ben

Yüreğimi serdim zamanın titreşen aralıklarına

Orda... uçuşuyor dünya.

Mevsimlerime dil veriyor baharın fecri

Mevsimlerime, mesellerime, bülbüllerime

Bu tabiatın ritmi, bu ateş böceği ve bu otlar

Hayatın yırtılan sessizliği bu

Tüter lekesiz ve çiğdem gözlerde

Yaşamak çağrısı, ölmek çağrısı upuzun düşen

Tutup kendimi saklıyorum tozlanmış kağıtlarda

Bir avuç tuza, üflenen hatıralara

Ve tenhasına insanların sıcak ve sessiz

Ağulum! Kefensiz biriyim işte şiirin kıyılarında

Kara bir özlemle kaderimi öpüyor annem

Öpüyor giyinmiş yağmurlarımı, yapraklarımı, kumlarımı

Öpülen yerde   s  i  m  u  r  g      r  e  s  i  m  l  e  r  i   güneşi utandıran

Kuytularda ışıldayan bir endişeyim ben!', 'Kuytularda ışıldayan bir endişeyim ben Yüreğimi serdim zamanın titreşen aralıklarına Orda... uçuşuyor dünya. Mevsimlerime dil veriyor baharı...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakurt']::text[], 8.5, '{"poet":"İsmail Karakurt","poet_slug":"i-smail-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simurg', 'simurg-i-smail-karakurt-vczgh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘eğildik

güneşin bürdesi düştü üzerimizden’

yüzümüzde ikindiler birikiyor, dilimizde sözcükler

zamanın korkuluğunda bir kuş

gibi duruyordu evren

an’ı dolduran imgelerin dumanıydı

yahut çağıltılı işaretler kervanı

orda... yaprakların altına yazıyordu kalbimizi.

Başımızı döndüren kara taş oyunu

Gibiydi hayat

Eşiğimizde çılgın fırtına

Yüzümüzde açılıp kapanan ölümün defteriydi sanki

Yaz’ı tüketip yazı üretiyorduk hep

Alnımızdakini görenler bile

Biliyordu yaz(ı)ların bedevisi olduğumuzu

Orda... her şey ve herkes savruk deniz halindeydi.

Açılan temmuzun festivali

Giydiğimiz güneş ve çayırların serinlik yüküydü

Sözcükleri hüznünün örsüne vurup

Uğultular çıkaran bir vadiydi kalbimiz

Yazın eskimiş çölünde

Kayalara düşmeden kuşlar

Yağmurları inci ve yakuttan işaretler bilirdik

Biz yağmurları hep böyle bilirdik

Orda... vedanın kanlı müziğinden önce.

Gecenin maskesini kaldırıp nasıl

Sabahı dökülürdük yollara

Eşiğimizde çılgın bir fırtına

Sorguların tahtı kurulurdu göğsümüzde

Yüzümüz gülün

Ve ölümün dokunuş kitabi, son sözdü

Güzeldi...

Kayıptı baharın içimize değip çekilen sesi

Sessizliğin rahmine akan fecir... ve otuz kuş!', '‘eğildik güneşin bürdesi düştü üzerimizden’ yüzümüzde ikindiler birikiyor, dilimizde sözcükler zamanın korkuluğunda bir kuş gibi duruyordu e...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakurt']::text[], 8.5, '{"poet":"İsmail Karakurt","poet_slug":"i-smail-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/simurg-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reenkarnasion', 'reenkarnasion-mine-ozdemirtas-zc0nd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkımsın…/ bilemeyeceğimiz kadar çok eski bir ezelden beri.

Labirentlerinde geçmişin, / elele, dudak dudağaydık belki.

Pekiştirmek içindir bence, / bu zamandaki birlikteliğimiz …/ o en eskileri.

Tapınmıştık eminim…/ asırlar önce de birbirimize.

Erkeğimdin…/ Kadınındım kollarında…/ sahiptik yüreklerimize.

Kahrolası bir ayrılık…/ büküvermişti belimizi…/ ölümdü o belki.

İçimize sığdıramadığımız özlemler çığlık olup/ takılmıştır boşluklara

Neden olmasın/ bence / bir yarımı tamlamaya geldik yeniden / bu dünyaya', 'Aşkımsın…/ bilemeyeceğimiz kadar çok eski bir ezelden beri. Labirentlerinde geçmişin, / elele, dudak dudağaydık belki. Pekiştirmek içindir b...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/reenkarnasion-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Belası', 'bas-belasi-mine-ozdemirtas-istin', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne karın olmak istiyorum,

ne de çocuklarının anası

Sadece aşığın olmak istiyorum.

Dinlesene baş belası.

Ne kirli çoraplarını yıkamaya hevesliyim,

Ne de dağınık yatağını toplamaya.

Ne ev istiyorum senden, ne de araba

Sadece aşk…. sadece aşkın, yeter bana.

Tutkunum be adam, anlasana.', 'Ne karın olmak istiyorum, ne de çocuklarının anası Sadece aşığın olmak istiyorum. Dinlesene baş belası. Ne kirli çoraplarını yıkamaya hevesl...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bas-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa Sen', 'yasa-sen-aziz-nesin-37d8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şeye boşver, dolu dolu yaşa.

Madem ki bir aşkın var, ne güzel, tadını çıkar...

Sanki ayıp bir şeymiş de utanıyormuşsun gibi

yazmışsın bana...

Her şeye boşver ve aşkı yaşa... 

İlle de büyük aşk olması gerekmez; 

yaşanan her aşk büyüktür, yeter ki tadını çıkarmasını bil...

Çok büyük umutlar bağlama, yarını hiç düşünmeden, 

günü gününe sev, sevginin tadını çıkar...

Sevgide geleceği düşünürsen aşkı, bombok edersin. Sakın haaa...

Sonsuz, monsuz diye karşındakinin başını yeme...

Her şeye boşver; öylesine sev ki, 

sevdiğini bile umursama, salt kendin için sev, 

bencilce yaşa aşkı, bütün maddesiyle...

Yaşamdan elinde kala kala salt yaşadığın

sevgiler kalır sonunda, ne şu, ne de bu...

Bütün onlar, aşkı yaşamak için gerekli olan

- ne yazık ki gerekli olan- gereklerdir.

Aslolan aşktır yaşamda...

Dolu dolu, dolu dizgin, zilzurna, saniye saniye

aşkı yaşayarak sev...

İki yıl, üç yıl sürecek diye umutlanıp enayilik etme...

İster sürer, ister sürmez... Sen o anı yaşa yeter ki...

Yitirdiğin zaman; yaşadıklarını kazanmış olacaksın...

Sonunda elbet yitireceksin, ama yitireceğini hiç

düşünme; çünkü aynı zamanda kazanmışsındır da...

Anılar kazanıyorsun daha ne...

İç o zaman, sarhoş ol...

Yüce şeyler düşünme severken, 

sevgiyi berbat edersin; çünkü sevginin

kendisinden daha yüce bir şey olamaz..

Aferin sana seviyorsan, seviliyorsan...

Sakın kuşkulara kapılma.

Karşındakini didikleme, yiyip bitirme...

Türk gelenekleri, görenekleri öyle...

Sakın bu aptallığı yapma...

Severken yirmi yıl sonrasını değil, 

yirmi dakika sonrasını bile düşünme, 

sevinin içine edersin...

An an yaşa, derin derin hem de...

Afferin sana...

Çok sevindim. İşe güce boşver.

Artık sana ne Surname''yi, 

ne de başka şeyi soruyorum.

Keyfince yaşa, sev... Sevildikçe sev, 

sevilmeyince de tastamam boşver ve

o zaman o güzelim yalnızlığına sarıl...

O yalnızlık ki, bütün sevgilerden daha güzeldir

ve sonunda onun koynuna girmek için

kendi kollarımızla kendimizi sararız...

O zaman da hiç üzülmeyeceksin.

Çünkü nasıl olsa, sığınacak bir yalnızlığımız var; 

günün birinde anamız bile bizi bırakır gider

ama o yalnızlığımız, biz yaşadıkça bizi hiç bırakmaz...

Severken bunları düşünme, lütfen yarınsız sev! 

Hadi, sevgiyle öperim.

Yaşa sen! ...', 'Her şeye boşver, dolu dolu yaşa. Madem ki bir aşkın var, ne güzel, tadını çıkar... Sanki ayıp bir şeymiş de utanıyormuşsun gibi yazmışsın ba...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesin']::text[], 8.5, '{"poet":"Aziz Nesin","poet_slug":"aziz-nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/yasa-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basamak', 'basamak-mine-ozdemirtas-odp67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yerlerde / adımı bile hatırlamayan, / eski sevdalarım yaşıyor olmalı.

Alaca bulaca bir karanlık içinde /  Kaybolmadan çok önce

Sanırım sevdim./  Evet sevdim./  Sevdim, hem de delicesine.

Ağrısız bir sünnet gibi, / Kopmayı başarabilsem - sessizce anılardan

Mor bir karanfil ekeceğim yüreğime. – Aşkın yerine.

Arsız bir sarmaşık misali, /  geçmiş kemirip dururken içimi

Kapatamıyorum. – / Kapatamıyorum ki  pencereyi.', 'Bir yerlerde / adımı bile hatırlamayan, / eski sevdalarım yaşıyor olmalı. Alaca bulaca bir karanlık içinde /  Kaybolmadan çok önce Sanırım s...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/basamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Le Violon Rouge', 'le-violon-rouge-mine-ozdemirtas-ahvrc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ASLINDA HİÇ YAŞANMAMIŞ BİR GÜNDÜ BİZİMKİ

KEŞFEDİLMEMİŞ ADALARIN KUMSALLARINDA...HİÇ YÜRÜNMEDİ Kİ

HİÇ SARILMADIN BANA VE HİÇ SARILMADIM SANA

DUDAKLARIMA, DUDAKLARININ DOKUNMASINI HİÇ DİLEMEDİM

TENİM TENİNE DEĞİP DE YANMADI ALEV ALEV

RUHLARIMIZIN BULDUĞU…HUZUR DEĞİLDİ ASLINDA

GERÇEK DEĞİLDİ

YAĞMURDAN SONRA BÜYÜYEN BAŞAKLARIN ÇIKARDIĞI SIZI

BİR DÜŞTÜ SADECE…YOLLARDAKİ ADAMIN YALNIZLIĞI

KALKARKEN YÜRÜRLÜKTEN MADDESİZ OLAN O SON MADDE

HİÇ ACITMADI...HİÇ KANATMADI...HİÇ AĞLATMADI

BİR HEVESTİ…GELDİ GEÇTİ...GÜNLÜKTÜ…ANLIKTI...İZİ KALMADI 

BİR DEMDİ SADECE..

AMA...BİR BARDAK ÇAYLIK BİLE…ZAMANI OLMADI.

ŞİİRLER YANMADI…KÜLLERİ SAVRULMADI…

BALIKLAR AĞLAMADI, SULAR YANMADI

KIRMIZI KEMAN…KIRMIZIYA….VERNİKLİ KANA… HİÇ BULANMADI

GELMEDİ HAZANLAR YEDİ TEPEYE...

ALTIN BOYNUZ..YALDIZLARA BOYANMADI

ÖYLESİNE…ÖYLESİNE BİR MASALDI İŞTE…

DEDİM YA…

ASLINDA HİÇ YAŞANMADI.', 'ASLINDA HİÇ YAŞANMAMIŞ BİR GÜNDÜ BİZİMKİ KEŞFEDİLMEMİŞ ADALARIN KUMSALLARINDA...HİÇ YÜRÜNMEDİ Kİ HİÇ SARILMADIN BANA VE HİÇ SARILMADIM SANA ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/le-violon-rouge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misketli Oğlan', 'misketli-oglan-mine-ozdemirtas-ud83m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şayet o sensen,

Bıyıklarında sallandığım adam.

Şayet o sensen...

O kısa pantalonlu

Kepçe kulaklı oğlan.

Sivilceli yüzlü

Sümükleri akan.

Komşunun bahçesinden erik çalan.

Sonra da

Bana yedirmeyip kendi yediği için

İshal olan

O sokak tocuğu, misketli oğlan

Eğer sensen...

Seninle kaçarım.

Erik ağacınada çıkarım

İp atlarız, yakartop oynarız.

Nur topu gibi misketlerimiz olur.

Sabahlara kadar tommiks okuruz.

Zilleri çalar, asansörleri durdururuz.

Eğer sevdiğim saz çalan adam sensen...

Sensen sokak tocuğu,

Kahve ekmeğimi bölüşürüm seninle...

Kurtlu elmanın şekerinden de veririm.

Artık Ebe sensin sokak tocuğu

Kapat gözlerini

Hissedeceksin.

Bu adak için göğe açtığım ellerimi.

Eğer o sensen...

Boşa hazırlamamış olacağım

ilk aşk kokan çeyizlerimi.

Ve lütfen sen ol sokak tocuğu.

Topaç çevirirken buluvermiş gibi...

Mahallede seni bekleyen mavi boncuğu.', 'Şayet o sensen, Bıyıklarında sallandığım adam. Şayet o sensen... O kısa pantalonlu Kepçe kulaklı oğlan. Sivilceli yüzlü Sümükleri akan. Komş...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/misketli-oglan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Poe^m', 'benim-poe-m-mine-ozdemirtas-c30o1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TAM YOSUNLARINI.....DALGALARA VERMEK ÜZEREYDİ Kİ YÜREĞİM,

DENİZ ÜLKESİNDE SESİN YANKILANDI SEVDİĞİM.

BİR BEN BİLİYORDUM AYRILIĞI GİZLEDİĞİM YERİ….

BİRDE….POE’NUN

ÖZLEMLERİ PARÇALAYAN ELLERİ.', 'TAM YOSUNLARINI.....DALGALARA VERMEK ÜZEREYDİ Kİ YÜREĞİM, DENİZ ÜLKESİNDE SESİN YANKILANDI SEVDİĞİM. BİR BEN BİLİYORDUM AYRILIĞI GİZLEDİĞİM ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-poe-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seven Arkamdan Gelsin', 'beni-seven-arkamdan-gelsin-mine-ozdemirtas-cju71', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün / farklı bir sabaha uyanacağım / bu lanet şehirde.

Ezanlar okunurken kalkacağım.

Son kez, 

Bohçamı hazırlayıp tez elden. 

Ve bir daha; 

Dönmemecesine çıkacağım evden. 

Ardımdaki kapı kapanırken / sessizce,

Serin bir rüzgar esecek denizden.

Göreceksin; Bir gün, / ve mutlaka 

Terkedeceğim bu ''''şehr''i Istanbul''u''''

Beni seven ardımdan gelsin diyerek.

Sonra…

Sonra / herşey yolunda gidecek.', 'Bir gün / farklı bir sabaha uyanacağım / bu lanet şehirde. Ezanlar okunurken kalkacağım. Son kez,  Bohçamı hazırlayıp tez elden.  Ve bir dah...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-seven-arkamdan-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekinme Beni Ara', 'cekinme-beni-ara-mine-ozdemirtas-nnwxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tekrar gönlün gezerse bu kentin yollarında;

Ben her gece evdeyim. Çekinme beni ara.

Maziyi soruyorsan, ıslak kaldırımlara,

Bıraktığın yerdeyim. Çekinme beni ara.

Utanma gözyaşından, gizlenme karanlığa,

Sen benim kabulümsün, batsan da  günahlara.

Zamanların birinde, düşerse başın dara

Yerimi biliyorsun. Çekinme beni ara.', 'Tekrar gönlün gezerse bu kentin yollarında; Ben her gece evdeyim. Çekinme beni ara. Maziyi soruyorsan, ıslak kaldırımlara, Bıraktığın yerdey...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cekinme-beni-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar Bir Adam Vardı', 'bir-zamanlar-bir-adam-vardi-mine-ozdemirtas-xpjvp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar bir adam vardı 

Bana uzun çok uzun mektuplar yazardı. 

''Kollarımda olsan bile...yanımdaki yastıkta başın, 

Ve belki de hayat arkadaşım...ama hergün bir mektubun olacak 

Sağ kaldıkça başım'''' 

Diye altını çizdiği yeminlere inat 

O şimdi kendi düşleriyle başbaşa ve çok rahat. 

Unutmuş mühürsüz yeminleri. 

Postacı terketmiş GİBİ mahalleyi 

Kıçını köpek ısırmış olmalı gelmiyor geri. 

Yoksa Artık Kara sevdam sevmiyor mu beni 

3,5,8 unutulalı beri 

Değişti bütün gündemi. 

Yine de sağ olsun.....yazsada bir yazmasa da 

Ben hala şairim ona. 

Sevdaya tutkun sazına kök söktüren elleri var ya 

Hızlı akan kanla yaşamayı öğretti damarlarıma, 

Yaşam boyu kadın olmaya...onun sevdasıyla başbaşa 

Onun kalmaya.mahkumum ya. 

Birgün mektuplar gibi... adımı ve beni unutur belki.. 

Ağlarım....ama sitem etmem Asla. 

Bugünden yarınlara.... 

narçiçeği dudağına, sımsıkı saran kollarına 

Gül nefesine, sıcağına 

Alıştığım kucağına... 

Bir daha..bir daha...bir daha 

MERHABA.', 'Bir zamanlar bir adam vardı  Bana uzun çok uzun mektuplar yazardı.  ''Kollarımda olsan bile...yanımdaki yastıkta başın,  Ve belki de hayat ar...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-zamanlar-bir-adam-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Vardı', 'biri-vardi-ali-tekinture-vjors', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç rüyana girmedi mi

Seni seven biri vardı

Hiç kalbine doğmadı mı

Sana aşık biri vardı

Biri vardı, biri vardı

Seni seven, sana tutkun

Biri vardı, biri vardı

Her şeyiyle sana vurgun

Sevdiğine hep gizledi

Hiç karşılık göremedi

Seviyorum diyemedi

Sana aşık biri vardı', 'Hiç rüyana girmedi mi Seni seven biri vardı Hiç kalbine doğmadı mı Sana aşık biri vardı Biri vardı, biri vardı Seni seven, sana tutkun Biri ...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biri-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamazsın', 'dayanamazsin-askin-tuna-6zhu9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz senle bir sevda yaşadık

İstesen de unutamazsın

Beni böyle üzgün görmeye 

Biliyorum dayanamazsın

Dönmemeye yemin etsen de

Görmemeye karar versen de

Bende aşkın bitti desen de

Biliyorum dayanamazsın

Gözlerime giç bakmamaya

Ömür boyu bensiz kalmaya

Hasretimle sen yaşamaya

Biliyorum dayanamazsın', 'Biz senle bir sevda yaşadık İstesen de unutamazsın Beni böyle üzgün görmeye  Biliyorum dayanamazsın Dönmemeye yemin etsen de Görmemeye karar...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dayanamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Olmaya Geldim', 'senin-olmaya-geldim-halit-celikoglu-ghieo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün akşam yine benim

Yollarıma bakmışsın

Gelmeyince üzülüp

Perdeyi kapatmışsın

Kalbinde ki derdine

Derman olmaya geldim

Sakın artık üzülme

Sende kalmaya geldim

Yıllar var ki hasretim

O güzel yüzüne

Karalıyım bu gece

Senin olmaya geldim

Benim için ağlayıp

Gözyaşları dökmüşsün

Yollarıma bakıp da

Hep boynunu bükmüşsün', 'Dün akşam yine benim Yollarıma bakmışsın Gelmeyince üzülüp Perdeyi kapatmışsın Kalbinde ki derdine Derman olmaya geldim Sakın artık üzülme S...', ARRAY['Türk Edebiyatı','Şiir','Halit Çelikoğlu']::text[], 8.5, '{"poet":"Halit Çelikoğlu","poet_slug":"halit-celikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-olmaya-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-hamza-dekeli-8zs1z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklından çıkmasın çok sevildiğin

Unutma sevgilim, beni unutma

Ettiğin yeminleri, verdiğin sözü

Unutma sevgilim, beni unutma

Araya bitmeyen hasret girse de

Ayrılık acısı candan etse de

Bir değil, yüz değil, bin yıl geçse de

Unutma sevgilim, beni unutma

Gönlümü gönlüne bağladığımı

Aşkınla kalbimi dağladığını

Canımı yoluna harcadığımı

Unutma sevgilim, beni unutma', 'Aklından çıkmasın çok sevildiğin Unutma sevgilim, beni unutma Ettiğin yeminleri, verdiğin sözü Unutma sevgilim, beni unutma Araya bitmeyen h...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutma-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceza', 'ceza-gonul-sen-7x5nf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir günde doğdum anamdan

Gökler ağlıyormuş ben doğdum diye

Doğarken günahkar olur mu insan

Ömrüme verilen bu ceza niye

Ne yaptım Allah''ım dertli doğacak

Sevip deömrünce acı duyacak

Hangi gönül bana derman olacak

Ömrüme verilen bu ceza niye

Dost diye sarıldım, bağrım kanadı

Mutluluk aradım, gönlüm ağladı

Vurdu, süründürdü felek tokadı

Ömrüme verilen bu ceza niye', 'Yağmurlu bir günde doğdum anamdan Gökler ağlıyormuş ben doğdum diye Doğarken günahkar olur mu insan Ömrüme verilen bu ceza niye Ne yaptım Al...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ceza-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Unutulacak Kadın mısın', 'sen-unutulacak-kadin-misin-selma-cuhaci-uq00s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usandım eskimiş yalnızlığımdan

Söyle, nerdesin can yoldaşım

Çok şeyler silinmiş hatıralarımdan

Bir tek seni hiç unutmadım

Geceler arkadaş sensizliğime

Odam bomboş, şarkılar yarım

Bir yemin, bir dua oldun dilime

Ne ümidim biter, ne yasım

Sensiz yılları, sensiz aşkları

İnanmam asla yaşamadım

Solgun düşlerde, bir kaç kadehte

Sen unutulacak kadın mısın', 'Usandım eskimiş yalnızlığımdan Söyle, nerdesin can yoldaşım Çok şeyler silinmiş hatıralarımdan Bir tek seni hiç unutmadım Geceler arkadaş se...', ARRAY['Türk Edebiyatı','Şiir','Selma Çuhacı']::text[], 8.5, '{"poet":"Selma Çuhacı","poet_slug":"selma-cuhaci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-unutulacak-kadin-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Elveda', 'bu-son-elveda-salih-ozalasan-3u6p6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı bitti deyişim

Kaçıncı geri dönüşüm sana

Farkındamısın bir tanem gönül dostum

Her dönüşümde biraz daha bağlandım sana

Artık olsun bu son elveda

Bir daha veda edemem sana

Anladımki ben seninle varolmuşum

Sensiz bir Dünya yok bana

Sen varsan bende varım

Anladım ki boşuna sana veda

Yetsin artık vermeyeceğim kendime ceza

Gözlerinin içinde bir başka güzel Dünya

Git derken yüreğim kal diyorsa sana

İstemem derken yüreğim sarılsa diyorsa boynuma

Her gidişimde durmadan bakıyorsam ardıma

Diyemem artık diyemem sana elveda

Sen gitsende ben düşeceğim ardına

Baktığın her yerde çıkacağım karşına

Gidip de dönmemek var ya çıkamassam karşına

Bu son elveda; gitme muhtacım sana

Y.Tarihi 17-09-2002 Saat 13.25', 'Bu kaçıncı bitti deyişim Kaçıncı geri dönüşüm sana Farkındamısın bir tanem gönül dostum Her dönüşümde biraz daha bağlandım sana Artık olsun ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-son-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Billur Akıntı', 'i-ki-billur-akinti-esma-ozdemir-o51me', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu, bilmiyorum

Gözlerindeki mananın

Derinliklerinde buluverdim kendimi

Bir an.

İki billur akıntı

Sürükledi beni

Coşkun dalgalar arasına.

Çırpınıp dururken hayalle gerçek arasında, 

Adeta, sonsuzluktan gelen bir esinti

Fırtınaya dönüştü.

Ve, aldı götürdü beni

Mercan kayalıkların olduğu yere.

Orada anladım

Derinliklerdeki mananın 

Erişilmezliğini.

Orada yaşadım

Doyasıya

Hazların en güzelini.

Ve, gördüm ki sonunda; 

Bu güzellikler diyarında

Manaların sihirli gücü, 

Yoketti bütün maddeleri

Sahte güzellikleri.

Kaybettim kendimi

Derin manaların, 

Sonsuzluğun eşiğinde

Yavaş yavaş.

İki akıntının kolları arasında

Mutluluğa eriştim', 'Nasıl oldu, bilmiyorum Gözlerindeki mananın Derinliklerinde buluverdim kendimi Bir an. İki billur akıntı Sürükledi beni Coşkun dalgalar aras...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iki-billur-akinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nü Masal', 'bir-nu-masal-mine-ozdemirtas-nae1p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşle gerçek hep iç içe…nasıl sevda bilmiyorum

Barut sende…ateş bende…üflemekle sönmüyorum.

Ayrılığın yükü ağır…yüreğimde zincirlerin...

Bir  NÜ masal gece boyu…Bana senden daha yakın.

Gün doğarken penceremde…Hasretini sevmiyorum...

Barut sende…Ateş bende…Üflesen de sönmüyorum', 'Düşle gerçek hep iç içe…nasıl sevda bilmiyorum Barut sende…ateş bende…üflemekle sönmüyorum. Ayrılığın yükü ağır…yüreğimde zincirlerin... Bir...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-nu-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanca Yaşamak', 'i-nsanca-yasamak-mine-ozdemirtas-rk986', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buzula çarpmış dev bir gemi misali,

Umutsuzluk, çaresizliğe kırıyorsa dümeni,

Kabus dolu bir uykudan uyanıp haykırarak…

Ustasını dövebiliyorsa ‘yeni yetme’ bir çırak.

Her sabah alfabenin ‘A’sından yola çıkarak,

Boşuna dolaşıyoruz ''insanca yaşamak''

Düşünde yalınayak.', 'Buzula çarpmış dev bir gemi misali, Umutsuzluk, çaresizliğe kırıyorsa dümeni, Kabus dolu bir uykudan uyanıp haykırarak… Ustasını dövebiliyor...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/insanca-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembemsi', 'pembemsi-i-smail-erkan-tolay-2hptm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün olur

gül öter

Bülbül solar

güneş doğmaktan cayar

adana kış viyanada bahar

Kuş uçmayı

balık yüzmeyi

av kaçmayı

güzel cilveyi

dünya dönmeyi 

unutur

Minare kuyu

kuyu minare

serefeside suyu 

olur

Doktorlar cellat

cellatlar ebe

kadınlar baba

erkekler de 

doğurur

valsi güneşle ayın

çalınırken kasap havası

tenekeden mamül sarayın

tahtadanda asası

hamal sultanı

sultanı hamal

miço kaptanı

eri mareşal

olur

Gün olur

gök yeşerir

masmavi çayırlar

ak saçlı çocuklar

haşarı dedelere 

nasihat eyler

kumaebaz zardan

sarhoş meyden

yiğit yardan

neyzen neyden 

geçer

deveden yumurta

yumurtadan deve

omletide fevkalade 

olur

Gün olur

gönlüm

al yanaklı

alev dudaklı

zümrüt gözlü

altın saçlı

kahve tenli

çeneside gemli

hem, iyi huylu

bir güzeller güzeli

bulur

olmayacak şey 

değil''a 

(1983)', 'Gün olur gül öter Bülbül solar güneş doğmaktan cayar adana kış viyanada bahar Kuş uçmayı balık yüzmeyi av kaçmayı güzel cilveyi dünya dönmey...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/pembemsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Başlıyor', 'kis-basliyor-muhammer-kahriman-gnpty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kış başlıyor sevgilim yeniden 

iyi bak kendine 

gözlerindeki usul sempati 

teslim etme hiçkimseye hiçbirşeye 

up uzun bir kış başlıyor gibi 

sevgilim

ayrılığımızın kışı...', 'Kış başlıyor sevgilim yeniden  iyi bak kendine  gözlerindeki usul sempati  teslim etme hiçkimseye hiçbirşeye  up uzun bir kış başlıyor gibi ...', ARRAY['Türk Edebiyatı','Şiir','Muhammer Kahriman']::text[], 8.5, '{"poet":"Muhammer Kahriman","poet_slug":"muhammer-kahriman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kis-basliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Zamanlar', 'zamansiz-zamanlar-muhammer-kahriman-3f22k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok zamansız zamanlardan geçtim zamanı mayalanmadan saklanmış zamanlar

beni tanırsın sen? 

Vakitlerin yanar döner hiçliğini: 

Dağları ateşe veren arzuların kalleşliğini

bilmişliğimde aynı zamanlarda.

Çocukluğumdanda uzak şimdi sevdaya hasretliğim

Ben bana gelene değil de

Nedense hep benden geçene yeltendim', 'Çok zamansız zamanlardan geçtim zamanı mayalanmadan saklanmış zamanlar beni tanırsın sen?  Vakitlerin yanar döner hiçliğini:  Dağları ateşe ...', ARRAY['Türk Edebiyatı','Şiir','Muhammer Kahriman']::text[], 8.5, '{"poet":"Muhammer Kahriman","poet_slug":"muhammer-kahriman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zamansiz-zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Koyma Hiç Bir Şeyin...', 'adini-koyma-hic-bir-seyin-ugur-deniz-ulkegul-ffesv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En zor anıdır bu saat insanın...

   Ne Tebessümün,

   Ne konuşulacak kelimenin 

   Bir hükmü kalır..

 

   Yaşanan, 

   Sanki hislerin donakaldığı bir tipi fırtınasıdır 

  

   Bırak aynı kalsın her şey..

   Bu sokak, bu oda, bu dağılmış yatak, 

   Bütün sevişmeler yorgun, korkak, 

   Kutsayarak saygınlığını umursamazlığın, 

   Aynı kalsın, özel bir anlam katmana gerek yok 

   Hiç bir şeyine bu vedanın...

   Ayrılıklar sevilemez...

   Yokluk, 

   Var kılamaz 

   Sevdiklerinin sıcaklığını teninde...

   Beklemek,

   Acıyı doyumsamaktır çoğu zaman..

   Beklemek övünülesi bir kavram değildir 

   Ve hiç olmamıştır 

   İnsanoğlunun değer yargıları içinde..

    Özlemek

    Yokluğuna paye vermektir bir insanın...

    Hele bu ayrılık noktasında, 

    Gereksiz ve önemsiz sebepler 

    Koca bir dağ gibi karşısına dikilmişse adamın...

  

    Hele bir de..üzgünüm deyip, 

    Aslında bütün hüzünlerin ve bütün acıların 

    Tek sebebi oluyorsa gidecek olan...

  

    Bir de......

    Ağlıyorsa hiç ama hiç utanmadan...

  

    O vakit özlemek, 

    En ağır hakareti olur kendine insanın...

  

    Ayrılık, 

    O vakit ömür boyu hapse mahkum olmak demektir 

    Gecenin karamsar ve bir o kadar yalnız saatlerine... 

    Bu yüzden...

    Adını koyma hiç bir şeyin...

    Gidiyorum deme mesela...

    Mesela üzgünüm deme...

    En olağan halinle 

    Sanki hiç bir şey yokmuşçasına

    Usulca kalk yerinden..

    Yavaşça yönel kapıya...

    Ben uyurken çık sokağa...

  

    Yine her zaman ki gibi, üstümü ört mesela, 

    Gitmeden....

    Mesela hiç asma yüzünü...

    Bükme boynunu bir suçlu gibi...

    Mesela ıslak dudaklarını yaklaştır bana...

    Susuzluğuma inat...

    Mesela saçlarımı okşa bir çocuk gibi...

    Nispet yaparcasına şu koca adamlığıma.... 

    Adını koyma hiç bir şeyin...

    Seni seviyorum deme mesela...

    Bunu zaten biliyorum...

    Yemeği koydun mu ocağa? 

    Bardakları kaldırdın mı masadan? 

    Gömleğimi ütüledin mi bu sabah? 

    Sen ondan haber ver...

    Aşk''a dair söylenesi bir şeyimiz yok 

    Onca yaşanandan sonra....

    Mesela saçlarını iki yana bırak yeniden...

    Tenini saran o siyah geceliğini geçir sırtına...

    Sonra yanıma uzan...

    Sevişen gölgelerimiz vursun duvara...

     Hayır.. 

     Adını koyma hiç bir şeyin...

     Seni özlemek istemiyorum ben....

     Var''dın lı zamanlara bölerek yokluğunu...

     Her gün...her saat..yeniden.....

     Gideceksen....

     Adını koymadan git hiç bir şeyin....

     Ya da sapla hançerini sırtıma yalnızlığın, 

     Öldür...Öldüreceksen.....

                                                           18...09....2002', 'En zor anıdır bu saat insanın...    Ne Tebessümün,    Ne konuşulacak kelimenin     Bir hükmü kalır..      Yaşanan,     Sanki hislerin donaka...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/adini-koyma-hic-bir-seyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-mehmet-onur-13q45', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllardır aranan ama hep

Kendisini saklayan bir kadın...

Oyuncuların oynadıklarından 

Bile haberdar olmadığı bir saklambaç oyunu

Birden bir kapı açılıyor

Ve kapının içinden gözleri kamaştıran

Ve odayı aydınlatan bir ışık fışkırıyor: 

İçime işleyen; huzur ve mutluluk veren...', 'Yıllardır aranan ama hep Kendisini saklayan bir kadın... Oyuncuların oynadıklarından  Bile haberdar olmadığı bir saklambaç oyunu Birden bir ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Onur']::text[], 8.5, '{"poet":"Mehmet Onur","poet_slug":"mehmet-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saklambac-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevdam', 'gizli-sevdam-gezginci-ugur-e9255', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gizli sevdamsin herkesten gizledigim ulasamadim askim sen benim herseyimsin, ruyalarimda öptügüm sarildigim sevgilim neden buna bu kadar uzaksin? 

Bosver zamanla gecer diyorlar Sana soruyorum gecermi Bu büyük askim zamanla bitermi, Bazen diyorumki sana sarilsam Söylesem askimi sende kosar sarilirmisin yada bana kizar darilirmisin? 

Korkiyorum seni kazanmadan kaybetmekten inan biktim beklemekten sabretmekten 

Gizli sevdam ben (SENI + SEVIYORUM)', 'Sen gizli sevdamsin herkesten gizledigim ulasamadim askim sen benim herseyimsin, ruyalarimda öptügüm sarildigim sevgilim neden buna bu kadar...', ARRAY['Türk Edebiyatı','Şiir','Gezginci Uğur']::text[], 8.5, '{"poet":"Gezginci Uğur","poet_slug":"gezginci-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gizli-sevdam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Düşün Öyle Sev', 'i-yi-dusun-oyle-sev-tahir-paker-szz1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sevene inanılmaz

Candan sevip bağlanılmaz

Çile verir dayanılmaz

İyi düşün öyle sev

Önceleri bir hoş eder

Sevgisiyle sarhoş eder

Acımadan çekip gider

İyi düşün öyle sev

Hiç bir şey, görmez gözün

Mutlulukla güler yüzün

Sonra birden çöker hüzün

İyi düşün öyle sev

Gün geçtikçe beter eder

Gözyaşların bir sel eder

Leyla eder, Mecnun eder

İyi düşün öyle sev', 'Her sevene inanılmaz Candan sevip bağlanılmaz Çile verir dayanılmaz İyi düşün öyle sev Önceleri bir hoş eder Sevgisiyle sarhoş eder Acımadan...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iyi-dusun-oyle-sev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kalbime Gömdüm', 'seni-kalbime-gomdum-sakir-askan-jz8t6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakıp bütün aşkımı

Külü maziye gömdüm

Yaşanılan sevdayı

Seni kalbime gömdüm

Öyle günler geçirdim

Ne yaşadım, ne öldüm

Kadeh kadeh sevgilim

Seni kalbime gömdüm

Ömründe hiç gülmeyen

Dertli kullara döndüm

Devgi nedir bilmeyen

Seni kalbime gömdüm

Gittiğin günden beri

Dertsiz gününü gördüm

Artık arama beni

Seni kalbime gömdüm

Bu şarkımda sen yoksun

Artık kendime döndüm

Yüreğim kabrin olsun

Seni kalbime gömdüm', 'Yakıp bütün aşkımı Külü maziye gömdüm Yaşanılan sevdayı Seni kalbime gömdüm Öyle günler geçirdim Ne yaşadım, ne öldüm Kadeh kadeh sevgilim S...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-kalbime-gomdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemedim', 'vazgecemedim-hamza-dekeli-mgp7h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bıraktığın gibi duruyor hala

Kıyıp da resmine el süremedim

Bu kadın kim diye seni sordular

Sakladım ismini, söyleyemedim

Ayrılsak her şey biter sanmıştım

Nedense bir türlü bitiremedim

Sen çoktan unuttun, vazgeçtin ama

Nedense ben hala vazgeçemedim

Görenler şaşırır oldu halime

Kimseye aşkından söz edemedim

Söylemek istedim soran herkese

Utandım gerçeği söyleyemedim', 'Bıraktığın gibi duruyor hala Kıyıp da resmine el süremedim Bu kadın kim diye seni sordular Sakladım ismini, söyleyemedim Ayrılsak her şey bi...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecemedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gariban', 'gariban-tahir-paker-ae36o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açla tok arası bir dilim ekmek

Garibin ekmeği baldan sayılır

Anamızdan yoksul geldik dünyaya

Aldığımız nefes kardan sayılır

Bizim güvencemiz Yüce Allah''tır

Doğruluk her yerde ordu sayılır

Zalimlere silah çekmeye değmez

Garibanın sözü kurşun sayılır

Doğruluktur bizim tek sermayemiz

Garibanın sözü sanat sayılır

Garipten kötülük gelmez kimseye

Gariban herkese candan sarılır', 'Açla tok arası bir dilim ekmek Garibin ekmeği baldan sayılır Anamızdan yoksul geldik dünyaya Aldığımız nefes kardan sayılır Bizim güvencemiz...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gariban-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Rüzgarları', 'hasret-ruzgarlari-sakir-askan-n8rnf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret rüzgarları çok erken esti

Savrulduk sevgilim dertlerden yana

Zamansız dökülen yapraklar gibi

Ayrıldık sevgilim, doymadım sana

Nasıl başlamıştı, bak nasıl bitti

En güzel duygular silindi gitti

Nasıl da sevmiştim bilirsin seni

Ayrıldık sevgilim, doymadım sana

O çocuk gülüşün aklımdan gitmez

Yalvarsam Allah''a yazımı silmez

Boşalan kadehler teselli etmez

Ayrıldık sevgilim, doymadım sana', 'Hasret rüzgarları çok erken esti Savrulduk sevgilim dertlerden yana Zamansız dökülen yapraklar gibi Ayrıldık sevgilim, doymadım sana Nasıl b...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz Ayrılık', 'sebepsiz-ayrilik-hamza-dekeli-s95u1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılırsak her şey biter sevgilim

Gidersen bir daha dönme boşuna

Gidişin her şeyin bitişi olur

Bağışlar, affeder sanma boşuna

Vazgeçmek; ayrılmak, kopmak demektir

Vazgeçmek; sözünden dönmek demektir

Çaresiz kadere boyun eğmektir

Düşünmeden karar verme boşuna

Suçluysam suçumu söylemelisin

Susup da boynunu bükme boşuna

Sebepsiz ayrılık olmaz sevgilim

Hiç yoktan bu aşkı yıkma boşuna', 'Ayrılırsak her şey biter sevgilim Gidersen bir daha dönme boşuna Gidişin her şeyin bitişi olur Bağışlar, affeder sanma boşuna Vazgeçmek; ayr...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sebepsiz-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-hamdi-seker-mlqn0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eylülde melul oldu da gönül geldi bu hale 

Hazan esti güller kurudu sine pare pare

Zahm-ı sinede elif yarası yaktı hare

Lokman hekim ab-ı hayvan getirse ne çare', 'Eylülde melul oldu da gönül geldi bu hale  Hazan esti güller kurudu sine pare pare Zahm-ı sinede elif yarası yaktı hare Lokman hekim ab-ı ha...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Şeker']::text[], 8.5, '{"poet":"Hamdi Şeker","poet_slug":"hamdi-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eylul-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Resimleri', 'kus-resimleri-i-smail-karakurt-mcygf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gök bitti

Hırkama yapıştırılmış kuş resimleri

Çocukluğumu bir kitap gibi 

Kapatmışlar anne

Akmıyor artık o nehir

Ağır 

Ve nazenin.

Çıkınımda ne kır çiçekleri var

Ne de börtü böcek sesi

Güneşle arama

Bu kent girdiğinden beri

Gülümsemek

Yaprakları hışırdatmıyor

Gelinciklere

Ve meleklere göz kırpmıyor

Güneşli çimenlerden uzak

Çok uzak

Asansör içinde yaşamakla

Rüyaların bile

Künhü kalmadı

Kaf dağında giden samanyolu yandı

 /bir gün

bu kentten kaçıp

çiçeklerden elbise giyeceğim

çocukluğumun

şarkılarını söyleyeceğim.../

gök bitti

hırkama yapıştırılmış kuş resimleri....', 'Gök bitti Hırkama yapıştırılmış kuş resimleri Çocukluğumu bir kitap gibi  Kapatmışlar anne Akmıyor artık o nehir Ağır  Ve nazenin. Çıkınımda...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakurt']::text[], 8.5, '{"poet":"İsmail Karakurt","poet_slug":"i-smail-karakurt","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kus-resimleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O Yokuşlarda Karşılaştık Seninle', 'hep-o-yokuslarda-karsilastik-seninle-tulun-ceylan-eegcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep o yokuşlarda karşılaştık seninle

Sen yukarı çıkarken ben aşağı iniyordum

Bu tam üç kere böyle oldu

Bir seferinde de ben yukarı çıkarken

Sen aşağı iniyordun

Bir selama sıkıştırılmış sohbetler ettik ayak üstü

Sen kederler içindeyken ben neşeliydim

Hep o yokuşta karşılaştık seninle 

Ah bir karşılaşabilsek aynı yöne giderken

Belki de vazgeçip yokuşlarda karşılaşmaktan

Aynı eve yürürdük yokuş yukarı', 'Hep o yokuşlarda karşılaştık seninle Sen yukarı çıkarken ben aşağı iniyordum Bu tam üç kere böyle oldu Bir seferinde de ben yukarı çıkarken ...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hep-o-yokuslarda-karsilastik-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Bilinmeyenli Bir Denklem', 'i-ki-bilinmeyenli-bir-denklem-tulun-ceylan-rhesw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki bilinmeyenli bir denklemiz biz

Bir gün Aksaray üst geçidinde 

Kalakalacağız

Birbirimize bakışlarımız

Yabancılara bakışlarımıza kesecek

Yüreklerimiz buz kesecek

Soracağız oradan geçenlere

“ Ben kimim? ” 

“ Beni tanıyan biri var mı? ”

“ Hayır “diyecekler

“ Peki beni tanıyan birin tanıyan biri var mı? ”

“ Hayır “ diyecekler

Ve Aksaray üst geçidi kanatlanıp

Bizi hiçbir geçidin geçit olmadığı

Dünyalara götürecek

O dünyalarda yollarımız ayrılacak

Kader bu; insan yaşamaya yazgılıdır

Biz de yaşayacağız

Ama 

İki bilinmeyenli denklem olarak', 'İki bilinmeyenli bir denklemiz biz Bir gün Aksaray üst geçidinde  Kalakalacağız Birbirimize bakışlarımız Yabancılara bakışlarımıza kesecek Y...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-bilinmeyenli-bir-denklem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktayken yaşatamazsın ki?', 'uzaktayken-yasatamazsin-ki-tulun-ceylan-lnnzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Taaaaa 

En başından

Sağdece bir çiziktin

Yüzük parmağımda

Acısına kına yaktığım kasti bir sızı

Sabahı karşıladığımız kırmızı bir sevişme sonunda 

Bedenlerimizin tarçınımsı buhurunda 

İtiraflarını sıraladım bir çırpıda

Kasap dükkanlarının vitrinlerine sıralanmış 

Sakatatları sıralar gibi sıraladın

Bütün yediklerim, bildiklerim, hislerim

Ağzıma geldi

Elimden kaydın

Bacaklarıma yapıştın

Adım atamadım

Ki

Bir cezve kahveydin

Falına bakmak istemedim

Kör oldum

Kahve acısı bir yanıktın

Ne zaman gözlerine baksam

Yanıklarım sızladı

Sonrasında

Her birlikteliğimiz

Bir uçak bileti kadar yakın ayrılığımız oldu

Akşam yemeklerinde karşı karşıya 

Çatal bıçak sesleri

Lezzeti kaçmış yemek kokuları arasında

İran’a yazgılı otobüs bileti

Ortada salataydı bol sirkeli

Her çatal batırışta

Kesinleşen bir el sallama

Tüm okuduklarımız

Kanada’ya dizgilenmiş

Bir tren bileti

Saatin her tikinde ve her takında 

Tren daha da yaklaşıyor istasyonumuza

Ve sen

Bir kazaydın

Ufka doğru döşenmiş rayların 

Ve tekerleklerin arasında kaldı bacaklarım

Bir daha hiç adım atamadım

Sakatlandım

Her susuşun

Her gidişin

İsmimi her söyleyişin

Bir kazaya sebep olurdu

Ben baştan aşağı yaralanırdım

Beni komaya hapsettin

Beni karantinaya soktun

Beni Veba, HİV virüsü gibi soğukta dondurdun

Sen beni yakınımdayken öldürdün 

Uzaktayken yaşatamazsın ki?', 'Taaaaa  En başından Sağdece bir çiziktin Yüzük parmağımda Acısına kına yaktığım kasti bir sızı Sabahı karşıladığımız kırmızı bir sevişme son...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/uzaktayken-yasatamazsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetme Korkusu', 'kaybetme-korkusu-tulun-ceylan-r2754', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni kaybetme ihtimaline karşı

Bildiğim tüm önlemleri alıyorum

Motoru su kaynatmış

Bir Volvo kamyon gibi

Yolda kalıyorum', 'Seni kaybetme ihtimaline karşı Bildiğim tüm önlemleri alıyorum Motoru su kaynatmış Bir Volvo kamyon gibi Yolda kalıyorum...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kaybetme-korkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marsyas', 'marsyas-tulun-ceylan-az9zl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökbel’in volkanik görüntüsü

Delinir her saat her dakika

Çine Çayı’nın ezgileriyle

 Ezgiler aşk toplayan arılara eş

Dolaşır zakkumlardan kavaklara

Cennet firarı sabah yeliyle

Yalayıp geçer Marsyas’ın

Bir çınara gerilmiş derisiz bedenini

Bizi okşayan rüzgar

Dayanılmaz acılar çektirir Marsyas’a 

Marsyas zavallı çoban

Athena’nın lanetlediği kavalı çalan

Anasının mayaladığı yoğurdu

Kestirip peynir yaptığı sütü

Veren koyunlarına inat

Çalar durur sabayeline karşı kavalını

Marsyas zavallı çoban

Kavala değil yüreğine üfler nefesini

Ve galip gelir bu yüzden 

Apollon’un lirine 

Dönmemek üzere gönderilir Hades’e

Gökbel’de bir çınara gerilir bedeni

Derisi yüzülerek çırılçıplak bırakılır Marsyas

Ama hala çağaldar bugün bile

Yüreğinin ezgisi 

Çine Çayı’nda', 'Gökbel’in volkanik görüntüsü Delinir her saat her dakika Çine Çayı’nın ezgileriyle  Ezgiler aşk toplayan arılara eş Dolaşır zakkumlardan kav...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/marsyas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersine düştüm', 'tersine-dustum-tulun-ceylan-b2cou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tersine düştüm bir kez

İçimde şelaleler gibi çağıldar bir damla gözyaşım

Köpüklenir doğumumdan beri sürüklediğim kederlerim

Tersine düştüm bir kez

Ağrı’nın tepesinden aşağılara kayıyorum 

Ayaklarımda barut kokulu sözlerin keskinliği

Çıplağım

Çırılçıplağım karşında

Üşüyorum

Ağrı’nın doruklarından kayıyorum

Düşeceği toprağına koşarken

Yarı yolda kalan bir yağmur damlasıyım

Donuyurom

Tersine düştüm bir kez

Acele demlenmiş çay tadı damağımda

Acele içilmiş çay yanığı dil ucumda

Konuşamıyorum

Tersine düştüm bir kez

Şeker kavanozlarına dadanmış hırsız bir çocuğum

Ağzımda akidelerin tadı

Yanaklarımda kızılcık kırmızısı 

Sözlerinin tokadı

Titriyorum, itirafçıyım

Tersine düştüm bir kez

Bir orduya karşı koşan

Silahsız bir askerim

Başıma geleceklerin bilincindeyim

Ama yinede siperimden çıkıp

Yaylım ateşine karşı yürümekteyim

Silahsızım

Çırılçıplağım

Konuşamıyorum

Korkuyorum

Donuyorum

Tersine düştüm bir kez', 'Tersine düştüm bir kez İçimde şelaleler gibi çağıldar bir damla gözyaşım Köpüklenir doğumumdan beri sürüklediğim kederlerim Tersine düştüm b...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tersine-dustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktaki evimiz', 'uzaktaki-evimiz-tulun-ceylan-efepp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evimizin yolları hep uzak mı olacak bize? 

Evimiz ki anlamını bizle bulur

Sen, ben, kızımız ve kedimiz Pati

Güneşi salonumuzun

Balkonumuzun sarı çiçekli

Martı sesli

Bataklı manzarası

Gecenin sessizliği

Çatıdaki güvercin ailesi

Evimizin yolları hep git git bitmeyecek mi? 

Evimizi 

Birbirimizi özlediğimiz

Kadar

Özleyecek miyiz hep? 

Sen, ben, kızımız ve kedimiz Pati

Sonra kıvrık kirpiklerin

Akdeniz güneşi gözlerin

Ay gibi parlak alnın

Hep uzak mı olacak bana? 

Hep içimdesin oysa? 

Evimizin yolları çim kokarken

Gül, sümbül ve çam kokarken

Mutfakta en sevdiğin yemeğin buharı tüterken

Sensiz içilen sıcak şarap

Çay yalnızlıktan sızlarken

Boğazımı tırmalarken sigaram

Ev sensizliğe ağlarken

Evimiz evimiz mi olacak? 

Ev ne zaman hep bizim olacak? 

 Sen, ben, kızımız ve kedimiz Pati...', 'Evimizin yolları hep uzak mı olacak bize?  Evimiz ki anlamını bizle bulur Sen, ben, kızımız ve kedimiz Pati Güneşi salonumuzun Balkonumuzun ...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/uzaktaki-evimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virgül Sevdalısı', 'virgul-sevdalisi-tulun-ceylan-ony3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep ünlemlerle bakıyorsun bana

Sorularıma verdiğin her cevap soru işareti

Ne zaman seni seviyorum desem

Üç nokta süzülüyor

Karanfil desenli naylon masa örtüsünün üstünde

Geçmişi dinlerken kesme işareti

Eski aşklarımı ağzımdan her kaçırışımda

Tırnağa alıyorsun beni

Eksik olan belki de? 

Parantezleri hiç kullanmayışımızda

Noktalı virgülleri unutuşumuzda

Bir tehdit gibi peşimden kovalıyor noktaların

Oysa ben virgül sevdalısıyım', 'Hep ünlemlerle bakıyorsun bana Sorularıma verdiğin her cevap soru işareti Ne zaman seni seviyorum desem Üç nokta süzülüyor Karanfil desenli ...', ARRAY['Türk Edebiyatı','Şiir','Tülün Ceylan']::text[], 8.5, '{"poet":"Tülün Ceylan","poet_slug":"tulun-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/virgul-sevdalisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Nasihat', 'kendime-nasihat-mehmet-fatin-baki-wussk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostuna düşmanına habis  gözlerle bakma

Esenlikle yaşarsın rahat eder vicdanın 

İhtiyacı halinde dostu yalnız bırakma

Esenlikle yaşarsın rahat eder vicdanın 

Fesat sözler söyleme seda çabuk yayılır

Alçak gönüllü olan mütevazi sayılır

Gıpta  etme kimseyi yüreğin temiz kalır

Esenlikle yaşarsın rahat eder vicdanın 

Yoksulun  gönlünü al, düşkünlere selâm ver

Arkadaş ol garibe, fakire dostluk göster

Tenkid etmek yerine tatlı söylersen eğer

Esenlikle yaşarsın rahat eder vicdanın 

Varlığa önem verme paylaş her yediğini

Sözlerinin eri ol infâz et dediğini

İlim irfân yolunda öğret öğrendiğini

Esenlikle yaşarsın rahat eder vicdanın 

Mefaki bahtiyar ol etrafına neş’e sal

Asık  surat yerine daim güler yüzlü kal

Ömrün hitâm bulmadan  felekten bir gece çal

Esenlikle yaşarsın rahat eder vicdanın 

Habis = kötü

İnfâz = yapmak, yerine getirmak

Hitâm = son', 'Dostuna düşmanına habis  gözlerle bakma Esenlikle yaşarsın rahat eder vicdanın  İhtiyacı halinde dostu yalnız bırakma Esenlikle yaşarsın rah...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kendime-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Misin?', 'deli-misin-mehmet-fatin-baki-faza0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kız sen nesin? Sen nesin? İlk bahar yeli misin? 

Deli dolu akan bir ırmağın seli misin? 

Kız sen nesin? Sen nesin?  Yüzü gamzeli misin? 

Manalı gülüşünle her gün neş’eli misin? 

Kız sen nesin? Sen nesin?  Gözü sürmeli misin? 

Güzel nağme çıkaran kemençe teli misin? 

Kız sen nesin? Sen nesin?  Her an cilveli misin? 

Mefakiyi mahvettin. Kızım sen deli misin?', 'Kız sen nesin? Sen nesin? İlk bahar yeli misin?  Deli dolu akan bir ırmağın seli misin?  Kız sen nesin? Sen nesin?  Yüzü gamzeli misin?  Man...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deli-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rapunzel', 'rapunzel-i-lhami-atmaca-n60zy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarını çöz geceye karşı 

Adını inat koy bahçende açan gülün 

Yağmuru kırdık rapunzel 

Biz bir bebeği öldürdük 

Unuttum çıbanlar başverdi tenimde 

Saçları yok muydu maksatlı kızların 

Süzülürdü gözlerin değince gözlerime 

Sana minnettar dilsizler 

Seni masallardan çıkardım 

Ve yaşadım bir günahı seninle 

Çıplak ayaklarını gizle gözlerden 

Yağmurun dokunduğu her yerini 

Sesini koru günah kelimelerden 

Yanında meleklernden bir ordu 

Saçlarını çöz geceye karşı 

Cadılar çıkmadan yerlerinden 

İnancın sancağını diktim her kapısız kuleye 

Adını yazdığım her sayfayı yoldum defterden 

Lakin rapunzel saçların korudu güzelliğini 

Dilin yağmurla sustu 

Gözlerin suçlu... tanınmaz 

Masum mahpusları korudu 

Kapımı zorluyor dilenci orduları 

Gazete küpürlerinde buna rastlanmıyor 

Para desteleri rapunzel, güzel kızların 

Kararan alınlarını süslüyor 

Öpmüyorum artık yüzünü çocukların 

Kirli elleri yakalarımda bundan ötürü 

Dinle rapunzel 

Güneşi suratsızlara bıraktık 

Dilin gücü kalmadı 

Yağmur sularıyla ıslattık 

Sana öldüm diye ağlamak geçiyor içimden 

Bekar odalarında yalnız bir ölü 

Gözlerim arsız seni görmemekten 

Odamda ifritler dolanıyor 

Kulaklarımda terkeden sevgililerin sözü 

Beni sokak ortalarında bırakıyor 

Kendimi unuttum uzaktan duyunca ağlayışını 

Şarkını sürdür rapunzel geceye karşı 

Saçlarını sarkıt sen bağımsız kollarına erkeklerin 

Güzel bir ölüm beğenerek kendime 

Güllere, leylaklara aldırmadan öpüyorum 

Yalnız duyunca rapunzel ağladığını 

Kendime lanet ederek, lanet ederek yiğitliğime 

İnceliğime yükleniyorum 

Yağan yağmurlar durur rapunzel 

Baharda kar yağar sen küsersen 

Karıncalar aç kalır sen gidersen gizlice 

Ve biter bir ömür 

Sana unutmanın ağırlığını anlatmıştım 

Ağı bir balığın nasıl kırdığını özgürlük için 

O engin denizde bir gün 

Anlatmıştım her insan gibi öldüğünü 

Dinle rapunzel 

Sararak dilini parmaklarına 

Ufkun ötesine sessizce geçtiğini 

Benden saklayamazsın 

Açsan da birgün kapını başkalarına 

Beni hiçbir zaman unutamazsın 

Sana öldüğümü anlatamam 

Cılızlaşan alevimin yavaşca söndüğünü 

Ve kalbimin hergün büyüdüğünü hasretinle 

Sana uzak kalmak aşka uzak kalmak demektir 

Duy artık, duy rapunzel çığlıklarımı 

Boğazlanan bir martınınkini andıran 

Bu bir aşk şarkısıdır ve adı sevilmemektir. 

Geçmedi sancısı savurduğun okların göğsümde 

Yağmur her düştüğü yeri yakıyor 

İnan rapunzel dilinde açan her çiçek 

Beni hiçliğin kucağına acımasız atıyor 

Artık yaşamaya kurulu bir kukla gibi 

Kulenin dibinde dönmeyeceğim 

Ve inansam da senin daima beni sevdiğine 

İsmini bir daha hiç seslenmeyeceğim 

Yine bir melek olarak sarkıt saçlarını 

Yahut kulende kal, insan ol biraz.', 'Saçlarını çöz geceye karşı  Adını inat koy bahçende açan gülün  Yağmuru kırdık rapunzel  Biz bir bebeği öldürdük  Unuttum çıbanlar başverdi ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/rapunzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Çocuklar Öyle Mahzun', 'o-cocuklar-oyle-mahzun-i-lhami-atmaca-eomm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I. 

Duy ey baharı bağrında taşıyan çiçek 

İnanır olmuştum artık solmayacağına 

O çocuklar öyle mahzun ağlamaya gittiler 

Azgın canavarlarla artık kimler pençeleşecek 

Ölmeye hazır umutlarım vardı mektuplar okudum 

Gördüm satırlarda nişanlı gençkızlar ağlardı 

Bir baba sıkardı kasketini kahırdan, gözyaşları 

Uçardı satırlarda ak saçlı bir ananın 

Ve bacılar avuçlarını gözlerine yamardı 

Benim ölmeye hazır umutlarım vardı 

Bana aşka ve sana dair mektuplar yazarlardı 

Şimdi saçmasapan sözler dolanıyor dilime 

Kurumlarım yaşlı bir adamın sakallarını aşıyor 

Delikanlı raconları, bitpazarları ve gençkızlar 

Aciz çırakları insanlığın, imdada koşuyorlar 

Çatlıyor damarlarım, utançtan eşgalim sararıyor 

Duy ey baharı bağrında taşıyan çiçek 

Beni kimler anlayacak artık, kimler sevecek. 

Korkuyorum tasalarım artıyor. 

O çocuklar öyle mahzun ağlamaya gittiler 

Beni kimler anlayacak artık, kimler sevecek 

II. 

O çocuklar öyle mahzun ağlamaya gittiler 

Senin solduğun bahçeleri görsem dayanamam 

Anlatıyorlar bir karanfilin herkese açtığını 

Çok ağladım sarsılarak saklamam 

O çocuklar öyle mahzun ağlamaya gittiler 

Gecelerin ürkünç karanlığına bulaştım 

O nurdan yüzlü aşıkları unutamam 

Duy ey baharı bağrında taşıyan çiçek 

Sensiz yaşamaya alıştım artık 

Bilmem idamlık kefenimi kimler biçecek.', 'I.  Duy ey baharı bağrında taşıyan çiçek  İnanır olmuştum artık solmayacağına  O çocuklar öyle mahzun ağlamaya gittiler  Azgın canavarlarla ...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/o-cocuklar-oyle-mahzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul', 'ah-i-stanbul-i-lhami-atmaca-4ne1v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok gece dayanır kapıma ağlamaklı istanbul 

Unutulmuş kokularıyla gülleri, leylakları 

Bir anadolu türküsü kadar çoğul 

Dindirdim içimde nice zehirli çavlanları 

Ne sırrına ne bakire ellerine dokundum 

Sabık bir şairin esrarıyla direndim yaslara 

Rahmetle anacağım aşklarla avundum 

Br yarasa gibi savruldum karanlıklara 

Çöker, ruhumun ölçülemez derinliğine 

Köpüre köpüre gelen denizlerin büyüsü 

Delinmiş gökyüzünün peşinde pervane 

Karanlıklara çarpan bir çığlığın türküsü 

Ah parçalar, parçalar içimi çalan saz 

Ah dökülür ellerim eteğinden tutunca 

Ah sızım sızlar içimde naz 

Ah istanbul çığlığın kapımda patlayınca 

Nice iniltilerle sokaklara doğuran 

Kadınların çocuklarına merhamet 

Ah ufkunda çığlıklı martılara karışan 

Güzel kızların etlerinde cinayet 

Peki har’ın yeter mi ki böyle gür 

Köpüre köpüre giden vapurların küpeştelerinde 

Nice aşklar kelimelere dökülür 

Kırılan bir gül dalı kalır ellerimizde 

İstanbul sustun, kıyılarına vuran denizi 

Nice ayrılıklara gömdün ulaşılmayan 

Şimdi kapımda bir yığın kum tanesi 

Beni mecnun gibi çöllere hazırlayan 

Ah parçalar, parçalar içimi çalan saz 

Ah dökülür kalırım ellerini saklayınca 

Ah sızım sızım buharlaşır niyaz 

Ah istanbul çığlığın kapımda patlayınca', 'Çok gece dayanır kapıma ağlamaklı istanbul  Unutulmuş kokularıyla gülleri, leylakları  Bir anadolu türküsü kadar çoğul  Dindirdim içimde nic...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ah-istanbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin Kiri', 'sehrin-kiri-i-lhami-atmaca-ckl8k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutuyorum kentin kirini denize bulaştıkça 

Hayat kendini kuruyor, aklımdan çıkmıyor 

Çocukluğum. Ardıma takılıyor yüzüm 

Çirkin, korkak, şımarmaktan utanan 

Ve tanrıya çokça sığınan 

Herşeyde bir merak bırakıyorum, yarım kalıyor 

Bıkkınlığım, hevesim, sevgim, çok şey 

Aşk beni yaratıyor içimden doğru 

Çıkıyorum, konuşuyorum, güzelleşiyorum 

Dostlarım oluyor. 

Sanki ben ben olmasaydım da olacaktı bunlar 

Bir baca tütecekti yine de, bir çiçek açacaktı 

Neden insanların ilgilenmediğine şaşarak 

Eskidikçe büyüyen bir dünyada yaşamak 

Biraz daha kirlenerek yaşamaktır. 

Lüzumsuz şeylere katlanmak 

Ruhuna ıramaktır. 

Unutuyorum, şehrin gürültüsünü sesine yaklaştıkça 

Bülbülün kuşluğunu unutuyorum, 

Seni bir melek gibi duyumsuyorum 

Ve aşkı kuşkulardan arıtıyorum 

Şehri unutuyorum', 'Unutuyorum kentin kirini denize bulaştıkça  Hayat kendini kuruyor, aklımdan çıkmıyor  Çocukluğum. Ardıma takılıyor yüzüm  Çirkin, korkak, şı...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sehrin-kiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Korkayım Benzemekle Bir Kahramana', 'neden-korkayim-benzemekle-bir-kahramana-i-lhami-atmaca-hp6kz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Orada, o mor tepelerin arkasında 

Yağmurla ıslanmış toprağa düştü 

İçimden sağılan sancılı aşk 

Uzağa alışmakla gurbete döndü 

Eskimiş bir insanın ruhunu taşıyorum 

Öğreneceğim ne kaldı ki hayatta 

Kirpilerin rüyalarında yaşıyorum 

Belki bir rüyada sahip bir tavşan bana 

Durdur beni hayat, kederlerden kopar 

Sırrın odama dolan ışığıyla aydınlandı kalbim 

Gençkız düşleriyle örselendi beynim 

Gittikçe küstahlaştı ruhum 

Ne korkutabilir ki beni daha 

Neden korkayım benzemekle diğer insanlara 

Şu gelen bahar kadar tazeyim 

Sözlerimin tanığı kadar gerçek 

Benim de bilgece sözlerim var 

Hayata dair şiirler çağlar kalbimden 

Öyleyse cesur olmakla ben kendime ihanetin 

Tadıyla yaşamaya direneceğim 

Neden korkayım benzemekle bir kahramana 

Neden benzemekle bir şaire sözümün düşsün değeri 

Aynada beliren kendi yüzüm 

Sesimin rengi hangi renge benzerki 

Korkayım ve saklayayım kılıncımı 

Ben olmaktan başka deneyebileceğim bir şey yok 

Kendim mezarımdan başka, hangi mezar kabullenir ki beni 

Bana bir adın verilişi 

Ne kadar uzaklaştırabilir beni o mor tepelerden 

Karşılaştığım her gerçekten aldığım bir parça ben 

Hergün ölmekte olan milyonlarca benden ne kadar farklı ki 

Bütün çizgilerini bozarak hayatın 

Çekildiğim darağacı, manzurun gölgesinde belirir 

Ruhumu sürükler elbette bir deniz.', 'Orada, o mor tepelerin arkasında  Yağmurla ıslanmış toprağa düştü  İçimden sağılan sancılı aşk  Uzağa alışmakla gurbete döndü  Eskimiş bir i...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/neden-korkayim-benzemekle-bir-kahramana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Onu Beklerken', 'gece-onu-beklerken-i-lhami-atmaca-rfg4d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben onu beklerken gece, 

Gömüldü içime 

Şiir buğusuyla puslandı kalbim 

Aydınlığı getirdi melekler pencereme 

Ben onu beklerken gece, 

Kuş sesleriyle süslenince 

Sokaklar bir nehir gibi aktı kalbime 

Olup bitenleri farketmediler 

Ben onu beklerken gece, 

Tinerci bir çocuk 

Sığındı koynuna kalbinin 

Melekler şefkatle ayışığı örttüler üstüne 

Ben onu beklerken gece, 

Bir sinsi yağmur, 

Zehir gibi karanlık 

Ve cinler kayarak geçtiler ötelere 

Ben onu beklerken gece, o uykunun 

Derinliğinde küçük bir çocuk 

Gülümsedi masal düşleriyle', 'Ben onu beklerken gece,  Gömüldü içime  Şiir buğusuyla puslandı kalbim  Aydınlığı getirdi melekler pencereme  Ben onu beklerken gece,  Kuş s...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-onu-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Perisiyle Geceleyin Konuşma', 'bir-gece-perisiyle-geceleyin-konusma-i-lhami-atmaca-scw4c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuşmayı bilirim 

Güz hüzünlerinin korkaklığını taşımaz kalbim 

Gerçekte bir soytarı kadar eğlenceliyim 

İnceliğinin farkına vardığımda ellerinin 

Uçarılığına gözlerinin 

Susmayı öğrettim, kalbim 

Dinler ve didişmez benimle 

Dünya yordamına konulabilir 

Yazgı düzenlenemez. 

Gözlerinin rengini görmeliyim 

Ki yosun kokularını hissedebileyim 

Derinliklerinde özenle gezinerek kalbinin 

Bütün gizlerini öğreneliyim 

Yüreğindeki ürkek güvercinleri 

Yeryüzüne özgürce salıvermeliyim 

Dökülmeli o zaman dilinden kelimeler 

Kelimelerini sevmeliyim. 

Düşsel denizlere doğru bir gemi 

Ancak düşlerde mi yelken açar 

Bu rüya biter diye üzülme 

Tekrar görübebilir aynı rüyalar. 

BİRDENBİRE OLUR MU HİÇBİRŞEY GERÇEKTEN/II 

Işığı görünce tanıyamaz mı yani insanlar 

Işık ve karanlık bir midir yani 

Pervane böcekleri ateşe ölümü bilmeden mi koşarlar 

Birdenbire gelir mi hiç aydınlık 

Birden bire olur mu hiçbirşey gerçekten 

Bir kalp nasıl titrer, kesilir bir nefes 

Birşeyler getirmemişse beklenen 

Nasıl söyler dil, nasıl betimler kalem 

Birden bire olur mu hiçbirşey gerçekten 

Düşsel denizlere doğru bir gemi 

Ancak düşlerde mi yelken açar 

Bu rüya biter diye üzülme 

Tekrar görübebilir aynı rüyalar. 

BİR HAYALE Mİ SÖYLÜYORUM BUNLARI/III 

Bir hayale söylüyorum bütün bunları 

Çünkü sığ kalbimi tanımak zordur 

Ve zordur onu sevmek bilirim 

Benim de ürkütülmüş kuşlar uçuyor kalbimde 

Benim de gölgem iz bırakır gezindiği yerde 

İzler kalır elbette benim de yüreğimde 

Öyle bakma gözlerime 

Benim de kanayan yerlerim vardır 

Belki hep kanayacaktır sonsuzluk mateminde 

Tül tül uçuşacaktır sersemliğim 

Serpilecektir üstüne bir gece 

sen uyurken düşsel ülkende 

benim de kanayan yerlerim vardır 

belki hep kanayacaktır sonsuzluk mateminde 

suskun diyorsun bana her fırsatta 

çığlık çığlığa anlatıyorum sana birşeyleri 

oysa çığlık çığlığa 

Düşsel denizlere doğru bir gemi 

Ancak düşlerde mi yelken açar 

Bu rüya biter diye üzülme 

Tekrar görübebilir aynı rüyalar. 

SEN O MUSUN YOKSA 

HANİ O HEP BEKLENEN/IV 

Sen o musun yoksa, o ansızın gelmesi beklenen 

Nasıl tanıyacağım seni 

Kimse bir şey söylemedi, şakağımda bir dövme, bir iz 

Bir belge yok, bir bilgi elimde 

İşte bu yüzden korkuyorum incitmelerden 

İşte bu yüzden sarılıyorum suskunluklara 

Çünkü insan sendeleyip düşebilir herşeyden sonra 

Ve 

Biter bir rüya 

Düşsel denizlere doğru bir gemi 

Ancak düşlerde mi yelken açar 

Bu rüya biter diye üzülme 

Tekrar görübebilir aynı rüyalar. 

BİLİYORUM MUTLAKA BİRŞEYLER 

SÖYLEMELİYİM SANA/V 

En dürüst şey zamandır evrende 

Ama zaman saat değildir, ay değildir sevgi için 

Sevgi doğurur zamanı 

Ve zaman yanılmaz insanı... 

Haydi neşelen... neşelen ve türkünü söyle ey peri 

Birazdan güneş baskın çıkacak geceye...', 'Konuşmayı bilirim  Güz hüzünlerinin korkaklığını taşımaz kalbim  Gerçekte bir soytarı kadar eğlenceliyim  İnceliğinin farkına vardığımda ell...', ARRAY['Türk Edebiyatı','Şiir','İlhami Atmaca']::text[], 8.5, '{"poet":"İlhami Atmaca","poet_slug":"i-lhami-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/bir-gece-perisiyle-geceleyin-konusma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem''e', 'annem-e-erol-sen-w4xzi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece soğuk gece ayaz sen bilmiyorsun

Ben yalnız sana bakıyorum camdan

Sen yine bilmiyorsun annem

Bize dönmeni bekliyorum umutla

Ben yıldız ararken gökyüzünde sana dilek dilemeye

Senin haberin yok güzel annem

Ağzında göğsünde kolunda bir sürü alet

İyileşmeni diliyorum annem

Yıldızlar olmasa da gökyüzünde

Bilirler onları sevdiğimi annem

Sana bakarken camdan yaşaman için umutla

Seni bağışlasın allahım bize 

Gece uzun ben yalnız ama seninleyim

Seni bekliyorum yağmurlu gecede 

Yağmur yağıyor ama ıslatmıyor annem

Çünki seni diliyorum tanrıdan

Yorgun bedenin hafif kıpırtılar da

Umut veriyor kıpırdaman

Ama beni görmüyorsun annem

Ne olur bize dön bizimle ol

Yine kız bana annem istediğin kadar

Kötülük yok içinde bilirim

Sen yüreklerimizde çiçeksin

Allahım çiçeğimizi söndürme...

18.09.2002

19.09.2002 de annem hakkın rahmetine kavuştu. Allah sevdiği

kulunu yanına alırmış. Acı tatlı hatıraları ben de 

rahat uyu annem......', 'Gece soğuk gece ayaz sen bilmiyorsun Ben yalnız sana bakıyorum camdan Sen yine bilmiyorsun annem Bize dönmeni bekliyorum umutla Ben yıldız a...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/annem-e-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynstayn', 'aynstayn-ahmet-i-plikci-vf4gd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'E esittir emcekare

diye soylemis

Aynstayn bundan

yuz yil once

E o zaman

Ne korkudur bu be

Yoktan var olunmaz 

Vardan yok olunmaz', 'E esittir emcekare diye soylemis Aynstayn bundan yuz yil once E o zaman Ne korkudur bu be Yoktan var olunmaz  Vardan yok olunmaz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İplikci']::text[], 8.5, '{"poet":"Ahmet İplikci","poet_slug":"ahmet-i-plikci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aynstayn-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İluh', 'i-luh-ali-galip-e0p97', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yangınına kör çığlığına sağır kaldığım bu kent

Hüzünlerimi umursamayacak kadar mahzundu

Çünkü kendine rağmen bir burca dayardı sırtını

Tarihe inat mesaiden sayılırdı kurşunlanan her ten

Bense müstemleke mekânlarda ilhamlar dilenirdim

Geceydi sokulduğum yanı ve şiirler sunardı bana

Düşlere dalardım takvimden kopardığım her yaprakla

Ve mahcuptum bu yüzden bîtaraf yanlarım sızlardı

Yok anlamı bu kentin kendine dair

Ölüme koşullanıyor hayat şaşmaz bir komutayla

Bayındır kılmıyor onu pamuk tütün ve petrol

Yeşilin bir kararnamelik hükmü kalıyor toprakta

Kuşkunun rengi eşitliyor gecenin gündüzden farkını

Çocuklar çoğaltıyor caddeleri sokaklar inadına barikat

Kendi dilinde susan kadınlara yenik düşüyor sivil hayat', 'Yangınına kör çığlığına sağır kaldığım bu kent Hüzünlerimi umursamayacak kadar mahzundu Çünkü kendine rağmen bir burca dayardı sırtını Tarih...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iluh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin Üzerine', 'filistin-uzerine-ahmet-faruk-y31xh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Babalar dönülmez sefere çıkmış

Çocuklar ağlaşır, yürek perişan

Her gece üstüne bombalar yağan

Tarumar edilen güller perişan

Figânlar yükselir, sarar dünyayı

Yetimler korkulu, anneler nâçar

Bir küçük yavrunun akarken kanı

Uykuyla kapanan gözler perişan

Gözü dönmüş yahudi vurdukça vurur

Kayıtsız seyreden vijdanlar kurur

Elbet bir gün hesap sorulur

Geri alınmayan Kudüs perişan...', 'Babalar dönülmez sefere çıkmış Çocuklar ağlaşır, yürek perişan Her gece üstüne bombalar yağan Tarumar edilen güller perişan Figânlar yükseli...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Faruk']::text[], 8.5, '{"poet":"Ahmet Faruk","poet_slug":"ahmet-faruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/filistin-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşten Gömlek', 'atesten-gomlek-cahit-i-pekoglu-tqmpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşmüşüm istemeden aşk derdine

arıyorum çareyi, soruyororum gülüm nerede..

Darmadağınım her parçam bir yerde

ateşten gömlektir sensiz yüreğim...

Umutları silinmiş

yolum çıkmaz yoldur artık..

Sensiz yaşanmıyor

İnleye, inleye ölüyorum artık..

Yaralı yüreğimi 

terk etmiş vurup''ta sevdiğim.

Uzaklarda kalmış artık gülüm dediğim. 

Umutla yaşadım gelir dediğim

hayallerde bile yoksun artık sevdiğim.. 

Gözlerin nedendir 

sanki bulutlu gibi.

Umutsuz olsa da 

hep görmek istediğim umutlu gibi.

Kendi yüreğinde

istemesede bensiz tutuklu gibi...

Bilemezsin neleri tükettiğini gülüm

kabullenemem aşkının bittiğini.

Seni öylesine yaşarken

düşünebilirmiyim gittiğini.

Kim bilir, belki de gülümü

Issız sonsuzlukta arıyor ruhum artık..', 'Düşmüşüm istemeden aşk derdine arıyorum çareyi, soruyororum gülüm nerede.. Darmadağınım her parçam bir yerde ateşten gömlektir sensiz yüreği...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/atesten-gomlek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğini Besle', 'yuregini-besle-cahit-i-pekoglu-ekg72', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duygularını beynine mahkum etme

biraz olsun, olsun yüreğinle besle.

Başkalarının hayatı

senden öne geçmesin.

Sen herşeyden önemli

gerçek bir değersin...

Yaşa sadece kendini yaşa

seviyor seviliyorsan boğulurcasına yaşa.

Her şeyden öte

doğru olan şey sensin.

Beynine izin verme

yüreğin ve ruhunla yaşa.

Duygularını beynine mahkum etme.

Sonsuzluk sensin

yüreğini besle, kendine eziyet etme.....', 'Duygularını beynine mahkum etme biraz olsun, olsun yüreğinle besle. Başkalarının hayatı senden öne geçmesin. Sen herşeyden önemli gerçek bir...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yuregini-besle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prenses''e!', 'prenses-e-ahmet-agdere-x1bj4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Peri masalı, gerçek değil geçen zaman. 

Rüya şu an yaşadığımız; minik bir an... 

Engin hayaller içinde sensin aranan. 

Niceleri kurudu, niceleri kurban. 

Serseri gönül yokluğunda bana kalan 

Erişilmez kalende istersen silahlan; 

Sev veya beni, gel hülyalarımda dolan…', 'Peri masalı, gerçek değil geçen zaman.  Rüya şu an yaşadığımız; minik bir an...  Engin hayaller içinde sensin aranan.  Niceleri kurudu, nice...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/prenses-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli Sularda Kürek Çekmek', 'kirli-sularda-kurek-cekmek-ates-agaci-ec7w5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kirli yağmurlar yağıyor

Kardan adamlar artık zenci

Havada kesif bir kükürt kokusu

Toprak çamur olmayı yeğliyor

Oysaki

Tertemiz kaynar yatağından ırmak

Öyleyse neden bu kadar kirli sular? 

Ağaçların gölgesini terk eden adalet

Silahların gölgesine dadanırken

Işıklar küsmüştür renklerle

Siyah beyaz bir dünya korkusuyla

Bir gece ansızın yatağından fırlamıştır çocuk

Yetişkin eller gezinir durur etrafta

“nerede bu kumanda(n) ! 

değiştirin artık şu kanalı”...

aslında

her durum yeni vazifelere gebe

yeni bir yasa tasarlayıp

bütün filmleri kötü sonla bitirmek gerek

dingin bir yürek

nasıl dayanır bu ironiye

hey yolcu! 

bu kayığa bindiğimizden beri

ne kadar da sisli deniz

suskunluğumuz kadar

büyük mü cesaretimiz?', 'Kirli yağmurlar yağıyor Kardan adamlar artık zenci Havada kesif bir kükürt kokusu Toprak çamur olmayı yeğliyor Oysaki Tertemiz kaynar yatağı...', ARRAY['Türk Edebiyatı','Şiir','Ateş Ağacı']::text[], 8.5, '{"poet":"Ateş Ağacı","poet_slug":"ates-agaci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kirli-sularda-kurek-cekmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Su', 'bir-avuc-su-ates-agaci-2489i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanayın artık

Dağladığım yaralar

Acı veren yanınızı özledim

Yalnızlık

İçimdeki okyanusun yelkeni

Hiç bilmediğim adaları

Yeniden keşfe çıktım

Hiçin içinde aradığım

Yokluk mudur bilmem

Kulağımda bir dervişin 

Üflediği nefesin çığlığı

Ve yine yolcuyum

Yelkenimi dolduran aşk rüzgarı

İşte teslimim sana

Bir avuç su

Okyanusa serpildiyse

Nereye gittiği mühim mi?', 'Kanayın artık Dağladığım yaralar Acı veren yanınızı özledim Yalnızlık İçimdeki okyanusun yelkeni Hiç bilmediğim adaları Yeniden keşfe çıktım...', ARRAY['Türk Edebiyatı','Şiir','Ateş Ağacı']::text[], 8.5, '{"poet":"Ateş Ağacı","poet_slug":"ates-agaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-avuc-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Aşık Tavuskuşu', 'kendine-asik-tavuskusu-ates-agaci-klhyv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık olduğum ses kayalara çarpar

Ve kulaklarımdan kalbime süzülür yankısı

Aynalar ki en vefalı dostlarım

Görmek istediğim yansır camlarından

İçimde yaşadığını sandığım okyanus

Aslında bir avuç su

Dilimdeki hikmetli sözler

Ariflerden arakladığım inciler

Ey boyalı fıçıya düşmüş

Ve kendini tavus kuşu sanan çakal! 

Bir gün göklerden ilahi bir yağmur yağar

Boyaların paçalarından süzülür

İşte o an

Aynalar terk eder seni

Arifler kendi mallarına haciz koyar

Harut ve Marut terk ederler babil kapılarını

Baş aşağı da asılsan

Gideceğin kaç kapı var? 

Gençlik pınarı

Yokluk denizine dökülürken

Ve bilinmezken hayatın diğer kalanı

Elindekinin muhasebesi

Hep alacak kalanı verirken

Terazinin sağ kefesine koyacağın

Ve adına aşk dediğin şey

Belki de denizlerden topladığın yakamozlardır.', 'Aşık olduğum ses kayalara çarpar Ve kulaklarımdan kalbime süzülür yankısı Aynalar ki en vefalı dostlarım Görmek istediğim yansır camlarından...', ARRAY['Türk Edebiyatı','Şiir','Ateş Ağacı']::text[], 8.5, '{"poet":"Ateş Ağacı","poet_slug":"ates-agaci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kendine-asik-tavuskusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elini Ver Cehenneme Gideyim', 'elini-ver-cehenneme-gideyim-mesut-biyik-gzqqs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaşardım kuytuluğunda hayatın

sevdiğimi sandığım eller dokunurdu ellerime

yüreğimi avucumda taşıdığım o günler

kimi biraz gülümsüyor görsem yüzüme

verirdim yüreğimi

verirdim yiğitliğimi

verirdim kendime bile vermediklerimi

her alan götürdü neyi bulduysa benden

her giden yalnızca pişmanlıkları bıraktı

yalnızca koyu bir yalnızlığı

anlaşılmazlığımmış dediklerine göre

anlayamadıklarıydı aslında

yüreğim derin geldi biliyorum

sığ sularda inci arayanlara

ve sen çıktın da bir gün karşıma

kapamışken tüm kapılarımı sıkı sıkıya

gelenleri eşik önünde karşıladığım bir zamanda

savuştururken hepsini bir selamla

sen çıkıverdin karşıma

yüreğimin ipi çözüldü birden

sana açıldı bütün kapılarım

seninle keşfettim okyanusumu

hep aşkı bilirdim de bulamazdım

sen gözlerini verdin bana 

ben aşkı gözlerinde buldum

gözlerinden geçtim de kalbine

orada buldum yüreğimin diğer yanını

hakettiğimdin sen

hakedilmiş sevdamın çoban yıldızı

kırmızıya çalan hayatımın kardelen çiçeği

artık sen varsın ya sevda kılavuzum

ellerimi tut ve götür beni deryalara

götür ki senin gözlerinde boğulayım

götür ki senin varlığında yok olayım

bilirim ki ellerindeyse ellerim

ben cehenneme bile giderim', 'yaşardım kuytuluğunda hayatın sevdiğimi sandığım eller dokunurdu ellerime yüreğimi avucumda taşıdığım o günler kimi biraz gülümsüyor görsem ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Bıyık']::text[], 8.5, '{"poet":"Mesut Bıyık","poet_slug":"mesut-biyik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/elini-ver-cehenneme-gideyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-murat-cetin-2pu2e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uzak diyarların sevdasını getiren rüzgar! 

ılık bir esinti doldur yüreğime 

ve fısılda kulağıma 

sevdiğimden bir haber 

.... 

hasretlerin kavurduğu 

ızdırabın savurduğu 

gözlerin yaşa durduğu 

bir zamanda 

buzdan kor düşür 

yüreğime 

.... 

ve buğulu bir nağme tak 

sensizliğe sağır kulağıma 

.... 

busesinin en yakın yerinden 

bir buse çal dudağıma. 

... 

ıssız volkanların sıcağını getiren rüzgar! 

onsuz hayatta lavını doldur bedenime 

ve fısılda alınyazıma 

yolculuk muştusunu. 

.. 

gül rengi akşamların kokusunu getiren rüzgar! 

bir ağırlık ver gözlerimin üstüne 

ve serin huzur sürmesi çek güne. 

... 

beni bana getiren rüzgar! 

beni bırakma 

birbaşıma. 

ya beni getir 

ya sende esme. 

16/09/2002', 'uzak diyarların sevdasını getiren rüzgar!  ılık bir esinti doldur yüreğime  ve fısılda kulağıma  sevdiğimden bir haber  ....  hasretlerin ka...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ruzgar-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık ve Git', 'cik-ve-git-murat-cetin-sfozw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çıkmak istiyorsan 

kapı orda, 

git bakma arkana 

kal diye yalvarır 

göz bulamayacaksın. 

... 

sevgimin kıymetini bilemedin 

kirletme daha fazla 

aptal gururunu silemedin 

sende kalamam asla 

dört yanlışın 

tüm sevgini götürdü 

boşa son bakışın 

kalbimdeki 

sevgi artıklarını 

süpürdü... 

... 

senli buladığım zamanlar 

hesap soracak benden 

gecenin mahmur gözleri 

hayallerinle kaplanan anlar 

soracaklar 

ne hakla ve neden 

... 

bilmeden 

desen inanırlar mı 

içime giren kötü ruh çıktı 

eskisi gibiyim artık 

desem tanırlar mı 

bıçak sırtı sevdan 

çekti gölgesini 

kalbimden 

ellerim kan 

yüreğim kan 

sen genede 

beni mutlu san. 

çıkmak istiyorsan 

kapı orda 

bakma ardına 

giderken 

vestiyere 

saf sevgimi 

bırakta çık. 

uğurlar olsun. 

çıkarken 

gözümü kırparsam eğer 

namerdim 

bu son nefesim olsun. 

.. 

.. 

çık dert, çık 

terket beni.

18/09/2002', 'çıkmak istiyorsan  kapı orda,  git bakma arkana  kal diye yalvarır  göz bulamayacaksın.  ...  sevgimin kıymetini bilemedin  kirletme daha fa...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cik-ve-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Kimin', 'el-kimin-sair-sehriyar-zckdk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehriyar''ım gözüm yaşı sel kimin, 

Garip sen mi vetanında el kimin, 

Sevdan üreğimde kara yel kimin, 

Heç elden özgeye gardaş olar mı? 

Haramzadalardan yoldaş olar mı? 

Gurt gurtnan dolaşır, itler it inen, 

Gurt şikarnan doyar, itler küt inen, 

Yanaşmanın goynu dolar pit inen

Heç elden özgeye gardaş olar mı? 

Fars, Çin, Urustan yoldaş olar mı? 

Oğuz Atam bizi görse neyliyer, 

Dövüner dizini helak eyliyer, 

Yeğin geyze gelir, gönü göynüyer, 

Heç elden özgeye gardaş olar mı? 

Yılandan, çiyandan yoldaş olar mı? 

Bed-güman değilem Allah kerimdir, 

Turan hayalimdir, etim, derimdir, 

Böyyük Asya nece olsa benimdir, 

Gurt yuvalarına tilki dolar mı? 

Ayıdan, Moskof''tan yoldaş olar mı? 

Şehriyar''ım, incinmeyin sözüme, 

Dost acı danışar dostun özüne

Gah ağlaram, gah vururam dizime

Heç elden özgeye gardaş olar mı? 

Hayından, uğrudan yoldaş olar mı?', 'Şehriyar''ım gözüm yaşı sel kimin,  Garip sen mi vetanında el kimin,  Sevdan üreğimde kara yel kimin,  Heç elden özgeye gardaş olar mı?  Hara...', ARRAY['Türk Edebiyatı','Şiir','Şair Şehriyar']::text[], 8.5, '{"poet":"Şair Şehriyar","poet_slug":"sair-sehriyar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/el-kimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Koyamadım', 'adini-koyamadim-salih-ozalasan-r45ln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün bir nokta koydum hayatıma

Hani ne derler iki nokta üst üste olanından

Bir parantez açtım bugünden sonrasına

Ama hani o gülümser gibi olanından

Ve bir söz verdim yeminler ederek

Ağlamayı, ağlatmayı hüznü çıkardım hayatımdan

Bir sen gidersen, yada ağlarsan ağlayacağım

Hiç bir kimseye taviz yok artık yaşantımdan

Bir seni yaşayıp yaşatacağım gönlümde

Yok bir daha ayrılık gönül dostumdan

Çok geç olsada anladım sayende

Kalmamış farkım ne Kerem nede Mecnun''dan

Yüreğimde bir fırtına olmuş sevdan

Git diyorum sana APTAL gibi hayatımdan! .

Biliyorum gitmeyeceksin zor senin bana kıyman

Ama olurya ya birde Şeytana uysan

Bugüne kısmetmiş geç kalmış sayılmam

Hep diyordum hayatıma bir nokta koysam

Çokda zor olmadı parantezi kapamam

İçinde sen ve ben çok mutlu artık Dünya''m

Y.Tarihi 18-09-2002 Saat 10.00', 'Bugün bir nokta koydum hayatıma Hani ne derler iki nokta üst üste olanından Bir parantez açtım bugünden sonrasına Ama hani o gülümser gibi o...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adini-koyamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Zindanda Kaldı', 'ruhum-zindanda-kaldi-abdulkerim-kasim-baltaci-1ixkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim bağlanarak

Elim kelepçelendi

Karanlık perde perde

Ruhumda şekillendi

Demir şakırtıları

Ve nöbetçinin sesi

Bir kaçak yakalandı

Hazırlansın hücresi

Beş numaralı hücre

Zamanın buz tuttuğu

Asırla eş değerde

Saniyenin artığı

Gün ışığına hasret

Rengi solmuş bir deri

Zaman zaman ey zaman

Bir ileri, üç geri

Buraya mazlum düşmez

O halde suçlusun sen

Adelet yanılmaz ki

Beyhude ne söylesen

Konuş, konuşamazsın

Ağlamak, gülmek yasak

Bir yasak ki sormayın

Yaşamak, ölmek yasak

Ekmeğim taştan katı

Ve kırık çanakta su

Ölümü hatırlatır

Zindanların uykusu

Ve bir gün olmaz olur

Demir kapı açılır

Hürriyetin kokusu

Üzerine saçılır

Derler eğlen, gül, oyna

Bedenin azad oldu

Nerden bilecekler

Ruhum zindanda kaldı', 'Gözlerim bağlanarak Elim kelepçelendi Karanlık perde perde Ruhumda şekillendi Demir şakırtıları Ve nöbetçinin sesi Bir kaçak yakalandı Hazır...', ARRAY['Türk Edebiyatı','Şiir','Abdulkerim Kasım Baltacı']::text[], 8.5, '{"poet":"Abdulkerim Kasım Baltacı","poet_slug":"abdulkerim-kasim-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ruhum-zindanda-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyormusun', 'usuyormusun-hulya-senkul-32om5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgarın sesine kattım sesimi

Hasretle inliyor, duyuyor musun

Karanlık verirken son nefesini

Bensiz gecelerde üşüyor musun

Bulutlar yolladım gözlersin diye

Sevgimi yükledim özlersin diye

Camlardan süzüp izlersin diye

Bensiz gecelerde üşüyor musun

Gecenin içinde sensiz kayboldum

Çektiğim acıyı biliyor musun

Unuttum dedikçe sana savruldum

Bensiz gecelerde üşüyor musun', 'Rüzgarın sesine kattım sesimi Hasretle inliyor, duyuyor musun Karanlık verirken son nefesini Bensiz gecelerde üşüyor musun Bulutlar yolladım...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usuyormusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıtname', 'agitname-omer-avsar-b76m7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen sevdigimi nerden bileceksin

gönlünün kapılarını açtınmıki

ateşimi bendenmi sileceksin

bilipte her şeyi yok sayacak gibi

ne istedim senden ey sevgili

kuru bir ümitti kalbimin dilegi

anlamadın aşkımın yüceligini

boş verdin yanıp eridigimi

gerçek dışı degilmi

görmeden sevmek...

görmedende sever insan

yüregin gücünü bilipde anlayan...

uzun lafın kısası

istedigin gibi olsun canısı

tıpkı bu günkü gibi

sanki ateşe  atıyor misali

bundan sonra yok aşkımı anlatan sözcükler

yakacagım hepsini kendimle birer birer

yine sen kazandın hain kader

gömecegim mezara düşleri teker teker..', 'sen sevdigimi nerden bileceksin gönlünün kapılarını açtınmıki ateşimi bendenmi sileceksin bilipte her şeyi yok sayacak gibi ne istedim sende...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agitname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurhak', 'nurhak-hasan-huseyin-korkmazgil-3mx5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dört bir yana haber salsam, 

Öldü desem inanır mı? 

Dağlar bana geri verin

Kadir''imi, Sinan''ımı...

Jandarma kurşunu çaldı, 

Canımı tenimden aldı

Nurhak''a abide kaldı

Dağlar aldı selamımı...

Nurhak sana güneş doğmaz, 

Uçan kuşlar yuva kurmaz

Dökülen kan, yerde kalmaz

Soracağız hesabını...

Böyle kalır sanma devran, 

Yola devam eder kervan

Öldü Sinan, doğdu Sinan

Omuzladı silahını...', 'Dört bir yana haber salsam,  Öldü desem inanır mı?  Dağlar bana geri verin Kadir''imi, Sinan''ımı... Jandarma kurşunu çaldı,  Canımı tenimden ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nurhak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-i-smail-ozer-4e007', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gideceğim bu diyardan bir gün ardıma bile bakmadan

Arkamda buz gibi bir boşlukla bir kaç çapul bırakarak

Acaba varmıydım, yokmuydum? 

Soracak yakınlarım kendilerine

Zamanla gömecekler beni zamanın içine, hatırlamaktan korkarak

Verdiğim canın diyeti belki ama belki iki damla göz yaşı olacak, 

belki de çeyrek depo benzin mezarlığa kadar', 'Gideceğim bu diyardan bir gün ardıma bile bakmadan Arkamda buz gibi bir boşlukla bir kaç çapul bırakarak Acaba varmıydım, yokmuydum?  Soraca...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özer']::text[], 8.5, '{"poet":"İsmail Özer","poet_slug":"i-smail-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takdim', 'takdim-refik-recep-pelit-8t2bb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu benim bana kendimi birnevi takdimimdir, 

her zaman olmaz aslında bu çok nadirdir

Eski hesapları düşünüyorum da ne vakittir 

Ürperiyorum aklıma geldikce gireceğim Kabir 

Bilmem öyle riya felan, gurur veya kibir

Bazı benimde aklıma gelir yaptıklarım bir bir, 

Bu yüzden içtiğim bade çok kere oldu zehir, 

Lakin arkamdan kimseye dedirtmedim Müzevir.

Muhabetteyken iki kadehle oluruz keyfiçakır 

Düşünmeyiz dünyayı hiç, güleriz kıkır kıkır 

Kaç dansöz oynattık masamızda şıkır şıkır 

Bundanmıdır bilmem saçlara düştü biryığın kır.

Çok çektik kimi zaman ayaklarımızdaydı zincir

Kimi zaman dostlarımız bile gördü bizi hakir, 

Arasıra vezir olduk, pekçok kezde düştük esir, 

Tebessüme hasretiz, bilmem ki kaç vakittir.', 'Bu benim bana kendimi birnevi takdimimdir,  her zaman olmaz aslında bu çok nadirdir Eski hesapları düşünüyorum da ne vakittir  Ürperiyorum a...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/takdim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Denizi İçecek Gibiydi...', 'gozlerin-denizi-i-cecek-gibiydi-ediz-karaoglu-w1es4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin denizi içecek gibiydi o gün seni gördüğümde, 

	Korkumdan sana ne kadar güzel olduklarını söyleyemedim, 

	Ve sana karşı hissettiklerimi, 

	Sonra çok aşındırdım yollarını ama, 

	Ne gözlerini görebildim, 

	Ne de gözlerinin içtiği Akdeniz’i...

	Sonra döndüğümde bıraktığım bu şehre, 

	İşte o dedim, 

	İşte buymuş beni hasretliğe sokan, 

O gözler, karşısında ağladığım deniz değil, 

	O gözler benim denizimi içinde barındıran, 

	O gözler benim değil...

	Sevdiğimi söyleyemeyecek kadar korkuyordum, 

	Korkuyordum, çünkü başımdan çok geçmişti böylesine belâlar, 

	Ve dağ gibi bir adamı yıkmıştı elleri yakan hatıralar, 

	Sen denize bakarken, ben gözlerinin ferine bakıyordum, 

	Ve sorduğunda, neden baktığımı söylemiyordum, 

Bir delikanlıya yakışmasa da böylesine kaçışlar...

Gözlerin denizi içecek gibiydi o gün seni gördüğümde, 

Elimden gelmedi, gel beraber içelim diyemedim, 

Ve sana fark ettirmemek için hep konuyu değiştirdim, 

Şimdi yaptığım her telefon kaçamağında, 

Ne sesini duymaya cesaret edebildim, 

Ne de söndürebildim içimdeki bu ateşi...

							08.Ağustos.2002

								Saat: 00: 13

								İstanbul', 'Gözlerin denizi içecek gibiydi o gün seni gördüğümde,  	Korkumdan sana ne kadar güzel olduklarını söyleyemedim,  	Ve sana karşı hissettikler...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gozlerin-denizi-icecek-gibiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Dair', 'sevmeye-dair-burhan-akgun-73jbb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben birisini seviyorum

herkes sevsin istiyorum.

Ben birisini seviyorum

herkes sevsin istiyorum.

Hayatı kucaklar gibi kavrarım elinden

özgürlüğe koşar gibi koşarım hasretine.

Herkese karşı sevecenim onunla

sanki herkes sevecen onunla

Saçları gizler alev alev yüzünü

her çapkın bakışımda.

Bakınca nemli, dalgın gözlerle

sevgi dolu hasret dolu.

Titreyince bedenlerimiz elektriklenmişcesine

dur diyebilmek mümkün mü bu yangına? 

Aramıza sevginin ilmiği atılmış çözülmemecesine.

Sanki herkes bize bakıyor.', 'Ben birisini seviyorum herkes sevsin istiyorum. Ben birisini seviyorum herkes sevsin istiyorum. Hayatı kucaklar gibi kavrarım elinden özgürl...', ARRAY['Türk Edebiyatı','Şiir','Burhan Akgün']::text[], 8.5, '{"poet":"Burhan Akgün","poet_slug":"burhan-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmeye-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ah! ne desem boş!', 'ah-ne-desem-bos-levent-serkan-ozdogan-15pl5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ah! ne desem boş. 

buğulu camların ardında 

kurşun gibi bir ankara. 

gelir en senli yerimden saplanır.

yüzündeki her bensiz tebessüm, 

sana dair bir düşte saklanır...', 'ah! ne desem boş.  buğulu camların ardında  kurşun gibi bir ankara.  gelir en senli yerimden saplanır. yüzündeki her bensiz tebessüm,  sana ...', ARRAY['Türk Edebiyatı','Şiir','Levent Serkan Özdoğan']::text[], 8.5, '{"poet":"Levent Serkan Özdoğan","poet_slug":"levent-serkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ah-ne-desem-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğe Umutlar', 'gelecege-umutlar-murat-cetin-dqrmh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurtmasını gökyüzü almış

bir çocuk gibi boyun büküp

elleri yana düşmüş

seyretmedeyim uzakları.

heveslerimi çalıp

ona kaçıran rüzgara inat

bırakmayacağım

gözlerimde biriktirdiğim yaşları.

sımsıkı kapadım işte

sımsıkı.

bak! 

avuçlarımıda sıktım

yalvarmayacağım geri dönmen için.

...

hem, yalnız değilim ki, 

benim o kadar çok

o kadar çok

yalnızlıklarım var ki

sana ihtiyacımın olmadığını

gidişin müjdeledi bana.

...

umutlar yeşertiyorum avucumda

geleceğe umutlar..

..

büyüyünce unutacaklar.', 'Uçurtmasını gökyüzü almış bir çocuk gibi boyun büküp elleri yana düşmüş seyretmedeyim uzakları. heveslerimi çalıp ona kaçıran rüzgara inat b...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gelecege-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Ver', 'haber-ver-mehmet-fatin-baki-lrz8j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıl geçti sen gideli

Geleceksen haber ver

Eserken hasret yeli

Geleceksen haber ver

Koruklar üzüm oldu

Yaşaran gözüm oldu

Sana son sözüm oldu

Geleceksen haber ver

Acı haber iletme 

Dedim sana gel gitme

Ben ettiysem sen etme

Geleceksen haber ver

Doğru çıkarsa falım

Vuslattan zevk alalım

Dügün bayram yapalım

Geleceksen haber ver

Mefaki üzdü seni 

Özlüyor affetmeni

İstemedi gitmeni

Geleceksen haber ver', 'Yıl geçti sen gideli Geleceksen haber ver Eserken hasret yeli Geleceksen haber ver Koruklar üzüm oldu Yaşaran gözüm oldu Sana son sözüm oldu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haber-ver-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köyümden Ayıldım', 'koyumden-ayildim-mehmet-fatin-baki-euvir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrıldım köyümden ederek merak

Dolaştım illeri birşeyler için

Bu merak götürdü beni çok ırak

Yerlere: Hint, Japon, Burma, Tibet, Çin

Acaip ellerde dolaşır iken

Gurbette tükettim hayatımı ben

Domuzla köpekle dalaşır iken

Temanen unuttum memâtımı ben

Yaptığım şeylerin edebi vardı

Bunca iyilikler boşa gitmez ki

Ne eyledi isem sebebi vardı

Hepsini yapmağa ömrüm yetmez ki

Füc’eten  ölürsem görmeden seni

Vatanım. HAKKINI HELAL ET derim

Garipler gömmeden mezara beni

Dostları namaza davet ederim

Mefaki ilm için Çine de gittin

Eğrildi büğrüldü ilk bildiklerin

Yıllarca gençleri öğdün eğittin

Billahi sevaptır eylediklerin.

Memât = ölüm

Füc’eten = ansızın', 'Ayrıldım köyümden ederek merak Dolaştım illeri birşeyler için Bu merak götürdü beni çok ırak Yerlere: Hint, Japon, Burma, Tibet, Çin Acaip e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/koyumden-ayildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-mavi-yunus-g44ot', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usulca yanağımı okşadı annem

''Uyan dedi, meleğim bak gün doğmuş

Hayat yeni umutlarla seni bekliyor.''

                   Meleğin aşktan yorulmuş annem.

''Sağlamdır o yürek acılarla yoğrulur

Daha sağlam basarsın yere

Güçlü kılar seni herşeye.''

                   Peki neden bukadar güçsüzüm annem

                   Uyumak istiyorum sonsuzlukta

                   Dinlenmeli yüreğim karanlıklarda

''Zamana bırak kendini

o halleder herşeyi acıyı sevgiyi sevgisizliği''

                    Ama ben sevmekten vazgeçemem annem 

                    Dayanırmı bu yüreğim? 

''Aç gözlerini dünyaya göreceksin orada

Sevilecek çok şey var

Kuşlar, yunuslar, ÇOCUKLAR

Meleğim SEN varsın.

3.7.2002 Sabah', 'Usulca yanağımı okşadı annem ''Uyan dedi, meleğim bak gün doğmuş Hayat yeni umutlarla seni bekliyor.''                    Meleğin aşktan yorul...', ARRAY['Türk Edebiyatı','Şiir','Mavi Yunus']::text[], 8.5, '{"poet":"Mavi Yunus","poet_slug":"mavi-yunus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/annem-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mapus', 'mapus-hasan-devrim-03yz9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mapus, hücrenin köşesine oturdu.

                                             Durdu.

İki elinin arasına kafasını koydu.Düşündü

                                              Düşler kurdu.

Arayanı yoktu

                       yoktu soranı.

Kuş olmak vardı dedi, 

Gökte uçan kartanesi kadar beyaz

                      Ve güneş kadar sıcak

Kuş olmak vardı, 

Uçmak vardı

Dala konmak, yere inmek, toprağa tatlı bir buse

                     Ve doymak vardı.

Mutlu olmak vardı.

Meziyet basamaklarını saymak, 

Özgürlüğü tatmak vardı.

                  Kuş idi, 

                              Kar idi, 

                                          Var idi, 

Gün dar idi, 

Karanlık sır, 

                   Özgürlük ateşten kor idi.

Gül olmak vardı, 

En az ateş kadar canlı.', 'Mapus, hücrenin köşesine oturdu.                                              Durdu. İki elinin arasına kafasını koydu.Düşündü              ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Devrim']::text[], 8.5, '{"poet":"Hasan Devrim","poet_slug":"hasan-devrim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mapus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Beni Vurayım Sen Seni', 'ben-beni-vurayim-sen-seni-necla-marasli-kt4al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki sen iki ben, 

Yeşil çuha kare bir masada boy ölçüşelim

Soyunalım sandalyelerin omuzlarına 

Tedirgin elbiselerimizi.

Sen beni al karşına ben seni

Mekanizmaları işliyor zamanın

Organizmalarımız sancılı.

İktidarını kaybetmiş dünya

Katli vaciptir törpü pasına karışmış geçmişimizin

İki şarjör sürelim ortaya önce

Ben beni vurayım sen seni.

Gerçekleşmiş düşlerimizde olmasın kirli bedenlerimiz

Parmak damgası vurulmuş alınyazımızla

Yüz yüze kalalım.

Gri bir gökdelende olsun kaldığımız oda

Pis bir kükürdü üflesin şehir ciğerlerinden

Mendilini sersin gökyüzüne bulutlar

Tertemiz bir akordeon sesi yükselsin yanımıza

Çatılar düşsün ağır ağır ıslak kaldırımlara.

Gece geçsin geniş camları

Gezinsin duvarlarımızda şehrin ayna yansımaları

Adresini arasın köşe başlarında yalnızlıklar

Taksimetre tutarları hesabımıza yazılsın

Bir eğreti bitki eğsin başını gölgesini seyretsin

Komidinin cilalı maun uçurumunda

Beyaz; tütünün sarı solgunluğunda yorgan.

Kibrit tutuşmayı beklesin tablanın yanıbaşında.

Ola ki postacı gelirse gıcırdatmayalım kapıları

Yoksul çocukluğumuzun üzüncü göndermiştir o mektupları

Bizim burada olduğumuzu onlardan başka kim bilebilir ki

Yanlış telefonlara bakmasın ellerimiz

Çalacak gibi durursa da açık bırakalım ahizeyi 

Sessizliğim seni dinlesin sen sesimi.', 'İki sen iki ben,  Yeşil çuha kare bir masada boy ölçüşelim Soyunalım sandalyelerin omuzlarına  Tedirgin elbiselerimizi. Sen beni al karşına ...', ARRAY['Türk Edebiyatı','Şiir','Necla Maraşlı']::text[], 8.5, '{"poet":"Necla Maraşlı","poet_slug":"necla-marasli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ben-beni-vurayim-sen-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandal Ağacı', 'sandal-agaci-necla-marasli-ekcwn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana kapımı her açtığımda, sandal ağacı kokusu doluyordu odama... İlk geldiğin gecelerin birinde'' sende aradığım ne'' dediğinde bana, ''belki de birbirimizin hüznünde gözümüz var'' demiştim sana. Gecenin bir yarısı hep aynı adrese koşuyorsa insan, ya dinlemek, ya anlatmak için çalıyordur o kapıyı. Ne diyordun? 

-Neyim var ki anlatacak. Bir adam. Yorgun, bezgin...

  Geceler iki gün arasına sıkıştırır insanı, ezer. ''Çözül'' der. Kendinde çözülürsün de sonra akarsın bir yere. Yazılara, yabanlara, cümlemiz gibi cümlen gibi. Savrulursun da savrulursun Yorulursun bazen serseri ruhundan. Yorulursun  taşmaktan.  Kalmak istersin... Aktığında dolacağın bir çukur ararsın. Bulursun, dolarsın, durursun ve kalırsın... Durmak yorar seni. Kalmanın yetersiz olduğunu anlarsın. Aradığın kalmak bu değildir,  başka bir şeydir. Anlatırsın. Denersin, denersin. Bezgin olur adın... Bırakırsın kendini, sürüklenirsin.

Anlatmaktan yorulmuş adam... Kıyıya vurmuş. 

Duygularının kalmak istediği yeri arıyordun, kaybolacağın yeri arıyordun, karışacağın yeri arıyordun. 

Sürükleniyorsan tutulmak, dolmuşsan emilmek, donmuşsan çözülmek, bir sandalsan yansımanı görmek istiyordun.

Kendini sandal ağacı kokusuyla örten, hüznüme gözlerini diken sen;  hüznümde senin bir yanını anlatabileceğim bir yer arıyordun bir eylül zamanında.

Gözelerde uyumak isteyen ırmak gibi, kuru bir yaprakla konuşmak isteyen rüzgar gibi, sürgünlerine hasretli toprak gibi... Sen sustuğunda ben kendimi dinliyordum. Öyle seyrettim işte seni, öylesine. Kendim gibi, bilir gibi. 

Biz neydik biliyor musun? ... 

Öylesineydik! ...', 'Sana kapımı her açtığımda, sandal ağacı kokusu doluyordu odama... İlk geldiğin gecelerin birinde'' sende aradığım ne'' dediğinde bana, ''belki ...', ARRAY['Türk Edebiyatı','Şiir','Necla Maraşlı']::text[], 8.5, '{"poet":"Necla Maraşlı","poet_slug":"necla-marasli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sandal-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Karanlık Zamanlar', 'en-karanlik-zamanlar-tarkan-ceper-w6kax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'derken göğüslerinden başlıyorum sevmeye, ama ne

oluyorsa oluyor: ve aniden bir elektrik kesilmesi. neye

yormalı: bilinmez ki. gereğince uzamış, hani nerdeyse

sabaha sarkacak ki gecede, büyük şehirde de

gerçekleşmesi olası teknolojik kusurlara çok da fazla

kafayı yormamalı gerçi. tabii canım, mutlaka hiç kuşkusuz

belli bir hoşgörü çerçevesinde düşünmek en iyisi.

ama gel gör ki bastırılmış cinsel açlık ve karanlığın libido

üzerindeki önlenemez tahrip etkisi. öyle olsun olacaksa da

ama, yani ne olacak şimdi? ! : mutsuzlukların laciverde boyandığı

ve nerden baksan pek umut vaat etmeyen karanlık bir

cumartesi gecesi. sonra kafamızı durmaksızın kurcalayan bir

soru: bütün bu sahip olmak istediklerimiz; alçakgönüllü bir hayat

için gereken aylık kazancımız karşılığında elde edilemez mi yani? 

sonuçta sen ve göğüslerin olmayınca, uçsuz bucaksız bir yatakta

kendimle başbaşa kalmışım gibi kayda değmez bir sezgi. öyleyken

yalnızlıktan söz açan şarkılar zihnimin zulasında; yine de biraz

vakit doldurmak için planlanmış şu tuhaf geceyi bir ucundan tutup

yırtmak istiyor sanki. ah! bilemezsiniz: aslında öyle delirtici

ki. böyle her şeyin en uzağında ve elimiz böğrümüzde kalalım

diye mi icat edildi yani, zamanımızın kahramanı demokrasi? 

ne tuhaf şimdi böyle gecenin en kör yerinde bakakalmak solmuş

ayışığına; karnım boylu boyunca yırtılmış gibi. belirsizliğe akıp giden

bütün gözyaşlarına rağmen, giderek yükselen adrenalin: anlaşılan

çalışıyor hala böbrek üstü bezleri. kıyametin kıyısına varıyorken

senin şirketini istiyorum diye haykırıyor bir adam: belli ki hayli

yaşlı ve yıpranmış sesi. yine de hani son bir umut diye tutarken

kalbimi, anlıyorum birdenbire her şeyin sebebini: olsa olsa burjuvazi!', 'derken göğüslerinden başlıyorum sevmeye, ama ne oluyorsa oluyor: ve aniden bir elektrik kesilmesi. neye yormalı: bilinmez ki. gereğince uzam...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Çeper']::text[], 8.5, '{"poet":"Tarkan Çeper","poet_slug":"tarkan-ceper","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/en-karanlik-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ozcan-yalim-kp2sb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yelken rüzgar istiyor

Bırak dolsun

Yum gözünü aç gönlünü

Ne olursa olsun

Mademki seviyorsun', 'Yelken rüzgar istiyor Bırak dolsun Yum gözünü aç gönlünü Ne olursa olsun Mademki seviyorsun...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalım']::text[], 8.5, '{"poet":"Özcan Yalım","poet_slug":"ozcan-yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangın', 'yangin-namik-kuyumcu-fio5n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'akrepler besliyorum ellerimde akbabalar için

çiçekler ve kuşlar bağışlasın beni

yanık yapraklarını döküyor üzgün ağaçlar

yarım kalan şiirler sahibini arıyor sularda

onlar kendi göklerinde hep yalnız ve yıldızdı

gözleri ayrılan iki sevgili

kolları kavuşmanın kum saatiydi

esirgeyen de onlardı bağışlayan da

bunun için kovuldular kutsal kitaptan

şeytanla bir tutuldular

kendi küllerinde açan güllere su vermeli

adını ürperten veda koymalı hepsinin

soyluca zamandan çekilmesini bilenler

hep acıtır

ve acıtacak takvimleri

kıbleyi

kabe yerine insan saymak kafirlikse eğer

benim de katlim vaciptir

ey müminler

ey ahali

paslı bıçaklar bileyin tenimde

çarmıha gerin yüreğimi

küllerimi de yakın

yangınlara yabancı değildir kabilem

hep yanarlar aşk için

aşkları gibi anıları da yasadışı

... /...

söz aradı sahibini buldu

yalanlar vuruldu pusuda beklerken

... /...', 'akrepler besliyorum ellerimde akbabalar için çiçekler ve kuşlar bağışlasın beni yanık yapraklarını döküyor üzgün ağaçlar yarım kalan şiirler...', ARRAY['Türk Edebiyatı','Şiir','Namık Kuyumcu']::text[], 8.5, '{"poet":"Namık Kuyumcu","poet_slug":"namik-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yangin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviş Yolcu', 'sevis-yolcu-cemal-sureya-6zlpc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.

Gurbet yavrum garba düşmektir gurbet

Çiçeklerden gelincik içinde Bünyamin sevgisi

2.

Yürüdün gittin eski kurganlar üstünden kent kent

Kulağında ama bir çömleğin kırılma sesi

3.

Barış demiştir ve güvercin tıkmışlardır boğazına

Bu yüzden edep kuralı gözetmez Anadolu ermişi

4.

Bu yüzden kimi zaman zordur ayırmak

Üstünü başını yırtmış ağı
..........
..........', '1. Gurbet yavrum garba düşmektir gurbet Çiçeklerden gelincik içinde Bünyamin sevgisi 2. Yürüdün gittin eski kurganlar üstünden kent kent Kul...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevis-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Seli', 'kus-seli-tahir-abaci-563ep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşları da vurdular

Işığı güneyde emmiş kanları

Donmuş tenlerinin buzunu çözsün diye

Ve düşer düşmez soğuyup kaldı kuşlar

Neyi hızlandırabilirdi bu

Çürümüş leşlerle doldu kasaba meydanı

Ve her mavi çamaşırı bir kuş lekeledi

Balkonlara çıkarılmış limonlar arasında

Hırsla çiftleşip dururken kediler

Güneş

İnsanlara ve tarlalara dökülerek

Isıttı insanları uyanan ekinler gibi

Canlanan insanlara çevirdi ekinleri

Işıkların oynaştığı sular

Akıp gidiyordu karşı dağlardan

Kuşlar artık dağlara akıp gidiyordu...', 'Kuşları da vurdular Işığı güneyde emmiş kanları Donmuş tenlerinin buzunu çözsün diye Ve düşer düşmez soğuyup kaldı kuşlar Neyi hızlandırabil...', ARRAY['Türk Edebiyatı','Şiir','Tahir Abacı']::text[], 8.5, '{"poet":"Tahir Abacı","poet_slug":"tahir-abaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kus-seli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Hava', 'kapali-hava-tahir-abaci-cmawq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece eksitilen rüyalar içinde eridi

Geçmiş dirildi siyah yağmurlarında arka bahçenin

Karanlıkta çırpındı hayalet dizeler

Yaralı biçimleri benzetme mağlubu

Başkasından ses umarken dile gelen söz gibi

Boş odaya uğrayanın dilinde ağrıyan söz gibi

Bu yıl boralandı kış, üşüdü rapsodi

Elimde büyüteç, saksıda kar çiçekleri

Üşenip suyu bidondan, şarabı şişeden içtim

Ve aynı tat geldi hepsinden ağu

Hayat sıkıcı hayatla barışık sevgili

Yıkıldı çoktan o mimari, binası dimdik ayakta

Hemen solmaya başlayan A''sı kadar yaşanıyor aşk

Ş''ye takati yetse alkol gibi olurdu zaten

Sabahın alışkanlık zifosunda solup gidecek bu resimde

Rüya kadar uyanık olmaya bir çağrı var', 'Gece eksitilen rüyalar içinde eridi Geçmiş dirildi siyah yağmurlarında arka bahçenin Karanlıkta çırpındı hayalet dizeler Yaralı biçimleri be...', ARRAY['Türk Edebiyatı','Şiir','Tahir Abacı']::text[], 8.5, '{"poet":"Tahir Abacı","poet_slug":"tahir-abaci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kapali-hava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-orhon-murat-ariburnu-9qc8q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O, yalnız ayna satardı.

Ve birgün aynalı çarşıda öldü.

Talih bu ya

Tabutunu taşıyanlar

AYNASIZLARDI...', 'O, yalnız ayna satardı. Ve birgün aynalı çarşıda öldü. Talih bu ya Tabutunu taşıyanlar AYNASIZLARDI......', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayna-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gözlerimin İçinde', 'sen-gozlerimin-i-cinde-orhon-murat-ariburnu-80a4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben daha büyük

Ben daha yüce

Sen gökyüzü

Ben insan

Ben sevgi

Ben düşünce

Ben daha büyük

Ben dana yüce

Ölürüm özgürluk için

Acılar bende

Umutlar bende

Ben daha büyük

Ben daha yüce

Sen gökyüzü

Sen sonsuzluk

Sen bende

SEN GÖZLERİMİN İÇİNDE', 'Ben daha büyük Ben daha yüce Sen gökyüzü Ben insan Ben sevgi Ben düşünce Ben daha büyük Ben dana yüce Ölürüm özgürluk için Acılar bende Umut...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gozlerimin-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Sevmem Bu Dünyayı', 'nasil-sevmem-bu-dunyayi-orhon-murat-ariburnu-h0r3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl sevmem bu dünyayı

İnsan eli değmiş her yere

Evlere

Caddelere

Makinelere

Nasıl sevmem bu dünyayı

İNSAN DOĞMUŞUM BİR KERE', 'Nasıl sevmem bu dünyayı İnsan eli değmiş her yere Evlere Caddelere Makinelere Nasıl sevmem bu dünyayı İNSAN DOĞMUŞUM BİR KERE...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nasil-sevmem-bu-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havvanın Kızı', 'havvanin-kizi-orhon-murat-ariburnu-ivr9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bacak bacak üstüne koyma

Ortadan ayırma saçlarını

Gülerken deli edersin

Gülme

Esvabın darını giyme

Hele kapının önünde durup mehtaba karşı

Elini elime verme

Zor olur ayrılması senden

Bak söylüyorum

Delikanlıyım

Fena olurum

Günahkar olurum

Yapma

Sakın ha

Söylediklerime bakma!', 'Bacak bacak üstüne koyma Ortadan ayırma saçlarını Gülerken deli edersin Gülme Esvabın darını giyme Hele kapının önünde durup mehtaba karşı E...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/havvanin-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Değil', 'bir-degil-turhan-doyran-bh5a1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk değil

İki değil üç değil

Dört değil beş değil

On değil on beş değil

Yüz değil

99.', 'İlk değil İki değil üç değil Dört değil beş değil On değil on beş değil Yüz değil 99....', ARRAY['Türk Edebiyatı','Şiir','Turhan Doyran']::text[], 8.5, '{"poet":"Turhan Doyran","poet_slug":"turhan-doyran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farelere ve Şairlere Dair', 'farelere-ve-sairlere-dair-savkar-altinel-4ef9q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kedinin gece getirdiği fare

sabah yatıyor holde.

Sırtı boz, karnı gri, 

burnunda bir parça

kurumuş kan; 

küçük ayakları

aşağı doğru kıvrılmış

daha kolay geçmesini

sağlamaya çalışmış gibi

ölümün deliğinden.

Bir torba buluyor

ve alıp atmak için

eğiliyorum üstüne; 

ama bir yandan da

her zamanki gibi aklım

keşfetmeye çalışıyor nasıl

yazabileceğimi bütün bunları, 

sanki yeterince ince ve kıvrak

sözcükler bulunabilse

sona erermiş gibi dürtüşü

bir daha hiç tamir olmayacak şeylerin.', 'Kedinin gece getirdiği fare sabah yatıyor holde. Sırtı boz, karnı gri,  burnunda bir parça kurumuş kan;  küçük ayakları aşağı doğru kıvrılmı...', ARRAY['Türk Edebiyatı','Şiir','Şavkar Altınel']::text[], 8.5, '{"poet":"Şavkar Altınel","poet_slug":"savkar-altinel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/farelere-ve-sairlere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balonlar', 'balonlar-savkar-altinel-tg2x9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaz akşamları

hava daha kararmadan

bu yörede büyük balonlar

beliriyor gökte bazı; 

baş aşağı armutlar gibi

süzülüp geçiyorlar yavaşça, 

brülörlerinin alevleri

arada bir parlayarak.

Ve onlardan birine binip

yükseldiğini düşlüyor insan; 

rüzgarın kımıldattığı ipler, 

boşlukta sallanan sepet

ve aşağıda tanıdık

coğrafyası bir hayatın: 

Umut çayırları, sevgi tepeleri, 

düşlerin sona erdiği

karanlık korular, 

bellekten silinmemiş

bir iki acı kasaba

ve kıvrıla büküle

uzanan yolları pişmanlığın, 

hepsi küçük, uzak, uyumlu

ve neredeyse önemsiz artık

gün ağır ağır sönerken.', 'Yaz akşamları hava daha kararmadan bu yörede büyük balonlar beliriyor gökte bazı;  baş aşağı armutlar gibi süzülüp geçiyorlar yavaşça,  brül...', ARRAY['Türk Edebiyatı','Şiir','Şavkar Altınel']::text[], 8.5, '{"poet":"Şavkar Altınel","poet_slug":"savkar-altinel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/balonlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caymaz Dönüş', 'caymaz-donus-seyyidhan-komurcu-vh4oc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'nasıl desem, adı ılgın, ağaç

giz dolu bir sesin öte yakası

- diyemedim -

sarı saman kağıdı galiba Ankara

savunmasız ve çizgisiz suç unsuru

yazdığım; benden yana, çirkin.

ki geldiğim yerde

ismimden bir harf unutmuşum

çağrıldıkça alnıma çarpan bir - olsun -

olsun, sen ödeştik say

biri birini tutmaz alfabelere yor

zira çocuk bile saysan

artık tartılınca eti benim, kemiği benim

babamın ve ustamın halefi say.

- artık - önemlidir

artık diyorum

ayak izlerim kalsın, parmak izimi ver

ve yaşama sevinci ve aşk

kalemiyle dağdağan çekirdeği fırlatan her çocuğa

öz kalıyor en büyük ganimet

bilet oluyor caymaz dönüş, daha acemi bir bedene

özlediğimiz yolculuk

kimbilir, bir kalıp yeşil sabuna

ve daha masum bir slogana; 

engürü olsun lakabın

adın da Ankara.', 'nasıl desem, adı ılgın, ağaç giz dolu bir sesin öte yakası - diyemedim - sarı saman kağıdı galiba Ankara savunmasız ve çizgisiz suç unsuru y...', ARRAY['Türk Edebiyatı','Şiir','Seyyidhan Kömürcü']::text[], 8.5, '{"poet":"Seyyidhan Kömürcü","poet_slug":"seyyidhan-komurcu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/caymaz-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Özeleştiri Denemesi', 'bir-ozelestiri-denemesi-omer-ates-vjp7o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu kara gözlükleri takmasan olmaz

Üç beş günlük sakallarını kesmesen

O kadar dağıtmasan saçlarını

Bir yerlerden bir yerlere

Telaş içinde

Bir yerlerden bir yerlere

Gecikmeden gitsen

Dudaklarının kıyısına

Ağır bir gülümseyişle

Bir karanfil iliştirsen yakana

Sevsen seni sevenleri biraz da

Kulak versen

Bayram tebrikleri yollasan büyüklerine

Güvercinleri dingin denizleri önemsemeden

Biraz para tutsan elinde

Üç öğün yemek yesen ama

Sigarana sigara eklemesen

Yer bezi yapsan

O bahriyeli kaputundan

Afrika menekşeleri koysan pencerene

Islık çalmasan da sabahları

Kırık aynalarda tıraş olurken

Özensen sarı dişlerine

Arasıra versen yüzünü

Denize bakan sokaklara

Tıp tıplasa yüreğin

Ne olur ellerin titrese

Görünce o dünyalar güzeli kadın

İndirsen gövdeni çarmıhlardan

Bir gün çocukların olsa senin de

Deniz koysan adını can

Mahir koysan memet koysan olmaz.', 'Şu kara gözlükleri takmasan olmaz Üç beş günlük sakallarını kesmesen O kadar dağıtmasan saçlarını Bir yerlerden bir yerlere Telaş içinde Bir...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ateş']::text[], 8.5, '{"poet":"Ömer Ateş","poet_slug":"omer-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-ozelestiri-denemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Gurbet Adı Gönder', 'bana-bir-gurbet-adi-gonder-abdulkadir-bulut-cnqjf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana bir gurbet adı gönder

Her yolda bir yürüme isteği

Bir de anımsamak için sevdiklerimi

Sarışın kızların gözleri gibi açılan

Bir harnup çiçeği

Bana bir gurbet adı gönder

İçinden çıkamadığım çok şey var

Kuşların ağzını açarak ölmesi

Ve dünyadaki çiçekler içinde

Fesleğenin örselenerek koklanması

Bana bir gurbet adı gönder

İlk kez oturup ağladığın yerden

Yeni yakılmış bir ağıt sözü içinde

Bir de söğüt yaprağı koy yanıma

Belki sulara olan hasretliğimi giderir

Bana bir gurbet adı gönder

Çoktandır kimsenin yüzüne bakmıyorum

Uyuyup kalıyorum oturduğum her yerde

Unutma bana bir gurbet adı gönder

Şu günlerde', 'Bana bir gurbet adı gönder Her yolda bir yürüme isteği Bir de anımsamak için sevdiklerimi Sarışın kızların gözleri gibi açılan Bir harnup çi...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Bulut']::text[], 8.5, '{"poet":"Abdülkadir Bulut","poet_slug":"abdulkadir-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-bir-gurbet-adi-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Gördü?', 'kim-gordu-i-smet-kemal-karadayi-uvq34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir genç kadın, orada

Çok ağlarmış, az güldü

Bir kadın... yani sonra

Çil çil çilek göründü

Koşup bana geldikçe

Deli düz bahçelerden

Tutup okşardım onu

Öğerdim... o gülümdü

Suskun, şemsiyeleri yok

Çizmeleri kırmızı

Ne ki şu bu... kuyu''da

''Kız saçını kim ördü''

Nasıl gün gün yaşanır

İster kış ister yazla

Dedik, ''çün sevişelim''

Sevişmemek ölümdü

Yorulsak mı, bilemem

Güzelim artılarla

İlk an, son an... dokumuz

Gizliydi, vay bölündü

Ve kaç kadın orada

Algın, yalnız... daha mı

Sevsen kaç kez seversin

Gül be Gülsüm, kim gördü', 'Bir genç kadın, orada Çok ağlarmış, az güldü Bir kadın... yani sonra Çil çil çilek göründü Koşup bana geldikçe Deli düz bahçelerden Tutup ok...', ARRAY['Türk Edebiyatı','Şiir','İsmet Kemal Karadayı']::text[], 8.5, '{"poet":"İsmet Kemal Karadayı","poet_slug":"i-smet-kemal-karadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kim-gordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bir Dönsen', 'ah-bir-donsen-selma-cuhaci-okeue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizlik geceler boyunca

Islak gözlerimde hayalin

Anılar duruyor başucumda

Sanki hiç gitmemiş gibisin

Bırakma bırakma, affet beni

Çok mu zor unutmak geçenleri

Hasrete yenilmez gerçek aşklar

Sevince vız gelir ayrılıklar

Ah bir bilsen nasıl pişmanım şimdi

Ah bir dönsen bir daha üzmem seni

Ben çok değiştim inan ki

Ah bir gelsen bir tutsan ellerimi

Ah bir sevsen yine eskisi gibi

Sen o zaman gör halimi

Ayrılık tak etti canıma

Yeter, hasretinle tükendim

Var mısın yeniden başlamaya

Hepsi bir şakaydı diyelim

Ağlatma, ağlatma artık beni

Bir şans ver, yıkmadan bu sevgiyi

Unutma yılların hatırı var

Sevince vız gelir ayrılıklar', 'Sensizlik geceler boyunca Islak gözlerimde hayalin Anılar duruyor başucumda Sanki hiç gitmemiş gibisin Bırakma bırakma, affet beni Çok mu zo...', ARRAY['Türk Edebiyatı','Şiir','Selma Çuhacı']::text[], 8.5, '{"poet":"Selma Çuhacı","poet_slug":"selma-cuhaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ah-bir-donsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancıymışız', 'yalanciymisiz-gonul-sen-8d6vx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani biz sevgilim ayrılamazdık

Hani ayrılırsak yaşayamazdık

Hala yaşıyoruz, toprak olmadık

Biz ikimiz birden yalancıymışız

Hani yenecektik kader gücünü

Alacaktık sevenlerin öcünü

Şimdi felek yendi ikimizi de

Biz ikimiz birden yalancıymışız

Seven kalbimizle bir söz vermiştik

Hani biz herkesten fazla sevmiştik

Hala benim neden gözlerim yaşlı

Biz ikimiz birden yalancıymışız', 'Hani biz sevgilim ayrılamazdık Hani ayrılırsak yaşayamazdık Hala yaşıyoruz, toprak olmadık Biz ikimiz birden yalancıymışız Hani yenecektik k...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalanciymisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerim Pişman Olmazsın', 'dilerim-pisman-olmazsin-hamza-dekeli-13wqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün başka biriyle görmüşler seni

Altında son model bir araba varmış

Üzerinde kardan beyaz elbise

Parmağında nişan yüzüğü varmış

Üzülme yoluna çıkmayacağım

Görsem de yüzüne bakmayacağım

Neden yaptın diye sormayacağım

Dilerim sonunda pişman olmazsın

Aldatırken beni düşünmedin mi

Kalbinde bir sızı hissetmedin mi

İnsan para için değişilir mi

Dilerim sonunda pişman olmazsın', 'Dün başka biriyle görmüşler seni Altında son model bir araba varmış Üzerinde kardan beyaz elbise Parmağında nişan yüzüğü varmış Üzülme yolun...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilerim-pisman-olmazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelecesin', 'sen-gelecesin-hulya-senkul-negc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrıldığımız o gün

Çok olmadı daha dün

Şu anda, hemen bugün

Sen bana geleceksin

Gözlerinde pişmanlık

Boğazında hıçkırık

Sevdiğimsin diyerek

Benden af dileyeceksin

Kıpır kıpır duygular

Sanki sen geleceksin

İçimde bir ümit var

Sanki sen geleceksin

Kalbim seni arıyor

Alev alev yanıyor

Herkes seni soruyor

Gönül bana kanıyor

İşte hazırlanzım bak

Başımda telli duvak

Yasakları yıkarak

Sen bana geleceksin', 'Ayrıldığımız o gün Çok olmadı daha dün Şu anda, hemen bugün Sen bana geleceksin Gözlerinde pişmanlık Boğazında hıçkırık Sevdiğimsin diyerek ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-gelecesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylardan Eylül...', 'aylardan-eylul-cigdem-simsek-h2yan', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aylardan Eylül...

Neden hep ayrılıklar eylülde yaşanır? 

Biten nedir? 

Yazın sıcağından daha alevli aşklar, 

Ne diye bir anda söner, kül olur gider? 

Aklını bir gülüşte, 

Gülüşlerini bir yürekte, 

O yüreğin teninde de ellerini bırakmışsındır, 

Geri alamazsın...

Eylülü sevmiyorum! 

Ben eylülleri yaşamak istemiyorum.

Eylüller kanıyor, 

Kapanmamış yaralardan...

Aylardan yine Eylül...

Ve biz seninle ayrılacağız, 

Bir yaz masalıydı, 

BİTTİ diyeceğiz küllerin içinde.

Aklını, gülüşlerini, yüreğini bende bırakacaksın, 

Geri alamadan...

Eylülü sevmiyorum! 

Ben eylülleri yaşatmak istemiyorum.

Eylüller hep kanıyor...

Hiç kapanmayan yaralardan...!', 'Aylardan Eylül... Neden hep ayrılıklar eylülde yaşanır?  Biten nedir?  Yazın sıcağından daha alevli aşklar,  Ne diye bir anda söner, kül olu...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aylardan-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeyiz?', 'nerdeyiz-cigdem-simsek-3rdr8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen nerdesin, 

Ben nerdeyim? 

Ayrı hayatlarda, 

Aynı kalpteyiz.

Sen bendesin, 

Ben sendeyim.

Biz nerdeyiz?', 'Sen nerdesin,  Ben nerdeyim?  Ayrı hayatlarda,  Aynı kalpteyiz. Sen bendesin,  Ben sendeyim. Biz nerdeyiz?...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nerdeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürsün...', 'olursun-cigdem-simsek-fgdp3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana inanmıyorum.

Güvenmiyorum...

Sende onlar gibisin, 

Her erkek gibi...

Başaramazsın! 

Benimle olamazsın...

Taşıyamazsın beni...

Çok ağır gelir sana; 

Gülüşlerim, sevişlerim...

Ne benle yapabilirsin, 

Ne de bensiz...

Kırılırsın! 

Yorulursun! 

Dayanamazsın! 

Ölürsün...! 

Sözlerim vurur seni, 

Kırılırsın...

Ellerimde şekillenir, 

Yorulursun...

Tenimde kaybolur, 

Dayanamazsın...

Zehirli gözlerim kanında dolaşır, 

Ölürsün...! 

Hiç deneme! 

Kırılırsın! 

Yorulursun! 

Dayanamazsın! 

Ölürsün!', 'Sana inanmıyorum. Güvenmiyorum... Sende onlar gibisin,  Her erkek gibi... Başaramazsın!  Benimle olamazsın... Taşıyamazsın beni... Çok ağır ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olursun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İstedim', 'yasamak-i-stedim-okay-yildiz-2wxa8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak İstedim 

Ölümün Öteki Ucunda 

Sessizce.

Görmeden Gözlerim

Umut Ve Hayal Arasındaki  Farkı

Yürüdüm

Yollar Deniz Oldu 

Ayağım Kaydı.

Yürüdüm

Rüzgar Dediler

Sevdamı Uçurdu.

Yürüdüm

Yolumu Şaşırarak

Elimde Tebessüm

Yüreğime Yasladım Avucumu.

Bir Sonraki Dönemeç Gelene Dek. 

Dönemeçler Başlangıç

Ve Her Seferinde  Biraz Daha Suskunluk

Biraz Daha Kızgınlık

Aradıklarımı Bulamamak

Hafif Bir Durgunluk

Haykırış Sonrada Tüm Sessizliğimle.

Yine De Yaşamak Dedim

Umutsuzluk, 

Karanlık Arasında 

Yine De Yaşamak.

Ağlamak Arada Bir

Arkasından İnadına Gülmek

Küfredercesine İlerlemek

Yaşamak Dedim 

Yine De Yaşamak

Boş Bir Kağıt Beyazlığı Gibi

Yaşadıkça Karalanan.

Yaşadıkça Buruşan.

 Merhaba, 

Merhaba Yazarak Her Satırına 

Hiç Aralık Vermeden 

Her Satırını Doldurarak 

Yaşamak Dedim 

Yıldızlar Kadar Çok 

Güneş Tadında Yaşamak.

                    				          05/03/2002', 'Yaşamak İstedim  Ölümün Öteki Ucunda  Sessizce. Görmeden Gözlerim Umut Ve Hayal Arasındaki  Farkı Yürüdüm Yollar Deniz Oldu  Ayağım Kaydı. Y...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yasamak-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşünü Bana Verir Misin?', 'gulusunu-bana-verir-misin-okay-yildiz-zcs6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ulaşılmaz oldukça. 

Bir az daha, 

Bir az daha benimsiyorum seni.

Bedenim titredikçe yanında, 

Hergün; bir az daha özlüyorum seni.

Kaçırmak isterken gözlerimi.

Sanki her yerdesin.

Sesini duyamadığımda. 

Unutur gibiyim tüm sesleri

Gülüşünü bana dinletir misin? 

Kelime kelime yazıyorum seni beynime, 

Kelime kelime anlıyorum sevdamı.

Kabullendiremiyorum.

Yokluğunda bende yokum.

Birleştirebilsem parçaları, 

Haykırabilicem gözlerine korkan sözcükleri.

Birer birer, 

Biner kere bağıracağım belki de.

Gülüşünü bana gösterir misin? 

Bir çözebilsem aşkın tanımını, 

Baharı ayağına getirmeye hazırım.

Bir anlayabilsem seni, 

Kara bulutları içime çekmeye hazırım.

Güneş inecektir bakışınla gözlerime, 

Gecem gündüzdür sen varken karanlığımda, 

Ah yürüyebilsem yolunda

Çiçekler dikmeye hazırım.

Gülüşünü bana verir misin?', 'Sen ulaşılmaz oldukça.  Bir az daha,  Bir az daha benimsiyorum seni. Bedenim titredikçe yanında,  Hergün; bir az daha özlüyorum seni. Kaçırm...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gulusunu-bana-verir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlat Beni', 'aglat-beni-okay-yildiz-pt8rr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlat beni

Suskunlukla

Bölüşülmüş günlerin en acımasızında 

Ellerimde çiçeklerin kuruduğu zaman

Beynimde direncin adı silinmiş

Kararsızlık kramp gibi girmişken bacaklarıma

Nereye gideceğimi bilmeden yürürken

Hadi söyle 

Söyle 

Ve ağlat beni

O kadar basit değildi her şey

Gülüp geçecek kadar

Susacak kadar sonsuza dek

Unutmak gibi  basit değildi

Farkına varmışken tam

Kabullenmişken 

Ne duruyorsun 

Bağırsana 

Bağır kulağımın dibinde

Sağır edene dek 

Çıldırtarak  sözcükleri

Duyurana kadar bağırsana

Bağır

Ve ağlat beni

Yıldızların arasında dolaşırken

Kaybettim birden, kırışmış özlemlerimi 

Nedense aramadım

Yıldız yıldız dolaşarak.

Sessizlik yetiyordu 

Uzunca

Her acının yerini doldurarak 

Arada bir kayardı yıldızlar ellerimden

Acırdı ellerim

Tırnaklarımdan akardı kırmızılık

Ve özlemlerimi hatırlardım  her yeni acıda

Işıklarını söndürün derdim yıldızlara

Yüzümü görürken ağlayamazdım

Söndür artık

Ve ağlat beni

Rüzgar taşlarını  gözlerime attığında 

Gözlerimden akan kanlı yaşlar gibi 

ağlat beni

Kör bir güvercinin uçarken ağlaması 

Dört duvar arasında dökülen gözyaşları 

Ağlat beni

Eskiden ağladığım gibi

Şafak türküsünü dinlerken 

Kaybolan aşka 

Unutulmuş hayallerin peşinden

Bahara 

Sıkıştırılmış yaşama

Ve sana

ağladığım gibi 

Ağlat beni

Çok uzun zaman oldu 

Bölüşmeyeli göz yaşlarımı

Bir yalnızlık var etrafımda 

Göremediğim 

Ama hep benimle.

Nedense boynu bükük kaldı 

Hayatın felsefesi

Ve bu yalnızlık varken içimde

Dökemem gözyaşlarımı dışarıya 

Ve içime attıkça suluyor sanki yalnızlığımı

Her gün  daha büyük

Her gün daha hissedilir..', 'Ağlat beni Suskunlukla Bölüşülmüş günlerin en acımasızında  Ellerimde çiçeklerin kuruduğu zaman Beynimde direncin adı silinmiş Kararsızlık k...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/aglat-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'son-bakis', 'son-bakis-okay-yildiz-dga63', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey gitti, 

Bir tek mavilik kaldı yerinde...

Haykırışlarım yormaya başlamıştı beynimi.

İnandırıcı gelmiyordu

yankılarımın bana söylediği yüzlerce öğüt, 

cesaretti benim için susup da dinlemek sessizliği

aramak içinde bir sesi.

Artık anlamı yoktu gözlerimi açık tutmanın

Elimle şekiller yapıp, görmediklerimin adını koymanın

Saçlarımı okşayarak uzadığını hissetmenin

Kestirmek isteyişimin

Tırnaklarımla kanatarak suratımı

Bir şekil vermenin.

Nefes almanın bir anlamı yoktu. 

Uykuydu  galiba

Varolandan uzaklaştıran beni.

Hangisi gerçekti bilmiyorum

Ama isterdim bir yeşillik önümde olsun

Bir koku gelsin burnuma küf kokusuna benzemeyen

Bir farklı ses duymayı

Önceden vardı

Evet, uyku değildi hatırladıklarım

Bir yüz var gözümde hiç silinmeyen

Bir ağlama sesi

Ve kırmızılık, 

Hayır uykuydu bunlar

Uyku olsun ne olur

Ben niye burdayım.

Ben neden kaçıyorum 

Kim  koydu bu karanlığa bedenimi

O yüz kime ait.

Önceden karanlığın dışını gezerdim

Bir çocuk sesi duyardım, 

Ağlayanlar 

Kuş yavrularıydı galiba

Su ses çıkarıyordu kendi başına

Usulca akarak.

Bir mavilik ve parlaklık vardı üstünde

Karanlığın sırrımıydı 

Ayaklarımı parçalayan demir teller hatırlıyorum

Dev  duvarları

Bağıranlar vardı etrafımda

Çığlıklar, bağırışlar ve 

Ve sessizlik.

Her şey gitti

Bir tek mavilik kaldı yerinde.

Demirlerle ayrılmış ve bazen yok olan', 'Her şey gitti,  Bir tek mavilik kaldı yerinde... Haykırışlarım yormaya başlamıştı beynimi. İnandırıcı gelmiyordu yankılarımın bana söylediği...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/son-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gidersen gözyaşlarım ıslatır yüreğimi', 'gidersen-gozyaslarim-islatir-yuregimi-okay-yildiz-0rz8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık belki de 

Beni bu kadar çok etkileyen

Ve bakışlar.

Bir yerlerde suskunluğumu saklamıştım

Kaybederim zannederek, 

unutulmayan suskunluğum 

Unutulan umutların arasından 

her seferinde sıyrılıyor 

bir şeyler var farkındayım

kendimi kanıtlamak istercesine dolanıyorum etrafında 

ve bir tek kalbimi sunabiliyorum sana

bilki bakarken gözlerim parlarsa

yüreğim ıslatıyordur gözlerimi

dolaşmak isterken karanlık sokaklarda

yanımda olmanın hayali yetmiyor

çaba gösteriyorsam uzunca seni seyretmemek için

baktığım yer senin gölgen oluyor.

Görüyorum 

Adım adım yaklaşıyorum sana

Tutmak istesemde kendimi

Her an yanındayım sanki

Bilmiyorum kalbinde neler var

Yaklaşırken sana doğru

Diğer taraf uçurum mu yoksa.

Korktuğumdan değil endişem

Adım adım yaklaşırken

Sen bir adım atarmısın benim için

Yoksa gidermisin

Bilmiyorum.

Bil ki giderken parlarsa gözlerim.

Yüreğimi ıslatan gözyaşlarımdandır.', 'Yalnızlık belki de  Beni bu kadar çok etkileyen Ve bakışlar. Bir yerlerde suskunluğumu saklamıştım Kaybederim zannederek,  unutulmayan susku...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gidersen-gozyaslarim-islatir-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-okay-yildiz-8a75r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep dört duvar arasında buluşuruz

Yeri bellidir yalnızlığın 

Sanki beni bekler gibi.

Geceyi, 

Dört duvar arasında düşünürüm 

Aslında o duvarlar arasında kimse yoktur 

Ben bile fark etmem kendimi

Ben hayaletimdir o duvarlar arasında.

O kadar sessiz ki her yer 

Korkutur yalnızlık beni

Ne kadar alışsam da yalnızlığa yine de korkarım 

Sessizliği delecek bir ses beklerim 

Bazen rüzgarın uğultusunu dinler 

Korku filmini baş oyuncusu olurum 

Yalnızlığın düzenlediği dekor içinde kaybolurum.

Sessizliğim ayak sesleriyle deliniyor.

Yaklaşan ayak seslerini yönetememenin ızdırabını yaşarım yüreğimde

Yavaş yavaş yok olur sesler.

Kapı kulpu hiç oynamıyor yerinden.

								27.07.2000', 'Hep dört duvar arasında buluşuruz Yeri bellidir yalnızlığın  Sanki beni bekler gibi. Geceyi,  Dört duvar arasında düşünürüm  Aslında o duvar...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluş', 'kaybolus-okay-yildiz-wbaue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirler Anlatmaz Oldu

Umutlarımı, 

İmgelerimi, 

Haykırışlarımı.

Eskisi Gibi Bakamıyorum Artık

Gözlerim Anlatmaz Oldu 

Güneş Batışının Ateş Rengini

Sokakların Sessiz 

Sokakların Sensiz Yaşayışlarını

Yüreğim Sızlamaz Oldu 

Sevginin Kanatları Avucumdayken 

Kanatların Yumuşaklığı Bedenimdeyken

Bedenimin Titrekliğiyle

Ölümle Yaşamın Arasında Savaşırken

Solgun, 

Kızgın, 

Acınan Bakışlar Bedenimdedir.

Kurşun Namludan Fırlar

Umut Akar 

Yüreğim Bulutlardan Yüksektedir.

						

						14.06.2000', 'Şiirler Anlatmaz Oldu Umutlarımı,  İmgelerimi,  Haykırışlarımı. Eskisi Gibi Bakamıyorum Artık Gözlerim Anlatmaz Oldu  Güneş Batışının Ateş R...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaybolus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-okay-yildiz-amjxp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden Bahar 

O Eski Bahar Yok Artık

Ne Sen Varsın

Ne De Sensiz Baharın Tadı Var

Türkü Söyleyişlerimiz 

Titretirdi Bazen 

Parktaki Yalnız Ve Tek Ağacı

Bazen O Ağaca Bakarken 

Gözlerin Dalardı

Yalnızlık Korkuturdu Hep Seni

Halbuki Beni Hiç Korkutamadı

Bilirdim Hep 

O Ağaca Gelip

Üstüne Kazıdığım Baş Harfini Tırnaklarımla Deşeceğimi

Ağlayacağımı Sonra Da

Bilirdim 

Sessizliğe Türkü Söyleyip

Sensizliğe Şiir Yazacağımı

Ama Güzel Kız

Bizi Ayıranın Ölüm Olacağını Bilemedim

Sen Söylerdin Bana 

İçine mi Doğmuştu 

Kahrolası Hayatın Kahpe Gerçekleri

Bilmiyorum

Ayırırsa Bizi Ölüm Ayırır

Ölümle Öldür Her Şeyimi Derdin 

Senle Gittiğimiz Her Yeri Bir Daha Geziyorum

Bazen Taş Alıp Sokaklara Fırlatıyor

Bağırıyorum

Ağlamak Yakışmaz Sana Derdin 

Ağlıyorum Güzel Kız Affet Beni

Unutamıyorum Seni 

Yeni Bir Hayat Yok Bana 

Tutamıyorum Sana Verdiğim Onca Sözü

Bir Kaçı Hariç Güzel Kız 

Yakamadım Mektuplarını

Doğum Günümde Aldığın 

Üzerinde Baş Harfin Olan Kolyeyi Atamadım Denize

Ama Senin Olan Yüreğimi 

Sadece Sen Olan Beynimi 

Öldürüyorum

Kır Çiçeğim 

Deniz Gözlüm

Güzel Kız, Öldürdüm Sen Olan Her Şeyimi

Geliyorum

Ayıramayacak Ölüm Bile Bizi 

Ayıramayacak.

										03.05.2000', 'Mevsimlerden Bahar  O Eski Bahar Yok Artık Ne Sen Varsın Ne De Sensiz Baharın Tadı Var Türkü Söyleyişlerimiz  Titretirdi Bazen  Parktaki Yal...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ozlem-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü Karanlık', 'gokyuzu-karanlik-okay-yildiz-bwbhh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarıda ki yaprak gibi titriyorsun yüreğim

O kadar sararmış tenin 

O kadar güçsüz bedenin

Her an bir rüzgar savurur seni 

Gecenin karanlığında kaybolmuş kente

Kim bilir belki yıldızlara savurur

Aydınlığa, umuda 

Yeniden yaşama savurur.

Perdeyi aralıyorum 

Gökyüzüne bakıyorum. 

Bakmaz olaydım

Gökyüzünde hiçbir şey görmüyorum

Dışarıda ki yaprak gibi titriyorsun yüreğim

Titriyorsun 

Çünkü yaşam titriyor

Yaşam, yaşamak için direniyor.

Elimde bir silah olsa vursam 

Ölümü vursam, karanlığı vursam 

Yada kendimi vursam

Yeter ki kurtulayım şu sızıdan

Sanki siper almış güneş bana 

Sanki zehir gibi geliyor rakının tadı

Papatyanın kokusu, kefen gibi ölüm kokuyor.

Bir ölsem diyorum 

Belki kurtulurum diyorum.

Perdeyi aralıyorum 

Gökyüzüne bakıyorum. 

Bakmaz olaydım

Gökyüzünde hiçbir şey görmüyorum

Ne  bir yıldız

Ne bir umut 

Gökyüzünde hiçbir şey görmüyorum 

Ne bir yaşam 

Ne bir aşk 

Ne de adam gibi ölüm

Gökyüzünde hiçbir şey görmüyorum		18-11-2000', 'Dışarıda ki yaprak gibi titriyorsun yüreğim O kadar sararmış tenin  O kadar güçsüz bedenin Her an bir rüzgar savurur seni  Gecenin karanlığı...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gokyuzu-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Özlem', 'dosta-ozlem-okay-yildiz-y7ucs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi sen de git bu gece

Giderken umut beklediğimiz yıldızları da götür

Götür ki ağlamasın arkandan

Götür ki  bende görmeyeyim onları

Yıllar kördüğüm oldu beynimde

Sanki dün gibi 

Elinin tersiyle ittiğin büyüklük

Hani biz hep çocuktuk

Hani biz hiç büyümeyecektik

Silah patlayacaktı yan dağlarda 

Biz oyun oynayacaktık.

Hadi sen de git bu gece

Giderken umut beklediğimiz güvercinleri de götür

Götür ki kanat çırpmasınlar arkandan

Götür ki  bende görmeyeyim son çırpınışlarını

Neden yaşam gibi 

Zaman da durmuyor bir anda 

Her sabah kaldığımda

Günaydın diyorum yeni uykusundan uyanmış papatyalara

Günaydın diyorum gökyüzüne

Biliyorum bugün de elbet ölecek

Karanlığa bürünecek

Yine de gökyüzüne günaydın diyorum 

Ve ağlıyorum

Daha yeni doğmuşken 

Ağlıyorum sana gökyüzü 

Alıştırıyorum kendimi 

Yıldızsız bir geceye

Hadi sen de git bu gece

Giderken umut beklediğimiz güneşi de götür

Götür ki aydınlatmasın günü mü

Götür ki  bende görmeyeyim batışını.

							18-11-2000', 'Hadi sen de git bu gece Giderken umut beklediğimiz yıldızları da götür Götür ki ağlamasın arkandan Götür ki  bende görmeyeyim onları Yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dosta-ozlem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsene', 'gelsene-okay-yildiz-2bxq8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel bir şeyler söyle bana 

Suskun olma yeter ki

Fark etmez ne söyleyeceğin

Sesini duysam yeter 

Unutmasın sesini yüreğim

Kulaklarım çınlasın yeter 

Gel bir şeyler söyle bana

Yarim; suskun olma yeter ki

Gel bir şeyler söyle bana

Uzak olma yeter ki 

Fark etmez nasıl geleceğin

Yüzünü görsem yeter 

Unutmasın yüzünü yüreğim

Gözlerim görür olsun yeter

Gel bir şeyler söyle bana

Yarim; uzak olma yeter ki.

						02.12.2000', 'Gel bir şeyler söyle bana  Suskun olma yeter ki Fark etmez ne söyleyeceğin Sesini duysam yeter  Unutmasın sesini yüreğim Kulaklarım çınlasın...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelsene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-okay-yildiz-akk60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denize, 

gökyüzüne

ve ufkun alev rengine 

merhaba diyorum.

Gözlerim yıldızları tanımaya çalışırken

nankör ama tek arkadaşım yalnızlığımla

bir merhaba diyorum

damarlarıma giren üzüm suyuyla

tatlı anıların yüreğimde ki yer kapma kavgasıyla

sokaklar ihaneti haberdar eder gibi sessiz

ve ben sessizliğin verdiği korkuya

yüreğimde yer açmak isterken

bir merhaba diyorum.

Kır çiçeklerine, 

yıldızlara 

ve karanlığa diyorum; 

suskunlukla...

haykırışla...

özlemle...

bir merhaba...', 'Denize,  gökyüzüne ve ufkun alev rengine  merhaba diyorum. Gözlerim yıldızları tanımaya çalışırken nankör ama tek arkadaşım yalnızlığımla bi...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merhaba-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Parlıyor', 'yuregim-parliyor-okay-yildiz-s2zjw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim, 

Bugün Gibi.

Yüzlerce Kuşun Kanat Çırpışı Gibi; 

Coşkun. 

Güneş Gözümü Kamaştırıyor 

Sen Gibi.

Ama Bir Ayaz Var

Bakışların Gibi.

Acımasız.

Karanlıkta Aranıyorum

Çarparak Serin Duvarlarına

Düşerek Umutlarımın Çukurlarına

Varabilir miyim ki Işığına 

Varabilir miyim ki Gözlerine 

Karanlıkta Aranıyorum 

Gözlerini de Kaybetmişim

Kayboluyorum.

Yüreğim, 

Bugün Gibi 

Bir Papatya Gibi; 

Ak.

Güneş Gözümü Kamaştırıyor

Sen Gibi.

Ama Bir Ayaz Var 

Bakışların Gibi.

Anlamsız.

Tutulan Dilim

Bir Dinlese Yüreğimi 

Konuşur Sana

Bir Dinlesen Gözlerimi 

Anlatır Sana; 

Baharımı Anlatır.

Ulaşabilir miyim ki Sıcaklığına

Ulaşabilir miyim ki Yüreğine

Umutlarım Donuyor.

Gözlerini de Kaybetmişim

Donuyorum.

Yüreğim, 

Bugün Gibi.

Bulutların Arkasında ki Yıldız Gibi; 

Gizlice Parlıyor.

							14-12-2000', 'Yüreğim,  Bugün Gibi. Yüzlerce Kuşun Kanat Çırpışı Gibi;  Coşkun.  Güneş Gözümü Kamaştırıyor  Sen Gibi. Ama Bir Ayaz Var Bakışların Gibi. Ac...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yuregim-parliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kendini Anlat', 'bana-kendini-anlat-okay-yildiz-am812', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana kendini anlat

Bulutları

Maviliği

Ve yıldızları anlat.

Sonrada yağmurları anlat 

Yağmurlar senin için nedir bilmem 

Sadece üşüten su damlacıkları

Gökyüzünden inen yaşam mı 

Yoksa karabulutların gözyaşları mı.

Yağmurlar senin için nedir bilmem 

Bilmem yağmurlar nedir.

Bazen yağması için bulutları çağırırım

Seyretmek isterim doyasıya

Gözlerimi kapatıp sesiyle dans ederim.

Gözlerimi kapatıp yağan yağmura umutlarımı akıtırım.

Bilmem yağmurlar nedir

Çığlıklar atarım gökyüzüne 

Rüzgar olup dağıtmak isterim bulutları

Yağmasın yağmur

Bulut olmasın

Yıldızlar kaybolmasın diye

Sen kaybolma diye içten içe ağlarım

Bana kendini anlat

Dağları 

Ağaçları 

Ve papatyayı anlat

Sonrada düşlerini anlat

Hiç dağları düşlerinle süsledin mi

Düşlerini dağlara saldın mı

Sonsuzluğa salmaktır dağlara salmak.

Peki kaybettin mi onları 

Kaybettiğin düşleri saatlerce aradın mı

Bulmak zordur

Ya bir uçurumdan düşüyordur

Yada yamaçlara kadar yuvarlanıyordur

Ve defalarca çığlığını duydum düşlerimin

Bağırışını

Ve ölümünü seyrettim defalarca.

Papatyalar yapraklarını kapatırken geceleri

Derin bir uykuyla

Bir çocuğun sıcak ellerinde okşanıyormuş gibi  gülerek

Ve halen karanlık toprağa ışık verecek kadar beyazken

Yüreğimde bir düştü o.

Hiç papatyalarla düş kurdun mu

Hiç meyve çiçeklerini yüreğinde açtırdın mı 

Bana yüreğini anlat

Tanıyorsan eğer

Bana kendini anlat 

Saçlarını

Sesini

Ve gözlerini anlat

Sonrada umutlarını anlat

Umutların ne kadar fazla

En büyük umudun nedir

En güzel umudun nedir

Umutların hiç seni aldattı mı

Bana saçlarındaki o ışığı anlat

Bana gözlerindeki o parıldayışı 

Kim için parlıyor 

Ne için parlıyor

Bana kendini anlat

Sen kimsin

Bana yüreğinin sesiyle bir masal anlat

İçinde masal perisi olsun.

İçinde sen ol.

		  				15-01-2001', 'Bana kendini anlat Bulutları Maviliği Ve yıldızları anlat. Sonrada yağmurları anlat  Yağmurlar senin için nedir bilmem  Sadece üşüten su dam...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/bana-kendini-anlat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığın Rengi Var Mı?', 'karanligin-rengi-var-mi-okay-yildiz-n3i19', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“hadi çizsene şu kuytu köşenin resmini, 

 çizebilir misin.

 Bir rengi var mı? 

 Neyi anlatacaksın çizerken, biliyor musun? ”

Kaçışlardır hep aradığımızda kuytu köşeleri, ne zaman zora düşsek çekiliriz bir köşeye, kabulleniriz karşımızdakinin gücünü ve yenilgidir köşeler. Siner bir yere titreriz. Biri elini uzatsa da çıkarsa. O kadar zor ki geri çıkmak. Yavaş yavaş alışırsın orada yaşamaya. Zor gelmez artık. Ve her acı çektiğinde seni ilk teselli eden yer olacaktır o köşeler. İhtiyaç duyulan bir dost, hayatının bir parçası yani. Öyle bir yerleşir ki hayatına, herkeze ondan bahseder, onu anlatırsın. Aslında o acılardan kaçıştaki bir yerdir, karanlıkta umut arayışı ve sadece acılarla vardır. Ona her gittiğinde acılara gidersin. Bir kaçıştır o.

	Kaçıştı 

	İhtiyaç oldu

	Hayatımın bir parçasıydı.

	Kayboldu.

“hadi çizsene şu kuytu köşenin resmini

 çizebilir misin? 

 Karanlığın içinde umut arayışı gibidir.

 Çizebilir misin? 

 Karanlığın rengi var mı.

 O rengi çizebilir misin? ”

                                                              18-11-2002', '“hadi çizsene şu kuytu köşenin resmini,   çizebilir misin.  Bir rengi var mı?   Neyi anlatacaksın çizerken, biliyor musun? ” Kaçışlardır hep...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanligin-rengi-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Küfür', 'son-kufur-okay-yildiz-fyvvu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyu...

Bugün sende uyu, 

Ertelenmiş bir gülüşün gelişine dek 

Yazarım ama 

Anlaşılmaz bazen kelimeler

Kaçtığımı zannederim 

Küfrederken hayata

Umudu anlatırken 

Bilirim yıllar sonra okusam dahi 

Aynı küfürler gelecektir aklıma

Ne faydası var ölürken

Tanrı’ya yalvarmanın

Tadını çıkarmak ölümün

Sessizlikle

Ateş eşliğinde...

				29-10-2001', 'Uyu... Bugün sende uyu,  Ertelenmiş bir gülüşün gelişine dek  Yazarım ama  Anlaşılmaz bazen kelimeler Kaçtığımı zannederim  Küfrederken haya...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-kufur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-okay-yildiz-tq3ee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ilık bir esintiyle esiyor rüzgar

Ve savrulanlar

Üşümüyorlar ama sarsılıyorlar

Fark edince rüzgarı

Yıldızlar çoktan gitmiş oluyor geceden

Seyretmek ışıkları 

Karanlık tadında 

Hayallerin karasızlığıyla 

Ve sonsuzluğa ulaştırmak umutlarını

Geceden kaybolmuş yıldızların yerine koymak.

Ve beklemek 

Ilık bir esintiyle esiyorken rüzgar.

                           		16-10-01', 'Ilık bir esintiyle esiyor rüzgar Ve savrulanlar Üşümüyorlar ama sarsılıyorlar Fark edince rüzgarı Yıldızlar çoktan gitmiş oluyor geceden Sey...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekleyis-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-okay-yildiz-fm9sg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidiyorum 

Karanlık tadında bir sessizlik

Şahin gibi yalnızım gökyüzünde

Son isteğini düşünmüş mahkûm gibi

İçimdeki kavgayla hazırım ölüme de

Sevmeye de.		

					28-09-01', 'Gidiyorum  Karanlık tadında bir sessizlik Şahin gibi yalnızım gökyüzünde Son isteğini düşünmüş mahkûm gibi İçimdeki kavgayla hazırım ölüme d...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gidiyorum-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Hesaplaşma', 'son-hesaplasma-okay-yildiz-ekq9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce ağlardı her akşamdan sonra

Sessizliğin arkasından 

Korna seslerinin kesildiği 

Kedi tıkırtılarının sustuğu

Rüzgarın; 

Uyandırmaktan korkarcasına insanlığı 

Duvarlara sürünmeden giderek

Korkak bir gecenin başında.

Ve sonra hesaplardı

Yaşayacağı günlerin sayısını, 

Kaçında mutluluk

Kaçında acı çekeceğini.

Bazen karışırdı hesaplar

Ve mutluluk yerine acı çekerdi.

Zaten ayda yılda bir gelirdi mutluluğun sırası

Oda hep karışırdı.

Az sonra başlar başının ağrısı

İçme dedim şunu

İçerken hesaplaşma hayatla

Küfretme Tanrı’ya 

Yine aklından ölüm geçiyordur

Birgün yalnızlığında yakalanacak diye korkarım

Biliyorum acımaz hayata...

				26-09-01', 'Önce ağlardı her akşamdan sonra Sessizliğin arkasından  Korna seslerinin kesildiği  Kedi tıkırtılarının sustuğu Rüzgarın;  Uyandırmaktan kor...', ARRAY['Türk Edebiyatı','Şiir','Okay Yıldız']::text[], 8.5, '{"poet":"Okay Yıldız","poet_slug":"okay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-hesaplasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi Olmalı', 'birisi-olmali-hafize-zuluflu-k47bw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birisi mi var diye

Soruyorsun.

Hayır! ...

Evet! ....

Olmalı...

Olacak...

Şöyle yürekli, herkese bakmayan

Zor ulaşılır birisi.

Evet, evet var...

Öyle uğraştırıyor ki beni

Sevdiğini söylemiyor öyle kolay

Sevdiğinde ise

Sırf onun için, 

Ama sözde bahanelerle

Yaşadığı şehre gittiğimde, 

Ama birtürlü arayamadığımda bilinmez

Bir sebeple

Hesap soruyor, öfkeleniyor.

''Sana kızıyorum, gizli şeyler yapıyorsun''

Diyor.

Ben de

''Ne! ben mi gizli şeyler yapıyorum? 

Neyim gizli ki? 

Sadece sana gelen yolları arıyorum

Yollar gizli, kayboluyorum.

Sen zaten kayıpsın''

Diyorum...', 'Birisi mi var diye Soruyorsun. Hayır! ... Evet! .... Olmalı... Olacak... Şöyle yürekli, herkese bakmayan Zor ulaşılır birisi. Evet, evet var...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/birisi-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Giden Yoldayım', 'olume-giden-yoldayim-hakan-akyurt-q7btr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçerken günler durduramadan bizler, 

İstemesekte akıp geçmez mi zaman! 

Hatıralarla ve hatalarla doludur günler, 

Bakınca, anlamsız gelmez mi hayat! 

Ölüme gitmez mi her insan yalnız! 

O anda kaybolmaz mı tüm insanlar! 

Yanımızda dostlarımız olsa da her an, 

Gelebilir mi sanırsın sen, o insanlar! 

Ölüme giden yoldayım ben şimdi, 

Cansız bedenim upuzun yatarken yerde, 

Ayrılacak olsamda  tüm sevdiklerimden, 

O yolda yürümenin zamanıdır artık şimdi...', 'Geçerken günler durduramadan bizler,  İstemesekte akıp geçmez mi zaman!  Hatıralarla ve hatalarla doludur günler,  Bakınca, anlamsız gelmez ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olume-giden-yoldayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poyraz', 'poyraz-mustafa-ozke-cj3zh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Poyraza direnen böğürtlen yaprağım

Nasıl düşünce üzerine kar tanesi üşüyorsun

İşte ben de öyle üşüyorum

Kumruların sesiyle ısındığım oluyor

Sen kaçtıkça ben peşine düşüyorum

Yoruldukça koşuyorum

Köpürdükçe taşıyorum

Karıncalar bile uyanıp yolunu buluyor

Ben şaşıyorum

Yokluğun gelip bana seni soruyor ya

Hani bir yağmur damlası gibi

Toprak alıp seni koynuna koyuyor ya

O vakit

Ben öksüz kalıyorum...', 'Poyraza direnen böğürtlen yaprağım Nasıl düşünce üzerine kar tanesi üşüyorsun İşte ben de öyle üşüyorum Kumruların sesiyle ısındığım oluyor ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/poyraz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet...', 'davet-nazim-hikmet-ran-zi6rd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dörtnala gelip Uzak Asya''dan

Akdeniz''e bir kısrak başı gibi uzanan

bu memleket, bizim.

Bilekler kan içinde, dişler ken
..........
..........', 'Dörtnala gelip Uzak Asya''dan Akdeniz''e bir kısrak başı gibi uzanan bu memleket, bizim. Bilekler kan içinde, dişler ken .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/davet-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin Benim', 'sensin-benim-rainer-maria-rilke-s2crx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensin benim bulduğum bütün bu şeylerde, 

Bu sevgiyle, kardeşçe bağlandıklarımda; 

Tohum gibi güçlenirsin daracık yerde, 

Büyükteyse büyüksün, bakarım da.

İnanılmaz oyunu bu güçlerin işte, 

Öyle işlerler aktıkları yerde ki: 

Köklerde büyürken azalır gövdelerde

Ve dirilirler ağaç tepelerinde sanki.', 'Sensin benim bulduğum bütün bu şeylerde,  Bu sevgiyle, kardeşçe bağlandıklarımda;  Tohum gibi güçlenirsin daracık yerde,  Büyükteyse büyüksü...', ARRAY['Türk Edebiyatı','Şiir','Rainer Maria Rilke']::text[], 8.5, '{"poet":"Rainer Maria Rilke","poet_slug":"rainer-maria-rilke","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baştaki', 'bastaki-rainer-maria-rilke-njkdm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuz özdeyişlerden yükselirler

Sonlu eylemler zayıf çeşmeler gibi, 

Vaktinde ve titreyerek eğilirler.

Bizde her zaman sessiz duranlar oysa, 

Mutlu güçlerimiz, gösterirler

Kendilerini bu dans eden gözyaşlarında.', 'Sonsuz özdeyişlerden yükselirler Sonlu eylemler zayıf çeşmeler gibi,  Vaktinde ve titreyerek eğilirler. Bizde her zaman sessiz duranlar oysa...', ARRAY['Türk Edebiyatı','Şiir','Rainer Maria Rilke']::text[], 8.5, '{"poet":"Rainer Maria Rilke","poet_slug":"rainer-maria-rilke","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bastaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-sakir-askan-ycitr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kadeh kırıldı sarhoş gönlümde

Bir türlü kendimi avutamadım

Kaç gece ağladım böyle gizlice

Ne yaptımsa seni unutamadım

Kimbilir kimler var şimdi kalbinde

Sen beni unuttun çoktan belki de

Ben hala yaşarım eski günlerde

Her şeyde sen varsın, unutamadım

Her sevgi zamanla bitermiş derler

Benim ki bitmedi anlayamadım

Bu aşktan hayır yok, unut dediler

Ne yaptımsa seni unutamadım', 'Kaç kadeh kırıldı sarhoş gönlümde Bir türlü kendimi avutamadım Kaç gece ağladım böyle gizlice Ne yaptımsa seni unutamadım Kimbilir kimler va...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamadim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüne Düşüne', 'dusune-dusune-ali-tekinture-6pzpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşüne düşüne çıldıracağım

Gözümün önünden gitmiyorsun ki

Sensizliğe nasıl katlanacağım

Gözümün önünden gitmiyorsun ki

Kendin başka, aklın başka bir yerde

Sen nerelerdesin, ben nerelerde

Sensiz fırtınalar kopar içimde

Gözümün önünden gitmiyorsun ki

Herkes sevdiğiyle bir ben yalnızım

Sönmüş gökyüzünde sevda yıldızım

Sensin tek isteğim, sensin tek arzum

Gözümün önünden gitmiyorsun ki', 'Düşüne düşüne çıldıracağım Gözümün önünden gitmiyorsun ki Sensizliğe nasıl katlanacağım Gözümün önünden gitmiyorsun ki Kendin başka, aklın b...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusune-dusune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heves mi Kaldı', 'heves-mi-kaldi-askin-tuna-r47hk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aşkın alevini küle döndürdün

Yüreğimi yakacak ateş mi kaldı

Sende beni terkedip gittikten sonra

Yarınıma doğacak güneş mi kaldı

Güzel derlerdi çocukken aşka

Sanki uçarmış tutulan aşka

Anlatılanlar başka, yaşanan başka

Bir daha sevmek için heves mi kaldı

O eski hatıralar rahat bırakmaz

Hiç bitmeyen hasretin aklımdan çıkmaz

Anladım ki bir tanem sensiz yaşanmaz

Huzurla aldığım nefes mi kaldı', 'Bu aşkın alevini küle döndürdün Yüreğimi yakacak ateş mi kaldı Sende beni terkedip gittikten sonra Yarınıma doğacak güneş mi kaldı Güzel der...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/heves-mi-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Bizi Affet', 'i-stanbul-bizi-affet-selma-cuhaci-72puw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul bizi affet ne olur

Biz ettik sen eyleme

İlk aşkım, ilk göz ağrım

Geri dön düşlerime

Seni sevmek uğruna 

Yok ettil keyfimizce

Bilmedik kıymetini

Umarsız, bilgisizce

Yitirmiş eski şenliğini

Yangınlar yüreğimde

Rüzgarlar bile esmer olmuş

Yorulmuş Yeditepe

İstanbul bizi affet ne olur

Biz ettik sen eyleme

Kahrettin bizi ah İstanbul

Neydin, ne oldun böyle

Bir güzel şehir vardı

Eskiyen resimlerde

Kirlettik nefesini

Göz koyduk yeşiline

Sahipsiz artık dar sokaklar

Toz duman gül yüzünde

Yağmurlar bile yağmaz olmuş

Yorulmuş Yeditepe

İstanbul bizi affet ne olur

Biz ettik sen eyleme

Dayanmak kolay değil artık

Ne hale geldin böyle

İstanbul bizi affet ne olur

Biz ettik sen eyleme

Kaybolan yaşamlardan

Şarkılar kaldı bize

Ne bir dost eli, ne bir selam

O bildik yüzler nerede

Sevdalar bile unutulmuş

Yorulmuş Yeditepe', 'İstanbul bizi affet ne olur Biz ettik sen eyleme İlk aşkım, ilk göz ağrım Geri dön düşlerime Seni sevmek uğruna  Yok ettil keyfimizce Bilmed...', ARRAY['Türk Edebiyatı','Şiir','Selma Çuhacı']::text[], 8.5, '{"poet":"Selma Çuhacı","poet_slug":"selma-cuhaci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/istanbul-bizi-affet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Aşkın Yeri Yok', 'gercek-askin-yeri-yok-halit-celikoglu-ofzp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç kimsede gerçek aşkın yeri yok

Kimi görsem, kime sorsam derdi çok

Bu hayatta bize göre sevgi yok

Vazgeç gönül sen bu tatlı sevdadan

Zor bulursun şu dünyada ben gibi

Sevdi sanar kaptırırsın kalbini

Bir gün olur naza çeker kendini

Vazgeç gönül sen bu tatlı sevdadan

Kime teslim edersin şu canımı

Kanatırlar sonra gönül yaramı

Ateş sarar benim dört bir yanımı

Vazgeç gönül sen bu tatlı sevdadan', 'Hiç kimsede gerçek aşkın yeri yok Kimi görsem, kime sorsam derdi çok Bu hayatta bize göre sevgi yok Vazgeç gönül sen bu tatlı sevdadan Zor b...', ARRAY['Türk Edebiyatı','Şiir','Halit Çelikoğlu']::text[], 8.5, '{"poet":"Halit Çelikoğlu","poet_slug":"halit-celikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-askin-yeri-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözemedin', 'cozemedin-aysel-gurel-5mqdo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce rüzgarla konuş

Sonra yağmurla ağla

Sen görmeden gideceğim

Geriye dönmem asla

Sence ayrılık kolay

Yalnız kal, bak göreceksin

Ben hatıraları aldım

Neyinle övüneceksin

Beni seven bir kadın var 

Deme artık inanmazlar

İçimde ki düğümleri

Çözemedin kalsın onlar', 'Önce rüzgarla konuş Sonra yağmurla ağla Sen görmeden gideceğim Geriye dönmem asla Sence ayrılık kolay Yalnız kal, bak göreceksin Ben hatıral...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cozemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Alona', 'adi-alona-kemal-diler-as56i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'global dünyanın özgür ülkesi

özgürlüğün anlamını yitirdiği

gencecik bedenlerin

şehvet uğruna satıldığı

demir perde kalıntısı

global dünyanın özgür ülkesi...

            ***

kapital ekonomi

sat ve kazan

ne olursa sat

gerekirse bedenin dahil 

sat ve kazan

değerlerin hiçe sayıldığı

global dünyanın özgür ülkesi...

             ***

kara kaşlı

kara bıyıklı

esmer adam

bir gece vakti karanlığında

ayakları yalpalıyordu

rakı yoktu sarhoşluğunda

votka-bira karışımı bir mahmurluk

kar beyazı sokakları arşınlarken evinin yolunda

irkildi ansızın ardındaki seste...

          ***

hoçiş devuşka? 

-kız ister misin-meali 

duraksadı bir an

kimbilir ne şeytanlıklar depreşti yüreğinde

şehvete dair

nerede diye yutkundu 

sto (yüz)    dolar dedi aynı ses

peki nerede diye tekrarladı esmer adam

davay-haydi- dedi

atla arabaya...

geldiler kar beyazı gece karanlığında

şehrin dışındaki bir sokağa

uzunları yaktı kazak adam

yerde kar var

eksi bilmem kaç ısı

uzunların ardında dört kız yarı çıplak

biri sarışın

mavi gözlü

diğeri kızıl 

mahzun bakışlı

kalan ikisi çekik gözlü

belli ki ya kazak

ya tatar

kimbilir belki de uygur

uzunların ardındaki görüntüde

ikinci kız dedi esmer adam

kızıl saçlı olan

ve bindiler arabaya beraber

kalanlar kayboldu

kar beyazı gece karanlığında

başka bedenlere satılıncaya değin...

            ***

döndüler şehrin ışıklı sokaklarına 

durdular lenina caddesindeki evinin önünde esmer adamın

girdiler içeri

meçhul kimlikler...

            ***

meçhul kimlikler dedim

titriyordu kızıl saçlı kız

ya çok beklemişti kar beyazı gecede

ya da korkuyordu olacaklardan...

              ***

esmer adam yaktı ışıkları

kızıl saçlı kız soyunmaya başladı

sorgusuz sualsiz

belli ki biliyordu 

neden geldiğini...

             ***

kara kaşlı 

kara bıyıklı 

esmer adam

kaldırdı kafasını sarhoşluğunun ötesinde

ilk kez alıcı gözle baktı kızıl saçlı kıza

aman tanrım dedi bir an

bu bir çocuk daha...

           ***

adın ne diye sordu

Alona dedi kızıl saçlı kız

kaç yaşındasın sen diye ekledi

esmer adam

onsekiz dedi 

içindeki ürkeklik

ve çıplak vücudunda başka bedenlerin morluklarını kapatarak

başı öne eğik

hayır dedi esmer adam

bana doğruyu söyle

işte o an yüreğini ters çevirdi kızıl saçlı kız

gözlerinde bir kaç damla yaş belirdi

korkuyla karışık 

onbeş dedi...

              ***

kendi kızı düştü aklına

kızıl saçlı değildi belki ama

aynı yaş 

ve henüz okul çağında

bir çocuktu daha...

             ***

bir çocuktu daha

annesi hasta-yatalak

babası alkolik

zordu aslında rusyada kadın olmak

hele çocuk olmak! 

hayalleri vardı

doktor olacaktı büyüyünce

yatalak annesini tedavi edecekti

kaybolmazsa karanlık gecelerin derin bataklığında...

               ***

şehvetin ötesinde kalktı ayağa esmer adam

kaç para kazanıyorsun bu işten dedi 

yirmi dolar dedi çocuk-kız

oysa hatırladı 

yüz dolar ödediğini

ve giyin dedi

şaşırdı kızıl saçlı çocuk-kız

giyin dedi yeniden

başka bedenlerin bıraktığı morlukları gizlercesine

giyindi kızıl saçlı çocuk-kız

ve kayboldu gecenin kar beyaz karanlığında

başka bedenlere yem olmaya değin

global dünyanın özgür ülkesinde! ...

17 Kasım 1995', 'global dünyanın özgür ülkesi özgürlüğün anlamını yitirdiği gencecik bedenlerin şehvet uğruna satıldığı demir perde kalıntısı global dünyanın...', ARRAY['Türk Edebiyatı','Şiir','Kemal Diler']::text[], 8.5, '{"poet":"Kemal Diler","poet_slug":"kemal-diler","theme":"Türk Şiiri","is_hero":false,"total_lines":126,"source_url":"https://www.antoloji.com/adi-alona-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-bilal-i-lkin-jxi6d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut

Yalnızım geceler boyu, 

Hasretim içime doldu, 

Sevdam aldı kalbimi, 

Dağlara yürü dinlemedi beni.

Umudum sabaha doğru, 

İçime huzur doldu, 

Bir melek aldı kalbimi, 

Dağlara yürüdü dinlemedi beni.

Umudum yalnızlığı boğdu, 

Sevda kuşunu uçurdu, 

Bir güzel aldı kalbimi, 

Dağlara yürüdü dinlemedi beni.', 'Umut Yalnızım geceler boyu,  Hasretim içime doldu,  Sevdam aldı kalbimi,  Dağlara yürü dinlemedi beni. Umudum sabaha doğru,  İçime huzur dol...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlkin']::text[], 8.5, '{"poet":"Bilal İlkin","poet_slug":"bilal-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendin', 'sendin-mavi-kalem-b17u4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sendin gökkuşağındaki yedinci renk

Sendin denizdeki uçsuz bucaksız mavilik

Sendin içimdeki ateş, yüreğimdeki sızı

Ve sana karşı koyulmaz hasretlikti gönlümde olan

Masallarda adı geçen güzel sendin

Kafdağındaki zümrütü anka kuşu gibi

Bana benden yakın, bana benden uzak olan

Akşamları gökyüzümdeki yıldız sendin

Sendin kaderimdeki yalnızlık

Şiirimdeki kadın sendin

İçtiğim kadehdeki şarap

Gördüğüm rüya sendin

Söylediğim şarkı olan sendin

Sigaramda duman duman

Yüreğime umut olan sendin

Sendin bitmez, tükenmez

Her fırsatta boğazımda düğümlenen sendin

Batan güneş sendin

Kalem tutan ellerim

Kulağımda çınlayan

Yazmaya çalıştığım şiir sendin

Yalnız akşamlarda üstüme çöken

Düşlerken kaybolup gittiğim sendin

Her bir gecede binlerce kere öldüren beni

Yağmur yağarken yüzüme düşen sendin

Aynaya baktığımda gördüğüm

Gören gözlerim sendin

Umudamda sendin, umutsuzluğumda

Yanlızlığımda sendin, yalınsızlığımda sen', 'Sendin gökkuşağındaki yedinci renk Sendin denizdeki uçsuz bucaksız mavilik Sendin içimdeki ateş, yüreğimdeki sızı Ve sana karşı koyulmaz has...', ARRAY['Türk Edebiyatı','Şiir','Mavi Kalem']::text[], 8.5, '{"poet":"Mavi Kalem","poet_slug":"mavi-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sendin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken Biraz Daha Ölüyorum Ben', 'sen-yokken-biraz-daha-oluyorum-ben-mavi-kalem-9osx5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yokken biraz daha ölüyorum ben

Gönlüm sonbahar, yaprak yaprak dökülüyor

Her mevsim kış, hergünüm gece

Sonu yok yolların, yarını yok saatlerin

Ve ben biraz daha ölüyorum sensizliğin ortasında

Kokusu yok çiçeklerin, gök kuşağının rengi yok

Ateşi yok sevmelerin, sigaramın dumanı yok

Gözlerin her yerde, ne yana baksam gözlerin

Ve ben biraz daha ölüyorum gözlerinin ortasında

Alevi yok yangınların, suyu olmadığı gibi yağmurun

Denizin mavisi yok, tıpkı gözlerin gibi

Gözlerin her yerde, ne yana baksam gözlerin

Ve ben biraz daha ölüyorum sensizliğin ortasında

Dostu yok gecelerin, geceler çok uzun

Geceler bir ömür, ömür dediğin bir tutam ümit

Ümidi yok yarınların, 

Tıpkı senin yokluğun gibi

Ve ben biraz daha sana hasret

Hasret bir ip boğazıma düğümlenmiş

Düğümler her tarafımda, bütün yollar kör düğüm

Ve ben biraz daha ölüyorum sensizliğin ortasında

Yalnızlığını ben yazarım şiirlerin, ayrılığını ben

Karamsarlıkları hep senden

Hayalinle süslenen bu şehir

Ve ben ölüyorum bu şehirde sensizlik ortasında', 'Sen yokken biraz daha ölüyorum ben Gönlüm sonbahar, yaprak yaprak dökülüyor Her mevsim kış, hergünüm gece Sonu yok yolların, yarını yok saat...', ARRAY['Türk Edebiyatı','Şiir','Mavi Kalem']::text[], 8.5, '{"poet":"Mavi Kalem","poet_slug":"mavi-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-yokken-biraz-daha-oluyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lütuf', 'lutuf-bilal-i-lkin-ep3ro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül bahçesinde hüzün varmış.

Ümidini yitirmiş bir gül varmış.

Lütufta bulunmuş bahçıvan.

Gülün başını göğe kaldırmış.

İçinde ısınmış gülün o an

Neden sonra kalbinde umut varmış.', 'Gül bahçesinde hüzün varmış. Ümidini yitirmiş bir gül varmış. Lütufta bulunmuş bahçıvan. Gülün başını göğe kaldırmış. İçinde ısınmış gülün o...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlkin']::text[], 8.5, '{"poet":"Bilal İlkin","poet_slug":"bilal-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/lutuf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ölürsem bir akşam ölürüm', 'ben-olursem-bir-aksam-olurum-mavi-kalem-5lgn6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ölürsem bir akşam ölürüm

Mevsimlerden yaz, aylardan temmuz

Bir akşamın alaca karanlığında

Hasretin bir ip gibi boynuma dolandığında ölürüm

Ben ölürsem bir akşam ölürüm

Mavi gecede hayalin belirirse gözlerimde

Esen rüzgarla saçlarında savrulurum

Kokunu rüzgardan alırda ölürüm

Ben ölürsem bir akşam ölürüm

Hafifce çiseleyen yağmur olurum bir gece vakti

Tenine düşer, düştüğüm tende eririm

Yağan yağmurla sevgi olurum sana öyle ölürüm

Ben ölürsem bir akşam ölürüm

Yakamoz olurum kıyılarında

Her sahile vurduğumda ismini söylediğim

Dalga olur, deniz olur, fırtına olur ölürüm

Ben ölürsem bir akşam ölürüm

Bir öpücük olurum yanaklarına

Gecenin en kuytu saatlerinde

Sabah vakti gül yaprağına konan

İki damla çiğ taneside olurda yapraklarında ölürüm

Özlem olur, özgürlük olurum gökyüzüne

Kağıdına kalem, şiirine satır olurum

Kalem tutan ellerine gece yarısı bir ilham

İlhamına kor bir ateş olurda

Senin gözlerinde ölürüm', 'Ben ölürsem bir akşam ölürüm Mevsimlerden yaz, aylardan temmuz Bir akşamın alaca karanlığında Hasretin bir ip gibi boynuma dolandığında ölür...', ARRAY['Türk Edebiyatı','Şiir','Mavi Kalem']::text[], 8.5, '{"poet":"Mavi Kalem","poet_slug":"mavi-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-olursem-bir-aksam-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan İstanbul', 'uyan-i-stanbul-hakki-hakan-kaya-3141v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarihin bir bir yağmalanıyor, 

Kanıma dokunuyor, uyan İstanbul.

Sokakların, meydanların yozlaşıyor, 

Canına okunuyor, uyan İstanbul.

Çamlıcası, Heybelisi, Ayasofyası, 

Nerde kaldı paytonla ada sefası, 

Düşündükçe dert oluyor içime cefası, 

Sırların dökülüyor, uyan İstanbul.

Gece sokakta bekçilerin olurdu, 

Uzaktan külhanların naraları duyulurdu, 

Hak, hukuk, adalet kadılardan sorulurdu, 

Yüreğin sökülüyor, uyan İstanbul.

Komşunun komşuya saygısı vardı, 

Avamın ulemaya saygısı vardı, 

Hainde bile Allah kaygısı vardı, 

Ecelin yazılıyor, uyan İstanbul.

Fazla söz söylemeye ne hacet, 

Döndü cehenneme iken cennet, 

Ne sabır kaldı nede selamet, 

Mezarın kazılıyor, uyan İstanbul.', 'Tarihin bir bir yağmalanıyor,  Kanıma dokunuyor, uyan İstanbul. Sokakların, meydanların yozlaşıyor,  Canına okunuyor, uyan İstanbul. Çamlıca...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyan-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemi İçimde Taşırım', 'alemi-i-cimde-tasirim-cahit-i-pekoglu-708ba', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm alemi ben içimde taşımışiım

taşımışım''da gerçeği yaşayamamışım.

Hep tek gerçeğim derdim

sana hatırlarmısın.

İnan çok yanılmışım

sende içimdeki alemden bir parçaymışsın.

Nasılda böylesine aldanmışım

ölürcesine severken, seviliyorum sanmışım..

Artık bahanelerin diz boyu

birde bunlara yalan eklendi.

Sonsuzluğum dediğin bana

gözlerimdeki ifadenin değiştiğide söylendi.

Sen görmek istediğini 

görmek istiyordun gözlerimde meleğim.

İnan çok yanılmışın sende

ben sadece içindeki alemden bir parçaymışım..', 'Tüm alemi ben içimde taşımışiım taşımışım''da gerçeği yaşayamamışım. Hep tek gerçeğim derdim sana hatırlarmısın. İnan çok yanılmışım sende iç...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alemi-icimde-tasirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim İçin Ağlıyor', 'bizim-i-cin-agliyor-cahit-i-pekoglu-gkv5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle olduğum tüm yerler

artık seni tanıyor.

Onca sevgi yaşanan yerler 

bizsizliği hiç hak etmedi.

Aşk buysa

yüreğim aşık olduğu için utanıyor..

Ne yaparsan yap

yaşıyorum zannedecek, hep yannız kalacaksın.

Öptüğüm dudakların, kuruyacak

kaybolmuşluk içinde yaşayacak tutsaklığı..

Her akşamın temiz karanlığını

yaşardın meleğim.

Şimdilerde çok değişmişsin

değil akşamların, kirlenmiş tüm sabahların.

Senile olduğum tüm yerler

artık bizim için ağlıyor...', 'Seninle olduğum tüm yerler artık seni tanıyor. Onca sevgi yaşanan yerler  bizsizliği hiç hak etmedi. Aşk buysa yüreğim aşık olduğu için utan...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizim-icin-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilimin Türküsü', 'sevgilimin-turkusu-gulsum-kevser-i-nce-1kahq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir anamın kokusu çeker beni

Bir de senin

Beklersiniz gelmemi

İki ayrı yol, iki ayrı sevda

Düşmüşte kor gibi yüreğime

Ne gel dersiniz, ne git dersiniz.

Aynı değil elbet

Köyümün bir tas soğuk suyu

Ve senin gülümseyen gözlerin

Hadi artık biriniz öldürün beni

Ya köyümün soğuk suyuna

Ya da senin gözlerine gömüleyim

Bir anamın, bir de senin sesin

Çınlar kulaklarımda

Geldiğin zaman dersiniz, 

Nasıl geldiğimi bilmezsiniz

Gittiğin zaman dersiniz

Nasıl gittiğimi bilmezsiniz

Kolay olanı siz yapar

Zor olanı bana bırakırsınız.

Çekip gitmek mi, çekip kalmak mı? 

Hangisi? 

Hadi artık öldürün beni

Onun gülümseyen gözlerinde

Sonra da o soğuk suyla yıkayın..', 'Bir anamın kokusu çeker beni Bir de senin Beklersiniz gelmemi İki ayrı yol, iki ayrı sevda Düşmüşte kor gibi yüreğime Ne gel dersiniz, ne gi...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgilimin-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkim', 'i-lkim-gulsum-kevser-i-nce-icomc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün sevdiklerim, 

Yavaş yavaş terkediyorlar beni

Yapraklarını kaybetmiş bir ağaç gibiyim

Çırılçıplak ve yalnız 

Ama ayaktayım herşeye rağmen

Bekleyeceğim, 

İlkbaharı ve yeni yaprakları

Daha yeşil daha taze olacaklar belki

Ama ilkinin tadını veremeyecekler bana...', 'Bütün sevdiklerim,  Yavaş yavaş terkediyorlar beni Yapraklarını kaybetmiş bir ağaç gibiyim Çırılçıplak ve yalnız  Ama ayaktayım herşeye rağm...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilkim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-gulsum-kevser-i-nce-f4afk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen değilsin içimdeki

Senden öte birşey

Senin adını vermişim sadece ben ona

Buna layıkmısın bilmiyorum

Seni her silip atışımda

Yine seninle teselli buluyorum

Sahte sevgilerle her yıkılışımda

Yine sana dönüyorum

Ve galiba ben seni değil

Sensizliği seviyorum...', 'Sen değilsin içimdeki Senden öte birşey Senin adını vermişim sadece ben ona Buna layıkmısın bilmiyorum Seni her silip atışımda Yine seninle ...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizlik-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-gulsum-kevser-i-nce-bccvu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiçbir zaman beklediğinin olmaması

Ve her zaman birşeyler vermeye çalışmak

Hiç anlaşılamamak

Ve her zaman anlamaya çalışmak

Ve bütün beklentileri

Bir tebessüme, bir teşekküre sığdırmak

Sanırım dostluğun gerekçesi

Ve tanımı bu...', 'Hiçbir zaman beklediğinin olmaması Ve her zaman birşeyler vermeye çalışmak Hiç anlaşılamamak Ve her zaman anlamaya çalışmak Ve bütün beklent...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tebessum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elmanın Yarısı', 'elmanin-yarisi-gulsum-kevser-i-nce-gr6zr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice nice acıları getirdin aklıma

Onca yoksulluğu getirdin

Gözyaşlarını, geceyarılarını, söylediklerini

Yaktığımız ateşi getirdin koydun yüreğime

Sığdıramadım yüreğime ateşi

Taştı doldu odam

Yenildim onun büyüklüğüne

Yenildim tanımadığım seslere, yitirdiklerime

Topladım ateşi onca büyüklüğüne rağmen

Aldığımız yere, yaktığımız yere koydum

İkimiz dedin, yürürüz ateşe

Elele versek yeneriz dedin güçsüzlüğü

Büyük işler yapabiliriz dedin.

Dün kadar uzak, yarın kadar yakınındayım

Ve dününde, bugününde, yarınında

Herşeye rağmen, hep yanındayım...', 'Nice nice acıları getirdin aklıma Onca yoksulluğu getirdin Gözyaşlarını, geceyarılarını, söylediklerini Yaktığımız ateşi getirdin koydun yür...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elmanin-yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğinde', 'gittiginde-gulsum-kevser-i-nce-dw3h9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün bir sayfa daha kapandı hayatımdan

Uçup giden yaprak gibiydin rüzgarda

Artık sana bu gözlerle başka türlü bakamam

Konuşamaz seninle eskisi gibi bu dudaklar

Gülümseyemem, bekleyemem seni artık

Korktuğum, kaçtığım gerçeklerimdin

Beklentilerimdin

Artık bittin benim için

Bitirdin beni..

Bulduğum yerde değil, 

Aradığım yerde yitirdim seni

Kozahan’ın duvarları üstüme geliyor

Küçük parkın ağaçları boş gözlerle bakıyorlar 

Utanıyorum onlardan, kendimden

Kandırdım, duvarları, ağaçları, kendimi

Kandırdın beni..

Ama pişman değilim

Bir adım daha öndeyim hayat kavgasında

Ve birgün geriye dönüp baktığımda

Eski bir yara gibi

Kanayacaksın içimde

Ve beni bir daha kandıramayacaklar

İsteselerde

İstemeselerde...', 'Dün bir sayfa daha kapandı hayatımdan Uçup giden yaprak gibiydin rüzgarda Artık sana bu gözlerle başka türlü bakamam Konuşamaz seninle eskis...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittiginde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geride Kalan', 'geride-kalan-levent-serkan-ozdogan-53b1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şehir hep susardı, 

Karanlık tenine düştüğüm zaman.

Ben susardım, 

Kuşlar susardı.

Hep benim oldu sanırdım, 

Takvimlerden düştü zaman.

Ben tükendim, 

Sen yoksun, 

Geride kuşlar kaldı...', 'Bir şehir hep susardı,  Karanlık tenine düştüğüm zaman. Ben susardım,  Kuşlar susardı. Hep benim oldu sanırdım,  Takvimlerden düştü zaman. B...', ARRAY['Türk Edebiyatı','Şiir','Levent Serkan Özdoğan']::text[], 8.5, '{"poet":"Levent Serkan Özdoğan","poet_slug":"levent-serkan-ozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geride-kalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pastırma Yazı', 'pastirma-yazi-yilmaz-erdogan-e17dp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'böyle zamansız güneşli, 

umulmadık mavi günlerde 

bir bekleme salonu yalnızlığına 

bürünüyorum.. 

iliklerimdeki yitik aşkı 

sarhoş bir unutkanlığa ilikliyorum... 

sanki şiirini bilmediğim 

bir fransız akşamında 

kaldırım taşlarını sayıyorum kalbimin.. 

içimde ayak izlerin, 

aylak bir yaz geçiyor avuçlarımdan... 

ve ben ne zaman, 

kiminle sevişsem, 

hâlâ seni aldatıyorum!', 'böyle zamansız güneşli,  umulmadık mavi günlerde  bir bekleme salonu yalnızlığına  bürünüyorum..  iliklerimdeki yitik aşkı  sarhoş bir unutk...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pastirma-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Daha', 'bir-gun-daha-sota-papaladze-9jppt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırgün daha, 

Birgündaha bekliyemedin suskunluğumu

Darılıp çekip gitmeseydin, 

Bir kenara itmeseydin

Ve terketmeseydin...

Birgündaha bekleyebilseydim suskunluğumu.

Bu birgün engel olmuşsa seninle bana

Lanet olsun bu bir günlük zamana.

O kadarını bekleyip

Bu kadarını bekleyemedin ya.

Oncalık benim küskünlüğümü

Birgündaha bekleyemedin suskunluğumu...

               Sohta Popoladze

               29/09/1999   lada', 'Bırgün daha,  Birgündaha bekliyemedin suskunluğumu Darılıp çekip gitmeseydin,  Bir kenara itmeseydin Ve terketmeseydin... Birgündaha bekleye...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-gun-daha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zakkum Çiçekleri', 'zakkum-cicekleri-hulya-senkul-0bvye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş yakmıyor hasretin kadar

Sahilde dalga gönlümde sen var

Gülmüyor yüzüm, her yanım hüzün

Tadı yok yazın eskisi kadar

Pembe ve beyaz, mahsunca biraz

Açılmış bu yaz  zakkum çiçekleri

Mehtap ve deniz, sensiz ve kimsesiz

Ağlıyor sessiz  zakkum çiçekleri

Hep aynı yerde yine o sandal

Akşam oldu mu yanıyor mangal

Seni özlüyor bütün fasıllar

Tadı yok yazın eskisi kadar', 'Güneş yakmıyor hasretin kadar Sahilde dalga gönlümde sen var Gülmüyor yüzüm, her yanım hüzün Tadı yok yazın eskisi kadar Pembe ve beyaz, mah...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zakkum-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Düştüğü Yeri Yakar', 'ask-dustugu-yeri-yakar-ali-tekinture-lejeo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılıktan acısı yok

Özlemenin sancısı çok

Bir sabah uyandığında

Bakarsın ki sevdiğin yok

Seviyordu sevmez olmuş

Yüreğine bir hal olmuş

Vefasızlık, hayırsızlık

Dedikleri demek buymuş

Aşk düştüğü yeri yakar

Depremler misali yıkar

Alabora olur her şey

Bu savaştan kim sağ çıkar

Bir düşte gör yangınlara

Bir düşte gör sevdalara

Ölüm Allah''ın emri

Bir çare yok ayrılığa', 'Ayrılıktan acısı yok Özlemenin sancısı çok Bir sabah uyandığında Bakarsın ki sevdiğin yok Seviyordu sevmez olmuş Yüreğine bir hal olmuş Vefa...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-dustugu-yeri-yakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedense', 'nedense-hamza-dekeli-4wc1p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün kadar kısa sürdü gençliğim

Zamanı yerinde durduramadım

Birbirinden beter geçti günlerim

Nedense gülmeyi başaramadım

Bilmiyorum neden, neden böyleyim

Bir türlü suçumu anlayamadım

Ömrümce hiç yoktan hep acı çektim

Nedense huzurlu yaşayamadım

Tükenmek bilmedi çaresizliğim

Aşk denen illetten kurtulamadım

Hep içimde saklı kaldı dertlerim

Nedense kimseye açılamadım', 'Bir gün kadar kısa sürdü gençliğim Zamanı yerinde durduramadım Birbirinden beter geçti günlerim Nedense gülmeyi başaramadım Bilmiyorum neden...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nedense-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkçe', 'turkce-ahmet-kurt-kfu8t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir gibi, şarkı gibi, 

Türküm Türkçe konuşurum.

Şırıl şırıl sular gibi, 

Türküm Türkçe konuşurum.

Oğlum, kızım beni anlar, 

Kulak verip sözüm dinler, 

Ağarır kararan günler, 

Türküm Türkçe konuşurum.

İlim yapar yavrularım, 

Çiçek açar avlularım, 

Dilsiz olsam ben neylerim, 

Türküm Türkçe konuşurum.

Dedem, babam, anam atam, 

Süslediler dilim tamam, 

Olmadıysa dediler ham, 

Türküm Türkçe konuşurum.

Duydum sesi içim yandı, 

İçtim suyu gönlüm kandı, 

O büyük atamın  andı, 

Türküm Türkçe konuşurum.

Yalvarırım hece hece, 

Şükrederim, gündüz gece, 

Hep bir esrarlı bilmece

Türküm Türkçe konuşurum.

Yağlı değil yavan değil, 

Bir kuru baş soğan değil, 

Var beyine kendin eğil, 

Türküm Türkçe konuşurum.

Kurdoğluyum beynim, ruhum, 

Hissederim bundan coşkum, 

Bu sevdayla bitmez aşkım, 

Türküm Türkçe konuşurum.', 'Şiir gibi, şarkı gibi,  Türküm Türkçe konuşurum. Şırıl şırıl sular gibi,  Türküm Türkçe konuşurum. Oğlum, kızım beni anlar,  Kulak verip söz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/turkce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetini Bilmedim', 'kiymetini-bilmedim-mehmet-fatin-baki-7jy1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar mutlydum pederimle yan yana

Kıymetini bilmedim, babam gitti kayboldu 

Ninem okuttu beni, eğitim verdi  bana

Kıymetini bilmedim, anam gitti kayboldu

Dünyanın dört yönünde insanlarla tanıştım

Kıymetini bilmedim, yoldaş gitti kayboldu.

Beş ah-lıebeveynle kah küstüm kah  barıştım

Kıymetini bilmedim, kardaş gitti kayboldu.

Dost oldum, dost edindim, dostça şem’alar yaktım

Kıymetini bilmedim,  yarân gitti kayboldu.

Gurbette göz ucuyla bezm-i hubana baktım

Kıymetini bilmedim,  canân gitti kayboldu.

Allâh verdikçe verdi, servet kesemi deldi

Kıymetini bilmedim, fırsat gitti kayboldu.

Mefaki  artık uyan, aklın başına geldi

Kıymetini bilmedim, sıhhat gitti kayboldu.

Ah-lıebeveyn = ana-baba bir kardeş

Şem’a = mumlu fitil

Bezm-i huban = güzeller  meclisi', 'Bir zamanlar mutlydum pederimle yan yana Kıymetini bilmedim, babam gitti kayboldu  Ninem okuttu beni, eğitim verdi  bana Kıymetini bilmedim,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kiymetini-bilmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Dediler', 'bekle-dediler-mehmet-fatin-baki-lvbzi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldızlara sordum sevgilimi ben buradan

Ay yüzlü güzel “Şimdi gelir, bekle” dediler

Günler gibi, aylar, seneler geçti aradan

Ay yüzlü güzel “Şimdi gelir, bekle” dediler

Ferhat gibi dağı delmek yok ki hevesimde

Mecnundaki titrek o seda yok ki sesimde

Duydum, yine dydum son ümit son  nefesimde

Ay yüzlü güzel “Şimdi gelir, bekle “ dediler

Mefaki kırk-yedi yıl önce köyünden göçtü

Şehrini terketti diyar-ı gurbeti seçti

Kamerru kızı  bulmak için  fezayı  geçti

Ay yüzlü güzel “Şimdi gelir, bekle.” dediler

Kamerru = ay yüzlü', 'Yıldızlara sordum sevgilimi ben buradan Ay yüzlü güzel “Şimdi gelir, bekle” dediler Günler gibi, aylar, seneler geçti aradan Ay yüzlü güzel ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekle-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyguların Kıpırdanışı', 'duygularin-kipirdanisi-hakan-rodop-1z61r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne varsa

aşka ilişkin

dün gece

fısıldadım

kulağına

ve senden hiç bir şey kıpırdamadı

boğazım düğümlendi o an

daha neler, neler vardı söyleyecek

ayrılık, 

ölüm, 

hüzün, 

bunların hepsi hepsi yalan

gerçek burada, işte burada

dilimin tam ucunda

uyandığında söylenecek

belki de düşlerinin arasında

sevgilim! 

eğer uyandığında şafaksa

aynaya bak

‘ seni tüm varlığımla seviyorum’

yazısı, 

silinmemiştir daha.', 'Ne varsa aşka ilişkin dün gece fısıldadım kulağına ve senden hiç bir şey kıpırdamadı boğazım düğümlendi o an daha neler, neler vardı söyleye...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/duygularin-kipirdanisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimizle', 'duslerimizle-hakan-rodop-9oqgb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dündü, 

           düşlerimizle birlikte

           gömüldü toprağa

           aydınlığını bıraktı

bugün, 

           yaşayarak bizimle

yarın, 

         düşlerimizle birlikte

         uzanacak gökyüzüne', 'dündü,             düşlerimizle birlikte            gömüldü toprağa            aydınlığını bıraktı bugün,             yaşayarak bizimle yarı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duslerimizle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimiz', 'ellerimiz-hakan-rodop-15ebr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerimiz birleşti, 

kopkoyu karanlıkta

yıldızlı bir koyda

ellerin ellerimdeydi hala

sabah olduğunda

gözlerin gözlerimde

dudakların dudaklarımda

ellerimiz ayrıldı, 

gecede kopkoyuluğunda

yıldızlı bir koyda

seviyorumların sonunda.', 'Ellerimiz birleşti,  kopkoyu karanlıkta yıldızlı bir koyda ellerin ellerimdeydi hala sabah olduğunda gözlerin gözlerimde dudakların dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ellerimiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-hakan-rodop-lx0tp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevince doğruluyor sabah

elimde kalem

dilimde türküler

aydınlık fikirler gibi

gönlüm ise tam bir panayır

güvercinlere soruyorum

geceleyin ölmek alın yazısı mı? 

hayır! ! !', 'sevince doğruluyor sabah elimde kalem dilimde türküler aydınlık fikirler gibi gönlüm ise tam bir panayır güvercinlere soruyorum geceleyin öl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sabah-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmediğini bilerek', 'sevmedigini-bilerek-hakan-rodop-fj2tf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biliyorum

aramızda bir şey olacak

sen ayrılacaksın

benden

benim yarınlarımdan

ayrı

haykıracaksın

belki de ağlayacaksın

ama

neye yarar ki

sevmediğini bilerek...', 'biliyorum aramızda bir şey olacak sen ayrılacaksın benden benim yarınlarımdan ayrı haykıracaksın belki de ağlayacaksın ama neye yarar ki sev...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevmedigini-bilerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda''n', 'sevda-n-hakan-rodop-9avbt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırak sevgini

şimdi git

hiçbirşey söylemeden

belki

bir zaman sonra

anlarsın 

yaptıklarını

ama

istersen

dönmek geri

derim ki

kızgınlık yok bende

önce

sevdana inan

sonra

başlayalım yeniden.', 'Bırak sevgini şimdi git hiçbirşey söylemeden belki bir zaman sonra anlarsın  yaptıklarını ama istersen dönmek geri derim ki kızgınlık yok be...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-n-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ve Aşk', 'gunes-ve-ask-hakan-rodop-t4w2y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nasıl güneş doğar 

binaların arasından

bilir misin

hani ışıklarını saklar ya

ateş böceği

ışıldamak için geceye

işte öyle geleceğim

çalacağım kapını

haykıracağım sevgimi

nasıl ateş böceği bıkar da

çalmazsa ıslığını gece yarısı

işte öyle düşüneceğim 

bıkana kadar seni

varsın olsun doğmamak sabaha', 'nasıl güneş doğar  binaların arasından bilir misin hani ışıklarını saklar ya ateş böceği ışıldamak için geceye işte öyle geleceğim çalacağım...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunes-ve-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-hakan-rodop-a9lhl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzün sarıyor her gece etrafımı

gencecik gönlüme hüzün geliyor

hüzün, 

hüzün, 

hüzünlenmek istemiyorum ben

ben şarkı söylemek

gencecik gönlümde

coşku duymak istiyorum

ben şafak doğarken

sevginin sesinde uyanmak

ve onun sesinde

yeniden doğmak istiyorum

ben kırılan yıkılan umutları

yeniden yaratmak

ve artık gülmek istiyorum

hüzün, 

hüzün, 

hüzünlenmek istemiyorum.', 'Hüzün sarıyor her gece etrafımı gencecik gönlüme hüzün geliyor hüzün,  hüzün,  hüzünlenmek istemiyorum ben ben şarkı söylemek gencecik gönlü...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huzun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşasın Aydınlık', 'yasasin-aydinlik-hakan-rodop-1sg8b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birden kağnılar doğruldu

öküzler iplerini kopardılar

o kalın acımasız iplerini

yularlarından boşalınca ağıt yaktılar

başlayınca kağnılar ağır ağır ağlamaya

yeni bir devrilme başladı

gökyüzüne baktılar başlarıyla

sabanı attılar yukarıya

ektiler biçtiler toprağı

toprak ana, ay dede

onlara yardım etti

kimse aramadı sormadı

o karlı dağların ardındaki dev’i

gün geldi doğrulunca sabah

birde baktılar gece hiç olmamış

işte! hiç olmuyor burada karanlık

ellerini birleştirip, haykırdılar: 

yaşasın aydınlık!', 'Birden kağnılar doğruldu öküzler iplerini kopardılar o kalın acımasız iplerini yularlarından boşalınca ağıt yaktılar başlayınca kağnılar ağı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasasin-aydinlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim', 'seni-ozledim-hakan-rodop-pwz7y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin aydınlığı vurmadan

                                      pencereme

bir ses uyandırır beni, 

                             sevgilim

bu kısacık yaşamda

gördüm insanların boşluğunu

senin doluluğunu

sevgilim

bu sabah

yeni bir güne kavuşurken

ne benim için

ne de geçen zaman için 

ağlama, üzülme

ama ağla, üzül

yaşayamadıklarımız için

bu sabah

sevgilim, 

                    penceremde

güneşin doğuşunu seyrederken

senin parlak, 

aydınlık yüzünü düşledim

sevgilim, gel artık

seni çok özledim.', 'Güneşin aydınlığı vurmadan                                       pencereme bir ses uyandırır beni,                               sevgilim bu...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-ozledim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev beni', 'sev-beni-hakan-rodop-0nmfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Solgun yaprakların ardından

git

bırakarak bana sevgini

konuş geldiğinde

mutluluğu anlat

nasıl bir şey

sokul yanıma

sev beni

ve dönünce geri

iste benden

bana verdiğin kalbini

ve güzel günleri yaşayamadığımız için ağla

ağla

ve güneşi sev

kuruttuğunda gözyaşlarını

ve sevgilim

mutlaka

dönünce

sev beni

tekrar gidene kadar...', 'Solgun yaprakların ardından git bırakarak bana sevgini konuş geldiğinde mutluluğu anlat nasıl bir şey sokul yanıma sev beni ve dönünce geri ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sev-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-hakan-rodop-mlct4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece anımsarken seni yine

gözlerim çağlıyordu gözlerine

özlemek meğersem ne güzelmiş

daha önce taddığın birşeyleri

alıp gitmek isterdim seni

buradan uzaklara

biryerlere götürmek

dağıtmak saçlarını

gerekirse değişirdim

seninkiyle yaşamımı

ama hiçbirşeye değişmezdim

o gözlerinin karasını...', 'Dün gece anımsarken seni yine gözlerim çağlıyordu gözlerine özlemek meğersem ne güzelmiş daha önce taddığın birşeyleri alıp gitmek isterdim ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Kuş', 'al-kus-hakan-rodop-jrufr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Al Kuş

     yaralı

kanadının yarasını sarıyor

günbatımında yolunu yarıyor

Al Kuş

         kanadını

ve

Al Kuş

             yolunu

ve kanadını

ve yolunu

Al Kuş

            herhangi bir kuş değil

            ta uzaklardan da gelmiyor

ama

Al Kuş

            hele kanadını

    ve

           hele yolunu

Al Kuş

içimizde yaşıyor...', 'Al Kuş      yaralı kanadının yarasını sarıyor günbatımında yolunu yarıyor Al Kuş          kanadını ve Al Kuş              yolunu ve kanadını...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/al-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırma sakın', 'sasirma-sakin-hakan-rodop-he0h4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak arkadaşım! 

Bu sabahın ilk ışıklarını

Seyrediyorum ben

Gülüyor gözlerimin içi

Ama sen

Bu sabahın ilk ışıklarında

Seyredemiyorsun onu

Gülmüyor gözlerinin içi

Gülemiyor

Kapanıyor

Merak etme! 

Bir gün

Delerek ışıklarını güneş

Gelecek sana da

Yakacak gözlerini

Bak arkadaşım! 

Bunları sana anlatıyorum

Sakın şaşırma! 

Zamanı geldiğinde', 'Bak arkadaşım!  Bu sabahın ilk ışıklarını Seyrediyorum ben Gülüyor gözlerimin içi Ama sen Bu sabahın ilk ışıklarında Seyredemiyorsun onu Gül...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sasirma-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar tanesi', 'kar-tanesi-hakan-rodop-8woki', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gerekirse bir söz söyleriz

İnatsa birlikteliğin gücü geliriz

Dağıtsanda inancını biz biliriz

Düşün ki onlar da geldi

Nasıl birleşti bu eller

Sessizliği kim bozmak ister

Farkındaysan doğallığın, yüzsüzlüğün

Senin için en güzeli ölmek

Doruğa ulaşıp düşmek

Ya da kar tanesi olmak...', 'Gerekirse bir söz söyleriz İnatsa birlikteliğin gücü geliriz Dağıtsanda inancını biz biliriz Düşün ki onlar da geldi Nasıl birleşti bu eller...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kar-tanesi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplumsal Başıboşluğun Cinselliği', 'toplumsal-basiboslugun-cinselligi-hakan-rodop-7po6d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilir misiniz

hani güneşin içinden gelen ışınlar gibi

sarar beni kıskaçlar boşlukta

bazen sorarım ne isterler benden

başıboşluğu onlar yarattı

hala ne isterler

yinelenen geçmişlere geri dönmek mi? 

kim ister kanlı gövdeyi, 

                       kansız cinselliği, 

                                utanmaz toplumu, 

herşey bir anda oldu

hatalıydık der büyükler

hatalı olan olacakların sarhoşluğunda

yarattıkları bencilliktir

çünkü onlar öğretti şu terimi: 

toplumsal başıboşluğun cinselliği.', 'Bilir misiniz hani güneşin içinden gelen ışınlar gibi sarar beni kıskaçlar boşlukta bazen sorarım ne isterler benden başıboşluğu onlar yarat...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/toplumsal-basiboslugun-cinselligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-hakan-rodop-16gfg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim de yıldızlardan bir isteğim var

alsınlar götürsünler beni oralara

orada ağlamak yokmuş diyorlar

orada güneş hiç batmıyor diyorlar

                                              doğru mu? 

istiyorum

çok istiyorum ben orayı

mutlaka

bana da yer vardır orada

eğer yoksa, 

boyun eğmek yok! 

yaşanacak yıldızlar çok...', 'Benim de yıldızlardan bir isteğim var alsınlar götürsünler beni oralara orada ağlamak yokmuş diyorlar orada güneş hiç batmıyor diyorlar     ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yildizlar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut ıslıkları', 'umut-isliklari-hakan-rodop-0gjsf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bir söz kaldı

             söyleyecek

aşka dair

ne de bir ışık var

              yakılacak

sadece bir umut şarkısı

     kaldı duyulacak

ve bir yumruk gibi ağır inan

söylediğin sözlerden

daha etkili

bir şarkı var

biraz da umut ıslıkları

çal sen

acıları dindirecek.', 'Ne bir söz kaldı              söyleyecek aşka dair ne de bir ışık var               yakılacak sadece bir umut şarkısı      kaldı duyulacak v...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umut-isliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık artık!', 'cik-artik-hakan-rodop-ldukt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saklandığın kovuklardan çık

git bak güneşin doğduğu yerden

başlıyor Aydınlık

kaçma sığınaklarına

söyle eski de olsa şarkılarını

hani özgürlük, aşk, vatan

hani nerde o umut türkülerin

biliyorsun sen

nasıl koşulacağını ölüme

nasıl haykırılacağını zulme

çık artık mağaralarından

koş meydanlara

katıl insanlara söyle.', 'Saklandığın kovuklardan çık git bak güneşin doğduğu yerden başlıyor Aydınlık kaçma sığınaklarına söyle eski de olsa şarkılarını hani özgürlü...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cik-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve biz ağıt yakmıştık', 've-biz-agit-yakmistik-hakan-rodop-w3u37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yandan bulutlar dağılıyor

şehrin üstünden

sanki dumanlı bir kış günü

geride kalmış da

hani oyuncaklarımızı yitirdiğimiz gün de

gökyüzü böyle dumanlıydı

ve biz ağıt yakmıştık

ateşler içinde

evet, bulutlar dağılıyor

aç içini gökyüzüne

durmadan kabaran o yüreğini

bir damlada boşalt

bak! 

dumanlı bir gecede

bir deniz kızı görmüş gibi

ya da elmas arayan bir avcının ışığında

söz! 

bitmeyecek bu sevda...', 'Bir yandan bulutlar dağılıyor şehrin üstünden sanki dumanlı bir kış günü geride kalmış da hani oyuncaklarımızı yitirdiğimiz gün de gökyüzü b...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ve-biz-agit-yakmistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-hakan-rodop-u4sf0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yasaklamışlar duygularımızı

geçit vermiyorlar

yasaklamışlar düşüncelerimizi

bırakmıyorlar söyleyelim

biz de haykırmak için

şiirlere başvuruyoruz

şiirlerimizle haykırıyoruz

‘insanlık için sevgi ve barış’ diye

çünkü onlara söz geçiremiyorlar', 'Yasaklamışlar duygularımızı geçit vermiyorlar yasaklamışlar düşüncelerimizi bırakmıyorlar söyleyelim biz de haykırmak için şiirlere başvuruy...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Dünya', 'mavi-dunya-hakan-rodop-yw40n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dünya olacak adı Sevgi, 

insanlar içten sevecekler

nefret ürkütmeyecek onları.

Bir dünya olacak adı Barış, 

insanlar yaşayacak kardeşçe

savaş ürkütmeyecek onları.

Bir dünya olacak adı İnsanlık, 

insanlar koşacaklar yardıma

bencillik ürkütmeyecek onları.

Bir dünya olacak adı Cennet, 

insanlar geleceğe gülecek

Geçmiş ürkütmeyecek onları.

Bir dünya olacak adı Mavi.', 'Bir dünya olacak adı Sevgi,  insanlar içten sevecekler nefret ürkütmeyecek onları. Bir dünya olacak adı Barış,  insanlar yaşayacak kardeşçe ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-hakan-rodop-i21nq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamak diyorum ben

bir martının yavrusuna bakışında

ya da bir serçenin güzel sesinde

hiç görülmeyen ve görülmeyecek

bir aşk diyorum ben

sanki hiç sevilmemişçesine

öpülmek, okşanmak, gülmek

mutluluk diyorum ben

gökyüzündeki yağmurda

yerdeki çamurda

rüzgarın esişinde

savaşmak zorluklarla

düşmemek tuzağa

yaşamak diyorum ben

yaşamak.', 'Yaşamak diyorum ben bir martının yavrusuna bakışında ya da bir serçenin güzel sesinde hiç görülmeyen ve görülmeyecek bir aşk diyorum ben san...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamak-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçedeki Oyun', 'bahcedeki-oyun-hakan-rodop-7c4gx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir aşktı yaşadığımız

bahçede oynadığımız oyundu

sonu ayrılık, 

sonu ölüm

hiç anmamak olur mu geçmişi

birlikte geçtiğimiz yolları

birlikte söylediğimiz türküleri

gidebildiğimiz kadar yürüdüğümüz

hani o sonu uçurum

sonra balıkçılarla gülüşüp

yaşadığımız hüznü

hani görünce o dilenciyi

söz verdiğimiz, 

dünyayı değiştireceğiz! 

bir bulut gibi süzülen yokluğun

gülümseyişin dudaklarımda

hala içimde diri bir umut

o kavga, o sevda, o ölüm

seni geri getirecek bana...', 'Bir aşktı yaşadığımız bahçede oynadığımız oyundu sonu ayrılık,  sonu ölüm hiç anmamak olur mu geçmişi birlikte geçtiğimiz yolları birlikte s...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahcedeki-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Adamın Öyküsü', 'koca-adamin-oykusu-hakan-rodop-vl2cc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-	Bizden geçti, dedi

Koca Adam

      Artık yapamayız

      Yalnızız, çaresisiz dedi

Ve ekledi: 

-	Umutsusuz

Ya! Koca Adam dedi bunları

      İnanırmısınız? 

Behey! Koca Adam

Sen ki tek başına dalmışsın

O köpeklerin inine

Atmışsın tokadı yüzlerine

Sonra gülmüşsün hallerine

İşte, Koca Adam

Demek ki böyle

Gün geliyor, devran dönüyor

Ama, doğru! 

İnsanlar değişiyor! 

            Kalktı, Koca Adam

Ayaktaydı

Yaktı bir sigara

Düşündü ve 

                   döndü

O, hep

Bir şey söylemeden önceki haline

Aniden, 

Sanki bir makinalı tüfek patladı

Kelimeler, 

Mermi gibi döküldü dudaklarından

-	Yok be arkadaş

Olur mu? 

Nasıl vazgeçermişim ben bu kavgadan

Çünkü, çıkmak istemem insanlığımdan!', '-	Bizden geçti, dedi Koca Adam       Artık yapamayız       Yalnızız, çaresisiz dedi Ve ekledi:  -	Umutsusuz Ya! Koca Adam dedi bunları      ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/koca-adamin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-derin-oger-uyfae', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalan gibi 

Dönüşü olmayan yol gibi

Ölüm gibi hasret gibi can gibi

Göremezsin dokunamazsın tanrı gibi

Yasak gibi ulaşılmaz bir şeydi seni sevmek

Gönlümü toz duman bıraktığın gibi

Değişilmez bir şeydi seni sevmek.

Her bahar yeni bir vedanın kılığında geldiğin gibi

Anlasana sırılsıklamım şimdi

Sen hangi baharın yağmuruydun

Anlasana yorgunum şimdi

Çık git artık, çık git yüreğimden

İçimdeki çocuk, sana küstü.........', 'Yalan gibi  Dönüşü olmayan yol gibi Ölüm gibi hasret gibi can gibi Göremezsin dokunamazsın tanrı gibi Yasak gibi ulaşılmaz bir şeydi seni se...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalan-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum Görsün', 'yavrum-gorsun-hulya-senkul-a7xdw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dünyanın sefasını

Süremedim, yavrum sürsün

İnsanların vefasını

Göremedim, yavrum görsün

Felek vurdu, gönül sustu

Bulamadım gerçek dostu

Şu toprağa aslan postu

Seremedim, yavrum sersin

Yalnızlığın çok cefası

Bana oldu her tafrası

Gariplere yer sofrası

Kuramadım, yavrum kursun', 'Bu dünyanın sefasını Süremedim, yavrum sürsün İnsanların vefasını Göremedim, yavrum görsün Felek vurdu, gönül sustu Bulamadım gerçek dostu Ş...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yavrum-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Aldı Gidiyor', 'demir-aldi-gidiyor-hamza-dekeli-e9s4e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Azat ettim sevgimi

Kalbimi araladım

Yasaklı aşkımızı

Maziye uğurladım

Gönlüm yeni bir aşka

Demir aldı gidiyor

Kalbimde ki yerinde

Şimdi yeller esiyor

Sildim defterden seni

İsmini karaladım

Bitti artık aşkımız

Seni gözden çıkardım', 'Azat ettim sevgimi Kalbimi araladım Yasaklı aşkımızı Maziye uğurladım Gönlüm yeni bir aşka Demir aldı gidiyor Kalbimde ki yerinde Şimdi yell...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/demir-aldi-gidiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Yıllar Gibi', 'kaybolan-yillar-gibi-halit-celikoglu-hyx1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybolan yıllar gibi

Uzayan yollar gibi

Kuruyan dallar gibi

Kuruttun şu kalbimi

Yüzüne hasret kaldım

Yıllara çok yalvardım

Yollara aşkı yazdım

Avuttum şu kalbimi

Hasretim dağlar gibi

Gözlerim ağlar gibi

Unutan kullar gibi

Unuttun şu kalbimi', 'Kaybolan yıllar gibi Uzayan yollar gibi Kuruyan dallar gibi Kuruttun şu kalbimi Yüzüne hasret kaldım Yıllara çok yalvardım Yollara aşkı yazd...', ARRAY['Türk Edebiyatı','Şiir','Halit Çelikoğlu']::text[], 8.5, '{"poet":"Halit Çelikoğlu","poet_slug":"halit-celikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybolan-yillar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İstiyorum', 'sevmek-i-stiyorum-gonul-sen-rnc0v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek istiyorum seni delice

Bütün benliğinle benliğime dol

Yak beni sevgilim delicesine

Küllere dönsem de ateşim sen ol

Sönmesin gönlümün ümit çırası

Nasılsa cehennem senden sonrası

Bendeyse sevip de yanma sırası

Küllere dönsem de ateşim sen ol

Alev alev dolaş bütün tenimde

Tek düşüncem sen ol, ümitlerimde

Yanmaya razıyım senin sevginle

Küllere dönsem de ateşim sen ol', 'Sevmek istiyorum seni delice Bütün benliğinle benliğime dol Yak beni sevgilim delicesine Küllere dönsem de ateşim sen ol Sönmesin gönlümün ü...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmek-istiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlersen...', 'ozlersen-ceyhun-kuburlu-pvhgs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum...

Bir gün özleyeceksin...

Ve arayacak....

..........

Biliyorum bir gün bu mısraları duyacaksın

Sesin titreyecek 

Soluğun kesilecek 

Mevsimin en güzel gününde 

Beni arayacaksın bu şehirde

Yağmurlar düşecek camına

Ve hüzünlü şarkılar çalacak radyoda

Biliyorum bir gün 

Hasret duyguları saracak gittiğin yolları

Dönmek isteyeceksin 

Sözler yasak bakışlar kaçak kalacak 

Bıraktığın baharlarda

Biliyorum sesinde hala işitmesi zor 

Sözler saklı

Ama hala umutlu...Kim bilir belki bir akşamüstü....

Beni düşünüyorsun

Hala aşık ve korkak

Kim bilir belki  bu şehirdesin 

Beni arıyorsun mevsimin en güzel gününde

Ve radyoda hüzünlü şarkılar

Çocuksu bir duygu başında 

Beni soruyorsun bildiğin tüm dostlara

Kim bilir belki bir akşamüstü 

Gökyüzünde alıcı bir bahar edası

Saçlarında alımlı bir meltem

Belki varım belki yokum 

Ama sen yinede gel...

Kim bilir belki hala seni bekliyorum

Bu sokaklarda 

Ağzımda serseri bir ıslıkla.... 

(19 Eylül 2002)

İstanbul’da Bir Akşamüstü Saati', 'Biliyorum... Bir gün özleyeceksin... Ve arayacak.... .......... Biliyorum bir gün bu mısraları duyacaksın Sesin titreyecek  Soluğun kesilece...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ozlersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonlu Sayıda Sessiz S''li Sevgi Sesi Sunumu', 'sonlu-sayida-sessiz-s-li-sevgi-sesi-sunumu-murat-cetin-o6eu2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'semadan semayı seyredip 

sevda savurdum 

sıra sıra sildim samanyolunu 

sabır sundum sükuta 

süngü sapladım soluk sarıya 

sevgini sevdim sevgilim 

safkan sürdüm sarayında 

sesini sezdim 

seyrettim sevgilim 

soluk saldım sonsuza 

sarmaşığı sardım sırtıma 

sahurda saydım saygıyı 

sarı saplı sapanla 

sazana sapladım sarı samanı 

sayıkladım senli saatleri 

sadabat sapağında 

söndüm sandım 

sensizlik sıcağında 

soldu soluğum 

sıgınak sağanağında 

saki su sundu 

susuzluk sustu. 

son sigarayı sardım sonra 

süzüldü.. 

sırf sevginin sancısını 

suskunlugun sızısıını 

sabrın sonunun selametini 

sazın sözü sunuş saatini 

santimini sentezleyip 

sergüzeşt sergisinde 

sarmalayıp sardığım 

sıkı sıkı sıkıp 

secdeye sunduğum 

süper sevgimi 

sağıma saklayıp 

senden sakındığım sevdiğimi 

sana seslice sunuyorum. 

seni seviyorum. 

.... 

sahi; 

seni sevmesem 

sence 

sen seni 

sevebilirmiydin? 

...... 

sustun... 

susma! 

sustukça 

sıkıntılar sıkar seni 

sen sevgini sun 

seni seven sevdiğine 

söyle sevdiğini 

..... 

sevgi; 

samanyolunun sabahı 

sabrın savaşı 

saadetin sesi 

sonsuzluğun sayısı 

seherin saati 

ve 

senliğin 

taa kendisidir. 

.....sırılsıklam seni seven, sevginede sanada sadık sevgilin 

18/08/2002', 'semadan semayı seyredip  sevda savurdum  sıra sıra sildim samanyolunu  sabır sundum sükuta  süngü sapladım soluk sarıya  sevgini sevdim sevg...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/sonlu-sayida-sessiz-s-li-sevgi-sesi-sunumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Kurban', 'askina-kurban-hulya-senkul-j2rse', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim ecelim, sen benim ahım

Sevmek oldu bütün suçum, günahım

Sensizliğe mahkum bu garip canım

Yoluna, uğruna, aşkına kurban

Düşmanın olamam kalbimi kırsan

Pişmanlık duyamam alnımdan vursam

Razıyım hasretle yakıp kavursan

Yoluna, uğruna, aşkına kurban

Sensiz şarap ne ki zehir içerim

Cihan vadetseler seni seçerim

Senden asla geçmem, candan geçerim

Yoluna, uğruna, aşkına kurban', 'Sen benim ecelim, sen benim ahım Sevmek oldu bütün suçum, günahım Sensizliğe mahkum bu garip canım Yoluna, uğruna, aşkına kurban Düşmanın ol...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askina-kurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekilin Başımdan', 'cekilin-basimdan-hamza-dekeli-oyteq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çekilin başımdan gidin ne olur

Ben kendi halime kendim yanarım

Size ne derdimden, acılarımdan

Ben kendi yaramı kendim sararım

İstemem elimden kimse tutmasın

Yanıma gelip de halim sormasın

Ölsem de derdime deman olmasın

Ben kendi halime kendim yanarım

Kayboldu şu ömrüm, bitti gençliğim

Ben kendi yolumu kendim ararım

İnsafsız kullara bırakma beni

Düştüğüm çıkmazdan sen kurtar Rabbim', 'Çekilin başımdan gidin ne olur Ben kendi halime kendim yanarım Size ne derdimden, acılarımdan Ben kendi yaramı kendim sararım İstemem elimde...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cekilin-basimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun Yerine', 'kursun-yerine-askin-tuna-kh35r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece ağlayan yaşlı gözlerle

Yüreğim yanarak baktım resmine

Bir anda kahroldum, yıkıldı dünyam

Resminle vuruldum kurşun yerine

Yokluğun aklımı başımdan aldı

Her yanımı özlem ateşi sardı

Gönlümün çiçeği yağmursuz kaldı

Hasretle vuruldum kurşun yerine

Kurtulmak istedim bir an sevginden

Her şeyi unutmak geçti içimden

Mümkün mü unutmak seni kalbimden

Sevginle vuruldum kurşun yerine', 'Dün gece ağlayan yaşlı gözlerle Yüreğim yanarak baktım resmine Bir anda kahroldum, yıkıldı dünyam Resminle vuruldum kurşun yerine Yokluğun a...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kursun-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor', 'doktor-sakir-askan-g9pz1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çaresiz derdimin sebebi belli

Dermanı yaramda arama doktor

Şifa bulmaz gönlüm senin elinden

Boşuna benimle uğraşma doktor

Aşk yarası bu, ilaç kapatmaz

Verdiğin teselli beni avutmaz

Dermanı yardadır, sende bulunmaz

Boşuna benimle uğraşma doktor

Bedenimde değil, kalbimde derdim

Tek alışkanlığım bir zalim sevdim

Sen çekil yanımdan sevdiğim gelsin

Boşuna zamanı harcama doktor', 'Çaresiz derdimin sebebi belli Dermanı yaramda arama doktor Şifa bulmaz gönlüm senin elinden Boşuna benimle uğraşma doktor Aşk yarası bu, ila...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/doktor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahkar Oldum', 'gunahkar-oldum-gonul-sen-mjkwy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Secde ettim aşka taparcasına

Uğrunda Allah''ın yolundan oldum

Sebep sensin bütün günahlarımın

Sevdikçe sayende günahkar oldum

Seninle açıldı günah defterim

Kokutuyor beni mahşer günlerim

Yaradan''a hangi yüzle dönerim

Sevdikçe sayende günahkar oldum

İbadetim oldun, inancım oldun

Sanki sen yarattın, ben kulun oldum

Affet Rabbim diye yalvardım durdum

Sevdikçe sayende günahkar oldum', 'Secde ettim aşka taparcasına Uğrunda Allah''ın yolundan oldum Sebep sensin bütün günahlarımın Sevdikçe sayende günahkar oldum Seninle açıldı ...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunahkar-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Gittin', 'neden-gittin-sair-oguzalp-xc1l6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi senden ayrı bir şehirdeyim

Senin eksikliğinle beraber gelen

Acı ve hüzündür yaşamın çektirecekleri

Neden gittin? 

Bak senin yokluğunda gemilerde gitti 

İstasyonlara uğramaz oldu trenler

Duraklarda bomboş nerede bunca yaşam sevinçleri

Şimdi kalbim bir sonbahar akşamının ıssız ve tenha bir sokağı

Ne gelen var nede giden

Ayrılık, ayrılmak bu olsa gerek

Neden be sevgilim neden

Sana en muhtaç olduğum bir anda neden

Biliyorum zaman belki değiştirecek bazı şeyleri 

Ama benidemi acaba

Seven ölümü senin için üstlenen 

Bir ömür boyu bekleyen ben olacağım

Sen hep beklenen yada gelmeyen veya gelen olacaksın

Neden gittin? 

Çiçekler gerçekten dargın gibi mi? 

Solgun bir halleri var bak

Onlarıda mı ayrılık vurdu dersin

Yoksa bir sonbahar uğultusumuydu üstlerindeki bezginlik', 'Şimdi senden ayrı bir şehirdeyim Senin eksikliğinle beraber gelen Acı ve hüzündür yaşamın çektirecekleri Neden gittin?  Bak senin yokluğunda...', ARRAY['Türk Edebiyatı','Şiir','Şair Oğuzalp']::text[], 8.5, '{"poet":"Şair Oğuzalp","poet_slug":"sair-oguzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmek Üzerine', 'gelmek-uzerine-murat-tali-wgz39', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gelmek ve gitmek arası biryerde geliverdim işte.

göğsümde kömür dolu ağır bir küfe

ve yorgun bedenim.

başımı alıp gitmek istediğim doruksuz tepeler ile

derinliğini kaybetmiş okyanuslar arasında

dümdüz vadilere dönmüş 

kalburüstü yanımla

sığ nehirlerin taşkınlarında hırpalanan 

ben

neresindeyim yaşamın

Bir avuç suda boğulacak sevinçlerimle

kim içimi boğuyor hangi karesindeyim oynayan filmin

uzun upuzun bir rüyadan uyanırcasına

ve yüzümü güneşe vererek acılarımı kavurmak istercesine

ağır ağır ilerliyorum susuz çöllerin ortasında

bırak dertler kendi salına binip gitsin diyorsun

beni bir yelkenliyle birlikte

seviçlere götür

rüzgarla beraber üfle 

yelkenler şişsin patlayıncaya kadar 

Nuh tufanı efsanesine dönen yaşamda

Ağrı dağına kondur 

sessizliği 

ve derin kar vadileriyle

uzat ellerini gökkuşağım ol

üşümemek için 

sımsıkı sar 

kürklerinle beni

kapat gözlerini...

kutsal sular serp 

sonra bırakıver bir yamaçtan 

çığ olup 

taşayım

ormanlara karışıp yaşamı bedenime katmak için

burada herşey gelmek ve gitmek üzerinedir çünkü

gelmek ve gitmek üzerine

gelmek ve gitmek

gelmek

gelme

gel', 'gelmek ve gitmek arası biryerde geliverdim işte. göğsümde kömür dolu ağır bir küfe ve yorgun bedenim. başımı alıp gitmek istediğim doruksuz ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gelmek-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'türkmen Kızı', 'turkmen-kizi-i-rfan-topcu-vz2hb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sırmalı saçların rüzgarı döğer, 

endamın inanki cihana değer, 

öğrendim banada dargınsın meğer, 

gözümün içine bak türkmen kızı

benide aşkınla yak türkmen kızı.

hiç varmı kitapta gönül incitmek, 

gördüğün her yerde dönüpte gitmek,

istersen ahirette  biraz gülmek, 

gözümün içine bak türkmen kızı

benide aşkınla yak türkmen kızı.

isyana zorlama merhamet eyle, 

sorarım duymazsın adını söyle, 

yüzünü dönüpte birkere böyle

gözümün içine bak türkmen kızı

benide aşkınla yak türkmen kızı.

kahredip ömrümü sonlandırayım,

belkide sonunda umutlanayım,

ne olur bir kere bak yaşayayım,

gözümün içine bak türkmen kızı

benide aşkınla yak türkmen kızı.', 'sırmalı saçların rüzgarı döğer,  endamın inanki cihana değer,  öğrendim banada dargınsın meğer,  gözümün içine bak türkmen kızı benide aşkın...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkmen-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma...', 'dostuma-zeynep-su-obuak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel otur yanıma

Söyleyeceklerim var sana..

Bir kahve yapayım ilk önce

İçerken başlarız sohbete..

Sen sigara içmezsin ama

Ben yakayım iyi gider kahvenin yanında..

Ne kadar oldu tanışalı, hatırlıyor musun? 

Ben unutmadım, dün gibi aklımda..

Yine geleceğim yanına

Bu sefer pastayı kendi ellerimle yapacağım sana..

Sohbetinin tadı kaldı damaklarımda

Hatırladıkça gülüşünü içim ısınır hala..

Sevmesini, yaşamasını yeniden öğrettin bana

Korkmadan kim değer verebilir ki bir insana..

Uzaktasın, omzun uzak ama

Biliyorum yüreğin yakın bana..

Ellerin uzanıp göz yaşlarımı silemedi

Asla izin vermedin yere düşmesine de..

Kaç kişiye nasip olur dostluğun

Ben seni tanıyan en şanslı kulum..

Adam gibi adam kime denirdi acaba? 

Öğrendim seni tanıyınca......', 'Gel otur yanıma Söyleyeceklerim var sana.. Bir kahve yapayım ilk önce İçerken başlarız sohbete.. Sen sigara içmezsin ama Ben yakayım iyi gid...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Su']::text[], 8.5, '{"poet":"Zeynep Su","poet_slug":"zeynep-su","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostuma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Bitti', 'yaz-bitti-esra-tacir-grd70', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya biterse; diye başlamaktan korktuğum, 

Uzun bir cümleydi aşk, 

Ben kısalarıyla yetindim.

Terkediliş hikayelerimden birini aldım elime, 

Donuk bir mateme bürünüp yanlızlığı, 

Ve sunulan ziyafetteki kırıntıları seçtim.

Korkuya saplanmış bir ecel terinin damlasıyla, 

Uğurluyorum yazı.

Yüreğime dalgaların buruk hıçkırığı çarpıyor.

Güneş yavaş yavaş soğuğa yılıyor.

Sahilde uzun cümleler kuran gençleri görüyorum.

Oysa henüz farkında değiller, 

Yaz bittikçe cümleler kısalıyor.!', 'Ya biterse; diye başlamaktan korktuğum,  Uzun bir cümleydi aşk,  Ben kısalarıyla yetindim. Terkediliş hikayelerimden birini aldım elime,  Do...', ARRAY['Türk Edebiyatı','Şiir','Esra Tacir']::text[], 8.5, '{"poet":"Esra Tacir","poet_slug":"esra-tacir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaz-bitti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardından', 'ardindan-gulsum-kevser-i-nce-8roym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olduğun gibi sevdim seni

Olacağın gibi değil

Gördüğüm gibi gördüm seni

Gördüğün gibi değil.

Ben seni sevdim bilemezsin, 

Bildiğin gibi değil.

Bakma güldüğüme sevindiğime, 

Benim sevincim, 

Güldüğüm gibi değil.

Gelsende artık farketmez, 

Gelişin, 

Gittiğin gibi değil.', 'Olduğun gibi sevdim seni Olacağın gibi değil Gördüğüm gibi gördüm seni Gördüğün gibi değil. Ben seni sevdim bilemezsin,  Bildiğin gibi değil...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ardindan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-gulsum-kevser-i-nce-3haje', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimin üzerinde bir ben

Parmağımın ucunda bir ben

Yanağımda bir ben, bacağımda bir ben

Ama bir yerde bir ben daha varki

Onu bir ben bilirim, bir ben..', 'Elimin üzerinde bir ben Parmağımın ucunda bir ben Yanağımda bir ben, bacağımda bir ben Ama bir yerde bir ben daha varki Onu bir ben bilirim,...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bile Bile', 'bile-bile-gulsum-kevser-i-nce-awaop', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun bir yürüyüştü

Farklı noktalara, 

Aynı yollardan yürüyorduk.

Mutluyduk ama, 

Ergeç gelecekti yolun sonu

Biliyorduk

Bile bile kendimizi gerçeklerden

Kaçırıyorduk

İşte yolun sonu geldi sevgilim

Artık herkes kendi yoluna

Ama senden bir ricam var

Lütfen, lütfen beni unutma..', 'Uzun bir yürüyüştü Farklı noktalara,  Aynı yollardan yürüyorduk. Mutluyduk ama,  Ergeç gelecekti yolun sonu Biliyorduk Bile bile kendimizi g...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bile-bile-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrendim', 'ogrendim-gulsum-kevser-i-nce-kaijs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyi öğrendim hayatta

Güneşin rengini, günün mavisini

Rakının tadını, sigaranın dumanını

Ağlamayı öğrendim, gülmeyi de

Öğrendim işte, 

Ne varsa öğrenilmesi gereken

Ama birşeyi öğrenemedim

İnsanlardan hiçbirşey 

Beklememeyi..', 'Herşeyi öğrendim hayatta Güneşin rengini, günün mavisini Rakının tadını, sigaranın dumanını Ağlamayı öğrendim, gülmeyi de Öğrendim işte,  Ne...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Kevser İnce']::text[], 8.5, '{"poet":"Gülsüm Kevser İnce","poet_slug":"gulsum-kevser-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ogrendim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünsem', 'seni-dusunsem-cahit-i-pekoglu-5prym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni düşünsem

sarhoş olurum.

Dudaklarından içtiğim özünle

hayat bulurum

Ne zaman seni düşünsem

tüm gözlerde seni ararım.

Tanrıya haykıran yüreğinbi düşünür

okşadıkca titreyen, teninle coşarım...

Ne zaman seni düşünsem

kaçışın gelir aklıma.

Gözlerini bende kaçırarak sonumuz

yok diyişin gelir aklıma.

Ne zaman seni düşünsem

aşk senden çok uzak gelir aklıma.

Sen yaşamak istediğini yaşadın

beni öldürme hakkını kim verdi sana...', 'Ne zaman seni düşünsem sarhoş olurum. Dudaklarından içtiğim özünle hayat bulurum Ne zaman seni düşünsem tüm gözlerde seni ararım. Tanrıya ha...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-dusunsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum Dediğinde! ! !', 'geliyorum-dediginde-turgut-erdogan-smp5w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen...

''Geliyorum sevgilim, hasret bitti'' dediğinde, 

kor olacak bedenim, 

her zerresi ayrı titreyecek.

Kirpiklerim cilve yapmayacak birbirine, 

sevişmeyecek.

O gece...

Akrebe ve yelkovana kör çivi çakılacak, 

zaman geçmek bilmeyecek.

Senin gelişinin şerefine tüm sevda güvercinlerimi azad edeceğim, 

taklacısı paçalısı pır pır uçacak yüreğimde.

Sabah olmak bilmeyecek, 

ay dolanacak belime yar, 

sen ''geliyorum'' dediğinde 

Alanya,15/09/2002', 'Sen... ''Geliyorum sevgilim, hasret bitti'' dediğinde,  kor olacak bedenim,  her zerresi ayrı titreyecek. Kirpiklerim cilve yapmayacak birbiri...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/geliyorum-dediginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-turgut-erdogan-8mcw8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yana baksam sen, 

Kimi görsem sana benziyor.

Gözümü kapatıyorum sen, 

Gözümü açıyorum yine sen.

Deli miyim neyim ben? 

Alanya,17/09/2002', 'Ne yana baksam sen,  Kimi görsem sana benziyor. Gözümü kapatıyorum sen,  Gözümü açıyorum yine sen. Deli miyim neyim ben?  Alanya,17/09/2002...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayal-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-cahit-i-pekoglu-bi35m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güle, güle sana güle, güle

kadınım, sevdiğim, tek gerçeğim güle, güle.

Geçerkenmi uğradın yoksa bana

yüreğimi bin parça eyledin güle, güle sana.

Güle, güle sana güle, güle

kadınım, sevdiğim, tek gerçeğim güle, güle...

Ne kadar seni uğurlasamda

yüreğimde hep kalıcısın.

Sen benim için misafir değildin

çıkıp gitsende.

Güle, güle sana güle, güle

kadınım, sevdiğim, tek gerçeğim güle, güle...

Sen gittiğin yoldaki beni durak zannettin

inipte yüreğime bakmak istedin.

Hep merak ederdin

aşk durağı nasıl olur diye

Tam sırrını çözmek isterken

gerçek aşkı farkettin.

Çok geçti değilmi meleğim

sanki zamanın dolmuş gibi gitmeyi terciğ ettin.

Güle, güle sana güle, güle

kadınım, sevdiğim, tek gerçeğim güle, güle...', 'Güle, güle sana güle, güle kadınım, sevdiğim, tek gerçeğim güle, güle. Geçerkenmi uğradın yoksa bana yüreğimi bin parça eyledin güle, güle s...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gule-gule-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum Ağlıyor', 'ruhum-agliyor-cahit-i-pekoglu-z0zwr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her ruh ölümden nasibini

aldığı kadar.

Her ruh aşktanda nasibini alır.

Benim ruhum

öylebir aşktan nasibini aldıki.

Artık aşkı olmadan yaşıyamıyor

ölümle kucaklaşacağı anı bekliyor...

Sensizlik hep ayaklarımı kaydırıyor

sanki hiç beni taşıyamıyor.

Sen olmadan ruhum seninle yaşasada

yüreğim sensizliğe hiç alışamıyor.

Her ruh ölümden ve aşktan

nasibini aldığı kadar.

Benim ruhum sana hiç doyamadı

doyamadığı içinde hep ağlıyor....', 'Her ruh ölümden nasibini aldığı kadar. Her ruh aşktanda nasibini alır. Benim ruhum öylebir aşktan nasibini aldıki. Artık aşkı olmadan yaşıya...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruhum-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevda', 'gizli-sevda-hamza-dekeli-pllfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırıldı umutlarım

Tükendi arzularım

Kurudu gözyaşlarım

Gizli sevda yüzünden

Ben sevdim eller aldı

Acısı bana kaldı

Yandı şu canım yandı

Gizli sevda yüzünden

Her çile beni buldu

Ömrüm acıyla doldu

Gençliğim haram oldu

Gizli sevda yüzünden', 'Kırıldı umutlarım Tükendi arzularım Kurudu gözyaşlarım Gizli sevda yüzünden Ben sevdim eller aldı Acısı bana kaldı Yandı şu canım yandı Gizl...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gizli-sevda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel Barışalım', 'hadi-gel-barisalim-hulya-senkul-uvzjc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dargınlığın sonu yok

Hadi gel barışalım

Otur şöyle yanıma

Konuşup, anlaşalım

Hadi gel al beni benden

Hadi beni sev yeniden

Hadi gel özlüyorum

Öp beni, sev yeniden

Olmaz olmaz gururun

İnce hesap hep huyun

Bitsin atık bu oyun

Hadi gel barışalım', 'Dargınlığın sonu yok Hadi gel barışalım Otur şöyle yanıma Konuşup, anlaşalım Hadi gel al beni benden Hadi beni sev yeniden Hadi gel özlüyoru...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hadi-gel-barisalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Bir Hatıra', 'senden-bir-hatira-askin-tuna-ggc51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrıldım diyorsun yüzüme karşı

Bilmem sensiz nasıl yaşayacağım

Demek ki bir aşkta böyle bitiyor

Mendilin varsa ver, ağlayacağım

Senden bir hatıra saklayacağım

Birlikte yaşanan günlerimize

Hasreti getiren kaderimize

Yıkılıp yok olan düşlerimize

Mendilin varsa ver, ağlayacağım

Senden bir hatıra saklayacağım

Madem görüşmemiz imkansız artık

Sevgilim, bir tanem Allah''a ısmarladık

Şöyle gözlerine son defa bakıp

Mendilin varsa ver, ağlayacağım

Senden bir hatıra saklayacağım', 'Ayrıldım diyorsun yüzüme karşı Bilmem sensiz nasıl yaşayacağım Demek ki bir aşkta böyle bitiyor Mendilin varsa ver, ağlayacağım Senden bir h...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/senden-bir-hatira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davacıyım', 'davaciyim-sakir-askan-hcdcm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalmadı gönlümde taş üstünde taş

Toz duman olmuşum, yıkılmışım ben

Gir de bak gönlüme sanki bir savaş

Rabbim bu kulundan davacıyım ben

Ben böyle ağlarken o şimdi mutlu

Ben yapayalnızken o sevda dolu

Delice sevmenin bedeli bu mu

Rabbim bu kulundan davacıyım ben

Baharda çiçeksiz bıraktın beni

Yağmurda kurutup sarattın beni

Cezasız bırakma böyle zalimi

Rabbim bu kulundan davacıyım ben', 'Kalmadı gönlümde taş üstünde taş Toz duman olmuşum, yıkılmışım ben Gir de bak gönlüme sanki bir savaş Rabbim bu kulundan davacıyım ben Ben b...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/davaciyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimden Silemedim', 'kaderimden-silemedim-halit-celikoglu-gqpqi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugünlerde bir hal oldu şansıma

Boşa geçen günler çıktı karşıma

Unutulmadık dertler açtın başıma

Kaderimden silemedim derdimi

Ümitsizlik rüzgarına kapıldım

Çaresizce gözyaşına satıldım

Gece gündüz dert içine atıldım

Kaderimden silemedim derdimi

Talih sardı beni çile çarkına

Varamadım geçen ömrün farkına

Ne yapayım böyle düştü şansıma

Kaderimden silemedim derdimi', 'Bugünlerde bir hal oldu şansıma Boşa geçen günler çıktı karşıma Unutulmadık dertler açtın başıma Kaderimden silemedim derdimi Ümitsizlik rüz...', ARRAY['Türk Edebiyatı','Şiir','Halit Çelikoğlu']::text[], 8.5, '{"poet":"Halit Çelikoğlu","poet_slug":"halit-celikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaderimden-silemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsiz', 'kalpsiz-ali-tekinture-558ce', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden bileceksin sevgilim aşkı

Kalbinin yerinde bir taş var senin

Boşuna mı yazdığım bu kadar şarkı

Kalbinin yerinde bir taş var senin

Hasremiş, özlemmiş sana ne bundan

Geçmemişsin sevda denilen yoldan

Haberin yok aşkın var olduğundan

Kalbinin yerinde bir taş var senin

Zalimlik yapmadan duramıyorsun

Seni sevenleri aldatıyorsun

Bu hayattan nasıl zevk alıyorsun

Kalbinin yerinde bir taş var senin', 'Nerden bileceksin sevgilim aşkı Kalbinin yerinde bir taş var senin Boşuna mı yazdığım bu kadar şarkı Kalbinin yerinde bir taş var senin Hasr...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalpsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Yeter ki', 'bil-yeter-ki-tahir-paker-3gr27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kapkara gözlerin

Deli ediyor beni

Senin olmak için

Aşarım her engeli

Uzak değil çok yakınım

Gelmesini bil yeter ki

Damarımdan akan kanı

Görmesini bil yeter ki

Her güzellik, sevgi sende

Sevmesini bil yeter ki

Kavuşamam deme sakın

Gelmesini bil yeter ki

Senden gelen tüm dertler

Seve seve çekilir

İnan senin uğruna

İnsan canını verir

Sen dalımda bir çiçeksin

Kıymetini bil yeter ki

Feda olsun canım sana

Sevmesini bil yeter ki', 'O kapkara gözlerin Deli ediyor beni Senin olmak için Aşarım her engeli Uzak değil çok yakınım Gelmesini bil yeter ki Damarımdan akan kanı Gö...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bil-yeter-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramak', 'aramak-sair-khan-t774c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ne misafirim ne de yaşamım

Şu alemde yalnızlığın, hasretin sesisiyim, 

Bir acaip karanlıkta hislerim, ışığım garip bir loşlukta

Gönlümün zindanında çekildim bir çareyim

yıkıldım vuruldum hayatın ihaneti ile viraneyim

Tebessümüm bile olmuş garip bir hüzün

Bu kalp baharı hiç yaşamadı gördüğü hep güzün 

Umutlarım yaprak yaprak dökülür gözlerden yaşlar eşliğinde

Sadece rüzgar okşar tenimi bir anne şefkatinde

hadi artık gelmedimi berim sıram? vurun boynumu

Asın beni hayat veren bir çınarın dalına, geçeceği yok bunun

Saatler hala vuruyor vuslatı dayanamıyorum dokunuyor kanıma

Dedim ya kapıldım hazin bir sonbahar rüzgarına

Kapandım dünya denen karanlık odama

Günlerimi sıraladım imamesi ben olanboşluk tesbihime

Yıldızlar kayarken bağrımda göklerin

Her gece gönül dağımda yaram olur bir asır kadar derin

Tamam artık anladım bu yalnızlık hep uzayan kızgın çöl

Sevinçler sevgiler aşklarda seraptır benim içimde

Bu amansız çölü geçerim ancak öldüğümde

Gecenin karanlığından çekiyorum acı bir nefes

Ayene onun kadar karamışciğerlerime

Karanlık geceyi gömdüm yorgun kalbime

Yumdum gözlerimi artık beyazın gizeminde

Mutluluğu arıyorum başımda dikilen imam efendinin telkininde', 'Ben ne misafirim ne de yaşamım Şu alemde yalnızlığın, hasretin sesisiyim,  Bir acaip karanlıkta hislerim, ışığım garip bir loşlukta Gönlümün...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aramak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-i-rfan-topcu-c2joo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözkapaklarından çıkıpta, 

Çenene doğru akan yaşlarının, 

Yüzünde bıraktığı izi bilmek, seni bilmek değilmiş.

Hoş bende bilememişimya

Gözlerinin derinliklerinde kaybolmak, 

Oradan aklına, 

Oradan gönlüne girdiğimi zannetmek, 

Yanılmışım.

Evet yanılmışım.

Ama bu benim suçum değil.

Nede senin vaz geçilmez güzelliğinin,eseri değil yanılmam.

Yanılmam insan olmam.....', 'Gözkapaklarından çıkıpta,  Çenene doğru akan yaşlarının,  Yüzünde bıraktığı izi bilmek, seni bilmek değilmiş. Hoş bende bilememişimya Gözler...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanilgi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'nineme', 'nineme-i-rfan-topcu-5js0k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'saçlarına ak düşmüş, 

tanıdığım ilk dadın.

ne zaman kovulsaydım, 

hep ona sığınırdım.

nede hoş konuşurdu, 

o kadife sesiyle.

nede güzel dua ederdi, 

nede güzel severdi hep.

saçlarımı okşayan, 

en merhametli eldi.

selvi boylu anam kadar güzeldi.

nede hoş severdi.

ne bulabiliyorum çocukluğumu, 

nede sevebiliyorum onun gibi çocuğumu.

merhametin adresi, 

nenemin yastık dizi.

yıllar sonra, 

elini öpmeye geldiğimde, 

ak saçları dahada artmıştı.

anca doğrula bildi yatağından.

halsizdi.

ama yine merhametli yine sevecen, 

yine en büyük sen, 

canım ninem.', 'saçlarına ak düşmüş,  tanıdığım ilk dadın. ne zaman kovulsaydım,  hep ona sığınırdım. nede hoş konuşurdu,  o kadife sesiyle. nede güzel dua ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nineme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice Resmini Öptüm...', 'gizlice-resmini-optum-cigdem-simsek-a0stf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gizlice resmini öptüm. 

Parmak ucumla yüzüne dokundum usulca...

Çok özlemişim seni! 

Ben sensizim, 

Ben kimsesizim...

Daha ne kadar sürecek bu; 

Sensizliğim... Kimsesizliğim... 

Gizlice resmini öptüm.

Parmak ucumla kimsesizliğime dokundum usulca...

Çok alışmışım sana! 

Ben yarımım, 

Ben sessizim...

Daha ne kadar sürecek bu; 

Yarım kalmışlığım... Sessizliğim... 

Gizlice resmini öptüm.

Parmak ucumla göz yaşlarıma dokundum usulca...

Çok sevmişim seni...!', 'Gizlice resmini öptüm.  Parmak ucumla yüzüne dokundum usulca... Çok özlemişim seni!  Ben sensizim,  Ben kimsesizim... Daha ne kadar sürecek ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gizlice-resmini-optum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye...', 'hediye-cigdem-simsek-zit97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gün doğum günün aşkım...

Ve ben seni kutlayamıyorum! 

Sana hediye alamıyorum, 

Renkli jelatinlerle paketleyip sana veremiyorum, 

“Doğum günün kutlu olsun aşkım” diyemiyorum, 

Mutlu gözlerle mumlarını üfleyişini izleyemiyorum, 

Resim karelerinde olamıyorum. 

Hiç okuyamayacağını biliyorum ama; 

Bu şiir sana veremediğim hediyen olsun...

“Doğum günün kutlu olsun AŞKIM...! ”', 'Bu gün doğum günün aşkım... Ve ben seni kutlayamıyorum!  Sana hediye alamıyorum,  Renkli jelatinlerle paketleyip sana veremiyorum,  “Doğum g...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hediye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayrandım...', 'hayrandim-cigdem-simsek-xks6k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sana hayrandım... 

Ruhuma savrulan yüreğine, 

İçime çektiğim nefesine, 

Gülerken kısılan gözlerine, 

Usulca dokunan ellerine, 

Beni saran kollarına, 

Üzerimde kalan kokuna, 

Boynumu öpen dudaklarına, 

Kanımın çekildiği tenine, 

Göğsüme değen göğsüne, 

Terime karışan terine...

Gülüşüne, 

Ellerine, 

Tenine, 

Ben sana HAYRANDIM...', 'Ben sana hayrandım...  Ruhuma savrulan yüreğine,  İçime çektiğim nefesine,  Gülerken kısılan gözlerine,  Usulca dokunan ellerine,  Beni sara...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Şimşek']::text[], 8.5, '{"poet":"Çiğdem Şimşek","poet_slug":"cigdem-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hayrandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Soğuk Yüzü', 'olumun-soguk-yuzu-erol-sen-fydov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ANNEM''E

Gecenin sırlar içindeki bitimsizliğinde

Biten hayatlara ağlamak varmış yaşantımızda

Gün ışığa döndüğünde birde sevdiğinden ayrılmak

Onu topraklara emanet etmek varmış

Soğuk olan bedene sarılmak son defa

Bakmak soğuk yanağını öpmek son defa

Nice ömürler tükendi bu ona benzemiyor

Yüreğim yanıyor bitimsiz.

19.09.2002', 'ANNEM''E Gecenin sırlar içindeki bitimsizliğinde Biten hayatlara ağlamak varmış yaşantımızda Gün ışığa döndüğünde birde sevdiğinden ayrılmak ...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olumun-soguk-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Yeter', 'bil-yeter-ozgecan-yavuz-88gl9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bir Duygu''sun hiç tadamadığım, 

Sen bir gülsün hiç tutamadığım, 

Sen benim için bir cansın kıyamadığım, 

Sen bir anımsın hiç ama hiçunutamadığım.

Bir gün tanışsak eğer, 

Senin olurdu günler geceler, 

Rüyanda gelirsem eğer, 

Rüyalarımda olduğunu bil yeter.', 'Sen bir Duygu''sun hiç tadamadığım,  Sen bir gülsün hiç tutamadığım,  Sen benim için bir cansın kıyamadığım,  Sen bir anımsın hiç ama hiçunut...', ARRAY['Türk Edebiyatı','Şiir','Özgecan Yavuz']::text[], 8.5, '{"poet":"Özgecan Yavuz","poet_slug":"ozgecan-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bil-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın Özlemi', 'asigin-ozlemi-salih-ozalasan-njm1r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meğerse ne kadar özlemişim seni

Deniz mavisi gözlerini

Beni hayallere daldıran sözlerini

Hüznü yok eden tatlı gülüşlerini

Kızdığında kaşlarını çatışını

Büyük harflerle bana bağırışını

Duygularını nokta nokta yazışını

Kalbimi delip geçen bakışını

İçimi titreten kokunu özlemişim

Edanı, işveni, nazını, savrulan siyah saçını

Gözlerinde kaybolup gitmeyi özlemişim

Özlemişim hayatıma neşe saçışını

Gitme ne olur kal benimle

Yasla kulağını dinle bak kalp atışımı

Ruhumda sensin esen fırtına

Sensiz devam ettiremem artık hayatımı

Hayat bilki sen olmadan artık bana zor

Hasretin yüreğimi yakan bir kor

Sensiz geçen geceleri birde bana sor

Gitme kal, özleminle yakıp yıkma hayatımı

Y.Tarihi 20-09-2002 Saat 10.35', 'Meğerse ne kadar özlemişim seni Deniz mavisi gözlerini Beni hayallere daldıran sözlerini Hüznü yok eden tatlı gülüşlerini Kızdığında kaşları...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asigin-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Bir Operaya Ağıt', 'yalniz-bir-operaya-agit-emrah-aydinalp-uvtju', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aralarda biryerlerde bizim sevdalıklarımız. Köhne, yıkılmaya yüz tutmuş hayallerin sonunda  inadına genç görünümlü, acımasızca kırılgan. Hani desem sana sinirli laflar veya yanlışlıkla yükselse sesim, başın düşecekmiş gibi geliyor öne. Veya ufacık bir hilede, aşk oyunlarının arasında, 

o arada bende kaybolurmuşum gibi. Nedenleri kenara bırakıp başlayabilirdik bu oyuna. Belki oyuncularıydık, belkide piyonları. Hani bazen kendimi Mungan`ın Yalnız Bir Opera`sının provasından çıkmış gibi hissederdim. Hani hiç bitmeyen provalar...

Oyuncular değişirdi. Sözler belki de. Gelmediği zaman aktrist önce ne kadar iyi bir oyuncu olduğuna dem vurmakla geçerdi zaman. Sonra; olursa sonrası, 

yeni arayışlar başlardı bir ihtimal. Baştan alınırdı oyun. Işıklar yeniden yanardı kararan sahneme. 

Sen çıktın... Sen girdiğinde operanın kapısında ışıklar varmıydı yoksa ışıkçı da sıkılıp uyumuşmuydu bilinmez. Görür gibiydi gözlerim ama kanlıydı, kırmızı... Sen geldiğin zamanki başrol oyuncum belki kuliste makyaj tazeliyordu, belkide çoktan çekip gitmişti. Hala da bilinmezi oynar ya... Hiç bana `ben devralayım rolü` demedin. Zaten devralacak bir rol yoktu ki. Ve senin belkide başrolün başka bir oyundaydı. Sahnedeydik. Sen vardın; evet kesinlikle vardın. Ben ordaydım. Ne sen değiştirmek istedin oyunu, ne ben sana ezber yaptırdım. Aklıma gelen sözcükleri kullanamadığım gece yalnızlıklarında, doğaçlama yıldızları seyrediyorduk. Ben yıldızların hareketlerini, seni izlediğimi bilmeden izlerken, sen beni belkide hiç yazılmaması gereken oyunlarımız için kurguluyordun. Perde açıldığı zaman ikimiz asla aynı sahnede olamazdık, bunu biliyordum. Provalar oyunun kendisini aratmamakla kalsaydı eğer, ben seni bir zaman sonra başka bir sahnede başka psikozların içindeki oyuncularla görmeye dayanabilirdim. 

Güçlü sözler kullanmamıştık aramızda. Bazen kim olduğumuzu sorgulardık, veya ben kimliğimi ararken sen kaybolanlar olduğumuzu öğrenmiştin bile.

Belki bunu sana ilk önce ben söylemeliydim. Benden duymanı hem isterdim, hemde benden duymadığın için memnunum. Kıvanç yüklü gençlik maceralarından arınmış, 

sahteliği olmayan, ama her adımda kaybetmeyi alışkanlık haline getiren ve bir zaman sonra fotoğraflarda bile yer almayan tinsel anıların içinde olacağımızı seni tanımadan 

önce öğrenmiştim. Hayatın karşıma çıkaracaklarını, karşına çıkarttıklarını sorgulamaya ayırdığımız zamanı, yok olan izlerimizi bulmaları için başkalarının yoluna ekmek kırıntıları serpmekle harcamadık. Öylesine zamanlardı ki onlar..  Hani senle sahnedeki saatler saniyelerle geçerken, belleklere milyon ışık yılları yer kaplayacak şekilde kazınıyordu.

Sahnedeydik... 

Sonlarımızı göremedik ki başlatmak için bilinçli davranalım. Tekrar dönersem başa, dağınık bir ruh haliyle, ve bir yazının edebi değerine sığmayan belki, ama bir hayatta insana çok şey katan mazi bilinciyle, işte o hayatın bize bir şeyler katabilmesi belkide tek umudumuzdu. Seni bana, beni sana, sonrasında biz dediğimiz ve hani

o benim kabul etmediğim kalabalık kitleyi birleştiren değerler, alkole katılmış güzel esanslar gibi yok oluyordu. Kokun ellerimdeydi dün mesela, bugün

hatırlamak için eldivenlerini kullanmak zorunda kaldım. Öylesine batmış görünüyordum ki belkide aramızda hani o elektrik dediğimiz nesne o batmışlığın statikliğinden

sıkıldığı için oluşmuştu. 

Bazı kararlar vermek gerekirdi  bazı oyunlarda. Mesela tüm yeteneğini bu oyunda göstermeyip bir başkasına saklamak gibi. Sonra insan kayboluşlarında anlarki

saklayarak o yeteneğini asla muhafaza edememekte. Öyleki ben senin için verdiğim kararlarda veya karar adını almasa bile -veya karar gibi zamanlara ihtiyaç duymasa bile- düşüncelerde ben olmanın ne kadar önemli bir şey olduğunu ortaya koymuştum. Çünkü senden istediğim senden başkası değildi. Ve eğer sen de günün birinde bu oyundan sıkılıp bir şekilde yönetmene itiraz etmeden tek suçlunun ben olduğumu farz edersen, -ki buna asla itiraz edemeyip sadece asla satılmayan gösteri biletlerini kaybolan gölgemi ısıtmak için kullanırım-   alıp götürmeyi en sona bırakmanı istediğim tek şey sensin. Ve eğer bir gün  fark edersen biz nasıl kaybolanlarsak ve içinde bulunduğumuz bir oyun değil de bizim ta kendimizse, bunu anladığın zaman işte o noktada hiç bir zaman kendini benden kaçıramazsın. Yılışık aşıklar gibi ense kökünde nefesimi hissettirmeye çalışmasam bile bunu anladığını bilmek; seni her gün kolumda, bir park gezintisinde, bir akşam meyhane çıkışında benimle yapacaktır. Çünkü her nasılsa bir gün bu perdenin hiç açılmamak üzere kapanacağını biliyorsam, bazen o anın bir an önce gelmesini istiyorsam, bu o andan korktuğumdan değil, o ana kadar oyunumu başarıyla oynayıp bir gün sahneden ışıklar üzerimde, gözlerimde o her zaman bahsettiğimiz mutluluk göz yaşlarım olsun diyedir...

Biz nasıl bu hayat dediğimizin içinde kaybolmaktaysak, gözümüzden akanlar asla bizim gibi davranmaz; akış yönlerine göre izlerini asla esirgemezler. Bir piyanonun aynı tuşlarına defalarca basılmasından çıkan tımbırtı nasıl hoşuna giderse; bir bardak aynı marka biraya sarhoş olabildiği için katlanırsa; rüzgar aynı yerden getirdiklerini iyi kötü bizim etrafımıza saçarsa; ''aynı sözleri'' sana söylemek te beni ne huzursuz ne de basit kılar...

Bir gün iklimlerin seni dağıtırcasına uzaklaştırdığı kişi ben olursam, çocukken ilerde eğlenceli olacağa benzer zannettiğim ''hayat'' senin arkandan ağlar, kokunu alamayan opera yas tutar.', 'Aralarda biryerlerde bizim sevdalıklarımız. Köhne, yıkılmaya yüz tutmuş hayallerin sonunda  inadına genç görünümlü, acımasızca kırılgan. Han...', ARRAY['Türk Edebiyatı','Şiir','Emrah Aydınalp']::text[], 8.5, '{"poet":"Emrah Aydınalp","poet_slug":"emrah-aydinalp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalniz-bir-operaya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşna Fişne', 'asna-fisne-refik-recep-pelit-7f4ep', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç çalmazmı davul ile zurna dengi dengine, 

Hangi nehir akar aktığığı yönün tersine, 

Hayat bu alabildiğine geçer kendi bildiğine, 

İnsanız geçmişiz kendimizden derdimiz aşnafişne!', 'hiç çalmazmı davul ile zurna dengi dengine,  Hangi nehir akar aktığığı yönün tersine,  Hayat bu alabildiğine geçer kendi bildiğine,  İnsanız...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asna-fisne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Uğruna', 'ask-ugruna-refik-recep-pelit-cagka', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılmadan yorulmadan

kırdık kalpleri 

ara vermeden, 

Gülemez hiç kimse

gülemeyiz

sadece bu yüzden, 

Sonu ne olur 

ne biter 

düşünmeyiz 

gideriz derinden

Güleni ağladı, 

seveni küstü 

sarstık herşeyi 

temelinden.', 'Yılmadan yorulmadan kırdık kalpleri  ara vermeden,  Gülemez hiç kimse gülemeyiz sadece bu yüzden,  Sonu ne olur  ne biter  düşünmeyiz  gider...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mukadder', 'mukadder-refik-recep-pelit-9wvfa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat

geçer gider

ömür

olur heder

günler

baştan keder.

gelen, gidenden 

beter 

bazen lider 

bazen semender

hayat çok uzun 

her yaşanan 

kader 

gönlümüz 

kalender

göçeriz

üçer beşer

ölüm''mü? 

MUKADDER.', 'Hayat geçer gider ömür olur heder günler baştan keder. gelen, gidenden  beter  bazen lider  bazen semender hayat çok uzun  her yaşanan  kade...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mukadder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derman Sendedir', 'derman-sendedir-hasret-gultekin-d4id5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'vakti seherde 

açılır perde 

düştüğüm yerde

derman sendedir

düşmüşüm kaldır

mihnetim oldur

ağlarım güldür

derman sendedir

benim biçare

kaldım avere

yürek pür yare

derman sendedir

nefs-i zalimi

gözle halimi

sundum elimi

DERMAN SENDEDİR', 'vakti seherde  açılır perde  düştüğüm yerde derman sendedir düşmüşüm kaldır mihnetim oldur ağlarım güldür derman sendedir benim biçare kaldı...', ARRAY['Türk Edebiyatı','Şiir','Hasret Gültekin']::text[], 8.5, '{"poet":"Hasret Gültekin","poet_slug":"hasret-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derman-sendedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Sevda', 'beyaz-sevda-yusuf-hayaloglu-n3dal', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen mapusta solan gülsün  her yanın duvar

SEN AĞLAMA KAN OLUR BANA O YAŞLAR

sen hayatın küskünüsün acının suskunu

sen yayalada bir baharsın, tarlada rüzgar

içimde sana dair bembeyaz bir sevda var

sen torosta yağan karsın tarlada rüzgar

SAKIN ESME TOZ OLUR KAPANIR YOLLAR

sen eylemin yangınısın hayatın cılgını

tenimde sana dair ürpertiler var

sen munzurda akan çaysın yaylada bahar

SEN GÜLÜNCE GÜL AÇAR YİNE O DAĞLAR

sen sevincin dudağısın sevdanın sapağı

sazımda sana dair esintiler var', 'sen mapusta solan gülsün  her yanın duvar SEN AĞLAMA KAN OLUR BANA O YAŞLAR sen hayatın küskünüsün acının suskunu sen yayalada bir baharsın,...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyaz-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-soner-salih-hve8r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum saat gecenin bilmem kaçı

Seni arıyorum şarkılarda şiirlerde 

Tattığım sigaranın dumanında bile 

Kısacası seni düşünüyorum gülüm 

Bizi düşünüyorum ettiğimiz yeminleri

Bizi düşünüyorum elele ve mutlu

Buluştuğumuz konuştuğumuz yerleri

Kısacası bizi düşünüyorum gülüm

Kendimi düşünüyorum seni seven

Kendimi hatırlıyorum candan sevilen 

Seven sevilen mutlu bir insan 

Kısacası kendimi düşünüyorum gülüm

Aradan haftalar günler geçti

Dedim ya saat gecenin bilmem kaçı

Seni unutamıyorum birazda bana acı

Kısacası seni unutamıyorum GÜLÜM.....

Ben.......? 

Ben........? 

Anlasana bi tanem 

Seni ben...............? 

SENİ HALA ÇOK AMA ÇOK SEVİYORUM GÜLÜM', 'Seni düşünüyorum saat gecenin bilmem kaçı Seni arıyorum şarkılarda şiirlerde  Tattığım sigaranın dumanında bile  Kısacası seni düşünüyorum g...', ARRAY['Türk Edebiyatı','Şiir','Soner Salih']::text[], 8.5, '{"poet":"Soner Salih","poet_slug":"soner-salih","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda', 'uzaklarda-alper-sarialp-w5xt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklarda seni yaşamak daha güzel

Daha güzel acı çekmek senin için, 

Kahve, meyhane köşelerinde sefil sefil

Tüm içkileri bitirmek bir solukta

Sarhoş olmak adam akıllı

Sonra yürümek karanlık gecelerde düşe kalka

Seni aramak caddelerde köşebaşlarında

Seni böyle yaşamak daha güzel

Yokluğunun verdiği acılarla

Bitmeyen yalnızlıklar içinde uzayan gecede

Seni böyle yaşamak, 

Ağlamak sabahlara kadar

Tükenmek bilmeyen gözyaşlarıyla dalmak geceye

Seni rüyalarda aramak 

Seni rüyalarda yaşamak  daha güzel...', 'Uzaklarda seni yaşamak daha güzel Daha güzel acı çekmek senin için,  Kahve, meyhane köşelerinde sefil sefil Tüm içkileri bitirmek bir solukt...', ARRAY['Türk Edebiyatı','Şiir','Alper Sarıalp']::text[], 8.5, '{"poet":"Alper Sarıalp","poet_slug":"alper-sarialp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzaklarda-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku Oğlum', 'oku-oglum-mehmet-fatin-baki-aiu14', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oku oğlum. Oku yaz. Her şeyi bilmen gerekir

Ne kadar zor sorular sorsa da Münkir ve Nekir

Acaip dünyadasın. Başkası tutmaz kolunu

Okumazsan kölelik mesleği bekler yolunu.

Feilatun  Feilatun  Feilatun  Feilun

..  /  /.. /    / ..  /   /..  /', 'Oku oğlum. Oku yaz. Her şeyi bilmen gerekir Ne kadar zor sorular sorsa da Münkir ve Nekir Acaip dünyadasın. Başkası tutmaz kolunu Okumazsan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/oku-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Yap', 'baris-yap-mehmet-fatin-baki-3f6cl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok varsa gücün âlemi bir karmakarış yap

Gâyen ödül almaksa rakiplerle yarış yap

Sarhoş dolu meyhanede zevk almak için sen

Nefsinle boğuşsan bile komşunla barış yap.

		

	

 Mefulu Mefailu Mefailu Feilun

   /   /..  /   /..  /   /..  /   /', 'Çok varsa gücün âlemi bir karmakarış yap Gâyen ödül almaksa rakiplerle yarış yap Sarhoş dolu meyhanede zevk almak için sen Nefsinle boğuşsan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/baris-yap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Katıl', 'bana-katil-ozlem-bayram-immf1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'OLSAK

Sarhoş olsak olur olmadık gecelerde..

Karelere bölünsek de; hiç bölünmesek.

Sonra toplasak bütün duygularımızı, 

Çıkartsak aklımızdan 

Bütün karamsarlıkları.

Bir aşk çarpsa sonra ikimizi, 

Hasta gibi olsak, ayakta duramasak.

Sarılsak birbirimize, 

Derin bir uykuya dalsak.

Sonra tek bir rüya görsek, 

İkimizin de görebildiği.

Hiç uyanmasak o rüyadan, 

Rüyayı gerçekte yaşasak.

Çıkmaz sokağın çıkışın da ki; 

Hani var ya o kuytu da bir olsak! 

Biz ikiyken bir olsak, bir iken üç...

Çoğalsak, 

Çoğaldıkça karşılıklı sonsuz sevgimiz....

Ve rüyadan hiç uyanmadan ölsek, 

Sadece ikimiz.', 'OLSAK Sarhoş olsak olur olmadık gecelerde.. Karelere bölünsek de; hiç bölünmesek. Sonra toplasak bütün duygularımızı,  Çıkartsak aklımızdan ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bana-katil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kocam Helen Ben', 'kocam-helen-ben-muazzez-menemencioglu-mo080', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üçümüz mutluyduk bir ara

Kocam, ben ve Helen

Nereye gittikse elele

Helen güzel bir kadın değildi aslında

Oldukça dişicene

Alıverdi kocamı elimden.

İşi bir verevinden tutmak var, 

Bir düzünden...

Bile bile çaprazına

Üçümüz oynadık bu oyunu

Kocam, Helen, ben

Ah ben, ben, ben, ben! ..', 'Üçümüz mutluyduk bir ara Kocam, ben ve Helen Nereye gittikse elele Helen güzel bir kadın değildi aslında Oldukça dişicene Alıverdi kocamı el...', ARRAY['Türk Edebiyatı','Şiir','Muazzez Menemencioğlu']::text[], 8.5, '{"poet":"Muazzez Menemencioğlu","poet_slug":"muazzez-menemencioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kocam-helen-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Çocuğun Düşü', 'kiz-cocugun-dusu-muazzez-menemencioglu-6kkle', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni kundaklara sarmıyacağım

adını Özgür koyacağım

ben büyüyünce

seni doğurunca...

Özgürce büyüsün elin, ayağın

düşüncelerin özgürce gelişsin

diye...

Zincir bir resim olarak

kalacak

söz veriyorum

tarihlere kazılı

ben büyüyünce

tüm savaşlara

paydos

özgürlüğün

dışında

Özgür bebek ve

arkadaşları

özgürce

yaşasın diye', 'Seni kundaklara sarmıyacağım adını Özgür koyacağım ben büyüyünce seni doğurunca... Özgürce büyüsün elin, ayağın düşüncelerin özgürce gelişsi...', ARRAY['Türk Edebiyatı','Şiir','Muazzez Menemencioğlu']::text[], 8.5, '{"poet":"Muazzez Menemencioğlu","poet_slug":"muazzez-menemencioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kiz-cocugun-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Çiçeği Bebecik', 'can-cicegi-bebecik-muazzez-menemencioglu-drhf1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşlanırken yavaş yavaş bu şiir ve

ben

sen el kadar bebecik

bebecik kalacaksın

bu şiirde...

Gün be gün serpildikçe

bu dizeler, 

sen büyüdükçe

bebecik

bu dizeler hep

böyle

yazıldığı gibi

kalacak

Can çiçeği

bebecik

hoş geldin

aramıza', 'Yaşlanırken yavaş yavaş bu şiir ve ben sen el kadar bebecik bebecik kalacaksın bu şiirde... Gün be gün serpildikçe bu dizeler,  sen büyüdükç...', ARRAY['Türk Edebiyatı','Şiir','Muazzez Menemencioğlu']::text[], 8.5, '{"poet":"Muazzez Menemencioğlu","poet_slug":"muazzez-menemencioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/can-cicegi-bebecik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğümlü Şiir', 'dugumlu-siir-i-lhan-demiraslan-wp3i4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günler birbirine bağlı

Seneler birbirine.

Sen doğduğuna şükret

Gerine gerine...

Senin mi başında sade

Cümlemizin başında

Vakitsiz olmasın yalnız

Bu genç yaşımda.

Elinde bir uzun urgan

Üstü milyon düğümlü.

İstesen de, istemesen de

Bir ucu ölümlü.

Madem kurtuluş yok

İnsan bilmiyor gününü.

Kuşlardan, böceklerden ibret

Düşün de ölümü.', 'Günler birbirine bağlı Seneler birbirine. Sen doğduğuna şükret Gerine gerine... Senin mi başında sade Cümlemizin başında Vakitsiz olmasın ya...', ARRAY['Türk Edebiyatı','Şiir','İlhan Demiraslan']::text[], 8.5, '{"poet":"İlhan Demiraslan","poet_slug":"i-lhan-demiraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dugumlu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sesler En Eski Uzaklarda', 'eski-sesler-en-eski-uzaklarda-i-lhan-demiraslan-plppc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelibolu''da kaldı iskelesi çocukluğum

Teneke kayıklarım yelkeni bezden

Boğazda balta burunlu gemiler

Kimbilir şimdi hangi denizlerde

Kimbilir şimdi nerelere gider

Eski sesler en eski gramofonlarda

En eski plaklarda Sadettin Kaynak

Eskiden daha da güzeldir

Kimbilir şimdi hangi kulaklarda

Kimbilir nerden alıma geldiler', 'Gelibolu''da kaldı iskelesi çocukluğum Teneke kayıklarım yelkeni bezden Boğazda balta burunlu gemiler Kimbilir şimdi hangi denizlerde Kimbili...', ARRAY['Türk Edebiyatı','Şiir','İlhan Demiraslan']::text[], 8.5, '{"poet":"İlhan Demiraslan","poet_slug":"i-lhan-demiraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/eski-sesler-en-eski-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Yerinin Elleri', 'tan-yerinin-elleri-i-lhan-demiraslan-5lksy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne horoz düzenliyor ne kuş korosu

Tan yerinin elleri tetiktedir

Sabaha düzenliyor tellerini

Horozum da gerçeği bilmektedir

Gördü ki bir dönemin öldüğünü

Sabah yıldızları dellenmektedir

Ve horozum ve kuşlarım ayakta

Almış yerlerini beklemektedir

Sömüreni kan emeni katili

Mest olup uykuda gerinmektedir

Bir ölüm perdesi ki ağır ağır

Her gece üstlerine inmektedir

Horozum öt horozum öt uzatma

Tan yerinin elleri tetiktedir', 'Ne horoz düzenliyor ne kuş korosu Tan yerinin elleri tetiktedir Sabaha düzenliyor tellerini Horozum da gerçeği bilmektedir Gördü ki bir döne...', ARRAY['Türk Edebiyatı','Şiir','İlhan Demiraslan']::text[], 8.5, '{"poet":"İlhan Demiraslan","poet_slug":"i-lhan-demiraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tan-yerinin-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydınlık Dünya', 'aydinlik-dunya-semsettin-unlu-m57uq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim aydınlık dünyamda serçeler

Bir yaz günü yaşarlar

Biri uçtuğu zaman

Hep birlikte uçarlar.

Benim aydınlık dünyamda kurbağalar

Bir yosunlu göl içindedir

Ay ışığında türkü söyler

Lezzetle çoğalırlar.

Benim aydınlık dünyamda

Çiçekler, böcekler, yıldızlar da var

Kardeş kardeş öyle telaşsız

Kendi hallerinde yaşarlar.

Benim aydınlık dünyamda hayat

Bir çorap söküğüdür gider

Böcekler yaşar, 

İnsanlar kavga ederler.', 'Benim aydınlık dünyamda serçeler Bir yaz günü yaşarlar Biri uçtuğu zaman Hep birlikte uçarlar. Benim aydınlık dünyamda kurbağalar Bir yosunl...', ARRAY['Türk Edebiyatı','Şiir','Şemsettin Ünlü']::text[], 8.5, '{"poet":"Şemsettin Ünlü","poet_slug":"semsettin-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aydinlik-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damladıkça', 'damladikca-i-brahim-yildiz-ea4m3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tutamadım kuşu sevindim

özgürlüğün tadı birikti içimde

bir şiir soluk alıp veriyor kanatlarında ıpıslak

yağıyor dilime', 'tutamadım kuşu sevindim özgürlüğün tadı birikti içimde bir şiir soluk alıp veriyor kanatlarında ıpıslak yağıyor dilime...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yıldız']::text[], 8.5, '{"poet":"İbrahim Yıldız","poet_slug":"i-brahim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/damladikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalın Çiğ', 'kalin-cig-i-brahim-yildiz-m1xt7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsansa insan yaşasın kitaplarda

bir ipin ucundaki ter gibi

nasıl olsa gözü içene açıktır şairin

öpmek için insanı sevgi suyunda yıkar şair

öpmek için insanı sevgi suyunda şiir

duyabilen algılar yılan ağzında bile

ama kendisini kaf dağında sanır cahil

hele yorgan örttüyse hasetten üstüne

gece karanlığında kalın çiğ

Şafak sökmez başkalarının sırtında-

şiir çok derindedir

ya da kimbilir nerdedir

-Halim', 'İnsansa insan yaşasın kitaplarda bir ipin ucundaki ter gibi nasıl olsa gözü içene açıktır şairin öpmek için insanı sevgi suyunda yıkar şair ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yıldız']::text[], 8.5, '{"poet":"İbrahim Yıldız","poet_slug":"i-brahim-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalin-cig-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çerçi', 'cerci-arif-coskun-0pft6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çerçi-yüküm pahalı

O güneş tayfında yirmi dört renk

Turuncusu pembesi moru yeşili

Laciverdi mavisi bol

Bir siyahtan katık

Bütün renklerden fazla

Sarıda ilişip

Canın pembe mi çekti

Al para verme

Bu beyazın tayfı bütün renklerde

Siyah katmayın ona n''olursunuz

Bu aldır beyaza en çok yakışan

Tozuyup sarıda

O en çok sevdiğim renk

Siyahtır beyazın yanında

Çerçi-yüküm pahalı

Ayva solup

Nar güle

Ak yuyup

Al sararım

Çıkınım da Anadolu

Beğen beğen al', 'Çerçi-yüküm pahalı O güneş tayfında yirmi dört renk Turuncusu pembesi moru yeşili Laciverdi mavisi bol Bir siyahtan katık Bütün renklerden f...', ARRAY['Türk Edebiyatı','Şiir','Arif Coşkun']::text[], 8.5, '{"poet":"Arif Coşkun","poet_slug":"arif-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cerci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tel Koptu', 'tel-koptu-arif-coskun-wfyqc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kopan telefon telleri leşinde

Düşünüyorum

Hem evet

Hem hayır

Çözemiyorum düğüm üstüne düğüm

Suların aydınlığında

Açmış nilüferi ben sanmıştım

Kopan iki uçta gurur ve kan

Sıkışmış iki yürek

Saniyede ne çok sinyal alıyorum ve veriyorum

Kopan tellerde ne çok orkide karanfil ölüsü', 'Kopan telefon telleri leşinde Düşünüyorum Hem evet Hem hayır Çözemiyorum düğüm üstüne düğüm Suların aydınlığında Açmış nilüferi ben sanmıştı...', ARRAY['Türk Edebiyatı','Şiir','Arif Coşkun']::text[], 8.5, '{"poet":"Arif Coşkun","poet_slug":"arif-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tel-koptu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Saçlarınızdaydı', 'eylul-saclarinizdaydi-atilla-birkiye-o8zb4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar düştü birden

Yapraklar sararmamış

Rüzgar, yağmur, bulutlar

Akşamdı

Hüznü söylüyor Pera

Eylül hazırlıksızdı

Saçlarınızdaydı yağmur

Saçlarınızdan yağmur aktı

Saçlarınız yağmur gibi damlıyor

Gözleriniz bir masalı taşıyordu

Akşamdı

Hüznü söylüyor Pera

Eylül hazırlıksızdı

Eylül aşkı anlatıyor

Eylül saçlarınızdaydı', 'Sonbahar düştü birden Yapraklar sararmamış Rüzgar, yağmur, bulutlar Akşamdı Hüznü söylüyor Pera Eylül hazırlıksızdı Saçlarınızdaydı yağmur S...', ARRAY['Türk Edebiyatı','Şiir','Atilla Birkiye']::text[], 8.5, '{"poet":"Atilla Birkiye","poet_slug":"atilla-birkiye","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eylul-saclarinizdaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-atilla-birkiye-iom8c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazın sakinliği

Lacivert denizde

Lacivert gökyüzünde

Bir gemi geçiyor

Yalnızlaştıkça

               yalnızlaşıyor

                                dolunay

Saçların kitap adı gibi

Gizleniyor Boğazın soğuk

                                   derinliklerine

Uzaklardasın, yine

Hem de çok yakın

Şiirin hüzün dolu sesinde', 'Yazın sakinliği Lacivert denizde Lacivert gökyüzünde Bir gemi geçiyor Yalnızlaştıkça                yalnızlaşıyor                           ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Birkiye']::text[], 8.5, '{"poet":"Atilla Birkiye","poet_slug":"atilla-birkiye","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yine-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman Eğilip Baksam Yüreğime', 'ne-zaman-egilip-baksam-yuregime-arif-damar-v6m8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman eğilip baksam yüreğime 

Eski aşklarımın kırıntıları

Parlayıp söner

Ve bir yaz gecesi karanlığında gözlerim

İKİ GÖLGE SEÇER

İstasyon Binası Ağaçlar ve Merdivenler

Rumca söylenen bir ezgiyi dinlerken

DALAR gider 

Ve bir tren gelip geçer aniden 

NE ZAMAN EĞİLİP BAKSAM YÜREĞİME', 'Ne zaman eğilip baksam yüreğime  Eski aşklarımın kırıntıları Parlayıp söner Ve bir yaz gecesi karanlığında gözlerim İKİ GÖLGE SEÇER İstasyon...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif-damar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-zaman-egilip-baksam-yuregime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Ağıdı', 'cocuk-agidi-cahit-okmen-6qen0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'taşlığa yılan yontuyor

gözkapaklarıyla ağlıyor

yılanın süt kabına

sarı gazozundan damlıyor

... bir gümüş tepsi getirin...

... bir de limon kolonyası...

... damlatın ovun kanımla...

... atın sonra misketleri...

... balkondaki boş saksıya...

... kırdım ayın ışığını...

... sapanımla ben kırdım...

... gece rüyamdan çaldığım...

.... aydan daha parlak...

... çakıl taşıyla kırdım...

tebeşir evin içinde

kasığında kızgın gamze

bir sap düğün menekşesi

kirlenmiş sır gözlerinde

... saklambaç kovasında...

... düğümledim beş taşımı...

... sulu sepkende çınlatın...

... asın nar ağacına...', 'taşlığa yılan yontuyor gözkapaklarıyla ağlıyor yılanın süt kabına sarı gazozundan damlıyor ... bir gümüş tepsi getirin... ... bir de limon k...', ARRAY['Türk Edebiyatı','Şiir','Cahit Ökmen']::text[], 8.5, '{"poet":"Cahit Ökmen","poet_slug":"cahit-okmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cocuk-agidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Kırgını', 'aksam-kirgini-cengiz-senol-sa614', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda hiç gelmez oldu aklıma

Hüznüme annem geleli

Kanar oldu kapılar şimdi her eve

Eşiklerde kalbim ezileli

Kalbim ki en içli akşamıdır yolların

Kuşları altın kuleli

Bir suyu dinler oldum artık yüzümde

Aynalar aynalar nasıl çileli

Sevda hiç gelmez oldu aklıma

Hüznüme annem geleli', 'Sevda hiç gelmez oldu aklıma Hüznüme annem geleli Kanar oldu kapılar şimdi her eve Eşiklerde kalbim ezileli Kalbim ki en içli akşamıdır yoll...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Şenol']::text[], 8.5, '{"poet":"Cengiz Şenol","poet_slug":"cengiz-senol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aksam-kirgini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Anlatılmaz Şey', 'ne-anlatilmaz-sey-cevdet-atmaca-ekw2y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çoğalır ağaran günle birlik

Bu senin gücün ölümden öte

Toprağı deviren traktörde

Mutlu gürültülerinde makinelerin

Çoğalır ağaran günle birlik

Bu senin gücün ateşte

Ocakları kaynatan yeniden

Silahların şavkıyan çeliğinde.

Gider inanmışlığımız daha yıllara

Nice öyküleri yazarız

Anıtlara kitaplara

Yaşarken evrenin üstünde

Sen erkinlik adına

Sen kavgadan önce barış

Gider inanmışlığımız daha yıllara

Büyürken oğullarımız, kızlarımız.

Duyuyor musun ne anlatılmaz şey

Milyonların korosunda

Uğul uğul kasım yeli

Dolanır dağ taş şehir köy

Iraksın hem o kadar yakın

Tedirgin sabahın oluşunda

Duyuyor musun ne anlatılmaz şey

Kuşun kurdun susuşunda.', 'Çoğalır ağaran günle birlik Bu senin gücün ölümden öte Toprağı deviren traktörde Mutlu gürültülerinde makinelerin Çoğalır ağaran günle birli...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Atmaca']::text[], 8.5, '{"poet":"Cevdet Atmaca","poet_slug":"cevdet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-anlatilmaz-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarından Tezi Yok', 'yarindan-tezi-yok-arif-damar-3tc7h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben yalnız tarla da mı başak

Deniz de mi balığım yoksa

Bu esen yel ne biçim yel 

Yapraktan sudan 

Poyraza mı dönüştü hava

Kötü günler mi geçti

Ben görmeyeli 

Ben de acılar mı kattım acıya

Bu yol o yol değil mi söyleyin N''olur

Gittiğim yol 

Giden yol 

HÜRLÜĞÜN YOLU', 'Ben yalnız tarla da mı başak Deniz de mi balığım yoksa Bu esen yel ne biçim yel  Yapraktan sudan  Poyraza mı dönüştü hava Kötü günler mi geç...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif-damar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarindan-tezi-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bez Ciltli Bir Kitapta', 'bez-ciltli-bir-kitapta-coskun-yerli-kwknu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bez ciltli bir kitapta kederli bir düş vardı

Solgundu düş, yorulmuş, eskimiş, eprimişti

Esmerdi, inceydi, tartımlı tümceleri

Hiçbir ileti yoktu, sözcüklerdendi evren

Her sözcük dilediği anlamı edinirdi

Gül kul olabilirdi, ses sus, sazlar susardı

Ay turuncu doğardı düş kentin üzerine

Işıklar yol boyunda ay olmayı isterdi

Gürüldeyen taşıtlar usul olalım derdi

Gelir kara bulutlar, ışıkları budardı

Çıkar yükseklere ay, aklaşır, paklaşırdı

Bir uçak yaklaşırdı, kanatları iki renk

Sözcükler yanaşırdı, bumlu kamyon arkada

Seyrederdi çocuklar baştan sona merakla

Acıların kalıba dökülmesini parkta

Yoksavar şairlerin varsıl şiirleri hey

Çiçek, sofra, oyuncak, donanma fişekleri

Düştü bu düş! Düğünde sepet havası çaldı

Değil mi ki yok saymak düşsüzlüğün umarı

Değil mi ki yaşamak düşlemek ve istemek

Bez ciltli kitaplarda düşler yinelenecek', 'Bez ciltli bir kitapta kederli bir düş vardı Solgundu düş, yorulmuş, eskimiş, eprimişti Esmerdi, inceydi, tartımlı tümceleri Hiçbir ileti yo...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Yerli']::text[], 8.5, '{"poet":"Coşkun Yerli","poet_slug":"coskun-yerli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bez-ciltli-bir-kitapta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-coskun-yerli-fiudu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neydi unuttum, ama davul gibi

Gümbürtüsü hala yüreğimde...

Yanıtsızdı zaten, şimdi sorsan

Da bilemem, anlatamam sana

Gecenin kar aydınlığında

Köşe bucak saklanıp oynadığı

O tuhaf oyunu, güzelliğiyle

Beni üzen, şaşırtan, kederli

Bir parlayıştı belki de gençlik? 

Yansımanın coşkusu, tezlik, 

Büyünsün hep süreceğini sanmam

Yanıtsızdı zaten, şimdi sorsan...

Sorma, yıkılır üstüme koca bir çınar

Ölürüm, n''apayım, yok olurum', 'Neydi unuttum, ama davul gibi Gümbürtüsü hala yüreğimde... Yanıtsızdı zaten, şimdi sorsan Da bilemem, anlatamam sana Gecenin kar aydınlığınd...', ARRAY['Türk Edebiyatı','Şiir','Coşkun Yerli']::text[], 8.5, '{"poet":"Coşkun Yerli","poet_slug":"coskun-yerli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soru-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinden Ürken Bir Kediyim', 'sesinden-urken-bir-kediyim-engin-korelli-ddr0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben anamın astarlı elbisesiyim

Her ikindi yıkadığı

Kovayla suladığı sokak gibiyim

Tozumu almaya inmese de kimse

Parke taşlı yollara dadanan bir deliyim

Ben anamın sigara dumanıyım

Her an vazgeçmek istese de

Dudağından düşürmediği bir tel

Her an onu dudaklarına götüren bir el

Ölürse ben ne ed''eyim

Ben anamın günlük gaz''tesiyim

Her gün okuduğu haberlerde bir kadın

Aşk uğruna kocasını aldatan

Evini yuvasını bırakan

Mahkemeye tek delilim

Ben anamın ölmüş kocasıyım

Şalvarını taktığımda babamın

Beyaz takkesini geçirince odama

Sesinden ürken kediyim', 'Ben anamın astarlı elbisesiyim Her ikindi yıkadığı Kovayla suladığı sokak gibiyim Tozumu almaya inmese de kimse Parke taşlı yollara dadanan ...', ARRAY['Türk Edebiyatı','Şiir','Engin Korelli']::text[], 8.5, '{"poet":"Engin Korelli","poet_slug":"engin-korelli","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sesinden-urken-bir-kediyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Su', 'yorgun-su-ergin-sander-yhi9p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sisli aynasında bir yorgun suyun

Bulanık dargın güneşlere doğru

Uzardı saçları onun ve sonsuzun

O kalabalık sularında akşamın

Puslu yeşil sessiz ve ıslak

Bir dal eğilirdi gözlerinin göğüne

Bir dal ve milyonla yaprak

Kuşlar uçardı kiremit denizlerden

O kalabalık sularda akşamın

Çocuk yüzlü bir utançla içe dönük

Hep kayıp anahtarını arardı kapısının

Sonra bir kapı kapanırdı yankısız

Sis onu örterdi usluca

Bir çiçeği örter gibi kar

İnce bir okşayışla uzun uzun

Ve değerken nice sular dudaklarına batının

Uzardı saçları onun ve sonsuzun', 'Sisli aynasında bir yorgun suyun Bulanık dargın güneşlere doğru Uzardı saçları onun ve sonsuzun O kalabalık sularında akşamın Puslu yeşil se...', ARRAY['Türk Edebiyatı','Şiir','Ergin Sander']::text[], 8.5, '{"poet":"Ergin Sander","poet_slug":"ergin-sander","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yorgun-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neon Güneş', 'neon-gunes-ergin-yildiz-v04zl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyaz neon bir akşam güneşi

taşmış kanalizasyon kıvamında bir trafik

ve yeni, yeni başlayan tereddütlü yağmur

buğulanmış camın üzerinde oyun oynuyorlar

denize, gökyüzüne dair, günaha ve melankoliye...

	-Bir Jacobean trajedi bu, 

		herkes ölüyor, kimse kaldıramıyor geriye-

Lokantanın yanındaki boş arsada

kör bir adam denize doğru yürürken.

Uzun; ama çok uzun bir zamandır çiğniyorduk bu lokmaları

çok iyi biliyorduk, çoktan gelmişti kalkma zamanı.

Beyaz örtünün üzerine saçılmış sözcükleri toplamaya çalıştık

bütün bir öğleden sonra. İsteksizdik...

Aramızda büyüyen boşlukta kaybolup gittiler! 

Şimdi havada ağır bir sessizlik.

Tabii, bir de çatal - bıçak sesleri.

Benim tabağımda giderek soğuyan palamut cesedi...

	-Uzun sürmüş bir saplantıya ilişkindi-

Onun gözlerinde koyu bir sis inerken üzerimize, 

deniz griyeşil ve hayra yorulamayacak kadar sakindi.', 'Beyaz neon bir akşam güneşi taşmış kanalizasyon kıvamında bir trafik ve yeni, yeni başlayan tereddütlü yağmur buğulanmış camın üzerinde oyun...', ARRAY['Türk Edebiyatı','Şiir','Ergin Yıldız']::text[], 8.5, '{"poet":"Ergin Yıldız","poet_slug":"ergin-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neon-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Vuran Gölge', 'uzun-vuran-golge-gultekin-samanoglu-52ck5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çağrılı gülücükle gelecek değildi ya, 

İşte kasımpatılar, işte el titremesi; 

Ve kalbimdeki dolup boşalmalar, depremler.

Uzaklarda sanılan yarım yüzyıl geldi ya: 

Artık kolay olmuyor, ''akşam olsun'' demesi...

Duygu meleyen kuzum, kuzulamaya durmuş.

Gülüşünü sularla bir tuttuğu yaramaz, 

''Bir''ken, ''iki'' olmanın yol ayrımında yorgun.

Ne bu tedirginliğim, gölge uzun mu vurmuş

Yollarına ömrümün; ellerim durduramaz.

Bu eller kaç günahın, kaç sevabın sahibi? 

Kalem tutan, el tutan, ara sıra gül tutan; 

Dikeni kanatsa da, ille gül, ille de gül.

Bir de üstüme yağan sevgiler, yağmur gibi: 

Yaşamayı sevdiren, ben böyle avutan...', 'Çağrılı gülücükle gelecek değildi ya,  İşte kasımpatılar, işte el titremesi;  Ve kalbimdeki dolup boşalmalar, depremler. Uzaklarda sanılan y...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Samanoğlu']::text[], 8.5, '{"poet":"Gültekin Samanoğlu","poet_slug":"gultekin-samanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzun-vuran-golge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbin Kara Lekesi', 'kalbin-kara-lekesi-mehmet-mumtaz-tuzcu-tbq1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yabanıl bir açılış içine çeker seni

Kaygan kalleş dilini ağzında dolaştırır

Acıtan bir doyuma ulaştırır enseni

Sayrıl dönekliğini aşılarken yüreğe

Sürtüğünün kokusu ayaklandırır onu

Sürdüğünün korkusu unutulur böylece

Yapma bir ışık diker sürgünün karşısına

Körpe yeşermeleri bir çekmeye kilitler

Sever itlere doğru itler itelemeyi

Karanlık tükrüğüyle yamar durur geceyi

Tek heceyi esirger tamamlanmışsa keyfi

Mevsimlik kopuğunu gezdirirken yanında

Yapışkan yırtıklığı yırtıksız bir dokuyla

Dengelemeye durur ipek köpek altında

Ünlü bir yünlü kumaş örter örekesini

Dilardının çift çatallı bezini

Kuştüyü sözcüklere sarar aşkı sorarken', 'Yabanıl bir açılış içine çeker seni Kaygan kalleş dilini ağzında dolaştırır Acıtan bir doyuma ulaştırır enseni Sayrıl dönekliğini aşılarken ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mümtaz Tuzcu']::text[], 8.5, '{"poet":"Mehmet Mümtaz Tuzcu","poet_slug":"mehmet-mumtaz-tuzcu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbin-kara-lekesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annanenin Ölümü', 'annanenin-olumu-nazmi-agil-ykbyo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tuzluktan boşalan beyaz

taneciklerin resmini kafamda taşıyarak

gidiyorum telefona: 

almacın deliklerinden toz

olup akıyor kardeşinin acı dolu sesi

aydınlık pazar sabahımıza.

Hiçbir şey sormuyorsun kahvaltı boyunca, 

kirazların arasındaki

çürük bir yenidünyayı ayıklayıp

çöpe atarken ağlıyorsun, biliyorum.

Eriyip avcuma yapışıyor

bıçağın plastik sapı: 

Söz, sayrılı bir baş gibi

güm güm vuruyor kendini

susuşumun duvarlarına.', 'Tuzluktan boşalan beyaz taneciklerin resmini kafamda taşıyarak gidiyorum telefona:  almacın deliklerinden toz olup akıyor kardeşinin acı dol...', ARRAY['Türk Edebiyatı','Şiir','Nazmi Ağıl']::text[], 8.5, '{"poet":"Nazmi Ağıl","poet_slug":"nazmi-agil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/annanenin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıma Sokulan Su', 'yanima-sokulan-su-muzaffer-kale-lu52o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sönmekte olan bir ateşi dinlerken yanıma sokulan su, 

Ürperecek ne var bunda, zaman gülünç gözkapaklarını

kapatıyor. Ellerim yokmuş gibi, üç gün üç gece dalgın

dolaşabilirim şimdi, 

Su seslerine yakın

Su seslerinden uzak, meyilli

ve

gülümseyen.

Ağaçlar yapraklarını öteye bir yerlere döküyorlar

gibime geliyor sonyaz olunca, nerdeyse eski bir

unutkanlıkla gülümsüyorum sabahların oluş biçimine, 

İyileşmez bir sarıya yakalanıyor tasam

ve

kendi kendime uzunca konuşuyorum.

Sönmekte olan bir ateşi dinlerken yanıma sokulan su

Yerime geç

Yerime geç

Yerime geç

Sana açtım bedenimi unutulmuş bu sarnıca dol.

Ben öldüğüm zaman siz benim nerede gömülü

olduğumu düşünürsünüz, yolunuz asmalı bir kente

düşerse. Her ağladığım yerde gömülüyümdür. Her

güldüğüm yerde dışarı taşmıştır hiç yaşamamış

bir Cumhuriyet

ve

kehanet yangına tırmanır aklım başımda niye kalsın.', 'Sönmekte olan bir ateşi dinlerken yanıma sokulan su,  Ürperecek ne var bunda, zaman gülünç gözkapaklarını kapatıyor. Ellerim yokmuş gibi, üç...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Kale']::text[], 8.5, '{"poet":"Muzaffer Kale","poet_slug":"muzaffer-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yanima-sokulan-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirimiz', 'siirimiz-mehmet-kiyat-gw7en', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki kere iki dört

Bizi

Şiirimiz kurtaracak sonunda

Dağlara

Dağlara vuracak ışığımız

Sevinçle

Kolkola çıkacağız bu yokuşları

Genç kanımızda

Yeni umutlar çoğalacak

Bizi

Direnç kurtaracak sonunda', 'İki kere iki dört Bizi Şiirimiz kurtaracak sonunda Dağlara Dağlara vuracak ışığımız Sevinçle Kolkola çıkacağız bu yokuşları Genç kanımızda Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyat']::text[], 8.5, '{"poet":"Mehmet Kıyat","poet_slug":"mehmet-kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siirimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-mehmet-kiyat-4fdkk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşümüzün kaçak oyuncağı

Beklemekle tükenmeyen gökyüzü

Sağıla sağıla bitmeyen sabah

Narçiçeği şafağı günlerin

Yaşamak ah yaşamak

Ölüm iki adım ötemizde unutma', 'Düşümüzün kaçak oyuncağı Beklemekle tükenmeyen gökyüzü Sağıla sağıla bitmeyen sabah Narçiçeği şafağı günlerin Yaşamak ah yaşamak Ölüm iki ad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kıyat']::text[], 8.5, '{"poet":"Mehmet Kıyat","poet_slug":"mehmet-kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olum-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çapak Öyküsü', 'bir-capak-oykusu-mehmet-mufit-nh3sv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurlu bir gündü abi yağmurlu bir gün

ilkyazdan

bir çapak fırladı torna tezgahından

ağır çekiminde gözlerimin

	ilkten küçücüktü çapak

	kekik kokulu bir oda

	geliyordu gözlere gözlere

	büyüdü çapak sonra

	hediyelerden portakal kolonya

	geliyordu gözlere gözlere

yağmurlu bir gündü abi yağmurlu bir gün

kapandı gözlerim', 'yağmurlu bir gündü abi yağmurlu bir gün ilkyazdan bir çapak fırladı torna tezgahından ağır çekiminde gözlerimin 	ilkten küçücüktü çapak 	kek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Müfit']::text[], 8.5, '{"poet":"Mehmet Müfit","poet_slug":"mehmet-mufit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-capak-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarışın Fatih', 'sarisin-fatih-mehmet-mufit-xqjyt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şöyle bir aralıyorum yağmurun perdesini, mis gibi

istanbul soyunuyor kollarımda, artık dayanamam

fırlıyorum sokaklara, kirpiklerimde bir damla

tıkanır gibiyim, çatlar gibi... kızaran bir şey var, 

bir şey var alnımın ortasında.

kirpiklerimde on damla

gümüş kakmalı bir çılgınlık mı bu, ince bir

raslantı mı atlaslara işli, yoksa ayasofya''ya sinmiş

cüce bir papazın ihaneti mi.

kirpiklerimde yüz damla

yüz damla çarşaflara, sakallara tuğralara

sancaklara yüz damla. nasıl da doğmuştu

sarışın fatih! .. ve o görkemli atının üstünde

haliçle birlik, altından resmimi çekti.

hayret, işaret parmağımda eridi bizans

bizans kırmızı bir gül oldu, 

kaypak bir gül bizans.

upuzun kesiksiz bir gül.

ayyaş ve tedirgin bir gül.

çektikçe soluğuma değecek

değdikçe gözlerim dönecek

işte öyle bir gül. kirpiklerimde bin damla

bin damla kirpiklerimde... ey kurnaz, ey akşamla

kuşatılmış inatçı sultan! şu hengame, şu cümbüş...

sarsılsın gül, morarsın, düşsün: buz gibi

gerilsin ayaklarında. ite kaka yer açıyorum

yer açıyorum, bir gül de karanlık sulara.', 'şöyle bir aralıyorum yağmurun perdesini, mis gibi istanbul soyunuyor kollarımda, artık dayanamam fırlıyorum sokaklara, kirpiklerimde bir dam...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Müfit']::text[], 8.5, '{"poet":"Mehmet Müfit","poet_slug":"mehmet-mufit","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sarisin-fatih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toparlama', 'toparlama-halil-i-brahim-bahar-a5iky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aradığım ırmak serinliği

yağmurdan güneşe çıkmışsın

buğular yükseliyor

kapkara saçlarından

şimdi güzelce yanmak için

kucaklaşmak isterim seninle

kurusun bir dala as

rüzgar çalmaz giysilerini', 'aradığım ırmak serinliği yağmurdan güneşe çıkmışsın buğular yükseliyor kapkara saçlarından şimdi güzelce yanmak için kucaklaşmak isterim sen...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Bahar']::text[], 8.5, '{"poet":"Halil İbrahim Bahar","poet_slug":"halil-i-brahim-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/toparlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Araştırı', 'arastiri-halil-i-brahim-bahar-hsbus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gelincikler söylemine geçelim

daha ortada yok buğdaylar çavdarlar

ama olsun masamızda ödünsüz

sürüyor nisan söyleşileri

varsa bir karmaşıklık nereden doğuyor

içinizden sorun geldiğiniz ırmağa

giysileriniz kurumadan

aşk kırmızıya mı yakın duruyor

gündüze geceye uygun

bir çağıltı bir eşsiz müzik

biraz anlam kaymalarıyla yeşile mi diyelim

dersek ipe gidecek düşünsün bunu

sabaha karşıyken saatler

kırmızıdan olanlar ayağa kalksın

gördüm başınız göğe eriyor

doruktaki karsuları gibi

yeşildenciler dışa tomurcuk yüreğinizle

baştan sona kaç yıllık çevrecisiniz

söz isteyen var mı yok

sonuç ortada aşk yeni bir yorum istiyor

öpüşmenin tadı kalmadı

kuşluğa doğru kırlara çıkalım

görelim nasılmış yansımalı uçuşu

kozadan çıkan ilk kelebeğin', 'gelincikler söylemine geçelim daha ortada yok buğdaylar çavdarlar ama olsun masamızda ödünsüz sürüyor nisan söyleşileri varsa bir karmaşıklı...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Bahar']::text[], 8.5, '{"poet":"Halil İbrahim Bahar","poet_slug":"halil-i-brahim-bahar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/arastiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış', 'yanlis-alaeddin-asna-0ix4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne varsa gözlerinden bileceğim

yeşil mi duman duman bebekleri

uzanır mı bir eski yalnızlığa

gözlerin boş! 

Ne varsa ellerin söyliyecek

duyar mı damar damar dokunduğumu

taşır mı akşam anılarını avuçlarında

ellerin soğuk...

Ne varsa dudaklarından duyacağım

titrer mi alaca karanlıkta

büyür mü öpülesi sarhoşluğunda gecelerin

dudakların ıslak.

Ne varsa sen anlatacaksın

neden yaşamımız bu kadar mutsuz

yalnızlık neden bu kadar güzel

yüreğin yanlış! ..', 'Ne varsa gözlerinden bileceğim yeşil mi duman duman bebekleri uzanır mı bir eski yalnızlığa gözlerin boş!  Ne varsa ellerin söyliyecek duyar...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin Asna']::text[], 8.5, '{"poet":"Alaeddin Asna","poet_slug":"alaeddin-asna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanlis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemici', 'gemici-alaeddin-asna-zyv3f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O mutsuz bir gemicidir

yanlış bir okyanusa yelken açmıştır

uzanır halatların dibine arada bir

güçsüz yumruklarıyla usulca gözlerini siler

nedenini bilmez.

Yalnız bir yaşantıya ıslık çalar

güneşin doğuşunu gördüğünde sabahları

denizin ta ucundadır aydınlık

ulaşamıyacağını bilir

nedenini bilmez.

Hiçbirşey dilemeden yaşamıştır

amaçsız -türküsüz-dostsuz-ışıksız

bir gün çekip gidecektir bu evrenden

kendiyle oturup içmiştir geceler boyu

nedenini bilmez.', 'O mutsuz bir gemicidir yanlış bir okyanusa yelken açmıştır uzanır halatların dibine arada bir güçsüz yumruklarıyla usulca gözlerini siler ne...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin Asna']::text[], 8.5, '{"poet":"Alaeddin Asna","poet_slug":"alaeddin-asna","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gemici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene', 'gidene-sema-gokcen-e4kv4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git gözümün alası

Git elimin kınası 

Gidişin kurtuluşudur bu ülkenin

Yükünü hazırladım bak...

Irgat MEMO''nun alın teri

İşçi RECEP''in nasırlı eli

ZEYNEP Çocuğun yalın ayağı

AL bu da MADENCİNİN kara gözleri

Yüreğin mavzer omzunda

Sevdalar mor nakışlı bir kilim

VAR dağların yücesine 

Vur zalimin gecesine 

Var dağların yücasine vur zalimin GECESİNE

Git gözümün alası 

Git elimin kınası

Gidişin

ÖZGÜRLÜĞÜDÜR 

Bu ülkenin', 'Git gözümün alası Git elimin kınası  Gidişin kurtuluşudur bu ülkenin Yükünü hazırladım bak... Irgat MEMO''nun alın teri İşçi RECEP''in nasırlı...', ARRAY['Türk Edebiyatı','Şiir','Sema Gökçen']::text[], 8.5, '{"poet":"Sema Gökçen","poet_slug":"sema-gokcen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidene-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşparmak Melodileri', 'besparmak-melodileri-osman-turkay-so1zn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yaz gününün bu eşref saatinde

Yeşil çamlar

	Yalçın kayalar

		Başdöndürücü uçurumlar

Kaleler

            Şatolar

	  Saraylar

Kıvrımlı asfalt yollar

Ağaçlar

             Pınarlar

                          Serin sular

Akıp gitmede rüyalarımdan

Şarkılarını dinliyorum cüce beşparmak! 

Şarkılarını dinliyorum binlerce kilometre uzakta

Taymis''in süt mavi sisleri ortasında

Evrensel sevgi, ümit ve gerçekten

Beş bin müzik yılı sonra gelecekten

Koparıp zevkimize armağan ettiklerin: 

Defne kokan, laden kokan bestelerin

Öyle renkli, öyle candan, öyle derin

Ezgilerin, sezgilerin, çizgilerin

Senin.', 'Bir yaz gününün bu eşref saatinde Yeşil çamlar 	Yalçın kayalar 		Başdöndürücü uçurumlar Kaleler             Şatolar 	  Saraylar Kıvrımlı asf...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkay']::text[], 8.5, '{"poet":"Osman Türkay","poet_slug":"osman-turkay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/besparmak-melodileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar ve İnsanlar', 'kuslar-ve-i-nsanlar-mustafa-necati-karaer-5qyem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-I-

Evler ve insanlar çıkmazında

Gidip gelen evsiz-ayaksız sesler, 

Duvardan duvara evden eve.

Ödünç diye bir şey vardı eskiden; 

Komşular, bir fincan aydınlık için

Ne dersiniz bir fincan acı kahve? 

Beyazıt''ta müslüman güvercinler

Kanat vurdukça sıcak zamanlara, 

Bir şadırvanda serinler gökkubbe.

Kuşluklar ve kuşlar pazarına

Bir Selçuklu gelir uzaklardan

Bir Osmanlı geçer omzunda yün heybe? 

Sabah sularıdır, şu yelkenliden

Bakarsınız Nilüfer hatun çıkar, 

Aşka düşersiniz bir selam üzre.

Yağmurla yıkanan serçe yürek

Kır atın üstüne bir Orhan Bey''dir, 

Uçar güneşlerden güneşlere.

-II-

Üzerinde ince badem dalları

Evimiz çok pencereli bir kuşluk, 

Ne cam ne çerçeve.

Rüzgar kaplı bir yorgan altında

En güzel yerinde ısınmak senin, 

Badem gözlerini seve seve.

Yan yana dizilmiş yüzlerce ayna

İçinde mum gibi dimdik kıskançlık, 

Yalınayak basar ateşlere.

Kanat uçları mı ellerin mi, 

Beni benden alıp alıp götüren

Ulu acıların çıktığı yere? 

Camlar kırıldıkça nasıl yeniden

Verirse içinin maviliğini, 

Kendimi vermişim öylesine.

İki yeşil kadeh bıraktın bana, 

İçmeye yeniden başladım iyi mi

Sevdalı kuşların şerefine.', '-I- Evler ve insanlar çıkmazında Gidip gelen evsiz-ayaksız sesler,  Duvardan duvara evden eve. Ödünç diye bir şey vardı eskiden;  Komşular, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Necati Karaer']::text[], 8.5, '{"poet":"Mustafa Necati Karaer","poet_slug":"mustafa-necati-karaer","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kuslar-ve-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temsil Edilmeyen''e', 'temsil-edilmeyen-e-mustafa-irgat-nur4b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soluğunu aileden birinin soluğunda duyduğuydu, 

anısı ten kimya ve katran safran meleği uç-uç; 

günü toz içre kaydırılan toprak tabut, -yönü

havzapol yerine geçmiş kuyruklu bir külyıldız

estikçe denizi yağan revnağa, yürü ya kulu''m

Arrrzuuuuuu tüneli açıkken çünkü, kurum es''inde

birbirini kesenlerden aslına dönemiyordu ülkem.

ve yazıklanmanın kamburu karşı kıyıda kalmıştı; 

sırtından dolunay bir sırt izleniyordu fazladan.

Beynin sessiz bir bölgesinin adı sanki ayna, 

katı bir tabaka, kendini dümdüz aşırtmış

sayıyla kendimize gelelim diye, yüz yüze.

- '' Hem ölümsüzlük ölümsüzlük söz konusu mu hala? ''', 'Soluğunu aileden birinin soluğunda duyduğuydu,  anısı ten kimya ve katran safran meleği uç-uç;  günü toz içre kaydırılan toprak tabut, -yönü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Irgat']::text[], 8.5, '{"poet":"Mustafa Irgat","poet_slug":"mustafa-irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/temsil-edilmeyen-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelen Dalga Bir', 'gelen-dalga-bir-huseyin-atlansoy-gtu9d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ya! 

İntihar ilacı şairi geri döndü.

İçeride yapamamış. Öyle çok kişi var ki içeride

                                                    yapamayan.

Öyle ise yeni baştan

ve şöyle başlayalım.

- bir yanımız kaç duvar yurt odalarına karışmış, 

suya ölümüne hasret bornazların kapladığı, yazlık

sinemalarda sessizliğe çıt-çıt iliklenen ayçekirdek-

lerinin alışkanlığında, kedi çöplüklerine aldırmayan, 

kendini yeni erenlere ısmarlamış, 

                                    çocuk-seni çocuk

- seni ''bile'' çok seviyorum

/O çocuğa spor ayakkabıları bir başlangıçtır

Üstüne savrulan büyü suları gelen dalga bir/sonuç.

Ve tekrar geriye dönelim

- bir yanımız yere düşen yağmur damlacıkları

                                              arasında delilikte

inat edebilirse bilgeliğe erişecek

- bir yanımız dumanlarını denize vuran

                                       yangınlarda, ve o deniz

canlıdır lütfen çöp atmayınız.

- bir yanımız yitip yitip büyüyen güneş, büyü

                                                  sahibi gece

- bizim kaç yanımız var? 

Ve tekrar hoşbulduk insanlar. hoşbulduk tahammül

hoş gidişler ola deseniz de siz sayın ölüm; 

                                                            hoşbulduk', 'Ya!  İntihar ilacı şairi geri döndü. İçeride yapamamış. Öyle çok kişi var ki içeride                                                     yap...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atlansoy']::text[], 8.5, '{"poet":"Hüseyin Atlansoy","poet_slug":"huseyin-atlansoy","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gelen-dalga-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halkımızın Gelini', 'halkimizin-gelini-savas-ezgi-x4a0f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Halkımızın gelini

Kınalamış elini 

Haydi halay çekelim 

Zılgıtlar sarsın bizi

İdil can çiçek olmuş 

Toprak ona tutunmuş

Hasreti vatan olmuş

Kavgasına tutulmuş

Mitralyöz Mitralyöz 

Halay başı MİTRALYÖZ

Zafer bizim olacak 

CAN YOLDAŞIM sana SÖZ

HALKIMIZ KAZANACAK

Can YOLDAŞIM sana SÖZ

Vur ha vur ha vur ha vur

Mitralyözle vur ha vur

Sevdamız kurşun olsun 

Zulmün üstüne yağdır', 'Halkımızın gelini Kınalamış elini  Haydi halay çekelim  Zılgıtlar sarsın bizi İdil can çiçek olmuş  Toprak ona tutunmuş Hasreti vatan olmuş ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/halkimizin-gelini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Voltada Söylenen Türkü', 'voltada-soylenen-turku-savas-ezgi-9lef9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarim salmış efkarını maphusa

Kendisi gelmez acep yollar kışmıdır

Kendisi gelmez yollar kışmı

Hasret başını eğermiş adamın

Maphustan kalkan uzun bir havayım şimdi

Maphustan kalkan uzun bir hava', 'Yarim salmış efkarını maphusa Kendisi gelmez acep yollar kışmıdır Kendisi gelmez yollar kışmı Hasret başını eğermiş adamın Maphustan kalkan ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/voltada-soylenen-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açlığın Yürüyüşü', 'acligin-yuruyusu-savas-ezgi-iz324', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fırtına olanlara rüzgar neylesin

Günü doğuranlara gece neylesin

Yüreği bir olanlar

Yürüyoruz zafere

Paylaştıkça çoğalan

Bu sevda bizim

ONUR NAMUS ADALET

BU SEVDA BİZİM', 'Fırtına olanlara rüzgar neylesin Günü doğuranlara gece neylesin Yüreği bir olanlar Yürüyoruz zafere Paylaştıkça çoğalan Bu sevda bizim ONUR ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/acligin-yuruyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Buca Olmuştu', 'vatan-buca-olmustu-savas-ezgi-d507x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eylül zamanı çatlamış tohum

Yangını dalından taşmış KIZIL güllerin

Seslerini bırakıp barikatlara

Çığlık olup saplandılar suskunluğa

ÜÇ YÜREKLE DOĞRULDUK ÖZGÜRLÜKLERE

YILDIZ YILDIZ UMUDU YAZDIK GÖKLERE

Duvar boylarında sıralanmışlar

Türkünün sıcağına toplanmış otururlar

Göz kapaklarına dek sokulan ölüm

Teslim alamadı SEVDALARINI', 'Eylül zamanı çatlamış tohum Yangını dalından taşmış KIZIL güllerin Seslerini bırakıp barikatlara Çığlık olup saplandılar suskunluğa ÜÇ YÜREK...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vatan-buca-olmustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümraniyedeydi İlginç', 'umraniyedeydi-i-lginc-savas-ezgi-wheil', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EY İSTANBUL bu kaçıncı yiğittir

Sevdanın yolunu zafer eyleyen

Maphuslardan taşan gökyüzüyüz biz

Teslim olmaz ÖZGÜR TUTSAKLARIZ BİZ

MACİT RIZA ORHAN GÜLTEKİNİZ BİZ', 'EY İSTANBUL bu kaçıncı yiğittir Sevdanın yolunu zafer eyleyen Maphuslardan taşan gökyüzüyüz biz Teslim olmaz ÖZGÜR TUTSAKLARIZ BİZ MACİT RIZ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umraniyedeydi-ilginc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nurhak''a Özlem', 'nurhak-a-ozlem-savas-ezgi-in4dn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nurhak Dağları

Sistir dumandır buzuldur

Rüzgar dokunsa yırtılır canım

Keskin sivridir laciverti kayaları

Hasreti: KILDAN İNCE

Sevdası: ATOMDAN AĞIR

Gözleri yüreğinin ardına düşmüş 

YANİ SEVDASI BAŞINDA...', 'Nurhak Dağları Sistir dumandır buzuldur Rüzgar dokunsa yırtılır canım Keskin sivridir laciverti kayaları Hasreti: KILDAN İNCE Sevdası: ATOMD...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nurhak-a-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aygün''ün Vasiyet', 'aygun-un-vasiyet-savas-ezgi-rz5tb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mezarımı yüksek yapın

Yar gelende gölgelene

Yitirsem de ben bu canımı

El yanında göğsün geçirme', 'Mezarımı yüksek yapın Yar gelende gölgelene Yitirsem de ben bu canımı El yanında göğsün geçirme...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aygun-un-vasiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Görüş Kabininde', 'bir-gorus-kabininde-savas-ezgi-9mubz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ANNE: Ne kadar da ufalmış bedenin göz yaşıma sığdın sen açlık mı yemiş ömrünü yavrum al sütümü iç kızım

KIZ: Saçların beyazına mı sakladın alevini yoksa güneş sen de mi batıyor batıyor geceleri

KIZ: Eriyen bedeni mi düşünme göğü giydim üstüme yüzünü asma keder ilen ah anam YİĞİTLER BİTMEZ BİZDE

ANNE: Bir alev olup yaksa da gidişin hiç analar biter mi ölüm toplasa da çiçekleri ÇİÇEKTE TOHUM BİTER Mİ?', 'ANNE: Ne kadar da ufalmış bedenin göz yaşıma sığdın sen açlık mı yemiş ömrünü yavrum al sütümü iç kızım KIZ: Saçların beyazına mı sakladın a...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gorus-kabininde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tedariği Hazırla', 'tedarigi-hazirla-savas-ezgi-jhq0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zindan alacaklarını topluyor

Borcum yok 

Bozdurdum ömrümü

Gençliğim düştü payıma 

TEDARİĞİ HAZIRLA

Olur ya olur ya 

DÜŞERİM SENDEN AYRI', 'Zindan alacaklarını topluyor Borcum yok  Bozdurdum ömrümü Gençliğim düştü payıma  TEDARİĞİ HAZIRLA Olur ya olur ya  DÜŞERİM SENDEN AYRI...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tedarigi-hazirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onurumsun', 'onurumsun-savas-ezgi-8te6q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dört duvar dönerim

Kaç gecedir yoksun oğul

Bıçak bilenir etimde

Başında toprak beton mu oğul

Bin yıl yatarım sevdana

Onurumsun susmam oğul

Yüreğim kopmuş geliyor

Devrime kadar düşmem oğul

Yere göğe koymazdım seni

Çaldılar dalımdan oğul

Ecelin öne alınmış

Olanca canım sana aksın oğul', 'Dört duvar dönerim Kaç gecedir yoksun oğul Bıçak bilenir etimde Başında toprak beton mu oğul Bin yıl yatarım sevdana Onurumsun susmam oğul Y...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onurumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gözüm(Herdu Çawe Min)', 'i-ki-gozum-herdu-cawe-min-savas-ezgi-43yll', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yolları tutmuşlar gelemiyorum ah gelemiyorum

Sen yanımda yoksun

Günüm uzakta karanlık 

Ah yüreğim 

İki gözümün arkadaşı

Ben ateşim

Yüreklerin ateşi

Sen iki gözümün kır çiçeği

Yapayalnızdır sevdiğim ah sevdiğim

Ellerin bana yasak olsun 

ÖZGÜRLÜK GÜNÜNE kadar 

Yüreği yaralı ülkem

Ellerin bana yasak olsun

ÖZGÜRLÜK GÜNÜNE KADAR', 'Yolları tutmuşlar gelemiyorum ah gelemiyorum Sen yanımda yoksun Günüm uzakta karanlık  Ah yüreğim  İki gözümün arkadaşı Ben ateşim Yürekleri...', ARRAY['Türk Edebiyatı','Şiir','Savaş Ezgi']::text[], 8.5, '{"poet":"Savaş Ezgi","poet_slug":"savas-ezgi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iki-gozum-herdu-cawe-min-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Munzur', 'baba-munzur-ahmet-can-akyol-rh7fx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarp kayalar kara bağlar

Feryada düşer zılgıtlar

O dağlar ki serin ağlar 

BABA MUNZUR /MUNZUR diye

Lokmalar niyaz edilir

Cem olur bade içilir

Hem söylenir hem dinlenir

BABA MUNZUR / MUNZUR diye

Bin yaram var sağ ederim 

Göç olsam da ben yine benim

Elbette bir gün dönerim 

BABA MUNZUR / MUNZUR diye

Gözelerde ikrarım var

Ata dede ocağım var

Secereler böyle yazar

BABA MUNZUR / MUNZUR diye

Daim sohbetler edelir

Aşk bilinir yol gidilir

Can olana el verilir

BABA MUNZUR / MUNZUR diye', 'Sarp kayalar kara bağlar Feryada düşer zılgıtlar O dağlar ki serin ağlar  BABA MUNZUR /MUNZUR diye Lokmalar niyaz edilir Cem olur bade içili...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baba-munzur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Munzur''un Kızı', 'munzur-un-kizi-ahmet-can-akyol-0d2wo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir acı ki bu

Kın değil kılıç değil

Dokundukça sızlıyor

Aklımda yar belası

Matemim

Uslanmaz hasretim

Gurbetim Munzur''un kızı

Uzaklar da mı kaldın

Kış gibi hasatsız derin

Ve düş gibi delice ve selin

Peki kim söyleyebilir şimdi kim

Bu vurgunca yanmak bu uğultuca kanamak kimin

Hani MUNZUR''un KIZI hani rüzgarlarımız vardı bizim

Doğruca esen yürekler büyüten mevsimlerimiz

Sözümüze ne oldu kurban olduğum 

Neler oldu yeminlerimize

Hadi / yine saçlarını yellere ver

Fırtına olsun getirsin seni

Tenimi ver / kokumu / ne olursun

Artık bu özlem bu ateş ve zulüm

Ama sensizlik yok mu / sensizlik cehennemden de ölüm

Biliyorum şimdi haykırsam bütün sesleri

Hiçbir söz seni bana getirmez belki

Belki yaşadıklarımız da bilinmez

Işığında ağlaştığımız ay''lı geceler de 

Vay MUNZUR''UN KIZI

Vay çilelim / kırçiçeğim / hasretim vay

Sen dur / Munzur aşkına dur / ne olursun dur

Dur da birlikte ölelim

Öyle bir yara ki bu

Çığ değil çığlık değil

Damladıkça yakıyor

İçimde kan deryası

Matemim / uslanmaz hasretim

Gurbetim Munzur''un Kızı', 'Öyle bir acı ki bu Kın değil kılıç değil Dokundukça sızlıyor Aklımda yar belası Matemim Uslanmaz hasretim Gurbetim Munzur''un kızı Uzaklar da...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/munzur-un-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-ahmet-can-akyol-l2c3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söz dönüşür körpe diller seslenir

Ses üşüşür düşen damla göllenir

Gün döllenir karaların bağrında

Gelir zaman al şafaklar güllenir

İklim döner güneş taşır alınlar

Emeklenir tez canlanır yarınlar

Bir sevdadır sabahlara sunulan

Çağrı duyar parçalanır sınırlar

Bul kendini öz benliğin beslensin

Ver elini yeni çağlar renklensin

MERHABA merhaba MERHABA de 

Şah damarımı bul benim

MERHABA de hayat kanım ol benim', 'Söz dönüşür körpe diller seslenir Ses üşüşür düşen damla göllenir Gün döllenir karaların bağrında Gelir zaman al şafaklar güllenir İklim dön...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/merhaba-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandım Allah''ım Yandım', 'yandim-allah-im-yandim-hulya-senkul-5p1sh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Harcanan yıllarımda

Umutlarım ağlıyor

Çaresizlik zinciri

Kollarımı bağlıyor

O vefasız haline

Bilmem ki nasıl kandım

Ateşe attı beni

Yandım Allah''ım yandım

Sevinçlerim gözlerimde

Damla damla yaş oldu

Kan doğradı içime

Seven kalbi taş oldu

O yalancı, haini

Aşka inanır sandım

Ateşe attı beni

Yandım Allah''ım yandım', 'Harcanan yıllarımda Umutlarım ağlıyor Çaresizlik zinciri Kollarımı bağlıyor O vefasız haline Bilmem ki nasıl kandım Ateşe attı beni Yandım A...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yandim-allah-im-yandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Sokaklar', 'karanlik-sokaklar-tahir-paker-2ek3u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkımda bir deli rüzgar

Alır beni savurur

İşte o an dudağımdan

Bir feryattır duyulur

Bu karanlık sokaklar

Benden sorulur benden

Yanımda yalnızlıklar

Bir de hayalimde sen

Her gün böyleyim işte

Ben mahkum, aşk kalepçe

Gözyaşlarım dinmez inan

Sen bana dönmedikçe

Yıldızlarla konuşurum

Her gün sabahlara kadar

Hasret dolu bu günlerim

Her köşede seni arar', 'Aşkımda bir deli rüzgar Alır beni savurur İşte o an dudağımdan Bir feryattır duyulur Bu karanlık sokaklar Benden sorulur benden Yanımda yaln...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlik-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bilsinler', 'nerden-bilsinler-gonul-sen-1pohe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni ben bir anda terkedeyim de

Varsın da adıma kalpsiz desinler

Mutlu göründük bütün gözlere

Neler çektiğimi nerden bilsinler

Kime dert yanarsan yan benim için

Farketmez ardımdan zalim desinler

Her zaman bilirsin haklı çıkmayı

Suçlu olduğunu nerden bilsinler

Kalbime akıttın gözyaşlarımı

Dışıma vurmadım acılarımı

Bundan sonra artık umurumda mı

Sana haklı, bana haksız desinler', 'Seni ben bir anda terkedeyim de Varsın da adıma kalpsiz desinler Mutlu göründük bütün gözlere Neler çektiğimi nerden bilsinler Kime dert yan...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerden-bilsinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakanlar Olur', 'yakanlar-olur-sakir-askan-e7wjr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep böyle gururla gezerim sanma

Senin de boynunu bükenler olur

Her zaman ağlatıp ezerim sanma

Zulmüne karşılık verenler olur

O taştan yüreğin dağılır gider

Vefasız gözlerin birini sever

Ne gururun kalır, ne zulmün yeter

Görürsün seni de yakanlar olur

Bakmadan sevgine çok kıymet verdim

Ağlattın, kahrettin yine de sevdim

Kendini bulunmaz güzel zannettin

Seni de bırakıp gidenler olur', 'Hep böyle gururla gezerim sanma Senin de boynunu bükenler olur Her zaman ağlatıp ezerim sanma Zulmüne karşılık verenler olur O taştan yüreği...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakanlar-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marmaris''te Bir Gün', 'marmaris-te-bir-gun-sair-hakan-9yobq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhaba güneş.....

Bu gün ne güzelde aydınlatmışsınız dünyayı

Giden geceye de merhaba uykularımı geri verdiniz bana

Merhaba börekçinin şişko  kızı...

Bu gün zayıflamış görünüyorsun, sivilcelerin de kaybolmuş

Balıkçının uyuz köpeği, nasılda güzel parlıyor tüylerin

İşçi kahvesinde sabahları içtiğim çayın bu kadar lezzetli olacağını bilemezdim

Sahilden gelen deniz kokuları dünde bu kadar güzel miydiniz.? 

Selam veriyorum tanımadıklarıma bile, gülüyorlar...

Ağlamıyor bu gün nedense kuaförün küçük  kızı

İlk defa temiz görünüyor piyangocu teyzenin beyaz şapkası

Alıp onu kafasından yere atıyorum kirlensin diye....

Çılgın çocuk diye bağırıyor arkamdan.....zaten kirliydi yıkayacaktım 

İlk defa göz kırptım, kapısının önünden her sabah geçmemi bekleyen

noterci Nigar hanıma

İlk defa içtiği çayın kalanını üstüme atıyormuş gibi yapmadı.

Şaşırdı kala kaldı.

Emekli Mehmet amca nedense cebindeki paraları saymıyordu ilk defa

Mutlu gözüküyordu

Mutlu gözüküyordu maliyeden ayrılma muhtar cemil efendi tespihini çekerken

Kuyumcu Bülent bey turistlere hava olsun diye her zaman göbeğine kadar

açık bıraktığı gömleğini ilk defa iliklemişti.

Gözükmüyordu iğrenç kılları.

İlk defa turistlerin göğüs aralıklarına bakasım gelmiyordu.

İlk defa kavga etmiyordum kendimle

İlk defa bu kadar mutlu hissediyordum kendimi

İlk defa  seviyordum birini.........

İlk defa  seviyordum.......

İlk defa.........

İlk.........

                                 

                                              (Marmaris - 20,09,2002)', 'Merhaba güneş..... Bu gün ne güzelde aydınlatmışsınız dünyayı Giden geceye de merhaba uykularımı geri verdiniz bana Merhaba börekçinin şişko...', ARRAY['Türk Edebiyatı','Şiir','Şair Hakan']::text[], 8.5, '{"poet":"Şair Hakan","poet_slug":"sair-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/marmaris-te-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simitçi Dükkanı', 'simitci-dukkani-sair-hakan-5tm8e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boş bulundum seviverdim seni bir anda

Bilseydim uykuların bu kadar tatlı olduğunu

ve onlardan uzaklaşacağımı 

Bakar mıydım gözlerine hiç.

O hınzır gülüşün nasıl da kazındı belleğime

Bilseydim gülmenin bu kadar yakışacağını dudaklarına

ve onları hiç unutamayacağımı

Yarısı bitmiş simidi yer misin diye uzatır mıydım  sana  annene çaktırmadan.....

Hiç güldürür müydüm seni.

Kaçamak bakışlarını nasıl da satıverdin gözlerime bedavadan

Seni kaybettikten sonra anladım o bakışların o gülüşlerin bana pahalıya mal olduğunu

Her gün devamlı gidiyorum artık o simitçi dükkanına

Elimde yarısı yenmiş simide tam para ödeyerek seni bekliyorum

                                      Hakan - 20,09,2002', 'Boş bulundum seviverdim seni bir anda Bilseydim uykuların bu kadar tatlı olduğunu ve onlardan uzaklaşacağımı  Bakar mıydım gözlerine hiç. O ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hakan']::text[], 8.5, '{"poet":"Şair Hakan","poet_slug":"sair-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/simitci-dukkani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-sair-hakan-2x7wh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geminin limandan ayrılışı gibi gittin sessizce ve uzaklara........

Geride  sadece sahipsiz bir yürek  bıraktın bedende

Nanik yapar gibi, nispet yapar gibi fokur, fokur karşımda

Yaşanması gereken tatlı zamanların katili ayrılık

Uykusuzluğumun en güzel sebebini çaldınız benden... 

Var mı  bedende bir can  daha benim gibi sana ölesiye tutkulu

Var mı laf dinlemez ayrılık bilmez yanar yürekleri

Uyanırlar mı  yeni güne sensiz ama  umutlu 

Açar mı çiçekler güneşe, içlerinde olmazsa heyecan

Yağar mı yağmurlar telaşlı ve ıslak, kara toprağa nedensiz

Bir bebek ağlar mı, gözyaşı döker mi, yırtınırcasına  sebepsiz

Mevsimlerim bitiyor gel artık.

Belki son doğuşudur güneşin gördüğüm.

Rüzgarlara bin de gel, yağmurlarla gel, şimşek gibi çabuk gel

Sensiz başlayan günlere tahammülüm yok artık.

Ayrılığın kalbine hançer vur da gel. 

Doğma ey...  güneş,  yapma geceleri sabah, dur bekle.

Onsuz geçen gün bir daha olmayacak

Göğe uzanıp ellerim yetişse seni torbaya koyacağım

Yeni başlamadan gün, bekle biraz

Ayrılığın gözünü oyacağım.

                                                   

                                      Hakan - 12,09,2002', 'Bir geminin limandan ayrılışı gibi gittin sessizce ve uzaklara........ Geride  sadece sahipsiz bir yürek  bıraktın bedende Nanik yapar gibi,...', ARRAY['Türk Edebiyatı','Şiir','Şair Hakan']::text[], 8.5, '{"poet":"Şair Hakan","poet_slug":"sair-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayrilik-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-ceyhun-kuburlu-qpdg6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman alıp başımı gitsem bu şehirden

Otobüs camlarının buğulu nefeslerine yazarım adını

Cam kenarı hep boş kalır yüreğimin

İmkansız hayaller kurarım

Omzumda ürkek bir çocuk gibi uyur gözlerin

Gözlerim tarifsiz hüzünler taşır gözlerinde

Özlerim...Ağlarım gözlerinde...

Dönemem...Yarım kalmışım sana...

(19 Temmuz 2002)

Tekirdağ, İstanbul arası...', 'Ne zaman alıp başımı gitsem bu şehirden Otobüs camlarının buğulu nefeslerine yazarım adını Cam kenarı hep boş kalır yüreğimin İmkansız hayal...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-zaman-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyledir Sevdamız', 'boyledir-sevdamiz-ceyhun-kuburlu-pm5fc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi sevsek kanar bu yürek

Kime tutulsak bükülür belimiz

Ve ne zaman içsek hazan sonbahar akşamlarında

Ağlar soframızda bir esmer silüeti

Kimseler duymaz anlayamaz

Ve hep zehir zemberek  gezer bu yürek

Bu yalan ayrılık akşamlarında... 

(Eylül 2002)

İstanbul', 'Kimi sevsek kanar bu yürek Kime tutulsak bükülür belimiz Ve ne zaman içsek hazan sonbahar akşamlarında Ağlar soframızda bir esmer silüeti Ki...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/boyledir-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemi Güzelmiş Ayrılığın', 'ozlemi-guzelmis-ayriligin-hakan-akyurt-jdaiy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın çilesini çekmezdim amma, 

Umutla doldu yarınlar, sen varken.

Yalnızken bu yıllar geçmezdi amma, 

Her derdi aşarım artık, sen varken.

Hasretler ızdırap vermez sanmıştım, 

Özlemi güzelmiş ayrılğın sen yokken.

Yaşarken sevenler kavuşur sandım, 

Neyleyim hayatı, yanımda sen yoksan...', 'Hayatın çilesini çekmezdim amma,  Umutla doldu yarınlar, sen varken. Yalnızken bu yıllar geçmezdi amma,  Her derdi aşarım artık, sen varken....', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlemi-guzelmis-ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilim...', 'canim-sevgilim-ergun-gultekin-fejyo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nicedir gönlümü kavuran bir ateştir sevdan, 

İçin için kavrulan bir kor misali, 

Yanar sana garip yüreğim.

Susuzluğum yalnız sensin sevgilim, 

Bir başka seviyorum seni! 

Nicedir ruhumu ısıtan bir mutluluktur sevdan, 

Güneşe doyamayan bir gül misali, 

Muhtaçtır sana garip yüreğim.

Açlığım yalnız sensin sevgilim, 

Bir başka seviyorum seni! 

(Ankara - 21 Eylül 2002)', 'Nicedir gönlümü kavuran bir ateştir sevdan,  İçin için kavrulan bir kor misali,  Yanar sana garip yüreğim. Susuzluğum yalnız sensin sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Ergün Gültekin']::text[], 8.5, '{"poet":"Ergün Gültekin","poet_slug":"ergun-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canim-sevgilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamet Günü', 'kiyamet-gunu-hakan-akyurt-fhuoq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elbet sonlanacak birgün, yaşam sona erecek, 

Günah gelecek aklına, hayatının son günü..

İnecek gökkubbe yere, tüm dünya titreyecek, 

Şaşıracak insanlar, hayatın o son günü..

Ölüm gelecek kapına, çalmadan açacak, 

Ne mal kalacak ne mülk, hayatınn son günü..

Kabaracak denizler, tüm dağları aşacak, 

Kalmayacak tek insan, hayatın o son günü..

Aklın gidecek başından, kalbini donduracak, 

Alacak o canı veren, hayatının son günü..

Açılacak bütün eller, Allaha inanacak, 

Farkedecek insanlar, gelince kıyamet günü...', 'Elbet sonlanacak birgün, yaşam sona erecek,  Günah gelecek aklına, hayatının son günü.. İnecek gökkubbe yere, tüm dünya titreyecek,  Şaşırac...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiyamet-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın Olsun', 'gunaydin-olsun-fikri-coskun-9hech', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günaydın Olsun

Bir gül salayım sana

	Güllerin hası

İliştir yanağına 

  güllerdamlası

	Günaydın olsun.

Bir sabah / bir sabah

	İşe yetişmek telaşıyla

yanımdan kalksan

Bir öpücüğü alnımda

Birlikte okunmuş bir şiiri

bir de sıcaklığını

Yastığında bıraksan

Günaydın olsun.

Kaç tepe var aramızda

	Bir kanat çırpışı

İki adımlık yer

 Şunun şurasında

	      Uzanıp alsam 

Kaçırsam seni

şu güldalının altına 

	      günaydın olsun.

Bir mektup almalıyım bugün senden

		Ayrılığı yudumlayıp duruyoruz n’asolsa

Çok yanına yaklaşmasa da

	Azıcık sevgiye çalan

        O cimri sözcüklerinle

	Bana şöyle dokunsan

		Günaydın olsun.

							Mayıs’02', 'Günaydın Olsun Bir gül salayım sana 	Güllerin hası İliştir yanağına    güllerdamlası 	Günaydın olsun. Bir sabah / bir sabah 	İşe yetişmek te...', ARRAY['Türk Edebiyatı','Şiir','Fikri Coşkun']::text[], 8.5, '{"poet":"Fikri Coşkun","poet_slug":"fikri-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gunaydin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-ugur-erkek-7gl57', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana yazıyorum, yine sana aşkım

Saat 4; gecenin sessizliğinde bir ben, 

Birde beni bu kadar düşündüren sen varsın

Yıldızlar bile susmuş, sanki benim duygularımı yansıtan, 

Sanki benim ruhumu okuyan Onur Akın''nın geceyi sana yazdım türküsünü dinliyordu, 

Oysa ben; 

Her zaman ki gibi seni düşünüyor, her zamanki gibi seninle yaşıyor, elimde yırtık bir resmin bir bir oluşturmaya çalışıyordum, 

Dudakların yoktu dağıttım resmini yine  topladım, gözlerin yoktu

teker teker topladım resmini, kalbin yoktu

dayanamadım sevgilim, dayanamadım işte, yaktım resmini

unttum sanma, ne olur unuttum sanma! çünkü bu kezde 

Resmin senin gibi koktu.', 'Sana yazıyorum, yine sana aşkım Saat 4; gecenin sessizliğinde bir ben,  Birde beni bu kadar düşündüren sen varsın Yıldızlar bile susmuş, san...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erkek']::text[], 8.5, '{"poet":"Uğur Erkek","poet_slug":"ugur-erkek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askima-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar ve Doğum Günü', 'acilar-ve-dogum-gunu-salih-ozalasan-jyu4x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve bir yıl daha çekip gitti hayatımdan

Her anı yıkandı sanırım gözyaşımdan

Acı tatlı anılarımı sorma sakın 

Hep acılar geçti benim hayatımdan

Bilmedim hiç nedir mutluluk

Saman alevi gibi geçti hep hayatımdan

Sevgiyi bulduğumu sandığımda bile

Belli değilmiki ağlamamdan

Doğmasaydım keşke demiştimya

Ama elde değilki vazgeçilmiyor yaşamdan

Yıllar bile acımasız bana karşı zamandan

Gönlüme fırtına gözlerime gözyaşı

Ağlıyor yüreğim hep yaralı her zamandan

Gönül dostlarım vardıya hani

Kimi yakınımda kimiyse uzaktan

Hani nerdeler geçmiyor hiçbiri

Yok olup gitmişler hayatımdan

Bir gün belki doğduğum gün 

Dostlarım elinde kalkarım musalladan

Mezar taşına doğduğu güne lanet 

Kaderine isyan vardı diye yazın ufaktan

Gönlüme ferman geçmedi ne eylesem

Sevincim olmadı hayatım hep vuslattan

Salih yaşarmı bilmiyorum artık bundan sonra

Sevdayı ne yakın nede uzaktan

Yüreği yaralı gözü yaşlı umudu tükenmiş

Kalmamış artık başka dostu kara topraktan

Kim bilir belki oda isyan edecek

Öldüğümde yılanları çıkarmayacak koynumdan

Ve ben bir garip gönül dostu

Hiç de umutlu değilim nedense yeni yılımdan

Y.Tarihi 21-09-2002 Saat 18.00', 'Ve bir yıl daha çekip gitti hayatımdan Her anı yıkandı sanırım gözyaşımdan Acı tatlı anılarımı sorma sakın  Hep acılar geçti benim hayatımda...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/acilar-ve-dogum-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılsak Öleceğiz', 'ayrilsak-olecegiz-hulya-senkul-8ylw9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel gidelim seninle

Gel gidelim buralardan

Gurbet yuvamız olsun

Gel gidelim neresi olursa olsun

Gitmezsek üzecekler

Sevmek yetmeyecek gülüm

Aramıza girecekler

Ayrılsak öleceğiz

Ayrılmazsak öldürecekler

Yarım mutluluklar var bu şehirde

Çaresiz aşklar, buruk acılar

Bütün ışıklar sönmüş bu şehirde

Gidelim ne olur', 'Gel gidelim seninle Gel gidelim buralardan Gurbet yuvamız olsun Gel gidelim neresi olursa olsun Gitmezsek üzecekler Sevmek yetmeyecek gülüm ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilsak-olecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadersizim', 'kadersizim-gonul-sen-ew5ih', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adımı doğarken koymuş Yaradan

Nasibim olur mu umuttan, şanstan

Yazılmaz insanın bahtı sonradan

Kadersiz doğmuşum, ben de kadersiz

Yürürüm umutsuz, yolum kapalı

Çaresiz kırdılar tuttuğum dalı

Ağlarım gözümü açtım açalı

Kadersiz doğmuşum, ben de kadersiz

Ağlarım, inlerim halime bakıp

Dünü yaşadım, bugünüm kayıp

Açtım ellerimi semaya bakıp

Kadersiz doğmuşum, ben de kadersiz', 'Adımı doğarken koymuş Yaradan Nasibim olur mu umuttan, şanstan Yazılmaz insanın bahtı sonradan Kadersiz doğmuşum, ben de kadersiz Yürürüm um...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kadersizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nankör', 'nankor-tahir-paker-qxdt5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sözümü unuttun

Sanki hiç konuşmadık

Birden oldun yabancı

Sanki hiç tanışmadık

Boşuna mı sevmiştik

Aşka umut vermiştik

Kim bunları unutur

Nankör olsun demiştik

Nankör kim, düşünsene

İkimizden hangisi

Bu aşka nankör olan

Hangimizin sevgisi

Önceleri istemiştim

Kimseye vermemiştim

Bir sözünle bu kalbimi

Söküp sana vermiştim', 'Sözümü unuttun Sanki hiç konuşmadık Birden oldun yabancı Sanki hiç tanışmadık Boşuna mı sevmiştik Aşka umut vermiştik Kim bunları unutur Nan...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nankor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Talihsiz Kadınmışım', 'ne-talihsiz-kadinmisim-sakir-askan-760lb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sırtımda ki hançer izi

Dost bildiğim yardan eser

Gözüm körmüş görmemişim

Boşa geçmiş ömrüm meğer

Karlar yağmış dağlarıma

Yazık olmuş yıllarıma

Yar diyerek kollarıma

Sardığım bir taşmış meğer

Ben ne kara bahtlıymışım

Ben ne kötü şanslıymışım

Acılar hep beni buldu

Ne talihsiz kadınmışım

Ziyan oldu büyük sevdam

Erken soldu gülüm, goncam

Her şey boşmuş, hepsi yalan

Boşa yanmış gönlüm meğer', 'Sırtımda ki hançer izi Dost bildiğim yardan eser Gözüm körmüş görmemişim Boşa geçmiş ömrüm meğer Karlar yağmış dağlarıma Yazık olmuş yılları...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-talihsiz-kadinmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Hayatım', 'i-ste-hayatim-deniz-tinarli-8t97o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Müslümanım ama çarmıha gerilmiş isa''ya aglarım, 

Aslında ona degil aglarım kendi halime, 

İsa''ya bir kaç çivi çakmışlar bırakmışlar mevlası ile kendi haline, 

Bana heran bir çiviler çakılıyorlar, 

Hemde hep ya yüregimin, ya dilimin, yada beynimim üzerine

Yaradanımlada beni başbaşa bırakmıyorlar, 

Ama biliyrmusunuz? her çakılan yeni bir çivi ile, 

Dünyamda yeni bir deniz büyütüyorlar, nedendir, 

Anamla degil, anılarımla aglıyorum

Anılarımı anlatmak bir kenara, genelde hatırlıyamıyorum, 

Ben gerçekten farklı yerdeyim, bunu çok iyi biliyorum, 

Ulaşılmaz degilim asla, ihityacım ama görülmüyorum, 

Hava gibi, sevgi gibi, aşk gibi, inanmak, hissetmek, özlemek gibi, 

İsa''dan şansızım ben havarilerimde yok çünkü benim, 

Ama belkide şanslıyım, çünkü melekler benim havarilerim, 

Çocuklar hep bana sarılıp uyurlar, bana sarılıp bebekler sükün buluyorlar, 

Hepsi nedense benim kucagımda gülüyorlar, 

Onlarda müritlerim benim

Masum degilim kesinlikle, 

Ama masum olmadıgımı söylüyecek kadar gerçekler yorgunuyum..

Beyazı severim-herşeyimdir, siyahı severim-sadce kendisidir o, 

Sarıyı severim-derinligimdir, pembeyi severim-yüregimdir

Kahverengiyi severim-beynimdir, lilayı severim-hayallerimdir

Moru severim-esrarımdır, farklılıgım gökyüzüne kazınmışlıgımdır, 

Renksiz rengimi berraklıgımı severim, en çok kendimdir o, 

Korkuturum insanları, içim dışım göründügü için, 

Hep ben aglarım nedense, 

Meleklerimi, bebeklerimi, sevgilerimi, sevgililerimi, 

Aglamak için kayboldugum anlaşılmaz, 

Çünkü ben berragım, zamanım, mekanım, 

Eşim, benzerimde yoktur benim, 

Çünkü, ben yürekten özlendigimi, 

Anılarımla anıldıgım, hiç kirletilmemiş yerlerse, yüregimin dibindeyim, 

Günaha girmedimmi? girdim, ama kimsenin degil 

Kendi günahıma, hep ahh dedim hiç ahh dedirtmedim, 

Ben bana izin vermiyen, rüyamdaki gölgeleri bile sevemedim, 

Gelen emanet oldu bana, hiç emanete ihanet etmedim, 

Çok yandım ama hiç yakmadım, enazından hiç yürek yıkmadım, 

Su oldum su dagıttım, ama ben hep susuz kaldım, 

Çözemiyorum be arkadaş ben sence 

Şeytanmı? Yoksa Şeytan Zebanismiyim? ? ? ? ? ?', 'Müslümanım ama çarmıha gerilmiş isa''ya aglarım,  Aslında ona degil aglarım kendi halime,  İsa''ya bir kaç çivi çakmışlar bırakmışlar mevlası ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Tınarlı']::text[], 8.5, '{"poet":"Deniz Tınarlı","poet_slug":"deniz-tinarli","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/iste-hayatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe Kuşu', 'serce-kusu-sair-hakan-hh6dr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sabah bahçeme gelip penceremin kenarında nasılda  mutlu ötersin serçe kuşu

Bilmem ki aşk şarkılarımı fısıldarsın kulağıma

Bilir misinki ne acılıdır yüreğim 

Git serçe kuşu ötelere git, uzaklara uç

Selam götür birisine benden

O hala gecelerde yaşıyor de, yarım kalmış gecelerde

Adı konulmamış sevdalarda aklı

Üstü örtülmemiş hatıraların, hep aklında saklı

Bir yara var ki iflah olmaz yüreğinde

Fısıldayarak de serçe kuşu fısıldayarak de

Uç serçe kuşu ötelere uç, uzaklara git

Beni de al kanatlarına

Ayrılıksız diyarlara  götür beni

Yaşanmamış sevdalarla tanıştır beni

Doğmamış acıları olsun

Tadılmamış ayrılıkları

Terk edilmemiş  seven kalpler olsun

Yarım kalmamış aşklar

Yanmamış yürekler olsun

Haydi serçe kuşu uç artık git, 

Beni de al kanatlarına

Bilinmeyen yerlere götür beni.......

                                      Hakan-21,09,2002', 'Her sabah bahçeme gelip penceremin kenarında nasılda  mutlu ötersin serçe kuşu Bilmem ki aşk şarkılarımı fısıldarsın kulağıma Bilir misinki ...', ARRAY['Türk Edebiyatı','Şiir','Şair Hakan']::text[], 8.5, '{"poet":"Şair Hakan","poet_slug":"sair-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/serce-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aya Ulaşmak', 'aya-ulasmak-bilal-i-lkin-2yhq4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elimi uzattım aya doğru, 

Lütfuna dokunmak için.

İçime huzur dolsun istedim

Fakat uzanamdım ona kadar.

Zaman akıp gitti parmaklarımdan

En sonunda eriştim derken ona.

Yine denedim, tekrar denedim, 

Neden sonra yaşlanmışım dedim.

Elimden aldı huzuru zaman o an.

Pes ettim aya ulaşmaktan.

Bakmakla yetinmek istedim aya, 

Üstünde yansıdıkça.

Yüzüme ışığı geldikçe, 

Üstümden bir yük kalkar dedim.

Kusursuz beyazlığını gördükçe

Daha da rahatlarım dedim

Umudum artıkça.

Mani oldu zaman bana

Ay ulaşmaya çalıştıkça.

Nafile...', 'Elimi uzattım aya doğru,  Lütfuna dokunmak için. İçime huzur dolsun istedim Fakat uzanamdım ona kadar. Zaman akıp gitti parmaklarımdan En so...', ARRAY['Türk Edebiyatı','Şiir','Bilal İlkin']::text[], 8.5, '{"poet":"Bilal İlkin","poet_slug":"bilal-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aya-ulasmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Vardı Bir Zamanlar', 'o-vardi-bir-zamanlar-ozan-rari-rrr63', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En güzel düştü o

Hayallerin sebebiydi

Aklı baştan alan gözleri

O sıcak samimi tavrı

Birden kıyamet koptu! 

Yıprattı, suiistimal etti değerleri! 

Aşkımla oynadı beni benden etti

Ben dersimi aldım! ! ! 

Sende devam et

Sakın dönme nefretim yok eder seni...', 'En güzel düştü o Hayallerin sebebiydi Aklı baştan alan gözleri O sıcak samimi tavrı Birden kıyamet koptu!  Yıprattı, suiistimal etti değerle...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-vardi-bir-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-ozan-rari-vfhy5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Renkler vardır insanı tuhaf eder

Benimde var rengim adı mavi

Huzur, ahenk hepsi onda

Herşeye yakışır o

Gözlerde başka, gökyüzünde başka

Rengi veren Rabbim ne güzelde vermiş', 'Renkler vardır insanı tuhaf eder Benimde var rengim adı mavi Huzur, ahenk hepsi onda Herşeye yakışır o Gözlerde başka, gökyüzünde başka Reng...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mavi-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-mehmet-fatin-baki-pkmxu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Erken başladı telaş

Büyüdü yavaş yavaş

Ana, baba, bac(ı)  kardaş

Köyde düğün var bugün

					

Bazlamalar açıldı

Sofralara geçildi

Üste ayran içildi

Köyde düğün var bugün

Davulla zurna çalsın

Oynayacaklar gelsin

Seyirciler halka olsun

Köyde düğün var bugün			

(Ertesi gün)

Mefaki dün çok yoruldun

Yataklara serildin

Sabahleyin dirildin

Köyde düğün vardı dün', 'Erken başladı telaş Büyüdü yavaş yavaş Ana, baba, bac(ı)  kardaş Köyde düğün var bugün 					 Bazlamalar açıldı Sofralara geçildi Üste ayran ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dugun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk', 'ataturk-ozan-rari-6bsxf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koca milletin atası ulu önderi

Tek başına tarih yazan kahraman! 

Allah razı olsun nur içinde yat

Sen kurtarıcısın, millet var oldukça lidersin

Seni sevmeyen kahrolsun

İhanetçiler Allah''tan bulsun

Bu kalp senle hep, unutma

Seni seviyorum Mustafa Kemal...', 'Koca milletin atası ulu önderi Tek başına tarih yazan kahraman!  Allah razı olsun nur içinde yat Sen kurtarıcısın, millet var oldukça liders...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ataturk-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-mehmet-fatin-baki-f0igo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden biz sevişirken senin ismin HEVA derdim

Elem yok, kederim yok, sana her gün kanat gerdim 

Çocuklar  gibi şendim, seni sevmekti hep derdim 

Meğer sen hava mışsın yokoluncak nefes verdim 

			

Heva = sevgi

Mefailu    Mefailu     Mefailu    Mefulu

.  /   / . .   /   / .  .   /   / .    /    / .', 'Neden biz sevişirken senin ismin HEVA derdim Elem yok, kederim yok, sana her gün kanat gerdim  Çocuklar  gibi şendim, seni sevmekti hep derd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevgi-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsak...', 'olsak-ozlem-bayram-exe5y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sarhoş olsak olur olmadık gecelerde..

Karelere bölünsek de; hiç bölünmesek.

Sonra toplasak bütün duygularımızı, 

Çıkartsak aklımızdan 

Bütün karamsarlıkları.

Bir aşk çarpsa sonra ikimizi, 

Hasta gibi olsak, ayakta duramasak.

Sarılsak birbirimize, 

Derin bir uykuya dalsak.

Sonra tek bir rüya görsek, 

İkimizin de görebildiği.

Hiç uyanmasak o rüyadan, 

Rüyayı gerçekte yaşasak.

Çıkmaz sokağın çıkışın da ki; 

Hani var ya o kuytu da bir olsak! 

Biz ikiyken bir olsak, bir iken üç...

Çoğalsak, 

Çoğaldıkça karşılıklı sonsuz sevgimiz....

Ve rüyadan hiç uyanmadan ölsek, 

Sadece ikimiz.', 'Sarhoş olsak olur olmadık gecelerde.. Karelere bölünsek de; hiç bölünmesek. Sonra toplasak bütün duygularımızı,  Çıkartsak aklımızdan  Bütün...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve o gün...Ve bu gün.', 've-o-gun-ve-bu-gun-ozlem-bayram-wszsv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve o gün... VE BU GÜN.

Ve yine günlerden 10 temmuz.

İlişkimizin başlangıç günü..

İçim de bir coşku, bir fırtına ki; eyvah! 

Hiç ayrılığı yaşamadım; 

ayrılığı yaşasam da.

Hiç hüznü tatmadım; 

hüznü tatsam da.

Çünkü; her gidişinin bir dönüşü vardı.

Ve hüzün mutluluğa bırakıyordu yerini.

Sensiz geçen geceler de bile; 

Seninle konuşmayı, 

Sen olunmayı öğrendim.

Senin olmadığın bir şehir de; 

Güneş’in doğuşunu

Tek başıma seyretsem de; 

Senin şehrinde de aynı güneşten Olduğunu bilerek yandım.

İçim buz kesmedi, 

Gözümden yaşlar acı acı akmadı, 

Gözlerim kan çanağı olmadı.

Ağlamayı özledim. 

Ve bilirsin! 

Özlenene kavuşmaktır hedefim.

Ağlıyorum. Hem de hıçkıra hıçkıra! 

Ama acı acı değil.

Bu mutluluğu yaşatan sevgi, 

Hep yanım da.

Ve ben bu mutluluğu, 

Bir ömür kısalığın da yaşayacağım için ağlıyorum.

İkiyken bir olunmayı öğrendim seninle.

Aynı yol da yan yana yürümeyi sonra...

Ve yolun sonun da; yanımız da, 

solumuz da, önümüz de, 

İçimiz de ne varsa paylaşmayı öğrendim.

Sevindim, coştum. 

Çocuk oldum seninle.

Seninle ben oldum. 

An oldu sen oldum.

Sen olunca, 

Seni damarlarım da hissettikçe 

Kuş oldum.

Hiçbir avcı görmeden çevren de uçtum.

Sonra kalbine kondum. 

Kendimi buldum.

Artık sen de ben olmuştun.

Biz ikiyken bir olduk; birken hür...', 'Ve o gün... VE BU GÜN. Ve yine günlerden 10 temmuz. İlişkimizin başlangıç günü.. İçim de bir coşku, bir fırtına ki; eyvah!  Hiç ayrılığı yaş...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ve-o-gun-ve-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde Ol...', 'kalbimde-ol-ozlem-bayram-ssn8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'VAZGEÇMEM

Can damarım çatladı! 

Bir soğuk bir sıcak ne olduğunu şaşırdı ve çatladı.

Bir varsın bir yoksun ne olduğumu şaşırdım.

Kendi kararımı kendim verecek yaştayım.

Artık ne can damarım çatlayabilir; 

Ne de bir üşürüm kışı yaşarım, 

Bir terlerim yazı yaşarım.

Artık baharı yaşamaya karar verdim.

İlk baharı son baharım da...

Ve seni, ardım da kalan 

Karların altına gömüverdim.

Bundan sonra, 

Ne can damarım çatlayabilir; 

Ne de gönlüm baharından vazgeçebilir.

Bundan sonra ne gönlüm sana gelebilir, 

Ne de seni içeriye kabul edebilir.', 'VAZGEÇMEM Can damarım çatladı!  Bir soğuk bir sıcak ne olduğunu şaşırdı ve çatladı. Bir varsın bir yoksun ne olduğumu şaşırdım. Kendi kararı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbimde-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yık...', 'yik-ozlem-bayram-fzums', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YOK! 

Bir şiir yazdım sana az önce; 

Şiir ’ in adı yok! 

Tıpkı, 

Bu ilişkiye isim veremediğimiz gibi; 

İsim veremedim şiirime.

Şiirle ilişkinin arasın da bir fark...

Şiir anlamlıydı çoğu yer de.

Ya ilişki? 

Gün geçtikçe anlamsızlaşıyordu. Sayende.

Ey sen! Sevgili! 

Şiirime anlam katan, 

Hayatımı karartan...

Bu şiir kimin eseri? 

Benim değil senin! 

Yazan ben, yazdıran sen! Yazarken, yaşatan! 

Bir zamanlar hayatım da olduğu gibi, 

Şiirin ana fikri yine sen! 

Ama artık ne şiir yazıyorum, 

Ne bir şiire isim arayışına giriyorum.

Çünkü; 

Artık şiirime anlam katabilecek birini

Hayatım da göremiyorum!', 'YOK!  Bir şiir yazdım sana az önce;  Şiir ’ in adı yok!  Tıpkı,  Bu ilişkiye isim veremediğimiz gibi;  İsim veremedim şiirime. Şiirle ilişki...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antibiyotik...', 'antibiyotik-ozlem-bayram-r0ahb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir sence “yalnızlık”? 

Yanın da kimse olmaması mı? 

Hayır hayır! 

Senin yalnızlığın bensizlik olmalı.

Bensiz kaldığın da 

Yalnız hissetmelisin kendini.

Her yer de beni aramalısın, 

Benim seni aradığım gibi...

Yalnız kalmak ölüm olmalı senin için.

Hasta olmalısın, doktor değil.

Beni istemelisin yanına, 

Antibiyotik niyetine...

Bense tüm vitaminleri kaldırıp rafa Yanına gelmeliyim.

Ve demeliyim ki; 

“Tedavisi kavuşmaktır sevdiğine”', 'Nedir sence “yalnızlık”?  Yanın da kimse olmaması mı?  Hayır hayır!  Senin yalnızlığın bensizlik olmalı. Bensiz kaldığın da  Yalnız hissetme...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/antibiyotik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal benimle...', 'kal-benimle-ozlem-bayram-lul5l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel desem gelir misin bana? 

Gelince, 

Gitmemecesine kalır mısın benimle? 

Kalbini aralayıp alır mısın beni içeriye? 

Sever misin beni de? 

Aramızda ki yollar yıpratamaz 

Bende ki sevgiyi, 

Aşılması güç sorunlar çıksa da karşıma.

Sevmedi kalbim daha önce kimseyi, 

Ürkek bir kuş gibi kalmıştım tenhada.

Bana geleceksen; 

İçimde ki; 

Seni öldürmek için kiraladığım, 

Azılı bir katilin ayak izlerini takip et.

Ve sevginin soğuk kanlı katilidir “O”! 

Acele et! 

Ağına düşme sevmeyenin, 

Yalancı sevginin.

Bir çocuk saflığıyla gülüp, 

Kıymet bilmeyenin.

İmkansızı sorun olarak görme kendine, 

İmkansız diye bir şey yok.

Sen imkansız olarak görüleni de dene, 

Olgunlaştırır bunlar seni; 

Sen fark etmesen de! 

Yılanın uykuda ki halini merak etme, 

O, 

Hiçbir zaman uyumayan bir düşmandır.

Sen bir kez de beni sevmeyi dene, 

Çünkü; o “ben” 

Hiçbir zaman uyumayan

Düşmanın düşmanıdır....', 'Gel desem gelir misin bana?  Gelince,  Gitmemecesine kalır mısın benimle?  Kalbini aralayıp alır mısın beni içeriye?  Sever misin beni de?  ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kal-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-ozlem-bayram-88c4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir  başına kaldığımda, dalıp giderim 

–di’li geçmiş zamanlı anılara

Sonra, 

gözümden bir iki damla yaş süzülür 

Olur olmadık

Seni düşünürüm, 

Uykuya hasret akşamlar da.

Kayıp bir çocuk gibi, 

Dolanırım anılarım da.

Bir o anı düşünürüm, bir de bu anı

Yeni zamanlar keşfederim, 

Daha önce fark edilmemiş, 

Kapanırım anıların gölgesine ağlarım.

Rotası belli yaşlar akar gözümden, 

Sana ulaşmak için.

Kalbimin; 

Sana susamış olduğunu anlarım.

Sensiz anlamsız bir gece de...

Kimsenin duyamadığı 

Sessiz çığlıklar atarım.

Duvarlarım sırdaşım olur 

Aynalarım düşmanım...

Solgun halimi gösterirler bana aynalar...

“Toparlanman lazım” derler..

“Onsuz olmaz” derim, 

Her geçen gün eridiğimi söylerler

Aynalara düşmanım...

Tek dostum, 

Göz yaşlarım olur sensiz geceler de.

Ağlarım durmadan, 

Çoğalsın diye dostlarım...

Gömülmediği sürece ölü demezler Hiçbir şeye...

Kalbime gömüyor, 

Göz yaşlarımla suluyorum seni artık 

Benim için ölmüş ol diye....', 'Bir  başına kaldığımda, dalıp giderim  –di’li geçmiş zamanlı anılara Sonra,  gözümden bir iki damla yaş süzülür  Olur olmadık Seni düşünürüm...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/anilar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım...', 'yanarim-ozlem-bayram-m3s1g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostumdun sen, 

Adına şiirler yazdığım.

Aşkımdın sen...

Geceleri uykusuz kaldığım.

Sırdaşımdın sen, 

Seni sana anlattığım.

Ağlarken bir omuz, 

Hastayken bir tas çorbaydın.

Sen; her şeydin benim için. 

Ama ben; 

Senin için tek bir şey bile olamadım. 

Şimdi oturur için için ona yanarım.

Özlem BAYRAM', 'Dostumdun sen,  Adına şiirler yazdığım. Aşkımdın sen... Geceleri uykusuz kaldığım. Sırdaşımdın sen,  Seni sana anlattığım. Ağlarken bir omuz...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İbaret...', 'i-baret-ozlem-bayram-5oo4h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk, 

Benim için bir bekleyişten ibaret

Anıların gölgesin de oturup

Eskileri anarken, 

Ve eski seni özlerken, 

İçim de koskocaman bir boşluk, 

Bir yara olduğunu anladığım da, 

Beklemeye başladığım.

Aşk, 

Benim için bir ömürden ibaret

Bir günümü ayırıp düşünebildiğim, Sevebildiğimi fark ettiğim 

Ama yalnız olduğum.

Aşk, 

Benim için senden ibaret, 

Taptığım, bir ilah yaptığım

Ama bir türlü anlatamadığım.

Ya da anlayamadığın.', 'Aşk,  Benim için bir bekleyişten ibaret Anıların gölgesin de oturup Eskileri anarken,  Ve eski seni özlerken,  İçim de koskocaman bir boşluk...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ibaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu olacağım...', 'mutlu-olacagim-ozlem-bayram-y9pw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutamıyorum diye

Kızmayın bana dostlarım, 

O her an aklımda diye kızmayın.

Kalbimin hızlı atmasına neden olan, 

Beni hayata bağlayan onu kıskanmayın.

Sevinin düşmanlarım, 

Mutsuzum sevinin.

Alındı intikamlarınız bir bir 

Sevdiğim tarafından.

Şimdi size şenlik bana yas zamanıdır. Sevinin.

Ama unutmayın! 

Kulaklarınızda sizi mutlu eden

Ve beni bitiren bir çığlıkla geçmeyecek bu ömür.

Mutlaka mutlu olacağım.

Ya dönecek bana

Ya ben gideceğim ona unutmayın.

Ve unutmayın, mutlu olacağım yine.

Ya bana döndüğü gün, 

Ya da onunla, 

O içimdeyken öldüğüm gün.....', 'Unutamıyorum diye Kızmayın bana dostlarım,  O her an aklımda diye kızmayın. Kalbimin hızlı atmasına neden olan,  Beni hayata bağlayan onu kı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mutlu-olacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakma...', 'birakma-ozlem-bayram-8fw5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yitik umutlarım var deyip, 

Kendini bırakma, 

Doğmamış umudunu yitirmedin ki...

Bu günün işini yarına bırakma

Yarın iş yapabileceğin bellimidir ki? 

“Seni seviyorum” demek için, 

Uygun zaman bekleme, 

Uygun zaman nedir bilir misin ki? 

Yaşa hayatı içinden geldiğince, 

Hayatın kısalığını hiç düşünmedin mi? 

Ulaş hedeflerine, 

Yer verme hayatında keşkelere.

Pişman olursun keşke dersen, 

Bir kere bile.

Keşke dememek için, 

Zamana bakmaksızın haykırıyorum.

Ve ben SENİ SEVİYORUM delice. 

Ve ben seni yaşıyorum 

İçimden geldiğince...', 'Yitik umutlarım var deyip,  Kendini bırakma,  Doğmamış umudunu yitirmedin ki... Bu günün işini yarına bırakma Yarın iş yapabileceğin bellimi...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birakma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşmak.', 'paylasmak-ozlem-bayram-nrrss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeni güne uyanamasak ta birlikte, 

Günü paylaşabilmek seninle.

Paramız olmasa ve acıksak, 

Bir simidi, bir ekmeği, bir zeytini, 

Paylaşmak seninle.

Havadaki oksijeni, 

Doğadaki güzellikleri, 

O yüce varlık sevgiyi, 

Mutluluğu, kederi, 

Olgunluğu, çocukluğu, 

Paylaşmak seninle...

Paylaşmak seninle paylaşmak! 

Paylaşmak sadece seninle.

Paylaşarak bütün olmak! 

Ve bütünlüğü paylaşmak yine seninle!', 'Yeni güne uyanamasak ta birlikte,  Günü paylaşabilmek seninle. Paramız olmasa ve acıksak,  Bir simidi, bir ekmeği, bir zeytini,  Paylaşmak s...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/paylasmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yokken', 'sen-yokken-ozlem-bayram-sop1e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onca hasrete sonunda, 

Büyük bir sevgiyle kavuşacaktık yine.

Resmine bakıp ağlıyorum sen yokken, 

Sensiz şehrin, sessiz gecelerinde.

Kimi başımı gömüyorum

Mektupların arasına, 

Kimi kulağım bir kapı zilinde.

Uzun yollar var aramızda 

Aşılması gereken.

Aşacağız biz 

Sevgimizin gücü sayesinde.

Nicedir hasretim gözlerine, 

Beni sen yapan sözlerine, 

Öyle alışmışım ki o pamuk ellerine, 

İçten gülüşüne...

Zaman geçmek bilmiyor sensiz, 

Ama seninleyim yinede.

Lanetlermi etmiyorum sensiz saatlerde 

Saatlerce yaşadığım kente...

Evlerin ışıkları bir bir söndüğünde, 

Ağlama nöbetlerim başlar sessizce.

Melekleri sana gönderiyorum

Dün gece olduğu gibi, 

Rahat uyu diye bu gece...', 'Onca hasrete sonunda,  Büyük bir sevgiyle kavuşacaktık yine. Resmine bakıp ağlıyorum sen yokken,  Sensiz şehrin, sessiz gecelerinde. Kimi ba...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-yokken-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibrit Söndü...', 'kibrit-sondu-ozlem-bayram-iklfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece yarısı yatağımdan kan ter içerisinde, sıçrayarak uyandığımda, iki kabus arası pembe rüya gibi yanımda aradım seni. 

Akşamdan kalma yorgunluğumu sabahlara taşıyordum sen yokken, geceler boyu. 

Ve geceler boyu uyuyabildiğimi sanıyordum gözlerim açık. Oysa rüya olarak gördüğüm şeyler, gözlerim açık kurduğum hayallerimmiş.

Hayalinde güzel senin... 

Hey gidi gözümden yaşlar döktüren serseri sevgili, unutacağımı mı sanmıştın seni? ! ! ! İçimdeki seni! 

Öyle alışmışım ki; karanlık dünyamı bir saniye bile olsa aydınlatan ışığına... öyle alışmışım ki o bir saniyelik ışığı bir ömür bulacağıma...

 Yazık! ! ! Sigaramı yakan bir kibritin ateşi bile, senin aydınlığından çok ışık verdi karanlık dünyama.

 Ve yazık! ! ! Sevgime inanmadan söndün derin yalnızlığımda. Geride, bıraktığın o anlık ışığın yarattığı büyü var ve penceremi açtığımda senin gibi uçup gidecek teninin kokusu... 

Şimdi bu dediklerim neyin korkusu? İç çekişinde saklı değil midir bir sevda masalının tortusu? Yorgun akşamlarda söylenen, o içten, uykulu kelimelerin altında yatmaz mı anlamsız bulunan aşk coşkusu, sevda yortusu? 

Şimdi bir kibrit yakıyorum ve bir dilek tutuyorum. 

Ve sen “kibrit hiç sönmezse dileğin gerçek olsun” diyorsun. Oysa ben seninle olmayı, benim olmanı diliyorum... 

Ve kibrit söndü. Gidiyorsun.', 'Gece yarısı yatağımdan kan ter içerisinde, sıçrayarak uyandığımda, iki kabus arası pembe rüya gibi yanımda aradım seni.  Akşamdan kalma yorg...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kibrit-sondu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara', 'sigara-ozan-rari-pkdmm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rezil utanmaz şey

Yaktın, yıktın hayatları

Sen zararlının önde gideni

Nefret ederdim, esir aldın benide! 

Kahretsin senide içenide

Ey malum şahıs Allah belanı versin', 'Rezil utanmaz şey Yaktın, yıktın hayatları Sen zararlının önde gideni Nefret ederdim, esir aldın benide!  Kahretsin senide içenide Ey malum ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sigara-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin...', 'gelmedin-ozlem-bayram-nhqt1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şiir yazasım geldi derin gözlerinin derin manalarında boğulurcasına. Sana, seni senli duygularımla anlatmak için. 

Senin adına senden habersiz..

Tıpkı bundan haberin olmadığı gibi, bu şiirden de haberin olmayacak.

Belki; yanı başındaydım çoğu zaman. Bir soluk kadar yakındım sana. Senin gibi olamadım. Yıldızlardan öte bir yakınlık veremedim sana.

 Öyle bir zamanda girmişim ki meğer hayatına, çıktığımı bile anlamadın.

 Bir haykırış olmalı bu şiir sana. Haberin olmayacak, şiirsiz haykırışlarımdan haberin olmadığı gibi Oysa hep duydun işine gelince beni, bazense kulakların tıkalı. Bu tıkaçlar sadece bana mı? Nedir sende bu bana karşı var olan duygu kıtlığı? Oya yakamozlar ne de güzel bu gece... 

Gözlerin ne de güzel dalgalanıyor yakamozlar üstünde. Kırık bir sandal gibi. 

Hadi çık o hiç giremediğin duygu denizinden, benim duygularımla boğulmadan çık öylesine güzel dalgaları yararken...

En güzel şeylerin çok çirkin bir şekilde bitişi, hiç olmadık bir şeyin; asla olamayacak bir şeye dönüşmesi ve bütün bu iç çekişlerin ve karmaşıklıkların arasında, sensin  en önemlisi.

Çıkarken anahtarını unutmuşsun. Bu kaçıncı anahtar unutuşun bilmem kaçıncı evdeki? 

Bu adresini hiç bilmediğin yada bilipte farkı göremediğin bu sıradan evden çıkarken, benden bana ait ama senin gibi görünen ne çok şey götürdün giderken...

İlk başta içini hiç merak etmediğin kalbimi, hiç bilmediğin,  düşünemeyeceğin düşüncelerimin kopyasını ve en önemlisi ruhumu aldın. Taş heykellerden kalmadı farkım. 

O yüzden gelmelisin. 

Gelmedin...

Kim bilir hangi bilmem ne adresindesin...

Ya da kaçıncı yedek anahtarınla açtın kapını ama GELMEDİN...', 'Bir şiir yazasım geldi derin gözlerinin derin manalarında boğulurcasına. Sana, seni senli duygularımla anlatmak için.  Senin adına senden ha...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelmedin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-ozlem-bayram-afwdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir trene bindirdiler beni. 

İte kaka zorla... Yanıma; hayata dair hiçbir şey almamıştım oysa.

Trenin acı çığlığı yankılandı kulaklarım da... Beni hiç bilmediğim bir odaya kapattılar. Ve yanıma yol arkadaşlarımı yolladılar.

Hiç bitmeyeceğini düşündüğüm yolculukta yaptığımız suskun konuşmalardan sonra, onların bana hiç yabancı olmadıklarını anladım.

Vefalı dostlarım benim.

Hiç yalnız bırakmamışlar beni oysa; bütün bir hayat boyunca.

Hiç merak etmediğim, ama hep öğrenmek istediğim soruyu sordum: “Nereye gidiyor bu tren? ”

Aldığım tek cevap “Son Durak”



Neyin son durağı bu? 

Acılarımın mı? Kederlerimin mi? 

Dostluklarımın ya da aşklarımın mı? 

Ben en son durakta inmeyi beklerken, 

beni ilk durakta indirdiler. Sadece benim hissedebildiğim dostlarımla beraber. Nereden bilirdim ilk durağın aslın da son durak olduğunu? 

Çıkışa yürüdüm, tüm çıkışlar kapalı. 

Yalnızca bir aralık kapı...

Kapı da beni karşılayan karanlıktı. 

Gözüm kapalı girdim içeriye, gözüm açık olsa ne görecektim ki? 

Midem bulanıyor, daha çabuk yorulmaya başlıyordum. Yoksa trende ki yükleri de mi aldım yanıma? 

Yoksa beni trene iterlerken de var mıydı 

bana yorgunluk veren bu yükler? 

Her karanlığın sonu bir aydınlık mıdır? 

Kimler var bu karanlığın için de? 

Yoksa hayatım boyunca olduğum gibi 

yalnız mıyım? 

Parlak bir ışık var, gözün alabildiğince giden karanlığın sonunda....

Belki; bir kurtuluştur diye koşuyorum o ışığa 

Yaklaştıkça daha bir kamaşıyor gözlerim...

Ve geliyorum yol sonuna...

Aman tanrım! ! ! 

Nereden bilebilirdim ki...

Nereden bilebilirdim ki; yalnızlığın hat safhasının bu kadar göz aldığını? 

Nereden bilebilirdim ki; 

ilk durağın aslın da “son durak” olduğunu?', 'Bir trene bindirdiler beni.  İte kaka zorla... Yanıma; hayata dair hiçbir şey almamıştım oysa. Trenin acı çığlığı yankılandı kulaklarım da.....', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/son-durak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum...', 'korkuyorum-ozlem-bayram-tak9q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor düşlerime...

Ya sel alırsa? 

Ya bilinmeze sürüklenirse hayallerim? 

Ya umut kapıları kapanırsa yüzüme? 

Ya sende tutulup yağmura gidersen? 

O gitmelerden bir daha dönmezsen? 

Ve sonra güneş açarsa? 

Kurutursa dönme umudunu? 

Sonra rüzgar çıkar; 

Süpürürse ayak izlerini, 

Sana gelme yolunu? 

Ya bir mevsim girerse aramıza? 

Ya sen yaz yaşarken 

Ben kurtulamazsam kıştan? 

Ya kar yağarsa sonra? 

Düşlerim kalırsa kar altında? 

Bir korku filizlenirse çatlamış toprakta? 

Kalbime kök salarsa? 

Ya mevsimlik değil; 

Kalıcıysa korkularım? 

Hiç bitmezse, 

Özleminle eridiğim akşamlarım? 

Hasretinle getirdiğim sabahlarım? 

Sana soruyorum...

Daha kaç mevsim bu durumdayım? 

Kaç mevsim daha 

Yana yakıla dolanmalı...

Ve kaç mevsim daha ağlamalıyım?', 'Yağmur yağıyor düşlerime... Ya sel alırsa?  Ya bilinmeze sürüklenirse hayallerim?  Ya umut kapıları kapanırsa yüzüme?  Ya sende tutulup yağm...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/korkuyorum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak dilencisi', 'sokak-dilencisi-ozlem-bayram-htxg3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğim elimde yol boyu yürüyorum, Rastlarsam bir dilenciye vereceğim.

Ama önce anlatacağım 

Yüreğimin öyküsünü.

Bir zamanlar oda dilenirdi diyeceğim.

Para değil sevgi istemişti yüreğim.

Paradan daha değerli, zor elde edilen...

Belki de kolay insanın sevgiyi sevmesi, Sevmeyi bilmesi...

“Sonra ne oldu? ” diyecek...

İflas etti diyeceğim.

Kanları görecek üzerinde, 

“Ne bunlar? ” diyecek. 

“Göz yaşlarımla suladığım kaktüs çiçeğimin izi” diyeceğim.

“Peki gül var mı içinde? ” 

Diye soracak belki de, 

“Tohumunu bulamadım.” diyeceğim.

Ve diyeceğim ki; 

“Ona iyi bak...”

“OLUR DA BİRGÜN GELİRSE SENDEN GERİ DİLENECEĞİM.”', 'Yüreğim elimde yol boyu yürüyorum, Rastlarsam bir dilenciye vereceğim. Ama önce anlatacağım  Yüreğimin öyküsünü. Bir zamanlar oda dilenirdi ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sokak-dilencisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Futbol Sevdası', 'futbol-sevdasi-ozan-rari-o6dgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir top ayaklar ona hakim

Öyle tutku başka yok herhal

Hep olmak isterdim bir topçu

Kader izin vermedi! ! 

Kalbimde yüreğimde hep o

Ne zaman oynasam, izlesem dünya''dan koparım

Oğlum olursa birgün onu en kralından yapıcam

Başka sefere buluşmak üzere

Hoşçakal ey yar...', 'Bir top ayaklar ona hakim Öyle tutku başka yok herhal Hep olmak isterdim bir topçu Kader izin vermedi! !  Kalbimde yüreğimde hep o Ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/futbol-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal diyemem...', 'kal-diyemem-ozlem-bayram-k45kz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geç oldu.

“Kal” diyeceğim bilirim 

“Kalamam” diyeceksin. 

Bildiğim için nedenini

“Neden? ” demeyeceğim

Söyleyeceğin bahane 2x2=4 çünkü.

“İşim var gideceğim! ”

Gidişin bitişim olacak irkileceğim, 

Aklım başıma gelirse düşüneceğim.

Ve bira sevineceğim, 

Sonra daha çok üzüleceğim.

Üzüldükçe, seni düşündükçe, 

Düşe gömüldükçe, 

Kadere bir daha güceneceğim.

Sonra kendime küseceğim.

Ve çekilip en koyusuna hüznümün, 

Barış güvercinlerinin 

Gelmesini bekleyeceğim! ! ! 

Gelmezlerse, 

Bende bir güvercin olup, 

Gökyüzüne göçeceğim...', 'Geç oldu. “Kal” diyeceğim bilirim  “Kalamam” diyeceksin.  Bildiğim için nedenini “Neden? ” demeyeceğim Söyleyeceğin bahane 2x2=4 çünkü. “İşi...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kal-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye kadar', 'nereye-kadar-ozlem-bayram-3pfnh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen nereye kadar diyorum

Bazen “Yeter! ” çığlıkları atıyorum. Kimseyi istemediğim zamanlar oluyor

Korkuyorum sonra sensizlikten

Ne yaptığımı bilmiyorum.

Ağlama nöbetlerim başlıyor sonra.

Gözlerim kalbine devrettiğinde nöbeti

Derin bir sızı sarıyor bedenimi.

Hapsediyor hüzünlerim beni karanlığa

Kurtuluşa beş kala, 

Hiçbir ümit yokmuşçasına.

Sevgi masalları anlatıyorum, 

Başıboş saatlerde, 

Gölgelerin dansettiği duvarlara.

Masal bitince, 

Üzerime devriliyor duvarlar

Bittiğimi hissediyorum.

Gözlerim kan çanağı olduğunda, 

Dikiyorum gözlerimi tavana.

Hayalin canlanıyor ardından, 

Canlanan hayalinin kollarında ben...

Ben ölüyorum.', 'Bazen nereye kadar diyorum Bazen “Yeter! ” çığlıkları atıyorum. Kimseyi istemediğim zamanlar oluyor Korkuyorum sonra sensizlikten Ne yaptığı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nereye-kadar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para Para Para', 'para-para-para-ozan-rari-pj670', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönüyor Dünya etrafında 

Sana inananlar, kananlar var

Yazık oysa hiç gözüm yok sende

Varlığın, yokluğun dert

Ne tür şeytansın sen, uğrunda ölenler! 

Birbirine düşüren sen insanları

Uçurumun sebebi sen

Kusura bakma sevemedim gitti seni.', 'Dönüyor Dünya etrafında  Sana inananlar, kananlar var Yazık oysa hiç gözüm yok sende Varlığın, yokluğun dert Ne tür şeytansın sen, uğrunda ö...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/para-para-para-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bi Söz....', 'oyle-bi-soz-ozlem-bayram-677zs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kuşun kanatlarının kırılması, 

Kuşa acı verir ancak.

Kanatlarını kırana değil', 'Bir kuşun kanatlarının kırılması,  Kuşa acı verir ancak. Kanatlarını kırana değil...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/oyle-bi-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İnsanım Usta...', 'ben-i-nsanim-usta-ozlem-bayram-2pxzh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne var yani okumadıysam, 

Babam okutmadı ki.

Ben istemedim mi adam olmayı.

Babam “okuyarak adam olunmaz”dedi

Verdi daha 11imde tamirci  yanına

Bilmezdim nedir daha tornavida

Mahalle maçlarında kalırdı aklım

Ama oynamaya korkardım.

“Ya yırtılırsa papuçlarım? ”

Babam “Az para getiriyorsun.” dedi

Zam istedim başım önümde

“Çalışmayana ekmek yok” dedin.

Mesaiye kalmamı söyledin saatlerce.

Çalışırken dayanamazdı, 

Kapanırdı o çocuk gözlerim.

Ensemde bir elin soğukluğuyla uyanır

Kendimi yerde bulurdum.

Canım acırdı belli edemezdim. 

Söylesem beni döverdin.

Sonra biraz daha büyüdüm. 

Yaşım erdi 18ime. 

Bakkal Hüseyin’in kızına aşık oldum.

Babam dedi: 

“Aşık olmak senin neyine? ”

Vurma artık usta; 

Yaşım geldi 20’ye

Gören ne der sonra; 

Rezil olurum millete.

“İsyan ediyorum artık bu düzene

Düzen denilen şey düzensizlik bence

Bu yaşamak değil bir işkence”

Attılar beni böyle konuşunca nezarete

Ne ekmek verdiler ne de su

Adam değilsin sen dediler birde

Babam dedi “Rezil olduk el aleme”

Kızdı ustam pişman değilim diye.

Çıkınca işe döndüm yine.

“Sabıkalı çırak” dediler birde. Sabıkam hak aramamdan dediysem de

Dinlemediler bir kere bile.

Vurma artık usta.

Gelen vuruyor, babam vuruyor.

Güvenin dedikleri herkes vuruyor.

Adam değilsem de hakkımı arayacağım

Artık bu adam olamayan; 

İnsan olduğunu biliyor.', 'Ne var yani okumadıysam,  Babam okutmadı ki. Ben istemedim mi adam olmayı. Babam “okuyarak adam olunmaz”dedi Verdi daha 11imde tamirci  yanı...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ben-insanim-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar ve Müzik', 'sarkilar-ve-muzik-ozan-rari-sdscy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne hoştur senle coşmak

Nasılda anlıyorsun halden

İnsanları birleştiren

Yerine göre mesaj veren

Pop, rap, sanat, arabesk her telden çalarsın

Tabi söyleyende, çalanda senin parçan

Allah eksik etmesin seni benden

O zevk hep var olsun

Aşıkları mutlu etsin', 'Ne hoştur senle coşmak Nasılda anlıyorsun halden İnsanları birleştiren Yerine göre mesaj veren Pop, rap, sanat, arabesk her telden çalarsın ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sarkilar-ve-muzik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmet...', 'ahmet-ozlem-bayram-fnrim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ahmet! Onun adı Ahmet. Bir köyün öksüz çocuğu. Kendinden ve pirinçten başka kimsesi yok. Pirinç; köpeği.

	Henüz 18’ine yeni girmiş. Bir de sevdiği var sevildiğini bilmeden. İçten içe sevmiş onu Ahmet kendini bildi bileli. Ama şimdi biraz dertli. Evleniyormuş sevdiği...

	Alev! Adı Alev. Ahmet’in sevdiği. Çocuk sayılacak yaşta daha 14. Ne anlar evlilikten, daha evcilik çağındayken. Onu alacak adamın 2. Eşi olacakmış. Kuma Alev. Bir başlık parasına, birkaç koyuna tav olmuş babası. “daha iyisi can sağlığı”

	Ahmet balık tutar her gün. alır sabahtan kendi elleriyle yaptığı oltasını ve gider göl kıyısına.

	Yine öyle bir gün. farkı göl kenarında ağlayan Alev. Elinde oyuncak bebeği. Ahmet’in konuşması olur şey mi? Alev bu Alev. Hem sevdiği hem de yarı evli...

-Neyin var Alev? 

-Bir şeyim yok Ahmet. 

Hiçbir şeyim yok.

Ve birkaç gün sonra; Alev’in kayıp olduğunu öğrenir Ahmet. Bir gariptir yüreği. Balık tutmaya gider yine elinde olta, aklında sevdiği. Oltanın ucu kayaların arasına takılmış o sıra. Ahmet göle dalmış kurtarmak için misinayı. 

Çıktığındaysa elinde büyük bir balık...

Balık; Alev’ in cesedi...

özlem bayram

bir deneme...', 'Ahmet! Onun adı Ahmet. Bir köyün öksüz çocuğu. Kendinden ve pirinçten başka kimsesi yok. Pirinç; köpeği. 	Henüz 18’ine yeni girmiş. Bir de s...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ahmet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Değil...', 'uzak-degil-ozlem-bayram-6tncd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu uçsuz bucaksız dedikleri denizi görüyor musun? 

Ucu da, bucağı da var bence.

Deniz senin gözlerinde...

Şu sonsuz gökyüzünü görüyor musun? 

Hani bir masmavi, bir yağmurlu...

Gökyüzü benim gözlerimde. 

Şu ufuk çizgisini görüyor musun? 

Hani deniz ve gökyüzünün birleştiği

O kadar uzak değil...

Ufuk bizim göz göze geldiğimiz yerde.

ÖZLEM BAYRAM', 'Şu uçsuz bucaksız dedikleri denizi görüyor musun?  Ucu da, bucağı da var bence. Deniz senin gözlerinde... Şu sonsuz gökyüzünü görüyor musun?...', ARRAY['Türk Edebiyatı','Şiir','Özlem Bayram']::text[], 8.5, '{"poet":"Özlem Bayram","poet_slug":"ozlem-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uzak-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşlar', 'arkadaslar-ozan-rari-qtva7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her yerde var onlar

Kimi iyi kimi kötü

Halden anlar destek olur bazısı

Diğer yandan acı vereni çok fenadır

Arkadaştan yüzüm gülmedi

Hep firar hep hüzün

Daha gencim dur bakalım

Ne yoldaşlar gelir

Kalbini ferah tutu Deli Gönül', 'Her yerde var onlar Kimi iyi kimi kötü Halden anlar destek olur bazısı Diğer yandan acı vereni çok fenadır Arkadaştan yüzüm gülmedi Hep fira...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/arkadaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abime', 'abime-ozan-rari-qmlu2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O tek dost idi çocukluğumda

Güzel vakit geçerdi onunla

Ama çok önce terk etti beni

Yıllarca yalnız kaldım onsuz

Kardeş sevgiside başka oluyor

Şimdi evli ve uzaklarda

Mesuttur herhalde kimbilir? 

Hayat yolu uzun tek başıma komaz beni

Çok severim onu ben...', 'O tek dost idi çocukluğumda Güzel vakit geçerdi onunla Ama çok önce terk etti beni Yıllarca yalnız kaldım onsuz Kardeş sevgiside başka oluyo...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/abime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-ozan-rari-1bjf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Türlü türlü renkleri 

O şakırdayan ötüşleri

Masumluğun simgesi

Kader yoldaşlarıdır onlar

İnsanı kıskandıran kanatları

Kuşlar göçmen kuşlar

Sevgiliyi alıp götürenler', 'Türlü türlü renkleri  O şakırdayan ötüşleri Masumluğun simgesi Kader yoldaşlarıdır onlar İnsanı kıskandıran kanatları Kuşlar göçmen kuşlar S...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kuslar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim', 'severim-ozan-rari-amgjn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek bir tutku

Sevmek yaşamın ta kendisi

İnsanı, hayvanı, doğayı

Sevgi kalbe giden yol

Sevgisiz kalmak korkum

Sevdikçe varım ben', 'Sevmek bir tutku Sevmek yaşamın ta kendisi İnsanı, hayvanı, doğayı Sevgi kalbe giden yol Sevgisiz kalmak korkum Sevdikçe varım ben...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/severim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-ozan-rari-sfju2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim nur yüzlüm

Örnek aldığım insan

En zor, en kötü günlerin dostu

Cefakar, cömert insan

Mekanı cennet olan

Karnında büyüten yar

O öyle bir sevgiliki

Ne menfat ne de fitne bilir o can', 'Benim nur yüzlüm Örnek aldığım insan En zor, en kötü günlerin dostu Cefakar, cömert insan Mekanı cennet olan Karnında büyüten yar O öyle bir...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anneme-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yağacak', 'sevgi-yagacak-sair-ethem-3b40f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yagmur bulutlarini gordum sevgi yagdiracaklardi

yagmuru bekledim umutla dizlerimi cokup yere

ama olmadi

yine cok yuksekten gectiler onlar, baska birine aitlermis

uzulmus olacaklardi ki halime

bir kucuk melek yolladilar 

bir teselli, 

bir umut

opucugu kondursun diye

ethem

09/02', 'yagmur bulutlarini gordum sevgi yagdiracaklardi yagmuru bekledim umutla dizlerimi cokup yere ama olmadi yine cok yuksekten gectiler onlar, b...', ARRAY['Türk Edebiyatı','Şiir','Şair Ethem']::text[], 8.5, '{"poet":"Şair Ethem","poet_slug":"sair-ethem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgi-yagacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kış Öğrendim', 'bu-kis-ogrendim-selim-eysioglu-3t3ok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarısı bembeyaz, 

Lapa lapa kar yağıyor, 

Gönlümdeyse kızıl bir ateş, 

Aşkınla tutuşuyor.

Karlar altında her taraf

Sobayı yakmak zor geliyor

Oturdum camın önüne

Aşkın beni ısıtıyor

''Karlar ne kadar sıcak, 

Bu kış öğrendim bunu''

Koşup sana gelmek istiyorum; 

Aşkının beni esir aldığı zamanlarda.

Sonra vazgeçiyorum..

Karlar değil korkutan, 

Yollar değil korkutan

Sensin lanet olası: ya kapından kovarsan

Tek şekerli demli bir çay doldurdum, 

İçemeden soğudu.

Mum yaktım bir tane

Resminin önüne koydum

Seni aydınlatsa yeter, 

Başka her şeye tokum.

Mum alevinden bir sigara yaktım, 

İçemeden kül oldu.

''Hava ne kadar tiriyaki, 

Bu kış öğrendim bunu''

Şu dünya ne kadar bayat

Bu hayat ne sıkıcı, 

Sen yokken anlıyorum hep.

Duvarlar üstüme geliyor, 

Evim bana dar geliyor, 

Sokağa attım kendimi

Eve dönmek zor geliyor.

Karlar birer kor geliyor

''Karlar ne kadar yakıcı, 

Bu kış öğrendim bunu''

Buz gibi bir hasret, 

Buz gibi bir sevdadan sonra

''Karlar ne kadar sıcak, 

Bu kış öğrendim bunu''', 'Dışarısı bembeyaz,  Lapa lapa kar yağıyor,  Gönlümdeyse kızıl bir ateş,  Aşkınla tutuşuyor. Karlar altında her taraf Sobayı yakmak zor geliy...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bu-kis-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alış(a) mıyorum', 'alis-a-miyorum-riza-aslan-05xgh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıkılıyorum bu şehirde

gözlerim dalıp giderken uzaklara

o uzakları sahiplenemiyorum

gezdiğim sokaklar

kaldırımlarını eksittiğim caddeler

içime sinmiyor

uzaklardan 

başka bir yer çağırıyor 

beni

gel diyor

gidemiyorum

alışamıyorum bu şehire

- aslında alışmak da istemiyorum-

havasını, suyunu, insanını

sevemiyorum

gitmem lazım 

biliyorum

birgün gideceğim 

biliyorum

yine de

dayanamıyorum

bu şehir bana 

dar geliyor

sanki birileri 

boğazımı sıkıyor

ben bu şehire

alışamadım

alışamıyorum

alışmak da istemiyorum

22 / 09 / 2002

Bergama   /  İzmir', 'sıkılıyorum bu şehirde gözlerim dalıp giderken uzaklara o uzakları sahiplenemiyorum gezdiğim sokaklar kaldırımlarını eksittiğim caddeler içi...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/alis-a-miyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albino', 'albino-enis-batur-t509b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kaç gece kaç gün geçti bilmem; 

bembeyaz denizin üzerinden uçarı

bir kabuk, uzun, arşa yükselen

albino dalgaların savurduğu kör

bir lekeydim: yorgun, korkusunu

çoktan terketmiş, hem 
..........
..........', 'kaç gece kaç gün geçti bilmem;  bembeyaz denizin üzerinden uçarı bir kabuk, uzun, arşa yükselen albino dalgaların savurduğu kör bir lekeydim...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/albino-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-enis-batur-l4o96', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cehennem kimdir demiştiniz? 

Keder kuşlarını ben de gördüm

Flütün ucundan bir oraya bir buraya

Evet, biliyorum, herşey benim düşg
..........
..........', 'Cehennem kimdir demiştiniz?  Keder kuşlarını ben de gördüm Flütün ucundan bir oraya bir buraya Evet, biliyorum, herşey benim düşg .............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bekleyis-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fugue V', 'fugue-v-enis-batur-98ti4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu çocuğu hemen aldırtmazsam

''İşaretleri bunca sevdiğine göre

ona yorulmadan işaret vermeliyim''.

Nasıl yorulmazdı: Kapısına götürüp

bağladığı beyaz at, aynı gün içinde

postaya attığı binbir mektup, beklenmedik

gecede beklenen bir güneş olmak -

ve
..........
..........', 'Bu çocuğu hemen aldırtmazsam ''İşaretleri bunca sevdiğine göre ona yorulmadan işaret vermeliyim''. Nasıl yorulmazdı: Kapısına götürüp bağladığ...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fugue-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşü Olmayan', 'donusu-olmayan-cemal-safi-jqkhq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senmisin neşemi götüren zalim 

Seninde bugün son gülüşün olsun

Aşkımı burnumdan getiren zalim 

Dönüşü olmayan gidişin olsun.

En kötü günümü arattın bana

Ne benli hayalin nede düşün olsun

Melekten bir şeytan yarattın bana 

Dönüşü olmayan gidişin olsun.

Kimseden merhamet dilenmemiştim

Kapımda dilenmek son işin olsun

Kimseye ah edip ilenmemiştim

Dönüşü olmayan gidişin olsun.

Ben aşkın narına yandım seninle

Mum gibi eriyip sönüşün olsun

Gözyaşın ismimi yazsın diline

Dönüşü olmayan gidişin olsun.

Hıçkıra hıçkıra çığlık çığlığa

Martılar misali ötüşün olsun

Peşimde koşuştur soluk soluğa

Dönüşü olmayan gidişin olsun

Sarhoşa meze ol meyhanelerde

Günahkar ellerde bitişin olsun

Enkazın bulunsun viranelerde

Dönüşü olmayan gidişin olsun', 'Senmisin neşemi götüren zalim  Seninde bugün son gülüşün olsun Aşkımı burnumdan getiren zalim  Dönüşü olmayan gidişin olsun. En kötü günümü ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donusu-olmayan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kalbin İçinde Durmayı Bil', 'bu-kalbin-i-cinde-durmayi-bil-duygu-gunkut-w5j9m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kaldırım taşına takılıyor gözlerin

Yaz güneşinden esmerleşmiş dirseğinde bir karasinek

Başını tutuyorsun hafifçe aklının solunda, 

Aklın, benim sağımda, hep yanımda.

Yenilgilerin geçiyor kalabalık kaldırımlardan

Gözünün feri yardan geçiyor

Benim gözlerim senin aklından, 

Vazgeçiyor, Salacak İskelesi o an Üsküdar’dan.

Hep terli bir atın terkisinde bozkırları geçiyor cesedin

Ben bu sahnenin mutlak yalancı şahidiyim.

Dirseğinde durabilen karasineğe iznin, 

Benim, sana hep uzağına düşme mecburiyetim.

Karasineği kaldırıyor dirseğinden rüzgarı

Hızla yanından geçen bir kızın çantası

Düşünüyorum da biraz aklının uzağında, 

Biraz utangaçsın, aslında biraz tuhaf, neredeyse yabancı.

Bağıran suskunluğun var bu kent ile aranda

Merdivenlere adım adım tırmanan cinayetlerin

Benim aklıma tutunmuş, tutuşturulmuş, 

Ah, bu akıl almaz yüreğin.

Anlatıyorsun, konuşur gibisin herşeyden

Kaygıların, ah bu rüyaların hiç sırasını bilmeyen.

Ben seni dinliyorum, kaldırım taşına takılı gözlerini, 

Bu kalbin içinde durmayı bir türlü bilemedin ki.', 'Bir kaldırım taşına takılıyor gözlerin Yaz güneşinden esmerleşmiş dirseğinde bir karasinek Başını tutuyorsun hafifçe aklının solunda,  Aklın...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-kalbin-icinde-durmayi-bil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlemem Daha Bitmedi', 'seni-ozlemem-daha-bitmedi-duygu-gunkut-kbujc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahları seviyor bu kız

ama sabahları uyanmayı değil, 

sabahlara doğmayı seviyor, 

sisin hafif yorganımsı inmesi gibi ortalığa

kendini armağan etmeyi biliyor

hiç kimsesi olmayan birinin

yalnızlık duygusuna.

Doğmayı biliyor ve çoğalmayı

susmasını da biliyor, 

henüz başlamamış bir aşkın karşısında

takılı oltada bir balığın gırtlağına

çırpınmadan durmasını biliyor.

Bıkmaksızın usanmadan

sabalara doğuyor, 

o, biliyor...', 'Sabahları seviyor bu kız ama sabahları uyanmayı değil,  sabahlara doğmayı seviyor,  sisin hafif yorganımsı inmesi gibi ortalığa kendini arma...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-ozlemem-daha-bitmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-hulya-senkul-r4nj5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde mayalandı acılar

Hasret bana zor geliyor bir tanem

Hele bir de başlayınca geceler

Bu can tene dar geliyor bir tanem

Çaresizlik aramızda dağ gibi

Deli gönül su görmemiş bağ gibi

Düşündükçe üzerime çığ gibi

Duman duman kar geliyor bir tanem

Ayrılığın kucağında yoruldum

Sensiz bittim, tükendim, hep kırıldım

Haydi yetiş yaralandım, vuruldum

Nefes almak zor geliyor bir tanem', 'Yüreğimde mayalandı acılar Hasret bana zor geliyor bir tanem Hele bir de başlayınca geceler Bu can tene dar geliyor bir tanem Çaresizlik ara...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şenkul']::text[], 8.5, '{"poet":"Hülya Şenkul","poet_slug":"hulya-senkul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-tanem-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'adresim-sensin', 'adresim-sensin-gonul-sen-dxzmm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklına ayrılık getirme sakın

Kalbin hislerinden şüphe etmesin

Mutluluk yolunda bana en yakın

Benim değişmeyen adresim sensin

Hayallerimdesin, düşlerimdesin

Yürek atışımda, can evimdesin

Uzayıp giden bu aşk sokağında

Benim değişmeyen adresim sensin

Kırılsa gönlümün kanadı, kolu

Ne yağmur dinlerim, ne kar, ne dolu

Gözlerim kapalı bulurum yolu

Benim değişmeyen adresim sensin

Bütün sokakları dolaştım nafile

Adresim sensin

Elimden hiç bir şey gelmiyor

Allah''ım kahretsin

Seni çok ama çok seviyorum

Her şeyim sensin

Biliyorum ki yanlış adrestesin', 'Aklına ayrılık getirme sakın Kalbin hislerinden şüphe etmesin Mutluluk yolunda bana en yakın Benim değişmeyen adresim sensin Hayallerimdesin...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adresim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Ol Yeter', 'mutlu-ol-yeter-tahir-paker-48j2w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belki de dilinden bu şarkı düşmez

Dilin söylese de gönlün hissetmez

Bilsem bile benim için farketmez

Bir tek dileğim var, mutlu ol yeter

Bunu sana yazdığımı bilmezsin

Bir yabancı şarkı gibi dinlersin

Benim için önce Allah sonra sensin

Bir tek dileğim var, mutlu ol yeter

Kimse dolduramaz inan yerini

Bu şarkı da aşkımızın yemini

Hiç düşünme Mecnun muyum, deli mi

Bir tek dileğim var, mutlu ol yeter

Bu şarkıda aşkımı anlattım sana

Duymazsan sevgilim üzülmem buna

Alıştım yıllarca ben yokluğuna

Bir tek dileğim var, mutlu ol yeter', 'Belki de dilinden bu şarkı düşmez Dilin söylese de gönlün hissetmez Bilsem bile benim için farketmez Bir tek dileğim var, mutlu ol yeter Bun...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mutlu-ol-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Olay Olacak', 'askimiz-olay-olacak-askin-tuna-8gk8u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tam hayallerim gibisn

Sevmem çok kolay olacak

Sende beni seversen

Aşkımız olay olacak

Akacak coşkun sellerde

Esecek deli yellerde

Dolaşıp bütün dillerde

Aşkımız olay olacak

Gönlüm bir deli

Sevdim bak seni

İnan bu sevgimi

Tarih yazacak

Haydi yak beni

Durma sar beni

Aşkımız olay olacak

Yakarken bizi ateşi

Doğacak sevda güneşi

Görülmüş değil böylesi

Aşkımız olay olacak', 'Tam hayallerim gibisn Sevmem çok kolay olacak Sende beni seversen Aşkımız olay olacak Akacak coşkun sellerde Esecek deli yellerde Dolaşıp bü...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/askimiz-olay-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-oktay-kara-1nvsr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'benim tanıdığım kaldırımlar yok artık

uzanır önümde, nereye gittiğini bilmeden

çocukluğumun sokakları unutmuş beni.

cahil sokakların ziftleri

çocukluğum dün gibi.

olsaydı yanımda telli arabam, 

misketim, gazoz kapağım.

kalbe düşmüş zaman.

karın üzerine düşen yağmur, 

şimdiki zaman.

çocukluğum gelir aklıma, 

yürüdüğüm yollarda kaldırımlar tanır beni

ben tanıyamam kendimi.', 'benim tanıdığım kaldırımlar yok artık uzanır önümde, nereye gittiğini bilmeden çocukluğumun sokakları unutmuş beni. cahil sokakların ziftler...', ARRAY['Türk Edebiyatı','Şiir','Oktay Kara']::text[], 8.5, '{"poet":"Oktay Kara","poet_slug":"oktay-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklugum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlerin Gecesi', 'dortlerin-gecesi-adnan-yucel-1a3n8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlenen ateş yakılmıştı sonunda

Elden ele bütün dünyaya taşınmıştı

Kıvılcım dansıydı gözlerdeki sevinç

Kavga dağlarda bilinci kuşanmış

Zindanlarda dirence sarılmıştı

Ve haykıran dudaklar

Her ihanet vakti çöl çöl yarılmıştı', 'Özlenen ateş yakılmıştı sonunda Elden ele bütün dünyaya taşınmıştı Kıvılcım dansıydı gözlerdeki sevinç Kavga dağlarda bilinci kuşanmış Zinda...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dortlerin-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutup Yıldızı', 'kutup-yildizi-adnan-yucel-t4i2s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O korku vardı hep çıkılan yolda

O korkusuzluk vardı

Suyun su olduğu günden beri akardı

Biri can verip aydınlatır

Diğeri boğar ve yakardı

Yaşamın her dönüm noktasında

Bir ileri bir de geri

Atılan adımlar gibi alçalma ve yücelme

Atılan adımlar gibi

Büyüme ve küçülmeydi adı

Biri sevgi olup yapardı

Diğeri öfke olup yıkardı

O korku vardı hep çıkılan yolda

O korkusuzluk vardı', 'O korku vardı hep çıkılan yolda O korkusuzluk vardı Suyun su olduğu günden beri akardı Biri can verip aydınlatır Diğeri boğar ve yakardı Yaş...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kutup-yildizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleri', 'ayak-i-zleri-bejan-matur-hgpoj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kuyuya eğildiğinde

Yüzünü görecek su yoksa

Çekil

Öldürse de su seni

Görerek öldürür

Susuz kuyudan kork

Kuru düşünme cehennemi

Nemlidir

Ve ayak izleri vardır

Önceden

Gidecek olan herkesin', 'Bir kuyuya eğildiğinde Yüzünü görecek su yoksa Çekil Öldürse de su seni Görerek öldürür Susuz kuyudan kork Kuru düşünme cehennemi Nemlidir V...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan-matur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayak-izleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüyen kız Berrak', 'buyuyen-kiz-berrak-ozan-rari-2bnmt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elbet geçer her insan o yoldan

     Masumduk yalansız dolansız! 

     Birden bize bişeyler oldu, her şey dönmeye başladı 

     Okul yılları hey günler hey nerelerdesiniz şimdi oysa? 

     Başlardık karşı cinse sokulmaya, anlamaya

     Bir kız vardı çok uzaklarda 

     Adı berrak idi

     Oda saf ve masum, memleketim koşularında yaşardı

     Kimi zaman hüzünlü kimi sevinçli

     Zaman geldi geçti kuşlar uçmaz oldu

     Bir kız vardı adı Berrak idi', 'Elbet geçer her insan o yoldan      Masumduk yalansız dolansız!       Birden bize bişeyler oldu, her şey dönmeye başladı       Okul yılları ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/buyuyen-kiz-berrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemen''in Dönüşü', 'yasemen-in-donusu-ozan-rari-95nub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüya gibiydi senle geçen kısa zaman

    Gerçek miydin yoksa hayal mi anlayamadım doğrusu

    Adın aklına yasemen idi, gözlerin aklımda yeşildiler

    Neydi hisslerim sana olan neydi aşk sanırım

    Sen ne haldeydin ne ben, ne sen, ne de diğerleri bilemedi

    Çoktu derdin, geçmişin peşinde bırakmıyordu ellerinden

   

     Hani vardı ya sohbet ederdik okul kantininde

     Seni görmek bana hayat verirdi

     Her zaman harika her zaman güzeldin sen

     Ansızın çekip gittin be yasmin

     Çok koydu bana bilemezsin! 

     Duydum dönmüşsün buralar ben çoktan unuttum

     Sen yaşamaya devam et, nedeni sende saklı! 

     Ömür çok kısa deymez yasmin deymez...', 'Bir rüya gibiydi senle geçen kısa zaman     Gerçek miydin yoksa hayal mi anlayamadım doğrusu     Adın aklına yasemen idi, gözlerin aklımda y...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasemen-in-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabia Ülkü Akçay Mıydı Neydi Adın', 'rabia-ulku-akcay-miydi-neydi-adin-ozan-rari-yiy1d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Razıydım senle bir ömre korkuların gözlerinde

   Akıl, mantık yoktu onlardan uzak geçerdi zaman seninle

   Bilakis kurtuldum derdin en belasından

   İstemem dünyayı verseler bir daha seni! ! 

   Ancak unutmak kolay değildir beni bilesin

    Üzülmek dışında meşgalem yoktu senle

    Laflar vardır ağızdan çıkar laflar vardır senden çıkar

    Kimse böyle ders veremez bana gayri

    Ülkü hocamsın benim dünya, ahiret

  

    Akçay dediğin ferah gelir kulağa sen karasın kapkara

    Keşke olmasaydı diyorum ama sevdim elimde değil

    Çekip gittim buralardan sen uzakta kalasın diye

    Artık yok öyle kaybolmak savaş yeridir bura savaş! 

    Yarın ne olur bilemem, seni artık hiç mi hiç sevemem! ! !', 'Razıydım senle bir ömre korkuların gözlerinde    Akıl, mantık yoktu onlardan uzak geçerdi zaman seninle    Bilakis kurtuldum derdin en belas...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/rabia-ulku-akcay-miydi-neydi-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-hikmet-szlemiolur-hnlvu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'vatandas bunalmis

vatandas bunamis

vatandasa ne

tam bir matador giymis

beyaz gomlekli ve beyaz corapli 

ceketli bir adam silinmisti kayitlardan

mutlu ol yeter dogan lar

cikamazdi altinolugun

gemi seyhatlerine

ve yarim yamalakti etekleri teyzelerin

kalin bir corap cekerlerdi

metroya binemezdi onlar

yururken paytak paytak

kaldirimla birlerdi

kimse de kalkip demedi

kimse de kalkip kalkmadi

kimse de yoktu zaten

birkac kisiydik biz

ben sevemedim mesela

birseyler anlatmayi

anlamayi sevmiyorlardi cunku

inanmak gelmiyordu icimden mesela

kangren omus ayaklarimi

orospu

travesti olmus bir millettik

ben sigarayi', 'vatandas bunalmis vatandas bunamis vatandasa ne tam bir matador giymis beyaz gomlekli ve beyaz corapli  ceketli bir adam silinmisti kayitlar...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/deprem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ulan', 'ulan-hikmet-szlemiolur-922nl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir nevi cay bahcesiydin

unkapaninda

ya da cafe java coast da

brisbane in bir kosesinde

avustralya da

mavi jeans vardi

blue cinler vardi sokaklarinda

gurbet mi

tam da susadigimda

sert bir dag suyuydu

kizilcahamamin

topraginda ayak izlerin vardi

sahillerinde behramkalenin

silinirken botanikteki 

dudaklar gozlerimden

caresiz bakismalardan korkuyorum

sona ulastigimiz an

sana ulastigimiz an', 'bir nevi cay bahcesiydin unkapaninda ya da cafe java coast da brisbane in bir kosesinde avustralya da mavi jeans vardi blue cinler vardi sok...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ulan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamze', 'gamze-hikmet-szlemiolur-9i48k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'toparlanirdi bir gun

hatta haftdaki gunlerde gelirdi

ve arabalardan bahsedilirdi 

ya da kizlardan

acaba kazlar da bahsedilir miydi? 

acaba mafyaydik biz de sahiden

ben mi cahildim? 

attiklari laflari yakalamadigim icin

icinde bisey var derlerdi bana cocuk

agzimi acinca

manasiz birseyler kusuyordum

ve soframiz oluyordu

kahkahalarim agliyordu

disarda bir ses

hic cizgiler olarak dusunduk mu bu hayati

yoksa bosverirken mi kusmaliyiz kluplerin kapisina

askin fotografini cekiyorum

ingiliz kedisi avuclarda oluyor

ama yine de bagirsak

organ olarak anlasiliyoruz

herkes kaciyor talibandan

durmak istiyor bir araba

sabah sabah kopru tikaniktir diye

hal buki mizani goren yok

yoldaki isaretlere

gozlerimizi gommusuz

gomulmekten kasdimiz

ya uzun bir organ olmus fikrimizde

ya da bir yumruk gozde patlayan', 'toparlanirdi bir gun hatta haftdaki gunlerde gelirdi ve arabalardan bahsedilirdi  ya da kizlardan acaba kazlar da bahsedilir miydi?  acaba m...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gamze-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kare', 'kare-hikmet-szlemiolur-hgjhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'biz varsayip duruyorduk

tukenip duruyormus gibi duruyordu hava

ankarada hersey yokoluyordu

alip goturdu icimden

valla gardas gormedim

diye yemin ediliyordu

duman da cikiyordu agzimdan

toprak kokusu vardi

dudaklarin sigarali ve islakti

olicem zannetmistim

duman bizim kediydi

atakuleden yere atmistim

cikan sese dunyaya kusmustum

herkes hakliydi

bir duramadim karsisinda trenin

hep yamicak oluyorum

sonra ayrilamiyorum bedenimde

disardaki adama hediye olsun diye

aman evi uyandirma

saklan bir koseye

okuldan cikip ise ordan da toprakla bulusacakti

boylece bir gunde gocup gidecekti

hattan dusuyordum bir gece

her gece sokaklar girerdi icime

ne zaman tuttuysam seni

titrerdi kalbim

benden s o n r a bugulandi sahiller

sarkilar soyledi zaman insanliga

ve acilara tutundum yillarca

ac kalmak gibi

o zamanlar metro dortte gecerdi 

buyuk olaydi benim icin o zaman

huzunluydu

simdi bosaldik

bir ileri bir de geri

sarsiliyor farkindamisin tavan

bir ritme kaptirmisim

ceketimin icini

donmekte gozlerim

evren goz bebegim

ve yalnizca dusuncelerim durmus

sigaram dudagimda bocalamakta', 'biz varsayip duruyorduk tukenip duruyormus gibi duruyordu hava ankarada hersey yokoluyordu alip goturdu icimden valla gardas gormedim diye y...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakit Tamam', 'vakit-tamam-timurtas-ucar-sif7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okudum: 

Okudugumu yol, yol dokudum.

Gördüm: 

Gördügümü lif, lif ördüm.

Duydum: 

Duydugumun en güzeline uydum.

Okuyana, görene, 

Duyana, anlayana

Bin Selam.............

Ten cürük bir kafes

Hayat bin anlik nefes

Allahu bes

Baki heves

Bes: Allah`ta dügümlenir

Baki: Arkada kalan

Fatih - Carsamba', 'Okudum:  Okudugumu yol, yol dokudum. Gördüm:  Gördügümü lif, lif ördüm. Duydum:  Duydugumun en güzeline uydum. Okuyana, görene,  Duyana, anl...', ARRAY['Türk Edebiyatı','Şiir','Timurtaş Uçar']::text[], 8.5, '{"poet":"Timurtaş Uçar","poet_slug":"timurtas-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vakit-tamam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Perdesi', 'dus-perdesi-huseyin-kerim-ece-p5v14', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam Güneşi, bir de takvimi öğretirdi, 

Seherin anlamını, zamanın aktığını,

Soframıza besmele umutlar getirirdi, 

Anlardık her saatin sonsuza baktığını,

Babam eski atların seyisidir her zaman, 

Dala tutunmayı ve kazma vurmayı bilir, 

Toprak elinde şekil alır; terden ve kandan,

Gözlerinde bin kere ufuk çizgisi erir.

Yazgının delisidir, isyanı bilmez babam, 

Sabahı ilk saçından tutar göle götürür, 

İşaret alınmıştır, vakit ve vâde tamam, 

Artık kendi düzünde yürümektedir ömür.

Ben kravat takmayı babamdan öğrenmedim, 

Tarlaya aşk ekmeyi ilk defa onda gördüm, 

İkindi yoğun ekmek ve bahardır her mevsim, 

Yalnız göğüs altında siyah, yağlı bir düğüm, 

Çoğalırken sorgular, şapka giyen horozlar, 

Eldivenli maymunlar, kırkikindi yağmuru, 

Güneş doğuda battı, akşamı tuttu pazar, 

Sular artık bulanık ve ardında hep soru.

Babam dirençli adam; kökleri derinlerde, 

Bir emeğin buğusu yarasına örtüdür, 

Ezelden bir ışığın gölgesine düşer de 

Dünyasına annemi, bir de beni götürür.

Güneş bu kez babamın ellerinde doğacak, 

Toprağı tez yaracak en değerli ışıklar, 

Göverecek fidanlar, yanacak sönen ocak, 

Bir kuytuda yitecek yüzyıllık yalnızlıklar.

                       19/12/1984  Eskişehir', 'Babam Güneşi, bir de takvimi öğretirdi,  Seherin anlamını, zamanın aktığını, Soframıza besmele umutlar getirirdi,  Anlardık her saatin sonsu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dus-perdesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Bir Yaşamaktır', 'huzun-bir-yasamaktir-huseyin-kerim-ece-8wgg2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzün bir yaşamaktır; gölgelerden arınmış

Yokuş bir nağmedir ki doğumlarda titreyen

Her gece gözlerimden haritalar çalınmış

Girmiş pembe yatağa o dükenli sütleğen

Bir usta balyoz vurur yeni ve mor hülyalara

Bir denizci ağ atar yalçınlaşan düşlere

Kapanır da kapılar ötede başlar sara

Bir yanlış ayak bağı doğan yürüyüşlere

Giden gitmiştir, şimdi uzaklarda hayal var

Ufukta gölge ve renk yavaşça küçülmüştür

Başlayan hüzne ortak içimdeki çarşılar

Üstüme çöken bulut sonu gelmez düştür

Yolun sonunda keder varsa da behey gönlüm

Aşmaya gücün yeter bu demirden düzlüğü

Nihayet çıkacaktır karşına bir gün ölüm

Tadmaya koşmalısın bugün ölümsüzlüğü

Ölümsüzlük içimde can, çevremde bahardır

Bir vadi bildirisi, bir zindan kurtuluşu

Bütün yürüyüşlerde sabit bir yazgı vardır

Gönlün hem kaybedişi, hem yeniden buluşu

Bir yay gerdim, taze ok attım can siperinden

Yürekler ovasında niceyi tutsak ettim

Bu gönül macerası çıkıverir derinden

Ben aynayı ilk defa yolculukta seyrettim, 

Dağınık güzellikler yormuştur dizlerimi

Üstüste yalçın rüya ve anlattığım ırmaklar

Badanasız duvarlar örtecektir derimi

Bir gün beni de dostlar sultandan sayacaklar.

Eskişehir 1985', 'Hüzün bir yaşamaktır; gölgelerden arınmış Yokuş bir nağmedir ki doğumlarda titreyen Her gece gözlerimden haritalar çalınmış Girmiş pembe yat...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/huzun-bir-yasamaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alkol', 'alkol-ozan-rari-hne8y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne garip şeysin sen insanı değiştiren

Aklını başından alan; hüzünde, sevinçte

Haram diyorlar senin için

Seni bırakmak nasip olur inşallah bana

Yetmedi mi yaptıkların ettiklerin

Yok ol görmesin gözüm!', 'Ne garip şeysin sen insanı değiştiren Aklını başından alan; hüzünde, sevinçte Haram diyorlar senin için Seni bırakmak nasip olur inşallah ba...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/alkol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya', 'dunyaya-mehmet-fatin-baki-z3cp8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hageldim ağlaya ağlaya 

Sıkıntılarla bu dünyaya 

Bi-çare, uryan, çırıl çıplak

Yavaşça gitmeliyim yaya 

Rahat huzur dolu dünyaya 

Beyaz kefenle temiz ve pak

Mefailun  Feilun  Feul

.  /.   /  . .  /  .   /', 'Hageldim ağlaya ağlaya  Sıkıntılarla bu dünyaya  Bi-çare, uryan, çırıl çıplak Yavaşça gitmeliyim yaya  Rahat huzur dolu dünyaya  Beyaz kefen...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dunyaya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-mehmet-fatin-baki-rk5gi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmekle sevilmek yaşanan güçlü  muamma

Söyler kimi gaflet, kimi der bimecemizdir

Alemde bu aşk-illeti yoktur bilen amma

Sevmek zedeler kalbi, sevilmekse lezizdir 

Fa’lun     Feilatun    Feilatun   Feilatun

/     /     . .   /   /   ..  /   /  ..   /   /', 'Sevmekle sevilmek yaşanan güçlü  muamma Söyler kimi gaflet, kimi der bimecemizdir Alemde bu aşk-illeti yoktur bilen amma Sevmek zedeler kalb...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/muamma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Yüzü', 'siirin-yuzu-serkan-gun-uluql', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan Yüzlerine Benzer Şiirler

Hepsinin İçinde Sırlar Saklı

Daima Başka

