INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Duş', 'soguk-dus-ozan-rari-eesz8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vardı ya o hayat veren gözleri

O sımsıcak dokunuşları

Saatler süren hoş sohbetler

Akan gözyaşları! 

Hep bir korku ayrılığa dair

Kalplerin çöküşü, hüsranı

Değerlerin, saygının kayboluşu

Sonunda o ölümsüz sanılan sevda''nın toprağa verilişi! 

Mevsim geçerde karşılaşırsın ya; işte buz gibidir o an.

-Çok sevip ayrılanlara hitafen...-', 'Vardı ya o hayat veren gözleri O sımsıcak dokunuşları Saatler süren hoş sohbetler Akan gözyaşları!  Hep bir korku ayrılığa dair Kalplerin çö...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soguk-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Bunu', 'unut-bunu-mehmet-fatin-baki-0ufgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aldın beni bir kul gibi, sen kendine bağladın

