INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerlik Şiirler ''Sürgün Saatler''', 'askerlik-siirler-surgun-saatler-ali-riza-erdem-wqgzo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sürgün saatler var bu yürekte 

yürekten sürgün sevdalar

yaşanmış bir zamanın hesabını yapıyoruz 

yaşanmayacak zamanların üzerinde çizikler atıyoruz

ikinci bir hayatın kapısını aralamayı bekliyoruz

gelecek üzerine hayaller kurup, bugünü unutuyoruz

gelecek üzerine üç köşe teşkiller yaratıyoruz 

umutla....

ve kaderimizi sıfırlama atışlarıyla tekrar başlatıyoruz. 

a.r.erdem

izmir 

şafak: 158', 'sürgün saatler var bu yürekte  yürekten sürgün sevdalar yaşanmış bir zamanın hesabını yapıyoruz  yaşanmayacak zamanların üzerinde çizikler a...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askerlik-siirler-surgun-saatler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbette', 'nobette-ali-riza-erdem-jdedk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'evimden çok uzaklarda 

soğuk bir koridor ortasındayım şimdi 

sonu belli olmayan zamanlar akıyor 

üzerimden 

dönüp bakamıyorum bile 

üşüyorum.... 

19/12/2001 

