INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesut''a Cevap', 'mesut-a-cevap-ali-riza-erdem-xfgja', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'son gülüşlerini iyi sakla yüzünde 

esen yellere bırakma sakın 

sakın yitirme umudu yüreğinde 

bekle ki umutda seni yitirmesin 

bu gözyaşların yüreğime akması 

bu hasretlerin bir sel olup taşması 

gidişimle sadece seni bırakmıyorum 

tüm bebkliğim

tüm çocukluğum

tüm gençliğim 

bütün bir şehir 

bütün bir ülkeyi 

bütün yaşanmışları bırakıyorum ardımda 

gidişimle 

yeni bir hayatın kapısı aralanıyor birazda 

ileride sonunda kadar açmak kaydıyla 

gidişimle 

yeşil tonunda bir yaşam başlıyor

ve buralarda yeşil e 

''HAKİ'' deniyor 

02/12/2001 - 14/12/2001 

izmir / narlıdere', 'son gülüşlerini iyi sakla yüzünde  esen yellere bırakma sakın  sakın yitirme umudu yüreğinde  bekle ki umutda seni yitirmesin  bu gözyaşları...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mesut-a-cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismarlama Şiir', 'ismarlama-siir-ali-riza-erdem-t6ec5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bıraktığın sensİzilikti 

ince ince yağarken yağmur 

nerede ve 

nasıl kaybetmiştim

umudu gençliğimi herşeyi 

riyakar zamanlardı 

seni benden ayıran

ayrılık zaten

razı olunmayan 

ancak yaşanılandı 

1.çvş.talimgah 

izmir - narlıdere

alirizaerdem', 'bıraktığın sensİzilikti  ince ince yağarken yağmur  nerede ve  nasıl kaybetmiştim umudu gençliğimi herşeyi  riyakar zamanlardı  seni benden ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ismarlama-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerlik Şiirleri '' İsımsiz Yare''', 'askerlik-siirleri-i-simsiz-yare-ali-riza-erdem-2sma4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her kapı açılışında ürperir yüreğim 

kapıdan sen girecekmişsin gibi gelir 

her telefon çalışında çarpar yüreğim 

seini duyacakmışım gibi gelir 

her gün sensiz geçer 

her saat sensiz 

ben yoktur aslında buralarda 

ben seninledir

burada olan etten ve kemikten 

bedenimdir 

ruh seninledir....

alirizaerdem', 'her kapı açılışında ürperir yüreğim  kapıdan sen girecekmişsin gibi gelir  her telefon çalışında çarpar yüreğim  seini duyacakmışım gibi gel...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askerlik-siirleri-isimsiz-yare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai', 'rubai-ali-riza-erdem-sgkr2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o kahrolası hayatın

hangi durağındasın şimdi 

nasıl bir durağanlıktır üzerindeki 

alirizaerdem', 'o kahrolası hayatın hangi durağındasın şimdi  nasıl bir durağanlıktır üzerindeki  alirizaerdem...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer Gözüm', 'gecer-gozum-ali-riza-erdem-s8ba6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geçer gözüm 

bu günler bu dertler

elbet geçer 

geçer gözüm 

yürekteki sızı geçer 

sevda geçer - aşk geçer 

her gece rüyamda hayalin geçer 

geçer gözüm

türküler dolusu hasretler geçer 

günler, haftalar, aylar, mevsimler geçer 

geçer gözüm 

ömür dediğinde bir gün gelip geçer 

tabutum bir gün önünden geçer 

18-01-2002

izmir 

--', 'geçer gözüm  bu günler bu dertler elbet geçer  geçer gözüm  yürekteki sızı geçer  sevda geçer - aşk geçer  her gece rüyamda hayalin geçer  g...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecer-gozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim Gübrelendim', 'sevdim-gubrelendim-umut-ulbegi-uo5jx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdim

Aldım ağzımın payını

Bittim

geldi gübrelenme vaktim

sevdim

verdi ağzımın payını

delirdim

düştüm karadeliklere

birden o belirdi

allahtan verdi de gübremi

biraz dirildim

sonra çekip gitse de

verse de arada bir ağzımın payını

onu hep sevdim

ona delirdim

onunla dirildim.

05.07.1995

İzmir', 'Sevdim Aldım ağzımın payını Bittim geldi gübrelenme vaktim sevdim verdi ağzımın payını delirdim düştüm karadeliklere birden o belirdi allaht...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdim-gubrelendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarihçe', 'tarihce-umut-ulbegi-e0g2u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yirmi 

sekiz

nisan

bin

dokuz

yüz

doksan

yedi

sen yoksun

ve sensiz ilk gece de yok

On

bir

ekim

iki

bin

iki

ben de yokum.', 'Yirmi  sekiz nisan bin dokuz yüz doksan yedi sen yoksun ve sensiz ilk gece de yok On bir ekim iki bin iki ben de yokum....', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tarihce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiklal Caddesi', 'i-stiklal-caddesi-figen-kiroglu-fq20s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'caddedeyim yine, 

yürüyorum, öyle kalabalıkta 

hava kararmış her zamanki gibi

esen rüzgar üşütüyor beni, titriyorum

insanların yüzlerine bakıyorum, şaşkın

unutmak istiyorum belki her şeyi

hızlı adımlarla yürüyorum o yüzden

her şeye gülüyorum.

sıkılıyorum sonra kalabalıktan

dalıyoruz bir ara sokağa düşünmeden, 

nasıl olsa çıkarır bizi bir yere, 

burası daha iyi gibi

gittiğim salaş bir kafe var.

bugünlerde huzur bulduğum tek yer, biliyor musun

unuttum galiba diyorum.

daha bir hızlı yürüyorum, aldığım kuvvetle

sonra gözüm bir şeye takılıyor

donup kalıyorum olduğum yerde

gördüğüm ise sadece bir tabela

burasıydı diyorum, yanımdakine

işte burasıydı! ! ! 

burayı aramıştık o akşam

nasıl da bir aşağı bir yukarı koşturmuştuk birlikte

bulamamıştık sonra

ben hala bağırıyorum '' burası''

“buldum işte bak kapanmamış.”

oysaki ne önemi var artık

zaten yanımdaki de anlamıyor.

öyle şaşkın bakıyor bana

çekiyor kolumdan beni, giriyoruz benim salaş kafeme.

tanıdık yüzler gülümsüyor bana, hoş geldiniz diyor

işte bu melodi de tanıdık

rahatlıyorum biraz olsun

konuşuyorum insanlarla

oysaki yeni tanıştım daha

hatta hiç birine karşı bir şey hissetmiyorum

ama niye konuşuyorum, güldürüyorum onları

oysaki ben konuşmam sevmediğim insanlarla bilirsin.

gülerken canım sıkılıyor birden

çıkıyoruz yine caddeye

aslında hava çok güzel

ama üşüyorum ben yine

çocukluk anılarımızdan bahsediyoruz, birbirimize

bandoda borazan çaldığından bahsediyorsun taklidini yaparak

güldürüyorsun o halinle beni

ne ilginç, niye anlatıyorum bunları sana

gökyüzüne bakıyorum, yıldızlara “ben iyiyim galiba” diyorum.

gözlerimi kapatıyorum bir an, 

yüzün gözlerimin önüne geliyor, aniden

oysaki aklımda bile değildin o an

yanımdaki konuşuyor durmadan

dinlemiyorum artık onu

sen değilsin yanımdaki, canım sıkılıyor

senle de yürümüştük, işte tam burada

belki ayak izlerimiz duruyordur hala

bakıyorum ama yoklar 

tıpkı senin gibi, 

hızla uzaklaşıyorum kaçar gibi

daha bir hızlı yürüyorum.

her şeyi unutmak ister gibi.

31 Ocak 2002', 'caddedeyim yine,  yürüyorum, öyle kalabalıkta  hava kararmış her zamanki gibi esen rüzgar üşütüyor beni, titriyorum insanların yüzlerine bak...', ARRAY['Türk Edebiyatı','Şiir','Figen Kıroğlu']::text[], 8.5, '{"poet":"Figen Kıroğlu","poet_slug":"figen-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/istiklal-caddesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-cuneyt-ozdemir-3o77n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gittiğinde, 

...sonbahar tüm hüznü ile çöker omuzlarımın üstüne.

Yapraklar sararır birden bire, 

dökülürlü omuzlarımdan kırık kalbimin

derinliklerine.

Yabancı dilde söylenen bir tangonun

anlaşılır hisleri

ele geçirir ruhumu, 

sessizce...

Omuzlarıma doğru, uçurumlara kendimi feda ederim.

Göz  yaşlarımın umutsuz direnişinde

seninle birlikte sensiz

sonsuzluğa  düşerim.

Pencereler kapatır göz kapaklarımın önünü.

Gözlerim duymaz

olur.

Sesin zaten görülmez...

Oysa sen yankılanırsın uzaklardan

kopup gelen yüzünün izinde..

Beni bana taşıyan bin bir türlü aşk

tarifinde...

Bir koku hediye kalır sen gittiğinde...

Sensizlik kokusu kaplar evleri, sokakları, 

bu umutsuz, 

bu terkedilmiş, 

bu ürkek şehrin

şu yalnızlık havasını.

Yanımdan geçen

her kadının kokusu sensizliği taşır bana.

Sensizlik ağırdır, 

sensizlik uzundur, 

sensizlik zordur.

Sokaklar boş, 

sözler boş, 

şehir boş, 

her şey boşalır...

Bir sessizlik çöker artık ihtiyar

adımlarıma.

Gençlik ağır gelir sensizlik sınırlarında.

Gemiler vardır sana doğru gelen, 

trenler, uçaklar, arabalar...

Bir de ''ah bir çalsa..'' dediğim telefonlar.

Sesinin o sarı hasreti.Uzaktan  kopup gelmesini beklediğim 

o bir çift sözün hasreti.

''seni seviyorum''

dediğin o sessizliklerin hasreti...

Ağzından çıkan her

kelimenin pastel rengini özlerim, 

omuzlarının utangaç duruşunu, 

soğuk havalarda hoyratça ellerini tutuşumu.

...seni özlerim, 

sensiz sessizliğimde.

Sen gittiğinde, durur zaman.

Güneş, ay, bulutlar öylece durur.

Dalgalar durur, 

rüzgarlar durur, 

insanlar durur.

Ben durmam.

...ben seni özlerim.

Durmadan, 

bıkmadan, 

usanmadan

döneceğin günü beklerim.

Bulutlara takılırım, 

güneşle şakalaşır, 

dolunayda gölgeni ararım.

Dalgalar bir türlü yazıp

sana atamadığım şişelerin hesabını  sorar, 

rüzgarlar kolumdan tutup beni sana taşımaya kalkar, 

çok geçmeden

insanlar ne olduğunu anlamaya başlar.

Sen, acımasız zamanı

da beraberinde götürürsün.

Tüm saatler, 

dakikalar, 

saniyeler

saygıyla geleceğin günü bekler.

Ben de beklerim.

...sensiz zamanı bensiz geçiririm.

Sen gittiğinde

uçan bir halı ile düşlerine konuk olurum.

Kendi rüyalarımdan

Seninkilere

bir masal prensi olarak patika bir

yol bulurum.

Uykularımda sana koştuğum için sensizken hep seninle uyurum.

Göz kapaklarım sana açılan mağaranın

iki serserisi, 

iki bekçisi, 

40 haramilerin son ikisidir...

Geceleri içine düştüğüm karanlıklar

senin açtığın, (sana açılan)

aydınlıkların habercisidir.

Sensiz

tarih yazılı masallardan ibarettir.

Sensizliğin en büyük dostu

geceleri bir masal prensesini uçan bir halı prensine taşıyan

saliselerdir.

Sen gittiğinde kırmızı bir mühür vurulur hayatı(mı)  n üzerine.

Sen gelene kadar

''tadilat nedeni ile kapalı''yız)  dır'' kalpler.

Ruh dünyalarında yıllık sayımlar yapılır.

Defterler açık verir ve tüm

matematik işlemleri seni gösterir.

Yediğim her şey seninle çarpılır, 

duyduğum her heyecan sana bölünür.

Seni düşünmediğim her an benden

çıkartılır, beni düşündüğüm her an seninle toplanır.

Ve sonuç hep

''sen'' çıkar.

Bir tek ''sen''in sağlaması beni ''ben'' yapar.

Yolumu eşkiyalar keser sen gittiğinde.

Hayat daha zor geçer.

Beyaz yalanlar, maskeli süvariler, boş

bedenler sen gelene kadar kapımın dibinde nöbet bekler.

İlişkiler

ilişilmez olur.

Dostluklar ağır bir yüktür.

Sana anlatılacak anlamlı

anlamsız çok şey vardır.

Sözcüklerin içi çok daha çabuk boşalır.

Ve kafama düşünülmemesi gereken, 

bir çöp torbası dolu fuzuli düşünce

takılır.

Suskunluklar daha bir anlam kazanır.

Sen görmezsin, sen bilmezsin, 

eminim hissetmezsin (de) ...

Sensizken beni taşımak her zamankinden daha zorlaşır.

O anlarda beni

yalnızca senin varlığın taşır.

Sen gittiğinde, 

Gündüzleri sokak lambaları sanki hiç sönmüyor

ve geceler zifiri

karanlıkta geçiyor

Nefes alınmıyor, yalnızca veriliyor.

Arabalar duruyor, 

yollar hareket ediyor.

Güneş dünyanın etrafında dönüyor, 

dünya ayın çekim alanına giriyor.

Kumlar denizleri kaplıyor, 

yunuslar toplu intiharlarla kendilerini kumsallara vuruyor.

Karada

yenilen vurgunlara derin düşüncelerde sıhhat bulunuyor.

Sonbaharı

yaz takip ediyor, 

yaz takip ediyor, 

yaz sonrası ilkbahar geliyor.

Her kar yağdığında güneş açıyor

Ve

güneşli havalarda beni en çok

sensizlik donduruyor.

Bir yara açılır içimde, 

senin her gidişinde.

Çaresiz bir hayat mahkumu...

Umutsuz bir yalan taciri belirir o

derin yaranın içinde.

Ruh avcısı olurum, beden simsarı...

Sensizlik

alıp sensizlik satarım.

Başkalarında hep beni ararım.

Kaçayım derken

yine sana yakalanırım.

Kan kaybı değil, sensizlik çektiğim.

En

çaresiz anlarımda

yani sen kaybından ruhumu teslim etmek üzereyken

senden gelen bir kart beni yine bana, 

telefondaki sesin beni yine

sana taşır.

Bir hayal mahkumunu

siyah beyaz flu bir fotoğraf karesi

tekrar hayatla tanıştırır.

Sen gittiğinde, ben de giderim.

Gittiğin uzaklıkların

tam tersinde sana ulaşmaya çalışır, 

kendime

yenilirim.

Utanmak gelmez

aklıma her gördüğüm cansız ruha seni

sorarım.

Tanımazlar seni.

Oysa beni görenler senin de varlığını

anlar.

Kimlik kartı olarak seni taşırım.

Umulmadık çevirmelerde

kolluk kuvvetlerine seni takdim eder, 

iş başvurularında imzayı hep

''sen'' diye atarım.

Doktorlar sihhatimi öğrenmek için seni dinlerler.

Senin adına öksürmemi, 

ağzımı açtırdıklarında derinliklerimde

seni

görmek isterler.

tüm tahlil sonuçları sen çıkar.

Danışmalara seni rehin bırakırım. ‚

çıkışta seni ceketimin iç cebine

koyarım.

Kalbimin üzerinde sen durursun.

Biliyor musun benim

varlığımı bana, 

en iyi sen kanıtlıyorsun.

Sen gittiğinde, söz de bitiyor.

...ve sensizlik, senin kadar ağır geliyor...

şiirleştiren: ali rıza erdem', 'Sen gittiğinde,  ...sonbahar tüm hüznü ile çöker omuzlarımın üstüne. Yapraklar sararır birden bire,  dökülürlü omuzlarımdan kırık kalbimin d...', ARRAY['Türk Edebiyatı','Şiir','Cüneyt Özdemir']::text[], 8.5, '{"poet":"Cüneyt Özdemir","poet_slug":"cuneyt-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":204,"source_url":"https://www.antoloji.com/gitme-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence Seni Sevmek Özlem Demek', 'bence-seni-sevmek-ozlem-demek-salih-ozalasan-znkn5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret olmasa yüreklerde

Buram buram dumansız tüten

Özlemler dolmasa gönüllere

Zaman zaman hüzünlü şarkılar söyleten

Gözler hep yollarda kalmasa

Arada dağlar olmasa özleten

Sevmenin ozaman ne önemi vardıki

Ben sana bağlanmışım seni hiç görmeden

Yüreğimde bir ateş yakmışım

Dumanı yok ama yanıyor sönmeden

Sevda bu değilmidir? 

Sevmek, hep sevmek sevildiğini bilmeden

İstendiğinde yüreğin söküp vermek

Karşılığında hiçbirşey beklemeden

Adına şarkılar yazmak, maniler düzmek

Saçının gözünün rengini bilmeden

Özlemek teninin kokusunu

Esen rüzgarda onu ayırdedebilmek

Bence seni sevmek, özlem demek

Özlemekse benim için, 

Seninle olmak demek

Y.Tar.10+11-10-2002 Saat 8.00', 'Hasret olmasa yüreklerde Buram buram dumansız tüten Özlemler dolmasa gönüllere Zaman zaman hüzünlü şarkılar söyleten Gözler hep yollarda kal...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bence-seni-sevmek-ozlem-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Gün', 'otuz-gun-onur-uysal-rilz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün, 

Bir ayı dolmuş sensizliğimin.

Yani koca bir otuz gün geçmiş, 

Dokunuşların, gülüşün, fısıldayışın olmadan, 

Sarmadan seni, ve sarılamadan.

Bugün, 

Tam bir ayı dolmuş yanlızlığımın.

Yani geçmiş yedi yüz yirmi saat, 

Güne doğan sohbetler yapmadan, 

Sabahleyin gözlerimi sana açıp, 

Bir gece yarısı, koynunda yine sana kapamadan.

Bugün, 

Bir ayı dolmuş hasretimin.

Yani geçmiş kırk üç bin iki yüz dakika, 

Sırt üstü uzanıp yatağa, dikip gözlerimi tavana

Hayalini kura kura.

Bugün, 

Yani henüz birinci ayındayken daha 

sevdamıza hasreti de katmanın, 

Aşık olduğun kent solgun, artık her gün ağlıyor, 

Aşık olduğun adam solgun, gözleri yollarda, 

					seni bekliyor.', 'Bugün,  Bir ayı dolmuş sensizliğimin. Yani koca bir otuz gün geçmiş,  Dokunuşların, gülüşün, fısıldayışın olmadan,  Sarmadan seni, ve sarıla...', ARRAY['Türk Edebiyatı','Şiir','Onur Uysal']::text[], 8.5, '{"poet":"Onur Uysal","poet_slug":"onur-uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/otuz-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin Bu Dargınlık', 'bitsin-bu-darginlik-salih-ozalasan-kx6mv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine sensizim

Yine kan ağlıyor yüreğim

Yine öfkem dağları deliyor

Yine derbederim

Yine sizli bizliyiz

Yine sözlerimizde sitemimiz

Yine kırıyoruz birbirimizi

Yine yıpratıyoruz sevgimizi

Oysa ikimizde biliyoruz

Biz bir elmanın iki yarısı

Ağlarken ağlayan

Gülerken gülen

İkimizinde aynı yürek yarası

Biz iki deli aşık

İyi olmaz yüreklerimizin yarası

İkimizinde gözü kara

Yüreğinde saklı sevdası

Bir dargın bir barışık

Bir gece karanlık

Bir gece ışık

Birgün elele birgün ayrılık

Oysa biliyoruz

Boşa bu dargınlık

Kavuşması olmayan sevdanın

Olmazki sonu ayrılık

Hadi gel vazgeçelim

Bitsin artık bu dargınlık

Y.Tar.11-10-2002 Saat 9.00', 'Yine sensizim Yine kan ağlıyor yüreğim Yine öfkem dağları deliyor Yine derbederim Yine sizli bizliyiz Yine sözlerimizde sitemimiz Yine kırıy...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bitsin-bu-darginlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmak Yok Kalemi', 'kirmak-yok-kalemi-salih-ozalasan-dd6gc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yok artık kırıp atmak

Kızdığında hemen kalemi

Yazacağım bundan sonra

Kızsamda aklıma geleni

Anladım geçte olsa

Birileri kırmamı istiyor kalemi

Aşkımı yazdım, hüznümü yazdım

Sıra geldi yazmaya kinimi

Sevdamı okurken gülen yüzler

Bakalım okuyabilecekmi nefretimi

Hasret öylesine körüklediki

Sanırım ölçmek zor şiddetini

Merak ettinya aslında bende ediyorum

Bakalım ilk kim alacak nasibini

Sevgi seli kaplamıştı yüreğimi

Sel sürükledi getirdi nefreti

Bence nefret aşkın kardeşi

Dilerim olmaz kardeş katili

Y.Tar.11-10-2002', 'Yok artık kırıp atmak Kızdığında hemen kalemi Yazacağım bundan sonra Kızsamda aklıma geleni Anladım geçte olsa Birileri kırmamı istiyor kale...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirmak-yok-kalemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-gunseli-basar-3x43m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kalabalık bir yoldu.. uzunca sürdük katarları denizin ortasına.. ay kızıl  kordu elimiz..sürgün gibi bir çığlık yankılanıyordu....

korku elim denizi ürküterek sese doğruldu.....

Ey tanrım! ...

bu gökyüzünü koru..

Ey tanrım! ..

bu ekmeği koru..

Ey tanrım! ..

nolur bu düşü, bu EVİ koru! ! ...

hadi çocuklar...günlük ekmek ve dualarla gelen korku sindirmesin sizi..hadi yüregim.....

AMİN...', 'kalabalık bir yoldu.. uzunca sürdük katarları denizin ortasına.. ay kızıl  kordu elimiz..sürgün gibi bir çığlık yankılanıyordu.... korku eli...', ARRAY['Türk Edebiyatı','Şiir','Gunseli Başar']::text[], 8.5, '{"poet":"Gunseli Başar","poet_slug":"gunseli-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dua-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Son Defa Ağlıyorum', 'bu-gece-son-defa-agliyorum-yakup-akkanat-shv9g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu Gece Son defa agLiyorum Senin icin! 

UZUN zamandir iLk kez Ama Bu farkLi! 

Seni siLmek icin kaLbimden, 

Son kirintiLari Son senLeri atmak icin kaLbimden! .. 

YaLniz kaLmak istiyorum kaLbimLe! 

Ona Tekrar BaKerKen Seni Hissetmek! 

Seni görüp sana dokunmak yani! 

Aci cekmek istemiyorum ARTIK! 

Bir gün KarSima Yine cikacakSin biLiyorum.. 

Birgün tekrar üzmek isteyecekSin beni..

Ama Bu sefer farkLi oLacak! .. 

cünki icimde sen oLmayacakSin! 

Bu Gece Son defa agLiyorum Senin icin! 

GözLerimden Akan Sey Yas deiL asLinda SENSIN! 

Tek tek döküLüyorSun gözLerimden! 

Parca Parca CikiyorSun Bu gece! 

kaLbimi tekrar istiyorum Cünki: 

Ona yeni Bir Sahip buLdum! ! 

beLki üzüLecekSin biLmiyorum! 

Cünki Sen herseye Ragmen benciLSin! 

Ve DüsünüyorSun beni gizLice! 

KarSima cikmaktan nasil korkuyorSun! 

Benim SeSimi Duymaktan.. 

benimLe konusurken neden titriyor SeSin ¿

Neden uzak duruyorsun benden ¿ 

Sen biLmeSende ben biLiyorum güzeLim! cünki Sevinmemden KorkuyorSun Kendince..! 

ama! yaniLiyorSun bunu biL! 

Artik Sevinc yok Senin ADINA! 

cünki senin adinda yok kaLbimde..! 

..Senin icin Son Defa agLiyorum Bu Gece..! 

iLk defa icimde acan bir günesle.. 

UZUN birkisti zorLandim ama; gördügüm bir bahar biLiyordum..! 

dokunuyordum ona isiniyordum artik! .... 

bunun zamani geLmisti biLiyorum! 

Bu defa yaniLmiyorum! 

yaniLmiyorum Cünki; 

görüyorum UZAK tepeLerdeki cicekleri 

inceden kokuLari caLiniyor burnuma

kokLuyorum Ve bunu HerSeyden cok Seviyorum! ..

Senin icin Son defa agliyorum Bu gece! 

icimde kaLbine gözLerini acan bir bebekLe..

artik öLmüs senin küLlerini atmanin zamani geLdi! 

Bak iste Son damlada Düstü gözümden! ...

Artik Seni Sevmiyorum! ! 

M.Ö.

(Şairin Adı bizde saklı..)', 'Bu Gece Son defa agLiyorum Senin icin!  UZUN zamandir iLk kez Ama Bu farkLi!  Seni siLmek icin kaLbimden,  Son kirintiLari Son senLeri atmak...', ARRAY['Türk Edebiyatı','Şiir','Yakup Akkanat']::text[], 8.5, '{"poet":"Yakup Akkanat","poet_slug":"yakup-akkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bu-gece-son-defa-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Hiç Sevmedim', 'ben-seni-hic-sevmedim-yakup-akkanat-e91k2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ben seni hiç sevmedim

gece karası sonsuz gözlerini

ve bana bakarken gece gözlerinde parlayan yıldızları sevmedim

güneş kadar parlak tenini sevmedim

ve bana dokunurken alev alev yakan sıcaklığını

ben gökkuşağı kadar renkli sözlerini sevmedim

ve benimle konuşurken akan bin bir rengi

ben senin kar kadar temiz ve yumuşak yüreğini hiç sevmedim

ve beni seven saf ve berrak kardanadamı

yağmur kadar bereketli ve hasret dolu yüreğini sevmedim

yağmur kadar bereketli ve hasret dolu ruhunu   sevmedim

ve bana soluk aldıran yağmur kokunu

ben seni hiç sevmedim

ben senden öteyi sevdim

ben ulaşılmazı

ben kavuşulmazı

ben hasreti sevdim

ve

ben sadece seni yaratanı sevdim

ve seni bana yazanı...

ve onun hatrına tövbe ederim ki

yalan söyledim

ben seni benden çok sevdim

sonsuza kadar', 'ben seni hiç sevmedim gece karası sonsuz gözlerini ve bana bakarken gece gözlerinde parlayan yıldızları sevmedim güneş kadar parlak tenini s...', ARRAY['Türk Edebiyatı','Şiir','Yakup Akkanat']::text[], 8.5, '{"poet":"Yakup Akkanat","poet_slug":"yakup-akkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-seni-hic-sevmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar ve Böcekler', 'isiklar-ve-bocekler-yakup-akkanat-hriwk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani küçük bir ışık yakarsın ya yaz gecesinde

çevresine büyülenmişcesine gelirya böcekler

işte sende benim en karanlık gecemde yanan bir tutam ışıksın

işte bende sana büyülenmişcesine geldim

ve çevrende düşünmeden avare avare dönüp durmaktayım

sabah olmadıkça

heryer senin kadar parlak

senin kadar sıcak olmadıkça yanındayım

ama sanmaki güneş doğacak

çünkü ben bir küçük kelebeksem eğer

sadece birkaç saatim kaldıysa yaşayacak

doğacak güneşler bana doğmaz

gün bana ağarmaz

ben seni gördüm ışık

ve ömrüm sadece seni görmeye yetecek bilirim

hiç sönmeki bu saadetim sonuna kadar sürsün ömrümün

hep ben senin çevrende avare pervane

hep, sen benim yüreğimde büyülü bir ışık...

şair: Efsun', 'hani küçük bir ışık yakarsın ya yaz gecesinde çevresine büyülenmişcesine gelirya böcekler işte sende benim en karanlık gecemde yanan bir tut...', ARRAY['Türk Edebiyatı','Şiir','Yakup Akkanat']::text[], 8.5, '{"poet":"Yakup Akkanat","poet_slug":"yakup-akkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isiklar-ve-bocekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU', 'su-ozgur-hatem-rb2qr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.

Sen benim, 

Öfkesiyle nehir olan yarimsin! 

(Dışarıda, vurgun, insan kuşları...)

Bir çember var, çevresiyle döndüğüm

Bir de sen, suyuna eklendiğim.

2.

(Acıyan parmaklarımdan,)

Küçük mısralar sere vuruyor kendini.

Gece, bir yıldız kalabalığı

Şimdi, türkü, suyumun sesi

Serinliğiyle dinlendiğim.

3.

İsyan, kendi çığlığını üretiyor sazında

Yüreğimin tellerine kuşlar konuyor

(Göç zamanı)

Bir sonbahar kokusu

Başımı yasladığım dağda, 

Dingin akıyor Su.

(11/10/2002 Mersin)', '1. Sen benim,  Öfkesiyle nehir olan yarimsin!  (Dışarıda, vurgun, insan kuşları...) Bir çember var, çevresiyle döndüğüm Bir de sen, suyuna e...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/su-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sunu', 'sunu-erol-nacar-96ddi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı benli

Bir damla su

Kopar da

Şimşeklerin çatalından

Biner de sırtına

O

Azgın dalgaların; 

Eleyler...

Geniş karınlı suların

Çılgın dansların

Arasında yaşarım; 

'' El '' olur

Tutar

Elimi sunarım

Bir ucu

Bir parçası bu

Deli-divane tarafı

İnsan olma yanı

Alklın 

Aklandığı anı...

Kalkar

Demir kıran

Çocuk gözlülerin ordusu

Bir

Garip eloğlu

Kucaklayıp okyanusu, 

Açar, 

Yüreğimi sunarım.

Köpürür öfkesi

Onbin yılın

Zincir kıran uykusu.

Kaldıra 

İndire okyanusu.

Bir 

Beni

Damladan taşarım

Bir

beni uzar

Kendimi sunarım

       (güney dergisi)', 'Aşkı benli Bir damla su Kopar da Şimşeklerin çatalından Biner de sırtına O Azgın dalgaların;  Eleyler... Geniş karınlı suların Çılgın dansla...', ARRAY['Türk Edebiyatı','Şiir','Erol Nacar']::text[], 8.5, '{"poet":"Erol Nacar","poet_slug":"erol-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sunu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Yaşamaya Dair', 'sevdaya-yasamaya-dair-vedat-koparan-rez8c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdaya Yaşamaya Dair

Hangi müzik, 

Hangi notasın sen

Hangi dağ gözlerin

Hangi deniz yüreğin gibi 

Nasılda çeker bilirmisin beni 

Her şey senle başlar

Bak nasılda özletir 

Hazan vurgunluğu 

Yoksun zamanlar şimdi seni

    Oysa gider ayak nice çetin

    Ve çetince bitirilecek  işlerimiz var

    Sevdaya yaşamaya dair..

    Vedat.K 11-10-2002', 'Sevdaya Yaşamaya Dair Hangi müzik,  Hangi notasın sen Hangi dağ gözlerin Hangi deniz yüreğin gibi  Nasılda çeker bilirmisin beni  Her şey se...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdaya-yasamaya-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sedef-diril-s747h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gözlerini suda gördüm, 

Ellerimi uzattım, 

Avuçlarımı suyla doldurup, 

Kana kana içmek için.

Dün ellerini kırda gördüm, 

Koşup yakalamak sarmak istedim.

Sıkıca tutup hep bende kalsın istedim.

Dün saclarını çölde gördüm.

Yanmış kavrulmuş çatlamış dudaklarını orten.

Dün seni hayalimde gördüm.

Sevecen tatlı ve oyle suskun.

S.D.', 'Dün gözlerini suda gördüm,  Ellerimi uzattım,  Avuçlarımı suyla doldurup,  Kana kana içmek için. Dün ellerini kırda gördüm,  Koşup yakalamak...', ARRAY['Türk Edebiyatı','Şiir','Sedef Diril']::text[], 8.5, '{"poet":"Sedef Diril","poet_slug":"sedef-diril","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önsöz', 'onsoz-ozdemir-i-nce-ip0hh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazan bir sözcük arar ozan, bekler

bir anahtar sözcük, başlamak için şiire, 

bir görüntü bazan, bir ses, bir koku, 

bazan da bir şey, bir devinim izi.

Hepsi var, hem de istemediğin kadar; 

kireç yanığı görüntüler: Lemnos, Ayios Istratis, 

üç tanık sözcük: Makronissos, Yaros ve Leros; 

sürgün ve işkence öyküleri, burun sızlatan.

Ağaçlar: Zeytin, çınar, incir, okaliptüs

Duvarlar: Ak badanalı bahçe duvarı

Sesler. Saban, çıngırak, keçi melemesi

Başka şeyler: Kiraç taşları, mavi ve yeşil.

Bir de fotoğraf var, eski biraz: 

Gülen bir kadın, saçları kısa, tatlı esmer, 

bir çocuk, kıvırcık saçlı, üç-dört yaşlarında, 

ve bir erkek, kısa pantolon giymiş, 

kolları çapraz, gövdesi çıplak

ve belinde bir asker palaskası.

Bir asker palaskası: Tıpkı o

parmağa dolanan beyaz iplikler gibi, 

hatırlamak için, unutmamak için

bir tarih yorumcusu gerektiği zaman.

Gülüyor adam, mutlu olduğu da söylenebilir, 

''daha az gökyüzü istemem'' der gibi sanki.

Ancak bir emekçi ozan böyle durabilir ayakta, 

bunca deney ve bunca sınavdan sonra.', 'Bazan bir sözcük arar ozan, bekler bir anahtar sözcük, başlamak için şiire,  bir görüntü bazan, bir ses, bir koku,  bazan da bir şey, bir de...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/onsoz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gürlevik', 'gurlevik-ozdemir-i-nce-kxe58', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir şeye benzetirim kendimi durmadan

tüyleri uzamış solgun kendimi

bütün kapıları açarım belki de korkumdan

o incecik kelimeler içindir bu yalnızca

kaybolur kurtarmasam uzay karanlığımda

resimler yaparım kırmızıdır sokaksızlıktan

çünkü ellerimi yaparım yüzümü yaparım

teraziler kurulur işler tatlı vücudumda

renklerini yaparım mavisi değişken sesli kara

kum gölgeli yeni balıklar geçer altından

kralların ölümünü bir onlardan anlarım

bir onları anlarım kadınlardan

bir şeye benzetirim kendimi durmadan

kervanlar geçer uzanırım ayaklarımdan

bir yerde dururum güneyde dış kapılarda

bilmem her keresinde böyle olur anlamam

bir o yüzden anarım öperim fantomayı

yeryüzünde işte kadınlar ve erkekler için

ve bir derinlik için yemyeşildir saçları', 'bir şeye benzetirim kendimi durmadan tüyleri uzamış solgun kendimi bütün kapıları açarım belki de korkumdan o incecik kelimeler içindir bu y...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gurlevik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlem', 'gozlem-ozdemir-i-nce-i3xt9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan gövdesine dokunmak: 

sonsuzun gidişine

ve gözkapaklarına belleğin

sözcüklerin yerine bir boşluk koymak

hiçliği görmek: mumları söndürmek

karanlıkta bakışmak karanlıkta

Sırat Köprüsünden geçerken

Köşeyi dön, uçurumsuz atlayış

gövdenin içindeki gövde

kırılan sırça... şamdanın sesi

Susamam onu, ne sözcüklerle

susamam onu, ne de sessizlikle, 

konuşamam onu konuşmamla

Bir ''O'' var sende ve bende

baştan çıkartıp onu bir şey yapacağım

çölün duvarsız gecesinde

Susamam onu, susturamam onu

ne sözcüklerle sözcüklerin içinde, 

ne de sessizlikle sessizlikte

Meczup sayfaların arasında

pervane olup dönen isyankar dervişler

önce yaşamak ve sonra yaşamak için

sesim kağıt gibi yayılırken mürekkebe.', 'İnsan gövdesine dokunmak:  sonsuzun gidişine ve gözkapaklarına belleğin sözcüklerin yerine bir boşluk koymak hiçliği görmek: mumları söndürm...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozlem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçıvan', 'bahcivan-ozdemir-i-nce-rtfiz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgara bırakma şikayet dilekçeni

yakarmalarla gelmez dünya

sen git onun ayağına

Rüzgara bırakma şikayet dilekçeni

veba sesiyle konuşuyor kahinler

yasaların dünyayı kirlettiği söyleniyor

yas tutuyor üzümde şarap

ve su dileniyor kavmin çocukları

Rüzgara bırakma şikayet dilekçeni

zaman daralıyor, aylardan dikim ayı

derinden sür tarlanın toprağını

yeni mahyalar dik

mahşerin karıklarına

Rüzgara bırakma şikayet dilekçeni

Sen dönek kent, yırtık kuma, 

diye yaz kağıdın beyaz alınlığına, 

sen hasret geçidinin softa bekçisi

çöl katlanıyor ve gelmiyor haberci.

Toprağa düşen neyin anlamıdır?', 'Rüzgara bırakma şikayet dilekçeni yakarmalarla gelmez dünya sen git onun ayağına Rüzgara bırakma şikayet dilekçeni veba sesiyle konuşuyor ka...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahcivan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-kemal-ozer-dl12g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'annem mi bir kadın

geciken bir kadın gece yatısına

ölüm kendini göstereli babamın saçlarından

günübirlik bir kadın

üsküdar''la istanbul arasında

babamdı sakalıydı babamın

bir akşam göle batırdı

çıkmamak üzere bir daha

hepsi de ekmek kokardı

sayısı unutulan parmaklarının

akşam bir attır bütün ülkelerde

serin esmer bir attır

terkisine çocukların bindiği', 'annem mi bir kadın geciken bir kadın gece yatısına ölüm kendini göstereli babamın saçlarından günübirlik bir kadın üsküdar''la istanbul arası...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agit-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Konuşmak İçin', 'bir-gun-konusmak-i-cin-kemal-ozer-ha3vx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalabalığı gördüm; fışkırmış ara yollardan, 

doldurmuş bir alanı göz alabildiğine.

Bir tek yüze çevirmiş bakışlarını, 

kulağını vermiş bir tek sese.

Kalabalığı gördüm; bir tek sözle

haykırmaya hazır bir ağızdan.

Gergin yaylar gibi atılmaya hazır, 

duramıyor durduğu yerde.

Kalabalığı gördüm; elindeki bayraklar

yatıştırıyor acısını ve öfkesini.

Yan yana getirmiyor coşkunluk

o kadar kolu bir yumruk gibi.

Kalabalığı gördüm; habersiz

nereye varacağından sesinin.

Dinlemek için değil de

bir araya geldiği vakit konuşmak için.', 'Kalabalığı gördüm; fışkırmış ara yollardan,  doldurmuş bir alanı göz alabildiğine. Bir tek yüze çevirmiş bakışlarını,  kulağını vermiş bir t...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gun-konusmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hüzün Niye', 'bu-huzun-niye-salih-ozalasan-r2pfb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni hüzünlü görmek ne kadar acı

Gülen gözlere ne oldu bu nekadar acı

Sendin hayatımın mutluluk ilacı

Gülen gözlerinde bana ilham vardı

Hüznü yazmayacaksın demiştin

Unutmadın sanırım değilmi

Mutluluk yoksa gözlerinde

Sevdayı yazamam anladın değilmi

Sorsam söylemessin nedir nedeni

Ah bir bilsem sana hüznü veren sebebi

Sana gülmek yakışır

O güzel gözlere yazık değilmi

Haydi gül neşelen eskisi gibi

Sen benim için olmuştun masal perisi

Sende herşey mutluluktu

Seninle yokolup giderdi hüznün en beteri

Bilirim sen hemen öyle pes demessin

Öyle basit şeylere boyun eğmessin

İçin kan ağlasada hep gülümsersin

Sen benim için neş''e sen bende herşeysin

Y.tarihi 12-10-2002 Saat 01.35', 'Seni hüzünlü görmek ne kadar acı Gülen gözlere ne oldu bu nekadar acı Sendin hayatımın mutluluk ilacı Gülen gözlerinde bana ilham vardı Hüzn...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-huzun-niye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Şarkı Söylemez', 'oluler-sarki-soylemez-nurettin-durman-kobof', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şarkılardan bir demet olmuyor ışık zaten      

Ölüler ki korkuyor şüpheli  hallerinden     

Toprağın kokusuyla buluşmak için erken 

Çabucak geçiyorlar karıncalar evinden.

Uzanıp da hasretle tutmadıkları güneş      

Saklanıp geçince gölgelerin üstünden

Ne olacaksa olsun değer mi hayata hiç 

Rüyasız kalmak için şu erkete yüzünden.

Birer birer ölecek en sonunda insanlar

Zaten ölümden başka kalmıyor ki aramak

Bütün mecburi günler geçerken birdenbire

Güneş çıksa da artık neye yarar yaşamak.

Sonunda sokaklardan rüzgar çağında bir halk

Çıkacak olsa şöyle bir yaz günü göğsümden

Söylemese de kimse ölüler gülmek için

Acele etmezler hiç kaçmak olmaz ölümden.

20 Mayıs 2001', 'Şarkılardan bir demet olmuyor ışık zaten       Ölüler ki korkuyor şüpheli  hallerinden      Toprağın kokusuyla buluşmak için erken  Çabucak ...', ARRAY['Türk Edebiyatı','Şiir','Nurettin Durman']::text[], 8.5, '{"poet":"Nurettin Durman","poet_slug":"nurettin-durman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oluler-sarki-soylemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarıma Haciz Geldi', 'ruyalarima-haciz-geldi-burak-olurogullari-2ylf2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskileri gömdüm! 

Yeni hayallerimi de sen hissetmeden boynuna asıyorum

Kırılmış düşlerimi, solmuş sevgi yapraklarımı! da

Yastığımın altına gizlice saklıyorum.

Bir gün halimi görürde gülersin diye

Tekrar yalanlar söyler seviyorum dersin diye

Senden öğrendiğim  gibi sessizce kaçıyorum

Oysa ki ben

Acı uykuların kasvetinde

Sabaha zor hatırladığım düşlerin ardındaki külleri

Ellerim yana yana, günün ilk ışıklarıyla topluyorum

Anlıyorsundur işte bu kadar güç hasretin

Yakıyor, terletiyor

Tozlanmış anılarıma her nefeste

Bir keder daha ekliyor

Bıraktım tüm istediklerini gidiyorum

Senden çaldığım bir kaç şeyi de yanımda götürüyorum.

Sol cebimde hasretini, dilimde özlemini

Yorgun kalbimdeki eşsiz sızıyı

Alıp yanıma yavaş yavaş uzaklaşıyorum

Affet beni

Bu gece de bir kez daha ölüyorum

Ağustos 2001

06FiLiNtA', 'Eskileri gömdüm!  Yeni hayallerimi de sen hissetmeden boynuna asıyorum Kırılmış düşlerimi, solmuş sevgi yapraklarımı! da Yastığımın altına g...', ARRAY['Türk Edebiyatı','Şiir','Burak Oluroğulları']::text[], 8.5, '{"poet":"Burak Oluroğulları","poet_slug":"burak-olurogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruyalarima-haciz-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helal Olsun Sana', 'helal-olsun-sana-burak-olurogullari-l3xw0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl aklını boyadılar beş para etmez iki cümleyle.

İki güzel söze iki güzel düşünceye tav oldun demek içten içe

Sen bu muydun? Bu muydu acının borcu

Bu denli mi aklının çalınması kolaydı

Ne ettim de ben sana bu denli, 

Gömdüğün dertlerimi çıkarıp koydun önüme

Ellerini tuttuğum sen

Kimseye vermediğim değerin anlamı sen

Böyle mi yüz üstü bırakıp bitecektin

Bu kadar mı acımasız insanın etini koparırcasına gidecektin

Benim için ölür O dediklerimi

Bu  kadar mı çabuk güldürecektin üstümüze.

Vicdansız kalbini, hemende nasıl katık ettin kalbimin içine.

Ben seni herkesten sakınırken

Nasılda gittin uydun ellerinin dileğine! 

Bu acıyı yaşatmasaydın keşke

İçinde yaşatıp ta neydi bu sakladığın

Demek sevmiştin, demek hala vardın her şeye

Peki neydi bu kaçış alelacele

Neden böyle ulu ortalıkta bıraktın beni ellere

Sevmedim mi? Kalbini alıp içime hapsetmedim mi? 

Mübarek bildiğim aşkın dara koydu işte

Acıttı sızlattı gözyaşını unutan gözlerimi

Ama sende mutlu olmuşsundur artık şimdi

Sağol yaşattığın bu işkenceye! 

29 Eylül 2002

06FiLiNtA', 'Nasıl aklını boyadılar beş para etmez iki cümleyle. İki güzel söze iki güzel düşünceye tav oldun demek içten içe Sen bu muydun? Bu muydu acı...', ARRAY['Türk Edebiyatı','Şiir','Burak Oluroğulları']::text[], 8.5, '{"poet":"Burak Oluroğulları","poet_slug":"burak-olurogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/helal-olsun-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun Bitanem', 'biliyormusun-bitanem-emine-sumra-uxdpy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eritir sessizliğin beni.

Kaç sefer telefona uzandım bilmem.

Yangınlar yanarda yüreğimde, 

Dökemediğim yaşlarla söndürürüm için, için.

Bir arasan, bi arasammı acaba? 

Biliyorum sende yanarsın ümitsizce

Ben istedim senziliği ama ama

Biliyormusun bitanem seni çok seviyorum', 'Eritir sessizliğin beni. Kaç sefer telefona uzandım bilmem. Yangınlar yanarda yüreğimde,  Dökemediğim yaşlarla söndürürüm için, için. Bir ar...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biliyormusun-bitanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen Ne Olurdu', 'gelsen-ne-olurdu-emine-sumra-amyts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni bekliyorum hasretle

Kekik kokuları yaydığım dağlarda

Terimi damlattım her adımda

kokumdan izimi bul diye

Bu dağlar varya bu dağlar

Vede üstündeki bitkiler

Hepsi tek tek şahittir sensizliğime.

Her yaprağına adını yazdım

Patikalarını umutlarıma çıkardım

Yeşilin her tonuna bezedim seni.

Bakışlarımı meşelere yaydım

Yaydımki sararıp dökülsün avuçlarıma.

Bari onlar benim olsun 

Seni öyle özlüyorumki

Yanımdan geçen her rüzgara, 

Her buluta seni soruyorum

Ne yapayım bitanem seni çok seviyorum.', 'Seni bekliyorum hasretle Kekik kokuları yaydığım dağlarda Terimi damlattım her adımda kokumdan izimi bul diye Bu dağlar varya bu dağlar Vede...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelsen-ne-olurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay''a itiraf', 'ay-a-itiraf-emine-sumra-o2urj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay''a seni sevdiğimi itiraf ediyordum

Suç üstü yaptı yıldızlar.

Onlarada söylemek zorunda kaldım.

Şimdi hepsi biliyorlar

Düşünsene bitanem

Ya onlarda gökyüzüne söylerse

Vallahi yarın güneşte duyar

Güneş çenesini tutamaz bilirim

Yer yüzü çatlar öğrenmezse

Öğrenipte anlatmazsa.

Ağaçlara, çiçeklere, otlara

Düşünsene bitanem 

Aşkımızı öğrenecek ne çok varlık var.', 'Ay''a seni sevdiğimi itiraf ediyordum Suç üstü yaptı yıldızlar. Onlarada söylemek zorunda kaldım. Şimdi hepsi biliyorlar Düşünsene bitanem Ya...', ARRAY['Türk Edebiyatı','Şiir','Emine Sumra']::text[], 8.5, '{"poet":"Emine Sumra","poet_slug":"emine-sumra","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-a-itiraf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz aşk...', 'sessiz-ask-hasan-vehbi-yarar-xxbh1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir aşkın yarasını okuyorken defterde

İçtiğim sigaradan dağıldı perde perde

Masmavi gökyüzünden siyah bulutlar geçmiş

Aşkın nehir kabından son damlasını içmiş

Hafif bir ürpermeyle başladı aşkın bağı

Yıllar var ki sevgiden bir habermişti bağrı

Bir tek söz istiyormuş bu sevgili periden

Bir tek sır veriyormuş kalbindeki sevgiden

23/04/2002', 'Bir aşkın yarasını okuyorken defterde İçtiğim sigaradan dağıldı perde perde Masmavi gökyüzünden siyah bulutlar geçmiş Aşkın nehir kabından s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Vehbi Yarar']::text[], 8.5, '{"poet":"Hasan Vehbi Yarar","poet_slug":"hasan-vehbi-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmez', 'gulmez-hasan-vehbi-yarar-qbo9m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adet etmiş yürürken o hiç gülmez, 

Geçerken en sevdiğini yine görmez, 

Neden acaba o gülmeyi mi bilmez, 

Hayır o evde şen yolda hiç gülmez.

                *******

Zaten onun ciddiyetine hayranım, 

Gördüğüm her ciddiyi o sanırım, 

Onu uzaktan görsem yine tanırm, 

Gülmez ki bir defa gülse şaşakalırım.

01/10/2002', 'Adet etmiş yürürken o hiç gülmez,  Geçerken en sevdiğini yine görmez,  Neden acaba o gülmeyi mi bilmez,  Hayır o evde şen yolda hiç gülmez. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Vehbi Yarar']::text[], 8.5, '{"poet":"Hasan Vehbi Yarar","poet_slug":"hasan-vehbi-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gulmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaplar Denizin Yüzünü', 'kaplar-denizin-yuzunu-behcet-necatigil-928xa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaplar denizin yüzünü

Unutulmuş uykularda

Şimdi değişmiş kayıp

Şimdi bir başka uzak.

Kopmuşsanız yıllar yılı sürmüş bir yaşamadan

Kapanmışsa o sayfa', 'Kaplar denizin yüzünü Unutulmuş uykularda Şimdi değişmiş kayıp Şimdi bir başka uzak. Kopmuşsanız yıllar yılı sürmüş bir yaşamadan Kapanmışsa...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kaplar-denizin-yuzunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anahtar Prens', 'anahtar-prens-kucuk-i-skender-vqloe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cam kurtlar var gecenin suyunda

içilse şehir; yırtılmış taşların

iade edilmiş melekler örttüğü

eski, imdat, tahlilsiz hikaye! 

israf edilmiş tayfalarla gelecek

uzattığım, uzatırken içine

tıkandığım menekşe! belli

belirsiz bir yaz ayında

sözgelimi ekim, sözgelimi kiraz

kırılacak bir tamburla geçecek

önerdiğim, önerirken dibine

çöküverdiğim efsane biraz; sesi yeis

sesi sabahlara kadar dinlediğim radyo

sesi oradan oraya oratoryo

sesi koynuma giren sesi koynundan çıktığım

sesi el konulmuş şeytan

sesi el kadar masumiyet

sesi hür siyah üzerine çalakalem mavi tül

sesi tül mavi üzerine nakşedilmiş siyah gül

sesi beni hep döven abim

sesi beni kovalayan polis

sesi bıçaklanışım, bıçaklanır

bıçaklanmaz eriyişim; kabullenilişim; 

ah ben nerdeymişim, ben kimmişim de

talazlanmış, tozlanmışım! üstümü süpür rüzgar! 

şimdi şikayetim var! çalıntı kalplerle kirlenmişim! 

ağlat beni özgürlüğüm, ağlat! gözyaşlarımla

yıkanırım, belki öyle başlar kim bilir

gökyüzünden yeryüzüne doğru

ölü bir hava kabarcığı gibi yükselişim!', 'cam kurtlar var gecenin suyunda içilse şehir; yırtılmış taşların iade edilmiş melekler örttüğü eski, imdat, tahlilsiz hikaye!  israf edilmiş...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/anahtar-prens-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosuna Sığıntı Mavi', 'yosuna-siginti-mavi-rusen-hakki-eky4h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak işte şurda, 

akarsuyu kıran

taşın yanında, 

çakıllar arasında

	mavisi yosun tutmuş

	bir şey var.

Dallarla oynaşıp da

suyu öpen günışığı

kamaştırmasa gözlerimi

	ele verecek kendini

	yosuna sığıntı mavi

bağışla adını, 

de ki ''bir anıyım

belki umudun dalgınlığı

ya da doğanın sabrıyım

	sel idim duruldum

	yosunda kendim buldum.''', 'Bak işte şurda,  akarsuyu kıran taşın yanında,  çakıllar arasında 	mavisi yosun tutmuş 	bir şey var. Dallarla oynaşıp da suyu öpen günışığı ...', ARRAY['Türk Edebiyatı','Şiir','Ruşen Hakkı']::text[], 8.5, '{"poet":"Ruşen Hakkı","poet_slug":"rusen-hakki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yosuna-siginti-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Yanlışlar', 'kucuk-yanlislar-rusen-hakki-brprq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne yiyip ne içiyorum

hasta mıyım söker miyim

özlemini duyuyor muyum bazı şeylerin

	örneğin

	martıyı uçarken

	karıncayı didinirken

	arıyı ballarken güzellemenin

	kıymığı yok içerde

içerde

gene yürek yüreğeyiz dostlarla

hesap kitap

ve birtakım küçük yanlışlar

	ki üstünde durmaya değer

	ki inanıyoruz zamanın yargısına

Gün gölgesini düşürdü mü duvara

	demir kafesin, 

	adımız ünlendi mi

	çayımız demlendi mi

	bir gün daha

	bir gün daha yakınım

	sana ve çocuklarıma

''Ya işinden atarlarsa

yeni bir iş bulamazsan çıktığında...

ya çocuklar ağlarlarsa

-ki hiç dayanamam bilirsin

bilirsin seni ne çok severim-

ne yapar ne ederiz şu pahalılıkta''

diye yakınmaktasın son mektubunda

Tasalanmakta haklısın

haklısın çocuklar konusunda

v elbette bilirim bizleri ne çok sevdiğini

ne var ki

allah kerim değilse de çağımızda

gene de bir çaresi bulunur bütün bunların

ve bunca yıkımın

gün olur hesabı sorulur', 'Ne yiyip ne içiyorum hasta mıyım söker miyim özlemini duyuyor muyum bazı şeylerin 	örneğin 	martıyı uçarken 	karıncayı didinirken 	arıyı bal...', ARRAY['Türk Edebiyatı','Şiir','Ruşen Hakkı']::text[], 8.5, '{"poet":"Ruşen Hakkı","poet_slug":"rusen-hakki","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kucuk-yanlislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışburnu', 'kisburnu-rusen-hakki-z99s3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kurcalarsa yaprağın tarihçesi

üst üste yanılgılar ve imla hataları

doğrular bir güzün bittiğini

bir kozalak bir kışburnu gibi uzanır

sandıkları açar, yünlüleri deşer

empirmeler, ipekliler dürülür kaldırılır

odun kıran çakal sesi, kırmızı gül artıkları

anımsatsalarda da çözülmeyen suları

hep birden yanıltırlar kışburnu kozalağı

ben bunu bildim bunu söylerim

kötü bir davranıştır üşütmek anıları

kar bindirmeden aktarmalı hüzünlü çatıları', 'kurcalarsa yaprağın tarihçesi üst üste yanılgılar ve imla hataları doğrular bir güzün bittiğini bir kozalak bir kışburnu gibi uzanır sandıkl...', ARRAY['Türk Edebiyatı','Şiir','Ruşen Hakkı']::text[], 8.5, '{"poet":"Ruşen Hakkı","poet_slug":"rusen-hakki","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kisburnu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağbozumu', 'bagbozumu-rusen-hakki-glu11', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ekmeği akıt

suyu böl! 

Suyu bahçeye çevirir gibi

yüzünü bana çevir, 

kirpiklerini batır hüznüme

ve öğret bana deliliği, 

çünkü çok bunaldım

aklımı hep yanımda taşımaktan! 

Bilsem bensiz çıldıracak nikotin

inan, çeker giderdim

üstüne basa basa sözcüklerin.

Beni bağışla, 

adı bağbozumu olan

bir hüzünse bana yakışan!', 'Ekmeği akıt suyu böl!  Suyu bahçeye çevirir gibi yüzünü bana çevir,  kirpiklerini batır hüznüme ve öğret bana deliliği,  çünkü çok bunaldım ...', ARRAY['Türk Edebiyatı','Şiir','Ruşen Hakkı']::text[], 8.5, '{"poet":"Ruşen Hakkı","poet_slug":"rusen-hakki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bagbozumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl ve Ay', 'col-ve-ay-hilmi-yavuz-nan93', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ince suydum, ezildimdi, basıldı

üstüme, kaldı ayak izleri suda; 

bir menzilden ötekine... nasıldı

gitmek? ağrdı çöl, kuytulardı, pusuda...

baktılar, haramiler, çölde su''ydum; 

gittimdi, kumlardı, soydular beni; 

yedi askı, çırılçıplak, söylendi, duydum: 

ört ketenle Mısır''ı ve Yemen''i...

iki menzil arasında bir menzil; 

soldu çöl ve vaha, çürüdüydü, ah rezil

blue mo on! arada kaldım, beni böl, 

ikiye... ne diye ayrılındı, ya Ömer? 

sırma gövdem di çiğdem, şakk-ı kamer...

bu ne tutkun gecedir, hüzünle beni, beni öl! ..', 'bir ince suydum, ezildimdi, basıldı üstüme, kaldı ayak izleri suda;  bir menzilden ötekine... nasıldı gitmek? ağrdı çöl, kuytulardı, pusuda....', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/col-ve-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizem', 'gizem-hilmi-yavuz-17wy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hem aldanan hem aldatan

	olduğu zaman

	dilden

dilin güzüdür üşür

sözün yazına karşı

kuşlar kuşlarla örtüşür

bir yaprak bir yaprağa

	doğru uğuldar: 

ve der ki onu yaşasan da

	yaşatsan da bir

dağlar çoktan dağlara göçmüştür

o altın gözlü anka

hangi derin dağdadır şimdi? 

bir acı, telörgünün ardında

	bir acıyla görüşür: 

ve der ki dilden kopan

bal örgüsü söz

hem söyleyen hem söyleten

	olduğu zaman

bana ben o''yum dedirten

	nedir? 

ustam der ki sen, şair

hiç gül kopardın mıydı gülden?', 'hem aldanan hem aldatan 	olduğu zaman 	dilden dilin güzüdür üşür sözün yazına karşı kuşlar kuşlarla örtüşür bir yaprak bir yaprağa 	doğru uğ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gizem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilmi''nin Çocukluğu', 'hilmi-nin-cocuklugu-hilmi-yavuz-epmhi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hilmi diyor ki yeminler

Bana çeşmeleri hatırlatır

Tabut kalın ciltli bir kitaptır

Senin de çocukluğun bir ceviz tabut muydu

Usulca bırakılan denize? 

Hilmi diyor ki ben

Ucuz hüzünler kiralardım

Alyanak bir kulakcıdan

Gök binlerce mavi şapkadır

Senin de şapkan mavi miydi

O günlerde? 

Hilmi diyor ki annem

Çiçek işlemeli bir lambaydı

Karartma gecelerinde

Sen de denizleri anlıyor muydun

Yatağa girmeden?', 'Hilmi diyor ki yeminler Bana çeşmeleri hatırlatır Tabut kalın ciltli bir kitaptır Senin de çocukluğun bir ceviz tabut muydu Usulca bırakılan...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Yavuz']::text[], 8.5, '{"poet":"Hilmi Yavuz","poet_slug":"hilmi-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hilmi-nin-cocuklugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözcüklerle Çıkmak Unutkanlığın Karşısına', 'sozcuklerle-cikmak-unutkanligin-karsisina-kemal-ozer-18zsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakarsınız, özetleyiverir bir tek sözcük, 

insanın bakışını bir savaşa.

Dönüşür bir tek sözcüğe, bakarsınız, 

geçmişteki bir olayın bütün anlamı.

Yıllar sonra, yeniden yazılmış, 

bir duvarda çıkar karşınıza.

Düşünürsünüz, küçümsenir gibi değil, 

bir tek sözcük deyip de hiçbiri; 

en az bir silah kadar yeri var kavgada.

Sözcükler olmasa, bir zaferin işlevini

nasıl çarpıtırlardı tarih kitaplarında, 

ne ile süsleyip de yuttururlardı yalanı? 

Anlarsınız, okurken yanlış bir şiiri, 

kendi sesinizle dirilttiğiniz düşman

ne kadar köprü varsa, yaşamla aranızda, 

biliyor önce onları atmak gerektiğini, 

sözcüklerle kurulduğunu biliyor köprülerin, 

geçmiş serüvenleri bugüne bağlayan.

Öyleyse, dersiniz, ulaşmak yetmez

nice kan ve acıdan sonra zafere, 

yapmak ve kazanmak kadar savaşı

sürdürmek de gerekir düşünce ve bilinçte, 

durmadan sürdürmek, çoğaltmak, tazelemek

en köklü yorumdan en küçük anıya dek.', 'Bakarsınız, özetleyiverir bir tek sözcük,  insanın bakışını bir savaşa. Dönüşür bir tek sözcüğe, bakarsınız,  geçmişteki bir olayın bütün an...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sozcuklerle-cikmak-unutkanligin-karsisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumsalda', 'kumsalda-kemal-ozer-d0xla', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kumsalda yürüyenlerin izlerini

dalgalar siliyor arkalarından

Birbirine seslenen iki kişinin

ne dediğini alıp gidiyor rüzgar

Yine de yürüyorlar kumsalda

ayakları yeni izler açarak

Sesleniyor yine de birbirine

yeni sözler bularak iki kişi', 'Kumsalda yürüyenlerin izlerini dalgalar siliyor arkalarından Birbirine seslenen iki kişinin ne dediğini alıp gidiyor rüzgar Yine de yürüyorl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kumsalda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilime Dolanıyor Gece', 'dilime-dolaniyor-gece-kemal-ozer-cssxz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söz almak için ayağa kalkıyorum

ve duruyorum yüreklerinizin önünde.

Kenetlenen dost elleri kutsamaya

ve uçurmaya barış güvercinlerini

hazır ağzımda sözcükler, 

anlatmaya hazırım sevdamı ve ülkemi, 

ırmaklar gibi taşıyıp getirdim

ürettiği bütün güzel sözleri

binlerce yıldan beri türkçenin.

Ama dökülmüyor ağzımdan işte

konuşmaya başladığım vakit

bunların hiçbiri.

Neyi söylemek istesem

dilime dolanıyor çünkü gece, 

çünkü elleri kenetleyen

dostluk değil gecenin kelepçesi, 

söz açmaya kalksam sevdadan

kurşunlanıp düşüyor kaldırıma çünkü

gencecik biri daha

ve kanına banıp gecenin parmakları

yazıyor adını gazete sayfalarına, 

çünkü yetmiyor anlatmaya güzel sözler

yurdumun üstündeki geceyi, 

yüreğimin üstündeki geceyi.', 'Söz almak için ayağa kalkıyorum ve duruyorum yüreklerinizin önünde. Kenetlenen dost elleri kutsamaya ve uçurmaya barış güvercinlerini hazır ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dilime-dolaniyor-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-serkan-arabul-7uoz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '10.10.2002

bitti

evet koskoca 3 yıl

         yıllar ne çabuk da geçti.

her şey ne güzel başlamıştı oysa.........

        ve şimdi..........

                        bitti.

ben söyledim bitsin diye

 ama istemeden

   çünkü söylemem için elinden geleni yaptı

       evet ben de söyledim.

şimdi; 

            şimdi mutlu muyum? ? ? ? 

                               hayır! ama artık yapacak birşey yok.

         Bitti 

                      ve inan biterken onu nekadar çok sevdiğimi söyledim.

       ama o kuru bir bitmesinden başka hiç bir şey söylemedi.

          artık burada kalmamı gerektiren hiç bir şey kalmadı.

        

                   gidiyorum

                                    ailemi, dostlarımı, işimi ve onu bırakıp gidiyorum.

                                             bir de kalbim, 

                                                                         kalbim hep burada kalacak.

 şairin dediği gibi ''aslında giden değil kalandır terkeden. giden de bu yüzden gitmiştir zaten''

                          dedimya gidiyorum buradan

                                                belki bir yıl 

                                                        belki iki

         ama aklım ve kalbim hep bu şehirde olacak

                                   kalbim hep bu şehirde atacak

                                            

                                                 hoşçakal giden sevgili

                                                             umarım yüzündeki o güzel gülümseme ebediyen kalır.

                                                                         HOŞÇAKAL....................', '10.10.2002 bitti evet koskoca 3 yıl          yıllar ne çabuk da geçti. her şey ne güzel başlamıştı oysa.........         ve şimdi.......... ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Arabul']::text[], 8.5, '{"poet":"Serkan Arabul","poet_slug":"serkan-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bitti-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse mutlu ol! - 4', 'gulumse-mutlu-ol-4-refik-recep-pelit-8cwxb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlemekten, hasret duymaktan 

bile mutluluk duyacaksın, 

Sevdiğine hasret kaldığın 

kadarda yakın olduğunu b

ileceksin, başkaldıracaksın umutsuzluga, 

karamsarlıga, 

baskaldıracaksın hayatın zorluklarına. 

Sadece bizmiyiz hayatın zoruklarını çeken 

sadece bizmiyiz üzülen, ağlayan, 

bilmiyormuyuz ağladıgımız kadar güleriz 

hayatta her şey eşit değilmi, 

her gidişin bir dönüşü yokmu ömür haricinde, 

hata yapmaktan korkmak kiminle yarış, 

kiminle boy ölçüşme, 

korkmayacaksın hata yapmaktan.. 

Keşke sevgim her zaman 

sevmeyi bilenleride bilmeyenleride durmaksızın uçursa...

Uçursa mutluluğa.

Benden aldıkları umutla en yasak şeyleri 

yaşamaya ömürleri boyunca hazır olsalar...

Oysa ellerini uzattıkları yerde güzelliğin 

ardında koşulsuz ve uçsuz bucaksız 

bir mutluluk bulacaklarını bilseler onlarda vazgeçmezler... 

Gördüm, bana uzanan ellerin hepsinin tertemiz oldugunu 

bembeyaz oldugunu, gördüm...

Çünkü benim sevmelerine 

izin vermek veya vermemek gibi bir şansım yoktu 

ve bu sözkonusu bile değildi, 

sevmek gönlün bir bahçesi hemde en güzel bahçesi, 

oraya girmek için izin alınmaz, 

izin almaya gerek de duyulmaz, 

kural yoktur sevmekte, olamazda zaten. 

Sevmesini bilenin içindedir güzellikler, 

çıkmak için fırsat bekler ve bir anda doğuverir, 

kimseye sormaz çıkarken, korkmazda.. 

Herşeylerini vermeye hazırdılar 

insanlar aşk için sevgi için. 

Sevgi yolculugu eger bir başlamıssa bitmez artık, 

istesende bitiremessin, 

her kes kendince sever değer herkes için farklıdır 

sevmesini bilen dagerlidir, değerli olmalıdır, 

Bilmiyormuyuzki değerimiz 

karşımızdaki insana verdiğimiz değer kadardır.

Önemli olan kiminle yola çıktıgımız değil, 

yola çıkmaya cesaretimizin, olup olmadığıdır. 

Korkmayacaksın kimseden özelliklede kendinden.

Boş yere harcanmayacak kadar değerli hayat, her günü, 

her dakikası hatta her anı.. 

Sen daha iyi şeylere layıksın demeyi 

her kes hak eder insan oldugu sürece, 

sevgiyi bildigi surece, 

iyi seylere layık oldugunu kendide bilir insanın, 

hak etsede etmesede insan iyi seylere layıktır, 

olmalıdır, hayat bu karamsar olunmayacak kadar uzun, 

sevinçlerin mutlulukların 

en kısa zaman diliminde bile yasanması gerektirdigini 

hatırlatacak kadar kısa. 

İnsan kendi hayatını kendi yüceltir, 

kendi umutlandırır, her sey kendinde saklıdır çünki, 

Çünkü neyi özlersem özleyim, nereye gidersem gideyim, 

özlediğim herşeyi, gittiğim heryeri biraz da kendime borçluydum..

Bilinmesi gereken ilk şey kendine sarılmasını ögrenmektir, 

güveneceksin kendine, 

baskalarının sana sarılmasını beklemek degildir.. 

Hem kaç kişi kaldı bu hayatta sevdasız kalınca 

ömründen kendini düşenler...

Şairin de dediği gibi...

Hem ben neyi özlersem özleyim; 

Uzun, çok uzun bir geceydi ömrüm..

Yalnızlıktan delice korkardım, 

ama kendimi en çok ayrılıklarda tanırdım. 

Ne kadar çoksa unuttuklarım, 

o kadarda çabuk oldu unutulmam, 

Ne kadar çoksa terkedenim ömrümde, 

o kadarda güzeldi vardığım heryer..

Ne kadar yaşarsak yaşayalım sevdiğimiz kadardır ömrümüz, 

Sevebildiğimiz kadar, gülebildiğimiz kadar mutluyuz Çünki', 'Özlemekten, hasret duymaktan  bile mutluluk duyacaksın,  Sevdiğine hasret kaldığın  kadarda yakın olduğunu b ileceksin, başkaldıracaksın umu...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/gulumse-mutlu-ol-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki*', 'i-yi-ki-bayram-tunca-98b7e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ancak bugün fark ettim, iyi ki iki evli değilim

Bu hususta, fazla söz söylemeye ehil değilim

Ama ikinciyle evlenecek kadar da deli değilim

Çünkü, ikisini idare edecek kadar veli değilim

30.09.2002-14.30', 'Ancak bugün fark ettim, iyi ki iki evli değilim Bu hususta, fazla söz söylemeye ehil değilim Ama ikinciyle evlenecek kadar da deli değilim Ç...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/iyi-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahr Oluyorum', 'kahr-oluyorum-civan-azadikar-vqeot', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğanın bütün güzellikleri bir yana

Uğraşlarımı

Kavuşulacak yüceliklerle kıyaslayınca

yağlı sicim

boynuma geçmesine ramak kala

Hiç bir şey ama hiç bir şey

gücüme gitmiyor

Ne hücremin 

boyun yarı beli olması

ne de 

gün görmemiş loşluğu

Hücremin karanlığında 

gözbebeklerimin ışıltısı

parıldıyor nasıl olsa

Yürüyecek dostlarım

Dostluktan yana

doğacak güne

Birtek şey varsa 

beni içten kahreden

Bedenime yapışmış kefenin 

Amerikan bezinden biçilmesidir', 'Doğanın bütün güzellikleri bir yana Uğraşlarımı Kavuşulacak yüceliklerle kıyaslayınca yağlı sicim boynuma geçmesine ramak kala Hiç bir şey a...', ARRAY['Türk Edebiyatı','Şiir','Cıvan Azadikar']::text[], 8.5, '{"poet":"Cıvan Azadikar","poet_slug":"civan-azadikar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kahr-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşemayşe', 'aysemayse-metin-eloglu-rhklr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüyü bitmemiş yetimliğimde miydin neydin, oysa babam yine sağ 

Ama adın Ayşe''ydi, ya da ayşemayşeydi ki 

Seni sırtımda bir küfe ana-kız gibi sevdim 

Değdim de denebilir - bakışıyorduk ya - 

Kış aksırığı hohlanmış ellerine 

Sonra senler bir başıboşluğa tüydü gitti 

Çalpara eteklerin çapraz ellerimde 

Sen de öyle mi yap dedim kendi kendime 

Coş savrul koşukoşuver esri 

- Ne haddime? - 

Ne haddime  mi 

Oh, her çimdik morartısına indiğimde 

Bir dişi  çukur - çıkmak belki de - 

Basamaklar noksandı hep 

Tabanlarımla merdiven içiçe 

Yepyeni bir göz takınıyordum tez 

Senin senden önceni görmeyesiye 

Adın Ayşe miydi, ayşemayşe miydi ne 

Kıraça daldım çok, kireç kerpiçe som buğday ekercesine 

Yufkayı un-ufak edercesine, ne ki en acıkımlık 

Gölgesinde bir leş yatırın çınarına ilk balta bu sevi 

İçi vıyıl vıyıl kurt, o da bir çeşni 

Ama kıç cebinde hep o yassı şişe 

İlle seni övdüm seni bildim seni sevdim yaşadım 

Yani bir gidişat ki pırnakıl bencesine 

Herkese duyur emi 

Ötesi tüm ayşemayşe 

Ha, bir de dulun penceresine tırmanmıştım yaz serinliğinde 

İbrişim dokurcasına keten kenevir yerine 

Ah ödünç Ayşe, ah yaşamın eğirdiği kıvrak yün 

Kâh kendini didiklercesine edindiğim büklüm filoş 

Dur, tâ gitme 

Bülûğ gövdede bir yanı gevşek örgüm 

Varını nakışlarcasına mıydı beni sevmen 

Alı al molu mor kilimler saçağında 

Bir azman çiçek gibi bükülmezliğimde, hoş 

Dipdiri sırmayı tiftikleyip de püskül kılmacasına 

Sımsıcak, yorgan-döşek, bitirim 

Maraş''ları Muş''ları hep geze geze 

İstanbul''dan hiç mi hiç çıkmadım 

Nice senler saysam yol boyunca sevdiğim 

Tepeden tırnağa ayşemayşe 

Sana bağdaş kuruşlarım mı? tuzuyaş''ın biriydim 

Hep o ben yaşımda 

İster şuydun de, ister buydun; doğrusu Metin 

Eh, bana bir türkü şimdi, ilki Karacaoğlan''dan 

Hasan yanım hâlâ çocuk tâ Alamanya''larda 

Özetliyeyim mi? 

Bu bir sevi tınazı 

Ve de ben kırık-dökük bir yaba.', 'Tüyü bitmemiş yetimliğimde miydin neydin, oysa babam yine sağ  Ama adın Ayşe''ydi, ya da ayşemayşeydi ki  Seni sırtımda bir küfe ana-kız gibi...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/aysemayse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıda Geçer', 'ayrida-gecer-civan-azadikar-fojvh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanık türküsünü söylerek

yüreğimin garından kalktı tren

dönen tekerlek değil başım

uykusuz gecenin ardından

...yaşadıkça gönlümde

kavuşmak dileği güzel günlere

ayrıda olsa geçer zaman', 'Yanık türküsünü söylerek yüreğimin garından kalktı tren dönen tekerlek değil başım uykusuz gecenin ardından ...yaşadıkça gönlümde kavuşmak d...', ARRAY['Türk Edebiyatı','Şiir','Cıvan Azadikar']::text[], 8.5, '{"poet":"Cıvan Azadikar","poet_slug":"civan-azadikar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrida-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-metin-yalcinkaya-bf9py', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ey yar! 

bir rüzgar getir sevdama

bırak ötelere

ıraklara sal! 

ey yar! 

bir bahar olsun getir sevdama 

bırak kışları ötelere 

yanımda kal! 

eyyar! 

Vuslatın ışığını yak 

Aydınlat yüreğimde

sevdama sal! 

Bilinmezlerdesin biliyorum...

Aşkınla giderken araflara

Adımı yüreğine al...

sağlıcakla kal ...

hoşçakal!!', 'ey yar!  bir rüzgar getir sevdama bırak ötelere ıraklara sal!  ey yar!  bir bahar olsun getir sevdama  bırak kışları ötelere  yanımda kal!  ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hoscakal-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-civan-azadikar-2oqz2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun argın batan 

Güneşe serdim seni

bir gün olurda

sıcak ışınlarını

değdirir yanağına

el öpmenin sıcaklığını duyarsan

bilki oğlun 

dikenli tellerin ardında

kutluyor bayramını 

                           sensiz', 'Yorgun argın batan  Güneşe serdim seni bir gün olurda sıcak ışınlarını değdirir yanağına el öpmenin sıcaklığını duyarsan bilki oğlun  dikenl...', ARRAY['Türk Edebiyatı','Şiir','Cıvan Azadikar']::text[], 8.5, '{"poet":"Cıvan Azadikar","poet_slug":"civan-azadikar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bayram-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Aşk', 'adin-ask-metin-yalcinkaya-t9f7q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şairliğim kutsansın adında

ak perçevin yüreğime düşsün

daha bir mavi deniz 

umarsız bir gece 

muradım olsun

adın aşktır bende  adında kutsansın adım

nasıl sevdiğimi şahikalarla anlattım', 'şairliğim kutsansın adında ak perçevin yüreğime düşsün daha bir mavi deniz  umarsız bir gece  muradım olsun adın aşktır bende  adında kutsan...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/adin-saduman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Bir Güzelsin', 'daha-bir-guzelsin-metin-yalcinkaya-c45v9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'daha bir güzelsin şimdi sen 

daha bir gül...

yanakların hala al al

üzerindeki mavi kazağın 

o boynundaki şal

 ve uzun beyaz elbisen 

daha bir güzelsin şimdi sen

Daha bir gül... 

bir melek olmalısın ezelden

tamamlamışsın şimdi kendini 

Unutturmadi ki bana ölmen

Ne olur gül...

daha bir güzelsin şimdi sen

Daha bir gül...

melek gibiydin diyordum ya 

Meleklerden bir melek 

Daha bir güzelsin, daha bir gül...

Bil ki hayat ışığım seninle tükenecek...', 'daha bir güzelsin şimdi sen  daha bir gül... yanakların hala al al üzerindeki mavi kazağın  o boynundaki şal  ve uzun beyaz elbisen  daha bi...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/daha-bir-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Ömür', 'giden-omur-civan-azadikar-yewtf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birçırpıda geçen 

yirmi beş yılı düşündüm

acısını çektim

sevincini yaşayamadan yaşamın

gözlerimi açtığımda

savaşta buldum kendimi

acemi asker edasıyla

ve kapayamadım 

zeytin dalının 

gölgesi altında gözlerimi

namlunun soğuk bakışı

titreşmesini engelliyordu yaprakların

ne olduğunu anlayamadan

geçti zaman

pencerenin yağmurluğundan

bir yirmi beş yılın daha 

hesabını yaptım 

birzamana birde kendime baktım 

getirdikleri güzel olunca

''gel zaman '' dedim

oysa giden ömürdü

farkına varamadan', 'Birçırpıda geçen  yirmi beş yılı düşündüm acısını çektim sevincini yaşayamadan yaşamın gözlerimi açtığımda savaşta buldum kendimi acemi aske...', ARRAY['Türk Edebiyatı','Şiir','Cıvan Azadikar']::text[], 8.5, '{"poet":"Cıvan Azadikar","poet_slug":"civan-azadikar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/giden-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-civan-azadikar-u26gc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Veremem sana 

ak günlerin umudunu

ve dolunay bakışında

üç odalı bir ev kuramam

kan ağlarken (ülkem)   yüreğim

çocuklara dizimde 

ninnide söylemem

kuru baş soğan kadar kuru

bir sevgiden başka

hiçbir şey veremem

ne aşkından deliye dönerim 

ne de Ferhat olurum dağlarda

seveceksen 

böyle sev beni

unut aklından geçenleri

şu dağ, bu orman demeden

gezegen bir evde

ve hergün tetikte ölüm 

yaşamaya ne dersin?', 'Veremem sana  ak günlerin umudunu ve dolunay bakışında üç odalı bir ev kuramam kan ağlarken (ülkem)   yüreğim çocuklara dizimde  ninnide söy...', ARRAY['Türk Edebiyatı','Şiir','Cıvan Azadikar']::text[], 8.5, '{"poet":"Cıvan Azadikar","poet_slug":"civan-azadikar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/davet-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapalarla Yeniden Seni Bulmaksa', 'capalarla-yeniden-seni-bulmaksa-orhan-polat-9ogqn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen aşksan suyun üzerinde, 

Sana aşksa benlik, 

Yola vurup kendini, 

Kaçmak olsa gerek bence...

Sorunlayıp dünyaya, 

Sığmadan, durmadan kaçmak...

Bir elin hasretin pençesinde, 

Diğeri damağa kalmak gibi, 

Gidiple - gidememek için, 

Gel - gitlere bulanmak gibi.

Huzur yoldaysa, 

Yola vurmak kalbini, 

Yola, yelle esmekse sen, 

Esipte geçmekse diyarlardan, 

Diyarlarla seni benliğimde çapalamaksa, 

Çapalarla yeniden seni bulmaksa...

(11 Ekim 2002 / ANKARA)', 'Sen aşksan suyun üzerinde,  Sana aşksa benlik,  Yola vurup kendini,  Kaçmak olsa gerek bence... Sorunlayıp dünyaya,  Sığmadan, durmadan kaçm...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/capalarla-yeniden-seni-bulmaksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kana Kana', 'kana-kana-mustafa-sureyya-sezgin-hdn8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceyi haber veren kızıllıklar ötesinde

Güneş bile kaybolmak istiyor.

Yağmur yağiyor yanaklarımdan, 

Seller boşanıyor gözlerimden, 

Ağlamıyorum...

Ürperen tüylerimle, 

Kayboluşunu seyrediyorum.

Neden bahar gelmesin diyorum, 

Neden? 

Dönmeni istedikçe

Ve seni özledikçe, 

Noktalaşıyorsun ufkumda...

Erişmenin yolu yok mu sana? 

Gitme, 

Ne olur bekle...

Doyamadım daha, 

Seyretmeye seni

Kana kana...', 'Geceyi haber veren kızıllıklar ötesinde Güneş bile kaybolmak istiyor. Yağmur yağiyor yanaklarımdan,  Seller boşanıyor gözlerimden,  Ağlamıyo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kana-kana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-turgay-kadiroglu-v990z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şiir yazan kalemlere mahrem kalasın, 

sevgi kokan çiçeklere mahrum kalasın, 

ihanet nişanı yüzünde muhkem kalsın, 

katil yüreğin göğüs kafesinde mahkum kalsın, 

yağmur getiren melekleri özleyesin, 

gündüzü gece geceyi gündüz bilesin.

uzun gece, kısa gündüz ne demek bilesin, 

bir tek seni sevdiğimi bilmeyesin.

aşık olasın sevdiğim, sevesin, 

kalbin dar gele onu sıkıştırdığın kafesine, 

ve kalbin ağır gele bedenine 

kabini taşlara vurasın, 

kanlara boyayasın dünyanı.

aslı olsun adın yada Züleyha, 

işkence aletin ateşin olsun, kül kokasın, 

ya da tırnakların olsun kan kokasın, 

iyisi mi adın ben olsun, 

göresin nasıl yaşanır

yaşlanmayı her gün özlemleyerek.

ölesin, en mutlu anında bir gün

bulutlara gömülesin, 

yağmur olasın, yağasın saçlarıma, 

adına her gün kar yağdırdığım saçlarıma, 

hatırlıyor musun sevdiğim, 

cenaze törenlerimin baş konuğuydu kar, tabiki senden sonra.

beni bulamazsan yağarken yeryüzüne

yalnız adamda bulursun.

yalnızlığın ne idüğünü bu küçük adamda bulursun, 

bu adada yalnız (,)   ADAM bulursun.

sen bulutlarda uyurken ölesiye, 

toprak çeksin bedenin, 

seni kurtarmaya talip dağların

sana uzansın gün be gün

ve benim ırmaklarım baş kaldırsın dağlarına

ta tepelerine

yıkılsın engin dağların, 

yıkılsın göklerden aşağıya bakan mağrur bakışların, 

sana ölümünde bile, 

hiç kimse el sürmesin, 

hatta toprak bile...

bu beddua da uyuyacak tıpkı senin gibi, 

sen okuduğunda bedduam uyanacak, 

büyün bozulacak, 

tüm beddualarım vücuda gelecek

ve senin kıyametin gelecek

ve gelecek artık seni beklemeyecek, 

yıllardır desteksiz ayakta durmaktan yorgun gökler

yorgunluklarını boşaltacak ve düşecek arza, 

yıllardır seni görmekten korkan gözler, 

can suyunu boşaltacak, siyaha boyayacak kanınla boyadığın arzı.

hapsolundukları çukurlardan azad olacak denizler, 

içimin ateşiyle dolacak, boşalan çukur kafesler, 

işte o an belki ilk kez ve son kez beni anlayacaksın, 

beni anlamanın maliyeti büyüktür, 

artık senin beni anlamanın hükmü bir hiçtir.

ve son bir duam sevdiğim, 

sen bu bedduayı hiç okumayasın.

bir ömür bu bedduadan bir de benden bihaber yaşayasın...', 'şiir yazan kalemlere mahrem kalasın,  sevgi kokan çiçeklere mahrum kalasın,  ihanet nişanı yüzünde muhkem kalsın,  katil yüreğin göğüs kafes...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/beddua-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akım', 'akim-turgay-kadiroglu-t53hd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seven yüreğim mi, aklım mı? 

Yoksa gözlerini gözlerime mıhlayan, 

Lambada yanmayan akım mı?', 'Seven yüreğim mi, aklım mı?  Yoksa gözlerini gözlerime mıhlayan,  Lambada yanmayan akım mı?...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/akim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız (,) Adam', 'yalniz-adam-turgay-kadiroglu-zi6ej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir ''ada''m olsun okyanus ortasında

adı yalnızlık olsun ''ada''mın, 

bir adam olsun hayatın yarısında

adı ben olsun adamın, 

ada mekanı olsun adamın, 

adam, yalnız olsun, 

adada yalnız (,)   adam olsun, 

başka kimse olmasın.

hiçbir şey olmasın, 

ne su damlası, ne çayır kuşu, 

ne yaprak tanesi, 

hepsi kıyılarda kalsın, 

adam tepelerde yaşasın.

düşünceler bulut olsun, 

göklerde kalsın, 

duygular toprak olsun 

ayaklar altına yatsın, 

ve her yağmurda, 

göğün kustuğu

düşünceler istila etsin

en temiz duyguları.

ve her yağmurda adam uyusun

düşler görsün istiladan bihaber, 

düşüncelerden arınmış düşler, 

yalnızlık düşleri..

ve her yağmurda

dünya boğulsun

üzüntü tufanında, 

ardından gökkuşağı dağıtsın tüm kederi

ardından adamsız dünya dönmeye devam etsin.

adam adada yaşasın, 

adada ölsün, 

duygularına gömülsün, 

düşünceleri yas tutsun ve mezarına aksın, 

mezarına ''yalnız(,)  adamdı.'' yazılsın...', 'bir ''ada''m olsun okyanus ortasında adı yalnızlık olsun ''ada''mın,  bir adam olsun hayatın yarısında adı ben olsun adamın,  ada mekanı olsun a...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yalniz-adam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek', 'melek-turgay-kadiroglu-2xdkn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'okyanusun soluğu ağır gelir gök denizine, 

her birine bir melek nişan vurur.

yağmur olur damlar bir bir yüreğime, 

ve yüreğimde bir melek can bulur.', 'okyanusun soluğu ağır gelir gök denizine,  her birine bir melek nişan vurur. yağmur olur damlar bir bir yüreğime,  ve yüreğimde bir melek ca...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/melek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum', 'mum-turgay-kadiroglu-raej1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mumlar erir, 

kül olma hakları yoktur, 

aydınlatırlar ve erirler, 

erirler ve aydınlatırlar.

içten içe erimesi, 

kabından taşıp, 

etrafı kirletmemesi makbuldür.

hem içten içe erirse, 

eriyik mum tekrar eriyebilir, 

böylece sürer gider, 

sonsuza dek bir eriyiş, 

içten içe, 

hem de etrafına ışık saçarak.

mumlar erir, 

tıpkı benim gibi...', 'mumlar erir,  kül olma hakları yoktur,  aydınlatırlar ve erirler,  erirler ve aydınlatırlar. içten içe erimesi,  kabından taşıp,  etrafı kir...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-turgay-kadiroglu-10lqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevda kıvılcımla başlar, 

acıyla sürer, 

yangınla söner...', 'sevda kıvılcımla başlar,  acıyla sürer,  yangınla söner......', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sevda-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki İsimli Şiir', 'i-ki-i-simli-siir-turgay-kadiroglu-y8z2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tarık çaksa semada yüreğim dirilir miymiş, 

fırtına kopsa gök denizinde hasretim diner miymiş? 

ufuktan yükselse ışık, gözlerim görmez miymiş? 

esse bir rüzgar çıldırırcasına, kulağımda fısıltısı çınlar mıymış? 

reyhanı, gülü, menekşeyi, ıtırı da beraberinde getirir miymiş? 

yarına sabırsızca, düne hasretle bakılır mıymış? 

günü yaşamaktan bihaber bir ömür yaşanır mıymış? 

zindan yapsam yüreğime, lutfedip de içeri girer miymiş? 

adını yazsam mezar taşıma, ölüme dek beni sever miymiş? 

aşkımı kazısam Hızır''ın yudumladığı bengisuya, eğilir de içer miymiş? 

yabanıl ölümden uzak olsa da çayır kuşuyla beraber mezara girer miymiş?', 'tarık çaksa semada yüreğim dirilir miymiş,  fırtına kopsa gök denizinde hasretim diner miymiş?  ufuktan yükselse ışık, gözlerim görmez miymi...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kadiroğlu']::text[], 8.5, '{"poet":"Turgay Kadiroğlu","poet_slug":"turgay-kadiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iki-isimli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-aykut-demirci-ce62i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllardır seni bekler bu gönül, 

Duysana..

Seni aradığım yolları aydınlatmak için doğar

Her sabah güneş..

Tüm bu yağmurlar, fırtınalar sebepsiz değil, 

Ruhumdaki karamsarlıkları, 

Gözlerimdeki yaşları ancak onlar bastırır

Onlar destek olur kötü günümde bana..

Yıllardır seni arar

Yıllardır seni ağlar bu gönül, 

Neredesin? 

Bir parçan benim

Kabullen bunu artık..

Ben sensiz, sen bensiz

Sadece küçük birer yarımız, 

Yıllardır yarım..

Yıllardır yârim der bu gönül, 

Gel artık..

Bırak bu öldüren oyunu..

Uzan, tut ellerimi

Bırakma bir daha..

Daha öncekiler gibi olmasın, 

Ellerim ıslak, kayıvermiştin avuçlarım arasından..

Ellerim ıslak, yüreğim kaygan

Oda azıcık heyecandan..

Ne yapsın, 

Yıllardır sana

Yıllardır seni çarpar bu gönül, 

Hoşgör artık..

Çık saklandığın köşeden, 

Sana körüm zaten, uğraştırma daha fazla..

Gel..

(IQ''t 04.602.1201 VM)', 'Yıllardır seni bekler bu gönül,  Duysana.. Seni aradığım yolları aydınlatmak için doğar Her sabah güneş.. Tüm bu yağmurlar, fırtınalar sebep...', ARRAY['Türk Edebiyatı','Şiir','Aykut Demirci']::text[], 8.5, '{"poet":"Aykut Demirci","poet_slug":"aykut-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakitsiz', 'vakitsiz-kadir-ciplak-98c1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Demirci türküleri çalınır evlerde 

öğle vakitleri

Dantelli kıyafetlerde kalır aklım

ince belli bir tebessüm

Tehlikeli

Adamı verem eden

Bir eşkıya sakatlanır bıyığından 

bana mısın demeden

II.

Gelin arabaları süslenir o şehirde

platonik savaşlar yaşanır

Keşiş dinginliğiyle çıkılır yolara

Yollar kurum kokar

mürekkep lekeli yollar

Geri dönmeyebilir

haddinden fazla esmer adamlar

Günün yemeği pirinç pilavıdır o vakitler

ve bezelye

III.

Anahtar sesiyle başlanan cümleler

tutarsız yüklemlerle sonlanır

çikolata kabuklarında kalır aklım

IV.

Meyveli gazoz kapakları

ve kiremit tozları

şüphesiz sosyalisttir

Bilinmez kim olduğu o vakitler

son ütücünün

önemli de değildir

V.

Üç tekerlekli bisiklette kalır aklım', 'I. Demirci türküleri çalınır evlerde  öğle vakitleri Dantelli kıyafetlerde kalır aklım ince belli bir tebessüm Tehlikeli Adamı verem eden Bi...', ARRAY['Türk Edebiyatı','Şiir','Kadir Çıplak']::text[], 8.5, '{"poet":"Kadir Çıplak","poet_slug":"kadir-ciplak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vakitsiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Saklı Geceler', 'seninle-sakli-geceler-esra-turkoglu-dvt7v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecelerime sakladim seni 

karanligin yorgan gibi üzerimi örttügü zamanlara 

aydinliktan uzak gecelerime sakladim seni 

yalnizligi yasadigim saatlere 

özlememek icin gecelerime sakladim seni 

dönmeyecegini bildigim halde bekledim 

seninle sakli gecelerimde düsündüm seni 

senin beni düsünemeyecegini bilsemde 

karsiliksiz kalan sevgim gibi 

gündüzü tanimayan gecelerime sakladim seni 

en duygusal vakitte hayalimde ol diye 

sensiz rüyali gecelerime sakladim seni 

gülümsedigimi hisset diye agladigim 

o en hüzünlü gecelerime sakladim seni 

gülümsedigimi farkedip huzurlu uyumani istedim 

sensiz gecen gündüzlerimden sonra 

senli gecsin diye 

o en güzel gecelerime sakladim seni 

yasayan ve ölen seni göremedigim icin belkide 

beni gördügünü sandigim 

en karanlik gecelerime sakladim seni 

bir isikta olsa 

sinyallerini bekledigim 

sari yildizli gecelerime sakladim SENi! 

3 mart 2001', 'Gecelerime sakladim seni  karanligin yorgan gibi üzerimi örttügü zamanlara  aydinliktan uzak gecelerime sakladim seni  yalnizligi yasadigim ...', ARRAY['Türk Edebiyatı','Şiir','Esra Türkoğlu']::text[], 8.5, '{"poet":"Esra Türkoğlu","poet_slug":"esra-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seninle-sakli-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğmak', 'yeniden-dogmak-ozan-rari-usfnf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatım sürükleniyor

Anlamaya, öğrenmeye çalışıyorum

İçimde fırtınalar onları dizginlemek istiyorum

Yapabilir miyim kuşkusu karşımda! 

Olmalı diyorum, mutluluk benimde olmalı...

Bir kız geldi ansızın yalnızlık köşküme

Aldı götürdü beni hiç gitmediğim yerlere

Neresiydi orası gerçek mi, yalan mı? 

Hatırladığım tek şey; ayaklarımın yere basmadığı idi.

Uyandım birden kendimi yine rutin yaşamımda buldum! 

Sanki yaşamadım, gitmedim bilinmezliklere

Kaldım yine kendimle sonunda

Kabulendim herşeyi yolum böyle imiş

Yaşar mıyım o güzellikleri başka birisi ile yeniden

Etrafımda benden habersizdir belki

O da bekliyordur kendince onu alıp bilinmeyen diyarlar götürecek adamı.

Beklemek nasıl da meraklandırıyor beni

Gözleri, saçları, kokusu nasıl acaba? 

Aradığımı bulabilecekmiyim onda! 

Eş ruhum sen misin; ey esrarengiz dilber.

     (12.10.2002-Bilkent Doğu)', 'Hayatım sürükleniyor Anlamaya, öğrenmeye çalışıyorum İçimde fırtınalar onları dizginlemek istiyorum Yapabilir miyim kuşkusu karşımda!  Olmal...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yeniden-dogmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sende Tattım Aşk''ı', 'ben-sende-tattim-ask-i-salih-ozalasan-a54fh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son sözüm bir sen bir de tanrı

Tanrıya bağlıyım çünki beni yarattı

Sense Dünya''da yok bir eşi

Ben sende tattım aşk''ı

Seninle yok oldu 

Yüreğimde söylenen içli şarkı

Senden önce hayatın yoktu

Belkide saman alevinden hiç farkı

Seninle değişti anlam kazandı

Bende geceyle gündüzün farkı

Gecem bir başka güzel

Gündüzüme sesin hayat kattı

Şimdi dilimde hep o

Bana armağan ettiğin içli şarkı

Sözlerinde bir umut 

Beni hayata bağlayan sır vardı

Bu şarkıdan sonra bende

Hayata dört elle sarılmak kaldı

Ve inandımki sende inan

Tanrım beni; seni sevmek için yarattı

Y.Tarihi 12-10-2002 Saat 16.00', 'Son sözüm bir sen bir de tanrı Tanrıya bağlıyım çünki beni yarattı Sense Dünya''da yok bir eşi Ben sende tattım aşk''ı Seninle yok oldu  Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-sende-tattim-ask-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk diyelim....!', 'ask-diyelim-mustafa-gozubuyuk-1z898', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçliğin bağrından kopartıp seni; 

Karanlık dünyama güneş eyledim.

Varlığın bağrından sıyırıp teni; 

Vehmimde diriltip bir eş eyledim.

Az ile yetinip çöle düşen ben; 

Bir meçhul isimle zakir olurum.

Dağları delipte dile düşen ben; 

Zavallı olurum, hakir olurum.

Teselli ararım viranelerde, 

İpekten kundakta uyursun şimdi; 

Hasretin ok, yaşanan her seherde...

Hayalin, köşküme buyursun şimdi...

İfrattan sakındım incinme diye, 

Bülbülü dinledim asırlar boyu.

Bir tel saçın can alacak hediye, 

O kadar faşisttim, o kadar koyu...

Cıncıktan yüreğin kırıksa şimdi; 

Aldığın ömrüme bedel biçelim.

Seni kendine mahkum eden kimdi? 

Beraber ağlayıp, hemde içelim.

Esrarın düşledim yıllar boyunca, 

Sular mı süzülür parmaklarından? 

Ah dedim! Ağladım ruhum doyunca.

Şarap mı akıyor ırmaklarından...? 

                                                  (18-10-2001)', 'Hiçliğin bağrından kopartıp seni;  Karanlık dünyama güneş eyledim. Varlığın bağrından sıyırıp teni;  Vehmimde diriltip bir eş eyledim. Az il...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gözübüyük']::text[], 8.5, '{"poet":"Mustafa Gözübüyük","poet_slug":"mustafa-gozubuyuk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-diyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormadılar', 'sormadilar-sota-papaladze-z30r5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sormadılar yüzümün beyazlığını

Sıcak yaz aylarında.

Ateşimi, 

İşimi, 

Vakitsiz gelip gidişimi.

Ve görmediler

Sacımdaki akların sıklığını, 

Gönlümün kırıklığını, 

Patlarcasına olan sıkkınlığımı.

Ve yine bilmediler

Aşkımı, 

Kuşkumu oynaşımı, 

Ve kendimden başka sırdaşımı.

             Tashkent  28.09.1999', 'Sormadılar yüzümün beyazlığını Sıcak yaz aylarında. Ateşimi,  İşimi,  Vakitsiz gelip gidişimi. Ve görmediler Sacımdaki akların sıklığını,  G...', ARRAY['Türk Edebiyatı','Şiir','Sota Papaladze']::text[], 8.5, '{"poet":"Sota Papaladze","poet_slug":"sota-papaladze","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sormadilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşan Zaman', 'kosan-zaman-ali-puskulluoglu-isemt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önemsiz demeyin.

Hafiften esen bir yel bile

Önemsiz değil.

Zaman yaklaşsa da

Unutmam sizi, çünkü bir düşte

Sonsuz bir anımsayıştır yaşamak.

Ah, elbet yaşamak! Yaşamak! 

Bunu derken, o an

Suya iniyor bir suna

Aşktır, çoğalıyor yeryüzünde.

Bir tay gibi koşuyor zaman

Yaşanıyor işte.', 'Önemsiz demeyin. Hafiften esen bir yel bile Önemsiz değil. Zaman yaklaşsa da Unutmam sizi, çünkü bir düşte Sonsuz bir anımsayıştır yaşamak. ...', ARRAY['Türk Edebiyatı','Şiir','Ali Püsküllüoğlu']::text[], 8.5, '{"poet":"Ali Püsküllüoğlu","poet_slug":"ali-puskulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kosan-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehenneme Kurulan Kamp', 'cehenneme-kurulan-kamp-ayhan-kirdar-dasw3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben iki elimde iki hançer

Kıpkızıl günahlar örmüşüm

Bu eller benim ellerim cennetten kovuldular

Kan kusan geceye nehir nehir

Tükrükle boğulan ezilen lanetlenen

İrin yüklü bakışlardan bu kaçıncı kaçışım

Bu kaçıncı saplayışım tırnaklarımı yüreğime

Ama ölmedim

Neden ölmedim

Öptüm ölümün kaynamış tutkal kokan ağzından

Kara kara yengeçlerin yuva yaptığı

Işık değmemiş ıslak saçlarına astım kendimi

Belki bin yıl sallandım durdum

Ama ölmedim

Neden ölmedim

Bıktım bu dost cüceler ülkesinde

Dev yalnızlığımı sırtımda taşımaktan

Yorgun alnımdan

İri terlerin aktığı kör kuyulara

Yılanların ve akreplerin

Ve ısırgan böceklerin susuzluğunu gideren

Bu denizler benzindi hep

Ve hep ne varsa deniz denilen kıyılarda ateşler yaktım

Ama ölmedim

Neden ölmedim

Açmış aç ağızlarını cılız arzular

Dişleri diken diken etimde dolaşan

Tutup bütün kapılarını kırıyorum mabetlerin

Tanrıyı arıyorum

Tanrı yok diyorlar ama neden yok

Bir yumruk olup sıkılıyorum

Parmaklarım dökülüyorlar

Bir kaç cam kırıyorum buz tutmuş gökten

Ben yarıdan fazla günahkarım biliyorum

Yarıdan fazla karanlık bu yer bu insanlar bu okyanus

Ve neden sonra zaman

Bir iskele olup sıyrıldı takvim yapraklarından

Artık bütün şarkılar susmuştu ölüm Tanrısı susmuştu

İçimdeki çanlar susmuştu ben susmuştum

Cehennemde yer bulmak zordu

En utanılır günahlarımı Sırat köprüsüne astım

Güneş bir fahişe gibi sarışındı üşüyordum

Demir örgülü kızgın kapıların mermer eşiğinden

Sümük gibi alevler akıyordu

Alev denizinde yıkanıyorduk -ho ho hoy-

Alev denizinde

Alev

Deniz

Alev

Tanrının iskeletinden kan sızıyordu...', 'Ben iki elimde iki hançer Kıpkızıl günahlar örmüşüm Bu eller benim ellerim cennetten kovuldular Kan kusan geceye nehir nehir Tükrükle boğula...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Kırdar']::text[], 8.5, '{"poet":"Ayhan Kırdar","poet_slug":"ayhan-kirdar","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/cehenneme-kurulan-kamp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölümden Kalanlar', 'bir-olumden-kalanlar-behcet-necatigil-vks6p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğuşundan beridir sakladığı

Tanrının bir emaneti vardı.

Yatağa düştü, 

Üçüncü gün akşam üstü, geri verdi güler yüzlü.

- Kalsın bende temelli, diye ağlar bazıları. -', 'Doğuşundan beridir sakladığı Tanrının bir emaneti vardı. Yatağa düştü,  Üçüncü gün akşam üstü, geri verdi güler yüzlü. - Kalsın bende temell...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-olumden-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
