INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-erdogan-alkan-ho4gu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözler çok önemli gözler

gözlerle gelir önce

bir şey başlayacak demektir

eller ellere değince

bir kadın koluna yatsa

kıpırdayamazsın sevince

bilmediklerine özlem duyarsın

bildiğini düşünürsün günlerce

sevda başlamıştır artık

kadın uykuya da', 'Gözler çok önemli gözler gözlerle gelir önce bir şey başlayacak demektir eller ellere değince bir kadın koluna yatsa kıpırdayamazsın sevince...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Alkan']::text[], 8.5, '{"poet":"Erdoğan Alkan","poet_slug":"erdogan-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Kızları', 'eylul-kizlari-erdogan-alkan-uyvwo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm uzak balkonundan yıldızların

Ağarırken Edirne eteklerinde

Ayışığı çizerdi eylül yüzüne

Dalgınlığı, kan tutan ince kızların.

Güz yağmuru karanlık kirpiklerinde

Öpmeğe susamış haylaz oğlanlardı, 

Bir esmer gecenin utancı vardı

Kuytu gözlerinin en ıssız yerinde.

Okşadıkça toy bedenlerini rüzgar

Aşkı ya da ölümü soyundururlar

Koklanmış bir karanfil yorgunluğunda.

Yüzlerinde çapkın dili alevin

Kan tutan ince kızlar aşk uykusunda

Açan üzgün ay çiçekleriydi evin.', 'Ölüm uzak balkonundan yıldızların Ağarırken Edirne eteklerinde Ayışığı çizerdi eylül yüzüne Dalgınlığı, kan tutan ince kızların. Güz yağmuru...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Alkan']::text[], 8.5, '{"poet":"Erdoğan Alkan","poet_slug":"erdogan-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eylul-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-kerim-aydin-erdem-bdw65', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep Kaf Dağı''nda durmayın çocuklar

Doğrular, gerçekler büyütsün sizi

Vatan sevgisiyle bütünleştirin

Güzelliğinizi.

Bakmayın nehirlerin bozbulanık aktığına

Zorluklar korkutmasın sizi

İnsan sevgisiyle bütünleştirin

Güzelliğinizi.

Aylar gelir geçer, yıllar gelir geçer

Belki rüzgarlar üşütür sizi

Bir bütünleşin bilgiyle, kültürle

Mevsimler bükemez bileğinizi.

Karanlıktayız, oturmuş bekliyoruz

Işık olun kurtarın bizi.', 'Hep Kaf Dağı''nda durmayın çocuklar Doğrular, gerçekler büyütsün sizi Vatan sevgisiyle bütünleştirin Güzelliğinizi. Bakmayın nehirlerin bozbu...', ARRAY['Türk Edebiyatı','Şiir','Kerim Aydın Erdem']::text[], 8.5, '{"poet":"Kerim Aydın Erdem","poet_slug":"kerim-aydin-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocuklar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Buluştu', 'oluler-bulustu-kerim-aydin-erdem-4wmnp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni hiç beklemiyordum

Demek sonunda sen de öldün

Çoktandır buradayım işte

Gelirken kimleri gördün? 

Yalancıktan ağladı mı dostların

Saksıdaki son karanfil soldu mu

İşlerini bir yana bırakıp

Bizlere de selam yollayan

Oldu mu? 

Artık kalmadı düşüncen

Yerin yuvan burası

Bakalım kaç adım gelecek

Cennetle cehennem arası.

Bazan kırlara çıkıyoruz

Gökyüzünü buluyoruz sesimizle uyanan

Dünyanın iç yüzünü görüyoruz

Şehre indiğimiz zaman.

Sen de aramıza genç yaşta karıştın

Üzüntüden en güzel ağaç dallarını kırsın

Birazdan öteki ölüler de gelir

Tanışırsın.', 'Seni hiç beklemiyordum Demek sonunda sen de öldün Çoktandır buradayım işte Gelirken kimleri gördün?  Yalancıktan ağladı mı dostların Saksıda...', ARRAY['Türk Edebiyatı','Şiir','Kerim Aydın Erdem']::text[], 8.5, '{"poet":"Kerim Aydın Erdem","poet_slug":"kerim-aydin-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oluler-bulustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzenim Seninle Bozuldu', 'duzenim-seninle-bozuldu-oktay-tuncer-nqe8g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün karanlıklarımı al götür

Yeniden öğret evleri ağaçları bayramları

Bütün karanlıklarımı al götür.

Günlerce yağmur yağsın istiyorum

Yağmur yağsın ve konuşma

Cümle dağ çiçekleri ıslansın ve konuşma

Ya da küçük kırmızı bir çiçek ıslansın.

Bunlar beyaz güvercinler

Bunlar büyük meydanlar

Bu küçük bir dağ çiçeği

Sen hiç gülmeyi bilmiyorsun

Sen hiç sevmeyi bilmiyorsun

İki kırmızı çizgi atbaşı

Yağmurlar hiç durmadan yağıyor

Artık dağ çiçeklerini sevmiyorum

Seyretmiyorum güvercinleri meydanlarda

Artık yaşamayı hiç bilmiyorum

Artık hiç konuşma.', 'Bütün karanlıklarımı al götür Yeniden öğret evleri ağaçları bayramları Bütün karanlıklarımı al götür. Günlerce yağmur yağsın istiyorum Yağmu...', ARRAY['Türk Edebiyatı','Şiir','Oktay Tuncer']::text[], 8.5, '{"poet":"Oktay Tuncer","poet_slug":"oktay-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duzenim-seninle-bozuldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balık Kız', 'balik-kiz-nihat-ziyalan-mlnfr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sokakla birlikte yüzer

balık kız dediğim

pencerelere üşüşmüş bekleşenlerin

bekleşen yüzüyle yüzer

pullarının ışıması

sana iç geçirtir

balık kızım

pullu güzelim diye

saysan kılçıklarını sayarsın

üzülürsün

bana olan aşkından bir deri bir kemik kalmış diye

okursun

derisinin altından

aklından geçenleri

bencilliğine yenik düşer

kimseye söylememek için güzelliğini

dilini ısırırsın

alışkanlık olur dilini ısırmak

pullu güzelim diye iç geçirmek

bazen yakaladım diye

kollarının arasında

bağrında

boşuna sıkıp kucaklarsın boşluğu

çoktan cup diye atlamıştır

bir başka kucağa

pullarının ışımasını

kokusunu bırakır geride

ellerinde', 'sokakla birlikte yüzer balık kız dediğim pencerelere üşüşmüş bekleşenlerin bekleşen yüzüyle yüzer pullarının ışıması sana iç geçirtir balık ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Ziyalan']::text[], 8.5, '{"poet":"Nihat Ziyalan","poet_slug":"nihat-ziyalan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/balik-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Sonu, Bir Ağıt', 'gun-sonu-bir-agit-kemal-ozer-w27uc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'senden alıp gidiyor gözlerimi

gölgesi bile sığmıyor yüzüme yorgunluğun

alıp gidiyor dönmeyen atlıkarıncalar

kırların düş artığı şölencileri

sanki ben değilim baktığın kadar

karla rüzgar alıp gidiyor geceye uygun

onları unutmamak bunca uzaklıktan

sarp yürekli ermişlerini boşluğun

göğe açılan yangınları unutmamak

kara bir günbatımı girişken saçlarından

yitik bir ses taşıdıkları ırmak

kırlarda tütüp duran binlerce bozgun

çığlıkları ağaçlara asılı

ıssızlığı yürüyenler birikmiş yoğun

herkesin yüzünde onlardan bir iz

bir kapanmaz yara ölüme karşı

kıyısına gelip durdukları deniz

damgasını yedikleri boğulmuşluğun

kan alıp gidiyor ışığa doğru

senden alıp gidiyor senin uğultun

geçitsiz bir başdönmesi karanlıkta

kulelerin çizgileşen uçurumu

çizgileşen o yenilgi her bakışta

açılmayı bekleyişi bir tohumun

düşler seni de karartıyor ey şehir

aldananlar yargılılar kim varsa unuttuğun

birer birer çıkıyorlar dalgın su yüzüne

yüreklerinden yayılan eski kır günleridir

kırçıl akşam şarkısı surların üzerinde

senin o yarı tutsak yarı tanrı yok oluşun', 'senden alıp gidiyor gözlerimi gölgesi bile sığmıyor yüzüme yorgunluğun alıp gidiyor dönmeyen atlıkarıncalar kırların düş artığı şölencileri ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gun-sonu-bir-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyle Başlar İnsan Yüzü', 'neyle-baslar-i-nsan-yuzu-kemal-ozer-c31s5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meraklıysan insan yüzünün tarihine

önce şunu sor ey yolcu: 

Neyle başlar insan yüzü, 

uçları güneş alevinde savrulan

saçıyla mı bir çocuğun, 

sarkık avurtlarıyla mı, 

kıvrılmaya hazır dudaklarıyla mı, 

gücenik bakışıyla mı yoksa? 

Bir de şunu sor: 

Gücendiren ne insan yüzünü?', 'Meraklıysan insan yüzünün tarihine önce şunu sor ey yolcu:  Neyle başlar insan yüzü,  uçları güneş alevinde savrulan saçıyla mı bir çocuğun,...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/neyle-baslar-insan-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kesik Kesik', 'kesik-kesik-kemal-ozer-kcxpz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sık sık kesiliyorsa başlattığımız konuşma, 

susuveriyorsak birden

bir sözcüğün yarısında, 

tükendiği için değil

konuşacağımız şeyler.

Araya giren bu sessizlik, 

söylememek için hiçbir şeyi

nereye varacağını bilmeden.

Çünkü bir tek sözcüğün değeri

satmaya da yetiyor bir insanı, kurtarmaya da; 

öyle uzun ve karanlık bir sorgudayız ki

atmışlar yaşamın bütün köprülerini

girmişler dünya ile aramıza, 

ve gün ışığı görmemiz yeniden

ya direnirsek mümkün, ya konuşursak!', 'Sık sık kesiliyorsa başlattığımız konuşma,  susuveriyorsak birden bir sözcüğün yarısında,  tükendiği için değil konuşacağımız şeyler. Araya ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kesik-kesik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadırga', 'kadirga-kemal-ozer-tbwxh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'karanlığı bıraktım benim değil bu rüzgar

artık yol almıyorum şafağında suların

kıyısı kıyım değil dışındayım zamanın

çözdü yelkenlerimi iplerinden yıldızlar

şimdi bir gökyüzüdür o bizans çarşıları

saraylarla avlarla kölelerle yan yana

köleler ki uzanmış her biri bir şafağa

her biri bir ağıtın vazgeçilmez uğrağı

o kırallar o gülen miraslı geniş yüzler

kutsal diye tapınak kurdukları o saygı

çürümüş gövdem bile onları anıp titrer

çoğalır bana varan beni aşan bu anı

çoğalır beni saran bir deniz evreninden

ölüme baş eğmeyen ölülerin rüzgarı', 'karanlığı bıraktım benim değil bu rüzgar artık yol almıyorum şafağında suların kıyısı kıyım değil dışındayım zamanın çözdü yelkenlerimi iple...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kadirga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimşek Pandandifi', 'simsek-pandandifi-gulseli-i-nal-1tkzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kadar sıcaktı ki bahçe

Yosunlar sararmıştı yıldızlara denk

Sıcağın diplerinde kanarya ölüleri

Neredeyse toprak rengi yüzler

Kuytuda saklı kalmış yeşille

Viyolet iniydi

Sanki gizli bir aşk

Asırlarca sürer bu sıcak eritir ellerimizi

Böyle alevli parmaklarımız durmadan

Birbirini yokladıkça

Öyle sıcaktı ki bahçe

Sen kuzgun alev alev

Yüzü gözükmeyen kirke

Mor dilini uzatınca havaya

Akrep mayası en dipte

Bütün bu çılgınlık yükselen ısı

Tüm bedenlerin bileşimi

Kanla buluşan alev yeryüzünde

Birazdan yıkımın algoritmasını başlatacak da

Biliyordum böyle olacağını

Ve

Buna benim tanıklık yapacağımı

Sıcağın kalkanını deldim

Deşildi yara yeryüzüne

Ne varsa

Sarı yosun antik taş ve yengeç başları

Magmanın konuşması başladı sonra

Sıcağı yöneten kirke

Hükmetti okyanusa ezdi kum diplerini

Ölü deniz panteri anemon ve su tutkalıyla

Tutundu kaldı yüz

Doğuran sıcağın içinde

Gözler meftun

Dudaklar aralık

Nefesinde saklı kalmış birkaç serin damla

Ne de olsa avutucuydu

Tapılası yüzün

Akşamüstüne doğru sakinleşen otlukta', 'O kadar sıcaktı ki bahçe Yosunlar sararmıştı yıldızlara denk Sıcağın diplerinde kanarya ölüleri Neredeyse toprak rengi yüzler Kuytuda saklı ...', ARRAY['Türk Edebiyatı','Şiir','Gülseli İnal']::text[], 8.5, '{"poet":"Gülseli İnal","poet_slug":"gulseli-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/simsek-pandandifi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Size Değil', 'size-degil-nazan-gunturkun-ogz6u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutkum sana değil, güneşin sıcaklığı, 

İçim ılıdıysa birden

Karanlığım güne döndüyse, 

Müjdeler geliyorsa çok ötelerden: 

	Sımsıcak bir düştür nedeni.

Tutkum sana değil

Suyun serinliği.

Bunca yalnızlığım eridiyse, 

Duygularım

Pınar pınarsa şimdi: 

	Sımsıcak bir düştür nedeni.

Sana değil tutkum, dağların yüceliği

Bin kez göklere erdiysem, 

Yankıladıysa yüreğim

En büyük içtenliği: 

	Sımsıcak bir düştür nedeni.

Tutkum hele sana, sana hiç değil

Mevsimlerin en güzeli.

İlk kez seviyorsam baharı, 

Ve diliyorsam

Uzun yaz gecelerini: 

	Sımsıcak bir düştür nedeni.', 'Tutkum sana değil, güneşin sıcaklığı,  İçim ılıdıysa birden Karanlığım güne döndüyse,  Müjdeler geliyorsa çok ötelerden:  	Sımsıcak bir düşt...', ARRAY['Türk Edebiyatı','Şiir','Nazan Güntürkün']::text[], 8.5, '{"poet":"Nazan Güntürkün","poet_slug":"nazan-gunturkun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/size-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Bulut', 'mavi-bulut-teoman-sarikahya-aacx5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykumu kaybettim

Sizin evden

İki sokak aşağıda

Ya bir karanfil kokacak biliyorum

Ya bir iğde

Girsem bahçenize...

Bütün gün

Bütün gece

Sokaklarda dolaşıyorum

Bir parça sevmek için...

Gel bir gül tak yakama

Ve bizi götürsün uzaklara

Bir mavi bulut...', 'Uykumu kaybettim Sizin evden İki sokak aşağıda Ya bir karanfil kokacak biliyorum Ya bir iğde Girsem bahçenize... Bütün gün Bütün gece Sokakl...', ARRAY['Türk Edebiyatı','Şiir','Teoman Sarıkahya']::text[], 8.5, '{"poet":"Teoman Sarıkahya","poet_slug":"teoman-sarikahya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yosun', 'yosun-behcet-necatigil-ce5rp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İkidir bir köpük elim bir koymuş gibi.

Yerimi bilemiyor, diş biliyorlar

..........
..........', 'İkidir bir köpük elim bir koymuş gibi. Yerimi bilemiyor, diş biliyorlar .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yosun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı Gerçeği', 'yazi-gercegi-behcet-necatigil-rsdjf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarımdır tam kaç yan

Yazın - - ne demeye geldiği

Hüznün keyfini sür! 

Sizi tutuyorlar bırakırl
..........
..........', 'Yarımdır tam kaç yan Yazın - - ne demeye geldiği Hüznün keyfini sür!  Sizi tutuyorlar bırakırl .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yazi-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin İzdüşümünde Sen', 'gecenin-i-zdusumunde-sen-vedat-koparan-dk9mw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin İzdüşümünde Sen

Kanayan geceleri gündüzün aydınlığına 

Özlemleri o güzel gözlerinle birlikte

Günün uyanan  ilk ışıklarında suya bıraktım 

Genin izdüşümünde sen olursun 

Dün gece elektrikler kesildi kentte

Uykudamı idin diye aklımdan  geçirdim 

Baktım pencereden heryer kapkaranlık 

Gökyüzünde yıldızlar çümbüşü vardı

Küçük çam ağaçları yeni filizleniyordu

Dalları arasından süzdüm gözlerimi 

Maviliğin karanlıkları içinde gözlerine

Desene bir şahan kaçaklığımız 

Yine kelepçelerde

Hele geldiğini bir bileyim

Bir duyayım çağıran sesini

Yürek atımım verirmisin haberini

Bak nasıl alır kaçırırım ben seni..

    

Vedat.K 13.03.2002', 'Gecenin İzdüşümünde Sen Kanayan geceleri gündüzün aydınlığına  Özlemleri o güzel gözlerinle birlikte Günün uyanan  ilk ışıklarında suya bıra...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gecenin-izdusumunde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemrem', 'cemrem-vedat-koparan-pvo1v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cemrem

Cemre düşer 

Havaya suya toprağa

Cemre

Yüreğime düşer sensizliğimde

Özlenen beklenensin 

Düşersin  düşlerimle gecelerime

Sevgi bendim olursun benliğimde

Sen bir yanda ben bir yanda 

Uzakları yatırdık 

Bahara erecek mevsimlere

Aman cemrem

Havaya düştün suya düş toprağa düş 

Düşlerimden yüreğime

Yüreğimden gerçeğime dönüş..

Vedat.K  25-28.03.2002', 'Cemrem Cemre düşer  Havaya suya toprağa Cemre Yüreğime düşer sensizliğimde Özlenen beklenensin  Düşersin  düşlerimle gecelerime Sevgi bendim...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cemrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sönen Umudum', 'sonen-umudum-ugur-oguz-sahin-zsziz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sendin hayalim emelim ümidim

Hani ne oldun

Tam alışmışken sana gönlüm

Severken seni kayboldun

Demek ki sen beni 

Ruhunda yaşatmıyordun

Hadi söyle ne oldu

Ne oldu beni seviyordun

Sen bukalemun sen riyakâr

Söyle sen bu muydun

Sahte sevgi saçılırdı gözlerinden

Sakın deme benim için yanıyordun

Ben de bu saflığımla öyle sanıyordum

Adını yalnızca yıldızlara fısıldıyordum

Umudum geleceğim sendin diyordum

Gözlerimin ufkunda sendin

Beni yaşatıyordun

Hayaline bile sen diye sarılıyordum

Bir sıcaklık yakar geçerdi bağrımı

İçin için yanıp eriyordum

Unutmadım çalan bir telefondu hatırlıyorum

Buraya kadarmış bitti dedin bitti aşkım

İşte o an gerçek oldu içimdeki korkum

Oysa ben seni ne hayallerle yaşıyordum

Artık söndü senle olan son umudum', 'Sendin hayalim emelim ümidim Hani ne oldun Tam alışmışken sana gönlüm Severken seni kayboldun Demek ki sen beni  Ruhunda yaşatmıyordun Hadi ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sonen-umudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-ugur-oguz-sahin-w7357', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seveni sevselerdi

Hiç hüzün olur muydu

Her gün dert

Her gün ıstırap

Hani mutluluk

Yaşamak

Bu muydu', 'Seveni sevselerdi Hiç hüzün olur muydu Her gün dert Her gün ıstırap Hani mutluluk Yaşamak Bu muydu...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hani-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silseler', 'silseler-ugur-oguz-sahin-q69kg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güller ne kadar narin ne kadar güzel

Dikenleri ne kadar zalim ne kadar acı

Sevmek sevilmek ne kadar güzel

Silseler defterlerden yıkan şu ayrılıkları', 'Güller ne kadar narin ne kadar güzel Dikenleri ne kadar zalim ne kadar acı Sevmek sevilmek ne kadar güzel Silseler defterlerden yıkan şu ayr...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/silseler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olacaksın', 'olacaksin-ugur-oguz-sahin-4306x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bahçemde yetişen 

Sen yağmur dualarımla serinlenen

Sendin en uzun gecelerimde

Düşlerimi süsleyen

Yine sen olacaksın hayatımda

Sevmeye sevilmeye devam edilen', 'Sen bahçemde yetişen  Sen yağmur dualarımla serinlenen Sendin en uzun gecelerimde Düşlerimi süsleyen Yine sen olacaksın hayatımda Sevmeye se...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/olacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atıf-0-16-Delfin’e', 'atif-0-16-delfin-e-vedat-koparan-c6ect', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Delfin’e

Bahar çiçeği Delfin’im

Su gibi akar 

İnce ince kıvrım kıvrım yol olur

Süzülür gecenin içinden yıldız olur 

Yıldızlar ona bakar

O hiçbir şeye aldırmadan

Yaşam pınarı akışında

Yaşamın yılmazlığına

Direnmenin türküsü yüreğinde olur

Sessiz içten ağlamaklı 

Hüzündedir yüreğim

Huşu ile bakarım bir gelincik gibi

Almaya korkarım elime onu

Alınca döker yapraklarını diye..

Vedat.K 26/eylül/2002

Antalya''dan iletişim dostum

ilik kanseri olup öldüğü kızı tarafından  bildirilmesi üzerine 

saygı ile hep anacağım can güzel yürek', 'Delfin’e Bahar çiçeği Delfin’im Su gibi akar  İnce ince kıvrım kıvrım yol olur Süzülür gecenin içinden yıldız olur  Yıldızlar ona bakar O hi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/atif-0-16-delfin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Karşı Çıkar ki:', 'kim-karsi-cikar-ki-zubeyir-sasmaz-fkue1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim karşı çıkar ki, 

Memleket te ki yücelmeye, 

Sefaletle, cehaletle mücadeleye

Herkese insanca eşit muameleye

Ağaların,  egemenliğini bitirmeğe

Kim karşı çıkar ki, 

Ulusal geliri, adilce pay etmeğe

Ayrıcalıkları, kaldırıp, yok etmeğe

Sosyal adaleti gerçekleştirmeğe

Her türlü sömürüye son vermeğe

Kim karşı çıkar ki,  kim karşı çıkar ki.

Memleketi,  doruklara  yüceltmeye, 

Bir alışsak ben değil de, BİZ demeye

Görsünler  o zaman,  kalkınmayı, 

Kazançlarımızı üçe, beşe  katlamayı

İnsanım, aç mı kalacak, işsiz mi kalacak

Herkes, anasının, babasının, eşinin

çoluğunun, çocuğunun yanında kalacak

Yaban eller de,  çöpçülük mü yapacak

AVRUPAlarda sokakları  mı paklayacak

Birlik olursak, vatan için çalışırsak, 

AVRUPALI gelip onun ayaklarını  yalayacak.

Bir alışsak ben değil de, BİZ demeye

Görsünler  o zaman,  kalkınmayı, 

Kazançlarımızı üçe, beşe  katlamayı

Allah razı olsun, tüm öğretenlerimizden, 

Meslek verdiler, balık tutmayı öğrettiler.

Bundan sonra kendi başınızın çaresine 

Bakabilir, ayakta durabilirsiniz dediler.

Dilerdim, her derste beş dakika da

Vatan, insan sevgisi üzerine ders verseler

Sakın ayrılığa düşmeyin,  birlik olun deseler.

Tarihten örnekler verseler, bildiklerini deseler

Birlikte rahmet, ayrılıkta azap var deseler.

Ah, Gençliğin enerjisini bir derdest etseler

Yeri göğü inletseler…', 'Kim karşı çıkar ki,  Memleket te ki yücelmeye,  Sefaletle, cehaletle mücadeleye Herkese insanca eşit muameleye Ağaların,  egemenliğini bitir...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kim-karsi-cikar-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Son', 'mutlu-son-zubeyir-sasmaz-hbpny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unumu eledikten sonra, 

çekildiğimde    köşeme

sormamalıyım kendime, 

daha yapacak ne vardı diye.

elimden geleni        ardıma koyarsam

yapabileceklerim varken yapmazsam

Hadi gel de Anlat onu sen 

Arayış''a  ve  Atılım''a

Bilirim, 

Allah ganidir. Rahmeti gazabını aşar.

Belkide bizi affına mazhar kılar.

halkım farkına varmaz bile

isimsiz kimler geldi, geçti diye

Ya, 

çok sevdiğin, örnek olacağın çocukların

vatan için çalışacaklarını umdukların, 

Sorarlarsa sana; ''vatan için Ne yaptın '' 

hazır mı, yalansız kaçamaksız yanıtların

Belki de başarısız olurum.

Olsun, seve seve yorulurum

'' Neyi, niçin, neden, nasıl'' ı sordun  mu? ''

''Aradın mı? '' diyecek  olursa ARAYIŞ.

''Benden başka bir Atılım yaptın mı? ''ı derse ATILIM.

Onlara neyi, nasıl anlatacağım.

Onun için, yaşarken,  vatan için 

varsa yapacaklarım, ardıma koymayacağım.

canla başla çalışacağım.

insanlık için savaşacağım.

soranlarla rahat rahat konuşacağım.

başım dik, utanmadan  hesaplaşacağım.

gözlerimi kapatacak,  açık bırakmayacağım.

ondan sonra son, nefesimi salacağım

dünyadaki görevimi yapmış, müsterih olacağım.

İşte sonunda ben böyle olacağım.

dünyadaki görevimi yapmış, müsterih olacağım.', 'Unumu eledikten sonra,  çekildiğimde    köşeme sormamalıyım kendime,  daha yapacak ne vardı diye. elimden geleni        ardıma koyarsam yapa...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mutlu-son-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Değerli Varlıklarınız Kızlarınız', 'en-degerli-varliklariniz-kizlariniz-ugur-oguz-sahin-qib5v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anneler babalar ne olur sesimi duyun

Kızlarınızı sevin onları sermaye görmeyin

Üzerlerine titreyin

Onlar en kutsal varlıklarınız

Genç kızlıklarını yaşatın onlara

Bir tomurcuk gülken zorla koparıp ellere vermeyin

Umutlarını hayallerini

Geleceklerini zorla söndürmeyin

Teslim etmeyin onları satarak cahil beyinlere

Salmayın onları geri dönüşü olmayan derelere

Bırakın sevmeyi sevilmeyi öğrensinler

Siz yazmayın kaderlerini

Niye ölene dek cefa sürsünler

Yetişsinler görsünler sevsinler

Kendi rızalarıyla gitsinler

Törelerle baskılarla kurban edilmesinler

Ne yazık hâlâ işliyor böyle kültürler

Hâlâ bitmedi böyle beyinler

Satmayın çocuklarınızı süt kuzusuyken

Bırakın olgunluğa erişsinler

Seven seveni alıp isteyerek gitsinler

Evlilik dediğin sorumluluk

Çocuklar onu nasıl bilsinler

Zorla olmaz sevmek zorla olur mu evlendirmek

Nasıl bir anlayıştır

Onlara erişemeyecekleri mutluluğu dilemek

Yıktığınız onurları hayalleri

Siz değil onlar bir ömür boyu çekecek

Yıkılanlar her gün cehennemi yaşıyor

Anneler babalar seyrediyor

Göz yaşları yağmur olup seller taşırıyor

Hayaller tek tek siliniyor

Böyle analar babalar onlara hangi yüzle

Hangi vicdanla yavrum diyor

Neden hep insanlarda 

Hep vücutlarda ararız arızaları

Neden görmezden geliriz

Özürlü beyinleri hasta insanları

Eskiden devir öyleymiş yaşanmış

Ne iz bırakmış mutlulukları

Bugün duvarlar yıkılmış çağlar atlanmış

Eller mesken etmiş gök yüzünü

Çözmüş ay''ı yıldızları

Hâlâ görüp duymak ne çirkin

Satanları satılanları

Ne olur anneler babalar

Satmayın kızlarınızı körpe kuzularınızı

Soldurmayın hayat çiçeklerini

Döktürmeyin kahır göz yaşları

Yarın mahşer de

Yaradan önünüze koyacak hep

Bu yanlış hesapları', 'Anneler babalar ne olur sesimi duyun Kızlarınızı sevin onları sermaye görmeyin Üzerlerine titreyin Onlar en kutsal varlıklarınız Genç kızlık...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/en-degerli-varliklariniz-kizlariniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Olman', 'mutlu-olman-ugur-oguz-sahin-zobdy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlün bir bahçesi vardır

Seversen yeşerir çiçek açar

Sevmezsen boynunu büker

Hemen solar

Sevgi dediğin kalpten kalbe dolar

Aşık olmak çok güzeldir ama

Sevgiye değer veren bundan anlar

Yaşamak sevmek demek değildir

Bazen sevmeden de yaşar insan

Değerini bileceksin güzelliklerin

O zaman güç değildir mutlu olman', 'Gönlün bir bahçesi vardır Seversen yeşerir çiçek açar Sevmezsen boynunu büker Hemen solar Sevgi dediğin kalpten kalbe dolar Aşık olmak çok g...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mutlu-olman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp Çarpıntısı', 'kalp-carpintisi-ahmet-ozdemir-s0a1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce bin nazla kopuşunu göreceksin

Bale yumuşaklığı ile uçuşunu, 

Düşüşünü duyacaksın gönül teline; 

Bir kaç solgun yaprağın...

Bu yorgun hışırtı, bu sürekli titreyiş, 

Dökecek sonunda hepsini biliyorum.

Sarının tonları kahverengiye çalacak

Alacak rengine toprağın.

Ah şu çarpıntısı olmasaydı kalbimin...

Çalı süpürge, paslı faraşla tanışacak

Yaslı parkın bir köşesende yanacak için için, 

Dumanı çıplak dalları, külü toprağı, 

Könpe yeşillere gebe bırakacak...

Hışır hışır, hışır hışır geceler boyu uykusuz.

Domur domur soğuk terler yok mu? 

Yok mu kulaklarımda çınlayan tansiyon? 

Her ilkin bir sonu olacaktır kuşkusuz, 

Her sonun bir ilki var...

Ey hoyrat rüzgar! 

Sondan önce bu kaçıncı istasyon

Ey şakaklarıma düşen kar, 

Gönlüme çöken sonbahar! 

Ah şu çarpıntısı olmasaydı kalbimin...

Hüznün bestelenmemiş en tatlı şarkısı

Ey pastırma yazında durasıca zaman

Güneşin donmalıydı bu son pırıltısı.

Yalnız kasımpatılar kaldı biliyorum, 

Ebedi yolculuğun uğurlayıcısı.

Ah şu çarpıntısı olmasaydı kalbimin.', 'Önce bin nazla kopuşunu göreceksin Bale yumuşaklığı ile uçuşunu,  Düşüşünü duyacaksın gönül teline;  Bir kaç solgun yaprağın... Bu yorgun hı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kalp-carpintisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuğu Güzelim', 'kugu-guzelim-ugur-oguz-sahin-4p4t1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülhane''deydim bugün

Sensiz o koskoca günü orada geçirdim

Kuğuları izledim

Kimilerini sevdim kimilerine yiyecek verdim

Onları sevip okşarken senin hasretini giderdim

Biri vardı ki onu seyrederken

Sen geliyorsun zannettim

Göz kapaklarındaki siyah çizgileri

Sürmelerine benzettim

Kuğu gözlerinde seyrettim hayalini

Kendimden geçtim

Sensin kalbimde dünyanın en güzeli

Sensin güzelim

Seni hatırlatan kuğuları

Seni sevdikten sonra bu denli fark ettim

O ne endam o ölesi zarafet

Bir de yok mu sudaki süzülüşleri

Senin gelişine bakar gibi

Vurgun gözlerle daldım seyrettim

Gelinliğin sandım beyaz tüyleri

Açtım kollarımı süzülen kuğunun görüntüsünde

Senin gelişini hayal ettim

Sana benziyordu ciddiyeti sükûneti

O ne güzelliktir tanrım

Başka nerde görürsün o masumiyeti

Başı dik ve nazlı duruşundaki asaletle

Mat eden güzelliği

Bugün kuğuları keşfettim kuğularda yaşadım seni

Kuğular bugün yalnızlığımı bir kenara itti

Seni yaşattılar bana sensizliğimde

Yanımda sen varmış gibi', 'Gülhane''deydim bugün Sensiz o koskoca günü orada geçirdim Kuğuları izledim Kimilerini sevdim kimilerine yiyecek verdim Onları sevip okşarken...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kugu-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayten’in Düşlerinde', 'ayten-in-duslerinde-vedat-koparan-9uwh3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşlerimiz tutsak alınmaya çalışılırken

Bir aykırı yolcudan bir aykırı yolcuya

Raslantısal gelişti o an

Belki de yasak bir kavşaktı 

Kesişti yollarımız 

Güzelliğini gördüm düşün gücünde

Yüreğini almıştın ellerine 

Yüreğini aldım kattım yüreğime

Yarım aklımın yitik kıyısına 

Nasılda geldin demirledin

Titreşimler kıvılcım olur

Dönerim güneşim sana 

Görmedim demeden

Görürüm güzellikleri sende

   

Aykırı birer yolcuyduk kesişen o kavşakta

İçten sevgilerle bölüştük sözümüzü şarkımızı

Hiç kırılmadan taşıdık onca zamanı

Nasıl akıp geçti farkınada varmadık 

Gün dönerken akşama

Her ayrılığımız isyandır

İçsel yolculuğumda 

Sanki yılların yoksun vurgunlarında 

Bir sevda masalı idi yaşanan

Dostluğun arkadaşlığın 

Yok edilmekte olduğu 

Bu zor zamanların isyanlarında

Varsıllar çıkarırım yoksullardan

Güneş vurdukça maviliği altan alta 

Kızılırmak kızıl kan akarken 

Gece üşüyor gece 

Ama ben üşümüyorum 

Çünkü sen varsın bende

Her gece açarım pencerimi 

Bakarım gözyüzüne

Ayten, Ayten

Hilal düşen güzel yüzüne

Düşmesin demiştik

Görmemiş olsakta

O güzel gözlere ''kirpiklerden başka gölge''

Gelecek Aytenin güzel düşlerinde..

  

     Vedat.K 17.3.2002..', 'Düşlerimiz tutsak alınmaya çalışılırken Bir aykırı yolcudan bir aykırı yolcuya Raslantısal gelişti o an Belki de yasak bir kavşaktı  Kesişti...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ayten-in-duslerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarımız', 'ruyalarimiz-ugur-oguz-sahin-7ev7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir rüyadır yaşadıklarımız

Bazen uykudan bazen hayattan bir şeyler anlatırız

Çoğu zaman unuturuz anlatamayız düşünür takılırız

Yaşarken ömürleri isteriz hep güzeli

Her şeye yakınırız

Bir de bakarız uçmuş gitmiş seneler

Farkında olamayız

Etkisinde bırakır bizi yaşadıklarımız

Kendimizle hesaplaşırız

Ne fark eder gözleri kapalı gördüklerimiz

Ya da hayat rüyasında yaşadıklarımız

Hepsi rüya değil mi anlattıklarımız

Nİhayet bir gün gelir

Başlar bedende yorgunluklarımız

Hüzünlü bir keman sesinin

Son titreşimine benzer vücutlarımız

O bezginlikle farklı ayrı köşelerde 

Çöker kalırız

Yıllara meydan okumak gelir içimizden

Belki de son kez baş kaldırırız

Kabul etmez ruhumuz hiç yaşlandığını

Başımıza hiç olmadık işler açarız

Son kez şamarını yeriz hayat tokatının

Yine uyanırız

Ne kadar acı ne kadar tatlı da olsa rüyalarımız

Hep acılarında kıvranır

Hülyalarında mutluluk yaşarız

Yine de ne kadar yaşarsak yaşayalım

Nihayet bir gün ebedi uykularda

Son bulur rüyalarımız', 'Bir rüyadır yaşadıklarımız Bazen uykudan bazen hayattan bir şeyler anlatırız Çoğu zaman unuturuz anlatamayız düşünür takılırız Yaşarken ömür...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ruyalarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Dediler', 'unut-dediler-ugur-oguz-sahin-grkkx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unut dediler o vefasızı

Seni mahkum etti

Dertlere kederlere

Salıpta gitti

Değer mi dediler

Sevme unut o''nu

O şimdi yuvasında mutlu

Seni çoktan unuttu

Aklını başına al dediler

Seninkisi ümitsiz bir bekleyiş

Kalbinden sök at dediler

Herkes bir şeyler söyledi

Ama çok zor olacak galiba

Seni kalbimden söküp atmak

Öyle yer etmişsin ki

Ruhumda yüreğimde

Öyle derin ki kalbimde yerin

Gündüzüm gecem 

Seninle dolu

Hasretin yakıyor yıkıyor beni

Ne derlerse desinler

Öyle kolay değil

Hayatımdan silip atmak seni', 'Unut dediler o vefasızı Seni mahkum etti Dertlere kederlere Salıpta gitti Değer mi dediler Sevme unut o''nu O şimdi yuvasında mutlu Seni çokt...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/unut-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Oyunu', 'hayat-oyunu-recep-kucukece-ckipt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat dediğin bir oyun

Bizde bu hayatın oyuncuları

Ne kadar sevsek de, sevmesek de bu oyunu

Gelip girmişiz oyuna bir kere

Tek çıkış yolu mutlak son

Hem bu oyunda

Hem mutlak sonda

Mutlu olmayı seninle istedim

Ama gel gör ki

Hayat oyununu birkez daha oynadı

Seninle benim, hem bu dünyada

Hem de ahirette birlikte olma umudumu

Alıp gitti benden, senin gidişinle birlikte.', 'Hayat dediğin bir oyun Bizde bu hayatın oyuncuları Ne kadar sevsek de, sevmesek de bu oyunu Gelip girmişiz oyuna bir kere Tek çıkış yolu mut...', ARRAY['Türk Edebiyatı','Şiir','Recep Küçükece']::text[], 8.5, '{"poet":"Recep Küçükece","poet_slug":"recep-kucukece","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-oyunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gibi', 'olum-gibi-ugur-oguz-sahin-j6wbf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yoksun

Zaten olmaya çalışmadın ki

Sadece üzmeyen mutlu olduğum

O vefalı hayalin vardı

Bıktırdı riyakârlığın bıktırdı ihanetlerin

Eskiden mutluluk yaşatırdın

Şimdi ise hüzün ve ıstırap verdiğin

Bir zamanlar bestelere güfteydi sözlerin

Bal akası gözlerin vardı senin

Ama hiç anlaşılmadı anlatamadın

Belli olmadı sevdiğin sevmediğin

Senin için yanıp tutuşan bir deliydi yüreğim

Bendim o kasıp kavrulan

Temmuz sıcaklarında göremediğin

Sen hep Sonbaharları sevdin yağmurları sevdin

Bir beni sevmeyi beceremedin

Girmedi lügatine gerçek diye bir kelime

Hep hayalinle yetindirdin

Sanki hep uzaklaştın benden

Uzak kaldın bana yakını oldun ellerin

Gönlümdeki sen gittin

Sadece geride kalan avunduğum hayalin

Şimdi bir başka sevgiyle

Gözlerimde taşıyorum seni

Çok ağır ödeniyor

Silinmez izler bırakıyor sevgi bedeli

Tarifsiz sıkıntılar yaşadım seninle

Tarifsiz bir korkuydun bende

Sanırdım devasın sen

Hani olacaktın her derde çare

Anladım çıkış yok bu yolun sonunda

Kalınca bir başına bi çare

Ama hiç pişman olmadım

Bugüne dek yaşadıklarımdan

Utanmadım hiç anılardan

Geçmişten hatıralardan

Hep gerçek verdim gerçek sevdim

Uzak durdum yalanlardan

Gülmedi bir türlü yüzüm

Beni satan karşılıklardan

Şayet bir pişmanlık varsa ortada

Yaşadıklarımızdan

Sen payına düşenin hesabını yap

Sakın bana pay çıkarma geriye kalandan

Zamanı şahit tutma geçmişe bir şey sorma

Ne sen değiştin ne de vicdan hesabı yaptı

Yüreğin olanlardan

Zaten bir değeri yoktu sende

Gerçek sevginin gerçek sevmelerin

Şunu bil ki karşılıksız kalmaz hiç bir şey

Bir gün hesap soracak sana

Rüzgârlar kopacak o fırtınalar

Bu hep böyle sürer zannetme

Unutma

Her şeyde ölüm gibi bir son var', 'Sen yoksun Zaten olmaya çalışmadın ki Sadece üzmeyen mutlu olduğum O vefalı hayalin vardı Bıktırdı riyakârlığın bıktırdı ihanetlerin Eskiden...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/olum-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarımdaki Sen', 'gozyaslarimdaki-sen-emel-cengiz-e76j5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalgalar öpüyordu kayaları, tek tek..

Tutkulu ve uzun soluklu..

İzlerken dalgaları..

Dalıp gittim, deli mavinin sonsuzluklarında.

Ufkun ötesindeydin oysa şimdi..

Özlemindi yüreğimde büyüyen.

Böylesine duru bir güzellikti, ufukta seyrettiğim..

Yokluğunda, sessiz sessiz eridiğim.

Gözpınarımda biriken her damla yaştın..

Yakalanamamış zamanlarca uzaktın..

Hırçındı dalgalar, kahırlarca çoğalırcasına..

Sevdayı yüreklerden dudaklara taşırcasına..

Sanki sensizliğe kahrımı anlamışcasına

Tutkulu zamanlara takılı kalışlarımdı, anımsadığım.

Sendin, sensizliğimde yaşadığım..

Sevi seliydin benliğimde taşıdığım..

Gün günden yokluğuna alıştığım.

.

Evet! 

Sendin, gönlümdeki arayışım..

Sevgiye susamışlığım..

Tükenmeyecekti beni benden almışlığın..

Bir anda yıldızlara takıldı gözlerim

Tek tek yüzünü resmettiğim.

Yüzlerceydi, binlerceydi..

Sanki gökyüzü o anda, özleminle gönlümdeydi..

Nazlanıyordu ay..

Kararsızdı tıpkı ben gibi.

Bilseydi doğmasını nasıl sabırsızlıkla beklediğimi.

Belli belirsizdi rüzgarın getirdiği nağmeler..

Ruhumdaki isyanı, yeterince ifade edemediler..

Sen düştün de aklıma sevdalı akşamlarda..

Özlem yağmurlarıyla sırılsıklamdım Boğaz''da.

Ne ay, 

Ne deniz, 

Ne de kayalar..

Engel olamadılar; 

Yudum yudum dudaklarıma seni taşımama..

Çıkmaz sokaklarda aramama..

Yalnızlığın kollarında med-cezirler yaşamama.

Ve efkarlı günbatımlarında İstanbul''da..

Boynu bükük, sersefil, biçare dolaşmama.

İşte böylesine sensizken..

Geçmek bilmez zamanları devirmeye çalışırken..

Asla bir başkasını sevemeyeceğimi bilirken..

Rüzgârlarım hep sana doğru eserken..

Gözlerim yollarda; 

Dalıp dalıp, senli düşlere sürüklenirken..

Doyumsuzca seni bende yaşarken..

Gecem gündüzüm karmakarışıkken..

Çağ çağ sevda yaşamak varken..

Tenim, teninin kokusunu isterken..

Uzakları sever oldum.

Direndim.

Bastırmaya çalıştım bendeki seni.

İstemiyordum zamansız akşamları.

Oysa, karşımdaydı mutluluğun anahtarı.

Dalgalar öperken kayaları tutkulu..

Bilemediler..

Gözpınarlarımda biriken damlaların; 

Her birinin sen olduğunu..', 'Dalgalar öpüyordu kayaları, tek tek.. Tutkulu ve uzun soluklu.. İzlerken dalgaları.. Dalıp gittim, deli mavinin sonsuzluklarında. Ufkun ötes...', ARRAY['Türk Edebiyatı','Şiir','Emel Cengiz']::text[], 8.5, '{"poet":"Emel Cengiz","poet_slug":"emel-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/gozyaslarimdaki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-recep-kucukece-v5o6t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğuna alıştım senin

Senin yanımda olmamana alıştım

Ama hala alıştıramadım kendime

Artık senin gittiğini

Artık benim olmadığını

Alıştıramadım gönlüme

Her ne kadar 

Hayat sensizde devam etsede

Biryerlerde birşeyler eksik

Sebebinide biliyorum

Senin tekrar gelişinle 

Tamamlanacak herşey

Bunu biliyorum

Ama bana dönmeyeceksin

Biliyorum

Senin için çok geç artık

Beni düşünmezsin ama

Arada aklına gelirsem

Bilki, yokluğunla yaşamaya çalışan

Sensiz hayattan 

Zevk almadan yaşayan

Garip bir adam oldum ben

Evet biliyorum

Elbet birgün seni unutacağım

Tıpkı, senin beni unuttuğun gibi

Tıpkı, bensiz yaşayabildiğin gibi

Tıpkı, başka birini sevebildiğin gibi

Bende seni unutup

Başka birini seveceğim

Bunu biliyorum', 'Yokluğuna alıştım senin Senin yanımda olmamana alıştım Ama hala alıştıramadım kendime Artık senin gittiğini Artık benim olmadığını Alıştıram...', ARRAY['Türk Edebiyatı','Şiir','Recep Küçükece']::text[], 8.5, '{"poet":"Recep Küçükece","poet_slug":"recep-kucukece","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biliyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Diyecekler Sana Da', 'bir-gun-diyecekler-sana-da-ugur-oguz-sahin-887gv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül bu sever sevilir

Üzülmek dertler ise bizi kemirir

Lalelere bakış bir aşk''tır yürek titretir

Tanrı her zaman gerçekten seven kalplerdedir

En güzel duygular mutluluklarda perçinlenir

Sabret

Sabrın sonu selamettir

Nihayet bir gün sana da

Biri sevgilim diyecektir', 'Gönül bu sever sevilir Üzülmek dertler ise bizi kemirir Lalelere bakış bir aşk''tır yürek titretir Tanrı her zaman gerçekten seven kalplerded...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-gun-diyecekler-sana-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayırırlar', 'ayirirlar-ugur-oguz-sahin-w1qjn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gönlümün tahtının sahibisin

Söyleme kimseye göze gelirsin

Ayırırlar sonra bizi

Sen kalbimde açan çiçeğimsin

Duyarlarsa koparırlar

Göze getirirler sevgimizi

Farkında olamadan 

Sonra ayırırlar ikimizi', 'Sen gönlümün tahtının sahibisin Söyleme kimseye göze gelirsin Ayırırlar sonra bizi Sen kalbimde açan çiçeğimsin Duyarlarsa koparırlar Göze g...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayirirlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susma', 'susma-ugur-oguz-sahin-ztneq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günler sensiz geçmiyor

Rüzgârlarla geçip gittin

Ne çabuk unutuldu sevgimiz

Fırtınalar dindi mi yüreğinde

Hadi söyle neden susuyorsun', 'Günler sensiz geçmiyor Rüzgârlarla geçip gittin Ne çabuk unutuldu sevgimiz Fırtınalar dindi mi yüreğinde Hadi söyle neden susuyorsun...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/susma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürçmeler', 'surcmeler-sadik-altinkaynak-tl4wp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevmiyorum demem yalandı

Sevdiğimi söylerken dilim sürçtü

Sana elim isteyerek kalkmadı

Okşamak isterken elim sürçtü

Başka bir yar sarmadı aşkın kolları

Buna şahit Mevla’nın tüm kulları

Yalnız sana çıkar sevda yolları

Bir kez sapmışsam inan yolum sürçtü

Ağaç olsam meyve sensin dalımda

Arı olsam çiçek sensin balımda

Kahve olsam çıkan sensin falımda

Farklı çıkarsa bil ki falım sürçtü

Seninle hemhalim her bir anımda

Başka sevdiğim de yok sevdalım da

Görürsen bir başkasını kolumda

İnanma sakın say ki kolum sürçtü

Kul hatasız olmaz bildim hatamı

Eline ne geçer tutsan yakamı

Sen hoş görüp affedersen cezamı

Mevlam affedip der ki “Kulum sürçtü”

Eylül 2002', 'Seni sevmiyorum demem yalandı Sevdiğimi söylerken dilim sürçtü Sana elim isteyerek kalkmadı Okşamak isterken elim sürçtü Başka bir yar sarma...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/surcmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Kimdi', 'giden-kimdi-ugur-oguz-sahin-xod83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O giden sen değildin

Sen değildin terk eden

Umutlarım yaşamım

Ruhumdun sönen

Verdiğin cezaysa eğer

Bedenim hâlâ ayakta

Sen değilsin nankör sevgin

Ruhumda nihayete eren', 'O giden sen değildin Sen değildin terk eden Umutlarım yaşamım Ruhumdun sönen Verdiğin cezaysa eğer Bedenim hâlâ ayakta Sen değilsin nankör s...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/giden-kimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkınla Benimlesin', 'askinla-benimlesin-sevki-dincal-lp5wz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitti artık gönlümde hasretin saltanatı

Olsan da olmasan da aşkınla benimlesin

Vazgeçtim yokluğunu özlemle sınamayı

Gelsen de gelmesen de aşkınla benimlesin

Bir elveda demeden aldın gittin başını

Gelmiyorum peşinden çatma artık kaşını

Senin için dökülen gözlerimin yaşını

Silsen de silmesen de aşkınla benimlesin

Kahırlar teslim olsa yaşama hevesimi

Yüreğin duymaz olsa feryadımı sesimi

Adınla vereceğim aşka son nefesimi

Bilsen de bilmesen de aşkınla benimlesin

Yaşadığım ne varsa bu sevdanın eseri

Ne kadar acı verse yine kalbimdir yeri

Bir gün beni gönlünün kapısından içeri

Alsan da almasan da aşkınla benimlesin

Bedenimde ruhumda sen varsın her anımda

Nasıl sensizim derim dolaşırken kanımda

Aldırmam ey sevgili ömür boyu yanımda

Kalsan da kalmasan da aşkınla benimlesin

Artık sana sitem yok işte sabrımla sına

Alıştırdım kendimi bu sevdanın yasına

Bir kere bile olsa aşkımın deryasına 

Dalsan da dalmasan da aşkınla benimlesin', 'Bitti artık gönlümde hasretin saltanatı Olsan da olmasan da aşkınla benimlesin Vazgeçtim yokluğunu özlemle sınamayı Gelsen de gelmesen de aş...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askinla-benimlesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Gözüm Üstüne', 'basim-gozum-ustune-sevki-dincal-b98gk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden başka yar bilmem ömür boyu gözüme

Bak de yeter bakarım başım gözüm üstüne

İster aşk denizine ister hicran gölüne

Ak de yeter akarım başım gözüm üstüne

Yılda bir olsa bile seviyorum de hele

Senden gelmişse eğer sefadır bana çile

Yalnız kalbimi değil koca dünyayı bile

Yak de yeter yakarım başım gözüm üstüne

Yeter ki sen bekle de hiç kalır sabır taşı

Küçük bir umut bile olur gönül yoldaşı

Razıyım ömür boyu gece gündüz gözyaşı

Dök de yeter dökerim başım gözüm üstüne

Biliyorum bu aşkın yalnız sensin galibi

Her derdine razıyım çıkmasın tek talibi

Varsın yağmur yağmasın sen iste şimşek gibi

Çak de yeter çakarım başım gözüm üstüne

Tek söz etmem bu sevda vursa beni her yandan 

Tanrım beni korusun benden bıktığın andan

Ne kadar sevsem bile bir gün olur dünyandan 

Çık de yeter çıkarım başım gözüm üstüne

Biliyorum sevgili gönlünde yerim gurbet

İster sılaya çağır ister hergün sürgün et

Sen mutlu ol bir tanem ben ömür boyu hasret

Çek de yeter çekerim başım gözüm üstüne

Seni bu kadar sevmek yalnız benim günahım

Hiç şikayet ettim mi bir gün çıktı mı ahım

Bir elimde yüreğim bir elimde silahım

Sık de yeter sıkarım başım gözüm üstüne', 'Senden başka yar bilmem ömür boyu gözüme Bak de yeter bakarım başım gözüm üstüne İster aşk denizine ister hicran gölüne Ak de yeter akarım b...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/basim-gozum-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-sevki-dincal-ejl82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir kalpsize aşık oldum ki

Bana sevgi ile bakışı yalan

Arkamı dönünce her şey bitiyor

Bakışından hüzün döküşü yalan

Bile bile acı verir dert verir

Bir yudum sevgiyi bana çok görür

Üzer pişmanım der haber gönderir

Masumca boynunu büküşü yalan

Neler çektim neler onun elinden

Sorarsanız adım düşmez dilinden

Boğulsam da gözyaşının selinden

Gözünden yaşların akışı yalan

Ne zaman aşkını getirse dile

Mutlaka altında vardır bir hile

Gecemi gündüze çevirse bile

Şimşek bile olsa çakışı yalan

Canım derken bile sitemli baktı

Sevdim dedi beni yürekten yaktı

Gitti aşkımızı öksüz bıraktı

Hasreti özlemi çekişi yalan

Mevsimi gelmeden aşkımız bitti

Elveda demeden bıraktı gitti

Seviyorum diye diye terketti

Sevdasına türkü yakışı yalan', 'Öyle bir kalpsize aşık oldum ki Bana sevgi ile bakışı yalan Arkamı dönünce her şey bitiyor Bakışından hüzün döküşü yalan Bile bile acı verir...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalan-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Veda', 'son-veda-sevki-dincal-pwh9x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir veda busesi verdi giderken

Geçmiş günler hatırına say dedi

Bilirim ararsın özlersin beni

Al resmimi baş ucuna koy dedi

Hasretten içinde azarsa yara 

Eski mektuplarda teselli ara

Bir şarkımız vardı çal ara sıra

Dinle dinle anılara doy dedi

Gitme dedim belki seni bulamam

Olmaz dedi ben sana yar olamam

İstesem de bir gönülde kalamam

Bu bende ki vaz geçilmez huy dedi

Sormayın bir ateş düştü özüme

Aldırmadı güldü geçti sözüme

Manalı gözlerle baktı yüzüme

Unut beni bu sevdadan cay dedi

Bir gün uzaklardan haberi geldi

Dediler sevdiğin sokakta öldü

Bir daha gönlümü ikiye böldü

Gözyaşlarım “vay sevdiğim vay” dedi', 'Bir veda busesi verdi giderken Geçmiş günler hatırına say dedi Bilirim ararsın özlersin beni Al resmimi baş ucuna koy dedi Hasretten içinde ...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-veda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Tükendi', 'yollar-tukendi-sevki-dincal-12w7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anladım bu aşkın sonuna geldik

EI ele gidecek yollar tükendi 

Kalemim kırıldı kağıtlar öksüz 

Mektup taşıyacak pullar tükendi

Bahane ararken göz kederine 

Hasretin zalimce işler derine

Ben kimi koyarım senin yerine 

Sevmeye zaman yok yıllar tükendi

Demek ki yalanmış ettiğin sözler 

Kimi sevmiş kime bakmış o gözler 

Söndü içimdeki yangınlar közler 

Rüzgar aldı gitti küller tükendi

Ne benim ne aşkım hayırsız çıkan 

Sendin bu sevdaya uzaktan bakan

Kuruyan ırmağım gönlüme akan

Yağmurlar tükendi seller tükendi

Bir bıçak sapladın işte şurama 

Hiç bir ilaç fayda etmez yarama 

Gönül bahçesinde artık arama 

Çiçekler tükendi güller tükendi', 'Anladım bu aşkın sonuna geldik EI ele gidecek yollar tükendi  Kalemim kırıldı kağıtlar öksüz  Mektup taşıyacak pullar tükendi Bahane ararken...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yollar-tukendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Sevdalı Kadın', 'aska-sevdali-kadin-sevki-dincal-lhywr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni ilk gördüğümde olamaz bu demiştim

Hasretinin resmini yüzüne çizen kadın 

Acısını bastırıp yüreğinin üstüne

Sevdası ellerinde gurbette gezen kadın

Farkı var mı içinde gece ile gündüzün 

Yaralı bakışından eksilmez mi hiç hüzün 

Gördüğüm günden beri bir an gülmedi yüzün 

Gözleriyle maziye sitemler yazan kadın

Gönül sayfalarına bir aşk mührünü vurmuş 

Yaşadığın bu sevda belli seni çok yormuş 

Zaman aşk bittiğinde bakışlarında durmuş 

Yolları nemli gözle özlemle süzen kadın

Tomurcukken açmayan güllere döneceksin 

Bu gönül oyununu ne zaman yeneceksin 

Bir mum sessizliğinde yanıp tükeneceksin 

Yıllarca özlemini gönlünde ezen kadın

Adressiz mektuplarda ağlayan pul gibisin 

Yaprağından ayrılmış kurumuş dal gibisin 

Dalgalara direnen çaresiz sal gibisin

Hicran denizlerinde sahipsiz yüzen kadın

Kor ateş mi mutluluk uzanıp tutamadın 

Bu kadar çok mu sevdin kalbinden atamadın 

O seni hiç anmazken neden unutamadın 

Böyle bir vefasıza kendini üzen kadın', 'Seni ilk gördüğümde olamaz bu demiştim Hasretinin resmini yüzüne çizen kadın  Acısını bastırıp yüreğinin üstüne Sevdası ellerinde gurbette g...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aska-sevdali-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-sevki-dincal-ilvaz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen umut tazelerken ben hep seni bekledim 

Sen bir yaz sabahıydın ben gecenin yarısı 

Ne sen geceme geldin ne ben erdim sabaha 

Güzel hayaller bile şimdi hazan sarısı

O sonsuzluk içinde kaybolur giderdim ben

Bir kere bile içsem alevli nefesini 

Dudağının tadıydı en değerli ödülüm 

Öpsem dünya duyardı yüreğimin sesini

Bir arzu deryasının girdabına düşerdim 

Ürperen bedenini düşünmek de yeterdi 

Sanki o an içimde seni sensiz yaşardım

Sonra bütün hayaller kaybolurdu biterdi

Gönlümün gizlisinde korkarak saklıyorum 

Geçmişimden bugüne ne varsa senden kalan 

Ya kaybolur gidersen bir daha göremezsem 

Biliyorum kalbimde senden başkası yalan

Son umudu tükenmiş idam mahkumu gibi 

Şimdi tek yaptığım şey seni düşünüp anmak 

Zaten yitik biriydim gözlerinin içinde

Ah ne güzel olurdu gözyaşınla ıslanmak

Son dileğim bu senden sonsuzluğa göçerken 

Ey ömrümün meleği sevdası saklı güzel 

Duanı esirgeme şöyle gelip geçerken

Ne olursun unutma arada bir hatırla', 'Sen umut tazelerken ben hep seni bekledim  Sen bir yaz sabahıydın ben gecenin yarısı  Ne sen geceme geldin ne ben erdim sabaha  Güzel hayall...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizlik-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Özlemler', 'sonsuz-ozlemler-sevki-dincal-s9ccu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Derin bakışlarında gözlerin ne güzeldi 

Dalınca hülyasına nasıl huzur bulurdum 

Kollarının arası en güzel sığınaktı

Sardıkça sevgi ile nasıl mutlu olurdum

Şimdi mazide kalan yılları arıyorum 

Bitmez hayallerimde o günlerin izi var 

Teninin sıcaklığı hala avuçlarımda

Yoksun şimdi yanımda düş kurmak neye yarar

Hayat beni kaç yerden vurdu durup dururken 

O gün bu gün hasretin izini sürüyorum 

Senden bana hatıra içimdeki yalnızlık 

Gözlerimde hayalin umuda yürüyorum

Hasret çekmek dünyada alın yazısı gibi 

Sonsuz özlemlerime türküler yakıyorum

Yüreğime bakmadan geçen zaman ardından

Çaresizlik içinde hüzünle bakıyorum', 'Derin bakışlarında gözlerin ne güzeldi  Dalınca hülyasına nasıl huzur bulurdum  Kollarının arası en güzel sığınaktı Sardıkça sevgi ile nasıl...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonsuz-ozlemler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Faydası Var', 'ne-faydasi-var-sevki-dincal-3q1v0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmiş gözlerinde aşka sadakat 

Kal desen vefasız ne faydası var 

Aşkına ağlayan iki gözümü

Sil desen vefasız ne faydası var

Gözyaşlarım kirpiğimde kururken 

Hasret beni her yanımdan vururken 

Ayrılığın hüznü kalpte dururken 

Gül desen vefasız ne faydası var

Kapılıp giderken hayal nehrine 

Sürükledin attın çile şehrine 

Bilerek içtiğim aşkın zehrine 

Bal desen vefasız ne faydası var

Ortasında kaldım yağmurun karın 

Yüreğimde acısı var yılların 

Dönüşü yok yürüdüğüm yolların 

Gel desen vefasız ne faydası var', 'Bitmiş gözlerinde aşka sadakat  Kal desen vefasız ne faydası var  Aşkına ağlayan iki gözümü Sil desen vefasız ne faydası var Gözyaşlarım kir...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-faydasi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Revamı', 'revami-sevki-dincal-fwosf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Madem sevmiyordun ayrılacaktın 

Her gece düşüme girmen revamı 

Bin sebebin vardı sevmekten yana 

Yalnız kusurumu görmen revamı

Yeni hasretlere sürmen revamı

Özlemin yoklarken daha derini

Hem gönlümde alıyorsun yerini 

Hem de gidip buluyorsun birini

Yoktu benim için senden öncesi 

Aşkınla doluydu gönül güncesi 

Hem duyup içimden sevdalı sesi 

Hem aşka duvarlar örmen revamı

Ne sandın sen gözlerimin selini

Uzatmadın silmek için elini

Ben candan sunarken sevda gülünü 

Başka gönüIlerden dermen revamı

Her cefana açtım çileli bağrı 

Dudağımda soldu sevdaya çağrı 

İçimde büyürken çektiğim ağrı 

Her gün başka dertler vermen revamı

Kabusa çevirdin gönlümde düşü 

Demek ki böyleymiş aşkın ölüşü 

Benden esirgerken tek bir gülüşü 

Kalbini ellere sermen revamı', 'Madem sevmiyordun ayrılacaktın  Her gece düşüme girmen revamı  Bin sebebin vardı sevmekten yana  Yalnız kusurumu görmen revamı Yeni hasretle...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/revami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-sevki-dincal-hkke2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Madem ki yalan aşkın küçük bir parçasıydım 

Vuracak yer yok muydu neden kalbimi seçtin 

Dile gelmez acılar bırakıp gittin bana

Neden kısa ömrümden bir rüzgar gibi geçtin

Gün geçtikçe bu tavrın daha işler derine 

Sen sebepsin gönlümün hüzün gecelerine 

Bak işte yüreğimde döndü yangın yerine 

Bu hasretin özlemin yarasını sen açtın

Yıktın bir şey demedim vurdun bir şey demedim

Suskun kaldı sitemim bir tek söz edemedim

Anılarım bağladı bırakıp gidemedim

Ben seni çok sevdikçe neden hep benden kaçtın', 'Madem ki yalan aşkın küçük bir parçasıydım  Vuracak yer yok muydu neden kalbimi seçtin  Dile gelmez acılar bırakıp gittin bana Neden kısa öm...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/neden-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle De Sen', 'i-lle-de-sen-ugur-oguz-sahin-qypxo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlle de sen

Vazgeçemediğim tutkum

Kimse yerini dolduramadı

Sen bana her şeyi unutturdun

Sabah olmuş yine güneş şafakta

Herkes hayat kavgasına koşacak birazdan

Bense yorgun gözlerimle uykuya

Bilmiyorum kaç şafak doğacak

Kaç akşam batacak

Bitmeyecek senin kavgan bende

Hasretin de öyle

Gönül ille de sen diyor

Başka bir şey bilmiyor

Kimi gün ela kimi gün mavi

Bazen de yeşil gözlerinde

Satır satır yaşamak için seni

Yola koyuldum

Hatırlar mısın karşılaştığımız o günü

İlk defa sen söylemiştin bana

Kahverengi gözlerimin

Ne kadar güzel olduğunu

Gözlerimin önünde o masum halin

Ne de utanmıştın o gün

Korku muydu sevgi miydi anlayamadım

Başını bile kaldırmadın önünden

Bir sıcak nehir aktı geçti sanki içimden

İşte o an bu dedim

Bir kelebek gibi uçarken

Farkında değildim kondum o bahçeye

Tahta sedirde bir vazoya konmuş

Çiçek gibiydin

Bir an üzerine konmak geldi içimden

Ama salyangoz misali içime çekildim

En vurgun halimle

Seyrettim seni uzun uzun

O çocuksu masum halini

Gözlerindeki renkleri

Çıkaramadım aklımdan bir türlü

Düşündüm uzun uzun 

Gece sabaha kadar

Ve sonunda

Hayatımın kararı çıktı bana

İşte o an

İlle de sen dedim', 'İlle de sen Vazgeçemediğim tutkum Kimse yerini dolduramadı Sen bana her şeyi unutturdun Sabah olmuş yine güneş şafakta Herkes hayat kavgasın...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ille-de-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Nerdesin', 'simdi-nerdesin-sevki-dincal-31phj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk en fazla gözlerinde güzeldi 

Buselerin tadı dudaklarında

Ne bakmaya doydum ne de öpmeye 

Ömrüm geçti gönül sokaklarında

Mehtap bile kıskanırdı yüzünü 

Baktığın aynalar çatlardı bir bir 

Sense aldırmazdın güzelliğine 

Yüzünde güllerin her rengi vardı

Tebessümün dalga dalga yayılır

 Yüzünde sayısız çiçek açardı

 Sanki kirpiğinin gölgelerinde 

Aşka kanat çırpan kuşlar uçardı

Ellerini sorma ateşten kordu 

Sıcaklık denince onu tanırdım 

Kollarında konaklasam bir gece 

Kendimi bitmeyen düşte sanırdım

Şimdi neredesin değiştin mi hiç 

Yıllar var ki görmüyorum yüzünü 

Neler hayal ettim neler düşündüm 

Çok aradım bulamadım izini

Anılar gönüle kör tesellisi 

Kokunu tenini çok özlüyorum 

Hatıralar avutuyor desem de

Gittiğinden beri yol gözlüyorum', 'Aşk en fazla gözlerinde güzeldi  Buselerin tadı dudaklarında Ne bakmaya doydum ne de öpmeye  Ömrüm geçti gönül sokaklarında Mehtap bile kısk...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/simdi-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay be', 'vay-be-sevki-dincal-hh2l3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalan aşkın ateşinde 

Çıra gibi yandım vay be 

Sevdim dedi inandırdı 

Ona nasıl kandım vay be 

Çıra gibi yandım vay be

Bu aşka bir ömür verdim 

Mutlu günler yakın derdim 

Gönlümü yoluna serdim 

Ona nasıl kandım vay be 

Çıra gibi yandım vay be

İçin için alevlenir 

Göz gönülü ele verir 

Üstüme çığ düşse erir 

Çıra gibi yandım vay be

Ona nasıl kandım vay be

Her doğan gün asık yüzlü 

Dert çekerim gizli gizli 

Acılarım dizi dizi

Ona nasıl kandım vay be 

Çıra gibi yandım vay be

Her gün sabır çekiyorum 

Kanlı yaşlar döküyorum 

EI açıp diz çöküyorum 

Ona nasıl kandım vay be 

Çıra gibi yandım vay be', 'Yalan aşkın ateşinde  Çıra gibi yandım vay be  Sevdim dedi inandırdı  Ona nasıl kandım vay be  Çıra gibi yandım vay be Bu aşka bir ömür verd...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vay-be-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimsin', 'sen-benimsin-sevki-dincal-qxqqv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimin hapsindesin 

Kaçamazsın sen benimsin 

Kanatların olsa bile 

Uçamazsın sen benimsin

Ne uzağa ne yakına 

Gidemezsin haydi sına 

Kollarını başkasına 

Açamazsın sen benimsin

Sensin beni benden eden 

Seviyorum işte neden 

Ayrılığı ben ölmeden 

Seçemezsin sen benimsin

Dinle kalbinin sesini 

Tüketme hiç nefesini 

Başka aşkın badesini

İçemezsin sen benimsin', 'Gözlerimin hapsindesin  Kaçamazsın sen benimsin  Kanatların olsa bile  Uçamazsın sen benimsin Ne uzağa ne yakına  Gidemezsin haydi sına  Kol...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-benimsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut!', 'umut-abdulkadir-karaman-fbthj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkes gitti, kaldi umut! 

Her sey bitti, baldi umut! 

Gözümde fer, canimda can

Tutundugum daldi umut! 

Feryad ederken, her zaman

Imdadima geldi umut! 

Hasret cekerken sevince

Kederimi aldi umut! 

Karamsarken, teselliye

Kusandigim saldi umut! 

Isyan ederken, asiye

Itaatkar oldu umut! 

Saklandigim dehlizlerde

Kaybolunca buldu umut! 

Mutsuz oldugum zamanlar

Ne, sikintim? bildi umut! 

Icimde pasli, pörsümüs

Ne aci var, sildi umut! 

Korktugumda  sigindigim 

Sarildigim, eldi umut! 

Hazan sarinca ruhumu

Kokladigim güldü umut! 

Omrü ömrüm kadar uzun…

Ben ölünce öldü umut! 

12.10.2002 München', 'Herkes gitti, kaldi umut!  Her sey bitti, baldi umut!  Gözümde fer, canimda can Tutundugum daldi umut!  Feryad ederken, her zaman Imdadima g...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/umut-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar', 'bir-zamanlar-sevki-dincal-52hv5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım gibi yakınken bir zamanlar sen bana 

Şimdi bak kadere ki yıldızlardan uzaksın 

Duyduğum her şey yalan yazık çok geç anladım 

Hayalime kurulan sen en büyük tuzaksın

Geçen çileli ömrün en uzun gecesinden 

Kırık dökük anılar bir de pişmanlık kaldı 

Gönüllerde yaşayan mutluluğun yerini 

Manasız mektuplarla solgun resimler aldı

Yarası geçti aşkın ama unutamadım 

Yüreğimin içinde sızısı saklı durur 

Mevsimler gelir geçer zamanın terkisinde 

Sen aklıma düştükçe yeni ağrılar vurur

Yeminler dudağında şimdi mutlu mu bilmem 

Herhalde gülüyordur nasıl inandım diye 

Varsın benim saf kalbim saflığından utansın 

Verdiğin bütün sözler senden birer hediye

Yağmalanmış duygular ancak toparlanacak 

Az fırtına esmedi az talan yaşamadım 

Yangınların içinden zor geçtim zor kurtuldum 

Sana olan öfkemi yıllardır aşamadım

Ben yine yaşıyorum içindeyim hayatın 

Ama senin sonunu pek iyi görmüyorum 

Güzellik gelir geçer zamanın gölgesinde 

Masal mutlu biter mi ihtimal vermiyorum', 'Canım gibi yakınken bir zamanlar sen bana  Şimdi bak kadere ki yıldızlardan uzaksın  Duyduğum her şey yalan yazık çok geç anladım  Hayalime ...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-zamanlar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanlıktan Öteyim', 'pismanliktan-oteyim-sevki-dincal-y0f03', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşte döndün geriye pişmanlıktan öteyim 

Gülerek aç kapıyı sıcak bir hoş geldin de 

İstersen hiç sarılma ellerimi tut yeter 

Gözünle olsa bile nerelerde kaldın de

Sitem etme ne olur bir şey sorma yorgunum 

Diyetini ödedim yaşattığım acının 

Tükendim son çaremsin belki de son umudum 

Dermanı yalnız sensin içimdeki sancının

Elveda dememiştik hoşçakal dememiştik

Ayrıldığımız günü birlikte unutalım 

Yine eskisi gibi mutlu günlere dönüp

Muhabbeti sevgiyi yarınlarda tutalım

Yaralıyım dertliyim mutsuzum görüyorsun 

Neye dokunsam hasret aklımda yalnız sensin 

Üşüyorum yalnızım sonsuz bir boşluktayım 

Bırak gönül borcunu çok severek ödensin', 'İşte döndün geriye pişmanlıktan öteyim  Gülerek aç kapıyı sıcak bir hoş geldin de  İstersen hiç sarılma ellerimi tut yeter  Gözünle olsa bil...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pismanliktan-oteyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertelenmiş Düşler', 'ertelenmis-dusler-sevki-dincal-lgvad', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ertelenmiş düşlerde sen çıktın hep karşıma

Dudağının tadıyla her sabah mutlu kalktım 

İnan bana kaç defa güneş doğmasın diye 

Pusu kurdum dağlara yaklaşsa vuracaktım

Mazide yarım kalan ne varsa tamamlandı 

Ne yazık mutluluğu şimdi düşlerde buldum 

Varsın gündüz yokluğun bir ağrı gibi dursun 

Gündelik acılara artık aşina oldum

Gecenin terkisinde riyasız bir sonsuzluk 

Bir nur gibi sen varsın görüntüyü süsleyen 

Mehtap solgun açmışsa saygısından bu aşka  

Sana duyduğum histir hayalimi besleyen

Senden başka iz düşmez karanlığın içine 

Kapatır gözlerimi düşüncemde yürürüm 

Acı tatlı ne varsa silinir gözlerimden 

Onca yıldız içinden yalnız seni görürüm', 'Ertelenmiş düşlerde sen çıktın hep karşıma Dudağının tadıyla her sabah mutlu kalktım  İnan bana kaç defa güneş doğmasın diye  Pusu kurdum da...', ARRAY['Türk Edebiyatı','Şiir','Şevki Dinçal']::text[], 8.5, '{"poet":"Şevki Dinçal","poet_slug":"sevki-dincal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ertelenmis-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Adı Doğmadan Vardı', 'onun-adi-dogmadan-vardi-ugur-oguz-sahin-8rt5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aylardan Şubat''ta doğmuşum ben

Her Şubat''ta doğardım yeniden

Şubat''ları çok severdim ben

Şubat''larda yağmurlar

Her Şubat''ta yeniden tazelenirdi anılar

Diğer aylar için pek takıntım yoktu

Ama şimdi Mayıs''lar

Mayıs''lar gelirken ölümü hazırlayacak bana

Ben her Mayıs''ta ölüp ölüp dirileceğim

Neden Mayıs''larda ölürüm bilir misiniz dostlar

Güzeller güzeli bir kız yeğenim vardı

İşte bu ayda Mayıs''ta 

Onu trafik canavarı aldı

Sadece kulaklarımda 

Dayıcığım dediği seslenişi kaldı

O ne muhteşem çiçekti

Onun ne mis kokusu vardı

Hayat dolu gülümserdi bana

Ne şakalar yapardı

Daha söylenemeden adın ne yaşadın

Bu kadar kısa mı olacaktı hatıraların

Dostlar sormayın bana adını

Artık söyleyemem ki

Uçtu gitti avuçlarımızdan o bir melekti

Zaten meleklerin başka adı olmaz ki

Seninle ne kadar birlikte olduk ki

Masallardaki bir varmış bir yokmuş gibi

Güzel uykular Allah''tan

Sana canım yeğenim

Hep gönlümüzdesin hep karşımızda

Artık sadece hatıra bıraktığın resimlerinleyiz

Şimdi öyle bir derin yara ki hicranın

Sormasınlar kimseye anlatamam

Nasıl iyileşir nasıl geçer nereden bileyim

Bu yangın nasıl söner ne diyeyim

Söyleyin dostlar hangi hekimlere gideyim', 'Aylardan Şubat''ta doğmuşum ben Her Şubat''ta doğardım yeniden Şubat''ları çok severdim ben Şubat''larda yağmurlar Her Şubat''ta yeniden tazeleni...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/onun-adi-dogmadan-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akan Kanım Olacaktır', 'akan-kanim-olacaktir-gultekin-firinci-79cc4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabah kalktigimda seni yanimda bulamadim

bir mektup birakmisin 

beni unut demisin 

ama bide dusun unutulmak istenen sen olsaydin 

ne yapardin

inanki senin yapmak istedigini ben yapmayacagim

 arkandan bir damla gozyasi damlatirsam namerdim arkandan akan gozyasim degil kanim olacaktir', 'sabah kalktigimda seni yanimda bulamadim bir mektup birakmisin  beni unut demisin  ama bide dusun unutulmak istenen sen olsaydin  ne yapardi...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Fırıncı']::text[], 8.5, '{"poet":"Gültekin Fırıncı","poet_slug":"gultekin-firinci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/akan-kanim-olacaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizler Dosttuk', 'bizler-dosttuk-gultekin-firinci-ct2lm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bizler dostuk ayirildik 

dort arkadstik

birimiz cilginlik 

yapmayi severdi

adi FERHAT di

mangal gibi yuregi vardi

kaldirdimi elini 

iki kisiyi birden yigardi.

(oy ferhat, can ferhat, can aldin can verdin ugruna.)

bizler dostuk ayirildik

birimiz duygusaldi

adi DERYA ydi 

icimizden birine 

en kucuk bir sey olsa

uzulup aglardi

cok iyi hat irlarim 

bir gun karinciya basti diye 

iki saat agladini.

(oy derya, can derya, hep aglayip durdun dustun mahbusa.)

bizler dostuk ayirildik

otekimiz sevdaliydi

adi SERHAT

vatan aski vardi kalbinde

sevdaliydi topraga

olume siirt kosardi

bucaksiz daglar ugruna.

(oy sehat, can serhat, ulastin en sonunda vatan topragina.)

bizler dostuk ayirildik

bide ben vardim 

adim FIRAT, dicle, zilan

yeri geldiginde semayim

bedenimi korkusuzca verecek

zamani geldimi agitim 

daglari korkusuzca delecek

(oy firat, can firat yere goge sigmadin gittin surgune.)

bizler dostuk ayirildik

birimiz toprakta

birimiz mahpusta

otekimiz dagda

bende surgunde

bizler dostuk ayrildik

(onlar dostu ayirildilar, vatan ugruna, bedenlerini hic saydilar kurdisatan ugruna.)', 'bizler dostuk ayirildik  dort arkadstik birimiz cilginlik  yapmayi severdi adi FERHAT di mangal gibi yuregi vardi kaldirdimi elini  iki kisi...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Fırıncı']::text[], 8.5, '{"poet":"Gültekin Fırıncı","poet_slug":"gultekin-firinci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bizler-dosttuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku Zannettin', 'tutku-zannettin-ugur-oguz-sahin-w6uzn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevinç koydum adını seni bulduğumda

Gayemdin pembe bulutlarımda umudumda

Hep seni yaşardım bardaktan boşalır gibi yağmurda

Giderken bir elveda demeyi neden çok gördün

    

Tekelinde zannettin bu sevdamı

Oysa görmedin gözlerimdeki sevgimi

Tortullaştırdın içimdeki kendini

Sen tutku zannettin oysa tutarsızlıktı seninki', 'Sevinç koydum adını seni bulduğumda Gayemdin pembe bulutlarımda umudumda Hep seni yaşardım bardaktan boşalır gibi yağmurda Giderken bir elve...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tutku-zannettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Tek Devre', 'sevda-tek-devre-canan-demir-q2yji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzsüz sevda yine geldi dayandı kapıma..

''Git'' diyemedim  ve geçti oturdu baş köşeme, tahtıma..

Hala boğulmaktayken sönen yangımın dumanında..

Yepyeni bir ateş saldım yüreğimin her karışına..

Her şeye aksetti taze alevin kızıllığı..

Hiç geçikmedi, yer etti bağrımda tanıdık bir sancı..

Bir el gözlerime yerleştirdi o bildik çağlayanları..

Yıpranmış maskemi söküp attı bir başka el, 

Ve yenisinin altına gömdüler acılarımı..

Bir halatla kalbimin kölesi ettiler yine beynimi..

Bu hamleyle bütün değerler yer degiştirdi..

Göz yaşlarımla yırtığım perde yenilendi..

Ve gerçek körü ettiler beni, 

Yabancısı değilim ben bu demlerin, 

Geçmiş yinelendi..

Şimdi elim kolum bağlı, çilemi doldurmaktayım, 

görmek, düşünmek yasak bana, sadece susmaktayım

Gündelik telaşlar ve şu maske de olmasa, 

Aşikar olurdu halim, ne denli yanmaktayım..

İşte yine ellerim buz gibi, gözlerim yanıyor..

(Oysa  her damarıma kalbimden gelmiyor mu kan? ..)

''Anlmaya çalışma'' diyor karanlıkta birileri

Ve o acı öğüt  duyuluyor; ''Sen sadece YAN..''

Söylemek istediklerimle söylediklerim bambaşka yine..

O ateşin kontrolünde en iradeli sözlerim bile..

Bilmem, daha ne kadar sabreder ruhum bu tene 

Yegane tesellim; '' Şu çağlayanlar bitsin hele..''

Bin kez de yaşamış olsa can alışmıyor bu derde..

Hep çırak kalınıyor, ustası yok bu işin aynı  telaş her kere

Hangi zaman birmine sığdırılır ki sevda? Gün, ay, sene? 

Başı yok, sonu yok, mola yok, sevda tek devre..

Ne insaflı katildir tek vuruşla ruhu bedenden kovan..

Başında bir kurşun yarasıyla yol alırsın ölüler diyarına.. 

Sevda canlılığa dair bir yürek bırakır içinde durmaksızın atan..

Ne canlılara katılabilirsin, ne ölüler alır seni aralarına..

Uzatmayın ellerinizi, siz somuttasınız, ben soyuttayım, 

Tutamazsınız, cismani değildir bu yeisi taşıyan..

Yandım yanalı ben  başka bir boyuttayım, 

Kusursuz bir kopyamdır aranızda yaşayan...

(Eylül  2002, İstanbul)', 'Yüzsüz sevda yine geldi dayandı kapıma.. ''Git'' diyemedim  ve geçti oturdu baş köşeme, tahtıma.. Hala boğulmaktayken sönen yangımın dumanında...', ARRAY['Türk Edebiyatı','Şiir','Canan Demir']::text[], 8.5, '{"poet":"Canan Demir","poet_slug":"canan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sevda-tek-devre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Artık Yiğidim', 'uyan-artik-yigidim-nurullah-genc-x97sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Istırâbdır yiğidim azığımız, hicrandır

Mirasımız mahkûmdur, mahzundur, perişandır

Gene de ye’se düşme yiğidim; imtihandır

Filizlenen her ölüm, mazlumlara nişandır

Ne gönüllerde sevinç, ruhlarda beyaz kaldı

Ufka bir bak, ilerle; inkılâba az kaldı.

Ülkemden hatırıma hep sefiller geliyor

Bin yüzlü Ebrehe’ler, kara filler geliyor

Şimdi devran değişti; ebâbiller geliyor

İbrahim bahçesinden taze güller geliyor

Âlemde, duyulacak kutlu bir âvaz kaldı

Ufka bir bak yiğidim; inkılâba az kaldı.

Çöküyor sırtımızda yükselen vahşi duvar

Heykeller kırılıyor; dökülüyor mumyalar

Toprağın sinesinde umut var, heyecan var

Okşadığın her kökten fışkırıyor bir bahar.

Buzlar çözüldü; kıştan kuru bir ayaz kaldı

Ufka bir bak yiğidim; inkılâba az kaldı.

Gözlerin âyet âyet büyüyen bir bebektir

Ellerin sokaklarda uçuşan kelebektir

Sana rehberlik eden ne cindir, ne melektir

O bir İnsan-ı Kâmil, mücella bir dilektir

O’ndan bize ebedi sürecek bir haz kaldı

Ufka bir bak yiğidim; inkılaba az kaldı.

Bulanık akan sular durulacak yeniden

Gökyüzüne direkler vurulacak yeniden

Saâdet menziline varılacak yeniden

Çağlar üstü bir nizam kurulacak yeniden 

Cehaletin elinde lanetli bir saz kaldı

Ufka bir bak yiğidim; inkılâba az kaldı.

Bu kan kokan coğrafya, bu çığlıklar senindir

Bu gözü yaşlı târih, hıçkırıklar senindir

Yeryüzünde çiğnenen bütün haklar senindir

Prangalı hükümler, aydınlıklar senindir.

Yıllardır, uygarlıktan sana hep enkaz kaldı

Ufka bir bak yiğidim, inkılâba az kaldı.

Tasalanma yiğidim; zaman bizden yanadır

Külümüzden yükselen duman bizden yanadır

Son durak, son ilahi ferman bizden yanadır

Dünya düşman olsa da, iman bizden yanadır

Kapıları açacak çoşkun bin niyaz kaldı

Ufka bir bak yiğidim, inkılâba az kaldı

Mahzenlerde beklemek ziyan artık, yiğidim

Fecr-i sâdık vaktidir; uyan artık yiğidim

Ateşlere girsen de, dayan artık yiğidim

Hakikate dönüyor rüyan artık, yiğidim

Zalimler için karar verildi; infaz kaldı

Ufka bir bak yiğidim, inkılâba az kaldı.', 'Istırâbdır yiğidim azığımız, hicrandır Mirasımız mahkûmdur, mahzundur, perişandır Gene de ye’se düşme yiğidim; imtihandır Filizlenen her ölü...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/uyan-artik-yigidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telek', 'telek-kemal-aslan-m2osd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dün müydü

kanatlanan 

kişnemesi

beyaz  atın

geçtiğim

puslu bahçe

bir telek

çocukluğum', 'dün müydü kanatlanan  kişnemesi beyaz  atın geçtiğim puslu bahçe bir telek çocukluğum...', ARRAY['Türk Edebiyatı','Şiir','Kemal Aslan']::text[], 8.5, '{"poet":"Kemal Aslan","poet_slug":"kemal-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/telek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bizim-cocuklar', 'bizim-cocuklar-salih-ozalasan-cjysa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Altlarında son model arabalar

Ceplerde sayısız kıredili kartlar

Yok hiç bozukluk yirmilik paralar

Kaçacak delik arıyor 

Onlar geçerken yayalar

Kimi hap içer kimi ot

Bozulmuş nedense mayalar

Moda olmuş dans ederken soyunmalar

Karışmış bir birine anahtarlar yataklar

Kalmamış hiç birinde ne utanma ne ar

Değişmiş kıyafetler enteresan modalar

Erkeği kadın kadını yosma etmiş modacılar

Şarkılar bile değişmiş farklı yorumlar

Klip diye sunuluyor erotik danslar

Bir özentiki sorma gitsin

Gençlik yok oldu sonunda

Korkarım şimdi sırada çocuklar

Uykudamı ne yapıyor bilinmez

Ne zaman uyanacak anneler babalar

Uyan artık uyan kaldır başını

Belkide sırada bizim çocuklar

Y.Tari.13-10-2002 Saat 11.45', 'Altlarında son model arabalar Ceplerde sayısız kıredili kartlar Yok hiç bozukluk yirmilik paralar Kaçacak delik arıyor  Onlar geçerken yayal...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bizim-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Entel Sosyete', 'adi-entel-sosyete-salih-ozalasan-y4x3l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Entel barda bir yosma

Takmış yine birilerini koluna

Kaptırmış kendini pistte oyuna

Balık etinde hem enine hem boyuna

Kirpikler takma kaşlar boya

Gözlere çekilmiş rimelden bir cila

Yanaklarda hem allık hem pudra

Bel desen önlü arkalı fora

Saçlar jöleli sanki peruk kafada

Ara sırada kırıştırıyor locada

Cilveleşmeler ardından şuh bir kahkaha

Çınlar vallahi sesinden loca

Bilmesen sanırsın bunlar

Birbirini seven karı koca

Yada iki sevgili

Gelmişler kaçamak için bara

Hey dostum dur bir dakika

Yosma dedimse sakın fahişe sanma

Şimdilerde böylesi olmuş moda

Entellik diyor herkes bunun adına

Ha pardon sosyete diyende var bu arada

Gizlemişler kimliklerini

Birer simgenin arkasına

Yokolup gidiyor bu gençlik

Ne zaman varılacak farkına

Y.Tar.13-10-2002 Saat 9.10', 'Entel barda bir yosma Takmış yine birilerini koluna Kaptırmış kendini pistte oyuna Balık etinde hem enine hem boyuna Kirpikler takma kaşlar ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/adi-entel-sosyete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Yüreği Diyorum', 'gecenin-yuregi-diyorum-duygu-gunkut-74cxg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin yüreği diyorum, 

Topal bir karasaban gibi

Biçiyor, geçiyor beni.

Nadasa bırakılmış

Bu zengin toprak, 

Ne ektiğini bilen herkese

Tapılası ekinler sunacak.

Bu sergin yürek

Her sabah, sadece bir çiy tanesine uyanacak.

Bu krallığın tartışılmaz hükümdarı

Yaşamın soluksuzluğunda

Kendi soluğunu paylaşmayı bilen

Küçük bir çocuk olacak.

Biraz mutlu, biraz parlak

Tedirgin bir ışıltı ile yaşayacak.

Aşk ölüme başkaldıracak.', 'Gecenin yüreği diyorum,  Topal bir karasaban gibi Biçiyor, geçiyor beni. Nadasa bırakılmış Bu zengin toprak,  Ne ektiğini bilen herkese Tapı...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-yuregi-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ın Ettiği', 'ask-in-ettigi-salih-ozalasan-slapk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O bir garip köylüydü

Sırtında abası yırtık pırtık

Ayağında garip bir postal

Tabanı delik burnu açık

Saçı darmadağın tanımamış tarak

Sakalıysa bir mecnunu andırır artık

İnsanlardan tecrit etmiş kendini

Korkuyla bakıyor gözleri artık

Gördüğümde hayretle izledim

Sormadan derdini söyler diye bekledim

Kaçmak istediysede yanımdan

Tuttum ona izin vermedim

Sordum nedir senin bu halin

Sen milletin efendisi değilmiydin

Söyle bana bu hale nasıl geldin

Sen bir zamanlar nede şık

Saçı taralı gezerdin

Verdiği cevap enteresan

Sadece

Sevdim, sevdim, sevdim

Sevmek bumu Allah''ım

Korkumdan tek bir cevap veremedim

Y.Tar.! 3-10-2002 Saat 9.40', 'O bir garip köylüydü Sırtında abası yırtık pırtık Ayağında garip bir postal Tabanı delik burnu açık Saçı darmadağın tanımamış tarak Sakalıys...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-in-ettigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak, Yakın...', 'uzak-yakin-duygu-gunkut-loa3u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaksın ve alabildiğince

Yakın.

İşte bu yüzden

seni sevmem, 

içiçe geçen bir zincir gibi

ince ince

sana kenetlenmem, 

kendimden geçmem

yine

bu yüzden.

Uzaksın ve olabildiğince

Yakın.

İşte bu yüzden

seni hapsetmem

kendime, 

yüreğime sızmana

yine

yeniden

izin vermem

bu yüzden.', 'Uzaksın ve alabildiğince Yakın. İşte bu yüzden seni sevmem,  içiçe geçen bir zincir gibi ince ince sana kenetlenmem,  kendimden geçmem yine ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzak-yakin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Petra’yı Seviyorum/Garsonun Türküsü', 'petra-yi-seviyorum-garsonun-turkusu-duygu-gunkut-88oc5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Petra’yı seviyorum.

Masmavi gözlerini, 

Saman sarısı saçlarını

Anamın yufka yüreğine benzetiyorum.

Seviyorum bu kızı.

Sözleri kafama uygun, 

Elleri bizim kuyum.

Onu ablamın gençkızlık neşesinde görüyorum.

Petra’ya tapıyorum.

Geniş kalçaları, 

Dolgun dudaklı ağzında

Babamın meyhane çıkışları gülüşünü duyuyorum.

Seviyorum bu kızı

Doğası çocuklarımız, 

Dünya vatandaşı.

Petra’yla sevişmek, yeni bir Malazgirt Savaşı.

Petra’yla evleniyorum.

Türkiye’yi bilmem ama, 

Ben A.T.’ye giriyorum.', 'Petra’yı seviyorum. Masmavi gözlerini,  Saman sarısı saçlarını Anamın yufka yüreğine benzetiyorum. Seviyorum bu kızı. Sözleri kafama uygun, ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/petra-yi-seviyorum-garsonun-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Görmek Ölmek Demek Sensizlikse Zaten Ölüm', 'seni-gormek-olmek-demek-sensizlikse-zaten-olum-sabri-salman-qpka6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin ikinci yarısı...

Herkes uykuda,

Yine yalnız, gene uykusuz

Hep seni düşünüyorum.

Oysa sen

Belki bir rüyanın koynunda

Huzur uykularında,

Ben hep huzursuzum.

Yine hasret gözlerim uykuya

Geceler uzun, sabahlar uzak

Saatlere, dakikalara 

Saniyelere mahkûm.

Zaman yine kurmuş tuzak

Şimdi yanımda olsan keşke,

Bir gece, sadece bir gece

Tarih 21 Aralık olsa 

Kuzey yarımkürede.

Ben durmadan sana baksam,

O yağmur gözlerinde 

Sırılsıklam ıslansam.

Baksam, baksam, baksam...

Zülfünün kıvrımlarını saysam,

Karanlıkta.

Hep sussam,

Durmadan konuşsan

Sevdiğin şiirleri okusan,

Ben, seni anlatan şiirleri:

Leylaları, Şirinleri, Aslıları...

Güneş bir kerecik doğmasa

Firkat, vuslatı boğmasa

Karanlık olmazdı dünyam,

Sen yanımda olunca.

Saatler yine geçmiyor

Hüzün kovalıyorum 

Tenha sokaklarda

Ne senin haberin var 

Bu yaman ıstıraptan 

Ne de başkalarının

Yalnız beni

Durmadan yakar 

Bu hicran.

Bir gün solacak bu tenha yürek,

Yaprak dökecek gönül ağacım

Ne senin haberin olacak

Ne de birilerinin

Ben ve yüreğim,

Sana mahkûm yaşayıp

Sana hasret ölecek.

Ne yağmurlar yağdı,

Milyon kemikler üstüne,

Ne rüzgârlar esti,

Harabelerde.

Bir yürek de öyle solacak,

Habersiz, kendi kendine

Bir gün bakarsan

Evinin beyaz penceresinden

Hep sana bakan

Bir yıldız göreceksin,

Uzak, başka, mahzun

Yağmur gözlerini yalayan

Işıkları olacak

Hep sana bakıp kalacak,

Sen, yıldız olana kadar

Benim gibi

Yalnız kalana kadar…

                                          (21.6.2002)

“Yan ki Üşümesin Yüreğin” adli şiir kitabımdan…', 'Gecenin ikinci yarısı... Herkes uykuda, Yine yalnız, gene uykusuz Hep seni düşünüyorum. Oysa sen Belki bir rüyanın koynunda Huzur uykularınd...', ARRAY['Türk Edebiyatı','Şiir','Sabri Salman']::text[], 8.5, '{"poet":"Sabri Salman","poet_slug":"sabri-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/seni-sevmek-olmek-demek-sensizlikse-zaten-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bercesteler', 'bercesteler-mehmet-fatin-baki-ajwla', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağyara çuvaldız sokacaksan, daha evvel

Kendin dene bir kez, kanatır iğne batınca

Fa’ lun   fe ilâ tun   fe i lâtun    fe i la tun

  /     /   . . /   /     . .  /   /   ..  /    /

*****

Bundan yana insanlığa kıymet veriyorsan

Öksüz ve yetimlerle de paylaş ne yiyorsan	

 Mef u lu  me fâ i lu  me fâ i lu   fe u lun    

    /   /.   .    /   / . .    /   /  . .  /   /

*****

Bazı düşman bazı şeytan seni etmiş  perişan

Sonu gelmez kibirindir sana güçlük çıkaran

Fe i la tun   fe i la tun   fe i la tun   fe i lun

. .   /   /  ..  /    /    . .   /   /  . .   /

*****

İdâma makkum olmadan  ölüm dahi güzel  gelir, 

Me fa i lun   me fa i lun  me fa i lun   me fa i lun

.   / .   /     .   / .   /    .   / .   /      .   / .   /

*****

Vezn-i âruzla şiir yazması derdim zor olay

Dediler cevheri yerden çıkarım çok mu kolay

                                           

Fe i lâ tun   fe i lâ tun   fe i lâ tun   fe i lun

 / .   /   /  ..    /    /   . .    /    / .  .   /

*****

Bu gün ölsem bu benim mâzimin en son günüdür

Ya yaşarsam bu gün istikbâlimin, ilk dünüdür

.

Fe i la tun  fe i la tun fe i la tun fe i lun

. .  /   /   ..   /   /  . .  /   /  . .   /

*****

Bir esb sanacaksın ne vakit nefsimi görsen

Hem tekme atar hem de sanır kendini tevsen

Esb = asil at 

Tevsen = azgın, huysuz at

Mef u lu   me fâ i lu  me fâ i lu   fe i lun

 /    /  .   .   /   / .  .   /   / .   .   /   /

*****', 'Ağyara çuvaldız sokacaksan, daha evvel Kendin dene bir kez, kanatır iğne batınca Fa’ lun   fe ilâ tun   fe i lâtun    fe i la tun   /     / ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatin Baki']::text[], 8.5, '{"poet":"Mehmet Fatin Baki","poet_slug":"mehmet-fatin-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bercesteler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahı Bekler Gibi', 'sabahi-bekler-gibi-sabri-salman-9lpmo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bekle sevdiğim,

Gecenin kucağında yapayalnız kalınca 

Ansızın geliveririm belki.

Ayrılık olur da, vuslat olmaz mı?

Gecenin zindan karanlığına,

Elbet güneş dolmaz mı?

Bekle sevdiceğim,

Dağlar duman kaplamış önümde

Ne kadar yüce de olsa

Yol olur gelirim, yol bulur gelirim.

Mesafeler olsa da vuslata perde

Sevda, devadır en onulmaz derde…

Beni yıldızın geceyi beklediği gibi bekle!

Belki bir yıldız olur doğarım, karanlık gecene

Belki de üşüyen iklimine güneş olur gelirim

Kapın çalarsa aniden

Anla ki benim.

Beni uçan kuşların kanatlarında bekle!

Müjdeli bir haber olurum.

Belki kaldırımda bastığın taş,

Belki tabağında aş,

Belki de hasret yolunda yoldaş olurum.

Sen bülbül ol, ben de gül

Seher vaktinde bekle açmamı

Denizin fırtınayı, hasretle yanmış dağların

Bembeyaz karları beklediği gibi bekle!

Bekle hasretim, yollar uzak da olsa...

Mesafeler önümde tuzak da olsa…

                                                      (1999)

“Yan ki Üşümesin Yüreğin” adli şiir kitabımdan…', 'Bekle sevdiğim, Gecenin kucağında yapayalnız kalınca  Ansızın geliveririm belki. Ayrılık olur da, vuslat olmaz mı? Gecenin zindan karanlığın...', ARRAY['Türk Edebiyatı','Şiir','Sabri Salman']::text[], 8.5, '{"poet":"Sabri Salman","poet_slug":"sabri-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sabahi-bekler-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra Yeniden', 'yillar-sonra-yeniden-sabri-salman-e2myg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretle kavrulan gönül çölüme

Bir yaz yağmuru oldu, anlık bakışın

Yol uzun, yolcu yorgun da olsa

Yoldaşım sensin ya o da yeter...

Artık kâbus dolu geceler

Bir ümit sabahıyla bitecek

Bir şafak bile olsa gelecek 

Sen varsın ya içinde, o da yeter...

Üzüm gözlerindeki o esrar

Bir orman tenhasına çeken

Tek bana eylese nazar,

O da yeter...

Kaderim ümitsizliği beklemektir 

Derdime dert eklemektir

Seni beklemek var ya, 

O da yeter...

Sen belki inanmadın karda açan çiçeğe

Yalan sevdalara başkaldıran gerçeğe

Ben inandım ya,

O da yeter...

Gönül dile geldi yıllar sonra,

Yola çıktı Kaf Dağına,

Dağ olmasın, yol var ya,

O da yeter...

Akıp giden zamana,

Seni beklemek düştü,

Geçmez artık saatler

Bu ıssız gözler

Ümitsizce yolunu gözler 

Gelmesen de, görmesen de

Seni gözlemek var ya,

Seni özlemek var ya,

Her şeyden öte,

Her şeyden yüce

Seni beklemek var ya,

İşte o, her şeye yeter...

                                    (01.01.2001)

“Yan ki Üşümesin Yüreğin” adli şiir kitabımdan…', 'Hasretle kavrulan gönül çölüme Bir yaz yağmuru oldu, anlık bakışın Yol uzun, yolcu yorgun da olsa Yoldaşım sensin ya o da yeter... Artık kâb...', ARRAY['Türk Edebiyatı','Şiir','Sabri Salman']::text[], 8.5, '{"poet":"Sabri Salman","poet_slug":"sabri-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yillar-sonra-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-sabri-salman-nsw92', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sene 1979

Mevsim hazan

Zamanın durduğu an

Siyah önlüklü,

Masum, ürkek

Elini sıkıca tuttuğu anasıyla

Girişinde 1926 yazan

Kocaman okul binası önünde

Ben…

Küçücük bedenimde kocaman

Bilinmezler, sorular

Çocuk çocuk

Gönlümde büyüyen

Merakla beklenen

Öğretmen…

Kahverenginde bir ceket,

Tertemiz ayakkabı, 

Yarısı ak, düzgün taranmış saçlar

Şaşkınlığın ifadesi

 “Öğretmen bir insanmış” denilen

Öğretmen…             

Akıp giden zamana

Sığdırılan dünyalar

Öğrenilen hayat…

Çok şeyi değil, her şeyi

Öğreten 

Öğretmen…

Ve gönülden kopan bir yaprak

Ekim’in on sekizi

Yaşanan en acı an

Ayrılık…

Gözyaşlarında anlatılan

Yüreğe yakılan ateş

Yangınlara eş,

Sarıldıkça artan hasret

Ve gözyaşları bırakılan

Ceket

Bir kalp ki, ceketinde 

Beraberce giden

Öğretmen…

Yıllarca yürekte duyulan ses:

“Toprak olmak istedim,

Atılan tohumları yeşerteyim, dedim, 

 İşte öğretmenim” diyen.

Aynı duayla geçen zamanlar

Ve müjdeli bir haberin ardından

Geçen dört sene…

Yıl 1995

Ağustos’un otuz biri

Yüreğe çiçek gibi takılan,

Özlenen, beklenen

Sıfatım artık

Onun gibi

Öğretmen…    

                        (18 Eylül 1997-Çermik)

“Yan ki Üşümesin Yüreğin” adli şiir kitabımdan…', 'Sene 1979 Mevsim hazan Zamanın durduğu an Siyah önlüklü, Masum, ürkek Elini sıkıca tuttuğu anasıyla Girişinde 1926 yazan Kocaman okul binası...', ARRAY['Türk Edebiyatı','Şiir','Sabri Salman']::text[], 8.5, '{"poet":"Sabri Salman","poet_slug":"sabri-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/ogretmenim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden', 'eskiden-deli-kerem-wtwhn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birini tanırdım eskiden 

Mutluluk ve haz verirdi

Arakasından da derin acılar

Oturup maziye dönünce

Anımsarım onu

Yaşadığımız olayları

Acıları ve mutlulukları

Ama elim bir kazada yitirip

Helvasını yiyeli çok olmuştu 

Kendisi çok az tanınırdı

Tarifi bir güle benzerdi

Adınaysa aşk deniyordu.', 'Birini tanırdım eskiden  Mutluluk ve haz verirdi Arakasından da derin acılar Oturup maziye dönünce Anımsarım onu Yaşadığımız olayları Acılar...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eskiden-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-deli-kerem-4qm1n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedendir bilinmez 

Yorgun ve mutsuzum

Kimedir bilinmez 

Üzgün ve kırgınım 

Yitirdik ümitleri 

Aşka dair

Paylaştık her şeyi

Dostluğa dair', 'Nedendir bilinmez  Yorgun ve mutsuzum Kimedir bilinmez  Üzgün ve kırgınım  Yitirdik ümitleri  Aşka dair Paylaştık her şeyi Dostluğa dair...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefe', 'serefe-deli-kerem-xwk5d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son perdeyi de kapatıyorum 

Alkışlarla, yaşlarla

Yorgun bedenimle yaşlanmak

Birkaç şiir okuyup 

Eski defleri karıştırmak için

Yanımda sigaram ve şarabım da olacak

Maziye bakıp kadeh kaldıracam 

Eski anılara diyerek...', 'Son perdeyi de kapatıyorum  Alkışlarla, yaşlarla Yorgun bedenimle yaşlanmak Birkaç şiir okuyup  Eski defleri karıştırmak için Yanımda sigara...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/serefe-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-deli-kerem-cxzeu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlığımla beraberim 

Sessiz ve yalnız..

Ufak bir ateş var 

Tüten sigaramın ucunda..

Bir damla yaş var 

Süzülen yanaklarımda....

Çaresiz ve korkmuş....

Hayattan değilse de 

Özlemekten, yalızlıktan, 

Sensizlikten korkmuş.

Seni isteyip bulamamaktan.

İşte özlüyorum seni

Benim küçük kedim.', 'Karanlığımla beraberim  Sessiz ve yalnız.. Ufak bir ateş var  Tüten sigaramın ucunda.. Bir damla yaş var  Süzülen yanaklarımda.... Çaresiz v...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozlem-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-deli-kerem-h8q1h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman akıp geçer 

Sevdalar tükenir 

Göz yaşları akar ya 

Her sondan Bir başlangıç 

Her acıdan 

Bir umut doğar ya hani 

Benim ki de öyle işte

Hayatın ipini çekerken 

Sevmeye tövbe ederken 

Unuttum yaşadıklarımı 

Yeniden yaşama 

Sevdalarıma döndüm 

Küçük bir kediye 

Masum bir kıza tutuldum', 'Zaman akıp geçer  Sevdalar tükenir  Göz yaşları akar ya  Her sondan Bir başlangıç  Her acıdan  Bir umut doğar ya hani  Benim ki de öyle işte...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/donus-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyirlik değil', 'seyirlik-degil-deli-kerem-nv12d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seyirlik değil

Ömürlük olsun dedik

Bunu yapmayı beceremedik

Dağlara, taşlara yazdık

Öylece kalakaldık

Aşk mı yoktu sevgimi eksikti

Hiç bilemedik

Tanrının lütfumuydu düşünmedik

Belki sen değil ama

Ben sordum dalgalarla kuşlara

Nedir bu diye

Oyunmu rüyamı 

Yoksa çektiğim cezamı?', 'Seyirlik değil Ömürlük olsun dedik Bunu yapmayı beceremedik Dağlara, taşlara yazdık Öylece kalakaldık Aşk mı yoktu sevgimi eksikti Hiç bilem...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seyirlik-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-deli-kerem-ett9u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava soğuyor

Bugün birkaç damla

Yarın ise fırtına 

Sonraları beyaz melekler

Ellerde eldiven

Ayaklarda çizmeler 

Bitti bizim çıplak günler', 'Hava soğuyor Bugün birkaç damla Yarın ise fırtına  Sonraları beyaz melekler Ellerde eldiven Ayaklarda çizmeler  Bitti bizim çıplak günler...', ARRAY['Türk Edebiyatı','Şiir','Deli Kerem']::text[], 8.5, '{"poet":"Deli Kerem","poet_slug":"deli-kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-figen-kiroglu-izrfb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana rüya olduğunu söylemiştim

Biz rüyalarımızı gerçek yapamadık sevgili

Olmadı yapamadık 

En uzun rüya sekiz  saniyeymiş biliyor musun? 

Oysaki anlatırken rüyalarımızı dakikalarca

Yaşananların çok kısa olduğunu düşünmek istemeyiz

Sana rüya olduğunu söylemiştim

Uyandım ben şimdi

Ama gözlerimi açmadım hala, sıcacık yatağımdayım

İnanmak istemiyorum rüya olduğuna

Yaşadıklarımızı düşünüyorum tekrar tekrar

Tekrar dalmak istiyorum rüyalara

Gözlerindeki derinliği görmek ne güzeldi

Ya ellerindeki sıcaklık içimi ısıtırdı

Ama rüyaydı işte hepsi ve ben uyandım

Tekrar uyuyamıyorum istesem de

Belki de artık yataktan kalkma zamanı geldi

Açmalıyım artık gözlerimi

Yeni doğan güne bakmalıyım

Biliyorum dışarısı çok soğuk

Artık sıcaklığında yok yanımda bunu da biliyorum

Ama kalkmalıyım sımsıkı giyinip çıkmalıyım dışarı

Hayata devam etmeliyim kaldığı yerden

Evet kolay olmayacak biliyorum

Özleyeceğim seni...

İşte açabildim gözlerimi gündoğarken

Merhaba dedim yeni doğan güne

Belki gerisi daha kolay kim bilir...

ve

Sana rüya olduğunu söylemiştim...', 'Sana rüya olduğunu söylemiştim Biz rüyalarımızı gerçek yapamadık sevgili Olmadı yapamadık  En uzun rüya sekiz  saniyeymiş biliyor musun?  Oy...', ARRAY['Türk Edebiyatı','Şiir','Figen Kıroğlu']::text[], 8.5, '{"poet":"Figen Kıroğlu","poet_slug":"figen-kiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ruya-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır', 'sabir-hakan-rodop-ryrhg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bırakıyorsun

bugün gidiyorsun

sonsuzluk bizim şehrimiz

en yiğit aşkları 

yaşayan benim

benim uzay 

benim deniz

sen yeni bir güneşe 

kavuştuğun zaman

geri geleceğim

adım sabır benim...', 'Beni bırakıyorsun bugün gidiyorsun sonsuzluk bizim şehrimiz en yiğit aşkları  yaşayan benim benim uzay  benim deniz sen yeni bir güneşe  kav...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sabir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doktor', 'doktor-hebil-akan-rpvvx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Verdiğin merhemler çare değilmiş 

Boş yere sürmüşün yarama doktor 

Gönül birine meyletmiş, eğilmiş 

Ondan gayri çare arama doktor 

O açtı yarayı lokman bivefa 

Bu yüzden ömrümce sürmedim sefa 

Benden ayrılamaz kopmaz bu cefa 

Hep bir sızı girer şurama doktor 

Hemşireyle ilaç yolladın dünde 

Derdime dermanım sanma ki sende 

Öyle bir yara kök saldı ki bende 

Dönüyor, dönecek vereme doktor 

Bu yara yaşıttır sevdiğim günle 

Yıllar var ki yaşar içimde benle 

Narkoza gerek yok yeter ki dinle 

Gerçi söylemesi zor ama doktor 

Gönlümde yaradır dikişsiz yamam 

Ben bu canı asla riske koyamam

Can içinde can var ona kıyamam

Öldürme neşteri vur ama doktor.

Tutmaz ki yamanın üstüne  yama 

Asla yaşamadım böyle muamma 

Sende sevilirsin güzelsin amma 

Aşığım el süremem harama doktor 

Tahliller boşuna mikrop yok kanda 

Nabız belirsizse gönül hicranda 

Hayat belirtisi ararsan canda 

Aslıyı bul yeter kereme doktor', 'Verdiğin merhemler çare değilmiş  Boş yere sürmüşün yarama doktor  Gönül birine meyletmiş, eğilmiş  Ondan gayri çare arama doktor  O açtı ya...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/doktor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Doktor Hanım', 'doktor-hanim-mustafa-engin-karatay-epzik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geç karşıma otur da, n''olur dinle derdimi! .. 

Bir sıkıntı bürüdü, içimi Doktor Hanım... 

Sevdiğim bu gün bâri, bir haber gönderdi mi? 

Bak darlandım iyice, sanki çıkacak canım... 

Bu odanın içine tıkılıp mahsûr kaldım 

Ne gelen var, ne giden; ümîdi mi kestiler? 

Üst-üste On gün geçti, inan hepten bunaldım! 

Hadi, yârim dargınsa; dostlar da mı küstüler? 

Bu sabah ne umutla, yatağımdan fırladım 

Telefon yine suskun; kapı dersen çalmadı 

Lâ havle söyleyerek, son sabrımı zorladım 

Rabbim`den gayri artık, hiç mi kimsem kalmadı? 

Amânsız derde düştüm, sen bâri tesellî ver! 

Eriyorum gün be gün, üste gönül yarası 

Uzakta Cânânım`a, bir de sen haber gönder! 

Musallâya varmadan, her hâl; son yer burası 

Bu beyaz elbiseyi, niye giydim ki böyle? 

Artık vakit tamam mı; geriye dönüş yok mu? 

Ne kadar ömrüm kaldı, çekinme haydi söyle! 

Dört Ay mı, Altı Ay mı; yoksa onlar da çok mu? 

Şu masanın üstünde, kâğıt-kalem olacak 

Ben diyeyim, sen de yaz; davran, zaman geçmeden! .. 

Fenâlaştım iyice, İki gözüm dolacak 

Yetiştir Nâlânım`a; henüz tezken, göçmeden... 

Amman her şeyden evvel; yaz yürekten selâmı! 

Merhâmete gelir de, belki anlar hâlimi 

Ondan sonra da aktar, keder dolu kelâmı! 

Anlasın, bellesin ki; tükettim mecâlimi... 

Olur da geldiğinde, ölmüş olursam şâyet; 

Bu cansız bedenime, son bir kere dokunsun! .. 

Bekliyorum Ukbâ''da kendisini nihâyet, 

Alenî arz-ı hâlim, aynen böyle okunsun! .. 

10.10.2001  Garmisch-P.  22: 10', 'Geç karşıma otur da, n''olur dinle derdimi! ..  Bir sıkıntı bürüdü, içimi Doktor Hanım...  Sevdiğim bu gün bâri, bir haber gönderdi mi?  Bak ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/doktor-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aah Ah', 'aah-ah-hebil-akan-0rn65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlamak hicrana çare olsaydı 

 Nil nehri gözyaşım olsa yanmazdım 

 Çiçeğimi şayet Mevla yolsaydı 

 Aşkın hazanında solsa yanmazdım 

 Ahdinde vefalı sandığım güzel 

 Allah''ın emriyle yandığım güzel 

 Güvenip sırtımı döndüğüm güzel 

 İhanet etmeyip ölse yanmazdım 

 Aşkın heyecanıyla atan bu yürek 

 Zulmünle ağlıyor, utan bu yürek 

 Feryadı figana katan bu yürek 

 Söylesen günahın, bilse yanmazdım 

 Bilmem nasıl bir alev düştü bu öze 

 Küllenen yaramı döndürdün köze 

 Hasretinle nasır bağlayan göze 

 Yaş yerine kanlar dolsa yanmazdım 

 Bir keskin hançeri alıp eline 

 Vurup duruyorsun daha derine 

 Saplayıp bıraktın ''''kendi yerine'''' 

 Bir vakitsiz ecel gelse yanmazdım', 'Ağlamak hicrana çare olsaydı   Nil nehri gözyaşım olsa yanmazdım   Çiçeğimi şayet Mevla yolsaydı   Aşkın hazanında solsa yanmazdım   Ahdinde...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aah-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Tanımı', 'yalnizligin-tanimi-hebil-akan-cyxsz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karamsar gözlerimde yitti bayramlar, 

Mazinin arkasına gitti bayramlar, 

Ne dost yüzü gördüm, ne bir sevgili.

Yine yapayalnız bitti bayramlar.', 'Karamsar gözlerimde yitti bayramlar,  Mazinin arkasına gitti bayramlar,  Ne dost yüzü gördüm, ne bir sevgili. Yine yapayalnız bitti bayramla...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizligin-tanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-hebil-akan-1gwve', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'karanlıksın geceler kadar karanlık

aydınlık bakışsın sabahlar kadar, 

hiçbir sevap mutlu etmedi beni 

senle işlediğim günahlar kadar.', 'karanlıksın geceler kadar karanlık aydınlık bakışsın sabahlar kadar,  hiçbir sevap mutlu etmedi beni  senle işlediğim günahlar kadar....', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozler-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırça Saray', 'sirca-saray-hebil-akan-w5ox6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşktan yana neler neler yitirdi 

 Küstü kaderine darıldı gönül 

 Vuslattan ümidini kesti bitirdi 

 Hasretin köşküne kuruldu gönül 

 Ümitsiz bir sevda, saldı hülyaya 

 Yine şafak yüzün geldi hülyaya 

 Yeşil gözlerinde daldı hülyaya 

 Bir ceylan misali vuruldu gönül 

 Bağlayıp hicranı gönül telime 

 Hasret yaşlarını verdin elime 

 Avutmuyor artık hiçbir kelime 

 Çırpınmaktan bitap yoruldu gönlüm

 Yoksun diye oturup ağlayacaktım 

 Ümitsiz çaresiz yollara baktım 

 Son çare diyerek fallara baktım 

 Falında ayrılık görüldü gönül 

 Şahtı sultanını görmek isteyen 

 Görüp payitahtın vermek isteyen 

 Sevdanla saltanat sürmek isteyen 

 Bir sırça saraydı kırıldı gönül', 'Aşktan yana neler neler yitirdi   Küstü kaderine darıldı gönül   Vuslattan ümidini kesti bitirdi   Hasretin köşküne kuruldu gönül   Ümitsiz ...', ARRAY['Türk Edebiyatı','Şiir','Hebil Akan']::text[], 8.5, '{"poet":"Hebil Akan","poet_slug":"hebil-akan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sirca-saray-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur ve Sen', 'yagmur-ve-sen-ufuk-cebe-xe8gq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine Sensiz bir İstanbul akşamında, 

Yine yağmur yağıyor..

Yağıyor yanlızlığımın ve sensizliğimin üzerine..

Her yağan yağmur damlasında, 

Bir yanlızlığım, 

Bir sensizliğim var aslında..

Kimi yağmur tanelerim, 

Bir kavuşma mucizesi gibi düşüyor yuzume, 

Ve bir imkansızlık gibi süzülüp gidiyor, 

Göz yaşlarım ile birlikte, 

Sensizlikler ve yanlızlıklar alemine..

Yağmurları seviyorum biliyorsun, 

Belki de sadece Yağmur yağdığında, 

Göz yaşlarım gözükmüyor diye..

Yada her damla, 

Her yağmur, 

Seni ve Sana olan Sevgimi, 

O masum, o tertemiz haline getiriyor diye..

Sizin orda yağmur yağıyormu bilmiyorum, 

Ama her yağmurda beni düşün, 

Düşün her damladaki sensizliğimi, 

Düşün her damladaki Yanlızlığımı, 

Yüzüne gelen damlaları silme sakın, 

Bırak onlar yüzünde kalsın, 

Çünkü yüzündeki her damla; 

Senin tekrar bana dönme İhtimalin..

Çünkü onlar, 

Benim sana gönderdiğim, 

Göz Yaşlarım..

Benim Her yağmurda seni düşünüp, 

Senin yanlızlığında ve 

sensizliğinde yaptığım gibi, 

Belki bir gün yürürüz seninle, 

Islanırız iliklerimize kadar, 

Islanırız belkide...

Yağmurların altında, 

El ele..', 'Yine Sensiz bir İstanbul akşamında,  Yine yağmur yağıyor.. Yağıyor yanlızlığımın ve sensizliğimin üzerine.. Her yağan yağmur damlasında,  Bi...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Cebe']::text[], 8.5, '{"poet":"Ufuk Cebe","poet_slug":"ufuk-cebe","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yagmur-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Anda', 'su-anda-gursel-colak-j6g6j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilirmisin şu anda en çok ne isterim? 

Dertlerini bilmek ve üzüntülerine son vermek isterdim

Bilirim çarelerini bulmak çok zordur

Ama denememle kaybedecek hiç birşeyim yokki

Keşke anlatabilseydin derdini bana

Ortak olurdum dertlerine sıkıntılarına

Çareyi susmakta arayarak yorulursun

Dök içini belki çaresini bulursun

İçine kapanarak eritirsin kendini

Değermi sanıyorsun üzülmeye bu hayat

Bilirim dışarıdan herşey kolay gözükür

Başkalarının dertleri gelir içini çürütür

Bilirmisin şu an ne düşünüyorum? 

Yanında olabilmeyi ve konuşmayı

Belki birazda olsa seni rahatlatmayı

Boğulmak üzere olduğun dertlerden kurtarmayı', 'Bilirmisin şu anda en çok ne isterim?  Dertlerini bilmek ve üzüntülerine son vermek isterdim Bilirim çarelerini bulmak çok zordur Ama deneme...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-anda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sir Şehirde Kaybolmak', 'sir-sehirde-kaybolmak-sezgin-gungor-7p9kj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sehrin her aksam yanan pencerelerinde, 

Bir elem yukudur camlardaki bugu, 

Yar zulfuyle oynasir gibi iskelelerinde, 

Gidenlerle kederi, gelenlerle sevinci tasir her vapuru, 

Bu sehrin Marmara yi kucaklayan avuclarinda, 

Bir sevda tufanidir sahilleri doven, 

Firari bir mahkumu kovalayan erler gibi sokaklarinda, 

Gercegin ejderha sabridir ruhumda gezinen, 

Bu sehrin goge cekilmis tepelerinde, 

Bir rahmet esintisidir ruzgar, 

Dayanilmaz bir gurbeti doldurarak heybelerime, 

Bu sehirdir gezdiren beni, diyar diyar, 

Beni bu sehirden sor sevgilim, 

Bu sehirde korkuyu bilen bir cambazim ben, 

Bu sehirde basladi bitmeyen elemim, 

Bu sehirdir beni Iki Cihan arasinda titreten.', 'Bu sehrin her aksam yanan pencerelerinde,  Bir elem yukudur camlardaki bugu,  Yar zulfuyle oynasir gibi iskelelerinde,  Gidenlerle kederi, g...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Güngör']::text[], 8.5, '{"poet":"Sezgin Güngör","poet_slug":"sezgin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sir-sehirde-kaybolmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Nasihatı', 'dost-nasihati-tahir-paker-jeeir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son sözümü söylemedim

Dinle beni, dur gitmeden

Sana bir dost nasihatı

Vereceğim al gitmeden

Karanlıklar yolun olur

Bu ayrılık senin için

Sonra pişman olursun

Ah çekersin için için 

Bir köşede kalırsın da

Halin nedir soran olmaz

Sana böyle benim gibi

Nasihatta veren olmaz

Bir bakarsın geçmiş yıllar

Tekrar başa dönüş olmaz

Herkes güler geçer sana

Benim gibi yanan olmaz', 'Son sözümü söylemedim Dinle beni, dur gitmeden Sana bir dost nasihatı Vereceğim al gitmeden Karanlıklar yolun olur Bu ayrılık senin için Son...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-nasihati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Ne', 'kime-ne-sakir-askan-a2u8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu zalim sevdayı ben kendim seçtim

Bağrıma bastığım taştan kime ne

Uzaktan uzağa ben kendim sevdim

İçime döktüğüm yaştan kime ne

Gönül benim, sevda benim

Bu yıkılan dünya benim

Zehir olsa her nefesim

Seviyorum, seviyorum kime ne

Hasretin dağları çökse başıma

Yine söz söyletmem büyük aşkıma

Çekilin başımdan Allah aşkına

Ben sevdim, ben yandım kime ne', 'Bu zalim sevdayı ben kendim seçtim Bağrıma bastığım taştan kime ne Uzaktan uzağa ben kendim sevdim İçime döktüğüm yaştan kime ne Gönül benim...', ARRAY['Türk Edebiyatı','Şiir','Şakir Askan']::text[], 8.5, '{"poet":"Şakir Askan","poet_slug":"sakir-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kime-ne-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesizlik', 'kimsesizlik-kemalettin-kamu-wlnpl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır ki bir kılıcım kapalı kında,

Kimsesizlik dört yanımda bir duvar gibi; 

Muzdaribim bu duvarın dış tarafında, 

Şefkatine inandığım biri var gibi. 

Sanıyorum saçlarımı okşuyor bir el, 

Kıpırdamak istemiyor göz kapaklarım; 

Yan odadan bir ince ses diyor gibi gel! 

Ve hakikat bırakıyor hülyamı yarım. 

Gözlerimde parıltısı bakır bir tasın, 

Kulaklarım komşuların ayak sesinde; 

Varsın yine bir yudum su veren olmasın, 

Baş ucumda biri bana ''su yok'' desin de!', 'Yıllardır ki bir kılıcım kapalı kında, Kimsesizlik dört yanımda bir duvar gibi;  Muzdaribim bu duvarın dış tarafında,  Şefkatine inandığım b...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin-kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimsesizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-yasar-kemal-seckin-z1uyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülümse bitsin karanlık

Gülümse karamsarları şaşırt

Gülümse güller açsın yüzünde

Gülümsemenle yayılsın ışık

Dünyayı ısıtamasan da güneş gibi

Çevreni ısıt', 'Gülümse bitsin karanlık Gülümse karamsarları şaşırt Gülümse güller açsın yüzünde Gülümsemenle yayılsın ışık Dünyayı ısıtamasan da güneş gibi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gulumse-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-sadik-orel-rxpvn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geleceksen bana gel, kendin ol degişmeden

Yalancı aşk olmasın beterdir ölümlerden

Yeminler olsun sana şu topraha girmeden 

Gözlerine doya doya bakacagım birtanem...', 'Geleceksen bana gel, kendin ol degişmeden Yalancı aşk olmasın beterdir ölümlerden Yeminler olsun sana şu topraha girmeden  Gözlerine doya do...', ARRAY['Türk Edebiyatı','Şiir','Sadık Orel']::text[], 8.5, '{"poet":"Sadık Orel","poet_slug":"sadik-orel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/birtanem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-sadik-orel-97weg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazık sana verdiğim sevgime...

Yazık senin için döktüğüm göz yaşlarına...

Yazık seni düşünerek uyuyamadığım uykusuz gecelere...

Yazık senin için devirdiğim kadehlere...

Yazık bana yazık seni gelecegim olarak düşündügüm için yazık...', 'Yazık sana verdiğim sevgime... Yazık senin için döktüğüm göz yaşlarına... Yazık seni düşünerek uyuyamadığım uykusuz gecelere... Yazık senin ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Orel']::text[], 8.5, '{"poet":"Sadık Orel","poet_slug":"sadik-orel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yazik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-deral-baran-ufr3r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzün de keder, 

Gözlerinde

Yokluğumu görmek istemem.

Biliyorsun, 

Yürüdüğüm bütün yollar 

Yüzüne çıkıyor.

Girdiğim çıkmaz bir sokağın 

Alıngan bakışlarında.

Deral 

14 Ekim 2002 İst.', 'Yüzün de keder,  Gözlerinde Yokluğumu görmek istemem. Biliyorsun,  Yürüdüğüm bütün yollar  Yüzüne çıkıyor. Girdiğim çıkmaz bir sokağın  Alın...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cikmaz-sokak-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-zubeyir-sasmaz-bdung', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca kitap okudum, 

az bucuk, kelime de biliyorum.

seni, 

güzelliğini, 

hele gülüşünü, 

anlatacak kelimeyi, 

ya ben bilmiyorum.

ya da o kelime henüz bulunmadı diyorum.

Canım benim.', 'Bunca kitap okudum,  az bucuk, kelime de biliyorum. seni,  güzelliğini,  hele gülüşünü,  anlatacak kelimeyi,  ya ben bilmiyorum. ya da o kel...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bilmem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hediye', 'hediye-zubeyir-sasmaz-wlx6u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana güzel hediyeler alsam,   ister misin? 

bilmem ki; benim sevdiklerimi sever misin.? 

kulağına küpe alsam, nasılını istersin

Bir kolye mi, Yüzük mü, bilezik mi, 

Bilmem ki en çok neyi seversin

bilirim, aslında ne alırsam beğenirsin.

Lakin  en çok sevdiğini almak isterim.

Seni hep güler yüzlü, neşeli görmek isterim.

Bunu için seni mutlu etmek isterim.

Allah ömrümden alsında sana katsın isterim.

canım benim', 'Sana güzel hediyeler alsam,   ister misin?  bilmem ki; benim sevdiklerimi sever misin.?  kulağına küpe alsam, nasılını istersin Bir kolye mi...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hediye-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan', 'sultan-zubeyir-sasmaz-0irbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen Sadece  istediğini söyle

Senin için yıkılmıyorsa dağlar

Seni seviyormuşuz, ne önemi var.

Sen kalbimizin tek sultanısın

İsteklerin, arzuların, emir değilse

yerine getirilmiyorsa, 

Sen ne biçim sultansın.

Biz ne biçim kuluz.

Sen söyle, her isteğin yerine gelsin.

Yoksa, kulluğumuz, nasıl bilinsin.', 'Sen Sadece  istediğini söyle Senin için yıkılmıyorsa dağlar Seni seviyormuşuz, ne önemi var. Sen kalbimizin tek sultanısın İsteklerin, arzul...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sultan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Yanımda Olsa', 'hep-yanimda-olsa-zubeyir-sasmaz-1jtc6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep yanımda olsa, 

Ben çalışırken,  o bana baksa.

Yorulduğumda, ellerimi ovsa.

Zihnime giren kötülükleri, o kovsa.

Canım sıkıldığında, tatlı, tatlı konuşsa.

Hep yanımda olsa, 

Bazen yanağıma  bir buse kondursa.

Ellerimi sevgiyle, sıkı sıkı tutsa

Yeni açmış güller misali, mis gibi koksa.

Karanlık gecelerime, güneş gibi doğsa

Hep yanımda olsa

Bana Turfanda meyveleri  sunsa

En iyi bildiği  aşk şiirlerini okusa

Yüzünde hep o  güzel gülüşü olsa.

Ne isterdim ki başka, o burda olsa.

canım benim.', 'Hep yanımda olsa,  Ben çalışırken,  o bana baksa. Yorulduğumda, ellerimi ovsa. Zihnime giren kötülükleri, o kovsa. Canım sıkıldığında, tatlı...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hep-yanimda-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenmemiş Ne Kaldı', 'soylenmemis-ne-kaldi-zubeyir-sasmaz-0j3xj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin  için, söylenecek sözler kaldı mı daha.

Dağarcık bittide, Yürekteki yangın sönmedi daha.

Sözler bitti de, bir gülüşün bile, anlatılamadı daha

Anlatabilmek için, Yeni diller öğreneyim daha.

Sevgiyi, seni,  iyiliğini, güzelliğini

Kağıtlara aktarmaktı amaç.

Sevgi  denizinde, sana doğru 

atamadım bir kaç kulaç.

Hep seni anlatmak istedim.

Senin gibi birinin bu dünyadan geçtiğini 

herkese duyurmak istedim.

Ama kimliğini hep gizledim.

Sadece, güzelliğini, gülüşünü

İnsanlığını anlatmak istedim.

(beceremesem de)', 'Senin  için, söylenecek sözler kaldı mı daha. Dağarcık bittide, Yürekteki yangın sönmedi daha. Sözler bitti de, bir gülüşün bile, anlatılama...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soylenmemis-ne-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürümek İstiyorum', 'yurumek-i-stiyorum-zubeyir-sasmaz-kwehb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen varsan, aklımda; yürümek istiyorum

Sen geldikçe aklıma, koşardım, 

Trenlerle, sirkeciden beri yarışırdım.

Sonra artezyende, yüzümü yıkarken

Sen Trenden inerdin, 

benim orada çoktan olduğumu zannederdin.

Halbuki Sen sirkeciden, ben sultanahmet''ten

Sen  tren de, ben paralelde koşar gelirdim.

Sabahları erkenden kalkıp, 

Topkapı''ya elim sende dedikten sonra

Dönerdim eve, giderdim okuluma

Hala

Sen takılınca aklıma; yürümek istiyorum

Koşmak, yarışmak.

Seninle karşılaşmak istiyorum.', 'Sen varsan, aklımda; yürümek istiyorum Sen geldikçe aklıma, koşardım,  Trenlerle, sirkeciden beri yarışırdım. Sonra artezyende, yüzümü yıkar...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yurumek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterim', 'i-sterim-zubeyir-sasmaz-he3xd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecemde, gündüzümde, her an yanında olmak isterim.

Her anımda, seninle ağlamak, seninle gülmek isterim.

Gücüm yetmez, ama seninle birlikte hizmet etmek isterim.

Yatağına kahvaltı getirmek, hep el üstünde tutmak isterim.

Neşene, gülüşüne, sevincine, ortak olmak isterim.

Sen varsan eğer, bu hayat yaşamağa değer derim.

Sen yoksan, Bu dünyada ne işim var benim derim.

Mutlu olacağını  bilsem,  canımı vermek isterim.

Sana söyleyecek daha nelerim var bilmeni isterim

Bir gelsen,  günlerce anlatacaklarımı  bir dinlesen

Seni kim, ne kadar, nasıl seviyormuş bir farketsen

Canımı vermek isterim, mutlu olacağını  bilsem, 

Canım benim.', 'Gecemde, gündüzümde, her an yanında olmak isterim. Her anımda, seninle ağlamak, seninle gülmek isterim. Gücüm yetmez, ama seninle birlikte h...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isterim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesab-ı Mahşer', 'hesab-i-mahser-hakki-hakan-kaya-4ils1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vatanını, milletini satanın, 

Yolunu mevlam biliyor.

Pişmiş aşa su katanın, 

Yolunu mevlam biliyor.

Ömrünce paraya tapanın, 

Doğrudan eğriye sapanın, 

Gece muhakemesiz yatanın, 

Yolunu mevlam biliyor.

Yetimin hakkını yiyenin, 

Kibir gömleği giyenin, 

Vurun kahpeye diyenin, 

Yolunu mevlam biliyor.

Başkasına iftira atanın, 

Hırsın maskesini takanın, 

Gönül ateşini yakanın, 

Yolunu mevlam biliyor.

Hakkı, hukuku defterinden silenin, 

Zulmü kendine hak bilenin, 

Dardaki komşuya gülenin, 

Yolunu mevlam biliyor.

Ana baba kalbi kıranın, 

Kardeş, bacıya gönül koyanın, 

Aileye hayırsız olanın, 

Yolunu mevlam biliyor.

Bu bedeni, can veren alır, 

Ruh gider, geriye toprak kalır, 

Mekanım ahrette ne olur? 

Yolumu mevlam biliyor.', 'Vatanını, milletini satanın,  Yolunu mevlam biliyor. Pişmiş aşa su katanın,  Yolunu mevlam biliyor. Ömrünce paraya tapanın,  Doğrudan eğriye...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hesab-i-mahser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Name', 'bir-garip-name-yakup-besinci-wii5p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bahar kokan güller var solduramadığım

Sessiz ve derin sesler var duyuramadığım

Gözle görülmez tutulmaz hisler var anlatamadığım 

Anlatsam anlaşılmaz bir garip name

Sabah seherde akşam rüzgarda

Hem kışta gelir hem baharda

Önüne binbir gizem katarda

Sorsam söylenmez bir garip name

Bir kurt bakışı bir bebek gülüşünde

Bir kız hayali bir erkek düşünde 

Yağmurun toprağı her öpüşünde

Çiğnesem ezilmez bir garip name

Bir seda anlatır dilimdeki ezgi

Çağlayan gibi akar bu sonsuz sezgi

Bu name ruhunun kalbindeki çizgi

Anlayan anladı bir garip name', 'İçimde bahar kokan güller var solduramadığım Sessiz ve derin sesler var duyuramadığım Gözle görülmez tutulmaz hisler var anlatamadığım  Anla...', ARRAY['Türk Edebiyatı','Şiir','Yakup Beşinci']::text[], 8.5, '{"poet":"Yakup Beşinci","poet_slug":"yakup-besinci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-garip-name-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-yakup-besinci-8nvpa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şafak vakti açan ufuklar gibi

Sonsuz bir ben dolar içime

Heyecandan dudak uçuklar gibi 

Sonsuz bir sen dolar içime', 'Şafak vakti açan ufuklar gibi Sonsuz bir ben dolar içime Heyecandan dudak uçuklar gibi  Sonsuz bir sen dolar içime...', ARRAY['Türk Edebiyatı','Şiir','Yakup Beşinci']::text[], 8.5, '{"poet":"Yakup Beşinci","poet_slug":"yakup-besinci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçme Kardeşim', 'i-cme-kardesim-sadik-altinkaynak-sx1nq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sayılmakla bitmez çoktur zararı

Söyle bana varsa bir tek yararı

Yakın eder uzak iken mezarı

Sigara muzurdur içme kardeşim

Bütün bedeninde yapar hasarı

Ciğerin kararır dişler sapsarı

Ömrünü törpüler ölüm hızarı

Hayatta ölümü seçme kardeşim

İçersen yalnız iç gelme yanıma

Sen canına kıydın kıyma canıma

Dumanın kokun siner her yanıma

Buralardan gelip geçme kardeşim

Sakın sözlerime gücenme e mi? 

Hafife alıp ta bu sözlerimi

''İçen öldü, içmeyen ölmedi mi? ''

Derler... Sen yine de içme kardeşim

Sadık sadakatle söyler sözünü

Sen sen ol zehirleme öz özünü

Ecel gelip kapatmadan gözünü

Kefeni elinle biçme kardeşim', 'Sayılmakla bitmez çoktur zararı Söyle bana varsa bir tek yararı Yakın eder uzak iken mezarı Sigara muzurdur içme kardeşim Bütün bedeninde ya...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icme-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haine', 'haine-omer-cidik-e8fur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir yerdeyim ki

Ne bir güşüşün nede sesin var

Ne bir ses nede bir nefes hiç birsey

Hasretim tekbir gülşüne birde ellerine

Nasıl zaman geçmiş dizlerinde

Ellerin saçlarımı neçabuk bırakmış

Şimdi karanlıktayım gözlerin kadar derin

Sen hiç baktın mı aynaya

Gözlerinle gözlerine baktınmı hiç

Korktun mu içindeki kini görünce

Ellerin yüzünü kapattımı sonra

Gözyaşların ellerinde kaldımı hiç

Rüzgarda süzülüp uçan bir yaprak 

Alıp götürdümü seni eski yıllara

Yıldızlara bakıp gördünmü

Mutluluk ne kadar uzak

Ellerinle bastırınca kalbimin üstüne

Senin için attığını düşündünmü hiç

Artık bir karanlıktayım

Gökyüzünün yıldızları yok

Ölüm kadar çabuk geldi ayrılık

Meğer azrail senmişsin

Peki neydi yanlış olan

İdamıma sebep netdi

Ellerim mi yanlış yazdı mektuplarımda 

Yoksa seni seviyorum aşkım diyen dilimmi

Söyle neydi tüm bunlara sebep

Yazmadıysam şiirlerimde mutluluğu sebep sensin

Şimdi yorgunum bu kalbi tasımaktan

Ve görmekten hayalini

Öldürmek kolay zor olan sevmekmiş

Sen öğrettin bana

Ama birseyi unuttun her nasılsa

Eden bulur gülüm eden bulur

Bak nasılda ağlıyorsun şimdi düşünüyorsun

Verdiğin acılar nasılda dönüyor şimdi fazlasıyla

Seni ben severdim ancak böyle ölümüne

Ve ölümünede sevdim işte

Ben akıllandım senden yana payımı aldım

Bak işte geldi sıran

Ben bırakıyorum bütün dertleri

Birazcıkta sen dayan

Yok sakın üzülme kurtarır seni sevdiğim diyenler

Evet kandır avut hadi

Bekle aydınlanır belki karanlığın

Bekle seni beklediğim gibi 

Bekle ölümü beklediğim gibi bekle artık...', 'Öyle bir yerdeyim ki Ne bir güşüşün nede sesin var Ne bir ses nede bir nefes hiç birsey Hasretim tekbir gülşüne birde ellerine Nasıl zaman g...', ARRAY['Türk Edebiyatı','Şiir','Ömer Çıdık']::text[], 8.5, '{"poet":"Ömer Çıdık","poet_slug":"omer-cidik","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/haine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklarda', 'uzaklarda-omer-cidik-117nj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklarda aşklar 

Böyle yasanırlar

Gündüzleri dostlar

Geceleri hayaller 

Girer akıla

Çılgınlık yapılır 

Gezip tozulur

Ama unutulmaz uzaktaki sevgili

Hep hayali kurulur

Dua edilir

Uğruna can feda edilir

Değermi değmez mi bilinmez ama

Uzaktan sevildimi böyle sevilir', 'Uzaklarda aşklar  Böyle yasanırlar Gündüzleri dostlar Geceleri hayaller  Girer akıla Çılgınlık yapılır  Gezip tozulur Ama unutulmaz uzaktaki...', ARRAY['Türk Edebiyatı','Şiir','Ömer Çıdık']::text[], 8.5, '{"poet":"Ömer Çıdık","poet_slug":"omer-cidik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uzaklarda-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Derdi ki', 'kim-derdi-ki-omer-cidik-3gsyi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kim derdiki  biz ayrılacağız

Ayrılıpta mutlu olacağız

Birbirimizi arayıp sormayacağız

Kimderdiki kim derdiki biz ayrılacağız

Aşkı başkalarında bulacağız

Belki birdaha karşılaşmayacağız', 'Kim derdiki  biz ayrılacağız Ayrılıpta mutlu olacağız Birbirimizi arayıp sormayacağız Kimderdiki kim derdiki biz ayrılacağız Aşkı başkaların...', ARRAY['Türk Edebiyatı','Şiir','Ömer Çıdık']::text[], 8.5, '{"poet":"Ömer Çıdık","poet_slug":"omer-cidik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kim-derdi-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canın Sağ Olsun', 'canin-sag-olsun-ceyhun-yilmaz-25hvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Günlerdir açım...

Boğazım kurudukça gözyaşlarımı içiyorum

Derdim acıyı sevdi...hem de çok sevdi

GİTMEDİ! 

İçimde seni öldürürken bebeğim bedenim öldü...

SENİN CANIN SAĞ OLSUN!', 'Günlerdir açım... Boğazım kurudukça gözyaşlarımı içiyorum Derdim acıyı sevdi...hem de çok sevdi GİTMEDİ!  İçimde seni öldürürken bebeğim bed...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/canin-sag-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ceyhun-yilmaz-qtva6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki güneş geçti bir gece

Biraz yağmur yağdı bana

Biraz ben yağmura...

Sevdiğim bir şarkı çıktı radyoda

Yarısına ben eşlik ettim

Yarısına gözlerim...

Anlatmak istemiyorum ama

BEN SENİ BURDA ÇOK ÖZLEDİM! ...', 'İki güneş geçti bir gece Biraz yağmur yağdı bana Biraz ben yağmura... Sevdiğim bir şarkı çıktı radyoda Yarısına ben eşlik ettim Yarısına göz...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozledim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşü Yaralım', 'gulusu-yaralim-ahmet-can-akyol-xqrjb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Firari bir serüven benimkisi

Yurdu yok kimliği sınır bozgunu

Öyle bir yürek ki deli mi deli

Hazan mevsimlerde sular yorgunu

Dağları isterim firarlarıma

Yüzüme yel değse fırtına olur

Ateşler taşırım sevdalarıma

Sözüm yemin olsa özüm aşk olur

Düşlerin kanarsa benden sonra

Çocuk haylazlığımı al sen koynuna

Şarkıların rengine yağmur yağarsa

Salma gözlerini uçurumlara

Dağları isterim firarlarıma

Yüzüme yel değse fırtına olur

Ateşler taşırım sevdalarıma

Sözüm yemin olsa özüm aşk olur

Ey esmer hüznünü hicrandan besleyen sevgili

Kendini bana beni yollara sürgün etmeden bil ki

Mavi düşlerine sardığın o acar delikanlı

Seni ve aşkını zehir bir yürekle kuşandı

Ama gün olur ve umutlar da yenilirse kalleş bir kurşuna 

Birlik olup büyüttüğümüz ışıkları söner sanma

Ve unutma gülüşü yaralım

O uslanmaz inadın yarısı sen diğeri ben olduktan sonra

Serüvencin seni nasıl olsa nerede olsa bulur', 'Firari bir serüven benimkisi Yurdu yok kimliği sınır bozgunu Öyle bir yürek ki deli mi deli Hazan mevsimlerde sular yorgunu Dağları isterim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gulusu-yaralim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sen Eden Sevdam', 'beni-sen-eden-sevdam-aydin-kansiray-voeup', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben hep yaşamadığım yaştayım, 

Her gün doğum günüm kutlanır, 

Mayınlarla, toplarla, kahpe kurşunlarla, 

Ve ben, üflerim tenimdeki ateşe

Bir dahaki doğum günüme kadar yakmasın diye.

İçimden bağırarak dilerim yarını.

Bugünden farklı olacak yanını

Ben miydim bütün bunları yaşayan 

Ben miydim gözyaşım olmadan ağlayan, 

Yoksa beni sen eden O ince düşüncemiydi, 

Bu kadar hayata bağlayan.

Adı yasaklarla süslenip, 

Bayrağı kana bulanıp göklere asılmış

Yiğitlerin toprakla anıldığı

Ve anaların gözyaşları ile dolmuş

Yavrularının kanı ile bulanmış

Asi nehirlerin aktığı

Nazlı ceylan yavrusu vatanın evladıyım

İşte bu yüzdendir seni böyle ölümüne sevmem

İşte bu yüzden dir seni vatan gibi sevmem

İşte bu yüzdendir seni toprak kadar yakın bulmam.

Ben ki, çocukluğu yaşatılmayan, 

Ama hep çocuk olmak zorunda olan.

Ben ki, düşünceleri yaşatılamayan, 

Ama hep düşünmek zorunda kalan.

Ve ben ki konuşacak bir dili olmadan

Ama anlatacak çok şeyi bulunan.

Ne yana dönsem fayda yok gelecekten

Ne sana ne ülkeme, 

Sizi seviyorum diyemeden gidiyorum

Ne Anamın nede davamın

Hakkını  ödeyemeden gidiyorum

Rahat bırakıyorum artık dünyayı

Ve seni benliğime hapsederek terk ediyorum

Ruhumun bedenimden çekilişidir

Dünyayı bu kadar hafifleten, 

Ve sana dair yaşadıklarımdır 

Dünyayı bu denli hızlı döndüren...', 'Ben hep yaşamadığım yaştayım,  Her gün doğum günüm kutlanır,  Mayınlarla, toplarla, kahpe kurşunlarla,  Ve ben, üflerim tenimdeki ateşe Bir ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Kansıray']::text[], 8.5, '{"poet":"Aydın Kansıray","poet_slug":"aydin-kansiray","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/beni-sen-eden-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Söz', 'sakli-soz-nevzat-gurmen-27mxt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bana direnen aklını

korkak yüreğini

ellerini, yüzünü

kaçak gözlerini

her şeyinle seni 

en çok 

çılgın öbür yanını', 'bana direnen aklını korkak yüreğini ellerini, yüzünü kaçak gözlerini her şeyinle seni  en çok  çılgın öbür yanını...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sakli-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Yetmedi', 'yillar-yetmedi-nevzat-gurmen-3e68z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'baktın mı kor gibi bakardın, 

arada dalıp dalıp giderdin, 

ıssız gecenin çığlığı gibi susardın.

sessiz tutkunu içimde hissederdim, 

aşkını anlamaya ömrüm yetmedi.

taptım mı ölümüne tapardım.

duyarlığın sınırını arardım, 

coşkudan sağnak olur yağardım.

şehvetle yüreğimde tüterdin, 

seni sevmeye yıllar yetmedi.', 'baktın mı kor gibi bakardın,  arada dalıp dalıp giderdin,  ıssız gecenin çığlığı gibi susardın. sessiz tutkunu içimde hissederdim,  aşkını a...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yillar-yetmedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemanın Nağmeleri', 'kemanin-nagmeleri-salih-ozalasan-yznhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam bir başka çıkıyor

Neden acaba kemancı bu kemanın sesi

Sanki ağlıyor, hıçkırıklı kemanın telleri

Yüreğim yanıyor nedir bunun nedeni

Hani nerde o coşturan şakının

Kanını oynatan şen nağmeleri

Yudum yudum içerdik sohbet ile

Sayende bir dikişte içiyoruz badeleri

Durmadan çalıyorsun nedense

Hep inleyen nağmeleri

Efkarımız zaten başımızdan aşkın

Dağıtır diye geldik kemanın nağmeleri

Hüzünlü geldik belki gönül şenlenir

Bir iki sohbet arada demlenir

Kalkarken biraz olsun ferahlık gelir

Nerde; bugün kemanından akıyor zehir

Gideceğine yüreğime doldu kahır

Aleve düştük yanıyoruz cayır cayır

Çekil artık şöyle kemancı başımdan ayrıl

Efkarı sardı başıma bugün kemanın nağmeleri

Y.Tar.14-10-2002 Saat 15.10', 'Bu akşam bir başka çıkıyor Neden acaba kemancı bu kemanın sesi Sanki ağlıyor, hıçkırıklı kemanın telleri Yüreğim yanıyor nedir bunun nedeni ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kemanin-nagmeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğunu Özlüyorum', 'cocuklugunu-ozluyorum-nevzat-gurmen-ugqhz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir gün annene gitsen diyorum 

oturup beni konuşsan 

eskiden konuştuğun gibi 

çay içseniz birlikte 

başbaşa kadın kadına 

beni anlatsan ona 

yüreğindeki beni 

oturup konışsanız annenle 

eski günlerdeki gibi 

çocukluk odana girip otursan 

-hala duruyor mu bilmiyorum- 

oyuncak bebeklerle oynar mıydın 

-bunu da bilmiyorum- 

çalıştığın masa ya da kalemliğin 

bir hatıra defterin var mıydı 

beğendiğin şiirleri biriktirdiğin bir defter 

kendinle yalnız kalmak gibi 

geçmişi yaşamak yeniden 

bir gün annene gitsen diyorum 

genç kızlığını yaşasan yeniden 

sana söylediklerimi düşünsen 

yıllar önce yazdığım şiirleri okusan 

gerçekten söyler misin 

ne değişmiş bunca zamanda 

yazdıklarım duruyor hala 

annene bunları da anlatır mısın 

benim için de anlatır mısın 

ha bir de 

seni doğurduğu için teşekkürlerimi 

iletir misin annene 

senin çocukluğunu özlüyorum 

seni tanımadan önceki 

ve seni tanıdığım günkü', 'bir gün annene gitsen diyorum  oturup beni konuşsan  eskiden konuştuğun gibi  çay içseniz birlikte  başbaşa kadın kadına  beni anlatsan ona ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cocuklugunu-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Cuma Günü Sıkıntı Partisindeyim...Gel Al Beni', 'bir-cuma-gunu-sikinti-partisindeyim-gel-al-beni-alperen-dagistanli-fqqmv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sabah akşam seni düşünürüm seni...

bir ah çekerim seni ararım seni...

yalnız gecelerde sensiz rüyalarda yaşarım seni...

cehennemlerde yanarım cennette görürüm seni...

cehennemde yanarım beter olurum göremeyince seni...

bir dünya beklerim yolunu gözlerim kefenle sararım seni...

ölüm gelir aklıma sabahsız kalırım göremeyince seni...

gözlerim yanar uykusuz geceler boyu karanlıkta beklerim seni...

seni çok seviyorum seni sevdam der beklerim seni...

bir cuma günü

yanlış bir hüküm yedim

asıldım kalbimden...

bir darağacına götürür

yalnızlık beni, 

sigara dumanıyla

boğdun beni...

yıkılan bir gencin ardından

ağıt yakan 

kadınlar gördüm...

bir sabah

uyanamamak günaha soktu beni...

isyan ederim Allah’a 

O’nun yokluğu şaşırtır beni...

bir hançer var elimde

sensizliğe sapladığım sensin

bir cuma günü...

hayretler içindedir melekler

isyanıma benim, 

kaybolmuş bir 

ufuk ok gibi saplanır

yüreğime...

göremeyince yarin aksini

boy aynasında kalbimin, 

sıkarsan boynumdaki ilmeği

bir can çıkar

sana ait kan çıkar, 

bir ruh çıkar sana dolanmış, 

bir yankı duyulur hicran dağının eteklerinde...

işte, o benim en yanık sesimdir...

adını ağzıma aldığımda

nefesim kesiliyorsa, 

boynumdaki 

ölüm ipine ne gerek var...

boğazıma düğümlenen hıçkırıklar, 

götürecekse beni sana, 

ağlamalıyım, ölmeliyim, 

vurmalıyım 

kendi kendimi kendi kalbimden...

şeytanlar görsün yüzümü

sen bana bakmayınca, 

ateşler öpsün dudağımdan, 

senden kalan gül bahçesini ateşler alsın, 

göğsümde aşktan bir hançer öldürsün beni, 

beynimde hummalar dolaşsın, 

damarlarında dolaşan aşk sıvısının yerine...

sen beni sevmezsen, 

melekler ölsün, 

zebaniler dolaştırsın beni ateş bahçelerinde...

ben razıyım ölüme, 

sen olmazsan yanımda, 

akreplerle yaşamaya kadir olsun bu gece...

cesedimde boğuşan

kötü ruhlar olsun, 

senin ruhunu sıktığımda...

zehirli bir bıçak keskin yüzünü göstersin, 

aşkın en onulmazını yaşadığımda...

kendi yaramı tuzlamalıyım, 

acılar içinde kıvranmalıyım, 

sesini duymazsam...

bir alev kaplasın ruhumu, 

aşk küllerimi savursun zalim rüzgar, 

nefesini hissetmeyeceksem...

göz yaşlarınla yıkanmayacaksa cesedim, 

şeytanlar tükürsün ruhuma...

ben çöllerde susuz kaldım, 

yırtık bir elbise giydim

kefen yerine, 

dolaştım hep ruhunun bahçelerinde, 

bin bir ah, bin bir eyvah içinde...

ateşten bir kolye taktım boynuma, 

o asar beni senin yokluğunda, 

bir damar kesildi, 

her umutsuz kaldığında...

bir yanık türkü söyledim, 

seni ararken cennette...

cehenneme attılar beni, 

rahatsızlık verdim munis ruhlara diye...

senin ruhunu asarken

kalbimin duvarlarına, 

çivi elime battı, kanattı yüreğimi...

bir çizik attım gözlerime, 

bir daha göremezsem seni diye...

kolumdan tutup çekti bir iblis, 

diğer yanımda

inanmadığım melekler...

gerek yok sensizliğe, 

muhtaç değilim sensizliğe, 

isyan ederim sensizliğe, 

aşka inanmaktır benim taatim, 

kalbinde yaşamaktır idealim...

boynumdadır sabahın incisi, 

kaybedersem ölürüm, 

tıpkı hayatta olduğu gibi...

sen sabahımın incisi, 

gönlümün bir incisi, 

deli yarimsin...

umudum, can kuşum her şeyimsin...

mağrur bakışlı, 

ceylanımsın beni...

senin ruhundan yıkanmış ruhum, 

tüm aşkım senden tevarüsmüş meğer, 

aşkım

senin gözlerine bakmamdan ibaretmiş meğer...

çıkar cebindekileri

gözlerimden aldığın inciyi, 

al eline bir bak...

gözü kara bir aşık

bundan sonra neler yaparmış...

aşk boynumun borcu, 

isyanım sermayem...

gözlerindeki boğan bir ifadeyim ben şimdi...

kalbindeki umudumsun sen, 

yalnızlığımın bekçisi, 

ruhumun yaşayan tek elçisi...

bir bayrak taşıyorum sana ait, 

bir kara parçası arıyorum...

beyaz ruhun yaşadığı ülkedeyim şimdi, 

karalara boyanmış kalbim, 

boynumda yanlıştan bir yafta, 

sokak sokak gezdiriyorsun beni şimdi...

ellerin saçlarımda

tutup koparıyorsun beni...

gözlerinde gözlerim 

öldürüyorsun beni...

sabah akşam

bir dolu bir sele götürüyorsun beni...

sonu yok bu aşkın, 

anlamsız direnmek boşuna...

beyaz ruh dediysem sana, 

hadi artık beni yalnızlıktan koparsana, 

bir yaprak gelmek için kalbimden kopar sana, 

bir sebep ver kalbim

sevdayı getir bana!', 'sabah akşam seni düşünürüm seni... bir ah çekerim seni ararım seni... yalnız gecelerde sensiz rüyalarda yaşarım seni... cehennemlerde yanarı...', ARRAY['Türk Edebiyatı','Şiir','Alperen Dağıstanlı']::text[], 8.5, '{"poet":"Alperen Dağıstanlı","poet_slug":"alperen-dagistanli","theme":"Türk Şiiri","is_hero":false,"total_lines":143,"source_url":"https://www.antoloji.com/bir-cuma-gunu-sikinti-partisindeyim-gel-al-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle İşte', 'oyle-i-ste-ozgur-hatem-ku2su', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi, kaldır başını, 

Gözlerime bak! 

Acı, öyle, kılıç gibidir işte, 

İnsan yüreğinden, kılıf arar kendine...

Yasaklanmış sözleri vardır gözlerin, 

Çığlıklarda sessiz kalır yüreğin, 

Fermanın derdi aşktır aslında, 

Bin kere yansa da, küllenmeyeceği ocak arar kendine...

Hadi, kaldır başını, 

Gözlerime bak! 

Yalnıza yar olmak, öyle, yamandır işte, 

Bütün renklerden arınır da sevda, 

Mavi bulutlardan,  otağ arar kendine...

(14/10/2002 Mersin)', 'Hadi, kaldır başını,  Gözlerime bak!  Acı, öyle, kılıç gibidir işte,  İnsan yüreğinden, kılıf arar kendine... Yasaklanmış sözleri vardır göz...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oyle-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dal Erguvan', 'bir-dal-erguvan-ahmet-ozdemir-jxzxl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ulaşırdım dudaklarına ben

Elinde şu erguvanın dalı olsaydım eğer, 

Nice isterik ''oh! ''larla derinden

Burcu burcu içine dolacak

Ve dudaklarından başka renk tanımazdım

Tanımazdım senden başka bahar

İçinde açacak...

Yıldönümünde bu sihirli nisanın

Elverir ki geçeceksin sen, 

Erguvanî şafağında

O parkın ya da bahçenin..

Ve ben; 

Yaşıyorken doruğunu pür heyecanın

Bekleyebilir miydim, 

Bekleyebilir miydim yapraklarımın açılışını? 

''Günaydın meleğim, 

Dudaklarının rengiyle ben geldim...''', 'Ulaşırdım dudaklarına ben Elinde şu erguvanın dalı olsaydım eğer,  Nice isterik ''oh! ''larla derinden Burcu burcu içine dolacak Ve dudakların...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-dal-erguvan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-refik-recep-pelit-anpsc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ak dolan saçlarımda bir tel siyah kalmadı, 

Kurudu göz pınarlarım birdamla yaş kalmadı, 

Ne Elemin ne kederin bir manasıda kalmadı, 

O yar unuttu çoktan bir değerimiz kalmadı.', 'Ak dolan saçlarımda bir tel siyah kalmadı,  Kurudu göz pınarlarım birdamla yaş kalmadı,  Ne Elemin ne kederin bir manasıda kalmadı,  O yar u...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/damla-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Serçe', 'i-ki-serce-eymen-ozcelik-iy6d7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bedenimden arta kalanı

Seven ve sevmeyen

İki serçe taşısın

Sen ile ben gibi 

Hep beraber yaşasın

Bedenimden arta kalanı

İki serçe taşısın

Her zaman ki gibi

Biri hiç, biri hep yaşasın', 'Bedenimden arta kalanı Seven ve sevmeyen İki serçe taşısın Sen ile ben gibi  Hep beraber yaşasın Bedenimden arta kalanı İki serçe taşısın He...', ARRAY['Türk Edebiyatı','Şiir','Eymen Özçelik']::text[], 8.5, '{"poet":"Eymen Özçelik","poet_slug":"eymen-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-serce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Kelebekler', 'olu-kelebekler-cezmi-ersoz-791zz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiçbir sevgi yetmiyordu bize... Başkalarının kalplerinde yarattığımız, ateşlediğimiz sevgilerle yaşayabiliyorduk ancak... Çünkü birileri bizi ilk ve gerçek sevgiden yoksun bırakmıştı... Ve bu boşluk hiçbir aşkla, hiçbir sevgiyle dolacak gibi değildi... Birinden, öbürüne, sonra bir başkası daha... İşte tam bulduk, derken, elimizde soluk, hüzünlü cam kırıkları kalıyordu... 

Sevgi arsızıydık sanki... Doğumumuzla birlikte verilmemiş olan o ilk ve gerçek sevginin yeri hiçbir insanın sevgisiyle dolacak gibi değildi... 

Dünyanı zihnimizde taşıyorduk sanki... Karşılaştığımız, bizi sevsinler, bize bağlansınlar, diye uğraştığımız insanları ayrı birer varlık olarak tanımaya, anlamaya çalışmıyorduk... Onlardan isteğimiz sadece içimizdeki o büyük boşluğu doldurmalarıydı... 

Bu boşluğu doldurmaları için bize hayran, sonsuz sevgili dolu, ve itaatkar insanlar olmaları gerekiyordu... Bir uzantımız olmaları... 

Belki bu güne dek gerçek anlamda hiç varolmadığımız için, kendimizden kurtulup başkalarının hayatlarına, kalplerine girmediğimiz, yüreklerimiz hep bizde kaldığı için çekici, parıltılı insanlardık... O yaralı, o hasta varlığımız çekiyordu sanki insanları bize... Hiç gerçek anlamda yaşamamışlığımız... 

Gerçek anlamda yaşamadığımız için bize yaklaşan insanı önce hiç olmadığı kadar yüceleştiriyor, kafamızda yarattığımız o sahte idollerden birinin yerine koyuyorduk... Çünkü onu olduğu haliyle anlayıp sevmek çaba isterdi... Onu zayıflıklarıyla sevmek bizi kendimizden kuşkuya düşürürdü... Bir insanı zayıflıklarıyla sevmek bize o derin boşluğumuzu hatırlatırdı... 

Bu karşılaşmada içini açmayan, kendinden vazgeçmeyen, adını hiç unutmayan taraf biz olmalıydık... Çünkü içimizi açarsak, kendimizden vazgeçersek, adımızı unutursak içimizdeki o büyük boşluk görünebilirdi... Hiç varolmadığımız... Kendimizi bugüne dek bir başkası için hiç feda edemediğimiz o hiç yaşamamışlığımız ortaya çıkardı... İçimizdeki o katil ortaya çıkardı... Onla yaşamaya mecbur olduğumuz... Mahvolmamak için mahvetmek zorunda olduğumuz... 

Evet... İçimizdeki katil... Çünkü bizi sevenlerin sevgisini onları öldürmek için kullanıyorduk... Onların önce varlıklarını gizleyen perdelerini, kapaklarını, zırhlarını açmalarını sağlıyor, çırılçıplak bırakıyor, sonra en zayıf, en kırılgan yerlerinden zehirli dudaklarımızla öpüyor ve o halde bırakıyorduk... Sonra da bir daha hiç aramıyorduk... Onlardan avuçlarımıza dökülen cam kırıklarına bakıp: Hayır aradığım bu değildi, o da diğerleri gibiydi, beni istediğim gibi sevmedi, deyip bir başkasına gidiyorduk... 

Birkaç gün önce yüceleştirdiğimiz insanları bize koşulsuz bağlandıklarını hissettikleri anda istediğimize kavuşuyor ve onu beklemediği bir anda küçümseyip aşağılıyor, sonra yolumuza devam ediyorduk... Aradığımız o değildi, diyorduk, o uymuyor yarattığımız idolümüze, o içimizdeki boşluğu dolduramazdı diyorduk... 

Öyleyse bir başkasını, bir başkası daha denemeliydik... a ki içimizdeki boşluk dolana dek... Ama dolacak gibi değildi... Bize kendisini sunan her sevginin bir buz kovasına atılmış küçücük bir kor parçası kadar hükmü oluyordu ancak... Ama biz kazanmayı terk etmek sanırken içimizdeki boşluk daha da büyüyordu... 

Bize sevgiyle yaklaşan insanları öylesine çaresiz, öylesine çıplak anlarında terk ediyorduk ki, birçoğu adeta sevme yeteneğini yitiriyordu... Önce bir süre o zehirli ateşle bir başlarına için için yanıyorlar, ateşleri dinerken bize ışıkla açılan kalplerine kasvetli bir gölge iniyor ve ardından içlerine doğru kırgın bir nefretle dönüyorlardı... 

Kimi geceler boşluğumuza aşık ettiğimiz, sonra da yapayalnız bıraktığımız kurbanlarımızın çığlıklarıyla uyanıyorduk.

İşte biz birbirimizle böylesi gecelerden birinde karşılaştık... 

İkimizde birbirimiz için fazlasıyla çekici ve parıltılıydık. Kafamızda yıllardır gezdirdiğimiz idollerin içine hemen yerleştirdik birbirimizi... Sanki daha yüz yüze gelmeden önce böyle bir şeyin olacağını sezmiş gibiydik... İkimizde güçlü, sevecen ve kendimizden emin gözüküyorduk... Fark etmiyorduk daha birbirimizin içindeki o derin boşlukları... Ama birbirimize öyle çekici ve parıltılı görünüyorduk ki içimizdeki boşluklar henüz acı vermeye başlamamıştı... 

İkimizde birbirimizi hiç olmadığı kadar yüceltiyorduk... Henüz, bu aradığım insan değil, bu o değil, aşamasına gelmemiştik. İki karanlık orman birbirini ne kadar severse o kadar seviyorduk işte... Daha önceleri başkalarına yaptığımız gibi, birbirimizi tanımaya, anlamaya, öğrenmeye çalışmıyor, durmadan kendimizi anlatıyorduk... Başkaları için ne kadar önemli ve vazgeçilmez olduğumuzu... Ne çok sevildiğimizi, ama gerçek anlamda bizim sevgimize kimselerin layık olmadığını... Gerçekte kim olduğumuzu, ne olduğumuzu, ne için yaşadığımızı anlamaya çalışmadan birbirimizin aynasında kendimize hayran olup duruyorduk.

Sonra biz değil, söylediklerimiz değil, hayatın kendisini usulca hissettirmeye başladı, başka dünyaların insanı olduğumuzu, çok başka şeyler özlediğimizi... 

İşte o zaman birbirimizi kendimiz için değiştirmeye başladık... 

Kim kimi kendisi için daha uysal, daha itaatkar, daha evcil yapacaktı... Herkes kendisini diğerinden daha kusursuz buluyor, böyle gördüğü için her şeyi kendisinde hak olarak görüyordu... O beni kıskandığı zaman bunu sevgi diye gösteriyor, ben onu kıskandığım zaman bu onun gözün hiç de soylu bir davranış olmuyordu... Durmadan birbirimizde suçluluk duyguları uyandırmaya çalışıyorduk... 

Aramızdaki gizli bir savaş başlamıştı... Birbirimiz için yarattığımız o sahte idoller çatlamaya başlamıştı bir yerlerinden...

Çünkü ne o benim istediğim gibi oluyordu, ne de ben onun istediği gibi... Kimse kendi düzenini değiştirmiyordu. Ben böyleyim beni böyle kabul et, sen bana uy, diyorduk birbirimize durmadan... 

Kimse bir diğerine içini açmıyor, zayıflığını, çaresizliğini, asıl önemlisi o büyük boşluğunu göstermeye yanaşmıyordu.

Zayıflıklarımızı birbirimize göstermemek için usta bir taklitçi gibi kılıktan kılığa giriyor, durmadan benlik değiştiriyorduk... 

Kendimiz için acı çekiyorduk, birbirimiz için değil. Anlamak değil, anlaşılmak istiyorduk. Bu trajik karşılaşma değil, o deva bulmaz dertlerimiz için değil kendimiz için ağlıyorduk, ağladığımız zamanlarda... 

Birbirimizi özlediğimiz için değil, kendimize duyduğumuz o derin hasretle koşuyorduk buluşma yerlerine... 

Yorulmaya, tükenmeye başlamıştık... İkimizin de beklediği o an yavaş yavaş gelmeye başlamıştı... 

Kim kimi en çıplak, en zayıf anında o zehirli öpücüğüyle öpecek ve onu orada bir başına, o en çaresiz anında bırakıp gidecekti... Kim kazandığı anda öbürünü terk edip gidecek ve bir daha aramayacaktı... 

Durmadan birbirimizin en kırılgan, en çaresiz anlarını gözlüyorduk. Benliklerimizi zayıflatmak, güçsüz bırakmak için hiç olmadık sebepler yaratıp birbirimize ayrılık senaryoları hazırlıyor, bu senaryolarda karşımızdakine terk edilmiş rolü veriyor, onun bu roldeki gücünü sınıyorduk, ama bunlar hiçbir işe yaramayınca yeniden bir araya geliyorduk.

Kimse yenik ayrılmak istemiyordu... Kimse bu beraberlikte katilinden, kazanma hırsından ve adından vazgeçmek istemiyordu..

Bu oyunları oynarken, kanlarımızı kimsesiz gecelere akıtırken gizliden gizliye birbirimize bağlandığımızı anlayamıyorduk bile..

Çünkü asli rollerimiz vardı bizim... Kazandığımızı anladığımız anda terk edip gitmekti bu... İçimizdeki o büyük üşümeye küçücük bir kor parçası daha atıp yürüyüp gitmek.

Nasılsa geride bizi her şeyimizle kabullenip ömür boyu koşulsuz sevmeye hazır insanlar vardı. Kolay kolay boşluğa düşmezdik.

Kim daha önce davrandı bilmiyorum, ama artık şimdi bunun ne önemi var ki....Bir gün birbirimizi o en zayıf, o kırılgan yanlarımızdan öptük... O zehirli öpücüklerimizle... İşte o zaman anladık birbirimize ne kadar çok benzediğimizi.

O zehirli kanlarımız birbirine bulaştı... Hastalıklarımızın birbirine bulaştığını anlamadan kazanmış olmanın verdiği o lekeli gururla bizi koşulsuz sevenlerin yanına koştuk hemen. Birbirimizde açtığımız yaraları sarmaları için... Onlar yaralarınızı sararken biz birbirimizi en derin mezarlara gömdüğümüzü düşünüyor, bu işten yakamızı sıyırmış ve sanki hiçbir şey olmamış gibi her şeye yeniden başlayacağımızı sanırken geceleri ansızın birbirimizin çığlıklarıyla uyanmaya başlamıştık... 

Birbirimizi gömdüğümüz yerden yükselen ve bizi geceleri hiç uyutmayan çığlıklarla.

Bazen bu çığlıklara daha önce terk edip gittiğimiz insanların çığlıkları da karışıyordu... Sanki bizim de kendileri gibi zehirlendiğimizi anlamışlar gibi... 

Benim boşluğum ona geçmiş, onu boşluğun bana geçmişti... 

Artık çaresizliklerimiz, zayıflıklarımız bize ait değildi, bizde sır değildi..

O kendimize sevdalı, kendimize saplantılı kanlarımız birbirine karışmıştı... 

Birbirimizdeki o uzun, o büyük geceyi öpmüştük... Gecelerimiz birbirimize karışmıştı.

Senin yüreğin benim olmuştu, benim yüreğim senin olmuştu... 

İsimlerimiz birbirine karışmıştı... Artık kendimi sen, diye anar olmuştum. Sen kendini ben, diye sorar olmuştun....

Birbirimizi öperken görmüştük o büyük boşluklarımızı... Birbirimizi zehirleyip gidecekken aslında hiçbir yere gidemeyeceğimizi anlamıştık... 

Baksana günler ne çabuk kararıyor artık... Sonra o uzun geceler başlıyor. Asıl dayanılmazı bu... Hep soruyorum kendime şimdi benim gecemle, benim yüreğimle, benim kanımla orada, uzaklarda ne yapıyorsun, diye... Asıl dayanılmazı bu... 

Geceleri çığlıklarını duyup birden uyanıyorum yatağımdan... Çünkü aynı soruları sen de bana soruyorsun, biliyorum... Benim gecemle, benim yüreğimle, benim kanımla orada, o uzaklarda ne yapıyorsun, diye... 

Yüzümün yarısı sende kaldı... Yüzümün yarısı öbür yarısına ağlayıp duruyor şimdi... 

Benim zamanım sen de kaldı, senin zamanın bende kaldı.

Benim geçmişim senin geleceğinde, benim geleceğim senin geçmişinde kaldı... Başlangıçlarım sende kaldı, bitişlerin bende.

Sığındığımız limanlardaki bizi koşulsuz seven hiçbir sevgili teselli edemez artık bizi..

İçimizdeki o büyük boşluğu onlar bilemez ki... Doğumumuzla birlikte verilmesi bize verilmesi gereken o ilk ve gerçek sevginin yokluğunu onlar ne yapsalar kapatamaz ki.

Geceleri birbirimizi gömdüğümüz mezarlardan yükselen çığlıkları onlar duyamaz ki..

Onlar sadece geçecek, derler... Zaten olmayacak bir ilişkiydi, sürmezdi, sürmeyecekti, bekle, zamanla unutursun, derler... 

Yüreklerimizin birbirimizde kaldığını onlar bilemezler ki.

Kiminle öpüşsem sende ki yüreğimi seyrettiğimi, sen kiminle öpüşsen bende ki yüreğini seyrettiğini onlar hissedemezler ki... 

Yokluğunu varlığa çevirirsem, biliyorum o artık ben olmayacağım.

Ama sensiz mahvolmaktansa seninle mahvolurum, daha iyi... 

Sensiz isimsiz kalacağıma seninle isimsiz kalırım daha iyi.

Bu hayatta yapmak istediğimiz her şey eksik, her şey yarım kaldı.

Artık birbirimizden başka kim tamamlayabilir ki bu eksikliği, bu yarım kalmışlığı... Bu büyük boşluğu... 

Çok kırdık, çok incittik, çok insanın sevgisinin önünü kestik, onları yarı yolda bıraktık... 

Şimdi onları ödüyoruz..

Artık hiçbir ev, hiçbir yuva almaz bizi içine..

Lanetlendik... Artık nereye gitsek yokluğumuz karşılayacak bizi... Nereye gitsek dışarıda kalacağız... 

Yokluğumu varlığa çevir, gel artık benimle mahvol... Bensiz isimsiz kalmaktansa, benimle isimsiz kal, daha iyi... Bak yüzünün yarısı öbür yarısına ağlıyor.

Eksik ve yarım kalmasın artık hayatımızda hiçbir şey... 

Bari bunu tamamlayalım... 

Gel birlikte mahvolalım... 

''Yüzünün yarısı çocuk / yarısı geçkin bir kadın / yüzünün yarısı öbür yarısına ağlıyor / yüzün kendisini arıyor... / Aşk kaçmış gözlerine / yaşanmamış yılların sana ağlıyor / zaman parçalanırken ellerinde / ölü kelebekler yastığın oluyor... / Ölü kelebekler / hepsi daha değerli erkeklerinden erkeklerinin kanıyla beslenen / ölü kelebekler... / hepsi daha değerli ömründen....''', 'Hiçbir sevgi yetmiyordu bize... Başkalarının kalplerinde yarattığımız, ateşlediğimiz sevgilerle yaşayabiliyorduk ancak... Çünkü birileri biz...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/olu-kelebekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
