INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevincelik', 'sevincelik-cemal-sureya-2viet', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızkulesi''ni düş getiren pay senetleri

Kısa günde kapış kapış gitti

İşçisi köylüsü öğrencisi şairi

Tam tamına 49,5 milyon kişi

Yazıldı defterine güzelliğin

Çocuklar sabah akşa
..........
..........', 'Kızkulesi''ni düş getiren pay senetleri Kısa günde kapış kapış gitti İşçisi köylüsü öğrencisi şairi Tam tamına 49,5 milyon kişi Yazıldı defte...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevincelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Nal', 'sicak-nal-cemal-sureya-838dm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-I-

Art çocuk, Muhyiddin Çelebi, 

Molla Fenari''nin kısık fitili; 

Okuduğu her beyitten sonra

Gülsuyuyla yıkardı ağzını; 

Kirlidir şiir; ve söz, atılmazsa zehirdir; 

Bunu bilirdi; 

Acı bir gölge geçerdi bakışından, 

Mesir macununun içindeki çivit gibi.

Karısı yanındaydı hep, 

Çocukluktan kalma

Ve artık değişmezlik kazanmış

Yanlış bilgi; 

Odalarda ışıksız iki aslan

Derinliğine iki atla sevişirdi.

Kerbela yası hemen her zaman

Görünmez kılardı Mevlit sevincini; 

Ölümü düşünen, 

Daha doğrusu anımsayan yüzü

İlençler denizinde yüzerdi.

-II-

Dikenli tele takılmış çiç
..........
..........', '-I- Art çocuk, Muhyiddin Çelebi,  Molla Fenari''nin kısık fitili;  Okuduğu her beyitten sonra Gülsuyuyla yıkardı ağzını;  Kirlidir şiir; ve s...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sicak-nal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
