INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kent Sürgünü Bir Ana', 'kent-surgunu-bir-ana-behcet-necatigil-k1bll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Savaş hattı, siperler

Sefertası apartımanları geç

Horlanmış, sıkkın

