INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-hasan-koca-2-72nq1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızdım şiirlerimin dibinde

sırf kahrolmamak için histim kendime

olmalıydı çözüm

sensizlikle inatlaşmak boştu.

yardım beklemedim istemedim

belki güçsüz dargınlığımı görmeni

soğuk artık meydanlar

kış olmuş nefesimin umudu

yazık bu soruyu soramadım

sen beni sonsuzluğuna uğurladın

el bile sallamamak meziyet oldu

ufalanmış kuş yemi his

ben niye döndüğümü bilmez pervane! 

yok artık sırf inatlaşmak 

sebeplerimi de sıramayacağım

kanadında gümüş de yok martıların

e ben niye burdayım bu soruyu da bilmiyorum

yani durum sandığından daha da ciddi

sen kendini biliyosun aslında saklanma

bir hiç uğruna herşey

bir yok uğruna 

bu gece de yatmayacağım inatla

sırf sana eziyet olsun okudukların

is kokan gece ve ben arkadaş

yağmur sana dost bize sırdaş! 

bu soru ne bilmiyorum

ne sormalıyım ve ya ne soracağım

ve yahut ne sormalıydım da cevabını

bilmeliydin e yani kısaca

zor kadere emanet ettin beni

bu kursak sana emanet 

bu yürek benim olsun peki

zaten anlaşmak mucize

sevmek kehanet! 

25,10,2002 saat 22,23', 'yalnızdım şiirlerimin dibinde sırf kahrolmamak için histim kendime olmalıydı çözüm sensizlikle inatlaşmak boştu. yardım beklemedim istemedim...', ARRAY['Türk Edebiyatı','Şiir','Hasan Koca 2']::text[], 8.5, '{"poet":"Hasan Koca 2","poet_slug":"hasan-koca-2","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/soru-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Eğer Buysa', 'sevgi-eger-buysa-muhammet-umut-dilek-w1yow', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni sevmek acıyı sevmekse, 

gözyaşı dökmekse her gece

sorularla boğuşup, 

yenilmekse çaresiz....

ölmek istemekse, 

bu acıya pes edip, 

sesini duyduğum anda, 

''nerdesin? ''diye azarlamaksa, 

aramamana rağmen, 

aramak  için için yanmaksa, 

sonra beni anlayan dostla, 

hep ama hep seni konuşmaksa, 

senin yıkacağını bile bile

hayaller kurup, 

her gün başka bir yüz, 

başka bir imajla, 

sana görünmek istemekse, 

kahretsin söylüyorum işte.....

''seni seviyorum....''

seni sevmemden, 

''nefret etsem bile.............''', 'seni sevmek acıyı sevmekse,  gözyaşı dökmekse her gece sorularla boğuşup,  yenilmekse çaresiz.... ölmek istemekse,  bu acıya pes edip,  sesi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevgi-eger-buysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurumlarımda Gezinirken', 'ucurumlarimda-gezinirken-muhammet-umut-dilek-16wgo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kemikle kefenlenmiş ruhum, 

plastik damarlarımda dolaşırken, 

alevden hapishanelerin, 

rüyalarında küser gerçekler...

yokluğuna sığınırken, 

yangınlı ormanlarıma, 

sen ise

ruh denizimde tek ada...

ben se, 

ateşi sen sanan, 

sessiz öten kanarya....

yalnızlık, loş duvarlarda, 

bir fahişe kadar esir.

oynaşır her gece benimle.

doyar kanımda sensizliğime.

ve sen, 

kaybolan gençliğimin en güzel anısı...

hayalet yoldaşı yalnızlığımın, 

intiharımın ateşi, 

dinmeyen acısı yüreğimin...

senin için işte, 

koparıyorum, 

göğüs kafesimden kalıntılarını.

bırakıyorum dalgalara, 

bilmelisin ki, 

ben artık, 

uçurumlarımı seviyorum.....', 'kemikle kefenlenmiş ruhum,  plastik damarlarımda dolaşırken,  alevden hapishanelerin,  rüyalarında küser gerçekler... yokluğuna sığınırken, ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Umut Dilek']::text[], 8.5, '{"poet":"Muhammet Umut Dilek","poet_slug":"muhammet-umut-dilek","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ucurumlarimda-gezinirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
