INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlarda Seninle', 'yildizlarda-seninle-filiz-turan-93kx6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlarda elele

Dolaştık seninle dün gece

Sevdamız yağmur oldu

Yağdı damla damla yeryüzüne

Sevgilerden buketler verdik

Sevmeyi unutmuş gönüllere

Yıldızlarla parladık gülümsedik

Bize bakan hasret dolu yüreklere

Gün ağarırken tutuşan ellerimiz ayrıldı

Ama biz ağlamadık..

Yüreğimizde filizlenen hasret çiçeğiyle

Vedalaşıp ayrıldık..

Yine böyle güzel bir gece de

Yıldızlarda seninle..

Buluşmak dileğiyle..', 'Yıldızlarda elele Dolaştık seninle dün gece Sevdamız yağmur oldu Yağdı damla damla yeryüzüne Sevgilerden buketler verdik Sevmeyi unutmuş gön...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildizlarda-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-filiz-turan-l6sr0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sabah minik bir kuş olur

Konarım pencerenin kenarına

Seyrederim senin uyanışını

Sonrada sessizce uçup giderim...

Belki de bir yağmur damlası olur..

Yağar üzerine ıslatırım saçlarını

Süzülürken saçlarından yüzüne

Öperim usulca yanağından...

Kırlarda gezinirken sen

Bir küçük papatya olurum ben

Beni fark etmeni beklerken

Yanımdan sessizce gelip geçersin

Gökyüzünde gezinen bir bulut olur

Sevgimi yağdırırım damla damla üzerine

Geceleri parlayan bir yıldız olur

Göz kırparım sana çok uzaklardan

Sonra beni görmen için

Kayar giderim gökyüzünden sonsuzluğa

Bahçende açan bir gül olur

Seyrederim seni doyasıya

Esen rüzgarlarla kokumu savurup

Sevdamı anlatırım sana

Bazen de ılık esen bir meltem olur

Eser durur dokunurum saçlarına

Fısıldarım sessizce sevgimi kulağına..

Senin beni duymayacağını bilerek...', 'Bir sabah minik bir kuş olur Konarım pencerenin kenarına Seyrederim senin uyanışını Sonrada sessizce uçup giderim... Belki de bir yağmur dam...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/senin-icin-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelince Aklıma', 'sen-gelince-aklima-filiz-turan-jospq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gelince aklıma

Bir lokma düğümlenir boğazımda

Derinden bir sızı yüreğimi yakar da

İçin için ağlarım..

Sen gelince aklıma

Yüreğime akar gözyaşlarım

Hasretin buram buram tüter de

Yokluğuna yanarım...

Sen gelince aklıma

Ufka dalar gider gözlerim

Bir bir hatıralar canlanır da

Seni  anar seni özlerim

Sen gelince aklıma

Gecenin bir yarısında

Karanlığın koynunda otururum da

Hayalinle saatlerce dertleşirim...

Sen gelince aklıma

Umudum yok olur yüreğimde

Hüzünler ruhumu sarar da

Kaderime küserim..

Sen gelince aklıma

Kaybolur gözümde güzel olan ne varsa

Sensizliğime boyun büker de

Kendimi yapayalnız hissederim...', 'Sen gelince aklıma Bir lokma düğümlenir boğazımda Derinden bir sızı yüreğimi yakar da İçin için ağlarım.. Sen gelince aklıma Yüreğime akar g...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gelince-aklima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şamil Fırtınası', 'samil-firtinasi-arif-altunbas-zuvph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğ ey güneş doğ artık üstümüze doğudan

Bunca zulüm, katliam ve işgallerden sonra

Kır ellerimizdeki paslanmış zincirleri

İnanç ve imanımızla dalgalansın kafkasların bağrında

Özgür bir bayrak gibi yankılansın kavgamız

Çeçenistan dağlarında

Ey rüzgar doldur özgürlüğe yönelen yelkenimizi

Rahmet yüklü bulutlar yetiş yüreğimize bir hızır gibi

Şamil fırtınasıyla kır zincirlerimizi

Uyandır uyandır derin uykulardan  bizi

Bin nice özlemle beklemeye durmuş bize hatırlat bizi

Anaların yanık bağırlarına merhem Kur´an´dan bir mustu gibi

Yağdır rahmetini üzerimize 

Gel artık gel göğsümüzü sabit kıl düşmana karşı

Cihadımızı galip kıl inkara karşı

Allah aşkına, Muhammed aşkına ya şafakla sökün edip gel

Esir koyma ellerimizi soldurtma tazecik güllerimizi

Şamilsiz birakma cephelerimizi

Ya şehadet gömlegini giydir 

Ya da gel demeden kurtar bizi

Viyana,05.09.1994', 'Doğ ey güneş doğ artık üstümüze doğudan Bunca zulüm, katliam ve işgallerden sonra Kır ellerimizdeki paslanmış zincirleri İnanç ve imanımızla...', ARRAY['Türk Edebiyatı','Şiir','Arif Altunbaş']::text[], 8.5, '{"poet":"Arif Altunbaş","poet_slug":"arif-altunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/samil-firtinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Ayazı', 'yalnizlik-ayazi-zeynep-savci-j16sc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yalnızlık ayazı, bu gece içimdeki

Bir üşüme, bir titreme hali..

Kalabalık içinde de böyle olurum ben, 

Hasretliklerin başladığı anlar gibi.. 

Ne uzak, ne yakındır o zaman gökyüzü, 

Ama sıcacıksa içim, ulaşırım bulutlara

Sevgi sözcükleri çalarım yıldızlardan

Sadece senin için..

Ama bir de yalnızsam, 

Hele bir de üşüyorsam, 

BiLirsin sen beni, 

O zaman ne uyur 

Ne de uyuturum seni..', 'Bir yalnızlık ayazı, bu gece içimdeki Bir üşüme, bir titreme hali.. Kalabalık içinde de böyle olurum ben,  Hasretliklerin başladığı anlar gi...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Savcı']::text[], 8.5, '{"poet":"Zeynep Savcı","poet_slug":"zeynep-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-ayazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya', 'gittin-ya-ali-gencli-adubo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/Ne denli yalnız 

  boşlukta, /

/Uzanıp boş kalan ellerim./

Parmak uçlarımdan /

dö

  kü

     lü

       yor

/bir  bir  özlemlerim. /

Geceyle birlikte /

/bir dost gibi kucaklar, 

yarım kalmış  hüzünlerim.../

                                               ALİ  GENÇLİ

                             [email protected]', '/Ne denli yalnız    boşlukta, / /Uzanıp boş kalan ellerim./ Parmak uçlarımdan / dö   kü      lü        yor /bir  bir  özlemlerim. / Geceyle ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençli']::text[], 8.5, '{"poet":"Ali Gençli","poet_slug":"ali-gencli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gittin-ya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Destanının Adı Gonca - 3', 'askimin-destaninin-adi-gonca-3-i-brahim-cagri-saglik-wm2oe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve bir mucize oldu anlayamadan

Yanyana yürürken bir gün caddede

Elimi tutuverdin hiç saklamadan

Anladım ki canımsın ayrı bedende

Beraber gezdik dolaştık Ankara''yı

Her yanına ayrı bir neşe getirdik

Yaşayan bilir kara sevdalanmayı

Nasılsa yılları günlere yetirdik

Heyhat ki tez zamanda çokça muhabbet

Ayrılık getirir derler inanmazdım

Aşık olmak değilmiş asıl marifet

Ayrılmadan onu anlayamazdım

Sadece sen istedin diyerekten

Bastırdım içimdeki aşk vurgununu

Anılarım mahalinde dolaşırken

Atamadım kalbimin burukluğunu

Terkettim şehri dönmemecesine 

Ayrılık kadermiş bile diyemedim

Yaktın yüreğimi sönmemecesine

Udumun saf nağmelerinde inledim

25 - 10 - 2002', 'Ve bir mucize oldu anlayamadan Yanyana yürürken bir gün caddede Elimi tutuverdin hiç saklamadan Anladım ki canımsın ayrı bedende Beraber gez...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askimin-destaninin-adi-gonca-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dün', 'bir-dun-asim-ozturk-r6jhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakıp gittiğin yerlerdeyim hep

Susuz

	Güneşsiz bir tohum gibi, 

Giyilmiş sabahların içinden akıyorum

Işıkların örselediği

Güzlerin sesiyle; 

Bir dün

	Bir dönülmez yolculukların

	Kıyısında duruyorum, 

Elimi kaldırsam

Yanık

	Yıkık bir gülümseme

Dudaklarıma gelip oturuyor, 

Çağrılmamış çocuklar gibi kırgın

Hani dokunsan

	Kızsan diyorum

Kirpiklerini örsen içimdeki sevgiye

Salıvermesem

Bakışlarının kuşlarını

Ürkek

	Şaşkın söğütler gibi

Sarkıtsam dallarımı gecelerime

Unutulmuş kıyılardan sürüklenip gelen kumlarda

Kendi ırmağımın düşleri olsa

Dünün bir tarihçesi

Okunmadan yırtılıp atılan

Kirlenen

	Örselenen sabahları

Çözsem kirpiklerinin ağından

Acının duvarında zincir izleri

Sürüklenir ardımdan

Kaldırımlarda ölü kent izleri', 'Bırakıp gittiğin yerlerdeyim hep Susuz 	Güneşsiz bir tohum gibi,  Giyilmiş sabahların içinden akıyorum Işıkların örselediği Güzlerin sesiyle...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-dun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfilin Gecesi', 'karanfilin-gecesi-asim-ozturk-cnnvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Işıklarla örselenmiş karanlıklar

Çimenlerin uykusunda kaldı

Duydun mu? 

Çürüyen mendireğin esintiye söylediğini

Yaşadın mı

Kanatsız martılar

Yaldızlı camlara yuva kuruyor şimdi; 

Kendisiyle boyatan ufukların

Kızıl düşü, 

Esrik limanlardan kalkıyor

Kör dalgalarda uyurken

Başlıyor evsiz çocukların türküsü; 

Yalnızlığın gergefinde iki damla karafil

İki damla kan, gülüşün; 

Başlıyor karanfilin gecesi.

Kim çocuk değildi

Ey aynaları odalar olan sesizlik

Öfkenin yenik başkaldırısı

Kendini ağır ağır tüketiyor

Yalın söz, 

Bir söylenebilse yaşandığı gibi

Dağılıp gidecek, 

Dağılıp sürüklenecek

Kayaların ürpertisi; 

Bir kıyıda öyle

Kumda ince bir ay çizgisi

Işığın küskün seli, 

Yaşandı ve bitti denilecek

Ay iri iri damlalar halinde

Sesinin karanfilinden dökülürken

Görüntün, 

Yalnızlığın kör dalgalarıyla sürüklenecek.', 'Işıklarla örselenmiş karanlıklar Çimenlerin uykusunda kaldı Duydun mu?  Çürüyen mendireğin esintiye söylediğini Yaşadın mı Kanatsız martılar...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karanfilin-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Çağı Çocukları', 'gul-cagi-cocuklari-arif-altunbas-my1v3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatı top yekün bir savaş bilin

Peygambere biat etmiş bir elle

Sabır zırhlarını giyerek gelin

Sevdamıza kenetlenmiş gönülle

Musa ile Tur dağında bilenin

Unutma bir ibret sahnesidir dün

Kızıl denizi yara yara gelin

Yarın sizler ile doğacaktır  gün 

Yeryüzünden gök yüzüne yükselin

Arşa değsin sevdamın kanatları

Güneimizi yüklenerek gelin

Gül çagının gül yüzlü çocuklari

Viyana,22.04.1993', 'Hayatı top yekün bir savaş bilin Peygambere biat etmiş bir elle Sabır zırhlarını giyerek gelin Sevdamıza kenetlenmiş gönülle Musa ile Tur da...', ARRAY['Türk Edebiyatı','Şiir','Arif Altunbaş']::text[], 8.5, '{"poet":"Arif Altunbaş","poet_slug":"arif-altunbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gul-cagi-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
