INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bir Daha Bir Daha', 'bir-bir-daha-bir-daha-behcet-necatigil-jith1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrı imtihan eder

Tekrar imtihan eder

Kul hazır ümitler

Kendi öyle zanneder.

Kiminde hafif geçer

Hatta bir şey sorulma
..........
..........', 'Tanrı imtihan eder Tekrar imtihan eder Kul hazır ümitler Kendi öyle zanneder. Kiminde hafif geçer Hatta bir şey sorulma .......... ............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-bir-daha-bir-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düne Doğru', 'dune-dogru-asim-ozturk-3tv9h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyukluyor ağaç sandalyeler

Çivit mavisi, 

Eski bir kahvenin gölgesinde

Yorgun seslerin yelkenine takılan

Günbatımında bir imbat, 

Pörsümüş bulutlardan sızan

Alev alev güneşe serilip yatıyor.

Sen de çekiliyorsun kışa

Bir dal kırıldı, 

Sızısız bir sözcük yatıyor

Dudaklarımda; 

Çekildi el ayak

Gecenin kıyısında akşam duruyor, 

Örselenen küller

Yaşlı gözleriyle uzaklara bulut bulut bakıp

Dün var mıydı? 

Akıp giden yelin koparıp aldığı ne; 

Çalınmayan tahta kapılardan

Ansızın giriveren, 

Leylak moru gözlerin, 

Uykulu saksılara döktüğü o rengin adı ne

Bir türkünün atlarıydı, ovalarda

Başaklar kuşatırdı, gümüş toynaklarını; 

Bir sevdanın kendisiydi, 

Solgun bir karanfilin düne söylediği; 

O yaşadı mı

Bensizliğin adı var mıydı, 

Dün öyle buruk ve sessiz geçti; 

Ağladım mı', 'Uyukluyor ağaç sandalyeler Çivit mavisi,  Eski bir kahvenin gölgesinde Yorgun seslerin yelkenine takılan Günbatımında bir imbat,  Pörsümüş b...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dune-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
