INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanfil Ölüleri', 'karanfil-oluleri-yilmaz-erdogan-fra3d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günler güz yanığı

sonsuza giden raylarda gümüş

kum susan çöller gibi

yalana buyruk akıyor

bıkıyor zaman...

senin maviliğinden eser yok

haki yeşil bir yaz

ve tel örgülerde

karanfil ölüleri...

bazı salak kuşlar

konduğu pencerelere tutsak

yalan yanlış konmalara zemin

haki yeşil bir yaz

hasret mavisinde karanfil ölüleri

önünden tren geçen hemzenin hayat

duran zaman

esneyen saatler

amaçsız bir bit yarışı

yürüdükçe uzayan

koştukça beton yollar

ve yollarda

karanfil ölüleri...

limanlarında denizsiz yaşanan

ezan vakti küheylan

kuşluk vakti beyinsiz bir şehir

diken biriktiren bir koleksiyoncu

ve gül kokumsuz çim bahçelerde

karanfil ölüleri...

bezgin çamurlarda

nefsi müdafadır bir tozun direnişi

kimsenin bikinisini çıkarmadığı

haki yeşil bir yaz

ve yarasına işeyen kırık haziran makamında

erotik

karanfil ölüleri...

sormadan konuşan ahmak

yalan değil gölge değil iz hiç değil

sanal bir serinliğe sığınan

çağıl çağıl bir nehir bile değil

çağlayan diliyle ırmamak

ve ırmaklarda

karanfil ölüleri...

yaprağına kırmızı

kıvrımına şarkılar

dallarına suskun bir hayat öpücüğü

ve haki yeşil bir yaz içre yazılan

sıkkın şiirlerde

karanfil ölüleri...', 'günler güz yanığı sonsuza giden raylarda gümüş kum susan çöller gibi yalana buyruk akıyor bıkıyor zaman... senin maviliğinden eser yok haki ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/karanfil-oluleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onulmaz', 'onulmaz-yilmaz-erdogan-vgrwg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'iyileşmez hiçbir yara bilirsin

tortusu kalır

hangi ses unutturabilir

ilk bıçağın yankısını

sende rehin kalmıştır

gecenin saplantısı

hiçbir yara

hiçbir zaman iyileşmez bilirsin

saklısı kalır

yel esince sızılanır

su susunca ikindilerde

herşey vakitsizce gelişir

birine sevişirsin

ötekini düşünürken

sabahları zordur korsan sevişmelerin

eski yaraların ağrır

oysa ne bir iz görünür teninde

ne şiiri ses verir orta kulağında

yalnız bir yürüme isteği vardır

eski yaraların eski yerinde

kahvaltısı zordur olmayası bir sevişmenin

ve hep ten tuzu basmaktır

eski yaraların eski yerlerine

hiçbir yara

tam olarak iyileşmez bilirsin

hangi bakış unutturabilir

ilk bıçağın ışıltısını

karanlıktaki

şairden bir bok olmaz sabaha karşı

sebepsiz hüzünler yazar ehliyetinde

ve ne söylese yalandır

alkol kontrolünde

sevmek bizahiti yaralanmaktır

ve yaralar hiçbir zaman iyileşmez teninde

yanlış vurulmuş bir aşıdan sızar da

diriltir solgun baharları

şiire sebep istemez

şairden bir bok olmaz ve

hiçbir yara

hiçbir zaman tam olarak iyileşmez

bardaklarda dudak izleri birikir

sahnede eğri büğrü sesler

ve sade bir yürümek isteği tek başına

eski bir yaranın artık gözle görülmeyen izinde...

çünkü hiçbir yara hiçbir zaman tam olarak iyileşmez

çünkü en hızlı hatırlanandır

en eski unutulan

ondan gelen ıtırlar olur yellerde

her esinti bir acılı kokuyu taşır hassas burunlara

savrulur gidersin

çok eski çok acıtan bir ağustosa

nasıl kıyısında kalmıştık

yapış yapış bir yazın

daha başkaydı hani yüzünde

herkese aynı oranda bulaşan tuz

yolların açmazıydı enginlikle kabaran

ve bütün yanlışları dalga dalga saklayan

şarkılıktan usanmış deniz

ve denizi herşeye benzeten şiirler

ve kıstırılmış istridyelerde kullanılmış inci taneleri...

çünkü bilirsin

hiçbir yara hiçbir zaman

tam olarak iyileşmez!', 'iyileşmez hiçbir yara bilirsin tortusu kalır hangi ses unutturabilir ilk bıçağın yankısını sende rehin kalmıştır gecenin saplantısı hiçbir y...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/onulmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Benim...', 'oy-benim-yilmaz-erdogan-76b7p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ceyhan depremi ve Kerim Tekin için

yakayıp geçti tramvay

atmosfer yakıverdi sızılayıp

yıldızların en haylazını

	hey gidi başıbozuk

	ayarsız gemi

	azıya aldım tayfalarımı

	salınmaktayım

	filikasız filan

	önce fareleri kurtarıyorum

	bu titanik akşamından

geçerdi her saat başı

cürmünden büyük amatör bir gökkuşağı

tedirgin renkler taşırdı

tedavisi yarım kalmış ikindilere

	oy benim

	gamzeli kuşbakışlı evrenim

	ummanda ıslak

	kaderde alt yazılı dünyalım

	önce çocukları

	ve

	muayyen kadınları kurtarıyorum

	bu galaksi mesaisinden

kırık faylarda yolalan

bir depremdir

trenimin güzergahı

açılır saçbağı gibi kundaklara düşerim

göçük altında enfes bir nefestir

bazen benden bile sakladığım

vay benim güzağacım

köklerinden kurtulmuş

erozyon bir hayatın özüdür

humuslu bir kayıbı anlamak

ya da mümkün müdür

bu rastlantısal karmaşada

ölümün sıradanlığına şaşmadan yaşamak? 

belki de o balkonları

ondört yaşında çocuklar atlasın diye yapıyoruz

ey benim

zavallı yüsekliğim

bütün serüven küçücük bir an''dı

allah hep kerimdi

ve tekin değildi doğumlar

genç bir gidiş için

erken çıkılmalıydı yola

vuslata varılmalıydı hava kararmadan

kimsenin gelmediği buluşmalara

aceleyle

polaroid hızıyla gidiyorduk

oysa koşmanın da bir hukuku vardı durulmanın da...

	oy benim

	yaz ölümlerim

	gencecik bir hazirana gömülen...', 'Ceyhan depremi ve Kerim Tekin için yakayıp geçti tramvay atmosfer yakıverdi sızılayıp yıldızların en haylazını 	hey gidi başıbozuk 	ayarsız ...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/oy-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötesi', 'otesi-yilmaz-erdogan-l8ewn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'saçakların buz kırgını

soğuk fırtınalar

boranlar yara doğru

sanrılar durulur duyulmaz

vakitlerden kehribar

şehr-i sefahatti kol kanat gerilmiş

kuşaklar tetikte

babil''in asma bahçelerinde infazlar

dünyanın yedinci cücesiydi sekiz harika insandan biri

mavi bir yuvarlaktı hepsi kainat kadar büyük

ve küçücük bir damla hayat kadar

bu işten en çok sıkılanlardır peygamberler

nefsi terbiye zemininde

uhrevi bir ıslıktı en kabadayı mucizesi

kolaydı çünkü bir olmazı anlatmak inanmak isteyene

denizler yarıldı yarıdan

sönük bir akşam yemeğinin ortasında

bir düzine uhrevana kaldı kabarık hesap

ve sonuncunun mucizesi mucizesizliği oldu

kardeşlerim! 

kardeşlerim acele etmeyiniz

hele bir ölelim de gerisi kolay!', 'saçakların buz kırgını soğuk fırtınalar boranlar yara doğru sanrılar durulur duyulmaz vakitlerden kehribar şehr-i sefahatti kol kanat gerilm...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/otesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sebep', 'sen-sebep-yilmaz-erdogan-v63ma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'korkutma beni

bu yaşlı başsız kelli felsiz halimle

gereğinden ziyade güzelsin zaten aklımı çelme

takma fikrime aksak ritimler

o havaya ayarlı değil bu yelken bu gemiler

kimin rastlantısı benim başıma geldi bilinmez

ummandır ıslak aksak girilmez

kapma kutusunu cahil ömrümün

açılır da içinden boş bir hayal çıkar seçilmez

daha bu yağış bir şey değil

sen bir de acıklı halimi gör

ürkünden derin soyulur farkına varmazsın

suda balık nasıl aymayı bilmez

su da balık da

hangi denizin neresindedir ayırmaz

böyle bir sevmek vardır

ve birçok er mektubunda görülmüştür

yok kadınlara aşık olanların işidir şiir

kirlidir yakası gömleklerinin

boyuna boyna fular papyon istemez

şairin boğazı darboğazdır

boğazın en inceldiği yerden solur

gülme üstüme kaçacak yerim yok

gelme yareme yarın veya başka seyir

tarih tevellüt iklim cetvel yok

	saçlarında bulunabilir

	bazı kayıp kentlerin

	yakışıklı cesetleri

	bir ağıta asılı kalır

	infaz gibi

	acılı çağların

yeri geldi diye ağlıyorum

yoksa hiç aklımda yoktu

gidenler gelirler

her gece yalnızlığıma

halleşir vedalaşırız

bir merhaba saflığında

kalanlarda kalmışya aklı gidenlerin

hep eski haberler arıyorlar

günlük taze gazetelerde

ve yalanlar kalanlara kalıyor

nasılsa gidenler gerçeğin olduğu yerde

sebebim sensin

bu mürekkep balığı

bu bukalemun

bu kalem

yokluğun

her şeyi sorduğum hayat

beni rahat bırak! 

her evin kilerinde toz içinde kitabı

ölülerle konuşma sanatının

grev var ansiklopedilerin bazı sayfalarında

süresiz olarak açıklamıyorlar

bazı ideolojileri

sözlüklerin bazı sapa harflerinde

işi yavaşlatma eylemi

beş saati buluyor anlamak

bir sözün etnik kökenini

bütün bunların sebebi sensin

asla hatırlanmayacak bir rüyanın

ortasında

elinde derin bir uyku kokusu.', 'korkutma beni bu yaşlı başsız kelli felsiz halimle gereğinden ziyade güzelsin zaten aklımı çelme takma fikrime aksak ritimler o havaya ayarl...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/sen-sebep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lalelim', 'lalelim-orhon-murat-ariburnu-60jrt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lalelim

Lalelide oturur

Laleli, lale kokar lalelimden

Laleliden geçilir

LALELİMDEN GEÇİLMEZ!', 'Lalelim Lalelide oturur Laleli, lale kokar lalelimden Laleliden geçilir LALELİMDEN GEÇİLMEZ!...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/lalelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz Böcek', 'aziz-bocek-orhon-murat-ariburnu-95pu3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karıncalar atlara binmiş

Arılar bal yapıyor kovanda

Bir sağır dünya üzeri

Herkes kendi avında

Sen sadece şiir yaz

Aziz böcek

Ağustosböceği.', 'Karıncalar atlara binmiş Arılar bal yapıyor kovanda Bir sağır dünya üzeri Herkes kendi avında Sen sadece şiir yaz Aziz böcek Ağustosböceği....', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aziz-bocek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sevgililer', 'son-sevgililer-orhon-murat-ariburnu-240l6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostlar elinde satılmak

Ölmek dostlar için.

Dost rüyalarıyla büyümek

Dostlara gönül vermek

Unutulmak için...

Şaşmıyor en büyük kayıplara

''İnsan oğlu kuş misali''

Kuşlarla uçuşan hatıralara.

Nankör insanlar bulup

Onları seviyorum

Sukutu hayale uğramıyorum

Nankörler

Son sevgililer...', 'Dostlar elinde satılmak Ölmek dostlar için. Dost rüyalarıyla büyümek Dostlara gönül vermek Unutulmak için... Şaşmıyor en büyük kayıplara ''İn...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-sevgililer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkûmlar', 'mahk-mlar-orhon-murat-ariburnu-3az4z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekseriya sabaha karşı

Kurşuna dizilir mahkûmlar

Bir sünger taşına döner

Ana sütünden yapılan heykel

Bari şu trampetler çalmasa,

İnsan gürültüye gitmese! ..', 'Ekseriya sabaha karşı Kurşuna dizilir mahkûmlar Bir sünger taşına döner Ana sütünden yapılan heykel Bari şu trampetler çalmasa, İnsan gürült...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mahkumlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-orhon-murat-ariburnu-hb8kh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya döndükçe

Umut fakirin ekmeği

Ye Memet ye

Ye Memet ye! ...', 'Dünya döndükçe Umut fakirin ekmeği Ye Memet ye Ye Memet ye! ......', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/umut-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez mi', 'yetmez-mi-orhon-murat-ariburnu-i1g0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce, Ozanlar ölsün

Sonra, hiç kimse.

Varsın Ozansız kalsın dünya

Barışı

İnsanlığı

Sevgiyi

Y a r a t t ı l a r  y a!', 'Önce, Ozanlar ölsün Sonra, hiç kimse. Varsın Ozansız kalsın dünya Barışı İnsanlığı Sevgiyi Y a r a t t ı l a r  y a!...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yetmez-mi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okulda Onkasım', 'okulda-onkasim-ali-hallac-u2fz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öğretmen: 

Bilirsiniz çocuklar

Onkasım yaslı bir gün

Ulus Ata''yı anar

İçten, buruk ve üzgün.

Çocuklar: 

Gerçekten öğretmenim

Özlem duyarız O''na

Fakat ne yazıktır ki

Yetişmedik çağına.

Öğretmen: 

Çocuklar, sizin gibi

Her kuşak anacaktır

İlkeleri dipdiri

Her zaman kalacaktır.

Çocuklar: 

Anlatınız öğretmenim

Ata''mızın yüzünü

Biz de duymak isterdik

Şefkat dolu sesini.

Öğretmen: 

Yavrularım dinleyin

Ata okulda, derste

Alfabede hece hece

Marşta, şarkıda, şiirde.

Çocuklar: 

İçimizde Atatürk

Işıktır gözümüzde

Düşüncede özgürlük

Ülküsü özümüzde.

Öğretmen: 

Evet  O öğretmişti

Bilinçli davranmayı

Ulus''a göstermişti

Aklını kullanmayı.

Gösterin çalışarak

Atatürk böyle ister

Huzuruna çıkarak

Her Onkasımda sizler.', 'Öğretmen:  Bilirsiniz çocuklar Onkasım yaslı bir gün Ulus Ata''yı anar İçten, buruk ve üzgün. Çocuklar:  Gerçekten öğretmenim Özlem duyarız O...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/okulda-onkasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onkasım Sabahında', 'onkasim-sabahinda-ali-hallac-g8h9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir onkasım sabahı

Yer yerinden oynadı

Koptu büyük bir çığlık

Ata''mız yoktu artık.

Dokuzu beş geçe tam! 

Bütün saatler durdu

Tarihi yazan adam

Sessizce uyuyordu.

Rahat uyu Ata''m sen

İzindedir bu millet

Elimizde meşalen

Vatan bize emanet.', 'Bir onkasım sabahı Yer yerinden oynadı Koptu büyük bir çığlık Ata''mız yoktu artık. Dokuzu beş geçe tam!  Bütün saatler durdu Tarihi yazan ad...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onkasim-sabahinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıtkabir Önünde And (On Kasım Şiiri)', 'anitkabir-onunde-and-on-kasim-siiri-ali-hallac-ircml', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tüm çocuklar elele

Atatürk sevgisiyle

Çiçekler götürelim

Gidip Anıtkabir''e.

Çiçekler birer birer

Bembeyaz karanfiller

Yaşa, varol Atatürk 

Çocuklar bunu diler.

Geldik yemin etmeye

Bayrağımız üstüne

Çağları aşacağız

Tarımda, sanayide.

Sanat, kültür ve fende

En iyisi ve en önde

Olacağız ey Ata''m

Mirasın sayesinde.

Şimdi gidiyor ama

Manevi nezdindeyiz

Söz veriyoruz sana

Ulusça izindeyiz.', 'Tüm çocuklar elele Atatürk sevgisiyle Çiçekler götürelim Gidip Anıtkabir''e. Çiçekler birer birer Bembeyaz karanfiller Yaşa, varol Atatürk  Ç...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anitkabir-onunde-and-on-kasim-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkçemiz (Dil Bayramı)', 'turkcemiz-dil-bayrami-ali-hallac-hwomu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Türkçe''dir anadilimiz

Gözümüz, kulağımız, elimiz

Onu doğru kullanalım

Bozulmasın dilimiz.

Akıcı ve arı

Sözcükler çoğalmalı

Yazarken, konuşurken

Çok dikkatli olmalı.

Pek güzeldir Türkçe''miz

Onu geliştirmeliyiz

Hep iyiye doğruya

Çaba göstermeliyiz.', 'Türkçe''dir anadilimiz Gözümüz, kulağımız, elimiz Onu doğru kullanalım Bozulmasın dilimiz. Akıcı ve arı Sözcükler çoğalmalı Yazarken, konuşur...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkcemiz-dil-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitap Haftası', 'kitap-haftasi-ali-hallac-nm3vv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kitap aydınlık getir

Ulusumun ufkuna

Uygarlık, ışık getir

Bize zemin hazırla.

Kitaplar ilgi ister

Yükselmek bilgi ister.

Hep oku genç kardeşim

Cahilliği kovarak

İşe yarar bir bilim

Sürekli okuyarak.

Kitaplar ilgi ister

Yükselmek bilgi ister.

Her kitap bir basamak

Yaşam merdiveninde

Okursan anlayarak

Dimağın kalar zinde.

Kitaplar ilgi ister

Yükselmek bilgi ister.

Bu kitap haftasında

Unutmayın çocuklar

Vermek için bir yarar

Sizi bekler kitaplar.

Kitaplar ilgi ister

Yükselmek bilgi ister.', 'Kitap aydınlık getir Ulusumun ufkuna Uygarlık, ışık getir Bize zemin hazırla. Kitaplar ilgi ister Yükselmek bilgi ister. Hep oku genç kardeş...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kitap-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen', 'ogretmen-ali-hallac-q94mv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ülküsü Atatürk''ün

Övüncü herbir Türk''ün

Yurda sevgisi bütün.

Elleri cumhuriyet

Dilleri de hürriyet

Okuyor öğretmenin.

Türk Kültürü içimize

Meslek verir elimize

Sevgi aşılar bize.

Dilleri cumhuriyet

Elleri de hürriyet

Dokuyor öğretmenin.', 'Ülküsü Atatürk''ün Övüncü herbir Türk''ün Yurda sevgisi bütün. Elleri cumhuriyet Dilleri de hürriyet Okuyor öğretmenin. Türk Kültürü içimize M...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogretmen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analık Görevi', 'analik-gorevi-ali-hallac-5yv1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayır anne! bitmedi bitti sandığın ödev

sakın salma topluma getirmeden sonunu

nefret tomumu eken, fırsat kolluyor bir dev

o bir yumuşak hamur sevgiyle işle onu.

sevgi ile yürüsün aksamadan bu kervan

insanlığa saygıyla gönüller dolar iman

beğenmediğin dünya böyle düzelir inan

sakın salma topluma getirmeden sonunu.

vatan millet aşkıyla, ilimle irfan gerek

senin bu oğlun anne bilincine ererek

güzel albayrak için göğsünü de gererek

ancak güzel amaçla bulabilir yolunu.', 'hayır anne! bitmedi bitti sandığın ödev sakın salma topluma getirmeden sonunu nefret tomumu eken, fırsat kolluyor bir dev o bir yumuşak hamu...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/analik-gorevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-ali-hallac-9krsq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sohbetlerin doyumsuz, bir neşe kaynağısın

sen gelince bu eve, keder asla uğramaz

bakıp örnek alırız, öyle eşsiz aynasın

üzüntü, karamsarlık önümüzde duramaz.

duramaz kötülükler, sayende yıkılırlar

şakalarla saatler, nasıl geçer bilinmez

türkülerle şarkılar, uzar gider fasıllar

binyıl geçse anılar belleklerden silinmez.

hergün gibi bugün de, eve yorgun gelirsin

geçim derdi pek çok, tanrı kolaylık versin

birlikte güzel günler, sağlık dileriz baba

yürek dolu sevgiler çocuklarından sana.

30.10.1980', 'sohbetlerin doyumsuz, bir neşe kaynağısın sen gelince bu eve, keder asla uğramaz bakıp örnek alırız, öyle eşsiz aynasın üzüntü, karamsarlık ...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/baba-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay evine giderken', 'ay-evine-giderken-mustafa-ozke-kkx5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşey Mina''nın ağlaması ile başladı

Önce yatağımdan kalktım

Ağlamasaydı uyanamayacaktım

Sonra saatime baktım

Ağlamasaydı işe geç kalacaktım

Ben Mina''nın beşiğini sallarken

Annesi mutfakta mamasını pişirdi

Getirip biberonunu eline verdi

Mamasını yemedi, biberonu düşürdü

Biliyorum benimle oynamaktı onun derdi

Kucağıma aldım öptüm yanağından

Bir salkım üzüm koparttım bağından

Annesi mamasını yedirdi tabağından

Ha kızım de kızım derken

Bir güne daha başladık ay evine giderken', 'Herşey Mina''nın ağlaması ile başladı Önce yatağımdan kalktım Ağlamasaydı uyanamayacaktım Sonra saatime baktım Ağlamasaydı işe geç kalacaktım...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ay-evine-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Çiçeği', 'sevda-cicegi-filiz-turan-qfr8a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanlış zamanda açtın sen

Sevda çiçeğim..

Bahar çoktan bitti..

Mevsim sonbahar..

Hazan yaprakları arasında

Açsan ne faydası var..

Güneşe hasret..

Güz yağmurlarında..

Ömrün olur mu dersin..

Sen güzel kokular saçsan da

Kime ne fayda sonbaharda..

Ne kadar güzel olsan da çiçeğim

Olurmu hiç güzün değerin..

Önünde zorlu kara kışlar var

Senden çok uzaklarda baharlar

Etrafına hele bir dön ve bak

Ne açmış bir çiçek var

Nede uçuşan kelebekler..

Etrafında uçuşan sadece

Kurumuş sarı yapraklar..

Sen yanlış zamanda

Ve Yanlış yerde açtın

Solmaya mahkumsun 

 sevda çiçeğim..

Mayıs 2002', 'Yanlış zamanda açtın sen Sevda çiçeğim.. Bahar çoktan bitti.. Mevsim sonbahar.. Hazan yaprakları arasında Açsan ne faydası var.. Güneşe hasr...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaresulallah', 'yaresulallah-filiz-turan-jyalh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretin bir kor yanar sinemde

Gül yüzünü görmek dilerim düşlerimde

Sana olan sevdam büyür yüreğimde

Vuslata erecek miyim yaresulallah

Gülleri koklarım senin hasretin ile

Gönlümü avuturum güzel isminle

Düşlerime gir ne olur eşsiz cisminle

Vuslata erecek miyim yaresulallah

Bu gönül seni görmeyi diler

Uğrunda bu canı vermeyi ister

Senin şefaatine ermeyi bekler

Vuslata erecek miyim yaresulallah

Geçmez oldu günlerim gecelerim

Bitmez bir türlü ömür defterim

Ecel ile sana kavuşmayı dilerim

Vuslata erecek miyim yaresulallah

Bu gönül kapında bir garip dilenci

Çok görme bana bu büyük sevinci

Bende öpeyim o gül kokulu elini

Vuslata erecek miyim yaresulallah 

Sensiz bu dünya zindan neyleyim

İzin ver de gül yüzünü bir kere göreyim

Ecel gelmeden düşümde vuslata ereyim

Sana kavuşmak varmıdır yaresulallah

                                          12 nisan 2002', 'Hasretin bir kor yanar sinemde Gül yüzünü görmek dilerim düşlerimde Sana olan sevdam büyür yüreğimde Vuslata erecek miyim yaresulallah Gülle...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaresulallah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kuşum', 'kucuk-kusum-filiz-turan-xlx9y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir küçük  kuş  uçmayı unutmuş

Nice uzun zamandır kafese konmuş

Semaya bakar durur gözleri

Uçmaktır mavi göklerde düşleri..

Hayal kurar  durur günlerce gecelerce

Gözyaşları akar durur  yüreğine gizlice

Kimseler görmez kimseler bilmez...

Ne göz yaşlarını ne de hayallerini

Bakan gözler sadece minik bir kuş görürler

Oysa yüreği ne engin  denizdir

bunu hiç bilmezler

Gözyaşları sessizce süzülürken yüreğine

Hasret şarkıları söyler

öter durur tüm güzelliğiyle

Ne yazık bir küçük altın kafese mahkum

Uçmayı unutmuş minicik kuşum..

Bırak hasret dolu yüreğin uçsun semaya

Alsın götürsün senden geride kalan ne varsa

Kaybolup gitsin uçsuz bucaksız maviliklerde

Kanat çırpsın hasretle gökyüzünde

Yaşarsın bu düşü anca hayallerinde..

        Mayıs 2002', 'Bir küçük  kuş  uçmayı unutmuş Nice uzun zamandır kafese konmuş Semaya bakar durur gözleri Uçmaktır mavi göklerde düşleri.. Hayal kurar  dur...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kucuk-kusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem Duyarsan', 'ozlem-duyarsan-filiz-turan-u8vpl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'An gelir şu koca dünyada 

Yapayalnız hissedersen kendini

Derinden bir sızı yakarsa yüreğini

Ve özlem duyarsan bir dosta

İşte o zaman etrafına bak

Baktığın her yerde görebilirsin

Sevgimi ve beni

Güneş olur ısıtırım yüreğini

Yağmur olur tutarım ellerini

Bazen de bir yıldız olur

Uzaklardan severim seni

           31 temmuz 2002', 'An gelir şu koca dünyada  Yapayalnız hissedersen kendini Derinden bir sızı yakarsa yüreğini Ve özlem duyarsan bir dosta İşte o zaman etrafın...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlem-duyarsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-filiz-turan-0v15l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir düş gördüm dün gece

Açılıyor büyükçe bir kapı önümde

Giriyorum içeri biraz çekingen

Bir bahçe burası güllerle bezenen

Mis gibi kokuyor rengarenk güller

Etrafı donatmış leylaklar sümbüller

Hayran kaldım seyrettim saatlerce

Zaman akıp gitmiş kalmışım öylece

Gördüm bu bahçede bir ırmak akan

Suyu billur gibi olan çağlayan

Irmağın kenarında var bir civan oturan

Elinde bir kalem nice güzel şiirler yazan

Bir an oldu geldik göz göze..

Yüreğim bir kuş oldu uçtu göklere

Eridi bu can kayboldu gözlerinde

Çağırdı beni de ırmağın yanına civan

Ne yazık dizlerimde yok gidecek derman

Gönül gördüğü güzelliklere kaldı hayran

Bir düş dedi kendince uyanmak var her an

Bir garip burukluk çöktü içine

Derin bir hüzün çöreklendi yüreğine

Gönül bu bahçeden gitmek istemez

Bir düş bu sonu belli

Elden hiç bir şey gelmez

Bir ah çekti derince içinden

Acep olur mu bu gerçek dilersem yürekten

7 mayıs 2002', 'Bir düş gördüm dün gece Açılıyor büyükçe bir kapı önümde Giriyorum içeri biraz çekingen Bir bahçe burası güllerle bezenen Mis gibi kokuyor r...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dus-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Bahçem', 'gonul-bahcem-filiz-turan-52k28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlüm bir bahçe idi viran

Çiçekleri solmuş açmayı unutan

Toprağı çatlamış susuzluktan kuruyan

Gülüne hasret bülbülü susmuş

Kapısına üst üste kilitler vurulmuş

Umudum yitmiş kadere küsmüş

Düzeltmeye bu canda yok idi derman

Mevla yardım eyledi bu kula heman

Bir yaren çıkardı karşıma bu derde derman

Söktü pas tutmuş kilitleri kapımdan

Geçen nice uzun zamandan sonra

Güneş gördü bu bahçeyi viran

Bahar getirdin sen gönül bahçeme

Hayat verdin kuruyan tüm çiçeklerime

Çiçeğe durdu bir bir kurumuş dallarım

Artık viran değil seninle gönül sarayım

Mis kokuyor bahçemde rengarenk güller

Yine nice şarkılar söyler bülbüller

Mevlasına seni tanıdığına şükrü niyaz eder

Ey yaren gönül bahçeme keyfince kurul

Verdiğin nice güzelliğin karşılığı budur

Seni gönülde taşımak benim için onurdur

Zaman ne gösterir bilinmez

Bir gün gelir eğer gitmek dilersen gönülden

Bil ki senden sonra bu bahçe olmayacak viran

Hatıralarınla  yaşayacak sonsuza dek  her an

Geçse de uzun yıllar seni unutamaz asla bu can

2 mayıs 2002', 'Gönlüm bir bahçe idi viran Çiçekleri solmuş açmayı unutan Toprağı çatlamış susuzluktan kuruyan Gülüne hasret bülbülü susmuş Kapısına üst üst...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gonul-bahcem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Ve Gece', 'hasret-ve-gece-filiz-turan-j7w5w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı

Gözlerimde uykudan eser yok..

Cesedim karanlıkta oturuyor bir köşede

Ruhum ise avare geziyor sokaklarda..

Omuzlarımda anıların ağır yükü..

Yüreğimde ve aklımda sen.

Yürüyorum yorulmadan bıkmadan..

Nereye gittiğimi bilmeden..

Etrafım alabildiğine yeşil..

ıhlamur ve leylak kokuları ruhumu sarıyor

Sarı ve beyaz papatyalar açmış görüyorum..

Kuşlar uçuyor masmavi gökyüzünde..

Onlar kadar özgür olmak istiyorum..

Yine bahar gelmiş ya sen nerelerdesin

İçimi bir sızı yakıyor derinden..

Hasret olmalı diyorum bu duygunun adı..

Bir bahar yağmuru yağıyor hafifçe..

Yağmurun damlacıkları göz yaşlarıma karışıyor.. 

Esen rüzgar okşuyor ıslanan saçlarımı..

Rüzgarın eli bana seni hatırlatıyor..

Çok uzaklardasın biliyorum..

Ben sadece hayalinle kendimi avutuyorum..

Oysa gecenin karanlığında..

Ne sen varsın nede bu güzellikler..

Var olan tek şey..

Olabildiğince karanlık ve uykusuz geceler..

3 nisan 2002', 'Gecenin bir yarısı Gözlerimde uykudan eser yok.. Cesedim karanlıkta oturuyor bir köşede Ruhum ise avare geziyor sokaklarda.. Omuzlarımda anı...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hasret-ve-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Rüzgarı', 'hazan-ruzgari-filiz-turan-faaai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoyrat esen hazan rüzgarı

Gönlümü savurur oradan oraya

Burcu burcu burnumda tüter

Nicedir hasretim sılaya', 'Hoyrat esen hazan rüzgarı Gönlümü savurur oradan oraya Burcu burcu burnumda tüter Nicedir hasretim sılaya...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hazan-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaren', 'yaren-filiz-turan-9xwxi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimsesiz sessiz bir deniz kenarı

dalgalar vuruyor ardı ardına sahile

çıplak ayak koşası geliyor içinden

bulutlar gömeç gömeç serpilmiş

Gökyüzü masmavi bir yorgan

Esen rüzgarla savruluyor çiçek kokuları

Uzaklarda gözüküyor papatya tarlaları

Kuşlar özgürce maviliklerde kanat çırpıyor

Çayırlara uzanmış suzan gökyüzünü seyrediyor

Kuşlar kadar özgür olmak nasıldır diyor

Karşı tepede gözüküyor bir ulu çınar

Gölgesinde  onu seyreden bir yaren var

Suzan sesleniyor yarene gücünün yettiğince

Ama gelmiyor yaren uzaklardan bakıyor

Suzan bir demet papatya ve gelincik topluyor

Soluğu tükenene kadar ulu çınara koşuyor

Oysa yaren gitmiş çok uzaklara

Çiçekleri bırakıyor ulu çınarın altına

Elbet gelir diyor bir gün tekrar buraya

O zaman alır çiçeklerimi kurumuş da olsa

Kesilen soluğunu dinlendiriyor çınar altında

Açıyor usulca gönül sandığını orada

Savruluyor rüzgarda silinmiş hatıralar

Rüzgar ne varsa bir bir alıp götürüyor

Sadece gönül sandığını dolduran hasret kalıyor

Yüreği sızlarken yanı başında yareni görüyor

Birlikte açıyorlar gönül sandıklarını yaren ve suzan

Savuruyorlar rüzgarın önüne ne varsa eskiden kalan

Anıların ağır yükü uçup gidiyor omuzlarından..

Nice güzel yeni sevdalar var yüreklerini dolduran..

1 mayıs 2002', 'kimsesiz sessiz bir deniz kenarı dalgalar vuruyor ardı ardına sahile çıplak ayak koşası geliyor içinden bulutlar gömeç gömeç serpilmiş Gökyü...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yaren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-ugur-erbil-s8c0s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arıyorum hiçbir yerde yoksun

Arıyorum günlerce bulunmuyorsun

Aşkım hasretinden kül oluyorum

Nerdesin, nerdesin, nerdesin aşkım

Şimdi bensiz uzaklardasın

Arıyorum soruyorum aşkım nerdesin

Yolunu söyle bana geleyim, geleyim yanına

Nerdesin, nerdesin, nerdesin aşkım

Bunca uzaklara kaçmanın nedeni ne

Peki beni sensiz bırakmanın anlamı

Ne yaptım sana ne yaptım ki bırakıp kaçtın

Nerdesin, nerdesin, nerdesin aşkım

Ne yeminler etmiştik senle ikimiz

Ayrılmanın “A” sı yoktu aklımızda

Söz vermiştik bir birimize peki ya şimdi

Nerdesin, nerdesin, nerdesin aşkım

Bu kaçışın sebebi neden ve kimden

Sonu nereye kadar bu kaçışın aşkım

Gel etme beni delirtme ağlatma aşkım

Nerdesin, nerdesin, nerdesin aşkım

Hasretin içimde oldu sancı

Gel sevdiğim beni üzme bu kaçıncı

Artık uyutmuyor beni yüreğimdeki sancı

Nerdesin, nerdesin, nerdesin aşkım.......', 'Arıyorum hiçbir yerde yoksun Arıyorum günlerce bulunmuyorsun Aşkım hasretinden kül oluyorum Nerdesin, nerdesin, nerdesin aşkım Şimdi bensiz ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nerdesin-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana Dilim', 'ana-dilim-ahmet-ozdemir-34ivl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha dün gibiydi sevgilim, 

“Inga! ”lı evrensel seslerle başlamıştı bu film.

Beş altı ayda ulaştığımız yarın, 

Ma’yı ma’ya, ba’yı ba’ya, de’yi de’ye; 

Ne’yi ne’ye eklemeler bilinçli, bilinçsiz.

Yalnız sen değildin şüphesiz; 

Hep müjdeli çığlıkları duyulmuştur anaların: 

“Yerim senin dilini, yerim senin dilini! ”

Doyumsuz öpmeler, okşamalar, gıdısına, dudağına; 

Güldükçe gamzelenen yanağına bir küçük ısırık...

Anımsıyor musun? 

Kıkır kıkır, kıkır kıkır...  Maskara şey, şımarık...

Harfi harfe, heceyi heceye; milim milim

Ba-ba, de-de, ne-ne, ci-ci; dilim dilim...

Yeni yeni yakıştırmalar,  yeni yeni buluşlar.

“Bay bay, baş baş, gel, gel, gel! ...”

Tel sarar oğlum tel sarar, tel tel! ...”

Artık anlam kazanan el kol hareketleri

“Day day”larla gelen dizlere derman; 

Bir adım, bir adım daha...

Başlayacak uzun ince yolun adıdır bu bilim! 

Bitmez tükenmez sorularla: 

“De de mu ne, mu ne an ne, ba ba mu ne, mu ne? ”

Sözcük sözcük senden benden bir akış, 

Sabır dolu; 

Kulaktan göze, gözden yüreğe, yürekten dudağa, dile, 

Ekleyerek sözü söze: 

Nakış nakış, 

Renk renk, ses ses, dokuduğumuz bu kilim, 

Desen desen, bağlanan köyüm, kasabam, il’im

Dilim dilim, ana dilim...

			Ahmet ÖZDEMİR', 'Daha dün gibiydi sevgilim,  “Inga! ”lı evrensel seslerle başlamıştı bu film. Beş altı ayda ulaştığımız yarın,  Ma’yı ma’ya, ba’yı ba’ya, de’...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ana-dilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzluk (Yalnız Gece)', 'umutsuzluk-yalniz-gece-mehmet-batihan-391v2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hava iyice soğudu

Rüzgar kutuptan esiyor

Karlı dağları sıyırarak

Bir cicim evim de yok 

Donuyorum iliklere kadar

Titreyerek bir cıgara tüttürüyorum 

Bir daha, bir daha

Bir cıgara daha

Üst üste… 

Dondukça tüttürüyorum

Ölüyorum soğuktan

Ve tekrar canlanıyorum

Seni düşünmektir bana hayat veren

Bekliyorum 

Yalnız gece gibi

Ve sonra kayıyorum

Bir yıldız gibi

Ateşten yanıyorum.

15.04.1997', 'Hava iyice soğudu Rüzgar kutuptan esiyor Karlı dağları sıyırarak Bir cicim evim de yok  Donuyorum iliklere kadar Titreyerek bir cıgara tüttü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Batıhan']::text[], 8.5, '{"poet":"Mehmet Batıhan","poet_slug":"mehmet-batihan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umutsuzluk-yalniz-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demeden', 'demeden-aykut-demirci-72bo6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kal demeden, kalsan yanımda

Dönüp baksan aniden

Gözlerim, gözlerinde..

Bir sıcaklık ararken

Sunsan sevgini, hesapsız..

Uzatsan ellerin

Boş kalmadan, soğumadan ellerim..

Dur demeden, dursan yanımda

Öylece kımıldamadan..

Sonra sarılsan, hiç bırakmasan

Bir olsak, bir yaşasak..

Öp demeden, öpsen aniden

Sevişmek, dudaklarda..

Ben demeden durdursan zamanı

Sonsuzluk güzel, seninle..

Saatler seninle, günler seninle, 

Aylar, seneler, bir hayat seninle..

Aykut Demirci

IQ''t 28.06021718 VM', 'Kal demeden, kalsan yanımda Dönüp baksan aniden Gözlerim, gözlerinde.. Bir sıcaklık ararken Sunsan sevgini, hesapsız.. Uzatsan ellerin Boş k...', ARRAY['Türk Edebiyatı','Şiir','Aykut Demirci']::text[], 8.5, '{"poet":"Aykut Demirci","poet_slug":"aykut-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/demeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabahtım', 'karabahtim-i-brahim-erkan-yesiltas-w4i2u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acep gülecekmi bu karabahtım, 

Gülsede anlamı kalmadı gitti.

Sevda sarayında kurulu tahtım, 

Aradıgı yeri bulmadı gitti.

Bağlamıştım umudumu kadere, 

Alışmıştım artık gamla kedere.

Sevda çiçeğimi nazik ellere, 

Vereyim dedim de almadı gitti.

Belliydi halinden bana küskündü.

Hıçkırık sesiyle yüzünü döndü.

Manalı manalı baktı yürüdü.

Dedi ki ''-Ahtımız olmadı gitti.''

Yaklaştım yanına, kolundan tuttum.

Dedi ki ''-Vefasız, sana umuttum.

Ne tez sevdin beni, ne tez unuttun.''

Dedim ki ''-Bahtımız gülmedi gitti.''

Hüzünlü gözleri yaşla dolmuştu.

Hazan vakti gibi rengi solmuştu.

Sinesinde ben ve kendi kalmıştı.

Giryanını sonunda silmedi gitti.', 'Acep gülecekmi bu karabahtım,  Gülsede anlamı kalmadı gitti. Sevda sarayında kurulu tahtım,  Aradıgı yeri bulmadı gitti. Bağlamıştım umudumu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkan Yeşiltaş']::text[], 8.5, '{"poet":"İbrahim Erkan Yeşiltaş","poet_slug":"i-brahim-erkan-yesiltas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karabahtim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim sensin anlasana', 'sevdigim-sensin-anlasana-salih-ozalasan-o85wk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer demişsem senden başkasına

Bir kere olsun seviyorum seni

Tek sevdiğim sensin anlasana

Neden anlamıyorsun  beni

Sana yemin bir kere dinle beni

Benden şüphe edeceğine

Ölmeden  mezara koy bedenimi

Cehenneme taştan diksinler heykelimi

Yakmasın ateş eritsin bedenimi

Damlasın aksın yerlere, çiyanlar yesin yüreğimi

Dilim olsun ateşe perde, yılanlar oysun gözlerimi

Demişsem senden başkasına sevdiğimi

Bilmedin bilemeyeceksin sende benim yüreğim

Sensin bu Dünya''da yaşama nedenim

İstesemde söylemez senden başkasına dilim

Sensin anlasana birtek yüreğimi verdiğim

Sensin geceler boyu yolunu gözlediğim

Hasretiyle yandığım, mecnun olup özlediğim

Birtek sensin senden başkasını neylesin yüreğim

Son sözüm sensin, sensin anlasana

Y.Tar.26-10-2002 Saat 16.20

(Dosta özel)', 'Eğer demişsem senden başkasına Bir kere olsun seviyorum seni Tek sevdiğim sensin anlasana Neden anlamıyorsun  beni Sana yemin bir kere dinle...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevdigim-sensin-anlasana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-ufuk-turan-9y7h7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokluğunda konuşmadım

Hiçbir gülü koklamadım

Hasret vurdu taştı amma

İnan sensiz ağlamadım GÜLÜM

Yağmur yağdı ıslanmadım

Kar döküldü uslanmadım

Hayalini yorgan yaptım

Yine sensiz uyumadım GÜLÜM

OY GÜLÜM

Mor dağlarda ay sümbülüm

Bu yer bu gök seni arar.

Gel kalbimi aç gör GÜLÜM

Senin sevdan ile yandım

Beden yandı tuzla sardım

Acın bile bir başka

Gül yüzüne türkü yazdım GÜLÜM

Gecelere gün bağladım

Uykulara can doğradım

Belki gözlerimi bile

Sensiz üst üste yummadım GÜLÜM.', 'Yokluğunda konuşmadım Hiçbir gülü koklamadım Hasret vurdu taştı amma İnan sensiz ağlamadım GÜLÜM Yağmur yağdı ıslanmadım Kar döküldü uslanma...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Turan']::text[], 8.5, '{"poet":"Ufuk Turan","poet_slug":"ufuk-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulum-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O', 'hep-o-mevlana-celaleddin-rumi-yutaf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk geldi, kan gibi

Damarlarıma derime doldu.

Beni benden aldı, 

Varlığımı sevgiliye doldurdu.

Kısaca; 

Bana benden kalan bir ad; 

Ancak ötesi hep o...', 'Aşk geldi, kan gibi Damarlarıma derime doldu. Beni benden aldı,  Varlığımı sevgiliye doldurdu. Kısaca;  Bana benden kalan bir ad;  Ancak öte...', ARRAY['Türk Edebiyatı','Şiir','Mevlana Celaleddin Rumi']::text[], 8.5, '{"poet":"Mevlana Celaleddin Rumi","poet_slug":"mevlana-celaleddin-rumi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hep-o-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asker', 'asker-gursel-colak-o8w1c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağda yiğit gezermi

Asker yüzü gülermi

İyi bakın resmime

Oğlunuz Gürsele benzermi

Saklayın resmimi rengi solmasın

Durdurun Güneşi erken doğmasın

İyi bakın resmime yerde kalmasın

Kıymetim yoksa ateşe atın

Ben bir askerim çoktur kederim

Saklayın resmimi bir gün ölür giderim

Ben ölürsem sizlere hasret giderim

Anasından ayrılan ASKER ağlasın', 'Dağda yiğit gezermi Asker yüzü gülermi İyi bakın resmime Oğlunuz Gürsele benzermi Saklayın resmimi rengi solmasın Durdurun Güneşi erken doğm...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asker-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koruyucu', 'koruyucu-gokcen-duran-5zkw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm, 

Bir yaşama gebedir

Çiçek tohumlarında.

Çiçekleri  rahminde  ölüm korur.

Beni muska gözlerin.

Kölelerin ve köleliklerin ülkesinde

Yaşamın kölesi ruhumu ve kalbimi

Hayaller ülkesinin tanrıçası korur

Beni, gözlerindeki bahar sevinci.

Rüyalara düşer yıldızlar bir bir

Yastığa düşmüş bozkır saçlarını

Hazan mevsimi muskaları korur

Ölüm, 

Bir yaşama gebedir

Çiçek tohumlarında.

Çiçekleri  rahminde  ölüm korur.

Beni muska gözlerin.', 'Ölüm,  Bir yaşama gebedir Çiçek tohumlarında. Çiçekleri  rahminde  ölüm korur. Beni muska gözlerin. Kölelerin ve köleliklerin ülkesinde Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/koruyucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-gokcen-duran-bh81d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O güzel gözlerin bana bakarken, 

Sevdan sel olup içime akarken, 

Yanımda değilken seni anarken, 

Çığ gibi büyür içimde ayrılık.

Yıllar geçti içimden atamadım.

Seni düşünmeden inan yatamadım.

Aynaya bir gün bile bakamadım.

Gözyaşı olur içimde ayrılık.

Ayrılık içimde şimdi bir kordur.

Sensiz gecelere katlanmak zordur.

Gördüğüm her kabusu hayra yordur.

Yangın olur içimde ayrılık', 'O güzel gözlerin bana bakarken,  Sevdan sel olup içime akarken,  Yanımda değilken seni anarken,  Çığ gibi büyür içimde ayrılık. Yıllar geçti...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Fark Edecek', 'ne-fark-edecek-gokcen-duran-g1bjh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha gelmişsin ha gelmemişsin

İkisi de aynı  ne fark edecek.

Gelişin su, gidişin şarap

İkisi de içilir ne fark edecek.', 'Ha gelmişsin ha gelmemişsin İkisi de aynı  ne fark edecek. Gelişin su, gidişin şarap İkisi de içilir ne fark edecek....', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-fark-edecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşinci İblis', 'besinci-i-blis-kucuk-i-skender-cwrcg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yığıntı: 

beklemez; gece, sesin süsüdür beklemez

örtülür başvuru aşkların

feylesof sırlarıyla, rahvan giden ömr.

söylemez; cinnet, bir serzeniş bahçesidir söylemez

sökülür takılarak

sökülür takılarak bütün kenarlarından şehr.

''oybirliğiyle yalnızız''

		der

		demez

		kuşu

birdenbire şaibe, birdenbire huşu; 

-söylemez; bu akşam birlikte uyuyalım

- ama sonra birbirine nüfuz eder rüyalar

- cereyana kapılır kalp, yalpalar

- vücut: tunç yalım. uyuyalım. Beklemez;', 'yığıntı:  beklemez; gece, sesin süsüdür beklemez örtülür başvuru aşkların feylesof sırlarıyla, rahvan giden ömr. söylemez; cinnet, bir serze...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/besinci-iblis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yeryüzü Öznesi', 'bir-yeryuzu-oznesi-kucuk-i-skender-fho7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1. gece gelen gece

yetmiyor münzevi kelimelerin kuytularına

pıhtılaşan çöl: yakıp yıkmak için bir kente

gittiğim günden beri biraz felç istemiştim

yeryüzünden, ve biraz öğütülmüştüm terle - -

bir ritmin bütün acizliğiyle çizildiğim

resim kağıtlarında beni bitiren kadın, o

sahte atölyenin eskimiş bir organı gibi

esrarlı bir dokuyla örtülmüştü portrem! 

tabutumu dört siyah adam dışarı çıkarttı

dört siyah atın çektiği arabadaydı ruhum

dört gözlü doğanın prensesine giden yolda

devrildi tabut, şimdi tüm boşlukları doldururum, 

der demez: tılsım gizlemiştim, bana sunulan

alkol harfleriyle oldu adım, çekilen silah

fırlatılan bir bıçak gibiydim o kadınla, bilirsin

katil bir kadın saklar bir parça içinde

her çocuk; ve yine bilirsin ki kimi aşklar

kediden firar etmiş keyifli bir öğle uykusudur

2. heves eden seda

içindeki heykele negatif bir kan aranıyor

kentin

bir yabancıyı idrak ediyorum

ki ilkokulu ne zor bitirdi yeryüzü

karnesinde tek kırık kalbim

derisini yitirmiş hayvan gibi gece

senden likör yapılmıyor ölüm

3. mr. pickwick''in son serüveni

s e v i y o r s u n  b e n i, anladım: 

güneş tutulması gibi gülümsemen çünkü; 

ö z l ü y o r s u n  b e n i, anladım: 

öpmesen, hemen baban ölecek çünkü; 

g i z l i y o r s u n  b e n i, anladım: 

ne vakit seni düşünsem, 

	yeryüzü evinden kaçıyor çünkü; 

4. misafir cinayet

gülle tartışıyor karanfil çocukta

geri verilmeyecektir hüzün hülya; az daha; 

ne pornografi suresi ne de

atlıkarıncası dışa dönük kabe, 

YERYÜZÜ! 

çağırma vücudumu, artık orada değil! 

sessiz film

	oyunu kurallarıyla anlat bakışımı

sessiz film

	gibi kalsın gururum anlaşılmadan

		talanında; 

dokunulmazlığılotuslarınınkuyularındauykuların, 

bir sesli harf

	gibi yalnızlığım

bir sessiz harf

	gibi dudağımdayım

ürk! o çemberler içre yazılı rakamlar

çoktan yuttu seksek oynayan çocukları, 

ve o seksek taşı

ve o seksek taşı

	kim bilir hangi gezegenin

uydusu şimdi, sona eren baygın uzayda; 

ya içeri dolarken artarsa eğer bir parça rüzgar

bana da ölüm ayırın, çok az vaktim var. velakin

bu kanayan gözü göbekdeliğimin

üstüne yerleştiren mecbur mecmua

	bilinçaltım bir müze, hatıralara; 

ey karanfil, tartışma gülle çocukta

komünist maestro bu gece sahne almayacak artık! 

gidiyormuş: 

ağırlaşır yağmurun iade etmediği karanlık

bırak gitsin: 

hiçbir caddeye çıkmayacak o sokak artık', '1. gece gelen gece yetmiyor münzevi kelimelerin kuytularına pıhtılaşan çöl: yakıp yıkmak için bir kente gittiğim günden beri biraz felç iste...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/bir-yeryuzu-oznesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakıverilen', 'birakiverilen-kucuk-i-skender-y0agq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'pusudadır

	içine şarapnel düşmüş menekşenin

	diz çökerek altından geçtiği kında

	yalanlarını kurutarak büyüyen uyku.

pusudadır

	sayıkladığı isme giydirdiği entarinin

	kollarını yüzünde kavuşturarak süslediği

	o kutsal vuruluşlar geçitindeki süvari sükutu.

pusudadır

	kalındığı yer hatırlanabilsin diye

	bir insanın kalbine bırakılan

	pırlanta düello kılıcı.

pusudadır

	tefsiri alnına yazılı kara cübbenin

	mabedin portmantosunda asılı durduğu

	koridorda duvara çakılan kirli su.

pusudadır

	ateşin sönüşündeki zeka pırıltısı.

pusudadır

	sarkıtılan ipe tutunarak inen meleğin

	astarındaki semai ayini.

pusudadır ah

	kontrbas, trombon, obua, ve flavta

	şehre dönüşünde kırılacaksa eğer

	israfilin borusu.', 'pusudadır 	içine şarapnel düşmüş menekşenin 	diz çökerek altından geçtiği kında 	yalanlarını kurutarak büyüyen uyku. pusudadır 	sayıkladığı ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birakiverilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci İblis', 'birinci-i-blis-kucuk-i-skender-dwm9k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüksek kirlenmelerin özet tanrıları

iniş hızını arttırarak aşklarda, 

uzaklaştırılmış kent ışıkları içinde

kendi ifadeleri üzerine uzanarak

rüya sondajlarının son huzursuz uleması

geciktirmişlerdir kimi yolların karanlığını; 

unutmaktır ilk dinsel yorumu akşamın, 

kesilmesi gibi elektriğin her vücutta

biçimlendirerek cam yüzlü feshi istenen

adamı

bir içki daha almaktır bardan, öncesizlik.

o halde, yazılan mektuplar neyin tümlecidir; 

neyin içerlenmesidir başlangıç antları; 

indirilen tek balta darbesiyle devrilmek

değil midir sözle aldatılan;', 'yüksek kirlenmelerin özet tanrıları iniş hızını arttırarak aşklarda,  uzaklaştırılmış kent ışıkları içinde kendi ifadeleri üzerine uzanarak ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birinci-iblis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birinci Uluma', 'birinci-uluma-kucuk-i-skender-trjij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'büyük ağrı kaplayacak rıhtımını; kaç kalibre

bilmiyorum ruhum

		at geliyor kişniyor

		büyük ağrı kaplıyor

ve deniz üstüne birşeyler giyip gidiyor

ve deniz üstüne birşeyler

ve deniz susamış ona su ver

oyuğuma bi türlü yerleşmiyor aşk

			 aşk

taşıyorum yeryüzünden sana ne benim yüzümden

			artık, 

tenin ne olabilir ölüm varken

gel bıçağınla

taklit et kalbimi

sen saplamazsan eğer

bıçak küsecek

bıçak üstüne birşeyler giyip gidecek

büyük ağrı kaplayacak rıhtımını ve tekne yanarak

yan yatacak çocukluğumuza doğru paslanacak su

saçları taralı delikanlıları korkutmaz çünkü

kibar rüzgarlar', 'büyük ağrı kaplayacak rıhtımını; kaç kalibre bilmiyorum ruhum 		at geliyor kişniyor 		büyük ağrı kaplıyor ve deniz üstüne birşeyler giyip gi...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/birinci-uluma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sırlı', 'cok-sirli-kucuk-i-skender-3s0jc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlamlı temasın kükrediği ırmağın

boyunda vurulan prens erkeği.

oyun biter ve yırtılır kapanırken perde

yılanın gözlerinde iguana boncukları ve anı

yaz odalarında kafeslendiğim çarşaflar

bir mor kuşağın boşalıp inci belden

usulca yuvarlandığı paslı zümrüt ant

acıların hiç tükenmeyen cin çağrıları

mimozaların yanından geçti hayat

kırık sokakta kan bandoları

ve birinin yatağından diğerinin yatağına

atılan yaralının aşk tutanakları

odanın beşinci duvarına kendimi astım', 'anlamlı temasın kükrediği ırmağın boyunda vurulan prens erkeği. oyun biter ve yırtılır kapanırken perde yılanın gözlerinde iguana boncukları...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cok-sirli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöküyoruz Ölü Bir', 'cokuyoruz-olu-bir-kucuk-i-skender-3gkin', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'greenwich''te saat yok: gölge bir çiy

tanesi gibi düşüyor boğulduğum suya

bakıyorsunuz yorulmuş sokak köpekleri

gibi nefes nefese gözlerinizden tanış

tığım ilk meridyen mühendisi kendisi

bir katalogta yanyana basılı durdu

ğumuz bir zamanlar eski bir pul arkada

şımdır söylüyorum

dumanın altında kalanların malafatı

kalkmış yürümüş bilgeye öğretiyor

artık geri gelmeyeceğini sabaha

doğru örtülüyor üstümüz bil

inmeyen bir elce; bir veda

tarifi olmasın sakın intihar da

da bulundum bir süre sessiz diyorum sen

inle diz çöküyoruz ölü bir çocuğun önünde

sen ciklet çiğniyorsun ben esrar içiyorum

greenwich''te saat yok: green sleeves

i çalıyor unutulmuş bir cazband söylüyorum

arkadaşımdır söylüyorum inatla sen anla', 'greenwich''te saat yok: gölge bir çiy tanesi gibi düşüyor boğulduğum suya bakıyorsunuz yorulmuş sokak köpekleri gibi nefes nefese gözlerinizd...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cokuyoruz-olu-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinah', 'dinah-kucuk-i-skender-8fzaz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yükselerek, gidlmiş uykunun

yaşanmakta olan sathi rüyasında

bekletilmiş sunu. Ben yok oldum! 

	soyadım söylenmesin;', 'yükselerek, gidlmiş uykunun yaşanmakta olan sathi rüyasında bekletilmiş sunu. Ben yok oldum!  	soyadım söylenmesin;...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dinah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'H. Adalet', 'h-adalet-kucuk-i-skender-zp9f2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir erkek kardeşim olsa ölür bu bir mısır

	sanatıdır diyerek elindeki ömür mecmualarını

	şerbete batırırsa çekirdekli yaz mevsiminde

	şüpheli; 

Aşklar yaşayarak kalbi karıncalanan o kızıl

	derili çocuğun toz dudağıyla zalim bir

	meşgale edinircesine ellerini kavminin

	büyüsünde seyrelttiği; 

Kalacak ad: seçilmemiş ruhun orospuluğu, söylenirse, 

	biri kendi gözlerini ele verir. bir cildin

	leoparları örgütlemesi

	gibi kararsız başlarsa sanrı, sesinde

	herkesi yenecek bir boğa görülür; 

Ellerini açıklayarak geçirdi hayatını bir saniye

	müsayedeyle her yerinden ayağa kalkmış

	tebessümün boşluğunda diz çöküvermiş

	pencere kenarlarıyla yalnızca az pişmiş

	ölüleri ellerinden tutup cennetten

	cehenneme karşıya geçiren; 

Neden tozlanmaz birlikte terkedilmiş evlerdeki

	pikaplar ve neden, kırıldığında bir 45''lik

	plak, çığlık çığlığa kurumuş bir nehre iner

	yüzlerce martı ve leylek; 

Lacivertler ve bu ben!', 'Bir erkek kardeşim olsa ölür bu bir mısır 	sanatıdır diyerek elindeki ömür mecmualarını 	şerbete batırırsa çekirdekli yaz mevsiminde 	şüphel...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/h-adalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mendebur Sureleri', 'mendebur-sureleri-kucuk-i-skender-nnqu3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ilk sesin med''inde dolunay büyüdü

düşleyerek geçtik yanan yılan ağzından

iri gözde damarlarını sürükleyen o bakış

içerisözlerin karanlık hiddeti, o çok zindan

o duyulmaz kundaklanış, yangın, o son yanış

biliyorduk, ki yanlıştı korkmak

yukardaki mezarlıklardan - - tecrit

aşklardan ayıkladığımız tebessüm: hüsran, ve

o tesadüfi sararış. Hani: sevdalım! içine

giden gizligeçitte

kaybolmuştum ya o gece, ruhuna açılan

gizligeçitte, elimde et mum, ötekinde

enzim bileziklerim.. dudak bukleleri..

biliyorum, ki bazen bu kent yoktur

terkeden, özlediğim değil

kaçırdığım çağdır. Nasıl yaparsın bunu, 

omuzlarıma bakır

	          tüylerime altın otu

diyen sen nasıl yaparsın bunu, 

(annelerinin tuttukları çarmıha gerili

	bütün oğullar; hatalarımız

veresiye, hatalarımız çocuk soygunu)

biliyorum, ki bazen bu kent yoktur

yalnız tersine büyüyen toz bir ur

gibi taşımaktır taşımaktır taşımaktır, 

taş bir ırmaktır aşk

aşk, sende taşırmak''ı yüzüme taşırmaktır

cin düşmüş dolunaylarda ben peri

şan, sen gül

yabani. Al / beni. Gizligeçitte öldürüyor

çünkü tayı alnından öpen elişi kişi! .

Ya da bir varsayıma göre

	çürümüş misafirim ayın

yatakodası penceresinden görülen sahi

le dokunduğu yerde- o zaman. Bacaklarım

plastik ve gömleğimin açık yakasından

görülebilecek kadarki göğsüm üstüne

neşterle çizilmiş bir harf görürsen

bu harfin açtığı yaralardan akankan

tuzlu ve hafif peltemsiyse.. Al / beni. Mahşer

gebedir ihanete!', 'ilk sesin med''inde dolunay büyüdü düşleyerek geçtik yanan yılan ağzından iri gözde damarlarını sürükleyen o bakış içerisözlerin karanlık hid...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mendebur-sureleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zahiri Ayna', 'zahiri-ayna-kucuk-i-skender-d8027', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''bize gönderilmeleri yetecekti''

- onu burada bulmamaya çalış; şal

liköründe

üstüme giydiğindi.

Ve genç erkekti haçı getiren

tanımadıkları ama örtündükleri, 

haçlı yaşlı kadın da götürecek

bir elinde bir tepsi örümcek

bir elinde bir tepsi örümcek', '''bize gönderilmeleri yetecekti'' - onu burada bulmamaya çalış; şal liköründe üstüme giydiğindi. Ve genç erkekti haçı getiren tanımadıkları am...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zahiri-ayna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlari', 'caglari-sabit-i-nce-dd9xt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşık Çağlari’ye

İkibin yılının Ekim ayında, 

Uyutmadı beni Aşğk çağlari, 

Asillik var belli onun soyunda, 

Avutmadı beni Aşık Çağlari.

Ey aşık çilemiz bitecek sanma, 

Allah’ın aşkına bizi pek anma, 

Biz yanmışız etme bir de sen yanma, 

Soğutmadı beni aşık Çağlari.

Gecenin üçünde derdimiz arttı, 

Hollanda elinden değnek fırlattı, 

O nurlu değnek ki gözüm parlattı, 

Dağıtmadı beni Aşık Çağlari.

Aşkın ocağı mı, pınarı mısın, 

Yesevi Dedemin çınarı mısın, 

Yunus odununun yanarı mısın, 

Kavurtmadı beni aşık çağlari.

Ey aşığım sürçmüş dilim affeyle, 

Sözlerim galatsa bakma, def eyle, 

Gel İnce kervanda sen de saf eyle, 

Yanıltmadı beni Aşık Çağlari.

Sabit İnce Kayseri 4.10.2002', 'Aşık Çağlari’ye İkibin yılının Ekim ayında,  Uyutmadı beni Aşğk çağlari,  Asillik var belli onun soyunda,  Avutmadı beni Aşık Çağlari. Ey aş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ters Cennet Çocuğu', 'ters-cennet-cocugu-kucuk-i-skender-qh7qw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ihtiyaç hocası kara cinin abluka aşklarla prensi sahiplendiği

ela matrikste elleri yapışık kuvarslarla ölü bayrağı selamla-

yarak bir sembolik attraction içinde kıpır güller

yaralı ganymedes

bıçaklı sabit

lekelerin zorunsuz barında alkol meleğinin tutuşan

strafordan kalıbı -iten, büken, kanırtan- hınç sebebi birle-

şik-katı ve-yorucu gölgeliği bir saksofon hışırtısı altın-

da

ezildi ecel

o nimçehrelerle beraber indiği katolik yaptırım -siniruçla-

rında karanlığın parmakizlerinin zinasına ihbar edilmiş ka-

maşma taktiği- yortu ve hiddet: beceriksizce gözakışı

öbür dizlerin başka topuklara çarpması müziği

ergiyen gövde damlası kuşa konarken yakalarında bir bunaltı

redoksu yaşanan yılların çöpkutularında aklanan sanık tutum

zenci kıssahan: gittikçe artan büyünün kafesi ardından - -

ney üfürür emel kalp nen olduğunda - -

siklamen akıntısı buruşuk aurora yitik habis

cadıkarga uçartüter lesbos''da Biten tırnak pseudo yırtılan

camdan

gemici ve ıtri pusulaya takriben secde edeceklerdi Ve hadis-

siz ve serhatsız

ve meal - - kromda mesafe olunur woodoo blues

anubis regle gelir tay ormanından İnsan beni hatırlamaz

alışkanlığın radyoaktif taneciklerinden kokina yaparak

iseolog kuru kış birikintilerinde eskiyen bir sevdalının

hep kuşku kutusunun lamelerine kaatilin eli batar o

yoksa garbarek

eşyanın etrafı

eşyanın eşrafı

yorucu bütünlemelerin beyin lavmanında sonrasız ile

ışık takibinde sualsiz ve usulün bozgunu

ve mürekkep avı

gizli çekmeceler sokağı

ve cinnet - - ve net cin

o protokol

siyah kadife nazar düşüşünde anını giz eden kuyum

yar

zikir

kum

tiz

maşuk

tokatlıyarak ikiye bölünen

O Ters Cennet''te kuyusuna sarkarak kaybolan seslerden

Çok şiddet yaşatarak kimsesizlikle ölçülebilen yaratı-

Cılığını tanımsız bırakabilme saadetine erecektir Ki

Tensiz yorgunluğunu tasvirinde buldurduğu eski zaman

Dağınıklığında belirsiz ve billur bir görüntü parola-

Sı peşinden küf ile adlandırılmış

O Ters Cennet Çocuğu gettosunda bir boyut rozeti ile

Kimliğini kölesinin karanlık göğsüne söndürdüğünde o

Çıkarımsız yalanlarından ve öncelerinin kurallarından

Artarak şekillenen küslerinin neyi temsil ettiğini bi-

liyord

Uzayan yarılarında O Ters Cennet Çocuğunun

bir söz tekrarıyla gelgitlendiği uç uçurum

anlayışsız imgelerden süprüntü bir fark o-

oluşumuydu Ve son düellosunda düet yaptığı-

nı herkesten gizlediği kirli hüznü bir bu-

za sürerek ''burada kara hiç görünmez'' di-

ye bağırdı

Toplanıp karaldıktan sonra suratlar yeni - -

den dağıtıld

o protokol', 'ihtiyaç hocası kara cinin abluka aşklarla prensi sahiplendiği ela matrikste elleri yapışık kuvarslarla ölü bayrağı selamla- yarak bir sembol...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/ters-cennet-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-sabit-i-nce-35lyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşık Çağlari’ye-

Bir kapıdan girip birinden çıkan, 

Bu handaki yolculardan birisin.

İnsanlık adına bir ışık yakan, 

Hacıbektaş erlerinden erisin.

Ey yolcu gardaşım sorum sanadır, 

Sözlere aldırma esas manadır.

Bütün yolculuklar sonsuz, sonadır, 

O zaman ki dirilerden dirisin.

Karanlık geceye yoldaş olmuşsan, 

Canının içinde canan bulmuşsan, 

Vardım derken yarı yolda kalmışsan, 

Bilesin ki ya cin, ya da perisin.

Yalnızlığı yoldaş ettim yar deyi, 

Açtım şu sineyi al da yar deyi, 

Çok çukurlar gördem bura yar deyi, 

O zaman ki ahmakların ser’isin.

Bu öyle bir sevda yaktıkça yakar, 

Her fert dayanamaz canından bıkar, 

Yandıkça dumanı başından çıkar, 

Bu ateşte zerrelerden zerisin.

İnce ince yanan dumanım böyle, 

İstersen alay et gönlünü eyle, 

Bir şey anlamışsan dostlara söyle, 

Onlarda yansın da böyle erisin.

Sabit İnce Kayseri 4.10.2002', 'Aşık Çağlari’ye- Bir kapıdan girip birinden çıkan,  Bu handaki yolculardan birisin. İnsanlık adına bir ışık yakan,  Hacıbektaş erlerinden er...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yolcu-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaleme', 'kaleme-sabit-i-nce-hd4qq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin dokuz yüz elli dörtlü yıllarda, 

Bir adem oğluyum geldim aleme.

Ne tozlar, çamurlar gördüm yollarda, 

Anlat diye emir verdim kaleme.

Al eline ne diyorsan yazayım, 

Ferman eyle dağıtayım, bozayım.

Istiyorsan kuyu bile kazayım, 

Rezil edem seni cümle aleme.

Ben ne dersem onu tek tek sırala, 

Herkese yaklaşma, biraz arala.

Bazen sorar isem sana parola, 

Hazır ola geçip de dur selama.

Sorarlarsa de ki emir kuluyum, 

Kalem iken nasıl kazma oluyum, 

Senin yitiğini ben mi buluyum, 

Gücüm ancak yeter benim kelama.

Gel kalem inadı bırak bir yana, 

Istersen dönersin sen dört bir yana, 

Acımadan kıyarsın sen insana, 

Sebep sensin çektiğim şu belama.

Yeter ince daha fazla yazamam, 

Sana uyup lain gibi azamam, 

Takdirde olanı ben de bozamam, 

Emlik kuzu gibi boşa meleme. 

Sabit İnce Kayseri 4.10.2002', 'Bin dokuz yüz elli dörtlü yıllarda,  Bir adem oğluyum geldim aleme. Ne tozlar, çamurlar gördüm yollarda,  Anlat diye emir verdim kaleme. Al ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
