INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinanpaşa', 'sinanpasa-behcet-necatigil-vzkl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yanı bir uzun cami duvarı

Çılgın akan taşıtlar bir yanı

Caddeye inemezsin

Kalın demir parmaklık arada

Üç kişi ancak sığar

Dar geçit - -

Buradan geçeceksin! 

Atmak için üstünden yorgunluğu

Biraz hava almaya

Dalgın gece uzakta

Bir ümit

Esintisi denizin.

Kim getirip bıraktı

İşte gene orada

O dar geçitte

Yapışık gibi duvara

Bir kad
..........
..........', 'Bir yanı bir uzun cami duvarı Çılgın akan taşıtlar bir yanı Caddeye inemezsin Kalın demir parmaklık arada Üç kişi ancak sığar Dar geçit - - ...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sinanpasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun', 'gidiyorsun-murat-kayabas-lcdp8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gördüğümde gözlerime düşen parıltı

Seslendiğimdeyse  dilime yayılan tattın

Oysa şimdi yoksun.

Düşüncelerimde esen tatlı bir rüzgar bıraktın

Hüzün kokan.

Üzerine çiğ düşen yapraklar kadar taze

Buram buram kokan çiçekler kadar alımlıydın

Oysa şimdi yoksun.

Görebilmek, 

Seslenebilmek, 

Dokunabilmek sana

Şimdi çok uzaklardasın, mümkünmü? 

Mümkünmü

Kalbimi parçalayan fırtınayı dindirebilmek

Gözlerime düşen yorgunluğu, 

Dilime yayılan acı tadı silebilmek.

Gidiyorsun

Mümkünmü sana yetişebilmek?', 'Gördüğümde gözlerime düşen parıltı Seslendiğimdeyse  dilime yayılan tattın Oysa şimdi yoksun. Düşüncelerimde esen tatlı bir rüzgar bıraktın ...', ARRAY['Türk Edebiyatı','Şiir','Murat Kayabaş']::text[], 8.5, '{"poet":"Murat Kayabaş","poet_slug":"murat-kayabas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidiyorsun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğduğum Kasaba', 'dogdugum-kasaba-fethi-giray-zbvru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öyle bir kasabada geçti ki; çocukluğum, 

Babam ekmeğimizi kazanırdı denizden, 

Ben akşama kadar rıhtımda ıslık çalardım

Ve yorgun gemiciler dönerdi seferden.

Üç odalı evimizin, 

Deniz kokardı her odası.

Sedef pullu balıkları ne kadar severdim, 

Ne iyiydi denizden korkarak ağlaması.

İhtiyar balıkçılardan dinlerdim: 

En korkunç ejder masallarını

Ve daima düşünürdüm; 

Allahın bu kadar suyu nasıl yarattığını.

Bembeyaz minareli, ufacık kasabamızın

Bayram sabahları hala yaşar gözlerimde.

Şimdi kimler oturur bilmem? 

Deniz kokulu evimizde.', 'Öyle bir kasabada geçti ki; çocukluğum,  Babam ekmeğimizi kazanırdı denizden,  Ben akşama kadar rıhtımda ıslık çalardım Ve yorgun gemiciler ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogdugum-kasaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyaya Davet', 'ruyaya-davet-fethi-giray-b4nkh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçüğüm rüyalarımda seni göremiyorum

Şefkat dolu ufacık eller; 

En tatlı uykularımda sihirbazlar

Ve azat edilmiş yıldızlarla sefer.

Küçüğüm rüyalarımda; 

Bıraktığın gibi mahzun ve ürkek melekler

Rengarenk cüceler göz kapaklarımda

Senin geleceğin zamanı bekler.

Küçüğüm rüyalarımda; 

Gökler dolusu aydınlık

Sana oyuncaklar hazırladım

Ve mavi boncuklardan nazarlık.', 'Küçüğüm rüyalarımda seni göremiyorum Şefkat dolu ufacık eller;  En tatlı uykularımda sihirbazlar Ve azat edilmiş yıldızlarla sefer. Küçüğüm ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruyaya-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-fethi-giray-fhbnm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler nerede? 

Kendimi özlediğim mesafelerin başı, 

Huzurun mahzunlaştığı oda, 

Gel, gel ey! Sabrın kara taşı.

Dört duvara çizilen, 

Günahlardan ürperiş; 

Azabın eridiği oda! 

Kapılar gerinir: bekleyiş, bekleyiş.

Resimlerde yaşıyan kara sevda, 

Gölgelerin sıtmalı mahşeri.

Korkunun soluduğu oda

Ve sırrın dudaklardan, dudaklara seferi.', 'Geceler nerede?  Kendimi özlediğim mesafelerin başı,  Huzurun mahzunlaştığı oda,  Gel, gel ey! Sabrın kara taşı. Dört duvara çizilen,  Günah...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Ortasında', 'sokak-ortasinda-fethi-giray-7qzqt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bomboş bir sokak ortasında, 

Yakaladım vehmin kemik elinden; 

Gecenin kafa tasında

Beni sordular, benden.

Bomboş bir sokak ortasında; 

Sallanarak ıslık çalmak, 

Sızmak kaldırım taşlarında

En temiz itiraflarla ağlamak.

Bomboş bir sokak ortasında, 

Düşünmek: terkedilmeyi; 

Müşteri bekleyen o kadınlar kadar, 

Duymak, sefilce duymak geceyi.

Bomboş bir sokak ortasında, 

En sonu yürümek yorgun adımlarla; 

Geceyi duymak

Ve hiç konuşmamak insanlarla.', 'Bomboş bir sokak ortasında,  Yakaladım vehmin kemik elinden;  Gecenin kafa tasında Beni sordular, benden. Bomboş bir sokak ortasında;  Salla...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sokak-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-yasar-aslan-hk4om', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gece firar edecektik? 

Ben saçlarına yıldızlar serpecektim, 

Güneşi koynumuza alacaktık kuşluk vakti.

Öpüşmeyi bilmiyen dudakların.

Korkma onlara  öpüşmeyi bilmediklerini söylemiyeceğim.

firar edecektik bu gece.

Zemheri ayazında dona kaldı sevinçlerim. 

üşüyorum.

Söyle hangi  taş yarar başımı? 

Hangi ateş yakar su boğar? 

Hangi içki sarhoş eder ki beni? 

Hangi evin kapısını tekmelesem de bulsam seni? 

Nerdesin Gülüm? 

Acıyor,  Kanıyor  yüreğim bu gece...', 'bu gece firar edecektik?  Ben saçlarına yıldızlar serpecektim,  Güneşi koynumuza alacaktık kuşluk vakti. Öpüşmeyi bilmiyen dudakların. Korkm...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-gece-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Kalleş', 'dost-kalles-gursel-colak-f6zdd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost bildim ve güvendim

Her sırrımı söyledim

İsteklerine boyun eğdim

Vurdu beni dost kalleş

Ne istedi masum candan

Vurdu beni her bir yandan

Attı çukura acımadan

Attı beni dost kalleş

Her tarafım kanlı kanlı

Gömdü beni canlı canlı

Sanmıştım biraz insaflı

İnsafsız cıktı dost kalleş

Toprak içinde kıvranırken

Acımadan bana bakarken

Toprağı üzerime atarken

Güldü bana dost kalleş

Son nefesimi alırken

Gözlerim usul usul kapanırken

Geride kalanları düşünürken

ALLAH seni affetsin dost kalleş', 'Dost bildim ve güvendim Her sırrımı söyledim İsteklerine boyun eğdim Vurdu beni dost kalleş Ne istedi masum candan Vurdu beni her bir yandan...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dost-kalles-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arsız Ölüm', 'arsiz-olum-asim-ozturk-rknw6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorulur gülüşün

Arsız bir gece başlar

Dudaklarının kıyısında

O gürültüyle geçen trenlerin

Bırakıp gittikleridir

Senin sığınağındaki yabancılık

Söyle ne kaldı, 

Söyle; 

Tanıdık yüzler

Yapılar

Bir bir yıkıldılar; 

Camları renkli vitrinlerin üstüne düşen

Bulutların gölgeleri de kirlendi

Bu sokaklar

Bu kaldırım taşları

Her gün durmadan yenilenen

Bu arsız gülüş, 

Akşamla birlikte saldırıyor

Tanıdıklarıma; 

Uzaklardan, 

Sesinden tanıyorum palmiyeleri

Pörsümüş boşlukları döven çığlıklarından

Kanadı kırık kuşlar gibi

Kaldırımlara gölgesinin düşüvermesinden

Sen de yalnız kaldın

Kıyının mavi yeliyle savrulan

Palmiyelerin sesi de

Kirlendi düşlerin

Umutların

Bu kent

Bu İzmir

Sulusepken yağmurların çocuğu

Durdurak bilmeyen imbat

Arsız bir gecede kaldı', 'Yorulur gülüşün Arsız bir gece başlar Dudaklarının kıyısında O gürültüyle geçen trenlerin Bırakıp gittikleridir Senin sığınağındaki yabancıl...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/arsiz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında Ben Yoktum', 'aslinda-ben-yoktum-asim-ozturk-xjtey', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep dünün anılarıyla yaşayan

Kanatları kırık güneş ışığı

Devinimsiz bir zaman saatidir

Durur evrenin kıyısında sesim, 

Aslında ben yoktum, 

Yitik tarihlerin örümceği sarıyor

Sarışın güneşlerimi; 

Durup durup bunaldığım

O kurşuni öfkelerin ardındaki gece

Kınından sıyrılmış pasların

Demirdeki gölgesi, 

Tüketiyor bak, 

Dudaklarımdaki sözcükler ülkesini, 

Irmaklarıma ayışığı düşmüş

Vadilerden geçenken, 

Toz bulutları kalacak ardımda

Giderek yabancılaştığım

O dar odalardan sonra

Penceresi evren maviliklerden

Çıkıp geleceğim, 

Kuşların pembe ayakları

Islanmış olacak sularda, 

Ötelerden

Çok ötelerden

Kanatları kırık güneş ışığı

Süzülerek inecek avuçlarıma

Kırşıl kıpırtılardan sonra

Yüreğimde tanıksız sevinci başlayacak

Adsız arılar sürüsü

Hep birden kanat çırpıp

Mavi evrenimin penceresinden

Yitiklere karışacak, 

Ey zaman

Aslında ben yoktum

Kuşlar ve ırmaklar yoktu.', 'Hep dünün anılarıyla yaşayan Kanatları kırık güneş ışığı Devinimsiz bir zaman saatidir Durur evrenin kıyısında sesim,  Aslında ben yoktum,  ...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/aslinda-ben-yoktum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avlak', 'avlak-asim-ozturk-ssahk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çizgiydim renksiz

Zamanın kıyısında çocuklar gibi oynardım

Kum göllerine bakardım

Yakutları sayardım, 

Derinlik daha yaşanmamıştı o zaman

Diplerin uykularını kaçırmamıştım

Elimde kandil gibi sallayıp dolaşırdım

Sözcüklerim kirlenmemişti

Aklığın adı yoktu

Hem geceyi, hem gündüzü severdim

Dilimin kentlerine bu kadar yağmur düşmezdi

Boğulmazdı karalar, 

Kirlenen salt gecelerdi.

Körlüğün kuyusunda uyurdum

Ne söyleseler sırılsıklam

Kovalarla beni çekerdi duygular, 

Zincirimin demir sesi

Taaa uzaklardan gelir

Körfezimi bir baştan bir başa geçerdi.

Eğrimin adı kalmamıştı

Tüm teğetler aklıklar içinde

Yeşilin kanatları vardı

Ormansa yuvasız, 

Sürülerle akıp giderlerdi

Göçlerin hep gurbetliğidir

Bulutlara gömüp yoksadığım

Acıların gözlerime demirlediği yerde

Kendi başıma karalar içinde

Renksiz çizgilerin

Körpe avlağıydım.', 'Bir çizgiydim renksiz Zamanın kıyısında çocuklar gibi oynardım Kum göllerine bakardım Yakutları sayardım,  Derinlik daha yaşanmamıştı o zama...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/avlak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Buradayım', 'ben-buradayim-asim-ozturk-h9cgw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derin çığlıklar bıraktım ardımda

Gecelerin taşıyamadığı düşler

Esmerliğin ağırlığından çatırdayan

Kırgınlıklar, 

Hep sevmenin fırtınasıyla dolaştım

Yangınımı yanıbaşımda taşırken

Alevden çok, 

Kızılın kendisi oldum uçurumun dilinde, 

Benim küllerimdi, 

Vadiyi dolduran gecelere verdiğim ad; 

Bu vur kaç

Bu yıkımdan yaralarla çıktım hep

Bir gözümü yitirdim

Karanlığa sürgünümde, 

Neyi özlediysem

Hep yitikler limanına çıktı yolum

Fırtınanın yüreğine bıçağı

Ben sapladım, 

O yüzden kırmızı bültenlerle aranır adım, 

Derin yokluklar bıraktım ardımda

Önce adımı sildim, 

Sesimin vadilerine girerek

Neyi yüklediysem sözcüklerime

Hep ben suçluyum, 

Acının da sevdanın da önünü kestim

Olanca çıplaklığımla

Seslendin yaşama, 

Ben buradayım

Ben burada

Ben.........', 'Derin çığlıklar bıraktım ardımda Gecelerin taşıyamadığı düşler Esmerliğin ağırlığından çatırdayan Kırgınlıklar,  Hep sevmenin fırtınasıyla d...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ben-buradayim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yıkandım Sevmelerle', 'ben-yikandim-sevmelerle-asim-ozturk-a1nh0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıyısında durup baktığım sulardan sonra

Geceler de kirlendi, 

Arsız bulutlar sardı mavinin dallarını

Suçsuz kaldırımlar

Azarlanmış ışıklar da bıraktı kenti

Şimdi, 

Yağmurun kol gezdiği İzmir''de

Görkemli çınarlar da yok

Süklüm püklüm palmiyeler

Pörsük kordon boyunda geziniyor

Yorgun imbatlar, 

Sesimizin aleviyle sımsıcak yanan

Sokaklar, 

Sokakların tanıdık yüzleri

Bir bir sırtını döndüler sinemalara

Gölgeni bir karanfil sanıp

Kızıl bir gülü akıtırken yüreğimize

Bir gün daha

Bir günü eskitti sokaklarda; 

O aynalarda düşen tomurcuklardık

Yağmurun ardından kenti böyle gelen

Sesimiz bulutlanırdı

Çatalkayada sağanağa döllenirdi zaman, 

Adların unutulduğu duraklar değişti

Islak görüntüler kaldı

Yorgun bir belleğin gezindiği yollarda.

Akıp geçen sesimizdi

Akıp geçen hiçliğin duvarında bir yankı

Ben yıkandım sevmelerle

Islak yağmurlar sürüklüyor

Pasaporta bağlı, çürüyen gövdemi.', 'Kıyısında durup baktığım sulardan sonra Geceler de kirlendi,  Arsız bulutlar sardı mavinin dallarını Suçsuz kaldırımlar Azarlanmış ışıklar d...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-yikandim-sevmelerle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-asim-ozturk-ika06', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir adam yağmurlarıyla gelirdi

Bir adam

Denizin kendisiydi, 

Mavinin esintisi

Çırılçıplak gecelerle gezerdi

Yıldız körüydü bir adam, 

Derin derin gitmeler sonrası

Çözerdi zincirlerini sulara

Sanki sudan öte

Bir yaprağın incinmesiydi

Kırıldığını duymazdınız

Eğilip bakınca gözlerinize

Kuytularında fırtınaları emzirirdi

Bir adam

Kirlenmiş neyi varsa

Bırakıp giderdi; 

Çıplaklığın sesiyle sevişir

Yağmurlarda erirdi; 

Koyup gitse de onca rengi ardında

Bir adam

Kırmızının sabahını severdi

Morun leylağını, 

Sesinin çapağında biriken kanla

Utançlar içinde bir adam

Sevmeleri sektirirdi suların üstünde

Bir ırmağın

Sellerle boğulan sesini

Alır gider

Kanatsız göklere verirdi; 

Bir adam

Uykusuzluk içinde gezinir

Karanlığa önce ellerini

Sonra gözlerini

Sonra.....sevmelerini

Sonra sonra sonra

Bir adam.....', 'Bir adam yağmurlarıyla gelirdi Bir adam Denizin kendisiydi,  Mavinin esintisi Çırılçıplak gecelerle gezerdi Yıldız körüydü bir adam,  Derin ...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-adam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adın Olmalı Senin', 'bir-adin-olmali-senin-asim-ozturk-lta75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir adın olmalı senin

Rüzgarın yazıp sildiği

Mavi aydınlıkların yanında duran

Gece ve gündüz resimlerin

Bir çakıl taşının düşü olmalı avuçlarında

Serinliği akıtırken uykulara

Irmağın mevsimi olmalı

Kim çağırırsa çağırsın

Korkudan önce, 

Rengini anımsamalısın

Adın bir çiçek olmalı, 

Dokundukça ince bir tenden sızan

Terin

Sevişmenin boyutunda

Dün ve yarın

Çocukluğun olmalı.

Asmalı çardak altlarında, 

Begonyalara düşmeli gözlerin

Yaralarını sarıp sarıp çıkmalısın

Sevda gülleriyle, 

Senin elin olmalı, 

Sıcaklığınla tutup tutup

Sonra büyük bir aydınlıkla salıverdiğin

Umutların olmalı, 

Suların ansızın yitip gittiği

Küskün

Kırık günlerden sonra

Bir dalın

Bir kökün olmalı, 

Bunca yabancılığın kol gezdiği

Arsız sokaklardan sonra

Adresin, 

Semtinin adlandıran dut ağaçların

Kopuk bir düğme

Bir adın, bir sesin olmalı senin.', 'Bir adın olmalı senin Rüzgarın yazıp sildiği Mavi aydınlıkların yanında duran Gece ve gündüz resimlerin Bir çakıl taşının düşü olmalı avuçla...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-adin-olmali-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapurları Sana Bıraktım', 'vapurlari-sana-biraktim-asim-ozturk-tmywk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vapurları sana bıraktım

Yıldız körü yazlardan sonra

Sürükleniyorum unuttuğum gecelerin sularında, 

İnce-uzun gölgemin ardından

Derinleşerek yok oluyor yosunlar

Kirlendi bak, 

Bir uzun güne serili

Çınarlarım

Kaldırımlarım

Sen kirpiklerinin ucunda dökülen

Son karanlık gibi

Ağır ve sessiz adımlarla geçip gittin

Yanımdan, 

Vapurları sana bıraktım

Kanatları karanfil rengi martıları da, 

O eski

Yaşlı limanların oynak ışıklarıyla

Bir demirin paslı sesi

Akıp indim renginden

Çözülmüş palamarların, 

Şimdi gidilmedik yerlerin

Uzun gurbetlikleriyim.

Sokakları sana bıraktım

Renklerin çığlığını

Kemeraltı sokaklarından

İnce-titrek bir gölge gibi

Geçip gittim.

Tarih neydi? 

Geveze saatlere takılıp kalan

Saçlarımın nergiziyle

Dağ kokulu özgürlükler masalı

Tökezlemiş sevdalarla

Bir kez daha yokladım

Sancımda saplı duran bıçağın

Geceye gömülü toynaklarını.', 'Vapurları sana bıraktım Yıldız körü yazlardan sonra Sürükleniyorum unuttuğum gecelerin sularında,  İnce-uzun gölgemin ardından Derinleşerek ...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/vapurlari-sana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renklerin Tüneği', 'renklerin-tunegi-asim-ozturk-6r6od', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pembeye sorup o uzun ince yolları

Akılksız sarılar içinden

Süzülüp geçtim geceleri, 

Küskün morlar uykudaydı; 

Bu nasıl doruk

Kızıl atların su içtiği

Ürpertili göklerden sonra

Al senin olsun kör maviler

Karanlık düğüm düğüm düşlerimde, 

Soyunup saydam sessizlikler içinde

Çektim perdelerini aklıkların

O yitip giden acemi taylarımdır

Yaşadıklarım; 

Kurşuni sersemlikler durur

Yüreğimin bir yanında, 

Kül kanatlı kuş tüneğidir

Emzirir gecelerin acısını

Ürpertilerle akan pembelerde, 

Yorgunlukların ardından gözlerine demirleyen

O mavi gemilerle, 

Kaçıncı yolcunun ardından

Hep seni

Hep seni anışım

Bu kanayan güllerle durup durup ağlayışım, 

Dişi mavilerle

Pembe sevişmelerle; 

Akan bir susuzluktan gelişin yeşille

Bırakıp bırakıp gidişin gecelerden

Hadi sarıl, 

Öpmenin selinde

Yangın moru sözcüklerim

Renklerin tüneğinde bu akşam.', 'Pembeye sorup o uzun ince yolları Akılksız sarılar içinden Süzülüp geçtim geceleri,  Küskün morlar uykudaydı;  Bu nasıl doruk Kızıl atların ...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/renklerin-tunegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzeyimin Yitik Sesi', 'kuzeyimin-yitik-sesi-asim-ozturk-mnga8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgar yeniği bir zamandan sesleniyorum

Kuzeyimden giderek uzaklaşan

Kar aydınlıklar içinde

Yosunlarımın kayasıydı gövdem.

Doruklar öylesine sessizdi

Acının çırılçıplak gözleriyle geçtim

Pusulamın yüreğinden

O yüzden, hep o yüzden

Sevdam; 

Yerleşik bir dağ gibi; 

Aşılmaz uzaklar oldu

Bu yıllara ne oldu

O yürek

O akıl almaz yalnızlıklara gömülü

Yüreğimle eskittiğim geceler

Hep senin

Hep senin sesinle dolu

Şimdi akıp giden yaprakların

Bulanık ırmağa

Yorgun söğütlerin gölgesine tutunan

İnce, zayıf

Korkak bir yel

Yitik bir yolun ardına düşen

Islak dumanların bacası, 

Dağıldı bak, 

Yorgun trenler de bir bir

Tomurcukların ilkyazı yok

Bu kuzey istasyonları

Umudun gövdeme açtığı yaradan

Akıp inen, 

Sessiz ırmağımın aydınlığı

Kuzeyimin limanları

Yitik zamanlarımı demirle.', 'Rüzgar yeniği bir zamandan sesleniyorum Kuzeyimden giderek uzaklaşan Kar aydınlıklar içinde Yosunlarımın kayasıydı gövdem. Doruklar öylesine...', ARRAY['Türk Edebiyatı','Şiir','Asım Öztürk']::text[], 8.5, '{"poet":"Asım Öztürk","poet_slug":"asim-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kuzeyimin-yitik-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar ve Yüzler I', 'uzaklar-ve-yuzler-i-muzaffer-sarigul-g0g7e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıyıkları hayriye kokan bir oğlan geçer

Bozgun bir mevsimdir aşk, hüzünler tüter geçer

Leylek bu, ardından sürükler mevsimini

Artık bir ısrardır ayrılık, bu sudan ıslanmadan geçer

Bir gırnata hüznü üfler, sanırsın saksıda fesleğen tüter

Bu dağlar talimlidir, eşkıya türküsü, tekmili asi geçer

Oysa bir vurgundur aşk, şuranda gül yanığı

Yüreğine sarılır da yatarsın, uyanınca rüyadır geçer

Koyu bir uğultudur şehirler, bıyığı üşümüş mülteci

Dilini yutmuş ulustur şehmus, içinden en tiz çığlığı geçer

Her ömür bir ıslık, yüreğimiz bir top nardır çatlar

Sayrılı bir uzun havadır tarih, elbet hüzzamdan geçer', 'Bıyıkları hayriye kokan bir oğlan geçer Bozgun bir mevsimdir aşk, hüzünler tüter geçer Leylek bu, ardından sürükler mevsimini Artık bir ısra...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Sarıgül']::text[], 8.5, '{"poet":"Muzaffer Sarıgül","poet_slug":"muzaffer-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uzaklar-ve-yuzler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar ve Yüzler II', 'uzaklar-ve-yuzler-ii-muzaffer-sarigul-t9w0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mevsimi dinlemekten geliyorum

Ellerim toprağın kabaran karnında

Bir kavganın uğultusu şiirlerimde

Tarih diyorum, herkesin yenildiği düello

Onun için yüreğine dolgu yaptı kahramanlar

Onun için faili meçhuldür masallar

Şairler beter bir aşk müridi

Ki bir hüzün endamıyla göçüp giderler', 'Bir mevsimi dinlemekten geliyorum Ellerim toprağın kabaran karnında Bir kavganın uğultusu şiirlerimde Tarih diyorum, herkesin yenildiği düel...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Sarıgül']::text[], 8.5, '{"poet":"Muzaffer Sarıgül","poet_slug":"muzaffer-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzaklar-ve-yuzler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustuklarım', 'sustuklarim-muzaffer-sarigul-22o8o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendine bir masal beğen çocuk

Kökü ateşle beslenen şarkılar beğen

Islıksız çıkılan yolculuklar tekin değildir

İhanetlere yakışan akrepler bul kendine

İşte böyle çocuk, acıyı aşktan muaf tutamazsın

Bir keklik sesini gösterir ya bize

Bir tavşan beyazlığını

Rüzgar ipekten mendiliyle siler ya alnımızı

İşte çözüver anıların ipini, sayrılı bir hüzün olur

Hohla bir camı, dünya salgın gibi durur

Bir efkar gelir kadehlerimizi doldurur

Yüreğimi yaslayıp bir gurbet türküsüne susuyorum işte

Her kederin bin ağu kustuğu

Martıların uzak limanlara sustuğu

Kendi tarihini yazacak kadar

Zimmetine geçirip birkaç imgeyi ve ütopyayı

Bir baş dönmesiydi diyeceğiz aşk ve geçti işte

Dilimizde dağladığımız söz, yüzümüzdeki yorgun hüzün

Ve çiğ ışıklara büyüyen gözlerimiz

Kendi ninnisini avutmak için

Her ömür ithafını yazmalıdır gecenin levhasına

İşte aklımı banıp bu sorulara susuyorum bunları da

Bana ölümden söz etme çocuk, aşktan söz etme

Bu çağın düşükleriyiz hepimiz

Yalnızlığa büyüyen sözler yazdık sulara

Bak bütün ütopyalarımız elimizde kaldı

Git git bitmiyor geceler karası

Ne kadar örtünsek de o kadar çıplağız işte

Bir ergenlik kaç kabahat sürer

Neden erişilmezdir kadınların mor sinesi

Neden hep aynı boyda kaldık dağlarla

Muhsin amcaya sorarsan tanrının marifeti

Ama neden hep nemlidir şairlerin gözleri terlemiş kadehler gibi

Alnımı yaslayıp bu sorulara susuyorum bunları da

Bütün uykularımı bıçaklıyorum işte

Velveleye veriyorum bu şehri

Lanet bir nasır gibi kalacağım aklınızda

Ama kendine bir masal beğen çocuk

Kökü ateşle beslenen şarkılar beğen

Islıksız çıkılan yolculuklar tekin değildir

İşte böyle çocuk, hayatı kavgadan muaf tutamazsın', 'Kendine bir masal beğen çocuk Kökü ateşle beslenen şarkılar beğen Islıksız çıkılan yolculuklar tekin değildir İhanetlere yakışan akrepler bu...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Sarıgül']::text[], 8.5, '{"poet":"Muzaffer Sarıgül","poet_slug":"muzaffer-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sustuklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metro Delisi', 'metro-delisi-muzaffer-sarigul-0inkf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her ömür tarifsiz bir uçurumdur

Her uçurum bir ıslıkla tanımlar kendini

Her ıslık bir çocuk masalından firardır

Ki hep aşklarla sınar yüreğini

Nietzsche ağlamış mıydı sahi

Van Gogh kulağını hangi renge kesmişti

Nazım güldü mü mami

Gülmüşse türkçe gülmüştür, ağlamışsa türkçe

Bak kalemim mavi yazıyor

Ben esmer söylüyorum oysa

Hangi kalabalığı söyledi Edip abi

Yesenin hangi ütopyasına susmuştu

Peki kuşlar vurulunca gölgesi n''olur mami

Sahi Can baba seke seke gelmiş

Ya biz nasıl gideriz bu şenlikten

Bak kalemim yine mavi

Ben hala esmer söylüyorum oysa

Bak bunları söylemezsem çatal dilimle

Yakaran sözcükler n''olur anlasana

Tamam mami, tamam iki gözüm

İşte bir şiir boyu bize sustum

Kıvrılıp uyusun diye bir kedi içinde

O tenha parkı, bir de uzun şarkıları konuştum', 'Her ömür tarifsiz bir uçurumdur Her uçurum bir ıslıkla tanımlar kendini Her ıslık bir çocuk masalından firardır Ki hep aşklarla sınar yüreği...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Sarıgül']::text[], 8.5, '{"poet":"Muzaffer Sarıgül","poet_slug":"muzaffer-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/metro-delisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Tamara', 'ah-tamara-goker-goktepe-jmd2e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kelebek ömürlü alkol gecelerde

Beraber yaşlanmayı hayal edecek kadar 

Genç

Bir bebek isteyecek kadar da çocuktuk daha.

Sabah olunca becerebilir miydik eski bir

Türk filmini sarılıp seyretmeyi acaba, 

Sevebilir miydik Münir Özkul’un Adile Naşit’i

Sevdiği gibi, 

yoksa kredi kartıyla mı öderdik geceyi, 

Bir nebze olsun kendimizi sever miydik, 

biz’den biz olmaktan bahsetmez miydik, 

yani imzalamasak olmaz mıydı slibi? 

Dokunduğumuzda ellerine, izin verdiğimizde

Tenimize değen eller kadar sert değildik

Oysa, 

sen ve ben.

Gizlice fark ederdin, 

bende söylemezdim, söyleyemezdim seni

sevdiğimi! 

Kalabalık içinde sessiz senli benli anlarda

Fark ederdik özeldik birbirimiz için

Özelliğimiz yasak bir ilişki değildi elbet

Olsa olsa henüz kaçak bir sezişti.

Benim için yeşilçam’ın son yangını gözlerindi

 Senin içinse ben hayatına giren ilk Türk filmi.

Tenine dokunmak aklıma bile gelmemiş bir 

Hayaldi, 

ten kokunu bildiğim halde

Düşlediğim sadece

Bir gece yağmur altında yürümekti.

Yıldızlarımızı saklayan bulutlara inat

Dilimde hep aynı cümleyle; 

Elimi uzatsam yıldızlara değecek sanki....', 'Kelebek ömürlü alkol gecelerde Beraber yaşlanmayı hayal edecek kadar  Genç Bir bebek isteyecek kadar da çocuktuk daha. Sabah olunca becerebi...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ah-tamara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babadan Miras', 'babadan-miras-goker-goktepe-68uhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskun kamera açıları hayal edip sihrine

Biraz kendimle alaycı; 

Saçlarının kısa olduğu 

Masallar kuruyorum zihnimde; 

Sen kendini hapsettiğin kulede, 

Ben seni kurtarmak için kuledibidine.

Saçların yetişmiyor ellerime ve dokunamadıkça

Sözcüklerim sadeleşiyor, tuhaftır; gün gelir bütün

Duygular üç dize şiire sığarmış düşüncesinde.

En alkollü arkadaş sohbetlerinde

’’Büyüdüğünde beraber zamparalık yaparsınız’’

Sözlerine inat arkadaşlarının; 

’’Benim oğlum aşık olacak’’

masallı bir babanın oğluyum

bir varmış bir yokmuş yaşlarında.

Biliyorum, çocuğuma anlatmak istediğim masal 

Senin adında, 

hem burada gökyüzü şehrin ışıklarıyla aydınlanıyor sadece ve

gökten üç elma düşmüyor bir türlü

sen ve ben oturup bira terli bar taburesinde

üstelik ara sıra bir de dans ediyoruz, 

ama yazık, çıkamıyoruz kerevetine...', 'Suskun kamera açıları hayal edip sihrine Biraz kendimle alaycı;  Saçlarının kısa olduğu  Masallar kuruyorum zihnimde;  Sen kendini hapsettiğ...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/babadan-miras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşıydı Yüzün', 'gozyasiydi-yuzun-goker-goktepe-zglwb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üyeydin; 

O halde  yapılan indirim

Çift değil tek başına hesaplaşmak

Olurdu herşeyle.

Asla sormazdım geldiğinde

Nerede kaldın, 

giderken nereye

gidiyorsun diye; bilirdim

ilişkinin değil ama

çelişkinin hesabını almaya 

giderdin

ertesi güne bırakılan aşk adisyonunda.

Gözyaşlarındı; 

Keyifsizce seyrek rakını beyazlatan

Ve dans ettiğinde elbet 

zor zamanlardı

etrafında salınan.

Boş sokaklarda öyle sessiz yürürken

Yağmurdu gecede gözyaşını silen, 

ağladığını sen bile görmezdin.

Gölgendim, asla sormaz yanıtlardım; 

Hüznünü getirmişsin

Yüzünü kaldırım taşları almış....', 'Üyeydin;  O halde  yapılan indirim Çift değil tek başına hesaplaşmak Olurdu herşeyle. Asla sormazdım geldiğinde Nerede kaldın,  giderken ner...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozyasiydi-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adisyon', 'adisyon-goker-goktepe-7wrct', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Matine suare farkı bilmeden

Seanslarımız devamlıdır mesaisinde 

Biraz alkol tadımlı

Aynası kadehteki yansımasına eş

Eve dönüş yolunda

Taksimetreye inadına gece tarifesi

Açtırdığım

Bir baş dönmesiydi seni özlemek.', 'Matine suare farkı bilmeden Seanslarımız devamlıdır mesaisinde  Biraz alkol tadımlı Aynası kadehteki yansımasına eş Eve dönüş yolunda Taksim...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adisyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiline Şiir Yazdım...', 'sevgiline-siir-yazdim-goker-goktepe-ts6g9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tabiatıyla hiçbir şey yoluna girmiyordu! 

Oturup bir deftere karşılıklı karaladığımız

Kolajlardan ibaretti

Birbirimize olan ten tuzu bilgimiz

Pardon; aslında ilgimiz.



Telefonuma yolladığın mesajları silemiyorum

Bir türlü; 

çünkü bir tek yani sade’ce

turkcell bir türkçede

sürçmüyordu dilimiz.

Ama ne tuhaf, beraber bir

Kurşun Asker Balerin masalına gülümsüyorduk

Ve beraberken berabere bile değildi skor.

Sen hakikaten balerindin

Bense asker kaçağı! 

Elbette; 

Tabiatıyla hiçbir şey yoluna girmiyordu.



Bir kuğunun ölüm anında üflediği

(kuğular üfler mi?)

şarkılar kadar özeldi sözlerin, 

ve saçlarını açtığında ısınıyordu yalnızlığım









sanki bir gece vakti

öyle habersiz kalkıp bir kahve içmeye

geliyordun, 

üşüyorum deyip; 

Tabiatıyla hiçbir şey yoluna girmiyordu ve sen bana

Sevgilinden, Doğa’dan bahsediyordun...', 'Tabiatıyla hiçbir şey yoluna girmiyordu!  Oturup bir deftere karşılıklı karaladığımız Kolajlardan ibaretti Birbirimize olan ten tuzu bilgimi...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgiline-siir-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harper''s Bazaar', 'harper-s-bazaar-goker-goktepe-ywnlp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '’Aklıma gelmedi’; ne ağır bir

Gözyaşıydı gözümden dökülen

Oysa o gözyaşlarımdı sensiz

Yalnızlığıma

Arkadaş olanlar.

Ve kimbilir, belki de farkında değildin; 

Gözyaşları mağazalarda satılmazlardı.

Ve hiç bir moda editörünün bilgisinde

Değildi benim kalbim.

Acaba; 

Çok demode bir yürek yorgunluğu mudur

Bir telefon beklentisi?', '’Aklıma gelmedi’; ne ağır bir Gözyaşıydı gözümden dökülen Oysa o gözyaşlarımdı sensiz Yalnızlığıma Arkadaş olanlar. Ve kimbilir, belki de fa...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/harper-s-bazaar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kırgınlığımın Yol Üzerine Şiiridir.', 'kucuk-kirginligimin-yol-uzerine-siiridir-goker-goktepe-m6nq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu evi en çok penceresinden gördüğüm

Damlar için sevdim.

Bir de kapı çalınıp geldiğini bildiğim anlar için, 

Kapıyı açıp seni öptüğüm için.

Söylediğim

Ve senin

Ne yazık; söylediğni zannettiğm

Can parçalarımız için.

Sana deyip, seninle deyip

Gün boyu ev içi huzursuzluklarımda

Yazdığı ve sana asla okutmadığım

Ruh parçası; can parçası

Mektuplarla sevdim bu evi, 

Birde; 

Camından gördüğüm damlarla.

Damlarla gelirdi yalnızlık  ve gidiş düşünceleri

Ama hep seninle giderdi akşamüstleri.

Saçımın kıvcırcığına gizlediğim şiirlwerimi

Sunardım sana karşı dama hergün gelen 

O siyah kedinin ayakizlerinde.

Ayak izi ben olurdum, 

Elime alıp plastik bebek seslerini

Dokunasın diye bana ayak izlerinden





En komik yirmibeş yaş şakasını yapardım sana.

Şimdi damlara bakıp oturduğumda salonda

Elimde plastik bebek sesleri; 

Sana uzatıyorum birşeyleri, 

Ruh parçası, can parçası gibi, 

Canım diye başlanılıp

Yarım bırakılmış mektuplar gibi.

’Ben’diyor dışındaki zırhın, 

’Bana’diyor.

Zırhını açacağın günü beklemeye de 

Gidiyorum bir nebze.

Zırhının içine beni de arzu edeceğin

Günler için.

Bu evi en çok penceresinden gördüğüm

Damlar için sevdim.

Damların üstüne bir de yolları 

Ekliyorum şimdi.



Elimde plastik bebek sesleri....', 'Bu evi en çok penceresinden gördüğüm Damlar için sevdim. Bir de kapı çalınıp geldiğini bildiğim anlar için,  Kapıyı açıp seni öptüğüm için. ...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kucuk-kirginligimin-yol-uzerine-siiridir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Değildir Çelişkiler...', 'keskin-degildir-celiskiler-goker-goktepe-uz8uj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denemek veya korkmak

Yapmak veya yapmamaktır; 

Hayat....! 

Veya intihar....!', 'Denemek veya korkmak Yapmak veya yapmamaktır;  Hayat....!  Veya intihar....!...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/keskin-degildir-celiskiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekzip', 'tekzip-goker-goktepe-p2d1l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatalarımdı yaşımı intiharlardan uzak tutan

Menziline akrostiş hayatım

D(g)  ün gözümün sızısında

G(d)  ün saçımın kıvırcığında

Adını bir türlü satırbaşı edemedim.

Keşke; 

Parmağımda taşıyabilseydim seni....', 'Hatalarımdı yaşımı intiharlardan uzak tutan Menziline akrostiş hayatım D(g)  ün gözümün sızısında G(d)  ün saçımın kıvırcığında Adını bir tü...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tekzip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Olsun Bilmeliydiniz...', 'siz-olsun-bilmeliydiniz-goker-goktepe-0sp6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sözcükte sizin için eksildim; 

Bir kere benim için

Çoğalmayı bilmediniz.

Kırıldım dedim; 

Öyle umarsızdınız ki; 

Kırıldığımın bile  önemi olmadı 

Sizin için, 

kendiniz değil kırılmak

sıkılmayasınız diye.

’büyütüyorsun, abartıyorsun’

dediniz.

Sustum...

Susmuşluğumun sesini

’kendine acımak’bildiniz.

Konuştum, denedim

Anlatmak için; 

ikimiz deyip, ikimize deyip



senli benli günlere

‘hiçbir şeyi göze alamıyorsun’

dediniz.

Size kızdığımı

‘biz canım’diye başlayan 

cümlelerle anlatmaya

çalışırken size, 

‘tavır göstermediğimi’zannettiniz.

Oysa yapmaya çalıştığım

Sizin için bir incelikti, 

Senli tümceleri

Bizli düşünmek…

Fark etmediniz.

Görmediniz

Ya da 

Görmek istemediniz.

Oysa ben; 

her sözcükte

sizin için eksildim.

Çok isterdim, 

Bencilcve belki, 

Bir kere olsun ben de isterdim, 

sevdiğiniz için inatsız, 

sevdiğiniz için savunmasız, 

bir kerede benim için….

Çoğalmayı bilmediniz!  ’Siz’ olsun, bilmeliydiniz....', 'Her sözcükte sizin için eksildim;  Bir kere benim için Çoğalmayı bilmediniz. Kırıldım dedim;  Öyle umarsızdınız ki;  Kırıldığımın bile  önem...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/siz-olsun-bilmeliydiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuma Bayramı', 'okuma-bayrami-goker-goktepe-s2x8z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Içimdeki sen, 

Bir ilkokul birinci sınıf çocuğunun

Kenarları ataç yüzü görmemiş

Sarı saman kağıdından

Defterlerine benzer.

Dönüşümsüz....', 'Içimdeki sen,  Bir ilkokul birinci sınıf çocuğunun Kenarları ataç yüzü görmemiş Sarı saman kağıdından Defterlerine benzer. Dönüşümsüz.......', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/okuma-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Evi Şarkısı', 'bir-gece-evi-sarkisi-goker-goktepe-3tw3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Farklı dünlerden kendimize kırat biçtiğimiz

Bir yontulmamış yalnızlık mıydık

Sen ve ben? 

Yoksa

Birkaç kadeh şarap tadında

Birbirimize, birbirine; 

Elmas ışığında bir gök mü arıyorduk

Adını, sanrısını ve hüznünü pek duyup

Iki günlük heveslerle vardığımız fado sokaklarına

Inat; 

Içine; içimize çekilmiş perdeler, 

Buzlanmasın diye tuz döktüğümüz kalbimize arkadaş

Buzlu camlar altında.

Bir gece evinin kimse bilmez ahengine dalip

Beş dakika önce sen

Beş dakika sonra ben uyanışlarda

Söylemezdin, söyleyemezdin günaydınlarında

Neydi sessizliğimiz? 

Sessizce seziliyor gözlerin

Adını uzun zaman şiiri koydum; senin….', 'Farklı dünlerden kendimize kırat biçtiğimiz Bir yontulmamış yalnızlık mıydık Sen ve ben?  Yoksa Birkaç kadeh şarap tadında Birbirimize, birb...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-gece-evi-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Buse Hayal Kadar', 'bir-buse-hayal-kadar-goker-goktepe-f1048', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluğumun pek de anımssayamadığım

Tek kanallı televizyon günlerinin

Masumiyetini anımsadım sen düş’ünce aklıma

Sebebi anlamsız bir 

hüzündü gelişin.

Biraz da zamansız...

Bir hıdrellez günü ateş üzerinden 

Atlamak gibiydi seni

Düş’ünmek.

Bir kılıcın sapından

Sırt adı biçip hayata

Anlarsınya; bıçak sırtı bile değildi hayatım.

Uuymaktan korkmak kadar

Kılıç sırtıydı teninden terinin kokusunu duymak.

Saçına ellerimi deydiremezken, 

Ona model hayalleri kurmaktı yakın plan, 

iddialıydı, tuhaftı, 

bir türlü yatakta uyuyamayıp

salon koltuğunda aşk sızısıyla bir gençlik geçirmek 

kadarda doğaldı...



Gülerken gözlerinde sakladığın o bir

Damla gözyaşı gibi

Aşkın yazılmamış tarihine bırakılan

Bir

Buse 

Hayal kadar, 

(başta daha fazla yazmamak için

yalan söyledim :)

sebebi; anlamlı bir

hüzündü gelişin! 

Ama gözlerindeki masalsılık kadar

Zamansız....', 'Çocukluğumun pek de anımssayamadığım Tek kanallı televizyon günlerinin Masumiyetini anımsadım sen düş’ünce aklıma Sebebi anlamsız bir  hüzün...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bir-buse-hayal-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yuppie Öyküsü', 'bir-yuppie-oykusu-goker-goktepe-rkk5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimi uzattım...

Ağız dolusuydu sana anlatmak

Istediklerim.

Yüzüne baktığımda

Kalbim çarpıyordu.

Çok seviyordum seni; 

Çok…

Nasıl anlatacağımı bilemiyordum.

Cümle kuramıyordum.

Ne kadar çok sevdiğimden bahseden 

Benzetmeler bulamıyordum.

Sana yağmurda ıslanışlarımı verecektim…

Şemsiyeden bahsettin…', 'Ellerimi uzattım... Ağız dolusuydu sana anlatmak Istediklerim. Yüzüne baktığımda Kalbim çarpıyordu. Çok seviyordum seni;  Çok… Nasıl anlatac...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-yuppie-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Film Sokağı', 'gonlumun-film-sokagi-goker-goktepe-muepy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bir

Sadri Alışık 

Kederiyle sevdim desem

Tutup film çekeceğim sanırdın.

İki saate sığmaz zannedersem

Hayatlarından birbirinin  affını 

Dileyen iki insanın hikayesi.

Hem sesi boğazına düğümlenmeyip

Kim bu filmin dublajını yapacak? 

Abilerim; 

Ablalarım; 

Fene halde seviyorum

Teninin beyazlığını gavurun

Rakı kadehime yapıştırıp bileniyorum.

Saçının sarısını

Bıyığımın sigara sarısına allayıp...

Fena halde  ’lan...



Abilerim

Ablalarım

Bağlasanıza deli gömleğimi

Bi’ zahmet...          (Seviyorum u’lan)

Hürmetler...           (Fena halde...)







Eyvallah...          (Eyvallah...)

Ararsanız beni Yalnızlar Rıhtımı’nda!', 'Seni bir Sadri Alışık  Kederiyle sevdim desem Tutup film çekeceğim sanırdın. İki saate sığmaz zannedersem Hayatlarından birbirinin  affını  ...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonlumun-film-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmlasız Aşk', 'i-mlasiz-ask-goker-goktepe-ap8hc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deniz üzerinde taş değil, 

yürek sektirdiğim anlardı 

ve kirpiklerim yüzme bilmez, boğulurlardı

gözyaşlarım arasında.

seninle çekilmiş iki fotoğrafımızında

bir adada olması

iması mıydı hayatın acaba

yoksa; 

bizim anımız

imlasız bir aşk mıydı?', 'Deniz üzerinde taş değil,  yürek sektirdiğim anlardı  ve kirpiklerim yüzme bilmez, boğulurlardı gözyaşlarım arasında. seninle çekilmiş iki f...', ARRAY['Türk Edebiyatı','Şiir','Göker Göktepe']::text[], 8.5, '{"poet":"Göker Göktepe","poet_slug":"goker-goktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/imlasiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız ve Ben', 'kiz-ve-ben-ersin-kiymaz-rs5es', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün, sıcaktı; 

Ama ben soğuk teri dökmeyi, 

Her nasılsa başarabiliyordum...

Yol, kısaydı; 

Bana ise, çoook uzun geldi...

Kız, güzeldi; 

Ama benim için, dünyanın en güzeliydi...

Kız, gülüyordu; 

''''Ey tanrım, inciyi sadece midyenin

içine gizlememişsin'''' dedim kendi kendime...

Kız; elimi tuttu; 

Kim demiş bu adamın pamuğa alerjisi var diye...

Kız, konuştu ''''Merhaba'''' dedi; 

Her bir harf yüreğime aktı, aktı ve aktı...

Kızın, saçları rüzgardan uçtu; 

Tüm telleri güneşin ıpıltılarıyla parladı...

Kız, anlattı; 

Ben ise, ölesiye dinledim onu...

Kız, sustu; 

Zaman durdu, güneş söndü, çimen sarardı, çay soğudu, 

arabam çalışmadı, heryer karardı, ama benim yüzüm; 

aydınlıktı...

Kız, evine gitti; 

Yüreğimi, benliğimi, yani beni ben yapan herşeyi, 

kalbinin bir yerine sıkıştırarak gitti, 

belkide, çantasına sokuşturdu herşeyimi, 

bilemem ki...

Kızı, anneme anlattım; 

''''İncinme yavrum'''' dedi, anladım...

Gün, tekrar doğmak için battı...

Ben, tekrar ölmek için yeniden doğdum...', 'Gün, sıcaktı;  Ama ben soğuk teri dökmeyi,  Her nasılsa başarabiliyordum... Yol, kısaydı;  Bana ise, çoook uzun geldi... Kız, güzeldi;  Ama ...', ARRAY['Türk Edebiyatı','Şiir','Ersin Kıymaz']::text[], 8.5, '{"poet":"Ersin Kıymaz","poet_slug":"ersin-kiymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kiz-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Bayram Sabahı', 'bu-gun-bayram-sabahi-sinan-toklucu-vm7ef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün bayram sabahı

şafak vakti yaralı güvercinim cami avlusunda

bu gün bayram sabahı

seni düşündükçe hüzün çöküyor içime...

bu yürek kadrini bilir...

dağlar aşar gelir belki öpmeye gözlerini

belki şifa bulur incinmiş yanları

bu gün bayram sabahı

acı acı sözler  geliyor dilime

bu gün bayram sabahı

aminler semaya yükselirken bir-bir....

bu gün bayram sabahı düşümde sensin

bu ay orucumu sende tuttum

bir ay biriktirdim sensizliğimi

bu gün bayram sabahı

her sahurda 

daha bir ağlamaklıydı kan çanağı gözlerim.

bu gün bayram sabahı

ölüm var biliyorum sonu ölüm

yinede seviyorum

bu gün bayram sabahı 

harçlıksız çocuk gibiyim

bu gün bayram sabahı

kalbim lisanınla konuşuyor...

ahizenin ucunda ''alo'' yu özledim senin sesinden

oysa meltem serinliğinde bakardım gözlerine..

bu gün bayram sabahı 

sır dolu bir bayram

bu gün bayram sabahı

sen yoksun

bayramın! ! 

Bayramın Mübarek Olsun

''dilimin ah''ı

gönlümün eyvah''ı''', 'Bu gün bayram sabahı şafak vakti yaralı güvercinim cami avlusunda bu gün bayram sabahı seni düşündükçe hüzün çöküyor içime... bu yürek kadri...', ARRAY['Türk Edebiyatı','Şiir','Sinan Toklucu']::text[], 8.5, '{"poet":"Sinan Toklucu","poet_slug":"sinan-toklucu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bu-gun-bayram-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak İzleri', 'ayak-i-zleri-orhan-polat-39nxf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biraz mutluluk istediğim, 

dolaşıyorum...

toprak beyaz örtüsünü örtüyor, 

mutlu...

insanlar yağan karla birlikte; 

belkide hayalleri kadar temiz, 

duyguları kadar saf ve beyaz, 

bir dünya kuruyorlar sevdiklerine...

gökten umut yağıyor

sevgi yağıyor, 

dostluk yağıyor, 

beyaz taneciklerle kalplerin en derinlerine....

kayboldum umut yolculuğunda, 

bulamıyorum senin olduğun yeri.

ve işte beni sana götürecek, 

kar tanelerinde sevginin bıraktığı ayak izleri...', 'biraz mutluluk istediğim,  dolaşıyorum... toprak beyaz örtüsünü örtüyor,  mutlu... insanlar yağan karla birlikte;  belkide hayalleri kadar t...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayak-izleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Beni', 'affet-beni-ilgin-polat-949hk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve bir gün olur da 

Dönersen geri bana, 

Sanmam ya hani, 

Dönersin belki 

Bakmaya yüzüm olursa yüzüne 

Affet diyeceğim 

affet beni... 

Yağmurlu akşamlarda 

Dışarı çıkardık hani 

Sırılsıklam olurduk ikimizde 

Ve bağıra bağıra 

Şarkılar söylerdik birbirimize 

Bağıra bağıra 

''Beni sevdiğini'' söylerdin bana 

Ve şimdi de 

Bağıra bağıra söyle diyeceğim 

Beni affettiğini. 

Hiç unutamam o günü 

Nasıl unuturum ki. 

Yine yağmurlu bir akşamdı 

Ve biz her zaman ki gibi 

Isınıyorduk yağmurun altında 

Birden bir rüzgar, 

Hafif bir ürperiş... 

Ve ben o gece nasıl; 

''Git, git ve bir daha geri dönme'' dediğim gibi 

Şimdi de; 

''Gel, gel ve bir daha bırakma beni'' diyorum 

Ve bir de; 

Söz veriyorum bir daha seni  kırmayacağıma dair. 

Ve bir gün olurda 

Dönersen geri bana, 

Sanmam ya hani 

Dönersin belki. 

Kırdığım bir kalbi 

Onarmak için 

Dalından kopardığımız 

Gülü göstereceğim sana. 

Neler yaşamadığımızı, 

O günleri hatırlamanı isteyeceğim. 

Ve bir de içimden geçen 

Biraz fiyakalı, 

Biraz da saçma sapan 

Kurduğum bir kaç cümleyi söyleceğim sana. 

Başımı öne eğip 

Affet diyeceğim 

  affet beni... 

             -2001- 

                          ILGIN POLAT', 'Ve bir gün olur da  Dönersen geri bana,  Sanmam ya hani,  Dönersin belki  Bakmaya yüzüm olursa yüzüne  Affet diyeceğim  affet beni...  Yağmu...', ARRAY['Türk Edebiyatı','Şiir','Ilgın Polat']::text[], 8.5, '{"poet":"Ilgın Polat","poet_slug":"ilgin-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/affet-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(Sevginin) Ayak İzleri', 'sevginin-ayak-i-zleri-orhan-polat-boibv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'biraz  mutluluk istediğim

dolaşıyorum...

toprak beyaz örtüsünü örtüyor bu gece, 

mutlu...

insanlar yağan karla birlikte; 

belkide hayalleri kadar temiz, 

duyguları kadar saf ve beyaz, 

bir dünya kuruyorlar sevdiklerine...

gökten umut yağıyor

sevgi yağıyor, 

dostluk yağıyor, 

beyaz taneciklerle kalplerin en derinlerine....

kayboldum umut yolculuğunda, 

bulamıyorum senin olduğun yeri.

ve işte beni sana götürecek, 

kar tanelerinde sevginin bıraktığı ayak izleri...

Ankara- 3,3,1996', 'biraz  mutluluk istediğim dolaşıyorum... toprak beyaz örtüsünü örtüyor bu gece,  mutlu... insanlar yağan karla birlikte;  belkide hayalleri ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevginin-ayak-izleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Pençesinde Mutlu', 'umut-pencesinde-mutlu-i-hsan-uncuoglu-eopr4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut Pençesinde

Mutlu, Mutluyum, Mutlusun, Mutlular

İnsanoğlu umutlu hepsi biri diğerine benzerler ancak bir konuda Bütünleşir ve Doyuma ulaşınca! işte bu noktada Mutlu olurlar

İNSANOĞLU bir konuda  konuyla Bütünleşmez   Doyum sağlamamışsa 

ASLA Mutlu OLAMAZLAR! 

Gönlüm öyle hovarda ki! bu hovardaya geçim sorma

Birkaç Milyar maaşla ömür boyu namusla çalışırım 

Dağda Kırda bayırda tarlada 

Bilmemki neden böyle cahilim soruyorum Allahıma 

İçimden çıkmaz asıl sesim kitli susturucu ağzımda

Sarıyer kilyos tepe yokuşta evim saray ağaçaltı konduda, 

***

Pazar günleri işimi de severim Ben 

Çok yanlızım başka fukara arama bak çalışkana, 

***

Seçim yılları dört-beş yılda kaç

Bir gün ya restoran ya bir cami kapısında

Boğazda zavallı lux nonoş çoook

Beni unutmazlar maaşaallah

İki Avucum açık hep onlara Elhamdülillah, 

***

Bir taraftan hepimize Allahversin

Dolar! la Nasırlaştı ellerim baka baka ineklere 

Gölge gazete Havadis vereyim size ahırdan ibretle

Boğaz''da Villalarda açlıktan ölen çook biri çıksa saysa 

Açlığımı anlamıyor nasırlı el hanımda benden başka karşımda

Ellerime yeminliyim sözüm söz açık gözlüyüm Aziz Milletime 

Çalışmadan üretmeden iş ona bedava! kimden gelirse Oy para 

Bir İktidar yeter artar bana canlar feda olsun bu angarya''ya! 

Çal gitar çal çalpara''yı unutma oyna, hayda hayda di haydaaa, , ,', 'Umut Pençesinde Mutlu, Mutluyum, Mutlusun, Mutlular İnsanoğlu umutlu hepsi biri diğerine benzerler ancak bir konuda Bütünleşir ve Doyuma ula...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/umut-pencesinde-mutlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gerçek Değilsin', 'sen-gercek-degilsin-cahit-i-pekoglu-64iac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şikayetim aşktan yana değil

sana sığındım vurdun beni.

Yaşamım sana bağlı değilken

mümtelan yaptın erittin beni.

Seni yaşamak boş değil

özünü verirken titrettin beni.

Aşk varsa bu değil

hissederken kaybolduğundan berri.

Söylediğin sözler doğru değil

yaşamak istediklerini seçtiğinden berri.

Anladım artık gerçek sen, sen değilsin

gözlerindeki nefreti gördüğümden berri..', 'Şikayetim aşktan yana değil sana sığındım vurdun beni. Yaşamım sana bağlı değilken mümtelan yaptın erittin beni. Seni yaşamak boş değil özün...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gercek-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Olsun', 'gecmis-olsun-ensar-aktas-8d4n9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç bir hastalık, dert çaresiz değil 

Yeterki kapıyı çalmasın Azrail

Yenilme kederlere, sabretmesini bil

Küsme kimselere, hayatı sevmesini bil

Kendinle barışık ol, gülmeye bak

Herşeye rağmen çok güzel yaşamak

Geçmiş olsun canım, çok geçmiş olsun

Unutma üzüntüler azalır paylaşarak

Üstesinden gelinir her derdin inanarak

Hafifler tüm acılar sevilip, sayılarak

Woerden,15.10.2002', 'Hiç bir hastalık, dert çaresiz değil  Yeterki kapıyı çalmasın Azrail Yenilme kederlere, sabretmesini bil Küsme kimselere, hayatı sevmesini b...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gecmis-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sevmeyle Başlar', 'yasam-sevmeyle-baslar-cahit-i-pekoglu-vw9ct', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamayı sordular bana

oysa sevmeyle başlamazmı yaşam.

Bir ömür boyunca

sadece bir, iki yıl yaşadı gönlüm.

Yaşamak denince aklıma ilk gelen

sevilirken mutluluktan titreyen sen.

Yaşamayı yine sordular bana

bilemezlerki seninle başlamazmı yaşam.

Bir ömür boyunca sadece 

bir, iki yıl yaşadı gönlüm.

Biliyormusun hiç anlayamıyacaklar

işte böyle böyle diye atan yüreğini.

Biliyormusun hiç bize sormayacaklar

beraberliğimizdeki gerçek nedeni.

Yaşamımızdaki aşkın gerçek nedeni

bakışırken yüreğimizi okumamız değilmi.

Bir ömür boyunca sadece 

senin yüreğini okurken yaşadı gönlüm...', 'Yaşamayı sordular bana oysa sevmeyle başlamazmı yaşam. Bir ömür boyunca sadece bir, iki yıl yaşadı gönlüm. Yaşamak denince aklıma ilk gelen ...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasam-sevmeyle-baslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Uzatma Elini', 'olum-uzatma-elini-levent-umit-temiz-1sy1h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O 

Yolun yarısını 

Henüz aşmıştı 

Ben çoktan aştım 

Teşekkürler Tanrım 

Bu fazladan yıllara 

Görmek varmış nasipte 

Kırk sonrası baharı 

Azmak değil sevmek bu 

Sevmek daha bir sevmek 

Tutmak uçup giden yaşamı 

Yalnız değilim 

Ben hiç yalnız olmadım 

Elimde 

Ekmek arası mavi deniz 

Yüreğimde 

Gene sen varsın 

Telaş etme karınca 

Sakin ol küçük kedi 

Uyan utangaç çiçek 

Elimdeki ekmek 

Bu bahar 

Hepimize yetecek 

Ölüm 

Sen uzatma elini', 'O  Yolun yarısını  Henüz aşmıştı  Ben çoktan aştım  Teşekkürler Tanrım  Bu fazladan yıllara  Görmek varmış nasipte  Kırk sonrası baharı  Azm...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-uzatma-elini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüteceksin', 'usuteceksin-gulsah-burdur-qug3c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorulacaksın diye düşünmeden yürü, 

Yolun sonuna kadar, yağmurun altında...

Özlemlerini değil, sevinçlerini düşün bir kerede

Yağmurun seni götürdüğü yerde...

İliklerine kadar sırılsıklam, 

Ama hala memnun yürü yağmurun altında...

Bu yol ne zaman bitecek endişesi olmasın kafanda...

Sen başladın ya, 

Ancak sen çizersin sonunu da...

Ne kadar istersen o kadar gidersin, 

Ama hep gül yol boyunca...

Çünkü bu, senin yolun

Islansan da...', 'Yorulacaksın diye düşünmeden yürü,  Yolun sonuna kadar, yağmurun altında... Özlemlerini değil, sevinçlerini düşün bir kerede Yağmurun seni g...', ARRAY['Türk Edebiyatı','Şiir','Gülşah Burdur']::text[], 8.5, '{"poet":"Gülşah Burdur","poet_slug":"gulsah-burdur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/usuteceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yok', 'artik-yok-sertac-kendirci-zjn1c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalar sahile vuruyor

Rüzgar, hafif serin

İçimi ürpertiyor

Güneş bulutların ardında

Artık eskisi gibi ısıtmıyor

Yağmur yağıyor, yavaş yavaş

Issız bir sokaktayım

Ve aklımda sen, 

Sen ve sana olan aşkım

Hani o anlamadığın, 

Anlayamadığın belki de

Veya ısrar ettiğin

Anlamamakta

Dalgalar daha hırçın

Rüzgar daha sert ve

Yağmur daha hızlı şimdi

Güneş görünmüyor bile

Kaldığı bulutların ardından

Sen ve anlama eylemini

Gerçekleştiremediğin aşkımla

Yapacağını sanmam ama

Beni sakın arama

Çünkü o aşık adam

Artık çok uzaklarda', 'Dalgalar sahile vuruyor Rüzgar, hafif serin İçimi ürpertiyor Güneş bulutların ardında Artık eskisi gibi ısıtmıyor Yağmur yağıyor, yavaş yava...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/artik-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yıldızdın Sen', 'bir-yildizdin-sen-sertac-kendirci-hjfe8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden başka olamadım kimseye aşık

Gökyüzünde parıl parıl parlayan yıldız

Sen oralarda olmuşsun aya aşık

Ben ise kaldım buralarda yalnız', 'Senden başka olamadım kimseye aşık Gökyüzünde parıl parıl parlayan yıldız Sen oralarda olmuşsun aya aşık Ben ise kaldım buralarda yalnız...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-yildizdin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünlerde', 'bugunlerde-metin-yalcinkaya-olg2i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kılıcımı kuşandım

Sevdadan bir zırh üzerimde

sana koşuyorum bugünlerde

ben sana geliyorum...

başka maviliklerde 

yepyeni ümitlerde

yeni bir yeşilde

yeni bir sevgiyle yollarındayım

Sevdandan bir yıl üzerinde 

unutmadım seni epeydir

güzeli yaşatmak için

Koşuşturuyorum

bir yarım gibisin bugünlerde

 tamamlanmak için sana geliyorum

bir başkayım aslında bugünlerde 

Ben sevdana koşuyorum...', 'kılıcımı kuşandım Sevdadan bir zırh üzerimde sana koşuyorum bugünlerde ben sana geliyorum... başka maviliklerde  yepyeni ümitlerde yeni bir ...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bugunlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayyüzlüm', 'ayyuzlum-sertac-kendirci-i3mxz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aklımdan çıkmıyor senin o ay yüzün 

Yine her an gözümün önüne geliyor

Yine kulaklarımda senin her sözün

Üzüntüsü derin, kalbim ağlıyor

Zamansız gittin, yüreğim sana küskün

Lakin bir türlü seni unutamıyor

Üstelik o deniz mavisi gözün

Maalesef gözümün önünden hiç gitmiyor...', 'Aklımdan çıkmıyor senin o ay yüzün  Yine her an gözümün önüne geliyor Yine kulaklarımda senin her sözün Üzüntüsü derin, kalbim ağlıyor Zaman...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayyuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Gün', 'beklenen-gun-sertac-kendirci-ng0xu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessiz bir hazan sabahı, 

Sensiz ağlayarak geçirdiğim

Gecenin ardından gelen

Gözlerin, 

O deniz mavisi

Aklımdan hiç silinmeyen

Gözlerimin önünde yine

Tatlı sesin, 

Çıkıp dudaklarının arasından

Musiki gibi yankılanan

Hep kulaklarımda

Ve sen, 

Ölümüne sevdiğim

Hep seveceğim

Yanımda hissetsem bile

Şimdi çok uzaklarda

Gel de dindir

Gözlerimdeki, yağan o yağmuru

Gel de söndür

Kalbimdeki, yanan o yangını

Hep bekleyeceğim o günü

Hasretin bitirmeden beni

Gelip de bitireceğin şu hasreti', 'Sessiz bir hazan sabahı,  Sensiz ağlayarak geçirdiğim Gecenin ardından gelen Gözlerin,  O deniz mavisi Aklımdan hiç silinmeyen Gözlerimin ön...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beklenen-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahar Sabahı', 'bir-bahar-sabahi-sertac-kendirci-jgx3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine güneş çıkıyor dağların ardından

Yavaş yavaş, hüzünlü bir şekilde

Yine uyanıyorum sabahın köründe

Yine sensiz, yine çaresizce

Yine çıkıyorum dışarı, dolaşıyorum boş boş

Ve aklımda yine sen varsın sadece

Rüzgar yine serin serin değiyor tenime

Yine deniz mavisi gözlerin geliyor

Gözlerimin önüne

Yine bir şarkı mırıldanıyorum

Yine gözlerim doluyor

Değil sadece bu bahar sabahı

Hiçbir zaman sensiz olmuyor

Yine geziyorum ben

Gözlerimde yaş, dudağımda bir şarkı

Aklımda sen...

Yüzün, güneşi andıran

Gözlerin, deniz mavisi...

Yine geziyorum bir bahar sabahı

Tıpkı yıllar önceki gibi', 'Yine güneş çıkıyor dağların ardından Yavaş yavaş, hüzünlü bir şekilde Yine uyanıyorum sabahın köründe Yine sensiz, yine çaresizce Yine çıkıy...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-bahar-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten Gün', 'biten-gun-sertac-kendirci-ko3st', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş yavaş yavaş gidiyor

Tepelerin ardından, bilinmezlere

Yorgun, üzgün bir gün daha bitiyor

Ve ben, kalbimde hasretin

Giden güneşle, biten bu gün ile

Yitiyorum, eriyorum

‘Keşke’ deme hiçbir zaman

Çünkü artık ben yokum', 'Güneş yavaş yavaş gidiyor Tepelerin ardından, bilinmezlere Yorgun, üzgün bir gün daha bitiyor Ve ben, kalbimde hasretin Giden güneşle, biten...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biten-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Güç', 'en-buyuk-guc-sertac-kendirci-67gth', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Önce sessiz, uzaktan

Kaçamak takipler

Daha sonra karşılıklı

Bakışmalar, selamlaşmalar

Ardından biraz biraz

Konuşmalar, yazışmalar

Artık tutku ile beraber

Artan samimiyetle gelen

Rahat rahat, uzun uzun

Ve sevgi dolu konuşmalar

Sonra cesur bir teklif

Ardından gelen kesin kabul

Hep buluşma, çıkma, gezme

Ve aşk dolu hitaplar, birbirimize

Ve yaşamak ölene dek

Hayır! Aşka doymak yok! 

Ölene değil sonsuza dek

Hayal gücü insanın en büyük gücü

Sadece kullanmayı bilmek gerek', 'Önce sessiz, uzaktan Kaçamak takipler Daha sonra karşılıklı Bakışmalar, selamlaşmalar Ardından biraz biraz Konuşmalar, yazışmalar Artık tutk...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/en-buyuk-guc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Baharın Ardından', 'gecen-baharin-ardindan-sertac-kendirci-bzayu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül bahçemde

Dikenler arasında açan

Nadide bir çiçektin sen

Baharla gelmiştin

Çabuk geçti bahar

Ve onunla sen de gittin

Şimdi çok uzaklardasın

Başka bir şehrin baharlarında

Yüreğimse uzun zamandır

Aldırmamakta yokluğuna', 'Gönül bahçemde Dikenler arasında açan Nadide bir çiçektin sen Baharla gelmiştin Çabuk geçti bahar Ve onunla sen de gittin Şimdi çok uzaklard...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecen-baharin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülbahar', 'gulbahar-metin-yalcinkaya-jvxdo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'arada bir fal bakıyorum

opera bile seyrettim

uyumak istemiyorum 

rüyalarımda olursan diye

epeydir televizyon izlemiyorum

gazeteyi unuttum

sokağa çıkınca

bir ses  uğulduyor kulağımda

bir anne bağırıyor bazen 

Gülbahar! Gülbahar! 

Bilemezsin sevdiğim

seni anımsatıyor herşey bikarar

hiç tanımadığım bu ses

........................ Yüküm kadar

şimdi mevsimlerden bir bahar

Aynı sokak aynı yol

kız aynı sen

neydi adı derken 

biri yine seni anar 

Hey! Gülbahar!

sana hep derdim ya

İki şeyi çok severdim

Gül ve bahar', 'arada bir fal bakıyorum opera bile seyrettim uyumak istemiyorum  rüyalarımda olursan diye epeydir televizyon izlemiyorum gazeteyi unuttum so...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dön', 'geri-don-sertac-kendirci-jqa4i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dışarıda hava buz gibi

Neye yarar benim içim yanıyor

Bazen avunuyorum düşleyerek seni

Ne faydası var seniz olmuyor

Yine sensiz bir gün daha bitti

Ama o ay yüzün unutulmuyor

Kimbilir neredesin şimdi

Şimdi o mavi gözlerin nereye bakıyor

Ne yapıyorsun şimdi ey sevgili

Bilmiyorum, aklım hiçbir şey almıyor

Sanki seninle beraber aklım da gitti

Ama dudaklarımdan şunlar dökülüyor

Neredeysen dön artık, geri dön, haydi...', 'Dışarıda hava buz gibi Neye yarar benim içim yanıyor Bazen avunuyorum düşleyerek seni Ne faydası var seniz olmuyor Yine sensiz bir gün daha ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geri-don-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Günün Sonunda', 'guzel-bir-gunun-sonunda-sertac-kendirci-8dbdh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah güneşin doğmasıyla birlikte

Uyandım kalbimde senin sevginle

Yıkadım yüzümü suda sen vardın

Aynaya baktım yine karşımdaydın

Yediğim ekmekte içtiğim çayda

Bu sabah da hep aklımdaydın

Güneş dakikalar geçtikçe güzelleşiyor

Parlaklığını gitgide artırıyordu

Hafif bir meltem tenime değiyor

İçimi tatlı tatlı ürpertiyordu

Ve seni düşündükçe benim ay yüzlüm

Kalbim daha da hızlı atıyordu

Ve artık beklenen an gelmişti

İşte karşımda duruyordun öylece

Kalbim çok daha hızlı çarpıyordu şimdi

Bir ara sadece bakındık birbirimize

Ve yürüdük beraberce bir süre

Artık ayrılma zamanı gelmişti

Veda vakti bir hançer gibi saplandı yüreğime', 'Sabah güneşin doğmasıyla birlikte Uyandım kalbimde senin sevginle Yıkadım yüzümü suda sen vardın Aynaya baktım yine karşımdaydın Yediğim ekm...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/guzel-bir-gunun-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatalı(mı) yım', 'hatali-mi-yim-sertac-kendirci-wwdca', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşktan geçtim

Arkadaşlığa razıydım

Gezmeyi geçtim

Oturmaya razıydım

Konuşmayı geçtim

Bakışlara razıydım

Gül yüzünden geçip

Deniz gözlerine de rıza gösterdim

Daha uysal olup

Senden de mi geçmeliydim

Yoksa...

Geçtiğim şeylerin hepsini

Ölümüne mi istemeliydim', 'Aşktan geçtim Arkadaşlığa razıydım Gezmeyi geçtim Oturmaya razıydım Konuşmayı geçtim Bakışlara razıydım Gül yüzünden geçip Deniz gözlerine d...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hatali-mi-yim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen', 'hep-sen-sertac-kendirci-1anus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıkıcı bir günün akşamında

Bir sürü düşünce var yine aklımda

Ama bu düşüncelerin arasında

Elbette sen varsın en başta

Seni düşlüyorum sabah akşam

Aklımdasın sen her zaman

Beni uykulardan uyaran

Gözlerin, denizi andıran

Ben bu günlerde hep seni özlüyorum

Ben bu günlerde yine yolunu gözlüyorum

Ben bu günlerde aşkınla yanıp tutuşuyorum

Anla beni anla ne olur

Seni çok seviyorum', 'Sıkıcı bir günün akşamında Bir sürü düşünce var yine aklımda Ama bu düşüncelerin arasında Elbette sen varsın en başta Seni düşlüyorum sabah ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hep-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Rağmen', 'herseye-ragmen-sertac-kendirci-x97jl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okyanuslar gibi gözlerin

Bakmaya doyum olmuyor ama

İçinde kaybolmaktan, boğulmaktan korkulan

Yine de huzur saçan

Bilsem de boğulacağımı

Vazgeçmem onlara bakmaktan

Güneşi andırıyor siman

Nemesis’in biricik aşkı

Uğruna yanıp kül olduğu, yok olduğu

Ama yine de aşık olunan

Bilsem de yol olacağımı

Bir buse konduracağım

Sonunda ne olursa olsun

Bitecek bu hasret, sana kavuşacağım', 'Okyanuslar gibi gözlerin Bakmaya doyum olmuyor ama İçinde kaybolmaktan, boğulmaktan korkulan Yine de huzur saçan Bilsem de boğulacağımı Vazg...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/herseye-ragmen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Kimse', 'hic-kimse-sertac-kendirci-uzqgj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tapmaz bir putperest, puta

Sana taptığım kadar

Veya bir filozof

Düşünemez hiçbir şeyi

Seni düşündüğüm kadar

Ne asker, ne şehit anası

Hasret duymaz yavrusuna

Sana olan hasretim kadar

Şeytan bile beklemez günahı

Seni beklediğim kadar

Ve sevemez hiçbir canlı

Başka bir canlıyı

Benim seni sevdiğim kadar', 'Tapmaz bir putperest, puta Sana taptığım kadar Veya bir filozof Düşünemez hiçbir şeyi Seni düşündüğüm kadar Ne asker, ne şehit anası Hasret ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hic-kimse-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-metin-yalcinkaya-015gx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'anladım ki...

siyah da oluyormuş bazen beyaz

tersine de esiyormuş bakar yeli

ırmaklar sessiz de akıyormuş çağlamadan

gözler olmasa da görülüyormuş

anladım...

Anladım ki...

uyanmadan bitmiyormuş rüyalar

çok zormuş aşkına ölmek

çok zormuş adını hecelere bölmek

anladım...

Anladım ki... sevgilim 

Bilinmez değilmiş yolların

kavuşabiliyormuş Birgün herkes

Tükenmez değilmiş nefesim

 ölebiliyormuş birgün herkes...

Anladım...', 'anladım ki... siyah da oluyormuş bazen beyaz tersine de esiyormuş bakar yeli ırmaklar sessiz de akıyormuş çağlamadan gözler olmasa da görülü...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anladim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühim Değil Ayrılık', 'muhim-degil-ayrilik-sertac-kendirci-ut8ie', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakma o gün elveda dedim

Peşini bırakmaya niyetli değilim

Kendinle olamasam bile

Hayalinle birlikteyim

Sanma ki sensiz yaşarım

Seni görmesem bile

Sesini duymasam bile

Kokunu almasam bile

Sen her gün benimlesin

Sen benim derinlerimde

Kalbimin köşesindesin', 'Bakma o gün elveda dedim Peşini bırakmaya niyetli değilim Kendinle olamasam bile Hayalinle birlikteyim Sanma ki sensiz yaşarım Seni görmesem...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muhim-degil-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-sertac-kendirci-07ngy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nadide bir çiçeksin sen

Ama henüz bulunmamış

     Bir şarkısın aşk anlatan

     Ama henüz söylenmemiş

Eşsiz bir kuşsun sen

Henüz farkedilmemiş

     Bir aşk şiirisin sen

     Sevgiliye fısıldanmamış

Ve bir insanım ben

Seni koklamak, 

Seni söylemek, 

Seni farketmek, 

Ve fısıldamak için bekleyen

Hep yollarını gözleyen

Hasretinden deliye dönen

Aşkından yollara düşen

Eğer sen de Leyla isen

Bil ki Mecnun’unum ben', 'Nadide bir çiçeksin sen Ama henüz bulunmamış      Bir şarkısın aşk anlatan      Ama henüz söylenmemiş Eşsiz bir kuşsun sen Henüz farkedilmem...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-ve-ben-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-sertac-kendirci-hl54m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen bir günün akşamında 

Elbette sen varsın yine aklımda

Ne parlayan güneş çıkarıyor seni aklımdan ne de

İçin için yağan yağmur veya en sevdiğim beste

Sensiz bir an bile rahat değilim

Evet ben hep seni istiyorum

Varsın dünya tersine dönsün

İsterse güneş dünyaya küssün

Ya da dalgalar tüm şehri yutsun

Olmazsa dünya kar altında kalsın

Rahat değilim, seni istiyorum

Uçmak istiyorum seninle uzak diyarlara

Millerce öteye ve seni seviyorum', 'Sensiz geçen bir günün akşamında  Elbette sen varsın yine aklımda Ne parlayan güneş çıkarıyor seni aklımdan ne de İçin için yağan yağmur vey...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmak', 'seni-unutmak-sertac-kendirci-pyese', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unut diyordun giderken ama

Kolay mı unutmak bir sorsana

Yine sen vardın dün gece aklımda

Yine seni düşündüm gece boyu kafamda

Yine sen geldin sen girdin aklıma

Nereye baksam sen karşımda

Yediğim yemekte içtiğim suda

Unut diyordun giderken ama

Kolay mı unutmak bir sorsana

Niçin gittin ki uzaklara

Niçin bıraktın ki beni buralarda

Olmalıydın sen hep yanımda 

Giderken unut diyordun ama

Kolay mı unutmak bir sorsana', 'Unut diyordun giderken ama Kolay mı unutmak bir sorsana Yine sen vardın dün gece aklımda Yine seni düşündüm gece boyu kafamda Yine sen geldi...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-unutmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Geçen Son Günüm', 'sensiz-gecen-son-gunum-sertac-kendirci-m846f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş doğuyordu dağların ardından

Kuşlar yeni başlıyorlardı cıvıldaşmaya

Araba sesleri geliyordu nadiren kulaklarıma

Ve gözlerime hayalin

Bu gece de uyuyamadım doğru düzgün

Senin düşüncen fırsat vermiyor ki uyumama

Kakıp erkenden çıktım dışarı ben de

Hafif bir rüzgar vardı ve bu rüzgar

Serin serin tenime değiyor

Ürpertiyordu içimi

Yürüdüm, yürüdüm bilmeyerek nereye gittiğimi

Sen vardın her an aklımda

Ve başka bir şey düşünemiyordum

Sonra bir arabanın fren sesiyle irkildim

Kendime geldim farkettim hava ısınmış

Rüzgar ılık esiyor şimdi

İçimi ısıtıyordu, ürpertmiyordu artık

Sokaklardaki araba sayısı da artmıştı

Gürültü çoğalmıştı şehrin caddelerinde

Ben ise hala yürüyordum

Issız sokaklar, işlek caddeler...

Bilmiyorum nerelere gittim, nerelerden geçtim

Güneş karşıki tepelerin ardından batarken

Gördüm onu son kez, toparlandım biraz

Sensiz bir gün daha bitiyordu

Belki de bugün

Sensiz geçen günlerin sonuncusuydu', 'Güneş doğuyordu dağların ardından Kuşlar yeni başlıyorlardı cıvıldaşmaya Araba sesleri geliyordu nadiren kulaklarıma Ve gözlerime hayalin Bu...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensiz-gecen-son-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin', 'bilesin-metin-yalcinkaya-831hu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana çok müşgülüm bilesin...

dizlerim dermansız

güvercinlerim esir

sevgilim...

sana muhtacım

bitir bu hasreti

gösterişli bir aşk

parıltılı bir saadet

neleri yaşatmadın ki bana

ve ben şimdi sana muhtacım

bahar kışa dönüyor artık bilesin...

turnalar göç etti

saçlarım ağarmadan

vakit daralmadan

gece varmadan

ben sana muhtacım...

Bilesin...

yedi rengiymişsin hayatın

Dengiymişsin Aslı''nın Leyla''nın

Be kadınım ...

geri gel desem 

Bu Yusuf''da Züleyha ol desem

Dönemez misin...

Ah be kadınım yoksa 

hala bir melek misin!', 'sana çok müşgülüm bilesin... dizlerim dermansız güvercinlerim esir sevgilim... sana muhtacım bitir bu hasreti gösterişli bir aşk parıltılı b...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mektubumu-aldin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizim', 'sensizim-sertac-kendirci-9hm7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz bir gün daha bitiyor

Artık ümitlerim tamamen yok oluyor

Loş bir odada uzanmış seni düşünüyorum

İsmin yankılanıyor kulaklarımda

Her andığımda seni gözlerim doluyor

Ay yüzlüm hasretine katlanılmıyor', 'Sensiz bir gün daha bitiyor Artık ümitlerim tamamen yok oluyor Loş bir odada uzanmış seni düşünüyorum İsmin yankılanıyor kulaklarımda Her an...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensizim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-sertac-kendirci-98m01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kolay değil o kadar

Bir çırpıda silmek herşeyi

Unutmak seni...

Hiç hem de hiç kolay değil

Değil çünkü kazınmışsın beynime

Yüzün her an gözlerimin önünde

Sözlerin çınlıyor kulaklarımda

Bir kere girmişsin aklıma

Şimdi imkan yok çıkmana

Seni öyle seviyorum ki

İstersen öl de, öleyim

Yalnız bunu benden isteme

Israrla “beni unut” deme

Seni kırmak istemem ama

Unutamam seni ömrüm boyunca', 'Kolay değil o kadar Bir çırpıda silmek herşeyi Unutmak seni... Hiç hem de hiç kolay değil Değil çünkü kazınmışsın beynime Yüzün her an gözle...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutamam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayacağım', 'unutamayacagim-sertac-kendirci-1h1yk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O gün daha dün gibi aklımda 

Elveda, artık gidiyorum deyişin

Anma beni, artık unut deyişin

Ve boğazıma hıçkırıkların düğümlendiği an

Bir de gözlerime o son baktığın zaman

O güne ait ne varsa yaşanmış

Aklımda hepsi, unutamadım

O günü unutsam da

Bana unut deyişini unutmayacağım

Sen her ne kadar bana unut desen de

Aslında ben seni unutamayacağım...', 'O gün daha dün gibi aklımda  Elveda, artık gidiyorum deyişin Anma beni, artık unut deyişin Ve boğazıma hıçkırıkların düğümlendiği an Bir de ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/unutamayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazsın', 'unutamazsin-sertac-kendirci-0n9lo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önceleri basit gelir 

‘Aşk da neymiş’ der geçersin 

‘Zaman her şeyin ilacı, 

Bunu da unuturum’ dersin

Unutmaya çalışınca

Anlarsın imkansızlığı

Her an aklında gözleri vardır

Bir şarkı duysan onu anarsın

Gözlerin dolar, ağlarsın

Sesi kulaklarında yankılanır

Hiç aklından çıkmaz o ve

Her gördüğünü o sanırsın

Olmadığını anlayınca

Öylece kalakalırsın

O çok uzakta olsa da

Düşüncesinden ayrılamazsın

Ve nihayet en sonunda

İşte şu gerçeği anlarsın: 

Bir kere seversen eğer

Kolay kolay unutamazsın', 'Önceleri basit gelir  ‘Aşk da neymiş’ der geçersin  ‘Zaman her şeyin ilacı,  Bunu da unuturum’ dersin Unutmaya çalışınca Anlarsın imkansızlı...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unutamazsin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmayan', 'unutulmayan-sertac-kendirci-4zq9r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle uyandım her zamanki gibi bu sabah da

Açıp pencereyi dışarı baktığımda

Limandaki gemilerin yelkenlerinde gördüm seni

İçerken çayımı yerken ekmeğimi

Her zaman aklımdasın seni unutamıyorum

Anla artık beni, seni çok seviyorum', 'Seninle uyandım her zamanki gibi bu sabah da Açıp pencereyi dışarı baktığımda Limandaki gemilerin yelkenlerinde gördüm seni İçerken çayımı y...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unutulmayan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklara Sesleniş', 'uzaklara-seslenis-sertac-kendirci-6lhlc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu mısraları okurken

Kilometrelerce uzakta

Olacaksın belki de

Peki hatırlayacak mısın

Uzaklardaki o aşık adamı

Sana, aşkların

En büyüğüyle bağlanan

Seni canından da fazla

Dünyalar kadar seven

İnanmayacaksın belki ama

Hâlâ hasretinden yanan

Her gün senin için ağlayan...

Hatırlıyor musun

Belki de hayır

Ama o seni unutmadı

Unutamadı

Ve emin ol

Unutamayacak

Anlayamadın, sana olan

O büyük aşkını

Sevmedin onu

Ama o, 

O senin için ölürdü

Şimdi kilometrelerce ötede

Seni düşünüyor

Hep ağlıyor

Sen onu unuttun belki ama

O senden vazgeçmeyecek

Yüzün, gözlerin, gülüşün

Gözünün önünden hiç gitmeyecek

Ve uzaklardaki o aşık adam

İnan hep seni sevecek', 'Bu mısraları okurken Kilometrelerce uzakta Olacaksın belki de Peki hatırlayacak mısın Uzaklardaki o aşık adamı Sana, aşkların En büyüğüyle b...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/uzaklara-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan İsterse', 'i-nsan-i-sterse-cemal-ugur-50ae6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bozuk kurmuş evrenin düzenini

Adem ile Havva

İlk başta yaratmış kini, nefreti

Kuşaklara sergilemiş çıkarı

Bana verselerdi koskoca evreni

Yaratırdım bir birini seveni

Atardım dilimden

Kin, 

Nefret, 

Günah, 

Sevap, 

Sözcüklerini

Olurdum tanrıyla eşdeğer

Vermezdim insanlığımdan ödün

Aldanmazdım hurilere

Gitmezdim yerin altındaki Cennete

Dünyayı yapardım Cehennemsiz Cennet

Özendirirdim tanrıyı

Gelmek için O Ederdi Minnet

18.09.1974

Cemal UĞUR', 'Bozuk kurmuş evrenin düzenini Adem ile Havva İlk başta yaratmış kini, nefreti Kuşaklara sergilemiş çıkarı Bana verselerdi koskoca evreni Yar...', ARRAY['Türk Edebiyatı','Şiir','Cemal Uğur']::text[], 8.5, '{"poet":"Cemal Uğur","poet_slug":"cemal-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insan-isterse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Sevmekse Seni', 'yasamak-sevmekse-seni-sertac-kendirci-6jzez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine gözümün önüne geliyor

O tatlı, anlamlı gülümseyişin

Son demlerini yaşıyorsun bende

Sessiz bir gecenin ardından gelen

Sensiz bir güne merhaba derken

Gözyaşı kalmadı göz pınarlarımda

Artık ağlamayacağım senin için

Ne sevdiğimi haykıracak

Ne de hep bağlı kalacak

Değilim artık sana

Ama asla demem

‘Lanet olsun

Seni ilk gördüğüm güne’

Hayatımın tatlı bir parçası

Bir hatırası olarak

Aklımdasın hep

Evet gitme vaktim geldi

Son soluklarımı alıp veriyorum

Artık son anlarım bunlar, belli

Yaşamak sevmekse seni

İlk ve son kez ölüyorum', 'Yine gözümün önüne geliyor O tatlı, anlamlı gülümseyişin Son demlerini yaşıyorsun bende Sessiz bir gecenin ardından gelen Sensiz bir güne me...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasamak-sevmekse-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittikçe Unutuyorum', 'gittikce-unutuyorum-metin-yalcinkaya-54ls9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gittikçe unutuyorum

ilk tanıştığımız gün 

hava nasıldı

evlendiğimiz gün 

pazar mıydı bilemiyorum...

çok unutkan oldum bu aralar

o en sevdiğin kazağın

hangi renkti

beraber seyrettiğimiz dizi

unuttum neydi

kahretsin!

gittikçe unutuyorum

sensiz de yaşamaya alışıyorum

Ama yavaş yavaş unutuyorum

ben gittikçe yaşlanırken

gittikçe unuturken

sensizliğe alışırken

böylesine yaşarken

Bir kağıda Adresini yazıyorum

neden gitmiştin

bunu da bilimyorum

Her nerdeyse bil ki!

dün olduğu gibi 

bugünde seni çok seviyorum', 'gittikçe unutuyorum ilk tanıştığımız gün  hava nasıldı evlendiğimiz gün  pazar mıydı bilemiyorum... çok unutkan oldum bu aralar o en sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittikce-unutuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efta', 'efta-metin-yalcinkaya-4rff7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biraz oynayalım mı Efta

ben herkül olurdum 

sen zeyna

ama yine de

illaki sen bana Efta...

ben kardanadam yapardım,

Dayanamaz atkı sarardın...

pazarları dolaşırdıkben emirgan Der, 

sen diretirdin bebek olsun diye

dedim ya Efta 

yine de illaki sen bana

bir zaman sonra

Yeniden yeniden Efta

inan bana

belki de bir masalda

ya da bir oyunda

belki de ben herkül 

sen zeyna

dedim ya Efta

kırıp zincirimi

çözeceğim büyüyü

Efta...

 birgün mutlaka 

ormanın kitabında

bir sevda masalında

yaseminin  penceresinde

belkide

Sinan Çetin ''le 

hiç ummadığın anda

illaki sen bana

 Efta...!

duy! 

sana geliyorum!

Yolum bir nefes uzağında...', 'biraz oynayalım mı Efta ben herkül olurdum  sen zeyna ama yine de illaki sen bana Efta... ben kardanadam yapardım, Dayanamaz atkı sarardın.....', ARRAY['Türk Edebiyatı','Şiir','Metin Yalçınkaya']::text[], 8.5, '{"poet":"Metin Yalçınkaya","poet_slug":"metin-yalcinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/efta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnancımı Yitiremem', 'i-nancimi-yitiremem-abdullah-taybogan-te4hn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zindanlarda çürüsemde

Bir gün açlıktan ölsemde

Kurşunlara dizilsemde

inancımı yitiremem

Beni ezip sömürsende

Bin bir parçaya bölsende

Her gün terör estirsende

inancımı yitiremem

Beni çarmıha gersende

Tırnaklarımı söksende

Gözlerimi kör etsende

İnancımı yitiremem

Yurdumdan sürgün etsende

İdam ipimi çeksende

Pir sultanlar gibi bende

İnancımı yitiremem

Kör etsende gözlerimi

Koparsanda dillerimi

Kaybetsemde her şeyimi

İnancımı yitiremem', 'Zindanlarda çürüsemde Bir gün açlıktan ölsemde Kurşunlara dizilsemde inancımı yitiremem Beni ezip sömürsende Bin bir parçaya bölsende Her gü...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/inancimi-yitiremem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sevgiliye seslenis', 'sevgiliye-seslenis-orhan-balta-sdag3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey benim...

Yoksul yuregimin., zengin sevdasi, 

kanayan yaramin, kan damlasi

ey benim acilarimin kralicesi...

 Gecenin ayazinda....

 otobus terminalinde, titrerken bedenim, 

senin geleceginin, sicakligiyle isiniyordu beynim.

bir bilinmezde tanimistim seni

 sesini duymus. yazdiklarini okumustum.

elin, yuzun, gozun her seyin yabanciydi bana..

kurdugumuz cumlelerin anlamliliginda tanismistik.

iste bu yuzdendi merakli bekleyisim.

geldiginde otobus, 

dalgali saclarin anlamli bakislarinla, 

atildin boynuma kucuk olan bedenindi

ama sarilmalarin kocaman..

yok oluvermisti gecenin ayazi

sicak nefesinle bir gunes gibi dogmustun, 

Ankaraya...

Ey benim..

Zengin sevdamin..  sevgilisi

kara gecelerimin ay gunesi..

ey benim...gonul bahcemin cicegi...

kucaklasmamizdan sonra anlamistim

sensiz olamazdim ben 

yasama dair tum guzelliklerin ortagiydik.

elele tutusumuz bitmemeliydi.

bir mavi denizde  yuzduk, 

bir masada yemek yedik, 

kadehlerimiz sevgi icin kalkti

ayni yatagi bolustuk sicak sevismelerimizle.

Ey benim...

Sevgilim gelecegim umutlarim, 

dunum bugunum yarinim.

ey benim canim karim.

seni seviyorum biliyormusun.

derinmavim.', 'Ey benim... Yoksul yuregimin., zengin sevdasi,  kanayan yaramin, kan damlasi ey benim acilarimin kralicesi...  Gecenin ayazinda....  otobus ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevgiliye-seslenis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Bayrağım', 'al-bayragim-orhan-seyfi-sirin-bjptx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin için dağlar aştım, çöllerde kaldım! 

Özgürlüğün türküsünü ben senden aldım! 

Dalgalan sen, dalgalan sen, nazlı bayrağım! 

Solma sakın, al rengine kan veririm ben! 

Hasretini bekleyenler yolda kalmasın, 

Uygarlığın zirveleri sensiz olmasın! 

Dalgalan sen, dalgalan sen, ayla yıldızım! 

Solma sakın, al rengine kan veririm ben! 

Dalgalan sen, dalgalan sen, sonsuz dalgalan! 

Al bayrağım, senin için can veririm ben!', 'Senin için dağlar aştım, çöllerde kaldım!  Özgürlüğün türküsünü ben senden aldım!  Dalgalan sen, dalgalan sen, nazlı bayrağım!  Solma sakın,...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/al-bayragim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurcun', 'yagmurcun-orhan-seyfi-sirin-f0axy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstersen sana sevdiğin sanatçıları gönderebilirim bir dolmuşa doldurup...

Maykıl ve arkadaşlarını bagajda gönderirim. 

Yolda inip kaçamazlar! 

Bilirim yağmurda yürüyüşü seversin... 

Yağmurcunum benim! 

Sağanak yağış istersen... Şöyle bir on dakika sepeleyebilirim. 

İstersen iki parmağımla yıldızları bir bir söndürürüm! 

İstersen dünyayı tersine döndürürüm. 

İstersen bütün kapı zillerini çalıp kaçarız İstanbul’un, Newyork’un, Berlin’in ve Paris’in

Hong  Kong’dan uzak dururuz istersen! 

Beni yeni baştan sevmek istersen eğer; 

Yılları geriye alabilirim.

Yeniden seversin daha özenli, daha sımsıcak... 

Ben seni, zaten;  alabildiğine, doludizgin, kusursuz sevmiştim... 

Boşa geçen zamanları telafi edebiliriz! 

Yüksek takvim kurulu yakınım dolu... 

İşi yukardan bağlayabilirim! 

Akşam erken  oluyorsa bana söyle. Saatleri yavaşlatabilirim... 

Saatleri ayarlama bakanlığında toprağım var! 

İşi yukardan bağlayabilirim! 

Senin için soyu tükenmekte olan türleri kurtarabilirim. 

Son kalan bitkiyi çoğaltabilirim. 

Sen istersen eğer! 

Ayrılık sözcüğünü silerim lugatlardan! 

Sen istersen eğer! 

Bütün çıplakları giydiririm. 

Bütün açları doyururum. 

Sen istersen eğer... 

“Daha yaşanabilir bir dünya olur! ” 

Kaldırımlardan rahatsızlığın varsa söyle... 

Ceviz yeşili gölgelerle uzanan; bisiklet yolları yaptırabilirim. 

Tokyo’dan Venedik’e ulaşabilirsin

İşi yukarlardan bağlayabilirim... 

Sen istersen eğer! 

Islanmayan sigaralar  yaptırabilirim

Duş alırkan de içersin! 

Hangi deniz  eteğini ıslatmıştı söyle bakiim! 

Dibine dalarım, açarım vanasını, suyunu boşaltırım. 

Söyle bana hangi savaşı durdurayım. 

Hangileri bırakalım savaşsınlar

Sen istersen, Çin’i, Çek Cumhuriyeti ile tutuşturabilirim. 

Ya da Kore ile Kongo’yu... 

Baş harfleri yüzünden... 

Bir bahane bulabilirim... 

Birleşmiş Milletler’de ağırlığım var... 

İşi yukardan bağlayabilirim... 

Sen istersen eğer... 

Kalemimi yüreğime batırırım. 

Fildişinden şiirler sürerim  tedavüle 

Coşku ve adrenalin basarım yüreklere

Şiir zevkini arttırabilirim. 

Motosikletli kuryelerle sana yepyeni şiirler gönderebilirim. 

Balyoz gibi dizelerle saldırırım haksızlara

İşi kendim de bağlayabilirim... 

Gözlerin mi doldu? 

Yağmurcunum benim...

O kadar da kuşatılmış değiliz! 

Temiz yürekli iyi insanlar da var. 

Ağlama sakın! Sonra ben de ağlayabilirim... 

Ağlamak ne ki! 

Bardaktan boşanırım çağlayabilirim! ... 

En iyisi, işi yukarlardan bağlamak! ... 

Yağmurcunum benim! 

Sen korkmayasın diye... 

Binlerce şimşeği savar göğe uzanan ellerim. 

Gerçekleri bez gibi parçalayan, kağıt gibi yırtan benim! ...

Dağları titreten, ufukları ağartan yıldırımlar benim! ... 

Yağmurcunum benim! 

Sağanak yağış istersen şöyle bir on dakika sepeleyebilirim.

İstersen iki parmağımla yıldızları bir bir söndürürüm! 

İstersen dünyayı tersine döndürürüm. 

İstersen bütün kapı zillerini çalıp kaçarız İstanbul’un; 

 Newyork’un, Berlin’in ve Paris’in... 

Hong Kong’dan uzak dururuz istersen! 

Beni yeni baştan sevmek istersen eğer! 

Yılları geriye alabilirim. 

Yeniden seversin; daha özenli, daha sımsıcak! 

Ben seni, zaten; alabildiğine, doludizgin, kusursuz sevmiştim! 

Allah ne verdiyse sevmiştim! 

Ölümüne sevmiştim... 

Boşa geçen zamanları telafi edebiliriz. 

Yüksek takvim kurulu yakınım dolu. 

İşi yukarlardan bağlayabilirim. 

Söylediklerimi hafife alma! 

Bağlantılarımı sınırlı sayma! 

Yukarlarda hiç kimsem yok sanma! 

Bütün bunlarla mutlu olmazsan eğer...

İşi, en yücelerden bağlayabilirim. 

Sen, bembeyaz, kusursuz bir gül olursun İrem bağında. 

Ben dalına konmuş şark usülü şakıyan bülbül... 

Masallar gerçek olur. 

Benim bütün işim haykırmak olur... 

Sende, bende; hepimizde, yansıyan ölçüleri... 

Mutlak birliği...  Kusursuz güzelliği... 

İşi en yüceden bağlayabilirim.

Yağmurcunum benim! 

Yağmurcun! ...', 'İstersen sana sevdiğin sanatçıları gönderebilirim bir dolmuşa doldurup... Maykıl ve arkadaşlarını bagajda gönderirim.  Yolda inip kaçamazlar...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/yagmurcun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Yandık Diye Yalan Söylerler', 'asktan-yandik-diye-yalan-soylerler-orhan-seyfi-sirin-1v9r6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşktan yandık diye yalan söylerler! 

Oysa gerçek aşkın serinliği var...

Yakamozlar ile gönül eylerler; 

Oysa ufukların derinliği var! 

Dünya pazarına girmeyen bilmez; 

Ruhunu satmanın bir anlığı var! 

Aşkın menzilinde kılavuz olmaz! 

Her ışıklı yolun karanlığı var! 

Kalbinde aşk varsa, sen ondan söz et! 

Servet değil gönül yapmaktan haz et! 

Gençlik sarayını özenle göz et; 

Yakında onun da viranlığı var! 

Şan ve şeref düşer yiğit payına.

Varlık, yokluk biçim vermez huyuna! 

Aldanma cebine kanma boyuna; 

İnsanın toprakta derinliği var! 

Seni doğruluktan dilden eylerler

Atanın gittiği yolu paylarlar

“Aşktan yandık” diyip yalan söylerler

Oysa gerçek aşkın serinliği var! 

Aşkın yollarında Yunus’tur deha, 

Bedel var sevgilim bedelden daha! 

İstersen varırsın Yüce Allah’a

Emek derler bir yüz görümlüğü var.', 'Aşktan yandık diye yalan söylerler!  Oysa gerçek aşkın serinliği var... Yakamozlar ile gönül eylerler;  Oysa ufukların derinliği var!  Dünya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asktan-yandik-diye-yalan-soylerler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacak Şeyler', 'olmayacak-seyler-orhan-seyfi-sirin-z7sup', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En olmayacak yerlerde karşılaştık seninle... 

Olmayacak engeller çıktı, gecikti tanışmamız... 

Düşünürdüm karlı dağların koynunda sonsuz mavilikleri.

İsmin çocukluğumun celladı idi, ışığım bilemezsin... 

Ah! Akvaryum balığım benim; azgın ve tuzlu dalgalarda acı çeken. 

Deliler gibi yanarım geçen zamana ah! Utangaç yağmurlarda. 

Denizin özlemi ile çırpınan olta balığı yalnızlığım. 

Olmazlıkları düşünme, deli tayım benim. 

Zeytuni kısrağım, akça alınlım, dişi kaplanım. 

En olmayacak saatte aramalısın, mutlaka, gizlice... 

Bak biz, ikimiz, ikiden fazla ederiz iyi bil! 

Tenimiz aynı kumaştan biçilmiş, bir mayadan hamurumuz. 

Çeker aşk denilen girdap bizi derinlere görüşmesek de

Mesafeler erir alevimizden ayrılamayız. 

Ara beni, güçlenmek için... Gizlenelim bütün kötülüklerden. 

Ay ışığında parslar gibi derin yaralarını yalayan... 

Susalım, sokulalım, cesaretimizi gömüp gecelerin koynuna...

Günahlarımızın mahmurluğu başımızda, şavkı gözlerimizde.

Tutacak olan bir gün ecel olsa da yakamızdan 

Deli taylar gibi koşalım daha uzağa arzumuzdan.

Soydukça saflık tülünü gökkuşağı sevdamızdan...

Yalnız geçse de ömrüm, yapayalnız olmam geçti gülüm. 

Nefes aldığını düşledikçe gök kubbenin altında. 

Çalıverdim o ölümsüz, içten gülüşlü anını birden, 

Pespembe bir alevdi tenime, tanıma armağanı... 

Yapayalnız olman geçti senin de sımsıcak ceylanım. 

Olmayacak şeyler bekler bizi en olmayacak! 

İsyankar bir dik açı oluşturdukça cesur, onurlu alnımız. 

Böyle gümbür gümbür vurdukça ateşten yüreklerimiz. 

En olmayacak şeyler pusudadır şimdi. 

Mayın tarlası gibidir geçecek dakikalar. 

Olmayacak yerler, arzular, görmek için bizi sabırsızlıkla. 

En olmayacak armağandır güzelliğe zeka, şiire yürek katman. 

Ah! Olmayacak şeyler hatırlatman, hatırlatman...', 'En olmayacak yerlerde karşılaştık seninle...  Olmayacak engeller çıktı, gecikti tanışmamız...  Düşünürdüm karlı dağların koynunda sonsuz mav...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/olmayacak-seyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hünkar Hacı Bektaş Veli’ye döndüm!', 'hunkar-haci-bektas-veli-ye-dondum-orhan-seyfi-sirin-r1h47', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurdum, kar oldum, doluya döndüm.

Çınardım, kurudum çalıya döndüm. 

Kendini kandıran akıllar görüp

Ben canı gönülden deliye döndüm. 

Ne ömürler sürdüm günler içinde, 

Ne saraylar kurdum canlar içinde, 

Her menzili gezdim, yönler içinde, 

Hünkar Hacı Bektaş Veli’ye döndüm! 

Bildim yaradana vardı niyazım

Yedi kat göklerden döndü avazım

Nerde Kiziroğlu? Hani Ayvazım? 

Köroğlunu bekler, Bolu’ya döndüm.', 'Yağmurdum, kar oldum, doluya döndüm. Çınardım, kurudum çalıya döndüm.  Kendini kandıran akıllar görüp Ben canı gönülden deliye döndüm.  Ne ö...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hunkar-haci-bektas-veli-ye-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ölümüm', 'benim-olumum-orhan-seyfi-sirin-uy73m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana inat bir gün öleceğim. 

Sana inat ve senin güzelliğine... 

Lale bayramında güllere, 

Yaşanmamış hayallere inat, 

Senin en arzulu, en güzel çağına inat! 

Kahkahalar atarak öleceğim. 

Kefenim olmamak pahasına; 

İş olsun diye, spor olsun diye... 

Kalleşlik olsun, kurnazlık olsun diye... 

Sinsice öleceğim, haince öleceğim. 

Nasıl ölünürmüş göstereceğim. 

İbret alacaksın, kıskanacaksın. 

İlkten tanımayacaksın tabutumu. 

Sonra öldüğüm söylenecek inanmayacaksın. 

Sonra onu bir iki defa görmüştüm diyeceksin... 

Yüzünün kızardığını göremeyecekler, 

Şükredeceksin. 

Sonra sessizliğim hükmedecek tüm limanlara

Ölü yelkenliler batacak. 

Sebepsiz öldüğüme hükmedeceksin. 

Kendini avutacaksın kandıracaksın

Ben ölmüş olacağım, susacağım. 

Suçu benim üzerime atacaksın. 

Sonra gençliğim aklına gelecek, 

Sonra, seni ne kadar sevdiğim, sana taptığım. 

Sonra çelik gibi vücudum gelecek aklına...

Gücüm kuvvetim, sıhhatim neşem. 

Ölümüm ecel olmayacak! 

Bunu gecelere haykıracaksın. 

Fakat bunu anladığın zaman

Kemiklerim çürümüş olacak. 

Aynalarda birazcık katil göreceksin kendini. 

Mezarımı deşeceksin tırnaklarınla, 

Böcekler beni taşımış olacak. 

Bu dünyanın bütün milyonları da, 

Unutmayı satın alamayacak. 

Sana bu  kalleşliği yapacağım. 

Firar edeceğim dünyadan, 

Yüzünü bir daha görür görmez.', 'Sana inat bir gün öleceğim.  Sana inat ve senin güzelliğine...  Lale bayramında güllere,  Yaşanmamış hayallere inat,  Senin en arzulu, en gü...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/benim-olumum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumhuriyeti Kuranlar', 'cumhuriyeti-kuranlar-orhan-seyfi-sirin-zsspn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'CUMHURİYET İ KURANLAR

ÜŞÜDÜK SANMA! 

Paltomuz yok diye üşüdük sanma

Güneşten de sıcak düşlerimiz var. 

Tibet yaylasından Sarıkamış’tan, 

Daha soğuk geçen kışlarımız var. 

Dünya kumarında zarar eyleriz. 

Gölgemiz dışına yarar eyleriz. 

Ta ezelden aşkta karar eyleriz 

Akıl sır ermeyen işlerimiz var. 

Bizleriz Yunus’un halinden bilen, 

Ahi sofrasında nimeti bölen, 

Şehit Şerife’nin göğsünden gelen, 

Ana sütüne eş, aşlarımız var! ... 

Uygarlığın zirvesine uzandık! 

Tepeden tırnağa al kan bezendik. 

Bu vatanı biz nasıl mı kazandık? 

Tırnaklarımız var, dişlerimiz var. 

Öldü sanma gafil, bizler diriyiz! 

Ne devşirme, ne  de yeniçeriyiz. 

Mustafa Kemal’in askerleriyiz, 

Dokuzdan dokuza yaşlarımız var. 

Paltomuz yok diye üşüdük sanman

Güneşten de sıcak düşlerimiz var. 

Toprak bir tepeyiz Arıburnu’nda

Afyon’dan İzmir’e taşlarımız var. 

Tibet yaylasından Sarıkamış’tan, 

Daha soğuk geçen kışlarımız var. 

Bizleri rastgele yaşıyor sanman 

Akıl sır ermeyen işlerimiz var!', 'CUMHURİYET İ KURANLAR ÜŞÜDÜK SANMA!  Paltomuz yok diye üşüdük sanma Güneşten de sıcak düşlerimiz var.  Tibet yaylasından Sarıkamış’tan,  Dah...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/cumhuriyeti-kuranlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk Her Yerde', 'ataturk-her-yerde-orhan-seyfi-sirin-h55dr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sınırda bekçiyim, gökte bayrağım. 

Yaylada çobanım, ekinciyim ben. 

Sakarya önünde; Dumlupınar’da, 

Türklüğün en keskin kılıncıyım ben

Milletimin önündeyim, 

Mehmetçiğin yanındayım, 

Yiğitlerin  gözlerinde, 

Bebeklerin nabzındayım ben. 

Gençlik bayramının ateşi benim! 

Çocuk bayramının sevinciyim ben. 

Sanma Anıttepe bir tek otağım. 

Çağdaş Türk gencinin bilinciyim ben. 

Laik cumhuriyet elimdir benim. 

Türk’ü dost bilenin övüncüyüm ben. 

Genç yaşında şehit olan Mehmet’in 

Patlayan öfkesi ve hıncıyım ben.', 'Sınırda bekçiyim, gökte bayrağım.  Yaylada çobanım, ekinciyim ben.  Sakarya önünde; Dumlupınar’da,  Türklüğün en keskin kılıncıyım ben Mille...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ataturk-her-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devler', 'devler-orhan-seyfi-sirin-lo13m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İyi karıncalar gibi iyi insanlar

Biçimleri görünüşleri bizim gibi

Kulaklarına mısralar sığmaz yalnızca 

İnce işlerine aklımız ermez

Gezerler tenimizde uygun adımlarıyla 

Ölürüz de kirpiklerimizi omuzlayıp götürürler

Söyleyerek her kafadan hüzünlü marşlarını

Mataralarını düşlerimizle doldururlar

Gülümser duvarlarda asılmış gözlerimiz', 'İyi karıncalar gibi iyi insanlar Biçimleri görünüşleri bizim gibi Kulaklarına mısralar sığmaz yalnızca  İnce işlerine aklımız ermez Gezerler...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/devler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ile sızdık', 'ask-ile-sizdik-orhan-seyfi-sirin-ma2dw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O gece nasıl da aşk ile sızdık

iki insan değil iki yıldızdık

Mağlup kahramanlar kadar yalnızdık

Körpe goncaların açtığı yerde... 

Düştük çimenlere vurulmuş gibi, 

Seviştik aşk bizden sorulmuş gibi, 

Yandık alev alev örülmüş gibi, 

Kerem’in ateşler saçtığı yerde...

Kubbeler uyandı, kandiller yandı, 

şafak yakut renkli bir yudum kandı, 

Periler de bizi efsane sandı.

Mecnun’un ilk câmı içtiği yerde...

Sonunda sevgimiz  âfâkı aştı, 

Göklere yüksledi arşa ulaştı, 

Artık sevda değil bu bir savaştı, 

Hakkın da kendinden geçtiği yerde... 

O. Seyfi şirin



SiZi ARARKEN

Sizden en küçük bir iz arıyorduk

Derin vadilerde, esmer yollarda, 

Bir gün yorgun, kıyılara vurduk

Yıldızlar yüzerken uzak sularda... 

Gel!  buyruğu verdi mavi bir ışık, 

Firuze nehrini geçtik seherde, 

Aradık öpmeye yakut bir eşik

Ufukta güneşin battığı yerde...

şimdi oradayız o mavilikte, 

Ve şafaklar söker en bakir kana...

inanalım siz de gelin birlikte.

inanalım aşk denilen yalana.', 'O gece nasıl da aşk ile sızdık iki insan değil iki yıldızdık Mağlup kahramanlar kadar yalnızdık Körpe goncaların açtığı yerde...  Düştük çim...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ask-ile-sizdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımdasın', 'yanimdasin-orhan-seyfi-sirin-aqal4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanımdasın, kalbim ilk defa bütün, 

Herşeyden ilkönce sen varsın yanımda

Ne şarap isterim, ne deli tütün, 

Varlığın gezdikçe sıcak kanımda... 

Bırak oturmayı! lütfen kalk biraz, 

Burası evimiz biliyorsun, 

Yemişimiz bu gün bir demet kiraz, 

Masada kırmızı güller bulunsun...

Günahımız ortak... Yok öyle yağma! 

Bölüşelim sıcak bir somun gibi, 

Sonsuz bir şiir ol süzül bağrıma, 

Eriyelim şamdandaki mum gibi...

ilk yaz yemişleri bunlar al biraz, 

Sıkılma başbaşa kaldığımıza

Gezin biraz, salın biraz, gül biraz, 

inanalım gerçek olduğumuza...', 'Yanımdasın, kalbim ilk defa bütün,  Herşeyden ilkönce sen varsın yanımda Ne şarap isterim, ne deli tütün,  Varlığın gezdikçe sıcak kanımda.....', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanimdasin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Göremezsem...', 'seni-goremezsem-orhan-seyfi-sirin-v5f0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni göremezsem, nabzım durulur, 

Paslı sustalılar yürür bağrımda...

Kollarıma prangalar vurulur, 

Soğuk bir kan donar damarlarımda...

Seni göremezsem, bil ki ben hiçim, 

Başım bir mermer taş kadar ağırdır.

Kemirilmiş loş bir mezardır içim, 

Gözlerim kör, kulaklarım sağırdır.', 'Seni göremezsem, nabzım durulur,  Paslı sustalılar yürür bağrımda... Kollarıma prangalar vurulur,  Soğuk bir kan donar damarlarımda... Seni ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-goremezsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Evleneceğiz...', 'bir-gun-evlenecegiz-orhan-seyfi-sirin-gpjya', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün evleneceğiz belki seninle, 

Hani geçip mermer koridorları, 

Yuvamız olacak pembe boyalı, 

iki yanında buğday  tarlaları...

Çocuklarımız olacak gözleri kara, 

Bal köpüğü, sarı saçlı, değirmi yüzlü, 

Çocuklarımız, bütün çocuklar gibi, 

Temiz kalpli, al yanaklı, badem gözlü...

Kapımız çarçabuk açılmalı hep, 

Bir an evvel görsem yüzünü kârdır, 

Bembeyaz kulların boynumda iken, 

Her  mekân cennettird, her dem bahardır...', 'Bir gün evleneceğiz belki seninle,  Hani geçip mermer koridorları,  Yuvamız olacak pembe boyalı,  iki yanında buğday  tarlaları... Çocukları...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gun-evlenecegiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-orhan-seyfi-sirin-54azw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sür felek durmadan kan dolu câmı bile

Kanla başlar her demin kandır encâmı bile.

Gün gelir al kan içer toprak da bir şan için

Bir yudum kandan alır, şair ilhâmı bile. 

Gitti çoktan hülyadan yâr serv-i revan olup

Uğramaz oldu hâba o gül endâmı bile.

Yıkmadı gönlümüzü dostun yıktığı kadar

Hülagu Han Bağdat’ı Timurlenk şam’ı bile

Boşa gitmez devlerin attığı adım elbet

Hür ufuklardan gelir kol kol devamı bile

Umma zâhitsenmedet, kuzgunîrüzgârlardan

Döndürürüz borana şol esen samı bile. 

Aldı gönül dünyadan fâniliğin tadını, 

Sildi yıllar koymadı dillerde gamı bile.

Kahpe eflâk sarsılır billâh senin de tahtın

Gür iman diş diş söker, zindanı, dâmı bile.

Dört duvar az ol cefa ehline elbet ey Seyf

Kim sevişmek ecelle, vuslât akşamı bile.', 'Sür felek durmadan kan dolu câmı bile Kanla başlar her demin kandır encâmı bile. Gün gelir al kan içer toprak da bir şan için Bir yudum kand...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gazel-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samatya Günlüğü', 'samatya-gunlugu-orhan-seyfi-sirin-cqmba', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık köhne meyhanelere düştü adın...

Gravatsız akşam üstleri Samatya’da

Ucuz şarap içen tüm sarhoşlara, 

Trıaşsız birisi dert anlatmakta...

şarap şişelerine vurmakta yüzün, 

Sakız leblebisi nasıl bayat bak! ... 

Anlatan adamda bir gam, bir  hüzün

Sesi boğum boğum göz yaşı berrak... 

Artık tüm sarhoşlar tanıyor seni.

Hep senin yüzünden kesik neşeler...

Bütün duvarlarda seni buluyor, 

Kırılan kadehler, uçan şişeler... 

O.Seyfi şiRiN

HATIRLATMA

Bir salonumuz vardı, loş tapınaklar gibi.

Sen geldikçe bakımlı, sen geldiğince temiz.

Hani duvarlarında  sevişirdi sesimiz! 

Hani göğsün vururdu bir silah patlar gibi. 

şimdi sensiz şu cihan gözümde bir harabe

Sensiz batan her güneş binbir hüsrâna gebe

Sonsuz mesafelerde oynarım da körebe

Kollarım yana düşer, kırık kanatlar gibi...', 'Artık köhne meyhanelere düştü adın... Gravatsız akşam üstleri Samatya’da Ucuz şarap içen tüm sarhoşlara,  Trıaşsız birisi dert anlatmakta......', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/samatya-gunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlatma', 'hatirlatma-orhan-seyfi-sirin-wzjs3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir salonumuz vardı, loş tapınaklar gibi.

Sen geldikçe bakımlı, sen geldiğince temiz.

Hani duvarlarında  sevişirdi sesimiz! 

Hani göğsün vururdu bir silah patlar gibi. 

şimdi sensiz şu cihan gözümde bir harabe

Sensiz batan her güneş binbir hüsrâna gebe

Sonsuz mesafelerde oynarım da körebe

Kollarım yana düşer, kırık kanatlar gibi...', 'Bir salonumuz vardı, loş tapınaklar gibi. Sen geldikçe bakımlı, sen geldiğince temiz. Hani duvarlarında  sevişirdi sesimiz!  Hani göğsün vur...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hatirlatma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmamış Sonbahar', 'yasanmamis-sonbahar-orhan-seyfi-sirin-s5zxo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bitti bir rüyâ gibi Lâleli’de sonbahar; 

Gitti o ince hâyal, savrulup yağarken kar..

Gitti... Meçhul bir ufka efsunlu bir giz gibi, 

Gitti. Samanyoluna  akan bir yşıldız gibi...

Işıl ışıl ağlarken göklerde nebülözler, 

Bu hicran acısıyla zehir tükürdü gözler... 

Bir kan yolunda atlar çıldırasıya koştu, 

Bir kalbe gök taşları uğultularla düştü... 

Kubbeler sıradağlar, güller ülkesinde kal, 

Derken Süleymaniye, Ayasofya, TaçMahal

Kahkahalar duyuldu Roma’nın damlarında, 

Korkular taş  kesildi Vezüv akşamlarında. 

Alevli kapılardan süzüldü, aktı gitti, 

Kan fıskıran dağların ufuklarında yitti...

Soldu iri lâleler bu hicran yarasıyla, 

Eski ledünni şarkın en son hatırasıyla... 

Hicran senin hüsnüne hiç yakışmadı güzel, 

Gel. ilkbahar gününde ilk lâle açarken gel! 

Aydınlansın gönüller aşkın şamdanlarında, 

Çiçek açsın sevdalar Boğaz akşamlarında.', 'Bitti bir rüyâ gibi Lâleli’de sonbahar;  Gitti o ince hâyal, savrulup yağarken kar.. Gitti... Meçhul bir ufka efsunlu bir giz gibi,  Gitti. ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasanmamis-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nadide''ye', 'nadide-ye-orhan-seyfi-sirin-y5b0o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün burda güller açar Nâdide! 

Yalnızlık derindir bekler âtide, 

Yollar durur bir karanlık vâdide; 

Bir gayyadır artık durmaz düşersin...

Benim hayatımı sen de yaşarsın! 

Boş bir esneyiştir sevdasız hayat, 

Orta çağ hüznüyle geçer her saat.

Kanlı örtülerdir karanlık kat kat.

Korka korka karanlığı deşersin...

Benim hayatımı sen de yaşarsın! 

Her akşam ufuktan ızdırap doğar, 

Geceleri yatağına kar yağar, 

Sanırsın ki pencerende biri var.

Çılgın arzularla ona koşarsın...

Benim hayatımı sen de yaşarsın! 

(bestelendi)

Bu gün burda güller açar Nâdide! 

Yalnızlık derindir bekler âtide, 

Yollar durur bir karanlık vâdide; 

Bir gayyadır artık durmaz düşersin...

Benim hayatımı sen de yaşarsın! 

Boş bir esneyiştir sevdasız hayat, 

Orta çağ hüznüyle geçer her saat.

Kanlı örtülerdir karanlık kat kat.

Korka korka karanlığı deşersin...

Benim hayatımı sen de yaşarsın! 

Her akşam ufuktan ızdırap doğar, 

Geceleri yatağına kar yağar, 

Sanırsın ki pencerende biri var.

Çılgın arzularla ona koşarsın...

Benim hayatımı sen de yaşarsın!', 'Bu gün burda güller açar Nâdide!  Yalnızlık derindir bekler âtide,  Yollar durur bir karanlık vâdide;  Bir gayyadır artık durmaz düşersin......', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nadide-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-orhan-seyfi-sirin-1h1ps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdanın tılsımlı sarnıçlarında

Daha gürül gürül aşk içmeliyiz, 

Karlı tepelerde, dağ burçlarında

Her gün doğuşunda sevişmeliyiz! 

Gür ormanlar bize sırdaş olmalı

Dağlar katılmalı sevincimize

Her lâdin gölgesi, her köknar dalı, 

Açmalı sır dolu koynunu bize...

Uçmalı coşkuyla boz üveyikler, 

Kayalardan ıtır, bal damlamalı, 

Uykulu gözlerle ala geyikler, 

Bizi ürkek ürkek selamlamalı.

Yolumuza yumak yumak çökmeli, 

Engin yaylaların kardan ak sisi, 

Derelerden ay ışığı akmalı

Yıldızlar örtmeli üzerimizi.

Akkor aşkımızla yanmalı sular, 

Tutuşmalı hoyrat yıldızlar bir bir.

Gerçeğe dönmeli sıcak arzular, 

Maddenin yerini almalı şiir.

Sürüklenmeliyiz maceramıza

Yıldızlara doğru yürümeliyiz! 

Çağlar girdabında omuz omuza

Katıksız gerçeği aramalıyız...

Anlatmalı bizi bin yıl çiçekler

Yarınlarda bizden kökler olmalı

imzamız olmalı çakan şimşekler

Nikah defterimiz gökler olmalı.', 'Sevdanın tılsımlı sarnıçlarında Daha gürül gürül aşk içmeliyiz,  Karlı tepelerde, dağ burçlarında Her gün doğuşunda sevişmeliyiz!  Gür orman...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dugun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-orhan-seyfi-sirin-uiszz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Körpe bir gonca gibi yoluma çıktığın an

Beline yaprak gibi sarılmak gerekirdi...

Çınlamalıydı beş yıl, Bebek Moda, Aşiyân

Tepelerde elele görülmek gerekirdi...

Ah bu çılgın gönülde esmemeliydi boran, 

Ah! o samur saçlarda durulmak gerekirdi... 

Otuz yıldır şevkimi felek eyledi talan, 

Oysa ki kaç  otuz yıl yorulmak gerekirdi...

Baş eğdi aşk önünde, aşıkın almadı şan, 

Halbuki kaç otuz yıl yorulmak gerekirdi...

Senin için göklere kan püskürmeliydi, kan! ...

Doksan dokuz kurşunla vurulmak gerekirdi... 

Beline yaprak gibi sarılmak gerekirdi, 

Yoluna toprak gibi serilmek gerekirdi...

Minber-i Dâr’da bana en son arzumu soran! ... 

Boynuma perçeminden bir ilmek gerekirdi.

Öldüğüm gün kabrimde bir sen vardın ağlayan

Ah o gün yenibaştan dirilmek gerekirdi.

Fağfur: Çin porseleni.

Minber-i Dar: Hallac-ı Mansur’un kürsüsü, asldığı yer...', 'Körpe bir gonca gibi yoluma çıktığın an Beline yaprak gibi sarılmak gerekirdi... Çınlamalıydı beş yıl, Bebek Moda, Aşiyân Tepelerde elele gö...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-an-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar Altı', 'cinar-alti-orhan-seyfi-sirin-lm890', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman göz göze gelsek Çınar’da

Aramızdan uzun yüzyıllar geçer, 

Samanyolu  sanki yere iner de

Masamıza mavi yıldızlar saçar...

Gelirsin hasretle açılır kollar, 

Güllerle donanır geçtiğin yollar, 

Çınar’da bahtiyar istanbul’lular, 

Kumral gözlerinden mehtabı içer.

Gidermiş gönlümü koyup kenarda, 

Mermerler yaş olur bağrım kanar da

Sensiz ey sevgili, sensiz Çınar’da

Yorgun güvercinler göz yaşı içer...', 'Ne zaman göz göze gelsek Çınar’da Aramızdan uzun yüzyıllar geçer,  Samanyolu  sanki yere iner de Masamıza mavi yıldızlar saçar... Gelirsin h...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cinar-alti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkçenin Son Şairlerine Gazel', 'turkcenin-son-sairlerine-gazel-orhan-seyfi-sirin-jswqn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nev sâlik-i nev tarh-ı cünûn digeriz biz...

Çün tirkeş-i pür tir vatan derseferiz biz... (şeyh Galip)

Artık su gibi berrak, rüzgâr kadar hürüz biz.

Öyle bil ki her akşam hasretle ölürüz biz.

Bizi konuşur Türkçe günde nice bin kerre, 

Gök kubbede sedayız, dillerde şiiriz biz. 

Biz ki şark aleminde son serdengeçtileriz

Gözlerde at oynatır, kalplerde yürürüz biz. 

Cennetten de kâm  almaz bu aylanmış gönlümüz 

Cehenneme de girsek billâhi üşürüz biz...

Ey patlayan şıvgınlar, ey körpe tomurcuklar, 

şu toprağın  altında orman kadar gürüz biz. 

Bu yolda ne mürşit, ne de müridimiz var.

Saf rüyalar dokuruz, ruhları görürüz biz. 

Her sabah gelecekler ümidiyle yoldaşlar, 

Kardan kaftanlar giyer, dağları bürürüz biz.

Sevgiyi avcumuzda bir sır gibi gizleriz

Ve aşkı saçlarından sonsuza sürürüz biz... 

Kâm: Zevk, arzu, emel, istek...', 'Nev sâlik-i nev tarh-ı cünûn digeriz biz... Çün tirkeş-i pür tir vatan derseferiz biz... (şeyh Galip) Artık su gibi berrak, rüzgâr kadar hür...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/turkcenin-son-sairlerine-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Emre''ye', 'yunus-emre-ye-orhan-seyfi-sirin-z8gi4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anla artık beni, artık duy beni, 

Tanır bülbülünü gül ötüşünden, 

Süre süre saf şiirden gölgeni, 

Çağlar sonra geldim işte peşinden...

Kızlar pınarına bir kar yağardı, 

Seni bekler gizli gizli üşürdüm, 

Senden her geçtiğim yolda iz vardı, 

Ben her zaman hep bu yüzden şaşırdım

Vitrinlerde, çarşılarda sen vardın, 

Senin hırkan vardı her camekânda, 

Kaşgar’dan Budin’e sıradağlardın, 

Rahmet deniYUNUSziydin Taklamakan’da

Endülüs’te sütunlar devrilirdi, 

Viyana’da iplik iplik ağlardın, 

Sanatın Türkçe’ye efsun verirdi, 

Volga’da, Aras’ta, Nil’de çağlardın...

Gök kubbeye ey sevginin mimarı, 

Mısralar biçmiştin mermer sütundan.

Mısralar, kardan ak, başaktan sarı, 

Mısralar ki lezîz, ana sütünden...

Benim de bu hasret gözümde tüter, 

istemem özge şey aşk ateşinden.

Türkçem bana her gün söz açsın yeter, 

Erdem abasının dikilişinden...

Türkçem hep besteler ister her dilden, 

Turgaydan, bülbülden, çalıkuşundan

Revaklar ister ki akikten lâlden

Sütunlar ister ki lüle taşından... 

Geldim işte söz açmaya “Dirlik” ten

“Yolların gurbete bükülüşü”nden

Geldim söz açmaya “Tek” ten, “Birlik”ten, 

“Suların denize dökülüşü”nden... 

Haykırsam, bozkırlar bin sedâ verse

Gönlümde çınlayan en son feryâda

O gün bahtiyarlık rüyama girse

Ve görsem şavkını Amuderya’da... 

Savursa aşkımın sonra dört yana

Közlerini bir sam yeli harmanda

O gün, o gün, o gün coşarken Tuna

Sözlerini dersem Deliormanda...

Kubbem hep besteler ister  her dilden, 

Torgaydan, bülbülden, çalıkuşundan, 

Revaklar ister ki akikten lâlden

Sütunlar ister ki lületaşından... 

Ey türkçe’min dostluk dolu figanı, 

Sen toprağı “Vatan” yapan cemresin...

Eyy! Hür ufukların bengü fidanı, 

Bin yıl sonra da sen Yunus Emre’sin...', 'Anla artık beni, artık duy beni,  Tanır bülbülünü gül ötüşünden,  Süre süre saf şiirden gölgeni,  Çağlar sonra geldim işte peşinden... Kızla...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/yunus-emre-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsimde Memleketim', 'dort-mevsimde-memleketim-orhan-seyfi-sirin-znb3c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi kar yağmıştır Çiçek dağına, 

Yaman esiyordur, Denizli- Burdur, 

Sis çökmüştür Erzincan’a Eğin’e

Bozdağ’da aç kurtlar dolaşıyordur.

Çakıcı mı acep izmir’den gelen? 

Mehmet mi toprağa diz vurup ölen? 

Dağlarda bir ses va: “Depreşme ülen! ”

Efeler, dağları üleşiyordur.

Doyum yoktur yiğit Kars’ın seyrine, 

içel’e uzaktan el sallar Girne, 

Yemyeşildir  Sarayiçi - Edirne

KIRKPINAR’DA  devler güreşiyordur. 

şenlik kesilmiştir Kırşehir- Kaman

Öksürür olmuştur ihtiyar  Raman, 

KARAKOÇ haykırır Maraş’ta “taman

Yitik ozan ile yarışıyordur. 

Melek ağlıyordur Alibeyköy’de, 

Mehmet yürüyordur Serencebey’de

Atlar koşuyordur  Karacabey’de

Suna’ya ne giyse yaraşıyordur. 

Çöküyordur göğü tutan direkler, 

Tutukludur zindan zindan yürekler, 

Sararmıştır idamlıklar kürekler, 

(*)   Sinop’a mektuplar ulaşıyordur.

Gayrı Karabağ’a gelmiştir bahar, 

Sel olmuş akmıştır, derelerden kar, 

Gökte  tümen tümen leylekler uçar, 

Gence’de kuzular meleşiyordur...

Can sunguru uçmak diler kafesten, 

“Bir tel kopar” sükut bulur gülistan, 

Kara yere söylenilmiş bu destan

Uzak yıldızlara erişiyordur...', 'şimdi kar yağmıştır Çiçek dağına,  Yaman esiyordur, Denizli- Burdur,  Sis çökmüştür Erzincan’a Eğin’e Bozdağ’da aç kurtlar dolaşıyordur. Çak...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dort-mevsimde-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzularım', 'arzularim-orhan-seyfi-sirin-hrojc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şeref gibi, gurur gibi din gibi

Yüreğime sinen sizler misiniz? 

Gözlerimde bin asırlık kin gibi, 

Alev alev yanan sizler misiniz? 

Çalan siz misiniz bengü sazlarla? 

Akan siz misiniz korkunç hızlarla? 

Ak topuklu, samur saçlı kızlarla, 

Süt gölünde yunan sizler misiniz? 

Göğe mi çıktınız dal dal olup da? 

Yere mi aktınız al al olup da? 

Çelik kanatlı bir kartal olup da 

Ufuklarda dönen sizler misiniz? 

iziniz mi var hey! Tunçda demirde? 

Yarına yoğrulan kanlı hamurda, 

Kırcali’de Nehcivan’da Pamir’de 

Kır atlara binen sizler misiniz? 

Tutsak mı oldunuz acep savaşta? 

Türkü mü oldunuz Yemen’de Muş’ta

Yoksa bir kış günü Sarıkamış’ta(*)

Tümen tümen donan sizler misiniz? 

(*)   1. Dünya Savaşı’nda  Allahüekber dağlarında bir gecede donan yüz bini aşkın Türk askerine işaret edilmekte...', 'şeref gibi, gurur gibi din gibi Yüreğime sinen sizler misiniz?  Gözlerimde bin asırlık kin gibi,  Alev alev yanan sizler misiniz?  Çalan siz...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arzularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidecek Yerimiz Yoktu Arzularım', 'gidecek-yerimiz-yoktu-arzularim-orhan-seyfi-sirin-rl5cd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıcak bir çorbaya, 

Güzel bir kıza, 

Yakın bir dosta gider gibiydik

Gidecek yerimiz yoktu. 

Dostlarımız yok olmuştu, 

Sevdiklerimiz ölmüştü, 

Geriye dönemezdik, 

ileri atılamazdık, 

Tutup yıldızlara uzanamazdık, 

Tutacak dalımız yoktu.

içmek yoktu bahtımızda, 

Sevişmek yoktu, 

Felekten çalınmış geceler yoktu

...

Sıcak bir çorbaya, 

Güzel bir kıza, 

Yakın bir dosta gider gibiydik...', 'Sıcak bir çorbaya,  Güzel bir kıza,  Yakın bir dosta gider gibiydik Gidecek yerimiz yoktu.  Dostlarımız yok olmuştu,  Sevdiklerimiz ölmüştü,...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gidecek-yerimiz-yoktu-arzularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Bir Kez Daha Donduğu Zaman', 'toprak-bir-kez-daha-dondugu-zaman-orhan-seyfi-sirin-jnva5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprak bir kez daha donduğu zaman

Yıldızlar bıçak gibi bilenirken ayazda

Küçük ayakların buzları adımlarken

Dumanı üstünde gözlerimle, 

Kesilmiş saçlarımla

Yün gömleğimle ve kararmış tenimle, 

Kimbilir sana gelmiş olacağım. 

Toprak bir kez daha donduğu zaman, 

Tel örgüler korkunç ıslıklar çalarken sınırlarda

Karlara süngüler gibi saplanırken, 

Bozkır gönlümüzden hoyratlar.

Sana doğru buzları adım adım kıracağım.

Çelik ve kalın postallarımla, 

Karşında olacağım.

Toprak bir kez daha donduğu zaman.', 'Toprak bir kez daha donduğu zaman Yıldızlar bıçak gibi bilenirken ayazda Küçük ayakların buzları adımlarken Dumanı üstünde gözlerimle,  Kesi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/toprak-bir-kez-daha-dondugu-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Atlılar', 'yanlis-atlilar-orhan-seyfi-sirin-4cp7x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlış yollara döküldü maceramız, 

Pul pul oldu ettiğimiz duâlar...

Fareler kemirdi düşlerimizi, 

Gagaladı ucuz kanatlı  kuşlar. 

Yanlış atlara binen yoldaşlar, 

Yanlış yollarda yitip gittiler...

Bir biz kaldık cehennemler içinde.

Üstümüze çöktü bütün anılar.

Acı gönlümüzde piramit oldu.

Türkü, dilimizde dinamit oldu.', 'Yanlış yollara döküldü maceramız,  Pul pul oldu ettiğimiz duâlar... Fareler kemirdi düşlerimizi,  Gagaladı ucuz kanatlı  kuşlar.  Yanlış atl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yanlis-atlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonserserim sensin', 'sonserserim-sensin-salih-ozalasan-3kgga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sönmeyecek yüreğimde yaktığın ateş

Olmasada kavuşmak bir ömür boyunca

Nazına kurbanım, sevdan bir Güneş

Sımsıcak içimi ısıtır, gün boyunca

Emret olayım, sevgili, dost, arkadaş

Ruhum sana köle Dünya durdukça

Saçının bir teline Dünya''nın serveti eş

Ellerim açık tanrıya duacıyım, gün boyunca

Rabbim şahit sensiz doğmuyor Güneş

İstediğim tek sensin gönlüme eş

Makberim sen ol kıyamet kopunca

Sen ol yüreğimde sûr üflendiğinde

Ellerin ellerimde, gözlerin yine gözlerimde

Nur''un parlasın cennetin göklerinde

Senin yine esirin, yine aşığın olayım bir bedende

İsmini anayım söylensin bütün dillerde

Nar''ı cehennem yakmasın seni, ben varken yüreğinde

Y..Tar 28-10-2002 Saat 9.00', 'Sönmeyecek yüreğimde yaktığın ateş Olmasada kavuşmak bir ömür boyunca Nazına kurbanım, sevdan bir Güneş Sımsıcak içimi ısıtır, gün boyunca E...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sonserserim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler vardır kaç okka eder', 'sevgiler-vardir-kac-okka-eder-salih-ozalasan-nm7sb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiler vardır her yaşda yaşamaya değer

Sevgililer vardır uğruna ölmeye değer

Gönüller sevdayı bilmeseydi eğer

O zaman bu Dünya söylermisiniz? kaç para eder

Olmasa yüreklerde yeşeren sevgiler

Arada hasretler, gönülden özlemeler

Uğrunda söylenen şarkılar, yazılan şiirler

Aşık olmak o zaman taşırmıydı bir değer

Olurmuydu ozaman Aslı''lar, Kerem''ler

Söylenirmiydi Karacaoğlan''dan deyimler

Sazını eline alırmıydı, ? gönül gözüyle aşık Veysel''ler

Sevgiler vardır biçilmez onlara asla değer

Sevdamı gözle görüp elinle tutsaydın eğer

Görürdün bak ozaman kaç okka çeker

Sevgimi yüreğimden yerlere salsam eğer

Yemin ederim bu Dünya ağırlığından batar gider

Y.Tar.28-10-2002 Saat 11.45', 'Sevgiler vardır her yaşda yaşamaya değer Sevgililer vardır uğruna ölmeye değer Gönüller sevdayı bilmeseydi eğer O zaman bu Dünya söylermisin...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgiler-vardir-kac-okka-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizler Sokak Çocukları', 'bizler-sokak-cocuklari-ugur-oguz-sahin-qyn40', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizler sokakların umut çocuklarıyız

Ellerinden bir tutanı olmayanlarız

Ne sevgi gösteren ne de yüzümüze gülenimiz var

Nerede insanlık hani insanlar

Hadi uzatın ellerinizi koyun yüreklerinizi

Yansın bize de ışıklar yeşersin umutlar

Sıcak ve şefkatli bakışlarınızla

Bakın gözlerimizin içine

Tutun ellerimizden avuçlarınızdaki sıcaklıkla

Kıpırdasın suskun küllenen yüreklerimiz

Bir kez olsun kendi yavrularınızın yerine koyun bizi

Düşünün ayrılıkları geceleri karanlıkları yoklukları

Yavrularınız evinizde karşınızda dizinizin dibinde

Düşünün bir de bizleri sokakta karda kışta açta açıkta

İşte onlar bizleriz sahipsiz kimsesiz sokak çocukları

Kim sahip çıkar bize kim korur bizleri

Dertler hiç eksik olmaz gölgedir hep peşimizde

Durmadan yağmur yağar kar yağar üzerimize

Hepimiz umutta hepimiz tedirgin hepimizin çatık kaşları

Ah bir de olsaydı sokakların çatıları

Ne olur abiler ablalar anneler babalar

Verin bize umutları yaşatın bize sevgileri

Yeşertin diriltin içimizde solan hevesleri

Horlamayın dışlamayın kopartmayın hayattan bizleri

Çocuklarınız gibi bizler de bu toplumun birer gülleri

Çabuk tutun ellerinizi sarın bizdeki yaraları

Biz de bu ülkenin hepinizin evlatları

Yalnızız yalnız kimsesiz sahipsiz

İşte onlar bizler hepimiz

Çaresiz sokak çocukları', 'Bizler sokakların umut çocuklarıyız Ellerinden bir tutanı olmayanlarız Ne sevgi gösteren ne de yüzümüze gülenimiz var Nerede insanlık hani i...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bizler-sokak-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet''le eş değer', 'cennet-le-es-deger-salih-ozalasan-zbsal', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deme sakın yürek dediğin nedirki

Elime alsam bir avuç eder

O küçücük yüreğe sığdırdığım

Sevgiyi görsen eğer

Denizler ortasında bir nokta

Dünya içinde kaybolur gider

Hasret ile içime attığım

Gözyaşım yerlere aksa eğer

Yemin ederim Dünya tufandan beter

Denizler taşar yer yarılır

Kainat biranda yokolur gider

Sana olan sevdamı

Yazmaya kalksam eğer

Sanmaki tüm canlıların

Yazmaya ömrü yeter

Dağlar kalem olsa

Denizler mürekkep eğer

Yetmez yazmaya

Yarıda hepsi biter

Biçilmez sevgime

Bu Dünya''da bir değer

Elmas olsa

Bilmem kaç kırat eder

Mizan terazisine tüm sevaplar konsa eğer

Belki onlar olur yarısına eş değer

Benim gönlümdeki s eda vazgeçilmez

Yalnız cennetle eşdeğer

O benim için binlerce cennet eder

Y.Tar.28-10-2002 Saat 12.30', 'Deme sakın yürek dediğin nedirki Elime alsam bir avuç eder O küçücük yüreğe sığdırdığım Sevgiyi görsen eğer Denizler ortasında bir nokta Dün...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cennet-le-es-deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktayım', 'uzaktayim-hakan-cabuk-hxr65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün ben burdayım

Senden bin adım daha uzaktayım

Sana seni sevdiğimi burdan söyledim

Baktım ki senden sadece bir adım uzaktayım.', 'Bugün ben burdayım Senden bin adım daha uzaktayım Sana seni sevdiğimi burdan söyledim Baktım ki senden sadece bir adım uzaktayım....', ARRAY['Türk Edebiyatı','Şiir','Hakan Çabuk']::text[], 8.5, '{"poet":"Hakan Çabuk","poet_slug":"hakan-cabuk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Onlar', 've-onlar-abdullah-dogann-r01x4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve onlar

     İki can

İki sevdalı, 

     İki uçurum çiçeği

İki yoldaş, 

     O an

Tek yürek kesilmiş

     Amed Surları gibi dikili, 

Babil bahçesi gibi görkemli, 

     Yıldızlara doğru ARARAT gibi...

Asi - gururlu - direngendiler

     Akıyorlardı Fırat Dicle''ye

Sonra Okyanus oluyordu gözleri

     İsyan etmişcesine, 

Zeus''a Ehriman''a

     Karanlığa...

Işık olmuşlardı Yeryüzüne

     Bir Kök 

     İki baş olmuş

Bilge ağacına dönmüşlerdi

     Beklerken 

        Barışı

           Zilan''ı

              Çiğdemi

                 ve...', 'Ve onlar      İki can İki sevdalı,       İki uçurum çiçeği İki yoldaş,       O an Tek yürek kesilmiş      Amed Surları gibi dikili,  Babil b...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ve-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Yüreğim', 've-yuregim-abdullah-dogann-f7kkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ve ben

Ne garip yalnızlık

Yalnız olmak içine dalmak...

     Ve beni, kendimi

     Ve bendeki seni aramak

     Şu uzaktaki yat gibi, 

     Gökyüzünde süzülen martı gibi, 

     Sahilde yürüyen ak sakallı gibi, 

     Ve yüreğim sıcak

     Ve yüreğim saf su misali...

Ve yalnızım, 

Ve sen,     

Ve ben,      

Ve Arıyorum sevgi seni, 

Ve yürüyorum, 

          Yürüyoruz güneşe...

                     Sonsuzluğa...', 'Ben ve ben Ne garip yalnızlık Yalnız olmak içine dalmak...      Ve beni, kendimi      Ve bendeki seni aramak      Şu uzaktaki yat gibi,     ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ve-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kadın', 'ey-kadin-abdullah-dogann-czs6k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay gibi ışıldayan gözleriyle, 

Yüreğimde yuva kuran kadın.

Gülümseyen gamzeleriyle, 

Ahriman ruhla karşi duran kadın.

  

Beni günaha davet eden

  PANDORA MISIN? 

Meyvenden verdiğin aden bahçesinde

Bilge Ağacı mısın kadın? 

Bakışlarımı güneşe çeken 

Buğday kokulu

Okyanus olmuş bedenimde, 

Yelkenime yön veren kadın...

Fırtına kesilip uçuruma götüren misin? 

Uçurum çiçeği misin yoksa kadın? 

Beni hayata - sevgiye davet eden, 

Söylermisin kadın sen ZiN misin?', 'Ay gibi ışıldayan gözleriyle,  Yüreğimde yuva kuran kadın. Gülümseyen gamzeleriyle,  Ahriman ruhla karşi duran kadın.    Beni günaha davet e...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirafın Olsun', 'i-tirafin-olsun-abdullah-dogann-fjekd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsyan bayrağını çek de git

YÜreğini inkar et de git

Yok oluşumla

Yeniden kendini

Yaratarak git

Hadi kendini itirafın olsun

Sevdiğin..

Seni Seviyoum de...

Hayatı, 

Ekmeği, 

Şarabı, 

Ananı

Tuzu sever gibi

Seviyorum de...

Ve kendine itirafın olsun, 

Ve git...', 'İsyan bayrağını çek de git YÜreğini inkar et de git Yok oluşumla Yeniden kendini Yaratarak git Hadi kendini itirafın olsun Sevdiğin.. Seni S...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/itirafin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılma', 'yanilma-riza-aslan-rx9g0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yanılmazsın

yanılmada

sen yine 

bildiklerini oku

bilmediklerinin arasında

devam et

sonuna kadar uğraş

hep bildiklerini yap

yapmaya da devam et

ve sakın ola yanılma

git

çok iyi bildiğin yoldan

hep aynı yere

patikalarına girme yaşamın

labirentlerinde dolanma 

kaybolursun 

üzülürsün

aman ha

git

çok iyi bildiğin yoldan

hep aynı yere

Rıza Aslan

Bergama        izmir

27  -  10  -  2002', 'yanılmazsın yanılmada sen yine  bildiklerini oku bilmediklerinin arasında devam et sonuna kadar uğraş hep bildiklerini yap yapmaya da devam ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanilma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaret', 'ziyaret-ugur-oguz-sahin-sev6m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Misafirlikteydim bugün

Ölü sandığımız varlıklara

Mezar ziyaretine

Yeşil yemyeşil her taraf

Ve tuhaf bir sessizlik

İstesen de istemesen de

Ürperti veriyor insana

Sadece çekiç sesleri geliyor

Başlık taşı yazan mezarcı ustadan

Bu ziyareti yazayım dedim hatıra kalsın

Bir kaç mısradan sonra başımı kaldırdım

Şöyle etrafıma bakayım dedim

Birde ne göreyim

Cesetlerin yıkandığı gasıl hane karşımda

Çok canlı bedenler gördüm

Yıkanırken banyolarda

Ama bu bambaşka farklı bir manzara

O bembeyaz fayanslar içinde

Bölmeler arasında karşımda tabutlar içinde

Sıra sıra yıkanmak için bekliyorlar

Cansız bedenler musalla taşında

Hep gideriz ya dostların ziyaretine

Şimdi burada da bir sürü

Sessiz sedasız yatan insanlar

Ama bu seferki başka keder

Derin bir hüzün

Ebedi bir yolcu uğurlanmakta

İki metrelik kefen elbisesi

Son yolculuk için hazırlanmakta

Ve birazdan tüm dostları sevdikleri ardında

Soluk aldığı yaşam bitmiş rızkı kesilmiş

Vakit ezan okunacak

Ardından namaz ve son dua

Her giden gibi oda ebedi istirahatgâha

En sevdikleri bile bırakacak onu

Ayrılacak yanından o mezarlıktan

Herkes eve dönecek doğanın kanunu bu

Çünkü yaşam devam edecek

Hep geçeceğiz bu kapıdan

Her gelişin bir dönüşü var muhakkak

İyi insan ol iyiliksever ol

Daima yardıma koş yardım et

Ne yaptıysan bu dünyada

Onlardır ebedi seninle gelecek

Şöyle derin derin düşünceye daldım

Al sana dedim işte hayat

Kırdığımıza kırıldığımıza değer mi

Bu yalancı dünyanın mücadelesi hırsı neye

Hani o unvanlar hani o mal mülkler nerede

Bir tiyatro sahnesindeyiz dostlar

Bilmiyoruz kaçıncı oyun bu

Ne zaman son perde

Hiç kapanmadı kapanmaz o sahne

Sadece seyirciler eksilir

Birer birer sessizce

Bir ses duydum birden bire

Arabanın camına vurdular geldim kendime

Dostlarım Tülin veTülay dönmüşler

Misafirlikten duadan

Bugün yağmurlu bir Cuma

Hava gibi pusluyduk hepimizde yüklü hüzün

Bugün biz Karaca Ahmet''teydik ziyaretteydik

Bize de başkaları gelecek ziyarete bir gün', 'Misafirlikteydim bugün Ölü sandığımız varlıklara Mezar ziyaretine Yeşil yemyeşil her taraf Ve tuhaf bir sessizlik İstesen de istemesen de Ür...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ziyaret-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzibe Mekan', 'i-zibe-mekan-riza-aslan-luura', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yağmur yağıyor

ıslanmışım

önemi yok 

sırıl sıklam ıslanmanın

yağmur yağıyor

bunalmışım

duramıyorum buralarda

herşey üstüme geliyor

ağaçlar devriliyor

binalar yıkılıyor

ben her şeye rağmen

yaşıyorum

yaşamaya çalışıyorum

yağmur yağıyor

sokaklar

izibe mekanlar gibi 

sessiz

hiç bir insanoğlu yokmuşcasına

yalın

bir ben varım

izibe mekanlarda

yaşadığımı

yaşamak zorunda olduğumu

kendime ispatlama ihtiyacıyla

hep ardımdan

takip ediliyorum sanki

geride bıraktıklarım

ardımdan geliyor gibi

çarasizce dönüp bakıyorum ardıma

bir kez daha

bir şeyleri

birilerini görmek umuduyla

ama değişmiyor 

hiç bir şey

her ardıma döndüğümde

olduğu gibi

gördüğüm yine 

büyük 

çok büyük bir 

boşluk...

08 - 10 - 2002 

Salı

Edremit     Balıkesir', 'yağmur yağıyor ıslanmışım önemi yok  sırıl sıklam ıslanmanın yağmur yağıyor bunalmışım duramıyorum buralarda herşey üstüme geliyor ağaçlar d...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/izibe-mekan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön', 'don-orhan-gencebay-k06co', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevdigim ellerde nazın çekilmez, 

olurya usanıp bıkarlarsa dön.

sohbetin dinlenmez kahrın çekilmez, 

olurya gönlünü yıkarlarsa dön, 

yalan sözlerine inandıkların; 

riyakar yüzüne aldandıkların; 

birgün terk ederse dost sandıkların, 

o tatlı canını sıkarlarsa dön, 

anlarsın sevdigim hele düşünce, 

kıymetimiz soysuz ele düşünce, 

ünvanın duyulup dile düşünce, 

lakabını dilber takarlarsa dön, 

eger savunacak sözün kalmazsa, 

başka çaren başka çözüm kalmazsa, 

sokaga çıkacak yüzün kalmazsa, 

artık kötü gözle bakarlarsa dön,', 'sevdigim ellerde nazın çekilmez,  olurya usanıp bıkarlarsa dön. sohbetin dinlenmez kahrın çekilmez,  olurya gönlünü yıkarlarsa dön,  yalan s...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/don-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayramlar_____________', 'bayramlar-ugur-oguz-sahin-4o7qi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir bayram daha yaşıyoruz bugün

Herkeste neşe mutluluk bendeyse hüzün

Herkes misafirlikte herkes el öpmede

Babam elini öpemiyorum yüzünü göremiyorum

Toprak göstermiyor seni üstünü örtmekte

Sokaklarda insan seli herkes bayram etmekte

Oysa bende yine o her zamanki hüzün

Göz yaşlarım yere düşmekte

Yine penceremin kanatları titremekte

Bayramları gözü yaşlı karşılarım hep o pencerede...', 'Bir bayram daha yaşıyoruz bugün Herkeste neşe mutluluk bendeyse hüzün Herkes misafirlikte herkes el öpmede Babam elini öpemiyorum yüzünü gör...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bayramlar-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahkar Resimler', 'gunahkar-resimler-mustafa-kucuktepe-rxgg6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'koşuyorum koşuyorum

gökyüzünden korkuyorum

bulutları dargın görüyorum resimlere

o resimler günahkar resimler

bırakın günahkar resimleri diyorum

korkuyorum

bırakın özgürlüğü haykırmak istiyorum

bağırmak dalga kırmak hayalleri dağıtmak istiyorum

koşuyorum korkuyorum gökyüzünden

zihnimin perçeminden tutmayı bırakın

bırakın beni sevmek istiyorum dağları dalgaları

bırakın

koşuyorum ve korkuyorum', 'koşuyorum koşuyorum gökyüzünden korkuyorum bulutları dargın görüyorum resimlere o resimler günahkar resimler bırakın günahkar resimleri diyo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Küçüktepe']::text[], 8.5, '{"poet":"Mustafa Küçüktepe","poet_slug":"mustafa-kucuktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunahkar-resimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ürperti', 'urperti-mustafa-kucuktepe-xij6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geceler

o

kabul etmeyip türkülerimi reddettiğinde

karanlık olur etraf

sazlar çalar zulmetin inadına

ağaçlara dinletirdi kahırlarımı

yalnızdı o

karanlık onu da sarmıştı

kaplamıştı rüyalarını türkülerimin

kimsesizdi o

çiçeksiz

kalpsiz

topraksız

ya sonbahar olmasaydı

kiminle çekerdi bu yükleri sırtında

dağ yamaçlarına

çile kokuyordu her tarafından

kahır esiyordu rüzgarlarla bu yana

ya sonbahar da olmasaydı

kim dinleyecekti türkülerimi

kim paylaşacaktı kederlerimi

kim', 'geceler o kabul etmeyip türkülerimi reddettiğinde karanlık olur etraf sazlar çalar zulmetin inadına ağaçlara dinletirdi kahırlarımı yalnızdı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Küçüktepe']::text[], 8.5, '{"poet":"Mustafa Küçüktepe","poet_slug":"mustafa-kucuktepe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/urperti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-ugur-oguz-sahin-1uypb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan günahlar için

Tövbesine sevap işlesen ne olur

Kırılan umutlar için

Sonsuz dünyalar kursan ne olur

      

Siyah lekeler nasıl ak olur

Günahlar nasıl silinir pak olur

O ayrılan eller yeniden nasıl birleşir

Gönüller de huzura kavuşur', 'Dönüşü olmayan günahlar için Tövbesine sevap işlesen ne olur Kırılan umutlar için Sonsuz dünyalar kursan ne olur        Siyah lekeler nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-olur-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İade-i İtibar', 'i-ade-i-i-tibar-ugur-oguz-sahin-k20oh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşklarda kalmadı o ince ruhlar

Düşünceden soyutlandı günahlar sevaplar

Artık pembe evler kurmuyor gönüldeki mekânlar

Eskiden gözlerden kalbe inilirdi şimdi riyakâr aşklar

Aslı ile Kerem Leyla ile Mecnundu aşk abideleri

Demek ki sevgiler yozlaşmış

Daha tarih yazmadı başka isimleri

Zamanlar geçti devir değişti

Aşklar internet''te yaşama geçti

Aşk abideleri bugünleri görselerdi

İade-i itibar isterlerdi', 'Aşklarda kalmadı o ince ruhlar Düşünceden soyutlandı günahlar sevaplar Artık pembe evler kurmuyor gönüldeki mekânlar Eskiden gözlerden kalbe...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/iade-i-itibar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Ayrılık', 'bitmeyen-ayrilik-ugur-oguz-sahin-bplat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiçekler bahçemde açmıyor artık

Seni çok özledim inan

Ne söylesem ne etsem de

Deli gönül dinlemiyor artık

Mevsimlerim hep hazan

Çekilmiyor yalnızlık

Dertliyim hicranım sonsuz

Tüketti beni bu ayrılık', 'Çiçekler bahçemde açmıyor artık Seni çok özledim inan Ne söylesem ne etsem de Deli gönül dinlemiyor artık Mevsimlerim hep hazan Çekilmiyor y...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bitmeyen-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gözlerin', 'deniz-gozlerin-ugur-oguz-sahin-q8xpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek sandım yaşattım seni özlemimde

Denize aşıktım içinde gözlerinin rengi var diye

Çırpındım dalgalar misali çaresizliğinde

Yolcuyum artık demir almış o meçhul gemide

Ayrılığın acısı içimde beraberimde

Resmin önümde rotamı çevirdim bilinmez gurbete

Ara sıra da olsa boş bir anında hatırına geldiğimde

Adımı anmasan da fark etmez

Hiç olmazsa

Hatıralarımız canlansın gözlerinde', 'Gerçek sandım yaşattım seni özlemimde Denize aşıktım içinde gözlerinin rengi var diye Çırpındım dalgalar misali çaresizliğinde Yolcuyum artı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deniz-gozlerin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Sandın Kendini', 'ne-sandin-kendini-ugur-oguz-sahin-wuysk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle günahlar işledik en kutsal günlerde bile

Kazancımız neydi elimize ne geçti hadi söylesene

Zamanı geçtikten sonra dövünsen af dilesen ne çare

Seninle birlikte çiğnedik ilkeleri göz göre göre

Yalan bir sevdaydın yalancı bir yemin

Peşindeki balık gibi

Sürükledin beni bir yerden bir yere

İstediğin neydi ki

Ne gönülde rahattın ne huzur bıraktın

Kabahat kimde ki

Ne sandın kendini seni de Allah yaratmadı mı

Onun yanında senin kutsallığının

Zerre kadar lafı mı olur ki', 'Seninle günahlar işledik en kutsal günlerde bile Kazancımız neydi elimize ne geçti hadi söylesene Zamanı geçtikten sonra dövünsen af dilesen...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-sandin-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım Seni', 'unutamadim-seni-ugur-oguz-sahin-ihowm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmurlarda ıslandım hep yürürken

Hiç çıkmadın aklımdan düşümden

Saçlarımdan buharlaşıp uçardın

Farkında olmazdım üşüdüğümün

Yol boyu seni düşünüp yürürken

Sanki vücuduma değen her damlayla birlikte

Senin gelişin sanırdım yağmurun şakırtısını

Kâh sessiz derinden kâh hızlı yağarken

Yağmur değil de sen düşerdin gönlüme

Hep yağmurlarla birlikte yaşadım hüznünü

Unutmadım unutamadım seni ömrümce', 'Yağmurlarda ıslandım hep yürürken Hiç çıkmadın aklımdan düşümden Saçlarımdan buharlaşıp uçardın Farkında olmazdım üşüdüğümün Yol boyu seni d...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/unutamadim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yaşıyorum', 'sana-yasiyorum-ugur-oguz-sahin-o0nnn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürüyorum sokaklarda yollar hep çıkmazda

Teslim olmuyorum bir gün güzel olacak diyorum her şey

Gülüyorum kendi kendime kaderime

Beni kandıran hayallere

Ve çaresizliğe inat direniyorum sensizliğe

Bazen karamsarlığa düşmüyorum değil

Ama aramızdaki engeller daha çok yükseltiyor hırsımı

Ne mümkün vazgeçmek senden o öldüren gözlerden

Ne de vazgeçmek fesleğene inat o hayat veren teninden

Çok şeyimiz var bir birine anlatacağımız

Değiştireceğiz geçmişi şaha kalkacak bu sevdamız

Kurtaracağız bir düş olmaktan yaşanacakları

Gerçekleşmesi için yüreğimizi sabrımızı ortaya koyacağız

Sevmenin uzantısı sensin noktası ben

Bu gönülde bu sevgi böyle olmasaydı zaten

Çekilmezdi zorlukların teslim olurdum hemen

Zaten hep yokluğunla yaşamaya çalıştı bu beden

Yıllar geçse de değişmeyeceksin bende

Etrafında yıkılmaz kaleler örülse de

Fark etmez içinde olduğunu bilmek yeter bana

Açılana dek beklerim kapılarda

Çünkü yaşadıklarım sana', 'Yürüyorum sokaklarda yollar hep çıkmazda Teslim olmuyorum bir gün güzel olacak diyorum her şey Gülüyorum kendi kendime kaderime Beni kandıra...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimize', 'i-kimize-ugur-oguz-sahin-v6skl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özlerim seni o sahil boyu gezdiğimiz yerlerde

Hep bizdik hep aşkımızdı gezerdik dillerde

Şimdi ayrıyız şimdi uzaklarda

Başka yerlerde

Kim bilir ne son bekliyor ikimizi

Başka başka gönüllerde

Ne mutluluk nasip oldu ne de gülmek bize

Bilmem dünyada gülmeyen kader

Birleştirir mi bizi mahşerde', 'Özlerim seni o sahil boyu gezdiğimiz yerlerde Hep bizdik hep aşkımızdı gezerdik dillerde Şimdi ayrıyız şimdi uzaklarda Başka yerlerde Kim bi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ikimize-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Aşk', 'sessiz-ask-gokcen-coskun-g0rv3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne olursa olsun biz sessizce anlaşabiliyorduk, 

yazdıklarımız saklıyorduk yakılacaklarmışcasına, 

müziklerimzi de dinliyorduk bizden çalacaklarmışcasına, 

birbirimizi çok seviyorduk ama söyleyemiyorduk 

sanki o sessiz aşk sona erecekmiş gibi......', 'ne olursa olsun biz sessizce anlaşabiliyorduk,  yazdıklarımız saklıyorduk yakılacaklarmışcasına,  müziklerimzi de dinliyorduk bizden çalacak...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Coşkun']::text[], 8.5, '{"poet":"Gökçen Coşkun","poet_slug":"gokcen-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sessiz-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şevval''im Sen Doğdun Bugün', 'sevval-im-sen-dogdun-bugun-ugur-oguz-sahin-g7af6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güneş doğdu yeni bir çiçek açtı bugün

Evimizde bayram var sen geldin bugün

Yüzüne bakınca dedeni hatırlattın bana

Hayatta olsaydı nasıl bağrına basardı seni bugün

Çok sevgilere şahit oldu bu gönlüm

Senin sevgin başka seni seyretmenin hazzı bambaşka

Bahtın açık olsun Şevval''im tomurcuk gülüm

Yaradanın en büyük hediyesi sensin

Bugün hem senin hem benim doğum günüm

Ne iyi ettin de geldin annen de baban da bugün ikinci düğün

Acılar sancılar bitti Sevgül''üm yanında boncuk gözlün

Mutluluk yaşattın bir dünya sundun bize uzun olsun ömrün

En büyük hediyesi bize çocuklar bu kısa acımasız ömrün

Şimdi seni bekliyor Oğuz Enes yaramazlık sırası sende

Evin de seni bekliyor köşe kapmaca oynamak için annenle

Baban kızarsa sana amcama söylerim sizi de

Sen hasretle gelen bebeğim nazar değmesin sana 

O güzel gözlerine

Şimdi bu hayatın ilk basamaklarındasın

Neler bekliyor seni neler bu yolda

Yıldızlara yükselsin adın

İnşallah bu ömrü kazasız belasız mutlulukla yaşarsın

Bu şiirim sana hediye sen de okuyunca amcanı anarsın', 'Bir güneş doğdu yeni bir çiçek açtı bugün Evimizde bayram var sen geldin bugün Yüzüne bakınca dedeni hatırlattın bana Hayatta olsaydı nasıl ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevval-im-sen-dogdun-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazsın', 'unutamazsin-ugur-oguz-sahin-9appw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnan bir gün 

Mutlulukla örteceğim özlemini

Her tarafı örten

Bem beyaz kar gibi

Buselerim alnında iz bırakacak

Dudaklarında yakışımı

Kalbinde akışımı

Ölene dek unutamayacaksın', 'İnan bir gün  Mutlulukla örteceğim özlemini Her tarafı örten Bem beyaz kar gibi Buselerim alnında iz bırakacak Dudaklarında yakışımı Kalbind...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutamazsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder Oldum', 'derbeder-oldum-ugur-oguz-sahin-aqftr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Garip şu dünya çok garip

Bitmiyor hazan mevsimleri

Gönüller yaralı düşler kırık

Hani gülmek mutluluk hani

Bir azap günü bitmeden

Bir diğeri başlıyor

Kurulan dünyalara

Atılan temeller hani

Artık gerçeği de

Yalanla karıştırır oldum

Unuttum kendimi de unuttum

Derbeder oldum', 'Garip şu dünya çok garip Bitmiyor hazan mevsimleri Gönüller yaralı düşler kırık Hani gülmek mutluluk hani Bir azap günü bitmeden Bir diğeri ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/derbeder-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemezsin', 'bilemezsin-ugur-oguz-sahin-moxtv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorum boynu bükük

Her gece bekliyorsun beni

Yine mahzun yine o pencerende

Yalnızlıkla kavgadasın biliyorum

Bakışların yorgun bitkin susamış

Umutlarına günler çekiyorsun

Hep çıkagelmemi bekliyorsun ansızın

Sonunda hep hayal hayal bu diyorsun

Biliyorum hep beni düşünüyorsun

Ama bir gerçeği unutuyorsun

Bizi ayıran kilometreleri sabrımı

Seni ne kadar sevdiğimi bilmiyorsun', 'Biliyorum boynu bükük Her gece bekliyorsun beni Yine mahzun yine o pencerende Yalnızlıkla kavgadasın biliyorum Bakışların yorgun bitkin susa...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilemezsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-ugur-oguz-sahin-8bx8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel artık özlemin deli divane etti

Beni boynu bükük serme yollara

Hasretim bir tanem ciğer parem

Uzat artık sevgi ellerini

Gel artık gecelerimin feneri

Kaldır serdiğin yollardan beni

Çıkar yüreğimden hasretleri

Dola artık boynuma ellerini

Gel artık hep yanımda ol

Kalksın aramızdan o hasret yol

Şimdi mevsim sonbahar

Sen bir ömür boyu sıcaklığım ol', 'Gel artık özlemin deli divane etti Beni boynu bükük serme yollara Hasretim bir tanem ciğer parem Uzat artık sevgi ellerini Gel artık geceler...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-artik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk', 'arabesk-attila-i-lhan-98ir8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ıslığında usturalar bileniyor

bıyıkları marşandiz katarı

zulasında eroini esrarı

tutuklandıkça yenileniyor

kafası kızdı mı taksim''de akşam

bütün lahmancunlar ondan sorulur

oğlanın birine takıldı / tamam

çengelköy''lü sevtap diye meşhur

göğüsleri hakikat birer kumru

eskiden de süslenir boyanırmış

ayak ayak üstüne atıp oturdu mu

insanda can mı bırakırmış

sabaha karşı bir büyük rakı

yıldız tozuması külüstür mehtap

arabada sevişmek başlıca merakı

ne kanun tanıyor ne de kitap

bu yollara düşecek adam mıydı

çiçek yaptırmalar parfüm filan

bu sefer yakasını fena kaptırdı

sevtap başını yiyecek anlaşılan

boşversene / daha ölmedik ulan', 'ıslığında usturalar bileniyor bıyıkları marşandiz katarı zulasında eroini esrarı tutuklandıkça yenileniyor kafası kızdı mı taksim''de akşam b...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/arabesk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batan Bu Köhne Şileb...', 'batan-bu-kohne-sileb-attila-i-lhan-yoz9d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'garson masa iyi manzarayı değiştir

sırası mı mehtabın yıldız yağmurunun

bu gece yalnızım onlar gelmeyecek

sapa bir yerindeyim umutsuzluğumun

hava soğuk olmalı ağaçlar bütün duman

eğer bulabilirsen ölü bir kar getir

beyazlığı kalın bir su gibi uzayan

bu gece yalnızım onlar gelmeyecek

batan bu köhne şilebde ne işleri var

çünkü battım kasa boş ne para ne çek

çünkü bütün telefonlar ısrarla alacaklı

bu gece yalnızım onlar gelmeyecek

hani o sarışın kirpikleri saçaklı

yanağını viski bardağıyla serinleten

sonra nilay hani kafayı buldu mu ağlar

cam yeşili yasemin cıgara dumanı nursen

batan bu köhne şilebde ne işleri var

garson masa iyi manzarayı değiştir

büyük şimşek çakmalı gök gürültüsü filan

şöyle dalları kıran şakırtılı bir yağmur

köpek havlamaları bulut karanlığından

zehir bulabilir misin çabucak öldürecek

artık arsenik mi olur siyanür mü olur

hangisi olursa olsun hepsi işime yarar

yoksa bir tabanca bul bir avuç mermi getir

bu gece yalnızım onlar gelmeyecek

batan bu köhne şilebde ne işleri var', 'garson masa iyi manzarayı değiştir sırası mı mehtabın yıldız yağmurunun bu gece yalnızım onlar gelmeyecek sapa bir yerindeyim umutsuzluğumun...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/batan-bu-kohne-sileb-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issızlığın Çığlığı', 'issizligin-cigligi-attila-i-lhan-q45kv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cam ipliğinden sıkı dokunmuştur

kristal vitrindeki bu loş kadın

soğuk tenhalığında kaşları alnının

ince bir hayretle sanki donmuştur

yansımaları sokağa vurmuştur

kafasındaki müstehcen dazlaklığın

sedef boşluğunda aralık ağzının

sevişmelere çağrısı korkunçtur

taşralı bir ''köpek'' buna tutulmuştur

simsiyah bir ünlem önünde camların

her gece jiletle kazıyamadığın

kaç kere kaçırmayı filan kurmuştur

çünkü kadınlar gözünü korkutmuştur

kraliçesi budur yalnızlığın

ürettiği nilüfer iç bataklığının

cansız olmasından neler ummuştur

ıssızlık çığlığını şehirde unutmuştur', 'cam ipliğinden sıkı dokunmuştur kristal vitrindeki bu loş kadın soğuk tenhalığında kaşları alnının ince bir hayretle sanki donmuştur yansıma...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/issizligin-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık Mezarlığı', 'isik-mezarligi-attila-i-lhan-9lhlf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'birden demir kuşlar fazla şehir

demir ağaçların tamamladığı

yeşilden sarıya gözleri değişir

gagaları kırmızı neon yaprağı

asmalımesçit''te dolmuş durağı

yarı gece açıkça geçilmiştir

meçhul kaatillerin bıraktığı

bir silah gibi parlıyor şiir

uykusuzlukların ateş aldığı

gece barlarında içkiler zehir

kınından çıkar öfke bıçağı

sabaha karşı cinayet işlenir

öle kim aslında öldüren midir

besbelli hiç anlaşılamayacağı

karakolda intihara heveslenir

bir acil serviste hazır yatağı

korku yalnızlığın gelişmesidir

gece hiç kimsenin kurtulamadığı

ay şimşek mavisi belirmiştir

bıçak parıltısıyla yalar sokağı

sarhoş bir fahişenin ağladığı

gözlerinde kahır birikmiştir

sevdiği itlerin farkına varmadığı

parasını yiyorlar allah bilir

geceleyin beyoğlu ışık mezarlığı', 'birden demir kuşlar fazla şehir demir ağaçların tamamladığı yeşilden sarıya gözleri değişir gagaları kırmızı neon yaprağı asmalımesçit''te do...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/isik-mezarligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hekimim Sensin', 'hekimim-sensin-ugur-oguz-sahin-zq6gu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Resmin önümde gözlerin gözümde

Bakışların bir ömür yolu sanki

En derin yarasın kalbimin köşesinde

Bekliyorum seni sensiz her günümde

Mevsimlerin adı sen yaşanacak yaşatacak sen

Artık korkmuyorum karanlık gecelerden

Sevgimin ışığı içinde farkı yok gündüzlerden

Ne senden vaz geçmek mümkün ne de o gözlerden

Şimdi dudaklarında buse ömründe bir imzayım

Yalnız sana ait koskoca bir dünyayım

Sevgin ekildi bir kere gönül bahçeme

Hekimim sensin şifa sende artık sana hastayım', 'Resmin önümde gözlerin gözümde Bakışların bir ömür yolu sanki En derin yarasın kalbimin köşesinde Bekliyorum seni sensiz her günümde Mevsiml...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hekimim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkunun İsi', 'korkunun-i-si-attila-i-lhan-buxpg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kederli bir ağustostu

mehtabı ölüm tehlikesi

tellerde bir vınlama

elektriğin titremesi

adeta gümüş kaplama

yağlı beyaz bir taksi

bebek''te unutulmuştu

cihangir''e son müşterisi

gece böcekleri sustu

kadın değil koyu sinema

bir renkli film güzelliği

içi hayli eskimiş ama

yosmalığı kusursuzdu

cıgara bir cıgara daha

besbelli eksiklendiği

dolmabahçe''de kustu

hem sarhoş hem huzursuzdu

hayatı büyük bir yanılma

pektaş holding''in metresi

yani sırılsıklam mutsuzdu

kul köle olmuştu adama

gençken ne kadar korkusuzdu

yaşlandıkça artıyor endişesi

gecelerdir uykusuzdu

bu da gelmişti başına

herhalde başka bir kız buldu

etine dolgun genç irisi

adam ondan soğumuştu

az kaldı kovulmasına

kederli bir ağustostu

acı sular geliyor ağzına

gözlerinde korkunun isi', 'kederli bir ağustostu mehtabı ölüm tehlikesi tellerde bir vınlama elektriğin titremesi adeta gümüş kaplama yağlı beyaz bir taksi bebek''te un...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/korkunun-isi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serüvenin Sonu', 'seruvenin-sonu-attila-i-lhan-vtfrk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yankılanır

abanoz sokağı''ndan

fahişelerin tamtamları

                tamtamları

ingiliz sarayı iki adımlık yer

viyana oteli tenha bir liman

koridorlarında bıyıkları ıslak

gözleri kan çanağı

yalnızlık adamları

             adamları

305''te şüpheli bir cıgara

ucunda tel tel dökülen bir çocuk

ne yanına dönse simsiyah

yağmurun kederli camları

                          camları

birini bekliyor ama kimi

elleri ter içinde teri soğuk

kapıyı dinler arasıra

akşamları

          militan akşamları

yukardaki odalar bütün boş

fakat merdivenlerde fısıltılar

belli belirsiz ayak sesleri

birileri mi var

o mu çok sarhoş

siyasi polis olmasın

yoksa serüven bitti mi

anlaşılmaz telefonlar çalıyor

karanlık anlamları

            anlamları', 'yankılanır abanoz sokağı''ndan fahişelerin tamtamları                 tamtamları ingiliz sarayı iki adımlık yer viyana oteli tenha bir liman ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seruvenin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokağa Çıkma Yasağı', 'sokaga-cikma-yasagi-attila-i-lhan-gq24z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öyle büyük hicran ki

cam çerçeve bırakmıyor

kırdı kapıları döküldü sokağa

havada yangın kokusu

itfaiye sirenleri

uzaktan uzağa

öyle büyük hicran ki

telefonlar devamlı meşgul çalıyor

trafik durdu

çarşılar darmadağın

çığlıklar geçiyor karanlıktan

camlarda sinsi bir titreme

boğuk bir uğultu

yeraltından

borular patlamış sular

vahim bir tenhalığa akıyor

öyle büyük ki hicran

zincirleme

elektrik kontakları

şerareler dökülüyor sokak lambalarından

ceryanlar kesildi

gözden kayboldu şehir

sanki siyah bir denize batıyor

ayak sesleri boş meydanlardan

hoyrat kanatları

yukarda bir helikopterin

o ihanet sessizliğini

par

     par

          parçalıyor', 'öyle büyük hicran ki cam çerçeve bırakmıyor kırdı kapıları döküldü sokağa havada yangın kokusu itfaiye sirenleri uzaktan uzağa öyle büyük hi...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sokaga-cikma-yasagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlı Yol', 'tasli-yol-behcet-necatigil-ins9d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşklar, dostluklar, bir arada olmalar

Hangi birine yetiş, geçtim, öderim.

Eşler, çocuklar, ölmüşlerin yakınları

Sonradan katılanlar, kaçtım, öderim.

Çığlık ve kısık çağrı

Kimi mi çağırdım, bilsem söylerim.

Gün gelir, bırakır, başlar yalnızlık

Ne için, kimdi,
..........
..........', 'Aşklar, dostluklar, bir arada olmalar Hangi birine yetiş, geçtim, öderim. Eşler, çocuklar, ölmüşlerin yakınları Sonradan katılanlar, kaçtım,...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tasli-yol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
