INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Roman Okudum Seni Düşündüm', 'roman-okudum-seni-dusundum-cemal-sureya-uccb1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bende tarçın sende ıhlamur kokusu

Yürürüz başkentin sokaklarında

Bir nehir şu tutuk konuşan cumartesi

Üstünde iki yonga: Çarşamba, bir de cuma

Ayrılık lafları etme sevgilim

Önümüz Temmuz önümüz Ağustos nasıl olsa

Kolkola yürüyoruz tek tük öpüşüyoruz

Sonra ayrılıyoru
..........
..........', 'Bende tarçın sende ıhlamur kokusu Yürürüz başkentin sokaklarında Bir nehir şu tutuk konuşan cumartesi Üstünde iki yonga: Çarşamba, bir de cu...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/roman-okudum-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-hakan-rodop-vmhs5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir türkü söyle kapımın önünden geçerken

içinde biraz hüzün biraz sevinç olsun

geçmişten kalan anıları anlatsın

ve kanat çırpışları duyulsun yalnızlığımın

salınsın dört bir yana ayrılık haberim

gülsünler halime okul önlerindeki çocuklar

ne zaman biterse kelimelerim

ben seni almaya yalnızlığımla gelirim...', 'Bir türkü söyle kapımın önünden geçerken içinde biraz hüzün biraz sevinç olsun geçmişten kalan anıları anlatsın ve kanat çırpışları duyulsun...', ARRAY['Türk Edebiyatı','Şiir','Hakan Rodop']::text[], 8.5, '{"poet":"Hakan Rodop","poet_slug":"hakan-rodop","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizligim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreklerde Köz Kalır', 'yureklerde-koz-kalir-ugur-oguz-sahin-3qkfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimi kapattım sana

Gönül gözlerimden yaş aksa da

Sildim seni yüreğimden

Bir tat alamadım bu sevgiden

Biz de nasip aldık kurtulamadık kader sillesinden

Gözü kör aşık olduk farkında olmadan bilmeden

Bir durakta durduk zamansız istemeden

Yanıldık bu sevdada da kesildik yemeden içmeden

Her aşkta sevgide bir tanık vardır

Her tanık sanık için bir şeyler anlatır

Zamanın her yerinde geçmişte bir şeyler kalır

Mazide hatıralar kapanmayan bir çok yara vardır

Yüreklerde köz bırakır mutluluksa hep bir ahtır', 'Kalbimi kapattım sana Gönül gözlerimden yaş aksa da Sildim seni yüreğimden Bir tat alamadım bu sevgiden Biz de nasip aldık kurtulamadık kade...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yureklerde-koz-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AY DA, GÜNEŞ’TE AYGÜNEŞ’TE GÖRDÜM', 'ay-da-gunes-te-aygunes-te-gordum-kemal-yilmaz-785cm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AY DA, GÜNEŞ’TE  AYGÜNEŞ’TE GÖRDÜM

ATATÜRK’Ü GÖRDÜM; MUSTAFA KEMALDE

Atatürk’ü gördüm, Atatürk’ü Mustafa Kemalde

Mustafa Kemal, Yılmaz’ın eli, Mustafa Kemalde

Saçları, ak, masmavi gözleri, yürüyor enginlerde

Mustafa Kemal, içimizden biri, daima sinemizde

Ulu Çınarın, gölgesinde büyür, serpilir nesilleri. 

Atatürk’ün izi, Mustafa Kemallerin hep ayni izi

Mustafa Kemal’in eli, dudağında koca tepedeydi

Tarihimize yazdık silinmezcesine, sinemizede seni

Mustafa Kemal, Yılmaz, yılmaz Atatürk’ün gençliği

Duysun Dünya, Atatürk’ün, izinde, Ey! Türk Gençliği

Mustafa Kemal, Aydın, umurluda, Atatürk, umurluda.

Üç demet şiir, umurlu çiçeklerini, okuyun bir solukta

Atatürk’ün elini gördü, el salladı, ah geçip gitti treni

Onurluca, umurludan çıktık yola, Atatürk’ü görmeye

Yaban ellerde kalanlar, kitap olur, elden ele gezmeye 

(Gök kubbeye baki)  (Kitaplar, en dayanıklı mezar taşı)

Atatürk, Mustafa Kemal, görür Mustafa Kemal’leri.

El sallar, beyaz vagonundan, Güneş gibi sıcak, elleri. 

Keskin, kararlı, şahin bakışı, cahilinin, yüreğini deldi.

Gecelerde, ay, mehtapla, yıldız, gündüzlerde Güneşti

Atatürk, Başöğretmen, Mustafa Kemal, öğretmendi

Farkı, yoktur, sadece zaman, Atatürk, daha, önceydi.

Biz, Mustafa Kemal, sizler, Mustafa Kemallersiniz

Atatürk, önderim, Mustafa Kemal Milletin vekiliydi

ATATÜRK! ü on sekiz bin aleme yazsam da yine az

Mustafa Kemal, Atatürk, Mustafa Kemaller Yılmaz

Kâlbimde, gönlümde, sevgimde, sensin, Atatürk’üm

Ne mutlu Türk’üm diyene, ne mutlu Türk, Türk’üm, 

Ey Türk; unutma, vazifeni, İstiklalini, Cumhuriyetini.

Kıyamete kadar yükselecek, Türkiye Cumhuriyeti

Fuat GÜRSOY, âşıksın sen Türkiye, Cumhuriyetine

Atatürk’ü gördün, Atatürk’ümü, Mustafa Kemallerde

(Hayatta en hakiki mürşit ilimdir)   AYGÜNEŞ’i izle.', 'AY DA, GÜNEŞ’TE  AYGÜNEŞ’TE GÖRDÜM ATATÜRK’Ü GÖRDÜM; MUSTAFA KEMALDE Atatürk’ü gördüm, Atatürk’ü Mustafa Kemalde Mustafa Kemal, Yılmaz’ın el...', ARRAY['Türk Edebiyatı','Şiir','Kemal Yılmaz']::text[], 8.5, '{"poet":"Kemal Yılmaz","poet_slug":"kemal-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ay-da-gunes-te-aygunes-te-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onüçüncü Burçta Delirmek', 'onucuncu-burcta-delirmek-hasan-huseyin-korkmazgil-xdc26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kollarını o biçim kavuşturma, kötü çok kötü

acır gibi bakma yüzüme yoksulluğum büyüyor

aç şu perdeleri nella aç nella uykum geliyor

kır şu camları nella kır nella boğulacağım

yapraklar kokunca bir

sular  yorulunca

sızılar gencelince

                                    bil ki bir başımayım

                                    bil ki kaçıp kurtulmak

                                    bil ki sayısız

                                    kötü çok kötü

sessizliği sevmiyorum sustur şu çığırtkanları

ben bu bulvarları güzel günlere götüreceğim

bırak ellerini ellerime mutluluklara götüreceğim

dalgınım kırıkdöküğüm bu düzenler beni böyle

uzak konuşunca bir

anılar tutuşunca bir

kollarım öksüzleşince

                                     bil ki dolaşıp düşmek

                                     bil ki kendimden öte

                                     bil ki karışık

                                     kötü çok kötü

bu karanlık sürdükçe kendimizden kurtulamayız

sığmıyor sığmıyor sesim bu yorgun biçimlere

çözdüm suları, bıraktım kısrakları, ardımsıra yıldızlar

onüçüncü burçtan beni gecelere dağıtacaklar

onüçüncü burçtan beni gecelere dağıtacaklar

acılar bağrışınca bir

şarkılar susunca bir

ninniler tükenince

                                       bil ki ben

                                       bil ki çok yakın

                                       bil ki apaçık

                                       kötü çok kötü

(Temmuz Bildirisi)', 'kollarını o biçim kavuşturma, kötü çok kötü acır gibi bakma yüzüme yoksulluğum büyüyor aç şu perdeleri nella aç nella uykum geliyor kır şu c...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/onucuncu-burcta-delirmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
