INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka Kuşu Olmaktı', 'anka-kusu-olmakti-abdullah-dogann-om0gq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün tan batarken, 

Fırtınalar koparken, 

Şimşekler çakarken, 

Kirpiklerimden düşen yağmur ruhuma akarken..

Bir ses gelecekti belirsiz.

Biraz öfkeli, huzursuz, 

Biraz kızgın, kaygısız, 

Nerdesin, nerlerdesin? 

Gidememiştim.

Yüreğim yanıyordu.

Ama seven su olup akmalı, 

Yağmurcasına dökülmeliydi saçlarına yarin.

Tanımıştım.

Derinlerden gelen, 

Dalgalarıydı kıyılarıma vuran

Volkan gibi içimden patlayan.

Tanımıştım

           Onu

                 Ve

                       Sesini...

Ama anlamıştım ki; 

Yeryüzünde ulaşabilmek sevdiğine...

Sevdiğinle, sevgiyle kalmak

Kendini küllerinden yaratmak.

Anka kuşu olmaktı sevmek.', 'Dün tan batarken,  Fırtınalar koparken,  Şimşekler çakarken,  Kirpiklerimden düşen yağmur ruhuma akarken.. Bir ses gelecekti belirsiz. Biraz...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/anka-kusu-olmakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıları Yaktım', 'anilari-yaktim-mehmet-babacan-g58xb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anıları yaktım gittiğin gece, 

Onlar ki, ömrümce doyamadığım.

Gözlerindir bende kalan sadece

Belki de yakmaya kıyamadığım...

İnce bir sızı ki, çok çok derinde, 

Nasılsa dinecek günün birinde.

Bir tutam kül kalır yangın yerinde

Rüzgârla savrulsun diyemediğim...

Gene bir hüzünle çökecek akşam, 

Yavaşça çıkacak pusudaki gam; 

Mevsimler geçecek, sürecek yaşam

Takvimde bir yere koyamadığım...', 'Anıları yaktım gittiğin gece,  Onlar ki, ömrümce doyamadığım. Gözlerindir bende kalan sadece Belki de yakmaya kıyamadığım... İnce bir sızı k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Babacan']::text[], 8.5, '{"poet":"Mehmet Babacan","poet_slug":"mehmet-babacan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anilari-yaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varmış Bir Yokmuş', 'bir-varmis-bir-yokmus-fahrettin-ozdemir-q7hue', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını sordular söylemedim

Pamuk prenses dedim

Yalan da değildi hani

O da kaf dağının ardında

Sen de

Ben gene de yılmadım

Seni bulmak için yola çıktım

Az gittim uz gittim

Engin dağları

Nice denizleri aştım sanırken

Bir de baktım ki

Bir arpa boyu yol gitmişim.', 'Adını sordular söylemedim Pamuk prenses dedim Yalan da değildi hani O da kaf dağının ardında Sen de Ben gene de yılmadım Seni bulmak için yo...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-varmis-bir-yokmus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmelisin', 'bilmelisin-abdullah-dogann-c9kr6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmelisin 

Bu ayrılık büktü belimi.

Şimdi ağlatıyor her şiir, 

Her türkü beni.

Usul usul giriyor dertler penceremden, 

Bazen soğuk bir rüzgar, 

Bazen damla damla yağmur gibi

Akıyor hasret pınarıma...

Bu ayrılık dayanılmaz bilmelisin

Sabahlara dek ağlıyorum / Yalnız ve içli.

Gözyaşlarım sevgi ırmağı dökülür, 

Bilmelisin...

Bir umut bekliyorum gelecekten

Bazen el açan bir dilenci, 

Bazen muhtaç bir çocuk...

Bilmelisin

Seninle anlıyorum yaşamın, 

Ve yaşamanın değerini, 

Seninle ölmekteydi bahçemdeki kuşlar

Seninle gelmekteydi alacalı kelebekler...

Ve kınalı Hazaller, 

Ve Seninle Açılıyordu 

Leylaklar, Nergis, Sosiler

Dört mevsim çiçekleri biliyor musun? 

Belki de dönmeyecek, 

Bana hep uzak olacaksın

Ama ne olur son bir defa

Gel tut şu ellerimden..

Hiç olmazsa bir dost, 

Hiç olmazsa bir arkadaş gibi...', 'Bilmelisin  Bu ayrılık büktü belimi. Şimdi ağlatıyor her şiir,  Her türkü beni. Usul usul giriyor dertler penceremden,  Bazen soğuk bir rüzg...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bilmelisin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Çocuk', 'merhaba-cocuk-abdullah-dogann-v1io5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşam dediğin nedir ki çocuk...

Bilmeksizin bakan iki gözle başlar.

Ve yenek felek tokadı ardından, 

Merhabayla konuk olursun YAŞAM''a çocuk...

         Yaşam, 

              Acı ve

                  İsyan pınarındasın...

Olmaz geriye dönüşün çocuk...

YAŞAM akışıyla götürür seni

Ölümsüzlük otunu arayan GILGAMEŞ''e

Kendini, 

         Aşkını, 

              Yoldaşını ve 

                    Koynuna gireceğin TOPRAK ANA''yı

Bulma yolculuğuna düşersin, 

''Yaşam Yoldur'' der ustalar çocuk

Sen de olmaktasın bir yolcu, 

Düşe-kalka olacaktır bu yolculuk.

          Yolu tanımak için, 

          Önce kendini tanımalısın çocuk, 

YAŞAM, 

ÖLÜM ikiz kardeştir sen de bilmelisin, 

Ölmek için yaşamamalı

Yaşamak için ölmeli çocuk

Ölüme giderken 

Şiir okuyan yüzüen celladın, 

Nesimince, 

           Şeyh Bedrettince, 

                 Gandhice, 

                      Mevlanaca...

Prometehsça yaşamalı çocuk...

Yoksa; 

YAŞAM

     Girdap 

           ve Sen 

                  Ayrılmaz üçgen olurmusunuz...

Sonra üzülür Ahura - Mazda

Yaşamına, 

Yaşamıyor yaşadığına, 

Gelip gidişinin iz bırakmayışına

      YAŞAM çocuk; 

Bir kelebeğin

Narin kaygılı ve heyecanıdır..

      Bir bal arısının

      O çiğdemden şu nergise uçmasıdır...

Bir topla karıncanın

Sırtlayıp ekmek kırıntısını

Yuvasına götürüşüdür...

      Bir ceylanın ela gözleriyle

      Biraz daha yaşama hevesiyle

      Arkasına bakmadan koşmasında, 

      Balerince figür çizmesinde saklıdır çocuk...

YAŞAM

     ve

         YAŞAM''a dair herşey...

              VE KAVGAN

                    VE ÜTOPYAN

                          VE SEN...

Sönmesin sakın çocuk, 

İçindeki yaşam ateşin, 

Ve kararmasın çocuk, 

Gözlerinde parıldayan sevgi Işığın, 

      Ve gülmeyi unutma! 

      Nerede oludan ol çocuk 

      Evde, okulda, sokakta, 

      Dağlarda, Zindanda, Dar ağacında...

      Ve kurumasın sakın çocuk

      Yüreğinden taşıp

      Derya  ile buluşan ırmakların...', 'Yaşam dediğin nedir ki çocuk... Bilmeksizin bakan iki gözle başlar. Ve yenek felek tokadı ardından,  Merhabayla konuk olursun YAŞAM''a çocuk....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/merhaba-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece-2', 'gece-2-fahrettin-ozdemir-5bjzj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sessiz çığlık gece

Başıboş zamanlarımda

Satır dolusu bağırdığım

Bir yaldızlı kılıf duygulara

Kimsesiz zamanlarımda

Pervasızca büründüğüm.', 'Bir sessiz çığlık gece Başıboş zamanlarımda Satır dolusu bağırdığım Bir yaldızlı kılıf duygulara Kimsesiz zamanlarımda Pervasızca büründüğüm...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece-3', 'gece-3-fahrettin-ozdemir-nljma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceyi ben çizerim

Hergün tekrar tekrar

Bir iki yıldız serpiştiririm gökyüzüne

Silerim tüm renkleri

Bir tek siyah kalır

Sonra da oturup seyrederim

Her yana gerdiğim siyah örtüyü

Uyuturum herkesi

Bir ben uyumam

Kucağımda bir avuç hüzün

Yarısını uyumayanlara dağıtırım

Yarısı ben de kalır

Sonra karanlıklardan çıkıp

Baş ucuna gelirim

Bakarım ki sen uyumuşsun

Bir öpücük kondurup yanağına

Yine karanlıklara dalarım

Sabah kalktığında

Sen düşünedur

Beni kim öptü diye 

Ben elimde kara kalemim

Diğer geceyi beklerim.', 'Geceyi ben çizerim Hergün tekrar tekrar Bir iki yıldız serpiştiririm gökyüzüne Silerim tüm renkleri Bir tek siyah kalır Sonra da oturup seyr...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gece-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O, Ben Değilim', 'o-ben-degilim-yuksel-aytug-cq4bt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısında

uykumun en tatlı anında

dürter, uyandırır beni

-Haydi tam vaktidir! 

Oysa tan vaktidir

hiç tınmaz, aldırmaz

bir çizgi gözlerim, 

kör - mahmur, açılmaz.

Tutuşturup elime kalemi

ne varsa aşka - ölüme dair

yazdırır, dikte ettirir

içimdeki gizli şair.

Ben bakarım, O görür.

Ben dinlerim, O duyar.

Ruhum uykudayken derin

sırtında geceden bir pelerin

köşe - bucak, diyar diyar

keşfindedir şiir ülkesinin.

Kimi gün yanıbaşımda

bazen bir köşebaşında

uzatır önüme kağıdı: 

-Haydi, geldi zamanı! 

Duygular zembereğinden boşalır

ihtiras, hüzün, vesair

yazdırır, dikte ettirir

içimdeki gizli şair.', 'Gecenin bir yarısında uykumun en tatlı anında dürter, uyandırır beni -Haydi tam vaktidir!  Oysa tan vaktidir hiç tınmaz, aldırmaz bir çizgi ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aytuğ']::text[], 8.5, '{"poet":"Yüksel Aytuğ","poet_slug":"yuksel-aytug","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/o-ben-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sende', 'ben-sende-abdullah-dogann-mes06', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sende gerçek beni buldum.

Sende gözyaşımı, 

Sende gerçek acımı, 

Sende aşkımı, 

           güzelliği buldum.

Ama anladım ki, 

Hepsi anlam ötesi

Gözyaşım denizlere, 

Acım hayata.

Güzellik dağ çiçeklerine, 

Aşkım zamana karışmış...

Meğer ben kendimi hiç tanımamışım...

Bir gün gelecek.

O kara gözlerin benim için bakacak

O tatlı sözlerin yalnız beni anlatacak.

Sen hep benmi düşünecek

           ben de seni...

Birbirimiz için yaşayacak...

Ama gün o gün sevdim...

İkimizde toprak olacak, 

Ağaç olup meyve vereceğiz

Gökyüzüne inandına yol alacağız...', 'Ben sende gerçek beni buldum. Sende gözyaşımı,  Sende gerçek acımı,  Sende aşkımı,             güzelliği buldum. Ama anladım ki,  Hepsi anla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hücre', 'hucre-abdullah-dogann-hg9g3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık gece soğuk yalnızlık 

Dağbaşarı gibi buz yürek

Bir tek isyan ateşi

Geriye kalan UMUT...

Yitirilmeyecek olan hep yeşerecek

İsyan, Ateş, Sevda, Kutsallık

Dalga dalga çoğalıp varılacak

             AYDINLIĞA...

Dünya büyük bir hücre 

İçinde ihanetin soğukluğu

İlişkiler yoz - karanlık

Hücremde bir yürek güvercin

             ASİ VE DİK...

Bulunduğun yeri çevirmelisin cennete, 

Cenneti yaşamalısın olduğun yerde.

Gelişmeli, çoğaltmalısın

             SEVGİNLE...

Sevginle var edip, 

Yol olmalısın.

Zılgıt olmalısın dağda çınlayan.

Ağıt olmalısın

             YÜREK kanatan.', 'Karanlık gece soğuk yalnızlık  Dağbaşarı gibi buz yürek Bir tek isyan ateşi Geriye kalan UMUT... Yitirilmeyecek olan hep yeşerecek İsyan, At...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hucre-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsan', 'olsan-yuksel-aytug-ys9ea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevda bulutu olsan

Kopup gelsen üzerime

Çözülsen damla damla

Yağsan çorak yüreğime...

Bir bozuk saat olsan

Hep ''o anı'' göstersen

Her akşam ufkumda batıp, 

Her sabah güneşle doğsan...

Bir deniz feneri olsan

Yol göstersen umuduma

Göz kırpıp her çakışında

Ruh versen vücuduma...

Bir kırık taş plak olsan

Hep takılsan hayatıma

Dinlerdim usanmadan

Şarkı olsan kulağıma...', 'Bir sevda bulutu olsan Kopup gelsen üzerime Çözülsen damla damla Yağsan çorak yüreğime... Bir bozuk saat olsan Hep ''o anı'' göstersen Her akş...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aytuğ']::text[], 8.5, '{"poet":"Yüksel Aytuğ","poet_slug":"yuksel-aytug","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimsin', 'benimsin-abdullah-dogann-esxar', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimden silinmiş

Tüm sevda sözleri, 

Ruhum boşalıp, 

Yanlız senle dolmuş.

   

Yüreğim Sen.

Sevgin varlığında.

Yalnızlığın.

Sıkı sarıl bana

Belki olmaz bir daha.

    YAŞAM ve

Yeniden varoluş

Yeniden Sen

Tut kendini

Unutma ben senim

Tuttuğum ben -im-sin..

KAVAĞIM VE YALNIZLIK 

Seğuk hücremde, 

Yalnızlığım Sen.

Karşımda küçük pencere.

İnceden bir ışık

Herşeye inat kavak

Yaprak yaprak...

Günün soğukluğunda

Rüzgara karşı

Kar tanelerine dost

Sana mı bilmem? 

Beyazlar giyinip

Gelin misali, dimdik karşımda.

Bir kacvak rüzgara karşı

Eğilir ama kırılmaz

             Yaprak yaprak

Toprak kökleri sımsıkı

Sevdiğini bırakmayan, 

Tarihteki sevdalılar gibi

                 

             Derin bağları...

Dalları göğe güneşe 

Yaprakları milyonlarca el

Sana açılmış, 

Seni sarmalamak ister gibi...

Arada demir parmaklık, gardiyan.

Sarıldım yüreğimden, 

Biz görmeden de sevenlerdeniz.

Hissettin mi kavak? 

Hissettin mi yanlızlığımı, 

Yüreğimde gizil olanı? 

Anamın sevgisi, 

Anamın bensizliğini

Yüreğimdeki sıcaklığını, 

Beni sen de gördün mü kavak? 

Üzerimden geçiyor taşıtlar

İnsan ayakları, 

Seni Seyrediyor kavak

Sesini hayal ederek...

Beni ısıtan, 

Beni saran, 

Küçük hücre

Dar pencere

Direngen kacak

             Ve sen

             Ve ardından 

             Yalnızlık...

Karşımda sen

Güneşten mi kopmuştun? 

Yüreğimden mi? 

Yanlızlığım, 

Gözyaşları...

Kavak dalgalanıyor

Rüzgara nazlı - nazlı

Üşüyorum, 

Sana ulaşamadım.

Kavağım, 

Derin Yanlızlığım.

Karanlık gece

Yıldızlar

Bırakılmışlığım...

İhanet 

Ölüm.

Sensiz hançer gibi

Donduruyor yalnızlığın

Yalnızlığım...', 'Yüreğimden silinmiş Tüm sevda sözleri,  Ruhum boşalıp,  Yanlız senle dolmuş.     Yüreğim Sen. Sevgin varlığında. Yalnızlığın. Sıkı sarıl ban...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Doğann']::text[], 8.5, '{"poet":"Abdullah Doğann","poet_slug":"abdullah-dogann","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/benimsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Meşgale', 'zor-mesgale-fahrettin-ozdemir-f25no', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok meşgulüm çok! 

Uykusuz gözlerim, 

Yorgun bedenim, 

Mürekkep mavisi ellerim

Düşünceler girdabında, 

Kaybolmuş aklım.

Ama işim uzun; 

Önümde boş sayfalar, 

Seni işliyorum, 

Sabahlara kadar.

Bıkmadan usanmadan, 

Yeter artık demeden.

Çok zor işim çok! 

Seni yazmak kolay

Ama iş

İkimizi yan yana koymaya gelince, 

Kaybediyorum, 

Tüm kelimeleri

Her şeye rağmen, 

Şundan da şüphen olmasın; 

Çok seviyorum seni çok! 

Sadece, 

Bir iki değersiz kelimeye

Sığdırabilecegim kadar küçük, 

İki şiirde tüketebileceğim kadar, 

Ucuz bir aşkla değil.', 'Çok meşgulüm çok!  Uykusuz gözlerim,  Yorgun bedenim,  Mürekkep mavisi ellerim Düşünceler girdabında,  Kaybolmuş aklım. Ama işim uzun;  Önüm...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/zor-mesgale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-fahrettin-ozdemir-tv8vo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cümle alem kendince söz söylemiş

Gel sen yalan söze gitme cananım 

Hüsnü aşkın beni tar''mar eylemiş

Gel sen bari cefa etme cananım

Ben sana günü geceyi vermişim

Yıldızları ayağına sermişim

Sensin uğraşım sen benim tek işim

Gel beni yabana atma cananım

Garibi dertli söyleten hazandır

Çekerim ben bilinmez ne zamandır

Dert bana gelir banadır hep kahır

Derdime bir de sen katma cananım.', 'Cümle alem kendince söz söylemiş Gel sen yalan söze gitme cananım  Hüsnü aşkın beni tar''mar eylemiş Gel sen bari cefa etme cananım Ben sana ...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Özdemir']::text[], 8.5, '{"poet":"Fahrettin Özdemir","poet_slug":"fahrettin-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hazan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş ve Sen', 'gunes-ve-sen-bilge-kaan-kantek-o7jss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir seni sevdim, 

Birde batan güneşi

Biriniz günümü, 

Biriniz gönlümü

Önce aydınlattınız, 

Sonra yok olup gittiniz...', 'Bir seni sevdim,  Birde batan güneşi Biriniz günümü,  Biriniz gönlümü Önce aydınlattınız,  Sonra yok olup gittiniz......', ARRAY['Türk Edebiyatı','Şiir','Bilge Kaan Kantek']::text[], 8.5, '{"poet":"Bilge Kaan Kantek","poet_slug":"bilge-kaan-kantek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunes-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen çiçeği', 'kardelen-cicegi-salih-ozalasan-ngglj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda masalı yazmıştım ya hani

Oynuyorduk ben prens sende prensesi

Ayarlanmıştı hikayeninin mutlu sonla bitmesi

Zor olmadı hikayeden gerçeğe dönmesi

Zor ama gerçekler acıydı çünki

İnsanın gerekiyor haddini bilmesi

Sen alplerde bir kardelen çiçeği

Bense sadece bir hayal prensi

Sen kimsenin erişemeyeceği birisi

Bense deli dolu bir serseri

İnsan serseri de olsa

Yeri geldiğinde haddini bilmeli

Sana sevdam bitmedi bitmeyecek bilki

Ama düşündümki artık Salih gitmeli

Bu hikayenin sonu yoktu nasılsa

Küstah kalem de artık haddini bilmeli

Sen hiç solma alplerin kardelen çiçeği

Karların erimesin hepcanlı tutsun seni

Arada sırada hatırlarsın belki beni

Tanrı şahit çok seviyor seni bu sonserseri

Y.Tar.30-10-2002 Saat 12.40', 'Bir sevda masalı yazmıştım ya hani Oynuyorduk ben prens sende prensesi Ayarlanmıştı hikayeninin mutlu sonla bitmesi Zor olmadı hikayeden ger...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kardelen-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır kalemi', 'kir-kalemi-salih-ozalasan-bu3ni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öylesine kaptırmışımki kendimi

Benim Dünya''m sandığım bir hayal alemi

Dev aynasında bir şey sanmışım kendimi

Bulunmaz hint kumaşı misali

Bugün birde normal aynada 

Görmek istedim nedense kendimi

İyiki bakmışım, oradaki serseri

Nasıl derler işte alâlade biri

Sıradan bir vatandaş

Yok ne tatlı dili, ne sivri kalemi

Alıp kıracaktımya biri tuttu sanki elimi

İkisinin ortasında durduğumda

Gördümki ikimizde taşıyoruz aynı bedeni

Hata bende aynalar değilmiş nedeni

Öylesine kaptırmışımki kendimi

Sanırım uyanma vakti geldi değilmi

Sen kimsin nesin, kim taksın seni

Sanmaki birileri asla unutmaz seni

Sen otur köyünde, kır o küstah kalemi

Y.tar.30-10-2002 Saat 8.50', 'Öylesine kaptırmışımki kendimi Benim Dünya''m sandığım bir hayal alemi Dev aynasında bir şey sanmışım kendimi Bulunmaz hint kumaşı misali Bug...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kir-kalemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Freud Juice', 'freud-juice-kucuk-i-skender-wa5t6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kahverenginin derisi soyulurdu

sokulurdu mutedil bir gülümsemeyle romans

şairler aşkı bir günde uyur buldular

kalıntılar arasında kurşunlanan ordu

ben yalnızca, hüzünden bir pardösü, istedim

kim bilir yalnızlık bitince artık ne başlayacak

ve kim bilir en büyük sevdalar kimler içindi

ve biz ki dünyanın tetikleri, 

bir yer vardı  bir yer vardı şimdi hatırlayamadığım

hani, insanların cümbür cemaat gelip

ölümle alay ederek tek başlarına gittikleri! 

bir cinnet yaşanır da

ardında ılık bir orgazm bırakır ya, 

orda etini, sütünü, rengini aşarak

uzar uzaklaşır büyür junior sardunya! 

oysa ben oyuncaklarıma acıyı çoktan öğrettim

anlattım onlara, hesse''in romantik ölü gençlerini

ben oyuncaklarımı hiç öpmedim

hep onlar sarıldılar bana...kim bilir

yalnızlık bitince artık ne başlayacak

kim bilir neyi tanımlayacak hiskara''mızın örttüğü gece

ölüm! öyle uygun gördü

uydumuz olan şeytan

onu kerhaneye götürmedik diye bize küstü!', 'kahverenginin derisi soyulurdu sokulurdu mutedil bir gülümsemeyle romans şairler aşkı bir günde uyur buldular kalıntılar arasında kurşunlana...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/freud-juice-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-bedirhan-gokce-e6lmi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bildik bir oyundu bu oynadığımız, 

Bir daha da oynamak istemiyorum.

Kazanan ben olsam da her oyun sonu, 

Bin kez ebe sen olsan istemiyorum...

Bir yanı yitik hep her yanımızın, 

Gözlerimiz bile bak, yalan söylüyor.

Rengi aynı olsa da her damlamızın

Kanımda tek kırmızı istemiyorum...

Miskette senin olsun, toplarda, ip de

Hem bizim mahalleli değilsin artık.

Oyuncaklar da sende, git oyna işte, 

Ben seninle oynamak istemiyorum...

Oyundaki kuralı bilmiyormuşum.

İlk defa oynamıştım, nerden bileyim? 

Bir daha deneyecek güçüm yok artık, 

Çek git artık buradan istemiyorum...

Bir gün bizde büyürüz, süt içmeyiz ki

Bir kere ağzı yanan yoğurdu netsin? 

Sapan taşları bir bir gönlümü deldi, 

Hayata küsmüşüm ben oyunu  batsın.

Artık ben oyunları hiç sevmiyorum, 

Kimseyle de oynamak istemiyorum...', 'Bildik bir oyundu bu oynadığımız,  Bir daha da oynamak istemiyorum. Kazanan ben olsam da her oyun sonu,  Bin kez ebe sen olsan istemiyorum.....', ARRAY['Türk Edebiyatı','Şiir','Bedirhan Gökçe']::text[], 8.5, '{"poet":"Bedirhan Gökçe","poet_slug":"bedirhan-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyun-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-bedirhan-gokce-o3fhk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl kar yağdı bugün, gece sabaha karşı, 

Ortalık bembeyazdı, sanki bir gelin gibi.

Tane tane döküldü, göklerin sevda marşı, 

Günahtan arındırdı, tüm günahkar yüzleri...

Yüzünde güller açtı kar yağınca herkesin, 

İlk kez böyle günahsız, ilk kez böyle neşeli.

Çocuklar gibi gülşen, çocuklar gibi şen

Gökten armağan gibi döküldü her tanesi...

Sokak lambalarından, süzüldü tane tane

Usul usul indiler bir birine değmeden.

Melekler indirirmiş her bir kar tanesi, 

Annem öyle derdi de inanmazdım küçükken.

Bir iken bin oldular, on binlere karıştı, 

Çoğaldı da yerden bir karış açtı.

İnsanlar döküldüler yollara birer birer, 

Değen her ayak izi bir günah gibi kaldı...

Allah kar gibi yağdı kullarının üstüne, 

Temizledi akladı, bembeyaz bir kuş gibi.

Her birimiz yıkandı, katran katran üstüne, 

Bakamaz olmuştuk biz aynalara gün gibi.

İnsanlar kötü artık, zaman hiç değişmedi, 

Geçen zaman ne yapsın, biz ettik kendimize.

Bu karda yağmasaydı halimiz ne olurdu? 

Allah yine acıdı, bak yetişti bizlere...

Kar da bembeyaz yağar, anamızın sütü de

Gelinlik de beyazdır, giydiğimiz kefen de, 

Birinde ağlarız biz diğerinde güleriz, 

Beyazdan ak beyazı, buyurun sıyırın işte...', 'Nasıl kar yağdı bugün, gece sabaha karşı,  Ortalık bembeyazdı, sanki bir gelin gibi. Tane tane döküldü, göklerin sevda marşı,  Günahtan arın...', ARRAY['Türk Edebiyatı','Şiir','Bedirhan Gökçe']::text[], 8.5, '{"poet":"Bedirhan Gökçe","poet_slug":"bedirhan-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilin Yalan Söylüyor', 'dilin-yalan-soyluyor-bedirhan-gokce-xcoiv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tohumdun yüreğimde fidan oldun büyüdün, 

Ağaç idin bağımda, çınar oldun yürüdün.

Nasıl söküldün öyle, çatır çatır içimden, 

Köklerin yüreğimde kan revan oldu birden.

Çalı çırpı bıraktın giderken yüreğimde, 

Hepsi bir kıymık gibi beynimin her yerinde.

Dilin ne derse desin, gözün öyle demiyor, 

Seni sevmedim derken, dilin yalan söylüyor.

Burası Ulus parkı, karşımız Anadolu, 

Gönlümün öbür yanı ondan böyle sır dolu.

Yalnızım bu şehirde, hem de yapayanlızım, 

Boğuluyorum gitme, şair olur bir yanım.

Yok böyle demiştim ben, yanlış anladım hemen, 

Bunun hepsi hikaye, baştan komiğiz zaten.

Kendimizi kandırdık, kargalar güler buna, 

Birde ciddiye aldık, karganın papuç damda.

Bu koca alemde biz, varla yok arasıyız, 

Olmasak da olurdu, varsak yaşamalıyız.

Olmayacak duaya amin demeyelim biz, 

Herkes kendi yoluna biz hep böyle gideriz...', 'Tohumdun yüreğimde fidan oldun büyüdün,  Ağaç idin bağımda, çınar oldun yürüdün. Nasıl söküldün öyle, çatır çatır içimden,  Köklerin yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Bedirhan Gökçe']::text[], 8.5, '{"poet":"Bedirhan Gökçe","poet_slug":"bedirhan-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dilin-yalan-soyluyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-bedirhan-gokce-zurd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Memleket havalarından bir haber ver, 

Eylül yağmuru nasıl düşer toprağa? 

Kemah’ın kapalı dar yollarında

Hangi kuş hatıra çizdi dal uçlarına? 

Yanıp sönen mavi ışıklarla kaybolan Yusuf

Geri döndü mü yurduna? 

Ya Viranşehirli Yakup, Çaykaralı Musa? 

Onlarda döndü mü yurduna? ...

Hani sen; 

Aşkı bir üveyikten satın almıştın Sadri.

Ne oldu ona? 

Bıçak kesmez oldu ağzını...

Susar oldun, yazmaz oldun daha...

Oysa yüreğimizi koymuştuk ortaya.

Hani, taşırdı be usta! 

Bak yine bir Eylül havası var Sadri, 

İkibin’e doğru 97 Mart’ında.

O gün doğan İsmail bugün delikanlı çağında

İlkbaharda sonbahar, bu nedir usta? 

Maltepe cigarasının adı mı var bugün? 

Üç bardak çayın hatırımı kaldı? 

Tornacının yanında çıraktı dayın, 

O günlerden yüzünde eser mi kaldı? 

Gel yine bir gurbet türküsü uçuralım.

Munzur’dan İstanbul’a

Fırat’ın suyundan  bulgur aşına

Serin göze başından Eylül ayına.

Üç gurbet türküsü tutturalım

Dostluk adına...

Bilirsin sende de bende de

Eylül’ün acı bir tadı vardı.

Şiire Eylül dediysek

Elbet; 

Bir maksadı vardı.

Elbet', 'Memleket havalarından bir haber ver,  Eylül yağmuru nasıl düşer toprağa?  Kemah’ın kapalı dar yollarında Hangi kuş hatıra çizdi dal uçlarına...', ARRAY['Türk Edebiyatı','Şiir','Bedirhan Gökçe']::text[], 8.5, '{"poet":"Bedirhan Gökçe","poet_slug":"bedirhan-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/eylul-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-bedirhan-gokce-p0xff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gideceğim diyorsun

Gitme be Ali gitme.

Bu gidiş bitirir tüketir seni, 

Hırsla kalkan zararla oturur Ali.

Gel lanet et şeytana gitme, 

Gitme be ali

Biz sahil kahvelerin

Romantik havasıyla, 

Otantik havasıyla sevdik.

Tavşan kanı çayı, 

Titreyen elleriyle sunan

İhtiyar balıkçının

Gülümseyen yüzüyle sevdik.

Sen gideceğim diyorsun, 

Gitme be Ali, 

Hayallerimiz var, 

Geleceğimiz  var, 

Dualarımız var.

O kızı alacağız Ali, 

Hem de istediğin

Bir “ebruli akşamda”, 

Sarı saçlarına Ankara’yı takıp

Ver elini İstanbul...

Yine gideceğiz 

O sahil kahvesine.

Tavşan kanında çay, 

Yosun tadında köy.

Çaydanlıkta demimiz muhabbet, 

Şekerimiz sohbetin olacak.

Sonra ijtiyar balıkçı gelecek, 

Oturtup ihtiyarı, ona çay ikram edeceğiz.

Ardından uzaklara dalacak gözleri, 

Ve hazin hikayesini anlatacak.

Kim bilir belki de

Hikayesi sana benzeyecek, 

Sonu “yanlıştı” diye bilecek...

Gitme be Ali gitme.

Bak bana şiir yazdırdın.

Gel yine hayallere dalalım, 

Düşüp sokaklara, sürüyelim Ankara’yı.

Tamam mı Ali, tamam mı? 

At şu paltoyu, 

Çaylar iki oldu Kerim! 

Çaylar iki oldu.

          Çankaya 1996', 'Gideceğim diyorsun Gitme be Ali gitme. Bu gidiş bitirir tüketir seni,  Hırsla kalkan zararla oturur Ali. Gel lanet et şeytana gitme,  Gitme ...', ARRAY['Türk Edebiyatı','Şiir','Bedirhan Gökçe']::text[], 8.5, '{"poet":"Bedirhan Gökçe","poet_slug":"bedirhan-gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gitme-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylan Gülüşlü Çingene', 'ceylan-guluslu-cingene-nuri-can-j6ldt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dermansız bir hasreti yükleyip yüreğine kayboldun

yazılmamış bir şiirin dizeleriydi dilinde aşk biliyorum

yalancı, yapay sevdalar harcın değildi senin

ah! karanfil ışığı, aşkın hilesiz yanı, çingene kız

neydi ki yaşın senin daha

sarhoş masalarında gezdirirlerdi kucak kucak

tamamlanmamış bir şiirin dizeleri gibi

gözyaşların dizilirdi yanaklarına her gece

sıra sıra… 

düşler ki, tek avuntundu

bir tek düşlere tutunurdun ceylan gülüşlünle

bilemezdinki, düşleri de yakarlar gün olur

şerefin beş para etmediği yerlerde…

kirli sularla yıkansa da esmer tenin

içkili nefeslerde saçların taransa da

bilirdim yüreğin en lekesizdi senin

vicdanların kirlendiği yerde doğmaktı tek suçun

ar, haya erbabı geçinip

bir ekmek parasına, 

körpecik dudaklarında şarap içenlerin olduğu yerde

üşürdün hep o küçücük pencerende bilirdim

dalıp dalıp giderdin uzaklara

gökyüzüne yazardın duygularını 

yıldızlarla konuşurdun her gece 

kimse bilmezdi

ağlardın şiir olur dökülürdü gözyaşların

yoksul çocukların donarak öldüğü gecekondularda

ısınmak için düşlerini yakardın… 

sahipsiz bir kedi kadar kimsesizdin ortalarda

yüreğini ısıtan ne bir kucak olurdu

ne de saçlarını okşayan şefkatli bir el

her gören tekmelerdi seni…

“iyi insanlar yok mu? '' derdin bu dünyada? 

bir tek sen bana iyi davranıyorsun” 

alnıma bir öpücük kondurur kaçardın

bilirdim hor görürlerdi seni, 

kimsesiz bir çingeneydin herkesin gözünde 

oysa sen dünyanın en güzel ceylanıydın

dünyanın en güzel kalpli kızı gönlümde

bir ben bilirdim içindeki güzelliği

bir de gecelerde göz kırpan yıldızlar

dünyayı yakmak isterdim dokunduklarında sana

yetmezdi gücüm, kahrolurdum

gözyaşların kor olur yakardı içimi

her gece pencerene bir gül bırakırdım senin için

ve gözyaşlarına bir mendil... 

bazen oturup ağlardım senin yerine 

senden habersiz

.../

yıllar geçip gitti habersiz, kayboldu izin

yaşım elliydi en son karşılaştığımızda 

tanıdın beni, ellerime sarılıp öptün

iki damla yaş yuvarlandı gözlerinde

yüreğimin ortasına düştü, üşüdüm.

utandım, önüme eğdim başımı

nasıl bakardım yüzüne senin

namussuzların yüreğini kirlettiği yerde

ah ceylan bakışlı çingene kız…

Nuri CAN', 'Dermansız bir hasreti yükleyip yüreğine kayboldun yazılmamış bir şiirin dizeleriydi dilinde aşk biliyorum yalancı, yapay sevdalar harcın değ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ceylan-guluslu-cingene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Sevda Masalı', 'eski-bir-sevda-masali-nuri-can-3cmnk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‘’Ölüm  asude  bahar  ülkesidir  bir  rinde

      Gönlü  her  yerde  buhurdan  gibi  yıllarca  tüter

          Ve  serin  serviler  altında  kalan  kabrinde

              Her  seher  bir  gül  açar, her  gece  bülbül  öter’’

                                                                              Beyatlı

  Menekşe  rengi  bir  çiçekti  sevdiğim  kız

Anadolu  yaylalarında  karanfil  kokan

Yanaklarında  güneşin  gül  öpücükleri

Dudaklarında  hayatın  nazlı  gülücükleri

Pınarlara  her  akşam  aşk  masalları  anlatan

Erguvan  rengi  bir  çiçekti  sevdiğim  kız

Munzur’un  eteklerinde  nergiz  kokan

Bakışı  ayışığı  yüklü  bir  ceylandı

Sevda  ve  gül  işlerdi  yüreklere

İpek  saçlarında  çayır  çiçekleri

Esmer  alnında  duygu  gelincikleri

Her  gece  yıldızları  alıp  koynuna  yatan

Bende  sevmiştim  ah  deli  gönlüm  bende

Hasret  rengi  bir  çiçekti  sevdiğim  kız

Gözlerinde  dağların  ilkyaz  gülücükleri

Dilinde  sevdanın  içli  sözcükleri

Saçlarında  bahar  yelleri  eserdi

Yaşamak  bir   şarkıya  benzerdi  dudaklarında

Dünyanın  bütün  dillerini  konuşan

Bende  sevmiştim  ah  ömrüm  bende

Kar  rengi  bir   çiçekti  sevdiğim  kız

Nefesinde  dağgüllerinin  kokuları

Kalbinde  sevdanın  gizli  korkuları

Üşüyen  yüreklere  beyaz  çiçekler  sunardı  her  gece

Türkü  türkü  seher  yeliydi  yüzü

Şiir  şiir  ay  güzeli

Doğanın  bütün  renklerine  yakışan

Bende  sevmiştim  ah  dostlarım  bende

Hayat  rengi  bir  çiçekti  sevdiğim  kız

Hala  özlem  kokuyor  bir  köşesinde  anadolunun

Hala  sevda  kokuyor  uzaklarda  sesizlikler  içinde

Kimselerin  uğramadığı  bir  yerde

Yıldızlara  bakıp  üşüyor  her  gece

Şimdi  güller  gülümsemiyor  artık, uzak  dağbaşlarında

Cerenler  inmiyor  sulara

Derin  uykuya  dalmış  gözlerinde sevdiğimin

Nergizler  uyanmıyor  sabahlara

Sarmıyor  yaşamı  maviler

Sonsuz  bir  hüzün  gibi  devrildi  düştü  gecelere

Bir  hüzünki  ne  yazgılara  sığar  ne  yıldızlara...

Ya  ben  nasıl  ağlamam  dostlarım  ya  ben  nasıl...', '‘’Ölüm  asude  bahar  ülkesidir  bir  rinde       Gönlü  her  yerde  buhurdan  gibi  yıllarca  tüter           Ve  serin  serviler  altında ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/eski-bir-sevda-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Yanım Güvercin', 'sol-yanim-guvercin-nuri-can-py37e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim  ömrüm  kimsesiz  bir  çığlık

Kırık  bir  figan  akarsularda  sesim

Çağlayanlara  vurur  yankısı

Mavisi  yağmalanmış  bir  gökyüzüyüm

Karanlığın  ortasında

Kendi  içinde  taşıyan  aydınlığını

Örselenmiş  çocuk  gözleriyim

Ömrümün  deltasında  yapayalnız

Sol  yanım   güvercin,  uçurumları  emzirir

Sağ  yanım  karanlık  kakülleri  kan

Ah  kalbim

Ah duyarlı  yanım

Ortak  oynanan  bir  oyunmu  hayat

Herkesin  kendisini  oynadığı

Yalnız  bir  tregadyayım  ben

Maskesiz  seyircisiz

Ve  her  gece  uykuya  yatmış  bir  dağ  gibi  kederli

Kirpiklerini  sulara  dökmüş  bir  çiçeğim

Silahsızım  kuşları  vurulmuş  bir  gökyüzünde

Bir  kar  çölü  ıssızlığıyım

Her  gece  bir  ateşdağına  tırmanıyorum

Bir  kahır  dağına

Hiç  bir  yol  çıkmıyor  umuda

Kalbimi  bir  buzdağının  ortasına  koyup  ve  uyuyorum

Bir  başka  bahara  açmak  için  çiçeklerimi

Denizi  olanlar  mavi  gözlüdür  belki

Ben   kavruk  bir  çöl  gibi  yangınım

Bir  doğulu  kadar  esmer  ve  tedirgin

Aşiretlerin  terkettiği  örenlere  benziyor 

Kaygılardaki yüzüm

Yollar  kar,  dağlar  karanfil

Göz  göz  oldu  yaralarım  bağlayamam

Gel  yürek  sıcağı  bir  ezgiyle  ört üstümü

                                                         ‘ örtki ölem’

*’Erzurum  ağzı’', 'Benim  ömrüm  kimsesiz  bir  çığlık Kırık  bir  figan  akarsularda  sesim Çağlayanlara  vurur  yankısı Mavisi  yağmalanmış  bir  gökyüzüyüm ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sol-yanim-guvercin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susku', 'susku-nuri-can-76fj2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susku

         bir  çığlık

                    yürek  içre

incinmiş  bir  sözcük  belki

hasret  yazılı  bir  şehirde

sızı

       sızı

            diken 

                      diken

                              biriken

                                  dil  üzre

susku

bir  şarkı  belki

sessiz  bir tını

kopuk  bir  keman  telinde

 inim

        inim 

             inleyen

 ilmek 

           ilmek

                  imleyen

                             yalnızlığı

                                        yel üzre 

susku

hüzün  soluklu  bir  güz

incelikleri  kanayan                   

           göğüne  küs  yıldız

son  intiharını  kusarken  aşk

                                          gül  üzre

bütün  imgeleri kırık  ve  yaralıdır

dudağında  gizlendiğimiz

                           şiir  gözlü  kız

ah  ben

acemi  ve  şaşkın

çok  geç  farkettim

bir ömrü  yana  yana  tükettiğini  aşkın

ve  sekerek  geçtiğini

iz

    iz

duman

         duman

                    kül  üzre

suya  küs  ateşe  barışkın', 'Susku          bir  çığlık                     yürek  içre incinmiş  bir  sözcük  belki hasret  yazılı  bir  şehirde sızı        sızı       ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/susku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havalan Güvercinim Havalan', 'havalan-guvercinim-havalan-nuri-can-czs4j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Havalan güvercinim havalan

siyahi  günlere kaldı kalan

suskunluğun ince çığlığı

yaralıyor geceyi

ölü yıldızların  koynunda gün

küller yağıyor umuduna bu şehrin

zor bir geçit yaşamak

boynu vuruldu ğöğün

ak köpüklü sesiyle bir nehir

kaygılar mırıldıyor sessizliğe

acılar çırpınıyor kirpiğinde sokakların

ateşe verildi  yürekler

duvarlara tırmanıyor ölüm

güvercinler yoruldu

son yolcusuda vuruldu direnişlerin

her gözde bir avuç şiir kaldı

her yürekte bir demet kor

düşlerin gizlendiği her tomurcuk

ihanet darbeleriyle parçalandı

yoldu saçlarını imgeler

şiirler  öksüz kaldı

korkular düştü balkonlardan

sevgiler yaralandı

havalan güvercinim havalan

siyahi günlere kaldı kalan', 'Havalan güvercinim havalan siyahi  günlere kaldı kalan suskunluğun ince çığlığı yaralıyor geceyi ölü yıldızların  koynunda gün küller yağıyo...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/havalan-guvercinim-havalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Gidiyorsam', 'eger-gidiyorsam-sair-reber-y6iq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer gidiyorsam şimdi

Bil ki hayatı sevdiğimdendir

Ve yaşamak istiyorsam delice hayatı

Denizleri sevdiğimden

Eğer seviyorsam denizleri

İçindeki güzelliklerdendir

Eğer anlıyorsam güzellikleri

Afrodite bağlıdır

Ve eğer gözlüyorsam Afrodit''i

Bil ki Mitolojiye inancımdan

Eğer gittiysem Mitolojiye kadar

Bil ki bu şiir tarihi de işlemiş', 'Eğer gidiyorsam şimdi Bil ki hayatı sevdiğimdendir Ve yaşamak istiyorsam delice hayatı Denizleri sevdiğimden Eğer seviyorsam denizleri İçind...', ARRAY['Türk Edebiyatı','Şiir','Şair Reber']::text[], 8.5, '{"poet":"Şair Reber","poet_slug":"sair-reber","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eger-gidiyorsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Kızıl Dünyada Kara bilinene', 'kendi-kizil-dunyada-kara-bilinene-sair-reber-ikcak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evet sana yazıyorum 

Sana ey dünyayı korkuta

Gerçekliği anlaşılmamış

Dünyalıca Kara Düş 

Sana 

Sana ve sana harcadığım 

Altı yıla bu şiir

Sen hüznümün KIZIL şiiri

Sen gözyaşımın KIZIL sıcağı

Sen ayazın KIZIL ateşi

Sen ne bir cisimsin

Ne de sana uymayan bir duygu

Ama hakikatin ta kendisi

1991-2002

Kim bilir kaç kişi yeminler bozmuştur

Ne savaşlar olmuştur 

Kaç kişi ölmüş kaç bebek doğmuştur

Ülkemde sen 1980''de sindin içine

Ya da sindirildin

Ama asla SİNDİRELLA olmadın

Ne de POLYANNA

Sen hep yürekte idin

Hala yürektesin

Ve yürekler güzelliğe hasret kalınca doğacaksın

Munzurdan EY KIZIL GÜNEŞ

12 yıl neler oldu

Artık vakti geldi

Ayrıl o gittiğin yerden

Anla artık beni

Geçmişteki günlerimiz hayal oldu

Gerçeğe döndür anla artık

Gel ve gözlerdeki yaşı sil

Gereksiz gidiş bitsin

Bu aşk bitmemeli

Doğ ve bit sevgililerin elinde Kızıl GÜL ol

KIZIL SEVDAM 

AŞK İÇİN HÜRRİYET İÇİN

MARX LENİN İÇİN

İRKİL VE KALK 

NAZIM GİBİ OL....', 'Evet sana yazıyorum  Sana ey dünyayı korkuta Gerçekliği anlaşılmamış Dünyalıca Kara Düş  Sana  Sana ve sana harcadığım  Altı yıla bu şiir Se...', ARRAY['Türk Edebiyatı','Şiir','Şair Reber']::text[], 8.5, '{"poet":"Şair Reber","poet_slug":"sair-reber","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kendi-kizil-dunyada-kara-bilinene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alevden tomurcuklar', 'alevden-tomurcuklar-nuri-can-2r4sz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğilip öpüyorum alnından 

gözlerinde uyuyan nazlı bir sabahı 

dudağımı yakıyor o gül ateşin / incecik 

bir defne dalında uzuyor kirpiklerin 

yüzünün aydınlığına ak güvercinler konuyor 

utanıyor saksılarda çiçekler 

bir dal kırılıyor / körpecik 

saatler akıp gidiyor 

bir ceylan iniyor sızının kıyılarına 

bütün ırmakların suyu çekiliyor 

ölüm kesiyor yolları / gencecik 

okşuyorum incitmeden 

yanağından süzülen damlacıkları 

utangaç bir mavi düşüyor gözlerinin içine 

boynunu büküyor yaşam 

yüreği parçalanıyor bakışı güvercin bir kızın 

bütün aynaları kırılıyor / sevincin 

hafiften bir rüzgar esiyor 

apansız ağıtlar düşüyor sesime 

korkunç ateşlere düşüyorum, uçurumlara 

alevden tomurcuklar patlıyor usumun gergefinde 

beyaz kefenlere sarılmış bir kar çölünde 

elimde çırılçıplak kalıyor yüreğim 

şimdi bir kıtada çocuklar güneşi öpüyor 

analar ağıt yakıyor başka bir  kıtada 

yüzümde çiçekleri solmuş bir bahçenin hüznü 

dalıp dalıp gidiyorum uzaklara 

 diyorum ki, yaşamak ancak bu kadar haklı olabilir 

ancak bu kadar güzel ah baharın sevdalı gülü 

çirkin bir ölüm kasırgasında kırılsada papatyalar 

sen ki, bırakıp nazlı bir baharda gül özlemlerini 

uçup gittin nazlı bir kuş gibi 

bir sonsuz maviyi çizip yüreklere 

zaman acısını işlerken hayatın güldikenine...

. 

Nuri Can 

www.nurican.com', 'Eğilip öpüyorum alnından  gözlerinde uyuyan nazlı bir sabahı  dudağımı yakıyor o gül ateşin / incecik  bir defne dalında uzuyor kirpiklerin ...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/alevden-tomurcuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeğin Kış Olduğunu Bilmezdim', 'gercegin-kis-oldugunu-bilmezdim-nuri-can-go4fz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün denizlerden uzak

bir coğrafyaydı büyüttüm gözlerimde

yıldızsız gecelere kanarken içim

bir anıydı büyüttüm

bir ayrılıktı, bir özlemdi

kırdım düş boyutlarını

uçan kuşlara öykündüm

her yaprağın düşüşünde

bir  dal  kırıldı  içimde

bir ağaç devrildi

bir orman kahroldu

oturup güz rüzgarlarına

ibrişim türküler yaktım

sazımın  telleri nazlıydı

üşüyen bir güldü sesim

bir sevdayı besteledim ömrünce

herkese aykırı kaldım

sevmenin suç olduğunu bilmezdim

nazlı  bahar  işlemeleriydi  yüreğimde  hayat

yıldız  gülümsemeleriydi  unutamadığım

saçlarımı  okşayan  ılık  bir  meltemdi  annemin  eli

kokusunu  özlediğim  bir çiçekti, uzanıpta  tutamadığım

sevgilerin kirletildiği bir dünyada

ömrümün bir hiç  olduğunu  bilmezdim

kar düşmüş yalnızlıklarda

ince sızı dostluklara sarıldım

sesim yel içinde yapraktı

aykırı denizlere aktı

hep düşlerde kaldım

imgelerde, renklerde

gerçeğin kış olduğunu bilmezdim', 'Bütün denizlerden uzak bir coğrafyaydı büyüttüm gözlerimde yıldızsız gecelere kanarken içim bir anıydı büyüttüm bir ayrılıktı, bir özlemdi k...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gercegin-kis-oldugunu-bilmezdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi umuda Uzansak Avutmuyor', 'hangi-umuda-uzansak-avutmuyor-nuri-can-ezwwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesine  dokunsam  sesim  kırılır

kirpiğine  dokunsam  kirpiğim

yaralı  bir  serçeyiz  incecik  dallarda

nereye  tutunsak  bir  yanı  kırık

bir  ince  gönül  sızısıdır  bizimkisi

bir  ince  aydın  duyarlılığı

sahte  gülücükler  ürkütür  yüreğimizi

pazarlıklı  dostluklar

ve  güzellikler  ki, 

yedeğimizde  kıyısız  bir  hıçkırık

bir  yanda  göğün  üşüyen  yıldızları

bir  yanda  umudun  sancıyan  sızıları

nehir  nehir  yalnızlıklar  akıyor  içimize

her  gece  bir  çocuk  alıp  başını  gidiyor

bir  çiçek  küsüyor  bahçesine  her  gece

mevsimler  bölüşmüyor  artık  sevdaları

hangi  hülyaya  uzansak  avutmuyor

bir  kanadı  kırık  gönül  kuşumuzun

ne  yana  vursak  ayrılık

kötü  zamanların  yitik  öyküsüdür  hayatımız

karanlık  her  sokakta  ışıklı  acılar  topluyoruz

sevgisizliğe  ağlarken  yaralarımızın  ortasında  bir  kent

kendi  yüreğimizin  depreminden  korkuyoruz

oysa  sevmektir  yalnız aydınlığımıza  yakışan

seherin  umut  veren  güzelliğini

bir  bahar  çiçeğinin  çiğini

tomurcuğunu  ayışığının

düşlerimize  dökmekte  ustayız  çünkü  içimizdekileri

sarssada  umudumuzun  derinliğini  karanlık', 'Sesine  dokunsam  sesim  kırılır kirpiğine  dokunsam  kirpiğim yaralı  bir  serçeyiz  incecik  dallarda nereye  tutunsak  bir  yanı  kırık b...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hangi-umuda-uzansak-avutmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yokum (proterst)', 'ben-yokum-proterst-nuri-can-aadb8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzellik bu denli ucuzsa 

ve bu denli çirkinse yaşamak 

nankörse emek 

çıkarsa her kapının anahtarı 

ben yokum 

ben yokum 

bir gecelik ilişkiler kadar değersizse aşk 

parayla ölçülüyorsa dostluklar 

ihanetler, savaşlar, karanlıklar üzmüyorsa 

ve utandırmıyorsa yoksulluklar 

ben yokum 

erdem bu denli küçükse 

ve bu denli büyükse yalanlar 

hayaller yoksa 

umutlar yoksa 

çiçek açmıyorsa sevda bahçeleri 

özlemi anlatmıyorsa karanfil 

ben yokum 

yaşam dediğiniz 

zamanı tüketmek 

maviyi kirletmek 

yiyip içip yan gelip geğirmekse 

ve küfretmekse sizden olmayana ana avrat

doğru dostum ben aykırıyım 

varsın sizin olsun

din, yalan, sahtekarlık

sizin olsun

marklar, arabalar, dolarlar 

konfor, lüks, şan, şöhret, mevki 

bana bir dilim şiir 

bir nebze sevgi yeter 

yeter 

bir içten gülüş 

bir tutam düş 

ve güneşin yedirengi 

Nuri CAN

1997 Calw Almanya', 'Güzellik bu denli ucuzsa  ve bu denli çirkinse yaşamak  nankörse emek  çıkarsa her kapının anahtarı  ben yokum  ben yokum  bir gecelik ilişk...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-yokum-proterst-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirler En Güzel Sevgilim Olsun', 'siirler-en-guzel-sevgilim-olsun-nuri-can-s8chl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sınırsız sevdim gökyüzünü

sevemedim tutsaklığı  bi-türlü

güvercinleri 

mavi

         göklerde

                       sevdim

beyaz beyaz uçarken

çiçekleri 

yeşil

      dallarda

                  derdim

nazlı nazlı açarken

oldum olası

ne bir saksım olsun istedim

ne bir kafesim

isterdimki, 

sevdalı  bir  rüzgar olsun

yaprakları  okşasın  sesim

isterdimki, 

yeryüzü çiçeklerin        

gökyüzü güvercinlerin  olsun

güneşin okşadığı her yer

özgürlük koksun

ve şiirler

en güzel sevgilim olsun', 'Sınırsız sevdim gökyüzünü sevemedim tutsaklığı  bi-türlü güvercinleri  mavi          göklerde                        sevdim beyaz beyaz uçar...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/siirler-en-guzel-sevgilim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nuri-can-p4i9d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitme! 

Figan düşer denizlere sular çekilir 

Yağmur yağmaz vahalardan kirpiklerime

Bir rüzgar hıçkırır tenhada, bir dal kırılır

Boynunu büker sabah kervanları, kelebekler ölür.

Gitme! 

Bir yıldız küser göğüne, içini çeker bir çocuk

Şaşırır yönünü rüzgarlar

Bütün pınarların suyu çekilir

Solar nazlı çiçekleri kalbimin, üzülürüm.

Gitme! 

Öksüz kalır içimdeki imge dağları

Saçlarını öpen seher yeli, çoban yıldızı 

Bir daha turnalar geçmez, bülbüller ötmez

Çiçekler açmaz bahçemde ah, gülüm! 

Gitme! 

Acılara mahkum olur yüreğim

Ardında fırtınalar kalır, ayrılıklar, anılar, yanlızlıklar

Boynu bükük aşklar, gözü yaşlı şarkılar

Alışamam yokluğuna, yokluğun ölüm.

Gitme! 

İçimdeki bütün vagonlar devrilir

Bir kar yağar istasyonlara, üşürüm.

Gitme! 

Kal, menevşeler açsın dağlarda

Sevince dönüşsün gökyüzü 

İki çığlık arasında bırakma beni ah gülüm 

Yokluğuna alışamam, yokluğun ölüm.

Gitme! 

Bütün ormanlar ateşe verilir

Kuşlar da gider bu kent de, ölürüm.', 'Gitme!  Figan düşer denizlere sular çekilir  Yağmur yağmaz vahalardan kirpiklerime Bir rüzgar hıçkırır tenhada, bir dal kırılır Boynunu büke...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gitme-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Ayışığımdır', 'gozlerin-ayisigimdir-nuri-can-2dfs6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anna  Frank’a

Ren’in  kirli  sularına  bıraktım  kaygılarımı

alıp  götürdü  dalga  dalga  tarihin  karanlık  dehlizlerine

tut elimden Anna Frank düşersen yalnız kalırım 

taşıyamaz yüreğimin  acısını bu köhne kaldırımlar

gözlerimde diken diken korku gölgesi

solgun bir gül  titremesi yüreğimde

feryadım  Amsterdam  sokaklarında  sarı  bir  yaprak

savrulur binlerce kilise  çanında hüzünsü

hangi kışlarda kaldı mutluluğum  baharımı   anımsamıyorum

hep acısını çektik ihanetlerin aldattı  bütün mevsimler

kesik kulağıyım Van Gogh’un  yaralı yarım tablosu

intiharımı ne yer bilir, ne gök,  ne de insanlar

aşklarki en güzel ölüm ve  ayrılıklarla  anlatılabilir

yarım  kalmış tablolar bitirilmemiş hatıralarla

düşersem elini ver, üşürsem yüreğini

ki, ömrünce ölü bir kadının dudaklarını öperek yaşadım

korkunç acısını  çektim  insanın  insana  ettiğinin

eğme  başını

kanar  içimdeki  yara

gözlerin ayışşığımdır güzelim Anna Frank

yıldızları kirlenmiş bir gecenin sayfalarında umutla  ışıyan

lığların örttüğü küs bir  bahçedir yüreğin

binlerce çiçeğin  içinde boğulduğu

eğme  başını

son  umudu   öpmeden  gülücüğün

ölüm  getirmeden  gençömrüne  ihanetler

eğme  başını

sen  ayışığıyla  yıkanmış  gökyüzünde

gecegözlü  güvercinimsin    güzelim  Anna  Frank

içinin kızıllığınca gül ve yangın

gelecek baharlara erteleyip tüm sevinçlerini

bir demet kızıl kor karanfille örttün yüreğinin üstünü

tüm hatıralarını ateşe  veriyorum, tüm acılarını

bağışla bu  masum kırğınlığımı dünyaya, bağışla', 'Anna  Frank’a Ren’in  kirli  sularına  bıraktım  kaygılarımı alıp  götürdü  dalga  dalga  tarihin  karanlık  dehlizlerine tut elimden Anna F...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gozlerin-ayisigimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Kalbine Düğümken', 'kalbim-kalbine-dugumken-nuri-can-xylt6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni nasıl unuturum

usul boylum

nasıl unuturum

deniz yeşili gözlerini

ipek sarısı saçlarını

kalbim kalbine düğümken

yaşamak bir türkü seninle

yediveren tomurcuk

gidersen, 

boynu bükük kalır bu şehir

ölür kahrından bu içli çocuk

yokluğuna nasıl alışırım

dudağın dudağıma mühürken', 'Seni nasıl unuturum usul boylum nasıl unuturum deniz yeşili gözlerini ipek sarısı saçlarını kalbim kalbine düğümken yaşamak bir türkü seninl...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalbim-kalbine-dugumken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışık Uyaklı Şiirler Düzenlenmemiş', 'karisik-uyakli-siirler-duzenlenmemis-nuri-can-59klu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Gül

Bilmem kimler kırmış nazlı dalını

kanıyor durmadan yüreğin ey gül

içli nağmelere vermiş ahını

dönüyor başında yaralı bülbül

pınarlar yas tutmuş akmıyor dere

gözyaşın dünyayı boğmuş kedere

yapraktan saçların dağılmış yere

rüzgarda inleyen incecik bir tül

gönüller virane puslanmış dağlar

bülbüller divane bozulmuş bağlar

sonbahar hıçkırır bahçivan ağlar

bahçeler tarumar örenler hep kül

sensiz yeşerir mi dalında ağaç? 

dostluk sana hasret, sevgi sana ac

gözyaşın kalplerde örülü bir taç

gülüşün dünyaya en kutsal ödül

ruhunu canından canıma veren

rengini kanından kanıma veren 

her bahar acını acıma veren

yeter bunca ağladığın artık gül



Elimde bir mendil kaldı

umudumu gurbet aldı

sevincimi hasret çaldı

gülmek ele, sevmek ele

isyan etmek bana kaldı

gitti ömür dönmez geri

gönül yurdum yangın yeri

ta doğduğum günden beri

garip boynum bükük kaldı

hazan vurdu viran bağlar

her yaprakta bir dal ağlar

ne halimi bir soran var

ne de derdim bilen kaldı 

dünya kahrı çeke çeke

gezdim boyun büke büke

gözyaşımı döke döke

elimde bir mendil kaldı

sarılmaya kırık kollar

kavuşmaya ırak yollar

ne sevdayı bilen kullar

ne uğrunda ölen kaldı



Eser daldan dala yel olur gider

Garipler gurbette yalnız kalınca

hasret oklarıyla yaralanınca

hazanlar hüsrana sevdalanınca

akar gözyaşları sel olur gider

ne arayan olur ne de bir soran

için için kanar kalbinde yaran

aramaz dostların usanır yaran

kardeş, bacı, oğul el olur gider

 başlarsa bir kez hazan mevsimi

kırar bellerini, kısar sesini

yitirirde kalbin son nefesini

eser daldan dala yel olur gider 

kalırsın köşende baharsız, yarsız

yıllar düşman olur, dostlar vefasız

inerse yastığa başın umarsız

düşer haldan hala del olur gider



Buzlara döndük

kırıldı kolumuz, tutmaz elimiz

küsmüş türkülere suskun dilimiz

koptu aramızda gönül telimiz

gayrı düzen tutmaz tellere döndük

ne yıllarda vefa, ne giden geldi

yaş kırkını geçti ömür eksildi

mevsim ayaz oldu ümit kesildi

yeşili tükenmiş yazlara döndük

direndik silinmez alın karamız

engellerle dolup taştı aramız

volkan volkan sızlar iken yaramız

kutupta eriyen buzlara döndük



Ova ayrı güzel, dağ ayrı güzel

Nereye bakarsan bir renk cümbüşü

ova ayrı güzel, dağ ayrı güzel

her dalın başında yeşil örtüsü

ağaç ayrı güzel. bağ ayrı güzel

güneş pırıl pırıl, bulutlar ap ak

kuşlar cıvıl cıvıl tasadan ırak

yüzünü yaşamın seyrine bırak

zaman ayrı güzel, çağ ayrı güzel

hayat güzel dostum gülenler için

yaşamın zevkini bölenler için

sevip, sevildiğin bilenler için

ana ayrı güzel, yar ayrı güzel



Kalbi kırık bir kuşum

Kalbi kırık bir kuşum

istemeden doğmuşum

sevgisiz bir dünyada 

severek yorulmuşum

sevgi benim ilacım

hem sevincim hem acım

yürekten bir sevgiye 

ölesiye muhtacım

candan bir seven olsa

canımı vereceğim

hep sevdalar peşinde

geçti ömrüm, gençliğim

arzular yağmur yağmur

özlem bulut buluttu

kime gönül verdiysem 

gönlümü taşa tuttu

ümitler gonca gonca

dal daldı yüreciğim

bir vefasız elinde

soldu gülüm. çiçeğim

türküler yaka yaka

korlara düştü gönlüm

yollara baka baka

yıllara küstü gönlüm





Dur gitme beni bekle

Ümitler yaprak yaprak 

sararıyor dallarda

güneş doğmuyor artık

gezdiğimiz yollarda

bütün emeller solmuş

bütün düşler yorulmuş

bütün yollar tutulmuş

kuş uçmuyor dağlarda

kaybolmuş bir erekle

tükenmiş bir yürekle

nereye gidiyorsun 

dur gitme beni bekle

çoştuk çoştuk durulduk

koştuk koştuk yorulduk

kalbimizden vurulduk

bak kaldık ayazlarda

oğul oğul bal idik

mutlulukla yar idik

filiz filiz dal idik

kuruduk sonbaharda

kaybolmuş bir erekle

tükenmiş bir yürekle

bir yere varamazsın 

dur gitme beni bekle





Çekilmez olur

yüklemiş derdini kervanı göçer

bilinmez yolları ne yana düşer

meyhane, derthane içer de içer

üfleti ayyaştan seçilmez olur

solar güller, hasbahçeler çöl olur

akar gözyaşları kanlı göl olur

kalbe ateş düşer hepsi kül olur

bağrını yakmıştan geçilmez olur

dertler dizi dizi, yol duman duman

mesken olur gayrı deryayı umman

kalır cihan içre garip, perişan

kahrı gurbet elin çekilmez olur





Halım mı  kaldı

Döküldü saçlarım göründü kelim

sılaya varacak halım mı kaldı

kırıldı kollarım büküldü belim

el atıp tutacak dalım mı kaldı

düşmüşüm gurbetin zalim ağına

kar yağar ömrümün sefil dağına

dalsamda hayalin ak ırmağına

deryada yüzecek salım mı kaldı

ciğerinden kurşun yemiş ceylanım

bir yanım yaralı, ağlar bir yanım 

karalar içinde geçti zamanım

üstüme giyecek alım mı kaldı

sargısız, merhemsiz azgın yarayım

yıllar oldu can ilimden ayrıyım

peteksiz, oğulsuz kalmış arıyım

dostlara verecek balım mı kaldı





Allemler dolusu kallemler yüklü

bir kervandı gelip geçti ömrümde

 allemler dolusu kallemler yüklü

her yükten bir kahır kaldı gönlümde 

ölümler  dolusu elemler yüklü

umudum çırpınan yaralı serçe

ihanet kalbime vurulan pençe

olmadı bir anım kuşkusuz geçe

kaygılar dolusu korkular yüklü

yer kısım kısım insan farklıdır

bilinmez kim haksız, kim haklıdır

herkesin kalbinde bir sır saklıdır

anılar dolusu ağrılar yüklü

bu dünya öyle bir zalim dünyaki

dümeni tersine dönüyor sanki

yüreğimde bir fırtına, bir harpki

sancılar dolusu acılar yüklü

gam yüküyle geçti ömrüm dünyada

yıkıldı köprüler kaldım arada

şeyda bülbül gibi düştüm feryada

feryatlar dolusu fiğanlar yüklü





Kadere lafım yok, Feleğe sözüm yok

 Alıp gittin ümitlerimi elimden

yıktın hüsran ettin hayallerimi

kaç eşiğe diz çöktüm,

kaç ihanet gördüm sevdiklerimden

kaç ihanet gömdüm şu dağlı sineme

kadere lafım yok, feleğe sözüm yok

ben bu ahları senden aldım 

dünya dünya

bir bahardı esip geçtin üzerimden

mutluluğumu alıp götürdün

ahlar yükselirken yaralı yüreğimden

hicran yaşlarını kalbime gömdün

dünya dünya

ya benide al götür gittiğin yöne

ya saadetimi bana geri getir

delirdim bu dertle ben döne döne

söyle benden istediğin nedir

dünya dünya

bir mutsuz adamım sitem ederim

sanadır bu kahrım kusar giderim

boynu bükük ara yerde bıraktın

fiğanla, firgatle feryat ederim

dünya dünya

Nuri CAN  73



Elvedâ Ey Şehir Sana Elvedâ

Hoşçakal ey şehir hoşça kal şimdi

acıya, kedere, sana elvedâ

üstüme simsiyah perdeler indi

elveda ey şehir sana elvedâ

hoşçakal sevdiğim hoşça kal şimdi.

yıllarca çektiğim bu yağmur dindi

gidiyorum işte bakmadan ardıma

elveda sevdiğim elveda şimdi.

hoşçakal sevdiğim duramam artık 

kedere boğulduğum bu şehirde

varsın ağlamasın ardımdan kimse

belki dönerim yine gün gelirde

hoşçakal karanlık geceler hoşça kal

hüzne boğulduğum şehir hoşçakal 

bir daha anma beni arama

kirpiğin değmesin yarama

susku mevsimi,dil mevsimi elvedâ 

hazan mevsimi, çöl mevsimi elvedâ 

nazlı gelincik, gül mevsimi elvedâ 

sevgiye, sevdaya,ey şehir sana elvedâ

Ardıma bakmadan gidiyorum işte

bir daha geçmeyeceğim bu sokaklardan

her köşede sessiz gözyaşımı bırakıyorum

bir odada gerçekleşmeyen düşlerimi

elvedâ ey şehir sana elvedâ

hoşçakal ey şehir hoşça kal şimdi

hoşçakal sevdiğim hoşça kal 

kedere boğulduğum bu şehirde 

duramam, duramam, duramam artık





Dalda solan yaprağa sor

Güller ile gülen benim

geyiklerle melen benim

yeller ile uçup giden

yağmur ile gelen benim

beni esen yellere sor

çoşan deli sellere sor

hazan vurmuş bahçelerde

boyun eğen güllere sor

kuşlar ile uçan benim

al güllerle açan benim

yollar ile yoldaş olup

yolculardan kaçan benim

dalda solan yaprağa sor

bağrı yanmış toprağa sor

gözyaşımda bulut bulut

sessiz akan ırmağa sor

acılları bilen benim

mevsimleri bölen benim

dört el sarılıp yaşama

sevgilerle ölen benim

bitmek bilmez yollarilen

gülmek bilmez kullarilen

Can Nuri''yi karlarilen

geçip giden kışlara sor



Can dediğin bir kuş gibi

Kara günler bir yel gibi

esip geçer üstümüzden

boz bulanık bir sel gibi

gelip geçer ömrümüzden

aşk denilen çoşkun nehir

içer isen olur zehir

zaman gelir döner devir

eser kalmaz gülümüzden

rüya gibi bir düş gibi

bahar gibi bir kış gibi

can dediğin bir kuş gibi

uçup gider göğsümüzden

ölüm en son durak olur

ten çürüyüp toprak olur

biter bir gün yaprak olur

filiz verir kabrimizden





Dünyanın ilk şiircisi

Buz tutmuş bir zaman dilimindeyim

içimde kaç bin yıllık tortular taşıyorum

dünyanın ilk şiircisiyim belki, yalnız ve yaralı

yaşamın her gün bir yanardağını aşıyorum

Dudaklarım ölü çocukların kanıyla kızıl

karanlık çağların acısıyla kör gözlerim

insanın dininden geliyorum, vahşetinden, kininden

çiçeklerin hala nasıl güzel açtığına şaşıyorum

Nuri CAN  1977







Gül Vurur Beni 

Her akşam üstüme bir hüzün çöker

Hasret mazgalında kül vurur beni

Baktığım her çiçek boynunu büker 

Kalbin yarasında gül vurur beni

Geçip gider günler hicranla gamla

Bazen nehir gibi bazen bir damla

Ağla ey gözlerim durmadan ağla

Akar bozbulanık sel vurur beni

Belalı karalı şu garip başım

Ağlarım ömrümce dinmedi yaşım

Ne bir dostum kaldı ne arkadaşım

Tutar taştan taşa el vurur beni

Tükendi baharım tükendi yazım

Gün be gün artıyor kederim sızım 

Kırıldı çanağım çalmıyor sazım

Bakar dertli dertli tel vurur beni

Bir zaman benimde ömrüm bahardı

İçimde yemyeşil duygular vardı

Umut dağlarımı dumanlar sardı

Eser badi sabah yel vurur beni





Sevmem

Kalender mert ve iyilik perverim

Bu yüzden olmadı dünyada yerim

Sevdiğim insana canım veririm

Ama seni seviyorum demeyi sevmem

Mühlit dost insanım mihnetim yoktur

Onur gururuma hürmetim çoktur

Yüksekten atana bilincim toktur

Ama altdan alan yağcıyı sevmem

Köpek olup kimseye kuyruk sallamam

Kendi tükürdüğümü alıp yalamam

Izzeti nefsime leke kondurmam

Ama ukala kibirli kişiyi sevmem

Fakir bir insanım gönlüm zengindir

Güzel duygulara ruhum engindir

Kimsenin malında gözüm değildir

Ama fukara sürünüp ölmeyi sevmem

Kemlik cennet olsa bir adım varmam

Zayıfı bırakıp güçlü kayırmam

Gavur müslüm diye, insan ayırmam

Ama kendini beğenmiş züppeyi sevmem

Emeğin hakkını savunan işçiyim

Doğrunun,gerçeğin tek bilinciyim

Aydınım, devrimciyim, ilericiyim

Ama tanrıya küfreden deliyi sevmem

ismim Nuri’dir benim soyadım Can

Köyüm Caferlidir şehrim Erzincan

Dinim islam dini kitabım kuran

Ama softa, yobaz hocayı sevmem

Nurí CAN  1970 





Söyle Nereye

Nereye gidiyorsun alıp başını

Söyle ey vefasız söyle nereye

Izdırap çileden elemden başka

Ne kalır, ne kalır söyle geriye

Hiç mi hatırı yok geçen günlerin

Solan sümbüllerin açan güllerin

Öpülen dudağın yaşlı gözlerin

Söyle ey vefasız söyle nereye

Yüzüne en zalim tavrını takıp

Sönmez ateşlere kalbimi atıp

Acılar içinde yalnız bırakıp

Geçip gidiyorsun söyle nereye

Hiç mi hatırı yok hatıraların

Okşanan saçların saran kolların

El ele gezilen ıssız yolların

Söyle ey vefasız söyle nereye

İçimde kaynayan ırmaklar gibi

Dalımda kuruyan yapraklar gibi 

Çiğneyip kalbimi topraklar gibi

Geçip gidiyorsun söyle nereye

Hiç mi sızlamıyor seven yüreğin

Ettiğin yeminin tuttuğun elin

Yağan yağmurların çağlay an selin

Söyle ey vefasız söyle nereye

Sanmaki bir daha mutlu olursun

Kaybolan yılları geri bulursun

Elbet gün gelir sende yorulursun

Söyle ey vefasız söyle nereye

Hiç mi sızlamıyor seven yüreğin

Hiç mi hatırı yok geçen günlerin

Söylenen şarkının okunan şiirin

Söyle ey vefasız söyle nereye

Bir gün ne kalmışsa maziden yana

Doldur yözyaşlarını gönder bana

Beddua etmeye kıyamam sana

Söyle ey vefasız söyle nereye





Gitme

Ömrü bitti bu mevsimin

deme sakın ayrılamam

öldürde git buralardan

hasretine dayanamam

gider isen gözüm kalır

yüreğimde közüm kalır

söylemedik sözüm kalır

utanırım ağlayamam

sormaz kimse hallarımı

güneş almaz dağlarımı

rüzgar eğer dallarımı

kırık kolla sarılamam

candan ayrı can mı olur

dertlere derman mı olur

el yurdu vatan mı olur

kahrolurum ayrılamam

güldürür mü yas sevdiğim

al mührünü bas sevdiğim

dur yoluna as sevdiğim

sen gidersen yaşayamam





Caferli

Yine bahar gelir açar çiçekler

süslenir dört yanda bahçeler bağlar

döndükçe semada mor kelebekler

secdeye kapanır şu yüce dağlar

sullar pırıl pırıl akar derede

kuşlar cıvıl cıvıl öter her yerde

cennet dedikleri sorma nerede

melekler rakseder periler ağlar

koyunlar, kuzular durmaz meleşir

bülbüller ötüşür, güller sevişir

sevda sevda doruklara erişir

gönülden gönüle mutluluk çağlar

1965 





Gül verir sevdan

Gecelerde mehtap  yıldızda ahenksin

dört mevsim bir başka yeşerir sevdan

dallarda goncasın, goncada renksin

her baha dağlara gül verir sevdan

  bakışın bir çiçek, bir yeşil bahar

saçların rüzgarda titreyen çınar

yüzün gülücükler serpilen pınar

yanmış yüreklere su verir sevdan

damarda dolaşan sıcak kan gibi

kalplerde titreyen heyecan gibi

sonsuzluk içinde bir zaman gibi

her sabah ruhlara can verir sevdan

bazen bir mehtapsın, büyülü bir ses

bazen bir rüzgarsın, serin bir nefes

taptaze hayatsın, tükenmez heves

yoksula, düşküne el verir sevdan

Can Nuri bulamam dünyada dengin

adın yüce senin dağlarca engin

asırlar geçsede bozulmaz rengin

bütün engelleri devirir sevdan



Gecenin büyüsü

Rüzgar eser hafif hafif

yaprak yaprak kımıldar

ay süzülür nazlı nazlı

mehtap mehtap parıldar

gerdeğin kollarına düşer gece

gecenin rahmine sevda

çiçeğe durur dalucları

bahar bahar fısıldar

dereler türkü söyler

iç çekişir gelinler

yel dolanır kavakların beline

selvi selvi eğilir

sabah olur sonra

ay çekilir gizlice

dağılır büyüsü gecenin

çözülür bilmece

bir özlem bin özlemle tutuşur

1969





Seven kalbin değeri

Şu gönlümün bahçesine 

taze açmış bir çiçeksin

dallarıma kar düşünce 

terkeyleyip gideceksin

bahar gibi bir kış gibi

hayal gibi bir düş gibi

kanat çırpan bir kuş gibi

başka diyar seçeceksin

sevdaların sihirini

sabahların seherini

seven kalbin değerini

sen nereden bileceksin

bir taş gibi toprak gibi

bir yaş gibi ırmak gibi

dalındaki yaprak gibi

uzaklara düşeceksin

elin elime değerken

yüzün yüzüme gülerken

ben gözyaşımı silerken 

başkasını seveceksin





Herşeyim Sensin

Kalbimde çarpan o tatlı heyecan

kemiğimde ilik, damarımda kan

dimağımda ateş, bedenimde can

Özlemim, sevincim, gerçeğim sensin

hayalim, hülyamsın, sevdiğim, eşim

ümidim, dünyamsın, günüm, güneşim 

sümbülüm, nergizim. nazlı menevşim

cananım, canevim, çiçeğim sensin

sensiz yaşayamam, sensiz gülemem

dünyamı dönüyor sensiz bilemem

yüzyıl yaşasamda yaşadım demem

yaşamım, ölümüm, herşeyim sensin







Dilber

Bir garip yolcuyum ben bu diyarda

gidersen yanına al beni Dilber

yüreğim yaralı kanadım kırık

gönül mehtabına sar beni dilber

İstersen ardından süründür koştur

istersen yanında ulve kavuştur

kalbimi aşk ile yandır tutuştur

çile dergahına sal beni Dilber

Diz çöküp önüne sana yalvarsam

anlar mısın beni, halim anlatsam

 bir gün seni bir kenara atarsam

hakkın divanına sal beni Dilber





Dünya senin olsa ne yazar

Arzular, emeller, umutlar biter

gönülde hüzünler silinmez imiş

kötünün katarı her yerde gider

iyinin kıymeti bilinmez imiş

savaşlar, zulümler, açlıklar uzar

insanlar insana kuyular kazar

dünya senin olsa sonuç ne yazar

ölenler bir daha dirilmez imiş

meyletme dünyanın saltanatına

herkes binip gider bir gün atına

dostluk hanesine, sevgi katına

yalanla, dolanla girilmez imiş

dünyaya her gelen bir gün göçecek

ecel şerbetinden bir tas içecek

herkes ektiğini kendi biçecek

kimseye hesabı sorulmaz imiş 

1973





Dalgalar dalgalar deli dalgalar

Dalgalar dalgalar deli dalgalar

Vurun kıyılara vurun taşlara

Dostlar gitti ıssız kaldı buralar

Kim dokunur gözümdeki yaşlara

Pınar olup sellerle mi çağlasam

çınar olup yellerle mi ağlasam

kim bölüşür kederimi, yasımı

hasretimi hangi tele bağlasam

Dumanlı dumanlı dağlar arkası

Bitmiyor gönlümün gamı tasası

Dostlar gitti viran oldu buralar

Kapanmaz bir daha hasret yarası

Anılar anılar güzel anılar

Bu garip gönlüme küsen anılar

Baktığım her kıyı gözyaşım doldu

Ey sonsuz denizde yüzen anılar

Bu başımı hangi taşa çalayım

Gözyaşımı hangi suya salayım

Rüzgar esmez, haber gelmez, kuş uçmaz

Bunca derdin hangisine yanayım

Zehir ettim çanağımda aşımı

Taştan taşa vurdum dertli başımı

Bir hasret çölünde yandım kavruldum

Kimler siler gözlerimde yaşımı

Geceler geceler uzun geceler

Hasret kurşun olur bağrımı deler

Her gece bir ateş düşer içime

Gelince uzaktan dertli nağmeler

Bulut olup yağdım gül bahçesine

gül olup ağladım bülbül sesine

Can Nuri''yim Hazan vurdu, gam vurdu 

kırıldı dallarım kimin nesine

1973







Ayrılık Treni

Ayrılık treni kalkıp giderken

içimi bin  sızı kapladı birden

 üç günlük dünyada gülelim derken

kalbimiz sonsuza ağladı birden

gelenler ağladı, giden ağladı

kırlmış kalplerin kolu kanadı

ayrılık ölmenin bir başka adı

bir eza başladı biri bitmeden

sislendi ardından gök perde perde

 düşler nerde kaldı, ümitler nerde

gönülden bir veda busesi verde

alıp gözyaşımı götür gitmeden

Can Nuri diner mi bu kar, bu rüzgar

kavuşuruz derken ayrılık uzar 

bir başka ölüm bu, bir başka mezar

bir dipsiz kuyuya düştük bilmeden

 1973







Tomurcuk güllerim kaldı

Esip geçen rüzgarlarda

savrulan küllerim kaldı

tipi, boran, ayazlarda

kavrulan güllerim kaldı

ömür bir kuştu alemde

uçup gitti ah elimde

yalvardığım bir zalimde

yorulan dillerim kaldı

ah ey felek bu ne hışım

yerden yere vurdun başım

çeşme gibi aktı yaşım

perişan hallerim kaldı

gönül gülü dala küstü

gelen vurdu, giden üzdü

aydınlıklar uzak düştü

karanlık günlerim kaldı

giden bahar, gelen yazda

yüreğim dondu ayazda

dertli dertli çalan sazda

kırılan tellerim kaldı







Kalplerde donan nedir

Ey günün gözlerinden

gönlüme akan nehir

ay geçerken penceremden

ruhumu yakan nedir

hasret midir nar mıdır? 

bir deli rüzgar mıdır? 

aşk mıdır hicran mıdır? 

içime dolan zehir

feryada yar feryada

anılar düştü yad''a 

 sevgisiz bir dünyada

kalplerde donan nedir

mavi düşler mi söndü

geceler mi karanlık

sustu bütün türküler 

sazlar çalmıyor artık

bir yapıp bir yıkarak

bir düşüp bir kalkarak

işte ölüm son durak

ardında kalan nedir







Bakarız yollara sislenir dağlar

kar yağar dağlara kar yağar oğul

bir dertli türküdür dertli ömrümüz 

yollar geçit vermez yel uğul uğul

kimbilir nerde garip kalır ölümüz

bakarız yollara duman sis çökmüş

hasret bağlarını hazanlar dökmüş

sılada çiçekler boynunu bükmüş

açmadan soluyor kahır gülümüz

her akşam hasretle yanar bağrımız

gün begün artıyor yürek ağrımız

içimizde çıban çıban çağrımız 

leylasız mecnuna döner çölümüz

bakarız yollara sislenir dağlar

hasretlik çekenler karalar bağlar

her gece içimde bir türkü ağlar

ne gözümüz güler ne de gönlümüz





Her Mecnuna Çöl Gerek

Aşka aşiyan olan

aşığa nişan gerek

Leyla''ya mecnun olan

zülfü perişan gerek

karlı dağlar esersin 

uzak yollar kesersin 

eldir sever unutur

varıp kime küsersin

ağlama yaşa diren

talihsiz başa diren

bahar geçti, yaz geçti

güz geldi kışa dayan 

hayal, düş idi gelmez

uçtu, kuş idi gelmez

yollar kış idi gelmez

feryat,fiğan çekersin

dağın dağıstanına

gülün gülüstanına

ömrünün bostanına

kara zehir ekersin 

ağlama yaşa dayan

atılan taşa dayan

ölümde olsa sonu

sevdalı başa dayan

bahçelere gül gerek

güllere bülbül gerek

her leylaya bir mecnun

her mecnuna çöl gerek







Ne Deyim

Bir ömür boyunca hep seni sevdim

sen başka sevmişsin sana ne deyim

canımı, ruhumu, kalbimi verdim 

yüreği yaralı bana ne deyim

deste deste iri güller elinde

savrulup gidersin seher yelinde

sen güler oynarsın kendi halinde

benim gözümdeki yaşa ne deyim

gönül kuşu elden ele salmışım

gözü bağlı dert içine dalmışım

bir sevda ki, bak çaresiz kalmışım

seven gönlümdeki yasa ne deyim

tufan yağmurdadır selinde değil

yara yürektedir dilinde değil

insanın kaderi elinde değil

ellerin attığı taşa ne deyim

