INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-bekir-ayral-6nrfq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üç şey dilerim, 

Tanrıdan.

Kendime, 

Sevdiklerime

Ve

Tüm insanlara.

“   Önce sağlık, 

     Sonra mutluluk

     Ve

     Daha sonra da

     PARA…………….  “', 'Üç şey dilerim,  Tanrıdan. Kendime,  Sevdiklerime Ve Tüm insanlara. “   Önce sağlık,       Sonra mutluluk      Ve      Daha sonra da      PA...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dua-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-bekir-ayral-1rmnn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceleri yatarken, 

En son seni öpüp, sevmek.

Sabahları uyanınca, 

İlk seni görmek.

Geceleri rüyada, 

Gündüzleri her anda

                               yaşamak seni.

Ne güzel olurdu, 

Değil  mi?', 'Geceleri yatarken,  En son seni öpüp, sevmek. Sabahları uyanınca,  İlk seni görmek. Geceleri rüyada,  Gündüzleri her anda                   ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dilek-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞEREF', 'seref-i-hsan-uncuoglu-mi766', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİZİM MAHALLEDE

ŞEREF''İN ŞEREF''İNE

Müezzin Şeref Şerefe''de

Vakit gelmiş çağırıyor

Şeref Şerefli meyhanede

Karışık Altınbaş içiyor, 

**

Mahallede iki bebek Şeref var

biri ınga ınga öbürü viyaklar

Zengini kucakta fakiri yerde

İki bebek çok bizim mahallede.

**

Bu bebek Şeref saray evde yaşar

Annesinden fazla seven etraflar

Şu da Şeref ana baba Şeref ağlar

Allahtandır bu felekten karanlıklar, 

**

Elimi sallasam elli Şereften kimisi

Nerden çıktılar Allahtan''mış Şerefli 

Asırlarca kara zarar bu o takım belli 

Şerefleri olmasada çıkmış hepsi Şerefede! 

Oy avcıları rüyalarda diz çöküyorken Şerefe 

Mahallemde! bakın ellerim havada sizin için

Haydi haydi çin çin Aslansütü..... Sağlığınıza! , , 

Şerrefe!', 'BİZİM MAHALLEDE ŞEREF''İN ŞEREF''İNE Müezzin Şeref Şerefe''de Vakit gelmiş çağırıyor Şeref Şerefli meyhanede Karışık Altınbaş içiyor,  ** Mahal...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seref-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzay Çağı İmamı', 'uzay-cagi-i-mami-i-hsan-uncuoglu-l4ho9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'UZAY ÇAĞI İMAMI

HOCA ATLA UZAYA

Her zaman en başta 

sağduyunla Fikrin 

sözün davranmanla 

Kalk ayağa canla başla 

Milletine

Çalış görelim ne olursa, 

İnancım enüstün Evvel Allah 

nerde ne varsa cebimde hoca

Çok dünyada yok eşi 

doğrusu bindenbiri 

bana öğretti

Göğe yakındır

O Dedem Bektaşi,        

**

Dur otur hep dünyada namlı

Papası papazı hacısı hocası 

Gün be gün anlatır satır satır 

Musa'' İsa'' Adem ile Havva''yı, 

**

Fizikten Kimyadan

Belledim Yaradan''ı

Yukarıda Uzayı

PirBakan parti sandı

bu genom çağında

Molekül yapısını

Papaz pas pas yaptı

bizim Hoca anlatmadı, 

**

Oy! be Arif''im diyen 

Yaradana yanan benim ben

Kınamayın sözinen

bana onu kalbim derinden 

Yüce doğru İnancımı

Allahımı/Tanrımı

anlatan bir hocasında

bulamadım öyle aklı

Derin bilgimden gayrı,', 'UZAY ÇAĞI İMAMI HOCA ATLA UZAYA Her zaman en başta  sağduyunla Fikrin  sözün davranmanla  Kalk ayağa canla başla  Milletine Çalış görelim ne...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/uzay-cagi-imami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâr', 'ruzg-r-atilgan-alemdar-kidon', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ister inan ister inanma

aşkın mucidi benim

ve düştüğüm bu zindanın asıl sebebi

içime sığmayan düşlerim

yüzümden anlaşılmaz

seni nasıl sevdiğim

bin yıldır hasretimdir

soğanım ve karanfilim

yansa olmaz alev alev

tuza dönen kirpiklerim

sakladığımdan değil 

barındıramaz ki tenim.....

şimdi sokak lâmbalarının altına

leş kokan bir rüzgâr gibi gireceğim

kimse bilmeyecek suçsuz olduğumu

kimse bilmeyecek ki kimsesizim

evet aşkın mucidi benim

kendimi tıkdığım zindan kadar

ve ıslak bir sokak lâmbasına

sığınmaya çalışan rüzgâr', 'ister inan ister inanma aşkın mucidi benim ve düştüğüm bu zindanın asıl sebebi içime sığmayan düşlerim yüzümden anlaşılmaz seni nasıl sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruzgar-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimdesin', 'duslerimdesin-abdullah-ozturk-yzuaq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'insanların yüzlerinde eskiden kalma bir tebessümün izleri

ve hala gülmeye çalışıyor bazıları

hiçbirşey olmamış gibi

bazıları umutlu, güneşin bir gün doğacağından

benimse umudum hiç kalmadı

bir sabah güneşin yerine, pencereme senin doğacağından

sevdana esir, aşkına ben köleyim

sen yoksan yanımda bırak beni öleyim

hani aşkımı anlatmamı istiyorsun ya

bir ömre sığmadı ki, bir şiirde söyleyim

ama yine de seni düşünmek huzur veriyor bana

bazen bağırmak geliyor içimden

kendimi tutuyorum

gözlerini görüyorum gözlerimde

kalkıp gitmek istiyorum buralardan

gidemiyorum

ben de kalkıp gecenin bir yarısı

sana şiirler yazıyorum

seni düşünüp ağlıyorum

affet beni ama, daha fazlasını yapamıyorum

her giden seni de götürüyor sanki

hiçbir iz kalmıyor senden geriye

ne yana baksam gidenleri görüyorum

ve her birinin elinde senden bir parça

senden geriye hiçbirşey kalmıyor bende

benim bildiğim her gecenin ardında bir sabah olurdu

ve çok çabuk gelirdi sabahlar, tabi geceleri uyursan

benim de sabahlarım gelecek

bir de sen olmasan

gecelerim de bitecek

düşlerimde kalmasan

bak saat kaç oldu, gecenin bir yarısı

ve ben hala babalar gibi yazıyorum

babalar gibi de söylüyorum senin için yazdığımı

ya sen ne haldesin

dünya umrunda değil yatıyorsun

ama farkında olmadan beni mahvediyorsun

hep bana oluyor  n''oluyorsa

bıktım usandım böyle aşkın ızdırabından

ya ver aşkını dünyalar benim olsun

ya da çek git düşlerimden, n''olacaksa olsun..', 'insanların yüzlerinde eskiden kalma bir tebessümün izleri ve hala gülmeye çalışıyor bazıları hiçbirşey olmamış gibi bazıları umutlu, güneşin...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztürk']::text[], 8.5, '{"poet":"Abdullah Öztürk","poet_slug":"abdullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/duslerimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Hayata Sığdırmak', 'aski-hayata-sigdirmak-gokcen-duran-7i7b1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anılarımızda

                      öldürdüğümüz

                                                 aşklar

                                                               yaşar

Yaşadıklarımız

                          öldürdüklerimizle

                                                            bütünleşir

                                                                               hayatta

Bundandır

                 yaşamın

                                 uzunluğu 

                                                    ve

                                                            acılar...

Bundandır 

                     Yaşamın

                                    kısalığı

                                                    ve

                                                             zaman kaygısı

Çünkü hayat, 

 Bir 

          Aşkı

                        yaşamak 

                                        için

                                                çok kısa

Aşksız 

              yaşamak 

                               içinse 

                                               çok uzun...', 'Anılarımızda                       öldürdüğümüz                                                  aşklar                                     ...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aski-hayata-sigdirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-hasan-huseyin-ozay-eajr2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek bu delice çocuk olmak 

Sonu olmayan sevdayı yaşamak 

Ümit ekmek gelecek yıllara

Hasret kalmak sevda yolunda

Özgür olmak gökyüzünde kuşlar gibi

Dost olmak gül ve diken gibi

Sevmek kerem ile aslı misali

hasret kalmak sahilde dalgayı bekler gibi.

Kaybettim artık sana olan sevgimi

Geceler aldı ümidimi hayalimi

Çok sevmiştim güzelim seni

Hasretinden kaybettim inan benliğimi', 'Sevmek bu delice çocuk olmak  Sonu olmayan sevdayı yaşamak  Ümit ekmek gelecek yıllara Hasret kalmak sevda yolunda Özgür olmak gökyüzünde ku...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özay']::text[], 8.5, '{"poet":"Hasan Hüseyin Özay","poet_slug":"hasan-huseyin-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmek-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade Bir Tebessüm', 'sade-bir-tebessum-hasan-huseyin-ozay-8i3qu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sade bir tebessümdür sevdayı yaşatan 

Aşk ateşini yakıp delice bağlayan 

Sevdadır çiçeklere baharı sevdiren 

Sade bir tebessümdür seveni ağlatan

Bir tebessümüne bağlanmıştım ben o zalimin 

sevgisinin sahte sözlerinin yalan olduğunu ne bileyim 

Canımı istese hemen verirdim

Sade bir tebessüm yeterdi bana', 'Sade bir tebessümdür sevdayı yaşatan  Aşk ateşini yakıp delice bağlayan  Sevdadır çiçeklere baharı sevdiren  Sade bir tebessümdür seveni ağl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özay']::text[], 8.5, '{"poet":"Hasan Hüseyin Özay","poet_slug":"hasan-huseyin-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sade-bir-tebessum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Dilinden', 'gulun-dilinden-sakir-bozan-mhf93', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahçıvana sorma gülün hikayesini...

Koklayarak öğren geçmişini...

Yaprakları kaç yağmur görmüş...

Kaç fırtınadan kurtarmış kendini...

Kaç kişi uzanmış koparmak için dalından...

Gerçek bir sevgiliye ulaşmak için...

Kaç yıl beklemiş...

Bir gece yarısı kimler getirmiş o sevgiliye...

Karanlığında gecenin...

Kimin odasına yayılmış kokusu...

Dikenleri kimin parmağına batmış...

Kimin avuçlarında kurumak istemiş...

Hepsini güle sor bunların...

Avuçlarında tut ama yok etme...

Koparma sevgi tomurcuklarını sahiplen onu...

Ansızın gelmişti bilirsin bir gece yarısı sevgiliye...

Dokun ona, kokla onu dikenlerin inadına...

Sevgi kristallerinden yapılmış bir vazoda sakla...

Acılara, geçmişine, fırtınalara ya da...

Yağan yağmura inat...', 'Bahçıvana sorma gülün hikayesini... Koklayarak öğren geçmişini... Yaprakları kaç yağmur görmüş... Kaç fırtınadan kurtarmış kendini... Kaç ki...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gulun-dilinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşündün Mü?', 'hic-dusundun-mu-sakir-bozan-qhsgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç düşündün mü benim sensizliğimi? 

Geceleri rüzgarın uğultusuyla uyur

Sabahları martıların çığlıklarıyla uyanırım

Bir kahvaltı bile yapamam sensizliğimde

Uykunun mahmurluğuyla yürümeye başlarım

Zakkum çiçeklerinin arasında

Sabahları adalar bir başka olurmuş

Sensizken bunu hiç anlamamışım

Geldiğim vapurla dönerim sana

İçimdeki hasreti söndürmek için

Alır götürür beni uzaklara

Sonra yavaş yavaş yaklaştığımı hissederim

Önce sesini duyarım telefonda

Sonra bedenimde kalan kokunu

Sana kavuşmak için zamanla yarışırım

Birazdan senin kollarında bulurum kendimi

Hiç düşündün mü benim sensizliğimi?', 'Hiç düşündün mü benim sensizliğimi?  Geceleri rüzgarın uğultusuyla uyur Sabahları martıların çığlıklarıyla uyanırım Bir kahvaltı bile yapama...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hic-dusundun-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beraber Ölelim', 'beraber-olelim-sakir-bozan-3ctef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine karanlık gecenin sensizliğinde

Yapayalnız tek başıma

Gözlerimi ufka dayamış

Güneşin doğmasını bekliyorum

Amacım güneş değil bir tanem

Doğsun şu güneş aydınlansın ki dünyam

Ya sana geleyim, ya sen gel bana

Dışarıda hafif bir yağmur çiseliyor

Elimde sigaram bir de ılık çay

Bir yandan düşünüyor

Bir yandan şarkılarda seni arıyorum

Şarkılar sanki bizi anlatıyor

Hele birisi var ki içlerinde şöyle diyor

Her şeye hazır ol bana öyle gel

Bir diğeriyse ölümüne vurgun olduğumuzu

Bir başkası seni çok ama çok seviyorum diyor

Hangisine dokunsam onda sen varsın

Bedenin olmasa da burada sen varsın

Senin varlığın yaşatıyor beni

Yokluğunda ise ölümüm aklıma geliyor

Son şarkıdaysa şöyle diyor

Beraber ölelim...

Öleceksek te beraber ölelim...', 'Yine karanlık gecenin sensizliğinde Yapayalnız tek başıma Gözlerimi ufka dayamış Güneşin doğmasını bekliyorum Amacım güneş değil bir tanem D...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beraber-olelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında Mısın?', 'farkinda-misin-sakir-bozan-ilagr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben hâlâ aynı benim

Doğduğumdan beri adım aynı ad

Saçlarımın rengi hiç değişmedi

Gözlerim aynı bakıyor hâlâ

Kalp atışlarım hiç durmadı

Gerçi biraz acıyor ama, ellerim de aynı

Yanımda olmasan da hep aynı sevdim seni

Senin için hep aynı şarkıları dinliyorum

Aynı yerde bekliyorum

Aynı masada şiir yazıp, sigaramı içiyorum

Sesini duymak istiyorum

Ve bir alo deyişin bile yetiyor her zamanki gibi

Bak ben hâlâ aynı benim

Biraz yüreğim buruk, biraz üzgünüm

Zaten eskiden beri hep böyleydi

Ben hâlâ aynı benim

Her gece cehennem azabı çekiyorum

Birileri zebani gibi başıma dikiliyor her gece 

Önceleri vapurları, martıları, yunusları severdim

Şimdilerde kahrediyorum onlara

Ben hâlâ aynı benim de

Hiç anlayamadım değişenleri

Ben hâlâ aynı benim, bilmem farkında mısın?', 'Ben hâlâ aynı benim Doğduğumdan beri adım aynı ad Saçlarımın rengi hiç değişmedi Gözlerim aynı bakıyor hâlâ Kalp atışlarım hiç durmadı Gerçi...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/farkinda-misin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüçlük', 'ucucluk-ali-gencli-ocxoa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım, canım  ne denli sevinç çekse de, /

 /Olmuyor!

  Kirpiklerimde asılı, / yüzün gibi hüzün.../

                             *

   / Kazandığım  ne varsa, 

  

   yitirmeye  hazırım. /Yeter ki sen benim ol.

    Ben her çileye razıyım. /

                            *

     / Yüklendim  çocukluk  acılarımı /

   

     biriktirdiğim  babasızlık hüzünlerimle/ geliyorum. 

  

     / Geride  kalan  günlere yanarak... /', 'Canım, canım  ne denli sevinç çekse de, /  /Olmuyor!   Kirpiklerimde asılı, / yüzün gibi hüzün.../                              *    / Kazan...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençli']::text[], 8.5, '{"poet":"Ali Gençli","poet_slug":"ali-gencli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ucucluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin?', 'neredesin-sakir-bozan-7svxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yosun tutmuş sevdaların

Anlamsız yüreklerde yol alması

Akıbetini kaybetmiş bir yaprağın

Rüzgara teslim olmasından ne farkı kalmış

Ben ki tutuşmuş bir alevin kavurucu sıcaklığında

Hasretin, özlemin, mesafelerin acımasızlığına yenik düşmüş

Yıllardan sonra buldum dediğim

Uğruna yüreğimi, canımı verdiğim

Gecelere adını yazdığım bir cana sevdalandım

Can dediğim, aşk dediğim, sevda dediğim sen

Hani ey yüce varlık

Neredesin sen? 

İçimi ürperten ses

Kocaman yürek neredesin sen? 

Bak bir gün daha bitiyor sessizce

Üzerimde gözler dolaşıyor, bakışlarımda seni ararken

Sersemliğime gülüyor insanlar

Sen...Ey sen diyorum

Hasretiyle bitiren sen

Neredesin? Neredesin? Neredeee? 

Mevsimlerine soğuk karlar mı yağdı? 

Yaklaşmaktan mı korkuyorsun yoksa? 

Her şeyin en güzeli sen

Sen bir tanem... Sen aşkım... Sen her şeyim...

Sen ve sen kadınım hâlâ yoksun

Neredesin sen?', 'Yosun tutmuş sevdaların Anlamsız yüreklerde yol alması Akıbetini kaybetmiş bir yaprağın Rüzgara teslim olmasından ne farkı kalmış Ben ki tut...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/neredesin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydimdi', 'neydimdi-erol-nacar-44e8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1

Kara kış değildim

Yaz da değildim, 

Bahar da

Hatta

Son bahar da, 

Ayaz da....

Neydimdi peki? 

Hiçtimdi! .......

Dört mevsimden

Bir

Kendimi biçtimdi.

2

Bir zaman

Kavaklarda yeldimdi

Mahallede 

Çağıldayan seldimdi

En önlerde yürüyen, 

Kavgalarda

'' Jeonimo '' bendimdi

Neydimdi......

.....................

Hiçtimdi! ...

3

Sevda neydi, 

Ben kimdimdi

Ondördümde

İlk aşkımı inşaatta.......................

Neydimdi...

Hiçtimdi! ........

4

Onyedimde

Şarabın acı tadını aldımdı.

Trenleri seyredip

Hülyalara daldımdı.

Postal marşı eşliğinde

İngilizce dersinde, 

Gusül abdesti ödevinden

Sınıfta da kaldımdı? ! ....

Halbuki Hoca

Ne dediyse; 

I am very well

Yaptımdı.

5

Yirmisinde

Postaldımdı, keptimdi.

Kapuska,  mercimek, 

Palaska, tüfek, 

Uygun ayak, 

Bir ton dayak bendimdi...

Tekmelerle, tokatlarla teptimdi....

Neydimdi...

Hiçtimdi! 

6

Baba evine dar geldimdi, 

Ana diline zar geldimdi, 

Üstüne üstlük yar sevdimdi; 

'' Değme yaram var '' dedimdi

..............

...............

Para da neydi ey sevgili? 

Hani

Yarin bir busesi 

Bir ömre bedeldi! ...

Neydimdi...

Hiçtimdi! 

Dört mevsimden

Bir

Kendimi biçtimdi.

7

Benden farklı yaşayanlar

Dört mevsimlikler de vardı.

Bembeyaz kar yağar

Ballı börek kayardı.

Tohum çatlar

Kokanalar

Çilek - çiçek kokardı.

Deniz tuzu

Dalgalar, 

Gündüz güneş, 

Gece ay, 

Tümsekleri yakardı.

Yağmur atar

Arkasından yaprak sarısı şaraplar...

8

Ekmek aslanın ağzında dediydi, 

Midesinde olduğuna

Yemin ettiydi

Eskiler.

Nefes alıp veriyorlar ya! 

Ekmeğin aslan olduğunu

Nereden bilsindi garipler.

9

Yaşamak için değil

Yaşatmak için çalıştığımızı

Ben babamdan bildimdi

Ustamın tokadını

Villaları boyar iken yedimdi.

Ustam dedim: '' Neydimdi ''

'' Avare - aylak ''

Bendimdi

'' Haydut, korsan, dangalak, 

Serseri - salak...''

Bendimdi

Haşa huzurdan, 

Allah''a ortak koşardımdı.

Hem kızar, 

Hem de beyefendilerin

Ekmeğiyle yaşardımdı.

Neydimdi...

Hiçtimdi.

10

Böylece

Ustamın sayesinde

Haddimi de bildimdi.

Aklımı başıma devşirdimdi.

Bu

Dünyaya ben...

Çalışmaya geldimdi.....

Neydimdi...

Hiçtimdi! 

11

'' Emek '' neydi, 

'' İşçi '' kimdi? 

Dedimdi

Felsefeye girdimdi.

Böyle 

Böyle

Marx''a kadar geldimdi.

Arkasından 

Polis copu yedimdi.

12

Neydimdi...

Bildimdi! ...

Bir acayip devdimdi! 

Bir acayip sevdimdi! ...

Şatolarda yazılan

Tarihleri deldimdi! ...

13

Neydimdi...

Yangın, motor, seldimdi

Kazma, kürek, beldimdi...

Zincirlerim bir yana

Kafa - Kol...tendimdi...

O

Muhteşem

Yakışıklı

Mezarcı başı bendimdi.

                                      (Güney  Dergisi)', '1 Kara kış değildim Yaz da değildim,  Bahar da Hatta Son bahar da,  Ayaz da.... Neydimdi peki?  Hiçtimdi! ....... Dört mevsimden Bir Kendimi...', ARRAY['Türk Edebiyatı','Şiir','Erol Nacar']::text[], 8.5, '{"poet":"Erol Nacar","poet_slug":"erol-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":149,"source_url":"https://www.antoloji.com/neydimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşuçurması', 'kusucurmasi-perihan-magden-k33op', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kuşu şimdi uçuracağım

ben bile boyalarını takmış olsam.

Seninle yapmak istediğim herşey

kursağımda kaldı.

Artık yepyeni bir çinseddinde dengede

Uyurken kulağından bezir yağı dökmek

isterim.

Kıskanç- Tüm kapılar onlara çalıyor.

Kaçıncı telefon defteri yırtıp attığım

Ne de uzun göbek kordonları var.

O kadar yıl geçti aynı terane

Hala kızarabildiğinde yüzüm

göndere çekiliyor.

Ganj dahi temizleyemez bu sıkıntıyı

ceset aralarında süzüldüğüm halde.

Çocuk- Akın akın baleye gidiyorlar.

Dolu zamanlarında ne düşünürler? 

Bunca sır; bunca esrar-Beyim

Baca baca dumanların ardından

bir tüftüf iki püfpüf

bu oyuncak tren mi çıkmalıydı? 

Hırçın- Anne ne biçim çocuklar bunlar! 

Anneleri de sana benzemiyorlar.

Kamçı kuyruğumu şaklatarak

hafızasızlığa kadar varabilirim.

Bütün bu küçük düğmeler sahilde

bulduğum; ne anlama gelirmiş şimdi bildim.

Kıskanççocukhırçın- Bak beni eve kitle.

Onlara korkuyu ezberletmişler

Çok lazımdı vapurda çarpım tabloları.

Son kez: 

Bu kuşu hemen uçuracağım.

Yenisini boyamak çocuk işi.', 'Bu kuşu şimdi uçuracağım ben bile boyalarını takmış olsam. Seninle yapmak istediğim herşey kursağımda kaldı. Artık yepyeni bir çinseddinde d...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kusucurmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Görmemiş Canım', 'gun-gormemis-canim-gursel-colak-9opjv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Katliama kurban olan doğmamış olan bebeğin insanlığa isyanı.

Beş aylıktım gün görmedim

Annemin karnındaydım hiç gülmedim

Deşmişler karnını annemin

Parçalamışlar bedenimi benim

Ne istediler? Annemden, benden

Ben gün görmemiş bir canım

Ne istediler? Gün görmemiş candan.

Deşerlerken annemin karnını

Parcalarlarken gün görmemiş bu canı

Herkes seyirci kaldı

Avrupası, Amerikası

Neredeydi bahsettikleri insanlık hakları? 

Nerede olduğum bilinmez

Parçalanmış bedenim birbirine eklenmez.

Uyanın kendini insan sananlar

Sığarmı insanlığa bu yapılanlar', 'Katliama kurban olan doğmamış olan bebeğin insanlığa isyanı. Beş aylıktım gün görmedim Annemin karnındaydım hiç gülmedim Deşmişler karnını a...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gun-gormemis-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-gursel-colak-c36g1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umarım bütün sevenler sevdikleri için aynı düşüncededir.

Özellikle evli olanlar.

Yaşamak seninle

Mutluluk seninle

Gülmek seninle

Ağlamak seninle

Güzel

Ne yaşamak

Ne mutluluk

Ne gülmek

Nede ağlamak

Güzel

Sensiz.....

Ecel seni almasın

Ne olur benden önce

Dua ederim bunun için her gece

Çıkmaz dudağımdan

O çok sevdiğim cümle

Diyemem senden başka kimseye

Seni seviyorum diye

Sevemem ben başkasını

Sevmek olmazki fani dünyada

Sensiz.....

Sen benim canım

Damarlarımda dolaşan kanım

İyi ve kötü günlerde

Yanımda olan

Ağlarken güldüren

Üzüntülüyken sevindiren

Hayata tek bağlantım

Yaşayamıyacağımı anladım

Sensiz.....', 'Umarım bütün sevenler sevdikleri için aynı düşüncededir. Özellikle evli olanlar. Yaşamak seninle Mutluluk seninle Gülmek seninle Ağlamak sen...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sensiz-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevgiyi Ne Bilirsin!', 'sen-sevgiyi-ne-bilirsin-gursel-colak-yspe3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmeyi bilmeyenler.

Sen sevgiyi ne bilirsin! 

Hiç sevmemişsinki

Sevdiğini sanıp

Kendini kandırdın

Belki bilerek

Belki bilmeyerek

Masum kalpleri kırdın

Aşkla sevgiyi karıştırdın

Sevgiye hiç inanmadın

Sevildiğini anlayamadın

Sen sevgiyi ne bilirsin! 

Dilerim, sende bir gün

Anlarsın ne demek

Delice birisini sevmek

Uğruna canını vermek.

Belki sen sevgiyi

Belkide sevgi seni bulur

Belki kapında

Belkide kalbinde durur

Ama ne olduğunu

Sen anlayamazsın

Sen sevgiyi ne bilirsin! 

Sevgilerden uzak

Kurmuşsun bir tuzak

Adı ise aşk

Sanmaki pişmanlık

Mutluluk kadar uzak

Aç kalbini girsin içeri 

Bırakta gönlün sevsin birini

Belki o zaman anlarsın sevmeyi

Vaz geç sevenleri üzmeyi

Öğren gerçekten sevmeyi.', 'Sevmeyi bilmeyenler. Sen sevgiyi ne bilirsin!  Hiç sevmemişsinki Sevdiğini sanıp Kendini kandırdın Belki bilerek Belki bilmeyerek Masum kalp...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-sevgiyi-ne-bilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeliyim Buralardan', 'gitmeliyim-buralardan-elif-atici-o9awj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dermanım yok, derdim sığmaz dağlara

Çare yok ki, gönüldeki yaraya

Hangi yürek dayanmış bu acıya

Gitmeliyim durmam ben buralarda

Tutma gardaş gidem ben bu diyardan

Sevdamı bağrıma düğümleyeyim

Derdimi katarlara yükleyeyim

Sen yoksan bu ellerde ben neyleyim

Bir cigara yakıp gidem buralardan

Tutma gardaş gidem ben bu diyardan

Elin koynunda yar, söyle ne edek

Buralarda durmam; gayri ne gerek

Yaşarken ölüm bu imiş demek

Sazım alıp gidem ben buralardan

Tutma gardaş gidem ben bu diyardan', 'Dermanım yok, derdim sığmaz dağlara Çare yok ki, gönüldeki yaraya Hangi yürek dayanmış bu acıya Gitmeliyim durmam ben buralarda Tutma gardaş...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gitmeliyim-buralardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Sana Ağlasam', 'simdi-sana-aglasam-cem-bektas-psodg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülümse, 

Gülmektir iklimi ısıtan buse.

Soğukta titrer ellerin, 

Gülmek için sen, 

Ellerinde baharla gezerdin.

Yarim...

Üzerini kalın giyin iyice, 

Soğuktur gurbet illerinde gece.

Gülümse, 

Ne olmuş üzüldümse.

Ağlamak denen çocuksu bela, 

Yokluğunda geldiğim kekik kokulu yayla.

O kekik kokusudur, 

Saçlarının kokusuna hasretin

avuntusu.

Şimdi sana ağlasam, 

Orası yağmur...

Gözyaşım limanını kaybetmiş vapur.

Sana ses versem, 

Orası fırtına...

Nefesim vurdukça rüzgarın sırtına.

Gülümse, 

Mevsim kış değilse...', 'Gülümse,  Gülmektir iklimi ısıtan buse. Soğukta titrer ellerin,  Gülmek için sen,  Ellerinde baharla gezerdin. Yarim... Üzerini kalın giyin ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/simdi-sana-aglasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Meçhul Kadını', 'o-mechul-kadini-cem-bektas-toqxz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını sorup uyandım görmeden rüyanın ardını

Sadece rüyamda tanıdım o adı meçhul kadını

Ateşlere girmeyen bilemezmiş yanmanın tadını

Ve ben yanıyorum, o gece andığımdan beri adını', 'Adını sorup uyandım görmeden rüyanın ardını Sadece rüyamda tanıdım o adı meçhul kadını Ateşlere girmeyen bilemezmiş yanmanın tadını Ve ben y...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/o-mechul-kadini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adına Bahar Demiştim', 'adina-bahar-demistim-cem-bektas-vz35v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar, 

Gençliğimin ihtiyar günlerinde, 

Dilime doladığım aşk türkülerinde, 

Sen vardın deniz gözlerinle.

Sen üşüyen sözlerimdeydin.

Ve yanan yüreğimde güzelim.

Adına bahar demiştim...

Seni bahar yağmurlarında sevmiştim.

Sonra, 

Fesleğenler kederlendi, gittin.

Elindeki eller değildi ellerim.

Mavi bakışlarında denizin, 

Unuttum deniz gözlerini senin.

Oysa, 

Adına bahar demiştim...

Seni bahar yağmurlarında sevmiştim.', 'Bir zamanlar,  Gençliğimin ihtiyar günlerinde,  Dilime doladığım aşk türkülerinde,  Sen vardın deniz gözlerinle. Sen üşüyen sözlerimdeydin. ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adina-bahar-demistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu''m', 'anadolu-m-cem-bektas-noag4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkından Anadolu’m

Yaprak olsam, 

Güz gelince

Toprağına düşsem

Bahar gelince

Dallarının ucunda

Yeniden yeşersem

Coşkundan, 

Bayramlarda sevda olsam

Düğünlerde halaybaşı.

Sen hüzün olsan Anadolu’m

Ben de gözyaşı...

Çamurlu yüzlerinde bebeklerin, 

Çizgi çizgi işlenmiş derdin.

Soyun şu hazinliğini Anadolu’m

Kırmızılar giyin.

Bilirsin, 

Akmayan derelerinde

Ve solmayan renginde senin

Kızıl kumlu patikalarında, 

Başakları yeni altınlaşan tarlalarında, 

Eğer bir gün, 

Bir çocuk doğarsa ürkek ve narin, 

Adı barış olacaktır.

Ve

Büyüyecektir yitirip bebekliğini, 

Sevdalı ellerinde senin.

Soyun üzüntünü Anadolu’m

Sevinçler giyin.', 'Aşkından Anadolu’m Yaprak olsam,  Güz gelince Toprağına düşsem Bahar gelince Dallarının ucunda Yeniden yeşersem Coşkundan,  Bayramlarda sevd...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anadolu-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Hasreti*', 'dost-hasreti-bayram-tunca-nvore', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir dost arıyorum, özü sözü aşina

Her şeyiyle de denk olsun arşıma

Çorap ördürmesin şu garip başıma

Görürseniz haber verin Rab aşkına

Bir bülbül kondu, dağdaki dal başına

Şu hayat yolunda neler geldi başıma

Ah zalim felek su kattı, pişmiş aşıma

Kaybettim dostu, kaldım tek başıma

Ne çok arayıp bulamadım aşina bir sima

Çoklarını benzetsem de o sadık dostuma 

Oturtmadım, hiç birilerini gönül postuma

Geçse de yıllar hâlâ arıyorum o dostuma

10.08.2002-10.10', 'Bir dost arıyorum, özü sözü aşina Her şeyiyle de denk olsun arşıma Çorap ördürmesin şu garip başıma Görürseniz haber verin Rab aşkına Bir bü...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dost-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Eksik', 'hangisi-eksik-laci-gece-47zqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbin gözyaşı yağmurundan gelen gecedir sanki bize sevmek! 

Yabancı ellerin dalından kopardığı bir yaprağın peşinde asılı kaldı yüreğim...

Çisil çisil yağan yağmurun altında umarsızca öpüşmekti bize sevmek! 

Donuk bir heykelin gözlerinden dökülen gecenin ortasında yapayalnız kalmaktı...

Yüreğinde hazan güneşleri açıp, yalnızlık tohumlarını yeşertirken, gölgesi kalmamış, içiboş çınarların serinliğinde mumdan bir gemiyle ateş denizinde yüzerek kavuşmaktı bize sevmek! 

Amansızca yağan hüzün yağmurunun selinden sandalsız ve küreksiz gecebilmekti...

İçindeki sevilme umudunu yeşertip kuşların söylediği yağmur şarkılarında bulmaktı yüreğini....

Söyle en sevenim...hangisi eksik bizde? ? ! !', 'Kalbin gözyaşı yağmurundan gelen gecedir sanki bize sevmek!  Yabancı ellerin dalından kopardığı bir yaprağın peşinde asılı kaldı yüreğim... ...', ARRAY['Türk Edebiyatı','Şiir','Laci Gece']::text[], 8.5, '{"poet":"Laci Gece","poet_slug":"laci-gece","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hangisi-eksik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Burada', 'i-ste-burada-laci-gece-bewcl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Türkülerle, şiirlerle yüzünde açan gülün tomurcuğunda, özümdesin..

İlk yazın asıldığı perdeleri aralayıp yüreğime eş buldum seni! 

Mızraba değen telde, telden süzülen aşk nağmelerindesin.

Kirpik misali...gözümdeki perdede buldum seni...

Gereksiz üzüntüm, her daim yaşama hevesimdesin.

Sümbülde, lalede, ölümün ilmiğinde buldum seni yüreğimde.

Yokluğunun sarhoşluğunda, öptüğün yaslı kaldırımdasın.

Dudaklarımın tattığı yerde; yüreğime yazdım seni...', 'Türkülerle, şiirlerle yüzünde açan gülün tomurcuğunda, özümdesin.. İlk yazın asıldığı perdeleri aralayıp yüreğime eş buldum seni!  Mızraba d...', ARRAY['Türk Edebiyatı','Şiir','Laci Gece']::text[], 8.5, '{"poet":"Laci Gece","poet_slug":"laci-gece","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iste-burada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sürgünün Yalnızlığı', 'bir-surgunun-yalnizligi-kamil-aydemir-uig8k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kanla yazılmış çıkmaz eylül''ün izi

bedenimde ince bir sızı

gecede dul kadının yalnızlığı

kendini aya sunuyor gece gizlice

ırmaklar kuruyor dudaklarımda

sevişme sıcaklığı ısıtıyor

koynunda ölülerimiz yatan toprağı

düşlerimin tırnaklarıyla

parça parça sökerken şafağı

yüreğimde bir sürgünün yalnızlığı

baharda doluya tutulmuş

çiçekli nar dalı gibi taddım yalnızlığı

kokuşmuş ilişkilerde

      insanlar kuşunlanıyor

      emek çalınıyor

      hoyratça alınıyor

      bir goncanın kızlığı

ve gecenin derinliğinde boğuluyor

      bir goncanın çığlığı

nasılda yakıştırıyor kendilerine

hırsızlar arsızlığı

şimdi moda da

                   umut hırsızlığı', 'kanla yazılmış çıkmaz eylül''ün izi bedenimde ince bir sızı gecede dul kadının yalnızlığı kendini aya sunuyor gece gizlice ırmaklar kuruyor d...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-surgunun-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasırlı Ellerinde Güvercinler 11', 'nasirli-ellerinde-guvercinler-11-kamil-aydemir-k8gv8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüreğim yoruldu susmaktan çıktı dile

benim için 

sensiz boştur saraylar bile

doldurmaya fazlasıyla yetersin

hatta artarsın dört duvar eve

güzelliklerin taşar

                      sokaklara

sokaklar denince biraz dur ve düşün

nelerimize tanıktır sokaklar

zaman gibi akarlar

ve sokaklar meydanlara çıkarlar

belki bedeli mahkumluktur sokaklarda ses olmanın

ödülü dövülmektir bazen de

bir kitabın koynuna dalmanın

oysa hayvanlarda görür

ayrıcalığı nerede insan olmanın', 'yüreğim yoruldu susmaktan çıktı dile benim için  sensiz boştur saraylar bile doldurmaya fazlasıyla yetersin hatta artarsın dört duvar eve gü...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasirli-ellerinde-guvercinler-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Sandal', 'garip-sandal-sair-karagozlum-bylhf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seviyorum mechul birini

garip bir sandalda gizli

gece karanligi denizin dibine vurarken

ayin ondördü gibi parlayan

karanlik denizin icinde

garip sandalin üzerinde

onu gördüm

dedigim gibi garip bir sandalin üzerinde

yüzü ayin ondördü gibi parlayan

bakmaya bakilmaya doyulmayan

güzelliginle kendisine öylece

baglayan.', 'Seviyorum mechul birini garip bir sandalda gizli gece karanligi denizin dibine vurarken ayin ondördü gibi parlayan karanlik denizin icinde g...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-sandal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruzigar', 'ruzigar-yusuf-ziya-eraslan-4l5vf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cigaramı sen mi içtin, 

Ben mi ruzigar? 

Neden efkarıma ortak oldun bu gün de? 

Bu sevdanın yükünü ağır mı sandın? 

Az aramadım bu sevdayı! ..

Ya alıp götürürsen; 

Ya bir daha bulamazsam,

Ne yaparım sevdasız! 

Bende senin kadar iyi olsam, 

Bir başkasının kaldıramayacağı 

Sevdanın yükünü..

Omuzlarıma almaya çalışsam 

Ne derler sonra! 

Bana da ruzigar mı derler, sanırsın! ...', 'Cigaramı sen mi içtin,  Ben mi ruzigar?  Neden efkarıma ortak oldun bu gün de?  Bu sevdanın yükünü ağır mı sandın?  Az aramadım bu sevdayı! ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Eraslan']::text[], 8.5, '{"poet":"Yusuf Ziya Eraslan","poet_slug":"yusuf-ziya-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruzigar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Kızı', 'ay-kizi-cem-bektas-v8yz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ser şu örgülü saçlarını omzuna, 

Ve gül o pespembe dudaklarınla.

Sen değil misin ki buraların ay kızı, 

Ağlamak uyuşmuyor hiç adınla...

Al eline bütün umutlarını, 

Yüzünü güneşe dön, sil hicranını, 

Sen değil misin ki buraların ay kızı, 

Sen de görmeliyim güneş sıcağını.

Paylaş onunla tüm oyuncaklarını, 

Barışıp oyunbozan ümidinle.

Sen değil misin ki buraların ay kızı, 

Sessiz sessiz yukarıdan kalbini dinle.

Ağlamak mı elindeki karakalem, 

Kaderin mi sanıyorsun çektiğin elem.

Sen değil misin ki buraların ay kızı, 

Ağlamak mı kendine yazdığın yazı.

Sen değil miydin bizim göğümüzün süsü, 

Ve sen değil miydin gecenin ışık örtüsü? 

Sen değil misin ki buraların ay kızı, 

Nasıl tek bırakırsın bunca bahtsız yıldızı.', 'Ser şu örgülü saçlarını omzuna,  Ve gül o pespembe dudaklarınla. Sen değil misin ki buraların ay kızı,  Ağlamak uyuşmuyor hiç adınla... Al e...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenti', 'beklenti-cem-bektas-d1941', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapatmam hiç kapıyı

Söndürmem ışıkları

Belki gelirsin diye...

Umudumun penceresinden, 

Her gün bir güvercin, 

Süzülüp gözler gökyüzünü...

Belki gelirsin diye.', 'Kapatmam hiç kapıyı Söndürmem ışıkları Belki gelirsin diye... Umudumun penceresinden,  Her gün bir güvercin,  Süzülüp gözler gökyüzünü... Be...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beklenti-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Sen', 'ben-ve-sen-cem-bektas-xqb02', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben gökkuşağında kırılan belirsiz bir renk, 

Güzün düşen yapraktaki yitirilmiş ahenk.

Sense okyanuslarda kayıp bir ıssız ada, 

Saf neşelerin ardındaki elemli seda.', 'Ben gökkuşağında kırılan belirsiz bir renk,  Güzün düşen yapraktaki yitirilmiş ahenk. Sense okyanuslarda kayıp bir ıssız ada,  Saf neşelerin...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-ve-sen-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir An Gelir', 'bir-an-gelir-cem-bektas-f731g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir an gelir adın düşer kalbimin yangınına, 

Saat durur, güneş batar, ben gecenin ortasında.

Karanlıkta uyku haram, sabahların firarında, 

Bir an gelir yüzün düşer gözlerimin hülyasına.

Azap denen örümcekmiş, bense onun ağında, 

Bir kelebek gibi güçsüzüm, içer beni aşk bardağında.

Sen aklıma geldiğinde tüm bu olanların ortasında, 

Kızsam da sitem etmem... bir intizar adın boğazımda.

Bir an gelir hüzündür yüzün, 

Bir an gelir sevinç.

Bir an gelir gidersin ellerimden, 

Bir an gelir gelirsin...', 'Bir an gelir adın düşer kalbimin yangınına,  Saat durur, güneş batar, ben gecenin ortasında. Karanlıkta uyku haram, sabahların firarında,  B...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-an-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İhtimal', 'bir-i-htimal-cem-bektas-dncw7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yanım doğudan doğuyor, 

Bir yanım soğuk şimal.

Bir yanım sevmez diyor...

Bir yanım bir ihtimal.', 'Bir yanım doğudan doğuyor,  Bir yanım soğuk şimal. Bir yanım sevmez diyor... Bir yanım bir ihtimal....', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-ihtimal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tesadüf', 'bir-tesaduf-cem-bektas-q4eoy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tesadüf, 

Gözlerimle gözlerinin buluşma hikayesi...

Sonbaharın sonlarında

Grileşen denizin yanındaki parkta...

Bir tesadüf, 

Yapraklara adanmış bir ömrün hikayesini

Dinliyorken ihtiyar ağaçlardan, 

Gözlerimi gözlerine yaklaştıran.

Bir tesadüf, 

Çılgın sevinçlerin üzdüğü kalbim, 

Çılgınca ağlıyorken her daim...

Bir yeşil retina ile, 

Sevmeyi yeniden sevişim...

Ve sonrasında, 

bir tesadüf, 

Cesaret ile seni seyredişim, 

Amaçsız dalgalar gibi kırılgan halinle, 

Bana cesaret verişin...

Bir tesadüf, 

Gözlerimin gözlerinle buluşma hikayesi...', 'Bir tesadüf,  Gözlerimle gözlerinin buluşma hikayesi... Sonbaharın sonlarında Grileşen denizin yanındaki parkta... Bir tesadüf,  Yapraklara ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-tesaduf-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaret', 'cesaret-cem-bektas-7ulgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizlerin de ötesinde, 

Siyah saçlı bir kız yaşarmış...

Her sabah kalkar, ilk önce saçlarını tararmış...

Çiçek denince o hatırlanırmış, 

Çünkü çiçekler kadar kırılganmış.

Fakat bir gün bir bilgeyle tanışmış.

Ve ondan cesareti öğrenmeye çalışmış...

Kız: Cesaret nedir Ey Bilge? 

Bilge: Yüreğinin gözüyle görmektir dünyayı.

Kız: Yüreğin gözü olur mu? 

Bilge: Gözü olmasa aşık olur mu? 

Kız: Peki aşk nasıl olur? 

Bilge: Kalbinin ipleri aklının elindedir. Ne zamanki o iplerden kurtulur, 

Kız: O zaman mı aşık olur? 

Bilge: Evet... O zaman aşık olur.

Kız: Peki ben beni sevenleri sevebilmek için kalbime ne demeliyim? 

Bilge: Hiçbirşey...

Kız: Nasıl yani? 

Bilge: Sadece onu dinlemelisin...

Kız: O şimdi susuyor...

Bilge: O sustuysa öldün demektir... İyice kulak vermelisin.

Kız: Ah evet... Birşeyler söylüyor...

Bilge: Anlayabildin mi kızım? Ne diyor...

Kız: Sen diyor, saçlarını kesip şu sahile bırakmalısın.

Bilge: O diyorsa yapmalısın.

Kız: Ama çılgınlık bu.

Bilge: Sudan yaratıldın ama yine hergün içtiğindir su. Peki çılgınlık değil midir bu.

Kız: Ama onu midem söylüyor.

Bilge: Bunu da kalbin.

Kız: Ama midem suyla doyuyor.

Bilge: Aşkla da kalbin... Kısacası onu dinlemelisin.

Bilge: Ey ak sakallı bilge. Seni ve kalbimi dinleyeceğim.

Kız o çok sevdiği saçlarından bir tutam koparmış.

Ve elinden usulca sahile bırakmış...

Denizden gelen ilk rüzgar, tüm saçları etrafa dağıtmış.

Kız dağılan saçların hep aynı yöne gittiğini anlamış.

Ve onları takip etmeye başlamış.

Az sonra savrulan saçlar bir dikenli tele takılmış.

Kız bundan bir öğüt almaya çalışırken, bir kuş oraya yaklaşmış.

Ölmek pahasına da olsa o saçları gagasıyla toplamış.

Epey yorulmuş ama dikenli telde hiç saç bırakmamış.

Sonra topladığı saçlarla yavaş yavaş bir şekil oluşturmaya çalışmış.

Ve en sonunda bunu başarmış. Kuşun yaptığı saçtan bir yuvaymış.

Az sonra en güzel melodilerle şakımaya başlamış.

Sesi duyan eşi çocuklarını da alıp yuvaya taşınmış...

Ve cesaretinin ödülünü mutlu bir yuvayla almış...

Denizlerin de ötesinde, 

Siyah saçlı bir kız yaşarmış...

Ve kız o gün cesaretle tanışmış.', 'Denizlerin de ötesinde,  Siyah saçlı bir kız yaşarmış... Her sabah kalkar, ilk önce saçlarını tararmış... Çiçek denince o hatırlanırmış,  Çü...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/cesaret-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha', 'daha-cem-bektas-m2dgz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah küçük kuzum, 

Ah beyaz papatyam.

Dağlarda örselenmiş

Efsunlu gözlerinle sen, 

Daha küçücük çocuksun.

Hoyrat yürekli yiğit, 

Sana yönelmiş her ümit.

Yalan şafaklarda solan, 

Efsunlu bakışlarınla sen, 

Daha dün çocuktun.

Yel yel eserken meltem, 

Tebessümünde nice matem.

Prangalardan kurtulmuş.

Efkarlı milletinle sen, 

Artık çocuk değilsin.', 'Ah küçük kuzum,  Ah beyaz papatyam. Dağlarda örselenmiş Efsunlu gözlerinle sen,  Daha küçücük çocuksun. Hoyrat yürekli yiğit,  Sana yönelmiş...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikenli Dünya', 'dikenli-dunya-cem-bektas-m4k0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kere bile bana değil, hep ellere güldün ya, 

Gül döndüğün yerde gül dünya! 

Gülen de sensin güldüren de sen, 

Güleceğim ben de sen bir gülümsesen.

Dünya! Hediyen ellere gül iken bana diken, 

Oysa bendim gülleri bağrına eken.

Senin dertlerin o kadar battı ki elime

Beddua kaldı dilimde tek kelime

Seni sevebilmek mi? Beni güldürme, 

Dikenli bile olsa sevilen sadece güldür.

Ne olur dünya... artık beni de güldür.', 'Bir kere bile bana değil, hep ellere güldün ya,  Gül döndüğün yerde gül dünya!  Gülen de sensin güldüren de sen,  Güleceğim ben de sen bir g...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dikenli-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-cem-bektas-y4925', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir küçük sevincim var

Bir de düşüm.

Bir düş kırıklığının hemen ardından

Bir yamacım var şimdi, yemyeşil.

Bir sana aşığım anladım, 

Bir de sana, özünden ötürü.

Bağışla beni ey gül, 

Düşleyemedim seni, heba ettim bu ömrü.

Buz gibi derelerde yüzmek varken, 

Çamurlar içinde oynadım hep.

Bağışla. 

Dağlardan ötürü, 

Dumanını görürdüm kızılderililerin.

Gök maviydi, duman beyaz, ben siyah.

Selamını alamazdım dağlardan ötürü.

Selam yollamayışım da bu yüzdendir.

Dağları deldim şimdi ey mis kokulum.

Altından geçtim gökkuşağının.

O yedi renkliydi, yamacım yeşil, ben...

Ben binbir renkteyim şimdi.

Bir küçük sevincim var bu yüzden.

Bir de düşüm.', 'Bir küçük sevincim var Bir de düşüm. Bir düş kırıklığının hemen ardından Bir yamacım var şimdi, yemyeşil. Bir sana aşığım anladım,  Bir de s...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dus-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Eğlence...', 'en-buyuk-eglence-cem-bektas-vstgx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En büyük eğlence...

Eskiyip kopan bir takvim yaprağı

Gibi umutsuz bekleyip yorgun düşen

Bir kalbi taşımak göğsünde senelerce.

Çiçek çiçek dolaşan arıların 

Kendi ballarına parmak çalacakları

Parmakları yokken, 

Ve bizim midemize hizmet ettikleri halde, 

Tek parmağımızla ezeriz görünce.

Bu kadar güçsüz ve bu kadar erdemli, 

Bir rakibi ezince hissedilendir, 

En büyük eğlence.

Ölümü unutturmak yaşlıya, 

Ve yaşlılığı unutturmak gence, 

İşte bu, 

En büyük eğlence.

Cehennem bileti satan, 

Bir karaborsacıyken günahlar, 

Kendini şanslı hissedip gülmektir, 

Elinde tuttuğun bileti gördükçe.

Cennet savan zırhlarının, 

İçinde saklanan şeytan ölünce, 

Kendini adayabilmektir geleceğe, 

En büyük eğlence.', 'En büyük eğlence... Eskiyip kopan bir takvim yaprağı Gibi umutsuz bekleyip yorgun düşen Bir kalbi taşımak göğsünde senelerce. Çiçek çiçek do...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/en-buyuk-eglence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğildim', 'egildim-cem-bektas-2bdra', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Esti de bahar yeliyle

Gitti yakalayamadığım ömrüm.

Düştü yapraklarım, soldum elinde.

Eğildim de öptüm toprağı.

Sazlıkların ortasında

Bir damla su idim, kurudum.

Kurudu nehirlerim, sustum elinde.

Eğildim de öptüm denizi.

Semanın en engin noktasında, 

Bir kuş idim vuruldum.

Kırıldı kanadım, öldüm elinde.

Eğildim de öptüm gökleri.', 'Esti de bahar yeliyle Gitti yakalayamadığım ömrüm. Düştü yapraklarım, soldum elinde. Eğildim de öptüm toprağı. Sazlıkların ortasında Bir dam...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/egildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fallardaki Aşk', 'fallardaki-ask-cem-bektas-3wjqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kahve fincanlarında aradım, 

Güzel prensesimi, 

Bir yol var diyordu falım, 

Gidecekmişiz tutarsan elimi.

Elimi tuttuğunda baktım, 

Avucunun içine, 

Çok sevmezsen beni tatlım

Ayrılırmışız üç vakit içinde.

Sarı papatyalara sordum seni, 

Sevmiyor diyorlar, 

Söyle sevmiyor musun beni? 

Yoksa yalancı mı papatyalar?', 'Kahve fincanlarında aradım,  Güzel prensesimi,  Bir yol var diyordu falım,  Gidecekmişiz tutarsan elimi. Elimi tuttuğunda baktım,  Avucunun ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fallardaki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden Sabaha', 'geceden-sabaha-cem-bektas-bmhik', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum; 

Gecenin sabahı düşündüğü gibi.

Seni düşünüyorum kapatıp gözlerimi.

Yutkunuyorum ilkin.

Yarınları düşünmek isterken, 

Sana varıyor düşüncem.

Seni arıyorum; 

Çölün çağlayanları aradığı gibi.

Seni arıyorum geceden sabaha, 

Mühürleniyorum ilkin.

Yıldızları aramak isterken, 

Sana varıyor arayışım.

Seni seviyorum, 

Papatyanın baharı sevdiği gibi, 

Çiftçinin rahmeti sevdiği gibi, 

Daha, çok daha öte hatta.

Seni seviyorum, sevgini hak etmesem de.

Sonra bakıyorum, 

Sen bir toz zerresi gözüyle bakmıyorsun

Sahildeki kumlara, 

Buna benim ruhum dayanamıyor.

Bir yana bükülüyor boynum.

Ağlıyorum, geceden sabaha.', 'Seni düşünüyorum;  Gecenin sabahı düşündüğü gibi. Seni düşünüyorum kapatıp gözlerimi. Yutkunuyorum ilkin. Yarınları düşünmek isterken,  Sana...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geceden-sabaha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Geceye Dönerdi', 'gun-geceye-donerdi-cem-bektas-u3mww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acı bir sitemin ifadesidir gözümün nemi, 

Yavaş yavaş süzülüp, parçalayan sinemi.

Sen... kıyımdan uzaklarda bir gemi, 

Dem... uzaklardan sana ağlama demi.

Elimi eline koyup ağlaşsam, 

Yüreğim bir eceye boyun eğerdi.

Hüznümü güneşle paylaşsam, 

Gün geceye dönerdi...', 'Acı bir sitemin ifadesidir gözümün nemi,  Yavaş yavaş süzülüp, parçalayan sinemi. Sen... kıyımdan uzaklarda bir gemi,  Dem... uzaklardan san...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gun-geceye-donerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlatırdı', 'hatirlatirdi-cem-bektas-n9mbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ne güzel ağlardın

Ve gülüşün de bir o kadar güzel.

Özlemin susuz ceylanları, 

Hüznün söylenmemiş şarkıları, 

Cesaretin rüzgara direnen yaprakları

hatırlatırdı...

Seni birisi sorduğunda, 

Öldü demek ne acıydı.

Sessizce gömülüşün toprağa, 

Mistik bir duygulanışı

hatırlatırdı...', 'Sen ne güzel ağlardın Ve gülüşün de bir o kadar güzel. Özlemin susuz ceylanları,  Hüznün söylenmemiş şarkıları,  Cesaretin rüzgara direnen y...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hatirlatirdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sabah', 'her-sabah-cem-bektas-yi9vr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dört duvar arasında bir pencere

Her sabah dolar odam güneşle.

Yaşam telaşı erken başlar evimde, 

Her sabah dolar kafam endişeyle.

Dört duvar arasında bir kapı, 

Her sabah dolar odam güneşle.

Gazetemi getirince yaşlı kapıcı

Her sabah dolar gözüm hüzünle.

Dört duvar arasında bir lamba.

Oysa her sabah dolar odam güneşle.

Isıtamaz omzumu şu yırtık aba, 

Her sabah donarım mevsimle.

Dört duvar arasında bir adam, 

Her sabah ölür adam güneşle.

Yalnızlıkla beraber artınca gam, 

Evlenir adam elem denen  eşle.', 'Dört duvar arasında bir pencere Her sabah dolar odam güneşle. Yaşam telaşı erken başlar evimde,  Her sabah dolar kafam endişeyle. Dört duvar...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-sabah-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sahur Ay Işığı', 'her-sahur-ay-isigi-cem-bektas-lkssm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sahur ay ışığı, 

Yakamozlanır gözlerinin mavi denizinde.

Bir hayal sessizliğinde bahar, 

Mırıldanır sana yazılan şarkıları.

Sen her mevsim bir başka çiçeksin.

Bazen hanımeli, bazen atlasçiçeğisin.

Yapraklarına ilk çiğ değdiğinde, 

İhtiyarlaşır zaman, yaşlanır ölüm.

Ama sen hala taptazesin.

Çoraklaşırken bile dudaklarımda ismin, 

Ne güzeldir gülmelerin.

Her sabah ezan sesleri, 

Yankılanır kalbinin derininde.

Muştu içerisinde yelkovankuşları, 

Mırıldanır sana yazılan şarkıları. 

Bir sevinç tümcesiyken dilimde ismin, 

Elmas parıltısı kadar kalıcıdır sadeliğin.

Ve sen ne güzelsin, 

ve ne güzeldir gülmelerin.', 'Her sahur ay ışığı,  Yakamozlanır gözlerinin mavi denizinde. Bir hayal sessizliğinde bahar,  Mırıldanır sana yazılan şarkıları. Sen her mevs...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/her-sahur-ay-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Zamanki Mucizeler', 'her-zamanki-mucizeler-cem-bektas-qjkbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep bir mucize bekliyorsan...

Tabiatın sihrini çözecek bir anahtar

Ve fısıltı şeklinde kulağına dokunan

Bir sır istiyorsan... dinle! 

Her bulut ağlamaklıdır sabahları, 

Ve her yağmur bir gözyaşı.

Her rüzgar zorbadır kovalarken bulutları, 

Ve her Nisan göklerin hicran ayı.

Gökyüzü mavidir her zaman...

Denizler ise gökyüzünün aynası.

Her çalışanın alnı terlidir, 

Ve her insan alnındaki teri kadar değerlidir.

Belki buzlar da terler güneşte bekledikçe.

Ama emeksiz terleyen buhar olur ve erir.

Tüm geceler karanlıktır, 

Ama her zifir geceyi 

aydınlatan bir sabah mutlaka vardır.

Açıldığında gökleri deler ellerin duası, 

Her duadadır, Musa’ nın gizemli asası.

Bir sır istiyorsan, 

Önce kendini dinlemelisin.

Ve mucize dediğin, 

kendinsin!', 'Hep bir mucize bekliyorsan... Tabiatın sihrini çözecek bir anahtar Ve fısıltı şeklinde kulağına dokunan Bir sır istiyorsan... dinle!  Her bu...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-zamanki-mucizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyet Yarası', 'hurriyet-yarasi-cem-bektas-7ljp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşlar gibi özgür olmayı istedim bugün.

Onlar gibi kanatlarım olmasa bile.

Uçamasam da onlarla aynı şehre, 

Yüreğimiz bir atsın istedim.

Aynı ağacın gölgesine sığınıp, 

Aynı kuyudan su içsek istedim.

Özgürlüğü soluklayıp ciğerlerimize, 

Ve ölümü hapsedip zindanlara, 

Haydi kuşlar! Maveraya gidelim.

Kuşlar gibi özgür doğmayı istedim bugün, 

Çünkü onlar suçsuzdu... suç işlerken bile.

Uçuşurlardı baharı müjdeledikleri diyarlara.

Onlarda bendeki delilik vardı, 

Bende de onlardaki hür yürek.

Bir çift de göz vardı gece karası, 

Gözlerim aşkın dayanılmaz gamı ile ıslaktı.

Ve yasak sözlerimdeki hürriyet yarası', 'Kuşlar gibi özgür olmayı istedim bugün. Onlar gibi kanatlarım olmasa bile. Uçamasam da onlarla aynı şehre,  Yüreğimiz bir atsın istedim. Ayn...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hurriyet-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Adamlar', 'i-yi-adamlar-cem-bektas-jw8cq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim masalım yazılı değilken, 

Sen uçmaya çalışıyordun.

Oysa cadılar süpürgesiz uçamazdı.

Ve ben elimde bir kalem, 

Senin uçabilmen için, 

Kendi masalımızı yazıyordum.

Ateşli dağın eteğinde, 

Masallar ülkesi diye bir diyar varmış.

Bu ülkenin geleneğinde, 

Hep iyi adamların kazanması şartmış.

Benim masalımda sen peri oluyordun önce, 

Bense prens olmayı bekleyen kurbağa.

Sonra sen beni öpünce, 

Devlerin elinde sürgün ediliyordum ateşli dağa.

Zar zor kurtuluyordum Ejderhaların elinden, 

Sonra bir cine rastlıyordum yoldayken, 

Dile benden ne dilersen diyordu, 

Ve ben sadece seni diliyordum.

Cin beni senin sarayına getirdiğinde, 

İyi adamlar kaybediyordu ilk kez.

Sen elinde bir kalem, bütün hainliğinle, 

Masalın benli olan kısımlarını karalıyordun.

Cadılar süpürgesiz uçamazmış.

Oysa sen süpürgesiz bir cadı idin.

Ve ben senin uçman için, 

Saçımı süpürge etmiştim.', 'Benim masalım yazılı değilken,  Sen uçmaya çalışıyordun. Oysa cadılar süpürgesiz uçamazdı. Ve ben elimde bir kalem,  Senin uçabilmen için,  ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/iyi-adamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-cem-bektas-i7ct7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen soğuk iklimlerin nazlı çiçeği

Aç bugün... aç baksana mevsimin geldi.

Sev biraz... Sev hayat suyun sevgidir.

Erittiğin karlar değil kalbimdir.

Oysa ben, 

Sen istesen...

Gece yıldızlarını toplayan bir ayışığı olabilirdim, 

Ve topladığım yıldızları ellerine verebilirdim.

Ben bir tanyeliydim, 

Sen gel desen, 

Sabahları perdene esebilirdim.

Ben bir gemiydim, 

Sen yer versen, 

Kalbine demirlerdim.

Sen bir mum ateşisin, 

Üflesem sönersin...

Sen bir bahar çiçeğisin, 

Kış bitti... açabilir misin.

Sen bir kardelensin, 

ama

Kalbimi delen de sensin...

 Oysa ben, 

Sen istesen...

Gece yıldızlarını toplayan bir ayışığı olabilirdim, 

Ve topladığım yıldızları ellerine verebilirdim.

Sen soğuk iklimlerin nazlı çiçeği

Aç bugün... aç baksana mevsimin geldi.

Sev biraz... Sev hayat suyun sevgidir.

Erittiğin karlar değil kalbimdir.', 'Sen soğuk iklimlerin nazlı çiçeği Aç bugün... aç baksana mevsimin geldi. Sev biraz... Sev hayat suyun sevgidir. Erittiğin karlar değil kalbi...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kardelen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Rüzgarından...', 'kendi-ruzgarindan-cem-bektas-si5m4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi Rüzgarından..

Sen hayat elbisemde bir desen

Hayat desem... Hayat da sen.

Pembe elbisenle sen, 

bir gülsen, 

Üşütür beni ve seni 

Senden esen, 

bir meltem...

Ey kendi rüzgarıyla üşüyen, 

Nasıl da ürkeksin sevdim derken...

Sen böyle gecikmiş iken..

Ben erken açtım... bu mevsim erken.

Ve işte biz, 

Hayatın kaçırdığı... mutlu aşk filmlerinden.

Sen hayat bahşedersin sevdim desen, 

Sevdim desem... Sevmek de sen...', 'Kendi Rüzgarından.. Sen hayat elbisemde bir desen Hayat desem... Hayat da sen. Pembe elbisenle sen,  bir gülsen,  Üşütür beni ve seni  Sende...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendi-ruzgarindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanan', 'kiskanan-cem-bektas-vwow7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Işıltılı bir günaydın öpücüğü ile, 

Usulca uyandırdım seni uykundan.

Rüyalarının ürkütücü karanlığıydı, 

Alnını gümüş rengi terlere boğan.

Sen gözünü açınca uyandı, 

İçimde uyuyan kıskanç kahraman...

Seni alnına düşen, 

Ter damlalarından bile kıskanan.

Bir ben sevmeliydim seni  bu yeni günde, 

Ve bir bana yurt olmalıydı kalp odan.

Bir sen demeliydim ki yüreğimden, 

Yorulsun akrep, yorulsun yelkovan.

Bir yağmur yağmalıydı dışarıda, 

Şemsiyen olmalıydım üstünde ıslanan.

Öyle bir sevmeliydin ki bu yeni günde, 

Ve bir bana gülmeliydi gözlerindeki mercan...

Bir dilek tutmalıydın ki içinden, 

Ve bir beni dilemeliydi sabah duan.

Sen uyandırdığım bir güneş olmalıydın, 

Yalnız benim için doğan.

 Işıltılı bir günaydın öpücüğü ile, 

Usulca uyandırdım seni uykundan.', 'Işıltılı bir günaydın öpücüğü ile,  Usulca uyandırdım seni uykundan. Rüyalarının ürkütücü karanlığıydı,  Alnını gümüş rengi terlere boğan. S...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kiskanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köhne Balıkçı Tekneleridir Şahidim', 'kohne-balikci-tekneleridir-sahidim-cem-bektas-3jwce', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köhne balıkçı tekneleridir şahidim, 

Ben bu denizlerde hiç ölmedim.

Her girdap çağırdıysa da beni, 

Şu yosunlar da şahittir ki, 

Hiç dibe inmedim...

Denizler yalancı yeşillenir, 

Poyraz yalandan eser.

Boşver o yalancıları, 

Sorsan çok öldü buralarda derler...

Sen denizin kolyelerine kulak ver, 

Her ıssız ada durağım olmuştur benim, 

Her limanda azcık sıcaklığım vardır, 

Dinlenirken bıraktığım bir yorgunluk, 

Bir umutsuzluk da vardır her limanda.

Ben de biraz sarhoşlanırım belki, 

ama

Nasıl ki her balık sendeler gün ışığında.

Ben de o kadar ölüyüm anca.

Şu gözümden düşen yaşlar mı? 

Onlar, 

Hırçın dalgaların uslanmaz evlatlarıdır.

Bir miras gibi saklarım her aşk yaramı, 

Çünkü onlar yaşadığımın kanıtıdır.

Ne zaman ki

Aşkımı bir kalp yarasıyla değiştirdim, 

İşte o andan beri

Yarama tuz basan şu suları yurt edindim.

Ve

Köhne balıkçı tekneleridir şahidim, 

Ben bu denizlerde hiç ölmedim.', 'Köhne balıkçı tekneleridir şahidim,  Ben bu denizlerde hiç ölmedim. Her girdap çağırdıysa da beni,  Şu yosunlar da şahittir ki,  Hiç dibe in...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kohne-balikci-tekneleridir-sahidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesiniz', 'nerdesiniz-cem-bektas-2oh50', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kiraz küpem... elma şekerim... misketlerim...

Bahar çiçeklerinin içinde saklanan, 

Çocuk yüreğim...

Çalışan teyzelerden saklanarak çilek toplamalar, 

Çilek lekesi yüzünden yediğim sopalar, 

Toplayıp fal uğruna yolduğum papatyalar.

Önce masmavi göklerde rakseden, 

Sonra tellere takılan uçurtmalarım...

Buzları emdiğim, kar yediğim kış gündüzleri, 

Duvarlara çizdiğim çocuk yüzleri, 

Hasta olmalarım... iyileşmelerim.

Kiraz küpem... elma şekerim... misketlerim...

“Abimi dövebilecek kadar güçlensem, 

Anneme ev alabilsem...

Babam kadar uzun boylu olsam, 

Ama kardeşlerim kadar da küçük ve sevimli kalsam.”

Dediğim günlerim...

Kiraz küpem.. elma şekerim.. misketlerim...

Çamurdan yaptığım otomobillerim...

Çayırdan aşağı yuvarlanmalarım...

Koca otları ezerek yaptığım ilk evim, 

Bayram harçlıklarıyla aldığım kızkaçıranlarım, 

El öpmelerim... bayramlıklar...

Her pedalda yağ sıçratan bisikletim, 

Yağ lekesi yüzünden yediğim sopalar..

Ördekli tişörtüm, ilk öğretmenim, ilk aşkım, 

Okul günlerim... simitlerim... güzel yazı defterim...

Neredesiniz? 

Kiraz küpem.. elma şekerim... misketlerim...', 'Kiraz küpem... elma şekerim... misketlerim... Bahar çiçeklerinin içinde saklanan,  Çocuk yüreğim... Çalışan teyzelerden saklanarak çilek top...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/nerdesiniz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ninni', 'ninni-cem-bektas-tv3a2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sesin nefesin kesiliyor usulca, 

Sıcaklığın yitiyor ten yurdunda, 

Uyuyor musun? 

Titriyorsun odanın sert ayazında, 

Yorganın yetişmez oldu ayağına, 

Büyüyor musun? 

Düş bahçelerinin allı duvarlarına, 

Bir şiir yazılıyor rüyanda, 

Görüyor musun? 

Gece ninniler doluyor koynuna, 

Melekler adını üflüyor kulağına, 

Duyuyor musun? 

Uyuyor büyüyorsun, 

Tıpış tıpış yürüyorsun.

Titriyorsun odanın sert ayazında, 

Yorganın yetişmez oldu ayağına, 

Büyüyor musun? 

Düş bahçelerinin allı duvarlarına, 

Bir şiir yazılıyor rüyanda, 

Görüyor musun? 

Gece ninniler doluyor koynuna, 

Melekler adını üflüyor kulağına, 

Duyuyor musun? 

Uyuyor büyüyorsun, 

Tıpış tıpış yürüyorsun.', 'Sesin nefesin kesiliyor usulca,  Sıcaklığın yitiyor ten yurdunda,  Uyuyor musun?  Titriyorsun odanın sert ayazında,  Yorganın yetişmez oldu ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ninni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O da Evimde Hala', 'o-da-evimde-hala-cem-bektas-lse1u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni uykudan hemen önce

Ağlayarak andığımda, 

Hasretin taşıyor rüyalara...

Bir garip hüzün mevsimi

Üşütüyor iliklerimi.

Gecenin siyah zülüflerinde, 

Bir keder damlası oluyor, 

Düşüyorsun gözlerimden.

Ve kaç gece vardır ki bilemezsin.

Odanın içinde dört döndüğüm.

Kaç sabah vardır ki yemin bozup, 

Tekrar resmini ellediğim.

Seni nasıl bir sevmişim, 

Nasıl bir değer vermişim ki, 

Kapının ucunda çıkarıp gittiğin, 

O kırmızı terliklerin, 

Daha hala aynı yerindedir.

En son onu ısıttı diye tenin, 

Bugüne kadar hiç ellemedim.

Bir de küpelerin var, 

Hani o senin inci küpelerin.

Nasıl unutmuşsan giderken, 

O da evimde hala.

Ver her baktığımda o hatıra, 

Canlanır durur gözlerimin ucunda.

Sen doğum gününü unuttum diye, 

Üzülüp sitemle bakarken gözlerime, 

Bir çırpıda çıkıvermişlerdi cebimden, 

Ve beni hiç unutmaman dileğiyle, 

Kulaklarını süslemişti o inci küpen.

nasıl unutmuşsan giderken, 

O da evimde hala.', 'Seni uykudan hemen önce Ağlayarak andığımda,  Hasretin taşıyor rüyalara... Bir garip hüzün mevsimi Üşütüyor iliklerimi. Gecenin siyah zülüfl...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/o-da-evimde-hala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpücük', 'opucuk-cem-bektas-5xyfm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayran kalıp izlerken seni, 

Bir de vurdu beni o gülücük.

Siyah saçların örgülerken, 

Kalbimi bölük bölük.

Aşk denen bilmem bu mu? 

Yüreğimde ağır bir yük.

Sonra senin sesini duydum, 

Ansızın geldi bir öpücük, 

Başın önde döneceğim dedin, 

Gidiyorum bir günlük.

Dönmedin bir daha, elimde kaldı, 

Parmağına takacağım yüzük, 

Ve hala saklıdır kalbimde, 

Ansızın gelen o öpücük.', 'Hayran kalıp izlerken seni,  Bir de vurdu beni o gülücük. Siyah saçların örgülerken,  Kalbimi bölük bölük. Aşk denen bilmem bu mu?  Yüreğimd...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/opucuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-cem-bektas-5rd00', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Portakalı soydum, başucuma koydum, 

Ben bir aşk uydurdum.

Oyunbozan aşk hayalleri yüzünden, 

Ellerinde oyuncak oldum, 

Ben dört mevsim kışım, sen yazımsın.

Zifir geceler gibi karayım, sen beyazımsın.

Yuvasız bir meyve kurduyum, sen kirazımsın, 

Sana bir oyun lazım, bana sen lazımsın.', 'Portakalı soydum, başucuma koydum,  Ben bir aşk uydurdum. Oyunbozan aşk hayalleri yüzünden,  Ellerinde oyuncak oldum,  Ben dört mevsim kışım...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oyun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemişim', 'ozlemisim-cem-bektas-lbuh3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi zamana isyan edesim geliyor, 

Uykusuz bekleyişlerin yorgunluğundan belki...

Sevgili diye bir şarkı söyleyesim geliyor, 

Nefesim hasret alevi, 

Özlemişim belki...

Şimdi resmine sarılasım geliyor, 

Cennete yürüyen bir günahsız masumiyetiyle.

Dudağıma beddualar geliyor, 

Kıyamıyorum, 

Sevmişim demek ki...', 'Şimdi zamana isyan edesim geliyor,  Uykusuz bekleyişlerin yorgunluğundan belki... Sevgili diye bir şarkı söyleyesim geliyor,  Nefesim hasret...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ozlemisim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçekleri', 'kir-cicekleri-cem-bektas-h0wdg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah beyazlığında

solmuştur gece çoktan, 

Ve benim rüyalarım, 

Rüyalarımdaki sahte sabahlarım, 

Dedim ya solmuştur, 

solmuştur çoktan...

Solsa da tüm geceler, 

Solmamalı sabah çiçekleri.

Bengisu diye köklerine, 

Gözyaşı serpmeliler.

Silinirse bir gün bu şehir dumanları, 

İşte o zaman sen güvercin yüreğim...

Sen duman karasıyla karalanırsın...

Bu şehir ki sen ilk burada yanmıştın.

Seni buraya gömmeliler...

Seni buraya gömmeliler, 

Bu tepe senin için en uygun yer, 

Çünkü buradan kolay görürsün çiçekleri.

Sabah çiçeklerini.

Hadi ağlayalım, 

Ağlayalım siyahlım, 

Yakışmıyor bize gülmeler', 'Sabah beyazlığında solmuştur gece çoktan,  Ve benim rüyalarım,  Rüyalarımdaki sahte sabahlarım,  Dedim ya solmuştur,  solmuştur çoktan... So...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kir-cicekleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
