INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-ceyhun-yilmaz-vv71p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuturum

Unutmak zor değil

Unutmak acı

Unutmak zor değil

Unutmak yazık

Unutulmaz kimse yok bende

Bir sana kıyamadım

Gücüm yetmedi seni yok saymaya

Kollarımı açtığım kadar unuttuğumsun

Açamadığım kadar özlediğim

Benim Unuttuğum Kadarını Sen Özler misin?', 'Unuturum Unutmak zor değil Unutmak acı Unutmak zor değil Unutmak yazık Unutulmaz kimse yok bende Bir sana kıyamadım Gücüm yetmedi seni yok s...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/unutmak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden', 'eskiden-ceyhun-yilmaz-3bb09', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden buralara güneş doğardı

Kuş seslerini kessen

Kuşlar kızardı

Yüzümde tebessüm bahardı

Senli şarkılarım vardı benim

Bir gittin

Gidişinle yağmur ağladı', 'Eskiden buralara güneş doğardı Kuş seslerini kessen Kuşlar kızardı Yüzümde tebessüm bahardı Senli şarkılarım vardı benim Bir gittin Gidişinl...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eskiden-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yine Eski Şiir', 'siir-yine-eski-siir-onder-karadag-km7es', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir Yine Eski Şiir

Eskiden de yazmıştım  ben bu şiiri 

	yürümüştü alanlara patikalar

 		tırmanmıştı ucuna  düşlerin

	uslanmazdı; kan ter  içindeki kalemim.

				

Oysa,  bu denli acıyıp üşümemişti ellerim.

Şiir  yine eski  şiir

           yine alı  al  moru mor çiçeklerin, 

	   ama, böylesine  yokuş,  böylesine  derin

            	             hem  yakıcı hem  serin

              		    hülyalı  akışında  aşk nehrinin

           kanamazdı  kan goncasında  şiir

			şiir gibi bir gülün.

Böyle çığlık çığlık  ürpermedi  dizelerim.

Şimdi,  ikindi vaktinde gün

              yanı başımda akşam, 

	      sabaha karşı, geceleyin... 

Bu denli  demlememişti hiç bir  sevgiyi  şiirlerim.

			 Haziran 2001 Abydos', 'Şiir Yine Eski Şiir Eskiden de yazmıştım  ben bu şiiri  	yürümüştü alanlara patikalar  		tırmanmıştı ucuna  düşlerin 	uslanmazdı; kan ter  i...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/siir-yine-eski-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke hapiste olsam', 'keske-hapiste-olsam-zubeyir-sasmaz-xx92m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keşke hapiste olsam, ekmek elden, su gölden

yan gelip yatsam, gelecek kaygısına düşmeden

   Ne fark ediyor ki; 

   Kim sorarsa özgürüz. 

   İstediğimize bakar istediğimizi görürüz.

Mutluluğa ermek için; 

              ya veli olmak gerekiyormuş ya da deli

Allah ''ın yoluna tam giremedim, olamadım bir veli.

Aptal sayılmam Allah''a şükür, hele hiç değilim deli.

Kim sorarsa özgürüz. 

doğruyu söylersek; olduğumuz yerden sürülürüz.

Her gün hiç durmadan hep geleceğimizi düşünürüz.

Hayatımızı üstlerin iki dudağı arasında sürdürürüz.

Sorarlarsa; söyleyin '' BİZ ÖZGÜRÜZ''.

İnsan hakları, ne menem bir şeyse; 

Onu hep gazetelerde, dergilerde, yasalarda

yazılı olduğunu görürüz.

Bir genç, bir pankart açsa,18 yıl hapiste çürütürüz.

Bir teğmen alışamadım dese, 

delir di der, askerlikten sürdürürüz.

İnsan hakları, ne menem bir şeyse; 

Onu sadece yasalarda görürüz.

Keşke bu günlerde hapiste olsam; 

Kendime bahaneler uydursam, 

Ulaşamıyorsak istediklerimize

hepsini hapiste olmamıza yorsam', 'Keşke hapiste olsam, ekmek elden, su gölden yan gelip yatsam, gelecek kaygısına düşmeden    Ne fark ediyor ki;     Kim sorarsa özgürüz.     ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/keske-hapiste-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-orhan-balta-i8yo2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen; 

buyuk okyanusdan daha derin

kuytu bir orman kosesi kadar serin

kelebek kadar narin

hercai bir menekse kadar guzelsin.

Ben; 

ruzgarda kuru bir yaprak misali savrulan

cehenmem atesllerinde kavrulan

sevdan ile yasayan

biriyim iste.

