INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtiyar', 'bahtiyar-zubeyir-sasmaz-6rk6v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahtiyar saymak için kendimi

                                Ne han isterdim, ne de hamam

Başımı sokacak, küçücük bir ocak.

                              anlayışlı bir eş, bir de  yavrucak

Çok şey istemezdim bahtiyar olmak için,        ancak.

Bir düzen isterdim, kimseler

                                 gelecekten kaygı duymayacak.

Yaşadığım yerlerde, herkes birbirine saygı duyacak

Her yer vatan için çalışan dürüstlerle dolup taşacak

Yaşadığım yerlerde;     Hak ve adalet tek güç olacak.

İşte ben böyle bahtiyar olurdum ancak', 'Bahtiyar saymak için kendimi                                 Ne han isterdim, ne de hamam Başımı sokacak, küçücük bir ocak.                 ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bahtiyar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-i-brahim-cagri-saglik-wisj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatsam sana bilemiyorum

Bir başka görüyorum hayatı artık

Hergün, her an seni özlüyorum

Ruhum senin, aşk senin eserin artık

Ellerin başka güzel, yüzün bir başka

Her an olsan yanımda, sıkılmam inan

İlk defa inanıyorum belki aşka

Ateş sensin, çıran ben seninle yanan

Yürüsek bu yolda beraber el ele

Ben seninle mutlu, sen benimle mesut

Süslesek birlikte yaşamı sevgiyle

Seninle, gelecek en büyük umut

Her gece nöbet gibi beklerim seni

Telefonun başında, sessiz ve sakin

Biliyorum anlamayacaksın beni

Anlatamamki, çok büyük senin sevgin', 'Nasıl anlatsam sana bilemiyorum Bir başka görüyorum hayatı artık Hergün, her an seni özlüyorum Ruhum senin, aşk senin eserin artık Ellerin b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duygular-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-i-brahim-cagri-saglik-2lxmu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte yine bir parktayım

Yalnızlığım, sensizliğim ve korkumla birlikte

Ağaçların ninnisini

Ve rüzgarın masalını dinliyorum

Uzaktan bir şehrin canlılığı duyulmakta

Geçen arabaların motor sesleri

Keskin bir soğuğun acısından çok

Sensizliğin acısını çekiyorum

1996', 'İşte yine bir parktayım Yalnızlığım, sensizliğim ve korkumla birlikte Ağaçların ninnisini Ve rüzgarın masalını dinliyorum Uzaktan bir şehrin...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aci-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Değilim', 'pisman-degilim-dost-tutkunu-lp11q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasretin içimde bir kor olsa da

Seni sevdiğime pişman değilim.

Hayalle yaşamak çok zor olsa da

Seni sevdiğime pişman değilim.

Şu gönül bahçemde açan bir gülsün

Güllerin üstüne konan bülbülsün

Sönmeyen volkanda yanan bir külsün

Seni sevdiğime pişman değilim.

Yıllarca arayıp sormasan bile

Bu aşka bir isim koymasan bile

O ceylan gözlere doymasam bile

Seni sevdiğime pişman değilim.

Bu gönül sevgiye inandı senle

Bir yudum mutluluk aradı sende

Fark etmez sen beni hiç sevmesen de

Seni sevdiğime pişman değilim.

Gece tüm sırları açığa vursun

Gülümseyen resmin karşımda dursun

Dilerim ömrünce mutlu olursun

Seni sevdiğime pişman değilim.

Bir gün gelin olup evlensen bile

Sevip de yeniden sevilsen bile

Bu garip oyunda yenilsem bile

Seni sevdiğime pişman değilim.

Aşk bahçemde açan o gül solmasın

Güzel gözlerine hüzün dolmasın 

Varsın da o benim gülüm olmasın

Onu sevdiğime pişman değilim.

[email protected]', 'Hasretin içimde bir kor olsa da Seni sevdiğime pişman değilim. Hayalle yaşamak çok zor olsa da Seni sevdiğime pişman değilim. Şu gönül bahçe...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/pisman-degilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay ve Sen', 'ay-ve-sen-i-brahim-cagri-saglik-aln5e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay kızıl doğdu tepenin ardından

Dolunaydı

Uzaktan tatlı bir name okur gibi

Esti meltem

Ve elimde sidara çakır keyifken

Sensizliğe sövmek geldi içimden

Ayağa kalktım

Yürüdüm kumsalda bir boy

Rüzgarda uçuşan kum taneleri kadar bile

Özgür olamadık biz seninle

Ay kızıl battı tepenin ardından

Yarım aydı

Ağaçların dallarında eridi meltem

Ve elimde sigara, öakır keyifken

Sensizliğe sövmek geldi içimden

1996', 'Ay kızıl doğdu tepenin ardından Dolunaydı Uzaktan tatlı bir name okur gibi Esti meltem Ve elimde sidara çakır keyifken Sensizliğe sövmek gel...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ay-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dosta', 'bir-dosta-i-brahim-cagri-saglik-smbro', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Selam söyle İstanbul’a

Selam söyle benden kardaş

Boyun büktürürse sıla

Sarıl mürekkebe sırdaş

Sıkılmakta canım şu an

Gönlümde hatırası var

Şu garip Çağrı, fıkaran

Hem derdi hem dertlisi var

Gittin beni yalnız koydun

Bunca sıkıntı içinde

Başından beri dostuydun

Bu garibin çevresinde

Şimdi ben sensiz burada

Söyle kimle konuşayım

Hep o ağacın altında

Acep kimle buluşayım

Dostsuz kaldım yetiş ey can

Uzat bana yardım eli

İçimde binbir heyecan

Bekliyorum gelişini

Selam söyle İstanbul’a

Selam söyle benden kardaş

Boyun büktürürse sıla 

Sarıl mürekkebe sırdaş

1992', 'Selam söyle İstanbul’a Selam söyle benden kardaş Boyun büktürürse sıla Sarıl mürekkebe sırdaş Sıkılmakta canım şu an Gönlümde hatırası var Ş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-dosta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz de seninle yaşayacağım', 'sensiz-de-seninle-yasayacagim-dost-tutkunu-5i15s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun çok acı verecek bana

İsminle gönlümü avutacağım

Sen olmadan geçen günlere inat

Sensiz de seninle yaşayacağım.

Her gece gönlüme elem dolsa da

Sanma ki ben seni unutacağım

Aramızda engel yollara inat

Sensiz de seninle yaşayacağım.

Gözlerine hasret geçse de zaman

Aklımda olacak hayalin her an

Sızlayan kalbimin durduğu o an

Sensiz de seninle yaşayacağım.

Olmasan ne yazar benim yanımda

Dolaşır hep ismin her an kanımda

Nehirler olsa da senle aramda

Sensiz de seninle yaşayacağım.

Bir yudum su gibi hasretim sana

Bakışlarım susuz bakışlarına

Bir selamı da çok görsen de bana

Sensiz de seninle yaşayacağım.

Hasrete dayanmak çok zor olsa da

Bu yükü ömrümce taşıyacağım

Aramızda engel yıllara inat

Sensiz de seninle yaşayacağım.

Ruhumuz sonsuza eriştiği gün

Sanma ki ben seni unutacağım.

Tanrı''nın mahşeri yarattığı gün

Sensiz de seninle yaşayacağım.

[email protected]', 'Yokluğun çok acı verecek bana İsminle gönlümü avutacağım Sen olmadan geçen günlere inat Sensiz de seninle yaşayacağım. Her gece gönlüme elem...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sensiz-de-seninle-yasayacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-ahmet-agdere-6tph4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinde bulurum düşlerimi; 

Kat kat tabakaları arasında.

Bir o yana bir bu yana savrulurken

Sarhoş misali, gözlerinin karşısında...

Her tabaka ayrı bir esrar, 

Kaybolur yüreğim her varışında.

Bilmem neden tüm gün titreme tutar, 

Gözbebeginin kendisini tek sarsmasında...

Sonra bir gün farkına vardım, 

Adın varmış benliğimin yaftasında.

Melekler adınla yer tutarmış, 

Alın yazımın her bir karışında...

Düşünmemek elimde değil, 

Alemin tek bir noktasında.

Varsın bitsin bu dünyada ömrüm, 

Gözlerin kazınmış yedi tahtasında! ...', 'Gözlerinde bulurum düşlerimi;  Kat kat tabakaları arasında. Bir o yana bir bu yana savrulurken Sarhoş misali, gözlerinin karşısında... Her t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sordun mu?', 'sordun-mu-dost-tutkunu-7z0ss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dizilir önünde hep sıradağlar

Aşamayan garip gizlice ağlar

Bu aşkta teselli ne fayda sağlar? 

Durup da kendine sordun mu bilmem.

Kalbinden bir parça kopup gidince

O gençlik yılların birden yitince

Ne yaparım diye oyun bitince

Durup da kendine sordun mu bilmem.

Savaştın yıllarca bir hiç uğruna

Elbette gidecek bu söz ağrına

Kaç taşı dost diye bastın bağrına

Durup da kendine sordun mu bilmem.

Güzel gözlerine bakman yasaksa

Uykusuz geceler ya bir tuzaksa? 

Unutman mümkün mü sana uzaksa? 

Durup da kendine sordun mu bilmem.

Hayalin yerini gerçek alınca

Sızlayan kalbine hüzün dolunca

Ne dersin şiirler onu sorunca? 

Durup da kendine sordun mu bilmem.

Gizlenen sevdanı sessiz yaşarken

İmkansız aşkına veda ederken

Nasıl unuturum diye severken

Durup da kendine sordun mu bilmem.

Anlamlı gözleri benzer vadiye

Hayatın anlamı ondan hediye

Sen gibi hiç seni sever mi diye

Durup da kendine sordun mu bilmem.

[email protected]', 'Dizilir önünde hep sıradağlar Aşamayan garip gizlice ağlar Bu aşkta teselli ne fayda sağlar?  Durup da kendine sordun mu bilmem. Kalbinden b...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sordun-mu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Olacak', 'biri-olacak-dost-tutkunu-e3100', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılık saati gelip çatınca

Hüznünü gizleyen biri olacak

Boş kalan yollara dönüp bakınca

Gözlerine birden yaşlar dolacak.

Kan kırmızı güller öksüz kalacak

Hasretin içimde bir kor olacak

İçimde son umut birden solacak

Rüzgarla savrulan biri olacak.

Zamanın dolup da veda edince

Her sahte dost gibi sen de gidince

Beni sensizliğe mahkum edince

Resminle avunan biri olacak.

Ne tadı kalır bu yerlerin sensiz? 

Geçerken tüm ömrüm senden habersiz

Dilerim tüm ömrün geçer kedersiz

Diye dua eden biri olacak.

Nasıl da su gibi akıyor zaman

Çaresiz bir dert bu hem de pek yaman

Ardına bakmayıp gittiğin o an

Anılara dalan biri olacak.

Sen çok uzaklarda bensiz yaşarken

Mutluluk yolunda hızla koşarken

Her zamanki gibi gülüp coşarken

Seni unutmayan biri olacak.

Gözlerindi beni umuda salan

Hayatın kendisi zaten bir yalan

Maziye bakınca aklında kalan

Teşekkür ettiğin biri olacak.

Kimbilir belki de günün birinde

Sensiz kalan bomboş hayallerimde

Dipsiz bir denizin derinlerinde

Saplanıp çıkmayan biri olacak.

Yine de üzülme sen sakın emi

Elbet bir limanda durur bu gemi

Hayat denen zorlu yolun matemi

Sona erdi diyen biri olacak.

[email protected]', 'Ayrılık saati gelip çatınca Hüznünü gizleyen biri olacak Boş kalan yollara dönüp bakınca Gözlerine birden yaşlar dolacak. Kan kırmızı güller...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/biri-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmayan Gül', 'solmayan-gul-dost-tutkunu-vxl4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatımın baharı son kışa vardığında

Mazimin gözyaşları kapımı vurduğunda

Boşa geçen yıllarım karşımda durduğunda

Depreşir her bir anı hayaller kurduğumda.

O anılar içinde hiç solmayan bir gül var

Ayakta dimdik hala üstünde olsa da kar

Kimseler edemedi ona bu bahçeyi dar

Belki ruhu ölmezdi sevmeseydi bu kadar.

İnsanları kendince başka türlü izlerdi

Buğulu gözlerinde binlerce sır gizlerdi

Hayatında durmadan bir şeyleri özlerdi

Gelmeyen bir hayalin yollarını gözlerdi.

Merhametsiz dünyada değişmeyen bir oydu

Hep karşılıksız verip vefasızlığa doydu

İnsanlar çok şerefsiz o gül ise çok toydu

Koklayanlar hep onu aptal yerine koydu.

[email protected]', 'Hayatımın baharı son kışa vardığında Mazimin gözyaşları kapımı vurduğunda Boşa geçen yıllarım karşımda durduğunda Depreşir her bir anı hayal...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/solmayan-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-dost-tutkunu-47hhj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbindeki sırları bir gün olsun aç bana

Gözümdeki elemin sebebini sorsana

Bilmem nasıl anlatsam bu çileyi ben sana

Hiç mutluluk vermiyor bu hayat inan bana.

Menfaat taşımayan dostluklar neden yalan? 

Bitmeyen bu kaosta gel de sevgiye inan

Yıllar geçti hala yok ne arayan ne soran

Tüm dertler son bulmuyor boşa geçince zaman

Bir gün belki anlarsın sen bu garip adamı

Hatırlarsın gün gelir unuttuğun adımı

Anarsın benle geçen üç beş günün tadını

Bense yıllar geçse de unutamam adını.

[email protected]', 'Kalbindeki sırları bir gün olsun aç bana Gözümdeki elemin sebebini sorsana Bilmem nasıl anlatsam bu çileyi ben sana Hiç mutluluk vermiyor bu...', ARRAY['Türk Edebiyatı','Şiir','Dost Tutkunu']::text[], 8.5, '{"poet":"Dost Tutkunu","poet_slug":"dost-tutkunu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sitem-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdiğim Yalandı', 'seni-sevdigim-yalandi-salih-ozalasan-046wq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğim yalandı

Nasılda kandırdım seni

Demiştim hayat bahardı

Kış ortasında bıraktım seni

Sandınki dudağımda ismin vardı

İsmini anmasam dilim yanardı

Gözlerim sandın hep seni arardı

Demiştimya sen varsan bahardı

Evet yalan söyledim ne yapayım

Elimde değildi söyleyemedim

Seni sevmediğimi 

Yada çok sevmediğimi

Çünki taptığım sendin 

Sevmek yanında neydiki

Sevgiler birgün biter

Ama ben seninle yapıyorum ibadeti

İsmin dua gözlerin gözüme ışık

Sevgiden öte yaşıyorum saadeti

Sana bahar yaramazdıki

Sen alplerin kardeleni

Beyaz karlar yaşatacaktı seni

Sen yaşayasın diye

Karlar altında yaşamaya mahkum

Sana esir ettim bu bedeni

Sevmiyorum baharı 

Bahar rüzgarları kurutur seni

Sen daim kalacaksın

Yeryüzü sana olacak mekan

Sen yoksan geçmeyecek

Duracak sensiz bana zaman

Adını ezber edip anacak aşık olan

Sen sevdalılara olacaksın mekan

Sevdiğine hasret sevgi arayan

Kapında yüz sürecek herzaman

Belki yüreğim donacak

Gelecek bu Dünya''dan göçmeye zaman

Alplerin karları sel olup akacak

Tufan kopacak işte ozaman

Gökler yarılıp yıldırımlar çakacak

Taş üstünde taş kalmayacak ozaman

Alplerin zirvesinde bir sen bir ben

Mahşerde olacağız ozaman

Sana olan sevdamı

Bakalım tartabilecekmi mizan

Y.Tar 04-11-2002 Saat 20.52', 'Seni sevdiğim yalandı Nasılda kandırdım seni Demiştim hayat bahardı Kış ortasında bıraktım seni Sandınki dudağımda ismin vardı İsmini anmasa...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/seni-sevdigim-yalandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Gül', 'kirmizi-gul-tuana-okan-l8iuu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk

Dilimde şarkımız gözümde yaşla

Kapına kırmızı bir gül bıraktım', 'Aşk Dilimde şarkımız gözümde yaşla Kapına kırmızı bir gül bıraktım...', ARRAY['Türk Edebiyatı','Şiir','Tuana Okan']::text[], 8.5, '{"poet":"Tuana Okan","poet_slug":"tuana-okan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kirmizi-gul-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-oguzkan-bolukbasi-tcs3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gülüm

yüzündeki o tebessüm

gamzelerinde büklüm büklüm

nehir yataklarına döner

serinlerim

rüzgar olur yaz günlerim

gülüm

seninle uzaklarda kalır ölüm

hayat doğar her gün ışımasında

umut olur düşlerim

seni beklerim

gülüm

sana sunulmuş ömrüm', 'gülüm yüzündeki o tebessüm gamzelerinde büklüm büklüm nehir yataklarına döner serinlerim rüzgar olur yaz günlerim gülüm seninle uzaklarda ka...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Başlı Mezar Taşı', 'i-ki-basli-mezar-tasi-ayhan-aktas-edtvc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki başlı mezar taşı

Yastıgından belliydi kaderi

Cift dikişti hayatı..

Hep birdi ikilerin önünde..

Hiç yılmam diyordu..

Ama hep yılıyordu gönlünde..

Anlatmıyordu yüregındeki ıkının sevdasını.

Birlerin içinde boguldu bilmeden..

Cıkamadı ıkılerin yanına

İkilik bir sevda diledi hayattan

Hayat bir verdi gönlünden, 

Birlik sevdayı çarptı yeni bir birle

Bilemedi, birkere bir bir ederdi, , 

Yeter dedi bari iki başlı mezar tasım olsun diledi, , 

Şimdi yatıyor iki başlı mezar tası olan mezarda, 

Artık olmustu hayatında ıkılık bır parcası.

İki başlı mezar tası..

Bir mezarcı yazdı yazıyı mezar taslarına, 

Ama bir degil iki taşa, 

Birinde bu şiir, 

Digerinde ruhuna fatiha

                                                                          Ayhan aktaş  

                                                                        03-kasım-2002', 'İki başlı mezar taşı Yastıgından belliydi kaderi Cift dikişti hayatı.. Hep birdi ikilerin önünde.. Hiç yılmam diyordu.. Ama hep yılıyordu gö...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Aktaş']::text[], 8.5, '{"poet":"Ayhan Aktaş","poet_slug":"ayhan-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-basli-mezar-tasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayamadık', 'anlayamadik-polat-unsal-bktag', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlayamadık biz birbirimizi, 

Ne sen beni anladın, ne ben seni.

Söyleyemedik hiç hislerimizi, 

Yüreğimizde kaldı hep ne varsa.

Ne sen yenebildin kaprislerini, 

Ne ben yenebildim benliğimi.

Hiç uğruna harcadık sevgimizi, 

Bitti gençlik vakit erken olsada.', 'Anlayamadık biz birbirimizi,  Ne sen beni anladın, ne ben seni. Söyleyemedik hiç hislerimizi,  Yüreğimizde kaldı hep ne varsa. Ne sen yenebi...', ARRAY['Türk Edebiyatı','Şiir','Polat Ünsal']::text[], 8.5, '{"poet":"Polat Ünsal","poet_slug":"polat-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlayamadik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle ve Sensiz', 'seninle-ve-sensiz-gursel-colak-w1n7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kör değilim, görüyorum

Sagır değilim, duyuyorum

Dilsiz değilim, konuşuyorum

Topal değilim, yürüyor, koşuyorum

Çolak değilim, tutuyor, sarıyorum

Seninle olduğum zaman

Körüm, görmüyorum

Sağırım, duymuyorum

Dilsizim, konuşamıyorum

Topalım, yürüyemiyor, koşamıyorum

Çolağım, tutamıyor, saramıyorum

Sensiz olduğum zaman, aşkım', 'Kör değilim, görüyorum Sagır değilim, duyuyorum Dilsiz değilim, konuşuyorum Topal değilim, yürüyor, koşuyorum Çolak değilim, tutuyor, sarıyo...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seninle-ve-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yoruldum', 'yoruldum-gursel-colak-5pv81', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoruldum! 

Aralarda kalmaktan

İtilip kakılmaktan

Düşürülüp ezilmekten

Yalan sözlerden

Sahte gülüşlerden

Kem gözlerden

Yoruldum! 

Kalbimin parçalanmasından

Umutlarımın kırılmasından

İçimin kan ağlamasından

Yarınlardan korkmaktan

Kurşun sesiyle uyanmaktan

Ezilenleri koruyamamaktan

Yoruldum! 

Yolda yürümekten

Kahvede oturmaktan

Korkuyla yaşamaktan

İnsanlardan, dertlerden, yaşamaktan

Yoruldum arkadaşım, Yoruldum! ! ! ! !', 'Yoruldum!  Aralarda kalmaktan İtilip kakılmaktan Düşürülüp ezilmekten Yalan sözlerden Sahte gülüşlerden Kem gözlerden Yoruldum!  Kalbimin pa...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yoruldum-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-elyase-i-skender-o8kqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'her aynaya baktığımda

 donuk gözler görürüm

 çatlayan tohum gibi sancıdadır.

 sonra izmir derler yanımda bile bile

 bilirim orada ruhum gibi sarıcadır.

 her aynaya baktığımda 

 donuk gözler görürüm

 kurumuş toprak gibi çizgi çizgi..

 bir  hain gelir bahçemden umudumu koparır

 biri son sigaramı alır

 biri gözümün içine baka baka tüm yeşillere küfreder

 biri gökyüzünü çalar, son nefesimi ister..

 her aynaya baktığımda 

 donuk gözler görürüm

 batan güneş gibi kızıldadır...', 'her aynaya baktığımda  donuk gözler görürüm  çatlayan tohum gibi sancıdadır.  sonra izmir derler yanımda bile bile  bilirim orada ruhum gibi...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/inadina-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-elyase-i-skender-qt3pd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin vücudunda soğudu dünya, 

Güneş kar etmedi, buz tuttu heryer.

Toprak hiç bu kadar direnmedi, 

Ve mezar kazıcılar hiç bu kadar uğraşmamıştı..

Keşke herşey gömülseydi

Keşke tüm dağlar dümdüz olsaydı, 

Yıkılsaydı dünya, bir depremle ortadan ayrılsaydı yerküre, 

bir yarısında ben diğerinde sen, yaşam kadar canlı

Keşke gün batıdan doğsaydı, 

ve herkes ölseydi şafak sökmeden kalbimi, 

Keşke ''keşke'' demeye zamanım olmasaydı! 

''Bir sonraki geceye miras bıraktım hasreti, 

  Ölümü bir sonraki yaşama, 

   Sevgileri bir başka kalbe sattım! ''', 'Senin vücudunda soğudu dünya,  Güneş kar etmedi, buz tuttu heryer. Toprak hiç bu kadar direnmedi,  Ve mezar kazıcılar hiç bu kadar uğraşmamı...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/keske-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Gideli', 'sen-gittin-gideli-elyase-i-skender-07aio', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanat çırptı hayallerim geceden gündüze, 

Son yaralı güvercin öldü rüyamda, 

Yaşama pranga vurdum sen olmadıkça.

   ''bahçeme kasımpatları ektiğinden beri

    gülmez oldu dünümün kızıl günleri! ''

Sen gittin herşey bitti

kurudu canpınarım, 

Sen gittin bir yaşam yitti

Renkler uğramaz oldu hayata.

Sen gittin gideli

Tüm trenlere sövdüm

Tüm vagonlar bir ölüm evi..

Sen gittin gideli, 

Günüm sarı, geceler sarı

yittin yiteli, 

Ölümle bitti tüm peri masalları.

      ''sen günahsız bebek yittin bu yangında''', 'Kanat çırptı hayallerim geceden gündüze,  Son yaralı güvercin öldü rüyamda,  Yaşama pranga vurdum sen olmadıkça.    ''bahçeme kasımpatları ek...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gittin-gideli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olanlar Bana Olmayanlar', 'sana-olanlar-bana-olmayanlar-elyase-i-skender-6dg2i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyorsa şehre hala

bilirim yakınlardasın.

bir el uzatımlık mesafedeyken tutamadımsa seni, 

      tüm suç benim değil(!)

   ''sen geldin mevsim kıştı, 

     şimdi yoksun heryer buz.''

Bir adım yaşama bir adım sana, 

eriyceğimi bilsemde bu sefer atacağım.

Sarhoş mu olmalıydım bilmiyorum, 

yüreğimi emanetçiye  bırakıp mı  gelmeliydim

yada gözlerimi kapatıp seni kokundan mı tanımalıydım bilmiyorum.

Bir sen uzakta oluyorsun hayat titrek serçe

Tüm şehir eriyor sana bir göz deyende..

Görmeyince daha bir çirkinleşiyor herşey

Hayat daha bir kararıyor.

Gözlerimde düşmeye meyilli yaşlar, 

Sana yakın bir yer arıyor.

Herşey sana yaşıyor, 

Rüzgar sana, yağmur sana

   anlasana..

Sararan yapraklar sana düşüyor, 

Her taraf herkes şu karşıdaki ev

Güller, sokakta ki lamba, herşey üşüyor.

Ölüm mü? ...

...Belki sonra, 

Yaşam takılı kalmış seni gördüğüm ana, 

Ben takılı kalmışım sana!', 'Yağmur yağıyorsa şehre hala bilirim yakınlardasın. bir el uzatımlık mesafedeyken tutamadımsa seni,        tüm suç benim değil(!)    ''sen gel...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sana-olanlar-bana-olmayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Gülleri', 'umut-gulleri-elyase-i-skender-yp1x5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine o yıllıktaki resminin 

Acıyan gözlerine bakmak istemiyorum

Çünki biliyorum, bakarsam 

Yıkılacak barajları ıssızlığımın

Çünki bir daha, 

Umut bahççemin gülü açmayacak

Mehtabı arayan yüreğimde.

İşte o zaman

Hayat kitabımın kelimeleri 

Daha ağır gelecek beynime

Ve son kez kan kızıllığında 

Sökecek şafak biliyorum.

Haydarpaşa garından giden 

O kara tren bir daha dönmeyecek

Ve yıkılacak yedi tepesi İstanbul''un

Kalbimin çığlıkları üstüne..

Ve o gülen çocuk, 

Bir daha dirilmeyecek!', 'Yine o yıllıktaki resminin  Acıyan gözlerine bakmak istemiyorum Çünki biliyorum, bakarsam  Yıkılacak barajları ıssızlığımın Çünki bir daha, ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-elyase-i-skender-adelq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün geceye hasret çeker, 

Tutuşur güneş sözlerinde, 

Bir kor olur düşer yüreğime.

Son yük trenide kaçmıştır, 

yükü sevgi, adresi belli.

Son umut tükenmiştir, 

Son geceyle beraber.

Ve kurumuştur gözpınarım, 

Gönül limanıma uğrayan son gemi, 

(ilk ve)   Son sevdamı alıp, 

Yelken açmıştır umutsuz gündüze.

Artık hiç gece olmayacak.

Artık sevemeyeceğim bir güvercini.

Artık umut etmek yok, 

Beklemek bitti.

  Son dalga vurdu karam''a, 

  Ve son kez tuz bastı yarama, 

  Yumuşak ellerin..

Gözlerin son kez nefret  getirdi, 

Ve son kez dirildi, 

Sohbetimi kısa kestiğim, 

Ruhum şeytanı.

Kelimeler zehir, cümleler yakar, 

Düştüğü yeri gözyaşlarımın.

Harfler şimşek gibi çakar beynimde..

Derdim: Sensizliğin savrulan sessizliği, 

Yaşam bir perde çekti, 

Sevdamın son sevinçli sahnesine...', 'Gün geceye hasret çeker,  Tutuşur güneş sözlerinde,  Bir kor olur düşer yüreğime. Son yük trenide kaçmıştır,  yükü sevgi, adresi belli. Son ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurbağa Bacaklı Şair''e', 'kurbaga-bacakli-sair-e-ahmet-ozturk-uifja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sopsoğuk bir geceden sıyrılıp 

gelmiştin çayımızın demine

ev arkadaşlarımızdan ayıracak kadar muhabbete sürdün bizi

ne kadar sorumsuz görünsen de 

o kadar için doluydu

Köftehorlar kralı bir deryaydın

Seni herkesden ayıran kimsede 

Bulamadığım o saklanan deli

Ama fırtınalarda kanamayan yüreğindi

Kimseler bilmedi ne depremlerle sarsılan

O kanlı yüreğini

Bil ki dört sene bile bile sustum 

Bilki bu oyunu oynadım dostum

Dostum diyorum sana

Belki bu ilgiyi bu lafın ağırlığı kadar 

Seremedim ayaklarına

Ama hep ayrılmayan gölgen oldu 

Sana duyduğum cümbüş sevgim

Bay dudaktın evde 

ne yemek yaptın

Ne de ganyanda altıda altı yaptın

Her gece sigarayı bıraktın

Bir kez olsun beni sensiz bırakmadan

Satıcı lakaplıydın 

bence çayın demini seven adamdın

herkes seni o yeren laflara boğdu

ama sen kimseye gel peşime takıl demedin

seni sen olduğun 

sen olabildiğin

hatta çoğu zaman ikimizinde yaptığı 

sen olmamayı başardığın için seviyorum

yedikuleyi bir anlattın kuleleri yıkıldı gözümüzde

silindi tarih ve yazıldı senin tarih olacak maceraların

aynı şarkıyı tekrar tekrar söyleten

sen sevdiğim tek deli adamsın

o şarkıyı herzaman omuz omuza 

söyleriz dileğim

çayımızı yudumlarken hep bire 

bir olana sabah ezanına kadar 

Şiiri kafa kafaya

Aşkın acısını ağlaşarak paylaştık

Geceleri sokakları omuz omuza

Namazı aynı secdeye baş koyarak paylaştık

Sen benim kurbağa bacaklı şair dostumsun

(11/5/2002)

(etiler- İstanbul)

(04: 26)', 'Sopsoğuk bir geceden sıyrılıp  gelmiştin çayımızın demine ev arkadaşlarımızdan ayıracak kadar muhabbete sürdün bizi ne kadar sorumsuz görüns...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/kurbaga-bacakli-sair-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşsiz Tabip (Latif Bir Taşlama)', 'i-ssiz-tabip-latif-bir-taslama-sabri-gurbuz-vqtdk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hem gaste okudum kahvaltı sonrası

Hem de dırdır yedim işsizlik avansı

Yahu fakirmişisz kalk bu miskinlik niye

Sana benzemez paracı tabip var nice

Hırs basmış kalkmışım hışımla iş aramaya

Hırs değil merdane yaresiymiş sırtımda

Göbeğimle alay eder buldum zevatı

Anda zerzavata boğdum ol erbabı

Nazettimde kendimce iş olmadı böylece

Oklavalı zebaniyi hazır buldum gece

                       5-11-2002', 'Hem gaste okudum kahvaltı sonrası Hem de dırdır yedim işsizlik avansı Yahu fakirmişisz kalk bu miskinlik niye Sana benzemez paracı tabip var...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/issiz-tabip-latif-bir-taslama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-sair-khan-4va81', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat nedir? nasıldır bilinmez bilinse de anlaşılması güç bir macera

Kimi için dopdolu heyecan dolu macera kimi için can yakan saatler

Kimi için gözlerde pırıltı kimi için dikenli teldeki kanlı bir kumaş parçası

Hayat nesin nasılsın bilemedik bir türlü anlayamadık seni.', 'Hayat nedir? nasıldır bilinmez bilinse de anlaşılması güç bir macera Kimi için dopdolu heyecan dolu macera kimi için can yakan saatler Kimi ...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrostiş', 'akrostis-yasar-velihan-ydrm4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haramiler gelip

Alsa seni elimden

Cehennem ateşi ile dolu

Ellerimi kırka bölüp

Recm ederdim hepsini', 'Haramiler gelip Alsa seni elimden Cehennem ateşi ile dolu Ellerimi kırka bölüp Recm ederdim hepsini...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Velihan']::text[], 8.5, '{"poet":"Yaşar Velihan","poet_slug":"yasar-velihan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/akrostis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bir Akşam', 'sensiz-bir-aksam-yusuf-ziya-eraslan-i2r23', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evet yine Güneş batıyor

Yine sensiz bir akşam doğuyor

Gözlerimden bir yaş daha düşüyor

Sokağın tam ortasına 

İşte oraya

Sokaklar sessiz, loş ve yağmurlu

Sevdiğimin hayalini görürüm

Ben giderim yar gider

Ben giderim yol gider

Ve yol biter

Yar kaybolur

Karanlıklar teselli eder beni

Neden diye sorarım

Yağmur cevap verir

Hayat bir sevgidir

Sevmezsen biter

Ben bu yağmurların emzirdiği çocuğum

İnanırım ve niçin derim

Susar cevap vermez

Ve sabah olur

Yağmur durur

BEN AĞLARIM...', 'Evet yine Güneş batıyor Yine sensiz bir akşam doğuyor Gözlerimden bir yaş daha düşüyor Sokağın tam ortasına  İşte oraya Sokaklar sessiz, loş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Eraslan']::text[], 8.5, '{"poet":"Yusuf Ziya Eraslan","poet_slug":"yusuf-ziya-eraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-bir-aksam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''daki Herşeyin', 'ankara-daki-herseyin-hafize-zuluflu-6b4p7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi neresindeyim bilmiyorum yaşantının

Yolumuzu kesiştirdikten sonra

Bizi ayrı noktalara savuran o gizli

Kudretin doruklarında mı

Yüreğimize sevgi tohumları serptikten sonra

Hasret uçurumlarına iten o utanmaz kaderin elinde mi

Bilmiyorum ama her neyse yazgım

Dönersem yolundan sensiz kalayım beni en çok yaralayan

Bilmiyorum gecelerine karışıyor mu hüznüm

Özlüyor musun gözlerimi sebepsiz

Durup dururken ya da tam ortasındayken uykularının

Düşüncelerine tırmanıyor mu ankara’daki herşeyin

Oysa sen hiç katıksız bendesin

Ellerin olmasa da tuttuğum

En sadık düşüncelerimdesin

Yağmur yağmur süzülürken hasretin saçlarımdan

Uzaklarda olsan da 

Elinde şemsiyeyle yanımdadır görüntün

Bir gidip bir gelen

İçimde sevgindir med cezir misali yükselen.', 'Şimdi neresindeyim bilmiyorum yaşantının Yolumuzu kesiştirdikten sonra Bizi ayrı noktalara savuran o gizli Kudretin doruklarında mı Yüreğimi...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ankara-daki-herseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviler', 'maviler-erdal-tuter-yjaoz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün bir gemiyle çıkarsam okyanuslara

Bütün maviler seni hatırlatacak bana

O bembeyaz köpükler seni isteyecek

Deniz kuduracak yokluğuna

Bir fırtına olup

Beni almak isteyecek içine

Oysa ben

O mavi el

Benim limanıma geldiğinde

Kendimi çoktan teslim etmiştim

Onun çare bilmez sürgün kentine

Bir denizcinin seyir defterine kendi adımı 

Onun üşüyen dudaklarında ki ismimle yazdım', 'Bir gün bir gemiyle çıkarsam okyanuslara Bütün maviler seni hatırlatacak bana O bembeyaz köpükler seni isteyecek Deniz kuduracak yokluğuna B...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüter']::text[], 8.5, '{"poet":"Erdal Tüter","poet_slug":"erdal-tuter","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/maviler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakala Beni', 'yakala-beni-erdal-tuter-sg8xd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün yakala beni diyeceğim ve aşka düşeceksin.O filmin unutulmaz sahnesinde olduğu gibi hayalinle dans edeceğim sen olmadığın zaman.En sevdiğin yemekleri yapacağım  ardından bir çay demleyeceğim sen varmışsın gibi.Hayalinle uyuyacağım nefesin bir nefes kadar yakın olacak.Biliyorum bir gün geleceksin ama bugün olmamalı hayalini sevmeliyim bugün.Onunla ilgilenmeli ona tebessüm etmeliyim.Geleceksin beraber yaşadığım hayalinle birleşeceksin ve bütün bunların toplamı bir dünya dolusu tebessüm olacak gözlerimde.Ama bugün değil, değil, değil...', 'Bir gün yakala beni diyeceğim ve aşka düşeceksin.O filmin unutulmaz sahnesinde olduğu gibi hayalinle dans edeceğim sen olmadığın zaman.En se...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüter']::text[], 8.5, '{"poet":"Erdal Tüter","poet_slug":"erdal-tuter","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yakala-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana doyamıyorum', 'sana-doyamiyorum-salih-ozalasan-q6o98', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deme bana darılırım kırılırım

Gözün üstünde kaşın oynuyor

Nede ayran gönüllüsün

Gözün bir türlü doymuyor

Şıpsevdisin yüreğin daldan dala konuyor

Bir gözün bana bir gözün başkasına bakıyor

Bu sözlerin inanki içimi yakıyor

Seni sevmek az gelir, yüreğim sana tapıyor

Sanmaki senle yada sensiz

Gözlerim bir başkasına bakıyor

Yüreğimde sevgin bir fırtına

Sanmaki senden başka sığınak arıyor

Sen vazgeçemediğim, 

Asla vazgeçemeyeceğimsin 

Binlerce güzel benim olsada

Benim gönlüm bir seni arıyor

Bir seninle süt dökmüş kedi

Bir sana asla dayanamıyor

Sana öyle sevdalı öyle hasretki yüreğim

Seninleyken bile sana doyamıyor

Y.Tar 05-11-2002 Saat 17.30', 'Deme bana darılırım kırılırım Gözün üstünde kaşın oynuyor Nede ayran gönüllüsün Gözün bir türlü doymuyor Şıpsevdisin yüreğin daldan dala kon...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-doyamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim (Kuvayımilliyeci)', 'sevdigim-kuvayimilliyeci-ali-hallac-qlcmj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'saçlarını, 

gökkuşağı rengine boya.

dudağına, 

kızılcık şerbeti sür.

salt kadın olma

biraz dişi ol

sevdiğim.

oku, dinle, izle..

sorgula, yargıla..

başkaldır gerekirse.

çekinme iste, hakkınsa

salt kadın olma

kişi ol

sevdiğim.

herkes bıraksada

sen kuvayımilliyeci kal.

inadına

seferberlik türküleri söyle.

salt kadın olma

fikrimin güneşi ol

sevdiğim.', 'saçlarını,  gökkuşağı rengine boya. dudağına,  kızılcık şerbeti sür. salt kadın olma biraz dişi ol sevdiğim. oku, dinle, izle.. sorgula, yar...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdigim-kuvayimilliyeci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün cok mutluyum.', 'bugun-cok-mutluyum-sevda-oz-r49d6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün cok daha özel 

Ve cok güclü 

Siradisi olmanin keyfi

Seninle olmanin zevkini sürüyorum

Bugün cok mutluyum...', 'Bugün cok daha özel  Ve cok güclü  Siradisi olmanin keyfi Seninle olmanin zevkini sürüyorum Bugün cok mutluyum......', ARRAY['Türk Edebiyatı','Şiir','Sevda Öz']::text[], 8.5, '{"poet":"Sevda Öz","poet_slug":"sevda-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bugun-cok-mutluyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce Giderim', 'sessizce-giderim-ali-hallac-mysxx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sessizce giderim

haberin bile olmaz

seni üzmem, hissettirmem

belki ruhun bile duymaz.

sessizce giderim

bir kuşun uçması gibi avuçlarından.

yüreğini terkederim.

sessizce giderim

ayak sesim bile duyulmaz.

sessizce giderim

haberin bile olmaz.

sessizce giderim

ardıma bakmam, geri de dönmem

sessizce giderim

belki sen uyurken.

sessizce giderim

ağlatmam, iz bırakmam.

sessizce giderim

hiçbirşeyin yerini değiştirmeden.

sessizce giderim

varlığımla yokluğum anlaşılmaz.

sessizce giderim

haberin bile olmaz.', 'sessizce giderim haberin bile olmaz seni üzmem, hissettirmem belki ruhun bile duymaz. sessizce giderim bir kuşun uçması gibi avuçlarından. y...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sessizce-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-ali-hallac-kyocx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buram buram ekmeğin kokusunda

Oya oya kilimin dokusunda

Sevgi sevgi canımın damarında

Gözümün bebeği benim vatanım.

Bir düşman eli uzanırsa eğer

Uğruna can feda etmeğe değer

İnsan olan öz vatanını sever

Canımın çiçeği benim vatanım.

Gece ve gündüz çalışıp duralım

Biz uygarlığın bekçisi olalım

Öz vatanımızı kalkındıralım

Ülkümün ereği benim vatanım.', 'Buram buram ekmeğin kokusunda Oya oya kilimin dokusunda Sevgi sevgi canımın damarında Gözümün bebeği benim vatanım. Bir düşman eli uzanırsa ...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vatanim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla', 'hatirla-sair-blues-6zwwu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzakta bir hıçkırık sesi duyarsan sesin için ağladığımı hatırla

Sende bir gün seversen seni nasıl sevdiğimi hatırla.

Eğer uzaklarda dikenli bir mezar görürsen senin için öldüğümü hatırla.

Sende bir gün terkedilirsen beni nasıl terkettiğini hatırla.', 'Uzakta bir hıçkırık sesi duyarsan sesin için ağladığımı hatırla Sende bir gün seversen seni nasıl sevdiğimi hatırla. Eğer uzaklarda dikenli ...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hatirla-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutları Çalınmış, Bir Çocuktur Kalbim...', 'umutlari-calinmis-bir-cocuktur-kalbim-emre-ozdamar-gdavk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tenimde yagmur lekeleri

Akşamlardan, yagmurlardan ve hüzün kokan

Mevsimlerden geçtim.

Payıma düşen hep bir avuç özleyişti

Dilsiz bir yalnızlığa müebbet yedim

Nicedir biriktirdiğim resimlerden

Kan damlıyor ellerime

Usulca aralıyorum perdeleri ve sen! 

Anlatabiliyormuyum..........Gitme! ....', 'Tenimde yagmur lekeleri Akşamlardan, yagmurlardan ve hüzün kokan Mevsimlerden geçtim. Payıma düşen hep bir avuç özleyişti Dilsiz bir yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umutlari-calinmis-bir-cocuktur-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zümrüt Gözlerin Canımı Yakar', 'o-zumrut-gozlerin-canimi-yakar-sair-blues-6euhi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdan ateş içimi dağlar

Bir duman yükselir gözlerimi dağlar

Her akşam içindeki sevginin ölüşü için

Bu ela gözlerim kan ağlar', 'Sevdan ateş içimi dağlar Bir duman yükselir gözlerimi dağlar Her akşam içindeki sevginin ölüşü için Bu ela gözlerim kan ağlar...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/o-zumrut-gozlerin-canimi-yakar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Eylem', 'bir-garip-eylem-cemal-ugur-z89w7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gariptir kuşun ötüşü

Avcının tüfek tutuşu

İkiside zevk alır eylemlerinden

Birisi doğa sevgi karışımı neşe yansıtır

Öteki 

	Kan 

Akıtır

Tüfekten çıkan ses kuşu susturur

Avcıyı çoşturur

Bir gariptir kuşun ötüşü

Avcının tüfek tutuşu

08.12.1974/ UŞAK

Cemal UĞUR', 'Bir gariptir kuşun ötüşü Avcının tüfek tutuşu İkiside zevk alır eylemlerinden Birisi doğa sevgi karışımı neşe yansıtır Öteki  	Kan  Akıtır T...', ARRAY['Türk Edebiyatı','Şiir','Cemal Uğur']::text[], 8.5, '{"poet":"Cemal Uğur","poet_slug":"cemal-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-garip-eylem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Demek', 'bu-demek-funda-ozdemir-9edhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne demek

Sensizlik

Ne demek? 

Doğmamış bir çocuğun

Ölümü demek.

Sensizlik? 

Cinayet..', 'Ne demek Sensizlik Ne demek?  Doğmamış bir çocuğun Ölümü demek. Sensizlik?  Cinayet.....', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin, Sözlerin ve Sensizliğin', 'gozlerin-sozlerin-ve-sensizligin-gursel-colak-ntcm0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '.Beni ne kurşun yaraları 

Nede bıçak yaraları

Nede beraberliğin öldürür.

Beni yaralayan kurşun bakışlı gözlerin

Keskin bıçaktan beter parçalayan sözlerin

İnan canım, beni öldürecek tek şey ise Sensizliğin', '.Beni ne kurşun yaraları  Nede bıçak yaraları Nede beraberliğin öldürür. Beni yaralayan kurşun bakışlı gözlerin Keskin bıçaktan beter parçal...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gozlerin-sozlerin-ve-sensizligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Meleği', 'olum-melegi-funda-ozdemir-2pcoa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık

Rahat rahat uyuyabilirsin.

Artık

Rahat rahat ölebilirim.

Ne sen kaldın, ne ben, 

Ne biz..

Sevdiğim..

Herşeyim..

Ölüm meleğim..', 'Artık Rahat rahat uyuyabilirsin. Artık Rahat rahat ölebilirim. Ne sen kaldın, ne ben,  Ne biz.. Sevdiğim.. Herşeyim.. Ölüm meleğim.....', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olum-melegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sensiz', 'sensiz-umit-kurtulus-qjh7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanaymış kağıtlarda yarım bir şiir                                         Bestelenmiş şarkı gibiyim                                                          Karanlık gecelerde doğmamış güneş                                     Sensiz ışığı tüten yıldız gibiyim                                                  İçtiğim sigaranın dumanısın                                                  Döktüğüm her damla göz yaşımsın                                       Sensiz ışığı tüten yıldız gibiyim                                                  Bir gün pişman olupta dönersen geri                                      İstemem sevgilim maziye gömdüm seni                                 Dilimden  düşmeyen o güzel ismini                                       Unuttum sevgilim unuttum seni.', 'Sanaymış kağıtlarda yarım bir şiir                                         Bestelenmiş şarkı gibiyim                                        ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kurtuluş']::text[], 8.5, '{"poet":"Ümit Kurtuluş","poet_slug":"umit-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sensiz-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-funda-ozdemir-533k5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kokunu duydum bugün bir adamda

Ve yürüdüm onla beraber tüm İstiklali, 

İki adım geriden, her zamanki gibi.

O da tuttu, 

Çıkmaz sokağa girdi.

Bağırmak istiyorum artık

Kendime diyemediklerimi..', 'Kokunu duydum bugün bir adamda Ve yürüdüm onla beraber tüm İstiklali,  İki adım geriden, her zamanki gibi. O da tuttu,  Çıkmaz sokağa girdi....', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cikmaz-sokak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-gursel-colak-1r0m1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kötü birşeydir yalnız kalmak

Kimseyle konuşamamak

Dertlerini anlatamamak

Tanıdığın birisini görünce

Bırakmamacasına sarılmak

Başka tanıdığını görünce

Yalan söyleyip kaçmak.

Tanıdıklarında seni bırakıp gitti

Aynı senin beni bıraktığın gibi

Bak gene yalnız kaldın.

Oturursun tek başına

Kendini avutursun

Yaptıklarını düşünür

Belki pişman, belkide kahrolursun

Beni görürsün gelemezsin

Ne söyleyeceğini bilemezsin

Kendi kendini üzersin

Yalnız kaldığın zaman

Sanki bir şey olmamış gibi

Gene bana geri dönersin.', 'Kötü birşeydir yalnız kalmak Kimseyle konuşamamak Dertlerini anlatamamak Tanıdığın birisini görünce Bırakmamacasına sarılmak Başka tanıdığın...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizlik-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-umit-kurtulus-m53iv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmemem için zincir vursalar.                                           Ellerimi kalbimi dilim dilim  parçalasalar.                               Kalbimi söküpte benden alsalar.                                              Yine seni seviyorum  diye haykıracağım.                                Sen aşkı ömrünce tanımadıkça sevmek ne demek bilmessin. Bir resme bakıpta ağlamadıkça özlemek ne demek bilmessin.                                                                                     Kurtar aşkınla beni anla anla seviyorum seni son nefesimi verirken.                                                                                   Aşkınla gel sen sar beni.', 'Seni sevmemem için zincir vursalar.                                           Ellerimi kalbimi dilim dilim  parçalasalar.                   ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kurtuluş']::text[], 8.5, '{"poet":"Ümit Kurtuluş","poet_slug":"umit-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/seni-seviyorum-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşama Doğru', 'aksama-dogru-funda-ozdemir-zvfwf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağzından

Çığlık olarak çıkacağım

Bağırdığında.

Sonra ipek örtü gibi

İneceğim

Dudaklarına.

Dudakların

Okşayan ikimizi; 

Dudakların

Ellerine yol açan.

Biraz daha çılgın sonra, 

Tatlı şeyler fısıldayan.

Neden önce

Ağlar bebek, 

Sonra da süt emer

Annesinin göğsünden? 

O denli merhametli bir aşk bu..

Dudaklarına ineceğim ben, 

Akşam üstümüze çökmeden..', 'Ağzından Çığlık olarak çıkacağım Bağırdığında. Sonra ipek örtü gibi İneceğim Dudaklarına. Dudakların Okşayan ikimizi;  Dudakların Ellerine y...', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aksama-dogru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayana', 'olmayana-funda-ozdemir-wve1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne tek bir satırına denksin yazdığım şiirlerin, 

Ne de ellerin erkekçesine sıcak, 

Hani üşüdüğümde bir yer, sığınacak? 

Yalansın.

Yalan.', 'Ne tek bir satırına denksin yazdığım şiirlerin,  Ne de ellerin erkekçesine sıcak,  Hani üşüdüğümde bir yer, sığınacak?  Yalansın. Yalan....', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/olmayana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluyum', 'mutluyum-saime-ozogul-68q6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve temiz hissediyorum kendimi

Bugün cok daha güzel

Cok sevecen

Ve cok güclü hissediyorum

Bugün sen i hissediyorum...

(25 Agustos 2002)', 'Ve temiz hissediyorum kendimi Bugün cok daha güzel Cok sevecen Ve cok güclü hissediyorum Bugün sen i hissediyorum... (25 Agustos 2002)...', ARRAY['Türk Edebiyatı','Şiir','Saime Özogul']::text[], 8.5, '{"poet":"Saime Özogul","poet_slug":"saime-ozogul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mutluyum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyguların Dünyası', 'duygularin-dunyasi-mustafa-sureyya-sezgin-3h9gv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir başka dünya var biliyorum, 

Her gün içinde yaşadığımız

Benden gelen sana giden

Elle tutulmayan, gözle görülmeyen, 

Duygularımızla örülü bir dünya bu.

Bir bakışla

Hiç sönmeden

Alev alev yanan

Bazen şiddetli bir tipi, 

Sonra, güneş kadar sıcak

Bazen bir davranış

Sevgi dolu kucak kucak.

Söz yok

Dalgalar var aramızda.

Fırtınanın  doruğunda

Ölesiye nefret kimi zaman

Coşku oluveriyor

Elime dokunduğun an.

Bir başka dünya var biliyorsun

Orda yalnızca sen varsın

Ben varım.

Başı sonu hiçbir yere ulaşmayan

Duygularımız var.

Benden gelip sana akan.

(İstanbul,05.11.2002)', 'Bir başka dünya var biliyorum,  Her gün içinde yaşadığımız Benden gelen sana giden Elle tutulmayan, gözle görülmeyen,  Duygularımızla örülü ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duygularin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mayın tarlası Yüreğim', 'mayin-tarlasi-yuregim-murat-cavga-zv97f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Puslu Vakitleri Özlemiş Baykuş Misali

Çöken Karanlıkta Sessizce Süzülüyor  Gece...

Böğrüme Yaslamış Potini Aşk..

Zulmediyor Bu Gece..

Mevzilerde Haram Lokma Savaşı..

Cepkenimde Sevdam Mermi

Mevsimlerden Bahar  Kokusunu

Doldururken Pistolume 

Kan Yerine Aşk Yerine Yara Yerime

Zulmediyor Sevdan Bu Gece.

Geç Diyorsun Ne Yardan Ne Serden..

Sen Geçit Veriyor musun ki Alın Terime..

Mayın Tarlası Yüreğimde..

Ölüyorsun Ve Öldükçe Diriliyorsun Her Gece...', 'Puslu Vakitleri Özlemiş Baykuş Misali Çöken Karanlıkta Sessizce Süzülüyor  Gece... Böğrüme Yaslamış Potini Aşk.. Zulmediyor Bu Gece.. Mevzil...', ARRAY['Türk Edebiyatı','Şiir','Murat Çavga']::text[], 8.5, '{"poet":"Murat Çavga","poet_slug":"murat-cavga","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mayin-tarlasi-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-umit-turan-slg77', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gönlüme bir hüzün saplanırsa

zifiri karanlıklarda; 

doğarmısın altın renkli saçlarınla

yolumu kaybedersem hülyalı şafaklarda

tutuverirmisin titreyen elimi

gül tutan, gül kokan ellerinle

yağmur kopuverse kara gecelerden

sineni yaslarmısın sıcacık, 

bir sığınak bir barınak gibi

zamanın nefesini soluyan duvarlara

yıllara meydan okuyan resminle

anlatırmısın ölümsüz sevgimizi

bakışlarım uzanırken karlı dağlara

hüzün çiçeği kardeleni, 

sararmısın ıslak bir yorgan gibi; 

efsunlu tutkuları sarmalarken

bir sonbahar gecesinde, 

gelirmisin ürkek bir ceylan gibi, 

ben acıyı severken buğulu gözlerde

yüreğini dalgalara vururmusun yağmur okşamalarında.', 'gönlüme bir hüzün saplanırsa zifiri karanlıklarda;  doğarmısın altın renkli saçlarınla yolumu kaybedersem hülyalı şafaklarda tutuverirmisin ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Turan']::text[], 8.5, '{"poet":"Ümit Turan","poet_slug":"umit-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzun-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-omer-lutfi-soylu-1upod', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duman var yine gözlerimde bu gece

Bulutlaşan sıkıntılarım acılarla sıkılıp

Boşalmak istiyor bakışlarımdan....

Yağmur ver Allah''ım yağmur ver

Ufuktan içime serin yağmur

Bunalan yüreğim delik delik olsun

Yalnızlıklar göğüne yükselen ruhum

Orada yağmurla boğulsun...', 'Duman var yine gözlerimde bu gece Bulutlaşan sıkıntılarım acılarla sıkılıp Boşalmak istiyor bakışlarımdan.... Yağmur ver Allah''ım yağmur ver...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Soylu']::text[], 8.5, '{"poet":"Ömer Lütfi Soylu","poet_slug":"omer-lutfi-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozyasi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokolan Umutlar', 'yokolan-umutlar-omer-lutfi-soylu-tjn2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler neden karanlık

Ruhumun aynasımı bulutlar? 

Darağacına götürseler

Farketmeyecek kadar...

Yapraklar bana nispet

Koşuşurken menzile

Toprağın nem kokusu

Her an genzimi yakar...

Geceler neden soğuk? 

Yüreğimdemi kar var? 

Benim yağan toprağa

Sahte olan damlalar...

Sessizlik ölüm gibi

Yorganım kefen bana

Gömdüğüm ben değilim

Benden öte umutlar...', 'Günler neden karanlık Ruhumun aynasımı bulutlar?  Darağacına götürseler Farketmeyecek kadar... Yapraklar bana nispet Koşuşurken menzile Topr...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Soylu']::text[], 8.5, '{"poet":"Ömer Lütfi Soylu","poet_slug":"omer-lutfi-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yokolan-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-bekir-ayral-mscam', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha yaşım olmadı yirmi, 

Saramadan sevdiğimi, 

Yaşamadan gençliğimi, 

Gelme ölüm, alma ölüm oy.

Hayallerim, gençlik düşlerim, 

Gerçekleşsin hep istedim, 

Hep istedim, çok istedim, 

Gelme ölüm, alma ölüm oy.

Baharda gülümü açmadım, 

Telli duvağımı takmadım, 

On yedi yıl önce doğdum, 

Amma ben hiç yaşamadım.

Gelme ölüm, alma ölüm.

Çalma ölüm beni benden

Oy........., Oy........., Oy......Oy. 

(Bu şiir; herkes için büyük umutlar ve mutluluklar taşıyan yeni bir yılık ilk günlerinde, kendi isteği ile aramızdan ayrılıp, ebediyete giden 17 yaşındaki genç bir kızın anısına yazılmıştır. Ruhu şad olsun.)', 'Daha yaşım olmadı yirmi,  Saramadan sevdiğimi,  Yaşamadan gençliğimi,  Gelme ölüm, alma ölüm oy. Hayallerim, gençlik düşlerim,  Gerçekleşsin...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeden Kanatlar', 'golgeden-kanatlar-omer-lutfi-soylu-ggxri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünüyorumda şimdi bütün yaşadıklarım

Sadece acı bırakmış yüreğime

Yanmışım erimişim, kala kala

Bir ben artmışım geriye...

Anlamıyorum neden hep acı peşimde? 

Yada ben onun ensesinde

Her kaçışın sonunda

Bulduğum çıkmaz sokak...

Seviyorum derdim

Neyi sevdiğimi bilmezmişim

Yıllardır bir gölge beklemişim

Tam buldum derken 

Güneşi yitirmişim...

Soruyorum kendime

Bütün yaşadıklarım

Yağmursuz toprakmıydı? 

Işıksız yaprakmıydı? 

Yoksa bir rüyamıydı? 

Biliyorum şimdi

Gökyüzüymüş vatanım

Bulutlarmış yatağım

Görüyorum şimdi

Kırılmış kanatlarım', 'Düşünüyorumda şimdi bütün yaşadıklarım Sadece acı bırakmış yüreğime Yanmışım erimişim, kala kala Bir ben artmışım geriye... Anlamıyorum nede...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Soylu']::text[], 8.5, '{"poet":"Ömer Lütfi Soylu","poet_slug":"omer-lutfi-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/golgeden-kanatlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Nasıl Biriyim?', 'ben-nasil-biriyim-bekir-ayral-enpk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Param yok ki, pulum yok ki; 

Yerim yok ki, yurdum yok ki; 

Yarim yok ki, dostum yok ki; 

Ben nasıl biriyim? 

Şu Dünyadan görmedim hayır, 

Yüce Mevlam beni de kayır, 

Hiç olmadı yanına çağır, 

Ben nasıl biriyim? 

Bekir der ki: kalmadı gücüm, 

Şu Dünyadan yakındır göçüm, 

Ben ölürsem kalır sözüm, 

Ben nasıl biriyim?', 'Param yok ki, pulum yok ki;  Yerim yok ki, yurdum yok ki;  Yarim yok ki, dostum yok ki;  Ben nasıl biriyim?  Şu Dünyadan görmedim hayır,  Yü...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-nasil-biriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal....!', 'hayal-bekir-ayral-iswyd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstesem de gidemem, 

Buradan çok uzaklara.

Her şey bağlamış beni, 

Ne yapsam da boşuna.

Oysa, 

Olmak isterdim; 

Gökte, 

Özgürce uçan bir kuş, 

Okyanusda yelkenli, 

Karada

Sorumsuz, 

Gezgin bir serseri.

Ne çareki; 

Şimdi ben, 

Özgür gibi görünen, 

Kendi yarattığı hapishanede

Sabah sekiz, 

Akşam beş 

Gidip, 

Gelen

BİR GARİP, 

Bİ ÇAREYİM.', 'İstesem de gidemem,  Buradan çok uzaklara. Her şey bağlamış beni,  Ne yapsam da boşuna. Oysa,  Olmak isterdim;  Gökte,  Özgürce uçan bir kuş...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hayal-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyoğlu', 'beyoglu-bekir-ayral-pewme', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyoğlu bir deniz, 

Ben de bir balık olsam.

İzin alıp, 

Beyoğlu Muhtarından

Hep orada kalıp, 

İçinde yaşasam.

Ne zaman istesem, 

Dışına çıkmak.

Boğulacağımı anlayıp, 

Hemen geriye koşsam.

Dalsam, 

Ara sokaklarına, 

Meyhane ve barlarına, 

Varlığını hissetsem, 

Tüm varlığımda.

Koklasam, 

Alkol kokan, 

Kirli, köhne havasını.

Dönsem yeniden hayata, 

Öğrensem yaşamasını.

Beyoğlu bir deniz, 

Bende bir balık olsam.

İzin verse, 

Beyoğlu Muhtarı

Hep içinde kalıp, 

ONUNLA YAŞASAM.........', 'Beyoğlu bir deniz,  Ben de bir balık olsam. İzin alıp,  Beyoğlu Muhtarından Hep orada kalıp,  İçinde yaşasam. Ne zaman istesem,  Dışına çıkm...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beyoglu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-bekir-ayral-rtvgg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Haftalardır, aylardır.

Ben onu hiç görmedim.

Bir haber gelir diye, 

Yollarını gözledim.

Ne haber geldi, ne sen.

Şimdi; çok yalnızım ben.

Ne olur dönsen bana, 

Yalvarıyorum sana.

Çok özledim ben onu.

Çok bekledim yolunu.

Dönsün diye yalvardım.

Sonunda bak kavuştum.

Dileğim oldu şimdi, 

Sevdiğim bana döndü.

Kalbim sevinçle doldu.

Ve hasretim son buldu.', 'Haftalardır, aylardır. Ben onu hiç görmedim. Bir haber gelir diye,  Yollarını gözledim. Ne haber geldi, ne sen. Şimdi; çok yalnızım ben. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün cok mutluyum', 'bugun-cok-mutluyum-sevda-ulm-8y5ly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluyum

Bugün 

Cok mutluyum

Bir kus kadar özgür

Bir cicek kadar güzel

Ve su kadar temiz hissediyorum kendimi

Bugün

Cok daha alimli

Cok sevecen

Ve cok güclü hissediyorum

Bugün sen i hissediyorum.

(25_agustos_2002)', 'Mutluyum Bugün  Cok mutluyum Bir kus kadar özgür Bir cicek kadar güzel Ve su kadar temiz hissediyorum kendimi Bugün Cok daha alimli Cok seve...', ARRAY['Türk Edebiyatı','Şiir','Sevda Ulm']::text[], 8.5, '{"poet":"Sevda Ulm","poet_slug":"sevda-ulm","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-cok-mutluyum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mimik', 'mimik-i-hsan-uncuoglu-sw6cp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüzümde MİMİK

İnceciğim İncecik

Minnacık burnum altı ağzım olgun

Her iki yanında yanaklarım dolgun

Göz bakışım alnım kaşlarım keman 

Kısa kulaklarım uzadı asılmaktan

Yoruldum durmadan sallarım

Başımı sağ sol her tarafa oynatmaktan, 

***

İnce kalın çıktı bu kantardan

Yazılanlar anlam dolu ne anlam

Anlayana deyiş en büyük rakam

Nefeslenip konuşurum unutmayın

Açılınca çenelerimle dudaklarım 

Fırın diyorlar ağzıma şaşar kalırım,', 'Yüzümde MİMİK İnceciğim İncecik Minnacık burnum altı ağzım olgun Her iki yanında yanaklarım dolgun Göz bakışım alnım kaşlarım keman  Kısa ku...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mimik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sen', 'yine-sen-sevda-ulm-h7ksc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gene sana uyandım

daha öncekiler gibi

sabahın serinliği saçlarımda

gözümde yağmur sesi

sabah umutmuş deme sakın

sabah karanlık

sabah keskin bıçak

sabah sensizlik birtanem

bir köy yolunda yürümek varken senle

bir ormanın kokusunu içimize çekmek varken

didişiyoruz hayatla

göz göze diş dişe

sorma bana ne olur

ağlamamı sorma

sensizliğimi sorma

inci tanesi gibi gözyaşlarıma dokunma

ne garip değilmi

içinde fırtınalar koparken dışının dingin kalması

ve ne garip

gözlerinde sevda varken

gözyaşınında olması

loş ışıklarında yıpranırken şehirlerin

lanet diyorum

bin kere lanet

yanlış zamana isyan ediyorum

su gibi akarmış zaman

boşversene

çakıldı kaldı benim saatlerim sevgimde

gözlerim boşlukta

ufacık bir umuda hasret

sana hasret

zaman durdu bu gece yine

ellerini uzat birtanem

çöz kırlmamış zincirimin kilidini

aksın yüreğim sana doğru

ve askim

sensin bu hayatin sonu', 'gene sana uyandım daha öncekiler gibi sabahın serinliği saçlarımda gözümde yağmur sesi sabah umutmuş deme sakın sabah karanlık sabah keskin ...', ARRAY['Türk Edebiyatı','Şiir','Sevda Ulm']::text[], 8.5, '{"poet":"Sevda Ulm","poet_slug":"sevda-ulm","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yine-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdesin', 'yuregimdesin-sevda-ulm-bg0zu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sevdalar yasanmis

Yüzyillar boyu

Ne firtinali asklar

ne asklar...

Seni 

Bir umutla sevmedim

Bir beklentiyle degil

Yüregini sevdim tek

Beni seven seni sevdim..

Bu sevdada bitecek 

Bütün yasanmislar gibi

Bitmedigi halde bitecek

Ama

bitmeyecek bir sey var

Sen benim kalbimdesin

Benimle toprak olacaksin

Buna hicbirsey engel olamaz

Cünkü

SENBENIM YÜREGIMDESIN..25 eylül 2002', 'Ne sevdalar yasanmis Yüzyillar boyu Ne firtinali asklar ne asklar... Seni  Bir umutla sevmedim Bir beklentiyle degil Yüregini sevdim tek Ben...', ARRAY['Türk Edebiyatı','Şiir','Sevda Ulm']::text[], 8.5, '{"poet":"Sevda Ulm","poet_slug":"sevda-ulm","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yuregimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Has`retim', 'has-retim-sevda-ulm-ljv38', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzyillar oldu sanki

seni görmeyeli

Senden önce yasamis olduguma inanmak

Öyle zorki birtanem

Isyan etmemek öyle zorki! 

Ben cok yalniz

Kimsesizim

Sensizim.......

Sen cok uzaksin bana

Büyüyor icimdeki firtina

Hasretim sana..25 temmuz 2002', 'Yüzyillar oldu sanki seni görmeyeli Senden önce yasamis olduguma inanmak Öyle zorki birtanem Isyan etmemek öyle zorki!  Ben cok yalniz Kimse...', ARRAY['Türk Edebiyatı','Şiir','Sevda Ulm']::text[], 8.5, '{"poet":"Sevda Ulm","poet_slug":"sevda-ulm","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/has-retim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kudüs', 'kudus-nizar-kabbani-d05l8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağladım tükeninceye kadar gözyaşlarım

Namaz kıldım sönünceye dek kandiller

Usanıncaya kadar rüku ettim

Muhammed''i sordum sende kaybolan

Ey Kudüs, ey nebilerin çıktığı şehir

Ey Kudüs, ey şeriatler feneri

Ey parmakları yanan güzel çocuk

Hüzün var gözlerinde, ey iffet şehri

Ey Resulün uğradığı bahçe

Kaldırımlarında hüzün var

Minarelerinde hüzün var

Ey Kudüs, ey karalara bürünen şehir

Kim çalacak çanlarını Kıyamet kilisesinin

Pazar sabahları

Kim taşıyacak çocuklara oyuncakları

Yılbaşı gecesinde

Ey Kudüs, ey hüzünler şehri

Ey gözlerinden kocaman yaşlar akan

Kim durduracak düşmanları

Üzerine çullanan, ey dinlerin incisi

Kim silecek kanları duvarlarından 

İncil’i kim kurtaracak

Kim kurtaracak Kur''an’ı

Kim kurtaracak Mesih’i kendisini öldürenlerden

İnsanlığı kim kurtaracak

Ey Kudüs, ey şehrim

Ey Kudüs, ey sevgilim

Yarın, yarın çiçek açacak limon

Sevinecek yeşil sümbüller ve zeytin 

Gözler gülecek

Geri dönecek göçmen güvercinler 

Tertemiz yuvasına

Ve geri dönecek çocuklar oynamaya

Buluşacak babalarla oğullar

Ey memleketim

Ey barış ve bereket şehri

Çeviren: İlyas Altuner', 'Ağladım tükeninceye kadar gözyaşlarım Namaz kıldım sönünceye dek kandiller Usanıncaya kadar rüku ettim Muhammed''i sordum sende kaybolan Ey K...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kudus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biricik Beyrut', 'biricik-beyrut-nizar-kabbani-m0pw7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık öpmüyorsun beni biricik Beyrut

Gördükten sonra seni insanlar

Güzel bir kuş gibi

Başımın üzerinde iki yıldır

Öpmüyorsun beni biricik Beyrut

Gördükten sonra denizler

Yapışık olarak, daima yapışık

Öpmüyor beni biricik cadde

Geçtikten sonra onu beraber geceleyin

Yıldızlar misali

İşte burdan

Başlıyor sorunum

Ne zaman barda bir şarap istesem

Dikkatsizce taşıyor kadehleri garson

Ne zaman binsem arabama

Açıyorsun kapıyı sessizce

Ve gizleniyorsun arasına koltukların

Ne zaman insem bir havaalanında

Sevgi taşıyorsun bana, çiçek taşıyorsun

Uzatıyorsun ellerini uzaktan

Bilmiyorum

Bir tek kadını mı seviyorum

Yoksa bir kadındaki iki kadını mı

Çevire: İlyas Altuner', 'Artık öpmüyorsun beni biricik Beyrut Gördükten sonra seni insanlar Güzel bir kuş gibi Başımın üzerinde iki yıldır Öpmüyorsun beni biricik Be...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/biricik-beyrut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Olsaydı Aklım', 'kucuk-olsaydi-aklim-nizar-kabbani-s4yi2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yirmi otuz yıl önce

Küçük bir aklım vardı sevgiden yana

İyi olmadı hiçbir dersim

Yalnızca aşkta iyiydim

Cesurdum o zamanlar

Taşırdım elimde güneşi kuş gibi

Gökteki yıldızları birer ağaç görürdüm

Koparırdım onları hırçınca

Ağaçlara seslenirdim şiir yazsınlar diye

Ve çağırırdım uçmaları için balıkları

Yirmi otuz yıl önce

Çocuktum akılsızlığı seven

Değiştirmeyi seven ve kırıp dökmeyi

Yağmur yağdırırdı yıldızlara göğüslerin

Ve serperdi Keşmir’in çevresine

Yirmi otuz yıl sonra

İstiyorum da

Küçük olsaydı aklım

Çeviren: İlyas Altuner', 'Yirmi otuz yıl önce Küçük bir aklım vardı sevgiden yana İyi olmadı hiçbir dersim Yalnızca aşkta iyiydim Cesurdum o zamanlar Taşırdım elimde ...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kucuk-olsaydi-aklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedir Sevgi', 'nedir-sevgi-nizar-kabbani-1yleu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

Nedir sevgi

Okusak da hakkında binlerce eser

Yine de anlamış değiliz okuduğumuzu

Tefsir kitapları okuduk

Astronomi ve tıp okuduk

Bilemedik, nereden başlasak

Ezberledik dünya edebiyatında

Ne varsa şiir ve deneme namına

Tek bir satır bile hatırlamıyoruz onlardan

Sevgi öğretmenlerine sorduk

Onlar da bizim kadar biliyor ancak

II.

Nedir sevgi

Gizemli barınağında sorduk onu fakat

Ne zaman varsak tutmak için

Kaçtı her seferinde bizden

Ardındayız ormanlarda yıllardır

Ve yıllardır bu yüzden kaybolduk

İzledik onu siyah Afrika’ya kadar

Bengal’e, Nepal’e kadar

Karaib denizine kadar ve Mayorka’ya

Amazon ormanlarına kadar

Ancak yetişemedik

Aşk bilgelerine sorduk

Onlar da bizim kadar biliyor ancak

III.

Nedir sevgi

Seçkinlere sorduk, bir de kıssacılara

“En güzel söz” deseler de ikna olmadık

Yoldaşlara sorduk bir kez de

Dediler “Uysal bir çocuk

Nergis üzerine şiirler yazan

Karınca ve ceviz toplayan mama önlüğüne

Düzenbaz ve hırçın bir çocuk

Zalim kedileri bile kandıran”

Aşk muhabirlerine sorduk

Onlar da bizim kadar biliyor ancak

IV.

Nedir sevgi

Takva ehline sorduk, nafile

Din adamlarına sorduk, faydasız

Bir de sorduk sırdaşlara, boşuna

Aşk ehline sorduk onu

Dediler “Terk etti küçükken

Rahatça taşıyarak serçelerle dalı”

Yaşını sorduk akranlarına sevginin

Gülerek cevap verdiler

“Ne zaman biliniyordu ki aşkın yaşı”

V.

Nedir sevgi

İlahi bir iş olduğunu işittik

İnandık buna öylece

Duyduk ki, bir kutsal yıldızmış

Açtık bu yüzden camları her akşam

Her akşam onu bekledik

Bir şimşek olduğunu duyduk

Dokunduğumuzda çarpacak

İşittik ki, keskin bir kılıç o

Çekersek kınından kesiliriz

Sevgi yolcularına sorduk

Onlar da bizim kadar biliyor ancak

VI.

Nedir sevgi

Görsek de yüzünü orkid çiçeğinde, anlamadık

Sesini duyduk bülbülün ötüşünde, anlamadık

Buğday başağı üstünde fark ettik onu

Ve üzerinde ceylanın boynuzlarının

Nisan renkleri içinde

Ayıp işler yaparken

Dikkat etmedik yalnız

Aşk elçilerine sorduk

Onlar da bizim kadar biliyor ancak

VII.

Sevgi krallarına sığındık tarihte

Danıştık bu yüzden bir kez delisine Leyla’nın 

Ve akıl sorduk Lübna’nın delisine bir kez

Keşfettik ki

Biziz kralları adlandıran

Olamadılar aşklarında daha mutlu bizden

Çeviren: İlyas Altuner', 'I. Nedir sevgi Okusak da hakkında binlerce eser Yine de anlamış değiliz okuduğumuzu Tefsir kitapları okuduk Astronomi ve tıp okuduk Bilemedi...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/nedir-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tören', 'toren-nizar-kabbani-4en02', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Şükranlarımı sunuyorum sana

Süslemişti ömrümü çünkü sevgin

Değişimdi her şeye karşı

Her şeye karşı bir başkaldırıydı

Büyüklüktü ve bir çığırtkanlık

Büyük bir törendi

Kalbimin köşesinde yaşayan

II.

Şükranlarımı sunuyorum sana

En güzel çiçeklerle

Büyük bir fetihti çünkü sevgin

Ve asil bir ilham

Yolumu ışıtan ve terbiye eden beni

Düşüncelerimi arındıran

Ve yıldız parıltısıydı

İşaretiydi doğrunun

Güzelin müjdesiydi

III.

Şükranlarımı sunuyorum sana

En derin izlerle

Şüpheden uzaktı çünkü sevgin

En mühim anahtarıydı şiirimin

Ve olmayan bir hadiseydi

Herhangi bir zaman ve yerde

Herhangi bir asırda

IV.

Sunuyorum sana

Neyi sunuyorum ki

Farkında değilim

Çeviren: İlyas Altuner', 'I. Şükranlarımı sunuyorum sana Süslemişti ömrümü çünkü sevgin Değişimdi her şeye karşı Her şeye karşı bir başkaldırıydı Büyüklüktü ve bir çı...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/toren-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağdaş Kültür', 'cagdas-kultur-nizar-kabbani-314g4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.

Eğit beni

Beni eğit

Okumadan evvel yüzünü

Hiç şiir okumadım ben

Ve buğday tenini keşfetmeden

Harabeydi bu dünya

Öğret bana kadın dilini

Ki ben

Bilmeme rağmen sevgiyi

Hiçbir şey bilmiyorum

Ezberlediğim halde halk şiirleri

Ezberlememişim hiçbir şey

İstediğim halde Çin’deki ilmi bile

Fakat Çinli kadınlar

Çay ikram ettiler yalnızca

Öğretmediler sevgiden bir şey

Eğit beni 

Beni eğit

Aldığım diplomalar

Gördüğüm eğitim

Hepsi hayaldi

II.

Öğret bana küçük bir öğrenci gibi

Nasıl cümle kuracağımı göğüslerinden

Dudaklarından nasıl öpücük yazacağımı

Çiz bunlar üzerine benim için yaprak

Nasıl hurma olur kalçası bir kadının

Nasıl tavan olur kadın saçı

Ve nasıl şemsiye olur

Halk şiir

Yaz mevsimi

Azarlama

III.

Başla benimle ilk satırdan

Başla ilk kaymaktan ve ilk kardan

Koltukaltı tüylerinden başla

Çetrefilliğinden bileziklerin

Üstünden başla örgülerin

Dilersen altından başla

İçime giren ve gezinen saldırgan kokudan

Başlangıçtan itibaren başla

Çünkü ben

Kadınlarla olmasına rağmen tarihim

Cevabını bilmiyorum

Çeviren: İlyas Altuner', 'I. Eğit beni Beni eğit Okumadan evvel yüzünü Hiç şiir okumadım ben Ve buğday tenini keşfetmeden Harabeydi bu dünya Öğret bana kadın dilini K...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/cagdas-kultur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var mı Vaktin', 'var-mi-vaktin-nizar-kabbani-l4wh5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne yapıyorsun pazar günü

Var mı vaktin

İncelemek için aşkı

Denizi

Kumsalı

Güzel kelimeleri bu pazar

Var mı vaktin

Gömmek için yüzümü saçlarına

Gün boyu

Var mı vaktin karşılamaya beni

Var mı beni dinlemek için sabrın

Yüzüm harap

Ruhum harap

Ve cesetsiz bir baş gibidir Beyrut

Verebilir misin bana ellerini

Hissetmem için ebediliği

Var mı vaktin hüznüm için

Beyrut katliamından sonra

Bir pazar günüm olmadı hiç

Çeviren: İlyas Altuner', 'Ne yapıyorsun pazar günü Var mı vaktin İncelemek için aşkı Denizi Kumsalı Güzel kelimeleri bu pazar Var mı vaktin Gömmek için yüzümü saçları...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/var-mi-vaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfırın Altında İki Bin', 'sifirin-altinda-i-ki-bin-nizar-kabbani-unvof', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I.

Kibar ve nazik olamadım

Maktuldüm, geldi katil olma vakti

Bitirdi ilişkimizi kesin şekilde

Kaygıya dönüştü ve katil bir yeise

Her zamanki gibi saçların 

Dağıtmadı buğday ve sümbül

Sesin her zamanki gibi

Bülbül sunmadı çocuklara

Bu gece gayet uzun olacak

Uzun bir ara olacak aramızda

II.

Son nefesini vermekte aşkımız

Ulaştı sıfırın altında iki yüze

Ah ne şiddetli hava

Rüzgar söze katılıyor

Bu son gece için değil mi

Şiire giriyor soğuk

Kül tablasına, sigaraya

Yoruldum bu tiyatro gösterisinden

Kürk ve mücevher kongresi önündeki

Yoruldum küçücük rolümden

Yoruldum boyaya bulanmış yüzümden

Buhurdanların yükünden yoruldum

III.

Aşkımız ciddi bir noktada

Geldi sıfırın altında iki bine

Soğuk delip geçiyor elbiseyi bıçak gibi

Delip geçiyor duyguları

Kalmadı gözlerinde bir damla yaş

Ne orman kaldı ne ekin

Ne şiir ne de nesir 

Kalmadı az çok bir neşe

IV.

Güneş doğdu

Sen oturuyorsun bir ucunda yatağın

Bense kar altındaki sevgimi denetliyorum

Güneş doğdu ve bulamadım sevgiyi

Ne büyük ne de küçük

Çeviren: İlyas Altuner', 'I. Kibar ve nazik olamadım Maktuldüm, geldi katil olma vakti Bitirdi ilişkimizi kesin şekilde Kaygıya dönüştü ve katil bir yeise Her zamanki...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sifirin-altinda-iki-bin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZamanınTersine Uçmak', 'zamanintersine-ucmak-nizar-kabbani-isusq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hala kırkındasın

Genç

Şuh

Ve berraksın süt kadar

Göğüslerin

Yarışan atlar gibi

Zamanın tersine uçmakta hala', 'Hala kırkındasın Genç Şuh Ve berraksın süt kadar Göğüslerin Yarışan atlar gibi Zamanın tersine uçmakta hala...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zamanintersine-ucmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Denir Ki', 'ne-denir-ki-nizar-kabbani-bnoua', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binlerce soru yöneltir geceleyin gözlerin

Yayılır dudaklarından portakal kokusu

Kanımın tutuşmasıyla

Tutuşması arasında madenlerin

Bulunur binlerce, binlerce ihtimal

Ne diyeyim öyleyse

Her köşesinde vücudunun

Art arda gelir iklimler

Geçip gider tören

Pek çok söz var bende

Pek çok şiir var

Fakat göğüslerin karşısında 

Ne denir ki

Çeviren: İlyas Altuner', 'Binlerce soru yöneltir geceleyin gözlerin Yayılır dudaklarından portakal kokusu Kanımın tutuşmasıyla Tutuşması arasında madenlerin Bulunur b...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-denir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan Şiir', 'siradan-siir-umut-ulbegi-sshnh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizim yaşadığımız öyle sıradan

bir sevgi olsaydı

Ben öyle sıradan bir genç adam

sen öyle sıradan bir genç kız olsaydın

Her şey bir sabah pat diye bitiverirdi şimdiye kadar

ve biz eski hayatlarımıza geri dönerdik

Belki bazen hatırlardık birbirimizi

bulutların ardından

ama inan yaşayıp giderdik

öyle sıradan...

05.04.1999', 'Bizim yaşadığımız öyle sıradan bir sevgi olsaydı Ben öyle sıradan bir genç adam sen öyle sıradan bir genç kız olsaydın Her şey bir sabah pat...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siradan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk / 12', 'ask-12-umut-ulbegi-btcgw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ocaktı ve ben onu seviyordum

Şubat oldu aşık oldum

Mart''ı Nisan''ı hiç sormayın 

Kovuldum

Mayıs''ta sokaklarda yattım, onunla yatmadım

Haziran, Temmuz sıcakta püfür püfür kaldırım kenarları

Ağustos, Eylül yapraklar düşerken

ilk yağmurlarla ona dönmek istedim

Ekimdi

cesaretimi topladım günlerce

ahmakıslatanlar altında

Kasım geldi

yanaştım

dedim

-Ben seni seviyorum

Uzaklaştı benden

koluna girdi birisi duvar suratlı yosmanın

İşte o Aralık aldım ağzımın payını

Ocak''a pişman daldım', 'Ocaktı ve ben onu seviyordum Şubat oldu aşık oldum Mart''ı Nisan''ı hiç sormayın  Kovuldum Mayıs''ta sokaklarda yattım, onunla yatmadım Haziran...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-12-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bestekarrın Aşkı', 'bestekarrin-aski-naci-eray-kins4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Senin Kaçıncı Şiirinim Bilemem

Ama Sen Benim Son Bestemsin, Unutma', 'Ben Senin Kaçıncı Şiirinim Bilemem Ama Sen Benim Son Bestemsin, Unutma...', ARRAY['Türk Edebiyatı','Şiir','Naci Eray']::text[], 8.5, '{"poet":"Naci Eray","poet_slug":"naci-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bestekarrin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyimsin', 'herseyimsin-pervin-adalioglu-1zkve', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir günahsa seni sevmek

bin yıl günah işlerim

bir gözyaşı ise sarılmalarım

gözpınarlarım kuruyuncaya dek akıtırım.

yorulmaksa seninle elele koşmak

ayaklarım yara olana kadar koşarım.

çılgınlıksa kalabalığın içinde seni sevdiğimi haykırmak

binlerce değil milyonlarcanın içinde sesim kısılana kadar haykırırım.

seni sevmek mutluluksa benim için 

sarılmalarım sevinçten akıtıyorsa gözyaşlarımı

seninle kırlarda koşmak hayallerimse

bir ayrılık ise seni göremeyişlerim

bedenimden çıkar yine sana gelirim.', 'bir günahsa seni sevmek bin yıl günah işlerim bir gözyaşı ise sarılmalarım gözpınarlarım kuruyuncaya dek akıtırım. yorulmaksa seninle elele ...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/herseyimsin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Tanımasaydım Seni', 'keske-tanimasaydim-seni-sair-blues-f1klt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keşke tanımasaydım seni

Omuzlarıma bu kadar yük binmezdi o zaman

Gözlerim ağlamayı bilemezdi

O kadar sık kalbim çarpmazdı böyle delicesine

Benim de ellerim sımsıcak olurdu mutlaka

Geceleri asla uykusuzluk çekmezdim sabaha kadar

Rüyalarım, hatta tatlı hayallerim olurdu

Duygusuzca düşünmezdim yokluğunda günlerimi, saatlerimi

Hem hiç üşümezdim böylesine ölü soğukluğunda 

Hırsla takip etmezdi beni böyle kötü kaderim

Kan çanağına dönmezdi gözlerimin ta içi

Kayan yıldızlarda bende farklı dilekler tutardım

Duyardım anlardım yanımda konuşulanları 

Hasretim bu kadar artmazdı o zaman

Bende gülerdim zaman zaman

Deniz ve mehtap benim içindi önemli olan

Hele hele kara saplı bıçak dostum olmazdı sırtımda

Bir de sırtımın yanında kavrulmazdı ciğerlerim

Beynimse böylesine hırçın uğuldamazdı sürekli

Kar yüreğimde damla damla vurmazdı gözyaşlarım

Ruhum daraltmazdı benliğimi sıkıştırmazdı

En cüssesiyle çığlıklar atmazdı göğsüm

Simsiyah yankılar oluşturmazdı ufkumda

Saçıma sakalıma bende bakardım delicesine

Bütün gücümle sigaramı her an keşke tanımasaydım seni keşke

Kara saplı bıçak dostum olmazdı kar yüreğimde damla damla

Vurmazdı gözyaşlarım dedim ya ulan

Keşke keşke tanımasaydım seni', 'Keşke tanımasaydım seni Omuzlarıma bu kadar yük binmezdi o zaman Gözlerim ağlamayı bilemezdi O kadar sık kalbim çarpmazdı böyle delicesine B...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/keske-tanimasaydim-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yaşadıklarım', 'seninle-yasadiklarim-sair-blues-et85f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çokmu uzak yollar bize, 

Yoksa korkularınmı var

Bu kadar zaman sonra

Yoksa seninle yaşadıklarım

Düşmü, gerçekmi...

Kırıldığımdan değil, 

Korku veriyorsun bana

Yanılma korkusu, aldanma

Bir garip düş sokağımsın

Yoksa seninle yaşadıklarım

Çecapsızmı kalaçak...

Dört mevsim papatya gördüm, 

Çeşit çeşit güllerde...

Sana olan hasretimi anlattım

Işıl ışıl sularda, mırıldandım seni

Doğa anaya

Yoksa senin ile yaşadıklarım

Beni kör eden duygularmı...

Seni düşündüm, ölümü düşündüm

Sana kızdım, kendime kızdım

Sana güldüm, kendimede amansızca

Yoksa seninle yaşadıklarım

Beni delimi ediyor...

Bir yerden ses ver, nefes ver

Yaşadığını bileyim

Nerden bilebilirimki

Koca bi zaman akıp gidiyor

Yaşadığımızdan habersizim

Yoksa senin ile yaşadıklarım

Ayrı dünyalarmı...

Çok yorgunum, 

Sevdan beni harap etti, mahfetti

Hangi dilden anlarsın bilmemki

Yüreğim yanık, sevda şarkıları çalıp duruyor

Gözlerim dolu, yeni denizler için

Yoksa senin ile yaşadıklarım, 

Senden fazla büyüdü, yanımda...

Yanımda sen olmayınca, 

Derin duygular beni bırakmaz oldu

Sevdalandık sanki

Halbuki demir atmıştım sevdana

Katıksız sevdalılar ile

Off off bittim ben, külümü denize at

Yakından çağırıyorlar, gideceğim

Neyleyeyim bu dünyayı güle güle, 

Sen olmayınca...

Yoksa senin ile yaşadıklarım, 

Sensiz yaşadıklarımdan mı...''', 'Çokmu uzak yollar bize,  Yoksa korkularınmı var Bu kadar zaman sonra Yoksa seninle yaşadıklarım Düşmü, gerçekmi... Kırıldığımdan değil,  Kor...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seninle-yasadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım ve Ben', 'yalnizligim-ve-ben-sair-blues-32zvn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımla başbaşayım yine

Hayaller ve anılarla

Yaşamımı hatırlayıp 

Ağladığım yalnızlığımlayım

Sadece duygularımı paylaşan

Kader var yanımda

Yalnızlığa düşmüş bir kuş gibi

Çaresiz kanadı kırık 

Yinede yılmadan ama gözyaşlarına yenilerek...

Terkedilip bırakılan bir güvercin gibi

Anılarımla ve kaderimle paylaşıyorum herşeyi...

Çaresizliğimi, umarsızlığımı

Yalnız bırakılan fakat yılmayan

Kimseye muhtaç olmayan

Ama ağlayan...

Bir dağ yamacına oturmuş

Geceyi ve gündüzü düşünüyorum sadece...

Sadece içimi yakan ateş gibi

Kıvılcımlanıp yaşadığım acı günleri yakmak istiyorum...

Yakmak istiyorum ki

Kül olup ortadan kalksınlar diye

Beni sadece yalnızlığımla bıraksınlar diye

Düşünüyorum.....

Seni düşünüyorum yinede Yılmadan bıkmadan 

Damla, damla dökülen yağmurlar gibi

Işte yine yanaklarım ıslandı

Yine aynı şey oluyor 

Ne zaman seni düşünsem

Hep aynı şey oluyor bana

Ama sen beni hiç sevmedin ki 

Beni yalnızlığımla başbaşa bıraktın

Şimdi kuş olup uçmak isterdim

Bulutların üzerinde

Aşağıya bakmak isterdim

Seni görürüm diye

Sevgimin bitmediğini 

Sana göstermek için

Sensizliğin acı yüzünü

Sevmenin şevkatsizliğini 

Göz yaşlarımın bile ezildiğini

Sana göstermek için', 'Yalnızlığımla başbaşayım yine Hayaller ve anılarla Yaşamımı hatırlayıp  Ağladığım yalnızlığımlayım Sadece duygularımı paylaşan Kader var yan...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yalnizligim-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımadan Önce', 'seni-tanimadan-once-sair-blues-h4s3d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni tanımadan önce SEVMEK nedir bilmezdim....

Ben sevmeyi seni dinleyerek öğrendim! 

Seni tanımadan önce DERT nedir bilmezdim....

Söylemesi acı ama bana derdi sen verdin! 

Seni tanımadan önce AĞLAMAK nedir bilmezdim....

Ben ilk defa senin icin ağladım! 

Seni tanımadan önce YAŞAMAK nedir, nasıldır bilmezdim....

Ben yaşamayı senin o sevgi akan, dert dolu, ağlayan gözlerine bakarak öğrendim', 'Seni tanımadan önce SEVMEK nedir bilmezdim.... Ben sevmeyi seni dinleyerek öğrendim!  Seni tanımadan önce DERT nedir bilmezdim.... Söylemesi...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-tanimadan-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gül Olsaydım', 'bir-gul-olsaydim-sair-blues-hesjm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gül olsaydım 

Yaprağım olur muydun 

Kırmızı yapraklarıma kan veren 

Toprağım olur muydun. 

Bir gül olsaydım 

Sende bulut olur muydun 

Benden uzak olduğun için 

Ağlar durumuydun 

Bir gül olsaydım 

Beni dalımdan koparırmıydın 

Odandaki vazoya kor 

Her zaman yanımda olurmuydun 

Eğer bir güle bu kadar değer verirsen 

Onu candan çok seversen 

Bırak bu gülün bir yaprağı olayım 

Ve gözlerinin önünde yavaş yavaş solayım. 

Sende benim gibi gül olamayasın 

Hasret acısı ile sararıp solamayasın 

Güller tek değildir bir birine benzer 

Ama sen benim bir tanemsin', 'Bir gül olsaydım  Yaprağım olur muydun  Kırmızı yapraklarıma kan veren  Toprağım olur muydun.  Bir gül olsaydım  Sende bulut olur muydun  Be...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-gul-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradım Seni', 'aradim-seni-sair-blues-uliea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevda şarkısında

Dağların arasında

Kuşların kanadında aradım seni

Volkan ağzında

Alevler arasında

Bir damla göz yaşında aradım seni

Bir umut yumağında

Güllerin arasında

Mehtabın ışığında aradım seni bulamadım seni', 'Bir sevda şarkısında Dağların arasında Kuşların kanadında aradım seni Volkan ağzında Alevler arasında Bir damla göz yaşında aradım seni Bir ...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aradim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız', 'yalniz-sair-blues-9cjsx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin yokluğun, senin sefilliğinde

Ümidimi yedim geceler boyu

Kadehlerden söz etmek istemiyorum

Hem dünden daha çok sarhoşum.

Geçer unuturum diyordum

Her gün yeni bir kanama gönül yaramda

Gün geçtikçe artıyor sızılar

Artık dayanamıyorum.

Bir duman yaşartır gözlerimi

Bilmiyorum bu kaçıncı

Parmaklarımı yakan sigaram

Yorgun dalgalarda yaşlı gözlerim

Oturmuş

Karanlık gecelere dert anlatıyorum.

Seni düşünürüm geceler boyu

Ve bir sözün gelir aklıma: 

''gözden ırak olan gönülden de ırak olurmuş''

Doğru, yıldızlar kadar uzaksın bana

Üstelik unutmam gerek seni

Fakat neden

Neden unutamıyorum? 

Bu kez ümitsizlik çepeçevre sardı

Karamsarlık geceler kadar derin.

Ve ben sahnede yalnız kalan aktör

Gülen ağlayan alkış tutan seyirci

Tutmuşum bir de

Mutluluğa öpücükler yolluyorum.', 'Senin yokluğun, senin sefilliğinde Ümidimi yedim geceler boyu Kadehlerden söz etmek istemiyorum Hem dünden daha çok sarhoşum. Geçer unuturum...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yalniz-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-sair-blues-nugwa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizken seninle olmayı özlemedim hiç

Seninleyken de sensizliği

Seni seviyorum diyemedim

Her şey bitti

Madem ki bir oyundu yaşadığımız

Oynarken söyleseydin

Oyun sonunda oyunbozanlık

Dostluğu öldürdü sadece

Yanlış şeyi vurdun

Kanın hala yerde', 'Sensizken seninle olmayı özlemedim hiç Seninleyken de sensizliği Seni seviyorum diyemedim Her şey bitti Madem ki bir oyundu yaşadığımız Oyna...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sensizken-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Senin İçin', 'sadece-senin-i-cin-sair-blues-71i9b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkımı kalbime gömüp de gidiyorum

Sonsuz bir okyanus da gittikçe batıyorum

Niye diye sorarsan çünkü seni seviyorum

Tek bir anım bile geçmiyor sensiz

Saatler dostum oldu çünkü çok sessiz

İnanmazdım asla böyle seveceğime

Gizli aşk yarası şarap gibi kadehte

İçimden bir ses diyor ki belki

Neden olmasın özgür niye sevmesin seni

Sevmeyişinin sebebi elbette belli

Başkasıyla yaşıyor senelerden beri

Üzülmek neye yarar böyle bir durumda

Seviyorsan durma sakın kalbinin yolunda

Kalbimdeki yara aşkım gibi büyüyor

Seni gördüğümde kalbim isyan ediyor

Sensiz geçen zamanlar beni çok boğuyor

Ne olur acı bana galiba sonum geliyor

Unutma sakın doğru olan bu değil

Kalbini dinle aklını değil

Üsteleme işte fazla sevmeyecek seni

Başı sonu belli hikayelerden biri

Başın öne eğik durma sakın asla

Boynunu dik tut bak birazcık bana

Ağlıyorsun sanırım içini dök rahatla

Aşk değil seninki si apaçık karasevda

Aşkından eridim bittim tükendim

Seviyorum seni benim güzel sevgilim

Sen güzelim evet evet sen

Bir kere konuşup bin kere öldüren

Hayatı her zaman toz pembe zanneden

Unutmak imkansız deli gibi severken

İnanasım gelmiyor başka sahte aşklara

Uyan artık adamım gerçek aşkın karşında

Ağzımla kuş tutsam, saatlerce yalvarsam

Hiçbir işe yaramaz dağa bile tırmansam

Umudunu yitirme sakın yere çökme

Uyan artık adamım biraz beni dinle

Ne demişti sana o yazdığı kağıt da

Vaz geç bu sevdadan işleri zorlaştırma

Engel olamıyorum duyduğum aşka

Tutamıyorum kendimi bağlanmışım sana

Yalan olan tek bir şey var oda fani dünya

Seviyorum seni işte gerçek bir rüya

Keşke ondan önce tanısaydım seni

Kaybettim işte gene bir oyun misali

Ne kadar zor bir yaşam bilemezsin ki

Kendimi unuttum senden beri

Boşuna bu oyunlar boşuna bu isyan

Hiçbir zaman sevmeyecek canını bile versen

Kim bilir belki 40 yıl sonra

Ayrılıp döner O umut dolu yıllara

Geç kaldın güzelim tren kalktı artık

Kalbinin yolunda yarı yoldan saptık

Dualarım hep seninle olsun

Çok zor ama yolun açık olsun

Çaresizim bana çekilmek yakışır

Ama unutma sakın kalbim seni yaşatır

Ne olursa olsun ancak ölüm ayırır

Aşkım öyle büyük ki hiçbir engel tanımaz

Ölüm olsa bile sonunda bu kalp senden ayrılmaz

Umarım bir gün anlarsın sende

Aşkımın büyüklüğü saklı kalmaz bende

Her şeyim feda senin gibi güzele

Öl desen ölürüm dizlerinin dibinde

Seviyorum seni de yeter ki evet de

Dünya bile dar gelir böyle bir sevince

Her rüya görüşümde aynı senaryo

Seven üzülür kaybeden aşk dır

O şirin yüzünle kaç canlar yaktın

O güzel gülüşünden yanlış yola saptım

Bilemez sin seni benim ne kadar sevdiğimi

Uğrunda hayatımı feda edeceğimi

Karşında bir yürek deli gibi çarpar

Niye sanki her zaman seven adam ağlar

Biliyorum korkuyorsun gücün yok buna

Her şey çok basit o şirin dünyanda

Kaçıp kurtulmak istiyorum bazen

Aşkın ızdırabını kalbimde yaşarken

Sorun buysa dostum cevap veriyim sana

Evet doğru bildin sorun kara sevda

Geliyorsa içinden durma sakın ağla

Akan her damla bir acı dolu pırlanta

Yaşamak bir işkence seni onla görünce

Öylece bakamam bu sahte gülüşlere

Olan oldu artık ölüm yakındır bana

Anlamsız gelir hayat sen yokken yanımda

Giderken arkamdan bakma sakın bana

Ağlarken dayanamam koşarım gene sana

Sanırım yaşamak en büyük yanlış

Sensizlik benim kaderime yazılmış

Gidiyorum şimdi bir yolcu gibi

Hayallerim omzumda

Umudum toprak da

Görüşmek üzere öteki dünyada....', 'Aşkımı kalbime gömüp de gidiyorum Sonsuz bir okyanus da gittikçe batıyorum Niye diye sorarsan çünkü seni seviyorum Tek bir anım bile geçmiyo...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/sadece-senin-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-sair-blues-v2q1i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden ötesi yok bana YAR

Adını anamazsa

Tadını alamazsa ruhum

İlk sönen yıldız olurum.

Bende saklı mektupların var

Satırlarında gizli bir aşk yakar

Gecenin bir yarısında

En gizli odalarda

Beklerim seni yar

Alıp verdiğin her nefes ruhuma dolsun

Senle esen rüzgarlar şarkımız olsun

Kış bahçelerinde aşk bizi bulsun

Bu şehir sensiz bana haram olsun yar

Senden ötesi yok bana yar

Elini tutamazsa, 

Sesini duyamazsa ruhum

İlk sönen yıldız olurum.

Bende saklı mektupların var

Satırlarında gizli bir aşk yakar

Gecenin bir yarısında

En gizli odalarda

Beklerim seni yar', 'Senden ötesi yok bana YAR Adını anamazsa Tadını alamazsa ruhum İlk sönen yıldız olurum. Bende saklı mektupların var Satırlarında gizli bir a...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayılmaz mı', 'sayilmaz-mi-sair-blues-bzy0q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağlamak için illede gözyaşımı akmalı 

Dudaklar gülerken kalp ağlamaz mı 

Sevmek için illede güzele mi bakmalı 

Çirkindeki güzel ruh insanı bağlamaz mı 

Hırsızlık sadece para çalmakla mı olur 

Kalp çalmak hırsızlık sayılmaz mı', 'Ağlamak için illede gözyaşımı akmalı  Dudaklar gülerken kalp ağlamaz mı  Sevmek için illede güzele mi bakmalı  Çirkindeki güzel ruh insanı b...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sayilmaz-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktum', 'yoktum-sair-blues-1vkiv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Var oldum sen gelince gecemde yıldız çoğaldı. 

Sen gülünce ne geçmişin tasası ne gelecek kaygısı

Hep arayıp durduğum anı buldum seninle 

Al sorgusuz sualsiz mahkum et yüreğine

Al beni de zamansız sürgün et gözlerine

Seni sevdiğim sürece gitmelerim gitmek değil

Her hoşçakal hoşgeldinin habercisi

Ve büyümek yok seni sevdikçe

Her dokunuş bir çocuğun sevgisi

Aşkın başı hayal sonu bir gerçek

Her gelişin bir aşkın hikayesi

Gözlerini gördükçe ve yüzünde gülleri

Her ölümüm bir diriliş nedeni

Her gidişin bin ölümüm', 'Var oldum sen gelince gecemde yıldız çoğaldı.  Sen gülünce ne geçmişin tasası ne gelecek kaygısı Hep arayıp durduğum anı buldum seninle  Al ...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoktum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maviye Sitem', 'maviye-sitem-sair-blues-pv0hm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gök alabildiğine masmavi, 

Pürüz addedilebilecek bir bulut bile yok

Öylesine bir mavi kaplamış ki gökyüzünü

Gözlerindeki unutamadığım mavilik var sanki

Yıllarca koştum ardından yıllarca

Benliğimin farkında bile değildin sen

Oysa gözlerimin derinliğinde

Kaybolmuşluğunun hikayesi yatıyor

O hikaye ki yıllarca sensiz

Aynen tekrarlanıyor

Ben bu maviliği sevdim, seni sevdim bir tanem 

Ellerini, yüzünü, benliğini sevdim

Sensizliğin uçsuz bucaksız çölünde

Bir dirhem mavi merhem oluyor

Senin için döktüğüm göz yaşlarım

Sensizlik çölünde vaha oluyor

Bu sevgi bitemez, bitmemeli

Sensizlik çok acı mavim

Ne olur gitme geceleri yıldızlar bile sana hasretimi arttırıyor

Gündüz, mavi gökyüzünde güneş

Terk etme ne olur, boş ver kırgınlıkları

Seni sevdim inan tertemiz

Sadece seni, unutma ne olur beni', 'Gök alabildiğine masmavi,  Pürüz addedilebilecek bir bulut bile yok Öylesine bir mavi kaplamış ki gökyüzünü Gözlerindeki unutamadığım mavili...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/maviye-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-sair-blues-95wf7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili 

İşte senin yanındayım, yanyanayız sevgili

Varlığın can katıyor inan cana sevgili

Sen sensiz kalmadın ki bilemezsin sevgili

Silinmez bir yazıyım silemezsin sevgili

Git demek istesen de diyemezsin sevgili

Birlikte yola çıktık dönemezsin sevgili

Ayak sesleri duysam

Umutla dolu olsan

Belki desem yatarken

Belki ile uyansam

Kollarımı sıkıca 

Bir tek cisme dolasam

Sen ceylan gibi koşsan 

Ben de hep avcı olsam

Bu olsalar bir olsa

Ben olsalarsız kalsam

Olsaların sonunda

Azraille buluşsam', 'Sevgili  İşte senin yanındayım, yanyanayız sevgili Varlığın can katıyor inan cana sevgili Sen sensiz kalmadın ki bilemezsin sevgili Silinmez...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgili-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Merak', 'sadece-merak-sair-blues-n3hzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayallerini süsleyen kim artık gözyaşım

Gözlerini, burnunu, yanaklarını kim seviyor dudaklarıyla

Merak ettim gözyaşım

Kimin eline sarılıyor elin

Kimin kalbini hapsetmiş bakışlarının sıcaklığı

Merak ettim gözyaşım

Gitarın kime söylüyor şarkılarını

Yüreğinden kopan buseler kimin dudaklarına konuyor

Merak ettim gözyaşım

Sıcak duyguların kiminle dans ediyor benim sessizliğimde

Kimin kulağına gidiyor gizli fısıltılar

Merak ettim gözyaşım, sadece merak', 'Hayallerini süsleyen kim artık gözyaşım Gözlerini, burnunu, yanaklarını kim seviyor dudaklarıyla Merak ettim gözyaşım Kimin eline sarılıyor ...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sadece-merak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuz Gül', 'susuz-gul-sair-blues-txfsy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurumuş gülleri saklar mısın

Ben saklarım sana benzedikleri için

Yağmurlu bir günde kendini yollara atar mısın

Ben atarım göz yaşlarım yağmura karışsın diye

Hiç terkedilmek nedir bilir misin

Ben bilirim sensiz kaldığım o günleri

Tekrardan sever misin beni eskisi gibi

Ben seviyorum eskisinden de deli

Yine bırakıp gider misin gizlice beni

Ben gidemem seni bensizliğe esir edemem

Ama şunu bil ki; ne zaman unutursun beni

İşte o susuz gül soldurur kendini', 'Kurumuş gülleri saklar mısın Ben saklarım sana benzedikleri için Yağmurlu bir günde kendini yollara atar mısın Ben atarım göz yaşlarım yağmu...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/susuz-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sevgilim', 'aglama-sevgilim-sair-blues-oy8d4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karşıma geçipte bana bakardın, 

Cennet gülü gibi bir aşk kokardın.

Bir saat gelmesem yollara bakardın, 

Bak yine yollara, ağla sevgilim...

Akşam oldu yine sardı karanlık, 

Kuş tüyünde yatsam olur samanlık, 

Ezdi yüreğimi zalim ayrılık, 

Beni hayal edip, ağla sevgilim...

Birgün bana kara haber gelirse, 

O yar benden kopup ele giderse, 

Başına geleni hep benden bilirse, 

O zaman ölürüm, canım sevgilim...

Bir gün bir kara haber geldi uzaktan, 

Meğerse başkasına varmış yarim, 

O zaman öleyazdım kahırdan, 

Ağladım gece gündüz, canım sevgilim', 'Karşıma geçipte bana bakardın,  Cennet gülü gibi bir aşk kokardın. Bir saat gelmesem yollara bakardın,  Bak yine yollara, ağla sevgilim... A...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglama-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatılması Güç', 'anlatilmasi-guc-sair-blues-crf6l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ulaşılmaz bir güzelliksin içimde, 

Avuçlarıma bıraktığın büyük yokluğun, 

Öyle bir büyüsün ki göz bebeklerimi soran, 

Çözülmesi güç, 

Hangi denizlerin derinliği saklı bakışlarında, 

Hangi gecelerin gizliliği, 

Anlaşılması güç, 

İnce şarkılar gibisin dudaklarımda, 

Her nağmesi sitem, 

Her nağmesi bir sır taşır, 

Anlaşılması güç, 

Yitik acılardan sonra gelen, 

Bir yağmursun iliklerime işleyen, 

Kanımda bereketsin, 

Gözlerimde renk, 

Sana neler borçluyum bilemezsin, 

Anlatılması güç...', 'Ulaşılmaz bir güzelliksin içimde,  Avuçlarıma bıraktığın büyük yokluğun,  Öyle bir büyüsün ki göz bebeklerimi soran,  Çözülmesi güç,  Hangi ...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlatilmasi-guc-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-sair-blues-fiudd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece resimlerin geçti elime

Uzun süre baktım

Ağlamak istedim bütün gece

Gözyaşlarım seni hatırlatır sandım

Ağlayamadım...

Sonra bir mektup ilişti gözüme

Bıkana dek okudum 

Haykırmak istedim kaderime

Dökülen heceler sana ulaşır sandım

Haykıramadım...

Şimdi son nefesimi veriyorum

Biliyorum gideceğim yakında

Hayır acımanı istemiyorum sevgilim

Acıma bana

Yıllar önceki sözünü 

Şimdi ben sana söylüyorum

Elveda', 'Dün gece resimlerin geçti elime Uzun süre baktım Ağlamak istedim bütün gece Gözyaşlarım seni hatırlatır sandım Ağlayamadım... Sonra bir mekt...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayrilik-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Şeyi Unutma', 'bir-tek-seyi-unutma-sair-blues-b6tj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni sevdim ben

kalbim simdi bir sokak çocuğu

kelebekleri göç etti gönlümün

ıssızlaştı hayat sanki

sanki sabahı eksik şiirlerimin

sanki gecesi hep kanayan bir yara

ve sanki artık hep kanayacak

ağlanacak bir aşkın kıyısına vurduysa gözlerim

çare yok ağlayacak

Bir tek şeyi unutma

seni sevdim ben

kapıları kendime ben açamadım

ya da yanlış saatlerde bekledim gelmeni

ter içinde takvimler

istasyon öksüzlüğünde gözyaşım

düşünüyorum da sen gideli ne çok yalnızım

sarmaşık aşkın sarışında kaldım, sarılamadım

savunamadım seni kimselere

anlatamadım seni kimselere

kimsesiz kaldım

en çok da sensin

Bir tek şeyi unutma

seni sevdim ben

sana uyumak

sana uyanmaktı hayat

sıratını geçtim yasarken, korkmadan

korkumu geçtim cesarete ihanetle

berduş bir, yalan masumiyeti öptüm bile bile

tek sen gitme diye

sonbahar oldum, yaprak yaprak

ağaç oldum köklerimi unutarak

tesellisiz bir geceye fırlatıldım

kalbimi dar bir kafese kapatarak

içimde bir kanarya

hiç susmadan ağlayacak

Bir tek şeyi unutma

seni sevdim ben

yakamozlarında yıkadım sevdamı çırılçıplak

seni sevdiğimi bağırdım mehtabına

beyazında aklandım bulutunun

mavi mavi sevdim seni

içim kan ağlayarak

Bir tek şeyi unutma

seni sevdim ben

anlattıkça kış vuruyor satırlarıma

anlattıkça üşüyor, anlattıkça ısınıyor yüreğim

bu gün sardunyalarım da açmadı

belki de küskün renklere

ellerimde ibadet gibi yaşadıklarım

ellerimde günah gibi yaşayamadıklarım

sensiz soluyorum anlayacağın

mavi mavi ölüyorum

duyuyor musun orda mısın var mısın yok musun

Bir tek şeyi unutma

seni sevdim ben

yanarak

yıkılarak

aklıma her geldiğinde AĞLAYARAK', 'seni sevdim ben kalbim simdi bir sokak çocuğu kelebekleri göç etti gönlümün ıssızlaştı hayat sanki sanki sabahı eksik şiirlerimin sanki gece...', ARRAY['Türk Edebiyatı','Şiir','Şair Blues']::text[], 8.5, '{"poet":"Şair Blues","poet_slug":"sair-blues","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bir-tek-seyi-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımındayım', 'adimindayim-siyar-durul-d2oyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arkandan geliyorum gittiğin yere.

Attığımız adımların aralıkları bile aynı.

Düştüğün çukura da düşüyorum, çıktığın tepeye de çıkıyorum.

Tabanlarımızda aynı çamur var.

Ayaklarımızı aynı yerlerden yaralıyor aynı taşlar.

Nasırlarımız bile aynı yerlerden çıkıyorlar.

Ayakkabıyla başladığın yürüyüşe, çıplak ayakla devam ettiğin belli oluyor.

Aynı yerde çıkarıp fırlatıyorum ayakkabımı.

Ayağına batan dikenlerde hala kan var.

Artık, benim ayağımdaki yarada da senin kanın var.

Bazen senin izlerinin yanında bir çift ayak izi daha görüyorum yolun tamamını tek başına almamışsın biliyorum.

Etrafıma bakıyorum ama yanımda yürüyecek kimseyi bulamıyorum.

Ben de bu yolda büyüyorum, ayaklarım ayak izlerinle büyüyor, 

En son kırküç numarada duruyoruz ikimiz de.Kırküç numara ayak izlerine, kırküç numara ayak basıyor ve de yakışıyor.

Artık ben de büyümüyorum senin gibi.

Bazen koştuğunu düşünüyorum, adım aralıkların açılıyor.Ben de koşuyorum ve biliyorum ki izlerin bittiği yerde ben de ölüyorum.', 'Arkandan geliyorum gittiğin yere. Attığımız adımların aralıkları bile aynı. Düştüğün çukura da düşüyorum, çıktığın tepeye de çıkıyorum. Taba...', ARRAY['Türk Edebiyatı','Şiir','Şiyar Durul']::text[], 8.5, '{"poet":"Şiyar Durul","poet_slug":"siyar-durul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adimindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar-ı Sevda (Sen Ay Ben Su)', 'nar-i-sevda-sen-ay-ben-su-yavuz-sayin-bqgqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay sununca sulara nar, sular birdenbire yanar, 

Yıldızlanır yürekte aşk, efkar ondan sonra başlar.

Sevda ağır, susma bağır, yar duvarlar gibi sağır.

Uzaksınya bitmez kahır, ne de birazcık azalır, 

Nihayetinde yangının, geriye sadece kül kalır.

asena''ya (trabzon)      2001', 'Ay sununca sulara nar, sular birdenbire yanar,  Yıldızlanır yürekte aşk, efkar ondan sonra başlar. Sevda ağır, susma bağır, yar duvarlar gib...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sayın']::text[], 8.5, '{"poet":"Yavuz Sayın","poet_slug":"yavuz-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nar-i-sevda-sen-ay-ben-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ve Sevda', 'gul-ve-sevda-ufuk-demir-4opa1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güle benzettim sevdamı 

Seni sevdiğim gibi 

Yalnaz kalan bir tek gülü sevdim', 'Güle benzettim sevdamı  Seni sevdiğim gibi  Yalnaz kalan bir tek gülü sevdim...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Demir']::text[], 8.5, '{"poet":"Ufuk Demir","poet_slug":"ufuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gul-ve-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Zaman', 'sakli-zaman-gulsum-yesilcicek-zgqqk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Darıldım ben zamana, vehmi saklı zamana.

İçinde girift bir iz, dışı boyalı kana.

Açılsın sahte yüzler, gizli kalmasın çehre, 

ağıtlarım sürükler beni o meçhul şehre.

Hani sevdiğim çiçek, hani papatyam nerde? 

Nerde ektiğim gerçek, mahsuller saklı gökte.

Ezeleden beri buydu, dünya bir çöp yığını, 

Mukaddesler ruhuydu, İhtişamın kıymığı.

Kan, damarala yarışır, düzendir bu değişir, 

Ayrılan tozlu yollar, gün gelir de kesişir.

Hatıram, soğuk kezzap, kafam boş bir teneke, 

İsmim konuldu ''azap'' tabut bana hediye.

Mezarım soğuk yatak, zifir idi toprağım, 

Ebediyetse batak, süründü yokum varım.

Sığınak kanlı odam, duygular barut satar, 

Tepeme yıkılsın dam, şivan inerken yakar.

Baharları silin de kış yakın ocağıma, 

Güneşim buz tutuyor, har düşmez toprağıma.

Gençliğim sona erdi, döndüm arz-ı yuvaya

Ellerim göğe açık, yüzüm dönük mevlaya..', 'Darıldım ben zamana, vehmi saklı zamana. İçinde girift bir iz, dışı boyalı kana. Açılsın sahte yüzler, gizli kalmasın çehre,  ağıtlarım sürü...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Yeşilçiçek']::text[], 8.5, '{"poet":"Gülsüm Yeşilçiçek","poet_slug":"gulsum-yesilcicek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sakli-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderimi benmi yazdım', 'kaderimi-benmi-yazdim-salih-ozalasan-9lmtc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaderimi benmi yazdım

Hesabını benden soruyorsun

Nerede gülecek benim bahtım

Acımasız birde sen vuruyorsun

Kaderime boyun eğmeyeceğim

Sen beni kadere yenilirmi sanıyorsun

Tersine çevireceğim alnımdaki yazıyı

Seni ben yazacağım inadına alnıma

Kıracağım bahtıma vurulan zinciri

Beni hayata bağlayan sensin biliyorsun

Eğilmedim kimsenin önünde

Kaderimide yeneceğimi iyi biliyorsun

Yıkılmadım yıllara okudum meydan

Vazgeçmedim asla ne yardan ne serden

Değiştirmek belki çok zor

Ama kaderimi deleceğim bir yerden

Sensizliği yıkacağım hayatımdan

Gerekirse herşeyi çıkaracağım yaşantımdan

Yok artık korkum ne kaderimden ne bahtımdan

Zalim kader boyun eğecek, edeceğim onu tahtından

Sensiz geçen zamanı durduracağım

Dönmeyeceğim sonsuza dek yolumdan

Yenildiğim yeter bunca zaman kadere

Galip çıkan ben olacağım bu oyundan

Sende göreceksin, sende bileceksin

Sevgilerin kadere asla yenilmediğini

Sen uçup gitsende kucağımdan

Asla çıkmayacaksın hayatımdan

Kader bana hayatı  etmişti zindan

Çok acı çektim çok ağladım

Çok dersler çıkardım 

Artık kaderimi tanıyorum çok yakından

Belkide ilk ben olacağım

Kaderi yıkan onu indiren tahtından

Belki isyan belki feryat kadere meydan okumam

Ama oda korkup kaçacak, yüreğimdeki aşkımdan

Y.Tar 06-11-2002 Saat 23.05', 'Kaderimi benmi yazdım Hesabını benden soruyorsun Nerede gülecek benim bahtım Acımasız birde sen vuruyorsun Kaderime boyun eğmeyeceğim Sen be...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kaderimi-benmi-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Aklıma Gelmendir', 'ask-aklima-gelmendir-oguzkan-bolukbasi-oclnr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk

senin aklıma gelmendi

senin düşünülmendi 

hicran kayalıkları üzerinden düşmemdi

öyle bir şeydi ki

güzeldi

acı vericiydi

esrar gibiydi

altın vuruştu

seni sevdiğimi söylemek

öldüm

kolumda sevdanın izleri

kimse inandıramamış polisleri

senin dolaştığını damarlarımda

adını aramışlar

oda bucak

yazı resim

hatıralarımda

sen yoksun

ben yokum

aşk yok

kapatılmış bir dosyada muhabbetimiz

evrenin arşivindeyiz

göz kırpan bir yıldız 

anlamıştır mutlaka

o da yeter bana', 'aşk senin aklıma gelmendi senin düşünülmendi  hicran kayalıkları üzerinden düşmemdi öyle bir şeydi ki güzeldi acı vericiydi esrar gibiydi al...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-aklima-gelmendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırağ', 'cirag-sanem-or-kilhb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çiy tanesi, 

Çığ gibi çiğner düşleri.

Düş taze, 

Küf değil, küfür gibi ağızda dolaşan.', 'Bir çiy tanesi,  Çığ gibi çiğner düşleri. Düş taze,  Küf değil, küfür gibi ağızda dolaşan....', ARRAY['Türk Edebiyatı','Şiir','Sanem Or']::text[], 8.5, '{"poet":"Sanem Or","poet_slug":"sanem-or","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cirag-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim', 'guzelim-gursel-colak-igjyy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana kötü demesinler diye

Kendimi kötü ettim.

Sana pislik demesinler diye

Kendimi pislik ettim.

Seni gelip ezmesinler diye

Kendimi ezdirdim.

Çünkü sen ne kötü, 

ne bir pislik olmaya, 

nede ezilmeye layıksın.

Sen sadece 

sevilmeye layıksın, Güzelim...', 'Sana kötü demesinler diye Kendimi kötü ettim. Sana pislik demesinler diye Kendimi pislik ettim. Seni gelip ezmesinler diye Kendimi ezdirdim....', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/guzelim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faili Meçhul', 'faili-mechul-hande-caner-t42ek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevmek gibi yüce bir

duyguyu, 

taşıyamadın omuzlarında

sırtlanamadın sevdanı, 

öldürdün, 

faili mechul kalacaksın.

yağamadın yollarıma

yağmurlar gibi, 

yıkanamadı bahçelerim

aşkınla, 

bulutları indireceğim

birdaha hiç, yağamayacaksın.

yorgansız ayaz gecelerimde, 

sarılamadın kucaklar

dolusu, 

korkulu rüyalarla dondurdun

ağlayarak uyandım

masal kar etmez, uyutamıcaksın.

katık edemedin kuru ekmeğinle

sevgimi, 

gönül  sofralarımı terkettin

bir parmak bala değiştin

oysa nasılda, senin delindim

yok artık sana davetim.', 'sevmek gibi yüce bir duyguyu,  taşıyamadın omuzlarında sırtlanamadın sevdanı,  öldürdün,  faili mechul kalacaksın. yağamadın yollarıma yağmu...', ARRAY['Türk Edebiyatı','Şiir','Hande Caner']::text[], 8.5, '{"poet":"Hande Caner","poet_slug":"hande-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/faili-mechul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamayı Beklemeden Ölüm', 'yasamayi-beklemeden-olum-umut-ulbegi-5edb7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yudum içki damarlarımda gezen

savurgan düşünceler

ıssız tepeler

ışıksız tepeler

nokta üzerinde koşarken

çizgilere düşen ben

her çizgide çizim çizim dört dönen gözler

faltaşı gibi açılan kanatlarda

sonsuza uçan helikopter

elimden kaçan seks

anlamsız dürtüler

içkinin artışı

damarların ölüme atlayışı

kayalıklar

rotası belirsiz bir gemi

gemici

dümen

iki adım ötesi ölüm

ölüm hemen

ölüm şimdi

ölüm

yaşamayı beklemeden

19.11.1996', 'Bir yudum içki damarlarımda gezen savurgan düşünceler ıssız tepeler ışıksız tepeler nokta üzerinde koşarken çizgilere düşen ben her çizgide ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasamayi-beklemeden-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyma Artık', 'duyma-artik-baris-akm-qm6p2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duy bu sesin cehennemini

Rüzgarın ateşini hisset

Dokun korkma O artık yok

Başını kaldır bak oradayım

Uzaklarda çok uzaklarda

Bir yıldız ölüsü varya

İşte oradayım

Yüzünde ılık bir şarkı

Saçlarında dudak rüzgarları

İçinde bir sızı duyarsan

Yağmurlu gecenin daha başında

Bilki ben oradayım

Sızım kalmışımdır eşikte

Belkide bir şişede cansız

Papatya kırlarında sensiz

Derin nefeslerin birinde

Bir sıcaklık dolarsa içine

Gözüne kaçarsa bahar rüyası

Dur! açma sakın kapını

Korkarsın şimdiki benden

Sensizliğin ettiğinden

Kara günlerimin birinde

Yalnızlık şarkısı duyarsan

Rengide huzuru andırıyorsa

Bilki gidiyorum uzağa

Hani bir yol varya

İnceden ince

Geceleri geçmeye korkulan

Bir yol 

Hayır, bilemedin işte

Bu yolun kızıl gözlü yolcuları

Cennete gitmez, cehennemede

Bir yol daha vardır aşıklara

Sevip kaybedeblere mahsus

Eski bir yoldur çok eski

Seçkindir buraya göçenler

Herkese göre değildir', 'Duy bu sesin cehennemini Rüzgarın ateşini hisset Dokun korkma O artık yok Başını kaldır bak oradayım Uzaklarda çok uzaklarda Bir yıldız ölüs...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/duyma-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolap Kuşu', 'dolap-kusu-umut-ulbegi-z9jg7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dolabın içindeyim

ne bir pantolon, ne bir gömlek

ne de başka bir şey

ceket de değilim

kocasını göndermeye çalışan

kadının peşindeyim

16.11.1994', 'Bir dolabın içindeyim ne bir pantolon, ne bir gömlek ne de başka bir şey ceket de değilim kocasını göndermeye çalışan kadının peşindeyim 16....', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dolap-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgün Hediye Paketi', 'uzgun-hediye-paketi-umut-ulbegi-tma1i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dişlerimi kırdım

Paket yapıp sana yolladım

Düşlerimi kırdın

O güzel gözlerinden

birini bile

sarıp

yollamadın.

01.09.1995', 'Dişlerimi kırdım Paket yapıp sana yolladım Düşlerimi kırdın O güzel gözlerinden birini bile sarıp yollamadın. 01.09.1995...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzgun-hediye-paketi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Yol Şiiri', 'uzun-yol-siiri-umut-ulbegi-v8zee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Erzincan''a-

Bitenlerin ardından

yitip gidenlerin ardından

ağıtlar yakıp ağlasam

içimdeki zindana yüreğimi bağlasam

kaçsam, kurtulamasam

mutluluk mevsimine döner miyim

döner miyim yeniden, bir bahar tazeliğinde aşka

Demek ki bekleyişin

özleyişin

inci tanesi gibi bedenime işleyişin yalandı

Ne zamandır avutuyordun yorgun kalbimi

masallar anlatıyordun, umuda ezgi masallar

çoktan vazgeçmiştin gözlerimden

Farkına bile varamamıştım düşlerinin

ve o düşlerin içinde eski rolüme sahip olamayacağımın 

demek ki hasretim, sensizliğim

her acıda yudum yudum seni içişim boşaydı

Ne zamandır yanmıyordun benim için

ne zamandır istiyordun yalnızlığı

yalnızlık şarkısı çalınıyordu uzak diyarlardan

duyuyordum

ölümüne duyuyordum

benden vazgeçmenin ve kendini seçmenin denkliğinde

ben ölüyordum

28 gün daha ölürüm

bir Şubat ayı mesafesindedir sonun başlangıcı

iki dudak arasındadır ''son''

gözlerdeki başlangıcın darağacında sallandırılışı

dudaklarının arasındadır

28 gün daha ölürüm

28 gün daha gelemem o şehire

28 gün daha bakamam şehir ışıklarına

ama dönüşüm yakın

baharda aşklar kucaklaşırken döneceğim

aşka kırgın

kış yorgunu

Sen yalnızlığını severken 

ona dokunurken

onunla sevişirken

döneceğim

ve o gün bile

bugünkü gibi seni isteyeceğim

arzularımı kilitleyip

sonumu bekleyeceğim

11.02.2001', '-Erzincan''a- Bitenlerin ardından yitip gidenlerin ardından ağıtlar yakıp ağlasam içimdeki zindana yüreğimi bağlasam kaçsam, kurtulamasam mut...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/uzun-yol-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Dar Odalarında Saklısın', 'yuregimin-dar-odalarinda-saklisin-ali-dost-aydin-x3clm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimin dar odalarında saklısın

Ne ben bilyorum yerini ne de sen

Bir haykırabilsem 

Fırlasa yüreğim 

Çıksa yerinden

Sonra dar odalarda arayıp bulsam 

Çıkarsam sevgimi 

Gün yüzüne 

Dosta düşmana 

Börtü böceğe 

Her şeye 

Duyurabilsem 

Sevdiğimi 

Seni', 'Yüreğimin dar odalarında saklısın Ne ben bilyorum yerini ne de sen Bir haykırabilsem  Fırlasa yüreğim  Çıksa yerinden Sonra dar odalarda ara...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregimin-dar-odalarinda-saklisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz, Hayal, Yoksulluk, Ölüm', 'deniz-hayal-yoksulluk-olum-umut-ulbegi-7ww2n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonsuz

            bir

                  denizim 

