INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Dünyası', 'yagmur-dunyasi-umut-ulbegi-4o2r9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yağmur

akıp giden sevgilileri getirir

gözümün önüne

ve her sevgili

bir yağmur damlasıdır

benim gözümde

13.08.1996', 'Her yağmur akıp giden sevgilileri getirir gözümün önüne ve her sevgili bir yağmur damlasıdır benim gözümde 13.08.1996...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yagmur-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazcik', 'birazcik-bekir-ayral-upuaz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnız yaşadım tüm hayatımı

Kimsem olmadı ki, benim.

Razıyım ben kavuşmasam da, 

Yeter ki, olsun bir sevenim.

Birazcık sevgi ve huzur, 

Hayattan tek beklediğim.

Birazcık sevgi ve huzur, 

Çok mu istediğim benim?', 'Yalnız yaşadım tüm hayatımı Kimsem olmadı ki, benim. Razıyım ben kavuşmasam da,  Yeter ki, olsun bir sevenim. Birazcık sevgi ve huzur,  Haya...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/birazcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-bekir-ayral-k4xax', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırlatma bana.

Hatırlatma ne olur..! 

Unuttuğum şeyleri.

Yanıma oturup, 

Ellerimi tutup, 

Gözlerime bakıp, 

Hatırlatma bana.

Boğazda bir tenhada, 

Ulu bir çınarın altına, 

Birlikte uzanıp da, 

Hatırlatma bana.

Hatırlatma bana, 

Hatırlatma ne olur....! 

Unuttuğum, 

UNUTTUĞUM ŞEYLERİ.', 'Hatırlatma bana. Hatırlatma ne olur..!  Unuttuğum şeyleri. Yanıma oturup,  Ellerimi tutup,  Gözlerime bakıp,  Hatırlatma bana. Boğazda bir t...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutmak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme', 'uzulme-taner-okumus-zu3d3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üzülme

diyordu yaşamayanlar.

oysa

Issız bir ormanda balta sesi gibiydi gidişin.

Ardından, 

bütün kuşlar terk etti ağacımı birer birer.

Ve hüzün çatkapı yerleşti derinliklerime.

Bir umuda sarmamıştım ne kendimi, ne seni.

Ağaçlar gibi ayakta ölmeye hazırlanırken

şiirler emzirdi beni.

Şimdi kalkıp, gelsen bile, 

neye yarar? 

ne berrak bir sessizlik oturuyor hayatımda

ne bir demet çiçek gibi

sapından tuttuğum bir baltam var.', 'Üzülme diyordu yaşamayanlar. oysa Issız bir ormanda balta sesi gibiydi gidişin. Ardından,  bütün kuşlar terk etti ağacımı birer birer. Ve hü...', ARRAY['Türk Edebiyatı','Şiir','Taner Okumuş']::text[], 8.5, '{"poet":"Taner Okumuş","poet_slug":"taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzulme-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam Bende Kal, Sonra Gidersin', 'bu-aksam-bende-kal-sonra-gidersin-taner-okumus-a74gh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam bende kal, sonra gidersin

bırak tanıdık ellerini yalnızlığıma, 

Gözlerini uzakta tutma sakın

bakışların üşür.

Altındaki acılarımız ne kadar da benziyor

Hadi saçlarını yüzüme düşür.

Tut ki çocuğuz, ışığa yürüyoruz

Daha dokunmadık ateşe

ve elimizi neyin yakacağını bilmiyoruz.

Bütün mal varlığımız, el yapımı oyuncaklarımız

Ve öpüşlerimiz, pembe bir utanç bırakmıyor

yüzümüzde henüz.

Gözümüzün değdiği her çiçek allı pullu, yayılıyor

baharın yamaçlarına

Meyveler iki düğme daha açıp göğsünden, 

yeni tomurcuklar ekliyor ağaçlarına.

Tut ki çocuğuz, ışığa yürüyoruz

Gelincikler makyajsız da kırmızı

Ve şiirler

Bir oksijen gibi köpürtmüyor yaralarımızı.

Bu akşam bende kal, sonra gidersin.

Açılmadık şiirlerimi al üstüne.

Anlıyorum çok bozgunlar, 

yenilgiler görmüşsün.

İstersen ağla biraz, 

kılcal sızıların toprağa düşsün.

Ama sonra sil yorgun gözlerini, 

omuzların doğrulsun.

Dökmeyelim zamanı yerlere bu gece olsun.

Bir tutsağı kurtaralım, bir çiçeği sulayalım, 

Bir sevinç olalım gel, gözlerini kapamazsın.

Sabaha bahar üstüne üstüne gelecek

tek başına yapamazsın.

Nasıl da gözümü alıyor bakışların, 

18 yaşım mı gönderdi seni? 

Tuttun nerelere götürdün beni.

Bak yüreğin çatırdıyor usul usul

arınıyor demirleri pastan

Gerekçesiz de işgale açığım artık

Bu akşam yüreğim Afganistan...', 'Bu akşam bende kal, sonra gidersin bırak tanıdık ellerini yalnızlığıma,  Gözlerini uzakta tutma sakın bakışların üşür. Altındaki acılarımız ...', ARRAY['Türk Edebiyatı','Şiir','Taner Okumuş']::text[], 8.5, '{"poet":"Taner Okumuş","poet_slug":"taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bu-aksam-bende-kal-sonra-gidersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Gelen', 'yagmurla-gelen-taner-okumus-dliyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam yağmura binip gelmişsin

Hoş geldin.

Senin sağanağın bellemiştim ne zamandır, 

Boşuna değilmiş.

Yüreğim dağınık kusura bakma, 

İçeri gel.

Sen, 

Parıldayan gözlerini alıp gideli, 

Evdeki her şeyi dilencilere verdim.

Şu ortadaki kocaman boşluk senin yerin

Buyur otur, 

Hiçbir şeyle dolmadı epeydir.

Çok zor günler geçirdim -senden niye saklayayım-

yavaş yavaş aşıyorum

Seni, hüznünü, hasretini, 

kırılmış bir kol gibi

yanımda taşıyorum.

Sığındığım bir çınar gölgesiydi gözbebeklerin

Güneş ilerledikçe etrafına dolandığım

Sen asla bu şehirden geçmeyecek bir otobüste

yolcuydun.

Ben katilini bildiğim bir filmi ısrarla seyrettim, 

Kıran kırana çatıştım umutsuzlukla.

Her gün bir kaç barikatımı daha geçiyordu

Yalnız yağmurda ateş kesiyorduk

Bazen teslim etmeyi düşündüm silahımı

Bazen kendime sakladığım son kurşun için

Kataloglardan ölümler baktım

Sicim gibi ağlamak istedim

Çığlık gibi patlamak.

Her akşam biraz daha azalmış bir gün kopardım

takvimimden

ama gene de

Her yağmurla birlikte

umudumla birlikte

temizledim silahımı

daha keskin bir atışa hazırladım.

Altında -kim bilir- oturacağımız bir gölge

Yıldızları yerleştirdim tek tek

Bir tane de şuraya, 

bir tane de şuraya...

Bekledim ki

bir gün bu yıldızlar altında

mevsimine kırılmış bir rüzgar saçlarımızı dağıtsın.

Ve bekledim ki

yağmur yağsın...

Üstü kalsın.', 'Bu akşam yağmura binip gelmişsin Hoş geldin. Senin sağanağın bellemiştim ne zamandır,  Boşuna değilmiş. Yüreğim dağınık kusura bakma,  İçeri...', ARRAY['Türk Edebiyatı','Şiir','Taner Okumuş']::text[], 8.5, '{"poet":"Taner Okumuş","poet_slug":"taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yagmurla-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-taner-okumus-6hshc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin gurbetim olacak, 

yokluğunda kuş uçmaz yollarda durdum.

Ve bu şehrin benle beraber başını eğip, 

Dağ gibi sustuğunu gördüm.

Ağaçlar hıçkırarak vazgeçtiler yapraklarından, 

Belediye beslemeli, çimler bile sarardı.

Benim hala yeşil beklentilerim var yarından.

Kanı çekilse de şehrin, 

parmaklarım donsa da şahlanan soğuğundan

aldırma.

bu dehşet titremelerim sadece, 

gittiğim her yere gelen yokluğundan...

İçimdeki kuş kafesini zorluyor, 

korkarım ne seni dinler, ne de beni.

Asi gençliğimi özlüyorum, 

her cebimde bir eylem hazırlığı

her halim bir tutuklama nedeni.

Ama görmüyorsun, ıssızım şimdi

demli bir çay bıyığıma bulaşıyor, 

ve dönülmez bir yolculuk planı

ısrarla ayaklarıma dolaşıyor.

Üstüm başım huzursuzluk içinde.

bütün ihtimalleri bir bir siliyorum

ben bu bahar da üzüleceğim

adım gibi biliyorum...', 'Gözlerin gurbetim olacak,  yokluğunda kuş uçmaz yollarda durdum. Ve bu şehrin benle beraber başını eğip,  Dağ gibi sustuğunu gördüm. Ağaçlar...', ARRAY['Türk Edebiyatı','Şiir','Taner Okumuş']::text[], 8.5, '{"poet":"Taner Okumuş","poet_slug":"taner-okumus","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/biliyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-ali-ayyildiz-r34qa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sayrılığa dermanım sensin diyordum

Ayrılığa fermanım bunca yıl sen

Uzaktan uzağa bilinir şimdi varlığı

Hasretine hasret kaldım, nerede vuslat

Ezilsen ağırlığı altında sevdanın

Çileye talip olmak gerekmiş meğer

Ulaşılmaz bir hayal imiş beklenen

Beklenen habersiz, beklendiğinden', 'Sayrılığa dermanım sensin diyordum Ayrılığa fermanım bunca yıl sen Uzaktan uzağa bilinir şimdi varlığı Hasretine hasret kaldım, nerede vusla...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beklenen-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Oldu Süleyman''a', 'yazik-oldu-suleyman-a-ozcan-nevres-blnx9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazık Oldu  Süleyman’a

Bir defada dokuz keleter üzümü

Yoktu ondan başka taşıyan

Toska Haydardı babası

Yörük Fadime de anası

Su arkının yanına çökerlerdi

Ellerinde kocaman bir topan ekmek

Yanlarında tuz kabağı

Önce suya banarlardı bayatlamış ekmeği

Sonra da kabaktaki tuza

Katık ederlerdi tuzu ekmeklerine 

Yemediler içmediler mal edindiler

Biz çok çektik

Çocuklarımız rahat etsin dediler

Varsıllığı yaşayamadan göçüp gittiler

Ölüm hak miras helal derler

İki kardeş malları tez bölüştüler

Süleyman payına düşeni 

Çok tez çıkardı elinden

Otuz dokuz dönüm tarla

Otuz dokuz bine gitti

Üç kağıtçılar sardı etrafını

Sen ağasın

Ağalık sana çok yakıştı dediler

İç Süleyman

Pavyona gidelim Süleyman

Vur patlasın çal oynasın derken

Ele geçen para 

Otuz dokuz günde bitti

Alkol bağımlılığı onu perişan etti

El açtı önüne gelen herkese

Ağam bir bardak şarap parası versene

Kimi hortumla su sıktı üstüne

Kış aylarının en soğuk günlerinde bile

Taş Hanın kapısız odalarından birini 

Mekan etmişti kendine

Yatağı gazete kağıtlarındandı

Kadir gecesiydi kapalıydı meyhaneler

Şaraba alışmış bedeni

Kara kışın soğuğuna dayanamadı

Handa oynayan çocuklar buldu ölüsünü

Çok temiz kalbi varmış dediler

Ölümü bile kadir gecesinde oldu

                       Özcan Nevres  7 Kasım 2002', 'Yazık Oldu  Süleyman’a Bir defada dokuz keleter üzümü Yoktu ondan başka taşıyan Toska Haydardı babası Yörük Fadime de anası Su arkının yanın...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/yazik-oldu-suleyman-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hergün Herakşam', 'hergun-heraksam-ozlem-ertas-3kbm2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hergün batımı, her geçen gün hiç bulamadığım çoban yıldızını bulmak için yenibir ümit doğuyor.  Rüyalarımda gördüğüm ve birtürlü bulamadığım güzel saçlı sevgilim: 

Binlerce bakışım üzerinde, herhalin hayalimde.

      Her kış, her yaz, hergün, herakşam kalbimi söküyorum yerinden.

Hangi şarkı ulaşır sana, hangi sözcük anlatır beni ve hangi düş getirir seni bana.

Nasıl bir yalan avutur seni ben yokken, tuttuğun her faldan ben çıkıyorum.Elbiselerin benim için, gözlerin benim için.Üç bin yıldır sen kokuyorum.Saçların ürperir aklımın yellerinde.

     Gizemli bir uykudan uyanır gibi düşle beni, saçlarını topla cesaretinin arkasında ve düşün; Bildiğin tüm zevklerin ve acıların dışında, bildiğin şeylerin hepsini ben keşfettim senin için.Aklındaki sorularının hepsi aklımda ve razı olacağın tüm cevapları biliyorum.

      Bir mesaj sana gönlümden bütün hallerine...', 'Hergün batımı, her geçen gün hiç bulamadığım çoban yıldızını bulmak için yenibir ümit doğuyor.  Rüyalarımda gördüğüm ve birtürlü bulamadığım...', ARRAY['Türk Edebiyatı','Şiir','Özlem Ertaş']::text[], 8.5, '{"poet":"Özlem Ertaş","poet_slug":"ozlem-ertas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hergun-heraksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Köprüsü', 'sevgi-koprusu-filiz-angay-opwrs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgiyle yenilir sıkıntılar, boşluklar, üzüntüler...

Bazen bir bakışta gizli sevgi, 

	Yoğun, derin, sevecen...

Bazen bir tebessümde, 

	Sade, içten, sıcak...

Bakış ve tebessümle kurulan köprüde yol alır insan, 

	Ulaşmak için hedefe, 

Bir tarafta çılgın dalgalar, 

Diğer tarafta dingin gökyüzünün oluşturduğu, 

	Ufuk çizgisine varmaktır hedef...

Hayattaki dalgalı çelişkileri aşıp

	Dinginliğe, huzura ulaşmak...

Sevgi köprüsüyle...', 'Sevgiyle yenilir sıkıntılar, boşluklar, üzüntüler... Bazen bir bakışta gizli sevgi,  	Yoğun, derin, sevecen... Bazen bir tebessümde,  	Sade,...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-koprusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ceyhun-yilmaz-l5vmv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz olduğu her halinden belli İstanbul''un 

Herhangi bir sokağında ağladım bu sabah. 

Doğsun mu doğmasın mı 

sürencemede güneş? .. 

Ve sırtında küfe ile ayva satıyor 

Bir yaşlı adam, 

Hiç düşünmeden... 

Kimsesizliği ağlamalarından belli bir çocuk 

Adeta kendi kendine doğmuş 

Bugün İstanbul...', 'Sensiz olduğu her halinden belli İstanbul''un  Herhangi bir sokağında ağladım bu sabah.  Doğsun mu doğmasın mı  sürencemede güneş? ..  Ve sır...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kazanacağım Sen Kaybedeceksin', 'ben-kazanacagim-sen-kaybedeceksin-ceyhun-yilmaz-gc9ky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anla işte bak anla! 

İŞTE HAYAT BU! 

Anla yüreğim anla..dimdik duruyorum karşında 

Geçen günler bileklerimi kesiyor yavaş yavaş.. 

..ve akan kan sadece gülümsetiyor beni 

Dayandıkça artıyor gücüm 

..ve bu hayata gülüyorum 

Ben kazanacağım, sen kaybedeceksin.. 

Önümüze gelen engeller! ! 

Önüme çıkan engeller! ! 

KAYBEDECEKSİNİZ! !', 'Anla işte bak anla!  İŞTE HAYAT BU!  Anla yüreğim anla..dimdik duruyorum karşında  Geçen günler bileklerimi kesiyor yavaş yavaş..  ..ve akan...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-kazanacagim-sen-kaybedeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Giderim', 'nasil-giderim-ceyhun-yilmaz-2c3lb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittiğine inanmak istemezki gözlerim 

Mademki gitmedin ne bu gözyaşları derse biri ne cevap veriririm 

Dudaklarımı ıslatan yağmur bir daha yağsa nasıl yalnız ıslanırım 

Giderken hiç düşünmedin mi? 

Sabah odama gelse güneş sensiz nasıl uyanırım 

Hep korktuğumuz ölüm hani ikimizi birden götürecekti 

Şimdi gelse tutsa kolumdan ben nasıl giderim...! ! !', 'Gittiğine inanmak istemezki gözlerim  Mademki gitmedin ne bu gözyaşları derse biri ne cevap veriririm  Dudaklarımı ıslatan yağmur bir daha y...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nasil-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Entel', 'entel-charles-bukowski-c932s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kadın

havaya sprey sıkan

uzun bir hortum misali

durmadan yazı yazıyor, 

ve durmadan

kavga ediyor; 

söyleyebileceğim

gerçekten farklı

hiçbir şey

olmadığından

söylemekten

vazgeçiyorum; 

sonunda-

üzerinde

etki yaratmaya çalışmıyorum

gibi bir şey deyip

söylene söylene

çıkıp gidiyor.

ama biliyorum ki

geri dönecek

hep dönerler.

ve

akşam 5''te

kapıyı çalıyordu.

açtım kapıyı

beni istemiyorsan

uzun kalmam, dedi.

eyvallah, dedim, 

banyo yapmam lazım.

evlilik gibi bir şey: 

her şeyi

hiç olmamış gibi

kabulleniyorsun.', 'kadın havaya sprey sıkan uzun bir hortum misali durmadan yazı yazıyor,  ve durmadan kavga ediyor;  söyleyebileceğim gerçekten farklı hiçbir ...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/entel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızlar', 'kizlar-charles-bukowski-nrpz0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beş yıldır

aynı

lamba siperliğine

bakıp duruyorum

üzerinde bir tür

bakar tozu birikti

ve buraya gelen kızlar

temizlemeyecek kadar

meşguller

ama önemi yok

zaten ben de

şu ana dek

farkedemeyecek kadar 

meşguldum

ışığın

beş yıllık

toz nedeniyle

iyi aydınlatmadığını', 'beş yıldır aynı lamba siperliğine bakıp duruyorum üzerinde bir tür bakar tozu birikti ve buraya gelen kızlar temizlemeyecek kadar meşguller ...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edebi Bir Aşk', 'edebi-bir-ask-charles-bukowski-rgvjx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'onu her nasılsa yazışma ya da şiir veya dergiler yoluyla tanıdım

ve bana tecavüz ve şehvet konulu çok seksi şiirler yollamaya başladı, 

ve işin içine biraz da entellektüellik karışınca

biraz kafam karıştı ve arabama atlayıp Kuzey''e sürdüm; 

uykusuz, akşamdan kalma, yeni boşanmış, 

işsiz, yaşlanmış, yorgun, beş on yıldır

çoğunlukla uyumak ister bir halde, sonunda moteli buldum

küçük güneşli bir kasabada toprak bir yol üzerinde

ve orda oturup bir sigara tüttürdüm

düşündüm, gerçekten delirmiş olmalısın diye, 

ve bir saat geç çıktım

kadınla buluşmaya, epey yaşlıydı, 

nedense benim kadar, pek seksi değildi

ve bana çok set, ham bir elma verdi

kalan dişlerimle çiğnediğim; 

adı konulmamış bir hastalıktan ölüyormuş

astım gibi bir şeyden, ve

sana bir sır vermek istiyorum dedi, ben de

biliyorum; bakiresin,35 yaşındasın, dedim.

ve bir defter çıkardı, on-oniki şiir: 

bir ömürlük çalışma ve okumak zorunda kaldım

ve anlayışlı olmaya çalıştım

ama çok berbattılar.

sonra onu bir yere götürdüm, boks maçlarına 

ve ellerini kenetleyip

dumanın içinde öksürdü

ve etrafına bakınıp durdu

bütün insanlara

ve sonra da boksörlere.

sen hiç heyecanlanmazsın, değil mi? , dedi

ama o gece tepelerde epeyce heyecanlandım, 

ve onunla iki-üç kere daha buluştum

şiirlerinin bazılarında yardımcı oldum

ve dilini boğazımın yarısına kadar soktu

ama ondan ayrıldığımda

hala bakireydi

ve berbat bir şair.

düşünüyorum da bir kadın açmamışsa bacaklarını

35 yıl

iş işten geçmiştir

aşk için de

şiir için de.', 'onu her nasılsa yazışma ya da şiir veya dergiler yoluyla tanıdım ve bana tecavüz ve şehvet konulu çok seksi şiirler yollamaya başladı,  ve i...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/edebi-bir-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edebi Bir...', 'edebi-bir-charles-bukowski-84sbn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'onu her nasılsa yazışma ya da şiir veya dergiler yoluyla tanıdım

ve bana tecavüz ve şehvet konulu çok seksi şiirler yollamaya başladı, 

ve işin içine biraz da entellektüellik karışınca

biraz kafam karıştı ve arabama atlayıp Kuzey''e sürdüm; 

uykusuz, akşamdan kalma, yeni boşanmış, 

işsiz, yaşlanmış, yorgun, beş on yıldır

çoğunlukla uyumak ister bir halde, sonunda moteli buldum

küçük güneşli bir kasabada toprak bir yol üzerinde

ve orda oturup bir sigara tüttürdüm

düşündüm, gerçekten delirmiş olmalısın diye, 

ve bir saat geç çıktım

kadınla buluşmaya, epey yaşlıydı, 

nedense benim kadar, pek seksi değildi

ve bana çok set, ham bir elma verdi

kalan dişlerimle çiğnediğim; 

adı konulmamış bir hastalıktan ölüyormuş

astım gibi bir şeyden, ve

sana bir sır vermek istiyorum dedi, ben de

biliyorum; bakiresin,35 yaşındasın, dedim.

ve bir defter çıkardı, on-oniki şiir: 

bir ömürlük çalışma ve okumak zorunda kaldım

ve anlayışlı olmaya çalıştım

ama çok berbattılar.

sonra onu bir yere götürdüm, boks maçlarına 

ve ellerini kenetleyip

dumanın içinde öksürdü

ve etrafına bakınıp durdu

bütün insanlara

ve sonra da boksörlere.

sen hiç heyecanlanmazsın, değil mi? , dedi

ama o gece tepelerde epeyce heyecanlandım, 

ve onunla iki-üç kere daha buluştum

şiirlerinin bazılarında yardımcı oldum

ve dilini boğazımın yarısına kadar soktu

ama ondan ayrıldığımda

hala bakireydi

ve berbat bir şair.

düşünüyorum da bir kadın açmamışsa bacaklarını

35 yıl

iş işten geçmiştir

aşk için de

şiir için de.', 'onu her nasılsa yazışma ya da şiir veya dergiler yoluyla tanıdım ve bana tecavüz ve şehvet konulu çok seksi şiirler yollamaya başladı,  ve i...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/edebi-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek üzerine', 'ozlemek-uzerine-ahmet-karaca-y2vpr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seni

 Kapalı bir cezaevinin maltasında, 

 kuru soğuğuna aldırış etmezmişcesine

 yere bağdaş kurup oturan

 kan davasından müebbetlik bir mahkumun, 

 sıradan bir lokantada

 çorbasına doğramak istediği gevrek ekmeği

 yada, evinin önüne gidip zili heyecanla caldığında

 Henüz üç aylık eşinin kim o sorusuna 

 benim demeyi özlediği kadar

 özledim seni

.', 'Ben seni  Kapalı bir cezaevinin maltasında,   kuru soğuğuna aldırış etmezmişcesine  yere bağdaş kurup oturan  kan davasından müebbetlik bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Karaca']::text[], 8.5, '{"poet":"Ahmet Karaca","poet_slug":"ahmet-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemek-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sonum', 'sonum-yasemin-yarar-yrlcx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sonum

