INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-onur-nazim-bulut-yhmm6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollar; amansız.

Ama yürümek güzel, 

bir düş karnlığında sırtıma alıp yağmuru, 

yürümek yollarda.

Dilimde tanıdık bir türkü, 

aklımda sen.

ıslanmak ama uslanmamak...', 'Yollar; amansız. Ama yürümek güzel,  bir düş karnlığında sırtıma alıp yağmuru,  yürümek yollarda. Dilimde tanıdık bir türkü,  aklımda sen. ı...', ARRAY['Türk Edebiyatı','Şiir','Onur Nazım Bulut']::text[], 8.5, '{"poet":"Onur Nazım Bulut","poet_slug":"onur-nazim-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yollar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sevda-ulm-698xc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana beni anlatacaktım

hani beraber kalıpta tanıyamadığın beni

ne sitem var sözlerimde

nede suçlu telaşı

nerden başlasam bilmemki

hangi yaramı anlatsam sana

her yanımda

bir başka sancı

hep biri geldi rüyalarıma

hepside gitti sessizce

bir sen vardın

en güvendiğim düşümdün sabaha karşı

yıllar geçti habersizce

gözümde bir sessiz çığlık

seyrettim gidenleri

bağırmaktan hoşlanmam bilirsin

usulca kaçmayı severim

belki derim her seferinde umutlanırım

umutlanmak yağlı ilmek gibi bana

her seferinde bir yanım daha ölür

kırılırım kolayca

kandırmakta kolaydır beni

bir gülümsemeye kanar giderim

unuturum daha dün sırtıma saplanan bıçağı 

nasıl mutlu olurum biliyorsun sen

bir sözcük ısıtır dünyamı

seni seviyorum diyen bir dudak

alır götürür beni yaşamın berbatlığından

düşünürüm yalnız kaldığımda

hatırlarım gözlerini

okyanus kadar derin

gökyüzü kadar mavi

ve saçlarının kokusunu duyarım

her sensizlik korkusunda

çocukluğumdada böyleymişim ben

can çıkar huy çıkmazmış ya

gücüm yetmeyince istediğime

sessizce çekilirmişim bir kenara

kopar gidermişim dünyadan

şimdide öyle yapıyorum

burnumun direği sızladığında yokluğunda

sana sığınıyorum üstüme yıldızları örtüp

herşeyi unutuyorum

bir şeyi unutmuyorum sadece

seni seviyorum

eylül 2002', 'sana beni anlatacaktım hani beraber kalıpta tanıyamadığın beni ne sitem var sözlerimde nede suçlu telaşı nerden başlasam bilmemki hangi yara...', ARRAY['Türk Edebiyatı','Şiir','Sevda Ulm']::text[], 8.5, '{"poet":"Sevda Ulm","poet_slug":"sevda-ulm","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ben-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar arasında', 'bulutlar-arasinda-murat-tali-uhl9d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günlerin döşünden 

akışını seyrettim 

kehribar rengi acılardan 

sıyrılarak geliyordun bana

göğsüme saplanan 

bir gül dikeni gibiydi gözlerin

çıtalarla korkuluklar ördüm

mermerler döşedim

saray yalnızlığında ki 

gecekondu pencerelerine

bulutlar arasında

kalan iki damla yağmura 

verdim iklimsiz 

katıklarımızı

bayatlamış ekmekleri

ısladım 

dudaklarına

usulca sürdüm 

açlığımızı bastırmak için

yürüdüm çölün kuma batmış

sıcaklığında

kaya ovuklarlarına sinmiş

sürüngenler aradım

denize düştüm 

dalgalara kapılarak

boğazıma kaçan binlerce ton suyla

yitiverdim okyanus derinliğinde

bulutlar arasında olmak

ve

bulutlara dönmek 

için yeniden', 'günlerin döşünden  akışını seyrettim  kehribar rengi acılardan  sıyrılarak geliyordun bana göğsüme saplanan  bir gül dikeni gibiydi gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bulutlar-arasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şadırvan', 'sadirvan-murat-tali-ptnsk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've sen arkanda toz karası buğulu kokun ile

karıştın ne olduğu belirsiz zamanlara

katıksız açlıklara terkederek beni

zalim ile yaren ettin sıla akşamlarında 

o vururken sazının tellerine kinayeli 

ben senin hasretini çiziyordum

oturduğum sert ranza üzerinden 

baktığım şadırvana

gece üç beş nöbetlerine kalkar gibi

üşüyen suya sokardım ayaklarımı

su üşürdü ben üşürdüm şadırvanda

sabırsızca koşuyorum ayna karşısına 

sıralanmış damlalar içinden

hikayemizi anlatırken kendime

rüzgarda sallanan kavak yeli

gibi oluyordu

şadırvandan akan su', 've sen arkanda toz karası buğulu kokun ile karıştın ne olduğu belirsiz zamanlara katıksız açlıklara terkederek beni zalim ile yaren ettin sı...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sadirvan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Gözlüm', 'sevda-gozlum-cahit-i-pekoglu-d5u1u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel sen yoksan

bütün sokaklarına kar yağar yüreğimin.

Nefesim

üşüyen bir gelincik ayazı.

Bütün geceler 

sen yoksan ıssız ve aysız..

Durmadan

bir ezgi savruluyor dudaklarında gecelerin.

Hüznün uzayan saçlarında 

kimsesizliğim kanıyor.

Yağmalanmıs bir ömrün ortasından sızarak

yaralı gönlümün ırmaklarına doluyor.

Gel sevda gözlüm

sen yoksan yüreğimde her gece bır deprem oluyor. 

Ey çağlayan bir suda 

yittirdiğim sevda kadını.

Seslen bana nerdesin

şimdi hangi gönüllerdesin.

Bir rüzgarın kanatlarına vursam 

duyulur mu sesim..

Gel sevda gözlüm

erişilmez uçurum diplerinde kaldı özleyişler. 

Yaralı ceylanlar 

bile bak sekiyor bakışlarımda.

Tomurcuklar öksüz, serçeler dilsiz

her durakta boynu bükük bir çocuk üşüyor. 

Ben bu yağmurlar dolusu yalnızlığımla

bütün bulutlardan sana koşuyorum.

Gel, sevda gözlüm

ay yüzlüm gel..

Gel sevda gözlüm

şimdi yüreğim boş, bakışlarım anlamıyor beni.

Her akşam vakti

el ayak sesleri çekilirken caddelerden.

Vurup yüreğimi acılı sevdalara 

yıldızlara ağladığımı kimse bilmiyor.

Gel, sevda gözlüm

ay yüzlüm gel..

Gel sevda gözlüm

geçmiş bahar sokaklarına çıkar beni.

Bahçesi tarumar bir çiçeğin kirpiğindeyim

bir kar çölünün ortasında bırakma beni.

Bir insan mahşerinin içinde 

yapayalnız sakın bırakma beni.

Her bakışta bir hüzün

her hüzünde bir bakış kanamada bırakma beni. 

Gel, sevda gözlüm

ay yüzlüm gel..

Gel sevda gözlüm

bahar sokaklarına çıkar beni.

kalbimin üstüne üstüne yağıyor kar

göçüp gitti sensiz sevda kuşları çoktan. 

Kalbimi sana rehin tutuyorum

sensiz yüreğim kanamalı ağır bir hüzün.

Gel, sevda gözlüm

ay yüzlüm gel..

Gel sevda gözlüm

ay yüzlüm

Gelki ömrümün bütün sokaklarına bak 

sensiz kar yağıyor şimdi...', 'Gel sen yoksan bütün sokaklarına kar yağar yüreğimin. Nefesim üşüyen bir gelincik ayazı. Bütün geceler  sen yoksan ıssız ve aysız.. Durmadan...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sevda-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-arif-damar-ruzlb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşımı sordular

57 dedim

Sorguda

Doğrusunu saklamadan

Yanıltırdım

Bu konuda

Kıyıcılar nerden bilsin

Bir delikanlıdır ozan

Her zaman

(Ocak 1988)', 'Yaşımı sordular 57 dedim Sorguda Doğrusunu saklamadan Yanıltırdım Bu konuda Kıyıcılar nerden bilsin Bir delikanlıdır ozan Her zaman (Ocak 19...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif-damar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sorgu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sensiz Avunmuyor Yüreğim', 'sensiz-avunmuyor-yuregim-mustafa-engin-karatay-dpf0u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi yüze bakarsam, sensin karşımda sanki; 

Bütün tebessümlerde seni görür gibiyim...

Takıldım peşlerine, gölge oldum inan ki; 

Her biri bir kılavuz, sana  yürür gibiyim...

Biliyorum, sen yoksun varacağım  yerlerde; 

Benimkisi aslında, boşa çekilen kürek...

Ne var ki; arıyorum,  soruyorum  her yerde; 

Avunmuyor be gülüm başka  türlü bu yürek...

Sen dolmuşsun içime, kıskıvrak çemberleyip; 

Özüme  işlemişsin, kuşatarak sarmışsın

Hûri gelse; bağrıma basamam ki,  yâr deyip! ..

Anladım ki; Dünyâ''da, bana tek sen yârmışsın...

06.10.2002    Fürstenfeldbruck    06: 05', 'Hangi yüze bakarsam, sensin karşımda sanki;  Bütün tebessümlerde seni görür gibiyim... Takıldım peşlerine, gölge oldum inan ki;  Her biri bi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensiz-avunmuyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Yere Sensizlik', 'yok-yere-sensizlik-duygu-gunkut-ejpsv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tam karşımda duruyorsun, güzelsin...

Yağmur ne kadar da yakışmış saçlarına! 

Hep gitmek istediğin uzak ülke kıyılarında

Dolanıyor kirpiklerin, 

Yüzün camlarımda geziniyor damla damla.

Terkedilmiş bir kumsalda, 

Sensizlikte çürüyen bir kürek gibiyim, 

Sonsuzdayım, derindeyim, 

Derin, ıslaklığı heceliyor geceleyin.

Gözlerinle sıcak bir köşe arıyorsun gözlerimde, 

Bakışların serin, kıyısında durduğun uçurum derin...

Ellerim sesine uzanıyor, ılıman iklimlere dokunuyor, 

Güneşin terkettiği bir havaya bürünmüşsün, sarınışın sımsıkı, 

Kollarında kavuşan dağların güvenli yanıltıcılığı, 

Bir tembih gibi dümdüz bakıyorsun bana uzaktan sıkı sıkı.

Gülüşün, ne zamandı, gülüşüme vururdu

Kurtulup ağzının kıvrımlarından

Girdabım olurdu, aldanışım sana sarılışım, 

Bir koku, uçup uçup giderdi bahar gibi, 

Başımız dönerdi.

Geriye, akdeniz güneşinin mevsimsiz sıcaklığı kalırdı.

Bir sis bulutunun içinde gibisin artık.

Dönüyorsun, uzaklara uzuyorsun içimden geçen boş vagonlu bir tren.

Seçemiyorum yüzündeki renkleri, yine tümüyle bu senin gecen.

Göz kenarlarında yerleşik kırışıklıklarını göremiyorum gülücüklerinin.

Yüzüyor gibisin belirsizliğe, tasasız, kendini akıntıya kaptırmış, 

Geride bıraktığın mahzun ellerim, kanayan yüreğim, 

Harcanmış ümitlerin ortasında kalakalmış bedenim, 

Dokunamıyor ellerimin ısısı donmuş bilincine, gidiyorsun.

Ben yine bir yağmur akşamında, yok yere sensizlikteyim.', 'Tam karşımda duruyorsun, güzelsin... Yağmur ne kadar da yakışmış saçlarına!  Hep gitmek istediğin uzak ülke kıyılarında Dolanıyor kirpikleri...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yok-yere-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaman Duası', 'saman-duasi-rustem-behrudi-ott11', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şaman Duası

Bu günüm de belece(1) 

        Ötüşüb (2)  keçip, geder

Bu yaşımda neyledim, 

        Ey Tanrım, ömür yarı.

Meni rahat burahmır, 

        İçimdeki gem-keder, 

Bir de ki, şehitlerin

        Gece gezen ruhları.

Boylanır (3)   gerib -gerib (4) 

        Geceler başım üsten, 

Sonsuzlug-Tanrı kimi

         Ayıynan(6) ,  ulduzuynan (6) 

Şaman kimi göylere 

         Üz tutub (7)  durmuşam (8)  men, 

-Durub gabag-gabaga (9) 

         göyüzü (10) 

          yalgızıynan.(11)

Bu cür (12)  gerib çağımda 

        Gelib mennen(13)   dilleşen(14)

Ağacın yarpağına, 

         Gülüne inanıram.

Yurd yerinde dayanıp, 

          Sönen ocagların men 

İçinde gor sahlayan  (15) 

          Külüne inanıram.

Yarama duz tek basır

          Sevdalar öz odunu

Bugün –sabah kül ollam..(16)

          Galmışam (17)  yana-yana: 

Tövbe duası kimi 

         Pıçıldadım (18)  adını, 

Sesim sene(19)   çatdı mı, (20)

          Eşitdin mi, ay ana? ! 

Tanrı olmag isterem 

          Dediyim sözde-bendem, (21)

Söze tilsim etmişem 

          Üreyimin ahını.

Men canımı vermeye 

         Bir teze söze bendem, (22) 

Ey mene can veren kes, (23)

         Bağışla günahımı.

Şaman kimi  sözlerden 

          Men tale (24)   tohuyuram, (25) 

Üreyimde sekseke, (26) 

           Ruhumda bir zelzele....

Her gece göy üzüne (27) 

            Men dua ohuyuram (28) 

İlahi, bu milleti 

            Yoh olmagdan  hıfz ele. (29) 



                                  1987

 1 Böylece

 2 geçip

 3 başını uzatıp bakıyor

 4 garip garip

 5 ayıyla

 6 yıldıyla

 7 yüzünü dönüp yönelip

 8 durmuşum

 9 yüzyüze

10 gök yüzü

11  yalnızıyla

12 böyle

13 benimle

14  konuşan

15  kor saklayan, besleyen

 16 olurum

17 kalmışım

18 fısıldadım

19 sana

20 ulaştı mı? 

21  Üzerinde durmuşum

22  bağlıyım

23  kimse

24  talih

25 dokuyorum

26 heyecan, ürperti

27 gökyüzüne

28 okuyorum

29 koru', 'Şaman Duası Bu günüm de belece(1)          Ötüşüb (2)  keçip, geder Bu yaşımda neyledim,          Ey Tanrım, ömür yarı. Meni rahat burahmır,...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Behrudi']::text[], 8.5, '{"poet":"Rüstem Behrudi","poet_slug":"rustem-behrudi","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/saman-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeye Rağmen ve Bu Yüzden', 'her-seye-ragmen-ve-bu-yuzden-ozlem-esmergul-tquuw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her otel odasında

aldım öcümü aşktan

her mavi dumanında tütünün

şakasını yaptım ciğerlerime ihanetin

bütün öyküleri kayıp artık aşkların

hiçbir  sevişmede buluşmuyor ellerimiz

her şeye rağmen ve bu yüzden

sevgili değiliz.

Dokunuşsuz sevişmelerdir aslında bütün çelişkilerimiz

her birimiz, ciddi ilişkilerde sevimsiz çizgi filmleriz

hangi ciddiyetin

zaten neresinde ciddiyiz.

''Yalan''la örtülür oldu korkaklığımız.

''Seviyorum''derken utanırdık da

sevgisiz sevişmelere ne zaman alıştık.

Aslında birbirimizden çok

asırlarca kendimizden kaçtık

her şeye rağmen ve bu yüzden

bir düşümüze bile tutunamadık.

Her yataktan sevdalanmış olarak kalkarız aslında

resepsiyonda uyanırız sonra

yağmur altında, tramvay durağında

ne bir avuç mendil anı

ne de içsel bir öpüş kalır sana

AŞK YOKSA ŞAYET, İHANET DE YOKTUR

her şeye rağmen ve bu yüzden

aşksız sevişlerde  ''ihanet''

sadece bir oyundur.....

22 nisan 2002............Pazartesi.............(korkuyorsun benden, İstanbul''da)', 'Her otel odasında aldım öcümü aşktan her mavi dumanında tütünün şakasını yaptım ciğerlerime ihanetin bütün öyküleri kayıp artık aşkların hiç...', ARRAY['Türk Edebiyatı','Şiir','Özlem Esmergül']::text[], 8.5, '{"poet":"Özlem Esmergül","poet_slug":"ozlem-esmergul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/her-seye-ragmen-ve-bu-yuzden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Mevsimi', 'ayrilik-mevsimi-ayhan-kol-4bvzr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine başladı ayrılık mevsimi

Dökülüyor yaprak misali sevdalar

Yeni vedalar belki elvedalar olacak

Hani ektiğinde biçmek için

Atarsın ya toprağa tohumu

Öylesi karmaşaya gerek yoktur aslında

Bİr anda köksalar yüreğine 

Ayrılık..! 

Daha ne olduğunu anlamadan

Büyümüştür artık bir çınar, bir orman misali

Bütünüyle kaplamıştır umutlarının üstünü

Yeniden başlamak için herşeye 

Bulamazsın o  cesareti kendinde

Onunla tükenmiştir duyguların

Amaçsız ve hedefsiz yürürsün

Aldırmaaa..

Mevsim dedim ya gelir geçer

Tekrar yeni bir sevdaya yelken açarsın....', 'Yine başladı ayrılık mevsimi Dökülüyor yaprak misali sevdalar Yeni vedalar belki elvedalar olacak Hani ektiğinde biçmek için Atarsın ya topr...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Kol']::text[], 8.5, '{"poet":"Ayhan Kol","poet_slug":"ayhan-kol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrilik-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Serçenin Gözyaşları', 'bir-sercenin-gozyaslari-ufuk-demir-9wd0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir serçenin gözyaşı olmuştu duam

her karanlık gecenin ardından

lüksünü yaşadığım

demir parmaklıklar olamasada 

bir oda mahkumiyetinde hür olmam

bir umuttu yarını olamayan geleceğim

anılarda saklı yaşanmayan anılardı beni sana bağlayan

ve bir serçenin gözyaşı olmuştu duam

anılarda hiç yeri olmayan', 'Bir serçenin gözyaşı olmuştu duam her karanlık gecenin ardından lüksünü yaşadığım demir parmaklıklar olamasada  bir oda mahkumiyetinde hür o...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Demir']::text[], 8.5, '{"poet":"Ufuk Demir","poet_slug":"ufuk-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-sercenin-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedeler Ne Anlatır Torunlarına', 'dedeler-ne-anlatir-torunlarina-yalcin-aydin-aycicek-5x1ga', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedeler Ne Analatır Torunlarına

                                                                   Şol torun dedesine

                                                                   kalkmış masal anlatır

                                                                   gün kıyamet günüdür

                                                                   doğurmak üz''re katır

Usanmadan toplanırdık hepimiz

hem de her kış gecesi

     onun sıcak sakalının altında

Ağzını açtığında dedem

filizlenirdi savaşın soğuk tohumları

     küçücük yüreklerimizde

Bir mavzer sesi girerdi önce kapıdan

ardından da top sesi

Yaralılar gelirdi

     üstü başı kan

          barut

               ve duman

                    ve binlerce asker elbisesi

	               soluk renkli ve yırtık

ve ölüler doluşurdu içeri

nereye sığacak bu kalabalık

Manda gözüne dönerdi korkudan gözümüz

     biz çıkardık odadan

          bir çığlık basardı en küçüğümüz

''Bütün savaşlar aynıdır aslında '' derdi

ve bu yüzden olacak

anlattıkları da pek benzerdi

                             birbirine

Öyle ki 

nişan alırdı bastonuyla

     her gece odanın aynı yerine

Elini kulağına atardı birden

     Albayrak''lı o yiğit (1) 

''-Atımı bağladım meşeye

                           meşeye (2) 

şarapnel parçası doludur sinem

son haberim bu olmaz ümit ederim

Benden selam söyleyin Ayşe''ye

                                     Ayşe''ye''(2) 

Ve her gece konuşmanın tam burasında

gülerdi odadaki kızlar / gelinler

     biraz kızarırdı ninem

Uyku ve korku

     dağlara çıkmış bir gece

Ve o gece baskınında dedemin

     bir orospu

          bir soğuk

               süngü girmiş koynuna

Ve derler ki o yüzden

her ağaç bir mermi olmuş

yaşlı Yıldız dağları bile

     nehirleri çapraz asmış boynuna

''Bugün

     her çağıranın yanına giden

          ağırbaşlı şu kolay ölüm

kanunlarla

     kitaplarla

          yasaklanmıştı o zaman''

''Ve o günlerde ölmek

      çok daha zordu ekmek bulmaktan''

                                         diye eklerdi

süngü izini gösterirken bizlere

bacağındaki kurşun yarası da

uslu bir çocuk gibi sırasını beklerdi

Emperyalizmi ne bilsin dedem

-bilseydi de dili dönmezdi mutlak-

Çanakkale derdi

     Kore derdi

          Yunan derdi o

bizim emperyalizm dediğimiz şeyin adına

Kimi zaman da bir türkü karışırdı

     bu savaş filminin arasına

''Telgırafın telleri

Pambuk gibi elleri

Üriyeti çıkaran

Enver Bey''in dilleri''(3) 

Ne zaman ki uzun bir soluk çeker içine dedem

ve tütün tabakasını almak için

     eli kuşağına girer

anlarız

     bu gecelik bu kadar

ayrılırız yanından birer birer

-Yaralılar

     yaralılarla yan yana yatar

ölülerle de

     ölüler-

Alışılagelmiş o çığlığı çoktan  attı diğerleri

öyleyse ben de atacağım

Dün gece karabasan görmedim çünkü

demek ki bu gece kesin

''Anneeee

       ben bu gece de ikinizin arasında yatacağım''

Son olarak bir de şunu anımsıyorum: 

Dedem konuşurken

     ne sözünün kesilmesini isterdi

          ne de bir yorum

O günlerden beri de

-ölüme yaklaşacağımdan değil- 

torunlarıma anlatacak hiç bir şeyim olmadığı için 

yaşlanmaktan korkuyorum

              (Temmuz’85 Babaeski) 

(1) : Albayrak: Kurtuluş Savaşı günlerinde Trakya dolaylarında kurulan direniş örgütü.

(2) : Bir Trakya türküsünün iki dizesi 

(3) : Bir Trakya mânisi', 'Dedeler Ne Analatır Torunlarına                                                                    Şol torun dedesine                       ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Aydın Ayçiçek']::text[], 8.5, '{"poet":"Yalçın Aydın Ayçiçek","poet_slug":"yalcin-aydin-aycicek","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/dedeler-ne-anlatir-torunlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmutsal Yalnızlık', 'mahmutsal-yalnizlik-yalcin-aydin-aycicek-nkgkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MAHMUTSAL YALNIZLIK

                                                                     Mahmut K. için

Doldurdu tıkış tıkış

     mavi bavuluna umutlarını

-hem zamanı yoktu

     hem sevmezdi ütüyü-

binburuşuk giyiverdi üstüne

                                ''Köydekinden daha mı çok -de kurban-

                                        sanki burda yıldızlar''

                                   Kentsel yenilgilerde

                                        Mahmutsal yalnızlığım sızlar

Dudağında serince bir türküyle

düşlerinde kekik topladı

Dağıttılar

     topladı

          ve yine dağıttılar

şöyle bir baktı kasketini yana yatırıp

Güneş hoyrattı

     gün hoyrat

ant içti dönüş için

hem de

     hoyradına bin hoyrat 

                                ''Sen de inanıyor musun -he kurban-

                                   taşrada

                                        daha cesur atar nabızlar''

                                   Kentsel yenilgilerde

                                        Mahmutsal yalnızlığım sızlar

Ne yenilgi yazdırdı bu kez

     ne de utku

savaş defterinin bu sayfasına

Ama yine de

yaylım ateş altında

     siper değiştirmeyi başardı

                                 ''Kimler indirmedi -be kurban-

                                   öfke ile o kocaman balyozu

                                   Biliyorum

                                   kırılmadı ama çatladı işte

                                        pahalı buzlar''

                                   Kentsel yenilgilerde

                                        Mahmutsal yalnızlığım sızlar

                   (Mayıs’86 Topkapı Otogarı)', 'MAHMUTSAL YALNIZLIK                                                                      Mahmut K. için Doldurdu tıkış tıkış      mavi bavul...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Aydın Ayçiçek']::text[], 8.5, '{"poet":"Yalçın Aydın Ayçiçek","poet_slug":"yalcin-aydin-aycicek","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mahmutsal-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-fethi-giray-s4cq1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne olur gemiciler, 

Beni de götürseniz ne olur, 

İyi insanlar.

Sizlere kavuşabilsem: 

Pırıl pırıl ışıklı, bol şarkılı limanlar.

Bir gün kurtulabilsem, 

Bu yalan dolu, 

Bu asık suratlı şehirlerden, 

Bir gün kurtulabilsem, 

Ne olur gemiciler, 

Bana da bahsetseniz

Següzeştten, 

En vahşi denizlerden.

Bir rıhtım kahvesinde, 

Saatlerce dertleşsek, 

İsmini bilmediğimiz şehirlerde; 

Son meteliğimize kadar içebilsek.

Maviliklere şarkı söyliyen yelkenliler, 

Beni de götürseniz ne olur, 

İyi insanlar.

Sizlere kavuşabilsem: 

Pırıl pırıl ışıklı, bol şarkılı limanlar.', 'Ne olur gemiciler,  Beni de götürseniz ne olur,  İyi insanlar. Sizlere kavuşabilsem:  Pırıl pırıl ışıklı, bol şarkılı limanlar. Bir gün kurt...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozleyis-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpushane', 'mahpushane-fethi-giray-gz5ir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demir parmaklıklarda

Üç kelime konuştuk: 

Paran var mı? dedim.

Sorma! 

Alıştık, 

Kuru ekmek de yerim dedi.

O, 

Dışarıdayken, 

Ağaçları, 

Kuşları, 

Çiçekleri, 

Ne kadar severdi.

Bazı geceler dinliyormuş

Şehirden gelen uğultuları.

Yahu! diyor, 

Her gece rüyamda görüyorum dostları.

Gündüzleri bahçede geziyor 

Ve seyrediyormuş

Güneşi, 

Masmavi bulutları.

Kendisi yıkıyormuş

Çamaşırlarını, 

Yemek tasını

101 seneye mahkum prangalıyla; 

Beraber söylüyormuş

Kazımım şarkısını.', 'Demir parmaklıklarda Üç kelime konuştuk:  Paran var mı? dedim. Sorma!  Alıştık,  Kuru ekmek de yerim dedi. O,  Dışarıdayken,  Ağaçları,  Kuş...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mahpushane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur Söyleme', 'dur-soyleme-bahri-sohtorik-n87lc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlaşıldı ayrılığı yazdın artık yazıma

Bir gariplik çoktan çöktü mızrabıma sazıma

Kötü deme düşman gibi bakma sakın yüzüme

Dur söyleme sakın deme ben bırakıp giderim

Hani nerde kalbindeki gizlendiğim köşeler

Bitti artık sevgiliyle eğlenmeler neşeler

Şimdi beni bekleyenler kadehler ve şişeler

Dur söyleme sakın deme ben bırakıp giderim

Sana ihanet etmedi ne gönlüm ne bedenim

İhanetin durağından hiç durmadan gidenim

Bu dünyada kalmadıysa yaşamaya nedenim

Dur söyleme sakın deme ben elbette giderim', 'Anlaşıldı ayrılığı yazdın artık yazıma Bir gariplik çoktan çöktü mızrabıma sazıma Kötü deme düşman gibi bakma sakın yüzüme Dur söyleme sakın...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dur-soyleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'cansin', 'cansin-bahri-sohtorik-lywlq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Donan gönül kutbunu ısıtansın yakansın

Susamış çöl gibiyim pınarsın can katansın

Dalında bir gül değil sen gülsün sen gülşensin

Sana canan diyemem canan değilsin cansın

Şarkılarda sen varsın bestedeki nağmesin

Dudaklarda sen varsın isterse söylenmesin

Gözlerdeki nur sensin damarda gezen sensin

Sana canan diyemem canan değilsin cansın

Ferhat''ın aşkı da ne dağlar delmek hüner mi

Tek iste bu bedenim cehennnemlerde yansın

Sen bende yeşerecek bende yaşayacaksın

Sana canan diyemem canan değilsin cansın', 'Donan gönül kutbunu ısıtansın yakansın Susamış çöl gibiyim pınarsın can katansın Dalında bir gül değil sen gülsün sen gülşensin Sana canan d...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silinenler', 'silinenler-bahri-sohtorik-z0g26', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılığı sildim artık lugattan

Ölüm yazdım yerine

İhaneti sildim

Adını yazdım

Aşk yalandır diyemedim

Aşkımı yazdım

Riyayı sildim

Sözünü yazdım

Sadakat yerine

Özümü yazdım

Sonra

Bir de şiir yazdım

Adınla dolu

Sözünle dolu

Özünle dolu bir şiir', 'Ayrılığı sildim artık lugattan Ölüm yazdım yerine İhaneti sildim Adını yazdım Aşk yalandır diyemedim Aşkımı yazdım Riyayı sildim Sözünü yazd...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/silinenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-bahri-sohtorik-8y2u9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toplanın dostlarım duyunca hemen

Benim içinde bir çalıp hemen oynayın

Neşesiz geçen günlerinizi

Yaşanmış günler diye saymayın

Peşimden ağlayıp saçını yolan

Suratından düşen bin parça olan

Güzeli sevmeyi de unutan

O garip insanlara da dönmeyin

Ben ''dostlar'' deyince, karım, çocuğum

Kendinizi sakın ayrı saymayın

Sevenlerim benim hepsi dostlarım

Dostlarımdan sizde ayrı durmayın

Arkamdan küfredip haykıran olur

Adıma lanetler yağdıran olur

Onları dinleyip hemen kızmayın

Hiç kimseye kin tutucu olmayın

''Tabiattan zevk almayı bilirdi

Güzel söze dost olmaya gelirdi''

Deyip beni yadederek anmayın

Sakın beni öldü diye sanmayın

Gülünce, ben sizinle gülerim

Çalınca, ben sizinle coşarım

Tatlı sözde sizinle buluşurum

Mısra ile meclise karışırım

Sevdiklerim susarda gülmeyi unutursa

Meclisler dağılırda mısralar karışırsa

Kin ile acı, nefret etrafa yayılırsa

İşte o zaman öldüm, benim için ağlayın.', 'Toplanın dostlarım duyunca hemen Benim içinde bir çalıp hemen oynayın Neşesiz geçen günlerinizi Yaşanmış günler diye saymayın Peşimden ağlay...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vasiyet-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Kızım', 'guzel-kizim-bahri-sohtorik-1fxi9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güler yüzlü, güzel kızım

İnce belli, fidan kızım

Gül dalında gonca kızım

Çiçek gibi narin kızım

Sevgi dolu o küçücük yüreğinde

Derya gibi, 

Duygu dolu kalbin, geniş

Dünya gibi

Güler yüzün asılmasın güzel kızım

Hayat kısa, 

İnce belin bükülmesin güzel kızım

Başın dik ol, 

Narin tenin çizilmesin güzel kızım

Temkinli ol, 

İnsanlara sevgi selin eksilmesin güzel kızım

Ölçülü ol, 

Duygu bahçen sararmasın güzel kızım

Mantıklı ol

Öğüdümü tut ki kızım

Hep mutlu ol.

                                        (Kızım Ayşe''ye)', 'Güler yüzlü, güzel kızım İnce belli, fidan kızım Gül dalında gonca kızım Çiçek gibi narin kızım Sevgi dolu o küçücük yüreğinde Derya gibi,  ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzel-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Değil', 'ben-degil-sevinc-keles-tfguf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırdılar yüreğimi, sebepli sebepsiz azarlarla

artık eskisi kadar yalın bakamıyorum dünyaya.

Elbette geçer diyip boş veremiyorum herşeye

ağlıyorum bütün dertlerimle yalnızlığıma, 

yağmur yağarken bakamıyorum çıplak gözle gökyüzüne

dokunamıyorum sıcağa ve soğuğa

korkutuyor beni herzamankinden daha çok karanlık

ağlıyorum bütün dertlerimle yalnızlığıma.

Gündüzlere, gecelere sığdıramadığım bütün hayatım, 

şimdi film şeridi gibi geçiyor gözlerimden

tutmak istiyorum ve asla bırakmamak

zamanı durdursalar keşke diyorum.

Bu ben değil, dünde yaşayan ben ben

Bugünde var olan değil...', 'Kırdılar yüreğimi, sebepli sebepsiz azarlarla artık eskisi kadar yalın bakamıyorum dünyaya. Elbette geçer diyip boş veremiyorum herşeye ağlı...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Keleş']::text[], 8.5, '{"poet":"Sevinç Keleş","poet_slug":"sevinc-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta çağrı.', 'dosta-cagri-ahmet-kurnaz-1g9tr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey dost, 

Kalemine kan, 

Yokluğuna can....... dayanmıyor.

Kalemim kâğıtta, 

ayaklarım kaldırımlarda yürümüyor.

Düşüncelerim kördüğüm, 

bir türlü çözülmüyor, 

Ey dost, 

Gidişini anlamadım.

Halâ düşünüyorum artmayan zamanlarda.

Çaylar masalarda soğumuş, 

caddeler, senden yoksun.

Hayat ne ki? 

Üç beş adımda tükeniyor bir ömür.

Her şeyini vur sırtına, 

dön artık 

Ey dost.

Sana sesleniyorum sisler ülkesinden, 

yetmiyor mu bıçak sırtında durduğun.

Bırak Ankara''nın loş ışıkları, 

mekân olsun serserilere, 

Üç beş kaltak oynaşsın caddelerinde.

Yollar, uzun da olsa bitmeye mahkûmdur, 

Ey dost, 

dön artık.

Dön ki hak ortadan bölünmesin düşlerim, 

bir dostu bile yok, demesin kimse bana.

ben senin muhabbetine aşinayım, 

biliyorum sende buraların çamuruna.

Ey dost, 

dön artık.

Bir bebeğin ağlamasında, 

seyyar satıcıların akşam çığlıklarında

aratma kendini.

Kalemine kan....

yoktluğuna can.......dayanmıyor.

                        25.NİSAN 1994/Elbistan', 'Ey dost,  Kalemine kan,  Yokluğuna can....... dayanmıyor. Kalemim kâğıtta,  ayaklarım kaldırımlarda yürümüyor. Düşüncelerim kördüğüm,  bir t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dosta-cagri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbime Hoş Geldiniz (Şarkı Sözü)', 'kalbime-hos-geldiniz-sarki-sozu-ali-hallac-7fc0r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbime hoş geldiniz, uzun zamandır boştu

Kaç ümidin peşinden boşu boşuna koştu

Kaç sevgili aldattı, ta o günden sarhoştu

Kalbime hoş geldiniz, uzun zamandır boştu.

Kaç ayrılık gördü de, binlerce kez üzüldü

Kaç vefasız sevdi de, ne zaman yüzü güldü

Kaç kez kapandı aşka, bağlanıpta çözüldü

Sevmeye mecbur gibi seni görünce coştu.

Kalbime hoş geldiniz uzun zamandır boştu.', 'Kalbime hoş geldiniz, uzun zamandır boştu Kaç ümidin peşinden boşu boşuna koştu Kaç sevgili aldattı, ta o günden sarhoştu Kalbime hoş geldin...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalbime-hos-geldiniz-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Bilmiyorsun', 'sevmeyi-bilmiyorsun-ali-hallac-gvrhf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu değil aşk dediğin, onun eşsiz tadı var

Öpmekten okşamaktan başka da maksadı var

Sevmek billahi bu değil, onun başka adı var

Seviyorum diyorsun, sevmeyi bilmiyorsun.

Gönülden vermeliydin, aşkta benlik olmazdı

Sevmek bu olsa idi, yolumuz ayrılmazdı

Sevda nedir bilseydin, mutluluk son bulmazdı

Seviyorum diyorsun, sevmeyi bilmiyorsun.

Seninki sevgi mi ki, ispat etmedin bana

Ömrümü hiç kuşkusuz feda ettimdi sana

Sen neyi feda ettin aşkımızın uğruna

Seviyorum diyorsun, sevmeyi bilmiyorsun', 'Bu değil aşk dediğin, onun eşsiz tadı var Öpmekten okşamaktan başka da maksadı var Sevmek billahi bu değil, onun başka adı var Seviyorum diy...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyi-bilmiyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan Gerek', 'sevdan-gerek-umit-kocak-lgext', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim uykuya hasret, 

Uykular sana, 

Yaşanamayanlar, 

Herşeyin mümkün olduğu rüyalara hasret, 

Geceler kovalarken birbirini, 

Benim kovalanmayan korkularım var, 

Durup durup hayalinle başlarken, 

İçimde parça parça özlemlerim var.

Korkular avunmak için tesellini bekliyor.

Yalnızlık güzeldir ya bazen, 

Yalnızlık değil de sensizlik öldürüyor, 

Şarkılar, şiirler, kelimeler yalan söylüyor, 

Lakin hergün yeniden doğan bir şey var içimde.

Her gece dua gibi dilime dolanan, 

İşte bunu anlatamaz hiçbir şiir, 

Bana şiir tadında, 

Baharı hatırlatan, 

Yüreğimde çiçekler açtıran, 

Sevdan gerek...', 'Gözlerim uykuya hasret,  Uykular sana,  Yaşanamayanlar,  Herşeyin mümkün olduğu rüyalara hasret,  Geceler kovalarken birbirini,  Benim koval...', ARRAY['Türk Edebiyatı','Şiir','Ümit Koçak']::text[], 8.5, '{"poet":"Ümit Koçak","poet_slug":"umit-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdan-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırt gitsin hayallerimi.', 'yirt-gitsin-hayallerimi-ahmet-kurnaz-7t6ue', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yırt gitsin hayallerimi orta yerinden, 

Yorgun akşamlarda düşlere yalvarayım.

Yaktığın bu ateş söner mi bilmem, 

Yaşlı gözlerime döner mi uykular.

Yırt gitsin hayallerimi orta yerinden.

Asılı kalsın duvarda tüm umutlarım.

Açtığın yaralar kanasın varsın.

Akşamlar çöksün gözlerime her sabah, 

Ak düşsün saçlarıma ağarsın varsın.

Asılı kalsın duvarda tüm umutlarım.

Bulutlar gözlerime inerse birgün, 

Bomboş yüreğime ateş düşerse.

Bahtıma ortak olma, kaderine git, 

Bıraktığın yerde kalsın yıllarım.

Bulutlar gözlerime inerse birgün.

Ayrılık gün gibi aşikâr gülüm.

Ağlamak, sızlamak fayda eder mi? 

Arzuların boynu bükük kalacak, 

Anlamayacak biliyorum hiç kimse, 

Ayrılık gün gibi aşikâr gülüm.

Neden ayrı dünyalarda doğmuşuz sanki, 

Nakış nakış işlenmiş hasret kaderimize, 

Nilüferi olmuşsun sen mavi göllerin, 

Nergizi ardıçlı dağların.

Neden ayrı dünyalarda doğmuşuz sanki.

Git, girme ömrümün kanarlığına, 

Gözlerimin donukluğu üşütmeden seni, 

Güz gülleri teslim olmadan hazana.

Gördüğün rüyaları anlatmadan git.

Git girme ömrümün karanlığına.

Üzeri küllensin bu bahtsız aşkın, 

Üşüsün yüreğime koyduğun ateş.

Üzmesin bu benim düştüğüm haller, 

Ürkütmesin gönlünü sevdadan yana.

Üzeri küllensin bu bahtsız aşkın.

Lâvanta kokunu yayma dört yana, 

Lânet etme, korkuyorum yaz gülü.

Lüle lüle saçlarında bir akşam, 

Lime lime dağıt beni saç ama, 

Lâvanta kokunu yayma dört yana.

Üç mevsim geriden gülersin bana, 

Üç adım ötede ecelim bekler, 

Ürperir sana hasret yüreğim, 

Üşürken gözyaşlarım, gözpınarımda, 

Üç mevsim geriden gülersin bana.

          02 KASIM 2000/Elbistan', 'Yırt gitsin hayallerimi orta yerinden,  Yorgun akşamlarda düşlere yalvarayım. Yaktığın bu ateş söner mi bilmem,  Yaşlı gözlerime döner mi uy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yirt-gitsin-hayallerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söndürün Işıkları', 'sondurun-isiklari-omer-lutfi-soylu-nqf1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir doğum sancısı sanırım..

Bu ağrı öldürecek kadar acı...

Söndürün ışıkları! ! ! 

Bittiğini bileyim

Bir kabusun içinde 

Acımı eriteyim

Ruhum sığmıyor bedenime

Çığlık olup çıkmak istiyor

Söndürün ışıkları...

Geceye koşsun ruhum

Fahişe yataklarında dinlenir ancak

Damarlarımda hayat yerine şarap aksın

Belki azalır acım

Yaşamayayım dünyanızda

Yokoluşlar semtinde kaybolsun ruhum

Kimse bulamasın onu

Södürün ışıkları

Karanlık izbe yuva bana

Bırakın delsin sinemi rüzgar

Kara dalgalar dövsün kumsallarımı

Karanlıkta bulurum belki

Kahreden yalnızlıkları

Ve ölümün soğuk parmaklarını

Söndürün ışıkları 

Bittiğini bileyim

Bir kabusun içinde 

Acımı eriteyim', 'Bir doğum sancısı sanırım.. Bu ağrı öldürecek kadar acı... Söndürün ışıkları! ! !  Bittiğini bileyim Bir kabusun içinde  Acımı eriteyim Ruhu...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Soylu']::text[], 8.5, '{"poet":"Ömer Lütfi Soylu","poet_slug":"omer-lutfi-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sondurun-isiklari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-omer-lutfi-soylu-qlm3e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak yine yalnızlık arkadaşım

En vefalı sevgilim

Elleri avuçlarımda ıslak

Rüzgar kulağıma ıslık

Yüreğimde koskocaman bir boşluk

Yürüyorum

Bir türkü tutturmuşum

Hasrete ve yalnızlığa dair

Sanki herşey kaf dağının ardına kaçmış...

Derken bir anıda

İçimde zakkum çiçekleri açmış

Yalnızlığın koynunda

Bir düş anında

Rüzgara sevdalı sigaram

Aşka inat tükenip

Elimi yakmış...', 'Bak yine yalnızlık arkadaşım En vefalı sevgilim Elleri avuçlarımda ıslak Rüzgar kulağıma ıslık Yüreğimde koskocaman bir boşluk Yürüyorum Bir...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Soylu']::text[], 8.5, '{"poet":"Ömer Lütfi Soylu","poet_slug":"omer-lutfi-soylu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Evlenir misin?', 'benimle-evlenir-misin-erkan-erdamar-iu1un', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sağ adımını atışından, 

Gözünün doluşundan bilirim.

Sen benim kaderimsin.

Boşa uğraşma, dönemem, 

Yıllarca beklediğimsin.

Sana düşlerimi veriyorum.

Küçük günahlarımı

Affet gitsin.

Sadece ben''i vaad ediyorum.

Yorgun ve yanlış, olduğum gibi.

Benimle evlenir misin? 

5.1.1994.  00.05.', 'Sağ adımını atışından,  Gözünün doluşundan bilirim. Sen benim kaderimsin. Boşa uğraşma, dönemem,  Yıllarca beklediğimsin. Sana düşlerimi ver...', ARRAY['Türk Edebiyatı','Şiir','Erkan Erdamar']::text[], 8.5, '{"poet":"Erkan Erdamar","poet_slug":"erkan-erdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benimle-evlenir-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telefonlu Hasret', 'telefonlu-hasret-erkan-erdamar-oyl8s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1

Bir tek sesinle, uzak

Tellerden utanarak.

Biçare yolunda, 

Yayan yapıldak.

2

Biz hasretin cırcır böcekleri

Ortak anlarımız soğumasın diye

Çağdaş termoslara doldurduk.

3

Nefessiz ses, mimiksiz söz, 

Tasarlanmamış orta oyunu, 

Sen Kavuklu, 

Ben Pişekar, 

Vur vurabildiğin kadar.

4

Yarın geriye dönüp güleriz.

-i şimdi biliriz de, 

Kendimizi alamayız.

Çokluk çocukluktan.

5

Kırılganlık daha abartık, 

Frekans inişli çıkışlı, 

Hassas konuşmatik.

6

Açık aşk mı ne, yeter! 

Bir hafta sesine mecbur, 

Sonlarında yüzyüze, 

Ve iki de sınavı

Bin beter.', '1 Bir tek sesinle, uzak Tellerden utanarak. Biçare yolunda,  Yayan yapıldak. 2 Biz hasretin cırcır böcekleri Ortak anlarımız soğumasın diye ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Erdamar']::text[], 8.5, '{"poet":"Erkan Erdamar","poet_slug":"erkan-erdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/telefonlu-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimyevi Şiir', 'kimyevi-siir-erkan-erdamar-6hv6v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geri dön deme boşuna.

Gün gün artıyor entropim.

Geri dönemem.

Geri dönemem.

Hem çalsam yeniden kapını, 

Gelen eski ben olamam.', 'Geri dön deme boşuna. Gün gün artıyor entropim. Geri dönemem. Geri dönemem. Hem çalsam yeniden kapını,  Gelen eski ben olamam....', ARRAY['Türk Edebiyatı','Şiir','Erkan Erdamar']::text[], 8.5, '{"poet":"Erkan Erdamar","poet_slug":"erkan-erdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kimyevi-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözümsüzlük', 'cozumsuzluk-erkan-erdamar-qu7e5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarını kırık 

Yeniden görmek

Karşıyaka’sında İzmir’in

Karşısını karşı yaka bilmek

Uçup bulutların üstünde

Yere inememek bir daha

(Ne bileyim dumanlı kafa)

Aklına geleni sıralamak

Uçmak, uçmak martılara inat, 

Kanat çırpamadan

Bir tuhaf İzmir

Bir garip yaz ortası

Karşıyaka çay bahçesinde

Aklına geleni bi daha anımsayamamak

Bir garip bir şiire başlamak

Bir geziye, bir mektuba, 

Bir sevdaya...

Sonunu bağlayamamak            

(Ağustos 2002 İzmir)', 'Göz yaşlarını kırık  Yeniden görmek Karşıyaka’sında İzmir’in Karşısını karşı yaka bilmek Uçup bulutların üstünde Yere inememek bir daha (Ne ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Erdamar']::text[], 8.5, '{"poet":"Erkan Erdamar","poet_slug":"erkan-erdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cozumsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Giz', 'gizli-giz-erkan-erdamar-rs3h4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gizim olsun istemedim.

Çünkü biliyorum, 

Her şeyimi döksem ortaya

Farkına varamadıklarımı gizliyorum', 'Bir gizim olsun istemedim. Çünkü biliyorum,  Her şeyimi döksem ortaya Farkına varamadıklarımı gizliyorum...', ARRAY['Türk Edebiyatı','Şiir','Erkan Erdamar']::text[], 8.5, '{"poet":"Erkan Erdamar","poet_slug":"erkan-erdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gizli-giz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekletme Beni', 'bekletme-beni-cahit-i-pekoglu-4him6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut ışığım aç gözünü, aç özünü

yüreğini bana aç.

Göz seni arıyor, söz sana muhtaç 

tek sensin derdime ilaç, aşkına muhtaç.

Yeter artık, yeter bekletme beni 

umutsuz, çâresiz birde sensiz tekletme beni.. 

Zor durumda ritmi bozuk yürekler

iş görmez, paslanmış bak eski kürekler. 

Perişanız yetişmezse gerekler… 

Yeter artık, yeter

sensiz ve sevginsiz bekletme beni.

Arsıza, nursuza 

sevgiyi çıkarı için kullanana yar etme beni.

Sırtımıza çıkmasın

sevgisizlerin çıkarcı  yüreği.

Şaşırtmasın yaradan bizi

yürek denizinde çekilsin sevda küreği.

Yeter artık, yeter bekletme beni

Gülden anlamayanları, koklatma bizi..

Güle hasret

koyma beni, gülden öte yar

Ne kadar fidanları budasam

sensiz hep ellerim kanar.

İnsan olmaktan uzaklaşıyorum

sensiz bak her an.

Yeter artık, yeter bekletme beni

yüreğim evgir oldu, daha fazla deldirme beni.. 

Ne bitmez sevdan varmış

harcıyorum, harcıyorum bitmiyor.

Yüreğime sen mükafatmışın

ne kadar inlesede ruhum sana doymadan ölmüyor.

Yeter artık, yeter! Bekletme beni

seviyorum diyeceğim sahte yüreklerde yaşatma beni..', 'Umut ışığım aç gözünü, aç özünü yüreğini bana aç. Göz seni arıyor, söz sana muhtaç  tek sensin derdime ilaç, aşkına muhtaç. Yeter artık, yet...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bekletme-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayakta Kalmalısın', 'ayakta-kalmalisin-serhan-karaduman-llq19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güçlü olmalısın

Her zorluğa birlikte

Her göz yaşına birlikte

Ve her gülümseyişe

Birlikte olmaktan değil sadece

Seni sevdim dediğim her an

Senin için ağladığım her an için

Sen ağlamamalısın

Umut ettiğim her an sen vardın çünkü

Güçlü olmalısın

Çünkü seni ben bulamam 

Kaybolmamalısın her aldanışta

Korkuyu yenmelisin

Onlar üstüne gelse de 

Sen senin için var olmalısın

Çünkü seni sevdiğim için yaşamalısın

Beni var eden öpüşün için katlanmalısın

Düşünmekten vazgeçmeyip

Göğsünü germek için her acıya

Ben varım yanı başında 

Güçlü olmalısın çünkü; 

Seni seviyorum…', 'Güçlü olmalısın Her zorluğa birlikte Her göz yaşına birlikte Ve her gülümseyişe Birlikte olmaktan değil sadece Seni sevdim dediğim her an Se...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayakta-kalmalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Bir Şiir Sana', 'oylesine-bir-siir-sana-ceyhun-kuburlu-t6l0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar mutlu görünsem de

Yüzümün bir köşesinde oturuyorsun

Sesin hala soluğumda 

Ne kadar aldırış etmesem de bu şarkılara

Sözlerinde senden izler

Gözlerinde hala yaz yağmuru ıslaklığı var

Belki şehrin bir ucundasın

Belki bir merhabaya hasret sabahlarımız

Kim bilir belki hala aşka ait

Küçük bir gamze çöküntüsü var 

Yüreğimizin tenha köşelerinde

Belki bir mektup yeter seni anlatmaya

Soğuk akşamların yeni şehrine

Belki bir esinti

Bir boynu bükük menekşe

Belki yalnızlığı sayfaların

Yeter seni anlatmaya

Soğuk akşamların yeni şehrine

Yeterdi sesinden küçük bir sevgi damlası

Sonbaharda tüm çiçekleri açtırmaya... 

7 Kasım 2002

İstanbul - Tekirdağ', 'Ne kadar mutlu görünsem de Yüzümün bir köşesinde oturuyorsun Sesin hala soluğumda  Ne kadar aldırış etmesem de bu şarkılara Sözlerinde sende...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oylesine-bir-siir-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangimiz?', 'hangimiz-serhan-karaduman-qsc2k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Diğerleri var, 

Biz de varız aynı gemide

Kaptan köşkünde oturanlar

ve makina dairesinde.

Hangimiz neresindeyiz bu geminin? 

Kimimiz direğinde

Bazımız pervanesinde

Ama hepimiz aynı yere gidiyoruz

O zaman ya biz olmalı 

ya da diğerleri...', 'Diğerleri var,  Biz de varız aynı gemide Kaptan köşkünde oturanlar ve makina dairesinde. Hangimiz neresindeyiz bu geminin?  Kimimiz direğind...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hangimiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadıklarım', 'anlatamadiklarim-salih-ozalasan-psdc6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazamadıklarımdı yazdıkların 

Söyleyemediklerim söylediklerin

Diyemediklerim dediklerin

Aklımdan geçenler aklından geçirdiklerin

Beni yazmışsın nokta nokta

Yüreğimi dökmüşsün ortaya

Anlatılan öyleki anlatılmaz

Tıpkı uyuyor benim yaşantıma

Benim karanlık gecelere anlattığım 

Yıldızların ağladığı benimle

Gözyaşımdan oluşan pınar

Çağlamış satır satır sözlerinde

Gözlerimdeki alev yüreğimdeki hüzün

Beynimdeki soru işaretleri

Geceye anlatamadığım karmaşık duygular

Hakim olmuş dönüşmüş kelimelere

Benim sözlerimi bana yazmışsın

Benim yerime sen ağlamışsın

Ben korkuyordum ama sen korkmamışsın

Sen satır satır nokta nokta beni anlatmışsın

Y. Tar 09-11-2002 Saat 22.25', 'Yazamadıklarımdı yazdıkların  Söyleyemediklerim söylediklerin Diyemediklerim dediklerin Aklımdan geçenler aklından geçirdiklerin Beni yazmış...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlatamadiklarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-muhammet-fatih-55nq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızlara bakarmısın geceleri... 

Ve sayarmısn kayıp gidenleri 

İnsan sayısınca yıldız varmış 

Ölünce insan yıldızı da kayarmış.. 

Sende biryıldız seç, o ben olayım 

Sen şarkılar soyle ben parlayayım 

Ve... bir gece aniden, yıldızın kaydığı zaman 

Sen şarkına devam et, ağlama sakın arkamdan', 'Yıldızlara bakarmısın geceleri...  Ve sayarmısn kayıp gidenleri  İnsan sayısınca yıldız varmış  Ölünce insan yıldızı da kayarmış..  Sende bi...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglama-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-muhammet-fatih-r322c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çay içeyim dedim seni beklerken... 

Dinlediğimiz son şarkı geldi aklıma içerken. 

Görünce yanımdaki kelebeği, seni hatırladım... 

Çayla beraber aşkınıda yudumladım. 

Sonra, sigarayı her çekişimde içime... 

Meydan okuyordu dumanlar derdime 

Gökte uçan güvercinlere baktım sonra... 

Bende uçardım ya, sardığında beni kollarına. 

Karşımdaki deniz bana gözlerini hatırlattı, bakarken daldım.... 

Tıpkı, saatlerce gözlerine bakarak daldığım gibi daldım. 

Denizde boğulmam ben, ama nedense gözlerinde boğuluyorum... 

Öldükçe sensiz akşamlarda, kollarında yeniden doğuyorum', 'Bir çay içeyim dedim seni beklerken...  Dinlediğimiz son şarkı geldi aklıma içerken.  Görünce yanımdaki kelebeği, seni hatırladım...  Çayla ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusunmek-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bensizlik', 'bensizlik-muhammet-fatih-xefg8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra bir gün hüzünlendiğinde 

Dinmeyen yaşların varsa gözlerinde 

Bir acı duyarsan eğer yüreğinde 

Bil ki canım, bensizliğin acısıdır. 

Çok isteyip de kimseyi sevemezsen 

Saraylarda, köşklerde mutludeğilsen 

Uyku tutmaz, gecelerde dertlenirsen 

Bil kicanım, bensizliğin dertleridir. 

Kalabalık caddelerde yalnızmışcasına 

Yürüyorsan, boynu bükük, tek başına 

Ben sanıyorsan her çıkanı karşına 

Bil ki canım, bensizliğin hayalleridir', 'Yıllar sonra bir gün hüzünlendiğinde  Dinmeyen yaşların varsa gözlerinde  Bir acı duyarsan eğer yüreğinde  Bil ki canım, bensizliğin acısıdı...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bensizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece ve Ben', 'gece-ve-ben-muhammet-fatih-3j0ga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece; sessiz, sakin ve karanlık 

Ben; sensiz, kimsesiz ve dağınık 

Gece; dertlerin boğuştuğu, köpeklerin koşuştuğu 

Ben; ben ki gecelerde dertlerin coştuğu 

Bir gece, bir ben, bir de yıldızlar 

Gecede yıldızlar parlar, ben de ateşler yanar 

Bazen bir yıldız kayar sessizliğinde gecenin 

Bir sızı gelir derinliğinden ta yüreğimin..', 'Gece; sessiz, sakin ve karanlık  Ben; sensiz, kimsesiz ve dağınık  Gece; dertlerin boğuştuğu, köpeklerin koşuştuğu  Ben; ben ki gecelerde de...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-ve-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek', 'seni-beklemek-muhammet-fatih-36fh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni beklemek ne zor, ne tarifsizmiş meğer 

Ama olsun, beklediğim sensin ya... her şeye değer... 

Seni beklerken bütün duyguları bir arada yaşadım... 

Geleceksin diye sevinirken, gelmeyişine ağladım... 

Şarkılar çalıyordu, dinledim durdum... 

sen gelmedin ya, nasıl yandım, kahroldum 

Bekledim öylece dakikalar geçti hep... 

Gelmedin, gelmedin işte, neydiki sebep... 

çayımı yudumlarken, sigaramı içerken 

Seni düşünüyorum yine, seni beklerken... 

Ya sen? nerdesin? kimlesin? ya da nasıl? 

Seni beklemekle mi gececek yoksa bütün fasıl?', 'Seni beklemek ne zor, ne tarifsizmiş meğer  Ama olsun, beklediğim sensin ya... her şeye değer...  Seni beklerken bütün duyguları bir arada y...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-beklemek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurmu', 'olurmu-muhammet-fatih-q4kei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat kaç, güneş ne zaman doğacak? 

Yine doğup yıldızlarımı boğacak 

Yıldızlar, gece yine gelin olur mu? 

Götürdüğünüz dertlerimi getirmeyin olur mu?', 'Saat kaç, güneş ne zaman doğacak?  Yine doğup yıldızlarımı boğacak  Yıldızlar, gece yine gelin olur mu?  Götürdüğünüz dertlerimi getirmeyin ...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olurmu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin Umurunda', 'kimin-umurunda-muhammet-fatih-xfiiy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşların şikayeti var; özgürlükten 

Bülbüllerin derdi var; sessizlikten 

Açmadan soluyor güller baharda 

Ağlayan çocuklar kimin umrunda? 

Buğday vermez oldu başaklar 

Söylenmiyor artık eski şarkılar 

Zalimlere şimdi bütün alkışlar 

Mazlumlar kimin umrunda? 

Hak var, hukuk var, hayat var 

Doğmamış yetimin hakkı var 

Birde burdan sonrası var 

Sonrası kimin umrunda?', 'Kuşların şikayeti var; özgürlükten  Bülbüllerin derdi var; sessizlikten  Açmadan soluyor güller baharda  Ağlayan çocuklar kimin umrunda?  Bu...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimin-umurunda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-muhammet-fatih-h2hn1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zor günlerdeyiz, kötü günlerde 

Aynı dert, aynı acı var yüzlerde 

Cevapsız sorular bütün beyinlerde 

Derinden kanayan yara var yüreklerde 

Biliyorum geçecek bu günler 

Bizi bekliyor halaylar, düğünler 

Şimdi yaşlı olsa da gözler 

Yarın gülecek bütün yüzler 

Ağlayın çocuklar, bu son yaşlarınız 

Bekleyin analar, ağarsa da saçlarınız 

Üzülmeyin evlatlar, aydınlıktır yarınlarımız 

Biz ağlasak da gülecek çocuklarımız 

Umutlarımız var, hiçbir şey kalmasa da 

Yine doğacak güneş bu gün batsa da 

Yarınlar bizim, bizimdir mutlaka 

İyi bak göreceksin, iyi bak ufka', 'Zor günlerdeyiz, kötü günlerde  Aynı dert, aynı acı var yüzlerde  Cevapsız sorular bütün beyinlerde  Derinden kanayan yara var yüreklerde  B...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umut-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Bitimine Karşı Sataşmalar..', 'gun-bitimine-karsi-satasmalar-i-smail-erkan-tolay-pzs8a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk beyazı bakmalarımdı

yaşamakların koyu renklerine

gölgeler düşüren

ve ben her gün bitiminde

peşinde koştum

çarpıldım, çark ettim

kılıçtan geçirdim

mısraladım manikledim

yinede yetişemedim 

gölgelerime

köknar endamınca

derinlerdeydi köklerim

tüm yaşlı ruhlar gibi

çekip almak kıvanmak ister

kılıç ister kın ister 

sırp sındığı mercidabık kosova

bazen de sen ister

kıvanmam için

yine de bunu 

bilmemelisin

bir cana dokundum dün gece

üşüdü ruhum, ruhumu ter bastı

bakışları aşk beyazı

değdi en mahrem beyin hücrelerime

neden dedim

bir açıklama, 

bir ulak bekledim

neden, neden yazılmaz hala

bu satırlar

gölgeler kitabına

camda haleler var

kefiyeler, sıla düşleri

dikkatli bakarsan göreceğin

keşaneler var viraneler

hatta kandiller

camda haleler

birleşip ruhumu çizer

Sucuklu bir lokomotifdir oysa

benim ruhum

uzaklara götürür değdiklerini

kaçmak gerekir insanlardan tattığında

gelenekseldir yavaş hareket eder

hızla tüketilir

sucuklu bir lokomotifdir

benim ruhum

sosyal demokrat bir titizlikle bakarken mazime

mistik anılardı beğendiğim

jimnastik coğrafya felsefe

değil, ayıplanacak tecrübeleri seçtim

ayıplı bir hayattı 

homo sapiens olmak

faturası budur 

irsaliyesi imzalı bir bütünlükle taşıdığımız düşler

belgelendi ve ödendi

aşk beyazı bakışlarımız yasaklıydı

sözlerimize kaldı dünya

öyküm

başlangıcı, serimi, sonucu

kaynakçası

olmayan rakamlardan seçildi

buyurmam için, ki

buyurdum: 

iş bu buyurudan sonra

sonuçlar önünde gidecektir

nedenlerin

nedensiz yaşamalarla ödüllendirilecek

bir keyfiyettir bu

...ve tarih

...ve imza hanesi

sonuçsuz kalmış nedenleri 

evlendirme dairesi

yav, madem öyle

söyleyelim polise

bir suç beğensin hepimiz için

suç ortağı olalım

homo sapiens olmaktan gayrı bir suç

büyük ve değerli

ve nedensiz

olanaksız duygularla ödensin

bu sonuç

senden ayrılma nedenim

bilmemendir gizli kardinali

hatta hakasyadaki zencefil

bile umurumda değil

saymıyorum

günbatımı düşlerini planktonların

oysa yakamozlar gördün sen sadece

gördün ama her rengi gözlerinle

aşk beyazıydı benimkiler

kahverengi değildi

suç yoktu kadın cinsinde

ne çok kadın sevdim

ne çok gece

kara değdi kızıl kahverengi

ne çok gece için için

bulut aradım karanlıkta

aşk beyazı bakmalarım

için

vizigotları merak ediyorum

kızgınım dorlara lemurya ya

neden, neden seviniyor içim

her yenilgimde

neodantal bir hüzünle

bahaneler de üretemiyorum

kaybolan aşklar için

için için seviniyorum neden

ve ne için? 

hey gidi 1815 tarihli ayıbalığı dişleri

1890 lardan teneke kalemliğim

17 teşrin-i evvel binikiyüzsekseniki

vakanüvis notları

çin yazısı için kalemlik

birde, kobra yılanı

(hint unutulmamalı) 

yetmiyorsunuz

aşk beyazı gözlerime

ruhum sizden bile yaşlı

ve artık son verebilirim

günbatımı

(18/09/2002 17: 40)', 'Aşk beyazı bakmalarımdı yaşamakların koyu renklerine gölgeler düşüren ve ben her gün bitiminde peşinde koştum çarpıldım, çark ettim kılıçtan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":120,"source_url":"https://www.antoloji.com/gun-bitimine-karsi-satasmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Gaffar', 'adi-gaffar-muhammet-fatih-spnox', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir can daha gitti, adı Gaffar 

Gaffarım şehid olmuş, yüreğim yanar 

İnsan olan, insana nasıl kıyar 

Bir can daha gitti, adı Gaffar 

Cesurdu, yürekliydi, korkmuyordu 

Vatan için, millet için çalışıyordu 

Bir akşam hainler onu vurdu 

Bir can daha gitti, adı Gaffar 

Zengin, fakir, kimseyi ayırmıyordu 

Hem seviyor, hem de seviliyordu 

Herkes ona “Baba” diyordu 

Bir can daha gitti, adı Gaffar 

Unutmayın, şunu iyi bilin 

Bu vatan bizim hepimizin 

Kanıyla sulandı şehitlerimizin 

Bir can daha gitti, adı Gaffar 

Biz canız, cananımız vatan 

Uğruna canlar gider, kalır canan 

Yine gitti bir can, Gaffar Okkan 

Bir can daha gitti, adı Gaffar 

Vurulur canlar, şehid olur 

Sanmayın onlar yok olur 

Bu vatan ne canlar doğurur 

Bir can daha gitti, adı Gaffar', 'Bir can daha gitti, adı Gaffar  Gaffarım şehid olmuş, yüreğim yanar  İnsan olan, insana nasıl kıyar  Bir can daha gitti, adı Gaffar  Cesurdu...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adi-gaffar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-muhammet-fatih-evjvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat zor.Yaşamaksa zor mu zor 

Hele ''''Adam gibi'''' yaşamak ''''ZOR'''' 

sözcüğünün anlatamayacağı kadar zor 

Evet, Yaşamak ve de yaşatmak... 

Hayatı yaşamak... 

Duyguları yaşamak... 

Aşkla sevgiyle yaşamak 

Aşkı, sevgiyi, dostluğu, 

insanlığı yaşamak ve de yaşatmak 

Hayatı yürekle bütünleştirebilmek. 

Aşkı yaşamak ve yaşatmak yüreklerde... 

Soldurmadan, aşkla açan gülleri koparmadan 

Sevgi ve hoşgörü içerisinde yaşamak. 

yaşamak; tüm güzellikleri 

ve yaşarken yaşatabilmek. 

Yaşamanın mutluluğunu hissedebilmek 

Ve hissettirebilmek... 

Sevgiyi hissettirebilmek sevdiğine... 

Ve paylaşmak... 

Bir ekmeği paylaşmak, en aç olduğu zamanlarda bile... 

susuz çöllerde bir tas suyu suyu paylaşabilmek... 

Ekmeği paylaşır gibi paylaşmak dostluğu, dostlarla. 

Suyu paylaşır gibi paylaşmak sevgiyi, 

sevgiye muhtaç yüreklerle... 

Ve hayatın tüm güzelliklerini paylaşmak. 

Ayrım yapmadan paylaşabilmek 

Sevgiyi, hoşgörüyü, mutluluğu... 

''''PAYLAŞMANIN ASİL DUYGUSUNU 

BENCİLLİĞİN ÇİRKİNLİĞİNE DEĞİŞMEMEK'''' 

Ayırmadan verebilmek tüm güzellikleri, eşitcesine... 

Ayrılmamak İnsanlardan ve hayattan 

Bıkmamak, bıkmadan ve bıktırmadan yaşamak hayatı... 

Ve... Anlamak...Anlayarak ve anlatarak yaşamak 

Anlatabilmek hayatı, aşkı ve sevgiyi... 

Anlayabilmek acıyı, ızdırabı ve kederi... 

Basit menfeatler uğruna asil duyguları kirietmemek. Kandırmadan ve kanmadan 

Ama kana kana, doya doya yaşamak... 

İşte kısaca ''''YAŞAMAK'''' budur. 

Ve bu ''''ASİLLERİN'''' olgusudur.', 'Hayat zor.Yaşamaksa zor mu zor  Hele ''''Adam gibi'''' yaşamak ''''ZOR''''  sözcüğünün anlatamayacağı kadar zor  Evet, Yaşamak ve de yaşatmak...  Ha...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yasamak-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-muhammet-fatih-f2qwp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tık, tık, tık...saat ilerliyor, zaman bitiyor... 

Buradan oraya seninle ne gidiyor.... 

Sualler buldumu bir cevap, buldumu 

Gidipde geriye hiç dönen oldumu', 'Tık, tık, tık...saat ilerliyor, zaman bitiyor...  Buradan oraya seninle ne gidiyor....  Sualler buldumu bir cevap, buldumu  Gidipde geriye h...', ARRAY['Türk Edebiyatı','Şiir','Muhammet Fatih']::text[], 8.5, '{"poet":"Muhammet Fatih","poet_slug":"muhammet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yolculuk-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaşlarım', 'gardaslarim-ozan-nebi-dadaloglu-5mk3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vura vura dizlerime

                                     Kan indirdim gözlerime

Kapımızda zilimiz yok

Oyumuz çok, kendimiz yok

Bilirik, balı yiyemek

Gardaşlarım, gardaşlarım! ..

Kapımızda aşcımız yok

Kelimiz çok, saçımız yok

Bilirik, tek görünemek

Gardaşlarım, gardaşlarım! ..

Kapımızda filomuz yok

Şapkamız çok, enimiz yok

Bilirik, takım giyemek

Gardaşlarım, gardaşlarım! ..

Kapımızda dutmamız yok

Ovamız çok, tarlamız yok

Bilirik, tek görünemek

Gardaşlarım, gardaşlarım! ..

Kapımızda yatımız yok

Kenemiz çok, kanımız tok

Bilirik, hap sürünemek

Gardaşlarım, gardaşlarım! ..', 'Vura vura dizlerime                                      Kan indirdim gözlerime Kapımızda zilimiz yok Oyumuz çok, kendimiz yok Bilirik, balı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Nebi Dadaloğlu']::text[], 8.5, '{"poet":"Ozan Nebi Dadaloğlu","poet_slug":"ozan-nebi-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gardaslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkon', 'balkon-ozan-nebi-dadaloglu-pfuqq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu çiçekler senin olsun

                                         Ben ırahan ekiciyim! ! ! 

Sarılar içinde gördüm

Çelik’de meneviş gibi

Tavsırı yüzüme sürdüm

Yüzüm yüze değmiyeli.

Açılmıssın leylak gibi

Görmüyeli görmiyeli

Aşlarımız çok küllendi

Seher yeli değmiyeli.

Unutulmaz Avşar eli

Toros’da yaylamız belli

Dağlar güllü reyhanlı

Sam yelleri değmiyeli.', 'Bu çiçekler senin olsun                                          Ben ırahan ekiciyim! ! !  Sarılar içinde gördüm Çelik’de meneviş gibi Tavsı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Nebi Dadaloğlu']::text[], 8.5, '{"poet":"Ozan Nebi Dadaloğlu","poet_slug":"ozan-nebi-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/balkon-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimiz', 'ellerimiz-ozan-nebi-dadaloglu-alnl8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sizin eller tükenecek 

Bizim eller öpülecek

Sizin elleriniz beyaz

Gödek gödek, yuvak yuvak

Gara bizim ellerimiz

Boğum boğum, çatlak çatlak

Sizin eller fink atıyor

Bizim eller çark tutuyor

Yer altında yer üstünde 

Gene hepsi bizim eller

Bizim ellere vurulur

Gara gatran, sarı gına

Sizin ellere sürülür

Elvan elvan, türlü boya

Bizim eller üretiyor

Sizin eller tüketiyor

Bizim düzende geliyor

Tükenecek sizin eller', 'Sizin eller tükenecek  Bizim eller öpülecek Sizin elleriniz beyaz Gödek gödek, yuvak yuvak Gara bizim ellerimiz Boğum boğum, çatlak çatlak S...', ARRAY['Türk Edebiyatı','Şiir','Ozan Nebi Dadaloğlu']::text[], 8.5, '{"poet":"Ozan Nebi Dadaloğlu","poet_slug":"ozan-nebi-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ellerimiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-ozan-nebi-dadaloglu-6k13r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Binbir derdin gamıyla

                          Gene hep seni düşündüm, 

Güzel gerdanını gördüm

Gar çiçeği, gar çiçeği

Gızıl saçın büklüm büklüm

Nar çiçeği nar çiçeği.

Yaradan nasıl yaratmış

Ağlar gözüm gülse sana

Dağlarını gırcı dutmuş

Güneş olsam doğsam sana

Dadal’ım gördüm düşümde

Üstümüze bir nur doğmuş

Uzanmışız o biçimde

Kervangıran döşşek olmuş...

                      Ozan Nebi DADALOĞLU', 'Binbir derdin gamıyla                           Gene hep seni düşündüm,  Güzel gerdanını gördüm Gar çiçeği, gar çiçeği Gızıl saçın büklüm bü...', ARRAY['Türk Edebiyatı','Şiir','Ozan Nebi Dadaloğlu']::text[], 8.5, '{"poet":"Ozan Nebi Dadaloğlu","poet_slug":"ozan-nebi-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-dusundum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-arif-baltaci-216m2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Değseydi yüreğimiz bir kere birbirine

Söndüremzdi bu aşkı ne yağmur ne kar 

Gülseydin bir kere dokunuca ellerine 

İnan zemheride bile olurdu bahar 

Yine sardı gönlümü sebepsiz bir sızı

Yüreğimde bir aşk var güller kadar kırmızı 

Sen gönül sarayımın son vefasızı 

Sevin işte oldum yine tarumar

Senin için uykumu boşa harap etmişim

Senin için boşuna bu dünyadan geçmişim

Ardından boş yere kahırlanıp içmişim

Bu tatlı rüyada buraya kadar

Seni tekrar anarsam tutulsun bu dilim 

Seni tekrar yazarsam kırılsın kalemim

Sen değilmisin ölüm sebebim

Sanma gönül kuşu tekrar sana konar 

Yenilgide tattım bu aşkın zaferini

Zevk-ü sefaya kattım gönlümün kederini

Ne de olsa sen yazdın bu aşkın kaderini

Şimdi bana dönmüşsün neye yarar...

			12.09.2002

		Z.KAMİL/İSTANBUL', 'Değseydi yüreğimiz bir kere birbirine Söndüremzdi bu aşkı ne yağmur ne kar  Gülseydin bir kere dokunuca ellerine  İnan zemheride bile olurdu...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neye-yarar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ardından', 'gecenin-ardindan-arif-baltaci-5dzrd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairin yüreğinden dökülürdü mısralar 

Yıldızlarla gelerek dalgaları severdi

İstanbul yeni bir güne soyunurdu 

Bütün çıplaklığıyla 

Sen gelirdin aklıma tüm ışıklar sönerdi

Ne taksimde çılgınca tanışmalar isterdim 

Ne de giden taksinin ardından bakakalmak

Yağmurların yerine sen yağsaydın tenime 

İstanbul mutlu bir güne soyunurdu belkide

Beşiktaş sahilinde insanlar umarsızdır

Elele olsalarda gönülleri yalnızdır

Dalgalar döverken o çaresiz taşları 

Bilseydim sonunu döker miydim yaşları 

Güneşin doğmasıyla bütün büyü bozuldu 

Üzülmek neye yarar ki kader böyle yazıldı 

					30.09.2002

				BEŞİKTAŞ/İSTANBUL', 'Şairin yüreğinden dökülürdü mısralar  Yıldızlarla gelerek dalgaları severdi İstanbul yeni bir güne soyunurdu  Bütün çıplaklığıyla  Sen gelir...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gecenin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülküyü Seçtim', 'ulkuyu-sectim-arif-baltaci-kg13f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Marksist bir teorinin

Sosyalist akımıyla 

Biten bizim aşkımızdı 

O güneş batımıyla

Sen lenin kitapları

Okurken gündüz gece 

Ben ülküye vuruldum 

Senden seneler önce 

Şimdi bana seç diyorsun 

Bunlardan birisini

Ben ülkümü seçtim 

Boşverdim gerisini

Ülkü bizim sevgimizdir 

Ülkü bize bir ışık 

Gönül sevgiliye değil

Büyük davaya aşık

Biz ebediyetler isteriz 

Fanide yoktur gözümüz

Bildiğimiz tek gerçek var 

Kuran''dır tek sözlüğümüz

Aşk denen o gizemin

Esrarını biz biliriz

Ahiret bahçelerinden 

Sevgiliye gül veririz

Başbuğumun yolundan 

Neferler yetişiyor

Çarpık siyaset çarkının

Hareketi değişiyor

Tanrıdağından başlayıp

Dünyaya dağılmışız

Biz bu turan uğrunda 

Yollarda yaya kalmışız

Azap değilki bize 

Olmasın evdeşimiz evimiz

Biz bu dava uğrunda 

Ne canları vermişiz...

				05.07.2002

			     İstanbul/Z.Kamil', 'Marksist bir teorinin Sosyalist akımıyla  Biten bizim aşkımızdı  O güneş batımıyla Sen lenin kitapları Okurken gündüz gece  Ben ülküye vurul...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ulkuyu-sectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-arif-baltaci-x4417', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susma sevdiğim; 

Bırak bana gecenin karanlığından bahsetmeyi

Yıldızlarına bak seyret gökyüzünü

Çıkar gizemli kalbinden sevdayı 

Haykır artık yüzüme söyle hüznünü

Kısma sevdiğim; 

Gönül ezgisinin yükselen sevgisini

Azap olmasın istiyorsan o karanlık geceler

Anlat insanlara bu aşk hikayesini

Anlat ki çözülsün çözülmeyen bilmeceler

Küsme sevdiğim; 

Zamansız açtı diye sevda çiçeklerine 

Onlar ki senin için umut oldu her zaman

Dönme artık hayat gerçeklerine 

Uzat ellerini yüreğin bam teline

Yeşillensin dört bir yan

Esme sevdiğim; 

Asi rüzgarlara uyupta sevdamdan kaçmak için

Senki pervasız yüreğimde kardelensin

Yeşil gözlerinde bu yaşlar niçin 

Bırakta bu yaşlarda yüreğim son nefesini versin

Sen son nefesimde bile tek isteğimsin....

				29.08.2002

			İstanbul / Z. Kamil', 'Susma sevdiğim;  Bırak bana gecenin karanlığından bahsetmeyi Yıldızlarına bak seyret gökyüzünü Çıkar gizemli kalbinden sevdayı  Haykır artık...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdigim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Gece', 'son-gece-arif-baltaci-r6e1o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın gözyaşlarıydı dökülen ellerine 

O bodrum katındaki son gecede 

Sen umarsız uyurken o daracık odada 

Elimizden kaçıverdi sevda kuşu bir anda 

Örterken saçların o bembeyaz tenini

Bir anda unutmuştum şu gölün matemini

Son sigaramın son nefesi gibi 

Bir anda içime çekmiştim seni

Sigarayı bırkatım dumanında sen vardın

Her gördüğüm yüzde karşıma sen çıkardın 

Şimdi söyle bana sevdiğim

Bilir misin senden sonra ben ne haldeyim 

Son gecede ilk defa seni öpmüştüm

Senden sonra acımı gecelerle bölüştüm 

Bana çılgın diyordun ya öperken dudağından 

Bir bebek kadar üzgündüm anasından ayrılan 

En güzel bölümüde kapattın bu perdeyi

Aşk sayfam yırtık yapıştırıcımı almışlar elimden

Ne mümkün seni unutmak son geceyi silmek kaderimden

Nadasa bıraktım gönlümün tarlasını 

Bıraktım ki rahatça yaşayayım yasını...

					21.09.2002

				   Z.KAMİL/İSTANBUL', 'Aşkın gözyaşlarıydı dökülen ellerine  O bodrum katındaki son gecede  Sen umarsız uyurken o daracık odada  Elimizden kaçıverdi sevda kuşu bir...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/son-gece-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlticâ', 'i-ltic-mustafa-engin-karatay-r0i94', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yâ Rabbî, dokunmasın hiç kimseye zarârım

Hem kendime, hem mahlûkuna olsun yarârım

Sana mültecîyim, bu en samîmi karârım

Mevlâm, verilen sözümden asla caydırma...

Herkesi eyle, benden daha samîmi kulun

Nâs içinde hükmü kalksın, şöhret, para, pulun

Muhabbetli gönüllerde, kıymeti vardır çulun

Ayağımı sâbit eyle, bir an bile kaydırma...

Âhir ömrüm, bundan böyle yolunadır fedâ

Yârenim, can yoldaşım, küsüp etse de vedâ

Abdullâh''ım, ısrarlıyım, bu bende kat''î sedâ

Taâtimi boşlayıp da, şu nefsimi baydırma...

Takvimde bu gün Pazar, günlerden Yedi Kasım

Geçen ömre tutarım, âh edip şimdi yasım

Seviyorum herkesi, olsa da çoğu hasım

Yeter ki rezîl etme, esrârımı  yaydırma...

Çok günâhlar işledim, yine utandırmadın

Şükürler olsun Rabbim, Sen''den usandırmadın

Harama uçkur açıp, cürme uzandırmadın

Rûz-i Mahşer''de beni, sakın pişmân aydırma...

Son nefeste Dünyâ''dan, iffetimle göçeyim

Sırat''ın üzerinden, sualsizce geçeyim

Cemâlin''i görüp de, aşk badesin içeyim

Hatâmı gizli eyle, şâhidlere saydırma...

07.11.1999    Landsberg   23: 20', 'Yâ Rabbî, dokunmasın hiç kimseye zarârım Hem kendime, hem mahlûkuna olsun yarârım Sana mültecîyim, bu en samîmi karârım Mevlâm, verilen sözü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/iltica-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzel Tesadüf', 'ne-guzel-tesaduf-arif-baltaci-jme2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir aşkın çığlıklarını silerdi 

Yeni bir aşkın fısıltıları 

Nasıl tanışırki tanışmayanlar deme 

Kendini bırka kaderin ellerine

Damdan düşer gibi aşık olmak ne güzel 

Ne güzel vurulmak böyle birine 

Böyle bir tanışma nasipmiş bize 

Tesadüfler içinde istasyon gişesinde

Bilet bulma teleşıyla seni görmek 

Sonra dalmak o yeşil gözlerine 

Tren hızla yol alırken haydarpaşaya 

Garip bir titreme sardı beni

Sonra tuttum ellerini 

Evet bir serseriyim belkide 

Ya da bir deli kimbilir 

Ben yoldaş arıyorum kendime 

Artık bütün yollar sende kesişir 

Demiştim ya aşkın zamanı yoktur 

Yine apansız geldi yine amansız geldi 

Ben aşka çoktan tövbe etmiştim ama 

O yeşil gözlerin aklımı çeldi...

				20.08.2002

			KADIKÖY/İSTANBUL', 'Bir aşkın çığlıklarını silerdi  Yeni bir aşkın fısıltıları  Nasıl tanışırki tanışmayanlar deme  Kendini bırka kaderin ellerine Damdan düşer ...', ARRAY['Türk Edebiyatı','Şiir','Arif Baltacı']::text[], 8.5, '{"poet":"Arif Baltacı","poet_slug":"arif-baltaci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-guzel-tesaduf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğerse', 'megerse-ozer-bal-knpjo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bütün bunlar manasızmış

meğer herşey yalanmış

meğer ben deliymişim

bütün olanları

meğer ben uydurmuşum', 'bütün bunlar manasızmış meğer herşey yalanmış meğer ben deliymişim bütün olanları meğer ben uydurmuşum...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/megerse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ''Ara''dayız', 'bir-ara-dayiz-ozer-bal-1bysb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'öncesini bilmeyiz

anlatırlar dinleriz

sonrası ayrı konu

rivayetler muhtelif

biz ''ara''dayız

biraradayız

bir arayı 

doldurmaktayız', 'öncesini bilmeyiz anlatırlar dinleriz sonrası ayrı konu rivayetler muhtelif biz ''ara''dayız biraradayız bir arayı  doldurmaktayız...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-ara-dayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun', 'lanet-olsun-ozer-bal-vudsz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep böyledir bu

birinin büyülü zorluğuna inat

diğerinin tiksindiren kolaylığı

koparır seni birinden 

diğerine bağladığı kadar.', 'hep böyledir bu birinin büyülü zorluğuna inat diğerinin tiksindiren kolaylığı koparır seni birinden  diğerine bağladığı kadar....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/lanet-olsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
