INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmeyen Bizleriz', 'gormeyen-bizleriz-ozer-bal-3e44d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yanılan bizleriz

görüntüler varlığınca doğal

biz adlıyoruz olduğumuzca

çokça da yanılıyoruz

kendimizi aklayıp

onları yalanlıyoruz.', 'yanılan bizleriz görüntüler varlığınca doğal biz adlıyoruz olduğumuzca çokça da yanılıyoruz kendimizi aklayıp onları yalanlıyoruz....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gormeyen-bizleriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşsüz Olmaz', 'dussuz-olmaz-ozer-bal-nl6fa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sözlerim yalan olsa da

söze gelmez ama 

düşlerim değil

adına düşler kurmayalı

inan hiç birşey 

eskisi gibi değil.', 'sözlerim yalan olsa da söze gelmez ama  düşlerim değil adına düşler kurmayalı inan hiç birşey  eskisi gibi değil....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dussuz-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice Bir Gece', 'gizlice-bir-gece-ozer-bal-h33d9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gizler gözlerde gizlidir

gözler karanlıkta gizlenir

karanlık gözleri

gözler gizleri gizler

geceleri 

gizlerimiz gözlerimizde

gizleniriz', 'gizler gözlerde gizlidir gözler karanlıkta gizlenir karanlık gözleri gözler gizleri gizler geceleri  gizlerimiz gözlerimizde gizleniriz...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gizlice-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Mahsulleri', 'hayal-mahsulleri-ozer-bal-nylrd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yoktunuz aslında

yaratan bendim

sevdim.

sevilen ne varsa

saftı.

saflık hep ardımda

önümde yoklar, 

bir yol ayrımında

seçmek değil

yaratmak vardı.', 'yoktunuz aslında yaratan bendim sevdim. sevilen ne varsa saftı. saflık hep ardımda önümde yoklar,  bir yol ayrımında seçmek değil yaratmak v...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayal-mahsulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Size İltimas Bana Kıyak', 'size-i-ltimas-bana-kiyak-ozer-bal-3s81a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'en az bir maskemiz var

bir de kendimiz - etti mi iki

bunlar bildiklerimiz

ya diğerleri? 

demek kabul ettiniz

maskeleri indirin

benden izinlisiniz.', 'en az bir maskemiz var bir de kendimiz - etti mi iki bunlar bildiklerimiz ya diğerleri?  demek kabul ettiniz maskeleri indirin benden izinli...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/size-iltimas-bana-kiyak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-ahmet-sever-qr2pr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kulağım kapı zilinde, gözüm sokakta

İrkilmekteyim duyduğum her motor sesinde, 

Acaba demekteyim geçen her insanda.

Terliklerin, su içtiğin bardağın, 

telaşla çıkarıp fırlattığın pijamaların duruyor

bıraktığın yerde, 

Onlar gibi bende bekliyorum seni.

‘Uzaktayım’ diyorsun, 

ışığım sönüyor perde perde.

Bir ürpertidir alıyor her yanımı, 

Kucaklıyorum boşluğu, seni kucaklar gibi.

Anlıyorum; en çok ihtiyacım olduğu anda 

yanımda olamayacaksın. 

Biliyorum ki yine yalnızım.

Dayanılır şey değil, böyle yaşamak... (20.10.2002)', 'Kulağım kapı zilinde, gözüm sokakta İrkilmekteyim duyduğum her motor sesinde,  Acaba demekteyim geçen her insanda. Terliklerin, su içtiğin b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satır Arası Mutluluk', 'satir-arasi-mutluluk-ahmet-sever-cyuie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Alınyazısıdır yaşam, 

Satır aralarında gizlidir mutluluk.

Satır araları olmasa, 

Koca bir yalandır yaşamak.

Satır aralarını bulmaya çalışarak geçirir insan küçücük yaşamını.

Üzülür, yıkılır, kahrolur çoğu zaman, 

Satır aralarındadır istediği gerçek yaşam.

Düz bir yazı değildir yaşam, 

Devrik cümlelerden kurulmuştur her zaman.

Okuyan başka, dinleyen başka hisseder

Satır aralarıdır atlanan.

Düz bir yazı, hatta bir tek cümle olmalıydı yaşam, 

Satır arasına gerek olmayan.

Her satırı ayrı bir mutluluk olmalıydı, 

Yorgunum, satır aralarını bulmaya çalışmaktan.', 'Alınyazısıdır yaşam,  Satır aralarında gizlidir mutluluk. Satır araları olmasa,  Koca bir yalandır yaşamak. Satır aralarını bulmaya çalışara...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/satir-arasi-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liman', 'liman-ahmet-sever-4sjgy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'fırtınalı bir havada, 

çalkantılı bir denizde yola çıkmış

bir sandal gibiyim.

yetmezmiş gibi bir de sis var.

sığınılacak limanı arıyorum, 

ama fenerini bile göremiyorum.

yanlış limanların fenerleri, 

çekmekte beni sarp kayalıklarına.

bir gün dağılacak sağlam gözüken iskeletim.', 'fırtınalı bir havada,  çalkantılı bir denizde yola çıkmış bir sandal gibiyim. yetmezmiş gibi bir de sis var. sığınılacak limanı arıyorum,  a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/liman-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevdiğim Olmalı', 'bir-sevdigim-olmali-ahmet-sever-3x6fn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevdiğim olmalı, 

Gece yarısı çıkıp gelmeli 

Bas pedala götür beni, 

Bilmediğim diyarlarda sarıl bana, 

Tut ellerimi hiç bırakma 

ben senin yanında başladım yaşamaya demeli.

Çıkmalıyız bilmediğimiz yolculuğumuza

Güneşin doğmasından, 

gecenin büyüsünün bozulmasından korkmalıyız, 

İki yüzlü ilişkilerden, 

yarına taşınacak telaşlardan 

alabildiğince uzak olmalıyız.', 'Bir sevdiğim olmalı,  Gece yarısı çıkıp gelmeli  Bas pedala götür beni,  Bilmediğim diyarlarda sarıl bana,  Tut ellerimi hiç bırakma  ben se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sevdigim-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamsız', 'anlamsiz-ahmet-sever-j5p0v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırladın mı bilmem

Hani geçen gün yolun ortasında

Bana kızıp bağırmış, sonra çekip gitmiştin

Biliyor musun sonra ne yaptım? 

Eve gidip çiçekleri suladım.

Neden mi yaptım, ne amaçla mı? 

Valla ne desem yalan olur, 

Her ikisine de anlam veremedim.', 'Hatırladın mı bilmem Hani geçen gün yolun ortasında Bana kızıp bağırmış, sonra çekip gitmiştin Biliyor musun sonra ne yaptım?  Eve gidip çiç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Yanımda Olacaktın', 'simdi-yanimda-olacaktin-ahmet-sever-d143v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eee! Havalar soğudu

Sobayı demin yaktım 

Ama ayaklarım üşüyor

Bir yerden soğuk geliyor olmalı

Ahh! Yanımda sen olacaktın şimdi

Mutlaka kulaklarım kızarırdı.', 'Eee! Havalar soğudu Sobayı demin yaktım  Ama ayaklarım üşüyor Bir yerden soğuk geliyor olmalı Ahh! Yanımda sen olacaktın şimdi Mutlaka kulak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/simdi-yanimda-olacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elindeki', 'elindeki-ahmet-sever-vpnbm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yatsam iyi olacak.

Yatmak dedim de aklıma geldi 

Evvelki gece rüyamda gördüm seni

Elinde ucu yanan bir sigara uzatıyordun bana

Diğer elindekini hiç sorma!', 'Yatsam iyi olacak. Yatmak dedim de aklıma geldi  Evvelki gece rüyamda gördüm seni Elinde ucu yanan bir sigara uzatıyordun bana Diğer elindek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elindeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-ahmet-sever-bvdiw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi ise hayattaki en önemli şey, 

İşte önem benim.

Şefkatse sığınılacak tek şey, 

Ben buradayım.

Eğer yalnızlıksa 

İşte o benim.

Eğer ki hiç biri değil ölümse en korktuğun şey, 

Bırak onu ben buradayım derim.”', 'Sevgi ise hayattaki en önemli şey,  İşte önem benim. Şefkatse sığınılacak tek şey,  Ben buradayım. Eğer yalnızlıksa  İşte o benim. Eğer ki h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huy', 'huy-ahmet-sever-snshh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce gülerim, sonra düşünürüm; 

Benim huyum bu! 

Ne kadar acıklı olursa olsun.', 'Önce gülerim, sonra düşünürüm;  Benim huyum bu!  Ne kadar acıklı olursa olsun....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/huy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı Kartı', 'yilbasi-karti-ahmet-sever-x9mca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yılbaşı günü, bana kart yazıp önlüğümün cebine koymuşsun

Üstüne, ne bana yazdığına dair bir yazı

Ne de yazanın kim olduğunu yazmışsın, 

Üstelik sonuna da ‘seni seviyorum’

Yazmışsın süslü büyük harflerle; 

Ama güzelim ben o önlüğü arkadaşa ödünç vermiştim, 

Bana bakışları değişti son iki gündür.', 'Yılbaşı günü, bana kart yazıp önlüğümün cebine koymuşsun Üstüne, ne bana yazdığına dair bir yazı Ne de yazanın kim olduğunu yazmışsın,  Üste...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yilbasi-karti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-ahmet-sever-dxovs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkalı kaç yıl olmuşta, 

Sana hiç şiir yazmıyor muşumda, 

Efendim mektup zarfı bile yokmuş senin ismine ait; 

Hadi bakalım şimdi ne söyleyeceksin? 

Şiiri postaya verdim, karşılığını isterim

Sağ yanağıma! ...', 'Çıkalı kaç yıl olmuşta,  Sana hiç şiir yazmıyor muşumda,  Efendim mektup zarfı bile yokmuş senin ismine ait;  Hadi bakalım şimdi ne söyleyec...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sitem-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Yıldızı', 'deniz-yildizi-ahmet-sever-1qmo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaz günü denizden çıkarmıştım da, 

Birkaç ay sonra sen görüpte; her zamanki gibi

Onu da istemiştin, 

Bense malum vermiştim.

Söylüyorsun, bir bacağını koparmışsın, 

Eh be güzelim seninki de iş hani

Ölü deniz yıldızı bacağını yeniler mi hiç?', 'Bir yaz günü denizden çıkarmıştım da,  Birkaç ay sonra sen görüpte; her zamanki gibi Onu da istemiştin,  Bense malum vermiştim. Söylüyorsun,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deniz-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamanın Amacı', 'yasamanin-amaci-ahmet-sever-ksyak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamanın amacı nedir diye hep soruyorum kendime, 

Birinin diğerine yaptığı kötülüğe şahit olmak mı? 

Yoksa benim gibi yaşamanın anlamını bilmeyen birinin 

                           bu anlamsız yaşamını devam ettirmek mi? 

Acaba diyorum, ben başka birinin gerçekten anlamlı 

                           yaşamının bir unsuru muyum da, farkında değilim? 

Belki de, ben mutsuz olsam bile bir başkasını

                           tüm yaşamı boyunca mutlu etmek mi? 

Anlamını bilmesem bile yaşıyorum işte! 

Yine de bilen varsa lütfen söylesin; belki

                           öğrenmeye vaktim olmaz.', 'Yaşamanın amacı nedir diye hep soruyorum kendime,  Birinin diğerine yaptığı kötülüğe şahit olmak mı?  Yoksa benim gibi yaşamanın anlamını bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sever']::text[], 8.5, '{"poet":"Ahmet Sever","poet_slug":"ahmet-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasamanin-amaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orman Haftası', 'orman-haftasi-ali-hallac-an1fv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ormanlar yurdumuzun yemyeşil bir tacıdır

Sele, kaymaya karşı en etkin ilacıdır

Birçok işte yardımcı ormanın ağacıdır

Ağaç dik, orman koru budur uygarlık yolu.

Binbir türlü eşyamız yapılıyor ağaçtan

Her iş böyle sürüyor nasıl giderse baştan

Yeşile beze yurdu, hayır gelmezki taştan

Ağaç dik, orman koru budur uygarlık yolu.

Gölgesinde insanlar, dalında kuş dinlenir

Tüm orman yangınları dikkat ile önlenir

Tek ağaç kesenin ocağı tütmez denir

Ağaç dik, orman koru budur uygarlık yolu.

Bu ağaç haftasında çocukların dileği

Çoban amca, olmasın havyanın yiyeceği

Fidanlar çocuk gibi, toplumun geleceği

Ağaç dik, ormanı koru budur uygarlık yolu.', 'Ormanlar yurdumuzun yemyeşil bir tacıdır Sele, kaymaya karşı en etkin ilacıdır Birçok işte yardımcı ormanın ağacıdır Ağaç dik, orman koru bu...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/orman-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Bayramı', 'agac-bayrami-ali-hallac-sp9ak', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaç dikme sevinci

Yükselmenin bilinci

Bu bilince erelim

Vatanı yeşertelim.

Ağaç dikmek de yetmez

Onu ekmekle bitmez

Yeşili korumalı

Ağacı yaşatmalı.

Her bir ağaç ekende

Toprak bayram ediyor

Temizleniyor hava

Kaymalar önleniyor.

Ağaç dikmek de yetmez

Onu ekmekle bitmez

Yeşili korumalı

Ağacı yaşatmalı.', 'Ağaç dikme sevinci Yükselmenin bilinci Bu bilince erelim Vatanı yeşertelim. Ağaç dikmek de yetmez Onu ekmekle bitmez Yeşili korumalı Ağacı y...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agac-bayrami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevre Haftası', 'cevre-haftasi-ali-hallac-lcrbj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çevreni hep temiz tut

Bataklıkları kurut

Sakın yere çöp atma

Yakışmaz uygarlığa.

Çevre sağlığı demek

İnsan sağlığı demek

Elbet sağlıklı olur

Buna gösteren emek.

Çöpleri artıkları

Yalnız çöpe atmalı

Yurttaşlık bilinciyle

Çevreyi parlatmalı, 

Çevre sağlığı demek

İnsan sağlığı demek

Elbet sağlıklı olur

Buna gösteren emek.', 'Çevreni hep temiz tut Bataklıkları kurut Sakın yere çöp atma Yakışmaz uygarlığa. Çevre sağlığı demek İnsan sağlığı demek Elbet sağlıklı olur...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cevre-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılay Haftası', 'kizilay-haftasi-ali-hallac-d03gu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaralar sarar eli bir anne sevgisiyle

Hepimiz tanırız Kızılay''lı bayrağı ile

Kucağını açmaktadır kırkkat düşmana bile

İnsanlık onurumuz, İnsancıl Kızılay''ımız.

Savaşta, barışta, her ulusal felakette

Örgütü, kolları var tüm yurtta, her bir kentte

Hemen koşar yetişir kim varsa başı dertte

Ona muhtaç olanın inancı Kızılay''ımız.

Dil, din, ırk ayrımı gözetmez hizmetinde

Hepsini dağıtmakta ne var ise elinde

Kızılay''a üye ol, bağış yap sen de

En güçlü ulusal dernek olsun Kızılay''ımız.

Kızılay güçlü ise muhtaç olan el açmaz

Vatanı, ulusu seven asla yardımdan kaçmaz

El verelim çocuklar, güçlensin alayımız

Felaketin düşmanı olsun Kızılay''ımız.', 'Yaralar sarar eli bir anne sevgisiyle Hepimiz tanırız Kızılay''lı bayrağı ile Kucağını açmaktadır kırkkat düşmana bile İnsanlık onurumuz, İns...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kizilay-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aile Planlaması Haftası', 'aile-planlamasi-haftasi-ali-hallac-a5hp5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aile toplumların en sağlam temelidir

Çocuklar ailenin yarını, emelidir

Planı, proğramı tüm toplum bilmelidir

Bizler de öğrenelim aile planlamasını.

Sağlıklı aileler yurdu teşkil etmeli

Herbir aileye bir iki çocuk yetmeli

Aile Planlaması kurslarına gitmeli

Bizler de öğrenelim aile planlamasını.

Ayrılmaz bir bütündür ruh ve beder sağlığı

Dengesiz beslenme tehdit eder insanlığı

Sağlam bir toplum ile kurarız uygarlığı

Bizler de öğrenelim aile planlamasını.

Evlerde işbölümü en iyi nasıl olur

Her uygar gereksinme tasarrufla hallolur

Yurdun tüm kentlerinde her isteyen kaydolur

Bizler de öğrenelim aile planlamasını.', 'Aile toplumların en sağlam temelidir Çocuklar ailenin yarını, emelidir Planı, proğramı tüm toplum bilmelidir Bizler de öğrenelim aile planla...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aile-planlamasi-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okulum (ilköğretim Haftası)', 'okulum-ilkogretim-haftasi-ali-hallac-b2dy0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabah erken kalkarım

Kahvaltımı yaparım

Büyük bir sevinç ile

Okuluma koşarım.

Okulum okulum

Benim güzel okulum

Arkadaşlarım ile

Pek de mutlu olurum.

Okumayı, yazmayı

Düşünmeyi, konuşmayı

Okulda öğrenirim

Uygarca davranmayı.

Okulum, okulum

Benim güzel okulum

Canım öğretmenlerim

Bana gösterir yolum.', 'Sabah erken kalkarım Kahvaltımı yaparım Büyük bir sevinç ile Okuluma koşarım. Okulum okulum Benim güzel okulum Arkadaşlarım ile Pek de mutlu...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/okulum-ilkogretim-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trafik Haftası', 'trafik-haftasi-ali-hallac-3ud9v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürümekteyken yolda

Sakın ha dalgın olma

Karşıya geçer iken

Ezilebilirsin sonra.

Dikkat ile önlenir

Kazaların pek çoğu

Yaya geçidi kullan

Kontrol et sağı solu.

Trafik kuralları

Korumak için bizi

Herkesi uyaralım

Kendimiz de uyalım.', 'Yürümekteyken yolda Sakın ha dalgın olma Karşıya geçer iken Ezilebilirsin sonra. Dikkat ile önlenir Kazaların pek çoğu Yaya geçidi kullan Ko...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/trafik-haftasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaya Davet', 'caya-davet-ali-hallac-uj7uo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gelin çayıma ortak olun buğulu

bugün veya ne zaman olursa

yudumladıkça koyulaştıralım dostluğu.

değme gitsin, 

bir de gözlerimiz birbirini bulursa.

asaletinizden izin alıp bu akşam

bu akşam hanımefendi veya ne gün isterseniz

buluşalım Hayyam''ın bir şiirinde.

şöyle birer demli çay, ne dersiniz

bakın bu son fasıl Neyzen''in neyinde

acele etmeyin, hava kararmadan gidersiniz.

bu son bardak, belki de dolmaz

gözlerinizi bırakın giderken, koyu çay renginde

belki bir daha gelirsiniz, belli olmaz

giderken gözlerinizi bırakın

hadi utanmayın, nezaketiniz kalsın yerinde

ne hoş olur yokluğunuzda gözlerinizi içmek

sizin ayıp bildiğiniz hisler içinde.', 'gelin çayıma ortak olun buğulu bugün veya ne zaman olursa yudumladıkça koyulaştıralım dostluğu. değme gitsin,  bir de gözlerimiz birbirini b...', ARRAY['Türk Edebiyatı','Şiir','Ali Hallaç']::text[], 8.5, '{"poet":"Ali Hallaç","poet_slug":"ali-hallac","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/caya-davet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Şaşıyorum', 'kendime-sasiyorum-beyhan-oral-bayram-owcy4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sabah sigaralarımın ucundasın

Yine nefes nefes tüketiyorum seni

Yalnızlığımı dolduracak bir zerre ararken

İçimdeki boşluğun dolmayacağı düşüncesi hakim

Ne için çırpınıyorum

Kendim için mi senin için mi

Şaibeli sorular arasında cevapsız dolaşıyorum

Kah bir ahize oluyorum

Kah kalem değmemiş bir kağıt

Her dakika ölüp her dakika doğuyorum senin için

Ucu yakalanmamış zor günlerde

Bir damla yağmur diye yalvarıyorum

Kuruyorum

Kuruyorsun

Tamamlayamıyorum

Tamamlanmıyorsun

Bak belimde ince bir sızı ile 

Doğrulmaya çalışıyorum

Sigara altı bir lokma ekmek arıyorum

Acıkıp susuyorum

Bak hala nasıl da yaşıyorum

Kendime şaşıyorum....', 'Yine sabah sigaralarımın ucundasın Yine nefes nefes tüketiyorum seni Yalnızlığımı dolduracak bir zerre ararken İçimdeki boşluğun dolmayacağı...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kendime-sasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-beyhan-oral-bayram-prjhz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Orada mısın? 

Hayır yoksun

Belki de varsın ama sesin yok 

Yokluğun sessizlik 

Yokluğun sensizlik

Ama alışırım ite kaka saklanmalara

Alışırım varlık içinde yokluğuna

Alışırım umursamamaya.

Alıştım bile hatta.

Yok yada var 

Var yada yok

Yokluk yoksulluk

Varlık yoksulluk

Yoksulluğun içinde umutsuzluk

Umutsuzluğun içinde yorgunluk

Yorgunluğun içinde yolculuk

Yolculuk içinde sensizsizlik

Sensizsizlik içinde kimsesizlik

Kimsesizlik içinde bir çığlık

Çığlığın içinde ben

Çığlığın içinde sen

HA BEN, HA SEN

HAYIR HA SEN, HA SEN.....', 'Orada mısın?  Hayır yoksun Belki de varsın ama sesin yok  Yokluğun sessizlik  Yokluğun sensizlik Ama alışırım ite kaka saklanmalara Alışırım...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/saklambac-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle!', 'oyle-beyhan-oral-bayram-3ynpq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canım

Bu mektubu sana yazıyorum

Kalemimden kan damlıyor 

Yüreğim parçalanmış

Kağıdım ala boyanmış

Burada sensizliğe yeni yeni alışmaya çalışırken

Suskunluğum son haddinde

Yoksulluğum yoksul senden

Saklanıyorum yokluğunun  menzilinden

Senin siperlerinde uyuyorum

Şarjörünün  boşaltılmış kovanı gibiyim burada

Nerede olduğumu bulmak zor

Ha buradayım

Ha orada

Kah sıkılırım

Kah yorulurum

Çöker kalırım zamanın içinde

Kolumdan tutacak bir sen olsa derim

Ah bir yanımda olsa derim

Gitme diyemediklerime ağlamamak için 

Hıçkırığı düğümleyip boğazıma

Bir sigara bir sigara daha

Sonra

Sonrası ne anlamsız ne  tuhaf

Öylesine yaşamak gibi sonrası

Öylesine hasret çekmek

Belki de öylesine bir öyle işte

Öyle....', 'Canım Bu mektubu sana yazıyorum Kalemimden kan damlıyor  Yüreğim parçalanmış Kağıdım ala boyanmış Burada sensizliğe yeni yeni alışmaya çalış...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/oyle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aŞk kIŞIn nAPAr', 'ask-kisin-napar-hasan-yasar-zuvkd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'AŞKışıN''APAR 

n''aparızaşkı 

şınerelerdel 

veriresimler

defkarlardamı 

lıcakentlerde 

midirüyalarda

mıdırızanlatsa 

naşkışınereler 

dedirızaşkışın''apar... 

ŞİİRİN ÇÖZÜMLEMESİ

napar rıza 

aşk kışın 

nerelerde 

elverir resimlerde

efkarlarda mı 

ılıcak kentlerde midir 

rüyalarda mıdır rıza 

anlatsana 

aşk kışın 

nerelerdedir rıza aşk 

kışın napar...', 'AŞKışıN''APAR  n''aparızaşkı  şınerelerdel  veriresimler defkarlardamı  lıcakentlerde  midirüyalarda mıdırızanlatsa  naşkışınereler  dedirızaş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-kisin-napar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Öleceğim', 'seninle-olecegim-beyhan-oral-bayram-jjjko', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben 

Senin beni sevmenle büyüdüm

Ellerimi tutuşunla kanım ısındı

Gözlerimi dünyaya bana bakışınla açtım

Bedenimin en sığ köşelerindeki çırpınışı seninle hissettim

Ben 

Senin sınıf arkadaşım oluşunu bile sevmiştim

Bir gölge gibi önümde arkamda gezmene alışkınım

Ben

Okul koridorlarında kaçamak sarılışlarınla

Sınıf köşesindeki acemi öpüşlerimizle

Öğle araları birbirimize yedirdiğimiz köfte ekmeklerle büyüdüm

Her günün sabahını zor  ettiğim günlerde

Yolda karşılaşırım ümidiyle okula giderdim

Ben

Seninle yolda beraber yürümenin tadına vararak

Pazar günleri

Yağmurda soğukta da olsa

Kollarının arasında ısınarak büyüdüm

Derslerden kaçarak kantinde oturduğumuz günlerde

Seni severek büyüdüm

Her ayın 13 ünde getirdiğin güllerle

Senin nefesinle ilginle 

Güler yüzün tatlı dilinle büyüdüm

Ben

13 Kasım 1992 den bugüne kadar senin sevginle büyüdüm

Sonra

Çocukluğuma geri dönmek istediğim günler geldi

Kollarının arasında tekrar büyümeyi hayal ettiğim günler

K_D yollarından hasreti çiğneyerek geçtik zaman zaman

Ama yetmedi.

Arkasından öldüren bir hasret geldi ki sorma gitsin

Artık büyümüştüm.

Kendi ayaklarımın üstünde durmaya çalıştığım

Ara sıra tökezlenip

Ayakta durmak için güçlü olmayı öğrendiğim yıllar geçirdim.

Sensiz yıllar, zor yıllar.

Bazen geleceği hayal ederek

Çoğu zamanda geçmişi ve seni düşünerek geçirdiğim yıllardı bunlar.

Üç yıl...

Dile kolay gelir söylemesi.

Avunduğum

Geçmişten kalan, gözleri o pırıltıyla yanan resimler

Ve bir de, 

Sevgiyle işlenen mektuplardı.

Her gece tuzlu göz kapaklarımın önünde hayalin belirir

Ve bana seni seviyorum derdi.

Uykuları unutmuştum.

Yanan göz bebeklerim sensiz kapanmak bilmez olmuştu.

Alışırsın derdi arkadaşlarım.

Ama alışılmıyormuş be canım.

Ben seninle büyümüştüm ama sensiz yürüdüm.

Yürümeyi de unutmadan 

Dön gel, dön gel be gülüm.

Karlı puslu soğuk havalarda, 

Demirci’den kalkan Halıkent arabalarına bakardım

Çekip gitmek isterdim buralardan.

Kimsenin olmadığı, hasretin olmadığı, 

Yalnızca senin olduğun yerlere gitmek ve hiç dönmemek.

Yaylada kurulmuş, 

Soğuğu donduran, sıcağı kavuran, 

Açık bir hapishaneydi yaşadığım yer.

Hasretinin canıma tak ettiği günlerde, 

Kaçıp yanına gelmek isterdim.

Gidip gelmeler başladıysa da, 

Üç dört günlük açık görüşlerdi bunlar.

Arkasından yine karanlık hücreme geri dönerdim.

Hep af çıksın diye beklerdim.

Ama burada af yoktu.

En erken dört yıl sonra azat olacaktım.

Elimi ayağımı bağlayan geleceğimdi.

Öyle böyle geçirdim burada günleri.

Ama ne geçmek! 

Yaşadım mı yaşamadım mı bende bilmiyorum.

Bazen küçük sevinçlerle dudaklarım tebessüm ederdi, 

Kahkahalarımın arasında buruk bir sancı belirirdi.

Anamın dediği gibi: 

‘hey gidi günler hey, neler çektirdi be hayat’

Ben hayatın çilesi içinde

Seninle büyüdüm, sensiz yürüdüm canım.

Ama her şeye rağmen

Seni can gibi sevdim

Yürekten içten, 

Martıların özgürlüğü sevdiği gibi sevdim.

Ben seni sevmeyi sevdim.

Eğitim caddesinde hep seninle yürüdüm, 

Yemekhanede yediğim bir lokma ekmek seninle geçti boğazımdan.

Gece yarılarında

Yurt bahçesindeki tipide, 

Savrulan kar örtüsündeki kaybolan ayak izlerimde, 

Geride bıraktığım ve yeniden başladığım sendin

Sen her şeydin her şeyimdin.

Seni hiç kendimden ayrı düşünmedim ki.

Çünkü sen bendin.

Her noktanı, her zerreni bildim.

Her şeyini sevdim.

Şimdi hasretin son fırtını çekerken, 

Kollarının arasında olmayı istediğim bir an, 

Çıkıp geleceğim.

Ve 

Dudaklarının arasında kaybolurken, 

Seni sevdiğimi söyleyeceğim.

Seninle büyüdüm, 

Sensiz yürüdüm, 

Ama seninle öleceğim canım.

SENİNLE ÖLECEĞİM.....', 'Ben  Senin beni sevmenle büyüdüm Ellerimi tutuşunla kanım ısındı Gözlerimi dünyaya bana bakışınla açtım Bedenimin en sığ köşelerindeki çırpı...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/seninle-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişkilerim', 'celiskilerim-riza-aslan-b860t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çelişkilerime 

göz göre göre 

bitişime rağmen 

herşeye baştan başlamam lazım 

tükenen benliğime 

kaybolan yarınlarıma inat 

yeni bir ben lazım 

geçmeyeceği düşünülen 

günlerin ardından bakıp 

nasılda geçti günler demeyen 

yeni bir ben lazım 

yeni bir ben lazım 

yüreğindeki tükenişlere 

içinde bitmek bilmeyen 

çelişkilere inat 

bitmeyen 

yenibir ben lazım 

tükenişlerin, çelişkilerin 

akıp gittiği 

geride izlerinin kalmadığı 

bir ben 

yeni bir ben 

09 - 11 - 2002 

Bergama     /   İzmir

Rıza Aslan', 'çelişkilerime  göz göre göre  bitişime rağmen  herşeye baştan başlamam lazım  tükenen benliğime  kaybolan yarınlarıma inat  yeni bir ben laz...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/celiskilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-asik-sefai-cplx8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün seni görende sinem sızladı, 

Damarım çekildi dilim lal oldu, 

Kara kaşın başkaldırıp bakanda, 

Aklım koydu gitti fikrim kül oldu.

Salınır da dağlar taşlar salınır, 

Deli çaylar gibi gönlüm bulanır, 

Seni görmeyinc ebeynim dolanır, 

Bir gün derler bu garip de del oldu.

Kurbanın olayım kurtaran yok mu, 

İki kelam etmek garibe çok mu, 

Bakışın kılıç mı gülüşün ok mu, 

Söküldü ciğerim her yan al oldu.

Güzel seni bir kenara koymayım, 

Hayalini syrettikçe doymayım, 

Yüzünü görüyüm sesin duymayım, 

Kim ne bilsin SEFAİ''e hal oldu.', 'Dün seni görende sinem sızladı,  Damarım çekildi dilim lal oldu,  Kara kaşın başkaldırıp bakanda,  Aklım koydu gitti fikrim kül oldu. Salını...', ARRAY['Türk Edebiyatı','Şiir','Aşık Sefai']::text[], 8.5, '{"poet":"Aşık Sefai","poet_slug":"asik-sefai","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzel-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Çekenlere Şiir', 'aci-cekenlere-siir-harun-resit-turgut-kqp4k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acı Bahar

		

şurada burada sıkılmış limon kesikleri 

paslanmaya bırakılmış demir çubuklar 

tertemiz kaynaklara atıksu tarifesi 

taze sürgünlerin ince boyunlarında ağır kementler 

henüz sıcaklığı soğumamış körpe cesetler 

karanlıklar ortasında bir ışık adası gibi 

talancıların gözünden nasılsa kaçmış çimenler 

birkaç tomurcuk üç-beş yeşil yaprak 

ıslak bir kağıt gibi yırtıp atmış 

kentin dokusunu acımasız kasırgalar 

arıtmıyor sabun çıkartmıyor sular 

giysilerden yalnızlığın kokusunu 

aşk mevsimi değil miydi bahar 

elele tutuşmaktan korkan ürkek ceylanlar 

hani nerede eşlerine kur yapan kumrular 

kuş cıvıltılarına hasret kulaklar 

denizler denli derin içezikliği 

geleceksen sekizinci günde gel sevgilim 

burada haftanın yedi gününde de 

aşka geçit vermiyor yağmurlar 

yalnızca bir ad yaraşabilir bu mevsime: “acı bahar”', 'Acı Bahar 		 şurada burada sıkılmış limon kesikleri  paslanmaya bırakılmış demir çubuklar  tertemiz kaynaklara atıksu tarifesi  taze sürgünl...', ARRAY['Türk Edebiyatı','Şiir','Harun Reşit Turgut']::text[], 8.5, '{"poet":"Harun Reşit Turgut","poet_slug":"harun-resit-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aci-cekenlere-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşerin orta yerinde', 'mahserin-orta-yerinde-salih-ozalasan-5vxud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana demiştim sevme yanarsın ateşlerde

Yıldızları sayarsın karanlık gecelerde

Çığlıkların olur geceye perde

Hesabını benden sorarsın sonra mahşerde

Gözlerine yaşlar dolar kalbin hep serde

Yüreğinde dinmez sızı, çare yok hekimde

Dualar unutulur hep o isim dilinde

Sonra yakama yapışırsın mahşerin orta yerinde

Saçların ağarır siyah kalmaz bir tek telinde

Sararmış, bir köşesi yırtık resim elinde

Sayfa sayfa mektuplar yığılmış önünde

Cehennem ateşi olur mahşerin orta yerinde

Yanarız demiştim, Yanarız biz ikimiz seninle

Kaderi yenemeyiz hep acı çektim ben ömrümce

Kader bana düşman aman vermez ben sevince

Biz ancak kavuşuruz demiştim mahşerde dirilince

Söz dinletemedim geçmiyor söz insan sevince

Bir umut bir ışık yanıyor yüreklerde ince ince

Tanrı şahit yeminim var sensiz ölünce

Kaderimden hesap soracağım mahşerin orta yerinde

Y.Tar 10-11-2002 Saat 7,25', 'Sana demiştim sevme yanarsın ateşlerde Yıldızları sayarsın karanlık gecelerde Çığlıkların olur geceye perde Hesabını benden sorarsın sonra m...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mahserin-orta-yerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz bekliyorum', 'yaz-bekliyorum-zubeyir-sasmaz-pnsaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YAZ BEKLİYORUM - Yaz....  Bekliyorum......

Kısacık yaz istersen, yorulmanı istemiyorum

Mutlu olduğunu, hayat bulduğunu

nereleri gezip, tozduğunu, 

iki çocuğunun olduğunu, 

adlarının  güzel olduğunu

kim bilir belki de özgür ve barış koyduğunu

Kısacık yaz istersen, yorulmanı istemiyorum

kısacık ta olsa bir kart atsan diyorum

durmadan  postacının yolunu gözlüyorum.

kendini anlat, neredesin, kiminlesin merak ediyorum.

Ne yapıyorsun, aç mısın, tok musun.

açları, fakirleri doyuruyor musun? 

Sokakta kalanlar için ağlıyor musun? 

Kim atmış, neden düşmüş köprü altına düşünüyor musun? 

Kısacık yaz istersen, yorulmanı istemiyorum

İşini kurdun mu, kendine mi çalışıyorsun, 

yoksa başkasının kapısında kul musun? 

O ekmek elden, su gölden günlerini arıyor musun? 

Kısacık yaz istersen, yorulmanı istemiyorum

Mutlu olduğunu, hayat bulduğunu

gezip, tozduğunu,

Yaz...   bekliyorum........

Merak ediyorum,  kimin için çalışıyorsun.

Vatana mı, hırsa mı, paraya mı çalışıyorsun.

Laboratuarda mı, yoksa kahvelerde mi sabahlıyorsun.? 

Seni görmediğim zamanlarda ne yapıyorsun.

Çok istiyordun,  ehliyetini aldın mı? .

Kaza yapıp hiç cana kıydın mı? .

siyasetle mi uğraşıyorsun? 

Köy, köy dağ tepe mi dolaşıyorsun.? 

İnsanlara umut mu dağıtıyorsun.? 

Dediklerini bir bir yapıyor musun? 

Yoksa yapamayınca vaadlerini; 

''Kaynağını  sordunuz mu? '' deyip onları kandırıyor musun? 

Tilki gibi hayatını kurnazlıkla mı kazanıyorsun? 

Kurtlar gibi leş mi yiyorsun

Bey atı gibi sadece süvariyi mi taşıyorsun? 

Arı gibi başkasını balla mı besliyorsun.

Güvercin gibi barış ve özgürlüğü mü simgeliyorsun

Karınca gibi emeğinle hem kendine, 

 hem topluma mı çalışıyorsun.

Yaz...   bekliyorum........', 'YAZ BEKLİYORUM - Yaz....  Bekliyorum...... Kısacık yaz istersen, yorulmanı istemiyorum Mutlu olduğunu, hayat bulduğunu nereleri gezip, tozdu...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/yaz-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ülkede yaşamak', 'bir-ulkede-yasamak-zubeyir-sasmaz-qi25e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Araçların egzosundan  kapkara dumanların çıkmadığı, 

Her araç geçişinde ortalığın toza dumana karışmadığı, 

    Bakımsız araçların, zararlı zehirli gazlar saçmadığı

    Gelişi güzel, klaksona basıp, gürültüler çıkarmadığı

Canının istediği yerde durup kazaya davetiye çıkarmadığı

Koca koca kamyonların, küçücük  otomobilleri sollamadığı

    Plakaların, Ucundan azıcık, bandı ile kapatılmadığı

    Araçların İçini göstermeyen camlarla karartılmadığı

Kaza ile adam  öldürenin yanına kar kalmadığı

Üç günlük hapisle ortalığa yeniden salınmadığı

     Motorlu araçları, seyyar Azrail lerin kullanmadığı

     Kazalara sebep olanların rüşvetle bırakılmadığı

Bir ülkede yaşamak istiyorum.

     Ben bu ülkeyi çok seviyor, burada yaşamak istiyorum.

     Dünyaya bir kere geldik, bir daha gelir miyiz, bilmiyorum.

Ülkemi hiç mi hiç  değiştirmek istemiyorum.

Ama Dünya ya bir daha gelmeyeceğiz diyorum.

     Böyle, düzensiz, güvensiz bir ülkede de yaşamak istemiyorum

     Allah''tan bizlere akıl vermesini diliyorum.

Atamın gösterdiği, muassır medeniyet seviyesine ulaşmak istiyorum.

Düzeni bozanları, güvensizliği yaratanları gayet iyi biliyorum

Onları yenemiyorum, ama bileklerini de öpmek istemiyorum.', 'Araçların egzosundan  kapkara dumanların çıkmadığı,  Her araç geçişinde ortalığın toza dumana karışmadığı,      Bakımsız araçların, zararlı ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-ulkede-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ülkede Yaşamak-2', 'bir-ulkede-yasamak-2-zubeyir-sasmaz-fyr3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğimi haykırabileceğim

Sevmediğimi açıklayabileceğim

bir ülkede yaşamak istiyorum.

Kimselerden çekinmeden, açıkça konuşabileceğim

Geleceğime korkmadan güvenle bakabileceğim

Yarın  ne olacağım! .

Ya olursa  ne yaparım diye kaygılanmayacağım.

bir ülkede yaşamak istiyorum.

Doğrularını  alkışlayacağım

Yanlışlıklarına halkımla beraber karşı çıkacağım

bir ülkede yaşamak istiyorum.

Kimseleri rahatsız etmeden, özgürce yaşayacağım.

Kuğu gölünü dinlediğimde, yadırganmayacağım.

bir ülkede yaşamak istiyorum.

Arkamı duvara vermek ihtiyacı duymayacağım

kapıyı, pencereyi açtığımda temiz hava alacağım

bir ülkede yaşamak istiyorum.

Horlanmadan, insan gibi çalışacağım.

Geleceğimi amirin dudakları arasında sıkıştırmayacağım

İhtiyacım olanları, zorlanmadan alacağım

Yıl boyunca çalışıp, bir ay tatil yapacağım

İnsan gibi çalışıp, İnsan gibi yaşayacağım, 

Bir ülkede yaşamak istiyorum.', 'Sevdiğimi haykırabileceğim Sevmediğimi açıklayabileceğim bir ülkede yaşamak istiyorum. Kimselerden çekinmeden, açıkça konuşabileceğim Gelece...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-ulkede-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtiyar saymak', 'bahtiyar-saymak-zubeyir-sasmaz-wq4xc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BAHTİYAR

Bahtiyar saymak için kendimi

                                Ne han isterdim, ne de hamam

Başımı sokacak, küçücük bir ocak.

                              anlayışlı bir eş, bir de  yavrucak

Çok şey istemezdim bahtiyar olmak için,        ancak.

Bir düzen isterdim, kimseler

                                 gelecekten kaygı duymayacak.

Yaşadığım yerlerde, herkes birbirine saygı duyacak

Her yer vatan için çalışan dürüstlerle dolup taşacak

Yaşadığım yerlerde;     Hak ve adalet tek güç olacak.

İşte ben böyle bahtiyar olurdum ancak', 'BAHTİYAR Bahtiyar saymak için kendimi                                 Ne han isterdim, ne de hamam Başımı sokacak, küçücük bir ocak.        ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahtiyar-saymak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdesin', 'hayalimdesin-emrullah-erdinc-teyly', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman seni dusunurken 

siir yazmak istiyorum

Bulabilecegim birkac kelimenin 

sigabilecegi bir kagit, 

ve kullanilmaz diye atilan 

bir kac misralik bir kalem 

Hayalimde cizemedigim 

senin yuzunumu cizmeye calissam, 

yoksa sana söyliyemediklerimi? ? ? 

Ama, yorgunlugumunda birakmis oldugu 

en derin acikli hatiralar derinliginde 

Artik uzulmuyorumda resimlere cizdim 

hayalimdeki gözleri artik uzulmuyorumda, 

Cunki hayalimde yasatiyorum seni? ? 

Icimde bir volkan patlasaydi 

bu kadar parcalamazdi vucudumu, 

Hayali her yere cizdim seni 

her yerden bakiyorsun huzur duyuyorum.

Cunki  hayalimde 

inanamiyacagin kadar seviyorum seni? ? ?', 'Kimi zaman seni dusunurken  siir yazmak istiyorum Bulabilecegim birkac kelimenin  sigabilecegi bir kagit,  ve kullanilmaz diye atilan  bir k...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayalimdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13. Şiir', '13-siir-bahadir-atay-da2ui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yazdığım 13. şiir oluyor, 

En iyisi hiç yazmayayım, 

Siz de okumayın sakın.

Haksızlık etmek istemezdim ama 13 e, 

O da uğursuz olmasaymış öyle.', 'Bu yazdığım 13. şiir oluyor,  En iyisi hiç yazmayayım,  Siz de okumayın sakın. Haksızlık etmek istemezdim ama 13 e,  O da uğursuz olmasaymış...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/13-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş II', 'savas-ii-bahadir-atay-65ihx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uçaklara bileti olanlar binemedi, 

Uçaklar biletleri getiriyordu insanlara, 

Birinci sınıf, hem de en hızlısından

Bu dünyadan, öteki dünyaya.

Toprak kazananlar bile gülemedi, 

Topraklarını almışlardı aslında.

Yazabilirdi isimleri belki, 

Eğer olsaydı mezar taşlarında.

İnsanları öldürenler üzülmedi.

Zafer çığlıkları vardı meydanlarda, 

Ama zafer getirmiyordu oğullarını, 

Onları savaşta kaybetmiş bir anaya.

Ağıt yakanlar ise gülemedi, 

Kin, nefret ve intikam vardı akıllarda, 

Sağ kalan çocuklar şaşkın, 

Ölülerin ise vakti yoktu şaşırmaya.', 'Uçaklara bileti olanlar binemedi,  Uçaklar biletleri getiriyordu insanlara,  Birinci sınıf, hem de en hızlısından Bu dünyadan, öteki dünyaya...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/savas-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-omer-faruk-cakir-wtsmn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tasasız koymak başımı yastığa,

Bilmeden gideceğini,

Ya da düşünmeden geleceği,

Hüzünle değil, yüzünle uyanmak

Ve Şükretmek Allah’a

Bugün de yanımdasın,

Merhaba', 'Tasasız koymak başımı yastığa, Bilmeden gideceğini, Ya da düşünmeden geleceği, Hüzünle değil, yüzünle uyanmak Ve Şükretmek Allah’a Bugün de ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/merhaba-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Bir Şiir', 'i-yi-bir-siir-bahadir-atay-s2y15', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İyi bir şiir yazmak için, 

İyi bir kalem, 

İyi bir silgi, 

Ve iyi bir kağıt gerekir.

Ne eksiği ne fazlası, 

Gerisi alın yazısı.', 'İyi bir şiir yazmak için,  İyi bir kalem,  İyi bir silgi,  Ve iyi bir kağıt gerekir. Ne eksiği ne fazlası,  Gerisi alın yazısı....', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iyi-bir-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fındık', 'findik-bahadir-atay-xck7g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçen aklıma geldi, 

Şu fındığı mı daha çok seviyorum

Yoksa seni mi? 

Fındık da fındık hani, 

Olgun, iri, lezzetli, 

Biliyorsun fındığı ne kadar sevdiğimi.

Sense benim en büyük derdim, 

En büyük üzüntüm, 

Biricik kederim.

Sen olmazsan yaşayamam belki

Ama sende neden ağrıtyorsun başımı

Niçin mutlu değilsin? 

Biliyorsun senin için ne acılar çektiğimi.

Neden rahat durmuyorsun be dişim? 

Ben fındık yiyemeyecek miyim?', 'Geçen aklıma geldi,  Şu fındığı mı daha çok seviyorum Yoksa seni mi?  Fındık da fındık hani,  Olgun, iri, lezzetli,  Biliyorsun fındığı ne k...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/findik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ferhat, Kerem, Mecnun Vesaire Vesaire', 'ferhat-kerem-mecnun-vesaire-vesaire-bahadir-atay-ijj8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şirin, 

Aslı, 

Leyla, 

Vesaire, 

Vesaire, 

Ve susmak düşer artık şaire.', 'Şirin,  Aslı,  Leyla,  Vesaire,  Vesaire,  Ve susmak düşer artık şaire....', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ferhat-kerem-mecnun-vesaire-vesaire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzenli Aşk', 'duzenli-ask-bahadir-atay-c34no', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düzenli aşk nasıl mı olur, 

İşte yazıyorum buraya.

Aşkın bir düzeni olurdu, 

Aslı ile Ferhat 

Kerem ile Leyla

Mecnun ile Şirin

Olsalardı eğer bu sırada.

İnanmazsanız bakın, 

Hepsi alfabetik sırada.

Bunu da bir kenara yazın, 

Başka bir düzeni yoktur aşkın.', 'Düzenli aşk nasıl mı olur,  İşte yazıyorum buraya. Aşkın bir düzeni olurdu,  Aslı ile Ferhat  Kerem ile Leyla Mecnun ile Şirin Olsalardı eğe...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/duzenli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(U) mutlu', 'u-mutlu-bahadir-atay-20vba', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mutluyum mutlu olmasına, 

Ama sensiz olmuyor ki.

Dağları deleceğim belki, 

Belki çölleri aşacağım, 

Ama bir U harfim eksik, 

Sende onu tamamlarsan, 

Ben umutlu olacağım.', 'Mutluyum mutlu olmasına,  Ama sensiz olmuyor ki. Dağları deleceğim belki,  Belki çölleri aşacağım,  Ama bir U harfim eksik,  Sende onu tamam...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/u-mutlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Gecede Ölüm', 'karanlik-gecede-olum-bahadir-atay-9vefi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece ıssız ve karanlık, 

Ay ölüm saçıyor, 

Çığlıklar uçuşuyor etrafta, 

Ama duyabilen yok, 

Herkes bağırıyor ölümüne, 

Kimse gözlerini açamıyor.

Sadece dilsizler susuyor, 

Sadece körler görüyor, 

Sadece sağırlar duyuyor, 

Sadece ölüler yaşıyor o diyarda.

Korku biricik umut, 

Korkmasalar ölmekten, 

Yaşamayı ve nefes almayı

Kalblerinin atışını, 

Unuturlar, bir daha da ancak, 

Öldüklerinde hatırlayacaklar.

Artık hayat bitiyor, 

Artık yaşam duruyor, 

Artık ölüm yaşıyor o diyarda.

Hiç ay batmayacak, 

Hiç güneş doğmayacak, 

Hiç sabah olmayacak, 

Ölüm bir başka olacak o diyarda.', 'Gece ıssız ve karanlık,  Ay ölüm saçıyor,  Çığlıklar uçuşuyor etrafta,  Ama duyabilen yok,  Herkes bağırıyor ölümüne,  Kimse gözlerini açamı...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/karanlik-gecede-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim İstanbul', 'sevgilim-i-stanbul-deral-baran-h2yuc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur, 

Bir avuç bulutla

Şehri yıkarken, 

Ellerime bir kelebek kondu

İstanbul kadar 

Aziz...

Gökyüzü genişledi, 

Yalnızlığım zamansızdı.

Bin yılların 

Özlemini içtim 

Terk edilmiş kaldırımlarda.

İstanbul kadar 

Şefkatli...

Yağmur, 

Günahlarımı yıkarken 

Çocukça bir gülümsemeyle 

Dirildi ruhum.

İstanbul kadar 

Nazlı...

İstanbul! 

Özlemini 

Şefkatini 

Narin ellerini 

Esirgeme benden.

İstanbul, 

Ben seni karşılıksız sevdim 

Ve 

Seni İstanbul kadar sevdim...

Deral 

10 Kasım 2002', 'Yağmur,  Bir avuç bulutla Şehri yıkarken,  Ellerime bir kelebek kondu İstanbul kadar  Aziz... Gökyüzü genişledi,  Yalnızlığım zamansızdı. Bi...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevgilim-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-hasan-huseyin-ozay-cdc2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgi nedir nasıl bir duygudur bilirmisin sen

Gelecek diye hergün yolunu gözlemek 

Gelmeyince içip kahretmek hayatına küsmek 

Seviyorum sözüne kanıp terk edilmek nedir Bilirmisin

Yalnızlığın acısını bilirmisin sen

Seviyorum sözüne kanıp terk edilmeyi

Bilirmisin herkes gülerken ağlamayı

Bilirmisin sevdiğinden ayrı yalnız yaşamayı

Unutmak istermisin o çok sevdiğin zalimi

Kapısına kırmızı gül bırakıp seviyorum dediğini

Bilirmisin büyük aşkın biteceğini

bilirmisin ayrılığın bıraktığı acıyı bilirmisin söyle', 'Sevgi nedir nasıl bir duygudur bilirmisin sen Gelecek diye hergün yolunu gözlemek  Gelmeyince içip kahretmek hayatına küsmek  Seviyorum sözü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özay']::text[], 8.5, '{"poet":"Hasan Hüseyin Özay","poet_slug":"hasan-huseyin-ozay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilirmisin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki Bu Gün...', 'belki-bu-gun-serra-timur-h57g9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarın dedğin  bu gün işte.

Uzat elini  çok geç olmadan.

Sevgiyi kucaklamak  için belki bir nefeslik  ömrün var.

Güneşi  doldurmak için yüreğine 

Belki  yarın dediğin bu günün var.

Bir  kısa seferdi  seferisiydik yaşamın.

Gördüklerimiz  yaşadıklraımız ve yaşayacaklraımız.

Üç perdeli bir  oyun  hepsi.

Güzel bir an kadar kısa 

Bir sancının geçmeyen  saniyesi kadar  uzun.

Ne duruyorsun o halde

İşte yarın  dediğin an

Bir bak,  küçük bebeğinin yüzündeki ergenlik sivilcesine.

Bir bak, endanlı genç kıza

Hani senin, karabaş saçlı  bazen örüklü

Cırtlak  sesle  bağıran  komşu kızın vardıya.

İşte o endamlı kız.

Hadi durma, sarıl telefona

Gururun  kabül etmesede,  ellerin titresede

Sesin çok değişmiş olsada

Söyle  rüyalrının  prensesine

İçinde hala sakladığın  sözcüğü.

Unutma  yarın  bu gündür.

Bir akşam vakti   yıldızlara  bir dost gibi  bakmak için

Belki son şansın.

Belki  son dolunaydır bu gece

Ve belki yarın dedğin

Oyunun son perdesini  inderecekl  bu gündür...

17 01 2002-', 'Yarın dedğin  bu gün işte. Uzat elini  çok geç olmadan. Sevgiyi kucaklamak  için belki bir nefeslik  ömrün var. Güneşi  doldurmak için yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Serra Timur']::text[], 8.5, '{"poet":"Serra Timur","poet_slug":"serra-timur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/belki-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun Yedim', 'vurgun-yedim-bahri-sohtorik-ia5sl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne gerek var bana kurşun atmaya

Vurgun yedim gül yüzüne bakarken

Lazım değil kadehten mey tatmaya

Sarhoş oldum sen kahkaha atarken

Mecburmusun kaşlarını çatmaya

Bakışların ömre ömür katarken

Çabam da yok kollarında yatmaya

Düşlerimi gözlerinde yaşarken

Sen devam et gönle ışık saçmaya

Benim yine ufkumda gün batarken

Güç mü kalır uzaklara kaçmaya

Kalpte sevda şimşekleri çakarken', 'Ne gerek var bana kurşun atmaya Vurgun yedim gül yüzüne bakarken Lazım değil kadehten mey tatmaya Sarhoş oldum sen kahkaha atarken Mecburmus...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vurgun-yedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaafımsın', 'zaafimsin-bahri-sohtorik-895w4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir rast, bir neva, bir hüzzam çaldı

Masada kim varsa bundan haz aldı

Bir, benim gözlerim ufka dalardı

Biliyorsun, zaafımsın sen benim

Bana bir kelimen, bakışın yeter

Sensiz dünya sanki mapustan beter

Sesini dinlesem, bülbüller öter

Biliyorsun, zaafımsın sen benim

Bu bilinç seni naza götürdü

Belliki bitmeyen haza götürdü

Beni hazan, seni yaza götürdü

Biliyorsun.zaafımsın sen benim

Gel de benimle masaya otur

İstersen, aşkımı masaya yatır

Çıkar kalemini kanıma batır

Kelimeler yetmez, yaz satır satır

Yine bir rast, neva ve hüzzam çaldı

Masada kim varsa, bundan haz aldı

Gözlerim seninle ufukta kaldı

Biliyorsun, zaafımsın sen benim', 'Bir rast, bir neva, bir hüzzam çaldı Masada kim varsa bundan haz aldı Bir, benim gözlerim ufka dalardı Biliyorsun, zaafımsın sen benim Bana ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaafimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezen Söylüyordu', 'sezen-soyluyordu-erhan-guleryuz-m9nw8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bütün gece sus pus oturduk çıt çımıyordu

bütün gece sus pus oturduk sezen söylyordu

gözlerin ayrılık dedi gözyaşların yalan

o  güzel günler geldi geçti sakın ağlama ardından

son defa elveda diye diye içimden

kal demni bekledim, kal demeni bekledim

yanlış gözlere aglıyorum

bomboş hayallere sığınıyorum

eski resimlere bakamıyorum

lanet ettim sevdaya', 'bütün gece sus pus oturduk çıt çımıyordu bütün gece sus pus oturduk sezen söylyordu gözlerin ayrılık dedi gözyaşların yalan o  güzel günler ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sezen-soyluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Bu Gönül', 'ah-bu-gonul-erhan-guleryuz-1vxr8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne hataların acısı

ne ayrılığın sancısı

bu sabah mutlu uyandım

bitti artık kendimle aşkın kavgası

bedeli ödenmiş sevdamın

acısı yamanmış dünyanın

yine de gelince aklıma

yağmurlarda bakışların

ah bu gönül 

seni deli sevdi güzelim

seni hep sevdi

yağmurlarda solan yüzüne

tutuşur bulutlu gözlerine', 'ne hataların acısı ne ayrılığın sancısı bu sabah mutlu uyandım bitti artık kendimle aşkın kavgası bedeli ödenmiş sevdamın acısı yamanmış dün...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ah-bu-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanına Gelmek İstedim', 'yanina-gelmek-i-stedim-bahri-sohtorik-0v457', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin haber vermeden

Peşinden son defa gelmek istedim

Güzel solgun yüzüne

Bir daha bakıp, görmek istedim

Toprak, bedenini kucaklayınca

Bende onun gibi sarmak istedim

Gözümden dökülen sevgi seliyle

Akarak sana varmak istedim

Acımın altında kaldım, ezildim

Bu yükü geriye vermek istedim

Gittiğin makamdan, ruhsat isteyip

Yeniden yanına gelmek istedim', 'Gittin haber vermeden Peşinden son defa gelmek istedim Güzel solgun yüzüne Bir daha bakıp, görmek istedim Toprak, bedenini kucaklayınca Bend...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanina-gelmek-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohum', 'tohum-erhan-guleryuz-g7izn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tohumunda ayrılık varsa aşkın

mahsulun gözyaşıdır

benim gibi ağır ağır öder yürek cezasını

susar yalan

tohumunda ayrılık varsa aşkın

mahsulun gözyaşıdır

benim gibi ağır ağır ödersin

zamanla geçer yaran

yalan yalan

yalan değil benim sevdam

seni sonsuza kadar seveceğim

yalan yalan

yaan yalandı herşeyin

seni sonsuza kadar affetmeyeceğim

mevsimlerden sonbahardayım

artık çok geç yağmurlardayım

ben vazgeçtim yalnızlardayım

seni affedemem

mevsimlerden sonbahardayım senin yüzünden

dünyadaki herkez için herhangi birisin 

ama herhangi biri için dünyalara değersin

ne yazıkki yüreğimde mahkumsun

cezan ömür boyu sevilmek

hemde sevildiğini hiçbirzaman bilmeden', 'tohumunda ayrılık varsa aşkın mahsulun gözyaşıdır benim gibi ağır ağır öder yürek cezasını susar yalan tohumunda ayrılık varsa aşkın mahsulu...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tohum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Soru', 'zor-soru-bahri-sohtorik-32o2u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana güzeli sordular

Kalbime baktım

Aşktır, dedi

Gözlerime baktım

Sana döndü

Ve sesini çıkarmadı

Bana aşkı sordular

Kalbime baktım

Beni yaşatandır, dedi

Gözlerime baktım

Sana döndü

Ve sesini çıkarmadı

Bana ihaneti sordular

Kalbime baktım

Beni öldürür, dedi

Gözlerime baktım

Yine sana döndü

Ve, ağladı.', 'Bana güzeli sordular Kalbime baktım Aşktır, dedi Gözlerime baktım Sana döndü Ve sesini çıkarmadı Bana aşkı sordular Kalbime baktım Beni yaşa...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zor-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcacıksın', 'sicaciksin-bahri-sohtorik-9bkf4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıcacıksın, sımsıcacıksın

Akşam göğsüne koyunca başımı

Yine beni okşayacaksın

Günün bütün yorgunluğunu

Koynunda atacağım

Beni bağrına basacaksın

Dertlerimi seninle paylaşacak

Sana herşeyimi anlatacağım

Mutlu günlerimde benimle gülecek

Üzüldüğümde anlayacaksın

Gözyaşlarımı göğsüne akıtacağım

Sana yine sımsıkı sarılacağım

Hep sana geleceğim

Dertleneceğim

Ömür boyu bıkmadan

Beni dinleyeceksin

Sen benim en iyi dostum

Sevdiğim

Arkadaşım

Vefakar, yastığımsın.', 'Sıcacıksın, sımsıcacıksın Akşam göğsüne koyunca başımı Yine beni okşayacaksın Günün bütün yorgunluğunu Koynunda atacağım Beni bağrına basaca...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sicaciksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Şafak', 'i-lk-safak-bahri-sohtorik-3g348', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başkasının koynunda bu ilk uyanışın

Bu ilk şafak, 

Kanımın kırmızısı, görüyormusun

Sana Bolu''dan seslenen var

Hissediyor, duyuyormusun

Camdan gözüken bu dağlar

İlk şafağı seyrettiğimiz  o ulu dağlar

O masum, o yemyeşil, o füsunkar

Başını öne eğip de, neden ağlar

Biliyormusun

Göğsünde yangın var

Ateş var, kor var

Bir volkan var, lavları yakar

Ta göğsüme kadar

Beni de kavurur, beni de yakar

Camdan gözüken  bu dağlar

Adını verdiğimiz

Sana ağlar, bana ağlar

O ilk şafağa ağlar

Bağrında ateş olur, lav olur

Akar da akar

İlk şafağa kadar yakar

Kor eder, kül eder

Hem maziyi, hem de beni

Yok eder.', 'Başkasının koynunda bu ilk uyanışın Bu ilk şafak,  Kanımın kırmızısı, görüyormusun Sana Bolu''dan seslenen var Hissediyor, duyuyormusun Camda...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ilk-safak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
